    private static IReadOnlyList<CSharpCompilation> BuildProductionCompilations()
    {
        string repository = FindRepositoryRoot();

        List<CSharpCompilation> compilations = [];

        Dictionary<string, CSharpCompilation> canonicalProjectCompilations =
            new(StringComparer.Ordinal);

        string[] projects = ["RetroDownfall.Arcanum.Core", "RetroDownfall.Arcanum.Secrets", "RetroDownfall.Arcanum.Infrastructure", "RetroDownfall.Arcanum.Api", "RetroDownfall.Arcanum.Cli"];

        foreach (string project in projects)
        {
            string projectDirectory = Path.Combine(repository, "src", project);

            ProcessStartInfo start = new("dotnet") { WorkingDirectory = repository, RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false };

            string evaluationTargets =
                "ResolveReferences,GenerateGlobalUsings,GenerateAssemblyInfo,GenerateMSBuildEditorConfigFile";

            if (project == "RetroDownfall.Arcanum.Core")
            {
                evaluationTargets += ",GenerateArcanumBuildInfo";
            }

            foreach (string argument in new[] { "msbuild", Path.Combine(projectDirectory, project + ".csproj"), "-t:" + evaluationTargets, "-p:Configuration=Release", "-p:UseSharedCompilation=false", "-m:1", "-nodeReuse:false", "-getItem:Compile,ReferencePath,Analyzer,AdditionalFiles,EditorConfigFiles", "-getProperty:DefineConstants,LangVersion,InterceptorsNamespaces,OutputType" })
            {
                start.ArgumentList.Add(argument);
            }

            using System.Diagnostics.Process process = System.Diagnostics.Process.Start(start) ?? throw new InvalidOperationException("Could not evaluate project compiler inputs.");

            Task<string> stdout = process.StandardOutput.ReadToEndAsync();

            Task<string> stderr = process.StandardError.ReadToEndAsync();

            if (!process.WaitForExit(60000))
            {
                process.Kill(entireProcessTree: true);

                throw new InvalidOperationException("Project compiler input evaluation timed out: " + project);
            }

            if (process.ExitCode != 0)
            {
                throw new InvalidOperationException("Project compiler input evaluation failed: " + stdout.Result + stderr.Result);
            }

            using JsonDocument document = JsonDocument.Parse(stdout.Result);

            JsonElement properties = document.RootElement.GetProperty("Properties");

            JsonElement[] InputItems(string name) => document.RootElement
                .GetProperty("Items")
                .GetProperty(name)
                .EnumerateArray()
                .GroupBy(
                    static item => item.GetProperty("FullPath").GetString()!,
                    StringComparer.Ordinal)
                .Select(static group => group.First())
                .ToArray();

            string[] Inputs(string name) => InputItems(name)
                .Select(static item => item.GetProperty("FullPath").GetString()!)
                .ToArray();

            LanguageVersionFacts.TryParse(properties.GetProperty("LangVersion").GetString(), out LanguageVersion version);

            CSharpParseOptions parse = new(version, preprocessorSymbols: properties.GetProperty("DefineConstants").GetString()!.Split(';'));

            // Opt in only to the two namespaces emitted by the evaluated SDK generators.
            // Explicit project interceptor namespaces are appended below, never wildcarded.
            parse = parse.WithFeatures([new("InterceptorsNamespaces", "Microsoft.Extensions.Configuration.Binder.SourceGeneration;Microsoft.AspNetCore.Http.Generated")]);

            if (properties.GetProperty("InterceptorsNamespaces").GetString() is { Length: > 0 } interceptorNamespaces)
            {
                parse = parse.WithFeatures([new("InterceptorsNamespaces", "Microsoft.Extensions.Configuration.Binder.SourceGeneration;Microsoft.AspNetCore.Http.Generated;" + interceptorNamespaces)]);
            }

            SyntaxTree[] trees = Inputs("Compile").Select(file => CSharpSyntaxTree.ParseText(File.ReadAllText(file), parse, Path.GetRelativePath(repository, file).Replace('\\', '/'))).ToArray();

            MetadataReference[] references = InputItems("ReferencePath")
                .Select<JsonElement, MetadataReference>(item =>
                {
                    string file = item.GetProperty("FullPath").GetString()!;

                    if (item.TryGetProperty(
                            "ReferenceSourceTarget",
                            out JsonElement sourceTarget)
                        && sourceTarget.GetString() == "ProjectReference"
                        && item.TryGetProperty(
                            "MSBuildSourceProjectFile",
                            out JsonElement sourceProject)
                        && sourceProject.GetString() is { Length: > 0 } sourcePath
                        && canonicalProjectCompilations.TryGetValue(
                            Path.GetFullPath(sourcePath),
                            out CSharpCompilation? canonical))
                    {
                        return canonical.ToMetadataReference();
                    }

                    return MetadataReference.CreateFromFile(file);
                })
                .ToArray();

            CSharpCompilation compilation = CSharpCompilation.Create(project, trees, references, new CSharpCompilationOptions(properties.GetProperty("OutputType").GetString() == "Exe" ? OutputKind.ConsoleApplication : OutputKind.DynamicallyLinkedLibrary, allowUnsafe: true, nullableContextOptions: NullableContextOptions.Enable));

            GeneratorLoader loader = new();

            string[] analyzers = Inputs("Analyzer");

            foreach (string analyzer in analyzers)
            {
                loader.AddDependencyLocation(analyzer);
            }

            ISourceGenerator[] generators = analyzers.SelectMany(file => new AnalyzerFileReference(file, loader).GetGenerators(LanguageNames.CSharp)).ToArray();

            GeneratorDriver driver = CSharpGeneratorDriver.Create(generators, Inputs("AdditionalFiles").Select(static file => (AdditionalText)new GeneratorText(file)), parse, new GeneratorOptions(Inputs("EditorConfigFiles")));

            driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation complete, out ImmutableArray<Diagnostic> generatorDiagnostics);

            Diagnostic[] errors = generatorDiagnostics.Concat(complete.GetDiagnostics()).Where(static diagnostic => diagnostic.Severity == DiagnosticSeverity.Error).ToArray();

            if (errors.Length != 0)
            {
                throw new InvalidOperationException("Generator-complete compilation failed for " + project + ":\n" + string.Join("\n", errors.Select(static error => error.ToString())));
            }

            CSharpCompilation completed = (CSharpCompilation)complete;

            compilations.Add(completed);

            canonicalProjectCompilations.Add(
                Path.GetFullPath(Path.Combine(
                    projectDirectory,
                    project + ".csproj")),
                completed);
        }

        return compilations;
    }

    private static string FindRepositoryRoot([CallerFilePath] string sourceFilePath = "")
    {
        string sourceDirectory = Path.GetDirectoryName(sourceFilePath)
            ?? throw new InvalidOperationException("The inventory source path has no directory.");

        foreach (string startDirectory in new[] { sourceDirectory, global::System.Environment.CurrentDirectory, AppContext.BaseDirectory })
        {
            DirectoryInfo? directory = new(startDirectory);

            while (directory is not null)
            {
                if (File.Exists(Path.Combine(directory.FullName, "RetroDownfall.Arcanum.slnx")))
                {
                    return directory.FullName;
                }

                directory = directory.Parent;
            }
        }

        throw new InvalidOperationException("Could not locate the Arcanum source root.");
    }

    private sealed class GeneratorLoader : IAnalyzerAssemblyLoader
    {
        public void AddDependencyLocation(string fullPath) { }

        public Assembly LoadFromPath(string fullPath) => Assembly.LoadFrom(fullPath);
    }

    private sealed class GeneratorText(string path) : AdditionalText
    {
        public override string Path => path;

        public override Microsoft.CodeAnalysis.Text.SourceText GetText(CancellationToken cancellationToken = default) => Microsoft.CodeAnalysis.Text.SourceText.From(File.ReadAllText(path));
    }

    private sealed class GeneratorOptions(IEnumerable<string> files) : AnalyzerConfigOptionsProvider
    {
        private readonly AnalyzerConfigOptions global = new Config(files.SelectMany(File.ReadAllLines).Where(static line => line.StartsWith("build_property.", StringComparison.Ordinal)).Select(static line => line.Split('=', 2)).Where(static pair => pair.Length == 2).GroupBy(static pair => pair[0].Trim(), StringComparer.OrdinalIgnoreCase).ToDictionary(static group => group.Key, static group => group.Last()[1].Trim(), StringComparer.OrdinalIgnoreCase));

        public override AnalyzerConfigOptions GlobalOptions => global;

        public override AnalyzerConfigOptions GetOptions(SyntaxTree tree) => global;

        public override AnalyzerConfigOptions GetOptions(AdditionalText textFile) => global;

        private sealed class Config(Dictionary<string, string> values) : AnalyzerConfigOptions
        {
            public override bool TryGetValue(string key, out string value) => values.TryGetValue(key, out value!);
        }
    }

    internal static HostedProducerInventoryValidation ValidateProductionTree() => ProductionValidation.Value;

    private static HostedProducerInventoryValidation ValidateProductionSources()
    {
        HostedProducerDiscovery<string> registrations = DiscoverApplicationHostedServices(ProductionCompilations);

        HostedProducerInventoryValidation validation = Validate(Catalog, NonHostedCatalog, registrations, ProductionSiteDiscovery);

        return new([.. ReviewedCapsules.Value.Diagnostics, .. ValidateManifestRoots(ReviewedCapsules.Value.Sites), .. validation.Diagnostics]);
    }

    private static HostedProducerDiscovery<HostedProducerSite> DiscoverProductionSites() =>
        DiscoverProductionSites(HostedProducerProductionPartition.Primary);

    private static HostedProducerDiscovery<HostedProducerSite> DiscoverAdditionalProductionSites() =>
        DiscoverProductionSites(HostedProducerProductionPartition.Additional);

    // The Production Discovery Entry: the one place that discovers the production partitions. It is the only
    // production caller that requests premises (always ProductionPremises, never a parameter), so the primary
    // run, the additional run and any scoped run (a root subset) share exactly one classification regime.
    internal static HostedProducerDiscovery<HostedProducerSite> DiscoverProductionSites(
        HostedProducerProductionPartition partition,
        IReadOnlyCollection<string>? rootSubset = null)
    {
        int rootWorkers = HostedProducerRootWorkers.ParseCount(global::System.Environment.GetEnvironmentVariable("ARCANUM_HOSTED_ANALYSIS_ROOT_WORKERS"));

        if (partition == HostedProducerProductionPartition.Primary)
        {
            HostedProducerDiscovery<string> registrations = DiscoverApplicationHostedServices(ProductionCompilations);

            ProductionRootSelection primary = SelectProductionRoots(rootSubset, registrations, Catalog, NonHostedCatalog);

            return DiscoverProducerSitesUnderPremises(ProductionPremises, ProductionCompilations, primary.Registrations, primary.Catalog, primary.NonHostedCatalog,
                rootWorkers: rootWorkers);
        }

        using HostedProducerPhaseProgress preparation = HostedProducerPhaseProgress.Start("additional-preparation", 0);

        IReadOnlyList<NonHostedProducerChainEntry> roots = AdditionalProductionRoots;

        preparation.Complete();

        ProductionRootSelection additional = SelectProductionRoots(rootSubset, new([], []), [], roots);

        using HostedProducerPhaseProgress traversal = HostedProducerPhaseProgress.Start("additional-traversal", 0);

        HostedProducerDiscovery<HostedProducerSite> result = DiscoverProducerSitesUnderPremises(
            ProductionPremises,
            ProductionCompilations,
            additional.Registrations,
            additional.Catalog,
            additional.NonHostedCatalog,
            rootWorkers: rootWorkers);

        traversal.Complete();

        return result;
    }

    private static IReadOnlyList<NonHostedProducerChainEntry> BuildAdditionalProductionRoots()
    {
        const string schemaCatalog =
            "RetroDownfall.Arcanum.Infrastructure.Data.Schema.GrimoireSchemaCatalog";

        const string schemaCatalogPath =
            "src/RetroDownfall.Arcanum.Infrastructure/Data/Schema/GrimoireSchemaCatalog.cs";

        const string schemaManifests =
            "RetroDownfall.Arcanum.Infrastructure.Data.Schema.GrimoireSchemaManifests";

        const string schemaManifestsPath =
            "src/RetroDownfall.Arcanum.Infrastructure/Data/Schema/GrimoireSchemaTierOwnershipRegistry.cs";

        const string activeStore =
            "RetroDownfall.Arcanum.Infrastructure.InstallationReset.InstallationResetActiveStore";

        const string activeStorePath =
            "src/RetroDownfall.Arcanum.Infrastructure/InstallationReset/InstallationResetActiveStore.cs";

        List<NonHostedProducerChainEntry> roots =
        [
            AdditionalRoot(schemaCatalog, schemaCatalogPath, "get_AllObjects", "focused bounded schema data proof"),
            AdditionalRoot(schemaCatalog, schemaCatalogPath, "get_CoreObjects", "focused bounded schema data proof"),
            AdditionalRoot(schemaCatalog, schemaCatalogPath, "get_CovenantCanonicalObjects", "focused bounded schema data proof"),
            AdditionalRoot(schemaCatalog, schemaCatalogPath, "get_CovenantAcceleratorObjects", "focused bounded schema data proof"),
            AdditionalRoot(schemaCatalog, schemaCatalogPath, "get_TransitionStatements", "focused bounded schema data proof"),
            AdditionalRoot(schemaCatalog, schemaCatalogPath, "get_CanonicalSchemaFingerprint", "focused bounded schema data proof"),
            AdditionalRoot(schemaCatalog, schemaCatalogPath, "get_CoreSchemaFingerprint", "focused bounded schema data proof"),
            AdditionalRoot(schemaCatalog, schemaCatalogPath, "get_CovenantCanonicalSchemaFingerprint", "focused bounded schema data proof"),
            AdditionalRoot(schemaCatalog, schemaCatalogPath, "get_CovenantAcceleratorSchemaFingerprint", "focused bounded schema data proof"),
            AdditionalRoot(schemaManifests, schemaManifestsPath, "get_Core", "focused bounded schema data proof"),
            AdditionalRoot(schemaManifests, schemaManifestsPath, "get_CovenantCanonical", "focused bounded schema data proof"),
            AdditionalRoot(schemaManifests, schemaManifestsPath, "get_CovenantAccelerator", "focused bounded schema data proof"),
            AdditionalRoot(
                "RetroDownfall.Arcanum.Infrastructure.Backup.BackupRestoreStagingIndex",
                "src/RetroDownfall.Arcanum.Infrastructure/Backup/BackupRestoreStagingIndex.cs",
                "Add",
                "focused production-shape classification"),
            AdditionalRoot(activeStore, activeStorePath, "SameBinding", "focused value-equality classification"),
            AdditionalRoot(activeStore, activeStorePath, "SamePayload", "focused value-equality classification"),
        ];

        foreach (INamedTypeSymbol handler in ProductionCompilations
            .SelectMany(static compilation => SourceTypes(compilation.Assembly.GlobalNamespace))
            .Where(static candidate => candidate is { TypeKind: TypeKind.Class, IsAbstract: false })
            .Where(static candidate => candidate.AllInterfaces.Any(static contract =>
                SourceTypeName(contract)
                    == "RetroDownfall.Arcanum.Core.Operations.ILongRunningOperationRecoveryHandler"))
            .OrderBy(static candidate => SourceTypeName(candidate), StringComparer.Ordinal))
        {
            IMethodSymbol recovery = handler.GetMembers("RecoverAsync")
                .OfType<IMethodSymbol>()
                .Single();

            SyntaxReference declaration = recovery.DeclaringSyntaxReferences.Single();

            string typeName = SourceTypeName(handler);

            roots.Add(new(
                typeName + ".RecoverAsync",
                declaration.SyntaxTree.FilePath,
                typeName,
                "RecoverAsync",
                HostedProducerAuthorityKind.FiniteRequest,
                typeName + ".RecoverAsync: recovery effect classification root",
                []));
        }

        return roots;
    }

    private static NonHostedProducerChainEntry AdditionalRoot(
        string type,
        string path,
        string member,
        string proof) => new(
            type + "." + member,
            path,
            type,
            member,
            HostedProducerAuthorityKind.FiniteRequest,
            type + "." + member + ": " + proof,
            []);

    private static IEnumerable<INamedTypeSymbol> SourceTypes(INamespaceSymbol @namespace)
    {
        foreach (INamedTypeSymbol type in @namespace.GetTypeMembers())
        {
            yield return type;

            foreach (INamedTypeSymbol nested in SourceTypes(type))
            {
                yield return nested;
            }
        }

        foreach (INamespaceSymbol child in @namespace.GetNamespaceMembers())
        {
            foreach (INamedTypeSymbol type in SourceTypes(child))
            {
                yield return type;
            }
        }
    }

    private static IEnumerable<INamedTypeSymbol> SourceTypes(INamedTypeSymbol type)
    {
        foreach (INamedTypeSymbol nested in type.GetTypeMembers())
        {
            yield return nested;

            foreach (INamedTypeSymbol descendant in SourceTypes(nested))
            {
                yield return descendant;
            }
        }
    }

    private static string SourceTypeName(INamedTypeSymbol type)
    {
        if (type.ContainingType is { } containingType)
        {
            return SourceTypeName(containingType) + "+" + type.MetadataName;
        }

        string containingNamespace = type.ContainingNamespace.ToDisplayString();

        return string.IsNullOrEmpty(containingNamespace)
            ? type.MetadataName
            : containingNamespace + "." + type.MetadataName;
    }

