    internal static string CapsuleManifestPath => Path.Combine(FindRepositoryRoot(), "tests", "RetroDownfall.Arcanum.Tests", "Support", "hosted-grimoire-producer-capsules-v1.tsv");

    private static HostedProducerCapsuleManifest LoadReviewedCapsules()
    {
        if (!File.Exists(CapsuleManifestPath))
        {
            return new([], [new("HOSTED_MANIFEST_MISSING", CapsuleManifestPath, "The reviewed producer capsule manifest is required.")]);
        }

        return ParseCapsuleManifest(File.ReadAllLines(CapsuleManifestPath));
    }

    internal static HostedProducerCapsuleManifest ParseCapsuleManifest(IReadOnlyList<string> lines)
    {
        List<HostedProducerInventoryDiagnostic> diagnostics = [];

        List<HostedProducerSite> sites = [];

        if (lines.Count == 0 || lines[0] != CapsuleManifestHeader)
        {
            diagnostics.Add(new("HOSTED_MANIFEST_VERSION_INVALID", lines.Count == 0 ? "<empty>" : lines[0], "The capsule manifest must start with the exact supported schema/version header."));
        }

        if (lines.Count < 2 || lines[1] != CapsuleManifestColumns)
        {
            diagnostics.Add(new("HOSTED_MANIFEST_COLUMNS_INVALID", lines.Count < 2 ? "<missing>" : lines[1], "The capsule manifest columns must match the v1 contract exactly."));
        }

        for (int index = 2; index < lines.Count; index++)
        {
            string line = lines[index];

            if (line.Length == 0)
            {
                continue;
            }

            string[] fields = line.Split('\t');

            if (fields.Length != 13)
            {
                diagnostics.Add(new("HOSTED_MANIFEST_ROW_INVALID", $"line:{index + 1}", $"Expected 13 tab-separated fields, found {fields.Length}."));

                continue;
            }

            if (!Enum.TryParse(fields[6], out HostedProducerSiteKind kind) || !Enum.IsDefined(kind) || !int.TryParse(fields[8], NumberStyles.None, CultureInfo.InvariantCulture, out int ordinal) || ordinal < 0 || !IsSha256(fields[9]))
            {
                diagnostics.Add(new("HOSTED_MANIFEST_ROW_INVALID", $"line:{index + 1}", "The kind, nonnegative syntax ordinal, and uppercase SHA-256 syntax fingerprint must be valid."));

                continue;
            }

            string? workFrontier = ParseOptionalSha256(fields[10], index, "work", diagnostics);

            string? effectFrontier = ParseOptionalSha256(fields[11], index, "effect", diagnostics);

            GrimoireWorkKind? admittedWorkKind = null;

            if (fields[12] != "-" && (!Enum.TryParse(fields[12], out GrimoireWorkKind parsedWorkKind) || !Enum.IsDefined(parsedWorkKind)))
            {
                diagnostics.Add(new("HOSTED_MANIFEST_ROW_INVALID", $"line:{index + 1}", "The admitted work kind must be '-' or one defined GrimoireWorkKind."));
            }
            else if (fields[12] != "-")
            {
                admittedWorkKind = Enum.Parse<GrimoireWorkKind>(fields[12]);
            }

            bool invalidRequiredIdentity = fields.Take(8).Where(static (_, fieldIndex) => fieldIndex != 4).Any(static field => string.IsNullOrWhiteSpace(field) || field.Contains('\r') || field.Contains('\n'));

            if (invalidRequiredIdentity || fields[4].Contains('\r') || fields[4].Contains('\n'))
            {
                diagnostics.Add(new("HOSTED_MANIFEST_ROW_INVALID", $"line:{index + 1}", "Required identity fields must be nonempty single-line values; anonymous-function member names may be empty."));

                continue;
            }

            HostedProducerSite site = new(
                fields[0],
                fields[1] + "/capsule@" + CapsuleId(fields[2], fields[5], kind, fields[7], ordinal, fields[9]),
                fields[2],
                fields[3],
                fields[4],
                kind,
                fields[7],
                fields[1],
                fields[5],
                ordinal,
                fields[9],
                workFrontier,
                effectFrontier,
                admittedWorkKind);

            sites.Add(site);
        }

        foreach (IGrouping<string, HostedProducerSite> duplicate in sites.GroupBy(StableSiteIdentity, StringComparer.Ordinal).Where(static group => group.Count() > 1))
        {
            diagnostics.Add(new("HOSTED_MANIFEST_ROW_DUPLICATE", duplicate.Key, "Each root/operation/capsule/frontier association must occur exactly once."));
        }

        foreach (HostedProducerSite site in sites)
        {
            ValidateManifestFrontier(site, site.WorkFrontierCapsuleId, IsWorkFrontierCallee, "work", sites, diagnostics);

            ValidateManifestFrontier(site, site.EffectFrontierCapsuleId, static callee => callee.EndsWith(".TryBeginExternalEffectGroup", StringComparison.Ordinal), "effect", sites, diagnostics);

            bool workFrontier = IsWorkFrontierCallee(site.Callee);

            if (workFrontier != site.AdmittedWorkKind.HasValue)
            {
                diagnostics.Add(new("HOSTED_MANIFEST_WORK_KIND_INVALID", StableSiteIdentity(site), "Exactly a work-admission frontier must name its admitted work kind."));
            }
        }

        ValidateManifestHandoffBindings(sites, diagnostics);

        return new(sites, diagnostics.Distinct().ToArray());
    }

    private static string? ParseOptionalSha256(string value, int index, string frontier, List<HostedProducerInventoryDiagnostic> diagnostics)
    {
        if (value == "-")
        {
            return null;
        }

        if (!IsSha256(value))
        {
            diagnostics.Add(new("HOSTED_MANIFEST_ROW_INVALID", $"line:{index + 1}", $"The {frontier} frontier must be '-' or an uppercase SHA-256 capsule identity."));

            return null;
        }

        return value;
    }

    private static bool IsSha256(string value) => value.Length == 64 && value.All(static character => character is >= '0' and <= '9' or >= 'A' and <= 'F');

    private static void ValidateManifestFrontier(HostedProducerSite site, string? frontierId, Func<string, bool> isFrontierCallee, string frontierKind, IReadOnlyList<HostedProducerSite> sites, List<HostedProducerInventoryDiagnostic> diagnostics)
    {
        if (frontierId is null)
        {
            return;
        }

        HostedProducerSite[] matches = sites.Where(candidate => candidate.RootType == site.RootType && candidate.AuthorityOperationId == site.AuthorityOperationId && candidate.CapsuleId == frontierId && candidate.Kind == HostedProducerSiteKind.EffectFrontier && isFrontierCallee(candidate.Callee)).ToArray();

        if (matches.Length != 1)
        {
            diagnostics.Add(new("HOSTED_MANIFEST_FRONTIER_UNRESOLVED", StableSiteIdentity(site), $"The exact same-operation {frontierKind} frontier capsule must resolve once; found {matches.Length}."));
        }
    }

    private static IReadOnlyList<HostedProducerInventoryDiagnostic> ValidateManifestRoots(IReadOnlyList<HostedProducerSite> sites)
    {
        HashSet<(string RootType, string OperationId)> roots = CatalogRoots.SelectMany(service => service.Operations.Select(operation => (service.ServiceType, operation.OperationId)))
            .Concat(NonHostedCatalogRoots.Select(static chain => (chain.EnclosingType, chain.ChainId)))
            .ToHashSet();

        return sites
            .Where(site => !roots.Contains((site.RootType, site.AuthorityOperationId)))
            .Select(site => new HostedProducerInventoryDiagnostic("HOSTED_MANIFEST_ROOT_UNRESOLVED", StableSiteIdentity(site), "The manifest row must map to one exact declared hosted operation or non-hosted authority chain."))
            .ToArray();
    }

    private static IReadOnlyList<HostedProducerServiceEntry> AttachHostedSites(IReadOnlyList<HostedProducerServiceEntry> roots, IReadOnlyList<HostedProducerSite> sites) => roots
        .Select(service => service with
        {
            Operations = service.Operations.Select(operation => operation with
            {
                Sites = sites.Where(site => site.RootType == service.ServiceType && site.AuthorityOperationId == operation.OperationId).ToArray(),
            }).ToArray(),
        })
        .ToArray();

    private static IReadOnlyList<NonHostedProducerChainEntry> AttachNonHostedSites(IReadOnlyList<NonHostedProducerChainEntry> roots, IReadOnlyList<HostedProducerSite> sites) => roots
        .Select(chain => chain with
        {
            Sites = sites.Where(site => site.RootType == chain.EnclosingType && site.AuthorityOperationId == chain.ChainId).ToArray(),
        })
        .ToArray();

    internal static string RenderCapsuleManifest(IEnumerable<HostedProducerSite> sites)
    {
        IEnumerable<string> rows = sites.OrderBy(StableSiteIdentity, StringComparer.Ordinal).Select(static site => string.Join('\t',
            site.RootType,
            site.AuthorityOperationId,
            site.SourcePath,
            site.EnclosingType,
            site.Member,
            site.MemberIdentity,
            site.Kind,
            site.Callee,
            site.SyntaxOrdinal.ToString(CultureInfo.InvariantCulture),
            site.SyntaxFingerprint,
            site.WorkFrontierCapsuleId ?? "-",
            site.EffectFrontierCapsuleId ?? "-",
            site.AdmittedWorkKind?.ToString() ?? "-"));

        return string.Join('\n', new[] { CapsuleManifestHeader, CapsuleManifestColumns }.Concat(rows)) + "\n";
    }

    internal static string RenderDiagnosticReport(
        IEnumerable<HostedProducerInventoryDiagnostic> diagnostics)
    {
        ArgumentNullException.ThrowIfNull(diagnostics);

        return string.Join(
            global::System.Environment.NewLine,
            diagnostics.Select(static diagnostic =>
                string.Join('\t', diagnostic.Code, diagnostic.Identity, diagnostic.Detail)));
    }

    internal static HostedProducerCapsuleManifestComparison CompareCapsuleManifests(
        string discovered,
        string reviewed)
    {
        ArgumentNullException.ThrowIfNull(discovered);
        ArgumentNullException.ThrowIfNull(reviewed);

        IReadOnlyList<string> discoveredRows = CapsuleManifestRows(discovered);
        IReadOnlyList<string> reviewedRows = CapsuleManifestRows(reviewed);

        return new(
            string.Equals(discovered, reviewed, StringComparison.Ordinal),
            MultisetExcept(discoveredRows, reviewedRows),
            MultisetExcept(reviewedRows, discoveredRows));
    }

    internal static string RenderProductionComparisonReport(
        IReadOnlyList<HostedProducerInventoryDiagnostic> diagnostics,
        HostedProducerCapsuleManifestComparison comparison)
    {
        ArgumentNullException.ThrowIfNull(diagnostics);
        ArgumentNullException.ThrowIfNull(comparison);

        List<string> lines =
        [
            $"DISCOVERY DIAGNOSTICS ({diagnostics.Count})",
            diagnostics.Count == 0
                ? "<none>"
                : RenderDiagnosticReport(diagnostics),
            $"MANIFEST EXACT TEXT MATCH: {comparison.ExactTextMatch}",
            $"MANIFEST ADDED ROWS ({comparison.AddedRows.Count})",
        ];

        if (comparison.AddedRows.Count == 0)
        {
            lines.Add("<none>");
        }
        else
        {
            lines.AddRange(comparison.AddedRows.Select(static row => "+ " + row));
        }

        lines.Add($"MANIFEST REMOVED ROWS ({comparison.RemovedRows.Count})");

        if (comparison.RemovedRows.Count == 0)
        {
            lines.Add("<none>");
        }
        else
        {
            lines.AddRange(comparison.RemovedRows.Select(static row => "- " + row));
        }

        return string.Join(global::System.Environment.NewLine, lines);
    }

    internal static HostedProducerCapsuleManifestUpdate ReadOrUpdateCapsuleManifest(
        string path,
        string expected,
        IReadOnlyList<HostedProducerInventoryDiagnostic> diagnostics,
        bool updateRequested,
        Action<string> reportBeforeWrite)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(path);

        ArgumentNullException.ThrowIfNull(expected);

        ArgumentNullException.ThrowIfNull(diagnostics);

        ArgumentNullException.ThrowIfNull(reportBeforeWrite);

        string reviewed = File.Exists(path)
            ? File.ReadAllText(path)
            : string.Empty;

        HostedProducerCapsuleManifestComparison comparison = CompareCapsuleManifests(
            expected,
            reviewed);

        string report = RenderProductionComparisonReport(diagnostics, comparison);

        if (updateRequested && diagnostics.Count == 0)
        {
            if (!comparison.ExactTextMatch)
            {
                reportBeforeWrite(report);
            }

            File.WriteAllText(path, expected);

            reviewed = File.ReadAllText(path);
        }

        return new(reviewed, report);
    }

    private static IReadOnlyList<string> CapsuleManifestRows(string manifest)
    {
        string[] rows = manifest.Split('\n', StringSplitOptions.None);

        return rows.Length > 0 && rows[^1].Length == 0
            ? rows[..^1]
            : rows;
    }

    private static IReadOnlyList<string> MultisetExcept(
        IReadOnlyList<string> source,
        IReadOnlyList<string> subtraction)
    {
        Dictionary<string, int> remaining = subtraction
            .GroupBy(static row => row, StringComparer.Ordinal)
            .ToDictionary(
                static group => group.Key,
                static group => group.Count(),
                StringComparer.Ordinal);

        List<string> difference = [];

        foreach (string row in source)
        {
            if (remaining.TryGetValue(row, out int count) && count > 0)
            {
                remaining[row] = count - 1;
            }
            else
            {
                difference.Add(row);
            }
        }

        return difference;
    }

    private static NonHostedProducerChainEntry Chain(string project, string folder, string type, string member, HostedProducerAuthorityKind authority, string proof)
    {
        string enclosingType = $"RetroDownfall.Arcanum.{project}.{folder}.{type}";

        return new(enclosingType + "." + member, $"src/RetroDownfall.Arcanum.{project}/{folder}/{type}.cs", enclosingType, member, authority, enclosingType + "." + member + ": " + proof, []);
    }

    private static HostedProducerOperationEntry Operation(string folder, string type, string member, HostedProducerAuthorityKind authority, GrimoireWorkKind? kind, string? proof = null, string project = "Infrastructure", string? sourceFile = null)
    {
        string enclosingType = $"RetroDownfall.Arcanum.{project}.{folder}.{type}";

        return new(enclosingType + "." + member, $"src/RetroDownfall.Arcanum.{project}/{folder}/{sourceFile ?? type + ".cs"}", enclosingType, member, authority, kind, proof is null ? null : enclosingType + "." + member + ": " + proof, []);
    }

    // A Lease-Handoff Root is an ordinary hosted root whose admission is not minted inside it: its callers carry a work lease in by
    // value, and the named formal is the root's admission origin (the Root Lease Formal).
    private static HostedProducerOperationEntry Handoff(HostedProducerOperationEntry operation, string leaseFormal) => operation with { LeaseFormal = leaseFormal };

    private static HostedProducerOperationEntry AtCall(HostedProducerOperationEntry operation, string callee, int occurrence, string exactExpression) => operation with { OperationId = operation.OperationId + "::call:" + callee + "#" + occurrence + "~" + Fingerprint(SyntaxFactory.ParseExpression(exactExpression)) };

    private static HostedProducerServiceEntry Ordinary(string folder, string type, GrimoireWorkKind kind, bool stop = false, string? sourceFile = null) => new(type, stop ? [Operation(folder, type, "ExecuteAsync", HostedProducerAuthorityKind.OrdinaryHostedWork, kind, sourceFile: sourceFile), Operation(folder, type, "StopAsync", HostedProducerAuthorityKind.OrdinaryHostedWork, kind, sourceFile: sourceFile)] : [Operation(folder, type, "ExecuteAsync", HostedProducerAuthorityKind.OrdinaryHostedWork, kind, sourceFile: sourceFile)]);

    private static HostedProducerServiceEntry Lifecycle(string folder, string type, HostedProducerAuthorityKind startAuthority, string startProof, HostedProducerAuthorityKind stopAuthority, string stopProof) => new(type, [Operation(folder, type, "StartAsync", startAuthority, null, startProof), Operation(folder, type, "StopAsync", stopAuthority, null, stopProof)]);

    internal static HostedProducerDiscovery<HostedProducerSite> DiscoverProducerSites(IReadOnlyList<CSharpCompilation> compilations, HostedProducerDiscovery<string> registrations) => DiscoverProducerSites(compilations, registrations, Catalog, NonHostedCatalog);

    // Fixtures never request premises: this overload has no premise parameter, so every caller that does not
    // use the premise seam below runs with HostedProducerPremises.None and today's strict behaviour.
    internal static HostedProducerDiscovery<HostedProducerSite> DiscoverProducerSites(IReadOnlyList<CSharpCompilation> compilations, HostedProducerDiscovery<string> registrations, IReadOnlyList<HostedProducerServiceEntry> catalog, IReadOnlyList<NonHostedProducerChainEntry> nonHostedCatalog, int evaluationEnvironmentMaximumMembers = DefaultEvaluationEnvironmentMaximumMembers, int evaluationEnvironmentMaximumDepth = DefaultEvaluationEnvironmentMaximumDepth, int traversalMaximumDepth = DefaultTraversalMaximumDepth, int maximumAnalyzedStatesPerRoot = DefaultMaximumAnalyzedStatesPerRoot, HostedProducerRecoverySelectionProbe? recoverySelectionProbe = null, bool auditRecoveryReachabilityParity = false, int rootWorkers = 1, bool reverseRootFamilies = false, Action<HostedProducerAdmittedStateObservation>? admittedStateObserver = null, Action<int, int, int, int, bool>? nestedReuseObserver = null) =>
        DiscoverProducerSitesUnderPremises(HostedProducerPremises.None, compilations, registrations, catalog, nonHostedCatalog, evaluationEnvironmentMaximumMembers, evaluationEnvironmentMaximumDepth, traversalMaximumDepth, maximumAnalyzedStatesPerRoot, recoverySelectionProbe, auditRecoveryReachabilityParity, rootWorkers, reverseRootFamilies, admittedStateObserver, nestedReuseObserver);

    // The only seam that accepts premises. Its callers are the Production Discovery Entry and the
    // ClosedWorldPremises fixtures; an architecture pin keeps it that way.
    internal static HostedProducerDiscovery<HostedProducerSite> DiscoverProducerSitesUnderPremises(HostedProducerPremises premises, IReadOnlyList<CSharpCompilation> compilations, HostedProducerDiscovery<string> registrations, IReadOnlyList<HostedProducerServiceEntry> catalog, IReadOnlyList<NonHostedProducerChainEntry> nonHostedCatalog, int evaluationEnvironmentMaximumMembers = DefaultEvaluationEnvironmentMaximumMembers, int evaluationEnvironmentMaximumDepth = DefaultEvaluationEnvironmentMaximumDepth, int traversalMaximumDepth = DefaultTraversalMaximumDepth, int maximumAnalyzedStatesPerRoot = DefaultMaximumAnalyzedStatesPerRoot, HostedProducerRecoverySelectionProbe? recoverySelectionProbe = null, bool auditRecoveryReachabilityParity = false, int rootWorkers = 1, bool reverseRootFamilies = false, Action<HostedProducerAdmittedStateObservation>? admittedStateObserver = null, Action<int, int, int, int, bool>? nestedReuseObserver = null)
    {
        if (rootWorkers is not (1 or 2 or 3))
        {
            throw new ArgumentOutOfRangeException(nameof(rootWorkers));
        }

        // Verified once per discovery, by an unbudgeted enumeration; every isolated worker graph shares the verdict.
        HostedProducerPremiseLedger ledger = premises == HostedProducerPremises.None
            ? HostedProducerPremiseLedger.None
            : VerifyPremises(compilations, premises);

        // Facts about the analysed compilations alone: computed at most once per discovery, by a scan that does not
        // depend on which isolated worker asks first, and shared by every worker graph.
        InventoryFacts facts = new(compilations);

        ProducerGraph CreateGraph() => new(compilations, evaluationEnvironmentMaximumMembers, evaluationEnvironmentMaximumDepth, traversalMaximumDepth, maximumAnalyzedStatesPerRoot, auditRecoveryReachabilityParity, admittedStateObserver, nestedReuseObserver, ledger, facts);

        return HostedProducerRootWorkers.OnAnalysisStack(() => rootWorkers == 1
            ? CreateGraph().Discover(registrations, catalog, nonHostedCatalog, recoverySelectionProbe)
            : ProducerGraph.DiscoverParallel(CreateGraph, registrations, catalog, nonHostedCatalog, recoverySelectionProbe, rootWorkers, reverseRootFamilies));
    }

