        // A graph that answers one question only: whether a body can reach a producer site that is classified (a member of the
        // vocabulary or an external producer). It does not ask whether the body uses a framework member nobody has reviewed,
        // or a construct it cannot follow, which the traversal of a body refuses. The static initialization of a type is
        // judged by such a graph, because no traversal ever enters it.
        private readonly bool scanSitesOnly;

        internal ProducerGraph(
            IReadOnlyList<CSharpCompilation> compilations,
            int evaluationEnvironmentMaximumMembers,
            int evaluationEnvironmentMaximumDepth,
            int traversalMaximumDepth,
            int maximumAnalyzedStatesPerRoot,
            bool auditRecoveryReachabilityParity,
            Action<HostedProducerAdmittedStateObservation>? admittedStateObserver = null,
            Action<int, int, int, int, bool>? nestedReuseObserver = null,
            HostedProducerPremiseLedger? premises = null,
            InventoryFacts? facts = null,
            bool sitesOnly = false)
        {
            this.premises = premises ?? HostedProducerPremiseLedger.None;

            inventoryFacts = facts ?? new InventoryFacts(compilations);

            scanSitesOnly = sitesOnly;

            analysedCompilations = compilations;

            foreach (HostedProducerInventoryDiagnostic violation in this.premises.Violations)
            {
                diagnostics.Add(violation);
            }

            this.evaluationEnvironmentMaximumMembers =
                evaluationEnvironmentMaximumMembers;

            this.evaluationEnvironmentMaximumDepth =
                evaluationEnvironmentMaximumDepth;

            this.traversalMaximumDepth = traversalMaximumDepth;

            this.maximumAnalyzedStatesPerRoot = maximumAnalyzedStatesPerRoot;

            this.auditRecoveryReachabilityParity = auditRecoveryReachabilityParity;

            this.admittedStateObserver = admittedStateObserver;

            this.nestedReuseObserver = nestedReuseObserver;

            foreach (CSharpCompilation compilation in compilations)
            {
                _ = CompilationIdentity(compilation);

                foreach (SyntaxTree tree in compilation.SyntaxTrees)
                {
                    if (!tree.FilePath.StartsWith("src/", StringComparison.Ordinal) || tree.FilePath.Contains("/obj/", StringComparison.Ordinal))
                    {
                        continue;
                    }

                    SemanticModel model = inventoryFacts.SemanticModelOf(compilation, tree);

                    semanticModels.Add(tree, model);

                    _ = TreeIdentity(tree);

                    foreach (SyntaxNode node in tree.GetRoot().DescendantNodes())
                    {
                        if (node is BaseMethodDeclarationSyntax or AccessorDeclarationSyntax or LocalFunctionStatementSyntax && model.GetDeclaredSymbol(node) is IMethodSymbol method)
                        {
                            AddMember(new(method, node, model));
                        }

                        if (node is PropertyDeclarationSyntax { ExpressionBody.Expression: { } expression } property && model.GetDeclaredSymbol(property)?.GetMethod is { } getter)
                        {
                            AddMember(new(getter, expression, model));
                        }

                        if (node is IndexerDeclarationSyntax { ExpressionBody.Expression: { } indexerExpression } indexer && model.GetDeclaredSymbol(indexer)?.GetMethod is { } indexerGetter)
                        {
                            AddMember(new(indexerGetter, indexerExpression, model));
                        }

                        if (node is InvocationExpressionSyntax invocation)
                        {
                            invocations.Add((invocation, model));
                        }

                        if (node is BaseObjectCreationExpressionSyntax creation)
                        {
                            objectCreations.Add((creation, model));
                        }

                        if (node is ConstructorInitializerSyntax initializer)
                        {
                            constructorInitializers.Add((initializer, model));
                        }
                    }
                }
            }

            foreach ((InvocationExpressionSyntax call, SemanticModel model) in invocations)
            {
                ReadBinding(call, model);
            }
        }

        private static MethodIdentity Identity(IMethodSymbol method) => new(method.ContainingAssembly.Identity, MethodKey(method));

        private IEnumerable<AuthoredMember> AuthoredMembers => members.Values.SelectMany(static group => group);

        private void AddMember(AuthoredMember member)
        {
            string key = MethodKey(member.Symbol);

            AuthoredTypeIdentity typeIdentity = new(member.Symbol.ContainingAssembly.Identity, CompilationIdentity(member.Model.Compilation), TypeKey(member.Symbol.ContainingType));

            if (!membersByType.TryGetValue(typeIdentity, out List<AuthoredMember>? typeMembers))
            {
                membersByType.Add(typeIdentity, typeMembers = []);
            }

            typeMembers.Add(member);

            if (!members.TryGetValue(key, out List<AuthoredMember>? candidates))
            {
                members.Add(key, candidates = []);
            }

            candidates.Add(member);

            if (member.Syntax is not MethodDeclarationSyntax { Body: null, ExpressionBody: null } && !IsBodilessAccessorSlot(member))
            {
                MethodIdentity identity = new(member.Symbol.ContainingAssembly.Identity, key);

                if (!membersByIdentity.TryGetValue(identity, out List<AuthoredMember>? exactCandidates))
                {
                    membersByIdentity.Add(identity, exactCandidates = []);
                }

                exactCandidates.Add(member);
            }
        }

        // An accessor declared without a body that is not an auto-property accessor: an abstract or extern accessor, an
        // interface member, the definition part of a partial property. Like a bodiless method it stands for whatever the
        // runtime type selects, or for the implementation part, never for code of its own.
        private static bool IsBodilessAccessorSlot(AuthoredMember member) =>
            member.Syntax is AccessorDeclarationSyntax { Body: null, ExpressionBody: null }
            && (member.Symbol.IsAbstract
                || member.Symbol.IsExtern
                || member.Symbol.ContainingType.TypeKind == TypeKind.Interface
                || member.Symbol.AssociatedSymbol is IPropertySymbol { IsPartialDefinition: true });

        private int CompilationIdentity(Compilation compilation)
        {
            if (!compilationIdentities.TryGetValue(compilation, out int identity))
            {
                identity = compilationIdentities.Count;

                compilationIdentities.Add(compilation, identity);
            }

            return identity;
        }

        private int TreeIdentity(SyntaxTree tree)
        {
            if (!treeIdentities.TryGetValue(tree, out int identity))
            {
                identity = treeIdentities.Count;

                treeIdentities.Add(tree, identity);
            }

            return identity;
        }

        private GraphMemberIdentity MemberIdentity(AuthoredMember member) => new(member.Symbol.ContainingAssembly.Identity, CompilationIdentity(member.Model.Compilation), TreeIdentity(member.Syntax.SyntaxTree), MemberMethodKey(member.Symbol), member.Syntax.SpanStart, member.Syntax.Span.Length);

        private string MemberMethodKey(IMethodSymbol method)
        {
            if (!memberMethodKeys.TryGetValue(method, out string? key))
            {
                memberMethodKeyBuilds++;

                key = MethodKey(method);

                memberMethodKeys[method] = key;
            }

            return key;
        }

        internal IReadOnlyList<(string Method, int Compilation, int Tree, int Start, int Length, int Builds)> ProbeMemberMethodIdentities(
            IReadOnlyList<(SemanticModel Model, IMethodSymbol Method, SyntaxNode Syntax)> queries)
        {
            List<(string Method, int Compilation, int Tree, int Start, int Length, int Builds)> results = [];

            foreach (var query in queries)
            {
                int before = memberMethodKeyBuilds;

                GraphMemberIdentity identity = MemberIdentity(new(query.Method, query.Syntax, query.Model));

                results.Add((identity.Method, identity.Compilation, identity.Tree, identity.SpanStart, identity.SpanLength, memberMethodKeyBuilds - before));
            }

            return results;
        }

        private TraversalStateIdentity TraversalState(AuthoredMember member, string rootType, string operationId, bool lifecycle, string? inheritedWork, string? inheritedEffect, string? recoveryEffect, SyntaxNode? selection, IReadOnlySet<int>? fieldPublications, bool completionOwned, int? knownEnvironmentToken = null, bool environmentTokenObtained = false)
        {
            SyntaxNode selected = selection ?? member.Syntax;

            string rootOperation = RootOperation(operationId);

            int? environmentToken = environmentTokenObtained
                ? knownEnvironmentToken
                : TryRegisterEvaluationEnvironmentToken(member);

            string fallbackAdmission = "";

            string fallbackEnvironment = "";

            string fallbackValue = "";

            string fallbackConcrete = "";

            string fallbackRecovery = "";

            EvaluationEnvironmentFingerprint environment;

            if (environmentToken is int exactToken
                && tokenEvaluationEnvironmentFingerprints.TryGetValue(
                    exactToken,
                    out EvaluationEnvironmentFingerprint certifiedEnvironment)
                && certifiedEnvironment.Complete
                && !certifiedEnvironment.ContainsBackreference)
            {
                environment = certifiedEnvironment;
            }
            else
            {
                environment = EvaluationEnvironmentIdentity(
                    member,
                    environmentToken);
            }

            if (environmentToken is not int
                || !environment.Complete
                || environment.ContainsBackreference)
            {
                environmentToken = null;

                if (!environment.Complete
                    && limitedEvaluationEnvironments.Add(rootType + "|" + rootOperation))
                {
                    diagnostics.Add(new(
                        "HOSTED_EVALUATION_ENVIRONMENT_LIMIT_EXCEEDED",
                        rootOperation,
                        $"The exact bound evaluation environment exceeded {evaluationEnvironmentMaximumMembers} members or {evaluationEnvironmentMaximumDepth} levels for one authority root."));
                }

                fallbackAdmission = AdmissionBindingIdentity(member);

                fallbackEnvironment = environment.Identity;

                fallbackValue = "included-in-evaluation-environment";

                fallbackConcrete = ConcreteBindingIdentity(member);

                fallbackRecovery = RecoveryBindingIdentity(member);
            }

            return new(
                rootType,
                rootOperation,
                MemberIdentity(member),
                selected.SpanStart,
                selected.Span.Length,
                environmentToken,
                fallbackAdmission,
                fallbackEnvironment,
                fallbackValue,
                fallbackConcrete,
                fallbackRecovery,
                inheritedWork,
                inheritedEffect,
                recoveryEffect,
                fieldPublications is null ? "" : string.Join(",", fieldPublications.Order()),
                completionOwned,
                lifecycle);
        }

        private static string RecoveryBindingIdentity(AuthoredMember member) =>
            (member.RecoveryContext is { } context
                ? context.Kind
                    + ":"
                    + context.CheckpointVersion
                    + ":"
                    + context.Disposition
                : "unbound")
            + "|"
            + (member.RecoveryBindings is null || member.RecoveryBindings.Count == 0
                ? "unbound"
                : string.Join(
                    ";",
                    member.RecoveryBindings
                        .OrderBy(static pair => pair.Key is IParameterSymbol parameter
                            ? parameter.Ordinal
                            : int.MaxValue)
                        .ThenBy(static pair => pair.Key.ToDisplayString(), StringComparer.Ordinal)
                        .Select(static pair =>
                            (pair.Key is IParameterSymbol parameter ? parameter.Ordinal : -1)
                            + ":"
                            + pair.Value.Kind
                            + ":"
                            + pair.Value.CheckpointVersion
                            + ":"
                            + pair.Value.Disposition)));

        private EvaluationEnvironmentFingerprint EvaluationEnvironmentIdentity(
            AuthoredMember member) => EvaluationEnvironmentIdentity(
                member,
                environmentToken: null,
                environmentTokenObtained: false);

        private EvaluationEnvironmentFingerprint EvaluationEnvironmentIdentity(
            AuthoredMember member,
            int? environmentToken) => EvaluationEnvironmentIdentity(
                member,
                environmentToken,
                environmentTokenObtained: true);

        private EvaluationEnvironmentFingerprint EvaluationEnvironmentIdentity(
            AuthoredMember member,
            int? environmentToken,
            bool environmentTokenObtained)
        {
            string metricMember = MethodKey(member.Symbol);

            if (!evaluationEnvironmentAnalysis.TryGetValue(
                    metricMember,
                    out EvaluationEnvironmentAnalysisCounter? analysis))
            {
                analysis = new();

                evaluationEnvironmentAnalysis.Add(metricMember, analysis);
            }

            analysis.FingerprintRequests++;

            if (evaluationEnvironmentFingerprints.TryGetValue(
                    member,
                    out EvaluationEnvironmentFingerprint cached))
            {
                return cached;
            }

            int? token = environmentTokenObtained
                ? environmentToken
                : TryRegisterEvaluationEnvironmentToken(member);

            if (token is int exactToken
                && tokenEvaluationEnvironmentFingerprints.TryGetValue(
                    exactToken,
                    out cached))
            {
                evaluationEnvironmentFingerprints.Add(member, cached);

                return cached;
            }

            EvaluationEnvironmentCacheIdentity? cacheIdentity =
                EvaluationEnvironmentCacheIdentityFor(member, analysis);

            if (cacheIdentity is { } exactCacheIdentity
                && equivalentEvaluationEnvironmentFingerprints.TryGetValue(
                    exactCacheIdentity,
                    out cached))
            {
                evaluationEnvironmentFingerprints.Add(member, cached);

                if (token is int cacheToken)
                {
                    tokenEvaluationEnvironmentFingerprints.TryAdd(
                        cacheToken,
                        cached);
                }

                return cached;
            }

            analysis.FingerprintBuilds++;

            EvaluationEnvironmentIdentityContext context = new(
                evaluationEnvironmentMaximumMembers,
                evaluationEnvironmentMaximumDepth);

            EvaluationEnvironmentFingerprint result = EvaluationEnvironmentIdentity(
                member,
                context,
                0);

            if (result.Complete && !result.ContainsBackreference)
            {
                evaluationEnvironmentFingerprints.Add(member, result);

                if (cacheIdentity is { } cacheableIdentity)
                {
                    equivalentEvaluationEnvironmentFingerprints.TryAdd(
                        cacheableIdentity,
                        result);
                }

                if (token is int resultToken)
                {
                    tokenEvaluationEnvironmentFingerprints.TryAdd(
                        resultToken,
                        result);
                }
            }

            return result;
        }

        private EvaluationEnvironmentCacheIdentity?
            EvaluationEnvironmentCacheIdentityFor(
                AuthoredMember member,
                EvaluationEnvironmentAnalysisCounter analysis)
        {
            analysis.EquivalentKeyBuilds++;

            EvaluationEnvironmentCacheIdentityContext context = new(
                evaluationEnvironmentMaximumMembers,
                evaluationEnvironmentMaximumDepth);

            return EvaluationEnvironmentCacheIdentityFor(
                member,
                context,
                analysis,
                0);
        }

        private EvaluationEnvironmentCacheIdentity?
            EvaluationEnvironmentCacheIdentityFor(
                AuthoredMember member,
                EvaluationEnvironmentCacheIdentityContext context,
                EvaluationEnvironmentAnalysisCounter analysis,
                int depth)
        {
            if (context.Memoized.TryGetValue(
                    member,
                    out EvaluationEnvironmentCacheIdentity cached))
            {
                return cached;
            }

            analysis.EquivalentKeyNodes++;

            EvaluationEnvironmentNodeIdentity traversalNode = new(
                MemberIdentity(member),
                EvaluationEnvironmentLocalBindingIdentity(member));

            if (context.Active.ContainsKey(traversalNode)
                || depth >= context.MaximumDepth
                || context.Members >= context.MaximumMembers)
            {
                return null;
            }

            context.Members++;

            context.Active.Add(traversalNode, depth);

            try
            {
                EvaluationEnvironmentNodeIdentity node = new(
                    MemberIdentity(member),
                    EvaluationEnvironmentIntrinsicBindingIdentity(member));

                StringBuilder references = new();

                AppendIdentitySection(
                    references,
                    "callable-bindings",
                    member.CallableBindings?.Count ?? 0);

                foreach ((ISymbol symbol, AuthoredMember target) in
                    member.CallableBindings?
                        .OrderBy(pair => BindingSymbolIdentity(
                            pair.Key,
                            member), StringComparer.Ordinal)
                        ?? Enumerable.Empty<KeyValuePair<ISymbol, AuthoredMember>>())
                {
                    AuthoredMember normalizedTarget =
                        NormalizeEvaluationCallableTarget(target);

                    EvaluationEnvironmentCacheIdentity? targetIdentity =
                        EvaluationEnvironmentCacheIdentityFor(
                            normalizedTarget,
                            context,
                            analysis,
                            depth + 1);

                    if (targetIdentity is not { } exactTargetIdentity)
                    {
                        return null;
                    }

                    AppendIdentitySegment(references, "callable");

                    AppendIdentitySegment(
                        references,
                        BindingSymbolIdentity(symbol, member));

                    AppendEvaluationEnvironmentCacheIdentity(
                        references,
                        exactTargetIdentity);
                }

                AppendIdentitySection(
                    references,
                    "value-bindings",
                    member.ValueBindings?.Count ?? 0);

                foreach ((ISymbol symbol, BoundValueSource source) in
                    member.ValueBindings?
                        .OrderBy(pair => BindingSymbolIdentity(
                            pair.Key,
                            member), StringComparer.Ordinal)
                        ?? Enumerable.Empty<KeyValuePair<ISymbol, BoundValueSource>>())
                {
                    BoundValueSource normalizedSource =
                        NormalizeEvaluationValueSource(source);

                    if (TryConstantValueIdentity(normalizedSource, out string constantIdentity))
                    {
                        AppendIdentitySegment(references, "value-constant");

                        AppendIdentitySegment(
                            references,
                            BindingSymbolIdentity(symbol, member));

                        AppendIdentitySegment(references, constantIdentity);

                        continue;
                    }

                    AuthoredMember projectedCaller =
                        ProjectEvaluationEnvironment(
                            normalizedSource.Caller,
                            normalizedSource.Expression);

                    EvaluationEnvironmentCacheIdentity? callerIdentity =
                        EvaluationEnvironmentCacheIdentityFor(
                            projectedCaller,
                            context,
                            analysis,
                            depth + 1);

                    if (callerIdentity is not { } exactCallerIdentity)
                    {
                        return null;
                    }

                    AppendIdentitySegment(references, "value");

                    AppendIdentitySegment(
                        references,
                        BindingSymbolIdentity(symbol, member));

                    AppendIdentitySegment(
                        references,
                        normalizedSource.Expression.SpanStart.ToString(
                            CultureInfo.InvariantCulture));

                    AppendIdentitySegment(
                        references,
                        normalizedSource.Expression.Span.Length.ToString(
                            CultureInfo.InvariantCulture));

                    AppendEvaluationEnvironmentCacheIdentity(
                        references,
                        exactCallerIdentity);
                }

                EvaluationEnvironmentCacheIdentity result = new(
                    node,
                    CompactIdentity(references.ToString()));

                context.Memoized.Add(member, result);

                return result;
            }
            finally
            {
                context.Active.Remove(traversalNode);
            }
        }

        private static void AppendEvaluationEnvironmentCacheIdentity(
            StringBuilder value,
            EvaluationEnvironmentCacheIdentity identity)
        {
            AppendIdentitySegment(value, identity.Node.Member.Assembly.ToString());

            AppendIdentitySegment(
                value,
                identity.Node.Member.Compilation.ToString(CultureInfo.InvariantCulture));

            AppendIdentitySegment(
                value,
                identity.Node.Member.Tree.ToString(CultureInfo.InvariantCulture));

            AppendIdentitySegment(value, identity.Node.Member.Method);

            AppendIdentitySegment(
                value,
                identity.Node.Member.SpanStart.ToString(CultureInfo.InvariantCulture));

            AppendIdentitySegment(
                value,
                identity.Node.Member.SpanLength.ToString(CultureInfo.InvariantCulture));

            AppendIdentitySegment(value, identity.Node.LocalBindings);

            AppendIdentitySegment(value, identity.ReferencedMembers);
        }

        private int? TryRegisterEvaluationEnvironmentToken(AuthoredMember member)
        {
            EvaluationEnvironmentAnalysisCounter analysis =
                EvaluationEnvironmentCounter(member);

            analysis.InternerRequests++;

            if (evaluationEnvironmentTokens.TryGetValue(
                    member,
                    out int existingToken))
            {
                analysis.InternerHits++;

                return existingToken;
            }

            if (EvaluationEnvironmentIsEmpty(member))
            {
                return RegisterEmptyEvaluationEnvironmentToken(
                    member,
                    analysis);
            }

            analysis.InternerContextBuilds++;

            EvaluationEnvironmentTokenContext context = new(
                evaluationEnvironmentMaximumMembers,
                evaluationEnvironmentMaximumDepth);

            return TryRegisterEvaluationEnvironmentToken(
                member,
                context,
                0,
                requestAccounted: true);
        }

        private int? TryRegisterEvaluationEnvironmentToken(
            AuthoredMember member,
            EvaluationEnvironmentTokenContext context,
            int depth,
            bool requestAccounted = false)
        {
            EvaluationEnvironmentAnalysisCounter analysis =
                EvaluationEnvironmentCounter(member);

            if (!requestAccounted)
            {
                analysis.InternerRequests++;

                if (evaluationEnvironmentTokens.TryGetValue(
                        member,
                        out int exactToken))
                {
                    analysis.InternerHits++;

                    return exactToken;
                }
            }

            if (context.Memoized.TryGetValue(member, out int? memoized))
            {
                return memoized;
            }

            if (EvaluationEnvironmentIsEmpty(member))
            {
                int emptyToken = RegisterEmptyEvaluationEnvironmentToken(
                    member,
                    analysis);

                context.Memoized[member] = emptyToken;

                return emptyToken;
            }

            analysis.InternerTraversalIdentityBuilds++;

            EvaluationEnvironmentNodeIdentity traversalNode = new(
                MemberIdentity(member),
                EvaluationEnvironmentLocalBindingIdentity(member));

            if (depth >= context.MaximumDepth
                || context.Members >= context.MaximumMembers
                || !context.Active.Add(traversalNode))
            {
                context.Memoized[member] = null;

                return null;
            }

            context.Members++;

            try
            {
                StringBuilder references = new();

                AppendIdentitySection(
                    references,
                    "callable-bindings",
                    member.CallableBindings?.Count ?? 0);

                foreach ((ISymbol symbol, AuthoredMember target) in
                    member.CallableBindings?
                        .OrderBy(pair => BindingSymbolIdentity(
                            pair.Key,
                            member), StringComparer.Ordinal)
                        ?? Enumerable.Empty<KeyValuePair<ISymbol, AuthoredMember>>())
                {
                    AuthoredMember normalizedTarget =
                        NormalizeEvaluationCallableTarget(target);

                    int? targetId = TryRegisterEvaluationEnvironmentToken(
                        normalizedTarget,
                        context,
                        depth + 1);

                    if (targetId is not int exactTargetId)
                    {
                        context.Memoized[member] = null;

                        return null;
                    }

                    AppendIdentitySegment(references, "callable");

                    AppendIdentitySegment(
                        references,
                        BindingSymbolIdentity(symbol, member));

                    AppendIdentitySegment(
                        references,
                        exactTargetId.ToString(CultureInfo.InvariantCulture));
                }

                AppendIdentitySection(
                    references,
                    "value-bindings",
                    member.ValueBindings?.Count ?? 0);

                foreach ((ISymbol symbol, BoundValueSource source) in
                    member.ValueBindings?
                        .OrderBy(pair => BindingSymbolIdentity(
                            pair.Key,
                            member), StringComparer.Ordinal)
                        ?? Enumerable.Empty<KeyValuePair<ISymbol, BoundValueSource>>())
                {
                    BoundValueSource normalizedSource =
                        NormalizeEvaluationValueSource(source);

                    if (TryConstantValueIdentity(normalizedSource, out string constantIdentity))
                    {
                        AppendIdentitySegment(references, "value-constant");

                        AppendIdentitySegment(
                            references,
                            BindingSymbolIdentity(symbol, member));

                        AppendIdentitySegment(references, constantIdentity);

                        continue;
                    }

                    AuthoredMember projectedCaller =
                        ProjectEvaluationEnvironment(
                            normalizedSource.Caller,
                            normalizedSource.Expression);

                    int? callerId = TryRegisterEvaluationEnvironmentToken(
                        projectedCaller,
                        context,
                        depth + 1);

                    if (callerId is not int exactCallerId)
                    {
                        context.Memoized[member] = null;

                        return null;
                    }

                    AppendIdentitySegment(references, "value");

                    AppendIdentitySegment(
                        references,
                        BindingSymbolIdentity(symbol, member));

                    AppendIdentitySegment(
                        references,
                        exactCallerId.ToString(CultureInfo.InvariantCulture));

                    AppendIdentitySegment(
                        references,
                        TreeIdentity(normalizedSource.Expression.SyntaxTree)
                            .ToString(CultureInfo.InvariantCulture));

                    AppendIdentitySegment(
                        references,
                        normalizedSource.Expression.SpanStart.ToString(
                            CultureInfo.InvariantCulture));

                    AppendIdentitySegment(
                        references,
                        normalizedSource.Expression.Span.Length.ToString(
                            CultureInfo.InvariantCulture));

                    AppendIdentitySegment(
                        references,
                        Fingerprint(normalizedSource.Expression));
                }

                analysis.InternerIdentityBuilds++;

                EvaluationEnvironmentInternIdentity identity = new(
                    new(
                        MemberIdentity(member),
                        EvaluationEnvironmentIntrinsicBindingIdentity(member)),
                    CompactIdentity(references.ToString()));

                if (internedEvaluationEnvironmentTokens.TryGetValue(
                        identity,
                        out int existingToken))
                {
                    analysis.InternerHits++;

                    evaluationEnvironmentTokens.Add(member, existingToken);

                    context.Memoized[member] = existingToken;

                    return existingToken;
                }

                int token = nextEvaluationEnvironmentToken++;

                internedEvaluationEnvironmentTokens.Add(identity, token);

                evaluationEnvironmentTokens.Add(
                    member,
                    token);

                analysis.InternerRegistrations++;

                context.Memoized[member] = token;

                return token;
            }
            finally
            {
                context.Active.Remove(traversalNode);
            }
        }

        private int RegisterEmptyEvaluationEnvironmentToken(
            AuthoredMember member,
            EvaluationEnvironmentAnalysisCounter analysis)
        {
            GraphMemberIdentity emptyIdentity = MemberIdentity(member);

            if (!emptyEvaluationEnvironmentTokens.TryGetValue(
                    emptyIdentity,
                    out int token))
            {
                token = nextEvaluationEnvironmentToken++;

                emptyEvaluationEnvironmentTokens.Add(
                    emptyIdentity,
                    token);

                analysis.InternerRegistrations++;
            }
            else
            {
                analysis.InternerHits++;
            }

            evaluationEnvironmentTokens.Add(member, token);

            return token;
        }

        private static bool EvaluationEnvironmentIsEmpty(AuthoredMember member) =>
            member.AdmissionBindings is not { Count: > 0 }
            && member.CallableBindings is not { Count: > 0 }
            && member.AbsentCallables is not { Count: > 0 }
            && member.ConcreteBindings is not { Count: > 0 }
            && member.RecoveryBindings is not { Count: > 0 }
            && member.RecoveryContext is null
            && member.ValueBindings is not { Count: > 0 }
            && member.ConstructorContexts is not { Count: > 0 }
            && member.OrdinaryScopedHolder is null
            && member.ReadinessSource is null
            && member.ScopedLeaseInstance is null;

        private EvaluationEnvironmentAnalysisCounter EvaluationEnvironmentCounter(
            AuthoredMember member)
        {
            string metricMember = MethodKey(member.Symbol);

            if (!evaluationEnvironmentAnalysis.TryGetValue(
                    metricMember,
                    out EvaluationEnvironmentAnalysisCounter? analysis))
            {
                analysis = new();

                evaluationEnvironmentAnalysis.Add(metricMember, analysis);
            }

            return analysis;
        }

        private EvaluationEnvironmentFingerprint EvaluationEnvironmentIdentity(
            AuthoredMember member,
            EvaluationEnvironmentIdentityContext context,
            int depth)
        {
            if (context.Memoized.TryGetValue(member, out EvaluationEnvironmentFingerprint cached))
            {
                return cached;
            }

            GraphMemberIdentity identity = MemberIdentity(member);

            EvaluationEnvironmentNodeIdentity nodeIdentity = new(
                identity,
                EvaluationEnvironmentLocalBindingIdentity(member));

            if (context.Active.TryGetValue(nodeIdentity, out int activeDepth))
            {
                return new(
                    "backreference:"
                        + (depth - activeDepth).ToString(CultureInfo.InvariantCulture)
                        + ":"
                        + nodeIdentity.LocalBindings,
                    true,
                    true);
            }

            if (depth >= context.MaximumDepth)
            {
                return new("depth-limit", false, false);
            }

            if (context.Members >= context.MaximumMembers)
            {
                return new("member-limit", false, false);
            }

            context.Members++;

            context.Active.Add(nodeIdentity, depth);

            try
            {
                StringBuilder value = new();

                bool complete = true;

                bool containsBackreference = false;

                AppendIdentitySegment(value, "member");

                AppendIdentitySegment(value, identity.Assembly.ToString());

                AppendIdentitySegment(value, identity.Compilation.ToString(CultureInfo.InvariantCulture));

                AppendIdentitySegment(value, identity.Tree.ToString(CultureInfo.InvariantCulture));

                AppendIdentitySegment(value, identity.Method);

                AppendIdentitySegment(value, identity.SpanStart.ToString(CultureInfo.InvariantCulture));

                AppendIdentitySegment(value, identity.SpanLength.ToString(CultureInfo.InvariantCulture));

                AppendIdentitySection(
                    value,
                    "admission-bindings",
                    member.AdmissionBindings?.Count ?? 0);

                foreach ((ISymbol symbol, IReadOnlySet<string> origins) in
                    member.AdmissionBindings?
                        .OrderBy(pair => BindingSymbolIdentity(pair.Key, member), StringComparer.Ordinal)
                        ?? Enumerable.Empty<KeyValuePair<ISymbol, IReadOnlySet<string>>>())
                {
                    AppendIdentitySegment(value, "admission");

                    AppendIdentitySegment(value, BindingSymbolIdentity(symbol, member));

                    AppendIdentitySegment(
                        value,
                        origins.Count.ToString(CultureInfo.InvariantCulture));

                    foreach (string origin in origins.Order(StringComparer.Ordinal))
                    {
                        AppendIdentitySegment(value, origin);
                    }
                }

                AppendIdentitySection(
                    value,
                    "concrete-bindings",
                    member.ConcreteBindings?.Count ?? 0);

                foreach ((ISymbol symbol, ITypeSymbol concrete) in
                    member.ConcreteBindings?
                        .OrderBy(pair => BindingSymbolIdentity(pair.Key, member), StringComparer.Ordinal)
                        ?? Enumerable.Empty<KeyValuePair<ISymbol, ITypeSymbol>>())
                {
                    BoundTypeIdentity type = TypeIdentity(
                        concrete,
                        member.Model.Compilation);

                    AppendIdentitySegment(value, "concrete");

                    AppendIdentitySegment(value, BindingSymbolIdentity(symbol, member));

                    AppendIdentitySegment(value, type.Assembly.ToString());

                    AppendIdentitySegment(
                        value,
                        type.Compilation?.ToString(CultureInfo.InvariantCulture)
                            ?? "external");

                    AppendIdentitySegment(value, type.Type);
                }

                if (member.RecoveryContext is { } recoveryContext)
                {
                    AppendIdentitySegment(value, "recovery-context");

                    AppendRecoveryTuple(value, recoveryContext);
                }
                else
                {
                    AppendIdentitySegment(value, "no-recovery-context");
                }

                AppendIdentitySection(
                    value,
                    "recovery-bindings",
                    member.RecoveryBindings?.Count ?? 0);

                foreach ((ISymbol symbol, RecoveryTuple tuple) in
                    member.RecoveryBindings?
                        .OrderBy(pair => BindingSymbolIdentity(pair.Key, member), StringComparer.Ordinal)
                        ?? Enumerable.Empty<KeyValuePair<ISymbol, RecoveryTuple>>())
                {
                    AppendIdentitySegment(value, "recovery");

                    AppendIdentitySegment(value, BindingSymbolIdentity(symbol, member));

                    AppendRecoveryTuple(value, tuple);
                }

                AppendIdentitySection(
                    value,
                    "absent-callables",
                    member.AbsentCallables?.Count ?? 0);

                foreach (ISymbol symbol in
                    member.AbsentCallables?
                        .OrderBy(symbol => BindingSymbolIdentity(symbol, member), StringComparer.Ordinal)
                        ?? Enumerable.Empty<ISymbol>())
                {
                    AppendIdentitySegment(value, "absent-callable");

                    AppendIdentitySegment(value, BindingSymbolIdentity(symbol, member));
                }

                AppendIdentitySection(
                    value,
                    "callable-bindings",
                    member.CallableBindings?.Count ?? 0);

                foreach ((ISymbol symbol, AuthoredMember target) in
                    member.CallableBindings?
                        .OrderBy(pair => BindingSymbolIdentity(pair.Key, member), StringComparer.Ordinal)
                        ?? Enumerable.Empty<KeyValuePair<ISymbol, AuthoredMember>>())
                {
                    AuthoredMember normalizedTarget =
                        NormalizeEvaluationCallableTarget(target);

                    EvaluationEnvironmentFingerprint targetEnvironment =
                        EvaluationEnvironmentIdentity(
                            normalizedTarget,
                            context,
                            depth + 1);

                    complete &= targetEnvironment.Complete;

                    containsBackreference |= targetEnvironment.ContainsBackreference;

                    AppendIdentitySegment(value, "callable");

                    AppendIdentitySegment(value, BindingSymbolIdentity(symbol, member));

                    AppendIdentitySegment(value, targetEnvironment.Identity);
                }

                AppendIdentitySection(
                    value,
                    "value-bindings",
                    member.ValueBindings?.Count ?? 0);

                foreach ((ISymbol symbol, BoundValueSource source) in
                    member.ValueBindings?
                        .OrderBy(pair => BindingSymbolIdentity(pair.Key, member), StringComparer.Ordinal)
                        ?? Enumerable.Empty<KeyValuePair<ISymbol, BoundValueSource>>())
                {
                    BoundValueSource normalizedSource =
                        NormalizeEvaluationValueSource(source);

                    if (TryConstantValueIdentity(normalizedSource, out string constantIdentity))
                    {
                        AppendIdentitySegment(value, "value-constant");

                        AppendIdentitySegment(value, BindingSymbolIdentity(symbol, member));

                        AppendIdentitySegment(value, constantIdentity);

                        continue;
                    }

                    AuthoredMember projectedCaller =
                        ProjectEvaluationEnvironment(
                            normalizedSource.Caller,
                            normalizedSource.Expression);

                    EvaluationEnvironmentFingerprint callerEnvironment =
                        EvaluationEnvironmentIdentity(
                            projectedCaller,
                            context,
                            depth + 1);

                    complete &= callerEnvironment.Complete;

                    containsBackreference |= callerEnvironment.ContainsBackreference;

                    AppendIdentitySegment(value, "value");

                    AppendIdentitySegment(value, BindingSymbolIdentity(symbol, member));

                    AppendIdentitySegment(value, normalizedSource.Expression.SpanStart.ToString(CultureInfo.InvariantCulture));

                    AppendIdentitySegment(value, normalizedSource.Expression.Span.Length.ToString(CultureInfo.InvariantCulture));

                    AppendIdentitySegment(value, callerEnvironment.Identity);
                }

                AppendOrdinaryScopedHolderIdentity(value, member);

                EvaluationEnvironmentFingerprint result = new(
                    CompactIdentity(value.ToString()),
                    complete,
                    containsBackreference);

                if (complete && !containsBackreference)
                {
                    context.Memoized.Add(member, result);
                }

                return result;
            }
            finally
            {
                context.Active.Remove(nodeIdentity);
            }
        }

        private void AppendEvaluationEnvironmentIntrinsicBindings(
            StringBuilder value,
            AuthoredMember member)
        {
            AppendOrdinaryScopedHolderIdentity(value, member);

            AppendIdentitySection(
                value,
                "constructor-contexts",
                member.ConstructorContexts?.Count ?? 0);

            foreach (IMethodSymbol constructor in
                member.ConstructorContexts?
                    .OrderBy(
                        constructor => BindingSymbolIdentity(
                            constructor,
                            member),
                        StringComparer.Ordinal)
                    ?? Enumerable.Empty<IMethodSymbol>())
            {
                AppendIdentitySegment(value, "constructor");

                AppendIdentitySegment(
                    value,
                    BindingSymbolIdentity(constructor, member));
            }

            AppendIdentitySection(
                value,
                "admission-bindings",
                member.AdmissionBindings?.Count ?? 0);

            foreach ((ISymbol symbol, IReadOnlySet<string> origins) in
                member.AdmissionBindings?
                    .OrderBy(pair => BindingSymbolIdentity(pair.Key, member), StringComparer.Ordinal)
                    ?? Enumerable.Empty<KeyValuePair<ISymbol, IReadOnlySet<string>>>())
            {
                AppendIdentitySegment(value, "admission");

                AppendIdentitySegment(value, BindingSymbolIdentity(symbol, member));

                AppendIdentitySegment(
                    value,
                    origins.Count.ToString(CultureInfo.InvariantCulture));

                foreach (string origin in origins.Order(StringComparer.Ordinal))
                {
                    AppendIdentitySegment(value, origin);
                }
            }

            AppendIdentitySection(
                value,
                "concrete-bindings",
                member.ConcreteBindings?.Count ?? 0);

            foreach ((ISymbol symbol, ITypeSymbol concrete) in
                member.ConcreteBindings?
                    .OrderBy(pair => BindingSymbolIdentity(pair.Key, member), StringComparer.Ordinal)
                    ?? Enumerable.Empty<KeyValuePair<ISymbol, ITypeSymbol>>())
            {
                BoundTypeIdentity type = TypeIdentity(concrete, member.Model.Compilation);

                AppendIdentitySegment(value, "concrete");

                AppendIdentitySegment(value, BindingSymbolIdentity(symbol, member));

                AppendIdentitySegment(value, type.Assembly.ToString());

                AppendIdentitySegment(value, type.Compilation?.ToString(CultureInfo.InvariantCulture) ?? "external");

                AppendIdentitySegment(value, type.Type);
            }

            if (member.RecoveryContext is { } recoveryContext)
            {
                AppendIdentitySegment(value, "recovery-context");

                AppendRecoveryTuple(value, recoveryContext);
            }
            else
            {
                AppendIdentitySegment(value, "no-recovery-context");
            }

            AppendIdentitySection(
                value,
                "recovery-bindings",
                member.RecoveryBindings?.Count ?? 0);

            foreach ((ISymbol symbol, RecoveryTuple tuple) in
                member.RecoveryBindings?
                    .OrderBy(pair => BindingSymbolIdentity(pair.Key, member), StringComparer.Ordinal)
                    ?? Enumerable.Empty<KeyValuePair<ISymbol, RecoveryTuple>>())
            {
                AppendIdentitySegment(value, "recovery");

                AppendIdentitySegment(value, BindingSymbolIdentity(symbol, member));

                AppendRecoveryTuple(value, tuple);
            }

            AppendIdentitySection(
                value,
                "absent-callables",
                member.AbsentCallables?.Count ?? 0);

            foreach (ISymbol symbol in
                member.AbsentCallables?
                    .OrderBy(symbol => BindingSymbolIdentity(symbol, member), StringComparer.Ordinal)
                    ?? Enumerable.Empty<ISymbol>())
            {
                AppendIdentitySegment(value, "absent-callable");

                AppendIdentitySegment(value, BindingSymbolIdentity(symbol, member));
            }
        }

        private string EvaluationEnvironmentIntrinsicBindingIdentity(
            AuthoredMember member)
        {
            StringBuilder value = new();

            AppendEvaluationEnvironmentIntrinsicBindings(value, member);

            return CompactIdentity(value.ToString());
        }

        private string EvaluationEnvironmentLocalBindingIdentity(
            AuthoredMember member)
        {
            StringBuilder value = new();

            AppendOrdinaryScopedHolderIdentity(value, member);

            void AppendMember(GraphMemberIdentity identity)
            {
                AppendIdentitySegment(value, identity.Assembly.ToString());

                AppendIdentitySegment(value, identity.Compilation.ToString(CultureInfo.InvariantCulture));

                AppendIdentitySegment(value, identity.Tree.ToString(CultureInfo.InvariantCulture));

                AppendIdentitySegment(value, identity.Method);

                AppendIdentitySegment(value, identity.SpanStart.ToString(CultureInfo.InvariantCulture));

                AppendIdentitySegment(value, identity.SpanLength.ToString(CultureInfo.InvariantCulture));
            }

            AppendIdentitySection(
                value,
                "constructor",
                member.ConstructorContexts?.Count ?? 0);

            foreach (IMethodSymbol constructor in
                member.ConstructorContexts?
                    .OrderBy(
                        constructor => BindingSymbolIdentity(
                            constructor,
                            member),
                        StringComparer.Ordinal)
                    ?? Enumerable.Empty<IMethodSymbol>())
            {
                AppendIdentitySegment(
                    value,
                    BindingSymbolIdentity(constructor, member));
            }

            AppendIdentitySection(value, "admission", member.AdmissionBindings?.Count ?? 0);

            foreach ((ISymbol symbol, IReadOnlySet<string> origins) in
                member.AdmissionBindings?
                    .OrderBy(pair => BindingSymbolIdentity(pair.Key, member), StringComparer.Ordinal)
                    ?? Enumerable.Empty<KeyValuePair<ISymbol, IReadOnlySet<string>>>())
            {
                AppendIdentitySegment(value, BindingSymbolIdentity(symbol, member));

                foreach (string origin in origins.Order(StringComparer.Ordinal))
                {
                    AppendIdentitySegment(value, origin);
                }
            }

            AppendIdentitySection(value, "concrete", member.ConcreteBindings?.Count ?? 0);

            foreach ((ISymbol symbol, ITypeSymbol concrete) in
                member.ConcreteBindings?
                    .OrderBy(pair => BindingSymbolIdentity(pair.Key, member), StringComparer.Ordinal)
                    ?? Enumerable.Empty<KeyValuePair<ISymbol, ITypeSymbol>>())
            {
                BoundTypeIdentity type = TypeIdentity(concrete, member.Model.Compilation);

                AppendIdentitySegment(value, BindingSymbolIdentity(symbol, member));

                AppendIdentitySegment(value, type.Assembly.ToString());

                AppendIdentitySegment(value, type.Compilation?.ToString(CultureInfo.InvariantCulture) ?? "external");

                AppendIdentitySegment(value, type.Type);
            }

            if (member.RecoveryContext is { } recoveryContext)
            {
                AppendIdentitySegment(value, "recovery-context");

                AppendRecoveryTuple(value, recoveryContext);
            }
            else
            {
                AppendIdentitySegment(value, "no-recovery-context");
            }

            AppendIdentitySection(value, "recovery", member.RecoveryBindings?.Count ?? 0);

            foreach ((ISymbol symbol, RecoveryTuple tuple) in
                member.RecoveryBindings?
                    .OrderBy(pair => BindingSymbolIdentity(pair.Key, member), StringComparer.Ordinal)
                    ?? Enumerable.Empty<KeyValuePair<ISymbol, RecoveryTuple>>())
            {
                AppendIdentitySegment(value, BindingSymbolIdentity(symbol, member));

                AppendRecoveryTuple(value, tuple);
            }

            AppendIdentitySection(value, "absent", member.AbsentCallables?.Count ?? 0);

            foreach (ISymbol symbol in
                member.AbsentCallables?
                    .OrderBy(symbol => BindingSymbolIdentity(symbol, member), StringComparer.Ordinal)
                    ?? Enumerable.Empty<ISymbol>())
            {
                AppendIdentitySegment(value, BindingSymbolIdentity(symbol, member));
            }

            AppendIdentitySection(value, "callable", member.CallableBindings?.Count ?? 0);

            foreach ((ISymbol symbol, AuthoredMember target) in
                member.CallableBindings?
                    .OrderBy(pair => BindingSymbolIdentity(pair.Key, member), StringComparer.Ordinal)
                    ?? Enumerable.Empty<KeyValuePair<ISymbol, AuthoredMember>>())
            {
                AppendIdentitySegment(value, BindingSymbolIdentity(symbol, member));

                AppendMember(MemberIdentity(NormalizeEvaluationCallableTarget(target)));
            }

            AppendIdentitySection(value, "value", member.ValueBindings?.Count ?? 0);

            foreach ((ISymbol symbol, BoundValueSource source) in
                member.ValueBindings?
                    .OrderBy(pair => BindingSymbolIdentity(pair.Key, member), StringComparer.Ordinal)
                    ?? Enumerable.Empty<KeyValuePair<ISymbol, BoundValueSource>>())
            {
                AppendIdentitySegment(value, BindingSymbolIdentity(symbol, member));

                AppendMember(MemberIdentity(source.Caller));

                AppendIdentitySegment(value, TreeIdentity(source.Expression.SyntaxTree).ToString(CultureInfo.InvariantCulture));

                AppendIdentitySegment(value, source.Expression.SpanStart.ToString(CultureInfo.InvariantCulture));

                AppendIdentitySegment(value, source.Expression.Span.Length.ToString(CultureInfo.InvariantCulture));

                AppendIdentitySegment(value, Fingerprint(source.Expression));
            }

            return CompactIdentity(value.ToString());
        }

        private AuthoredMember NormalizeEvaluationCallableTarget(
            AuthoredMember target)
        {
            HashSet<AuthoredMember> path = new(ReferenceEqualityComparer.Instance);

            while (path.Add(target)
                && target.Symbol.MethodKind == MethodKind.AnonymousFunction
                && target.Syntax.AncestorsAndSelf()
                    .OfType<AnonymousFunctionExpressionSyntax>()
                    .FirstOrDefault() is { AsyncKeyword.RawKind: 0 }
                && target.Syntax is InvocationExpressionSyntax invocation
                && invocation.ArgumentList.Arguments.Count == 0
                && target.Model.GetSymbolInfo(invocation).Symbol is IMethodSymbol
                {
                    MethodKind: MethodKind.DelegateInvoke,
                }
                && target.Model.GetSymbolInfo(invocation.Expression).Symbol is { } invoked
                && target.CallableBindings is { } bindings
                && bindings.TryGetValue(invoked, out AuthoredMember? forwarded)
                && forwarded is not null)
            {
                target = forwarded;
            }

            return target;
        }

        private BoundValueSource NormalizeEvaluationValueSource(
            BoundValueSource source)
        {
            AuthoredMember initialCaller = source.Caller;

            ExpressionSyntax initialExpression = source.Expression;

            EvaluationEnvironmentAnalysisCounter analysis =
                EvaluationEnvironmentCounter(initialCaller);

            analysis.ValueNormalizationRequests++;

            if (completeEvaluationValueSourceNormalizations.TryGetValue(
                    source.Caller,
                    out Dictionary<ExpressionSyntax, BoundValueSource>? cached)
                && cached.TryGetValue(source.Expression, out BoundValueSource? normalized))
            {
                analysis.ValueNormalizationHits++;

                return normalized;
            }

            analysis.ValueNormalizationBuilds++;

            HashSet<(GraphMemberIdentity Member, int Start, int Length)> path = [];

            bool complete = true;

            while (true)
            {
                if (!TryNormalizeBuiltInCleanupValue(
                        source.Caller.Model,
                        source.Expression,
                        out ExpressionSyntax expression,
                        requireIdentityPreservingCasts: true))
                {
                    complete = false;

                    break;
                }

                source = new(source.Caller, expression);

                if (!path.Add((
                        MemberIdentity(source.Caller),
                        expression.SpanStart,
                        expression.Span.Length)))
                {
                    complete = false;

                    break;
                }

                if (TryResolveStableBoundValueSource(
                        source.Caller,
                        expression,
                        out BoundValueSource? bound)
                    && bound is not null)
                {
                    source = bound;

                    continue;
                }

                if (TryResolveStableLocalInitializerValueSource(
                        source.Caller,
                        expression,
                        out BoundValueSource? initialized)
                    && initialized is not null)
                {
                    source = initialized;

                    continue;
                }

                if (expression is InvocationExpressionSyntax invocation
                    && TryResolveExactIdentityValueSource(
                        source.Caller,
                        invocation,
                        out BoundValueSource? forwarded)
                    && forwarded is not null)
                {
                    source = forwarded;

                    continue;
                }

                break;
            }

            if (complete)
            {
                if (!completeEvaluationValueSourceNormalizations.TryGetValue(
                        initialCaller,
                        out Dictionary<ExpressionSyntax, BoundValueSource>?
                            sources))
                {
                    sources = new(ReferenceEqualityComparer.Instance);

                    completeEvaluationValueSourceNormalizations.Add(
                        initialCaller,
                        sources);
                }

                sources[initialExpression] = source;
            }

            return source;
        }

        private bool TryResolveStableLocalInitializerValueSource(
            AuthoredMember caller,
            ExpressionSyntax expression,
            out BoundValueSource? source)
        {
            source = null;

            if (caller.Model.GetSymbolInfo(expression).Symbol is not
                    ILocalSymbol local
                || !SymbolEqualityComparer.Default.Equals(
                    local.ContainingSymbol,
                    caller.Symbol)
                || local.DeclaringSyntaxReferences.SingleOrDefault()
                    ?.GetSyntax() is not VariableDeclaratorSyntax
                    {
                        Initializer.Value: { } initializer,
                    } variable
                || variable.SyntaxTree != caller.Syntax.SyntaxTree
                || !caller.Syntax.Span.Contains(variable.Span))
            {
                return false;
            }

            EvaluationEnvironmentAnalysisCounter analysis =
                EvaluationEnvironmentCounter(caller);

            analysis.StableLocalProofRequests++;

            StableLocalInitializerProofIdentity identity = new(
                MemberIdentity(caller),
                variable.SpanStart,
                variable.Span.Length,
                expression.SpanStart,
                expression.Span.Length);

            if (!stableLocalInitializerProofs.TryGetValue(
                    identity,
                    out bool stable))
            {
                analysis.StableLocalProofBuilds++;

                stable = RecoveryTupleSourceIsStable(
                    caller,
                    local,
                    expression,
                    allowSimpleLocalAssignments: false);

                stableLocalInitializerProofs.Add(identity, stable);
            }
            else
            {
                analysis.StableLocalProofHits++;
            }

            if (!stable)
            {
                return false;
            }

            source = new(
                ValueExpressionContext(caller, initializer),
                initializer);

            return true;
        }

        private bool TryResolveExactIdentityValueSource(
            AuthoredMember caller,
            InvocationExpressionSyntax call,
            out BoundValueSource? source)
        {
            source = null;

            if (caller.Model.GetSymbolInfo(call).Symbol is not IMethodSymbol method
                || ResolveInvocationTarget(method, caller, call) is not { } target
                || target.Symbol.RefKind != RefKind.None)
            {
                return false;
            }

            ExpressionSyntax? returned = target.Syntax switch
            {
                MethodDeclarationSyntax
                {
                    Body: null,
                    ExpressionBody.Expression: { } expression,
                } => expression,
                LocalFunctionStatementSyntax
                {
                    Body: null,
                    ExpressionBody.Expression: { } expression,
                } => expression,
                _ => null,
            };

            if (returned is null
                || !TryNormalizeBuiltInCleanupValue(
                    target.Model,
                    returned,
                    out ExpressionSyntax normalizedReturn,
                    requireIdentityPreservingCasts: true)
                || normalizedReturn is not IdentifierNameSyntax identifier
                || target.Model.GetSymbolInfo(identifier).Symbol is not
                    IParameterSymbol returnedParameter
                || !SymbolEqualityComparer.Default.Equals(
                    returnedParameter.ContainingSymbol,
                    target.Symbol)
                || returnedParameter.Ordinal < 0
                || returnedParameter.Ordinal >= target.Symbol.Parameters.Length
                || !SymbolEqualityComparer.Default.Equals(
                    returnedParameter,
                    target.Symbol.Parameters[returnedParameter.Ordinal])
                || !SymbolEqualityComparer.Default.Equals(
                    returnedParameter.Type,
                    target.Symbol.ReturnType)
                || caller.Model.GetOperation(call) is not
                    IInvocationOperation operation)
            {
                return false;
            }

            IArgumentOperation[] arguments = operation.Arguments
                .Where(argument => argument.Parameter?.Ordinal ==
                    returnedParameter.Ordinal)
                .ToArray();

            if (arguments is not [IArgumentOperation argument]
                || argument.Parameter?.RefKind != RefKind.None)
            {
                return false;
            }

            ExpressionSyntax? value = argument.Syntax switch
            {
                ArgumentSyntax syntax => syntax.Expression,
                ExpressionSyntax expression => expression,
                _ => argument.Value.Syntax as ExpressionSyntax,
            };

            if (value is null)
            {
                return false;
            }

            source = new(caller, value);

            return true;
        }

        private AuthoredMember ProjectEvaluationEnvironment(
            AuthoredMember member,
            ExpressionSyntax expression,
            TraversalRecoveryProjectionAnalysisCounter? analysis = null,
            Action? projectionBuilt = null)
        {
            if (completedPartialEvaluationProjections.TryGetValue(member, out var projections)
                && projections.TryGetValue(expression, out AuthoredMember? cached))
            {
                return cached;
            }

            HashSet<ISymbol> candidates = new(SymbolEqualityComparer.Default);

            candidates.UnionWith(member.AdmissionBindings?.Keys ?? []);

            candidates.UnionWith(member.CallableBindings?.Keys ?? []);

            candidates.UnionWith(
                member.AbsentCallables ?? Enumerable.Empty<ISymbol>());

            candidates.UnionWith(member.ConcreteBindings?.Keys ?? []);

            candidates.UnionWith(member.RecoveryBindings?.Keys ?? []);

            candidates.UnionWith(member.ValueBindings?.Keys ?? []);

            HashSet<ISymbol> required = new(SymbolEqualityComparer.Default);

            foreach (ISymbol candidate in candidates)
            {
                if (IsCertifiedOwnEnumSlot(member, candidate)
                    || ExpressionDependsOnSymbol(
                    member,
                    expression,
                    candidate,
                    new HashSet<ISymbol>(SymbolEqualityComparer.Default),
                    analysis,
                    dependencySymbols))
                {
                    required.Add(candidate);
                }
            }

            if (required.Count == candidates.Count)
            {
                return member;
            }

            projectionBuilt?.Invoke();

            AuthoredMember projected = member with
            {
                AdmissionBindings = ProjectEvaluationBindings(
                    member.AdmissionBindings,
                    required),
                CallableBindings = ProjectEvaluationBindings(
                    member.CallableBindings,
                    required),
                AbsentCallables = member.AbsentCallables is null
                    ? null
                    : new HashSet<ISymbol>(
                        member.AbsentCallables.Where(required.Contains),
                        SymbolEqualityComparer.Default),
                ConcreteBindings = ProjectEvaluationBindings(
                    member.ConcreteBindings,
                    required),
                RecoveryBindings = ProjectEvaluationBindings(
                    member.RecoveryBindings,
                    required),
                ValueBindings = ProjectEvaluationBindings(
                    member.ValueBindings,
                    required),
            };

            if (projections is null)
            {
                projections = new(ReferenceEqualityComparer.Instance);

                completedPartialEvaluationProjections.Add(member, projections);
            }

            projections.Add(expression, projected);

            return projected;
        }

        internal IReadOnlyList<HostedProducerProjectionSymbolProbe> ProbeProjectionSymbolLookups(
            CSharpCompilation compilation,
            IMethodSymbol method,
            ExpressionSyntax expression,
            int repetitions)
        {
            SyntaxNode syntax = method.DeclaringSyntaxReferences.Single().GetSyntax();

            AuthoredMember member = new(method, syntax, compilation.GetSemanticModel(syntax.SyntaxTree));

            Dictionary<ISymbol, IReadOnlySet<string>> admissions = new(SymbolEqualityComparer.Default);

            Dictionary<ISymbol, AuthoredMember> callables = new(SymbolEqualityComparer.Default);

            HashSet<ISymbol> absent = new(SymbolEqualityComparer.Default);

            Dictionary<ISymbol, ITypeSymbol> concrete = new(SymbolEqualityComparer.Default);

            Dictionary<ISymbol, RecoveryTuple> recovery = new(SymbolEqualityComparer.Default);

            Dictionary<ISymbol, BoundValueSource> values = new(SymbolEqualityComparer.Default);

            foreach (IParameterSymbol parameter in method.Parameters)
            {
                admissions.Add(parameter, new HashSet<string> { parameter.Name });

                callables.Add(parameter, member);

                absent.Add(parameter);

                concrete.Add(parameter, parameter.Type);

                recovery.Add(parameter, new(parameter.Name, 1, default));

                values.Add(parameter, new(member, expression));
            }

            member = member with { AdmissionBindings = admissions, CallableBindings = callables, AbsentCallables = absent, ConcreteBindings = concrete, RecoveryBindings = recovery, ValueBindings = values };

            List<HostedProducerProjectionSymbolProbe> results = [];

            for (int index = 0; index < repetitions; index++)
            {
                TraversalRecoveryProjectionAnalysisCounter analysis = new();

                int builds = dependencySymbols.Builds;

                AuthoredMember projected = ProjectEvaluationEnvironment(member, expression, analysis);

                static string Names(IEnumerable<ISymbol>? symbols) => string.Join(",", (symbols ?? []).Select(static symbol => symbol.Name).Order(StringComparer.Ordinal));

                results.Add(new([Names(projected.AdmissionBindings?.Keys), Names(projected.CallableBindings?.Keys), Names(projected.AbsentCallables), Names(projected.ConcreteBindings?.Keys), Names(projected.RecoveryBindings?.Keys), Names(projected.ValueBindings?.Keys)], analysis.DependencyNodes, analysis.UncachedSymbolQueries + dependencySymbols.Builds - builds));
            }

            return results;
        }

        internal HostedProducerCallableMutationProbe ProbeCallableMutations(
            INamedTypeSymbol owner,
            IReadOnlyList<string> fieldNames,
            int repetitions)
        {
            IFieldSymbol[] fields = fieldNames
                .Select(name => owner.GetMembers(name).OfType<IFieldSymbol>().Single())
                .ToArray();

            bool[] mutated = [];

            for (int repetition = 0; repetition < repetitions; repetition++)
            {
                mutated = fields
                    .Select(HasAuthoredCallableMutation)
                    .ToArray();
            }

            return new(mutated, authoredCallableMutationCorpusScans);
        }

        internal (int NormalizationBuilds, int FingerprintBuilds, int DistinctFingerprints, bool Complete) ProbeRepeatedExactSourceProjection(IMethodSymbol sourceMethod, ExpressionSyntax sourceExpression, int repetitions)
        {
            BoundValueSource source = completeEvaluationValueSourceNormalizations
                .Where(pair => SymbolEqualityComparer.Default.Equals(pair.Key.Symbol.OriginalDefinition, sourceMethod.OriginalDefinition))
                .SelectMany(pair => pair.Value.Keys
                    .Where(expression => ReferenceEquals(expression, sourceExpression))
                    .Select(expression => new BoundValueSource(pair.Key, expression)))
                .First();

            int normalizationBefore = evaluationEnvironmentAnalysis.Values.Sum(static value => value.ValueNormalizationBuilds);

            int fingerprintBefore = evaluationEnvironmentAnalysis.Values.Sum(static value => value.FingerprintBuilds);

            HashSet<string> fingerprints = [];

            bool complete = true;

            for (int index = 0; index < repetitions; index++)
            {
                AuthoredMember projected = ProjectEvaluationEnvironment(source.Caller, source.Expression);

                EvaluationEnvironmentFingerprint fingerprint = EvaluationEnvironmentIdentity(projected);

                fingerprints.Add(fingerprint.Identity);

                complete &= fingerprint.Complete && !fingerprint.ContainsBackreference;

                _ = NormalizeEvaluationValueSource(new(projected, source.Expression));
            }

            return (evaluationEnvironmentAnalysis.Values.Sum(static value => value.ValueNormalizationBuilds) - normalizationBefore,
                evaluationEnvironmentAnalysis.Values.Sum(static value => value.FingerprintBuilds) - fingerprintBefore,
                fingerprints.Count,
                complete);
        }

        internal HostedProducerPartialProjectionProbe ProbeRepeatedPartialSourceProjection(
            HostedProducerDiscovery<HostedProducerSite> discovery,
            IMethodSymbol sourceMethod,
            ExpressionSyntax sourceExpression,
            int repetitions)
        {
            if (repetitions is < 1 or > 64)
            {
                throw new ArgumentOutOfRangeException(nameof(repetitions));
            }

            static string Keys(AuthoredMember member) => string.Join(",", (member.AdmissionBindings?.Keys ?? [])
                .Concat(member.CallableBindings?.Keys ?? [])
                .Concat(member.AbsentCallables ?? Enumerable.Empty<ISymbol>())
                .Concat(member.ConcreteBindings?.Keys ?? [])
                .Concat(member.RecoveryBindings?.Keys ?? [])
                .Concat(member.ValueBindings?.Keys ?? [])
                .Select(static symbol => symbol.Name)
                .Distinct(StringComparer.Ordinal)
                .Order(StringComparer.Ordinal));

            // Select only a context produced by ordinary discovery. Never seed missing bindings.
            BoundValueSource source = completeEvaluationValueSourceNormalizations
                .Where(pair => SymbolEqualityComparer.Default.Equals(pair.Key.Symbol.OriginalDefinition, sourceMethod.OriginalDefinition)
                    && Keys(pair.Key) == "cleanup,unused")
                .SelectMany(pair => pair.Value.Keys
                    .Where(expression => ReferenceEquals(expression, sourceExpression))
                    .Select(expression => new BoundValueSource(pair.Key, expression)))
                .FirstOrDefault()
                ?? throw new InvalidOperationException("Partial projection witness missing: discovery did not retain both real cleanup inputs at the selected exact source.");

            int identityBefore = evaluationEnvironmentAnalysis.Values.Sum(static value => value.InternerIdentityBuilds);

            int projectionBuilds = 0;

            int exactTokenInputs = 0;

            int nullTokens = 0;

            bool contextsPreserved = true;

            List<string> retained = [];

            HashSet<int> tokens = [];

            for (int index = 0; index < repetitions; index++)
            {
                AuthoredMember projected = ProjectEvaluationEnvironment(source.Caller, source.Expression, projectionBuilt: () => projectionBuilds++);

                retained.Add(Keys(projected));

                contextsPreserved &= ReferenceEquals(source.Caller.ConstructorContexts, projected.ConstructorContexts)
                    && source.Caller.RecoveryContext == projected.RecoveryContext;

                if (evaluationEnvironmentTokens.ContainsKey(projected))
                {
                    exactTokenInputs++;
                }

                if (TryRegisterEvaluationEnvironmentToken(projected) is int token)
                {
                    tokens.Add(token);
                }
                else
                {
                    nullTokens++;
                }
            }

            return new(discovery, Keys(source.Caller), retained, projectionBuilds,
                evaluationEnvironmentAnalysis.Values.Sum(static value => value.InternerIdentityBuilds) - identityBefore,
                exactTokenInputs, nullTokens, tokens.Count, contextsPreserved);
        }

        private AuthoredMember ProjectTraversalEvaluationEnvironment(
            AuthoredMember member,
            out int? environmentToken,
            out bool environmentTokenObtained)
        {
            environmentToken = null;

            environmentTokenObtained = false;

            if (EvaluationEnvironmentIsEmpty(member))
            {
                return member;
            }

            environmentToken = TryRegisterEvaluationEnvironmentToken(member);

            environmentTokenObtained = true;

            EvaluationEnvironmentFingerprint environment =
                environmentToken is int exactToken
                    && tokenEvaluationEnvironmentFingerprints.TryGetValue(
                        exactToken,
                        out EvaluationEnvironmentFingerprint certified)
                    ? certified
                    : EvaluationEnvironmentIdentity(member, environmentToken);

            if (environmentToken is not int
                || !environment.Complete
                || environment.ContainsBackreference)
            {
                return member;
            }

            HashSet<ISymbol> candidates = new(SymbolEqualityComparer.Default);

            candidates.UnionWith(member.AdmissionBindings?.Keys ?? []);

            candidates.UnionWith(member.CallableBindings?.Keys ?? []);

            candidates.UnionWith(
                member.AbsentCallables ?? Enumerable.Empty<ISymbol>());

            candidates.UnionWith(member.ConcreteBindings?.Keys ?? []);

            candidates.UnionWith(member.RecoveryBindings?.Keys ?? []);

            candidates.UnionWith(member.ValueBindings?.Keys ?? []);

            if (candidates.Count == 0)
            {
                return member;
            }

            StringBuilder candidateIdentity = new();

            foreach (string candidate in candidates
                .Select(symbol => BindingSymbolIdentity(symbol, member))
                .Order(StringComparer.Ordinal))
            {
                AppendIdentitySegment(candidateIdentity, candidate);
            }

            TraversalEvaluationProjectionIdentity identity = new(
                MemberIdentity(member),
                candidateIdentity.ToString());

            if (!traversalEvaluationProjections.TryGetValue(
                    identity,
                    out IReadOnlySet<ISymbol>? required))
            {
                ExpressionSyntax[] expressions = member.Syntax
                    .DescendantNodesAndSelf()
                    .OfType<ExpressionSyntax>()
                    .ToArray();

                HashSet<ISymbol> retained = new(
                    candidates.Where(candidate =>
                        candidate is not IParameterSymbol parameter
                        || member.Symbol.MethodKind != MethodKind.Ordinary
                        || parameter.ContainingSymbol is not IMethodSymbol
                        {
                            MethodKind: MethodKind.Ordinary,
                        }),
                    SymbolEqualityComparer.Default);

                foreach (ISymbol candidate in candidates)
                {
                    if (retained.Contains(candidate))
                    {
                        continue;
                    }

                    if (expressions.Any(expression => ExpressionDependsOnSymbol(
                        member,
                        expression,
                        candidate,
                        new HashSet<ISymbol>(SymbolEqualityComparer.Default))))
                    {
                        retained.Add(candidate);
                    }
                }

                required = retained;

                traversalEvaluationProjections.Add(identity, required);
            }

            // Recovery membership can differ for the same candidate symbols. Keep
            // those handoff bindings per invocation, outside the syntax-only cache.
            if (member.RecoveryBindings is { Count: > 0 } recoveryBindings
                && recoveryBindings.Keys.Any(symbol => !required.Contains(symbol)))
            {
                required = new HashSet<ISymbol>(
                    required.Concat(recoveryBindings.Keys),
                    SymbolEqualityComparer.Default);
            }

            if (required.Count == candidates.Count)
            {
                return member;
            }

            environmentToken = null;

            environmentTokenObtained = false;

            return member with
            {
                AdmissionBindings = ProjectEvaluationBindings(
                    member.AdmissionBindings,
                    required),
                CallableBindings = ProjectEvaluationBindings(
                    member.CallableBindings,
                    required),
                AbsentCallables = member.AbsentCallables is null
                    ? null
                    : new HashSet<ISymbol>(
                        member.AbsentCallables.Where(required.Contains),
                        SymbolEqualityComparer.Default),
                ConcreteBindings = ProjectEvaluationBindings(
                    member.ConcreteBindings,
                    required),
                RecoveryBindings = ProjectEvaluationBindings(
                    member.RecoveryBindings,
                    required),
                ValueBindings = ProjectEvaluationBindings(
                    member.ValueBindings,
                    required),
            };
        }

        private static IReadOnlyDictionary<ISymbol, TValue>?
            ProjectEvaluationBindings<TValue>(
                IReadOnlyDictionary<ISymbol, TValue>? bindings,
                IReadOnlySet<ISymbol> required) =>
            bindings?.Where(pair => required.Contains(pair.Key))
                .ToDictionary(
                    static pair => pair.Key,
                    static pair => pair.Value,
                    SymbolEqualityComparer.Default);

        private AuthoredMember ProjectStaticCallbackCaptureEnvironment(
            AuthoredMember callback)
        {
            if (!callback.Symbol.IsStatic
                || callback.Symbol.MethodKind is not (
                    MethodKind.AnonymousFunction or MethodKind.LocalFunction)
                || EvaluationEnvironmentIsEmpty(callback))
            {
                return callback;
            }

            int? environmentToken =
                TryRegisterEvaluationEnvironmentToken(callback);

            EvaluationEnvironmentFingerprint environment =
                EvaluationEnvironmentIdentity(callback, environmentToken);

            if (environmentToken is not int
                || !environment.Complete
                || environment.ContainsBackreference)
            {
                return callback;
            }

            HashSet<ISymbol> candidates = new(SymbolEqualityComparer.Default);

            candidates.UnionWith(callback.AdmissionBindings?.Keys ?? []);

            candidates.UnionWith(callback.CallableBindings?.Keys ?? []);

            candidates.UnionWith(
                callback.AbsentCallables ?? Enumerable.Empty<ISymbol>());

            candidates.UnionWith(callback.ConcreteBindings?.Keys ?? []);

            candidates.UnionWith(callback.ValueBindings?.Keys ?? []);

            HashSet<ISymbol> retained = new(
                candidates.Where(candidate =>
                    candidate is not IParameterSymbol
                    {
                        ContainingSymbol: IMethodSymbol
                        {
                            MethodKind: MethodKind.Ordinary,
                        } owner,
                    }
                    || SymbolEqualityComparer.Default.Equals(
                        owner,
                        callback.Symbol)),
                SymbolEqualityComparer.Default);

            if (retained.Count == candidates.Count)
            {
                return callback;
            }

            return callback with
            {
                AdmissionBindings = ProjectEvaluationBindings(
                    callback.AdmissionBindings,
                    retained),
                CallableBindings = ProjectEvaluationBindings(
                    callback.CallableBindings,
                    retained),
                AbsentCallables = callback.AbsentCallables is null
                    ? null
                    : new HashSet<ISymbol>(
                        callback.AbsentCallables.Where(retained.Contains),
                        SymbolEqualityComparer.Default),
                ConcreteBindings = ProjectEvaluationBindings(
                    callback.ConcreteBindings,
                    retained),
                ValueBindings = ProjectEvaluationBindings(
                    callback.ValueBindings,
                    retained),
            };
        }

        private AuthoredMember ProjectTraversalRecoveryEnvironment(
            AuthoredMember member)
        {
            if (member.RecoveryContext is null
                && member.RecoveryBindings is not { Count: > 0 })
            {
                return member;
            }

            TraversalRecoveryProjectionAnalysisCounter analysis =
                TraversalRecoveryProjectionCounter(member);

            analysis.Requests++;

            int? environmentToken = TryRegisterEvaluationEnvironmentToken(member);

            TraversalRecoveryProjectionIdentity? identity =
                environmentToken is int token
                    ? new(MemberIdentity(member), token)
                    : null;

            if (identity is { } exact
                && traversalRecoveryProjections.TryGetValue(
                    exact,
                    out TraversalRecoveryProjectionDecision? cached))
            {
                analysis.CacheHits++;

                return ApplyTraversalRecoveryProjection(member, cached);
            }

            analysis.Builds++;

            TraversalRecoveryProjectionDecision decision =
                BuildTraversalRecoveryProjection(member, analysis);

            if (identity is { } cacheable)
            {
                traversalRecoveryProjections.TryAdd(cacheable, decision);
            }

            return ApplyTraversalRecoveryProjection(member, decision);
        }

        private TraversalRecoveryProjectionDecision BuildTraversalRecoveryProjection(
            AuthoredMember member,
            TraversalRecoveryProjectionAnalysisCounter analysis)
        {
            Dictionary<ISymbol, RecoveryTuple> liveBindings =
                new(SymbolEqualityComparer.Default);

            List<KeyValuePair<ISymbol, RecoveryTuple>> unresolvedBindings =
                member.RecoveryBindings
                    ?.ToList()
                ?? [];

            foreach ((ISymbol symbol, RecoveryTuple tuple) in unresolvedBindings)
            {
                bool currentHandoffParameter = symbol is IParameterSymbol parameter
                    && parameter.ContainingSymbol is IMethodSymbol owner
                    && SymbolEqualityComparer.Default.Equals(
                        owner.OriginalDefinition,
                        member.Symbol.OriginalDefinition);

                if (currentHandoffParameter)
                {
                    liveBindings.Add(symbol, tuple);
                }
            }

            if (unresolvedBindings.Count != 0)
            {
                analysis.WholeMemberScans++;

                foreach (ExpressionSyntax expression in member.Syntax
                    .DescendantNodesAndSelf(node => node == member.Syntax
                        || node is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .OfType<ExpressionSyntax>())
                {
                    analysis.ExpressionsInspected++;

                    for (int index = unresolvedBindings.Count - 1;
                        index >= 0;
                        index--)
                    {
                        (ISymbol symbol, RecoveryTuple tuple) =
                            unresolvedBindings[index];

                        if (!ExpressionDependsOnSymbol(
                            member,
                            expression,
                            symbol,
                            new HashSet<ISymbol>(SymbolEqualityComparer.Default),
                            analysis))
                        {
                            continue;
                        }

                        liveBindings.TryAdd(symbol, tuple);

                        unresolvedBindings.RemoveAt(index);
                    }

                    if (unresolvedBindings.Count == 0)
                    {
                        break;
                    }
                }
            }

            bool retainContext = liveBindings.Count != 0
                || member.RecoveryContext is
                {
                    Disposition: RecoveryDisposition.OrdinaryDbOnly
                        or RecoveryDisposition.OrdinaryPerUnitExternalEffect,
                };

            return new(
                liveBindings.Keys.ToHashSet(SymbolEqualityComparer.Default),
                retainContext);
        }

        private static AuthoredMember ApplyTraversalRecoveryProjection(
            AuthoredMember member,
            TraversalRecoveryProjectionDecision decision)
        {
            Dictionary<ISymbol, RecoveryTuple> liveBindings = member.RecoveryBindings?
                .Where(pair => decision.RetainedBindings.Contains(pair.Key))
                .ToDictionary(
                    static pair => pair.Key,
                    static pair => pair.Value,
                    SymbolEqualityComparer.Default)
                ?? new(SymbolEqualityComparer.Default);

            if (liveBindings.Count == (member.RecoveryBindings?.Count ?? 0)
                && (decision.RetainContext || member.RecoveryContext is null))
            {
                return member;
            }

            return member with
            {
                RecoveryBindings = liveBindings.Count == 0
                    ? null
                    : liveBindings,
                RecoveryContext = decision.RetainContext
                    ? member.RecoveryContext
                    : null,
            };
        }

        private TraversalRecoveryProjectionAnalysisCounter
            TraversalRecoveryProjectionCounter(AuthoredMember member)
        {
            string metricMember = MethodKey(member.Symbol);

            if (!traversalRecoveryProjectionAnalysis.TryGetValue(
                    metricMember,
                    out TraversalRecoveryProjectionAnalysisCounter? analysis))
            {
                analysis = new();

                traversalRecoveryProjectionAnalysis.Add(metricMember, analysis);
            }

            return analysis;
        }

        private static bool TryResolveStableBoundValueSource(
            AuthoredMember member,
            ExpressionSyntax expression,
            out BoundValueSource? source)
        {
            source = null;

            return member.Model.GetSymbolInfo(expression).Symbol is { } symbol
                && CanUseCurrentInstanceStorageBinding(symbol, expression)
                && member.ValueBindings?.TryGetValue(symbol, out source) == true
                && source is not null
                && (symbol is not IParameterSymbol { Type.SpecialType: SpecialType.System_Boolean }
                    || IsStableAcrossAdmissionCleanupBackEdges(member, expression, symbol))
                && RecoveryTupleSourceIsStable(
                    member,
                    symbol,
                    expression,
                    allowSimpleLocalAssignments: false);
        }

        private string BindingSymbolIdentity(
            ISymbol symbol,
            AuthoredMember member)
        {
            if (!bindingSymbolIdentities.TryGetValue(member.Model.Compilation, out Dictionary<ISymbol, string>? identities))
            {
                bindingSymbolIdentities.Add(member.Model.Compilation, identities = new(ReferenceEqualityComparer.Instance));
            }

            if (!identities.TryGetValue(symbol, out string? identity))
            {
                bindingSymbolIdentityBuilds++;

                identity = BuildBindingSymbolIdentity(symbol, member);

                identities[symbol] = identity;
            }

            return identity;
        }

        private string BuildBindingSymbolIdentity(
            ISymbol symbol,
            AuthoredMember member)
        {
            string owner = symbol.ContainingSymbol switch
            {
                IMethodSymbol method => MethodKey(method),
                INamedTypeSymbol type => TypeKey(type),
                { } containing => containing.ToDisplayString(
                    SymbolDisplayFormat.FullyQualifiedFormat),
                _ => "global",
            };

            SyntaxReference? declaration = symbol.DeclaringSyntaxReferences
                .OrderBy(reference => TreeIdentity(reference.SyntaxTree))
                .ThenBy(static reference => reference.Span.Start)
                .FirstOrDefault();

            int ordinal = symbol is IParameterSymbol parameter
                ? parameter.Ordinal
                : -1;

            return string.Join(
                ':',
                symbol.ContainingAssembly?.Identity.ToString() ?? "no-assembly",
                declaration is null
                    ? "external"
                    : CompilationIdentity(member.Model.Compilation)
                        .ToString(CultureInfo.InvariantCulture),
                declaration is null
                    ? "external"
                    : TreeIdentity(declaration.SyntaxTree)
                        .ToString(CultureInfo.InvariantCulture),
                declaration?.Span.Start.ToString(CultureInfo.InvariantCulture)
                    ?? "external",
                declaration?.Span.Length.ToString(CultureInfo.InvariantCulture)
                    ?? "external",
                symbol.Kind,
                owner,
                ordinal.ToString(CultureInfo.InvariantCulture),
                symbol.MetadataName);
        }

        private static void AppendIdentitySection(
            StringBuilder value,
            string section,
            int count)
        {
            AppendIdentitySegment(value, section);

            AppendIdentitySegment(
                value,
                count.ToString(CultureInfo.InvariantCulture));
        }

        internal IReadOnlyList<(string Identity, int Builds, int Compilations, int Trees)> ProbeBindingSymbolIdentities(
            IReadOnlyList<(SemanticModel Model, IMethodSymbol Method, ISymbol Symbol)> queries)
        {
            List<(string Identity, int Builds, int Compilations, int Trees)> results = [];

            foreach (var query in queries)
            {
                AuthoredMember member = new(query.Method, query.Method.DeclaringSyntaxReferences.Single().GetSyntax(), query.Model);

                int before = bindingSymbolIdentityBuilds;

                string identity = BindingSymbolIdentity(query.Symbol, member);

                results.Add((identity, bindingSymbolIdentityBuilds - before, compilationIdentities.Count, treeIdentities.Count));
            }

            return results;
        }

        private static void AppendIdentitySegment(
            StringBuilder value,
            string segment) =>
            value.Append(segment.Length.ToString(CultureInfo.InvariantCulture))
                .Append(':')
                .Append(segment)
                .Append(';');

        private static void AppendRecoveryTuple(
            StringBuilder value,
            RecoveryTuple tuple)
        {
            AppendIdentitySegment(value, tuple.Kind);

            AppendIdentitySegment(
                value,
                tuple.CheckpointVersion.ToString(CultureInfo.InvariantCulture));

            AppendIdentitySegment(value, tuple.Disposition.ToString());
        }

        private static string CompactIdentity(string value) =>
            Convert.ToHexString(
                System.Security.Cryptography.SHA256.HashData(
                    System.Text.Encoding.UTF8.GetBytes(value)));

        private string ConcreteBindingIdentity(AuthoredMember member)
        {
            if (member.ConcreteBindings is null || member.ConcreteBindings.Count == 0)
            {
                return "unbound";
            }

            return string.Join(";", member.ConcreteBindings.OrderBy(static pair => pair.Key is IParameterSymbol parameter ? parameter.Ordinal : int.MaxValue).ThenBy(static pair => pair.Key.ToDisplayString(), StringComparer.Ordinal).Select(pair =>
            {
                BoundTypeIdentity type = TypeIdentity(pair.Value, member.Model.Compilation);

                return (pair.Key is IParameterSymbol parameter ? parameter.Ordinal : -1) + ":" + type.Assembly.Name + ":" + type.Compilation + ":" + type.Type;
            }));
        }

        private string RootOperation(string operationId)
        {
            string? declared = declaredOperations.Select(static operation => operation.OperationId).Where(root => operationId == root || operationId.StartsWith(root + "/", StringComparison.Ordinal)).OrderByDescending(static root => root.Length).FirstOrDefault();

            if (declared is not null)
            {
                return declared;
            }

            int separator = new[] { "/call@", "/callback@", "/get@", "/set@", "/dispose@", "/work@", "/effect@", "/site@" }.Select(marker => operationId.IndexOf(marker, StringComparison.Ordinal)).Where(static index => index >= 0).DefaultIfEmpty(operationId.Length).Min();

            return operationId[..separator];
        }

        private void ReadBinding(InvocationExpressionSyntax invocation, SemanticModel model)
        {
            if (model.GetSymbolInfo(invocation).Symbol is not IMethodSymbol bound)
            {
                return;
            }

            if (TryGetExactScopedEnumerableDescriptor(invocation, bound, model,
                out InvocationExpressionSyntax descriptor, out IMethodSymbol descriptorMethod))
            {
                IndexResolvedRegistration(diActivationRegistrations, descriptor, model,
                    descriptorMethod, includeFactoryConstruction: true);

                ReadServiceBinding(descriptor, model, descriptorMethod);

                return;
            }

            if (bound.Name is
                    "AddHostedService" or "AddSingleton" or "TryAddSingleton"
                        or "AddScoped" or "TryAddScoped"
                        or "AddTransient" or "TryAddTransient"
                || IsExactResetAwareHostedServiceRegistration(bound))
            {
                IndexResolvedRegistration(
                    diActivationRegistrations,
                    invocation,
                    model,
                    bound,
                    includeFactoryConstruction: true);
            }

            if (bound.Name is "AddDbContext" or "AddDbContextPool")
            {
                IndexResolvedRegistration(
                    sqliteDbContextRegistrationCalls,
                    invocation,
                    model,
                    bound,
                    includeFactoryConstruction: false);
            }

            if (bound.Name is not
                    ("AddSingleton" or "TryAddSingleton"
                        or "AddScoped" or "TryAddScoped"
                        or "AddTransient" or "TryAddTransient")
                || !IsExactServiceCollectionFluentMethod(bound))
            {
                return;
            }

            ReadServiceBinding(invocation, model, bound);
        }

        private void ReadServiceBinding(InvocationExpressionSyntax invocation, SemanticModel model,
            IMethodSymbol bound)
        {
            ITypeSymbol? contract = bound.TypeArguments.FirstOrDefault();

            if (contract is null)
            {
                return;
            }

            IEnumerable<ITypeSymbol?> implementations = bound.TypeArguments.Length == 2 ? [bound.TypeArguments[1]] : invocation.ArgumentList.Arguments.Count == 0 ? [contract] : ReturnedTypes(invocation.ArgumentList.Arguments.Last().Expression, model, new HashSet<ISymbol>(SymbolEqualityComparer.Default));

            foreach (ITypeSymbol? implementation in implementations.DefaultIfEmpty(null))
            {
                bool assignable = implementation is INamedTypeSymbol { TypeKind: TypeKind.Class, IsAbstract: false } concrete && (SymbolEqualityComparer.Default.Equals(concrete, contract) || concrete.AllInterfaces.Any(slot => SymbolEqualityComparer.Default.Equals(slot, contract)) || IsBase(concrete, contract));

                if (assignable)
                {
                    BoundTypeIdentity contractIdentity = TypeIdentity(contract, model.Compilation);

                    BoundTypeIdentity implementationIdentity = TypeIdentity(implementation!, model.Compilation);

                    bindings.Add(new(contractIdentity, implementationIdentity));

                    boundImplementationTypes[implementationIdentity] = (INamedTypeSymbol)implementation!;

                    boundContracts.Add(new(contractIdentity.Assembly, contractIdentity.Type));
                }
                else if (contract.TypeKind == TypeKind.Interface)
                {
                    incompleteInterfaceBindings.Add(TypeIdentity(contract, model.Compilation));
                }
            }
        }

        private static void IndexResolvedRegistration(
            Dictionary<BoundContractIdentity, List<ResolvedRegistration>> index,
            InvocationExpressionSyntax call,
            SemanticModel model,
            IMethodSymbol method,
            bool includeFactoryConstruction)
        {
            HashSet<BoundContractIdentity> keys = method.TypeArguments
                .Select(static type => new BoundContractIdentity(
                    type.ContainingAssembly.Identity,
                    TypeKey(type)))
                .ToHashSet();

            INamedTypeSymbol[] factoryTypes = includeFactoryConstruction
                ? call.ArgumentList.Arguments
                    .Select(static argument => argument.Expression)
                    .OfType<AnonymousFunctionExpressionSyntax>()
                    .Select(ExactFactoryCreation)
                    .OfType<BaseObjectCreationExpressionSyntax>()
                    .Select(creation => model.GetSymbolInfo(creation).Symbol)
                    .OfType<IMethodSymbol>()
                    .Select(static constructor => constructor.ContainingType)
                    .DistinctBy(
                        static type => type.OriginalDefinition,
                        SymbolEqualityComparer.Default)
                    .Take(2)
                    .ToArray()
                : [];

            if (factoryTypes is [INamedTypeSymbol createdType])
            {
                keys.Add(new(
                    createdType.ContainingAssembly.Identity,
                    TypeKey(createdType)));
            }

            ResolvedRegistration registration = new(call, model, method);

            foreach (BoundContractIdentity key in keys)
            {
                if (!index.TryGetValue(key, out List<ResolvedRegistration>? registrations))
                {
                    index.Add(key, registrations = []);
                }

                registrations.Add(registration);
            }
        }

        private BoundTypeIdentity TypeIdentity(ITypeSymbol type, Compilation consumingCompilation) => new(type.ContainingAssembly.Identity, AuthoredCompilationIdentity(type, consumingCompilation), TypeKey(type));

        private int? AuthoredCompilationIdentity(ISymbol symbol, Compilation consumingCompilation)
        {
            if (!authoredCompilationIdentities.TryGetValue(consumingCompilation, out Dictionary<IAssemblySymbol, int>? identities))
            {
                authoredCompilationIdentities.Add(consumingCompilation, identities = new(ReferenceEqualityComparer.Instance));
            }

            IAssemblySymbol assembly = symbol.ContainingAssembly;

            if (identities.TryGetValue(assembly, out int cached))
            {
                return cached;
            }

            if (ReferenceEquals(consumingCompilation.Assembly, assembly))
            {
                int exact = CompilationIdentity(consumingCompilation);

                identities.Add(assembly, exact);

                return exact;
            }

            CompilationReference[] exactReferences = consumingCompilation
                .References
                .OfType<CompilationReference>()
                .Where(reference => ReferenceEquals(
                    consumingCompilation.GetAssemblyOrModuleSymbol(reference),
                    assembly))
                .ToArray();

            if (exactReferences is [CompilationReference exactReference]
                && compilationIdentities.ContainsKey(exactReference.Compilation))
            {
                int exact = CompilationIdentity(exactReference.Compilation);

                identities.Add(assembly, exact);

                return exact;
            }

            HashSet<SyntaxTree> declaringTrees = symbol.DeclaringSyntaxReferences.Select(static reference => reference.SyntaxTree).ToHashSet<SyntaxTree>(ReferenceEqualityComparer.Instance);

            CSharpCompilation[] declaringCompilations = compilationIdentities.Keys
                .OfType<CSharpCompilation>()
                .Where(compilation =>
                    compilation.Assembly.Identity.Equals(assembly.Identity)
                    && declaringTrees.Any(tree => compilation.SyntaxTrees.Contains(
                        tree,
                        ReferenceEqualityComparer.Instance)))
                .ToArray();

            if (declaringCompilations.Length == 1)
            {
                int exact = CompilationIdentity(declaringCompilations[0]);

                identities.Add(assembly, exact);

                return exact;
            }

            return null;
        }

        private static bool IsBase(INamedTypeSymbol implementation, ITypeSymbol contract) => implementation.BaseType is { } parent && (SymbolEqualityComparer.Default.Equals(parent, contract) || IsBase(parent, contract));

        private IEnumerable<ITypeSymbol?> ReturnedTypes(SyntaxNode expression, SemanticModel model, HashSet<ISymbol> path)
        {
            switch (expression)
            {
                case ParenthesizedExpressionSyntax parentheses:
                    return ReturnedTypes(parentheses.Expression, model, path);
                case CastExpressionSyntax cast:
                    return ReturnedTypes(cast.Expression, model, path);
                case AnonymousFunctionExpressionSyntax lambda:
                    return ReturnedTypes(lambda.Body, model, path);
                case ArrowExpressionClauseSyntax arrow:
                    return ReturnedTypes(arrow.Expression, model, path);
                case BlockSyntax block:
                    return block.DescendantNodes(node => node is not AnonymousFunctionExpressionSyntax and not LocalFunctionStatementSyntax).OfType<ReturnStatementSyntax>().SelectMany(statement => statement.Expression is { } result ? ReturnedTypes(result, model, path) : [null]).DefaultIfEmpty(null).ToArray();
                case ConditionalExpressionSyntax conditional:
                    return ReturnedTypes(conditional.WhenTrue, model, path).Concat(ReturnedTypes(conditional.WhenFalse, model, path)).ToArray();
                case SwitchExpressionSyntax selection:
                    return selection.Arms.SelectMany(arm => ReturnedTypes(arm.Expression, model, path)).ToArray();
                case ObjectCreationExpressionSyntax or ImplicitObjectCreationExpressionSyntax:
                    return [model.GetTypeInfo(expression).Type];
            }

            ISymbol? symbol = model.GetSymbolInfo(expression).Symbol;

            if (symbol is IMethodSymbol method && expression is InvocationExpressionSyntax && method.Name == "GetRequiredService" && (method.ReducedFrom ?? method).ContainingNamespace.ToDisplayString() == "Microsoft.Extensions.DependencyInjection")
            {
                return [method.ReturnType];
            }

            if (symbol is null || !path.Add(symbol))
            {
                return [null];
            }

            IEnumerable<ITypeSymbol?> resultTypes = [null];

            if (symbol is IMethodSymbol factory && Resolve(factory, model.Compilation) is { } authored)
            {
                SyntaxNode? body = authored.Syntax switch { MethodDeclarationSyntax declaration => (SyntaxNode?)declaration.ExpressionBody ?? declaration.Body, LocalFunctionStatementSyntax local => (SyntaxNode?)local.ExpressionBody ?? local.Body, _ => null };

                resultTypes = body is null ? [null] : ReturnedTypes(body, authored.Model, path).ToArray();
            }
            else if (symbol is ILocalSymbol local && local.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax() is VariableDeclaratorSyntax variable)
            {
                List<SyntaxNode> values = variable.Initializer is { } initializer ? [initializer.Value] : [];

                values.AddRange(variable.Ancestors().OfType<BlockSyntax>().First().DescendantNodes().OfType<AssignmentExpressionSyntax>().Where(assignment => assignment.SpanStart < expression.SpanStart && SymbolEqualityComparer.Default.Equals(model.GetSymbolInfo(assignment.Left).Symbol, local)).Select(static assignment => assignment.Right));

                resultTypes = values.SelectMany(value => ReturnedTypes(value, model, path)).DefaultIfEmpty(null).ToArray();
            }
            else if (symbol is IMethodSymbol { ReturnType: INamedTypeSymbol { TypeKind: TypeKind.Class, IsAbstract: false } returned })
            {
                resultTypes = [returned];
            }
            else if (model.GetTypeInfo(expression).Type is INamedTypeSymbol { TypeKind: TypeKind.Class, IsAbstract: false } concrete)
            {
                resultTypes = [concrete];
            }

            path.Remove(symbol);

            return resultTypes;
        }

        internal HostedProducerDiscovery<HostedProducerSite> Discover(
            HostedProducerDiscovery<string> registrations,
            IReadOnlyList<HostedProducerServiceEntry> catalog,
            IReadOnlyList<NonHostedProducerChainEntry> nonHostedCatalog,
            HostedProducerRecoverySelectionProbe? recoverySelectionProbe)
        {
            PlannedRoot[] roots = PrepareRoots(registrations, catalog, nonHostedCatalog);

            foreach (PlannedRoot root in roots)
            {
                TraversePlannedRoot(root);
            }

            progressOccurrence = roots.Length + 1;

            CompletePrimaryRoots(recoverySelectionProbe);

            DiscoverExternalRoots(registrations, () => sites.Count,
                (member, rootType, operation) =>
                {
                    progressOccurrence++;

                    _ = TraverseRoot(member, rootType, operation, false);
                });

            return CompleteDiscovery();
        }

        internal HostedProducerDiscovery<HostedProducerSite> ProbeWholeRootInvocationContexts(
            HostedProducerOperationEntry root, string firstCaller, string secondCaller, bool declaredFirst)
        {
            PlannedRoot[] plans = PrepareRoots(new([root.EnclosingType], []), [new(root.EnclosingType, [root])], [])
                .Where(plan => plan.Operation == root.OperationId).ToArray();

            if (plans is not [{ Lifecycle: true }, { Lifecycle: false }]) throw new InvalidOperationException("Expected one automatic and one declared whole root.");

            AuthoredMember Bind(string callerName, AuthoredMember target)
            {
                AuthoredMember caller = AuthoredMembers.Single(member => member.Symbol.Name == callerName);

                InvocationExpressionSyntax call = caller.Syntax.DescendantNodes().OfType<InvocationExpressionSyntax>().Single();

                if (caller.Model.GetSymbolInfo(call).Symbol is not IMethodSymbol method
                    || ResolveInvocationTarget(method, caller, call) is not { } resolved
                    || MemberIdentity(resolved) != MemberIdentity(target)) throw new InvalidOperationException("Expected an exact call to this root.");

                return BindInvocationContext(caller, call, target);
            }

            plans[0] = plans[0] with { Member = Bind(firstCaller, plans[0].Member) };

            plans[1] = plans[1] with { Member = Bind(secondCaller, plans[1].Member) };

            foreach (PlannedRoot plan in declaredFirst ? plans.Reverse() : plans) TraversePlannedRoot(plan);

            CompletePrimaryRoots(null);

            return CompleteDiscovery();
        }

        internal HostedProducerDiscovery<HostedProducerSite> ProbeNestedRootBoundary(HostedProducerOperationEntry root, string boundary, Exception sentinel)
        {
            if (boundary is not ("probe-before" or "probe-between" or "cached-probe-between" or "direct-probe-between" or "source-exception" or "unplanned-first" or "unplanned-second")) throw new ArgumentOutOfRangeException(nameof(boundary));

            PlannedRoot[] plans = PrepareRoots(new([root.EnclosingType], []), [new(root.EnclosingType, [root])], [])
                .Where(plan => plan.Operation == root.OperationId).ToArray();

            if (plans is not [{ Lifecycle: true }, { Lifecycle: false }]) throw new InvalidOperationException("Expected exact automatic and declared roots.");

            void Probe(bool structural, int repetitions)
            {
                var result = ProbeRepeatedBoundedDataRollback(repetitions, structural);

                if (result.Proofs.Length != repetitions || result.Proofs.Any(static proof => proof != "PureBoundedData")) throw new InvalidOperationException("Expected the actual compiled pure bounded factory.");
            }

            if (boundary == "probe-before") Probe(true, 1);

            try
            {
                if (boundary == "unplanned-first")
                {
                    progressOccurrence = plans[0].Occurrence + 1;

                    _ = TraverseRoot(plans[0].Member, plans[0].RootType, plans[0].Operation, true);
                }
                else TraversePlannedRoot(plans[0]);
            }
            catch (Exception exception) when (ReferenceEquals(exception, sentinel)) { }

            if (boundary is "probe-between" or "cached-probe-between" or "direct-probe-between") Probe(boundary != "direct-probe-between", boundary == "cached-probe-between" ? 2 : 1);

            if (boundary == "unplanned-second")
            {
                progressOccurrence = plans[1].Occurrence + 1;

                _ = TraverseRoot(plans[1].Member, plans[1].RootType, plans[1].Operation, false, plans[1].Selection);
            }
            else TraversePlannedRoot(plans[1]);

            CompletePrimaryRoots(null);

            return CompleteDiscovery();
        }

        private sealed record PlannedRoot(
            int Occurrence,
            string Family,
            string RootType,
            string Operation,
            AuthoredMember Member,
            bool Lifecycle,
            SyntaxNode? Selection);

        private SyntaxNode? preparedOwnerRecoveryAnchor;

        private int progressWorker = 1;

        private int progressOccurrence;

        private readonly Dictionary<string, int> siteOccurrences = new(StringComparer.Ordinal);

        internal static HostedProducerDiscovery<HostedProducerSite> DiscoverParallel(
            Func<ProducerGraph> createGraph,
            HostedProducerDiscovery<string> registrations,
            IReadOnlyList<HostedProducerServiceEntry> catalog,
            IReadOnlyList<NonHostedProducerChainEntry> nonHostedCatalog,
            HostedProducerRecoverySelectionProbe? recoverySelectionProbe,
            int rootWorkers,
            bool reverseRootFamilies)
        {
            ProducerGraph coordinator = createGraph();

            if (coordinator.HasRecoveryMatrixInputs(catalog, nonHostedCatalog))
            {
                // Compute immutable facts only. First-use diagnostics and probe rollback stay lazy.
                coordinator.recoveryMatrixFacts = coordinator.BuildRecoveryMatrix();

                if (!coordinator.recoveryMatrixFacts.IsValid)
                {
                    return coordinator.Discover(registrations, catalog, nonHostedCatalog, recoverySelectionProbe);
                }
            }

            ProducerGraph[] workers = Enumerable.Range(0, rootWorkers)
                .Select(worker => worker == 0 ? coordinator : createGraph()).ToArray();

            foreach (ProducerGraph worker in workers)
            {
                worker.recoveryMatrixFacts = coordinator.recoveryMatrixFacts;
            }

            PlannedRoot[][] plans = workers.Select(graph => graph.PrepareRoots(registrations, catalog, nonHostedCatalog)).ToArray();

            for (int worker = 0; worker < workers.Length; worker++)
            {
                workers[worker].progressWorker = worker + 1;

                var identities = plans[worker].Select(root => (root.Occurrence, root.Family, root.RootType, root.Operation,
                    Member: workers[worker].MemberIdentity(root.Member), root.Lifecycle, Selection: root.Selection?.Span));

                var expected = plans[0].Select(root => (root.Occurrence, root.Family, root.RootType, root.Operation,
                    Member: coordinator.MemberIdentity(root.Member), root.Lifecycle, Selection: root.Selection?.Span));

                if (!identities.SequenceEqual(expected))
                {
                    throw new InvalidOperationException("Isolated workers did not prepare the same complete root plan.");
                }
            }

            int[][] families = HostedProducerRootWorkers.OrderFamilies(plans[0].Select(static root => (root.Family, root.Occurrence)));

            if (reverseRootFamilies)
            {
                Array.Reverse(families);
            }

            int[] owners = HostedProducerRootWorkers.Run(plans[0].Length, families, workers.Length, (worker, family) =>
            {
                List<int> completed = [];

                foreach (int occurrence in family)
                {
                    workers[worker].TraversePlannedRoot(plans[worker][occurrence]);

                    completed.Add(occurrence);
                }

                return completed.ToArray();
            });

            Dictionary<string, int> familyOwners = plans[0].GroupBy(static root => root.Family, StringComparer.Ordinal)
                .ToDictionary(static family => family.Key, family => owners[family.First().Occurrence], StringComparer.Ordinal);

            HashSet<string> handoffServices = [.. coordinator.leaseHandoffRootTypes.Values];

            foreach (string service in handoffServices)
            {
                if (plans[0].Where(root => root.RootType == service).Select(root => owners[root.Occurrence]).Distinct().Count() > 1)
                {
                    throw new InvalidOperationException("The roots of a service that declares a lease-handoff root were split across workers.");
                }
            }

            ProducerGraph Owner(string rootType, string operation)
            {
                string family = HostedProducerRootWorkers.FamilyOf(rootType, coordinator.RootOperation(operation), handoffServices.Contains(rootType));

                if (!familyOwners.TryGetValue(family, out int worker))
                {
                    worker = familyOwners.Count % workers.Length;

                    familyOwners.Add(family, worker);
                }

                return workers[worker];
            }

            int nextOccurrence = plans[0].Length;

            if (recoverySelectionProbe is not null)
            {
                coordinator.TraverseRecoverySelectionProbe(recoverySelectionProbe, (rootType, operation) =>
                {
                    ProducerGraph owner = Owner(rootType, operation);

                    owner.progressOccurrence = ++nextOccurrence;

                    return owner;
                });
            }

            foreach (ProducerGraph worker in workers)
            {
                coordinator.lifecycleMembers.UnionWith(worker.lifecycleMembers);

                coordinator.ownerRecoveryAssociations.UnionWith(worker.ownerRecoveryAssociations);

                coordinator.provenLeaseHandoffCalls.UnionWith(worker.provenLeaseHandoffCalls);
            }

            ProducerGraph? matrixOwner = workers.FirstOrDefault(static worker => worker.recoveryMatrixResolved);

            if (matrixOwner is not null)
            {
                coordinator.recoveryMatrix = matrixOwner.recoveryMatrix;

                coordinator.recoveryMatrixResolved = true;
            }

            coordinator.progressOccurrence = ++nextOccurrence;

            coordinator.CompletePrimaryRoots(null);

            HashSet<string> globalSites = workers.SelectMany(static worker => worker.sites.Keys).ToHashSet(StringComparer.Ordinal);

            coordinator.DiscoverExternalRoots(registrations, () => globalSites.Count, (member, rootType, operation) =>
            {
                ProducerGraph owner = Owner(rootType, operation);

                owner.progressOccurrence = ++nextOccurrence;

                AuthoredMember bound = owner.Resolve(member.Symbol, member.Model.Compilation)
                    ?? throw new InvalidOperationException("An external root was missing from its isolated graph.");

                _ = owner.TraverseRoot(bound, rootType, operation, false);

                globalSites.UnionWith(owner.sites.Keys);
            });

            HostedProducerDiscovery<HostedProducerSite>[] results = workers.Select(static worker => worker.CompleteDiscovery()).ToArray();

            using HostedProducerPhaseProgress merge = HostedProducerPhaseProgress.Start("merge", 0, workers.Length);

            HostedProducerSite[] mergedSites = workers.SelectMany(worker => worker.sites.Select(pair =>
                    (Key: pair.Key, Site: pair.Value, Occurrence: worker.siteOccurrences[pair.Key])))
                .GroupBy(static item => item.Key, StringComparer.Ordinal)
                .Select(static group => group.OrderBy(static item => item.Occurrence).First().Site)
                .OrderBy(SiteIdentity, StringComparer.Ordinal).ToArray();

            HostedProducerInventoryDiagnostic[] mergedDiagnostics = results.SelectMany(static result => result.Diagnostics)
                .Distinct().OrderBy(static diagnostic => diagnostic.Code, StringComparer.Ordinal)
                .ThenBy(static diagnostic => diagnostic.Identity, StringComparer.Ordinal)
                .ThenBy(static diagnostic => diagnostic.Detail, StringComparer.Ordinal).ToArray();

            HostedProducerDiscovery<HostedProducerSite> result = new(mergedSites, mergedDiagnostics, HostedProducerRootWorkers.MergeMetrics(results.Select(static result => result.AnalysisMetrics!).ToArray()) with { RootWorkers = workers.Length });

            merge.Complete();

            return result;
        }

        private bool HasRecoveryMatrixInputs(
            IReadOnlyList<HostedProducerServiceEntry> catalog,
            IReadOnlyList<NonHostedProducerChainEntry> nonHostedCatalog)
        {
            if (catalog.SelectMany(static service => service.Operations).Any(static root => root.Authority == HostedProducerAuthorityKind.OwnerBoundRecovery)
                || nonHostedCatalog.Any(static root => root.Authority == HostedProducerAuthorityKind.OwnerBoundRecovery))
            {
                return true;
            }

            if (objectCreations.Any(candidate => candidate.Model.GetTypeInfo(candidate.Creation).Type is { } type
                && TypeKey(type) == "RetroDownfall.Arcanum.Core.Operations.LongRunningOperation"))
            {
                return true;
            }

            // Source-bound triggers mirror the two dispatch call sites. Merely referencing a
            // production assembly does not make an ordinary synthetic fixture a recovery input.
            return invocations.Any(candidate => candidate.Model.GetSymbolInfo(candidate.Call).Symbol is IMethodSymbol method
                && (method.Name == "RecoverAsync"
                        && IsExactAuthoredProtocolType(method.ContainingType,
                            "RetroDownfall.Arcanum.Core.Operations.ILongRunningOperationRecoveryHandler", candidate.Model.Compilation)
                    || method.Name == "RecoverAuthenticatedAsync"
                        && IsExactAuthoredProtocolType(method.ContainingType,
                            "RetroDownfall.Arcanum.Infrastructure.Data.IAuthenticatedCovenantErasureRecoveryHandler", candidate.Model.Compilation)));
        }

        private PlannedRoot[] PrepareRoots(
            HostedProducerDiscovery<string> registrations,
            IReadOnlyList<HostedProducerServiceEntry> catalog,
            IReadOnlyList<NonHostedProducerChainEntry> nonHostedCatalog)
        {
            HashSet<string> hosted = registrations.Items.ToHashSet(StringComparer.Ordinal);

            HostedProducerOperationEntry[] declared = [.. catalog.SelectMany(static service => service.Operations), .. nonHostedCatalog.Select(static chain => new HostedProducerOperationEntry(chain.ChainId, chain.SourcePath, chain.EnclosingType, chain.Member, chain.Authority, null, chain.Proof, chain.Sites))];

            declaredOperations = declared;

            List<(HostedProducerOperationEntry Operation, AuthoredMember Member, SyntaxNode Selection)> resolvedRoots = [];

            foreach (HostedProducerOperationEntry operation in declared)
            {
                AuthoredMember[] roots = AuthoredMembers.Where(member => member.Syntax.SyntaxTree.FilePath == operation.SourcePath && TypeKey(member.Symbol.ContainingType) == operation.EnclosingType && member.Symbol.Name == operation.Member).ToArray();

                SyntaxNode? selection = roots.Length == 1 ? SelectRoot(roots[0], operation.OperationId) : null;

                if (selection is null)
                {
                    diagnostics.Add(new("HOSTED_ROOT_UNRESOLVED", operation.OperationId, "The exact file/type/member and executable call selector must bind once."));

                    continue;
                }

                if (resolvedRoots.Any(existing => MemberIdentity(existing.Member) == MemberIdentity(roots[0]) && existing.Selection.Span.OverlapsWith(selection.Span)))
                {
                    diagnostics.Add(new("HOSTED_ROOT_OVERLAP", operation.OperationId, "Declared authority roots must select disjoint source regions; whole-member mixed claims are forbidden."));
                }

                resolvedRoots.Add((operation, roots[0], selection));

                if (selection != roots[0].Syntax)
                {
                    GraphMemberIdentity key = MemberIdentity(roots[0]);

                    if (!selectedRoots.TryGetValue(key, out List<SyntaxNode>? selections))
                    {
                        selectedRoots[key] = selections = [];
                    }

                    selections.Add(selection);
                }
            }

            List<PlannedRoot> planned = [];

            foreach (AuthoredMember root in AuthoredMembers.Where(member => hosted.Contains(member.Symbol.ContainingType.Name) && IsLifecycle(member.Symbol)))
            {
                string operation = TypeKey(root.Symbol.ContainingType) + "." + root.Symbol.Name;

                string rootType = root.Symbol.ContainingType.Name;

                planned.Add(new(planned.Count, HostedProducerRootWorkers.FamilyOf(rootType, RootOperation(operation), serviceDeclaresLeaseHandoff: false), rootType, operation, root, true, null));
            }

            foreach ((HostedProducerOperationEntry operation, AuthoredMember root, SyntaxNode selection) in resolvedRoots)
            {
                string rootType = catalog.FirstOrDefault(service => service.Operations.Contains(operation))?.ServiceType ?? nonHostedCatalog.FirstOrDefault(chain => chain.ChainId == operation.OperationId)?.EnclosingType ?? operation.EnclosingType;

                if (operation.LeaseFormal is not null)
                {
                    leaseHandoffRootTypes[operation.OperationId] = rootType;
                }

                planned.Add(new(planned.Count, HostedProducerRootWorkers.FamilyOf(rootType, RootOperation(operation.OperationId), serviceDeclaresLeaseHandoff: false), rootType, operation.OperationId, root, false, selection));
            }

            // A service that declares a lease-handoff root is one family: its roots cut to the handoff root, whose closure is shared only
            // through the state cache of the worker that runs it, so a pool that split them would admit the closure once for every worker.
            HashSet<string> handoffServices = [.. leaseHandoffRootTypes.Values];

            for (int index = 0; index < planned.Count; index++)
            {
                if (handoffServices.Contains(planned[index].RootType))
                {
                    planned[index] = planned[index] with
                    {
                        Family = HostedProducerRootWorkers.FamilyOf(planned[index].RootType, RootOperation(planned[index].Operation), serviceDeclaresLeaseHandoff: true),
                    };
                }
            }

            ValidateLeaseHandoffDeclarations();

            preparedOwnerRecoveryAnchor = resolvedRoots.FirstOrDefault(static root => root.Operation.Authority == HostedProducerAuthorityKind.OwnerBoundRecovery).Selection;

            perUnitRootOwners.Clear();

            foreach (PlannedRoot root in planned.Where(static root => !root.Lifecycle))
            {
                var key = (root.RootType, RootOperation(root.Operation));

                if (!perUnitRootOwners.TryGetValue(key, out HashSet<AuthoredTypeIdentity>? owners))
                {
                    owners = [];

                    perUnitRootOwners.Add(key, owners);
                }

                owners.Add(new(root.Member.Symbol.ContainingAssembly.Identity,
                    CompilationIdentity(root.Member.Model.Compilation), TypeKey(root.Member.Symbol.ContainingType)));
            }

            return planned.ToArray();
        }

        private void TraversePlannedRoot(PlannedRoot root)
        {
            progressOccurrence = root.Occurrence + 1;

            _ = TraverseRoot(root.Member, root.RootType, root.Operation, root.Lifecycle, root.Selection, root);
        }

        private void CompletePrimaryRoots(HostedProducerRecoverySelectionProbe? recoverySelectionProbe)
        {
            if (recoverySelectionProbe is not null)
            {
                TraverseRecoverySelectionProbe(recoverySelectionProbe);
            }

            if (!recoveryMatrixResolved
                && preparedOwnerRecoveryAnchor is { } ownerRecoveryAnchor)
            {
                _ = ResolveRecoveryMatrix(ownerRecoveryAnchor);
            }

            ValidateOwnerRecoveryAssociations();

            CheckLeaseHandoffCallerCensus();
        }

        private void DiscoverExternalRoots(
            HostedProducerDiscovery<string> registrations,
            Func<int> siteCount,
            Action<AuthoredMember, string, string> traverse)
        {
            using HostedProducerPhaseProgress progress = HostedProducerPhaseProgress.Start("external-invocations", progressWorker, invocations.Count);

            int scanned = 0;

            HashSet<string> hosted = registrations.Items.ToHashSet(StringComparer.Ordinal);

            foreach ((InvocationExpressionSyntax call, SemanticModel model) in invocations)
            {
                if (scanned > 0 && scanned % 1024 == 0)
                {
                    progress.Report(scanned);
                }

                scanned++;

                if (model.GetSymbolInfo(call).Symbol is not IMethodSymbol target)
                {
                    continue;
                }

                AuthoredMember? authored = Resolve(target, model.Compilation);

                if (authored is null || !hosted.Contains(authored.Symbol.ContainingType.Name) || IsLifecycle(target))
                {
                    continue;
                }

                IMethodSymbol? caller = model.GetEnclosingSymbol(call.SpanStart) as IMethodSymbol;

                if (caller is not null && SymbolEqualityComparer.Default.Equals(caller.ContainingType, authored.Symbol.ContainingType))
                {
                    continue;
                }

                if (caller is not null && Resolve(caller, model.Compilation) is { } authoredCaller && lifecycleMembers.Contains(MemberIdentity(authoredCaller)))
                {
                    continue;
                }

                bool catalogued = declaredOperations.Any(entry => entry.EnclosingType == TypeKey(authored.Symbol.ContainingType) && entry.Member == authored.Symbol.Name && entry.SourcePath == authored.Syntax.SyntaxTree.FilePath);

                int before = siteCount();

                string operation = TypeKey(authored.Symbol.ContainingType) + "." + authored.Symbol.Name;

                traverse(authored, authored.Symbol.ContainingType.Name, operation);

                if (!catalogued && siteCount() > before)
                {
                    diagnostics.Add(new("HOSTED_EXTERNAL_OPERATION_UNCATALOGUED", Location(call), operation));
                }
            }

            progress.Complete();
        }

        private HostedProducerDiscovery<HostedProducerSite> CompleteDiscovery()
        {
            nestedReuseObserver?.Invoke(progressWorker, completedNestedRoots.Count, retainedNestedWitnesses, nestedReuseHits, boundedDataProbeEncountered);

            using HostedProducerPhaseProgress progress = HostedProducerPhaseProgress.Start("complete-discovery", progressWorker);

            HostedProducerAnalysisMetrics analysisMetrics = new(
                maximumRecoveryConditionEvaluations
                    .OrderBy(static pair => pair.Key, StringComparer.Ordinal)
                    .Select(pair => new HostedProducerRecoveryConditionMetric(
                        pair.Key,
                        pair.Value,
                        totalRecoveryConditionEvaluations.GetValueOrDefault(pair.Key),
                        totalRecoveryFeasibilityQueries.GetValueOrDefault(pair.Key),
                        totalRecoveryPlanBuilds.GetValueOrDefault(pair.Key),
                        totalRecoveryStructuralInspections.GetValueOrDefault(pair.Key),
                        totalRecoveryUnreachableIntervals.GetValueOrDefault(pair.Key),
                        totalRecoveryProbeComparisons.GetValueOrDefault(pair.Key),
                        totalRecoveryParityComparisons.GetValueOrDefault(pair.Key),
                        totalRecoveryParityMismatches.GetValueOrDefault(pair.Key),
                        totalRecoveryValueQueries.GetValueOrDefault(pair.Key)))
                    .ToArray(),
                retainedAdmissionAnalysis
                    .OrderBy(static pair => pair.Key, StringComparer.Ordinal)
                    .Select(static pair => new HostedProducerRetainedAdmissionMetric(
                        pair.Key,
                        pair.Value.AuthorityQueries,
                        pair.Value.OriginFreeFastPathReturns,
                        pair.Value.OriginPossibilityRequests,
                        pair.Value.OriginPossibilityBuilds,
                        pair.Value.SemanticQueries,
                        pair.Value.QueryPositions.Count,
                        pair.Value.SourceIndexBuilds,
                        pair.Value.LifetimeNodeInspections))
                    .ToArray(),
                evaluationEnvironmentAnalysis
                    .OrderBy(static pair => pair.Key, StringComparer.Ordinal)
                    .Select(static pair => new HostedProducerEvaluationEnvironmentMetric(
                        pair.Key,
                        pair.Value.FingerprintRequests,
                        pair.Value.FingerprintBuilds,
                        pair.Value.EquivalentKeyBuilds,
                        pair.Value.EquivalentKeyNodes,
                        pair.Value.InternerRequests,
                        pair.Value.InternerContextBuilds,
                        pair.Value.InternerIdentityBuilds,
                        pair.Value.InternerHits,
                        pair.Value.InternerRegistrations,
                        pair.Value.InternerTraversalIdentityBuilds,
                        pair.Value.StableLocalProofRequests,
                        pair.Value.StableLocalProofBuilds,
                        pair.Value.StableLocalProofHits,
                        pair.Value.ExactValueProvenanceVisits,
                        pair.Value.ValueNormalizationRequests,
                        pair.Value.ValueNormalizationBuilds,
                        pair.Value.ValueNormalizationHits))
                    .ToArray(),
                traversalRecoveryProjectionAnalysis
                    .OrderBy(static pair => pair.Key, StringComparer.Ordinal)
                    .Select(static pair => new HostedProducerTraversalRecoveryProjectionMetric(
                        pair.Key,
                        pair.Value.Requests,
                        pair.Value.Builds,
                        pair.Value.CacheHits,
                        pair.Value.WholeMemberScans,
                        pair.Value.ExpressionsInspected,
                        pair.Value.AssignmentScans,
                        pair.Value.AssignmentInspections,
                        pair.Value.DependencyNodes,
                        pair.Value.DependencyCacheHits))
                    .ToArray(),
                invocationExecutionAnalysis
                    .OrderBy(static pair => pair.Key, StringComparer.Ordinal)
                    .Select(static pair => new HostedProducerInvocationExecutionMetric(
                        pair.Key,
                        pair.Value.PlanRequests,
                        pair.Value.PlanBuilds))
                    .ToArray(),
                closedCallableAnalysis
                    .OrderBy(static pair => pair.Key, StringComparer.Ordinal)
                    .Select(static pair => new HostedProducerClosedCallableMetric(
                        pair.Key,
                        pair.Value.ResolutionRequests,
                        pair.Value.ResolutionBuilds))
                    .ToArray(),
                rootTraversalAnalysis
                    .OrderBy(static pair => pair.Key.RootType, StringComparer.Ordinal)
                    .ThenBy(static pair => pair.Key.RootOperation, StringComparer.Ordinal)
                    .Select(pair => new HostedProducerRootTraversalMetric(
                        pair.Value.RootType,
                        pair.Value.RootOperation,
                        pair.Value.TraversalCalls,
                        analyzedStateCounts.GetValueOrDefault(
                            pair.Value.RootType
                                + "|"
                                + pair.Value.RootOperation),
                        pair.Value.Elapsed))
                    .ToArray(),
                publicationRegionAnalysis
                    .OrderBy(static pair => pair.Value.Member, StringComparer.Ordinal)
                    .ThenBy(static pair => pair.Key.Compilation)
                    .ThenBy(static pair => pair.Key.Tree)
                    .ThenBy(static pair => pair.Key.SpanStart)
                    .Select(static pair => new HostedProducerPublicationRegionMetric(
                        pair.Value.Member,
                        pair.Value.IndexRequests,
                        pair.Value.IndexBuilds,
                        pair.Value.CandidateInspections))
                    .ToArray(),
                cleanupCacheAnalysis
                    .OrderBy(static pair => pair.Key, StringComparer.Ordinal)
                    .Select(static pair => new HostedProducerCleanupCacheMetric(
                        pair.Key,
                        pair.Value.ProvenanceRequests,
                        pair.Value.ProvenanceBuilds,
                        pair.Value.ProvenanceStableHits,
                        pair.Value.ValueFlowRequests,
                        pair.Value.ValueFlowBuilds,
                        pair.Value.ValueFlowStableHits))
                    .ToArray(),
                repeatedRegistrationSemanticQueries,
                registrationCandidateInspections)
            {
                CleanupSources = cleanupSourceAnalysis
                    .OrderBy(static pair => pair.Key.Kind, StringComparer.Ordinal)
                    .ThenBy(static pair => pair.Key.Identity.Compilation)
                    .ThenBy(static pair => pair.Key.Identity.Symbol.ToDisplayString(), StringComparer.Ordinal)
                    .Select(static pair => new HostedProducerCleanupSourceMetric(
                        pair.Key.Kind,
                        pair.Key.Identity.Compilation,
                        pair.Key.Identity.Symbol.ToDisplayString(),
                        pair.Value.Requests,
                        pair.Value.Builds))
                    .ToArray(),
            };

            HostedProducerDiscovery<HostedProducerSite> result = new(
                sites.Values.OrderBy(SiteIdentity, StringComparer.Ordinal).ToArray(),
                diagnostics.Distinct()
                    .OrderBy(static diagnostic => diagnostic.Code, StringComparer.Ordinal)
                    .ThenBy(static diagnostic => diagnostic.Identity, StringComparer.Ordinal)
                    .ThenBy(static diagnostic => diagnostic.Detail, StringComparer.Ordinal).ToArray(),
                analysisMetrics);

            progress.Complete();

            return result;
        }

        private void TraverseRecoverySelectionProbe(
            HostedProducerRecoverySelectionProbe probe,
            Func<string, string, ProducerGraph>? selectOwner = null)
        {
            (AuthoredMember Member, InvocationExpressionSyntax Call)[] bindingCalls =
                AuthoredMembers
                    .Select(member => (
                        Member: member,
                        Call: SelectRoot(member, probe.BindingCallOperationId)
                            as InvocationExpressionSyntax))
                    .Where(static candidate => candidate.Call is not null)
                    .Select(static candidate => (candidate.Member, candidate.Call!))
                    .ToArray();

            if (bindingCalls is not [(AuthoredMember caller, InvocationExpressionSyntax call)]
                || caller.Model.GetSymbolInfo(call).Symbol is not IMethodSymbol method
                || ResolveInvocationTarget(method, caller, call) is not { } target)
            {
                diagnostics.Add(new(
                    "HOSTED_RECOVERY_SELECTION_PROBE_UNRESOLVED",
                    probe.BindingCallOperationId,
                    "The exact binding call must resolve once to one authored target."));

                return;
            }

            foreach (string operationId in probe.SelectionOperationIds)
            {
                if (selectOwner is not null)
                {
                    ProducerGraph owner = selectOwner(TypeKey(target.Symbol.ContainingType), operationId);

                    owner.TraverseRecoverySelectionProbe(probe with { SelectionOperationIds = [operationId] });

                    continue;
                }

                AuthoredMember bound = BindAdmissionArguments(caller, call, target);

                if (SelectRoot(bound, operationId) is not { } selection)
                {
                    diagnostics.Add(new(
                        "HOSTED_RECOVERY_SELECTION_PROBE_UNRESOLVED",
                        operationId,
                        "The exact selected target call must resolve once."));

                    continue;
                }

                _ = TraverseRoot(
                    bound,
                    TypeKey(bound.Symbol.ContainingType),
                    operationId,
                    lifecycle: false,
                    selection: selection);
            }
        }

        private TraversalEvidence TraverseRoot(
            AuthoredMember member,
            string rootType,
            string operationId,
            bool lifecycle,
            SyntaxNode? selection = null,
            PlannedRoot? plannedRoot = null)
        {
            string rootOperation = RootOperation(operationId);

            var key = (RootType: rootType, RootOperation: rootOperation);

            if (!rootTraversalAnalysis.TryGetValue(
                    key,
                    out RootTraversalAnalysisCounter? analysis))
            {
                analysis = new(rootType, rootOperation);

                rootTraversalAnalysis.Add(key, analysis);
            }

            long started = Stopwatch.GetTimestamp();

            int sequence = ++rootTraversalSequence;

            int statesBefore = analyzedStateCounts.GetValueOrDefault(
                rootType + "|" + rootOperation);

            WriteRootProgress(
                "start",
                sequence,
                rootType,
                rootOperation,
                TimeSpan.Zero,
                0);

            bool completed = false;

            try
            {
                (member, string? rootWork) = CanonicalDeclaredRoot(
                    member,
                    operationId,
                    selection,
                    lifecycle);

                TraversalEvidence result = Traverse(
                    member,
                    rootType,
                    operationId,
                    [],
                    lifecycle,
                    inheritedWork: rootWork,
                    selection: selection,
                    plannedRoot: plannedRoot);

                completed = true;

                return result;
            }
            finally
            {
                TimeSpan elapsed = Stopwatch.GetElapsedTime(started);

                analysis.TraversalCalls++;

                analysis.Elapsed += elapsed;

                WriteRootProgress(
                    completed ? "complete" : "failed",
                    sequence,
                    rootType,
                    rootOperation,
                    elapsed,
                    analyzedStateCounts.GetValueOrDefault(
                        rootType + "|" + rootOperation) - statesBefore);
            }
        }

        private AuthoredMember BindLifecycleRootFactoryContext(
            AuthoredMember member)
        {
            if (!diActivationRegistrations.TryGetValue(
                    new(
                        member.Symbol.ContainingAssembly.Identity,
                        TypeKey(member.Symbol.ContainingType)),
                    out List<ResolvedRegistration>? registrations))
            {
                return member;
            }

            bool NamesLifecycleType(ResolvedRegistration registration) =>
                registration.Method.TypeArguments.Any(type => SameBoundType(
                    type,
                    registration.Model.Compilation,
                    member.Symbol.ContainingType,
                    member.Model.Compilation));

            ResolvedRegistration[] hostedRegistrations = registrations
                .Where(registration =>
                    registration.Method.Name == "AddHostedService"
                    && NamesLifecycleType(registration))
                .DistinctBy(
                    static registration => registration.Call,
                    ReferenceEqualityComparer.Instance)
                .ToArray();

            if (hostedRegistrations is not
                    [ResolvedRegistration hostedRegistration]
                || !IsExactFrameworkMethod(
                    hostedRegistration.Method,
                    "Microsoft.Extensions.DependencyInjection.ServiceCollectionHostedServiceExtensions",
                    "AddHostedService",
                    "Microsoft.Extensions.Hosting.Abstractions"))
            {
                return member;
            }

            AuthoredMember? BindFactoryConstruction(
                ResolvedRegistration registration,
                AnonymousFunctionExpressionSyntax factory)
            {
                if (ExactFactoryCreation(factory) is not
                        BaseObjectCreationExpressionSyntax creation
                    || registration.Model.GetSymbolInfo(creation).Symbol is not
                        IMethodSymbol constructor
                    || !SameBoundType(
                        constructor.ContainingType,
                        registration.Model.Compilation,
                        member.Symbol.ContainingType,
                        member.Model.Compilation)
                    || ResolveCallable(
                        factory,
                        registration.Model,
                        null,
                        null) is not { } factoryMember
                    || ResolveConstructorContextTarget(
                        constructor,
                        registration.Model.Compilation) is not { } target)
                {
                    return null;
                }

                return BindConstructedReadonlyFieldContext(
                    BindCleanupConstructorArguments(
                        factoryMember,
                        creation,
                        target));
            }

            ArgumentSyntax[] hostedArguments = hostedRegistration.Call
                .ArgumentList.Arguments
                .ToArray();

            AuthoredMember? exact;

            if (hostedArguments.Length == 0)
            {
                IMethodSymbol[] constructors = member.Symbol.ContainingType
                    .InstanceConstructors
                    .Where(static constructor =>
                        !constructor.IsStatic
                        && constructor.DeclaredAccessibility
                            == Accessibility.Public)
                    .DistinctBy(
                        static constructor => constructor.OriginalDefinition,
                        SymbolEqualityComparer.Default)
                    .ToArray();

                if (constructors is not [IMethodSymbol constructor]
                    || ResolveConstructorContextTarget(
                        constructor,
                        member.Model.Compilation) is not { } target)
                {
                    return member;
                }

                exact = BindConstructedReadonlyFieldContext(target with
                {
                    ConstructorContexts = new HashSet<IMethodSymbol>(
                        [constructor],
                        SymbolEqualityComparer.Default),
                });
            }
            else if (hostedArguments is
                [ArgumentSyntax
                {
                    Expression: AnonymousFunctionExpressionSyntax factory,
                }])
            {
                exact = BindFactoryConstruction(hostedRegistration, factory);

                if (exact is null)
                {
                    IParameterSymbol? provider = factory switch
                    {
                        SimpleLambdaExpressionSyntax simple =>
                            hostedRegistration.Model.GetDeclaredSymbol(
                                simple.Parameter),
                        ParenthesizedLambdaExpressionSyntax
                        {
                            ParameterList.Parameters:
                                [ParameterSyntax parameter],
                        } => hostedRegistration.Model.GetDeclaredSymbol(
                            parameter),
                        _ => null,
                    };

                    if (provider is null
                        || !IsExactFrameworkType(
                            provider.Type,
                            "System.IServiceProvider",
                            typeof(IServiceProvider).Assembly.GetName())
                        || ExactFactoryCreation(factory) is not
                        { } forwardedService
                        || !IsExactFactoryServiceResolution(
                            hostedRegistration.Model,
                            forwardedService,
                            provider,
                            member.Symbol.ContainingType,
                            member.Model.Compilation))
                    {
                        return member;
                    }

                    ResolvedRegistration[] serviceRegistrations = registrations
                        .Where(registration =>
                            !ReferenceEquals(
                                registration.Call,
                                hostedRegistration.Call))
                        .DistinctBy(
                            static registration => registration.Call,
                            ReferenceEqualityComparer.Instance)
                        .ToArray();

                    if (serviceRegistrations is not
                            [ResolvedRegistration serviceRegistration]
                        || !IsExactRootFactoryRegistrationMethod(
                            serviceRegistration.Method)
                        || serviceRegistration.Method.Name is not
                            ("AddSingleton" or "TryAddSingleton")
                        || serviceRegistration.Method.TypeArguments
                            .FirstOrDefault() is not { } registeredService
                        || !SameBoundType(
                            registeredService,
                            serviceRegistration.Model.Compilation,
                            member.Symbol.ContainingType,
                            member.Model.Compilation)
                        || serviceRegistration.Call.ArgumentList.Arguments
                            is not
                            [ArgumentSyntax
                            {
                                Expression:
                                    AnonymousFunctionExpressionSyntax
                                        serviceFactory,
                            }])
                    {
                        return member;
                    }

                    exact = BindFactoryConstruction(
                        serviceRegistration,
                        serviceFactory);
                }
            }
            else
            {
                return member;
            }

            return exact is null
                ? member
                : MergeValueContext(
                    member,
                    BindDemandedReceiverReadonlyFieldContext(
                        exact,
                        member));
        }

        private AuthoredMember BindDeclaredRootFactoryContext(
            AuthoredMember member,
            string operationId,
            SyntaxNode? selection)
        {
            if (!declaredOperations.Any(operation =>
                    (operationId == operation.OperationId
                        || operationId.StartsWith(
                            operation.OperationId + "/",
                            StringComparison.Ordinal))
                    && operation.SourcePath == member.Syntax.SyntaxTree.FilePath
                    && operation.EnclosingType
                        == TypeKey(member.Symbol.ContainingType)
                    && operation.Member == member.Symbol.Name)
                || !diActivationRegistrations.TryGetValue(
                    new(
                        member.Symbol.ContainingAssembly.Identity,
                        TypeKey(member.Symbol.ContainingType)),
                    out List<ResolvedRegistration>? registrations)
                || registrations is not [ResolvedRegistration registration]
                || !IsExactRootFactoryRegistrationMethod(
                    registration.Method))
            {
                return member;
            }

            ArgumentSyntax[] arguments = registration.Call.ArgumentList
                .Arguments
                .ToArray();

            AuthoredMember target;

            AuthoredMember constructed;

            if (arguments.Length == 0)
            {
                if (registration.Method.TypeArguments.LastOrDefault() is not
                        { } registeredImplementation
                    || !SameBoundType(
                        registeredImplementation,
                        registration.Model.Compilation,
                        member.Symbol.ContainingType,
                        member.Model.Compilation))
                {
                    return member;
                }

                IMethodSymbol[] constructors = member.Symbol.ContainingType
                    .InstanceConstructors
                    .Where(static constructor =>
                        !constructor.IsStatic
                        && constructor.DeclaredAccessibility
                            == Accessibility.Public)
                    .DistinctBy(
                        static constructor => constructor.OriginalDefinition,
                        SymbolEqualityComparer.Default)
                    .ToArray();

                if (constructors is not [IMethodSymbol constructor]
                    || ResolveConstructorContextTarget(
                        constructor,
                        member.Model.Compilation) is not { } constructorTarget)
                {
                    return member;
                }

                target = constructorTarget;

                constructed = BindConstructedReadonlyFieldContext(target with
                {
                    ConstructorContexts = new HashSet<IMethodSymbol>(
                        [constructor],
                        SymbolEqualityComparer.Default),
                });
            }
            else if (arguments is
                    [ArgumentSyntax
                    {
                        Expression: AnonymousFunctionExpressionSyntax factory,
                    }]
                && ExactFactoryCreation(factory) is
                    BaseObjectCreationExpressionSyntax creation
                && registration.Model.GetSymbolInfo(creation).Symbol is
                    IMethodSymbol constructor
                && SameBoundType(
                    constructor.ContainingType,
                    registration.Model.Compilation,
                    member.Symbol.ContainingType,
                    member.Model.Compilation)
                && ResolveCallable(
                    factory,
                    registration.Model,
                    null,
                    null) is { } factoryMember
                && ResolveConstructorContextTarget(
                    constructor,
                    registration.Model.Compilation) is { } constructorTarget)
            {
                target = constructorTarget;

                constructed = BindConstructedReadonlyFieldContext(
                    BindCleanupConstructorArguments(
                        factoryMember,
                        creation,
                        target));
            }
            else
            {
                return member;
            }

            AuthoredMember constructionContext = MergeValueContext(
                member,
                constructed);

            Dictionary<ISymbol, BoundValueSource> demanded =
                member.ValueBindings?.ToDictionary(
                    static pair => pair.Key,
                    static pair => pair.Value,
                    SymbolEqualityComparer.Default)
                ?? new(SymbolEqualityComparer.Default);

            foreach ((IFieldSymbol field, ExpressionSyntax use) in
                DeclaredRootDemandedFieldUses(
                        member,
                        selection ?? member.Syntax,
                        allowRelinquishedFields: true)
                    .DistinctBy(
                        static candidate => candidate.Item1,
                        SymbolEqualityComparer.Default))
            {
                BoundValueSource[] values = constructed.ValueBindings?.TryGetValue(
                        field,
                        out BoundValueSource? selected) == true
                    && selected is not null
                        ? [selected]
                        : !field.IsReadOnly
                            ? ExactAssignedFieldCleanupValueFlow(
                                constructionContext,
                                use,
                                field,
                                new CleanupProvenanceContext(),
                                allowSameOwnerLifetimeWriters:
                                    HasExactSameOwnerLifetimeFieldWriterSemantics(
                                        field)) is
                            { Complete: true } relinquished
                                    ? relinquished.Values.ToArray()
                                    : []
                            : ExactReadOnlyFieldValues(
                                    constructionContext,
                                    StripTransparentExpression(use),
                                    field)
                                .Where(value =>
                                    SymbolEqualityComparer.Default.Equals(
                                        value.Caller.Symbol.OriginalDefinition,
                                        target.Symbol.OriginalDefinition))
                                .ToArray();

                if (values is not [BoundValueSource value])
                {
                    continue;
                }

                HashSet<ISymbol> dependencies =
                    DeclaredRootConstructorDependencies(value, target);

                IReadOnlyDictionary<ISymbol, BoundValueSource>? bindings =
                    value.Caller.ValueBindings?
                        .Where(pair => dependencies.Contains(pair.Key))
                        .ToDictionary(
                            static pair => pair.Key,
                            static pair => pair.Value,
                            SymbolEqualityComparer.Default);

                demanded[field] = value with
                {
                    Caller = value.Caller with
                    {
                        ValueBindings = bindings,
                    },
                };
            }

            return member with
            {
                ValueBindings = demanded,
                ConstructorContexts = constructed.ConstructorContexts,
            };
        }

        private HashSet<ISymbol> DeclaredRootConstructorDependencies(
            BoundValueSource source,
            AuthoredMember constructor)
        {
            HashSet<ISymbol> dependencies = new(SymbolEqualityComparer.Default);

            HashSet<IFieldSymbol> visitedFields = new(
                SymbolEqualityComparer.Default);

            HashSet<ILocalSymbol> visitedLocals = new(
                SymbolEqualityComparer.Default);

            Stack<(BoundValueSource Source, int Depth)> pending = new();

            pending.Push((source, 0));

            while (pending.TryPop(out var current))
            {
                foreach (ExpressionSyntax expression in current.Source.Expression
                    .DescendantNodesAndSelf()
                    .OfType<ExpressionSyntax>())
                {
                    ISymbol? symbol = current.Source.Caller.Model
                        .GetSymbolInfo(expression)
                        .Symbol;

                    if (symbol is null)
                    {
                        continue;
                    }

                    if (symbol is IParameterSymbol or ILocalSymbol
                        && !RecoveryTupleSourceIsStable(
                            current.Source.Caller,
                            symbol,
                            current.Source.Expression,
                            allowSimpleLocalAssignments: false))
                    {
                        continue;
                    }

                    dependencies.Add(symbol);

                    if (current.Depth < ReceiverCleanupForwardingMaximumDepth
                        && symbol is ILocalSymbol local
                        && SymbolEqualityComparer.Default.Equals(
                            local.ContainingSymbol,
                            current.Source.Caller.Symbol)
                        && local.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                            is VariableDeclaratorSyntax { Initializer.Value: { } initializer } declaration
                        && declaration.SyntaxTree == current.Source.Caller.Syntax.SyntaxTree
                        && current.Source.Caller.Syntax.Span.Contains(declaration.Span)
                        && visitedLocals.Add(local))
                    {
                        pending.Push((new(current.Source.Caller, initializer), current.Depth + 1));
                    }

                    if (current.Depth >= ReceiverCleanupForwardingMaximumDepth
                        || symbol is not IFieldSymbol
                        {
                            IsStatic: false,
                            IsReadOnly: true,
                            DeclaredAccessibility: Accessibility.Private,
                        } field
                        || !SymbolEqualityComparer.Default.Equals(
                            field.ContainingType,
                            constructor.Symbol.ContainingType)
                        || !visitedFields.Add(field))
                    {
                        continue;
                    }

                    BoundValueSource[] nested = ExactReadOnlyFieldValues(
                            current.Source.Caller,
                            expression,
                            field)
                        .Where(value =>
                            SymbolEqualityComparer.Default.Equals(
                                value.Caller.Symbol.OriginalDefinition,
                                constructor.Symbol.OriginalDefinition))
                        .ToArray();

                    if (nested is [BoundValueSource value])
                    {
                        pending.Push((value, current.Depth + 1));
                    }
                }
            }

            return dependencies;
        }

        private IEnumerable<(IFieldSymbol Field, ExpressionSyntax Use)>
            DeclaredRootDemandedFieldUses(
                AuthoredMember root,
                SyntaxNode selection,
                bool allowRelinquishedFields = false)
        {
            HashSet<GraphMemberIdentity> visited = [];

            Stack<(AuthoredMember Member, SyntaxNode Scope, int Depth)> pending =
                new();

            pending.Push((root, selection, 0));

            while (pending.TryPop(out var current))
            {
                if (current.Depth >= ReceiverCleanupForwardingMaximumDepth
                    || !visited.Add(MemberIdentity(current.Member)))
                {
                    continue;
                }

                foreach (ExpressionSyntax expression in current.Scope
                    .DescendantNodesAndSelf()
                    .OfType<ExpressionSyntax>())
                {
                    ISymbol? symbol = current.Member.Model.GetSymbolInfo(expression).Symbol;

                    if (symbol is IFieldSymbol
                        {
                            IsStatic: false,
                            DeclaredAccessibility: Accessibility.Private,
                        } field
                        && (field.IsReadOnly
                            || allowRelinquishedFields
                                && (HasExactGuardedFieldReadSemantics(
                                        field,
                                        allowNullingAssignments: true)
                                    || HasExactSameOwnerLifetimeFieldWriterSemantics(
                                        field)))
                        && SymbolEqualityComparer.Default.Equals(
                            field.ContainingType,
                            root.Symbol.ContainingType))
                    {
                        yield return (field, expression);
                    }

                    if (symbol is IPropertySymbol
                        {
                            IsStatic: false,
                            GetMethod: { } getter,
                        }
                        && SymbolEqualityComparer.Default.Equals(
                            symbol.ContainingType,
                            root.Symbol.ContainingType)
                        && StripTransparentExpression(expression) is
                            (IdentifierNameSyntax or MemberAccessExpressionSyntax
                            {
                                Expression: ThisExpressionSyntax,
                            })
                        && Resolve(
                            getter,
                            current.Member.Model.Compilation) is { } target)
                    {
                        pending.Push((target, target.Syntax, current.Depth + 1));
                    }
                }

                foreach (InvocationExpressionSyntax call in current.Scope
                    .DescendantNodesAndSelf()
                    .OfType<InvocationExpressionSyntax>())
                {
                    if (current.Member.Model.GetSymbolInfo(call).Symbol is not
                            IMethodSymbol method)
                    {
                        continue;
                    }

                    AuthoredMember? target = ResolveInvocationTarget(
                            method,
                            current.Member,
                            call)
                        ?? Resolve(method, current.Member.Model.Compilation);

                    if (target is not { Symbol.IsStatic: false }
                        || !SymbolEqualityComparer.Default.Equals(
                            target.Symbol.ContainingType,
                            root.Symbol.ContainingType)
                        || StripTransparentExpression(call.Expression) is not
                            (IdentifierNameSyntax or GenericNameSyntax
                                or MemberAccessExpressionSyntax
                            {
                                Expression: ThisExpressionSyntax,
                            }))
                    {
                        continue;
                    }

                    pending.Push((
                        target,
                        target.Syntax,
                        current.Depth + 1));
                }
            }
        }

        private bool IsExactRootFactoryRegistrationMethod(
            IMethodSymbol method) =>
            method.Name is "AddSingleton" or "AddScoped" or "AddTransient"
                && IsExactFrameworkMethod(
                    method,
                    "Microsoft.Extensions.DependencyInjection.ServiceCollectionServiceExtensions",
                    method.Name,
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
            || method.Name is
                    "TryAddSingleton" or "TryAddScoped" or "TryAddTransient"
                && IsExactFrameworkMethod(
                    method,
                    "Microsoft.Extensions.DependencyInjection.Extensions.ServiceCollectionDescriptorExtensions",
                    method.Name,
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
            || IsExactResetAwareHostedServiceRegistration(method);

        private bool IsExactResetAwareHostedServiceRegistration(
            IMethodSymbol method)
        {
            IMethodSymbol definition = (method.ReducedFrom ?? method)
                .OriginalDefinition;

            if (definition.Name !=
                    "AddInstallationResetRecoveryAwareHostedService"
                || TypeKey(definition.ContainingType) !=
                    "RetroDownfall.Arcanum.Infrastructure.DependencyInjection.ServiceCollectionExtensions"
                || method.TypeArguments is not
                    [INamedTypeSymbol implementation]
                || !implementation.AllInterfaces.Any(static contract =>
                    TypeKey(contract)
                        == "Microsoft.Extensions.Hosting.IHostedService")
                || definition.TypeParameters is not [ITypeParameterSymbol service]
                || definition.DeclaringSyntaxReferences is not
                    [SyntaxReference declarationReference]
                || declarationReference.GetSyntax() is not
                    MethodDeclarationSyntax
                    {
                        ParameterList.Parameters:
                            [ParameterSyntax collectionSyntax],
                        Body.Statements:
                            [
                                ExpressionStatementSyntax activationStatement,
                                ExpressionStatementSyntax wrapperStatement,
                                ReturnStatementSyntax returnStatement,
                            ],
                    } declaration
                || !semanticModels.TryGetValue(
                    declaration.SyntaxTree,
                    out SemanticModel? model)
                || model.GetDeclaredSymbol(collectionSyntax) is not
                    IParameterSymbol collection
                || activationStatement.Expression is not
                    InvocationExpressionSyntax activation
                || model.GetSymbolInfo(activation).Symbol is not
                    IMethodSymbol activationMethod
                || activationMethod.TypeArguments is not
                    [ITypeSymbol activated]
                || !SymbolEqualityComparer.Default.Equals(activated, service)
                || !IsExactFrameworkMethod(
                    activationMethod,
                    "Microsoft.Extensions.DependencyInjection.Extensions.ServiceCollectionDescriptorExtensions",
                    "TryAddSingleton",
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
                || InvocationReceiver(activation) is not { } activationReceiver
                || !SymbolEqualityComparer.Default.Equals(
                    model.GetSymbolInfo(activationReceiver).Symbol,
                    collection)
                || wrapperStatement.Expression is not
                    InvocationExpressionSyntax wrapper
                || model.GetSymbolInfo(wrapper).Symbol is not
                    IMethodSymbol wrapperMethod
                || !IsExactFrameworkMethod(
                    wrapperMethod,
                    "Microsoft.Extensions.DependencyInjection.ServiceCollectionHostedServiceExtensions",
                    "AddHostedService",
                    "Microsoft.Extensions.Hosting.Abstractions")
                || wrapperMethod.TypeArguments is not
                    [INamedTypeSymbol
                    {
                        TypeArguments: [ITypeSymbol wrapped],
                    } wrapperType]
                || TypeKey(wrapperType.OriginalDefinition) !=
                    "RetroDownfall.Arcanum.Infrastructure.Hosting.InstallationResetRecoveryAwareHostedService`1"
                || !SymbolEqualityComparer.Default.Equals(wrapped, service)
                || InvocationReceiver(wrapper) is not { } wrapperReceiver
                || !SymbolEqualityComparer.Default.Equals(
                    model.GetSymbolInfo(wrapperReceiver).Symbol,
                    collection)
                || returnStatement.Expression is not { } returned
                || !SymbolEqualityComparer.Default.Equals(
                    model.GetSymbolInfo(returned).Symbol,
                    collection))
            {
                return false;
            }

            return true;
        }

        private static ExpressionSyntax? InvocationReceiver(
            InvocationExpressionSyntax invocation) => invocation.Expression is
                MemberAccessExpressionSyntax access
                    ? access.Expression
                    : null;

        private void WriteRootProgress(
            string phase,
            int sequence,
            string rootType,
            string rootOperation,
            TimeSpan elapsed,
            int states)
        {
            string? path = global::System.Environment.GetEnvironmentVariable(
                "ARCANUM_HOSTED_ANALYSIS_PROGRESS");

            if (string.IsNullOrWhiteSpace(path))
            {
                return;
            }

            static string Safe(string value) => value
                .Replace('\t', ' ')
                .Replace('\r', ' ')
                .Replace('\n', ' ');

            string line = string.Join(
                '\t',
                "HOSTED_ROOT_PROGRESS",
                "phase=" + phase,
                "worker=" + progressWorker.ToString(CultureInfo.InvariantCulture),
                "occurrence=" + progressOccurrence.ToString(CultureInfo.InvariantCulture),
                "sequence=" + sequence.ToString(CultureInfo.InvariantCulture),
                "elapsed_ms=" + elapsed.TotalMilliseconds.ToString("F3", CultureInfo.InvariantCulture),
                "states=" + states.ToString(CultureInfo.InvariantCulture),
                "root_type=" + Safe(rootType),
                "root=" + Safe(rootOperation));

            AppendProgressLine(path, line);
        }

        private void WriteRootStateProgress(
            string rootType,
            string rootOperation,
            int states,
            GraphMemberIdentity member,
            int memberStates,
            IReadOnlyDictionary<GraphMemberIdentity, int> stateCounts)
        {
            string? path = global::System.Environment.GetEnvironmentVariable(
                "ARCANUM_HOSTED_ANALYSIS_PROGRESS");

            if (string.IsNullOrWhiteSpace(path))
            {
                return;
            }

            static string Safe(string value) => value
                .Replace('\t', ' ')
                .Replace('\r', ' ')
                .Replace('\n', ' ');

            string topMembers = string.Join(
                ';',
                stateCounts
                    .OrderByDescending(static pair => pair.Value)
                    .ThenBy(static pair => pair.Key.Method, StringComparer.Ordinal)
                    .Take(5)
                    .Select(pair => Safe(pair.Key.Method)
                        + ":"
                        + pair.Value.ToString(CultureInfo.InvariantCulture)));

            string line = string.Join(
                '\t',
                "HOSTED_STATE_PROGRESS",
                "worker=" + progressWorker.ToString(CultureInfo.InvariantCulture),
                "occurrence=" + progressOccurrence.ToString(CultureInfo.InvariantCulture),
                "states=" + states.ToString(CultureInfo.InvariantCulture),
                "member_states=" + memberStates.ToString(CultureInfo.InvariantCulture),
                "member=" + Safe(member.Method),
                "top_members=" + topMembers,
                "root_type=" + Safe(rootType),
                "root=" + Safe(rootOperation));

            AppendProgressLine(path, line);
        }

        private static void AppendProgressLine(string path, string line)
        {
            HostedProducerPhaseProgress.AppendProgressLine(path, line);
        }

        private void ValidateOwnerRecoveryAssociations()
        {
            if (recoveryMatrix is not { IsValid: true } matrix)
            {
                return;
            }

            RecoveryTuple[] ownerTuples = matrix.Tuples
                .Where(static tuple => tuple.Disposition == RecoveryDisposition.OwnerBound)
                .ToArray();

            foreach (RecoveryTuple tuple in ownerTuples)
            {
                if (!ownerRecoveryAssociations.Any(association =>
                        association.Kind == tuple.Kind
                        && association.CheckpointVersion == tuple.CheckpointVersion))
                {
                    diagnostics.Add(new(
                        "HOSTED_RECOVERY_OWNER_ROOT_UNPROVEN",
                        tuple.Kind + ":" + tuple.CheckpointVersion,
                        "The owner-bound checkpoint must be reached from a declared exact-owner recovery root."));
                }
            }

            foreach (HostedProducerOperationEntry root in declaredOperations.Where(static operation =>
                operation.Authority == HostedProducerAuthorityKind.OwnerBoundRecovery))
            {
                if (!ownerRecoveryAssociations.Any(association =>
                        association.RootOperation == root.OperationId))
                {
                    diagnostics.Add(new(
                        "HOSTED_RECOVERY_OWNER_ROOT_UNPROVEN",
                        root.OperationId,
                        "The declared exact-owner recovery root must reach at least one owner-bound checkpoint handler."));
                }
            }
        }

        private static SyntaxNode? SelectRoot(AuthoredMember member, string operationId)
        {
            string identity = TypeKey(member.Symbol.ContainingType) + "." + member.Symbol.Name;

            if (operationId == identity)
            {
                return member.Syntax;
            }

            string prefix = identity + "::call:";

            if (!operationId.StartsWith(prefix, StringComparison.Ordinal))
            {
                return null;
            }

            int separator = operationId.LastIndexOf('#');

            int fingerprintSeparator = operationId.LastIndexOf('~');

            if (separator < prefix.Length || fingerprintSeparator <= separator || !int.TryParse(operationId[(separator + 1)..fingerprintSeparator], NumberStyles.None, CultureInfo.InvariantCulture, out int occurrence) || occurrence < 0 || !IsSha256(operationId[(fingerprintSeparator + 1)..]))
            {
                return null;
            }

            string callee = operationId[prefix.Length..separator];

            InvocationExpressionSyntax? selected = member.Syntax.DescendantNodes().OfType<InvocationExpressionSyntax>().Where(call => member.Model.GetSymbolInfo(call).Symbol is IMethodSymbol target && Normalize(target) == callee).ElementAtOrDefault(occurrence);

            return selected is not null && Fingerprint(selected) == operationId[(fingerprintSeparator + 1)..]
                ? selected
                : null;
        }

        private AuthoredMember? Resolve(IMethodSymbol method, Compilation consumingCompilation)
        {
            IMethodSymbol definition = (method.ReducedFrom ?? method).OriginalDefinition;

            static bool IsClosedInternalType(INamedTypeSymbol type) => type.DeclaredAccessibility is Accessibility.Internal or Accessibility.Private
                || type.ContainingType is { } containing && IsClosedInternalType(containing);

            MethodIdentity identity = Identity(method);

            if (resolvedMembers.TryGetValue(consumingCompilation, out Dictionary<IAssemblySymbol, Dictionary<string, AuthoredMember>>? assemblyResolutions)
                && assemblyResolutions.TryGetValue(definition.ContainingAssembly, out Dictionary<string, AuthoredMember>? methodResolutions)
                && methodResolutions.TryGetValue(identity.Method, out AuthoredMember? cached))
            {
                return cached;
            }

            if (nonAuthoredMethods.Contains(identity))
            {
                return null;
            }

            bool hasAuthoredCandidates = membersByIdentity.TryGetValue(identity, out List<AuthoredMember>? identityCandidates);

            bool hasBoundContract = method.ContainingType.TypeKind == TypeKind.Interface && boundContracts.Contains(new(identity.Assembly, TypeKey(method.ContainingType)));

            bool hasClosedInternalContract = method.ContainingType is INamedTypeSymbol { TypeKind: TypeKind.Interface } contract && IsClosedInternalType(contract);

            if (!hasAuthoredCandidates && !hasBoundContract && !hasClosedInternalContract)
            {
                nonAuthoredMethods.Add(identity);

                return null;
            }

            int? authoredCompilation = AuthoredCompilationIdentity(definition, consumingCompilation);

            void Cache(AuthoredMember target)
            {
                if (!resolvedMembers.TryGetValue(consumingCompilation, out Dictionary<IAssemblySymbol, Dictionary<string, AuthoredMember>>? exactAssemblyResolutions))
                {
                    resolvedMembers.Add(consumingCompilation, exactAssemblyResolutions = new(ReferenceEqualityComparer.Instance));
                }

                if (!exactAssemblyResolutions.TryGetValue(definition.ContainingAssembly, out Dictionary<string, AuthoredMember>? exactMethodResolutions))
                {
                    exactAssemblyResolutions.Add(definition.ContainingAssembly, exactMethodResolutions = new(StringComparer.Ordinal));
                }

                exactMethodResolutions.Add(identity.Method, target);
            }

            AuthoredMember? BoundImplementation()
            {
                if (method.ContainingType.TypeKind != TypeKind.Interface)
                {
                    return null;
                }

                BoundTypeIdentity contract = TypeIdentity(method.ContainingType, consumingCompilation);

                ServiceBinding[] eligibleBindings = bindings
                    .Where(binding => binding.Contract.Assembly.Equals(contract.Assembly)
                        && binding.Contract.Type == contract.Type
                        && (contract.Compilation is null || binding.Contract.Compilation == contract.Compilation))
                    .ToArray();

                HashSet<GraphMemberIdentity> seen = [];

                List<AuthoredMember> implementations = [];

                foreach (ServiceBinding binding in eligibleBindings)
                {
                    if (binding.Implementation.Compilation is not int implementationCompilation || !membersByType.TryGetValue(new(binding.Implementation.Assembly, implementationCompilation, binding.Implementation.Type), out List<AuthoredMember>? implementationMembers))
                    {
                        continue;
                    }

                    foreach (AuthoredMember candidate in implementationMembers)
                    {
                        bool implements = candidate.Symbol.ContainingType.AllInterfaces
                            .Where(slotType => slotType.ContainingAssembly.Identity.Equals(binding.Contract.Assembly) && TypeKey(slotType) == binding.Contract.Type)
                            .SelectMany(static slotType => slotType.GetMembers())
                            .OfType<IMethodSymbol>()
                            .Any(slot => MethodKey(slot) == MethodKey(method)
                                && candidate.Symbol.ContainingType.FindImplementationForInterfaceMember(slot) is IMethodSymbol implementation
                                && SymbolEqualityComparer.Default.Equals(implementation.OriginalDefinition, candidate.Symbol.OriginalDefinition));

                        if (implements && seen.Add(MemberIdentity(candidate)))
                        {
                            implementations.Add(candidate);
                        }
                    }
                }

                return implementations.Count == 1 ? implementations[0] : null;
            }

            AuthoredMember? ClosedInternalImplementation()
            {
                if (method.ContainingType is not INamedTypeSymbol contract || contract.TypeKind != TypeKind.Interface || !IsClosedInternalType(contract))
                {
                    return null;
                }

                HashSet<GraphMemberIdentity> seen = [];

                List<AuthoredMember> implementations = [];

                foreach (AuthoredMember candidate in AuthoredMembers.Where(candidate => candidate.Symbol.ContainingAssembly.Identity.Equals(contract.ContainingAssembly.Identity)))
                {
                    bool implements = candidate.Symbol.ContainingType.AllInterfaces
                        .Where(slotType => slotType.ContainingAssembly.Identity.Equals(contract.ContainingAssembly.Identity) && TypeKey(slotType) == TypeKey(contract))
                        .SelectMany(static slotType => slotType.GetMembers())
                        .OfType<IMethodSymbol>()
                        .Any(slot => MethodKey(slot) == MethodKey(method)
                            && candidate.Symbol.ContainingType.FindImplementationForInterfaceMember(slot) is IMethodSymbol implementation
                            && SymbolEqualityComparer.Default.Equals(implementation.OriginalDefinition, candidate.Symbol.OriginalDefinition));

                    if (implements && seen.Add(MemberIdentity(candidate)))
                    {
                        implementations.Add(candidate);
                    }
                }

                return implementations.Count == 1 ? implementations[0] : null;
            }

            if (!hasAuthoredCandidates)
            {
                AuthoredMember? implementation = BoundImplementation() ?? ClosedInternalImplementation();

                if (implementation is not null)
                {
                    Cache(implementation);
                }

                return implementation;
            }

            AuthoredMember? exactAuthored = null;

            AuthoredMember? onlyAuthored = null;

            int exactCount = 0;

            int candidateCount = 0;

            foreach (AuthoredMember candidate in identityCandidates!)
            {
                if (authoredCompilation is not null && CompilationIdentity(candidate.Model.Compilation) != authoredCompilation)
                {
                    continue;
                }

                onlyAuthored = candidate;

                candidateCount++;

                if (SymbolEqualityComparer.Default.Equals(candidate.Symbol.OriginalDefinition, definition))
                {
                    exactAuthored = candidate;

                    exactCount++;
                }
            }

            if (exactCount == 1)
            {
                Cache(exactAuthored!);

                return exactAuthored;
            }

            if (authoredCompilation is not null
                && candidateCount == 1)
            {
                Cache(onlyAuthored!);

                return onlyAuthored;
            }

            AuthoredMember? bound = BoundImplementation() ?? ClosedInternalImplementation();

            if (bound is not null)
            {
                Cache(bound);
            }

            return bound;
        }

        private static bool IsExactSqliteCommandFactorySlot(IMethodSymbol method) =>
            method.Name == "CreateCommand"
                && method.MethodKind == MethodKind.Ordinary
                && !method.IsStatic && method.IsVirtual && method.Arity == 0
                && method.Parameters.IsEmpty
                && IsExactFrameworkType(method.ContainingType,
                    "Microsoft.Data.Sqlite.SqliteConnection", typeof(Microsoft.Data.Sqlite.SqliteConnection).Assembly.GetName())
                && IsExactFrameworkType(method.ReturnType,
                    "Microsoft.Data.Sqlite.SqliteCommand", typeof(Microsoft.Data.Sqlite.SqliteConnection).Assembly.GetName());

        private bool TryGetExactSqliteReceiverAllocation(AuthoredMember member, ExpressionSyntax receiver,
            CleanupProvenanceContext proof, out BoundValueSource allocation)
        {
            allocation = null!;

            HashSet<ISymbol> visited = new(SymbolEqualityComparer.Default);

            HashSet<GraphMemberIdentity> factories = [];

            while (proof.RemainingWork > 0)
            {
                // Reuse the stable-local proof, including its conversion check at
                // every initializer. Never consult cast-erasing cleanup caches.
                ExpressionSyntax? value = PerUnitStableLocalValue(member, receiver, receiver.Span.End,
                    proof, new HashSet<ISymbol>(SymbolEqualityComparer.Default), requireBuiltInConversions: true,
                    requireUncapturedSqliteSlots: true);

                if (value is null) return false;

                if (value is BaseObjectCreationExpressionSyntax
                    && member.Model.GetOperation(value) is IObjectCreationOperation { Constructor: not null })
                {
                    allocation = new(member, value);

                    return proof.RemainingWork > 0;
                }

                if (value is AwaitExpressionSyntax awaited)
                {
                    // This is only a selected object-value return hop. Factory
                    // execution, cleanup and admission still use normal traversal.
                    if (proof.RemainingWork-- <= 0
                        || member.Model.GetOperation(awaited) is not IAwaitOperation
                            { Operation: IInvocationOperation configured, Type: { } resultType }
                        || !IsExactFrameworkType(resultType, "Microsoft.Data.Sqlite.SqliteConnection",
                            typeof(Microsoft.Data.Sqlite.SqliteConnection).Assembly.GetName())
                        || !IsExactFrameworkConfigureAwait(configured.TargetMethod)
                        || configured.TargetMethod.ContainingType is not { TypeArguments: [ITypeSymbol taskValue] } task
                        || !IsExactFrameworkType(task, "System.Threading.Tasks.Task`1", typeof(Task).Assembly.GetName())
                        || !SymbolEqualityComparer.Default.Equals(taskValue, resultType)
                        || configured.Arguments is not [{ Value.ConstantValue: { HasValue: true, Value: false } }]
                        || configured.Instance is not IInvocationOperation sourceCall
                        || sourceCall.Syntax is not InvocationExpressionSyntax sourceSyntax
                        || sourceCall.TargetMethod is not { IsStatic: true, MethodKind: MethodKind.Ordinary, Arity: 0 }
                        || sourceCall.TargetMethod.Parameters.Any(static parameter => parameter.RefKind != RefKind.None)
                        || !SymbolEqualityComparer.Default.Equals(sourceCall.Type, task)
                        || Resolve(sourceCall.TargetMethod, member.Model.Compilation) is not { } factory
                        || factory.Symbol is not { IsStatic: true, IsAsync: true, RefKind: RefKind.None }
                        || factory.Syntax is not MethodDeclarationSyntax
                        || !factories.Add(MemberIdentity(factory))) return false;

                    // ReturnedExpressions excludes nested callable bodies. Charge
                    // every candidate and reject exhaustion before using the sole
                    // successful returned expression; catch-dispose/throw adds none.
                    ExpressionSyntax[] returned = PerUnitVisited(ReturnedExpressions(factory.Syntax), proof).ToArray();

                    if (proof.RemainingWork <= 0 || returned is not [ExpressionSyntax successful]) return false;

                    member = BindAdmissionArguments(member, sourceSyntax, factory);

                    receiver = successful;

                    // The next iteration checks the original return and each local
                    // or bound argument with the same built-in-only normalizer.
                    continue;
                }

                ISymbol? symbol = member.Model.GetSymbolInfo(value).Symbol;

                if (symbol is IFieldSymbol field)
                {
                    if (field is not { IsStatic: false, IsReadOnly: true, DeclaredAccessibility: Accessibility.Private }
                        || member.Model.GetOperation(value) is not IFieldReferenceOperation { Instance: IInstanceReferenceOperation }
                        || !SymbolEqualityComparer.Default.Equals(field.ContainingType, member.Symbol.ContainingType)) return false;
                }
                else if (symbol is not IParameterSymbol { RefKind: RefKind.None }
                    || !SqliteValueSlotHasNoLexicalCapture(member, symbol, proof)) return false;

                // These existing bindings retain the actual constructor RHS or
                // caller argument. Unsupported/unbound fields and factories refuse.
                if (!visited.Add(symbol)
                    || !IsStableAcrossAdmissionCleanupBackEdges(member, value, symbol)
                    || !TryResolveStableBoundValueSource(member, value, out BoundValueSource? source)
                    || source is null) return false;

                member = source.Caller;

                receiver = source.Expression;
            }

            return false;
        }

        private static bool SqliteValueSlotHasNoLexicalCapture(AuthoredMember member, ISymbol slot,
            CleanupProvenanceContext proof)
        {
            // A constructor/heap can store a callback without an invocation argument
            // exposing its mutation. Refuse capture rather than interpret that owner.
            foreach (SyntaxNode callable in PerUnitVisited(member.Syntax.DescendantNodes()
                .Where(static node => node is AnonymousFunctionExpressionSyntax or LocalFunctionStatementSyntax), proof))
            {
                if (SyntaxReferencesSymbol(member.Model, callable, slot)) return false;
            }

            return proof.RemainingWork > 0;
        }

        private bool IsReviewedExactSqliteCommandFactory(IMethodSymbol method, SyntaxNode? node, AuthoredMember? member)
        {
            if (member is null || node is not InvocationExpressionSyntax call
                || member.Model.GetOperation(call) is not IInvocationOperation invocation
                || !SymbolEqualityComparer.Default.Equals(invocation.TargetMethod.OriginalDefinition, method.OriginalDefinition)) return false;

            // A base invocation selects the metadata body directly; it cannot
            // dispatch to the source subclass's override.
            if (!invocation.IsVirtual) return true;

            // SqliteSealedByUse: no subclass of SqliteConnection exists in the analysed universe, so the
            // virtual slot selects the reviewed framework body for a receiver of any provenance.
            if (SqliteSealedByUse) return true;

            CleanupProvenanceContext proof = new();

            return AdmissionReceiver(member, call) is { } receiver
                && TryGetExactSqliteReceiverAllocation(member, receiver, proof, out BoundValueSource allocation)
                && IsExactFrameworkType(allocation.Caller.Model.GetTypeInfo(allocation.Expression).Type,
                    "Microsoft.Data.Sqlite.SqliteConnection", typeof(Microsoft.Data.Sqlite.SqliteConnection).Assembly.GetName());
        }

        private AuthoredMember? ResolveExactSqliteCommandFactoryOverride(
            IMethodSymbol method,
            AuthoredMember member,
            SyntaxNode node,
            CleanupProvenanceContext? existingProof)
        {
            if (!IsExactSqliteCommandFactorySlot(method)
                || node is not InvocationExpressionSyntax call
                || member.Model.GetOperation(call) is not IInvocationOperation { IsVirtual: true } invocation
                || !SymbolEqualityComparer.Default.Equals(invocation.TargetMethod.OriginalDefinition, method.OriginalDefinition)
                || AdmissionReceiver(member, call) is not { } receiver)
            {
                return null;
            }

            CleanupProvenanceContext proof = existingProof ?? new();

            if (!TryGetExactSqliteReceiverAllocation(member, receiver, proof, out BoundValueSource allocation)
                || allocation.Caller.Model.GetTypeInfo(allocation.Expression).Type is not INamedTypeSymbol
                    { TypeKind: TypeKind.Class, IsAbstract: false, IsSealed: true } concrete) return null;

            for (INamedTypeSymbol? current = concrete; current is not null; current = current.BaseType)
            {
                if (proof.RemainingWork-- <= 0) return null;

                foreach (IMethodSymbol candidate in current.GetMembers(method.Name).OfType<IMethodSymbol>())
                {
                    if (proof.RemainingWork-- <= 0) return null;

                    for (IMethodSymbol? overridden = candidate; overridden is not null; overridden = overridden.OverriddenMethod)
                    {
                        if (proof.RemainingWork-- <= 0) return null;

                        if (!SymbolEqualityComparer.Default.Equals(overridden.OriginalDefinition, method.OriginalDefinition)) continue;

                        if (Resolve(candidate, member.Model.Compilation) is not { } target
                            || !SameBoundType(target.Symbol.ContainingType, target.Model.Compilation,
                                concrete, allocation.Caller.Model.Compilation)) return null;

                        return BindCleanupInvocationContext(member, call, target, proof, selectedReceiver: allocation);
                    }
                }
            }

            return null;
        }

        private AuthoredMember? ResolveInvocationTarget(IMethodSymbol method, AuthoredMember member, SyntaxNode node,
            CleanupProvenanceContext? cleanupProof = null)
        {
            if (member.OrdinaryScopedHolder is not null && method.ContainingType.TypeKind == TypeKind.Interface
                && node is InvocationExpressionSyntax scopedCall
                && TryScopedLeaseInvocationTarget(method, member, scopedCall,
                    cleanupProof ?? new CleanupProvenanceContext()) is { } scopedTarget) return scopedTarget;

            if (ResolveExactSqliteCommandFactoryOverride(method, member, node, cleanupProof) is { } exactOverride)
            {
                return exactOverride;
            }

            if (method.ContainingType.TypeKind == TypeKind.Interface
                && node is InvocationExpressionSyntax call
                && AdmissionReceiver(member, call) is { } receiver
                && (ConcreteType(member, receiver)
                    ?? ExactOptionalDiDefaultCleanupReceiverType(
                        member,
                        receiver)) is
                    { } concrete)
            {
                IMethodSymbol[] implementations = concrete.AllInterfaces
                    .Where(contract => contract.ContainingAssembly.Identity.Equals(method.ContainingAssembly.Identity) && TypeKey(contract) == TypeKey(method.ContainingType))
                    .SelectMany(static contract => contract.GetMembers())
                    .OfType<IMethodSymbol>()
                    .Where(slot => MethodKey(slot) == MethodKey(method))
                    .Select(slot => concrete.FindImplementationForInterfaceMember(slot))
                    .OfType<IMethodSymbol>()
                    .ToArray();

                if (implementations is [IMethodSymbol implementation] && Resolve(implementation, member.Model.Compilation) is { } target)
                {
                    return target;
                }
            }

            // An authored default is only effective when the exact concrete receiver or each
            // proven registration inherits that slot. Its body alone does not close dispatch.
            return IsDefaultInterfaceSlot(method) ? null : Resolve(method, member.Model.Compilation);
        }

        private static bool IsDefaultInterfaceSlot(IMethodSymbol method) =>
            method.ContainingType.TypeKind == TypeKind.Interface && !method.IsAbstract && !method.IsStatic && method.IsVirtual;

        private bool HasIncompleteDefaultInterfaceBinding(IMethodSymbol method, Compilation consumingCompilation) =>
            IsDefaultInterfaceSlot(method) && incompleteInterfaceBindings.Contains(TypeIdentity(method.ContainingType, consumingCompilation));

        private ITypeSymbol? ExactOptionalDiDefaultCleanupReceiverType(
            AuthoredMember member,
            ExpressionSyntax receiver)
        {
            receiver = StripTransparentExpression(receiver);

            if (member.Model.GetSymbolInfo(receiver).Symbol is not IFieldSymbol
                {
                    DeclaredAccessibility: Accessibility.Private,
                    IsReadOnly: true,
                    IsStatic: false,
                    ContainingType.IsSealed: true,
                } field
                || receiver is not (IdentifierNameSyntax
                    or MemberAccessExpressionSyntax
                    {
                        Expression: ThisExpressionSyntax,
                    })
                || ExactReadOnlyFieldValues(member, receiver, field) is not
                    [BoundValueSource fieldValue]
                || StripTransparentExpression(fieldValue.Expression) is not
                    BinaryExpressionSyntax coalescing
                || !coalescing.IsKind(SyntaxKind.CoalesceExpression)
                || fieldValue.Caller.Model.GetSymbolInfo(
                    StripTransparentExpression(coalescing.Left)).Symbol is not
                    IParameterSymbol optionalDependency
                || StripTransparentExpression(coalescing.Right) is not
                    BaseObjectCreationExpressionSyntax
                || !TryExactAbsentOptionalDiDefault(
                    fieldValue.Caller,
                    optionalDependency,
                    out _))
            {
                return null;
            }

            CleanupProvenance provenance = CleanupProvenanceOf(
                member,
                receiver,
                new CleanupProvenanceContext());

            return provenance is
                {
                    Complete: true,
                    HasAuthoredSource: true,
                    Candidates: [CleanupTypeCandidate exact],
                }
                    ? exact.Type
                    : null;
        }

        private AuthoredMember[] ResolveBoundImplementations(
            IMethodSymbol method,
            Compilation consumingCompilation)
        {
            if (method.ContainingType.TypeKind != TypeKind.Interface)
            {
                return [];
            }

            BoundTypeIdentity contract = TypeIdentity(method.ContainingType, consumingCompilation);

            if (contract.Compilation is null)
            {
                return [];
            }

            ServiceBinding[] eligibleBindings = bindings
                .Where(binding => binding.Contract.Assembly.Equals(contract.Assembly)
                    && binding.Contract.Type == contract.Type
                    && binding.Contract.Compilation == contract.Compilation)
                .ToArray();

            HashSet<GraphMemberIdentity> seen = [];

            List<AuthoredMember> implementations = [];

            foreach (ServiceBinding binding in eligibleBindings)
            {
                if (binding.Implementation.Compilation is null
                    || !boundImplementationTypes.TryGetValue(binding.Implementation, out INamedTypeSymbol? concrete))
                {
                    continue;
                }

                foreach (IMethodSymbol slot in concrete.AllInterfaces
                    .Where(slotType => slotType.ContainingAssembly.Identity.Equals(contract.Assembly)
                        && TypeKey(slotType) == contract.Type)
                    .SelectMany(static slotType => slotType.GetMembers())
                    .OfType<IMethodSymbol>()
                    .Where(slot => MethodKey(slot) == MethodKey(method)))
                {
                    if (concrete.FindImplementationForInterfaceMember(slot) is IMethodSymbol implementation
                        && Resolve(implementation, consumingCompilation) is { } candidate
                        && seen.Add(MemberIdentity(candidate)))
                    {
                        implementations.Add(candidate);
                    }
                }
            }

            return implementations
                .OrderBy(static implementation => TypeKey(implementation.Symbol.ContainingType), StringComparer.Ordinal)
                .ThenBy(static implementation => MethodKey(implementation.Symbol), StringComparer.Ordinal)
                .ToArray();
        }

        private AuthoredMember[] ResolveStrategyTargets(IMethodSymbol method)
        {
            if (Normalize(method) == "RetroDownfall.Arcanum.Infrastructure.Data.Schema.IGrimoireSchemaBackfill.AdvanceBatchAsync")
            {
                return AuthoredMembers.Where(candidate => SchemaBackfillStrategies.Contains(TypeKey(candidate.Symbol.ContainingType)) && candidate.Symbol.ContainingType.AllInterfaces
                        .Where(contract => contract.ContainingAssembly.Identity.Equals(method.ContainingAssembly.Identity) && TypeKey(contract) == TypeKey(method.ContainingType))
                        .SelectMany(static contract => contract.GetMembers())
                        .OfType<IMethodSymbol>()
                        .Any(slot => MethodKey(slot) == MethodKey(method) && candidate.Symbol.ContainingType.FindImplementationForInterfaceMember(slot) is IMethodSymbol implementation && SymbolEqualityComparer.Default.Equals(implementation.OriginalDefinition, candidate.Symbol.OriginalDefinition)))
                    .OrderBy(static candidate => TypeKey(candidate.Symbol.ContainingType), StringComparer.Ordinal)
                    .ToArray();
            }

            return TypeKey(method.ContainingType) == "RetroDownfall.Arcanum.Infrastructure.GrimoireTransitions.IGrimoireOfflineTransitionHandler"
                ? ResolveClosedProductionRegistryTargets(method)
                : [];
        }

        private AuthoredMember[] ResolveReviewedClosedDispatchTargets(
            IMethodSymbol method,
            SyntaxNode node,
            AuthoredMember member)
        {
            string contractMethod = TypeKey(method.ContainingType) + "." + method.Name;

            if (method.ContainingType.TypeKind != TypeKind.Interface
                || !ReviewedClosedDispatchTargets.TryGetValue(contractMethod, out IReadOnlySet<string>? expectedTypes))
            {
                return [];
            }

            AuthoredMember[] targets = AuthoredMembers
                .Where(candidate => candidate.Symbol.ContainingType.AllInterfaces
                    .Where(contract => contract.ContainingAssembly.Identity.Equals(method.ContainingAssembly.Identity)
                        && TypeKey(contract) == TypeKey(method.ContainingType))
                    .SelectMany(static contract => contract.GetMembers())
                    .OfType<IMethodSymbol>()
                    .Any(slot => MethodKey(slot) == MethodKey(method)
                        && candidate.Symbol.ContainingType.FindImplementationForInterfaceMember(slot) is IMethodSymbol implementation
                        && SymbolEqualityComparer.Default.Equals(implementation.OriginalDefinition, candidate.Symbol.OriginalDefinition)))
                .DistinctBy(MemberIdentity)
                .OrderBy(static target => TypeKey(target.Symbol.ContainingType), StringComparer.Ordinal)
                .ThenBy(static target => MethodKey(target.Symbol), StringComparer.Ordinal)
                .ToArray();

            string[] observedTypes = targets
                .Select(static target => TypeKey(target.Symbol.ContainingType))
                .Distinct(StringComparer.Ordinal)
                .Order(StringComparer.Ordinal)
                .ToArray();

            if (!new HashSet<string>(expectedTypes, StringComparer.Ordinal).SetEquals(observedTypes))
            {
                diagnostics.Add(new(
                    "HOSTED_CLOSED_DISPATCH_CHANGED",
                    Location(node),
                    contractMethod + "; expected exactly [" + string.Join(", ", expectedTypes.Order(StringComparer.Ordinal)) + "] but found [" + string.Join(", ", observedTypes) + "]."));

                return [];
            }

            if (node is not InvocationExpressionSyntax call
                || AdmissionReceiver(member, call) is not { } receiver)
            {
                return targets;
            }

            CleanupValueFlow receiverValues = CleanupValueFlowOf(
                member,
                receiver,
                new CleanupProvenanceContext());

            if ((!receiverValues.Complete
                    && !IsFailureGuardedSuccessfulValueAccess(
                        member,
                        receiver))
                || receiverValues.Values.Count == 0)
            {
                return targets;
            }

            List<(INamedTypeSymbol Type, Compilation Compilation)> exactTypes = [];

            foreach (BoundValueSource value in receiverValues.Values)
            {
                ExpressionSyntax expression = ExactNonThrowingValue(
                    value.Expression);

                ITypeSymbol? valueType = value.Caller.Model
                    .GetTypeInfo(expression).Type;

                if (valueType is not INamedTypeSymbol named
                    || named.TypeKind is not TypeKind.Struct
                        && (!named.IsSealed || named.IsAbstract))
                {
                    return targets;
                }

                exactTypes.Add((named, value.Caller.Model.Compilation));
            }

            AuthoredMember[] reachableTargets = targets
                .Where(target => exactTypes.Any(exact => SameBoundType(
                    exact.Type,
                    exact.Compilation,
                    target.Symbol.ContainingType,
                    target.Model.Compilation)))
                .ToArray();

            return reachableTargets.Length == 0
                ? targets
                : reachableTargets;
        }

        private AuthoredMember[] ResolveClosedProductionRegistryTargets(IMethodSymbol method)
        {
            if (method.ContainingType is not INamedTypeSymbol
                {
                    TypeKind: TypeKind.Interface,
                    DeclaredAccessibility: Accessibility.Internal or Accessibility.Private,
                })
            {
                return [];
            }

            var candidates = semanticModels.SelectMany(pair => pair.Key.GetRoot()
                    .DescendantNodes()
                    .OfType<PropertyDeclarationSyntax>()
                    .Select(property => (
                        Property: property,
                        Model: pair.Value,
                        Symbol: pair.Value.GetDeclaredSymbol(property))))
                .Where(candidate => candidate.Symbol is
                {
                    Name: "Production",
                    IsStatic: true,
                    SetMethod: null,
                }
                    && candidate.Property.Initializer?.Value is not null
                    && candidate.Symbol.ContainingAssembly.Identity.Equals(
                        method.ContainingAssembly.Identity))
                .ToArray();

            if (candidates is not [var production]
                || production.Symbol is not IPropertySymbol productionSymbol
                || productionSymbol.ContainingType is not
                {
                    IsSealed: true,
                    IsAbstract: false,
                } registryType
                || production.Property.Initializer?.Value is not InvocationExpressionSyntax valueCall
                || valueCall.ArgumentList.Arguments is not [ArgumentSyntax valueArgument]
                || valueArgument.Expression is not InvocationExpressionSyntax createCall
                || createCall.ArgumentList.Arguments is not [ArgumentSyntax createArgument]
                || createArgument.Expression is not CollectionExpressionSyntax collection
                || production.Model.GetSymbolInfo(valueCall).Symbol is not IMethodSymbol
                {
                    Name: "Value",
                    IsStatic: true,
                } valueMethod
                || production.Model.GetSymbolInfo(createCall).Symbol is not IMethodSymbol
                {
                    Name: "Create",
                    IsStatic: true,
                } createMethod
                || !SymbolEqualityComparer.Default.Equals(
                    valueMethod.ContainingType,
                    registryType)
                || !SymbolEqualityComparer.Default.Equals(
                    createMethod.ContainingType,
                    registryType)
                || registryType.InstanceConstructors.Any(static constructor =>
                    !constructor.IsImplicitlyDeclared
                    && constructor.DeclaredAccessibility != Accessibility.Private))
            {
                return [];
            }

            InvocationExpressionSyntax[] createCalls = invocations
                .Where(candidate => candidate.Model.GetSymbolInfo(candidate.Call).Symbol is IMethodSymbol target
                    && Identity(target) == Identity(createMethod))
                .Select(static candidate => candidate.Call)
                .ToArray();

            if (createCalls is not [InvocationExpressionSyntax onlyCreate]
                || onlyCreate != createCall
                || Resolve(createMethod, production.Model.Compilation) is not { } createTarget)
            {
                return [];
            }

            bool ContainsContract(ITypeSymbol type)
            {
                if (type.ContainingAssembly is { } containingAssembly
                    && containingAssembly.Identity.Equals(method.ContainingAssembly.Identity)
                    && TypeKey(type) == TypeKey(method.ContainingType))
                {
                    return true;
                }

                return type is INamedTypeSymbol named
                    && named.TypeArguments.Any(ContainsContract);
            }

            IFieldSymbol[] handlerFields = registryType.GetMembers()
                .OfType<IFieldSymbol>()
                .Where(field => !field.IsImplicitlyDeclared && ContainsContract(field.Type))
                .ToArray();

            if (handlerFields.Any(static field => !field.IsReadOnly)
                || AuthoredMembers.Any(owner => SymbolEqualityComparer.Default.Equals(
                        owner.Symbol.ContainingType,
                        registryType)
                    && owner.Symbol.MethodKind is not (MethodKind.Constructor or MethodKind.StaticConstructor)
                    && owner.Syntax.DescendantNodesAndSelf()
                        .OfType<AssignmentExpressionSyntax>()
                        .Any(assignment => owner.Model.GetSymbolInfo(assignment.Left).Symbol is IFieldSymbol field
                            && handlerFields.Any(candidate => SymbolEqualityComparer.Default.Equals(candidate, field))))
                || createTarget.Syntax.DescendantNodesAndSelf()
                    .OfType<InvocationExpressionSyntax>()
                    .Any(call => createTarget.Model.GetTypeInfo(call).Type is { } returnType
                        && ContainsContract(returnType))
                || createTarget.Syntax.DescendantNodesAndSelf()
                    .OfType<BaseObjectCreationExpressionSyntax>()
                    .Any(creation => createTarget.Model.GetTypeInfo(creation).Type is INamedTypeSymbol created
                        && created.AllInterfaces.Any(ContainsContract)))
            {
                return [];
            }

            BaseObjectCreationExpressionSyntax[] registryCreations = objectCreations
                .Where(candidate => candidate.Model.GetSymbolInfo(candidate.Creation).Symbol is IMethodSymbol constructor
                    && SymbolEqualityComparer.Default.Equals(constructor.ContainingType, registryType))
                .Select(static candidate => candidate.Creation)
                .ToArray();

            if (registryCreations.Length == 0
                || registryCreations.Any(creation => creation.SyntaxTree != createTarget.Syntax.SyntaxTree
                    || !createTarget.Syntax.Span.Contains(creation.Span)))
            {
                return [];
            }

            List<AuthoredMember> targets = [];

            foreach (CollectionElementSyntax element in collection.Elements)
            {
                if (element is not ExpressionElementSyntax
                    {
                        Expression: BaseObjectCreationExpressionSyntax creation,
                    }
                    || production.Model.GetTypeInfo(creation).Type is not INamedTypeSymbol
                    {
                        IsSealed: true,
                        IsAbstract: false,
                    } concrete)
                {
                    return [];
                }

                IMethodSymbol[] implementations = concrete.AllInterfaces
                    .Where(contract => contract.ContainingAssembly.Identity.Equals(
                            method.ContainingAssembly.Identity)
                        && TypeKey(contract) == TypeKey(method.ContainingType))
                    .SelectMany(static contract => contract.GetMembers())
                    .OfType<IMethodSymbol>()
                    .Where(slot => MethodKey(slot) == MethodKey(method))
                    .Select(slot => concrete.FindImplementationForInterfaceMember(slot))
                    .OfType<IMethodSymbol>()
                    .ToArray();

                if (implementations is not [IMethodSymbol implementation]
                    || Resolve(implementation, production.Model.Compilation) is not { } target)
                {
                    return [];
                }

                targets.Add(target);
            }

            return targets
                .DistinctBy(MemberIdentity)
                .OrderBy(static target => TypeKey(target.Symbol.ContainingType), StringComparer.Ordinal)
                .ThenBy(static target => MethodKey(target.Symbol), StringComparer.Ordinal)
                .ToArray();
        }

        private static ITypeSymbol? ConcreteType(AuthoredMember member, ExpressionSyntax expression)
        {
            ISymbol? symbol = member.Model.GetSymbolInfo(expression).Symbol;

            if (symbol is not null && member.ConcreteBindings?.TryGetValue(symbol, out ITypeSymbol? bound) == true)
            {
                return bound;
            }

            if (expression is BaseObjectCreationExpressionSyntax
                && member.Model.GetTypeInfo(expression).Type is
                    INamedTypeSymbol created)
            {
                return created;
            }

            return member.Model.GetTypeInfo(expression).Type is
                INamedTypeSymbol
            {
                TypeKind: TypeKind.Struct,
            } valueType
                    ? valueType
                    : member.Model.GetTypeInfo(expression).Type is
                        INamedTypeSymbol
                    {
                        TypeKind: TypeKind.Class,
                        IsAbstract: false,
                        IsSealed: true,
                    } sealedType
                            ? sealedType
                            : null;
        }

        private RecoveryMatrix ResolveRecoveryMatrix(SyntaxNode anchor)
        {
            if (recoveryMatrixResolved)
            {
                return recoveryMatrix!;
            }

            recoveryMatrixResolved = true;

            recoveryMatrix = recoveryMatrixFacts ??= BuildRecoveryMatrix();

            foreach (string failure in recoveryMatrix.Failures)
            {
                diagnostics.Add(new("HOSTED_RECOVERY_MATRIX_UNPROVEN", Location(anchor), failure));
            }

            return recoveryMatrix;
        }

        private RecoveryMatrix BuildRecoveryMatrix()
        {
            List<string> failures = [];

            RecoveryDescriptor[] descriptors = objectCreations
                .Where(candidate => candidate.Model.GetTypeInfo(candidate.Creation).Type is { } type
                    && TypeKey(type)
                        == "RetroDownfall.Arcanum.Core.Operations.LongRunningOperationRecoveryDescriptor"
                    && candidate.Creation.Ancestors()
                        .OfType<TypeDeclarationSyntax>()
                        .FirstOrDefault() is { } owner
                    && candidate.Model.GetDeclaredSymbol(owner) is INamedTypeSymbol ownerType
                    && TypeKey(ownerType)
                        == "RetroDownfall.Arcanum.Core.Operations.LongRunningOperationRecoveryRegistry")
                .Select(candidate =>
                {
                    if (candidate.Model.GetOperation(candidate.Creation) is not IObjectCreationOperation creation)
                    {
                        return null;
                    }

                    object? Argument(string name) => creation.Arguments
                        .SingleOrDefault(argument => argument.Parameter?.Name == name)
                        ?.Value.ConstantValue is
                    {
                        HasValue: true,
                    } value
                        ? value.Value
                        : null;

                    return Argument("Kind") is string kind
                        && Argument("MinCheckpointVersion") is int minimum
                        && Argument("MaxCheckpointVersion") is int maximum
                        ? new RecoveryDescriptor(kind, minimum, maximum)
                        : null;
                })
                .OfType<RecoveryDescriptor>()
                .ToArray();

            if (descriptors.Length == 0
                || descriptors.Any(static descriptor =>
                    descriptor.MinimumCheckpointVersion < 0
                    || descriptor.MaximumCheckpointVersion
                        < descriptor.MinimumCheckpointVersion)
                || descriptors.Select(static descriptor => descriptor.Kind)
                    .Distinct(StringComparer.Ordinal)
                    .Count() != descriptors.Length)
            {
                failures.Add("The recovery registry must expose one valid descriptor per durable kind.");
            }

            AuthoredMember[] classifiers = AuthoredMembers
                .Where(static member => member.Symbol.Name == "Classify")
                .Where(member => TypeKey(member.Symbol.ContainingType)
                    == "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationRecoveryAdmission")
                .ToArray();

            SwitchExpressionSyntax? classification = classifiers is [AuthoredMember classifier]
                ? classifier.Syntax.DescendantNodesAndSelf()
                    .OfType<SwitchExpressionSyntax>()
                    .SingleOrDefault(selection => selection.GoverningExpression is TupleExpressionSyntax)
                : null;

            if (classifiers is not [AuthoredMember exactClassifier]
                || classification?.GoverningExpression is not TupleExpressionSyntax
                {
                    Arguments: [ArgumentSyntax kindArgument, ArgumentSyntax versionArgument],
                }
                || exactClassifier.Model.GetSymbolInfo(kindArgument.Expression).Symbol is not
                    IPropertySymbol { Name: "Kind" } kindProperty
                || exactClassifier.Model.GetSymbolInfo(versionArgument.Expression).Symbol is not
                    IPropertySymbol { Name: "CheckpointVersion" } versionProperty
                || kindProperty.ContainingType is null
                || versionProperty.ContainingType is null
                || !SymbolEqualityComparer.Default.Equals(
                    kindProperty.ContainingType,
                    versionProperty.ContainingType))
            {
                failures.Add("Classify must switch exactly on one operation's (Kind, CheckpointVersion) tuple.");
            }

            Dictionary<(string Kind, int Version), RecoveryDisposition> explicitRows = [];

            bool hasUnsupportedDefault = false;

            if (classification is not null && classifiers is [AuthoredMember classifierMember])
            {
                foreach (SwitchExpressionArmSyntax arm in classification.Arms)
                {
                    RecoveryDisposition? disposition = RecoveryDispositionOf(
                        classifierMember,
                        arm.Expression);

                    if (arm.WhenClause is not null || disposition is null)
                    {
                        failures.Add("Every recovery classification arm must be unconditional and resolve to one known disposition.");

                        continue;
                    }

                    if (arm.Pattern is DiscardPatternSyntax)
                    {
                        hasUnsupportedDefault = disposition
                            is RecoveryDisposition.Unsupported;

                        continue;
                    }

                    if (arm.Pattern is not RecursivePatternSyntax
                        {
                            PositionalPatternClause.Subpatterns:
                            [SubpatternSyntax kindPattern, SubpatternSyntax versionPattern],
                        })
                    {
                        failures.Add("Every non-default classification arm must be one exact kind/version tuple pattern.");

                        continue;
                    }

                    string[] kinds = RecoveryPatternConstants<string>(
                        classifierMember,
                        kindPattern.Pattern);

                    int[] versions = RecoveryPatternConstants<int>(
                        classifierMember,
                        versionPattern.Pattern);

                    if (kinds.Length == 0 || versions.Length == 0)
                    {
                        failures.Add("Every classification tuple must use compile-time kind and checkpoint constants.");

                        continue;
                    }

                    foreach (string kind in kinds)
                    {
                        foreach (int version in versions)
                        {
                            if (!explicitRows.TryAdd((kind, version), disposition.Value))
                            {
                                failures.Add($"Recovery tuple {kind} V{version} is classified more than once.");
                            }
                        }
                    }
                }
            }

            if (!hasUnsupportedDefault)
            {
                failures.Add("The recovery classifier must fail closed with an unsupported default arm.");
            }

            HashSet<(string Kind, int Version)> registeredRows = descriptors
                .SelectMany(static descriptor => Enumerable.Range(
                        descriptor.MinimumCheckpointVersion,
                        descriptor.MaximumCheckpointVersion
                            - descriptor.MinimumCheckpointVersion
                            + 1)
                    .Select(version => (descriptor.Kind, version)))
                .ToHashSet();

            foreach ((string kind, int version) in explicitRows.Keys)
            {
                if (!registeredRows.Contains((kind, version)))
                {
                    failures.Add($"Recovery classification names unregistered tuple {kind} V{version}.");
                }
            }

            RecoveryTuple[] tuples = registeredRows
                .OrderBy(static row => row.Kind, StringComparer.Ordinal)
                .ThenBy(static row => row.Version)
                .Select(row => new RecoveryTuple(
                    row.Kind,
                    row.Version,
                    explicitRows.GetValueOrDefault(
                        row,
                        RecoveryDisposition.Unsupported)))
                .ToArray();

            return new(
                descriptors,
                tuples,
                failures.Count == 0,
                failures.Distinct(StringComparer.Ordinal).ToArray());
        }

        private RecoveryDisposition? RecoveryDispositionOf(
            AuthoredMember classifier,
            ExpressionSyntax expression)
        {
            if (classifier.Model.GetSymbolInfo(expression).Symbol is IFieldSymbol field)
            {
                return field.Name switch
                {
                    "OrdinaryDbOnly" => RecoveryDisposition.OrdinaryDbOnly,
                    "OrdinaryExternalEffect" => RecoveryDisposition.OrdinaryExternalEffect,
                    "OrdinaryPerUnitExternalEffect" when IsExactPerUnitDispositionField(classifier, field) => RecoveryDisposition.OrdinaryPerUnitExternalEffect,
                    "UnsupportedCheckpointVersion" => RecoveryDisposition.Unsupported,
                    _ => null,
                };
            }

            return expression is InvocationExpressionSyntax call
                && classifier.Model.GetSymbolInfo(call).Symbol is IMethodSymbol
                {
                    Name: "OwnerBoundKind",
                }
                ? RecoveryDisposition.OwnerBound
                : null;
        }

        private static T[] RecoveryPatternConstants<T>(
            AuthoredMember member,
            PatternSyntax pattern)
        {
            if (pattern is BinaryPatternSyntax binary
                && binary.IsKind(SyntaxKind.OrPattern))
            {
                return
                [
                    .. RecoveryPatternConstants<T>(member, binary.Left),
                    .. RecoveryPatternConstants<T>(member, binary.Right),
                ];
            }

            return pattern is ConstantPatternSyntax constant
                && member.Model.GetConstantValue(constant.Expression) is
                {
                    HasValue: true,
                    Value: T value,
                }
                ? [value]
                : [];
        }

        private IReadOnlyDictionary<InvocationExpressionSyntax, RecoveryCompositionKind>
            RecoveryRegistrationCompositions()
        {
            PreparePerUnitRecoveryCompositionSources(recoveryMatrixFacts ??= BuildRecoveryMatrix());

            if (recoveryRegistrationCompositions is not null)
            {
                return recoveryRegistrationCompositions;
            }

            recoveryRegistrationCompositions = new(
                ReferenceEqualityComparer.Instance);

            Queue<(AuthoredMember Member, ISymbol Services, RecoveryCompositionKind Kind, bool MustExecute, bool ExactlyOnce)>
                pending = [];

            HashSet<(GraphMemberIdentity Member, int Parameter, RecoveryCompositionKind Kind, bool MustExecute, bool ExactlyOnce)>
                visited = [];

            Dictionary<(GraphMemberIdentity Member, int Parameter, RecoveryCompositionKind Kind),
                HashSet<(GraphMemberIdentity Caller, int Call)>> incomingCalls = [];

            Dictionary<(RecoveryCompositionKind Kind, BoundTypeIdentity Service),
                HashSet<InvocationExpressionSyntax>> concreteRegistrations = [];

            void Seed(
                Func<AuthoredMember, bool> predicate,
                RecoveryCompositionKind kind,
                bool requireUnique)
            {
                AuthoredMember[] roots = AuthoredMembers
                    .Where(predicate)
                    .Where(member => member.Symbol.Parameters.Any(parameter =>
                        IsExactFrameworkType(
                            parameter.Type,
                            "Microsoft.Extensions.DependencyInjection.IServiceCollection",
                            typeof(Microsoft.Extensions.DependencyInjection.IServiceCollection)
                                .Assembly.GetName())))
                    .ToArray();

                if (requireUnique
                    && (roots.Length == 0
                        || roots.GroupBy(static root => root.Model.Compilation)
                            .Any(static group => group.Count() != 1)))
                {
                    return;
                }

                foreach (AuthoredMember root in roots)
                {
                    foreach (IParameterSymbol services in root.Symbol.Parameters.Where(
                        parameter => IsExactFrameworkType(
                            parameter.Type,
                            "Microsoft.Extensions.DependencyInjection.IServiceCollection",
                            typeof(Microsoft.Extensions.DependencyInjection.IServiceCollection)
                                .Assembly.GetName())))
                    {
                        var rootKey = (
                            MemberIdentity(root),
                            services.Ordinal,
                            kind);

                        incomingCalls[rootKey] =
                        [
                            (MemberIdentity(root), int.MinValue),
                        ];

                        pending.Enqueue((root, services, kind, true, true));
                    }
                }
            }

            Seed(
                member => member.Symbol.Name == "Configure"
                    && TypeKey(member.Symbol.ContainingType)
                        == "RetroDownfall.Arcanum.Infrastructure.DependencyInjection.StoppedComposition"
                    && AuthoredMembers.Any(candidate =>
                        ReferenceEquals(
                            candidate.Model.Compilation,
                            member.Model.Compilation)
                        && candidate.Symbol.Name == "Configure"
                        && TypeKey(candidate.Symbol.ContainingType)
                            == "Composition"),
                RecoveryCompositionKind.StoppedHost,
                requireUnique: true);

            Seed(
                static member => member.Symbol.Name == "AddArcanumApiServices"
                    && TypeKey(member.Symbol.ContainingType)
                        == "RetroDownfall.Arcanum.Api.ApiBootstrapper",
                RecoveryCompositionKind.Serving,
                requireUnique: true);

            Seed(
                static member => member.Symbol.Name == "AddArcanumCliClientStack"
                    && TypeKey(member.Symbol.ContainingType)
                        == "RetroDownfall.Arcanum.Infrastructure.DependencyInjection.ServiceCollectionExtensions",
                RecoveryCompositionKind.StoppedHost,
                requireUnique: true);

            while (pending.TryDequeue(out var state))
            {
                int parameter = state.Services is IParameterSymbol formal
                    ? formal.Ordinal
                    : -1;

                if (!visited.Add((
                        MemberIdentity(state.Member),
                        parameter,
                        state.Kind,
                        state.MustExecute,
                        state.ExactlyOnce)))
                {
                    continue;
                }

                InvocationExpressionSyntax[] compositionCalls = state.Member.Syntax
                    .DescendantNodes(node => node == state.Member.Syntax
                        || node is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .OfType<InvocationExpressionSyntax>()
                    .ToArray();

                IReadOnlySet<ISymbol> collectionAliases =
                    RecoveryCollectionAliases(state.Member, state.Services);

                if (UnsafeRecoveryCollectionAssignment(
                        state.Member,
                        collectionAliases)
                    || RecoveryCollectionIsCaptured(
                        state.Member,
                        collectionAliases)
                    || UnsafeRecoveryCollectionObjectEscape(
                        state.Member,
                        collectionAliases))
                {
                    invalidRecoveryComposition |= state.Kind;
                }

                foreach (InvocationExpressionSyntax call in compositionCalls)
                {
                    if (state.Member.Model.GetSymbolInfo(call).Symbol is not
                        IMethodSymbol method)
                    {
                        continue;
                    }

                    if (!InvocationCanExecuteFromEntry(state.Member, call))
                    {
                        continue;
                    }

                    bool mustExecute = state.MustExecute
                        && InvocationMustExecuteFromEntry(state.Member, call);

                    bool exactlyOnce = state.ExactlyOnce
                        && !InvocationMayRepeat(state.Member, call);

                    AuthoredMember? target = ResolveInvocationTarget(
                        method,
                        state.Member,
                        call);

                    (ExpressionSyntax Expression, IParameterSymbol? Parameter, RefKind RefKind)[]
                        callArguments = AdmissionArguments(state.Member, call)
                        .ToArray();

                    bool authoredCollectionForwardingIsInspectable = target is not null
                        && callArguments.Any(argument =>
                            ExpressionUsesRecoveryCollection(
                                state.Member,
                                argument.Expression,
                                collectionAliases))
                        && callArguments
                            .Where(argument => ExpressionUsesRecoveryCollection(
                                state.Member,
                                argument.Expression,
                                collectionAliases))
                            .All(argument =>
                                argument.Parameter is { } targetParameter
                                && argument.RefKind == RefKind.None
                                && targetParameter.RefKind == RefKind.None
                                && state.Member.Model.GetSymbolInfo(
                                        StripTransparentExpression(
                                            argument.Expression)).Symbol is
                                { } argumentSymbol
                                && collectionAliases.Contains(argumentSymbol)
                                && target.Symbol.Parameters.ElementAtOrDefault(
                                    targetParameter.Ordinal) is { } forwarded
                                && forwarded.RefKind == RefKind.None
                                && IsRecoveryServiceCollectionType(
                                    forwarded.Type));

                    ObservePerUnitRecoveryCompositionCall(
                        state.Member, call, method, collectionAliases, state.Kind,
                        mustExecute, exactlyOnce, authoredCollectionForwardingIsInspectable);

                    if (UnsafeRecoveryCollectionMutation(
                            state.Member,
                            call,
                            collectionAliases,
                            authoredCollectionForwardingIsInspectable))
                    {
                        invalidRecoveryComposition |= state.Kind;
                    }

                    if (IsExactCompositionRegistrationMethod(method)
                        && RecoveryRegistrationUsesCollection(
                            state.Member,
                            call,
                            collectionAliases))
                    {
                        if (RecoveryRegistrationMentionsProtectedType(
                                state.Member,
                                call)
                            && !exactlyOnce)
                        {
                            invalidRecoveryComposition |= state.Kind;
                        }

                        if (ExactConcreteRecoveryRegistrationType(
                                state.Member,
                                call,
                                method) is { } concrete)
                        {
                            var concreteKey = (state.Kind, concrete);

                            if (!concreteRegistrations.TryGetValue(
                                    concreteKey,
                                    out HashSet<InvocationExpressionSyntax>?
                                        registrations))
                            {
                                registrations = new(
                                    ReferenceEqualityComparer.Instance);

                                concreteRegistrations.Add(
                                    concreteKey,
                                    registrations);
                            }

                            if (registrations.Add(call)
                                && registrations.Count > 1)
                            {
                                invalidRecoveryComposition |= state.Kind;
                            }
                        }

                        recoveryRegistrationCompositions[call] =
                            recoveryRegistrationCompositions.GetValueOrDefault(call)
                            | state.Kind;

                        if (mustExecute)
                        {
                            recoveryRegistrationMustExecuteCompositions[call] =
                                recoveryRegistrationMustExecuteCompositions
                                    .GetValueOrDefault(call)
                                | state.Kind;
                        }
                    }

                    if (target is null)
                    {
                        continue;
                    }

                    foreach ((ExpressionSyntax argument, IParameterSymbol? targetParameter, RefKind argumentRefKind) in
                        callArguments)
                    {
                        if (targetParameter is null
                            || argumentRefKind != RefKind.None
                            || targetParameter.RefKind != RefKind.None
                            || state.Member.Model.GetSymbolInfo(
                                    StripTransparentExpression(argument)).Symbol is
                                not { } argumentSymbol
                            || !collectionAliases.Contains(argumentSymbol)
                            || target.Symbol.Parameters.ElementAtOrDefault(
                                targetParameter.Ordinal) is not { } forwarded
                            || forwarded.RefKind != RefKind.None
                            || !IsRecoveryServiceCollectionType(forwarded.Type))
                        {
                            continue;
                        }

                        pending.Enqueue((
                            target,
                            forwarded,
                            state.Kind,
                            mustExecute,
                            ChildExactlyOnce()));

                        bool ChildExactlyOnce()
                        {
                            var targetKey = (
                                MemberIdentity(target),
                                forwarded.Ordinal,
                                state.Kind);

                            if (!incomingCalls.TryGetValue(
                                    targetKey,
                                    out HashSet<(GraphMemberIdentity Caller, int Call)>?
                                        calls))
                            {
                                calls = [];

                                incomingCalls.Add(targetKey, calls);
                            }

                            calls.Add((
                                MemberIdentity(state.Member),
                                call.SpanStart));

                            return exactlyOnce
                                && MemberIdentity(target)
                                    != MemberIdentity(state.Member)
                                && calls.Count == 1;
                        }
                    }
                }
            }

            return recoveryRegistrationCompositions;
        }

        private static IReadOnlySet<ISymbol> RecoveryCollectionAliases(
            AuthoredMember member,
            ISymbol services)
        {
            HashSet<ISymbol> aliases = new(SymbolEqualityComparer.Default)
            {
                services,
            };

            bool added;

            do
            {
                added = false;

                foreach (VariableDeclaratorSyntax declarator in member.Syntax
                    .DescendantNodes(node => node == member.Syntax
                        || node is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .OfType<VariableDeclaratorSyntax>())
                {
                    if (declarator.Initializer?.Value is not { } initializer
                        || member.Model.GetDeclaredSymbol(declarator) is not
                            ILocalSymbol local
                        || !IsRecoveryServiceCollectionType(local.Type))
                    {
                        continue;
                    }

                    ExpressionSyntax sourceExpression =
                        StripTransparentExpression(initializer);

                    bool directAlias = member.Model.GetSymbolInfo(
                            sourceExpression).Symbol is { } source
                        && aliases.Contains(source);

                    bool returnedAlias = sourceExpression is
                            InvocationExpressionSyntax fluent
                        && member.Model.GetSymbolInfo(fluent).Symbol is
                            IMethodSymbol method
                        && IsRecoveryServiceCollectionType(method.ReturnType)
                        && InvocationUsesRecoveryCollection(
                            member,
                            fluent,
                            aliases);

                    if (directAlias || returnedAlias)
                    {
                        added |= aliases.Add(local);
                    }
                }
            }

            while (added);

            return aliases;
        }

        private static bool IsRecoveryServiceCollectionType(ITypeSymbol type)
        {
            if (IsExactFrameworkType(
                    type,
                    "Microsoft.Extensions.DependencyInjection.IServiceCollection",
                    typeof(Microsoft.Extensions.DependencyInjection.IServiceCollection)
                        .Assembly.GetName()))
            {
                return true;
            }

            return type is INamedTypeSymbol
            {
                TypeArguments: [ITypeSymbol descriptor],
            } collection
                && TypeKey(collection) is
                    "System.Collections.Generic.ICollection`1"
                        or "System.Collections.Generic.IList`1"
                && IsExactFrameworkType(
                    descriptor,
                    "Microsoft.Extensions.DependencyInjection.ServiceDescriptor",
                    typeof(Microsoft.Extensions.DependencyInjection.ServiceDescriptor)
                        .Assembly.GetName());
        }

        private static bool IsExactServiceCollectionFluentMethod(
            IMethodSymbol method)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            string containingType = TypeKey(definition.ContainingType);

            return (containingType is
                        "Microsoft.Extensions.DependencyInjection.ServiceCollectionServiceExtensions"
                        or "Microsoft.Extensions.DependencyInjection.Extensions.ServiceCollectionDescriptorExtensions")
                && IsExactFrameworkMethod(
                    method,
                    containingType,
                    definition.Name,
                    "Microsoft.Extensions.DependencyInjection.Abstractions");
        }

        private static bool InvocationUsesRecoveryCollection(
            AuthoredMember member,
            InvocationExpressionSyntax call,
            IReadOnlySet<ISymbol> services)
        {
            return call.Expression is MemberAccessExpressionSyntax access
                    && ExpressionUsesRecoveryCollection(
                        member,
                        access.Expression,
                        services)
                || call.ArgumentList.Arguments.Any(argument =>
                    ExpressionUsesRecoveryCollection(
                        member,
                        argument.Expression,
                        services));
        }

        private static bool ExpressionUsesRecoveryCollection(
            AuthoredMember member,
            ExpressionSyntax expression,
            IReadOnlySet<ISymbol> services)
        {
            expression = StripTransparentExpression(expression);

            if (member.Model.GetSymbolInfo(expression).Symbol is { } symbol
                && services.Contains(symbol))
            {
                return true;
            }

            return expression is InvocationExpressionSyntax returned
                && member.Model.GetSymbolInfo(returned).Symbol is
                    IMethodSymbol method
                && IsRecoveryServiceCollectionType(method.ReturnType)
                && InvocationUsesRecoveryCollection(member, returned, services);
        }

        private static bool UnsafeRecoveryCollectionObjectEscape(
            AuthoredMember member,
            IReadOnlySet<ISymbol> services) => member.Syntax
                .DescendantNodes(node => node == member.Syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<BaseObjectCreationExpressionSyntax>()
                .Any(creation => creation.ArgumentList?.Arguments.Any(argument =>
                    ExpressionUsesRecoveryCollection(
                        member,
                        argument.Expression,
                        services)) == true);

        private static bool RecoveryCollectionIsCaptured(
            AuthoredMember member,
            IReadOnlySet<ISymbol> services) => member.Syntax
                .DescendantNodes()
                .Where(static node => node is
                    AnonymousFunctionExpressionSyntax
                        or LocalFunctionStatementSyntax)
                .Any(boundary => boundary.DescendantNodesAndSelf()
                    .OfType<IdentifierNameSyntax>()
                    .Any(identifier => member.Model.GetSymbolInfo(identifier).Symbol is
                    { } symbol
                        && services.Contains(symbol)));

        private static bool InvocationMayRepeat(
            AuthoredMember member,
            InvocationExpressionSyntax call) => call.Ancestors()
                .TakeWhile(node => node != member.Syntax)
                .Any(static node => node is
                    ForStatementSyntax
                        or ForEachStatementSyntax
                        or ForEachVariableStatementSyntax
                        or WhileStatementSyntax
                        or DoStatementSyntax);

        private static bool RecoveryRegistrationMentionsProtectedType(
            AuthoredMember member,
            InvocationExpressionSyntax call)
        {
            static bool ProtectedContract(ITypeSymbol type) => TypeKey(type) is
                "RetroDownfall.Arcanum.Core.Operations.ILongRunningOperationRecoveryHandler"
                or "RetroDownfall.Arcanum.Infrastructure.Data.IAuthenticatedCovenantErasureRecoveryHandler"
                or "RetroDownfall.Arcanum.Infrastructure.GrimoireTransitions.IGrimoireOfflineTransitionHandlerDispatch";

            static bool ProtectedImplementation(ITypeSymbol type) => type is
                INamedTypeSymbol named
                && named.AllInterfaces.Any(ProtectedContract);

            return call.DescendantNodesAndSelf()
                .OfType<InvocationExpressionSyntax>()
                .Select(invocation => member.Model.GetSymbolInfo(invocation).Symbol)
                .OfType<IMethodSymbol>()
                .SelectMany(static method => method.TypeArguments)
                .Concat(call.DescendantNodes()
                    .OfType<TypeOfExpressionSyntax>()
                    .Select(typeOf => member.Model.GetTypeInfo(typeOf.Type).Type)
                    .Where(static type => type is not null)
                    .Cast<ITypeSymbol>())
                .Any(type => ProtectedContract(type)
                    || ProtectedImplementation(type));
        }

        private BoundTypeIdentity? ExactConcreteRecoveryRegistrationType(
            AuthoredMember member,
            InvocationExpressionSyntax call,
            IMethodSymbol method)
        {
            if (!IsExactRecoveryRegistrationMethod(method)
                || method.TypeArguments is not [INamedTypeSymbol implementation]
                || call.ArgumentList.Arguments.Count != 0
                || !implementation.AllInterfaces.Any(static contract =>
                    TypeKey(contract) is
                        "RetroDownfall.Arcanum.Core.Operations.ILongRunningOperationRecoveryHandler"
                            or "RetroDownfall.Arcanum.Infrastructure.Data.IAuthenticatedCovenantErasureRecoveryHandler"))
            {
                return null;
            }

            return TypeIdentity(implementation, member.Model.Compilation);
        }

        private static bool UnsafeRecoveryCollectionAssignment(
            AuthoredMember member,
            IReadOnlySet<ISymbol> services)
        {
            bool IsTracked(ExpressionSyntax expression) => member.Model
                .GetSymbolInfo(StripTransparentExpression(expression)).Symbol is
            { } symbol
                && services.Contains(symbol);

            return member.Syntax
                .DescendantNodes(node => node == member.Syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<AssignmentExpressionSyntax>()
                .Any(assignment =>
                    assignment.Left is ElementAccessExpressionSyntax element
                        && IsTracked(element.Expression)
                    || IsTracked(assignment.Left)
                        && !IsTracked(assignment.Right)
                    || IsTracked(assignment.Right)
                        && !IsTracked(assignment.Left));
        }

        private bool UnsafeRecoveryCollectionMutation(
            AuthoredMember member,
            InvocationExpressionSyntax call,
            IReadOnlySet<ISymbol> services,
            bool authoredCollectionForwardingIsInspectable)
        {
            if (!InvocationUsesRecoveryCollection(member, call, services)
                || member.Model.GetSymbolInfo(call).Symbol is not
                    IMethodSymbol method)
            {
                return false;
            }

            bool exactProductionFrameworkBuilder =
                IsExactProductionFrameworkServiceBuilder(method)
                && !RecoveryRegistrationMentionsProtectedType(member, call);

            IMethodSymbol tryAddEnumerableDefinition = method.ReducedFrom ?? method;

            bool protectedTryAddEnumerableCandidate =
                tryAddEnumerableDefinition.Name == "TryAddEnumerable"
                && TypeKey(tryAddEnumerableDefinition.ContainingType) ==
                    "Microsoft.Extensions.DependencyInjection.Extensions.ServiceCollectionDescriptorExtensions"
                && RecoveryRegistrationMentionsProtectedType(member, call);

            if (protectedTryAddEnumerableCandidate
                && !TryGetExactScopedEnumerableDescriptor(call, method, member.Model,
                    out _, out _))
            {
                return true;
            }

            if (IsRecoveryServiceCollectionType(method.ReturnType)
                && !IsExactServiceCollectionFluentMethod(method)
                && !authoredCollectionForwardingIsInspectable
                && !exactProductionFrameworkBuilder)
            {
                return true;
            }

            if (exactProductionFrameworkBuilder)
            {
                return false;
            }

            bool exactDescriptorCollectionMutation =
                IsExactServiceDescriptorCollectionMutation(method);

            bool exactRegistration = IsPotentialRecoveryRegistrationMethod(method)
                || method.Name is
                    "TryAddSingleton" or "TryAddScoped" or "TryAddTransient"
                    && IsExactFrameworkMethod(
                        method,
                        "Microsoft.Extensions.DependencyInjection.Extensions.ServiceCollectionDescriptorExtensions",
                        method.Name,
                        "Microsoft.Extensions.DependencyInjection.Abstractions");

            bool exactDescriptorExtension = method.Name is
                    "TryAdd" or "TryAddEnumerable" or "Replace" or "RemoveAll"
                && IsExactFrameworkMethod(
                    method,
                    "Microsoft.Extensions.DependencyInjection.Extensions.ServiceCollectionDescriptorExtensions",
                    method.Name,
                    "Microsoft.Extensions.DependencyInjection.Abstractions");

            if (!exactDescriptorCollectionMutation
                && !exactRegistration
                && !exactDescriptorExtension)
            {
                return !authoredCollectionForwardingIsInspectable;
            }

            if (exactDescriptorCollectionMutation
                && method.Name is "Clear" or "RemoveAt")
            {
                return true;
            }

            static bool ProtectedContract(ITypeSymbol type) =>
                TypeKey(type) is
                    "RetroDownfall.Arcanum.Core.Operations.ILongRunningOperationRecoveryHandler"
                    or "RetroDownfall.Arcanum.Infrastructure.Data.IAuthenticatedCovenantErasureRecoveryHandler"
                    or "RetroDownfall.Arcanum.Infrastructure.GrimoireTransitions.IGrimoireOfflineTransitionHandlerDispatch";

            static bool ProtectedImplementation(ITypeSymbol type) => type is
                INamedTypeSymbol named
                && named.AllInterfaces.Any(ProtectedContract);

            (bool complete, ITypeSymbol[] mentionedTypes) =
                RecoveryCollectionMutationTypes(member, call, method, services);

            ITypeSymbol[] protectedTypes = mentionedTypes
                .Where(type => ProtectedContract(type)
                    || ProtectedImplementation(type))
                .ToArray();

            if (!complete)
            {
                return true;
            }

            if (protectedTypes.Length == 0)
            {
                return false;
            }

            bool exactHandlerContract(ITypeSymbol type) => TypeKey(type) is
                "RetroDownfall.Arcanum.Core.Operations.ILongRunningOperationRecoveryHandler"
                or "RetroDownfall.Arcanum.Infrastructure.Data.IAuthenticatedCovenantErasureRecoveryHandler";

            bool ExactFactoryAlias(InvocationExpressionSyntax registration) =>
                registration.ArgumentList.Arguments is
                    [ArgumentSyntax
                    {
                        Expression: AnonymousFunctionExpressionSyntax factory,
                    }]
                && (factory switch
                {
                    SimpleLambdaExpressionSyntax simple => simple.ExpressionBody,
                    ParenthesizedLambdaExpressionSyntax parenthesized =>
                        parenthesized.ExpressionBody,
                    _ => null,
                }) is InvocationExpressionSyntax resolution
                && member.Model.GetSymbolInfo(resolution).Symbol is
                    IMethodSymbol resolver
                && IsExactFrameworkMethod(
                    resolver,
                    "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions",
                    "GetRequiredService",
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
                && resolver.TypeArguments is [ITypeSymbol implementation]
                && ProtectedImplementation(implementation);

            bool exactHandler = IsExactRecoveryRegistrationMethod(method)
                && (method.TypeArguments is
                        [ITypeSymbol contract, ITypeSymbol implementation]
                    && exactHandlerContract(contract)
                    && ProtectedImplementation(implementation)
                    && call.ArgumentList.Arguments.Count == 0
                    || method.TypeArguments is [ITypeSymbol aliasContract]
                    && exactHandlerContract(aliasContract)
                    && ExactFactoryAlias(call)
                    || method.TypeArguments is [ITypeSymbol concreteImplementation]
                    && ProtectedImplementation(concreteImplementation)
                    && call.ArgumentList.Arguments.Count == 0);

            bool ExactRecoveryDescriptor(
                InvocationExpressionSyntax invocation) =>
                member.Model.GetSymbolInfo(invocation).Symbol is
                    IMethodSymbol descriptor
                && IsExactRecoveryRegistrationMethod(descriptor)
                && (descriptor.TypeArguments is
                        [ITypeSymbol descriptorContract,
                            ITypeSymbol descriptorImplementation]
                    && exactHandlerContract(descriptorContract)
                    && ProtectedImplementation(descriptorImplementation)
                    && invocation.ArgumentList.Arguments.Count == 0
                    || descriptor.TypeArguments is
                        [ITypeSymbol descriptorAliasContract]
                    && exactHandlerContract(descriptorAliasContract)
                    && ExactFactoryAlias(invocation));

            bool exactTryAddEnumerableDescriptor =
                TryGetExactScopedEnumerableDescriptor(call, method, member.Model,
                    out InvocationExpressionSyntax tryAddDescriptor, out _)
                && ExactRecoveryDescriptor(tryAddDescriptor);

            bool exactDescriptor = IsExactServiceDescriptorCollectionAdd(method)
                    && call.DescendantNodes()
                        .OfType<InvocationExpressionSyntax>()
                        .Any(ExactRecoveryDescriptor)
                || exactTryAddEnumerableDescriptor;

            bool exactDispatcher = method.Name == "TryAddSingleton"
                && IsExactFrameworkMethod(
                    method,
                    "Microsoft.Extensions.DependencyInjection.Extensions.ServiceCollectionDescriptorExtensions",
                    "TryAddSingleton",
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
                && method.TypeArguments is [ITypeSymbol dispatcherContract]
                && TypeKey(dispatcherContract) ==
                    "RetroDownfall.Arcanum.Infrastructure.GrimoireTransitions.IGrimoireOfflineTransitionHandlerDispatch"
                && call.DescendantNodes()
                    .OfType<BaseObjectCreationExpressionSyntax>()
                    .Count(creation => member.Model.GetTypeInfo(creation).Type is
                    { } created
                        && TypeKey(created) ==
                            "RetroDownfall.Arcanum.Infrastructure.GrimoireTransitions.GrimoireOfflineTransitionHandlerDispatch") == 1;

            return !exactHandler && !exactDescriptor && !exactDispatcher;
        }

        private static bool IsExactTryAddEnumerableMutation(IMethodSymbol method)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            return method.Name == "TryAddEnumerable"
                && IsExactFrameworkMethod(method,
                    "Microsoft.Extensions.DependencyInjection.Extensions.ServiceCollectionDescriptorExtensions",
                    "TryAddEnumerable", "Microsoft.Extensions.DependencyInjection.Abstractions")
                && definition.Parameters is
                    [IParameterSymbol { Type: ITypeSymbol collection },
                     IParameterSymbol { Type: ITypeSymbol descriptor }]
                && IsExactFrameworkType(collection,
                    "Microsoft.Extensions.DependencyInjection.IServiceCollection",
                    typeof(Microsoft.Extensions.DependencyInjection.IServiceCollection).Assembly.GetName())
                && IsExactFrameworkType(descriptor,
                    "Microsoft.Extensions.DependencyInjection.ServiceDescriptor",
                    typeof(Microsoft.Extensions.DependencyInjection.ServiceDescriptor).Assembly.GetName());
        }

        private static bool TryGetExactScopedEnumerableDescriptor(InvocationExpressionSyntax call,
            IMethodSymbol method, SemanticModel model,
            out InvocationExpressionSyntax descriptor, out IMethodSymbol descriptorMethod)
        {
            descriptor = null!;
            descriptorMethod = null!;

            if (!IsExactTryAddEnumerableMutation(method)
                || model.GetOperation(call) is not IInvocationOperation invocation) return false;

            IArgumentOperation[] descriptors = invocation.Arguments.Where(argument =>
                argument.Parameter is { } parameter && IsExactFrameworkType(parameter.Type,
                    "Microsoft.Extensions.DependencyInjection.ServiceDescriptor",
                    typeof(Microsoft.Extensions.DependencyInjection.ServiceDescriptor).Assembly.GetName())).ToArray();

            if (descriptors is not [IArgumentOperation argument]
                || argument.Value.Syntax is not ExpressionSyntax expression
                || !TryNormalizeBuiltInCleanupValue(model, expression, out ExpressionSyntax normalized)
                || normalized is not InvocationExpressionSyntax nested
                || model.GetSymbolInfo(nested).Symbol is not IMethodSymbol bound
                || bound.Name != "Scoped" || !IsExactRecoveryRegistrationMethod(bound)) return false;

            descriptor = nested;
            descriptorMethod = bound;

            return true;
        }

        private static bool IsExactIndexedScopedDescriptor(InvocationExpressionSyntax call,
            IMethodSymbol method, SemanticModel model) =>
            method.Name == "Scoped" && IsExactRecoveryRegistrationMethod(method)
                && call.Ancestors().OfType<InvocationExpressionSyntax>().FirstOrDefault() is { } outer
                && model.GetSymbolInfo(outer).Symbol is IMethodSymbol mutation
                && TryGetExactScopedEnumerableDescriptor(outer, mutation, model,
                    out InvocationExpressionSyntax nested, out _)
                && ReferenceEquals(nested, call);

        private static bool IsExactProductionFrameworkServiceBuilder(
            IMethodSymbol method)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            string? assembly = (TypeKey(definition.ContainingType), definition.Name)
                switch
            {
                ("Microsoft.Extensions.DependencyInjection.ExceptionHandlerServiceCollectionExtensions", "AddExceptionHandler") =>
                    "Microsoft.AspNetCore.Diagnostics",
                ("Microsoft.Extensions.DependencyInjection.ProblemDetailsServiceCollectionExtensions", "AddProblemDetails") =>
                    "Microsoft.AspNetCore.Http.Extensions",
                ("Microsoft.Extensions.DependencyInjection.CorsServiceCollectionExtensions", "AddCors") =>
                    "Microsoft.AspNetCore.Cors",
                ("Microsoft.Extensions.DependencyInjection.OpenApiServiceCollectionExtensions", "AddOpenApi") =>
                    "Microsoft.AspNetCore.OpenApi",
                ("Microsoft.AspNetCore.Builder.RateLimiterServiceCollectionExtensions", "AddRateLimiter") =>
                    "Microsoft.AspNetCore.RateLimiting",
                ("Microsoft.AspNetCore.Builder.ResponseCompressionServicesExtensions", "AddResponseCompression") =>
                    "Microsoft.AspNetCore.ResponseCompression",
                ("Microsoft.Extensions.DependencyInjection.HttpJsonServiceExtensions", "ConfigureHttpJsonOptions") =>
                    "Microsoft.AspNetCore.Http.Extensions",
                ("Microsoft.Extensions.DependencyInjection.DataProtectionServiceCollectionExtensions", "AddDataProtection") =>
                    "Microsoft.AspNetCore.DataProtection",
                ("Microsoft.Extensions.DependencyInjection.HttpClientFactoryServiceCollectionExtensions", "AddHttpClient") =>
                    "Microsoft.Extensions.Http",
                ("Microsoft.Extensions.DependencyInjection.ServiceCollectionHostedServiceExtensions", "AddHostedService") =>
                    "Microsoft.Extensions.Hosting.Abstractions",
                ("Microsoft.Extensions.DependencyInjection.OptionsServiceCollectionExtensions", "Configure") =>
                    "Microsoft.Extensions.Options",
                ("Microsoft.Extensions.DependencyInjection.EntityFrameworkServiceCollectionExtensions", "AddDbContext" or "AddDbContextPool") =>
                    "Microsoft.EntityFrameworkCore",
                ("Serilog.SerilogServiceCollectionExtensions", "AddSerilog") =>
                    "Serilog.Extensions.Hosting",
                _ => null,
            };

            return assembly is not null
                && IsExactFrameworkMethod(
                    method,
                    TypeKey(definition.ContainingType),
                    definition.Name,
                    assembly);
        }

        private static (bool Complete, ITypeSymbol[] Types)
            RecoveryCollectionMutationTypes(
                AuthoredMember member,
                InvocationExpressionSyntax call,
                IMethodSymbol method,
                IReadOnlySet<ISymbol> services)
        {
            List<ITypeSymbol> types = [.. method.TypeArguments];

            bool requiresArgumentEvidence = method.TypeArguments.Length == 0
                && method.Name is not ("Clear" or "RemoveAt");

            bool foundArgumentEvidence = false;

            foreach (ArgumentSyntax argument in call.ArgumentList.Arguments)
            {
                ExpressionSyntax expression =
                    StripTransparentExpression(argument.Expression);

                if (member.Model.GetSymbolInfo(expression).Symbol is { } symbol
                    && services.Contains(symbol))
                {
                    continue;
                }

                ITypeSymbol? argumentType = member.Model.GetTypeInfo(expression).Type;

                if (argumentType is null
                    || TypeKey(argumentType) is not
                        ("System.Type"
                            or "Microsoft.Extensions.DependencyInjection.ServiceDescriptor"))
                {
                    continue;
                }

                if (!TryResolveRecoveryCollectionMutationTypes(
                        member,
                        expression,
                        call,
                        new HashSet<ISymbol>(SymbolEqualityComparer.Default),
                        out ITypeSymbol[] resolved))
                {
                    return (false, [.. types]);
                }

                foundArgumentEvidence = true;

                types.AddRange(resolved);
            }

            return (!requiresArgumentEvidence || foundArgumentEvidence, [.. types]);
        }

        private static bool TryResolveRecoveryCollectionMutationTypes(
            AuthoredMember member,
            ExpressionSyntax expression,
            InvocationExpressionSyntax use,
            ISet<ISymbol> active,
            out ITypeSymbol[] types)
        {
            expression = StripTransparentExpression(expression);

            if (expression is TypeOfExpressionSyntax typeOf
                && member.Model.GetTypeInfo(typeOf.Type).Type is { } reflected)
            {
                types = [reflected];

                return true;
            }

            if (expression is BaseObjectCreationExpressionSyntax creation
                && member.Model.GetSymbolInfo(creation).Symbol is
                    IMethodSymbol constructor
                && IsExactFrameworkType(
                    constructor.ContainingType,
                    "Microsoft.Extensions.DependencyInjection.ServiceDescriptor",
                    typeof(Microsoft.Extensions.DependencyInjection.ServiceDescriptor)
                        .Assembly.GetName()))
            {
                ArgumentSyntax[] typeArguments = creation.ArgumentList?.Arguments
                    .Where(argument => member.Model.GetTypeInfo(
                            argument.Expression).Type is { } argumentType
                        && TypeKey(argumentType) == "System.Type")
                    .ToArray()
                    ?? [];

                if (typeArguments.Length == 0)
                {
                    types = [];

                    return false;
                }

                List<ITypeSymbol> resolved = [];

                foreach (ArgumentSyntax argument in typeArguments)
                {
                    if (!TryResolveRecoveryCollectionMutationTypes(
                            member,
                            argument.Expression,
                            use,
                            active,
                            out ITypeSymbol[] argumentTypes))
                    {
                        types = [];

                        return false;
                    }

                    resolved.AddRange(argumentTypes);
                }

                types = [.. resolved];

                return types.Length != 0;
            }

            if (member.Model.GetSymbolInfo(expression).Symbol is ILocalSymbol local)
            {
                if (!active.Add(local)
                    || !RecoveryTupleSourceIsStable(
                        member,
                        local,
                        use,
                        allowSimpleLocalAssignments: false)
                    || local.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                        is not VariableDeclaratorSyntax
                        {
                            Initializer.Value: { } initializer,
                        })
                {
                    types = [];

                    return false;
                }

                bool resolved = TryResolveRecoveryCollectionMutationTypes(
                    member,
                    initializer,
                    use,
                    active,
                    out types);

                active.Remove(local);

                return resolved;
            }

            List<ITypeSymbol> resolvedTypes = [];

            foreach (TypeOfExpressionSyntax nestedTypeOf in expression
                .DescendantNodesAndSelf()
                .OfType<TypeOfExpressionSyntax>())
            {
                if (member.Model.GetTypeInfo(nestedTypeOf.Type).Type is not
                    { } nestedType)
                {
                    types = [];

                    return false;
                }

                resolvedTypes.Add(nestedType);
            }

            foreach (InvocationExpressionSyntax invocation in expression
                .DescendantNodesAndSelf()
                .OfType<InvocationExpressionSyntax>())
            {
                if (member.Model.GetSymbolInfo(invocation).Symbol is not
                    IMethodSymbol factory
                    || TypeKey((factory.ReducedFrom ?? factory).ContainingType)
                        != "Microsoft.Extensions.DependencyInjection.ServiceDescriptor")
                {
                    continue;
                }

                resolvedTypes.AddRange(factory.TypeArguments);
            }

            types = [.. resolvedTypes];

            return types.Length != 0;
        }

        private bool InvocationMustExecuteFromEntry(
            AuthoredMember member,
            InvocationExpressionSyntax call) =>
            InvocationExecution(member).MustExecute.Contains(call);

        private bool InvocationCanExecuteFromEntry(
            AuthoredMember member,
            InvocationExpressionSyntax call) =>
            InvocationExecution(member).Reachable.Contains(call);

        private InvocationExecutionPlan InvocationExecution(AuthoredMember member)
        {
            string metricMember = TypeKey(member.Symbol.ContainingType)
                + "."
                + member.Symbol.Name;

            if (!invocationExecutionAnalysis.TryGetValue(
                    metricMember,
                    out InvocationExecutionAnalysisCounter? analysis))
            {
                analysis = new();

                invocationExecutionAnalysis.Add(metricMember, analysis);
            }

            analysis.PlanRequests++;

            if (invocationExecutionPlans.TryGetValue(
                    member.Syntax,
                    out InvocationExecutionPlan? cached))
            {
                return cached;
            }

            analysis.PlanBuilds++;

            ControlFlowGraph? graph;

            try
            {
                graph = ControlFlowGraph.Create(
                    member.Syntax,
                    member.Model);
            }
            catch (ArgumentException)
            {
                return Cache(
                    new HashSet<InvocationExpressionSyntax>(
                        ReferenceEqualityComparer.Instance),
                    new HashSet<InvocationExpressionSyntax>(
                        ReferenceEqualityComparer.Instance));
            }
            catch (InvalidOperationException)
            {
                return Cache(
                    new HashSet<InvocationExpressionSyntax>(
                        ReferenceEqualityComparer.Instance),
                    new HashSet<InvocationExpressionSyntax>(
                        ReferenceEqualityComparer.Instance));
            }

            if (graph is null)
            {
                return Cache(
                    new HashSet<InvocationExpressionSyntax>(
                        ReferenceEqualityComparer.Instance),
                    new HashSet<InvocationExpressionSyntax>(
                        ReferenceEqualityComparer.Instance));
            }

            BasicBlock[] reachable = graph.Blocks
                .Where(static block => block.IsReachable)
                .ToArray();

            BasicBlock entry = graph.Blocks[0];

            BasicBlock exit = graph.Blocks[^1];

            if (!exit.IsReachable)
            {
                return Cache(
                    new HashSet<InvocationExpressionSyntax>(
                        ReferenceEqualityComparer.Instance),
                    new HashSet<InvocationExpressionSyntax>(
                        ReferenceEqualityComparer.Instance));
            }

            Dictionary<BasicBlock, HashSet<BasicBlock>> dominators = [];

            foreach (BasicBlock block in reachable)
            {
                dominators[block] = block == entry
                    ? [entry]
                    : [.. reachable];
            }

            bool changed;

            do
            {
                changed = false;

                foreach (BasicBlock block in reachable.Where(candidate =>
                    candidate != entry))
                {
                    BasicBlock[] predecessors = block.Predecessors
                        .Select(static branch => branch.Source)
                        .Where(static predecessor => predecessor.IsReachable)
                        .Distinct()
                        .ToArray();

                    HashSet<BasicBlock> updated = predecessors.Length == 0
                        ? []
                        : new(dominators[predecessors[0]]);

                    foreach (BasicBlock predecessor in predecessors.Skip(1))
                    {
                        updated.IntersectWith(dominators[predecessor]);
                    }

                    updated.Add(block);

                    if (!dominators[block].SetEquals(updated))
                    {
                        dominators[block] = updated;

                        changed = true;
                    }
                }
            }

            while (changed);

            HashSet<InvocationExpressionSyntax> reachableCalls = new(
                ReferenceEqualityComparer.Instance);

            HashSet<InvocationExpressionSyntax> mustExecuteCalls = new(
                ReferenceEqualityComparer.Instance);

            static void Collect(
                IOperation operation,
                ISet<InvocationExpressionSyntax> calls)
            {
                if (operation is IInvocationOperation
                    && operation.Syntax is InvocationExpressionSyntax invocation)
                {
                    calls.Add(invocation);
                }

                foreach (IOperation child in operation.ChildOperations)
                {
                    Collect(child, calls);
                }
            }

            foreach (BasicBlock block in reachable)
            {
                HashSet<InvocationExpressionSyntax> blockCalls = new(
                    ReferenceEqualityComparer.Instance);

                foreach (IOperation operation in block.Operations)
                {
                    Collect(operation, blockCalls);
                }

                if (block.BranchValue is { } branch)
                {
                    Collect(branch, blockCalls);
                }

                reachableCalls.UnionWith(blockCalls);

                if (dominators[exit].Contains(block))
                {
                    mustExecuteCalls.UnionWith(blockCalls);
                }
            }

            return Cache(reachableCalls, mustExecuteCalls);

            InvocationExecutionPlan Cache(
                IReadOnlySet<InvocationExpressionSyntax> reachableCalls,
                IReadOnlySet<InvocationExpressionSyntax> mustExecuteCalls)
            {
                InvocationExecutionPlan plan = new(
                    reachableCalls,
                    mustExecuteCalls);

                invocationExecutionPlans[member.Syntax] = plan;

                return plan;
            }
        }

        private static bool RecoveryRegistrationUsesCollection(
            AuthoredMember member,
            InvocationExpressionSyntax registration,
            IReadOnlySet<ISymbol> services)
        {
            bool IsTracked(ExpressionSyntax expression) => member.Model
                .GetSymbolInfo(StripTransparentExpression(expression)).Symbol is
            { } symbol
                && services.Contains(symbol);

            if (registration.Expression is MemberAccessExpressionSyntax access
                && IsTracked(access.Expression)
                || registration.ArgumentList.Arguments.FirstOrDefault() is
                { Expression: { } first }
                    && IsTracked(first))
            {
                return true;
            }

            if (member.Model.GetSymbolInfo(registration).Symbol is not
                    IMethodSymbol
                {
                    Name: "Scoped" or "Singleton" or "Transient",
                }
                || registration.Ancestors().OfType<ArgumentSyntax>().FirstOrDefault()
                    ?.Parent?.Parent is not InvocationExpressionSyntax enumerable
                || member.Model.GetSymbolInfo(enumerable).Symbol is not
                    IMethodSymbol enumerableMethod)
            {
                return false;
            }

            bool trackedCollection = enumerable.Expression is MemberAccessExpressionSyntax enumerableAccess
                    && IsTracked(enumerableAccess.Expression)
                || enumerable.ArgumentList.Arguments.FirstOrDefault() is
                { Expression: { } enumerableFirst }
                    && IsTracked(enumerableFirst);

            return trackedCollection
                && (IsExactFrameworkMethod(
                        enumerableMethod,
                        "Microsoft.Extensions.DependencyInjection.Extensions.ServiceCollectionDescriptorExtensions",
                        "TryAddEnumerable",
                        "Microsoft.Extensions.DependencyInjection.Abstractions")
                    || IsExactServiceDescriptorCollectionAdd(
                        enumerableMethod));
        }

        private static bool IsExactServiceDescriptorCollectionAdd(
            IMethodSymbol method) => method.Name == "Add"
                && IsExactServiceDescriptorCollectionMutation(method);

        private static bool IsExactServiceDescriptorCollectionMutation(
            IMethodSymbol method)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            return definition.Name is
                    "Add" or "Insert" or "Remove" or "RemoveAt" or "Clear"
                && !definition.IsStatic
                && !definition.Locations.Any(static location =>
                    location.IsInSource)
                && definition.ContainingType is INamedTypeSymbol
                {
                    TypeArguments: [ITypeSymbol descriptor],
                } collection
                && TypeKey(collection) is
                    "System.Collections.Generic.ICollection`1"
                    or "System.Collections.Generic.IList`1"
                && IsExactFrameworkType(
                    descriptor,
                    "Microsoft.Extensions.DependencyInjection.ServiceDescriptor",
                    typeof(Microsoft.Extensions.DependencyInjection.ServiceDescriptor)
                        .Assembly.GetName());
        }

        private RecoveryHandlerTarget[] ResolveRecoveryHandlerTargets(
            AuthoredMember caller,
            IMethodSymbol contractMethod,
            SyntaxNode anchor,
            RecoveryMatrix matrix)
        {
            // This delegated cache can contain partial targets without a completion fact.
            // Its ordinary result remains useful, but cannot certify whole-root reuse.
            RefuseTraversalCompletion();

            RecoveryHandlerResolutionIdentity contractIdentity = new(
                TypeIdentity(
                    contractMethod.ContainingType,
                    caller.Model.Compilation),
                MethodKey(contractMethod));

            if (recoveryHandlerTargets.TryGetValue(
                contractIdentity,
                out RecoveryHandlerTarget[]? cached))
            {
                return cached;
            }

            List<RecoveryHandlerTarget> targets = [];

            PreparePerUnitRecoveryCompositionSources(matrix);

            IReadOnlyDictionary<InvocationExpressionSyntax, RecoveryCompositionKind>
                registrationCompositions = RecoveryRegistrationCompositions();

            foreach (AuthoredMember candidate in AuthoredMembers
                .Where(member => member.Symbol.Name == contractMethod.Name)
                .Where(member => member.Symbol.ContainingType.AllInterfaces.Any(type =>
                    SameBoundType(
                        type,
                        member.Model.Compilation,
                        contractMethod.ContainingType,
                        member.Model.Compilation))))
            {
                IMethodSymbol[] slots = candidate.Symbol.ContainingType.AllInterfaces
                    .Where(type => SameBoundType(
                        type,
                        candidate.Model.Compilation,
                        contractMethod.ContainingType,
                        candidate.Model.Compilation))
                    .SelectMany(static type => type.GetMembers())
                    .OfType<IMethodSymbol>()
                    .Where(slot => MethodKey(slot) == MethodKey(contractMethod))
                    .ToArray();

                if (!slots.Any(slot => candidate.Symbol.ContainingType
                        .FindImplementationForInterfaceMember(slot) is IMethodSymbol implementation
                    && SymbolEqualityComparer.Default.Equals(
                        implementation.OriginalDefinition,
                        candidate.Symbol.OriginalDefinition))
                    || ConstantRecoveryHandlerProperty(candidate, "Kind") is not string kind
                    || ConstantRecoveryHandlerProperty(candidate, "SupportedCheckpointVersion") is not
                        int supported)
                {
                    diagnostics.Add(new(
                        "HOSTED_RECOVERY_HANDLER_UNPROVEN",
                        Location(candidate.Syntax),
                        TypeKey(candidate.Symbol.ContainingType)
                            + "; Kind and SupportedCheckpointVersion must be compile-time constants."));

                    continue;
                }

                if (invalidRecoveryComposition != RecoveryCompositionKind.None)
                {
                    diagnostics.Add(new(
                        "HOSTED_RECOVERY_HANDLER_UNPROVEN",
                        Location(candidate.Syntax),
                        TypeKey(candidate.Symbol.ContainingType)
                            + "; a recovery composition can mutate or compete with the final service registration set."));

                    continue;
                }

                (InvocationExpressionSyntax Call, RecoveryCompositionKind Composition, bool Supported)[]
                    potentialRegistrations = invocations
                    .Where(registration => registration.Model.GetSymbolInfo(registration.Call).Symbol is
                        IMethodSymbol registrationMethod
                        && IsPotentialRecoveryRegistrationMethod(registrationMethod)
                        && (registrationMethod.TypeArguments.Length == 2
                                && SameBoundType(
                                    registrationMethod.TypeArguments[0],
                                    registration.Model.Compilation,
                                    contractMethod.ContainingType,
                                    candidate.Model.Compilation)
                                && SameBoundType(
                                    registrationMethod.TypeArguments[1],
                                    registration.Model.Compilation,
                                    candidate.Symbol.ContainingType,
                                    candidate.Model.Compilation)
                            || registrationMethod.TypeArguments.Length == 1
                                && SameBoundType(
                                    registrationMethod.TypeArguments[0],
                                    registration.Model.Compilation,
                                    contractMethod.ContainingType,
                                    candidate.Model.Compilation)
                                && IsExactScopedFactoryAlias(
                                    registration.Call,
                                    registration.Model,
                                    candidate.Symbol.ContainingType)))
                    .Select(registration => (
                        Call: registration.Call,
                        Composition: registrationCompositions.GetValueOrDefault(
                            registration.Call),
                        Supported: IsExactRecoveryRegistrationMethod((IMethodSymbol)
                            registration.Model.GetSymbolInfo(registration.Call).Symbol!)
                            && (recoveryRegistrationMustExecuteCompositions
                                    .GetValueOrDefault(registration.Call)
                                & registrationCompositions.GetValueOrDefault(
                                    registration.Call)) ==
                                registrationCompositions.GetValueOrDefault(
                                    registration.Call)))
                    .Where(static registration =>
                        registration.Composition != RecoveryCompositionKind.None)
                    .ToArray();

                if (potentialRegistrations.Any(static registration =>
                    !registration.Supported))
                {
                    diagnostics.Add(new(
                        "HOSTED_RECOVERY_HANDLER_UNPROVEN",
                        Location(candidate.Syntax),
                        TypeKey(candidate.Symbol.ContainingType)
                            + "; unsupported-lifetime or competing recovery-handler registrations are not exact scoped aliases."));

                    continue;
                }

                (InvocationExpressionSyntax Call, RecoveryCompositionKind Composition)[]
                    registrations = potentialRegistrations
                    .Select(static registration => (
                        registration.Call,
                        registration.Composition))
                    .ToArray();

                if (registrations.Length == 0)
                {
                    diagnostics.Add(new(
                        "HOSTED_RECOVERY_HANDLER_UNPROVEN",
                        Location(candidate.Syntax),
                        TypeKey(candidate.Symbol.ContainingType)
                            + "; the handler has no exact closed registration."));

                    continue;
                }

                int servingRegistrations = registrations.Count(registration =>
                    registration.Composition.HasFlag(
                        RecoveryCompositionKind.Serving));

                int stoppedRegistrations = registrations.Count(registration =>
                    registration.Composition.HasFlag(
                        RecoveryCompositionKind.StoppedHost));

                if (servingRegistrations > 1 || stoppedRegistrations > 1)
                {
                    diagnostics.Add(new(
                        "HOSTED_RECOVERY_HANDLER_UNPROVEN",
                        Location(candidate.Syntax),
                        TypeKey(candidate.Symbol.ContainingType)
                            + "; each runtime composition must contain exactly one registration for the handler contract."));

                    continue;
                }

                RecoveryCompositionKind composition = registrations.Aggregate(
                    RecoveryCompositionKind.None,
                    static (combined, registration) =>
                        combined | registration.Composition);

                targets.Add(new(candidate, kind, supported, composition));
            }

            if (IsExactAuthoredProtocolType(
                    contractMethod.ContainingType,
                    "RetroDownfall.Arcanum.Core.Operations.ILongRunningOperationRecoveryHandler",
                    caller.Model.Compilation))
            {
                foreach (RecoveryDescriptor descriptor in matrix.Descriptors)
                {
                    RecoveryHandlerTarget[] generic = targets
                        .Where(target => target.Composition.HasFlag(
                                RecoveryCompositionKind.Serving)
                            && target.Kind == descriptor.Kind)
                        .ToArray();

                    if (generic is not [RecoveryHandlerTarget exact]
                        || exact.SupportedCheckpointVersion
                            != descriptor.MaximumCheckpointVersion)
                    {
                        diagnostics.Add(new(
                            "HOSTED_RECOVERY_HANDLER_UNPROVEN",
                            Location(anchor),
                            descriptor.Kind
                                + "; the host must register exactly one generic handler whose supported maximum matches the registry."));
                    }
                }
            }

            foreach (RecoveryHandlerTarget ownerOnly in targets.Where(static target =>
                target.Composition.HasFlag(
                    RecoveryCompositionKind.StoppedHost)
                && !target.Composition.HasFlag(
                    RecoveryCompositionKind.Serving)))
            {
                bool exactOwnerTuple = matrix.Tuples.Any(tuple =>
                    tuple.Kind == ownerOnly.Kind
                    && tuple.CheckpointVersion
                        == ownerOnly.SupportedCheckpointVersion
                    && tuple.Disposition == RecoveryDisposition.OwnerBound);

                if (!exactOwnerTuple)
                {
                    diagnostics.Add(new(
                        "HOSTED_RECOVERY_HANDLER_UNPROVEN",
                        Location(ownerOnly.Member.Syntax),
                        TypeKey(ownerOnly.Member.Symbol.ContainingType)
                            + "; a stopped-host-only handler must name exactly an owner-bound checkpoint."));
                }
            }

            foreach (RecoveryTuple tuple in matrix.Tuples.Where(static tuple =>
                tuple.Disposition == RecoveryDisposition.OwnerBound))
            {
                RecoveryHandlerTarget[] exactOwners = targets
                    .Where(target => target.Composition.HasFlag(
                            RecoveryCompositionKind.StoppedHost)
                        && !target.Composition.HasFlag(
                            RecoveryCompositionKind.Serving)
                        && target.Kind == tuple.Kind
                        && target.SupportedCheckpointVersion == tuple.CheckpointVersion)
                    .ToArray();

                if (exactOwners.Length != 1)
                {
                    diagnostics.Add(new(
                        "HOSTED_RECOVERY_HANDLER_UNPROVEN",
                        tuple.Kind + ":" + tuple.CheckpointVersion,
                        "Each owner-bound checkpoint must have exactly one stopped-host-only handler; found "
                            + exactOwners.Length
                            + "."));
                }
            }

            RecoveryHandlerTarget[] resolved = [.. targets];

            recoveryHandlerTargets.Add(contractIdentity, resolved);

            return resolved;
        }

        private static bool IsExactRecoveryRegistrationMethod(IMethodSymbol method) =>
            method.Name switch
            {
                "AddScoped" => IsExactFrameworkMethod(
                    method,
                    "Microsoft.Extensions.DependencyInjection.ServiceCollectionServiceExtensions",
                    "AddScoped",
                    "Microsoft.Extensions.DependencyInjection.Abstractions"),
                "TryAddScoped" => IsExactFrameworkMethod(
                    method,
                    "Microsoft.Extensions.DependencyInjection.Extensions.ServiceCollectionDescriptorExtensions",
                    "TryAddScoped",
                    "Microsoft.Extensions.DependencyInjection.Abstractions"),
                "Scoped" => IsExactFrameworkMethod(
                    method,
                    "Microsoft.Extensions.DependencyInjection.ServiceDescriptor",
                    "Scoped",
                    "Microsoft.Extensions.DependencyInjection.Abstractions"),
                _ => false,
            };

        private static bool IsExactCompositionRegistrationMethod(
            IMethodSymbol method) =>
            IsPotentialRecoveryRegistrationMethod(method)
            || method.Name == "TryAddSingleton"
                && IsExactFrameworkMethod(
                    method,
                    "Microsoft.Extensions.DependencyInjection.Extensions.ServiceCollectionDescriptorExtensions",
                    "TryAddSingleton",
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
            || IsExactFrameworkMethod(
                method,
                "Microsoft.Extensions.DependencyInjection.OptionsServiceCollectionExtensions",
                "Configure",
                "Microsoft.Extensions.Options");

        private static bool IsPotentialRecoveryRegistrationMethod(
            IMethodSymbol method) =>
            IsExactRecoveryRegistrationMethod(method)
            || method.Name is "AddSingleton" or "AddTransient"
                && IsExactFrameworkMethod(
                    method,
                    "Microsoft.Extensions.DependencyInjection.ServiceCollectionServiceExtensions",
                    method.Name,
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
            || method.Name is "Singleton" or "Transient"
                && IsExactFrameworkMethod(
                    method,
                    "Microsoft.Extensions.DependencyInjection.ServiceDescriptor",
                    method.Name,
                    "Microsoft.Extensions.DependencyInjection.Abstractions");

        private static bool IsExactFrameworkMethod(
            IMethodSymbol method,
            string containingType,
            string name,
            string assembly)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            AssemblyName trustedAssembly = assembly switch
            {
                "System.Linq" => typeof(System.Linq.Enumerable).Assembly.GetName(),
                "Microsoft.Extensions.DependencyInjection.Abstractions" =>
                    typeof(Microsoft.Extensions.DependencyInjection.ServiceCollectionServiceExtensions)
                        .Assembly.GetName(),
                "System.Private.CoreLib" => typeof(IAsyncDisposable)
                    .Assembly.GetName(),
                "Microsoft.AspNetCore.Diagnostics"
                    or "Microsoft.AspNetCore.Http.Extensions"
                    or "Microsoft.AspNetCore.Cors"
                    or "Microsoft.AspNetCore.OpenApi"
                    or "Microsoft.AspNetCore.RateLimiting"
                    or "Microsoft.AspNetCore.ResponseCompression"
                    or "Microsoft.AspNetCore.DataProtection"
                    or "Microsoft.Extensions.Http"
                    or "Microsoft.Extensions.Hosting.Abstractions"
                    or "Microsoft.Extensions.Options"
                    or "Microsoft.EntityFrameworkCore"
                    or "Serilog.Extensions.Hosting" =>
                    Assembly.Load(new AssemblyName(assembly)).GetName(),
                _ => throw new InvalidOperationException(
                    "No trusted framework assembly identity is registered for "
                        + assembly
                        + "."),
            };

            AssemblyIdentity actualAssembly = definition.ContainingAssembly.Identity;

            return definition.Name == name
                && TypeKey(definition.ContainingType) == containingType
                && FrameworkAssemblyIdentityMatches(
                    actualAssembly,
                    trustedAssembly)
                && !definition.Locations.Any(static location => location.IsInSource);
        }

        private bool SameBoundType(
            ITypeSymbol left,
            Compilation leftCompilation,
            ITypeSymbol right,
            Compilation rightCompilation) =>
            TypeIdentity(left, leftCompilation)
                == TypeIdentity(right, rightCompilation);

        private static bool IsOrdinaryNonGenericPropertyType(
            ITypeSymbol type) =>
            type is INamedTypeSymbol
            {
                Arity: 0,
                IsGenericType: false,
                IsUnboundGenericType: false,
                TypeKind: TypeKind.Class
                    or TypeKind.Struct
                    or TypeKind.Interface
                    or TypeKind.Enum
                    or TypeKind.Delegate,
            } named
            && (named.ContainingType is null
                || IsOrdinaryNonGenericPropertyType(named.ContainingType));

        internal bool SameBoundPropertyDefinition(
            IPropertySymbol left,
            Compilation leftCompilation,
            IPropertySymbol right,
            Compilation rightCompilation)
        {
            if (SymbolEqualityComparer.Default.Equals(
                    left.OriginalDefinition,
                    right.OriginalDefinition))
            {
                return true;
            }

            return !left.IsIndexer
                && !right.IsIndexer
                && left.Parameters.Length == 0
                && right.Parameters.Length == 0
                && left.ExplicitInterfaceImplementations.Length == 0
                && right.ExplicitInterfaceImplementations.Length == 0
                && left.GetMethod is not null
                && right.GetMethod is not null
                && left.SetMethod is null
                && right.SetMethod is null
                && left.MetadataName == right.MetadataName
                && left.IsStatic == right.IsStatic
                && left.ReturnsByRef == right.ReturnsByRef
                && left.ReturnsByRefReadonly == right.ReturnsByRefReadonly
                && IsOrdinaryNonGenericPropertyType(left.Type)
                && IsOrdinaryNonGenericPropertyType(right.Type)
                && SameBoundType(
                    left.ContainingType,
                    leftCompilation,
                    right.ContainingType,
                    rightCompilation)
                && SameBoundType(
                    left.Type,
                    leftCompilation,
                    right.Type,
                    rightCompilation);
        }

        private bool IsExactAuthoredProtocolType(
            ITypeSymbol? type,
            string expectedType,
            Compilation consumingCompilation)
        {
            if (type is null
                || TypeKey(type) != expectedType
                || AuthoredCompilationIdentity(
                    type,
                    consumingCompilation) is not int authoredCompilation)
            {
                return false;
            }

            if (ReferenceEquals(
                    type.ContainingAssembly,
                    consumingCompilation.Assembly))
            {
                return true;
            }

            string? owningProject = expectedType switch
            {
                _ when expectedType.StartsWith(
                    "RetroDownfall.Arcanum.Core.",
                    StringComparison.Ordinal) =>
                    "RetroDownfall.Arcanum.Core",
                _ when expectedType.StartsWith(
                    "RetroDownfall.Arcanum.Infrastructure.",
                    StringComparison.Ordinal) =>
                    "RetroDownfall.Arcanum.Infrastructure",
                _ => null,
            };

            if (owningProject is null)
            {
                return false;
            }

            CSharpCompilation[] canonical = compilationIdentities.Keys
                .OfType<CSharpCompilation>()
                .Where(compilation => compilation.AssemblyName == owningProject
                    && compilation.SyntaxTrees.Any(tree => tree.FilePath.StartsWith(
                        "src/" + owningProject + "/",
                        StringComparison.Ordinal)))
                .ToArray();

            return canonical is [CSharpCompilation exact]
                && CompilationIdentity(exact) == authoredCompilation;
        }

        private static bool IsExactFrameworkType(
            ITypeSymbol? type,
            string expectedType,
            AssemblyName trustedAssembly) =>
            type is not null
            && TypeKey(type) == expectedType
            && (FrameworkAssemblyIdentityMatches(
                    type.ContainingAssembly.Identity,
                    trustedAssembly)
                || IsReviewedSystemMemoryContractType(
                    type,
                    expectedType,
                    trustedAssembly))
            && !type.Locations.Any(static location => location.IsInSource);

        // Runtime-library types that the production reference pack declares in the System.Memory contract
        // assembly while the runtime implements them in System.Private.CoreLib. Each is reviewed by name: the
        // contract mapping above is deliberately limited to the contracts whose every type is implemented there.
        private static readonly IReadOnlySet<string> SystemMemoryContractTypes = new HashSet<string>(StringComparer.Ordinal)
        {
            "System.Text.SpanRuneEnumerator",
        };

        private static bool IsReviewedSystemMemoryContractType(
            ITypeSymbol type,
            string expectedType,
            AssemblyName trustedAssembly) =>
            trustedAssembly.Name == "System.Private.CoreLib"
            && SystemMemoryContractTypes.Contains(expectedType)
            && AssemblyIdentityMatches(
                type.ContainingAssembly.Identity,
                Assembly.Load(new AssemblyName("System.Memory")).GetName());

        private bool IsExactScopedFactoryAlias(
            InvocationExpressionSyntax registration,
            SemanticModel model,
            INamedTypeSymbol implementation)
        {
            if (registration.ArgumentList.Arguments is not [ArgumentSyntax argument]
                || argument.Expression is not AnonymousFunctionExpressionSyntax factory
                || factory switch
                {
                    SimpleLambdaExpressionSyntax simple => simple.ExpressionBody,
                    ParenthesizedLambdaExpressionSyntax parenthesized =>
                        parenthesized.ExpressionBody,
                    _ => null,
                } is not InvocationExpressionSyntax resolution
                || model.GetSymbolInfo(resolution).Symbol is not IMethodSymbol resolver
                || !IsExactFrameworkMethod(
                    resolver,
                    "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions",
                    "GetRequiredService",
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
                || resolver.TypeArguments.Length != 1
                || !SameBoundType(
                    resolver.TypeArguments[0],
                    model.Compilation,
                    implementation,
                    model.Compilation)
                || resolution.Expression is not MemberAccessExpressionSyntax access
                || model.GetSymbolInfo(access.Expression).Symbol is not { } provider
                || factory switch
                {
                    SimpleLambdaExpressionSyntax simple =>
                        model.GetDeclaredSymbol(simple.Parameter),
                    ParenthesizedLambdaExpressionSyntax
                    {
                        ParameterList.Parameters: [ParameterSyntax parameter],
                    } => model.GetDeclaredSymbol(parameter),
                    _ => null,
                } is not { } factoryProvider
                || !SymbolEqualityComparer.Default.Equals(provider, factoryProvider))
            {
                return false;
            }

            InvocationExpressionSyntax collectionRegistration = registration;

            if (model.GetSymbolInfo(registration).Symbol is
                    IMethodSymbol descriptorFactory
                && descriptorFactory.Name == "Scoped"
                && IsExactFrameworkMethod(
                    descriptorFactory,
                    "Microsoft.Extensions.DependencyInjection.ServiceDescriptor",
                    "Scoped",
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
                && registration.Ancestors().OfType<ArgumentSyntax>()
                    .FirstOrDefault()?.Parent?.Parent is
                        InvocationExpressionSyntax enclosing
                && model.GetSymbolInfo(enclosing).Symbol is
                    IMethodSymbol collectionMethod
                && IsExactServiceDescriptorCollectionAdd(collectionMethod))
            {
                collectionRegistration = enclosing;
            }

            SyntaxNode? containingMember = registration.Ancestors()
                .FirstOrDefault(static ancestor => ancestor is BaseMethodDeclarationSyntax
                    or LocalFunctionStatementSyntax);

            ExpressionSyntax? serviceCollection = collectionRegistration.Expression is
                MemberAccessExpressionSyntax registrationAccess
                    ? registrationAccess.Expression
                    : null;

            ISymbol? serviceCollectionSymbol = serviceCollection is null
                ? null
                : model.GetSymbolInfo(serviceCollection).Symbol;

            ExpressionStatementSyntax? registrationStatement = collectionRegistration
                .Ancestors()
                .OfType<ExpressionStatementSyntax>()
                .FirstOrDefault();

            BlockSyntax? registrationBlock = registrationStatement?.Parent as BlockSyntax;

            if (containingMember is null
                || serviceCollectionSymbol is null
                || registrationStatement is null
                || registrationBlock is null)
            {
                return false;
            }

            InvocationExpressionSyntax[] concreteRegistrations = invocations
                .Where(candidate => candidate.Call != registration
                    && candidate.Call.Ancestors().FirstOrDefault(static ancestor =>
                        ancestor is BaseMethodDeclarationSyntax
                            or LocalFunctionStatementSyntax) == containingMember
                    && candidate.Model.GetSymbolInfo(candidate.Call).Symbol is
                        IMethodSymbol method
                    && candidate.Call.Ancestors()
                        .OfType<ExpressionStatementSyntax>()
                        .FirstOrDefault()?.Parent == registrationBlock
                    && IsExactFrameworkMethod(
                        method,
                        "Microsoft.Extensions.DependencyInjection.ServiceCollectionServiceExtensions",
                        "AddScoped",
                        "Microsoft.Extensions.DependencyInjection.Abstractions")
                    && method.TypeArguments.Length == 1
                    && SameBoundType(
                        method.TypeArguments[0],
                        candidate.Model.Compilation,
                        implementation,
                        model.Compilation)
                    && candidate.Call.ArgumentList.Arguments.Count == 0
                    && candidate.Call.Expression is MemberAccessExpressionSyntax candidateAccess
                    && SymbolEqualityComparer.Default.Equals(
                        candidate.Model.GetSymbolInfo(candidateAccess.Expression).Symbol,
                        serviceCollectionSymbol))
                .Select(static candidate => candidate.Call)
                .ToArray();

            return concreteRegistrations is [InvocationExpressionSyntax concrete]
                && IsStraightLineRegistrationPair(
                    model,
                    registrationBlock,
                    registrationStatement,
                    collectionRegistration,
                    concrete,
                    serviceCollectionSymbol);
        }

        private static bool IsStraightLineRegistrationPair(
            SemanticModel model,
            BlockSyntax block,
            ExpressionStatementSyntax aliasStatement,
            InvocationExpressionSyntax aliasRegistration,
            InvocationExpressionSyntax concrete,
            ISymbol serviceCollection)
        {
            if (concrete.Ancestors().OfType<ExpressionStatementSyntax>()
                    .FirstOrDefault() is not { } concreteStatement
                || concreteStatement.Parent != block)
            {
                return false;
            }

            int aliasIndex = block.Statements.IndexOf(aliasStatement);

            int concreteIndex = block.Statements.IndexOf(concreteStatement);

            if (aliasIndex < 0 || concreteIndex < 0)
            {
                return false;
            }

            int first = Math.Min(aliasIndex, concreteIndex);

            int last = Math.Max(aliasIndex, concreteIndex);

            return block.Statements
                .Skip(first)
                .Take(last - first + 1)
                .All(statement => statement is ExpressionStatementSyntax
                {
                    Expression: InvocationExpressionSyntax call,
                }
                    && model.GetSymbolInfo(call).Symbol is IMethodSymbol method
                    && (IsExactFrameworkMethod(
                            method,
                            "Microsoft.Extensions.DependencyInjection.ServiceCollectionServiceExtensions",
                            "AddScoped",
                            "Microsoft.Extensions.DependencyInjection.Abstractions")
                        || ReferenceEquals(statement, aliasStatement)
                            && ReferenceEquals(call, aliasRegistration)
                            && IsExactServiceDescriptorCollectionAdd(method))
                    && call.Expression is MemberAccessExpressionSyntax access
                    && SymbolEqualityComparer.Default.Equals(
                        model.GetSymbolInfo(access.Expression).Symbol,
                        serviceCollection));
        }

        private object? ConstantRecoveryHandlerProperty(
            AuthoredMember handler,
            string propertyName)
        {
            IPropertySymbol[] properties = handler.Symbol.ContainingType
                .GetMembers(propertyName)
                .OfType<IPropertySymbol>()
                .ToArray();

            if (properties is not [IPropertySymbol property]
                || property.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax() is not
                    PropertyDeclarationSyntax declaration)
            {
                return null;
            }

            ExpressionSyntax? expression = declaration.ExpressionBody?.Expression
                ?? declaration.Initializer?.Value
                ?? declaration.AccessorList?.Accessors
                    .SingleOrDefault(static accessor => accessor.IsKind(SyntaxKind.GetAccessorDeclaration))
                    ?.ExpressionBody?.Expression
                ?? declaration.AccessorList?.Accessors
                    .SingleOrDefault(static accessor => accessor.IsKind(SyntaxKind.GetAccessorDeclaration))
                    ?.Body?.Statements
                    .OfType<ReturnStatementSyntax>()
                    .SingleOrDefault()
                    ?.Expression;

            if (expression is null
                || !semanticModels.TryGetValue(expression.SyntaxTree, out SemanticModel? model)
                || model.GetConstantValue(expression) is not
                {
                    HasValue: true,
                } constant)
            {
                return null;
            }

            return constant.Value;
        }

        private string? RecoveryEffectFrontierAt(
            AuthoredMember member,
            InvocationExpressionSyntax dispatch,
            string operationId,
            string? work)
        {
            TryStatementSyntax? protector = dispatch.Ancestors()
                .OfType<TryStatementSyntax>()
                .FirstOrDefault(candidate => candidate.Block.Span.Contains(dispatch.Span)
                    && candidate.Finally is not null);

            IfStatementSyntax? gate = dispatch.Ancestors()
                .OfType<IfStatementSyntax>()
                .FirstOrDefault(candidate => candidate.Else?.Statement.Span.Contains(dispatch.Span)
                    == true);

            if (protector?.Finally is not { } finalizer
                || gate?.Condition is not BinaryExpressionSyntax condition
                || !condition.IsKind(SyntaxKind.LogicalAndExpression)
                || !TryMatchRecoveryDisposition(
                    member.Model,
                    condition.Left,
                    "OrdinaryExternalEffect",
                    negated: false,
                    out _)
                || condition.Right is not PrefixUnaryExpressionSyntax refusal
                || !refusal.IsKind(SyntaxKind.LogicalNotExpression)
                || refusal.Operand is not InvocationExpressionSyntax admission
                || member.Model.GetSymbolInfo(admission).Symbol is not IMethodSymbol admissionMethod
                || Normalize(admissionMethod)
                    != "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease.TryBeginExternalEffectGroup"
                || admission.ArgumentList.Arguments.LastOrDefault()?.Expression is not { } outExpression)
            {
                return null;
            }

            SingleVariableDesignationSyntax? designation = outExpression
                .DescendantNodesAndSelf()
                .OfType<SingleVariableDesignationSyntax>()
                .SingleOrDefault();

            ISymbol? group = designation is null
                ? member.Model.GetSymbolInfo(outExpression).Symbol
                : member.Model.GetDeclaredSymbol(designation);

            if (group is null)
            {
                return null;
            }

            AssignmentExpressionSyntax[] writes = member.Syntax.DescendantNodes()
                .OfType<AssignmentExpressionSyntax>()
                .Where(assignment => SymbolEqualityComparer.Default.Equals(
                    member.Model.GetSymbolInfo(assignment.Left).Symbol,
                    group))
                .ToArray();

            InvocationExpressionSyntax[] cleanups = finalizer.Block.DescendantNodes()
                .OfType<InvocationExpressionSyntax>()
                .Where(call => AdmissionReceiver(member, call) is { } receiver
                    && SymbolEqualityComparer.Default.Equals(
                        member.Model.GetSymbolInfo(receiver).Symbol,
                        group)
                    && member.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method
                    && method.Name is "Dispose" or "DisposeAsync")
                .ToArray();

            if (writes.Length != 0
                || cleanups is not [InvocationExpressionSyntax cleanup]
                || member.Model.GetSymbolInfo(cleanup).Symbol is not IMethodSymbol cleanupMethod
                || cleanupMethod.Name == "DisposeAsync"
                    && CompletionPoint(member, cleanup, false) is null
                || cleanupMethod.Name == "Dispose"
                    && TypeKey(cleanupMethod.ReturnType) != "System.Void"
                || cleanup.Ancestors()
                    .TakeWhile(ancestor => ancestor != finalizer)
                    .OfType<IfStatementSyntax>()
                    .Any(guard => guard.Condition is not IsPatternExpressionSyntax
                    {
                        Expression: { } tested,
                        Pattern: UnaryPatternSyntax
                        {
                            Pattern: ConstantPatternSyntax
                            {
                                Expression.RawKind: (int)SyntaxKind.NullLiteralExpression,
                            },
                        },
                    }
                        || !SymbolEqualityComparer.Default.Equals(
                            member.Model.GetSymbolInfo(tested).Symbol,
                            group))
                || AdmissionEndedBefore(
                    member,
                    Location(admission),
                    dispatch.SpanStart,
                    []))
            {
                return null;
            }

            // CK-3: the recovery effect is the shell's own acquisition, never a lease the shell was handed or took twice.
            if (!LeaseReceiverIsOwnAcquisition(member, admission, work))
            {
                RefuseTraversalCompletion();

                diagnostics.Add(LeaseReceiverMismatch(operationId, admission));

                return null;
            }

            return RootOperation(operationId)
                + "@effect:"
                + Location(admission);
        }

        private bool RuntimeRecoveryDispatchRejectsNonGenericTuples(
            IReadOnlySet<TraversalStateIdentity> active,
            SyntaxNode anchor)
        {
            AuthoredMember[] candidates = AuthoredMembers
                .Where(static member => member.Symbol.Name == "SettleDiscoveredRuntimeAsync")
                .Where(member => TypeKey(member.Symbol.ContainingType)
                    == "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationReconciler")
                .Where(member => active.Any(state =>
                    state.Member == MemberIdentity(member)))
                .ToArray();

            if (candidates is not [AuthoredMember method])
            {
                RefuseTraversalCompletion();

                diagnostics.Add(new(
                    "HOSTED_RECOVERY_DISPATCH_UNPROVEN",
                    Location(anchor),
                    "The ordinary recovery call path must pass through the one runtime settlement entry."));

                return false;
            }

            InvocationExpressionSyntax[] settlementCalls = method.Syntax
                .DescendantNodes()
                .OfType<InvocationExpressionSyntax>()
                .Where(call => method.Model.GetSymbolInfo(call).Symbol is IMethodSymbol target
                    && target.Name == "SettleLeasedAsync"
                    && SymbolEqualityComparer.Default.Equals(
                        target.ContainingType,
                        method.Symbol.ContainingType))
                .ToArray();

            if (settlementCalls is not [InvocationExpressionSyntax settlement])
            {
                RefuseTraversalCompletion();

                diagnostics.Add(new(
                    "HOSTED_RECOVERY_DISPATCH_UNPROVEN",
                    Location(method.Syntax),
                    "Generic runtime recovery must have one exact handler-settlement continuation."));

                return false;
            }

            bool HasTerminatingClassificationGuard(string disposition) =>
                method.Syntax.DescendantNodes()
                    .OfType<IfStatementSyntax>()
                    .Any(guard => guard.Span.End < settlement.SpanStart
                        && DefinitelyTerminates(guard.Statement)
                        && IsRecoveryDispositionTest(
                            method,
                            guard.Condition,
                            disposition));

            bool ownerRejected = HasTerminatingClassificationGuard(
                "OwnerBoundAwaitingExactOwner");

            bool unsupportedRejected = HasTerminatingClassificationGuard(
                "UnsupportedCheckpointVersion");

            bool supported = ownerRejected && unsupportedRejected;

            if (!supported)
            {
                RefuseTraversalCompletion();

                diagnostics.Add(new(
                    "HOSTED_RECOVERY_DISPATCH_UNPROVEN",
                    Location(method.Syntax),
                    "Generic runtime recovery must terminate owner-bound and unsupported classifications before handler dispatch."));
            }

            return supported;
        }

        private bool ReadinessRecoveryDispatchRejectsNonGenericTuples(
            IReadOnlySet<TraversalStateIdentity> active,
            SyntaxNode anchor)
        {
            AuthoredMember[] methods = AuthoredMembers
                .Where(static member => member.Symbol.Name == "ReconcileAsync")
                .Where(member => TypeKey(member.Symbol.ContainingType)
                    == "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationReconciler")
                .ToArray();

            if (methods is not [AuthoredMember method]
                || !active.Any(state => state.Member == MemberIdentity(method)))
            {
                RefuseTraversalCompletion();

                diagnostics.Add(new(
                    "HOSTED_RECOVERY_DISPATCH_UNPROVEN",
                    Location(anchor),
                    "The readiness recovery call path must pass through the one bounded reconciliation entry."));

                return false;
            }

            AuthoredMember[] settlers = AuthoredMembers
                .Where(static member => member.Symbol.Name == "SettleAsync")
                .Where(member => member.Syntax.Ancestors().Contains(method.Syntax))
                .ToArray();

            if (settlers is not [AuthoredMember settle]
                || !active.Any(state => state.Member == MemberIdentity(settle)))
            {
                RefuseTraversalCompletion();

                diagnostics.Add(new(
                    "HOSTED_RECOVERY_DISPATCH_UNPROVEN",
                    Location(anchor),
                    "Readiness reconciliation must enter its one closed per-operation settlement function."));

                return false;
            }

            InvocationExpressionSyntax[] handlerSettlements = settle.Syntax
                .DescendantNodes()
                .OfType<InvocationExpressionSyntax>()
                .Where(call => settle.Model.GetSymbolInfo(call).Symbol is IMethodSymbol target
                    && target.Name == "SettleLeasedAsync"
                    && SymbolEqualityComparer.Default.Equals(
                        target.ContainingType,
                        method.Symbol.ContainingType))
                .ToArray();

            if (handlerSettlements is not [InvocationExpressionSyntax handlerSettlement])
            {
                RefuseTraversalCompletion();

                diagnostics.Add(new(
                    "HOSTED_RECOVERY_DISPATCH_UNPROVEN",
                    Location(settle.Syntax),
                    "Readiness reconciliation must have one exact handler-settlement continuation."));

                return false;
            }

            foreach (LocalDeclarationStatementSyntax declaration in settle.Syntax
                .DescendantNodes()
                .OfType<LocalDeclarationStatementSyntax>())
            {
                if (declaration.Declaration.Variables is not
                    [VariableDeclaratorSyntax
                    {
                        Initializer.Value: InvocationExpressionSyntax classification,
                    } variable]
                    || settle.Model.GetDeclaredSymbol(variable) is not ILocalSymbol decision
                    || settle.Model.GetSymbolInfo(classification).Symbol is not IMethodSymbol
                    {
                        Name: "Classify",
                    } classifier
                    || TypeKey(classifier.ContainingType)
                        != "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationRecoveryAdmission")
                {
                    continue;
                }

                bool MatchesDecision(
                    ExpressionSyntax expression,
                    string disposition,
                    bool negated) =>
                    IsRecoveryDispositionTest(
                        settle,
                        expression,
                        disposition,
                        negated);

                bool ownerRejected = settle.Syntax.DescendantNodes()
                    .OfType<IfStatementSyntax>()
                    .Any(guard => guard.SpanStart > declaration.Span.End
                        && guard.Span.End < handlerSettlement.SpanStart
                        && DefinitelyTerminates(guard.Statement)
                        && MatchesDecision(
                            guard.Condition,
                            "OwnerBoundAwaitingExactOwner",
                            negated: false));

                bool unsupportedRejected = handlerSettlement.Ancestors()
                    .OfType<ConditionalExpressionSyntax>()
                    .Any(conditional => conditional.WhenFalse.Span.Contains(handlerSettlement.Span)
                        && MatchesDecision(
                            conditional.Condition,
                            "UnsupportedCheckpointVersion",
                            negated: false));

                if (ownerRejected && unsupportedRejected)
                {
                    return true;
                }
            }

            RefuseTraversalCompletion();

            diagnostics.Add(new(
                "HOSTED_RECOVERY_DISPATCH_UNPROVEN",
                Location(settle.Syntax),
                "Readiness reconciliation must reject owner-bound and unsupported classifications before handler dispatch."));

            return false;
        }

        private TraversalEvidence TraverseRecoveryDispatch(
            AuthoredMember caller,
            InvocationExpressionSyntax call,
            IMethodSymbol contractMethod,
            string rootType,
            string operationId,
            HashSet<TraversalStateIdentity> active,
            bool lifecycle,
            string? workAdmitted,
            string? recoveryEffect)
        {
            RecoveryMatrix matrix = ResolveRecoveryMatrix(call);

            string rootOperation = RootOperation(operationId);

            HostedProducerOperationEntry[] roots = declaredOperations
                .Where(operation => operation.OperationId == rootOperation)
                .ToArray();

            if (!matrix.IsValid)
            {
                return TraversalEvidence.Inconclusive;
            }

            if (roots is not [HostedProducerOperationEntry root])
            {
                RefuseTraversalCompletion();

                diagnostics.Add(new(
                    "HOSTED_RECOVERY_AUTHORITY_UNPROVEN",
                    operationId,
                    "Recovery-handler dispatch must originate from one declared authority root."));

                return TraversalEvidence.Inconclusive;
            }

            RecoveryHandlerTarget[] targets = ResolveRecoveryHandlerTargets(
                caller,
                contractMethod,
                call,
                matrix);

            if (LaunchGapRecoveryDispatchIsExact(
                    caller,
                    call,
                    allowLegacyFallback: root.Authority ==
                        HostedProducerAuthorityKind.OwnerBoundRecovery))
            {
                if (root.Authority != HostedProducerAuthorityKind.OwnerBoundRecovery)
                {
                    // The exact launch-gap dispatcher is the authority handoff. Its own declared
                    // owner-recovery root traverses both DI compositions and owns their effects;
                    // bootstrap callers only need evidence that they reach this closed handoff.
                    return TraversalEvidence.Evidence;
                }

                return TraverseComposedOwnerRecoveryDispatch(
                    caller,
                    call,
                    rootType,
                    operationId,
                    active,
                    lifecycle,
                    matrix,
                    targets,
                    "launch-gap-recovery",
                    "RecoverAsync");
            }

            if (OwnerRecoveryDispatchIsExact(active, out string exactnessFailure))
            {
                if (root.Authority != HostedProducerAuthorityKind.OwnerBoundRecovery)
                {
                    // SettleExactlyAsync is the authority handoff. The canonical owner-recovery
                    // root below traverses every owner-only handler and closes the matrix over every
                    // tuple; re-attributing those same handlers to each bootstrap caller both gives
                    // their effects the wrong owner and multiplies the graph until its safety cap.
                    return TraversalEvidence.Evidence;
                }

                return TraverseOwnerRecoveryDispatch(
                    caller,
                    call,
                    rootType,
                    operationId,
                    active,
                    lifecycle,
                    matrix,
                    targets);
            }

            if (root.Authority == HostedProducerAuthorityKind.OwnerBoundRecovery)
            {
                RefuseTraversalCompletion();

                diagnostics.Add(new(
                    "HOSTED_RECOVERY_OWNER_DISPATCH_UNPROVEN",
                    operationId,
                    "Exact-owner recovery must reach the shared handler only through SettleExactlyAsync after owner evidence classifies the operation as OwnerBoundOffline; "
                        + exactnessFailure
                        + "."));

                return TraversalEvidence.Inconclusive;
            }

            if (root.Authority is not HostedProducerAuthorityKind.OrdinaryHostedWork
                and not HostedProducerAuthorityKind.PreReadinessStartup)
            {
                RefuseTraversalCompletion();

                diagnostics.Add(new(
                    "HOSTED_RECOVERY_AUTHORITY_UNPROVEN",
                    operationId,
                    "Generic recovery-handler dispatch requires readiness or ordinary-work authority; owner-only dispatch requires authenticated owner evidence."));

                return TraversalEvidence.Inconclusive;
            }

            bool genericDispatchProven = root.Authority switch
            {
                HostedProducerAuthorityKind.OrdinaryHostedWork =>
                    RuntimeRecoveryDispatchRejectsNonGenericTuples(active, call),
                HostedProducerAuthorityKind.PreReadinessStartup =>
                    ReadinessRecoveryDispatchRejectsNonGenericTuples(active, call),
                _ => true,
            };

            if (!genericDispatchProven)
            {
                return TraversalEvidence.Inconclusive;
            }

            TraversalEvidence evidence = TraversalEvidence.NoEvidence;

            foreach (RecoveryHandlerTarget target in targets
                .Where(static target => target.Composition.HasFlag(
                    RecoveryCompositionKind.Serving)))
            {
                RecoveryDescriptor? descriptor = matrix.Descriptors
                    .SingleOrDefault(candidate => candidate.Kind == target.Kind);

                if (descriptor is null)
                {
                    continue;
                }

                foreach (RecoveryTuple tuple in matrix.Tuples.Where(tuple =>
                    tuple.Kind == target.Kind
                    && tuple.CheckpointVersion
                        <= target.SupportedCheckpointVersion
                    && tuple.Disposition is RecoveryDisposition.OrdinaryDbOnly
                        or RecoveryDisposition.OrdinaryExternalEffect
                        or RecoveryDisposition.OrdinaryPerUnitExternalEffect))
                {
                    IParameterSymbol? operation = target.Member.Symbol.Parameters
                        .SingleOrDefault(parameter => TypeKey(parameter.Type)
                            == "RetroDownfall.Arcanum.Core.Operations.LongRunningOperation");

                    if (operation is null)
                    {
                        RefuseTraversalCompletion();

                        diagnostics.Add(new(
                            "HOSTED_RECOVERY_HANDLER_UNPROVEN",
                            Location(target.Member.Syntax),
                            TypeKey(target.Member.Symbol.ContainingType)
                                + "; RecoverAsync must receive one exact durable operation."));

                        continue;
                    }

                    if (root.Authority == HostedProducerAuthorityKind.OrdinaryHostedWork
                        && tuple.Disposition == RecoveryDisposition.OrdinaryExternalEffect
                        && recoveryEffect is null)
                    {
                        RefuseTraversalCompletion();

                        diagnostics.Add(new(
                            "HOSTED_RECOVERY_EFFECT_FRONTIER_UNPROVEN",
                            operationId + "/recovery@" + tuple.Kind + ":" + tuple.CheckpointVersion,
                            "Ordinary external-effect recovery must retain the conditional effect frontier through its exact handler."));
                    }

                    AuthoredMember bound = BindAdmissionArguments(
                        caller,
                        call,
                        target.Member);

                    Dictionary<ISymbol, RecoveryTuple> bindings = bound.RecoveryBindings is null
                        ? new(SymbolEqualityComparer.Default)
                        : new(bound.RecoveryBindings, SymbolEqualityComparer.Default);

                    bindings[operation] = tuple;

                    bound = bound with
                    {
                        RecoveryBindings = bindings,
                        RecoveryContext = tuple,
                    };

                    string? handlerWork = workAdmitted;

                    if (tuple.Disposition == RecoveryDisposition.OrdinaryPerUnitExternalEffect)
                    {
                        if (!TryBindPerUnitRecoveryHandoff(caller, call, target, tuple,
                                rootType, operationId, workAdmitted, bound, out AuthoredMember perUnit)
                            && !(workAdmitted is null && root.Authority == HostedProducerAuthorityKind.PreReadinessStartup
                                && TryBindReadinessRecoverySource(caller, call, target, bound, out perUnit)))
                        {
                            RefuseTraversalCompletion();

                            diagnostics.Add(new(
                                "HOSTED_RECOVERY_PER_UNIT_HANDOFF_UNPROVEN",
                                operationId + "/recovery@" + tuple.Kind + ":" + tuple.CheckpointVersion,
                                "Per-unit recovery must retain the exact acquired lease through its bound instance and physical-send groups."));

                            handlerWork = null;
                        }
                        else
                        {
                            bound = perUnit;
                        }
                    }

                    TraversalEvidence targetEvidence = Traverse(
                        bound,
                        rootType,
                        operationId
                            + "/recovery@"
                            + Uri.EscapeDataString(tuple.Kind)
                            + ":"
                            + tuple.CheckpointVersion
                            + "/call@"
                            + Location(call),
                        active,
                        lifecycle,
                        handlerWork,
                        root.Authority == HostedProducerAuthorityKind.OrdinaryHostedWork
                            && tuple.Disposition == RecoveryDisposition.OrdinaryExternalEffect
                            ? recoveryEffect
                            : null,
                        completionOwned: true,
                        recoveryEffect: tuple.Disposition == RecoveryDisposition.OrdinaryPerUnitExternalEffect
                            ? null
                            : recoveryEffect);

                    evidence = MergeEvidence(evidence, targetEvidence);
                }
            }

            return evidence;
        }

        // These are immutable facts about the admitted source graph. They are never a
        // runtime admission certificate and never replace the full value/work context.
        private HashSet<BoundTypeIdentity>? perUnitProtectedSourceTypes;

        private readonly HashSet<RecoveryCompositionKind> perUnitUnprovenCompositions = [];

        private readonly Dictionary<InvocationExpressionSyntax, (RecoveryCompositionKind Proven, RecoveryCompositionKind Unproven)>
            perUnitRegistrationExecution = new(ReferenceEqualityComparer.Instance);

        private bool perUnitSourceClosureComplete;

        private sealed record PerUnitHolderSource(
            AuthoredMember Bind,
            IPropertySymbol Getter,
            IFieldSymbol Storage);

        private sealed record PerUnitMaterializationSource(
            AuthoredMember Constructor,
            IParameterSymbol Handlers,
            InvocationExpressionSyntax Services,
            AssignmentExpressionSyntax Store);

        private sealed record PerUnitHandoffSource(
            AuthoredMember Origin,
            InvocationExpressionSyntax Acquisition,
            InvocationExpressionSyntax Binding,
            ExpressionSyntax Receiver,
            PerUnitHolderSource Holder,
            bool Scoped);

        private sealed record OrdinaryScopedHolderConsumerSource(
            AuthoredMember Constructor,
            IParameterSymbol HolderSlot,
            PerUnitHolderSource Holder);

        private readonly Dictionary<BoundTypeIdentity, OrdinaryScopedHolderConsumerSource>
            ordinaryScopedHolderConsumers = [];

        private readonly Dictionary<GraphMemberIdentity, bool> ordinaryScopedHolderDemands = [];

        private readonly Dictionary<(GraphMemberIdentity Member, int Environment, SyntaxTree Tree,
            int Position, string Operation, GrimoireWorkKind Kind), OrdinaryScopedHolderWitness?>
            ordinaryScopedHolderWitnesses = [];

        private string? ReadinessSourceIdentity(AuthoredMember member, SyntaxNode source, CleanupProvenanceContext proof)
        {
            if (proof.RemainingWork-- <= 0) return null;

            EvaluationEnvironmentFingerprint environment = EvaluationEnvironmentIdentity(member);

            return environment.Complete ? MemberIdentity(member) + "|" + Location(source) + "|" + environment.Identity : null;
        }

        private AuthoredMember BindReadinessReconcilerSource(AuthoredMember caller,
            InvocationExpressionSyntax call, AuthoredMember bound, string operationId, bool detached)
        {
            if (detached) return bound with { ReadinessSource = null };

            if (caller.ReadinessSource is { } inherited
                && SameBoundType(caller.Symbol.ContainingType, caller.Model.Compilation,
                    bound.Symbol.ContainingType, bound.Model.Compilation)
                && caller.Model.GetOperation(call) is IInvocationOperation invocation
                && (invocation.TargetMethod.IsStatic || invocation.TargetMethod.MethodKind == MethodKind.LocalFunction
                    || invocation.Instance is IInstanceReferenceOperation))
                return bound with { ReadinessSource = inherited };

            if (PerUnitInvocationSpelling(call) != "ReconcileAsync"
                || !declaredOperations.Any(entry => entry.OperationId == RootOperation(operationId)
                    && entry.Authority == HostedProducerAuthorityKind.PreReadinessStartup)
                || !IsExactAuthoredProtocolType(bound.Symbol.ContainingType,
                    "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationReconciler", bound.Model.Compilation)) return bound;

            CleanupProvenanceContext proof = new();

            if (CompletionPoint(caller, call, inheritedCompletion: false) is null
                || AdmissionReceiver(caller, call) is not { } receiver
                || PerUnitStableLocalValue(caller, receiver, call.Span.End, proof,
                    new HashSet<ISymbol>(SymbolEqualityComparer.Default)) is not { } actual
                || ReadinessSourceIdentity(caller, call, proof) is not { } identity) return bound;

            if (actual is BaseObjectCreationExpressionSyntax creation
                && caller.Model.GetOperation(creation) is IObjectCreationOperation constructed
                && constructed.Constructor is { } constructor
                && ResolveConstructorContextTarget(constructor, caller.Model.Compilation) is { } selected)
            {
                foreach (IArgumentOperation argument in constructed.Arguments)
                {
                    if (proof.RemainingWork-- <= 0) return bound;

                    if (argument.Parameter is not { RefKind: RefKind.None } slot
                        || argument.Syntax is not ArgumentSyntax syntax || !argument.InConversion.IsIdentity
                        || slot.Type is not INamedTypeSymbol holderType) continue;

                    foreach (IMethodSymbol bind in holderType.GetMembers("Bind").OfType<IMethodSymbol>())
                    {
                        if (!TryGetPerUnitHolderSource(bind, caller.Model.Compilation, proof, out PerUnitHolderSource holder)
                            || !ReadinessDirectHolderIsFresh(caller, syntax.Expression, call, holder, proof)
                            || !PerUnitProjectedConstructorPreservesStorage(selected, holder,
                                new HashSet<IParameterSymbol>([selected.Symbol.Parameters[slot.Ordinal]], SymbolEqualityComparer.Default),
                                proof)) continue;

                        return bound with
                        {
                            ReadinessSource = new(identity, caller, call, null, selected, null,
                                selected.Symbol.Parameters[slot.Ordinal], new(caller, syntax.Expression)),
                        };
                    }
                }

                return bound;
            }

            if (actual is not InvocationExpressionSyntax resolution
                || !PerUnitServiceProvider(caller, resolution, out ExpressionSyntax scope)
                || !PerUnitScopeRetained(caller, resolution, scope, call, proof)
                || !TrySelectPerUnitScopedConstruction(bound.Symbol.ContainingType, bound.Model.Compilation, proof,
                    out ResolvedRegistration registration, out IMethodSymbol selectedConstructor, out AuthoredMember? construction)
                || construction is null
                || registration.Call.ArgumentList.Arguments is not [ArgumentSyntax { Expression: AnonymousFunctionExpressionSyntax factory }]
                || ExactFactoryCreation(factory) is not BaseObjectCreationExpressionSyntax made
                || registration.Model.GetOperation(made) is not IObjectCreationOperation selectedCreation) return bound;

            IArgumentOperation[] factories = selectedCreation.Arguments.Where(argument => argument.Parameter is { } parameter
                && IsExactFrameworkType(parameter.Type, "Microsoft.Extensions.DependencyInjection.IServiceScopeFactory",
                    typeof(Microsoft.Extensions.DependencyInjection.IServiceScopeFactory).Assembly.GetName())).ToArray();

            if (factories is not [IArgumentOperation { Parameter: { } formal, Syntax: ArgumentSyntax { Expression: InvocationExpressionSyntax supplied } }]
                || !IsExactPerUnitFactoryProvider(registration.Model, factory, supplied)
                || registration.Model.GetSymbolInfo(supplied).Symbol is not IMethodSymbol resolver
                || !IsExactFrameworkMethod(resolver, "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions",
                    "GetRequiredService", "Microsoft.Extensions.DependencyInjection.Abstractions")
                || resolver.TypeArguments is not [ITypeSymbol suppliedType]
                || !SameBoundType(suppliedType, registration.Model.Compilation, formal.Type, registration.Model.Compilation)) return bound;

            AssignmentExpressionSyntax[] stores = PerUnitVisited(construction.Syntax.DescendantNodes().OfType<AssignmentExpressionSyntax>(), proof)
                .Where(store => construction.Model.GetSymbolInfo(store.Left).Symbol is IFieldSymbol
                    { IsReadOnly: true, IsStatic: false, DeclaredAccessibility: Accessibility.Private }
                    && SymbolEqualityComparer.Default.Equals(construction.Model.GetSymbolInfo(store.Right).Symbol,
                        construction.Symbol.Parameters[formal.Ordinal])).ToArray();

            if (proof.RemainingWork <= 0 || stores is not [AssignmentExpressionSyntax stored]
                || construction.Model.GetSymbolInfo(stored.Left).Symbol is not IFieldSymbol field
                || !IsAssignedOnEverySuccessfulConstruction(construction, stored)
                || construction.Syntax is not ConstructorDeclarationSyntax { Initializer: null }
                || construction.Symbol.ContainingType.BaseType is not { } baseType
                || !IsExactFrameworkType(baseType, "System.Object", typeof(object).Assembly.GetName())) return bound;

            construction = construction with
            {
                ConstructorContexts = new HashSet<IMethodSymbol>([selectedConstructor], SymbolEqualityComparer.Default),
            };

            // Prove the selected field's complete source, not just a matching store:
            // initializers, additional writes and ref/out exposure must not replace it.
            if (!PerUnitCapturedSlotStable(construction.Symbol.Parameters[formal.Ordinal], proof)
                || ExactReadOnlyFieldValues(construction, stored.Left, field) is not [BoundValueSource fieldValue]
                || !SymbolEqualityComparer.Default.Equals(fieldValue.Caller.Symbol.OriginalDefinition,
                    construction.Symbol.OriginalDefinition)
                || !SymbolEqualityComparer.Default.Equals(fieldValue.Caller.Model.GetSymbolInfo(fieldValue.Expression).Symbol,
                    construction.Symbol.Parameters[formal.Ordinal])
                || !PerUnitSourceSymbolStable(construction, field, stored.Span.End, construction.Syntax.Span.End, proof)) return bound;

            return bound with
            {
                ReadinessSource = new(identity, caller, call, scope, construction, field, null, null),
            };
        }

        private bool ReadinessDirectHolderIsFresh(AuthoredMember caller, ExpressionSyntax value,
            InvocationExpressionSyntax dispatch, PerUnitHolderSource holder, CleanupProvenanceContext proof)
        {
            if (PerUnitStableLocalValue(caller, value, dispatch.Span.End, proof,
                    new HashSet<ISymbol>(SymbolEqualityComparer.Default)) is not BaseObjectCreationExpressionSyntax creation
                || caller.Model.GetOperation(creation) is not IObjectCreationOperation constructed
                || !SameBoundType(constructed.Type!, caller.Model.Compilation, holder.Storage.ContainingType, holder.Bind.Model.Compilation)
                || constructed.Constructor is not { IsImplicitlyDeclared: true, Parameters.Length: 0 }
                || creation.Initializer is not null
                || caller.Model.GetSymbolInfo(value).Symbol is not ILocalSymbol local
                || constructed.Constructor.ContainingType.DeclaringSyntaxReferences.FirstOrDefault() is not { } typeReference
                || typeReference.GetSyntax() is not TypeDeclarationSyntax holderDeclaration
                || !semanticModels.TryGetValue(typeReference.SyntaxTree, out SemanticModel? holderModel)
                || !PerUnitProjectedConstructorPreservesStorage(new(constructed.Constructor, holderDeclaration, holderModel),
                    holder, new HashSet<IParameterSymbol>(SymbolEqualityComparer.Default), proof)) return false;

            foreach (IdentifierNameSyntax read in PerUnitVisited(caller.Syntax.DescendantNodes().OfType<IdentifierNameSyntax>()
                .Where(read => read.SpanStart > creation.Span.End && read.SpanStart < dispatch.Span.End), proof))
            {
                if (!SymbolEqualityComparer.Default.Equals(caller.Model.GetSymbolInfo(read).Symbol, local)) continue;

                if (read != value || read.Parent is not ArgumentSyntax argument
                    || argument.Parent?.Parent is not BaseObjectCreationExpressionSyntax receiver
                    || !dispatch.Expression.Span.Contains(receiver.Span)) return false;
            }

            return proof.RemainingWork > 0;
        }

        private bool ReadinessScopeFactoryIsExact(AuthoredMember owner, ExpressionSyntax expression,
            CleanupProvenanceContext proof)
        {
            return proof.RemainingWork-- > 0 && owner.ReadinessSource is { ScopeFactoryStorage: { } field } source
                && owner.Model.GetOperation(expression) is IFieldReferenceOperation { Instance: IInstanceReferenceOperation } read
                && SymbolEqualityComparer.Default.Equals(read.Field.OriginalDefinition, field.OriginalDefinition)
                && SameBoundType(owner.Symbol.ContainingType, owner.Model.Compilation,
                    source.ReconcilerConstructor.Symbol.ContainingType, source.ReconcilerConstructor.Model.Compilation);
        }

        private bool ReadinessGetServices(AuthoredMember member, InvocationExpressionSyntax services, out ExpressionSyntax scope)
        {
            scope = null!;

            if (member.Model.GetSymbolInfo(services).Symbol is not IMethodSymbol method
                || !IsExactFrameworkMethod(method, "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions",
                    "GetServices", "Microsoft.Extensions.DependencyInjection.Abstractions")
                || method.TypeArguments is not [ITypeSymbol handler]
                || !IsExactAuthoredProtocolType(handler,
                    "RetroDownfall.Arcanum.Core.Operations.ILongRunningOperationRecoveryHandler", member.Model.Compilation)
                || services.ArgumentList.Arguments.Count != 0
                || services.Expression is not MemberAccessExpressionSyntax
                { Expression: MemberAccessExpressionSyntax { Expression: { } receiver } provider }
                || member.Model.GetSymbolInfo(provider).Symbol is not IPropertySymbol { Name: "ServiceProvider" } property
                || !IsExactFrameworkType(property.ContainingType, "Microsoft.Extensions.DependencyInjection.AsyncServiceScope",
                    typeof(Microsoft.Extensions.DependencyInjection.AsyncServiceScope).Assembly.GetName())) return false;

            scope = receiver;

            return true;
        }

        private bool TryGetReadinessDictionarySource(AuthoredMember member, ExpressionSyntax expression,
            CleanupProvenanceContext proof, HashSet<(GraphMemberIdentity, int)> path,
            out AuthoredMember origin, out InvocationExpressionSyntax services, out InvocationExpressionSyntax dispatch)
        {
            origin = null!; services = null!; dispatch = null!;

            if (proof.RemainingWork-- <= 0 || !path.Add((MemberIdentity(member), expression.SpanStart))) return false;

            try
            {
                if (member.Model.GetSymbolInfo(expression).Symbol is not (ILocalSymbol or IParameterSymbol)
                    || member.Model.GetSymbolInfo(expression).Symbol is not { } carrier
                    || !PerUnitRetainedDictionaryStable(carrier, member.Model.Compilation, proof,
                        new HashSet<ISymbol>(SymbolEqualityComparer.Default), null,
                        new HashSet<IMethodSymbol>(SymbolEqualityComparer.Default))
                    || PerUnitStableLocalValue(member, expression, expression.Span.End, proof,
                        new HashSet<ISymbol>(SymbolEqualityComparer.Default)) is not { } actual) return false;

                if (member.Model.GetSymbolInfo(actual).Symbol is IParameterSymbol { RefKind: RefKind.None } formal
                    && SymbolEqualityComparer.Default.Equals(formal.ContainingSymbol, member.Symbol)
                    && SymbolIsStableWithin(member, formal, member.Syntax.SpanStart, actual.Span.End)
                    && member.ValueBindings?.TryGetValue(formal, out BoundValueSource? source) == true)
                    return TryGetReadinessDictionarySource(source.Caller, source.Expression, proof, path,
                        out origin, out services, out dispatch);

                if (actual is not InvocationExpressionSyntax dictionary
                    || member.Model.GetSymbolInfo(dictionary).Symbol is not IMethodSymbol method
                    || !IsExactFrameworkMethod(method, "System.Linq.Enumerable", "ToDictionary", "System.Linq")
                    || dictionary.Expression is not MemberAccessExpressionSyntax { Expression: InvocationExpressionSyntax resolution }
                    || !ReadinessGetServices(member, resolution, out ExpressionSyntax scope)
                    || method.TypeArguments.Length < 1
                    || !PerUnitDictionarySelectorIsExact(member, dictionary, method.TypeArguments[0], member.Model.Compilation)
                    || expression.Parent is not ArgumentSyntax argument
                    || argument.Parent?.Parent is not InvocationExpressionSyntax settlement
                    || !PerUnitScopeRetained(member, resolution, scope, settlement, proof)) return false;

                origin = member; services = resolution; dispatch = settlement;

                return proof.RemainingWork > 0;
            }
            finally
            {
                path.Remove((MemberIdentity(member), expression.SpanStart));
            }
        }

        private bool PerUnitDictionarySelectorIsExact(AuthoredMember source, InvocationExpressionSyntax toDictionary,
            ITypeSymbol contract, Compilation contractCompilation)
        {
            return toDictionary.ArgumentList.Arguments is
                [ArgumentSyntax { Expression: AnonymousFunctionExpressionSyntax selector }, ArgumentSyntax comparer]
                && PerUnitLambdaValue(selector) is MemberAccessExpressionSyntax { Expression: { } receiver } kind
                && source.Model.GetSymbolInfo(kind).Symbol is IPropertySymbol { Name: "Kind" } property
                && SameBoundType(property.ContainingType, source.Model.Compilation, contract, contractCompilation)
                && source.Model.GetSymbolInfo(receiver).Symbol is IParameterSymbol selectedHandler
                && selector.Span.Contains(selectedHandler.DeclaringSyntaxReferences.SingleOrDefault()?.Span ?? default)
                && source.Model.GetSymbolInfo(comparer.Expression).Symbol is IPropertySymbol { Name: "Ordinal" } ordinal
                && IsExactFrameworkType(ordinal.ContainingType, "System.StringComparer", typeof(StringComparer).Assembly.GetName());
        }

        private AuthoredMember BindReadinessOwnedShell(AuthoredMember member)
        {
            if (member.ReadinessSource is not { OwnedAdmission: null, InstanceConstructor: { } constructor } source) return member;

            CleanupProvenanceContext proof = new();

            foreach (InvocationExpressionSyntax binding in PerUnitVisited(member.Syntax.DescendantNodes()
                .OfType<InvocationExpressionSyntax>().Where(call => PerUnitInvocationSpelling(call) == "Bind"), proof))
            {
                if (member.Model.GetSymbolInfo(binding).Symbol is not IMethodSymbol binder
                    || !TryGetPerUnitHolderSource(binder, member.Model.Compilation, proof, out PerUnitHolderSource holder)
                    || AdmissionReceiver(member, binding) is not { } receiver
                    || member.Model.GetSymbolInfo(receiver).Symbol is not IParameterSymbol slot
                    || !SymbolEqualityComparer.Default.Equals(slot.ContainingSymbol.OriginalDefinition, constructor.OriginalDefinition)
                    || !PerUnitCapturedSlotStable(slot, proof)
                    || binding.ArgumentList.Arguments is not [ArgumentSyntax argument]
                    || member.Model.GetSymbolInfo(argument.Expression).Symbol is not ILocalSymbol lease
                    || lease.DeclaringSyntaxReferences is not [SyntaxReference declaration]
                    || declaration.GetSyntax() is not VariableDeclaratorSyntax
                    { Initializer.Value: InvocationExpressionSyntax returned } variable
                    || variable.Parent?.Parent is not LocalDeclarationStatementSyntax
                    { AwaitKeyword.RawKind: not 0, UsingKeyword.RawKind: not 0, Parent: BlockSyntax block }
                    || member.Model.GetSymbolInfo(returned).Symbol is not IMethodSymbol acquisitionMethod
                    || !SameBoundType(acquisitionMethod.ContainingType, member.Model.Compilation,
                        holder.Storage.ContainingType, holder.Bind.Model.Compilation)
                    || AdmissionReceiver(member, returned) is not { } acquireReceiver
                    || !SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(acquireReceiver).Symbol, slot)
                    || ResolveReturnedAdmissionProofs(member, returned) is not [ReturnedAdmissionProof returnedProof]
                    || !Enum.TryParse(returnedProof.WorkKind, out GrimoireWorkKind kind)
                    || kind != GrimoireWorkKind.LongRestSweep
                    || ResolveInvocationTarget(acquisitionMethod, member, returned) is not { } acquisitionOwner) continue;

                InvocationExpressionSyntax[] origins = PerUnitVisited(acquisitionOwner.Syntax.DescendantNodes()
                    .OfType<InvocationExpressionSyntax>().Where(call => Location(call) == returnedProof.Origin), proof).ToArray();

                InvocationExpressionSyntax[] dispatches = PerUnitVisited(block.DescendantNodes().OfType<InvocationExpressionSyntax>()
                    .Where(call => call.SpanStart > binding.Span.End), proof)
                    .Where(call => member.Model.GetOperation(call) is IInvocationOperation invocation
                        && invocation.Arguments.Any(passed => passed.Parameter is { RefKind: RefKind.None }
                            && passed.Syntax is ArgumentSyntax syntax
                            && SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(syntax.Expression).Symbol, lease))
                        && CompletionPoint(member, call, inheritedCompletion: false) is not null).ToArray();

                IfStatementSyntax[] guards = PerUnitVisited(block.Statements.OfType<IfStatementSyntax>()
                    .Where(guard => guard.Span.End < variable.SpanStart), proof)
                    .Where(guard => guard.Condition is MemberAccessExpressionSyntax access
                        && SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(access.Expression).Symbol, slot)
                        && member.Model.GetSymbolInfo(access).Symbol is IPropertySymbol property
                        && ReadinessStorageObservation(property, member.Model.Compilation, holder.Storage, proof)).ToArray();

                if (proof.RemainingWork <= 0 || origins is not [InvocationExpressionSyntax acquisition]
                    || dispatches is not [InvocationExpressionSyntax dispatch]
                    || guards is not [IfStatementSyntax borrowed]
                    || member.Model.GetSymbolInfo(borrowed.Condition).Symbol is not IPropertySymbol observation
                    || block.Statements is not [ExpressionStatementSyntax cancellation, IfStatementSyntax branch,
                        LocalDeclarationStatementSyntax acquiredStatement, LocalDeclarationStatementSyntax bindingStatement,
                        StatementSyntax dispatchStatement]
                    || branch != borrowed || acquiredStatement != variable.Parent.Parent
                    || !bindingStatement.Span.Contains(binding.Span) || !dispatchStatement.Span.Contains(dispatch.Span)
                    || cancellation.Expression is not InvocationExpressionSyntax cancelled
                    || member.Model.GetOperation(cancelled) is not IInvocationOperation cancellationCall
                    || !IsExactFrameworkMethod(cancellationCall.TargetMethod, "System.Threading.CancellationToken",
                        "ThrowIfCancellationRequested", typeof(CancellationToken).Assembly.GetName().Name!)
                    || cancellationCall.Instance is not IParameterReferenceOperation cancellationParameter
                    || !SymbolEqualityComparer.Default.Equals(cancellationParameter.Parameter.ContainingSymbol, member.Symbol)
                    || !PerUnitBindingRetained(member, binding, dispatch, proof)
                    || FindRetainedAdmission(member, binding, "TryAcquireWorkLease", kind) != returnedProof.Origin
                    || !SymbolIsStableWithin(member, lease, returned.Span.End, dispatch.Span.End)
                    || !ReadinessLeaseUsesRetained(member, lease, returned, binding, dispatch, proof)) continue;

                ReadinessOwnedAdmission own = new(member, acquisitionOwner, acquisition, binding, dispatch,
                    borrowed, observation, holder.Getter, holder.Storage, lease, slot);

                return member with
                {
                    ReadinessSource = source with
                    {
                        Identity = source.Identity + "|owned:" + Location(acquisition) + "|" + Location(binding) + "|" + Location(dispatch),
                        OwnedAdmission = own,
                    },
                };
            }

            return member;
        }

        private bool ReadinessStorageObservation(IPropertySymbol property, Compilation compilation,
            IFieldSymbol storage, CleanupProvenanceContext proof)
        {
            if (proof.RemainingWork-- <= 0 || property.IsStatic || property.IsVirtual || property.IsIndexer
                || property.Type.SpecialType != SpecialType.System_Boolean || property.SetMethod is not null
                || property.GetMethod is not { } getter || Resolve(getter, compilation) is not { } source) return false;

            ExpressionSyntax? expression = source.Syntax switch
            {
                PropertyDeclarationSyntax { ExpressionBody.Expression: { } value } => value,
                AccessorDeclarationSyntax { ExpressionBody.Expression: { } value } => value,
                ExpressionSyntax value => value,
                _ => null,
            };

            return expression is IsPatternExpressionSyntax
                { Expression: { } tested, Pattern: UnaryPatternSyntax { Pattern: ConstantPatternSyntax { Expression: LiteralExpressionSyntax literal } } }
                && literal.IsKind(SyntaxKind.NullLiteralExpression)
                && source.Model.GetOperation(tested) is IFieldReferenceOperation { Instance: IInstanceReferenceOperation } read
                && SymbolEqualityComparer.Default.Equals(read.Field, storage);
        }

        private bool ReadinessLeaseUsesRetained(AuthoredMember member, ILocalSymbol lease,
            InvocationExpressionSyntax returned, InvocationExpressionSyntax binding,
            InvocationExpressionSyntax dispatch, CleanupProvenanceContext proof)
        {
            if (CompletionPoint(member, dispatch, inheritedCompletion: false) is not { } completion) return false;

            foreach (IdentifierNameSyntax use in PerUnitVisited(member.Syntax.DescendantNodes().OfType<IdentifierNameSyntax>()
                .Where(use => use.SpanStart > returned.Span.End && use.SpanStart < completion.Span.End), proof))
            {
                if (!SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(use).Symbol, lease)) continue;

                if (use.Parent is not ArgumentSyntax { RefKindKeyword.RawKind: 0 } argument
                    || argument.Parent?.Parent is not InvocationExpressionSyntax owner
                    || owner != binding && owner != dispatch) return false;
            }

            return proof.RemainingWork > 0;
        }

        private readonly record struct ScopedAdmissionSource(
            string Identity,
            string Origin,
            IMethodSymbol? Constructor,
            IReadOnlyList<IMethodSymbol>? SelectedConstructors,
            IPropertySymbol Getter,
            IFieldSymbol Storage,
            Compilation StorageCompilation,
            IPropertySymbol? Observation,
            bool Active);

        private static ScopedAdmissionSource? ScopedAdmissionOf(AuthoredMember member)
        {
            if (member.ReadinessSource is { OwnedAdmission: not null } readiness)
                return ScopedAdmissionOf(readiness);

            if (member.OrdinaryScopedHolder is { } ordinary)
                return new(ordinary.Identity, ordinary.AdmissionOrigin, ordinary.Constructor.Symbol,
                    ordinary.SelectedConstructors, ordinary.Getter, ordinary.HolderStorage,
                    ordinary.HolderBinding.Model.Compilation, null, true);

            return null;
        }

        private static ScopedAdmissionSource? ScopedAdmissionOf(ReadinessRecoverySource source) =>
            source.OwnedAdmission is { } own
                ? new(source.Identity, Location(own.Acquisition), source.InstanceConstructor,
                    source.SelectedConstructors, own.LeaseGetter, own.HolderStorage, own.Shell.Model.Compilation,
                    own.StorageObservation, source.AdmissionActive)
                : null;

        private bool TryReadinessCapturedParameter(AuthoredMember member, ExpressionSyntax expression,
            CleanupProvenanceContext proof, out IParameterSymbol parameter)
        {
            parameter = null!;

            if (proof.RemainingWork-- <= 0
                || !TryNormalizeBuiltInCleanupValue(member.Model, expression, out ExpressionSyntax value)) return false;

            SemanticModel model = member.Model;

            if (model.GetSymbolInfo(value).Symbol is IFieldSymbol
                { IsStatic: false, IsReadOnly: true, DeclaredAccessibility: Accessibility.Private } field)
            {
                if (value is not (IdentifierNameSyntax or MemberAccessExpressionSyntax { Expression: ThisExpressionSyntax })
                    || !SymbolEqualityComparer.Default.Equals(field.ContainingType, member.Symbol.ContainingType)
                    || (member.ReadinessSource?.InstanceConstructor ?? member.OrdinaryScopedHolder?.Constructor.Symbol) is not { } selected
                    || !SymbolEqualityComparer.Default.Equals(selected.ContainingType, field.ContainingType)
                    || ExactReadOnlyFieldValues(member, value, field) is not [BoundValueSource source]
                    || !TryNormalizeBuiltInCleanupValue(source.Caller.Model, source.Expression, out value)) return false;

                model = source.Caller.Model;
            }

            if (model.GetSymbolInfo(value).Symbol is not IParameterSymbol { RefKind: RefKind.None } captured) return false;

            parameter = captured;

            return proof.RemainingWork > 0;
        }

        private bool ReadinessHolderReceiver(AuthoredMember member, ExpressionSyntax expression,
            ReadinessRecoverySource source, CleanupProvenanceContext proof,
            HashSet<(GraphMemberIdentity, int)> path)
        {
            if (ScopedAdmissionOf(source) is { } admission)
                return ScopedAdmissionHolderReceiver(member, expression, admission, proof, path);

            // Preserve the existing unsuccessful readiness receiver charge.
            proof.RemainingWork--;

            return false;
        }

        private bool ScopedAdmissionHolderReceiver(AuthoredMember member, ExpressionSyntax expression,
            ScopedAdmissionSource source, CleanupProvenanceContext proof,
            HashSet<(GraphMemberIdentity, int)> path)
        {
            if (proof.RemainingWork-- <= 0
                || !path.Add((MemberIdentity(member), expression.SpanStart))) return false;

            try
            {
                if (!TryReadinessCapturedParameter(member, expression, proof, out IParameterSymbol slot)) return false;

                if (slot.ContainingSymbol is IMethodSymbol { MethodKind: MethodKind.Constructor } constructor)
                    return source.Constructor is { } selected
                        && SymbolEqualityComparer.Default.Equals(constructor.OriginalDefinition, selected.OriginalDefinition)
                        && SameBoundType(slot.Type, member.Model.Compilation, source.Storage.ContainingType,
                            source.StorageCompilation)
                        && PerUnitCapturedSlotStable(slot, proof);

                if (member.ValueBindings?.TryGetValue(slot, out BoundValueSource? value) != true || value is null
                    || !SymbolIsStableWithin(member, slot, member.Syntax.SpanStart, expression.Span.End)) return false;

                if (value.Caller.ReadinessSource is { } readiness)
                    return readiness.Identity == source.Identity
                        && ReadinessHolderReceiver(value.Caller, value.Expression, readiness, proof, path);

                return ScopedAdmissionOf(value.Caller) is { } callerSource
                    && callerSource.Identity == source.Identity
                    && ScopedAdmissionHolderReceiver(value.Caller, value.Expression, callerSource, proof, path);
            }
            finally
            {
                path.Remove((MemberIdentity(member), expression.SpanStart));
            }
        }

        private bool ReadinessLeaseReceiver(AuthoredMember member, ExpressionSyntax expression, int through,
            ReadinessRecoverySource source, CleanupProvenanceContext proof)
        {
            return ScopedAdmissionOf(source) is { } admission
                && ScopedAdmissionLeaseReceiver(member, expression, through, admission, proof);
        }

        private bool ScopedAdmissionLeaseReceiver(AuthoredMember member, ExpressionSyntax expression, int through,
            ScopedAdmissionSource source, CleanupProvenanceContext proof)
        {
            if (PerUnitStableLocalValue(member, expression, through, proof,
                    new HashSet<ISymbol>(SymbolEqualityComparer.Default), requireBuiltInConversions: true)
                    is not MemberAccessExpressionSyntax access
                || member.Model.GetOperation(access) is not IPropertyReferenceOperation read
                || read.Property.GetMethod is not { } getter
                || Resolve(getter, member.Model.Compilation) is not { } sourceGetter
                || !SymbolEqualityComparer.Default.Equals(sourceGetter.Symbol.OriginalDefinition, source.Getter.GetMethod!.OriginalDefinition)) return false;

            return ScopedAdmissionHolderReceiver(member, access.Expression, source, proof, []);
        }

        private bool? ReadinessConditionBoolean(AuthoredMember member, ExpressionSyntax expression)
        {
            if (member.ReadinessSource is null
                && member.OrdinaryScopedHolder is not null && ScopedAdmissionOf(member) is { Active: true } ordinary
                && expression is MemberAccessExpressionSyntax ordinaryAccess
                && member.Model.GetSymbolInfo(ordinaryAccess).Symbol is IPropertySymbol ordinaryProperty)
            {
                // Prove the existing lease is still live before using its exact
                // storage observation. The lifetime proof cannot assume this
                // ordinary condition (or another ordinary condition) in return.
                CleanupProvenanceContext ordinaryProof = new() { SuppressOrdinaryStorageConditions = true };

                if (ReadinessStorageObservation(ordinaryProperty, member.Model.Compilation, ordinary.Storage, ordinaryProof)
                    && ScopedAdmissionHolderReceiver(member, ordinaryAccess.Expression, ordinary, ordinaryProof, [])
                    && !AdmissionEndedBefore(member, ordinary.Origin, expression.SpanStart, [], ordinaryProof)
                    && ordinaryProof.RemainingWork > 0) return true;

                return null;
            }

            if (member.ReadinessSource is not { } source) return null;

            CleanupProvenanceContext proof = new();

            if (expression is IsPatternExpressionSyntax
                { Expression: { } factory, Pattern: ConstantPatternSyntax { Expression: LiteralExpressionSyntax literal } }
                && literal.IsKind(SyntaxKind.NullLiteralExpression)
                && ReadinessScopeFactoryIsExact(member, factory, proof)) return false;

            if (source.OwnedAdmission is not { } own || expression is not MemberAccessExpressionSyntax access
                || member.Model.GetSymbolInfo(access).Symbol is not IPropertySymbol property
                || !SymbolEqualityComparer.Default.Equals(property.OriginalDefinition, own.StorageObservation.OriginalDefinition)
                || !ReadinessHolderReceiver(member, access.Expression, source, proof, [])) return null;

            if (source.AdmissionActive) return true;

            return MemberIdentity(member) == MemberIdentity(own.Shell)
                && expression.SyntaxTree == own.BorrowedBranch.Condition.SyntaxTree
                && expression.Span == own.BorrowedBranch.Condition.Span ? false : null;
        }

        private bool ReadinessScopeResolutionHistoryIsComplete(AuthoredMember origin, ExpressionSyntax scope,
            InvocationExpressionSyntax services, InvocationExpressionSyntax settlement,
            IReadOnlyList<PerUnitPriorScopeResolution> priorResolutions, CleanupProvenanceContext proof)
        {
            ISymbol? scopeSymbol = origin.Model.GetSymbolInfo(scope).Symbol;

            if (scopeSymbol is null || CompletionPoint(origin, settlement, inheritedCompletion: false) is not { } completion)
                return false;

            foreach (InvocationExpressionSyntax call in PerUnitVisited(origin.Syntax.DescendantNodes()
                .OfType<InvocationExpressionSyntax>().Where(call => call.SpanStart < completion.Span.End
                    && PerUnitInvocationSpelling(call) is "GetRequiredService" or "GetServices"), proof))
            {
                if (!(PerUnitServiceProvider(origin, call, out ExpressionSyntax receiver)
                    || ReadinessGetServices(origin, call, out receiver))
                    || !SymbolEqualityComparer.Default.Equals(origin.Model.GetSymbolInfo(receiver).Symbol, scopeSymbol)) continue;

                if (call != services && !priorResolutions.Any(prior => prior.Resolution == call)) return false;
            }

            return proof.RemainingWork > 0;
        }

        private bool ReadinessPriorInstancesRemainUnobserved(IReadOnlyList<PerUnitPriorScopeResolution> exposed,
            InvocationExpressionSyntax settlement, CleanupProvenanceContext proof,
            IReadOnlyList<ExpressionSyntax>? retainedReceivers = null)
        {
            foreach (PerUnitPriorScopeResolution prior in exposed)
            {
                if (prior.Result is null) continue;

                if (CompletionPoint(prior.Origin, settlement, inheritedCompletion: false) is not { } completion) return false;

                foreach (IdentifierNameSyntax read in PerUnitVisited(prior.Origin.Syntax.DescendantNodes()
                    .OfType<IdentifierNameSyntax>().Where(read => read.SpanStart > prior.Resolution.Span.End
                        && read.SpanStart < completion.Span.End && read.Identifier.ValueText == prior.Result.Name), proof))
                {
                    if (SymbolEqualityComparer.Default.Equals(prior.Origin.Model.GetSymbolInfo(read).Symbol, prior.Result)
                        && retainedReceivers?.Any(receiver => receiver.SyntaxTree == read.SyntaxTree && receiver.Span == read.Span) != true)
                        return false;
                }
            }

            return proof.RemainingWork > 0;
        }

        private bool TryBindReadinessRecoverySource(AuthoredMember caller, InvocationExpressionSyntax call,
            RecoveryHandlerTarget target, AuthoredMember bound, out AuthoredMember authenticated)
        {
            authenticated = bound;

            if (caller.ReadinessSource is not { } route) return false;

            CleanupProvenanceContext proof = new();

            if (route.DirectHolder is { } direct && route.DirectHolderSlot is { } reconcilerSlot)
            {
                if (AdmissionReceiver(caller, call) is not { } receiver
                    || PerUnitStableLocalValue(caller, receiver, call.Span.End, proof,
                        new HashSet<ISymbol>(SymbolEqualityComparer.Default)) is not BaseObjectCreationExpressionSyntax made
                    || caller.Model.GetOperation(made) is not IObjectCreationOperation constructed
                    || constructed.Constructor is not { Parameters: [IParameterSymbol { Type: INamedTypeSymbol }] } selected
                    || !SameBoundType(selected.ContainingType, caller.Model.Compilation,
                        target.Member.Symbol.ContainingType, target.Member.Model.Compilation)
                    || constructed.Arguments is not [IArgumentOperation passed]
                    || passed.ArgumentKind != ArgumentKind.Explicit || !passed.InConversion.IsIdentity
                    || passed.Parameter?.RefKind != RefKind.None
                    || !SymbolEqualityComparer.Default.Equals(passed.Parameter.OriginalDefinition,
                        selected.Parameters[0].OriginalDefinition)
                    || (passed.Syntax is ArgumentSyntax argument ? argument.Expression : passed.Value.Syntax) is not ExpressionSyntax supplied
                    || !TryNormalizeBuiltInCleanupValue(caller.Model, supplied, out ExpressionSyntax normalized)
                    || caller.Model.GetSymbolInfo(normalized).Symbol is not IParameterSymbol slot
                    || !SymbolEqualityComparer.Default.Equals(slot.OriginalDefinition, reconcilerSlot.OriginalDefinition)
                    || !PerUnitCapturedSlotStable(slot, proof)
                    || ResolveConstructorContextTarget(selected, caller.Model.Compilation) is not { } constructor) return false;

                IMethodSymbol[] binders = ((INamedTypeSymbol)selected.Parameters[0].Type).GetMembers("Bind").OfType<IMethodSymbol>().ToArray();

                if (binders is not [IMethodSymbol binder]
                    || !TryGetPerUnitHolderSource(binder, caller.Model.Compilation, proof, out PerUnitHolderSource holder)
                    || !ReadinessDirectHolderIsFresh(direct.Caller, direct.Expression, route.Dispatch, holder, proof)
                    || !PerUnitProjectedConstructorPreservesStorage(constructor, holder,
                        new HashSet<IParameterSymbol>(constructor.Symbol.Parameters, SymbolEqualityComparer.Default), proof)) return false;

                authenticated = BindReadinessOwnedShell(bound with
                {
                    ReadinessSource = route with
                    {
                        Identity = route.Identity + "|handler:" + MethodKey(constructor.Symbol),
                        SelectedConstructors = [constructor.Symbol],
                        InstanceConstructor = constructor.Symbol,
                    },
                    ConstructorContexts = new HashSet<IMethodSymbol>([constructor.Symbol], SymbolEqualityComparer.Default),
                });

                return authenticated.ReadinessSource?.OwnedAdmission is not null;
            }

            if (!TryGetPerUnitHandlerDictionary(caller, call, proof, out ExpressionSyntax dictionary)
                || !ReadinessHandlerRetained(caller, call, proof)
                || !TryGetReadinessDictionarySource(caller, dictionary, proof, [],
                    out AuthoredMember origin, out InvocationExpressionSyntax services, out InvocationExpressionSyntax settlement)
                || origin.ReadinessSource?.Identity != route.Identity
                || !ReadinessGetServices(origin, services, out ExpressionSyntax scope)
                || origin.Model.GetSymbolInfo(services).Symbol is not IMethodSymbol { TypeArguments: [ITypeSymbol contract] }
                || !TryGetPerUnitPriorScopeResolutionRoots(origin, scope, services, proof,
                    out IReadOnlyList<PerUnitPriorScopeResolution> priorResolutions)
                || !ReadinessScopeResolutionHistoryIsComplete(origin, scope, services, settlement, priorResolutions, proof)
                || !TrySelectPerUnitScopedConstruction(target.Member.Symbol.ContainingType, target.Member.Model.Compilation, proof,
                    out _, out IMethodSymbol handlerConstructor, out AuthoredMember? handlerSource)
                || handlerSource is null) return false;

            foreach (AuthoredMember candidate in PerUnitVisited(AuthoredMembers.Where(static member => member.Symbol.Name == "Bind"), proof))
            {
                if (!TryGetPerUnitHolderSource(candidate.Symbol, candidate.Model.Compilation, proof, out PerUnitHolderSource holder)
                    || !TryGetPerUnitFreshConstructionProjection(holder, contract, origin.Model.Compilation, priorResolutions, proof,
                        out IReadOnlyList<IMethodSymbol> selected, out IReadOnlyList<PerUnitPriorScopeResolution> exposedPriors)
                    || !ReadinessPriorInstancesRemainUnobserved(exposedPriors, settlement, proof)
                    || !selected.Any(constructor => SymbolEqualityComparer.Default.Equals(constructor.OriginalDefinition,
                        handlerConstructor.OriginalDefinition))) continue;

                // A source-level resolution of this holder before handler materialization
                // is a separate history. It cannot borrow this fresh construction proof.
                bool exposed = PerUnitVisited(origin.Syntax.DescendantNodes().OfType<InvocationExpressionSyntax>()
                    .Where(invocation => invocation.SpanStart < settlement.SpanStart), proof)
                    .Any(invocation => invocation != services
                        && origin.Model.GetSymbolInfo(invocation).Symbol is IMethodSymbol resolver
                        && resolver.TypeArguments.Any(type => SameBoundType(type, origin.Model.Compilation,
                            holder.Storage.ContainingType, holder.Bind.Model.Compilation))
                        && PerUnitServiceProvider(origin, invocation, out ExpressionSyntax resolvedScope)
                        && SymbolEqualityComparer.Default.Equals(origin.Model.GetSymbolInfo(resolvedScope).Symbol,
                            origin.Model.GetSymbolInfo(scope).Symbol));

                if (exposed || proof.RemainingWork <= 0
                    || !TryGetPerUnitActivationHistoryIdentity(origin, services, priorResolutions,
                        selected, proof, out string identity)) return false;

                ReadinessRecoverySource source = route with
                {
                    Identity = identity + "|handler:" + MethodKey(handlerConstructor)
                        + "|constructors:" + string.Join(";", selected.Select(MethodKey).Order(StringComparer.Ordinal)),
                    Origin = origin,
                    Dispatch = settlement,
                    Scope = scope,
                    SelectedConstructors = selected,
                    InstanceConstructor = handlerConstructor,
                };

                if (!ReadinessHandlerPropertiesPreserveStorage(source, contract, origin.Model.Compilation, proof)) return false;

                authenticated = BindReadinessOwnedShell(bound with
                {
                    ReadinessSource = source,
                    ConstructorContexts = new HashSet<IMethodSymbol>([handlerConstructor], SymbolEqualityComparer.Default),
                });

                // A forwarding handler may not own the lease itself. The exact selected
                // dependency edge below must reach the owning shell before work exists.
                return true;
            }

            return false;
        }

        // This selects only the actual current-instance or selected dependency
        // edge. It does not query work, groups, lifetime or completion, so the
        // existing lifetime walker can reuse it without recursive authority proof.
        private bool TryGetReadinessReceiverConstructor(AuthoredMember caller,
            InvocationExpressionSyntax call, AuthoredMember target, CleanupProvenanceContext proof,
            out IMethodSymbol? constructor)
        {
            constructor = null;

            IReadOnlyList<IMethodSymbol>? selected = caller.ReadinessSource?.SelectedConstructors
                ?? caller.OrdinaryScopedHolder?.SelectedConstructors;

            if (selected is null || caller.Model.GetOperation(call) is not IInvocationOperation invocation) return false;

            IMethodSymbol? current = caller.ReadinessSource?.InstanceConstructor
                ?? caller.OrdinaryScopedHolder?.Constructor.Symbol;

            constructor = null;

            if (invocation.Instance is IInstanceReferenceOperation
                && SameBoundType(caller.Symbol.ContainingType, caller.Model.Compilation,
                    target.Symbol.ContainingType, target.Model.Compilation)) constructor = current;
            else if (invocation.Instance?.Syntax is ExpressionSyntax receiver
                && TryReadinessCapturedParameter(caller, receiver, proof, out IParameterSymbol dependency)
                && current is not null
                && SymbolEqualityComparer.Default.Equals(dependency.ContainingSymbol.OriginalDefinition, current.OriginalDefinition)
                && PerUnitCapturedSlotStable(dependency, proof))
            {
                IMethodSymbol[] dependencies = selected.Where(candidate => SameBoundType(candidate.ContainingType,
                    PerUnitExactSourceCompilation(candidate.ContainingType) ?? caller.Model.Compilation,
                    target.Symbol.ContainingType, target.Model.Compilation)).ToArray();

                if (dependencies is [IMethodSymbol dependencyConstructor]
                    && PerUnitPotentialImplementations(dependency.Type, caller.Model.Compilation).Any(implementation =>
                        SameBoundType(implementation, PerUnitExactSourceCompilation(implementation) ?? caller.Model.Compilation,
                            dependencyConstructor.ContainingType, target.Model.Compilation))) constructor = dependencyConstructor;
            }

            if (constructor is not null && caller.OrdinaryScopedHolder is not null
                && invocation.Instance is not IInstanceReferenceOperation)
            {
                if (invocation.Instance?.Syntax is not ExpressionSyntax actual
                    || !TryReadinessCapturedParameter(caller, actual, proof, out IParameterSymbol slot)
                    || !TryGetPerUnitSelectedActivation(current!.ContainingType, caller.Model.Compilation, proof, [], out var owner)
                    || !SymbolEqualityComparer.Default.Equals(owner.Construction.Constructor.OriginalDefinition, current.OriginalDefinition)
                    || PerUnitVisited(owner.Chain[^1].Dependencies, proof).Where(candidate => candidate.Parameter is not null
                        && SymbolEqualityComparer.Default.Equals(candidate.Parameter.OriginalDefinition, slot.OriginalDefinition)).ToArray()
                        is not [PerUnitActivationDependency dependencyEdge]
                    || !TryGetPerUnitSelectedActivation(dependencyEdge.Contract, dependencyEdge.Compilation, proof, [], out var supplied)
                    || !SymbolEqualityComparer.Default.Equals(supplied.Construction.Constructor.OriginalDefinition, constructor.OriginalDefinition))
                    return false;
            }

            return proof.RemainingWork > 0 && constructor is not null;
        }

        private bool ReadinessCarriesHolder(AuthoredMember member, ExpressionSyntax expression, CleanupProvenanceContext proof)
        {
            if (ScopedAdmissionOf(member) is not { Active: true, Constructor: { } current,
                SelectedConstructors: { } selected } source) return false;

            if (proof.RemainingWork-- <= 0) return true;

            ExpressionSyntax candidate = StripTransparentExpression(expression);

            ISymbol? symbol = member.Model.GetSymbolInfo(candidate).Symbol;

            // None of these compiler-bound values can be a captured parameter,
            // private instance field, current instance or instance method group.
            // Only this holder query is skipped; authored execution is still visited.
            if (candidate is LiteralExpressionSyntax
                || symbol is INamespaceOrTypeSymbol
                    or IPropertySymbol { IsStatic: true }
                    or IFieldSymbol { IsStatic: true }
                    or IMethodSymbol { IsStatic: true }) return false;

            if (ScopedAdmissionHolderReceiver(member, expression, source, proof, [])) return true;

            expression = candidate;

            if (expression is ThisExpressionSyntax or BaseExpressionSyntax) return true;

            if (symbol is IMethodSymbol { IsStatic: false } methodGroup)
            {
                if (expression is MemberAccessExpressionSyntax group
                    && ReadinessCarriesHolder(member, group.Expression, proof)) return true;

                if (expression is SimpleNameSyntax
                    && SameBoundType(methodGroup.ContainingType, member.Model.Compilation,
                        member.Symbol.ContainingType, member.Model.Compilation)) return true;
            }

            if (!TryReadinessCapturedParameter(member, expression, proof, out IParameterSymbol parameter)
                || !SymbolEqualityComparer.Default.Equals(parameter.ContainingSymbol.OriginalDefinition,
                    current.OriginalDefinition)) return false;

            return selected.Any(candidate => PerUnitPotentialImplementations(parameter.Type,
                member.Model.Compilation).Any(implementation => SameBoundType(implementation,
                    PerUnitExactSourceCompilation(implementation) ?? member.Model.Compilation,
                    candidate.ContainingType, PerUnitExactSourceCompilation(candidate.ContainingType)
                        ?? member.Model.Compilation)));
        }

        private bool ReadinessHasUnsupportedHolderAccess(AuthoredMember member, string origin,
            int position, CleanupProvenanceContext proof)
        {
            if (ScopedAdmissionOf(member) is not { Active: true } source
                || source.Origin != origin) return false;

            foreach (SyntaxNode node in PerUnitVisited(member.Syntax.DescendantNodesAndSelf(node =>
                node == member.Syntax || node is not AnonymousFunctionExpressionSyntax and not LocalFunctionStatementSyntax)
                .Where(node => node.Span.End < position && node is ExpressionSyntax or VariableDeclaratorSyntax), proof))
            {
                RetainedAdmissionCounter(member).LifetimeNodeInspections++;

                if (!RecoveryNodeMayExecute(member, node,
                    includeOrdinaryStorageObservation: !proof.SuppressOrdinaryStorageConditions)) continue;

                if (node is AnonymousFunctionExpressionSyntax closure)
                {
                    foreach (ExpressionSyntax captured in PerUnitVisited(closure.DescendantNodes().OfType<ExpressionSyntax>(), proof))
                    {
                        if (ReadinessCarriesHolder(member, captured, proof)
                            || member.Model.GetOperation(captured) is IInvocationOperation { Instance: IInstanceReferenceOperation }
                                or IPropertyReferenceOperation { Instance: IInstanceReferenceOperation }) return true;
                    }
                }

                // Holder/carrier capabilities may be used only as the receiver
                // of an inspected call or property. Copies, aggregates, constructor
                // arguments, conversions and captures otherwise escape this proof.
                if (node is ExpressionSyntax expression && ReadinessCarriesHolder(member, expression, proof))
                {
                    bool receiverRead = expression.Parent is MemberAccessExpressionSyntax access
                        && access.Expression == expression
                        && (access.Parent is InvocationExpressionSyntax call && call.Expression == access
                            || member.Model.GetSymbolInfo(access).Symbol is IPropertySymbol);

                    bool methodRead = expression.Parent is InvocationExpressionSyntax invocation
                        && invocation.Expression == expression;

                    if (!receiverRead && !methodRead) return true;
                }

                if (member.Model.GetOperation(node) is not IPropertyReferenceOperation property) continue;

                if (property.Instance is IInstanceReferenceOperation) return true;

                if (property.Instance?.Syntax is not ExpressionSyntax receiver
                    || !ReadinessCarriesHolder(member, receiver, proof)) continue;

                if (!ScopedAdmissionHolderReceiver(member, receiver, source, proof, [])
                    || !SymbolEqualityComparer.Default.Equals(property.Property.OriginalDefinition, source.Getter.OriginalDefinition)
                        && !(source.Observation is { } observation
                            ? SymbolEqualityComparer.Default.Equals(property.Property.OriginalDefinition, observation.OriginalDefinition)
                            : ReadinessStorageObservation(property.Property, member.Model.Compilation, source.Storage, proof)))
                    return true;
            }

            return proof.RemainingWork <= 0;
        }

        private bool TryReadinessLifetimeCall(AuthoredMember member, InvocationExpressionSyntax call,
            string origin, HashSet<GraphMemberIdentity> path, CleanupProvenanceContext proof, out bool ended)
        {
            ended = false;

            if (ScopedAdmissionOf(member) is not { } source || source.Origin != origin) return false;

            ReadinessOwnedAdmission? own = member.ReadinessSource?.OwnedAdmission;

            bool ownDispatch = own is not null && MemberIdentity(member) == MemberIdentity(own.Shell)
                && call.SyntaxTree == own.Dispatch.SyntaxTree && call.Span == own.Dispatch.Span;

            if (!source.Active && !ownDispatch) return false;

            if (source.Active && AdmissionReceiver(member, call) is { } receiver
                && ScopedAdmissionHolderReceiver(member, receiver, source, proof, []))
            {
                ended = true;

                return true;
            }

            // A callback or method-group escape can close the lease through the
            // captured holder even if no lease appears as an explicit argument.
            foreach (ArgumentSyntax argument in call.ArgumentList.Arguments)
            {
                if (ReadinessCarriesHolder(member, argument.Expression, proof))
                {
                    ended = true;

                    return true;
                }
            }

            if (member.Model.GetSymbolInfo(call).Symbol is not IMethodSymbol method
                || ResolveInvocationTarget(method, member, call, proof) is not { } target) return false;

            if (target.ScopedLeaseInstance is { } instance && instance.Origin == origin)
            {
                ended = !instance.ContinuationProven || proof.RemainingWork <= 0;

                return true;
            }

            if (!TryGetReadinessReceiverConstructor(member, call, target, proof, out IMethodSymbol? constructor))
            {
                ended = proof.RemainingWork <= 0;

                return ended;
            }

            if (IsAwaitable(method.ReturnType)
                && CompletionPoint(member, call, inheritedCompletion: false) is null)
            {
                ended = true;

                return true;
            }

            AuthoredMember bound = BindAdmissionArguments(member, call, target);

            if (member.ReadinessSource is { } readiness)
                bound = bound with
                {
                    ReadinessSource = readiness with { InstanceConstructor = constructor, AdmissionActive = true },
                    ConstructorContexts = new HashSet<IMethodSymbol>([constructor!], SymbolEqualityComparer.Default),
                };
            else if (member.OrdinaryScopedHolder is not { } ordinary
                || !TryBindOrdinaryScopedConstructor(bound, constructor!, ordinary, proof, out bound))
            {
                ended = true;

                return true;
            }

            ended = AdmissionEndedBefore(bound, origin, int.MaxValue, path, proof);

            return true;
        }

        private AuthoredMember BindReadinessRecoveryReceiver(AuthoredMember caller, InvocationExpressionSyntax call,
            AuthoredMember target, string operationId, string? work, bool detached, SyntaxNode? completion)
        {
            AuthoredMember refused = target with { ReadinessSource = null };

            if (detached || completion is null
                || caller.ReadinessSource is not { SelectedConstructors: { } } source) return refused;

            CleanupProvenanceContext proof = new();

            _ = TryGetReadinessReceiverConstructor(caller, call, target, proof, out IMethodSymbol? constructor);

            // A joined helper that does not receive this holder may retain the work
            // and group history, but receives no selected holder-instance context.
            if ((constructor is null && !source.AdmissionActive) || proof.RemainingWork <= 0) return refused;

            if (!source.AdmissionActive && source.OwnedAdmission is null
                && !ReadinessFreshInstanceUntil(caller, call, call.Span.End, proof, [])) return refused;

            bool active = source.AdmissionActive;

            if (!active && source.OwnedAdmission is { } own
                && call.SyntaxTree == own.Dispatch.SyntaxTree && call.Span == own.Dispatch.Span
                && MemberIdentity(caller) == MemberIdentity(own.Shell)) active = true;

            if (active && source.OwnedAdmission is { } retainedWork
                && work != RootOperation(operationId) + "@work:" + Location(retainedWork.Acquisition)) return refused;

            AuthoredMember bound = target with
            {
                ReadinessSource = source with { InstanceConstructor = constructor, AdmissionActive = active },
                ConstructorContexts = constructor is null ? target.ConstructorContexts
                    : new HashSet<IMethodSymbol>([constructor], SymbolEqualityComparer.Default),
            };

            string? groupLocation = FindRetainedAdmission(caller, call, "TryBeginExternalEffectGroup", null);

            bool localGroupCompletion = !IsAwaitable(target.Symbol.ReturnType) || completion is AwaitExpressionSyntax;

            if (groupLocation is not null && !localGroupCompletion)
                bound = bound with
                {
                    ReadinessSource = bound.ReadinessSource! with
                    {
                        GroupOwner = null,
                        GroupFrontier = null,
                        GroupIdentity = null,
                    },
                };

            if (active && localGroupCompletion && completion is not null && groupLocation is not null
                && FindRetainedAdmission(caller, completion, "TryBeginExternalEffectGroup", null) == groupLocation
                && caller.ReadinessSource?.OwnedAdmission is { } retained
                && !AdmissionEndedBefore(caller, Location(retained.Acquisition), completion.SpanStart, []))
            {
                InvocationExpressionSyntax[] groups = AdmissionSyntax(caller).AdmissionCalls
                    .Where(group => Location(group) == groupLocation).ToArray();

                if (groups is [InvocationExpressionSyntax group]
                    && ReadinessSourceIdentity(caller, group, proof) is { } groupIdentity)
                    bound = bound with
                    {
                        ReadinessSource = bound.ReadinessSource! with
                        {
                            GroupOwner = caller,
                            GroupFrontier = group,
                            GroupIdentity = groupIdentity,
                        },
                    };
            }

            return BindReadinessOwnedShell(bound);
        }

        private string? ReadinessWorkAt(AuthoredMember member, SyntaxNode site, string operationId, int? position)
        {
            if (member.ReadinessSource is not { OwnedAdmission: { } own } source) return null;

            int through = position ?? site.SpanStart;

            if (!source.AdmissionActive && (MemberIdentity(member) != MemberIdentity(own.Shell)
                || site.SyntaxTree != own.Binding.SyntaxTree || through <= own.Binding.Span.End
                || CompletionPoint(own.Shell, own.Dispatch, inheritedCompletion: false) is not { } completion
                || through > completion.Span.End)) return null;

            string origin = Location(own.Acquisition);

            return AdmissionEndedBefore(member, origin, through, []) ? null : RootOperation(operationId) + "@work:" + origin;
        }

        private bool ReadinessFreshInstanceUntil(AuthoredMember member, InvocationExpressionSyntax dispatch,
            int through, CleanupProvenanceContext proof, HashSet<GraphMemberIdentity> active)
        {
            if (member.ReadinessSource is not { SelectedConstructors: { } selected, InstanceConstructor: { } constructor }
                || proof.RemainingWork-- <= 0 || !active.Add(MemberIdentity(member))) return false;

            try
            {
                foreach (SyntaxNode node in PerUnitVisited(member.Syntax.DescendantNodes()
                    .Where(node => node.SpanStart < through), proof))
                {
                    if (node is ThisExpressionSyntax or BaseExpressionSyntax) return false;

                    if (member.Model.GetOperation(node) is IParameterReferenceOperation parameter
                        && SymbolEqualityComparer.Default.Equals(parameter.Parameter.ContainingSymbol.OriginalDefinition,
                            constructor.OriginalDefinition)
                        && (member.ReadinessSource.DirectHolderSlot is { } holderSlot
                            && SameBoundType(parameter.Parameter.Type, member.Model.Compilation, holderSlot.Type,
                                member.ReadinessSource.ReconcilerConstructor.Model.Compilation)
                            || selected.Any(candidate => PerUnitPotentialImplementations(parameter.Parameter.Type,
                                member.Model.Compilation).Any(implementation => SameBoundType(implementation,
                                    PerUnitExactSourceCompilation(implementation) ?? member.Model.Compilation,
                                    candidate.ContainingType, PerUnitExactSourceCompilation(candidate.ContainingType)
                                        ?? member.Model.Compilation)))))
                    {
                        if (node.Parent is not MemberAccessExpressionSyntax access || access.Expression != node
                            || access.Parent != dispatch) return false;
                    }

                    if (member.Model.GetOperation(node) is IInvocationOperation { Instance: IInstanceReferenceOperation }
                        && node != dispatch) return false;

                    if (member.Model.GetOperation(node) is IFieldReferenceOperation { Instance: IInstanceReferenceOperation })
                        return false;

                    if (member.Model.GetOperation(node) is IPropertyReferenceOperation
                        { Instance: IInstanceReferenceOperation, Property.GetMethod: { } getter })
                    {
                        if (Resolve(getter, member.Model.Compilation) is not { } body
                            || !ReadinessFreshInstanceUntil(body with { ReadinessSource = member.ReadinessSource },
                                dispatch, body.Syntax.Span.End, proof, active)) return false;
                    }
                }

                return proof.RemainingWork > 0;
            }
            finally
            {
                active.Remove(MemberIdentity(member));
            }
        }

        private bool ReadinessHandlerRetained(AuthoredMember member, InvocationExpressionSyntax dispatch,
            CleanupProvenanceContext proof)
        {
            if (AdmissionReceiver(member, dispatch) is not { } receiver
                || member.Model.GetSymbolInfo(receiver).Symbol is not ILocalSymbol handler) return false;

            foreach (IdentifierNameSyntax read in PerUnitVisited(member.Syntax.DescendantNodes().OfType<IdentifierNameSyntax>()
                .Where(read => read.SpanStart < dispatch.Span.End && read.Identifier.ValueText == handler.Name), proof))
            {
                if (!SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(read).Symbol, handler)) continue;

                if (read.Parent is not MemberAccessExpressionSyntax access || access.Expression != read) return false;

                if (access.Parent == dispatch) continue;

                if (member.Model.GetSymbolInfo(access).Symbol is not IPropertySymbol { Name: "SupportedCheckpointVersion" } property
                    || !IsExactAuthoredProtocolType(property.ContainingType,
                        "RetroDownfall.Arcanum.Core.Operations.ILongRunningOperationRecoveryHandler", member.Model.Compilation)) return false;
            }

            return proof.RemainingWork > 0;
        }

        private bool ReadinessHandlerPropertiesPreserveStorage(ReadinessRecoverySource source,
            ITypeSymbol contract, Compilation compilation, CleanupProvenanceContext proof)
        {
            foreach (IMethodSymbol selected in PerUnitVisited(source.SelectedConstructors ?? [], proof))
            {
                Compilation? sourceCompilation = PerUnitExactSourceCompilation(selected.ContainingType);

                if (sourceCompilation is null) return false;

                INamedTypeSymbol? implemented = selected.ContainingType.AllInterfaces.SingleOrDefault(candidate =>
                    SameBoundType(candidate, sourceCompilation, contract, compilation));

                if (implemented is null) continue;

                foreach (string name in new[] { "Kind", "SupportedCheckpointVersion" })
                {
                    if (proof.RemainingWork-- <= 0
                        || implemented.GetMembers(name).OfType<IPropertySymbol>().ToArray() is not [IPropertySymbol property]
                        || selected.ContainingType.FindImplementationForInterfaceMember(property) is not IPropertySymbol { GetMethod: { } getter }
                        || Resolve(getter, sourceCompilation) is not { } body
                        || !ReadinessFreshInstanceUntil(body with
                            { ReadinessSource = source with { InstanceConstructor = selected } }, source.Dispatch,
                            body.Syntax.Span.End, proof, [])) return false;
                }
            }

            return proof.RemainingWork > 0;
        }

        // Invoke only after this same proof completed the fresh-construction
        // projection. This freezes source history; it grants no admission fact.
        private bool TryGetPerUnitActivationHistoryIdentity(AuthoredMember origin,
            InvocationExpressionSyntax services, IReadOnlyList<PerUnitPriorScopeResolution> priorResolutions,
            IReadOnlyList<IMethodSymbol> selectedConstructors, CleanupProvenanceContext proof,
            out string identity)
        {
            identity = string.Empty;

            if (selectedConstructors.Count == 0 || proof.PerUnitActivationSources.Count == 0
                || ReadinessSourceIdentity(origin, services, proof) is not { } originIdentity) return false;

            // Snapshot only completed immutable records. No resolution, activation
            // discovery or fresh proof context is performed by this helper.
            var contracts = proof.PerUnitActivationSources.ToArray();

            PerUnitActivationSource[] activations = contracts.SelectMany(static pair => pair.Value)
                .DistinctBy(static source => source, ReferenceEqualityComparer.Instance).ToArray();

            PerUnitConstructorActivation[] constructions = activations.Where(static source => source.Construction is not null)
                .Select(static source => source.Construction!)
                .DistinctBy(static source => source, ReferenceEqualityComparer.Instance).ToArray();

            PerUnitSelectedActivation[] selections = proof.PerUnitSelectedActivations.Values
                .DistinctBy(static source => source, ReferenceEqualityComparer.Instance).ToArray();

            if (selections.Length == 0 || selectedConstructors.Any(constructor =>
                    !selections.Any(selected => SymbolEqualityComparer.Default.Equals(selected.Construction.Constructor, constructor)))
                || selections.Any(selected => selected.Chain.Length == 0
                    || selected.Chain.Any(source => !activations.Contains(source, ReferenceEqualityComparer.Instance)))) return false;

            Dictionary<PerUnitActivationSource, int> sourceOrdinals = new(ReferenceEqualityComparer.Instance);

            Dictionary<PerUnitConstructorActivation, int> constructorOrdinals = new(ReferenceEqualityComparer.Instance);

            Dictionary<(int Compilation, int Tree, int Start, int Length), string> syntaxIdentities = [];

            EvaluationEnvironmentFingerprint originEnvironment = EvaluationEnvironmentIdentity(origin);

            if (!originEnvironment.Complete || originEnvironment.ContainsBackreference) return false;

            Dictionary<GraphMemberIdentity, string> environments = new()
            {
                [MemberIdentity(origin)] = originIdentity,
            };

            StringBuilder history = new();

            AppendIdentitySegment(history, "per-unit-activation-history-v2");
            AppendIdentitySegment(history, originIdentity);

            bool AppendSyntax(SemanticModel model, SyntaxNode node)
            {
                if (!ReferenceEquals(model.SyntaxTree, node.SyntaxTree)) return false;

                var key = (CompilationIdentity(model.Compilation), TreeIdentity(node.SyntaxTree), node.SpanStart, node.Span.Length);

                if (!syntaxIdentities.TryGetValue(key, out string? value))
                {
                    if (proof.RemainingWork-- <= 0) return false;

                    value = key.ToString() + "|" + Location(node) + "|" + Fingerprint(node);
                    syntaxIdentities.Add(key, value);
                }

                AppendIdentitySegment(history, value);

                return true;
            }

            bool AppendEnvironment(AuthoredMember member)
            {
                GraphMemberIdentity key = MemberIdentity(member);

                if (!environments.TryGetValue(key, out string? value))
                {
                    if (proof.RemainingWork-- <= 0) return false;

                    EvaluationEnvironmentFingerprint environment = EvaluationEnvironmentIdentity(member);

                    if (!environment.Complete || environment.ContainsBackreference) return false;

                    value = key + "|" + environment.Identity;
                    environments.Add(key, value);
                }

                AppendIdentitySegment(history, value);

                return true;
            }

            void AppendDependencies(ImmutableArray<PerUnitActivationDependency> dependencies)
            {
                AppendIdentitySegment(history, dependencies.Length.ToString(CultureInfo.InvariantCulture));

                foreach (PerUnitActivationDependency dependency in dependencies)
                {
                    AppendIdentitySegment(history, PerUnitClosedSymbolIdentity(dependency.Contract, dependency.Compilation).ToString());
                    AppendIdentitySegment(history, (dependency.Parameter?.Ordinal ?? -1).ToString(CultureInfo.InvariantCulture));
                    AppendIdentitySegment(history, dependency.Resolution is { } resolution
                        ? TreeIdentity(resolution.SyntaxTree).ToString(CultureInfo.InvariantCulture) + "|" + Location(resolution)
                        : "constructor-parameter");
                }
            }

            // Source-record ordinals are local to this immutable snapshot. Their
            // contents include compilation/tree/symbol identity, never names alone.
            foreach (PerUnitConstructorActivation construction in constructions)
            {
                constructorOrdinals.Add(construction, constructorOrdinals.Count);
                AppendIdentitySegment(history, "constructor");
                AppendIdentitySegment(history, construction.ClosedConstructor.ToString());
                AppendIdentitySegment(history, MethodKey(construction.Constructor));

                if (construction.Source is { } source)
                {
                    if (!AppendEnvironment(source)) return false;
                }

                foreach (SyntaxReference declaration in construction.Constructor.ContainingType.DeclaringSyntaxReferences)
                {
                    if (!semanticModels.TryGetValue(declaration.SyntaxTree, out SemanticModel? model)
                        || !AppendSyntax(model, declaration.GetSyntax())) return false;
                }

                AppendDependencies(construction.Dependencies);
            }

            foreach (PerUnitActivationSource activation in activations)
            {
                sourceOrdinals.Add(activation, sourceOrdinals.Count);
                AppendIdentitySegment(history, "activation");
                AppendIdentitySegment(history, activation.Singleton + ":" + activation.Alias + ":" + activation.Selectable);

                if (activation.Original is { } registration)
                {
                    AppendIdentitySegment(history, registration.Method.ContainingAssembly.Identity.ToString());
                    AppendIdentitySegment(history, MethodKey(registration.Method));

                    if (!AppendSyntax(registration.Model, registration.Call)) return false;
                }
                else AppendIdentitySegment(history, "no-source-registration");

                AppendIdentitySegment(history, activation.Construction is { } construction
                    ? constructorOrdinals[construction].ToString(CultureInfo.InvariantCulture) : "no-construction");

                if (activation.Construction is { } direct && activation.Dependencies.Equals(direct.Dependencies))
                    AppendIdentitySegment(history, "constructor-dependencies");
                else
                    AppendDependencies(activation.Dependencies);
            }

            foreach (var contract in contracts.OrderBy(static pair => pair.Key.ToString(), StringComparer.Ordinal))
            {
                AppendIdentitySegment(history, contract.Key.ToString());
                AppendIdentitySegment(history, string.Join(",", contract.Value.Select(source => sourceOrdinals[source])));
            }

            foreach (PerUnitSelectedActivation selection in selections)
            {
                AppendIdentitySegment(history, "selected-chain");
                AppendIdentitySegment(history, string.Join(",", selection.Chain.Select(source => sourceOrdinals[source])));
            }

            foreach (PerUnitPriorScopeResolution prior in priorResolutions)
            {
                if (!proof.PerUnitActivationSources.ContainsKey(PerUnitClosedSymbolIdentity(prior.Contract, prior.Origin.Model.Compilation))
                    || !AppendEnvironment(prior.Origin)
                    || !AppendSyntax(prior.Origin.Model, prior.Resolution)) return false;

                AppendIdentitySegment(history, "prior-resolution");
                AppendIdentitySegment(history, BindingSymbolIdentity(prior.Scope, prior.Origin));
                AppendIdentitySegment(history, prior.Result is { } result
                    ? BindingSymbolIdentity(result, prior.Origin) : "discarded-result");
                AppendIdentitySegment(history, PerUnitClosedSymbolIdentity(prior.Contract, prior.Origin.Model.Compilation).ToString());
            }

            if (proof.RemainingWork <= 0) return false;

            identity = CompactIdentity(history.ToString());

            return true;
        }

        private bool TryGetOrdinaryScopedHolderConsumer(AuthoredMember entry, PerUnitHolderSource holder,
            CleanupProvenanceContext proof, out OrdinaryScopedHolderConsumerSource consumer)
        {
            consumer = null!;

            INamedTypeSymbol type = entry.Symbol.ContainingType;

            if (proof.RemainingWork-- <= 0 || entry.Symbol.IsStatic || type.IsGenericType || !type.IsSealed)
                return false;

            IMethodSymbol[] constructors = PerUnitVisited(type.InstanceConstructors, proof)
                .Where(static constructor => constructor.DeclaredAccessibility == Accessibility.Public).ToArray();

            if (proof.RemainingWork <= 0 || constructors is not [IMethodSymbol selected]
                || ResolveConstructorContextTarget(selected, entry.Model.Compilation) is not { } source)
                return false;

            IParameterSymbol[] slots = PerUnitVisited(source.Symbol.Parameters, proof)
                .Where(parameter => SameBoundType(parameter.Type, source.Model.Compilation,
                    holder.Bind.Symbol.ContainingType, holder.Bind.Model.Compilation)).ToArray();

            if (proof.RemainingWork <= 0 || slots is not [IParameterSymbol { RefKind: RefKind.None } slot]
                || !PerUnitCapturedSlotStable(slot, proof)) return false;

            bool consumed = false;

            foreach (SyntaxReference declaration in type.DeclaringSyntaxReferences)
            {
                if (proof.RemainingWork-- <= 0
                    || !semanticModels.TryGetValue(declaration.SyntaxTree, out SemanticModel? model)) return false;

                foreach (MemberAccessExpressionSyntax access in declaration.GetSyntax().DescendantNodes()
                    .OfType<MemberAccessExpressionSyntax>().Where(access => access.Name.Identifier.ValueText == holder.Getter.Name))
                {
                    if (proof.RemainingWork-- <= 0) return false;

                    if (model.GetOperation(access) is not IPropertyReferenceOperation read
                        || !SymbolEqualityComparer.Default.Equals(read.Property.OriginalDefinition,
                            holder.Getter.OriginalDefinition)) continue;

                    if (read.Instance is null
                        || PerUnitTransparentOperation(read.Instance) is not IParameterReferenceOperation receiver
                        || !SymbolEqualityComparer.Default.Equals(receiver.Parameter.OriginalDefinition,
                            slot.OriginalDefinition)) return false;

                    consumed = true;
                }
            }

            if (!consumed || proof.RemainingWork <= 0) return false;

            consumer = new(source, slot, holder);

            return true;
        }

        private bool RequiresOrdinaryScopedHolderWitness(AuthoredMember member)
        {
            GraphMemberIdentity identity = MemberIdentity(member);

            if (ordinaryScopedHolderDemands.TryGetValue(identity, out bool cached)) return cached;

            CleanupProvenanceContext proof = new();

            bool demand = false;

            foreach (MemberAccessExpressionSyntax access in member.Syntax.DescendantNodesAndSelf(node =>
                node == member.Syntax || node is not AnonymousFunctionExpressionSyntax and not LocalFunctionStatementSyntax)
                .OfType<MemberAccessExpressionSyntax>())
            {
                if (proof.RemainingWork-- <= 0)
                {
                    demand = true;
                    break;
                }

                if (member.Model.GetOperation(access) is not IPropertyReferenceOperation read
                    || read.Property.IsStatic || read.Property.DeclaringSyntaxReferences.IsEmpty
                    || !IsExactAuthoredProtocolType(read.Property.Type,
                        "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease", member.Model.Compilation)) continue;

                // This is an unproved source demand, never a grant from a type label.
                // A returned holder lease cannot borrow ambient work in lieu of its instance.
                foreach (IMethodSymbol bind in read.Property.ContainingType.GetMembers("Bind").OfType<IMethodSymbol>())
                {
                    if (proof.RemainingWork-- <= 0
                        || !bind.IsStatic && bind.Parameters is [IParameterSymbol { RefKind: RefKind.None } lease]
                            && IsExactAuthoredProtocolType(lease.Type,
                                "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease", member.Model.Compilation))
                    {
                        demand = true;
                        break;
                    }
                }

                if (demand) break;
            }

            ordinaryScopedHolderDemands[identity] = demand;

            return demand;
        }

        private void AppendOrdinaryScopedHolderIdentity(StringBuilder value, AuthoredMember member)
        {
            if (member.ScopedLeaseInstance is { } instance)
            {
                AppendIdentitySegment(value, "scoped-lease-instance");

                AppendIdentitySegment(value, instance.Identity);

                AppendIdentitySegment(value, instance.EntryPreservesAdmission + ":" + instance.ContinuationProven);
            }

            if (member.ReadinessSource is { } readiness)
            {
                AppendIdentitySegment(value, "readiness-source");
                AppendIdentitySegment(value, readiness.Identity);
                AppendIdentitySegment(value, readiness.InstanceConstructor is { } selected ? MethodKey(selected) : "");
                AppendIdentitySegment(value, readiness.AdmissionActive ? "owned-active" : "construction-only");
                AppendIdentitySegment(value, readiness.GroupIdentity ?? "");
            }

            if (member.OrdinaryScopedHolder is not { } witness) return;

            AppendIdentitySegment(value, "ordinary-scoped-holder");

            AppendIdentitySegment(value, witness.Identity);
            AppendIdentitySegment(value, MethodKey(witness.Constructor.Symbol));
        }

        private OrdinaryScopedHolderWitness? OrdinaryScopedHolderAtDispatch(AuthoredMember caller,
            InvocationExpressionSyntax call, string rootType, string operationId, GrimoireWorkKind? kind)
        {
            if (kind is null || caller.RecoveryContext is not null
                || !declaredOperations.Any(operation => operation.Authority == HostedProducerAuthorityKind.OrdinaryHostedWork
                    && RootOperation(operation.OperationId) == RootOperation(operationId)
                    && operation.WorkKind == kind
                    && operation.EnclosingType == TypeKey(caller.Symbol.ContainingType)
                    && operation.SourcePath == caller.Syntax.SyntaxTree.FilePath)
                || PerUnitInvocationSpelling(call) != "ResumeAsync"
                || caller.Model.GetOperation(call) is not IInvocationOperation invocation
                || invocation.TargetMethod.IsStatic || invocation.TargetMethod.IsGenericMethod
                || CompletionPoint(caller, call, inheritedCompletion: false) is not { } completion
                || TryRegisterEvaluationEnvironmentToken(caller) is not int token) return null;

            var cacheKey = (MemberIdentity(caller), token, call.SyntaxTree, call.SpanStart,
                RootOperation(operationId), kind.Value);

            if (ordinaryScopedHolderWitnesses.TryGetValue(cacheKey, out OrdinaryScopedHolderWitness? cached)) return cached;

            OrdinaryScopedHolderWitness? result = ProveOrdinaryScopedHolderDispatch(caller, call, rootType,
                operationId, kind.Value, completion);

            ordinaryScopedHolderWitnesses[cacheKey] = result;

            return result;
        }

        private OrdinaryScopedHolderWitness? ProveOrdinaryScopedHolderDispatch(AuthoredMember caller,
            InvocationExpressionSyntax call, string rootType, string operationId, GrimoireWorkKind kind,
            SyntaxNode completion)
        {
            CleanupProvenanceContext proof = new();

            if (AdmissionReceiver(caller, call) is not { } receiver
                || PerUnitStableLocalValue(caller, receiver, completion.Span.End, proof,
                    new HashSet<ISymbol>(SymbolEqualityComparer.Default)) is not InvocationExpressionSyntax resolution
                || !PerUnitServiceProvider(caller, resolution, out ExpressionSyntax scope)
                || caller.Model.GetSymbolInfo(resolution).Symbol is not IMethodSymbol resolver
                || !TrySelectPerUnitScopedConstruction(resolver.TypeArguments[0], caller.Model.Compilation, proof,
                    out ResolvedRegistration registration, out IMethodSymbol constructor, out AuthoredMember? construction)
                || construction is null
                || !ordinaryScopedHolderConsumers.TryGetValue(TypeIdentity(construction.Symbol.ContainingType,
                    construction.Model.Compilation), out OrdinaryScopedHolderConsumerSource? consumer)
                || !SymbolEqualityComparer.Default.Equals(construction.Symbol.OriginalDefinition,
                    consumer.Constructor.Symbol.OriginalDefinition)) return null;

            List<(string Work, PerUnitHandoffSource Handoff, ResolvedRegistration HolderRegistration)> witnesses = [];

            foreach (InvocationExpressionSyntax binding in caller.Syntax.DescendantNodes().OfType<InvocationExpressionSyntax>()
                .Where(binding => binding.Span.End < call.SpanStart && PerUnitInvocationSpelling(binding) == "Bind"))
            {
                if (proof.RemainingWork-- <= 0) return null;

                string? work = WorkAt(caller, binding, operationId, kind, inherited: null, position: binding.SpanStart);

                if (work is null || !TryGetPerUnitOrigin(work, rootType, operationId, proof,
                    out AuthoredMember origin, out InvocationExpressionSyntax acquisition)
                    || MemberIdentity(origin) != MemberIdentity(caller)
                    || caller.Model.GetOperation(binding) is not IInvocationOperation transfer
                    || transfer.Arguments is not [IArgumentOperation { Syntax: ArgumentSyntax argument } passed]
                    || passed.Parameter?.RefKind != RefKind.None
                    || !passed.InConversion.IsIdentity || !passed.OutConversion.IsIdentity
                    || AdmissionReceiver(caller, binding) is not { } holderReceiver
                    || !PerUnitSameAcquiredLease(caller, argument.Expression, acquisition, proof,
                        new HashSet<ISymbol>(SymbolEqualityComparer.Default), completion.Span.End)
                    || caller.Model.GetSymbolInfo(binding).Symbol is not IMethodSymbol binder
                    || !SymbolEqualityComparer.Default.Equals(binder.OriginalDefinition,
                        consumer.Holder.Bind.Symbol.OriginalDefinition)
                    || binding.Parent is not EqualsValueClauseSyntax initializer
                    || initializer.Value != binding
                    || !PerUnitBindingRetained(caller, binding, call, proof)) continue;

                PerUnitHandoffSource handoff = new(caller, acquisition, binding, holderReceiver, consumer.Holder, true);

                if (!PerUnitRootLeaseRetained(caller, acquisition, binding, completion, proof)
                    || PerUnitStableLocalValue(caller, holderReceiver, completion.Span.End, proof,
                        new HashSet<ISymbol>(SymbolEqualityComparer.Default)) is not InvocationExpressionSyntax holderResolution
                    || !PerUnitServiceProvider(caller, holderResolution, out ExpressionSyntax holderScope)
                    || !SymbolEqualityComparer.Default.Equals(caller.Model.GetSymbolInfo(scope).Symbol,
                        caller.Model.GetSymbolInfo(holderScope).Symbol)
                    || !PerUnitScopeRetained(handoff, scope, call, proof)
                    || !TrySelectPerUnitScopedConstruction(consumer.Holder.Bind.Symbol.ContainingType,
                        consumer.Holder.Bind.Model.Compilation, proof, out ResolvedRegistration holderRegistration,
                        out _, out _)) continue;

                EvaluationEnvironmentFingerprint environment = EvaluationEnvironmentIdentity(caller);

                if (!environment.Complete || environment.ContainsBackreference || proof.RemainingWork <= 0) return null;

                witnesses.Add((work, handoff, holderRegistration));
            }

            if (proof.RemainingWork <= 0 || witnesses is not [(string retained, PerUnitHandoffSource selected, ResolvedRegistration selectedHolder)]) return null;

            StringBuilder identity = new();

            AppendIdentitySegment(identity, EvaluationEnvironmentIdentity(caller).Identity);
            AppendIdentitySegment(identity, Location(call));
            AppendIdentitySegment(identity, Fingerprint(call));
            AppendIdentitySegment(identity, Location(selected.Binding));
            AppendIdentitySegment(identity, Fingerprint(selected.Binding));
            AppendIdentitySegment(identity, retained);
            AppendIdentitySegment(identity, BindingSymbolIdentity(constructor, construction));
            AppendIdentitySegment(identity, BindingSymbolIdentity(consumer.HolderSlot, consumer.Constructor));
            AppendIdentitySegment(identity, CompilationIdentity(registration.Model.Compilation).ToString(CultureInfo.InvariantCulture));
            AppendIdentitySegment(identity, TreeIdentity(registration.Call.SyntaxTree).ToString(CultureInfo.InvariantCulture));
            AppendIdentitySegment(identity, Location(registration.Call));
            AppendIdentitySegment(identity, Fingerprint(registration.Call));
            AppendIdentitySegment(identity, CompilationIdentity(selectedHolder.Model.Compilation).ToString(CultureInfo.InvariantCulture));
            AppendIdentitySegment(identity, TreeIdentity(selectedHolder.Call.SyntaxTree).ToString(CultureInfo.InvariantCulture));
            AppendIdentitySegment(identity, Location(selectedHolder.Call));
            AppendIdentitySegment(identity, Fingerprint(selectedHolder.Call));

            if (!TryGetPerUnitPriorScopeResolutionRoots(caller, scope, resolution, proof,
                    out IReadOnlyList<PerUnitPriorScopeResolution> priorResolutions, selected.Binding)
                || !ReadinessScopeResolutionHistoryIsComplete(caller, scope, resolution, call, priorResolutions, proof)
                || !TryGetScopedHolderConstructionProjection(consumer.Holder, resolver.TypeArguments[0],
                    caller.Model.Compilation, priorResolutions, proof, out IReadOnlyList<IMethodSymbol> selectedConstructors,
                    out IReadOnlyList<PerUnitPriorScopeResolution> exposedPriors)
                || !ReadinessPriorInstancesRemainUnobserved(exposedPriors, call, proof, [selected.Receiver, receiver])) return null;

            return new(CompactIdentity(identity.ToString()), retained, caller, call, selected.Binding, consumer.Constructor,
                consumer.HolderSlot, consumer.Holder.Getter, consumer.Holder.Bind, consumer.Holder.Storage,
                Location(selected.Acquisition), selectedConstructors);
        }

        private AuthoredMember BindOrdinaryScopedHolderInvocation(AuthoredMember caller,
            InvocationExpressionSyntax call, AuthoredMember target, string rootType, string operationId,
            GrimoireWorkKind? kind, string? work, bool detached)
        {
            AuthoredMember cleared = target.OrdinaryScopedHolder is null
                ? target : target with { OrdinaryScopedHolder = null };

            if (detached || work is null || caller.RecoveryContext is not null) return cleared;

            OrdinaryScopedHolderWitness? witness = OrdinaryScopedHolderAtDispatch(caller, call,
                rootType, operationId, kind);

            if (witness is not null && witness.Work == work
                && SameBoundType(witness.Constructor.Symbol.ContainingType, witness.Constructor.Model.Compilation,
                    target.Symbol.ContainingType, target.Model.Compilation))
                return cleared with { OrdinaryScopedHolder = witness };

            if (caller.OrdinaryScopedHolder is not { } inherited || inherited.Work != work
                || caller.Symbol.IsStatic || target.Symbol.IsStatic) return cleared;

            CleanupProvenanceContext proof = new();

            return TryGetReadinessReceiverConstructor(caller, call, target, proof, out IMethodSymbol? constructor)
                && TryBindOrdinaryScopedConstructor(cleared, constructor!, inherited, proof, out AuthoredMember bound)
                ? bound : cleared;
        }

        private bool TryBindOrdinaryScopedConstructor(AuthoredMember target, IMethodSymbol constructor,
            OrdinaryScopedHolderWitness source, CleanupProvenanceContext proof, out AuthoredMember bound)
        {
            bound = target;

            if (SymbolEqualityComparer.Default.Equals(constructor.OriginalDefinition, source.Constructor.Symbol.OriginalDefinition))
            {
                bound = target with { OrdinaryScopedHolder = source,
                    ConstructorContexts = new HashSet<IMethodSymbol>([constructor], SymbolEqualityComparer.Default) };

                return proof.RemainingWork > 0;
            }

            PerUnitHolderSource holder = new(source.HolderBinding, source.Getter, source.HolderStorage);

            if (!TryGetOrdinaryScopedHolderConsumer(target, holder, proof, out var consumer)
                || !SymbolEqualityComparer.Default.Equals(consumer.Constructor.Symbol.OriginalDefinition, constructor.OriginalDefinition)
                || !TryGetPerUnitSelectedActivation(constructor.ContainingType, target.Model.Compilation, proof, [], out var activation)
                || PerUnitVisited(activation.Chain[^1].Dependencies, proof).Where(edge => edge.Parameter is not null
                    && SymbolEqualityComparer.Default.Equals(edge.Parameter.OriginalDefinition, consumer.HolderSlot.OriginalDefinition)).ToArray()
                    is not [PerUnitActivationDependency dependency]
                || !SameBoundType(dependency.Contract, dependency.Compilation, source.HolderStorage.ContainingType,
                    source.HolderBinding.Model.Compilation)
                || proof.RemainingWork <= 0) return false;

            bound = target with
            {
                OrdinaryScopedHolder = source with { Constructor = consumer.Constructor, HolderSlot = consumer.HolderSlot },
                ConstructorContexts = new HashSet<IMethodSymbol>([constructor], SymbolEqualityComparer.Default),
            };

            return true;
        }

        private bool OrdinaryScopedHolderWorkIsCurrent(AuthoredMember member, string work)
        {
            return member.OrdinaryScopedHolder is { } witness && witness.Work == work
                && !member.Symbol.IsStatic
                && SameBoundType(member.Symbol.ContainingType, member.Model.Compilation,
                    witness.Constructor.Symbol.ContainingType, witness.Constructor.Model.Compilation);
        }

        private bool OrdinaryScopedPhysicalGroupSharesWork(AuthoredMember member, SyntaxNode site,
            string operationId, string? work, string? effect)
        {
            if (work is null || !OrdinaryScopedHolderWorkIsCurrent(member, work)
                || member.OrdinaryScopedHolder is not { } witness) return false;

            CleanupProvenanceContext proof = new();

            bool ReceiverProved(InvocationExpressionSyntax group)
            {
                if (proof.RemainingWork-- <= 0 || !IsGuardedAdmission(group)
                    || member.Model.GetSymbolInfo(group).Symbol is not IMethodSymbol method
                    || !IsExactAuthoredProtocolType(method.ContainingType,
                        "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease", member.Model.Compilation)
                    || AdmissionReceiver(member, group) is not { } receiver
                    || PerUnitStableLocalValue(member, receiver, group.SpanStart, proof,
                        new HashSet<ISymbol>(SymbolEqualityComparer.Default)) is not MemberAccessExpressionSyntax access
                    || member.Model.GetOperation(access) is not IPropertyReferenceOperation read
                    || !SymbolEqualityComparer.Default.Equals(read.Property.OriginalDefinition, witness.Getter.OriginalDefinition)
                    || read.Instance is null
                    || PerUnitTransparentOperation(read.Instance) is not IParameterReferenceOperation owner
                    || !SymbolEqualityComparer.Default.Equals(owner.Parameter.OriginalDefinition,
                        witness.HolderSlot.OriginalDefinition)) return false;

                return PerUnitSourceSymbolStable(member, owner.Parameter, member.Syntax.SpanStart,
                    group.SpanStart, proof) && proof.RemainingWork > 0;
            }

            if (site is InvocationExpressionSyntax frontier
                && PerUnitInvocationSpelling(frontier) == "TryBeginExternalEffectGroup") return ReceiverProved(frontier);

            if (effect is null || !effect.StartsWith(RootOperation(operationId) + "@effect:", StringComparison.Ordinal)
                || FindRetainedAdmission(member, site, "TryBeginExternalEffectGroup", null) is not { } local
                || effect != RootOperation(operationId) + "@effect:" + local) return false;

            InvocationExpressionSyntax[] groups = AdmissionSyntax(member).AdmissionCalls
                .Where(group => Location(group) == local).ToArray();

            return groups is [InvocationExpressionSyntax selected] && ReceiverProved(selected);
        }

        private bool IsExactPerUnitDispositionField(AuthoredMember classifier, IFieldSymbol field)
        {
            return field.IsStatic && field.HasConstantValue
                && IsExactAuthoredProtocolType(field.ContainingType,
                    "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningRecoveryAdmissionKind",
                    classifier.Model.Compilation)
                && field.ContainingType.TypeKind == TypeKind.Enum
                && classifier.Symbol.ReturnType.GetMembers("Kind").OfType<IPropertySymbol>()
                    .Any(property => SameBoundType(property.Type, classifier.Model.Compilation,
                        field.ContainingType, classifier.Model.Compilation));
        }

        private bool IsPerUnitProtectedSourceType(ITypeSymbol type, Compilation compilation) =>
            perUnitProtectedSourceTypes?.Contains(TypeIdentity(type, compilation)) == true;

        private bool TryGetPerUnitHolderSource(IMethodSymbol method, Compilation compilation,
            CleanupProvenanceContext proof, out PerUnitHolderSource holder)
        {
            holder = null!;

            if (proof.RemainingWork-- <= 0 || method.Name != "Bind"
                || method.IsStatic || method.IsGenericMethod
                || method.Parameters is not [IParameterSymbol { RefKind: RefKind.None } lease]
                || !IsExactAuthoredProtocolType(lease.Type,
                    "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease", compilation)
                || !IsExactFrameworkType(method.ReturnType, "System.IDisposable", typeof(IDisposable).Assembly.GetName())
                || Resolve(method, compilation) is not { } bind
                || !SameBoundType(method.ContainingType, compilation, bind.Symbol.ContainingType, bind.Model.Compilation)
                || !bind.Symbol.ContainingType.IsSealed || bind.Symbol.ContainingType.Arity != 0
                || bind.Symbol.Parameters is not [IParameterSymbol formal]) return false;

            IPropertySymbol[] getters = PerUnitVisited(bind.Symbol.ContainingType.GetMembers().OfType<IPropertySymbol>(), proof)
                .Where(property => !property.IsStatic && property.SetMethod is null && property.GetMethod is not null
                    && property.Parameters.Length == 0
                    && SameBoundType(property.Type, bind.Model.Compilation, formal.Type, bind.Model.Compilation))
                .ToArray();

            if (proof.RemainingWork <= 0 || getters is not [IPropertySymbol getter]
                || getter.DeclaringSyntaxReferences is not [SyntaxReference declaration]
                || declaration.GetSyntax() is not PropertyDeclarationSyntax
                {
                    ExpressionBody.Expression: BinaryExpressionSyntax coalesce,
                }
                || !coalesce.IsKind(SyntaxKind.CoalesceExpression)
                || coalesce.Right is not ThrowExpressionSyntax
                || !semanticModels.TryGetValue(coalesce.SyntaxTree, out SemanticModel? getterModel)
                || getterModel.GetSymbolInfo(coalesce.Left).Symbol is not IFieldSymbol
                {
                    IsStatic: false, DeclaredAccessibility: Accessibility.Private,
                } storage
                || !SymbolEqualityComparer.Default.Equals(storage.ContainingType, bind.Symbol.ContainingType)
                || storage.DeclaringSyntaxReferences is not [SyntaxReference fieldDeclaration]
                || fieldDeclaration.GetSyntax() is not VariableDeclaratorSyntax { Initializer: null }) return false;

            AssignmentExpressionSyntax[] stores = PerUnitVisited(bind.Syntax.DescendantNodes().OfType<AssignmentExpressionSyntax>()
                .Where(assignment => assignment.Left.DescendantNodesAndSelf().OfType<IdentifierNameSyntax>()
                    .Any(name => name.Identifier.ValueText == storage.Name)), proof)
                .Where(assignment => SymbolEqualityComparer.Default.Equals(bind.Model.GetSymbolInfo(assignment.Left).Symbol, storage)).ToArray();

            if (proof.RemainingWork <= 0 || stores is not [AssignmentExpressionSyntax store]
                || !store.IsKind(SyntaxKind.SimpleAssignmentExpression)
                || !SymbolEqualityComparer.Default.Equals(bind.Model.GetSymbolInfo(store.Right).Symbol, formal)
                || bind.Syntax is not MethodDeclarationSyntax { Body: { } bindBlock }
                || store.Parent is not ExpressionStatementSyntax { Parent: BlockSyntax storeBlock }
                || storeBlock != bindBlock
                || !PerUnitVisited(bindBlock.Statements.OfType<IfStatementSyntax>()
                        .Where(guard => guard.Span.End < store.SpanStart && guard.Statement is ThrowStatementSyntax), proof)
                    .Any(guard => PerUnitNonNullStorageGuard(bind, guard, storage))
                || proof.RemainingWork <= 0
                || ReturnedExpressions(bind.Syntax) is not [BaseObjectCreationExpressionSyntax token]
                || token.Parent is not ReturnStatementSyntax { Parent: BlockSyntax returnBlock } returned
                || returnBlock != bindBlock || returned.SpanStart <= store.Span.End
                || bindBlock.Statements.LastOrDefault() != returned
                || bind.Model.GetOperation(token) is not IObjectCreationOperation tokenCreation
                || tokenCreation.Arguments is not [IArgumentOperation ownerArgument, IArgumentOperation leaseArgument]
                || ownerArgument.Value is not IInstanceReferenceOperation
                || leaseArgument.Value is not IParameterReferenceOperation passedLease
                || !SymbolEqualityComparer.Default.Equals(passedLease.Parameter, formal)
                || tokenCreation.Constructor is not { } tokenConstructor
                || tokenConstructor.Parameters is not [IParameterSymbol owner, IParameterSymbol tokenLease]
                || !SameBoundType(owner.Type, bind.Model.Compilation, bind.Symbol.ContainingType, bind.Model.Compilation)
                || !SameBoundType(tokenLease.Type, bind.Model.Compilation, formal.Type, bind.Model.Compilation)
                || !PerUnitSourceSymbolStable(bind, formal, bind.Syntax.SpanStart, token.Span.End, proof)
                || !PerUnitCapturedSlotStable(owner, proof)
                || !PerUnitCapturedSlotStable(tokenLease, proof)
                || !PerUnitTokenInitializersPreserveCaptures(tokenConstructor, owner, tokenLease, proof)) return false;

            AuthoredTypeIdentity tokenType = new(tokenConstructor.ContainingAssembly.Identity,
                CompilationIdentity(bind.Model.Compilation), TypeKey(tokenConstructor.ContainingType));

            AuthoredMember[] disposals = PerUnitVisited(membersByType.GetValueOrDefault(tokenType) ?? [], proof)
                .Where(candidate => candidate.Symbol.Name == "Dispose"
                    && SameBoundType(candidate.Symbol.ContainingType, candidate.Model.Compilation,
                        tokenConstructor.ContainingType, bind.Model.Compilation)).ToArray();

            if (proof.RemainingWork <= 0 || disposals is not [AuthoredMember disposal]) return false;

            AssignmentExpressionSyntax[] clears = PerUnitVisited(disposal.Syntax.DescendantNodes().OfType<AssignmentExpressionSyntax>()
                .Where(assignment => assignment.Left.DescendantNodesAndSelf().OfType<IdentifierNameSyntax>()
                    .Any(name => name.Identifier.ValueText == storage.Name)), proof)
                .Where(assignment => SymbolEqualityComparer.Default.Equals(disposal.Model.GetSymbolInfo(assignment.Left).Symbol, storage)).ToArray();

            if (proof.RemainingWork <= 0 || clears is not [AssignmentExpressionSyntax clear]
                || !clear.IsKind(SyntaxKind.SimpleAssignmentExpression)
                || !clear.Right.IsKind(SyntaxKind.NullLiteralExpression)
                || disposal.Model.GetOperation(clear.Left) is not IFieldReferenceOperation
                {
                    Instance: IParameterReferenceOperation clearedOwner,
                }
                || !SymbolEqualityComparer.Default.Equals(clearedOwner.Parameter.OriginalDefinition, owner.OriginalDefinition)
                || clear.Ancestors().OfType<IfStatementSyntax>().FirstOrDefault() is not { } clearGuard
                || !clearGuard.Statement.Span.Contains(clear.Span)
                || disposal.Model.GetOperation(clearGuard.Condition) is not IInvocationOperation referenceEquals
                || !IsExactFrameworkMethod(referenceEquals.TargetMethod, "System.Object", "ReferenceEquals", "System.Private.CoreLib")
                || referenceEquals.Arguments is not [IArgumentOperation left, IArgumentOperation right]
                || PerUnitTransparentOperation(left.Value) is not IFieldReferenceOperation { Instance: IParameterReferenceOperation testedOwner } testedField
                || !SymbolEqualityComparer.Default.Equals(testedField.Field, storage)
                || !SymbolEqualityComparer.Default.Equals(testedOwner.Parameter.OriginalDefinition, owner.OriginalDefinition)
                || PerUnitTransparentOperation(right.Value) is not IParameterReferenceOperation testedLease
                || !SymbolEqualityComparer.Default.Equals(testedLease.Parameter.OriginalDefinition, tokenLease.OriginalDefinition)) return false;

            foreach (SyntaxReference typeDeclaration in bind.Symbol.ContainingType.DeclaringSyntaxReferences)
            {
                if (!semanticModels.TryGetValue(typeDeclaration.SyntaxTree, out SemanticModel? model)) return false;

                foreach (SyntaxNode node in PerUnitMutationCandidates(typeDeclaration.GetSyntax(), storage))
                {
                    if (proof.RemainingWork-- <= 0) return false;

                    if (node != store && node != clear
                        && (!PerUnitChargeWriteVisit(node, proof) || SyntaxNodeWritesSymbol(model, node, storage))) return false;
                }

                foreach (InvocationExpressionSyntax call in typeDeclaration.GetSyntax().DescendantNodes().OfType<InvocationExpressionSyntax>()
                    .Where(call => PerUnitInvocationSpelling(call) == bind.Symbol.Name))
                {
                    if (proof.RemainingWork-- <= 0) return false;

                    if (model.GetSymbolInfo(call).Symbol is IMethodSymbol invoked
                        && SymbolEqualityComparer.Default.Equals(invoked.OriginalDefinition, bind.Symbol.OriginalDefinition))
                    {
                        AuthoredMember? ownerMember = model.GetEnclosingSymbol(call.SpanStart) is IMethodSymbol enclosing
                            ? Resolve(enclosing, model.Compilation) : null;

                        if (ownerMember is null || !PerUnitVisited(ownerMember.Syntax.DescendantNodes().OfType<IfStatementSyntax>()
                                .Where(guard => guard.Span.End < call.SpanStart && guard.Statement is ReturnStatementSyntax), proof)
                            .Any(guard => PerUnitNonNullStorageGuard(ownerMember, guard, storage))
                            || proof.RemainingWork <= 0) return false;
                    }
                }
            }

            holder = new(bind, getter, storage);

            return true;
        }

        private static IEnumerable<T> PerUnitVisited<T>(IEnumerable<T> candidates, CleanupProvenanceContext proof)
        {
            foreach (T candidate in candidates)
            {
                if (proof.RemainingWork-- <= 0) yield break;

                yield return candidate;
            }
        }

        private static IEnumerable<SyntaxNode> PerUnitMutationCandidates(SyntaxNode syntax, ISymbol symbol) =>
            syntax.DescendantNodes().Where(node => node is AssignmentExpressionSyntax or RefExpressionSyntax
                or ArgumentSyntax { RefKindKeyword.RawKind: not 0 }
                or PrefixUnaryExpressionSyntax or PostfixUnaryExpressionSyntax)
                .Where(node => node.DescendantNodesAndSelf().OfType<IdentifierNameSyntax>()
                    .Any(name => name.Identifier.ValueText == symbol.Name));

        private static bool PerUnitChargeWriteVisit(SyntaxNode node, CleanupProvenanceContext proof)
        {
            SyntaxNode? inspected = node switch
            {
                AssignmentExpressionSyntax assignment => assignment.Left,
                ArgumentSyntax argument => argument.Expression,
                RefExpressionSyntax reference => reference.Expression,
                PrefixUnaryExpressionSyntax prefix => prefix.Operand,
                PostfixUnaryExpressionSyntax postfix => postfix.Operand,
                _ => null,
            };

            if (inspected is null) return true;

            // The unchanged semantic primitive can inspect tuple targets or all
            // references inside a ref operand. Charge those source visits up front.
            foreach (SyntaxNode source in inspected.DescendantNodesAndSelf())
            {
                if (proof.RemainingWork-- <= 0) return false;
            }

            return proof.RemainingWork > 0;
        }

        private bool PerUnitSourceSymbolStable(AuthoredMember member, ISymbol symbol,
            int after, int through, CleanupProvenanceContext proof)
        {
            foreach (SyntaxNode node in PerUnitMutationCandidates(member.Syntax, symbol))
            {
                if (node.Span.End <= after || node.SpanStart >= through) continue;

                if (proof.RemainingWork-- <= 0 || !PerUnitChargeWriteVisit(node, proof)
                    || SyntaxNodeWritesSymbol(member.Model, node, symbol)) return false;
            }

            return proof.RemainingWork > 0;
        }

        private bool PerUnitCapturedSlotStable(IParameterSymbol slot, CleanupProvenanceContext proof)
        {
            foreach (SyntaxReference declaration in slot.ContainingType.DeclaringSyntaxReferences)
            {
                if (proof.RemainingWork-- <= 0
                    || !semanticModels.TryGetValue(declaration.SyntaxTree, out SemanticModel? model)) return false;

                foreach (SyntaxNode node in PerUnitMutationCandidates(declaration.GetSyntax(), slot))
                {
                    if (proof.RemainingWork-- <= 0 || !PerUnitChargeWriteVisit(node, proof)
                        || SyntaxNodeWritesSymbol(model, node, slot)) return false;
                }
            }

            return proof.RemainingWork > 0;
        }

        private bool PerUnitTokenInitializersPreserveCaptures(IMethodSymbol constructor,
            IParameterSymbol owner, IParameterSymbol lease, CleanupProvenanceContext proof)
        {
            // A base constructor could consume the retained owner or lease before
            // the token is returned. Only the direct Object lane is proved here.
            if (proof.RemainingWork-- <= 0 || constructor.ContainingType.BaseType is not { } baseType
                || !IsExactFrameworkType(baseType, "System.Object", typeof(object).Assembly.GetName())
                || !PerUnitVisited(constructor.ContainingType.AllInterfaces, proof).Any(contract =>
                    IsExactFrameworkType(contract, "System.IDisposable", typeof(IDisposable).Assembly.GetName()))
                || proof.RemainingWork <= 0) return false;

            foreach (SyntaxReference reference in constructor.ContainingType.DeclaringSyntaxReferences)
            {
                if (proof.RemainingWork-- <= 0
                    || !semanticModels.TryGetValue(reference.SyntaxTree, out SemanticModel? model)) return false;

                SyntaxNode declaration = reference.GetSyntax();

                if (declaration is not TypeDeclarationSyntax tokenType
                    || tokenType.BaseList?.Types.Any(static type => type is PrimaryConstructorBaseTypeSyntax) == true) return false;

                foreach (EqualsValueClauseSyntax initializer in PerUnitVisited(declaration.DescendantNodes()
                    .OfType<EqualsValueClauseSyntax>(), proof))
                {
                    foreach (IdentifierNameSyntax name in PerUnitVisited(initializer.Value.DescendantNodesAndSelf()
                        .OfType<IdentifierNameSyntax>().Where(name => name.Identifier.ValueText == owner.Name
                            || name.Identifier.ValueText == lease.Name), proof))
                    {
                        ISymbol? referenced = model.GetSymbolInfo(name).Symbol;

                        if (SymbolEqualityComparer.Default.Equals(referenced, owner)
                            || SymbolEqualityComparer.Default.Equals(referenced, lease)) return false;
                    }

                    if (proof.RemainingWork <= 0) return false;
                }
            }

            return proof.RemainingWork > 0;
        }

        private static bool PerUnitNonNullStorageGuard(AuthoredMember member, IfStatementSyntax guard, IFieldSymbol storage) =>
            guard.Condition is IsPatternExpressionSyntax
            {
                Expression: { } expression,
                Pattern: UnaryPatternSyntax { Pattern: ConstantPatternSyntax { Expression: LiteralExpressionSyntax literal } },
            }
            && literal.IsKind(SyntaxKind.NullLiteralExpression)
            && SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(expression).Symbol, storage);

        // Spelling is only a cheap candidate filter; every positive edge below is
        // subsequently authenticated by its semantic source/member identity.
        private static string? PerUnitInvocationSpelling(InvocationExpressionSyntax call) => call.Expression switch
        {
            SimpleNameSyntax name => name.Identifier.ValueText,
            MemberAccessExpressionSyntax access => access.Name.Identifier.ValueText,
            _ => null,
        };

        private static IOperation PerUnitTransparentOperation(IOperation operation)
        {
            while (operation is IConversionOperation { OperatorMethod: null } conversion
                && (conversion.Conversion.IsIdentity || conversion.Conversion.IsReference)) operation = conversion.Operand;

            return operation;
        }

        private Compilation? PerUnitExactSourceCompilation(INamedTypeSymbol type)
        {
            Compilation[] owners = type.DeclaringSyntaxReferences.Select(reference =>
                semanticModels.GetValueOrDefault(reference.SyntaxTree)?.Compilation)
                .OfType<Compilation>().DistinctBy(static compilation => compilation, ReferenceEqualityComparer.Instance).ToArray();

            return owners is [Compilation owner] && ReferenceEquals(owner.Assembly, type.ContainingAssembly) ? owner : null;
        }

        private INamedTypeSymbol[] PerUnitPotentialImplementations(ITypeSymbol contract, Compilation compilation)
        {
            BoundTypeIdentity identity = TypeIdentity(contract, compilation);

            INamedTypeSymbol[] registered = bindings.Where(binding => binding.Contract == identity)
                .Select(binding => boundImplementationTypes.GetValueOrDefault(binding.Implementation))
                .OfType<INamedTypeSymbol>()
                .Where(type => SamePerUnitClosedType(type, compilation, contract, compilation)
                    || type.AllInterfaces.Any(slot => SamePerUnitClosedType(slot, compilation, contract, compilation))
                    || IsBase(type, contract))
                .DistinctBy(static type => type, SymbolEqualityComparer.Default).ToArray();

            return registered.Length != 0 ? registered
                : contract is INamedTypeSymbol { TypeKind: TypeKind.Class } concrete ? [concrete] : [];
        }

        private bool PerUnitDependencyPath(INamedTypeSymbol type, Compilation compilation,
            INamedTypeSymbol admission, Compilation admissionCompilation, CleanupProvenanceContext proof,
            HashSet<BoundTypeIdentity> active, HashSet<BoundTypeIdentity> path)
        {
            if (PerUnitExactSourceCompilation(type) is not { } owner) return false;

            compilation = owner;

            BoundTypeIdentity identity = TypeIdentity(type, compilation);

            if (proof.RemainingWork-- <= 0 || identity.Compilation is null || !active.Add(identity)) return false;

            try
            {
                if (SameBoundType(type, compilation, admission, admissionCompilation))
                {
                    path.Add(identity);

                    return true;
                }

                bool found = false;

                foreach (IMethodSymbol constructor in type.InstanceConstructors.Where(static constructor => !constructor.IsStatic))
                {
                    if (proof.RemainingWork-- <= 0) return false;

                    AuthoredMember? source = ResolveConstructorContextTarget(constructor, compilation);

                    if (source is null) continue;

                    foreach (IParameterSymbol parameter in source.Symbol.Parameters)
                    {
                        if (proof.RemainingWork-- <= 0) return false;

                        foreach (INamedTypeSymbol implementation in PerUnitPotentialImplementations(parameter.Type, source.Model.Compilation))
                        {
                            if (proof.RemainingWork-- <= 0) return false;

                            if (PerUnitExactSourceCompilation(implementation) is not { } implementationCompilation) continue;

                            // This source grammar admits the holder and direct constructor
                            // carriers. An unknown wrapper cannot lend instance provenance.
                            if (!SameBoundType(implementation, implementationCompilation, admission, admissionCompilation)
                                && !implementation.InstanceConstructors.Any(candidate => candidate.Parameters.Any(formal =>
                                    SameBoundType(formal.Type, implementationCompilation, admission, admissionCompilation)))) continue;

                            HashSet<BoundTypeIdentity> branch = [];

                            if (PerUnitDependencyPath(implementation, implementationCompilation, admission,
                                admissionCompilation, proof, active, branch))
                            {
                                path.UnionWith(branch);

                                path.Add(TypeIdentity(parameter.Type, source.Model.Compilation));

                                found = true;
                            }
                        }
                    }
                }

                if (found) path.Add(identity);

                return found;
            }
            finally
            {
                active.Remove(identity);
            }
        }

        private void PreparePerUnitRecoveryCompositionSources(RecoveryMatrix matrix)
        {
            if (perUnitProtectedSourceTypes is not null) return;

            perUnitProtectedSourceTypes = [];

            RecoveryTuple[] tuples = matrix.Tuples.Where(static tuple =>
                tuple.Disposition == RecoveryDisposition.OrdinaryPerUnitExternalEffect).ToArray();

            if (tuples.Length == 0)
            {
                perUnitSourceClosureComplete = true;

                return;
            }

            // Candidate source closure precedes composition resolution, avoiding a
            // selected-handler -> composition -> selected-handler cache recursion.
            CleanupProvenanceContext proof = new();

            List<PerUnitHolderSource> holders = [];

            foreach (AuthoredMember member in PerUnitVisited(AuthoredMembers.Where(static member => member.Symbol.Name == "Bind"), proof))
            {
                if (TryGetPerUnitHolderSource(member.Symbol, member.Model.Compilation, proof, out PerUnitHolderSource holder))
                    holders.Add(holder);

                if (proof.RemainingWork <= 0) return;
            }

            List<AuthoredMember> candidates = [];

            foreach (AuthoredMember member in PerUnitVisited(AuthoredMembers.Where(static member => member.Symbol.Name == "RecoverAsync"), proof))
            {
                if (ConstantRecoveryHandlerProperty(member, "Kind") is string kind
                    && tuples.Any(tuple => tuple.Kind == kind)) candidates.Add(member);

                if (proof.RemainingWork <= 0) return;
            }

            foreach (AuthoredMember candidate in candidates)
            {
                bool found = false;

                foreach (PerUnitHolderSource holder in holders)
                {
                    HashSet<BoundTypeIdentity> path = [];

                    if (PerUnitDependencyPath(candidate.Symbol.ContainingType, candidate.Model.Compilation,
                        holder.Bind.Symbol.ContainingType, holder.Bind.Model.Compilation, proof, [], path))
                    {
                        perUnitProtectedSourceTypes.UnionWith(path);

                        found = true;
                    }
                }

                if (!found || proof.RemainingWork <= 0) return;
            }

            // Ordinary candidates share the protected registration observer, but
            // consume a separate existing-size source budget. An incomplete census
            // grants no ordinary facts and preserves the original recovery closure.
            CleanupProvenanceContext ordinaryProof = new();

            Dictionary<BoundTypeIdentity, OrdinaryScopedHolderConsumerSource> ordinaryConsumers = [];

            HashSet<BoundTypeIdentity> ordinaryProtected = [];

            foreach (AuthoredMember entry in PerUnitVisited(AuthoredMembers.Where(static member =>
                member.Symbol.Name == "ResumeAsync" && !member.Symbol.IsStatic)
                .DistinctBy(member => TypeIdentity(member.Symbol.ContainingType, member.Model.Compilation)), ordinaryProof))
            {
                foreach (PerUnitHolderSource holder in holders)
                {
                    if (!TryGetOrdinaryScopedHolderConsumer(entry, holder, ordinaryProof,
                        out OrdinaryScopedHolderConsumerSource consumer)) continue;

                    BoundTypeIdentity identity = TypeIdentity(consumer.Constructor.Symbol.ContainingType,
                        consumer.Constructor.Model.Compilation);

                    HashSet<BoundTypeIdentity> dependencyPath = [];

                    if (!PerUnitDependencyPath(entry.Symbol.ContainingType, entry.Model.Compilation,
                        holder.Bind.Symbol.ContainingType, holder.Bind.Model.Compilation, ordinaryProof, [], dependencyPath)) continue;

                    ordinaryProtected.UnionWith(dependencyPath);

                    ordinaryConsumers[identity] = consumer;
                }

                if (ordinaryProof.RemainingWork <= 0) break;
            }

            if (ordinaryProof.RemainingWork > 0)
            {
                perUnitProtectedSourceTypes.UnionWith(ordinaryProtected);

                foreach ((BoundTypeIdentity identity, OrdinaryScopedHolderConsumerSource consumer) in ordinaryConsumers)
                {
                    ordinaryScopedHolderConsumers[identity] = consumer;

                    perUnitProtectedSourceTypes.Add(identity);
                }
            }

            bool foundReconciler = false;

            foreach (AuthoredMember reconciler in PerUnitVisited(membersByType.Where(static pair =>
                pair.Key.Type == "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationReconciler")
                    .SelectMany(static pair => pair.Value), proof))
            {
                if (!IsExactAuthoredProtocolType(reconciler.Symbol.ContainingType,
                    "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationReconciler", reconciler.Model.Compilation)) return;

                perUnitProtectedSourceTypes.Add(TypeIdentity(reconciler.Symbol.ContainingType, reconciler.Model.Compilation));
                foundReconciler = true;
            }

            perUnitSourceClosureComplete = holders.Count != 0 && candidates.Count != 0 && foundReconciler
                && proof.RemainingWork > 0;
        }

        private void ObservePerUnitRecoveryCompositionCall(AuthoredMember member, InvocationExpressionSyntax call,
            IMethodSymbol method, IReadOnlySet<ISymbol> services, RecoveryCompositionKind composition,
            bool mustExecute, bool exactlyOnce, bool authoredForwarding)
        {
            if (perUnitProtectedSourceTypes is not { Count: > 0 }
                || !InvocationUsesRecoveryCollection(member, call, services)) return;

            (bool complete, ITypeSymbol[] types) = RecoveryCollectionMutationTypes(member, call, method, services);

            bool relevant = types.Any(type => IsPerUnitProtectedSourceType(type, member.Model.Compilation))
                // An exact forwarding alias consumes its protected concrete target,
                // even when its nominal contract is outside the dependency closure.
                || IsExactRootFactoryRegistrationMethod(method) && method.Name == "AddScoped"
                    && method.TypeArguments.Length == 1
                    && call.ArgumentList.Arguments is [ArgumentSyntax { Expression: AnonymousFunctionExpressionSyntax factory }]
                    && ExactFactoryCreation(factory) is InvocationExpressionSyntax alias
                    && member.Model.GetSymbolInfo(alias).Symbol is IMethodSymbol resolver
                    && IsExactFrameworkMethod(resolver,
                        "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions", "GetRequiredService",
                        "Microsoft.Extensions.DependencyInjection.Abstractions")
                    && resolver.TypeArguments is [ITypeSymbol forwarded]
                    && IsPerUnitProtectedSourceType(forwarded, member.Model.Compilation)
                    && IsExactPerUnitFactoryProvider(member.Model, factory, alias);

            if (!complete && !authoredForwarding && !IsExactProductionFrameworkServiceBuilder(method)
                || method.Name is "Clear" or "RemoveAt")
            {
                perUnitUnprovenCompositions.Add(composition);

                return;
            }

            bool scoped = complete && IsExactRootFactoryRegistrationMethod(method) && method.Name == "AddScoped";

            // Prior resolutions can expose this holder through consumers outside
            // the handler dependency closure. Retain the actual walk's execution
            // facts for their descriptors too, including every unproven visit.
            if (scoped)
            {
                var execution = perUnitRegistrationExecution.GetValueOrDefault(call);

                perUnitRegistrationExecution[call] = mustExecute && exactlyOnce
                    ? (execution.Proven | composition, execution.Unproven)
                    : (execution.Proven, execution.Unproven | composition);
            }

            if (relevant && (!scoped || !mustExecute || !exactlyOnce))
                perUnitUnprovenCompositions.Add(composition);
        }

        private readonly record struct PerUnitClosedIdentity(int Compilation, int? SourceCompilation, int Symbol);

        private readonly Dictionary<Compilation, Dictionary<ISymbol, int>> perUnitClosedSymbols =
            new(ReferenceEqualityComparer.Instance);

        private PerUnitClosedIdentity PerUnitClosedSymbolIdentity(ISymbol symbol, Compilation compilation)
        {
            if (!perUnitClosedSymbols.TryGetValue(compilation, out Dictionary<ISymbol, int>? symbols))
                perUnitClosedSymbols.Add(compilation, symbols = new(SymbolEqualityComparer.Default));

            if (!symbols.TryGetValue(symbol, out int identity)) symbols.Add(symbol, identity = symbols.Count);

            // Compiler equality retains containing substitutions and argument assembly/
            // source identities. Tokens are local to this graph and consuming context.
            return new(CompilationIdentity(compilation), AuthoredCompilationIdentity(symbol, compilation), identity);
        }

        private bool SamePerUnitClosedType(ITypeSymbol left, Compilation leftCompilation,
            ITypeSymbol right, Compilation rightCompilation) =>
            SymbolEqualityComparer.Default.Equals(left, right)
                || left is INamedTypeSymbol { IsGenericType: false }
                    && right is INamedTypeSymbol { IsGenericType: false }
                    && SameBoundType(left, leftCompilation, right, rightCompilation);

        private bool PerUnitRegistrationNamesClosedType(ResolvedRegistration registration,
            ITypeSymbol contract, Compilation compilation) =>
            registration.Method.TypeArguments.Any(type =>
                SamePerUnitClosedType(type, registration.Model.Compilation, contract, compilation))
                || registration.Call.ArgumentList.Arguments is
                    [ArgumentSyntax { Expression: AnonymousFunctionExpressionSyntax factory }]
                    && ExactFactoryCreation(factory) is BaseObjectCreationExpressionSyntax creation
                    && registration.Model.GetSymbolInfo(creation).Symbol is IMethodSymbol constructor
                    && SamePerUnitClosedType(constructor.ContainingType, registration.Model.Compilation, contract, compilation);

        private sealed record PerUnitActivationDependency(
            ITypeSymbol Contract,
            Compilation Compilation,
            IParameterSymbol? Parameter,
            InvocationExpressionSyntax? Resolution);

        private sealed record PerUnitConstructorActivation(
            IMethodSymbol Constructor,
            AuthoredMember? Source,
            Compilation Compilation,
            ImmutableArray<PerUnitActivationDependency> Dependencies,
            PerUnitClosedIdentity ClosedConstructor);

        // Original is retained even when this activation forwards to another
        // contract. Dependencies retain actual factory resolution element types.
        private sealed record PerUnitActivationSource(
            ResolvedRegistration? Original,
            PerUnitConstructorActivation? Construction,
            ImmutableArray<PerUnitActivationDependency> Dependencies,
            bool Singleton,
            bool Alias,
            bool Selectable);

        private sealed record PerUnitSelectedActivation(
            ImmutableArray<PerUnitActivationSource> Chain,
            PerUnitConstructorActivation Construction);

        private bool TryGetPerUnitActivationSources(ITypeSymbol contract, Compilation compilation,
            CleanupProvenanceContext proof, out ImmutableArray<PerUnitActivationSource> sources)
        {
            PerUnitClosedIdentity identity = PerUnitClosedSymbolIdentity(contract, compilation);

            if (proof.PerUnitActivationSources.TryGetValue(identity, out sources)) return true;

            sources = [];

            if (proof.RemainingWork-- <= 0) return false;

            BoundContractIdentity key = new(contract.ContainingAssembly.Identity, TypeKey(contract));

            IReadOnlyDictionary<InvocationExpressionSyntax, RecoveryCompositionKind> compositions =
                RecoveryRegistrationCompositions();

            List<PerUnitActivationSource> result = [];

            foreach (ResolvedRegistration registration in (diActivationRegistrations.GetValueOrDefault(key) ?? [])
                .Where(candidate => compositions.GetValueOrDefault(candidate.Call).HasFlag(RecoveryCompositionKind.Serving))
                .DistinctBy(static candidate => candidate.Call, ReferenceEqualityComparer.Instance))
            {
                if (!PerUnitRegistrationNamesClosedType(registration, contract, compilation))
                {
                    // Compiler inequality proves different substitutions only in
                    // the same context. An unresolved cross-context definition
                    // bucket is uncertainty, even beside a matched registration.
                    if (contract is INamedTypeSymbol { IsGenericType: true }
                        && !ReferenceEquals(registration.Model.Compilation, compilation)) return false;

                    continue;
                }

                if (!proof.PerUnitRegistrationSources.TryGetValue(registration.Call, out PerUnitActivationSource? activation))
                {
                    if (!TryReadPerUnitActivationSource(registration, proof, out activation)) return false;

                    proof.PerUnitRegistrationSources.Add(registration.Call, activation);
                }

                result.Add(activation);
            }

            if (result.Count == 0 && contract is INamedTypeSymbol
                {
                    OriginalDefinition.SpecialType: SpecialType.System_Collections_Generic_IEnumerable_T,
                    TypeArguments: [ITypeSymbol element],
                })
            {
                if (proof.RemainingWork-- <= 0) return false;

                // Exact framework DI collection activation passes each resolved
                // element to this slot, including a fresh holder/carrier element.
                result.Add(new(null, null, [new(element, compilation, null, null)], false, true, false));
            }

            if (result.Count == 0)
            {
                // No source factory receives this scope's provider. Only actual
                // source constructor signatures can add fresh-holder edges here.
                foreach (INamedTypeSymbol implementation in PerUnitPotentialImplementations(contract, compilation))
                {
                    if (PerUnitExactSourceCompilation(implementation) is not { } sourceCompilation)
                    {
                        if (implementation.IsGenericType) return false;

                        continue;
                    }

                    if (!TryGetPerUnitConstructorActivation(implementation, sourceCompilation, null, proof,
                        out PerUnitConstructorActivation construction)) return false;

                    result.Add(new(null, construction, construction.Dependencies, false, false, false));
                }
            }

            if (proof.RemainingWork <= 0) return false;

            sources = result.ToImmutableArray();

            proof.PerUnitActivationSources.Add(identity, sources);

            return true;
        }

        private bool TryGetPerUnitConstructorActivation(INamedTypeSymbol implementation, Compilation compilation,
            IMethodSymbol? chosen, CleanupProvenanceContext proof, out PerUnitConstructorActivation construction)
        {
            construction = null!;

            bool direct = chosen is null;

            PerUnitClosedIdentity typeIdentity = PerUnitClosedSymbolIdentity(implementation, compilation);

            if (direct && proof.PerUnitDirectConstructions.TryGetValue(typeIdentity, out construction!)) return true;

            if (chosen is null)
            {
                // This is the existing selector's unique public constructor
                // grammar. Multiple candidates refuse rather than invent a choice.
                IMethodSymbol[] constructors = implementation.InstanceConstructors.Where(static constructor =>
                    !constructor.IsStatic && constructor.DeclaredAccessibility == Accessibility.Public).ToArray();

                if (constructors is not [IMethodSymbol selected]) return false;

                chosen = selected;
            }

            PerUnitClosedIdentity constructorIdentity = PerUnitClosedSymbolIdentity(chosen, compilation);

            if (proof.PerUnitConstructorSources.TryGetValue(constructorIdentity, out construction!))
            {
                if (direct) proof.PerUnitDirectConstructions.TryAdd(typeIdentity, construction);

                return true;
            }

            AuthoredMember? source = ResolveConstructorContextTarget(chosen, compilation);

            IMethodSymbol identity = source?.Symbol ?? chosen;

            if (proof.RemainingWork-- <= 0) return false;

            Compilation actualCompilation = source?.Model.Compilation ?? compilation;

            List<PerUnitActivationDependency> dependencies = [];

            foreach (IParameterSymbol parameter in PerUnitVisited(chosen.Parameters, proof))
            {
                if (parameter.RefKind != RefKind.None) return false;

                // Preserve constructed dependency types from the actual chosen
                // symbol, while mapping captures to the authored parameter slot.
                IParameterSymbol slot = source?.Symbol.Parameters[parameter.Ordinal] ?? parameter;

                dependencies.Add(new(parameter.Type, compilation, slot, null));
            }

            if (proof.RemainingWork <= 0) return false;

            construction = new(identity, source, actualCompilation, dependencies.ToImmutableArray(), constructorIdentity);

            proof.PerUnitConstructorSources.Add(constructorIdentity, construction);

            if (direct) proof.PerUnitDirectConstructions.Add(typeIdentity, construction);

            return true;
        }

        private bool TryReadPerUnitActivationSource(ResolvedRegistration registration,
            CleanupProvenanceContext proof, out PerUnitActivationSource activation)
        {
            activation = null!;

            if (proof.RemainingWork-- <= 0) return false;

            bool standard = IsExactServiceCollectionFluentMethod(registration.Method);

            bool descriptor = IsExactIndexedScopedDescriptor(registration.Call, registration.Method, registration.Model);

            if (standard && registration.Method.Name is "AddSingleton" or "TryAddSingleton")
            {
                activation = new(registration, null, [], true, false, false);

                return true;
            }

            if (!(standard && registration.Method.Name is "AddScoped" or "TryAddScoped" or "AddTransient" or "TryAddTransient"
                || descriptor) || registration.Method.TypeArguments.Length is < 1 or > 2) return false;

            bool selectable = (IsExactRootFactoryRegistrationMethod(registration.Method)
                && registration.Method.Name == "AddScoped" || descriptor);

            ITypeSymbol implementation = registration.Method.TypeArguments[^1];

            if (registration.Call.ArgumentList.Arguments.Count == 0)
            {
                if (implementation is not INamedTypeSymbol concrete
                    || !TryGetPerUnitConstructorActivation(concrete,
                        PerUnitExactSourceCompilation(concrete) ?? registration.Model.Compilation, null, proof,
                        out PerUnitConstructorActivation direct)) return false;

                activation = new(registration, direct, direct.Dependencies, false, false, selectable);

                return true;
            }

            if (registration.Call.ArgumentList.Arguments is not
                [ArgumentSyntax { Expression: AnonymousFunctionExpressionSyntax factory }]) return false;

            ParameterSyntax? declaration = factory switch
            {
                SimpleLambdaExpressionSyntax simple => simple.Parameter,
                ParenthesizedLambdaExpressionSyntax { ParameterList.Parameters: [ParameterSyntax parameter] } => parameter,
                _ => null,
            };

            if (declaration is null
                || registration.Model.GetDeclaredSymbol(declaration) is not IParameterSymbol provider
                || !IsExactFrameworkType(provider.Type, "System.IServiceProvider", typeof(IServiceProvider).Assembly.GetName()))
                return false;

            bool consumesProvider = false;

            foreach (IdentifierNameSyntax name in PerUnitVisited(factory.Body.DescendantNodesAndSelf()
                .OfType<IdentifierNameSyntax>().Where(name => name.Identifier.ValueText == provider.Name), proof))
            {
                consumesProvider |= SymbolEqualityComparer.Default.Equals(registration.Model.GetSymbolInfo(name).Symbol, provider);
            }

            if (proof.RemainingWork <= 0) return false;

            ExpressionSyntax? returned = ExactFactoryCreation(factory) as ExpressionSyntax;

            if (returned is InvocationExpressionSyntax alias
                && TryReadPerUnitActivationDependency(registration, factory, alias, null, out PerUnitActivationDependency forwarded))
            {
                if (proof.RemainingWork-- <= 0) return false;

                // Existing scoped selection accepts only GetRequiredService for
                // forwarding, while a census can inspect GetServices as an edge.
                selectable &= registration.Model.GetSymbolInfo(alias).Symbol is IMethodSymbol { Name: "GetRequiredService" };

                activation = new(registration, null, [forwarded], false, true, selectable);

                return true;
            }

            if (returned is not BaseObjectCreationExpressionSyntax creation
                || registration.Model.GetSymbolInfo(creation).Symbol is not IMethodSymbol chosen
                || registration.Model.GetOperation(creation) is not IObjectCreationOperation operation
                || operation.Initializer is not null)
            {
                if (consumesProvider) return false;

                // The actual provider is unused and the fresh holder is private.
                // This unrelated factory has no fresh-instance capability edge.
                activation = new(registration, null, [], false, false, false);

                return true;
            }

            selectable &= SamePerUnitClosedType(chosen.ContainingType, registration.Model.Compilation,
                implementation, registration.Model.Compilation);

            if (!TryGetPerUnitConstructorActivation(chosen.ContainingType, registration.Model.Compilation, chosen,
                proof, out PerUnitConstructorActivation construction)) return false;

            List<PerUnitActivationDependency> dependencies = [];

            foreach (IArgumentOperation argument in PerUnitVisited(operation.Arguments, proof))
            {
                if (argument.Parameter?.RefKind != RefKind.None || argument.Syntax is not ArgumentSyntax syntax
                    || !argument.InConversion.IsIdentity || !argument.OutConversion.IsIdentity) return false;

                IParameterSymbol parameter = construction.Constructor.Parameters[argument.Parameter.Ordinal];

                if (syntax.Expression is InvocationExpressionSyntax resolution
                    && TryReadPerUnitActivationDependency(registration, factory, resolution, parameter,
                        out PerUnitActivationDependency dependency))
                {
                    dependencies.Add(dependency);

                    continue;
                }

                if (registration.Model.GetConstantValue(syntax.Expression).HasValue)
                {
                    selectable &= !IsPerUnitProtectedSourceType(argument.Parameter.Type, registration.Model.Compilation);

                    continue;
                }

                if (consumesProvider) return false;

                selectable = false;
            }

            if (proof.RemainingWork <= 0) return false;

            activation = new(registration, construction, dependencies.ToImmutableArray(), false, false, selectable);

            return true;
        }

        private static bool TryReadPerUnitActivationDependency(ResolvedRegistration registration,
            AnonymousFunctionExpressionSyntax factory, InvocationExpressionSyntax resolution,
            IParameterSymbol? parameter, out PerUnitActivationDependency dependency)
        {
            dependency = null!;

            if (registration.Model.GetSymbolInfo(resolution).Symbol is not IMethodSymbol method
                || method.Name is not ("GetRequiredService" or "GetServices")
                || !IsExactFrameworkMethod(method,
                    "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions", method.Name,
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
                || method.TypeArguments is not [ITypeSymbol contract]
                || !IsExactPerUnitFactoryProvider(registration.Model, factory, resolution)) return false;

            dependency = new(contract, registration.Model.Compilation, parameter, resolution);

            return true;
        }

        private bool TryGetPerUnitSelectedActivation(ITypeSymbol contract, Compilation compilation,
            CleanupProvenanceContext proof, HashSet<PerUnitClosedIdentity> active,
            out PerUnitSelectedActivation selected)
        {
            selected = null!;

            PerUnitClosedIdentity identity = PerUnitClosedSymbolIdentity(contract, compilation);

            if (proof.PerUnitSelectedActivations.TryGetValue(identity, out selected!)) return true;

            if (!active.Add(identity)) return false;

            try
            {
                _ = RecoveryRegistrationCompositions();

                if (!perUnitSourceClosureComplete
                    || perUnitUnprovenCompositions.Any(kind => kind.HasFlag(RecoveryCompositionKind.Serving))
                    || !TryGetPerUnitActivationSources(contract, compilation, proof, out var sources)
                    || sources is not [PerUnitActivationSource { Original: { } registration, Selectable: true } source]
                    || !perUnitRegistrationExecution.TryGetValue(registration.Call, out var execution)
                    || !execution.Proven.HasFlag(RecoveryCompositionKind.Serving)
                    || execution.Unproven.HasFlag(RecoveryCompositionKind.Serving)
                    || !(SamePerUnitClosedType(registration.Method.TypeArguments[0], registration.Model.Compilation, contract, compilation)
                        || registration.Method.TypeArguments.Length == 2
                            && SamePerUnitClosedType(registration.Method.TypeArguments[1], registration.Model.Compilation, contract, compilation)))
                    return false;

                if (source.Alias)
                {
                    if (source.Dependencies is not [PerUnitActivationDependency alias]
                        || !TryGetPerUnitSelectedActivation(alias.Contract, alias.Compilation, proof, active,
                            out PerUnitSelectedActivation forwarded)) return false;

                    selected = new([source, .. forwarded.Chain], forwarded.Construction);
                }
                else
                {
                    if (source.Construction is not { } construction
                        || construction.Source is null && !(construction.Constructor.IsImplicitlyDeclared
                            && construction.Constructor.Parameters.Length == 0)) return false;

                    selected = new([source], construction);
                }

                proof.PerUnitSelectedActivations.Add(identity, selected);

                return proof.RemainingWork > 0;
            }
            finally
            {
                active.Remove(identity);
            }
        }

        private bool TrySelectPerUnitScopedConstruction(ITypeSymbol contract, Compilation compilation,
            CleanupProvenanceContext proof, out ResolvedRegistration registration,
            out IMethodSymbol constructor, out AuthoredMember? source)
        {
            registration = null!;
            constructor = null!;
            source = null;

            if (!TryGetPerUnitSelectedActivation(contract, compilation, proof, [], out PerUnitSelectedActivation selected))
                return false;

            registration = selected.Chain[^1].Original!;
            constructor = selected.Construction.Constructor;
            source = selected.Construction.Source;

            return true;
        }

        // The caller authenticates a newly created retained scope, no holder or
        // current-provider escape, and the actual ordered prior-resolution list.
        private bool TryGetPerUnitFreshConstructionProjection(PerUnitHolderSource holder,
            ITypeSymbol handlerContract, Compilation compilation,
            IReadOnlyList<PerUnitPriorScopeResolution> priorResolutions, CleanupProvenanceContext proof,
            out IReadOnlyList<IMethodSymbol> selectedConstructors,
            out IReadOnlyList<PerUnitPriorScopeResolution> exposedPriorResolutions)
        {
            selectedConstructors = [];
            exposedPriorResolutions = [];

            return IsExactAuthoredProtocolType(handlerContract,
                    "RetroDownfall.Arcanum.Core.Operations.ILongRunningOperationRecoveryHandler", compilation)
                && TryGetScopedHolderConstructionProjection(holder, handlerContract, compilation, priorResolutions,
                    proof, out selectedConstructors, out exposedPriorResolutions);
        }

        private bool TryGetScopedHolderConstructionProjection(PerUnitHolderSource holder,
            ITypeSymbol handlerContract, Compilation compilation,
            IReadOnlyList<PerUnitPriorScopeResolution> priorResolutions, CleanupProvenanceContext proof,
            out IReadOnlyList<IMethodSymbol> selectedConstructors,
            out IReadOnlyList<PerUnitPriorScopeResolution> exposedPriorResolutions)
        {
            selectedConstructors = [];
            exposedPriorResolutions = [];

            _ = RecoveryRegistrationCompositions();

            if (!perUnitSourceClosureComplete
                || invalidRecoveryComposition != RecoveryCompositionKind.None
                || perUnitUnprovenCompositions.Any(kind => kind.HasFlag(RecoveryCompositionKind.Serving))) return false;

            Dictionary<PerUnitClosedIdentity, bool> complete = [];

            Dictionary<PerUnitClosedIdentity, (PerUnitConstructorActivation Construction, HashSet<IParameterSymbol> Exposed)>
                projected = [];

            // Registration records are keyed by actual invocation, so distinct
            // alias factories are inspected even when they return the same store.
            foreach (PerUnitPriorScopeResolution prior in priorResolutions)
            {
                if (!PerUnitProjectionActivationCensus(prior.Contract, prior.Origin.Model.Compilation,
                    holder, proof, [], complete, projected, out _)) return false;
            }

            if (!PerUnitProjectionActivationCensus(handlerContract, compilation, holder, proof, [],
                complete, projected, out bool reaches) || !reaches) return false;

            List<IMethodSymbol> selected = [];

            foreach (var candidate in projected.Values)
            {
                PerUnitConstructorActivation construction = candidate.Construction;

                if (!TryGetPerUnitSelectedActivation(construction.Constructor.ContainingType,
                        construction.Compilation, proof, [], out PerUnitSelectedActivation selection)
                    || !SymbolEqualityComparer.Default.Equals(selection.Construction.Constructor,
                        construction.Constructor)) return false;

                AuthoredMember? source = construction.Source;

                if (source is null)
                {
                    if (proof.RemainingWork-- <= 0 || !construction.Constructor.IsImplicitlyDeclared
                        || construction.Constructor.Parameters.Length != 0
                        || construction.Constructor.ContainingType.DeclaringSyntaxReferences.FirstOrDefault() is not { } declaration
                        || declaration.GetSyntax() is not TypeDeclarationSyntax syntax
                        || !semanticModels.TryGetValue(declaration.SyntaxTree, out SemanticModel? model)) return false;

                    source = new(construction.Constructor, syntax, model);
                }

                if (!PerUnitProjectedConstructorPreservesStorage(source, holder, candidate.Exposed, proof)) return false;

                selected.Add(source.Symbol);
            }

            if (proof.RemainingWork <= 0 || selected.Count == 0) return false;

            List<PerUnitPriorScopeResolution> exposedPrior = [];

            foreach (PerUnitPriorScopeResolution prior in priorResolutions)
            {
                if (!complete.TryGetValue(PerUnitClosedSymbolIdentity(prior.Contract, prior.Origin.Model.Compilation),
                    out bool priorReaches)) return false;

                if (priorReaches) exposedPrior.Add(prior);
            }

            selectedConstructors = selected.ToArray();
            exposedPriorResolutions = exposedPrior.ToArray();

            return true;
        }

        private bool PerUnitProjectionActivationCensus(ITypeSymbol contract, Compilation compilation,
            PerUnitHolderSource holder, CleanupProvenanceContext proof, HashSet<PerUnitClosedIdentity> active,
            Dictionary<PerUnitClosedIdentity, bool> complete,
            Dictionary<PerUnitClosedIdentity, (PerUnitConstructorActivation Construction, HashSet<IParameterSymbol> Exposed)> projected,
            out bool reachesHolder)
        {
            reachesHolder = false;

            PerUnitClosedIdentity identity = PerUnitClosedSymbolIdentity(contract, compilation);

            if (complete.TryGetValue(identity, out reachesHolder)) return true;

            if (proof.RemainingWork <= 0
                || IsExactFrameworkType(contract, "System.IServiceProvider", typeof(IServiceProvider).Assembly.GetName()))
                return false;

            bool isHolder = SamePerUnitClosedType(contract, compilation, holder.Bind.Symbol.ContainingType,
                holder.Bind.Model.Compilation);

            // Even primitive contracts can have an authored factory receiving
            // the current provider. Registration facts must be inspected before
            // an otherwise capability-free result is classified as disjoint.
            if (!active.Add(identity)) return false;

            try
            {
                if (!TryGetPerUnitActivationSources(contract, compilation, proof, out var activations)) return false;

                // Each unique registration/constructor source and its dependency
                // edges were charged while building the immutable activation.
                // Traversing the same completed record does not rediscover them.
                foreach (PerUnitActivationSource activation in activations)
                {
                    if (activation.Singleton)
                    {
                        if (isHolder) return false;

                        continue;
                    }

                    bool activationReaches = isHolder || activation.Construction is { } created
                        && SamePerUnitClosedType(created.Constructor.ContainingType, created.Compilation,
                            holder.Bind.Symbol.ContainingType, holder.Bind.Model.Compilation);

                    HashSet<IParameterSymbol> exposed = new(SymbolEqualityComparer.Default);

                    foreach (PerUnitActivationDependency dependency in activation.Dependencies)
                    {
                        if (!PerUnitProjectionActivationCensus(dependency.Contract, dependency.Compilation,
                            holder, proof, active, complete, projected, out bool dependencyReaches)) return false;

                        activationReaches |= dependencyReaches;

                        if (dependencyReaches && dependency.Parameter is { } parameter) exposed.Add(parameter);
                    }

                    if (activationReaches && !activation.Alias)
                    {
                        if (activation.Construction is not { } construction
                            || construction.Constructor.ContainingType.IsGenericType
                            || PerUnitExactSourceCompilation(construction.Constructor.ContainingType) is null) return false;

                        if (projected.TryGetValue(construction.ClosedConstructor, out var existing))
                            existing.Exposed.UnionWith(exposed);
                        else
                            projected.Add(construction.ClosedConstructor, (construction, exposed));
                    }

                    reachesHolder |= activationReaches;
                }

                if (proof.RemainingWork <= 0 || isHolder && !reachesHolder) return false;

                complete[identity] = reachesHolder;

                return true;
            }
            finally
            {
                active.Remove(identity);
            }
        }

        private bool PerUnitProjectedConstructorPreservesStorage(AuthoredMember source,
            PerUnitHolderSource holder, IReadOnlySet<IParameterSymbol> exposed, CleanupProvenanceContext proof)
        {
            INamedTypeSymbol type = source.Symbol.ContainingType;

            if (proof.RemainingWork-- <= 0 || !type.IsSealed || type.IsRecord
                || type.BaseType is not { } baseType
                || !IsExactFrameworkType(baseType, "System.Object", typeof(object).Assembly.GetName())) return false;

            foreach (IParameterSymbol parameter in PerUnitVisited(exposed, proof))
            {
                if (!PerUnitCapturedSlotStable(parameter, proof)) return false;
            }

            foreach (SyntaxReference reference in PerUnitVisited(type.DeclaringSyntaxReferences, proof))
            {
                if (!semanticModels.TryGetValue(reference.SyntaxTree, out SemanticModel? model)
                    || reference.GetSyntax() is not TypeDeclarationSyntax declaration
                    || declaration.BaseList?.Types.Any(static value => value is PrimaryConstructorBaseTypeSyntax) == true)
                    return false;

                // Only initializers on this instance execute here. Nested type and
                // ordinary method bodies are not constructor execution.
                foreach (MemberDeclarationSyntax member in PerUnitVisited(declaration.Members.Where(static member =>
                    member is FieldDeclarationSyntax or PropertyDeclarationSyntax or EventFieldDeclarationSyntax), proof))
                {
                    if (member is FieldDeclarationSyntax fields)
                    {
                        foreach (VariableDeclaratorSyntax variable in PerUnitVisited(fields.Declaration.Variables, proof))
                        {
                            if (variable.Initializer is not { } initializer) continue;

                            if (model.GetDeclaredSymbol(variable) is not IFieldSymbol field) return false;

                            if (field.IsStatic) continue;

                            if (PerUnitProjectionCapture(initializer.Value, model, source.Symbol, exposed, out _))
                            {
                                if (!field.IsReadOnly || field.DeclaredAccessibility != Accessibility.Private
                                    || SymbolEqualityComparer.Default.Equals(field, holder.Storage)) return false;
                            }
                            else if (!PerUnitProjectionInitializerCannotObserveInstance(initializer.Value, model, exposed, proof))
                                return false;
                        }
                    }
                    else if (member is PropertyDeclarationSyntax { Initializer.Value: { } initializer } property
                        && !property.Modifiers.Any(static modifier => modifier.IsKind(SyntaxKind.StaticKeyword))
                        && !PerUnitProjectionInitializerCannotObserveInstance(initializer, model, exposed, proof)) return false;
                    else if (member is EventFieldDeclarationSyntax events
                        && events.Declaration.Variables.Any(static variable => variable.Initializer is not null)) return false;
                }
            }

            if (source.Syntax is ParameterListSyntax { Parent: TypeDeclarationSyntax }) return proof.RemainingWork > 0;

            if (source.Symbol.IsImplicitlyDeclared && source.Symbol.Parameters.Length == 0
                && source.Syntax is TypeDeclarationSyntax implicitType
                && SymbolEqualityComparer.Default.Equals(source.Model.GetDeclaredSymbol(implicitType), type))
                return proof.RemainingWork > 0;

            if (source.Syntax is not ConstructorDeclarationSyntax constructor
                || constructor.ExpressionBody is not null || constructor.Body is not { } body) return false;

            if (constructor.Initializer is { } initializerCall
                && (!initializerCall.IsKind(SyntaxKind.BaseConstructorInitializer)
                    || initializerCall.ArgumentList.Arguments.Count != 0
                    || source.Model.GetSymbolInfo(initializerCall).Symbol is not IMethodSymbol target
                    || !IsExactFrameworkType(target.ContainingType, "System.Object", typeof(object).Assembly.GetName()))) return false;

            foreach (StatementSyntax statement in PerUnitVisited(body.Statements, proof))
            {
                if (statement is EmptyStatementSyntax) continue;

                if (statement is not ExpressionStatementSyntax
                    { Expression: AssignmentExpressionSyntax assignment }
                    || !assignment.IsKind(SyntaxKind.SimpleAssignmentExpression)
                    || source.Model.GetOperation(assignment.Left) is not IFieldReferenceOperation
                        { Field: { IsStatic: false, IsReadOnly: true, DeclaredAccessibility: Accessibility.Private } field,
                          Instance: IInstanceReferenceOperation }
                    || !SymbolEqualityComparer.Default.Equals(field.ContainingType, type)
                    || SymbolEqualityComparer.Default.Equals(field, holder.Storage)
                    || !PerUnitProjectionCapture(assignment.Right, source.Model, source.Symbol,
                        null, out IParameterSymbol? parameter)
                    || parameter is null) return false;
            }

            return proof.RemainingWork > 0;
        }

        private static bool PerUnitProjectionCapture(ExpressionSyntax expression, SemanticModel model,
            IMethodSymbol constructor, IReadOnlySet<IParameterSymbol>? allowed, out IParameterSymbol? parameter)
        {
            parameter = null;

            if (model.GetOperation(expression) is not { } operation
                || PerUnitTransparentOperation(operation) is not IParameterReferenceOperation reference
                || !SymbolEqualityComparer.Default.Equals(reference.Parameter.ContainingSymbol, constructor)
                || allowed is not null && !allowed.Contains(reference.Parameter)) return false;

            parameter = reference.Parameter;

            return true;
        }

        private static bool PerUnitProjectionInitializerCannotObserveInstance(ExpressionSyntax expression,
            SemanticModel model, IReadOnlySet<IParameterSymbol> exposed, CleanupProvenanceContext proof)
        {
            foreach (SyntaxNode node in PerUnitVisited(expression.DescendantNodesAndSelf(), proof))
            {
                if (model.GetOperation(node) is IParameterReferenceOperation parameter && exposed.Contains(parameter.Parameter)
                    || node is ThisExpressionSyntax or BaseExpressionSyntax
                    || model.GetOperation(node) is IInvocationOperation { Instance: IInstanceReferenceOperation }
                    || model.GetOperation(node) is IPropertyReferenceOperation { Instance: IInstanceReferenceOperation }
                    || model.GetOperation(node) is IFieldReferenceOperation { Instance: IInstanceReferenceOperation }) return false;
            }

            return proof.RemainingWork > 0;
        }

        private sealed record PerUnitPriorScopeResolution(
            AuthoredMember Origin,
            InvocationExpressionSyntax Resolution,
            ILocalSymbol Scope,
            ILocalSymbol? Result,
            ITypeSymbol Contract);

        // The caller must already authenticate this scope's creation/retention.
        // This helper records actual reads of that local scope's provider before
        // handler materialization; it does not infer a provider from a type.
        private bool TryGetPerUnitPriorScopeResolutionRoots(AuthoredMember owner,
            ExpressionSyntax scopeExpression, InvocationExpressionSyntax handlers,
            CleanupProvenanceContext proof, out IReadOnlyList<PerUnitPriorScopeResolution> roots,
            InvocationExpressionSyntax? retainedBinding = null)
        {
            roots = [];

            if (proof.RemainingWork-- <= 0
                || owner.Model.GetSymbolInfo(scopeExpression).Symbol is not ILocalSymbol scope
                || scope.DeclaringSyntaxReferences is not [SyntaxReference declaration]
                || declaration.GetSyntax() is not VariableDeclaratorSyntax
                {
                    Parent.Parent: LocalDeclarationStatementSyntax { Parent: BlockSyntax block } scopeStatement,
                }
                || scopeStatement.Declaration.Variables.Count != 1
                || handlers.SyntaxTree != declaration.SyntaxTree
                || handlers.Ancestors().OfType<LocalDeclarationStatementSyntax>().FirstOrDefault() is not { } materialization
                || materialization.Parent != block || materialization.SpanStart <= scopeStatement.Span.End
                || owner.Model.GetSymbolInfo(handlers).Symbol is not IMethodSymbol { TypeArguments.Length: 1 } handlerMethod
                || !IsExactFrameworkMethod(handlerMethod,
                    "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions",
                    retainedBinding is null ? "GetServices" : "GetRequiredService",
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
                || handlers.Expression is not MemberAccessExpressionSyntax
                    { Expression: MemberAccessExpressionSyntax { Expression: { } actualScope } provider }
                || owner.Model.GetSymbolInfo(provider).Symbol is not IPropertySymbol { Name: "ServiceProvider" } property
                || !IsExactFrameworkType(property.ContainingType, "Microsoft.Extensions.DependencyInjection.AsyncServiceScope",
                    typeof(Microsoft.Extensions.DependencyInjection.AsyncServiceScope).Assembly.GetName())
                || !SymbolEqualityComparer.Default.Equals(owner.Model.GetSymbolInfo(actualScope).Symbol, scope)) return false;

            List<PerUnitPriorScopeResolution> resolutions = [];

            foreach (StatementSyntax statement in PerUnitVisited(block.Statements.Where(statement =>
                statement.SpanStart >= scopeStatement.Span.End && statement.Span.End <= materialization.SpanStart), proof))
            {
                if (retainedBinding is not null && statement is LocalDeclarationStatementSyntax
                    { Declaration.Variables: [VariableDeclaratorSyntax { Initializer.Value: { } bindingValue }] }
                    && bindingValue == retainedBinding)
                {
                    // The caller already proved this exact Bind and retained token.
                    // Its inline holder resolution still belongs to the scope census.
                    if (AdmissionReceiver(owner, retainedBinding) is InvocationExpressionSyntax inlineResolution)
                    {
                        if (!PerUnitServiceProvider(owner, inlineResolution, out ExpressionSyntax inlineScope)
                            || !SymbolEqualityComparer.Default.Equals(owner.Model.GetSymbolInfo(inlineScope).Symbol, scope)
                            || owner.Model.GetSymbolInfo(inlineResolution).Symbol is not IMethodSymbol
                                { TypeArguments: [ITypeSymbol inlineContract] }) return false;

                        resolutions.Add(new(owner, inlineResolution, scope, null, inlineContract));
                    }

                    continue;
                }

                InvocationExpressionSyntax resolution;

                ILocalSymbol? result;

                if (statement is LocalDeclarationStatementSyntax
                    { Declaration.Variables: [VariableDeclaratorSyntax { Initializer.Value: InvocationExpressionSyntax localResolution } variable] }
                    && owner.Model.GetDeclaredSymbol(variable) is ILocalSymbol local)
                {
                    resolution = localResolution;
                    result = local;
                }
                else if (statement is ExpressionStatementSyntax { Expression: AssignmentExpressionSyntax assignment }
                    && assignment.IsKind(SyntaxKind.SimpleAssignmentExpression)
                    && owner.Model.GetOperation(assignment) is ISimpleAssignmentOperation { Target: IDiscardOperation }
                    && assignment.Right is InvocationExpressionSyntax discardedResolution)
                {
                    resolution = discardedResolution;
                    result = null;
                }
                else return false;

                if (!PerUnitServiceProvider(owner, resolution, out ExpressionSyntax receiver)
                    || !SymbolEqualityComparer.Default.Equals(owner.Model.GetSymbolInfo(receiver).Symbol, scope)
                    || owner.Model.GetSymbolInfo(resolution).Symbol is not IMethodSymbol { TypeArguments: [ITypeSymbol contract] })
                    return false;

                resolutions.Add(new(owner, resolution, scope, result, contract));
            }

            if (proof.RemainingWork <= 0) return false;

            if (retainedBinding is not null)
            {
                // The selected consumer is also an exposed instance before dispatch.
                // Only its exact joined dispatch receiver is exempted by the caller.
                if (materialization.Declaration.Variables is not [VariableDeclaratorSyntax
                    { Initializer.Value: { } initializer } materialized]
                    || initializer != handlers
                    || owner.Model.GetDeclaredSymbol(materialized) is not ILocalSymbol result) return false;

                resolutions.Add(new(owner, handlers, scope, result, handlerMethod.TypeArguments[0]));
            }

            roots = resolutions.ToArray();

            return true;
        }

        private static bool IsExactPerUnitFactoryProvider(SemanticModel model,
            AnonymousFunctionExpressionSyntax factory, InvocationExpressionSyntax resolution)
        {
            ParameterSyntax? declaration = factory switch
            {
                SimpleLambdaExpressionSyntax simple => simple.Parameter,
                ParenthesizedLambdaExpressionSyntax { ParameterList.Parameters: [ParameterSyntax parameter] } => parameter,
                _ => null,
            };

            return declaration is not null && model.GetDeclaredSymbol(declaration) is IParameterSymbol provider
                && IsExactFrameworkType(provider.Type, "System.IServiceProvider", typeof(IServiceProvider).Assembly.GetName())
                && resolution.Expression is MemberAccessExpressionSyntax access
                && SymbolEqualityComparer.Default.Equals(model.GetSymbolInfo(access.Expression).Symbol, provider)
                && resolution.ArgumentList.Arguments.Count == 0;
        }

        private bool TryGetPerUnitRootOwner(string rootType, string operationId, out AuthoredTypeIdentity owner)
        {
            owner = default;

            if (!perUnitRootOwners.TryGetValue((rootType, RootOperation(operationId)), out HashSet<AuthoredTypeIdentity>? owners)
                || owners.Count != 1) return false;

            owner = owners.Single();

            return true;
        }

        private bool TryGetPerUnitOrigin(string? work, string rootType, string operationId,
            CleanupProvenanceContext proof, out AuthoredMember origin, out InvocationExpressionSyntax acquisition)
        {
            origin = null!;
            acquisition = null!;

            if (work is null || !work.StartsWith(RootOperation(operationId) + "@work:", StringComparison.Ordinal)
                || !admissionCapsules.ContainsKey(work)) return false;

            string location = work[(work.LastIndexOf("@work:", StringComparison.Ordinal) + 6)..];

            int separator = location.LastIndexOf(':');

            if (separator < 0 || !int.TryParse(location[(separator + 1)..], CultureInfo.InvariantCulture, out int position)) return false;

            string path = location[..separator];

            if (!TryGetPerUnitRootOwner(rootType, operationId, out AuthoredTypeIdentity rootOwner)) return false;

            AuthoredMember[] owners = PerUnitVisited((membersByType.GetValueOrDefault(rootOwner) ?? [])
                .Where(member => member.Syntax.SyntaxTree.FilePath == path
                    && member.Syntax.Span.Contains(position)), proof)
                .Where(member => SymbolEqualityComparer.Default.Equals(member.Symbol,
                    member.Model.GetEnclosingSymbol(position))).DistinctBy(MemberIdentity).ToArray();

            if (owners is not [AuthoredMember exact] || proof.RemainingWork-- <= 0) return false;

            InvocationExpressionSyntax[] calls = AdmissionSyntax(exact).AdmissionCalls.Where(call => call.SpanStart == position
                && exact.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method
                && Normalize(method) == "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireConnectionAdmissionGate.TryAcquireWorkLease"
                && IsExactAuthoredProtocolType(method.ContainingType,
                    "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireConnectionAdmissionGate", exact.Model.Compilation)
                && IsGuardedAdmission(call)).ToArray();

            if (calls is not [InvocationExpressionSyntax selected]) return false;

            // Recompute the admitted source/member capsule; location alone does not
            // authenticate a different compilation, member, overload or source tree.
            string fingerprint = Fingerprint(selected);

            int ordinal = PerUnitVisited(exact.Syntax.DescendantNodesAndSelf().Where(node => node.RawKind == selected.RawKind
                && node.SpanStart < selected.SpanStart
                && node is InvocationExpressionSyntax call && PerUnitInvocationSpelling(call) == PerUnitInvocationSpelling(selected)), proof)
                .Count(node => SyntaxFactory.AreEquivalent(node, selected));

            if (proof.RemainingWork <= 0) return false;

            string capsule = CapsuleId(path, StableMemberIdentity(exact), HostedProducerSiteKind.EffectFrontier,
                "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireConnectionAdmissionGate.TryAcquireWorkLease", ordinal, fingerprint);

            if (admissionCapsules[work] != capsule) return false;

            origin = exact;
            acquisition = selected;

            return true;
        }

        private static IOperation PerUnitAcquisitionOutput(IOperation operation)
        {
            operation = PerUnitTransparentOperation(operation);

            return operation is IDeclarationExpressionOperation declaration
                ? PerUnitTransparentOperation(declaration.Expression)
                : operation;
        }

        private bool PerUnitSameAcquiredLease(AuthoredMember origin, ExpressionSyntax expression,
            InvocationExpressionSyntax acquisition, CleanupProvenanceContext proof, HashSet<ISymbol> active,
            int? through = null)
        {
            expression = StripTransparentExpression(expression);

            if (proof.RemainingWork-- <= 0 || origin.Model.GetSymbolInfo(expression).Symbol is not ILocalSymbol local
                || !active.Add(local) || !IsStableAcrossAdmissionCleanupBackEdges(origin, expression, local)) return false;

            try
            {
                if (origin.Model.GetOperation(acquisition) is IInvocationOperation acquired
                    && acquired.Arguments.Any(argument => argument.Parameter?.RefKind == RefKind.Out
                        && PerUnitAcquisitionOutput(argument.Value) is ILocalReferenceOperation output
                        && SymbolEqualityComparer.Default.Equals(output.Local, local)))
                {
                    return SymbolIsStableWithin(origin, local, acquisition.Span.End, through ?? expression.SpanStart)
                        && PerUnitSourceSymbolStable(origin, local, acquisition.Span.End, through ?? expression.SpanStart, proof)
                        && !AdmissionEndedBefore(origin, Location(acquisition), expression.SpanStart, []);
                }

                if (local.DeclaringSyntaxReferences is [SyntaxReference declaration]
                    && declaration.GetSyntax() is VariableDeclaratorSyntax { Initializer.Value: { } initializer } variable
                    && variable.SyntaxTree == origin.Syntax.SyntaxTree && origin.Syntax.Span.Contains(variable.Span)
                    && SymbolIsStableWithin(origin, local, variable.Span.End, through ?? expression.SpanStart)
                    && PerUnitSourceSymbolStable(origin, local, variable.Span.End, through ?? expression.SpanStart, proof))
                {
                    return PerUnitSameAcquiredLease(origin, initializer, acquisition, proof, active, through);
                }

                return false;
            }
            finally
            {
                active.Remove(local);
            }
        }

        private bool PerUnitBindingRetained(AuthoredMember origin, InvocationExpressionSyntax binding,
            InvocationExpressionSyntax settlement, CleanupProvenanceContext proof)
        {
            VariableDeclaratorSyntax? declaration = binding.Ancestors().OfType<VariableDeclaratorSyntax>().FirstOrDefault();

            if (declaration is null || origin.Model.GetDeclaredSymbol(declaration) is not ILocalSymbol token
                || declaration.Parent?.Parent is not LocalDeclarationStatementSyntax { UsingKeyword.RawKind: not 0 } owned
                || owned.Parent is not BlockSyntax block || !block.Span.Contains(settlement.Span)
                || owned.Span.End >= settlement.SpanStart
                || declaration.Initializer?.Value is not { } initializer
                || !(StripTransparentExpression(initializer) == binding
                    || StripTransparentExpression(initializer) is ConditionalExpressionSyntax conditional
                        && StripTransparentExpression(conditional.WhenTrue) == binding)
                || CompletionPoint(origin, settlement, inheritedCompletion: false) is not { } completion
                || !block.Span.Contains(completion.Span)
                || !PerUnitSourceSymbolStable(origin, token, declaration.Span.End, completion.Span.End, proof)
                || !SymbolIsStableWithin(origin, token, declaration.Span.End, block.Span.End)) return false;

            foreach (InvocationExpressionSyntax call in block.DescendantNodes().OfType<InvocationExpressionSyntax>())
            {
                if (proof.RemainingWork-- <= 0) return false;

                if (call == binding || call.SpanStart >= completion.Span.End) continue;

                if (call.Expression is MemberAccessExpressionSyntax access
                    && SymbolEqualityComparer.Default.Equals(origin.Model.GetSymbolInfo(access.Expression).Symbol, token)
                    || call.ArgumentList.Arguments.Any(argument => argument.Expression.DescendantNodesAndSelf()
                        .OfType<IdentifierNameSyntax>().Any(identifier => SymbolEqualityComparer.Default.Equals(
                            origin.Model.GetSymbolInfo(identifier).Symbol, token)))) return false;
            }

            // Only the null test selecting the linked revocation token may read the
            // using token before completion. Assignment, aliases, returns and captures
            // could let another owner dispose the binding before its send.
            foreach (IdentifierNameSyntax read in block.DescendantNodes().OfType<IdentifierNameSyntax>()
                .Where(identifier => identifier.Identifier.ValueText == token.Name))
            {
                if (proof.RemainingWork-- <= 0) return false;

                if (read.SpanStart <= declaration.Span.End || read.SpanStart >= completion.Span.End
                    || !SymbolEqualityComparer.Default.Equals(origin.Model.GetSymbolInfo(read).Symbol, token)) continue;

                if (read.Parent is not IsPatternExpressionSyntax test
                    || test.Expression != read
                    || test.Pattern is not ConstantPatternSyntax { Expression: LiteralExpressionSyntax literal }
                    || !literal.IsKind(SyntaxKind.NullLiteralExpression)) return false;
            }

            foreach (AnonymousFunctionExpressionSyntax callback in block.DescendantNodes().OfType<AnonymousFunctionExpressionSyntax>())
            {
                foreach (IdentifierNameSyntax identifier in callback.DescendantNodes().OfType<IdentifierNameSyntax>())
                {
                    if (proof.RemainingWork-- <= 0
                        || SymbolEqualityComparer.Default.Equals(origin.Model.GetSymbolInfo(identifier).Symbol, token)) return false;
                }
            }

            return proof.RemainingWork > 0;
        }

        private bool TryGetPerUnitHandoffSource(string? work, string rootType, string operationId,
            CleanupProvenanceContext proof, out PerUnitHandoffSource witness, out InvocationExpressionSyntax settlement)
        {
            witness = null!;
            settlement = null!;

            if (!TryGetPerUnitOrigin(work, rootType, operationId, proof, out AuthoredMember origin,
                out InvocationExpressionSyntax acquisition)) return false;

            InvocationExpressionSyntax[] settlements = PerUnitVisited(origin.Syntax.DescendantNodes().OfType<InvocationExpressionSyntax>()
                .Where(static call => PerUnitInvocationSpelling(call) == "SettleDiscoveredRuntimeAsync"), proof)
                .Where(call => origin.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method
                    && method.Name == "SettleDiscoveredRuntimeAsync"
                    && IsExactAuthoredProtocolType(method.ContainingType,
                        "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationReconciler", origin.Model.Compilation)).ToArray();

            if (proof.RemainingWork <= 0 || settlements is not [InvocationExpressionSyntax dispatch]
                || proof.RemainingWork-- <= 0
                || CompletionPoint(origin, dispatch, inheritedCompletion: false) is not { } completion) return false;

            List<(InvocationExpressionSyntax Call, PerUnitHolderSource Holder, ExpressionSyntax Receiver)> bindings = [];

            foreach (InvocationExpressionSyntax call in origin.Syntax.DescendantNodes().OfType<InvocationExpressionSyntax>()
                .Where(static call => PerUnitInvocationSpelling(call) == "Bind"))
            {
                if (proof.RemainingWork-- <= 0) return false;

                if (call.SpanStart <= acquisition.Span.End || call.Span.End >= dispatch.SpanStart
                    || origin.Model.GetSymbolInfo(call).Symbol is not IMethodSymbol method || method.Name != "Bind") continue;

                if (origin.Model.GetOperation(call) is not IInvocationOperation operation
                    || operation.Arguments is not [IArgumentOperation argument]
                    || argument.Parameter?.RefKind != RefKind.None
                    || !argument.InConversion.IsIdentity || !argument.OutConversion.IsIdentity
                    || argument.Syntax is not ArgumentSyntax syntax
                    || AdmissionReceiver(origin, call) is not { } receiver
                    || !PerUnitSameAcquiredLease(origin, syntax.Expression, acquisition, proof,
                        new HashSet<ISymbol>(SymbolEqualityComparer.Default), completion.Span.End)
                    || !TryGetPerUnitHolderSource(method, origin.Model.Compilation, proof, out PerUnitHolderSource bindingHolder)
                    || !PerUnitBindingRetained(origin, call, dispatch, proof)) continue;

                bindings.Add((call, bindingHolder, receiver));
            }

            if (bindings is not [(InvocationExpressionSyntax binding, PerUnitHolderSource selectedHolder, ExpressionSyntax selectedReceiver)]
                || proof.RemainingWork-- <= 0
                || !PerUnitRootLeaseRetained(origin, acquisition, binding, completion, proof)) return false;

            ConditionalExpressionSyntax? conditional = binding.Ancestors().OfType<ConditionalExpressionSyntax>().FirstOrDefault();

            if (conditional is not null && !PerUnitConditionalBindingIsExact(origin, conditional, dispatch, proof)) return false;

            bool scoped = StripTransparentExpression(selectedReceiver) is InvocationExpressionSyntax;

            if (!scoped && (origin.Model.GetSymbolInfo(StripTransparentExpression(selectedReceiver)).Symbol is not ILocalSymbol holder
                    || !SymbolIsStableWithin(origin, holder, binding.Span.End, completion.Span.End)
                    || !PerUnitSourceSymbolStable(origin, holder, binding.Span.End, completion.Span.End, proof))) return false;

            witness = new(origin, acquisition, binding, selectedReceiver, selectedHolder, scoped);
            settlement = dispatch;

            return true;
        }

        private string? PerUnitWorkAtRootSettlement(AuthoredMember caller, InvocationExpressionSyntax call,
            string rootType, string operationId, GrimoireWorkKind? kind)
        {
            // WorkAt itself never calls this hook: authenticate the live caller before
            // its sole selected transfer, rather than recursively reclaiming a lost edge.
            if (kind is null || !TryGetPerUnitRootOwner(rootType, operationId, out AuthoredTypeIdentity rootOwner)
                || rootOwner != new AuthoredTypeIdentity(caller.Symbol.ContainingAssembly.Identity,
                    CompilationIdentity(caller.Model.Compilation), TypeKey(caller.Symbol.ContainingType))
                || PerUnitInvocationSpelling(call) != "SettleDiscoveredRuntimeAsync") return null;

            CleanupProvenanceContext proof = new();

            if (proof.RemainingWork-- <= 0 || caller.Model.GetSymbolInfo(call).Symbol is not IMethodSymbol method
                || !IsExactAuthoredProtocolType(method.ContainingType,
                    "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationReconciler", caller.Model.Compilation)) return null;

            List<(string Work, PerUnitHandoffSource Witness)> candidates = [];

            foreach (InvocationExpressionSyntax binding in PerUnitVisited(caller.Syntax.DescendantNodes()
                .OfType<InvocationExpressionSyntax>().Where(candidate => candidate.Span.End < call.SpanStart
                    && PerUnitInvocationSpelling(candidate) == "Bind"), proof))
            {
                string? beforeTransfer = WorkAt(caller, binding, operationId, kind, inherited: null,
                    position: binding.SpanStart);

                if (beforeTransfer is null || !TryGetPerUnitHandoffSource(beforeTransfer, rootType, operationId, proof,
                        out PerUnitHandoffSource witness, out InvocationExpressionSyntax settlement)
                    || MemberIdentity(caller) != MemberIdentity(witness.Origin)
                    || binding.SyntaxTree != witness.Binding.SyntaxTree || binding.Span != witness.Binding.Span
                    || call.SyntaxTree != settlement.SyntaxTree || call.Span != settlement.Span) continue;

                candidates.Add((beforeTransfer, witness));
            }

            return proof.RemainingWork > 0 && candidates is [(string work, _)] ? work : null;
        }

        private bool PerUnitRootLeaseRetained(AuthoredMember origin, InvocationExpressionSyntax acquisition,
            InvocationExpressionSyntax binding, SyntaxNode completion, CleanupProvenanceContext proof)
        {
            if (proof.RemainingWork-- <= 0
                || AdmissionEndedBefore(origin, Location(acquisition), binding.SpanStart, [])) return false;

            bool Carries(ExpressionSyntax expression)
            {
                if (proof.RemainingWork-- <= 0) return false;

                return AdmissionOrigins(origin, expression, new HashSet<ISymbol>(SymbolEqualityComparer.Default))
                        .Contains(Location(acquisition))
                    && MayCarryAdmissionHandle(origin, expression);
            }

            foreach (SyntaxNode node in PerUnitVisited(AdmissionSyntax(origin).LifetimeNodes
                .Where(node => node.Span.End >= binding.SpanStart && node.Span.End < completion.Span.End), proof))
            {
                if (node is InvocationExpressionSyntax call && (call == binding
                        || origin.Model.GetOperation(call) is INameOfOperation)) continue;

                if (node is ReturnStatementSyntax { Expression: { } returned } && Carries(returned)
                    || node is ArrowExpressionClauseSyntax arrow && Carries(arrow.Expression)
                    || node is AssignmentExpressionSyntax assignment
                        && origin.Model.GetSymbolInfo(assignment.Left).Symbol is not ILocalSymbol and not IParameterSymbol
                        && Carries(assignment.Right)) return false;

                if (node is InvocationExpressionSyntax invocation)
                {
                    IMethodSymbol? method = origin.Model.GetSymbolInfo(invocation).Symbol as IMethodSymbol;

                    if (method is not null && Normalize(method) == "System.ArgumentNullException.ThrowIfNull") continue;

                    if (AdmissionReceiver(origin, invocation) is { } receiver && Carries(receiver)
                        && (method is null || !PreservesAdmissionReceiver(method) && !IsCompletionCombinator(method))) return false;

                    if ((method is null || !IsCompletionCombinator(method))
                        && AdmissionArguments(origin, invocation).Any(argument =>
                            argument.Expression is not DeclarationExpressionSyntax && Carries(argument.Expression))) return false;
                }

                if (node is UsingStatementSyntax { Expression: { } resource } statement
                        && statement.Span.End < completion.Span.End && Carries(resource)
                    || node is VariableDeclarationSyntax declaration
                        && (declaration.Parent is LocalDeclarationStatementSyntax { UsingKeyword.RawKind: not 0 }
                            || declaration.Parent is UsingStatementSyntax)
                        && DisposalPosition(declaration) < completion.Span.End
                        && declaration.Variables.Any(variable => variable.Initializer is not null && Carries(variable.Initializer.Value))) return false;
            }

            // Object construction can also retain a handle without an invocation node.
            foreach (BaseObjectCreationExpressionSyntax creation in PerUnitVisited(origin.Syntax.DescendantNodes()
                .OfType<BaseObjectCreationExpressionSyntax>().Where(creation => creation.SpanStart > binding.Span.End
                    && creation.Span.End < completion.Span.End), proof))
            {
                if ((creation.ArgumentList?.Arguments.Any(argument => Carries(argument.Expression)) ?? false)
                    || (creation.Initializer?.Expressions.Any(Carries) ?? false)) return false;
            }

            return proof.RemainingWork > 0;
        }

        private ExpressionSyntax? PerUnitStableLocalValue(AuthoredMember member, ExpressionSyntax expression,
            int through, CleanupProvenanceContext proof, HashSet<ISymbol> active, bool requireBuiltInConversions = false,
            bool requireUncapturedSqliteSlots = false)
        {
            if (requireBuiltInConversions)
            {
                if (!TryNormalizeBuiltInCleanupValue(member.Model, expression, out ExpressionSyntax normalized)) return null;

                expression = normalized;
            }
            else expression = StripTransparentExpression(expression);

            if (proof.RemainingWork-- <= 0) return null;

            if (member.Model.GetSymbolInfo(expression).Symbol is not ILocalSymbol local) return expression;

            if (!active.Add(local)) return null;

            try
            {
                if (local.DeclaringSyntaxReferences is not [SyntaxReference declaration]
                    || declaration.GetSyntax() is not VariableDeclaratorSyntax { Initializer.Value: { } initializer } variable
                    || variable.SyntaxTree != member.Syntax.SyntaxTree || !member.Syntax.Span.Contains(variable.Span)
                    || !SymbolIsStableWithin(member, local, variable.Span.End, through)
                    || requireUncapturedSqliteSlots && !SqliteValueSlotHasNoLexicalCapture(member, local, proof)) return null;

                return PerUnitStableLocalValue(member, initializer, through, proof, active, requireBuiltInConversions,
                    requireUncapturedSqliteSlots);
            }
            finally
            {
                active.Remove(local);
            }
        }

        private bool PerUnitConditionalBindingIsExact(AuthoredMember origin, ConditionalExpressionSyntax conditional,
            InvocationExpressionSyntax settlement, CleanupProvenanceContext proof)
        {
            if (!conditional.WhenFalse.IsKind(SyntaxKind.NullLiteralExpression)
                || conditional.Condition is not IsPatternExpressionSyntax
                {
                    Expression: MemberAccessExpressionSyntax access,
                    Pattern: ConstantPatternSyntax { Expression: { } category },
                }
                || origin.Model.GetSymbolInfo(category).Symbol is not IFieldSymbol { Name: "OrdinaryPerUnitExternalEffect" } field
                || origin.Model.GetSymbolInfo(access).Symbol is not IPropertySymbol { Name: "Kind" } property
                || !SameBoundType(property.Type, origin.Model.Compilation, field.ContainingType, origin.Model.Compilation)
                || origin.Model.GetSymbolInfo(access.Expression).Symbol is not ISymbol decision
                || settlement.ArgumentList.Arguments.FirstOrDefault()?.Expression is not { } operation) return false;

            bool Pair(AuthoredMember owner, ExpressionSyntax decisionValue, ExpressionSyntax operationValue, int through)
            {
                ExpressionSyntax? source = PerUnitStableLocalValue(owner, decisionValue, through, proof,
                    new HashSet<ISymbol>(SymbolEqualityComparer.Default));

                return source is InvocationExpressionSyntax classifier
                    && owner.Model.GetSymbolInfo(classifier).Symbol is IMethodSymbol { Name: "Classify" } method
                    && IsExactAuthoredProtocolType(method.ContainingType,
                        "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationRecoveryAdmission", owner.Model.Compilation)
                    && classifier.ArgumentList.Arguments is [ArgumentSyntax classified, ArgumentSyntax evidence]
                    && evidence.Expression.IsKind(SyntaxKind.NullLiteralExpression)
                    && owner.Model.GetSymbolInfo(classified.Expression).Symbol is { } input
                    && SymbolEqualityComparer.Default.Equals(input, owner.Model.GetSymbolInfo(operationValue).Symbol)
                    && SymbolIsStableWithin(owner, input, classified.Span.End, through)
                    && IsExactPerUnitDispositionField(Resolve(method, owner.Model.Compilation) ?? owner, field);
            }

            if (decision is ILocalSymbol) return Pair(origin, access.Expression, operation, settlement.Span.End);

            if (decision is not IParameterSymbol formal
                || !SymbolEqualityComparer.Default.Equals(formal.ContainingSymbol, origin.Symbol)
                || origin.Model.GetSymbolInfo(operation).Symbol is not IParameterSymbol operationFormal
                || !SymbolEqualityComparer.Default.Equals(operationFormal.ContainingSymbol, origin.Symbol)
                || !SymbolIsStableWithin(origin, formal, origin.Syntax.SpanStart, settlement.Span.End)
                || !SymbolIsStableWithin(origin, operationFormal, origin.Syntax.SpanStart, settlement.Span.End)) return false;

            List<(AuthoredMember Owner, InvocationExpressionSyntax Call)> incoming = [];

            AuthoredTypeIdentity ownerType = new(origin.Symbol.ContainingAssembly.Identity,
                CompilationIdentity(origin.Model.Compilation), TypeKey(origin.Symbol.ContainingType));

            foreach (AuthoredMember owner in membersByType.GetValueOrDefault(ownerType) ?? [])
            {
                foreach (InvocationExpressionSyntax call in owner.Syntax.DescendantNodes().OfType<InvocationExpressionSyntax>()
                    .Where(call => PerUnitInvocationSpelling(call) == origin.Symbol.Name))
                {
                    if (proof.RemainingWork-- <= 0) return false;

                    if (owner.Model.GetSymbolInfo(call).Symbol is IMethodSymbol invoked
                        && SymbolEqualityComparer.Default.Equals(invoked.OriginalDefinition, origin.Symbol.OriginalDefinition))
                        incoming.Add((owner, call));
                }
            }

            var unique = incoming.DistinctBy(static edge => edge.Call, ReferenceEqualityComparer.Instance).ToArray();

            if (unique is not [(AuthoredMember caller, InvocationExpressionSyntax forwarding)]
                || caller.Model.GetOperation(forwarding) is not IInvocationOperation forwarded) return false;

            IArgumentOperation? decisionArgument = forwarded.Arguments.SingleOrDefault(argument => argument.Parameter?.Ordinal == formal.Ordinal);
            IArgumentOperation? operationArgument = forwarded.Arguments.SingleOrDefault(argument => argument.Parameter?.Ordinal == operationFormal.Ordinal);

            return decisionArgument is { Parameter.RefKind: RefKind.None, Syntax: ArgumentSyntax callerDecision }
                && operationArgument is { Parameter.RefKind: RefKind.None, Syntax: ArgumentSyntax callerOperation }
                && decisionArgument.InConversion.IsIdentity && operationArgument.InConversion.IsIdentity
                && Pair(caller, callerDecision.Expression, callerOperation.Expression, forwarding.Span.End);
        }

        private bool PerUnitSameReceiver(PerUnitHandoffSource witness, ExpressionSyntax expression,
            int through, CleanupProvenanceContext proof)
        {
            if (witness.Origin.Model.GetSymbolInfo(StripTransparentExpression(witness.Receiver)).Symbol is ILocalSymbol receiver
                && !SymbolIsStableWithin(witness.Origin, receiver, witness.Binding.Span.End, through)) return false;

            ExpressionSyntax? expected = PerUnitStableLocalValue(witness.Origin, witness.Receiver, through, proof,
                new HashSet<ISymbol>(SymbolEqualityComparer.Default));

            ExpressionSyntax? actual = PerUnitStableLocalValue(witness.Origin, expression, through, proof,
                new HashSet<ISymbol>(SymbolEqualityComparer.Default));

            if (expected is null || actual is null) return false;

            if (expected is BaseObjectCreationExpressionSyntax) return actual == expected;

            return expected is InvocationExpressionSyntax expectedResolution && actual is InvocationExpressionSyntax actualResolution
                && PerUnitServiceProvider(witness.Origin, expectedResolution, out ExpressionSyntax expectedProvider)
                && PerUnitServiceProvider(witness.Origin, actualResolution, out ExpressionSyntax actualProvider)
                && witness.Origin.Model.GetSymbolInfo(expectedResolution).Symbol is IMethodSymbol expectedMethod
                && witness.Origin.Model.GetSymbolInfo(actualResolution).Symbol is IMethodSymbol actualMethod
                && SameBoundType(expectedMethod.TypeArguments[0], witness.Origin.Model.Compilation,
                    actualMethod.TypeArguments[0], witness.Origin.Model.Compilation)
                && SymbolEqualityComparer.Default.Equals(witness.Origin.Model.GetSymbolInfo(expectedProvider).Symbol,
                    witness.Origin.Model.GetSymbolInfo(actualProvider).Symbol);
        }

        private static bool PerUnitServiceProvider(AuthoredMember owner, InvocationExpressionSyntax resolution,
            out ExpressionSyntax scope)
        {
            scope = null!;

            if (resolution.ArgumentList.Arguments.Count != 0
                || owner.Model.GetSymbolInfo(resolution).Symbol is not IMethodSymbol { TypeArguments.Length: 1 } method
                || !IsExactFrameworkMethod(method,
                    "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions", "GetRequiredService",
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
                || resolution.Expression is not MemberAccessExpressionSyntax
                {
                    Expression: MemberAccessExpressionSyntax { Expression: { } receiver } provider,
                }
                || owner.Model.GetSymbolInfo(provider).Symbol is not IPropertySymbol { Name: "ServiceProvider" } property
                || !IsExactFrameworkType(property.ContainingType, "Microsoft.Extensions.DependencyInjection.AsyncServiceScope",
                    typeof(Microsoft.Extensions.DependencyInjection.AsyncServiceScope).Assembly.GetName())) return false;

            scope = receiver;

            return true;
        }

        private bool PerUnitScopeRetained(PerUnitHandoffSource witness, ExpressionSyntax expression,
            InvocationExpressionSyntax settlement, CleanupProvenanceContext proof) =>
            PerUnitScopeRetained(witness.Origin, witness.Binding, expression, settlement, proof);

        // Scope ownership authenticates source values, independently of how a work
        // lease is acquired. The anchor must be an actual use inside this lifetime.
        // The caller remains responsible for proving work and physical groups.
        private bool PerUnitScopeRetained(AuthoredMember owner, SyntaxNode ownershipAnchor,
            ExpressionSyntax expression, InvocationExpressionSyntax settlement, CleanupProvenanceContext proof)
        {
            if (proof.RemainingWork-- <= 0
                || CompletionPoint(owner, settlement, inheritedCompletion: false) is not { } completion
                || owner.Model.GetSymbolInfo(expression).Symbol is not ILocalSymbol scope
                || !IsExactFrameworkType(scope.Type, "Microsoft.Extensions.DependencyInjection.AsyncServiceScope",
                    typeof(Microsoft.Extensions.DependencyInjection.AsyncServiceScope).Assembly.GetName())) return false;

            List<InvocationExpressionSyntax> creations = [];

            if (scope.DeclaringSyntaxReferences is [SyntaxReference declaration]
                && declaration.GetSyntax() is VariableDeclaratorSyntax { Initializer.Value: InvocationExpressionSyntax initializer }) creations.Add(initializer);

            creations.AddRange(PerUnitVisited(owner.Syntax.DescendantNodes().OfType<AssignmentExpressionSyntax>()
                .Where(assignment => assignment.Left.DescendantNodesAndSelf().OfType<IdentifierNameSyntax>()
                    .Any(name => name.Identifier.ValueText == scope.Name)), proof)
                .Where(assignment => AssignmentTargetWritesSymbol(owner.Model, assignment.Left, scope))
                .Select(static assignment => assignment.Right).OfType<InvocationExpressionSyntax>());

            if (proof.RemainingWork <= 0 || creations is not [InvocationExpressionSyntax creation]
                || owner.Model.GetSymbolInfo(creation).Symbol is not IMethodSymbol method
                || !IsExactFrameworkMethod(method, "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions",
                    "CreateAsyncScope", "Microsoft.Extensions.DependencyInjection.Abstractions")
                || creation.Expression is not MemberAccessExpressionSyntax { Expression: { } factory }
                || creation.Span.End >= ownershipAnchor.SpanStart
                || !SymbolIsStableWithin(owner, scope, creation.Span.End, completion.Span.End)) return false;

            if (owner.Model.GetSymbolInfo(factory).Symbol is IParameterSymbol parameter
                && parameter.ContainingSymbol is IMethodSymbol { MethodKind: MethodKind.Constructor } constructor
                && SymbolEqualityComparer.Default.Equals(constructor.ContainingType, owner.Symbol.ContainingType)
                && IsExactFrameworkType(parameter.Type, "Microsoft.Extensions.DependencyInjection.IServiceScopeFactory",
                    typeof(Microsoft.Extensions.DependencyInjection.IServiceScopeFactory).Assembly.GetName()))
            {
                if (!PerUnitCapturedSlotStable(parameter, proof)) return false;
            }
            else if (!ReadinessScopeFactoryIsExact(owner, factory, proof)) return false;

            if (!PerUnitSourceSymbolStable(owner, scope, creation.Span.End, completion.Span.End, proof)) return false;

            foreach (IdentifierNameSyntax read in owner.Syntax.DescendantNodes().OfType<IdentifierNameSyntax>()
                .Where(identifier => identifier.Identifier.ValueText == scope.Name))
            {
                if (proof.RemainingWork-- <= 0) return false;

                if (read.SpanStart < creation.Span.End || read.SpanStart > completion.Span.End
                    || !SymbolEqualityComparer.Default.Equals(owner.Model.GetSymbolInfo(read).Symbol, scope)) continue;

                if (read.Parent is not MemberAccessExpressionSyntax { Expression: { } instance } access
                    || instance != read || owner.Model.GetSymbolInfo(access).Symbol is not IPropertySymbol { Name: "ServiceProvider" }
                    || access.Parent is not MemberAccessExpressionSyntax serviceAccess
                    || serviceAccess.Parent is not InvocationExpressionSyntax resolution
                    || !(PerUnitServiceProvider(owner, resolution, out _)
                        || owner.ReadinessSource is not null && ReadinessGetServices(owner, resolution, out _))) return false;
            }

            foreach (AnonymousFunctionExpressionSyntax callback in owner.Syntax.DescendantNodes().OfType<AnonymousFunctionExpressionSyntax>())
            {
                foreach (IdentifierNameSyntax identifier in callback.DescendantNodes().OfType<IdentifierNameSyntax>())
                {
                    if (proof.RemainingWork-- <= 0
                        || SymbolEqualityComparer.Default.Equals(owner.Model.GetSymbolInfo(identifier).Symbol, scope)) return false;
                }
            }

            if (creation.Ancestors().OfType<LocalDeclarationStatementSyntax>().FirstOrDefault() is
                { AwaitKeyword.RawKind: not 0, UsingKeyword.RawKind: not 0 } usingScope
                && usingScope.Parent is BlockSyntax block && block.Span.Contains(completion.Span)) return true;

            TryStatementSyntax? region = ownershipAnchor.Ancestors().OfType<TryStatementSyntax>()
                .FirstOrDefault(candidate => candidate.Block.Span.Contains(completion.Span) && candidate.Finally is not null);

            if (region?.Finally is null) return false;

            InvocationExpressionSyntax[] cleanup = PerUnitVisited(region.Finally.DescendantNodes().OfType<InvocationExpressionSyntax>()
                .Where(static call => PerUnitInvocationSpelling(call) == "DisposeAsync"), proof)
                .Where(call => call.Expression is MemberAccessExpressionSyntax access
                    && SymbolEqualityComparer.Default.Equals(owner.Model.GetSymbolInfo(access.Expression).Symbol, scope)
                    && owner.Model.GetSymbolInfo(call).Symbol is IMethodSymbol { Name: "DisposeAsync" } disposed
                    && IsExactFrameworkType(disposed.ContainingType, "Microsoft.Extensions.DependencyInjection.AsyncServiceScope",
                        typeof(Microsoft.Extensions.DependencyInjection.AsyncServiceScope).Assembly.GetName())).ToArray();

            if (proof.RemainingWork <= 0 || cleanup is not [InvocationExpressionSyntax joined]
                || !joined.Ancestors().OfType<AwaitExpressionSyntax>().Any()
                || joined.SpanStart <= completion.Span.End
                || joined.Ancestors().OfType<IfStatementSyntax>().FirstOrDefault() is not { } guard
                || !guard.Statement.Span.Contains(joined.Span)
                || joined.Ancestors().TakeWhile(node => node != region.Finally).Any(node =>
                    node is IfStatementSyntax conditional && conditional != guard
                    || node is ForStatementSyntax or ForEachStatementSyntax or WhileStatementSyntax or DoStatementSyntax
                        or SwitchStatementSyntax or AnonymousFunctionExpressionSyntax)
                || owner.Model.GetSymbolInfo(guard.Condition).Symbol is not ILocalSymbol initialized
                || initialized.Type.SpecialType != SpecialType.System_Boolean
                || initialized.DeclaringSyntaxReferences is not [SyntaxReference flagDeclaration]
                || flagDeclaration.GetSyntax() is not VariableDeclaratorSyntax
                {
                    Initializer.Value: LiteralExpressionSyntax initialFalse,
                }
                || !initialFalse.IsKind(SyntaxKind.FalseLiteralExpression)) return false;

            AssignmentExpressionSyntax[] flagWrites = PerUnitVisited(owner.Syntax.DescendantNodes().OfType<AssignmentExpressionSyntax>()
                .Where(assignment => assignment.Left.DescendantNodesAndSelf().OfType<IdentifierNameSyntax>()
                    .Any(name => name.Identifier.ValueText == initialized.Name)), proof)
                .Where(assignment => AssignmentTargetWritesSymbol(owner.Model, assignment.Left, initialized)).ToArray();

            if (proof.RemainingWork <= 0 || flagWrites is not [AssignmentExpressionSyntax set]
                || !set.IsKind(SyntaxKind.SimpleAssignmentExpression)
                || !set.Right.IsKind(SyntaxKind.TrueLiteralExpression)
                || set.SpanStart <= creation.Span.End || set.Span.End >= ownershipAnchor.SpanStart
                || set.Parent is not ExpressionStatementSyntax { Parent: BlockSyntax setBlock }
                || !setBlock.Span.Contains(ownershipAnchor.Span)
                || creation.Parent is not AssignmentExpressionSyntax { Parent: ExpressionStatementSyntax { Parent: BlockSyntax creationBlock } }
                || creationBlock != setBlock
                || !SymbolIsStableWithin(owner, initialized, set.Span.End, guard.SpanStart)
                || !PerUnitSourceSymbolStable(owner, initialized, set.Span.End, guard.SpanStart, proof)) return false;

            foreach (IdentifierNameSyntax identifier in PerUnitVisited(owner.Syntax.DescendantNodes()
                .OfType<AnonymousFunctionExpressionSyntax>().SelectMany(static callback => callback.DescendantNodes()
                    .OfType<IdentifierNameSyntax>()).Where(identifier => identifier.Identifier.ValueText == initialized.Name), proof))
            {
                if (SymbolEqualityComparer.Default.Equals(owner.Model.GetSymbolInfo(identifier).Symbol, initialized)) return false;
            }

            foreach (InvocationExpressionSyntax call in PerUnitVisited(owner.Syntax.DescendantNodes().OfType<InvocationExpressionSyntax>()
                .Where(call => call.SpanStart > creation.Span.End && call.SpanStart < completion.Span.End
                    && PerUnitInvocationSpelling(call) is "Dispose" or "DisposeAsync"), proof))
            {
                if (call.Expression is MemberAccessExpressionSyntax access
                    && SymbolEqualityComparer.Default.Equals(owner.Model.GetSymbolInfo(access.Expression).Symbol, scope)) return false;
            }

            return proof.RemainingWork > 0;
        }

        private bool PerUnitReconcilerMaterialization(ResolvedRegistration registration,
            IMethodSymbol constructor, AuthoredMember source, CleanupProvenanceContext proof, out IFieldSymbol retainedDictionary, out PerUnitMaterializationSource materialization)
        {
            retainedDictionary = null!;
            materialization = null!;

            if (registration.Call.ArgumentList.Arguments is not
                [ArgumentSyntax { Expression: AnonymousFunctionExpressionSyntax factory }]
                || ExactFactoryCreation(factory) is not BaseObjectCreationExpressionSyntax creation
                || registration.Model.GetOperation(creation) is not IObjectCreationOperation constructed
                || !SymbolEqualityComparer.Default.Equals(constructed.Constructor?.OriginalDefinition, constructor.OriginalDefinition)) return false;

            IParameterSymbol[] handlerParameters = source.Symbol.Parameters.Where(parameter => parameter.Type is INamedTypeSymbol named
                && TypeKey(named.OriginalDefinition) == "System.Collections.Generic.IEnumerable`1"
                && IsExactFrameworkType(named, "System.Collections.Generic.IEnumerable`1", typeof(IEnumerable<>).Assembly.GetName())
                && named.TypeArguments is [ITypeSymbol element]
                && IsExactAuthoredProtocolType(element,
                    "RetroDownfall.Arcanum.Core.Operations.ILongRunningOperationRecoveryHandler", source.Model.Compilation)).ToArray();

            if (handlerParameters is not [IParameterSymbol handlers]
                || constructed.Arguments.SingleOrDefault(argument => argument.Parameter?.Ordinal == handlers.Ordinal) is not
                { Syntax: ArgumentSyntax { Expression: InvocationExpressionSyntax services } }
                || registration.Model.GetSymbolInfo(services).Symbol is not IMethodSymbol resolver
                || !IsExactFrameworkMethod(resolver,
                    "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions", "GetServices",
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
                || resolver.TypeArguments is not [ITypeSymbol contract]
                || !SameBoundType(contract, registration.Model.Compilation,
                    ((INamedTypeSymbol)handlers.Type).TypeArguments[0], source.Model.Compilation)
                || !IsExactPerUnitFactoryProvider(registration.Model, factory, services)) return false;

            // The serving constructor may delegate materialization through this(...).
            // Follow only an exact identity conversion of the selected handlers formal.
            HashSet<IMethodSymbol> constructorPath = new(SymbolEqualityComparer.Default);

            List<AuthoredMember> selectedPath = [source];

            while (source.Syntax is ConstructorDeclarationSyntax { Initializer: { } initializer })
            {
                if (proof.RemainingWork-- <= 0 || !constructorPath.Add(source.Symbol)
                    || !initializer.IsKind(SyntaxKind.ThisConstructorInitializer)
                    || source.Model.GetOperation(initializer) is not IInvocationOperation forwarding
                    || !SymbolEqualityComparer.Default.Equals(forwarding.TargetMethod.ContainingType, source.Symbol.ContainingType)
                    || forwarding.Arguments.Where(argument => PerUnitTransparentOperation(argument.Value) is
                            IParameterReferenceOperation formal && SymbolEqualityComparer.Default.Equals(formal.Parameter, handlers))
                        .ToArray() is not [IArgumentOperation forwarded]
                    || forwarded.Parameter is not { RefKind: RefKind.None } nextFormal
                    || !forwarded.InConversion.IsIdentity || !forwarded.OutConversion.IsIdentity
                    || !SymbolIsStableWithin(source, handlers, source.Syntax.SpanStart, initializer.Span.End)
                    || ResolveConstructorContextTarget(forwarding.TargetMethod, source.Model.Compilation) is not { } next) return false;

                source = next;
                selectedPath.Add(source);
                handlers = source.Symbol.Parameters[nextFormal.Ordinal];
            }

            VariableDeclaratorSyntax[] arrays = PerUnitVisited(source.Syntax.DescendantNodes().OfType<VariableDeclaratorSyntax>()
                .Where(static variable => variable.Initializer?.Value is CollectionExpressionSyntax
                    { Elements: [SpreadElementSyntax] }), proof)
                .Where(variable => variable.Initializer!.Value is CollectionExpressionSyntax
                    { Elements: [SpreadElementSyntax spread] }
                    && SymbolEqualityComparer.Default.Equals(source.Model.GetSymbolInfo(spread.Expression).Symbol, handlers)).ToArray();

            if (proof.RemainingWork <= 0 || arrays is not [VariableDeclaratorSyntax array]
                || source.Syntax is not ConstructorDeclarationSyntax { Body: { } materializingBody }
                || array.Parent?.Parent is not LocalDeclarationStatementSyntax { Parent: BlockSyntax arrayBlock }
                || arrayBlock != materializingBody
                || source.Model.GetDeclaredSymbol(array) is not ILocalSymbol materialized) return false;

            AssignmentExpressionSyntax[] dictionaries = PerUnitVisited(source.Syntax.DescendantNodes().OfType<AssignmentExpressionSyntax>()
                .Where(static assignment => assignment.Right is InvocationExpressionSyntax call
                    && PerUnitInvocationSpelling(call) == "ToDictionary"), proof)
                .Where(assignment => source.Model.GetSymbolInfo(assignment.Left).Symbol is IFieldSymbol
                    { IsReadOnly: true, IsStatic: false, DeclaredAccessibility: Accessibility.Private } field
                    && field.Type is INamedTypeSymbol dictionary
                    && TypeKey(dictionary) == "System.Collections.Generic.IReadOnlyDictionary`2"
                    && IsExactFrameworkType(dictionary, "System.Collections.Generic.IReadOnlyDictionary`2",
                        typeof(IReadOnlyDictionary<,>).Assembly.GetName())
                    && dictionary.TypeArguments is [ITypeSymbol key, ITypeSymbol value]
                    && key.SpecialType == SpecialType.System_String
                    && SameBoundType(value, source.Model.Compilation, contract, registration.Model.Compilation)
                    && assignment.Right is InvocationExpressionSyntax call
                    && call.Expression is MemberAccessExpressionSyntax access
                    && SymbolEqualityComparer.Default.Equals(source.Model.GetSymbolInfo(access.Expression).Symbol, materialized)
                    && source.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method
                    && IsExactFrameworkMethod(method, "System.Linq.Enumerable", "ToDictionary", "System.Linq")).ToArray();

            if (proof.RemainingWork <= 0 || dictionaries is not [AssignmentExpressionSyntax stored]
                || source.Model.GetSymbolInfo(stored.Left).Symbol is not IFieldSymbol retained
                || stored.Parent is not ExpressionStatementSyntax { Parent: BlockSyntax storeBlock }
                || storeBlock != materializingBody || array.Span.End >= stored.SpanStart
                || PerUnitVisited(materializingBody.DescendantNodes().Where(node =>
                    node.SpanStart < stored.SpanStart && node is ReturnStatementSyntax or GotoStatementSyntax), proof).Any()
                || proof.RemainingWork <= 0
                || stored.Right is not InvocationExpressionSyntax toDictionary
                || !PerUnitDictionarySelectorIsExact(source, toDictionary, contract, registration.Model.Compilation)) return false;

            HashSet<IMethodSymbol> selectedConstructors = new(selectedPath.Select(static member => member.Symbol),
                SymbolEqualityComparer.Default);

            foreach (SyntaxReference declaration in retained.ContainingType.DeclaringSyntaxReferences)
            {
                if (proof.RemainingWork-- <= 0
                    || !semanticModels.TryGetValue(declaration.SyntaxTree, out SemanticModel? model)) return false;

                foreach (SyntaxNode node in PerUnitMutationCandidates(declaration.GetSyntax(), retained))
                {
                    if (proof.RemainingWork-- <= 0) return false;

                    if (node == stored) continue;

                    if (!PerUnitChargeWriteVisit(node, proof)) return false;

                    if (!SyntaxNodeWritesSymbol(model, node, retained)) continue;

                    if (!PerUnitUnselectedConstructorStore(model, node, retained, selectedConstructors)) return false;
                }
            }

            // The private array is consumed only by authenticated, read-only source
            // uses. A mutable alias or unknown consumer prevents handler identity proof.
            if (!PerUnitMaterializedArrayStable(source, handlers, materialized, array, toDictionary, proof)
                || !PerUnitRetainedDictionaryStable(retained, source.Model.Compilation, proof,
                    new HashSet<ISymbol>(SymbolEqualityComparer.Default), stored, selectedConstructors)) return false;

            retainedDictionary = retained;
            materialization = new(source, handlers, services, stored);

            return proof.RemainingWork-- > 0;
        }

        private bool PerUnitMaterializedArrayStable(AuthoredMember source, IParameterSymbol handlers,
            ILocalSymbol array, VariableDeclaratorSyntax declaration, InvocationExpressionSyntax dictionary,
            CleanupProvenanceContext proof)
        {
            foreach (IdentifierNameSyntax read in source.Syntax.DescendantNodes().OfType<IdentifierNameSyntax>()
                .Where(identifier => identifier.Identifier.ValueText == handlers.Name || identifier.Identifier.ValueText == array.Name))
            {
                if (proof.RemainingWork-- <= 0) return false;

                ISymbol? symbol = source.Model.GetSymbolInfo(read).Symbol;

                if (SymbolEqualityComparer.Default.Equals(symbol, handlers))
                {
                    if (read.Parent is SpreadElementSyntax spread && declaration.Span.Contains(spread.Span)) continue;

                    if (read.Parent is ArgumentSyntax argument && argument.Parent?.Parent is InvocationExpressionSyntax guard
                        && source.Model.GetSymbolInfo(guard).Symbol is IMethodSymbol method
                        && IsExactFrameworkMethod(method, "System.ArgumentNullException", "ThrowIfNull", "System.Private.CoreLib")) continue;

                    return false;
                }

                if (!SymbolEqualityComparer.Default.Equals(symbol, array)) continue;

                if (dictionary.Span.Contains(read.Span)) continue;

                if (read.Parent is not ArgumentSyntax { RefKindKeyword.RawKind: 0 } passed
                    || passed.Parent?.Parent is not InvocationExpressionSyntax call
                    || source.Model.GetOperation(call) is not IInvocationOperation invocation
                    || invocation.TargetMethod.ContainingType is not { } owner
                    || !SymbolEqualityComparer.Default.Equals(owner, source.Symbol.ContainingType)
                    || Resolve(invocation.TargetMethod, source.Model.Compilation) is not { } consumer
                    || invocation.Arguments.SingleOrDefault(argument => argument.Syntax == passed)?.Parameter is not { } formal
                    || !PerUnitReadOnlyHandlerSequence(consumer, consumer.Symbol.Parameters[formal.Ordinal], proof)) return false;
            }

            return true;
        }

        private static ExpressionSyntax? PerUnitLambdaValue(AnonymousFunctionExpressionSyntax lambda) => lambda switch
        {
            SimpleLambdaExpressionSyntax { Body: ExpressionSyntax expression } => expression,
            ParenthesizedLambdaExpressionSyntax { Body: ExpressionSyntax expression } => expression,
            _ => null,
        };

        private bool PerUnitReadOnlyHandlerSequence(AuthoredMember source, IParameterSymbol formal,
            CleanupProvenanceContext proof)
        {
            foreach (IdentifierNameSyntax read in source.Syntax.DescendantNodes().OfType<IdentifierNameSyntax>()
                .Where(identifier => identifier.Identifier.ValueText == formal.Name))
            {
                if (proof.RemainingWork-- <= 0) return false;

                if (!SymbolEqualityComparer.Default.Equals(source.Model.GetSymbolInfo(read).Symbol, formal)) continue;

                if (read.Parent is not MemberAccessExpressionSyntax access || access.Expression != read
                    || access.Parent is not InvocationExpressionSyntax call
                    || source.Model.GetSymbolInfo(call).Symbol is not IMethodSymbol method
                    || !IsExactFrameworkMethod(method, "System.Linq.Enumerable", "Select", "System.Linq")
                    || call.ArgumentList.Arguments is not [ArgumentSyntax { Expression: AnonymousFunctionExpressionSyntax selector }]
                    || PerUnitLambdaValue(selector) is not MemberAccessExpressionSyntax selected
                    || source.Model.GetSymbolInfo(selected).Symbol is not IPropertySymbol { Name: "Kind" } property
                    || !IsExactAuthoredProtocolType(property.ContainingType,
                        "RetroDownfall.Arcanum.Core.Operations.ILongRunningOperationRecoveryHandler", source.Model.Compilation)
                    || source.Model.GetSymbolInfo(selected.Expression).Symbol is not IParameterSymbol element
                    || element.DeclaringSyntaxReferences is not [SyntaxReference declaration]
                    || !selector.Span.Contains(declaration.Span)) return false;
            }

            return true;
        }

        private static bool PerUnitUnselectedConstructorStore(SemanticModel model, SyntaxNode node,
            ISymbol field, IReadOnlySet<IMethodSymbol> selectedConstructors) =>
            node is AssignmentExpressionSyntax assignment
            && assignment.IsKind(SyntaxKind.SimpleAssignmentExpression)
            && AssignmentTargetWritesSymbol(model, assignment.Left, field)
            && assignment.Ancestors().OfType<ConstructorDeclarationSyntax>().FirstOrDefault() is { } constructor
            && model.GetDeclaredSymbol(constructor) is IMethodSymbol exact
            && !selectedConstructors.Contains(exact);

        private bool PerUnitRetainedDictionaryStable(ISymbol symbol, Compilation compilation,
            CleanupProvenanceContext proof, HashSet<ISymbol> active,
            AssignmentExpressionSyntax? selectedStore, IReadOnlySet<IMethodSymbol> selectedConstructors)
        {
            if (proof.RemainingWork-- <= 0 || !active.Add(symbol)) return false;

            try
            {
                IEnumerable<SyntaxReference> references = symbol is IFieldSymbol field
                    ? field.ContainingType.DeclaringSyntaxReferences
                    : symbol.ContainingSymbol.DeclaringSyntaxReferences;

                foreach (SyntaxReference declaration in references)
                {
                    if (!semanticModels.TryGetValue(declaration.SyntaxTree, out SemanticModel? model)) return false;

                    foreach (IdentifierNameSyntax read in declaration.GetSyntax().DescendantNodes().OfType<IdentifierNameSyntax>()
                        .Where(identifier => identifier.Identifier.ValueText == symbol.Name))
                    {
                        if (proof.RemainingWork-- <= 0) return false;

                        if (!SymbolEqualityComparer.Default.Equals(model.GetSymbolInfo(read).Symbol, symbol)) continue;

                        if (symbol is IFieldSymbol && read.Parent is AssignmentExpressionSyntax assignment
                            && assignment.Left == read && assignment.IsKind(SyntaxKind.SimpleAssignmentExpression)
                            && (assignment == selectedStore
                                || PerUnitUnselectedConstructorStore(model, assignment, symbol, selectedConstructors))) continue;

                        if (read.Parent is MemberAccessExpressionSyntax access && access.Expression == read
                            && model.GetSymbolInfo(access).Symbol is { } member
                            && IsExactFrameworkType(member.ContainingType, "System.Collections.Generic.IReadOnlyDictionary`2",
                                typeof(IReadOnlyDictionary<,>).Assembly.GetName())
                            && (member is IPropertySymbol { Name: "Count" }
                                || member is IMethodSymbol { Name: "TryGetValue" or "ContainsKey" })) continue;

                        if (read.Parent is ElementAccessExpressionSyntax index && index.Expression == read
                            && model.GetSymbolInfo(index).Symbol is IPropertySymbol property
                            && IsExactFrameworkType(property.ContainingType, "System.Collections.Generic.IReadOnlyDictionary`2",
                                typeof(IReadOnlyDictionary<,>).Assembly.GetName())
                            && index.Parent is not AssignmentExpressionSyntax) continue;

                        if (read.Parent is ArgumentSyntax { RefKindKeyword.RawKind: 0 } passed
                            && passed.Parent?.Parent is InvocationExpressionSyntax call
                            && model.GetOperation(call) is IInvocationOperation invocation
                            && SymbolEqualityComparer.Default.Equals(invocation.TargetMethod.ContainingType, symbol.ContainingType)
                            && Resolve(invocation.TargetMethod, model.Compilation) is { } target
                            && invocation.Arguments.SingleOrDefault(argument => argument.Syntax == passed)?.Parameter is { RefKind: RefKind.None } formal
                            && PerUnitRetainedDictionaryStable(target.Symbol.Parameters[formal.Ordinal], target.Model.Compilation,
                                proof, active, selectedStore, selectedConstructors)) continue;

                        return false;
                    }
                }

                return true;
            }
            finally
            {
                active.Remove(symbol);
            }
        }

        private bool TryBindPerUnitRecoveryHandoff(AuthoredMember caller, InvocationExpressionSyntax call,
            RecoveryHandlerTarget target, RecoveryTuple tuple, string rootType, string operationId,
            string? work, AuthoredMember bound, out AuthoredMember authenticated)
        {
            authenticated = bound;

            CleanupProvenanceContext proof = new();

            if (!TryGetPerUnitHandoffSource(work, rootType, operationId, proof,
                    out PerUnitHandoffSource witness, out InvocationExpressionSyntax settlement)
                || AdmissionReceiver(witness.Origin, settlement) is not { } receiver
                || PerUnitStableLocalValue(witness.Origin, receiver, settlement.Span.End, proof,
                    new HashSet<ISymbol>(SymbolEqualityComparer.Default)) is not { } actualReceiver) return false;

            IMethodSymbol selectedConstructor;

            if (actualReceiver is BaseObjectCreationExpressionSyntax created)
            {
                if (witness.Origin.Model.GetOperation(created) is not IObjectCreationOperation reconciler
                    || reconciler.Constructor is not { } reconcilerConstructor
                    || reconciler.Arguments.Where(argument => argument.Parameter is { } parameter
                            && SameBoundType(parameter.Type, witness.Origin.Model.Compilation,
                                witness.Holder.Bind.Symbol.ContainingType, witness.Holder.Bind.Model.Compilation))
                        .ToArray() is not [IArgumentOperation { Syntax: ArgumentSyntax admissionArgument } argument]
                    || !argument.InConversion.IsIdentity || argument.Parameter?.RefKind != RefKind.None
                    || !PerUnitSameReceiver(witness, admissionArgument.Expression, settlement.Span.End, proof)) return false;

                if (caller.Model.GetOperation(call) is not IInvocationOperation dispatch
                    || dispatch.Instance?.Syntax is not ExpressionSyntax handlerReceiver
                    || PerUnitStableLocalValue(caller, handlerReceiver, call.Span.End, proof,
                        new HashSet<ISymbol>(SymbolEqualityComparer.Default)) is not BaseObjectCreationExpressionSyntax handlerCreation
                    || caller.Model.GetOperation(handlerCreation) is not IObjectCreationOperation handler
                    || handler.Constructor is not { } handlerConstructor
                    || !SameBoundType(handlerConstructor.ContainingType, caller.Model.Compilation,
                        target.Member.Symbol.ContainingType, target.Member.Model.Compilation)
                    || handlerCreation.ArgumentList?.Arguments is not [ArgumentSyntax handlerArgument]
                    || handler.Arguments is not [IArgumentOperation { ArgumentKind: ArgumentKind.Explicit } passed]
                    || handlerConstructor.Parameters is not [IParameterSymbol handlerFormal]
                    || handlerFormal.IsParams || !SymbolEqualityComparer.Default.Equals(passed.Parameter, handlerFormal)
                    || !PerUnitExplicitArgumentMatchesSource(caller, handlerCreation, handlerArgument, passed, proof)
                    || !passed.InConversion.IsIdentity || passed.Parameter?.RefKind != RefKind.None
                    || caller.Model.GetSymbolInfo(StripTransparentExpression(handlerArgument.Expression)).Symbol is not IParameterSymbol slot
                    || passed.Value is not IParameterReferenceOperation actualSlot
                    || !SymbolEqualityComparer.Default.Equals(slot, actualSlot.Parameter)
                    || slot.ContainingSymbol is not IMethodSymbol { MethodKind: MethodKind.Constructor } owner
                    || !SameBoundType(owner.ContainingType, caller.Model.Compilation,
                        reconcilerConstructor.ContainingType, witness.Origin.Model.Compilation)
                    || slot.Ordinal != argument.Parameter.Ordinal
                    || ResolveConstructorContextTarget(reconcilerConstructor, witness.Origin.Model.Compilation) is not { } selectedReconciler
                    || !SymbolEqualityComparer.Default.Equals(owner.OriginalDefinition, selectedReconciler.Symbol.OriginalDefinition)
                    || !SameBoundType(slot.Type, caller.Model.Compilation,
                        witness.Holder.Bind.Symbol.ContainingType, witness.Holder.Bind.Model.Compilation)
                    || !PerUnitConstructorSlotStable(caller, slot, proof)) return false;

                selectedConstructor = ResolveConstructorContextTarget(handlerConstructor, caller.Model.Compilation)?.Symbol ?? handlerConstructor;
            }
            else
            {
                ExpressionSyntax? admissionResolution = PerUnitStableLocalValue(witness.Origin,
                    witness.Receiver, settlement.Span.End, proof, new HashSet<ISymbol>(SymbolEqualityComparer.Default));

                if (actualReceiver is not InvocationExpressionSyntax resolvedReconciler
                    || admissionResolution is not InvocationExpressionSyntax resolvedAdmission
                    || !PerUnitServiceProvider(witness.Origin, resolvedReconciler, out ExpressionSyntax reconcilerScope)
                    || !PerUnitServiceProvider(witness.Origin, resolvedAdmission, out ExpressionSyntax admissionScope)
                    || !SymbolEqualityComparer.Default.Equals(witness.Origin.Model.GetSymbolInfo(reconcilerScope).Symbol,
                        witness.Origin.Model.GetSymbolInfo(admissionScope).Symbol)
                    || !PerUnitScopeRetained(witness, admissionScope, settlement, proof)
                    || witness.Origin.Model.GetSymbolInfo(resolvedReconciler).Symbol is not IMethodSymbol resolver
                    || !TrySelectPerUnitScopedConstruction(resolver.TypeArguments[0], witness.Origin.Model.Compilation, proof,
                        out ResolvedRegistration registration, out IMethodSymbol reconcilerConstructor, out AuthoredMember? reconciler)
                    || reconciler is null || !PerUnitReconcilerMaterialization(registration, reconcilerConstructor, reconciler, proof,
                        out IFieldSymbol retainedDictionary, out PerUnitMaterializationSource materialization)
                    || !PerUnitHandlerLookupUsesDictionary(caller, call, retainedDictionary, registration, materialization,
                        witness, settlement, proof)
                    || !TrySelectPerUnitScopedConstruction(witness.Holder.Bind.Symbol.ContainingType,
                        witness.Holder.Bind.Model.Compilation, proof, out _, out _, out _)
                    || !TrySelectPerUnitScopedConstruction(target.Member.Symbol.ContainingType,
                        target.Member.Model.Compilation, proof, out _, out IMethodSymbol activated, out _)
                    || !SameBoundType(activated.ContainingType, target.Member.Model.Compilation,
                        target.Member.Symbol.ContainingType, target.Member.Model.Compilation)) return false;

                selectedConstructor = ResolveConstructorContextTarget(activated, target.Member.Model.Compilation)?.Symbol ?? activated;
            }

            Dictionary<ISymbol, BoundValueSource> values = new(bound.ValueBindings ?? new Dictionary<ISymbol, BoundValueSource>(SymbolEqualityComparer.Default), SymbolEqualityComparer.Default);

            foreach (IParameterSymbol parameter in selectedConstructor.Parameters.Where(parameter =>
                SameBoundType(parameter.Type, target.Member.Model.Compilation,
                    witness.Holder.Bind.Symbol.ContainingType, witness.Holder.Bind.Model.Compilation)))
            {
                BoundValueSource actual = new(witness.Origin, witness.Receiver);

                if (values.TryGetValue(parameter, out BoundValueSource? previous)
                    && !PerUnitSameBoundSource(previous, actual)) return false;

                values[parameter] = actual;
            }

            HashSet<IMethodSymbol> constructors = new(bound.ConstructorContexts ?? Enumerable.Empty<IMethodSymbol>(),
                SymbolEqualityComparer.Default);

            if (constructors.Any(existing => SymbolEqualityComparer.Default.Equals(existing.ContainingType,
                    selectedConstructor.ContainingType)
                && !SymbolEqualityComparer.Default.Equals(existing.OriginalDefinition, selectedConstructor.OriginalDefinition))) return false;

            constructors.Add(selectedConstructor);

            // A handler without a holder retains only its selected constructor
            // identity. A later exact receiver edge must reconstruct and authenticate
            // its dependency before introducing that dependency's holder slot.
            if (proof.RemainingWork <= 0) return false;

            authenticated = bound with
            {
                ValueBindings = values,
                ConstructorContexts = constructors,
            };

            return true;
        }

        private bool PerUnitConstructorSlotStable(AuthoredMember context, IParameterSymbol slot, CleanupProvenanceContext proof)
        {
            return PerUnitCapturedSlotStable(slot, proof)
                && (context.ConstructorContexts is not { Count: > 0 }
                    || context.ConstructorContexts.Any(constructor => SymbolEqualityComparer.Default.Equals(
                        constructor.OriginalDefinition, slot.ContainingSymbol.OriginalDefinition)));
        }

        private bool RequiresPerUnitHolderArgumentSource(AuthoredMember caller,
            ExpressionSyntax argument, IParameterSymbol parameter)
        {
            if (caller.RecoveryContext is not { Disposition: RecoveryDisposition.OrdinaryPerUnitExternalEffect }
                || parameter.RefKind != RefKind.None || parameter.Type is not INamedTypeSymbol type) return false;

            CleanupProvenanceContext proof = new();

            if (!type.GetMembers("Bind").OfType<IMethodSymbol>().Any(method =>
                    TryGetPerUnitHolderSource(method, PerUnitExactSourceCompilation(type) ?? caller.Model.Compilation,
                        proof, out _))) return false;

            ExpressionSyntax? value = PerUnitStableLocalValue(caller, argument, argument.Span.End, proof,
                new HashSet<ISymbol>(SymbolEqualityComparer.Default));

            if (value is null || caller.Model.GetSymbolInfo(value).Symbol is not IParameterSymbol slot
                || caller.ValueBindings?.ContainsKey(slot) != true || slot.RefKind != RefKind.None) return false;

            return slot.ContainingSymbol is not IMethodSymbol { MethodKind: MethodKind.Constructor }
                || caller.ConstructorContexts?.Any(constructor => SymbolEqualityComparer.Default.Equals(
                    constructor.OriginalDefinition, slot.ContainingSymbol.OriginalDefinition)) == true
                    && PerUnitConstructorSlotStable(caller, slot, proof);
        }

        private static bool PerUnitExplicitArgumentMatchesSource(AuthoredMember caller,
            BaseObjectCreationExpressionSyntax creation, ArgumentSyntax argument,
            IArgumentOperation passed, CleanupProvenanceContext proof)
        {
            if (proof.RemainingWork-- <= 0
                || !ReferenceEquals(creation.SyntaxTree, caller.Model.SyntaxTree)
                || !ReferenceEquals(creation.SyntaxTree, caller.Syntax.SyntaxTree)
                || !caller.Syntax.Span.Contains(creation.Span)) return false;

            if (proof.RemainingWork-- <= 0 || argument.Parent is not ArgumentListSyntax arguments
                || arguments.Parent is not BaseObjectCreationExpressionSyntax actualCreation
                || !SameSyntax(actualCreation, creation)) return false;

            ExpressionSyntax expression = argument.Expression;

            while (expression is PostfixUnaryExpressionSyntax suppression
                && suppression.IsKind(SyntaxKind.SuppressNullableWarningExpression))
            {
                if (proof.RemainingWork-- <= 0) return false;

                expression = suppression.Operand;
            }

            // Roslyn can attach an Explicit argument operation to the operand of
            // source null-forgiving syntax. Its value must still use that exact node.
            return proof.RemainingWork-- > 0
                && (SameSyntax(passed.Syntax, argument) || SameSyntax(passed.Syntax, expression))
                && proof.RemainingWork-- > 0 && SameSyntax(passed.Value.Syntax, expression);

            static bool SameSyntax(SyntaxNode left, SyntaxNode right) =>
                ReferenceEquals(left.SyntaxTree, right.SyntaxTree)
                && left.Span == right.Span && left.RawKind == right.RawKind;
        }

        private AuthoredMember BindPerUnitRecoveryReceiverContext(AuthoredMember caller,
            InvocationExpressionSyntax call, AuthoredMember target, AuthoredMember genericBound,
            string rootType, string operationId, string? work, bool detached, SyntaxNode? completion)
        {
            if (caller.ReadinessSource is { SelectedConstructors: not null })
                return BindReadinessRecoveryReceiver(caller, call, genericBound, operationId, work, detached, completion);

            // Retain prior real method-formal bindings. Imported instance bindings from
            // the generic receiver resolver cannot establish this route's instance.
            Dictionary<ISymbol, BoundValueSource> values = (genericBound.ValueBindings ??
                    new Dictionary<ISymbol, BoundValueSource>(SymbolEqualityComparer.Default)).Where(pair =>
                    !(pair.Key is IFieldSymbol { IsStatic: false } field
                            && IsPerUnitProtectedSourceType(field.ContainingType,
                                PerUnitExactSourceCompilation(field.ContainingType) ?? target.Model.Compilation))
                    && !(pair.Key is IParameterSymbol
                        {
                            ContainingSymbol: IMethodSymbol { MethodKind: MethodKind.Constructor } constructor,
                        }
                        && IsPerUnitProtectedSourceType(constructor.ContainingType,
                            PerUnitExactSourceCompilation(constructor.ContainingType) ?? target.Model.Compilation)))
                .ToDictionary(static pair => pair.Key, static pair => pair.Value, SymbolEqualityComparer.Default);

            HashSet<IMethodSymbol> unrelatedConstructors = new((genericBound.ConstructorContexts ??
                Enumerable.Empty<IMethodSymbol>()).Where(constructor => !IsPerUnitProtectedSourceType(
                    constructor.ContainingType, PerUnitExactSourceCompilation(constructor.ContainingType) ?? target.Model.Compilation)),
                SymbolEqualityComparer.Default);

            AuthoredMember refused = genericBound with { ValueBindings = values, ConstructorContexts = unrelatedConstructors };

            if (caller.RecoveryContext is not { Disposition: RecoveryDisposition.OrdinaryPerUnitExternalEffect }
                || caller.ConstructorContexts?.GroupBy(static constructor => constructor.ContainingType,
                    SymbolEqualityComparer.Default).Any(group => group.Count() != 1) == true) return refused;

            CleanupProvenanceContext proof = new();

            if (!TryGetPerUnitHandoffSource(work, rootType, operationId, proof,
                out PerUnitHandoffSource witness, out InvocationExpressionSyntax settlement)) return refused;

            if (proof.RemainingWork-- <= 0
                || caller.Model.GetOperation(call) is not IInvocationOperation invocation) return refused;

            ExpressionSyntax? receiver = invocation.Instance?.Syntax as ExpressionSyntax;

            if (target.Symbol.IsStatic
                || call.Expression is IdentifierNameSyntax or GenericNameSyntax
                    && invocation.Instance is IInstanceReferenceOperation
                || call.Expression is MemberAccessExpressionSyntax { Expression: ThisExpressionSyntax }
                    && invocation.Instance is IInstanceReferenceOperation)
            {
                // A static helper has no new instance; only the same authored owner can
                // retain its current construction. Explicit holder arguments retain their
                // actual Caller edges independently through ordinary argument binding.
                if (!SameBoundType(caller.Symbol.ContainingType, caller.Model.Compilation,
                    target.Symbol.ContainingType, target.Model.Compilation)) return refused;

                foreach ((ISymbol key, BoundValueSource source) in caller.ValueBindings ??
                    Enumerable.Empty<KeyValuePair<ISymbol, BoundValueSource>>())
                {
                    if (key is IParameterSymbol { ContainingSymbol: IMethodSymbol { MethodKind: MethodKind.Constructor } owner }
                        && caller.ConstructorContexts?.Any(constructor => SymbolEqualityComparer.Default.Equals(
                            constructor.OriginalDefinition, owner.OriginalDefinition)) == true)
                    {
                        if (genericBound.ValueBindings?.TryGetValue(key, out BoundValueSource? existing) == true
                            && !PerUnitSameBoundSource(existing, source)) return refused;

                        values[key] = source;
                    }
                }

                return refused with { ValueBindings = values, ConstructorContexts = caller.ConstructorContexts };
            }

            if (receiver is null) return refused;

            ExpressionSyntax? actual = PerUnitStableLocalValue(caller, receiver, call.Span.End, proof,
                new HashSet<ISymbol>(SymbolEqualityComparer.Default));

            if (actual is null || caller.Model.GetSymbolInfo(actual).Symbol is not IParameterSymbol dependency
                || dependency.ContainingSymbol is not IMethodSymbol { MethodKind: MethodKind.Constructor } owningConstructor
                || caller.ConstructorContexts?.Any(constructor => SymbolEqualityComparer.Default.Equals(
                    constructor.OriginalDefinition, owningConstructor.OriginalDefinition)) != true
                || !PerUnitConstructorSlotStable(caller, dependency, proof)) return refused;

            // A holder method receiver must already be an exact holder source binding.
            // It never creates a holder instance from matching names or types.
            if (SameBoundType(dependency.Type, caller.Model.Compilation,
                witness.Holder.Bind.Symbol.ContainingType, witness.Holder.Bind.Model.Compilation))
            {
                if (!PerUnitHolderReceiverSharesSource(caller, actual, call.SpanStart, witness, proof,
                    new HashSet<(GraphMemberIdentity Member, int Start, int Length)>())) return refused;

                if (caller.ValueBindings?.TryGetValue(dependency, out BoundValueSource? boundHolder) != true
                    || boundHolder is null) return refused;

                values[dependency] = boundHolder;

                return refused with { ValueBindings = values };
            }

            // Only a dependency supplied by the already authenticated serving scoped
            // provider can cross to a different selected constructor in this grammar.
            if (PerUnitStableLocalValue(witness.Origin, witness.Receiver, settlement.Span.End, proof,
                    new HashSet<ISymbol>(SymbolEqualityComparer.Default)) is not InvocationExpressionSyntax resolvedAdmission
                || !PerUnitServiceProvider(witness.Origin, resolvedAdmission, out ExpressionSyntax scope)
                || !PerUnitScopeRetained(witness, scope, settlement, proof)
                || !IsPerUnitProtectedSourceType(dependency.Type, caller.Model.Compilation)
                || !TrySelectPerUnitScopedConstruction(dependency.Type, caller.Model.Compilation, proof,
                    out _, out IMethodSymbol selected, out AuthoredMember? construction)
                || construction is null
                || !SameBoundType(selected.ContainingType, construction.Model.Compilation,
                    target.Symbol.ContainingType, target.Model.Compilation)) return refused;

            foreach (IParameterSymbol slot in selected.Parameters.Where(parameter => SameBoundType(parameter.Type,
                construction.Model.Compilation, witness.Holder.Bind.Symbol.ContainingType, witness.Holder.Bind.Model.Compilation)))
            {
                if (!PerUnitConstructorSlotStable(construction, slot, proof)) return refused;

                BoundValueSource actualSource = new(witness.Origin, witness.Receiver);

                if (genericBound.ValueBindings?.TryGetValue(slot, out BoundValueSource? existing) == true
                    && !PerUnitSameBoundSource(existing, actualSource)) return refused;

                values[slot] = actualSource;
            }

            return refused with
            {
                ValueBindings = values,
                ConstructorContexts = new HashSet<IMethodSymbol>([selected], SymbolEqualityComparer.Default),
            };
        }

        private bool PerUnitHolderReceiverSharesSource(AuthoredMember member, ExpressionSyntax receiver,
            int through, PerUnitHandoffSource witness, CleanupProvenanceContext proof,
            HashSet<(GraphMemberIdentity Member, int Start, int Length)> active)
        {
            if (proof.RemainingWork-- <= 0) return false;

            var identity = (MemberIdentity(member), receiver.SpanStart, receiver.Span.Length);

            if (!active.Add(identity)) return false;

            try
            {
                ExpressionSyntax? actual = PerUnitStableLocalValue(member, receiver, through, proof,
                    new HashSet<ISymbol>(SymbolEqualityComparer.Default));

                if (actual is null || member.Model.GetSymbolInfo(actual).Symbol is not IParameterSymbol slot
                    || slot.RefKind != RefKind.None
                    || !SameBoundType(slot.Type, member.Model.Compilation,
                        witness.Holder.Bind.Symbol.ContainingType, witness.Holder.Bind.Model.Compilation)
                    || member.ValueBindings?.TryGetValue(slot, out BoundValueSource? source) != true
                    || source is null) return false;

                if (slot.ContainingSymbol is IMethodSymbol { MethodKind: MethodKind.Constructor } constructor)
                {
                    return member.ConstructorContexts?.Any(selected => SymbolEqualityComparer.Default.Equals(
                            selected.OriginalDefinition, constructor.OriginalDefinition)) == true
                        && PerUnitConstructorSlotStable(member, slot, proof)
                        && MemberIdentity(source.Caller) == MemberIdentity(witness.Origin)
                        && PerUnitSameReceiver(witness, source.Expression, witness.Binding.Span.End, proof);
                }

                return SymbolEqualityComparer.Default.Equals(slot.ContainingSymbol, member.Symbol)
                    && SymbolIsStableWithin(member, slot, member.Syntax.SpanStart, through)
                    && source.Expression.SyntaxTree == source.Caller.Syntax.SyntaxTree
                    && source.Caller.Syntax.Span.Contains(source.Expression.Span)
                    && PerUnitHolderReceiverSharesSource(source.Caller, source.Expression,
                        source.Expression.Span.End, witness, proof, active);
            }
            finally
            {
                active.Remove(identity);
            }
        }

        private bool PerUnitLeaseReceiverSharesSource(AuthoredMember member, ExpressionSyntax receiver,
            int through, PerUnitHandoffSource witness, CleanupProvenanceContext proof)
        {
            ExpressionSyntax? actual = PerUnitStableLocalValue(member, receiver, through, proof,
                new HashSet<ISymbol>(SymbolEqualityComparer.Default));

            return actual is MemberAccessExpressionSyntax access
                && member.Model.GetOperation(access) is IPropertyReferenceOperation read
                && !read.Property.IsStatic && !read.Property.IsVirtual && !read.Property.IsIndexer
                && !read.Property.ReturnsByRef && !read.Property.ReturnsByRefReadonly
                && read.Property.GetMethod is { } getter
                && Resolve(getter, member.Model.Compilation) is { } authoredGetter
                && SymbolEqualityComparer.Default.Equals(authoredGetter.Symbol.OriginalDefinition,
                    witness.Holder.Getter.GetMethod!.OriginalDefinition)
                && PerUnitHolderReceiverSharesSource(member, access.Expression, through, witness, proof,
                    new HashSet<(GraphMemberIdentity Member, int Start, int Length)>());
        }

        private bool PerUnitPhysicalGroupSharesWork(AuthoredMember member, SyntaxNode site,
            string rootType, string operationId, string? work, string? effect)
        {
            CleanupProvenanceContext proof = new();

            ReadinessRecoverySource? independent = member.ReadinessSource is { AdmissionActive: true, OwnedAdmission: { } own } sourceProof
                && work == RootOperation(operationId) + "@work:" + Location(own.Acquisition) ? sourceProof : null;

            PerUnitHandoffSource witness = null!;

            if (independent is null && !TryGetPerUnitHandoffSource(work, rootType, operationId, proof,
                out witness, out _)) return false;

            bool ReceiverProved(AuthoredMember source, InvocationExpressionSyntax group) =>
                proof.RemainingWork-- > 0 && source.Model.GetSymbolInfo(group).Symbol is IMethodSymbol method
                && Normalize(method) == "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease.TryBeginExternalEffectGroup"
                && IsExactAuthoredProtocolType(method.ContainingType,
                    "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease", source.Model.Compilation)
                && IsGuardedAdmission(group)
                && AdmissionReceiver(source, group) is { } receiver
                && (independent is null
                    ? PerUnitLeaseReceiverSharesSource(source, receiver, group.SpanStart, witness, proof)
                    : source.ReadinessSource is { AdmissionActive: true } actual
                        && actual.Identity == independent.Identity
                        && ReadinessLeaseReceiver(source, receiver, group.SpanStart, actual, proof));

            if (site is InvocationExpressionSyntax frontier
                && PerUnitInvocationSpelling(frontier) == "TryBeginExternalEffectGroup")
                return ReceiverProved(member, frontier);

            if (effect is null || !effect.StartsWith(RootOperation(operationId) + "@effect:", StringComparison.Ordinal)) return false;

            string location = effect[(effect.LastIndexOf("@effect:", StringComparison.Ordinal) + 8)..];

            // Local sends first authenticate the actually retained guarded group.
            if (FindRetainedAdmission(member, site, "TryBeginExternalEffectGroup", null) is { } local)
            {
                InvocationExpressionSyntax[] groups = AdmissionSyntax(member).AdmissionCalls
                    .Where(call => Location(call) == local && local == location).ToArray();

                return groups is [InvocationExpressionSyntax group] && ReceiverProved(member, group);
            }

            if (independent is not null)
                return independent is { GroupOwner: { } groupOwner, GroupFrontier: { } inheritedGroup }
                    && Location(inheritedGroup) == location && ReceiverProved(groupOwner, inheritedGroup);

            // An inherited callback group needs a surviving real source edge to its
            // bound owner. Capsule/source location alone cannot reconstruct an instance.
            Stack<AuthoredMember> pending = new();

            HashSet<AuthoredMember> visited = new(ReferenceEqualityComparer.Instance);

            pending.Push(member);

            while (pending.TryPop(out AuthoredMember? source))
            {
                if (proof.RemainingWork-- <= 0) return false;

                if (!visited.Add(source)) continue;

                InvocationExpressionSyntax[] groups = AdmissionSyntax(source).AdmissionCalls
                    .Where(call => Location(call) == location).ToArray();

                if (groups is [InvocationExpressionSyntax group] && ReceiverProved(source, group)) return true;

                foreach (BoundValueSource value in source.ValueBindings?.Values ?? Enumerable.Empty<BoundValueSource>())
                {
                    if (proof.RemainingWork-- <= 0) return false;

                    pending.Push(value.Caller);
                }
            }

            return false;
        }

        private bool RequiresPerUnitReconcilerSourceValue(AuthoredMember caller,
            ExpressionSyntax argument, IParameterSymbol parameter, AuthoredMember target)
        {
            if (parameter.RefKind != RefKind.None || !IsExactAuthoredProtocolType(target.Symbol.ContainingType,
                    "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationReconciler", target.Model.Compilation)) return false;

            bool dictionary = parameter.Type is INamedTypeSymbol named
                && TypeKey(named) == "System.Collections.Generic.IReadOnlyDictionary`2"
                && IsExactFrameworkType(named, "System.Collections.Generic.IReadOnlyDictionary`2",
                    typeof(IReadOnlyDictionary<,>).Assembly.GetName())
                && named.TypeArguments is [ITypeSymbol { SpecialType: SpecialType.System_String }, ITypeSymbol handler]
                && IsExactAuthoredProtocolType(handler,
                    "RetroDownfall.Arcanum.Core.Operations.ILongRunningOperationRecoveryHandler", target.Model.Compilation);

            if (!dictionary) return false;

            // The actual readonly dictionary argument is semantically used by the
            // handler lookup. It never itself certifies admission.
            return ResolveRecoveryMatrix(argument).Tuples.Any(static tuple =>
                tuple.Disposition == RecoveryDisposition.OrdinaryPerUnitExternalEffect);
        }

        private bool PerUnitDictionaryTerm(AuthoredMember member, ExpressionSyntax expression,
            IFieldSymbol retained, ResolvedRegistration registration, PerUnitMaterializationSource materialization,
            PerUnitHandoffSource witness, InvocationExpressionSyntax settlement,
            CleanupProvenanceContext proof, HashSet<(GraphMemberIdentity Member, int Start, int Length)> active)
        {
            if (proof.RemainingWork-- <= 0) return false;

            var key = (MemberIdentity(member), expression.SpanStart, expression.Span.Length);

            if (!active.Add(key)) return false;

            try
            {
                ExpressionSyntax? actual = PerUnitStableLocalValue(member, expression, expression.Span.End, proof,
                    new HashSet<ISymbol>(SymbolEqualityComparer.Default));

                if (actual is null) return false;

                ISymbol? symbol = member.Model.GetSymbolInfo(actual).Symbol;

                if (symbol is IFieldSymbol field && SymbolEqualityComparer.Default.Equals(field, retained))
                    return member.Model.GetOperation(actual) is IFieldReferenceOperation { Instance: IInstanceReferenceOperation }
                        && PerUnitFieldMaterializationMatchesScope(member, field, registration, materialization, witness, settlement, proof);

                return symbol is IParameterSymbol { RefKind: RefKind.None } formal
                    && SymbolEqualityComparer.Default.Equals(formal.ContainingSymbol, member.Symbol)
                    && SymbolIsStableWithin(member, formal, member.Syntax.SpanStart, actual.Span.End)
                    && member.ValueBindings?.TryGetValue(formal, out BoundValueSource? source) == true
                    && PerUnitDictionaryTerm(source.Caller, source.Expression, retained, registration, materialization,
                        witness, settlement, proof, active);
            }
            finally
            {
                active.Remove(key);
            }
        }

        private bool PerUnitHandlerLookupUsesDictionary(AuthoredMember caller, InvocationExpressionSyntax call,
            IFieldSymbol retained, ResolvedRegistration registration, PerUnitMaterializationSource materialization,
            PerUnitHandoffSource witness, InvocationExpressionSyntax settlement, CleanupProvenanceContext proof) =>
            TryGetPerUnitHandlerDictionary(caller, call, proof, out ExpressionSyntax dictionary)
                && PerUnitDictionaryTerm(caller, dictionary, retained, registration, materialization, witness, settlement, proof,
                    new HashSet<(GraphMemberIdentity Member, int Start, int Length)>());

        // A guarded handler lookup identifies an actual dictionary value. That value
        // still needs provider/materialization proof; this is never lease authority.
        private bool TryGetPerUnitHandlerDictionary(AuthoredMember caller, InvocationExpressionSyntax call,
            CleanupProvenanceContext proof, out ExpressionSyntax dictionary)
        {
            dictionary = null!;

            if (AdmissionReceiver(caller, call) is not { } receiver
                || caller.Model.GetSymbolInfo(StripTransparentExpression(receiver)).Symbol is not ILocalSymbol handler) return false;

            InvocationExpressionSyntax[] lookups = PerUnitVisited(caller.Syntax.DescendantNodes().OfType<InvocationExpressionSyntax>()
                .Where(candidate => candidate.Span.End < call.SpanStart
                    && PerUnitInvocationSpelling(candidate) == "TryGetValue"), proof)
                .Where(candidate => caller.Model.GetOperation(candidate) is IInvocationOperation operation
                    && operation.Arguments.Any(argument => argument.Parameter?.RefKind == RefKind.Out
                        && PerUnitAcquisitionOutput(argument.Value) is ILocalReferenceOperation output
                        && SymbolEqualityComparer.Default.Equals(output.Local, handler))).ToArray();

            if (proof.RemainingWork <= 0 || lookups is not [InvocationExpressionSyntax lookup]
                || proof.RemainingWork-- <= 0
                || caller.Model.GetSymbolInfo(lookup).Symbol is not IMethodSymbol method
                || !IsExactFrameworkMethod(method, "System.Collections.Generic.IReadOnlyDictionary`2", "TryGetValue",
                    typeof(IReadOnlyDictionary<,>).Assembly.GetName().Name!)
                || !IsGuardedAdmission(lookup)
                || !SymbolIsStableWithin(caller, handler, lookup.Span.End, call.Span.End)
                || AdmissionReceiver(caller, lookup) is not { } actualDictionary) return false;

            dictionary = actualDictionary;

            return true;
        }

        private AuthoredMember BindPerUnitReconcilerEntryContext(AuthoredMember caller,
            InvocationExpressionSyntax call, AuthoredMember bound, string rootType,
            string operationId, string? work)
        {
            if (PerUnitInvocationSpelling(call) != "SettleDiscoveredRuntimeAsync") return bound;

            CleanupProvenanceContext proof = new();

            if (proof.RemainingWork-- <= 0
                || caller.Model.GetSymbolInfo(call).Symbol is not IMethodSymbol { Name: "SettleDiscoveredRuntimeAsync" } method
                || !IsExactAuthoredProtocolType(method.ContainingType,
                    "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationReconciler", caller.Model.Compilation)) return bound;

            if (!TryGetPerUnitHandoffSource(work, rootType, operationId, proof,
                    out PerUnitHandoffSource witness, out InvocationExpressionSyntax settlement)
                || MemberIdentity(caller) != MemberIdentity(witness.Origin)
                || call.SyntaxTree != settlement.SyntaxTree || call.Span != settlement.Span
                || AdmissionReceiver(caller, call) is not { } receiver
                || PerUnitStableLocalValue(caller, receiver, call.Span.End, proof,
                    new HashSet<ISymbol>(SymbolEqualityComparer.Default)) is not InvocationExpressionSyntax resolved
                || !PerUnitServiceProvider(caller, resolved, out ExpressionSyntax scope)
                || !PerUnitScopeRetained(witness, scope, settlement, proof)
                || !TrySelectPerUnitScopedConstruction(method.ContainingType, caller.Model.Compilation, proof,
                    out ResolvedRegistration registration, out IMethodSymbol constructor, out AuthoredMember? source)
                || source is null
                || !PerUnitReconcilerMaterialization(registration, constructor, source, proof,
                    out IFieldSymbol field, out PerUnitMaterializationSource materialization)
                || registration.Call.ArgumentList.Arguments is not
                    [ArgumentSyntax { Expression: AnonymousFunctionExpressionSyntax factory }]
                || registration.Model.GetOperation(factory) is not IAnonymousFunctionOperation function
                || function.Symbol.Parameters is not [IParameterSymbol provider]
                || resolved.Expression is not MemberAccessExpressionSyntax { Expression: { } providerExpression }) return bound;

            // These are actual values consumed by the selected materialization: the
            // factory provider, its GetServices result, and the readonly dictionary.
            AuthoredMember factoryContext = new(function.Symbol, factory, registration.Model,
                ValueBindings: new Dictionary<ISymbol, BoundValueSource>(SymbolEqualityComparer.Default)
                {
                    [provider] = new(caller, providerExpression),
                });

            AuthoredMember constructorContext = materialization.Constructor with
            {
                ValueBindings = new Dictionary<ISymbol, BoundValueSource>(SymbolEqualityComparer.Default)
                {
                    [materialization.Handlers] = new(factoryContext, materialization.Services),
                },
                ConstructorContexts = new HashSet<IMethodSymbol>([materialization.Constructor.Symbol], SymbolEqualityComparer.Default),
            };

            BoundValueSource actual = new(constructorContext, materialization.Store.Right);

            if (bound.ValueBindings?.TryGetValue(field, out BoundValueSource? previous) == true
                && !PerUnitMaterializationValueCompatible(previous, actual, proof))
            {
                RefuseTraversalCompletion();

                diagnostics.Add(new("HOSTED_RECOVERY_PER_UNIT_HANDOFF_UNPROVEN", operationId + "/call@" + Location(call),
                    "The selected Reconciler field has competing construction provenance."));

                return RemovePerUnitReconcilerFieldContext(bound);
            }

            Dictionary<ISymbol, BoundValueSource> values = new(bound.ValueBindings ??
                new Dictionary<ISymbol, BoundValueSource>(SymbolEqualityComparer.Default), SymbolEqualityComparer.Default)
            {
                [field] = actual,
            };

            HashSet<IMethodSymbol> constructors = new((bound.ConstructorContexts ?? Enumerable.Empty<IMethodSymbol>())
                .Where(selected => !SameBoundType(selected.ContainingType, bound.Model.Compilation,
                    field.ContainingType, constructorContext.Model.Compilation)), SymbolEqualityComparer.Default);

            constructors.Add(materialization.Constructor.Symbol);

            return bound with { ValueBindings = values, ConstructorContexts = constructors };
        }

        private bool PerUnitMaterializationValueCompatible(BoundValueSource existing,
            BoundValueSource selected, CleanupProvenanceContext proof)
        {
            if (proof.RemainingWork-- <= 0 || existing.Expression.SyntaxTree != selected.Expression.SyntaxTree
                || existing.Expression.Span != selected.Expression.Span
                || !SymbolEqualityComparer.Default.Equals(existing.Caller.Symbol.OriginalDefinition,
                    selected.Caller.Symbol.OriginalDefinition)) return false;

            // Missing demanded constructor arguments are filled from the authenticated
            // actual factory edge. An already-bound argument may not disagree with it.
            foreach ((ISymbol symbol, BoundValueSource actual) in selected.Caller.ValueBindings ??
                Enumerable.Empty<KeyValuePair<ISymbol, BoundValueSource>>())
            {
                if (proof.RemainingWork-- <= 0) return false;

                if (existing.Caller.ValueBindings?.TryGetValue(symbol, out BoundValueSource? old) != true) continue;

                if (old is null || old.Expression.SyntaxTree != actual.Expression.SyntaxTree || old.Expression.Span != actual.Expression.Span
                    || MemberIdentity(old.Caller) != MemberIdentity(actual.Caller)) return false;

                foreach ((ISymbol provider, BoundValueSource source) in actual.Caller.ValueBindings ??
                    Enumerable.Empty<KeyValuePair<ISymbol, BoundValueSource>>())
                {
                    if (proof.RemainingWork-- <= 0) return false;

                    if (old.Caller.ValueBindings?.TryGetValue(provider, out BoundValueSource? prior) == true
                        && !PerUnitSameBoundSource(prior, source)) return false;
                }
            }

            return true;
        }

        private bool PerUnitSameBoundSource(BoundValueSource left, BoundValueSource right)
        {
            if (left.Expression.SyntaxTree != right.Expression.SyntaxTree || left.Expression.Span != right.Expression.Span
                || MemberIdentity(left.Caller) != MemberIdentity(right.Caller)) return false;

            EvaluationEnvironmentFingerprint first = EvaluationEnvironmentIdentity(left.Caller);
            EvaluationEnvironmentFingerprint second = EvaluationEnvironmentIdentity(right.Caller);

            return first.Complete && second.Complete && first.Identity == second.Identity;
        }

        private AuthoredMember RemovePerUnitReconcilerFieldContext(AuthoredMember member)
        {
            return member with
            {
                ValueBindings = member.ValueBindings?.Where(pair => pair.Key is not IFieldSymbol field
                    || !IsExactAuthoredProtocolType(field.ContainingType,
                        "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationReconciler", member.Model.Compilation))
                    .ToDictionary(static pair => pair.Key, static pair => pair.Value, SymbolEqualityComparer.Default),
                ConstructorContexts = member.ConstructorContexts?.Where(constructor => !IsExactAuthoredProtocolType(
                    constructor.ContainingType, "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationReconciler",
                    member.Model.Compilation)).ToHashSet<IMethodSymbol>(SymbolEqualityComparer.Default),
            };
        }

        private AuthoredMember PreservePerUnitReconcilerFieldContext(AuthoredMember caller,
            SyntaxNode node, AuthoredMember bound)
        {
            CleanupProvenanceContext proof = new();

            KeyValuePair<ISymbol, BoundValueSource>[] fields = PerUnitVisited((caller.ValueBindings ??
                new Dictionary<ISymbol, BoundValueSource>(SymbolEqualityComparer.Default)).Where(static pair => pair.Key is IFieldSymbol), proof)
                .Where(pair => pair.Key is IFieldSymbol
                { IsStatic: false, IsReadOnly: true, DeclaredAccessibility: Accessibility.Private } field
                && IsExactAuthoredProtocolType(field.ContainingType,
                    "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationReconciler", caller.Model.Compilation)
                && pair.Value.Caller.Symbol.MethodKind == MethodKind.Constructor
                && pair.Value.Expression is InvocationExpressionSyntax creation
                && pair.Value.Caller.Model.GetSymbolInfo(creation).Symbol is IMethodSymbol method
                && IsExactFrameworkMethod(method, "System.Linq.Enumerable", "ToDictionary", "System.Linq")).ToArray();

            if (proof.RemainingWork <= 0)
            {
                RefuseTraversalCompletion();

                return RemovePerUnitReconcilerFieldContext(bound);
            }

            if (fields.Length == 0) return bound;

            if (fields.Length != 1 || node is not InvocationExpressionSyntax call
                || caller.Model.GetOperation(call) is not IInvocationOperation invocation
                || invocation.TargetMethod.IsStatic
                || !SameBoundType(caller.Symbol.ContainingType, caller.Model.Compilation,
                    bound.Symbol.ContainingType, bound.Model.Compilation)
                || !(call.Expression is IdentifierNameSyntax or GenericNameSyntax
                    && invocation.Instance is IInstanceReferenceOperation
                    || call.Expression is MemberAccessExpressionSyntax { Expression: ThisExpressionSyntax }
                        && invocation.Instance is IInstanceReferenceOperation)) return RemovePerUnitReconcilerFieldContext(bound);

            var selected = fields[0];

            if (bound.ValueBindings?.TryGetValue(selected.Key, out BoundValueSource? existing) == true
                && !PerUnitSameBoundSource(existing, selected.Value))
            {
                RefuseTraversalCompletion();

                return RemovePerUnitReconcilerFieldContext(bound);
            }

            Dictionary<ISymbol, BoundValueSource> values = new(bound.ValueBindings ??
                new Dictionary<ISymbol, BoundValueSource>(SymbolEqualityComparer.Default), SymbolEqualityComparer.Default)
            {
                [selected.Key] = selected.Value,
            };

            HashSet<IMethodSymbol> constructors = new(bound.ConstructorContexts ?? Enumerable.Empty<IMethodSymbol>(),
                SymbolEqualityComparer.Default);

            foreach (IMethodSymbol constructor in caller.ConstructorContexts ?? Enumerable.Empty<IMethodSymbol>())
            {
                if (constructors.Any(existing => SymbolEqualityComparer.Default.Equals(existing.ContainingType,
                        constructor.ContainingType)
                    && !SymbolEqualityComparer.Default.Equals(existing.OriginalDefinition, constructor.OriginalDefinition)))
                {
                    RefuseTraversalCompletion();

                    return RemovePerUnitReconcilerFieldContext(bound);
                }

                constructors.Add(constructor);
            }

            return bound with { ValueBindings = values, ConstructorContexts = constructors };
        }

        private bool PerUnitFieldMaterializationMatchesScope(AuthoredMember member, IFieldSymbol field,
            ResolvedRegistration registration, PerUnitMaterializationSource materialization,
            PerUnitHandoffSource witness, InvocationExpressionSyntax settlement, CleanupProvenanceContext proof) =>
            PerUnitFieldMaterializationMatchesScope(member, field, registration, materialization,
                witness.Origin, witness.Receiver, witness.Binding, settlement, proof);

        private bool PerUnitFieldMaterializationMatchesScope(AuthoredMember member, IFieldSymbol field,
            ResolvedRegistration registration, PerUnitMaterializationSource materialization,
            AuthoredMember origin, ExpressionSyntax scopedResolution, SyntaxNode ownershipAnchor,
            InvocationExpressionSyntax settlement, CleanupProvenanceContext proof)
        {
            if (proof.RemainingWork-- <= 0
                || member.ValueBindings?.TryGetValue(field, out BoundValueSource? source) != true
                || source is null
                || source.Caller.Symbol.MethodKind != MethodKind.Constructor
                || !SymbolEqualityComparer.Default.Equals(source.Caller.Symbol.OriginalDefinition,
                    materialization.Constructor.Symbol.OriginalDefinition)
                || source.Expression.SyntaxTree != materialization.Store.Right.SyntaxTree
                || source.Expression.Span != materialization.Store.Right.Span
                || source.Expression is not InvocationExpressionSyntax dictionary
                || source.Caller.Model.GetSymbolInfo(dictionary).Symbol is not IMethodSymbol method
                || !IsExactFrameworkMethod(method, "System.Linq.Enumerable", "ToDictionary", "System.Linq")) return false;

            IParameterSymbol[] handlers = source.Caller.Symbol.Parameters.Where(parameter => parameter.Type is INamedTypeSymbol type
                && TypeKey(type) == "System.Collections.Generic.IEnumerable`1"
                && IsExactFrameworkType(type, "System.Collections.Generic.IEnumerable`1", typeof(IEnumerable<>).Assembly.GetName())
                && type.TypeArguments is [ITypeSymbol element]
                && IsExactAuthoredProtocolType(element,
                    "RetroDownfall.Arcanum.Core.Operations.ILongRunningOperationRecoveryHandler", source.Caller.Model.Compilation)).ToArray();

            if (handlers is not [IParameterSymbol parameter]
                || !SymbolEqualityComparer.Default.Equals(parameter, materialization.Handlers)
                || source.Caller.ValueBindings?.TryGetValue(parameter, out BoundValueSource? services) != true
                || services is null
                || services.Expression is not InvocationExpressionSyntax resolution
                || resolution.SyntaxTree != materialization.Services.SyntaxTree || resolution.Span != materialization.Services.Span
                || registration.Call.ArgumentList.Arguments is not
                    [ArgumentSyntax { Expression: AnonymousFunctionExpressionSyntax selectedFactory }]
                || services.Caller.Syntax.SyntaxTree != selectedFactory.SyntaxTree || services.Caller.Syntax.Span != selectedFactory.Span
                || !ReferenceEquals(services.Caller.Model.Compilation, registration.Model.Compilation)
                || services.Caller.Model.GetOperation(services.Caller.Syntax) is not IAnonymousFunctionOperation function
                || function.Symbol.Parameters is not [IParameterSymbol provider]
                || !IsExactPerUnitFactoryProvider(services.Caller.Model,
                    (AnonymousFunctionExpressionSyntax)services.Caller.Syntax, resolution)
                || services.Caller.ValueBindings?.TryGetValue(provider, out BoundValueSource? providerValue) != true
                || providerValue is null
                || MemberIdentity(providerValue.Caller) != MemberIdentity(origin)
                || providerValue.Expression is not MemberAccessExpressionSyntax actualProvider
                || origin.Model.GetSymbolInfo(actualProvider).Symbol is not IPropertySymbol { Name: "ServiceProvider" } property
                || !IsExactFrameworkType(property.ContainingType, "Microsoft.Extensions.DependencyInjection.AsyncServiceScope",
                    typeof(Microsoft.Extensions.DependencyInjection.AsyncServiceScope).Assembly.GetName())
                || PerUnitStableLocalValue(origin, scopedResolution, settlement.Span.End, proof,
                    new HashSet<ISymbol>(SymbolEqualityComparer.Default)) is not InvocationExpressionSyntax holderResolution
                || !PerUnitServiceProvider(origin, holderResolution, out ExpressionSyntax expectedScope)
                || !SymbolEqualityComparer.Default.Equals(origin.Model.GetSymbolInfo(actualProvider.Expression).Symbol,
                    origin.Model.GetSymbolInfo(expectedScope).Symbol)) return false;

            return PerUnitScopeRetained(origin, ownershipAnchor, expectedScope, settlement, proof);
        }

        private TraversalEvidence TraverseAuthenticatedRecoveryDispatch(
            AuthoredMember caller,
            InvocationExpressionSyntax call,
            IMethodSymbol contractMethod,
            string rootType,
            string operationId,
            HashSet<TraversalStateIdentity> active,
            bool lifecycle)
        {
            RecoveryMatrix matrix = ResolveRecoveryMatrix(call);

            string rootOperation = RootOperation(operationId);

            HostedProducerOperationEntry[] roots = declaredOperations
                .Where(operation => operation.OperationId == rootOperation)
                .ToArray();

            if (!matrix.IsValid)
            {
                return TraversalEvidence.Inconclusive;
            }

            if (roots is not [HostedProducerOperationEntry root])
            {
                diagnostics.Add(new(
                    "HOSTED_RECOVERY_AUTHORITY_UNPROVEN",
                    operationId,
                    "Authenticated offline-transition dispatch requires one declared exact-owner recovery root."));

                return TraversalEvidence.Inconclusive;
            }

            if (!AuthenticatedRecoveryDispatchIsExact(
                    caller,
                    call,
                    out string exactnessFailure))
            {
                diagnostics.Add(new(
                    "HOSTED_RECOVERY_OWNER_DISPATCH_UNPROVEN",
                    operationId,
                    "Authenticated journal recovery must select one current owner-bound handler behind exact evidence and tuple guards; "
                        + exactnessFailure
                        + "."));

                return TraversalEvidence.Inconclusive;
            }

            if (root.Authority != HostedProducerAuthorityKind.OwnerBoundRecovery)
            {
                // The authenticated dispatcher is the authority handoff. Only its
                // declared exact-owner root expands the owner-only handlers; callers
                // retain evidence that they reached the closed handoff without
                // re-attributing or multiplying the protected work graph.
                return TraversalEvidence.Evidence;
            }

            RecoveryHandlerTarget[] targets = ResolveRecoveryHandlerTargets(
                caller,
                contractMethod,
                call,
                matrix);

            return TraverseComposedOwnerRecoveryDispatch(
                caller,
                call,
                rootType,
                operationId,
                active,
                lifecycle,
                matrix,
                targets,
                "authenticated-recovery",
                "RecoverAuthenticatedAsync");
        }

        private TraversalEvidence TraverseComposedOwnerRecoveryDispatch(
            AuthoredMember caller,
            InvocationExpressionSyntax call,
            string rootType,
            string operationId,
            HashSet<TraversalStateIdentity> active,
            bool lifecycle,
            RecoveryMatrix matrix,
            IReadOnlyList<RecoveryHandlerTarget> targets,
            string pathSegment,
            string handlerMethod)
        {
            RecoveryTuple[] tuples = ProvenOwnerTuplesAt(
                caller,
                call,
                matrix,
                allowAuthenticatedAdmission: handlerMethod ==
                    "RecoverAuthenticatedAsync",
                allowLaunchGapAdoption: handlerMethod == "RecoverAsync");

            if (tuples.Length == 0)
            {
                diagnostics.Add(new(
                    "HOSTED_RECOVERY_OWNER_DISPATCH_UNPROVEN",
                    operationId,
                    "Every owner recovery dispatch call must bind exactly one current owner-bound kind and checkpoint version."));

                return TraversalEvidence.Inconclusive;
            }

            TraversalEvidence evidence = TraversalEvidence.NoEvidence;

            foreach (RecoveryTuple tuple in tuples)
            {
                RecoveryHandlerTarget[] servingTargets = targets
                    .Where(target => target.Composition.HasFlag(
                            RecoveryCompositionKind.Serving)
                        && target.Kind == tuple.Kind
                        && target.SupportedCheckpointVersion == tuple.CheckpointVersion)
                    .ToArray();

                RecoveryHandlerTarget[] stoppedTargets = targets
                    .Where(target => target.Composition.HasFlag(
                            RecoveryCompositionKind.StoppedHost)
                        && target.Kind == tuple.Kind
                        && target.SupportedCheckpointVersion == tuple.CheckpointVersion)
                    .ToArray();

                if (servingTargets is not [RecoveryHandlerTarget serving]
                    || stoppedTargets is not [RecoveryHandlerTarget stopped])
                {
                    evidence = MergeEvidence(
                        evidence,
                        TraversalEvidence.Inconclusive);

                    continue;
                }

                foreach (RecoveryHandlerTarget target in new[] { serving, stopped })
                {
                    evidence = MergeEvidence(
                        evidence,
                        TraverseOwnerRecoveryTarget(
                            caller,
                            call,
                            rootType,
                            operationId,
                            active,
                            lifecycle,
                            target,
                            tuple,
                            pathSegment,
                            handlerMethod));
                }
            }

            return evidence;
        }

        private bool AuthenticatedRecoveryDispatchIsExact(
            AuthoredMember dispatch,
            InvocationExpressionSyntax call,
            out string failure)
        {
            if (dispatch.Symbol.Name != "DispatchAsync"
                || !IsExactAuthoredProtocolType(
                    dispatch.Symbol.ContainingType,
                    "RetroDownfall.Arcanum.Infrastructure.GrimoireTransitions.GrimoireOfflineTransitionHandlerDispatch",
                    dispatch.Model.Compilation))
            {
                failure = "the typed call is not owned by the one offline-transition dispatcher";

                return false;
            }

            IParameterSymbol[] evidenceParameters = dispatch.Symbol.Parameters
                .Where(parameter => IsExactAuthoredProtocolType(
                    parameter.Type,
                    "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningRecoveryOwnerEvidence",
                    dispatch.Model.Compilation))
                .ToArray();

            if (evidenceParameters is not [IParameterSymbol evidence])
            {
                failure = "the dispatcher does not receive one exact recovery-owner evidence value";

                return false;
            }

            IfStatementSyntax[] dominanceGuards = call.Ancestors()
                .TakeWhile(ancestor => ancestor != dispatch.Syntax)
                .OfType<IfStatementSyntax>()
                .Where(guard => guard.Statement.Span.Contains(call.Span))
                .ToArray();

            if (!dominanceGuards.Any(guard => IsAuthenticatedEvidenceGuard(
                    dispatch,
                    guard.Condition,
                    evidence)
                && !guard.Statement.DescendantNodesAndSelf()
                    .OfType<GotoStatementSyntax>()
                    .Any()))
            {
                failure = "RecoverAuthenticatedAsync is not dominated by the exact authenticated-journal evidence test";

                return false;
            }

            if (!ExactAuthenticatedHandlerSelection(dispatch, call))
            {
                failure = "the typed handler is not selected by exact kind/version equality, a two-item cap, and a one-item refusal";

                return false;
            }

            failure = string.Empty;

            return true;
        }

        private bool IsAuthenticatedEvidenceGuard(
            AuthoredMember dispatch,
            ExpressionSyntax condition,
            IParameterSymbol evidence)
        {
            condition = StripTransparentExpression(condition);

            if (condition is not IsPatternExpressionSyntax
                {
                    Expression: { } tested,
                    Pattern: { } pattern,
                })
            {
                return false;
            }

            bool exactParameter = SymbolEqualityComparer.Default.Equals(
                    dispatch.Model.GetSymbolInfo(tested).Symbol,
                    evidence)
                || tested is IdentifierNameSyntax identifier
                    && identifier.Identifier.ValueText == evidence.Name;

            if (!exactParameter)
            {
                return false;
            }

            TypeSyntax? evidenceType = pattern switch
            {
                DeclarationPatternSyntax declaration => declaration.Type,
                TypePatternSyntax type => type.Type,
                RecursivePatternSyntax recursive => recursive.Type,
                _ => null,
            };

            ITypeSymbol? resolved = evidenceType is null
                ? null
                : dispatch.Model.GetTypeInfo(evidenceType).Type
                    ?? dispatch.Model.GetSymbolInfo(evidenceType).Symbol as ITypeSymbol;

            return IsExactAuthoredProtocolType(
                resolved,
                "RetroDownfall.Arcanum.Infrastructure.GrimoireTransitions.AuthenticatedJournalRecoveryOwnerEvidence",
                dispatch.Model.Compilation);
        }

        private bool ExactAuthenticatedHandlerSelection(
            AuthoredMember dispatch,
            InvocationExpressionSyntax call)
        {
            if (!TryGetExactRecoveryHandlerSelection(
                    dispatch,
                    call,
                    out RecoveryHandlerSelection selection)
                || selection.CallContainer is not ExpressionStatementSyntax
                    and not LocalDeclarationStatementSyntax)
            {
                return false;
            }

            IfStatementSyntax[] cardinalityGuards = selection.Block.Statements
                .OfType<IfStatementSyntax>()
                .Where(guard => guard.SpanStart > selection.Declaration.Span.End
                    && guard.Span.End < selection.CallContainer.SpanStart
                    && DefinitelyTerminates(guard.Statement)
                    && IsHandlerCountComparison(
                        dispatch,
                        guard.Condition,
                        selection.Handlers,
                        SyntaxKind.NotEqualsExpression,
                        1))
                .ToArray();

            return cardinalityGuards is [IfStatementSyntax cardinalityGuard]
                && ExactFailureTermination(dispatch, cardinalityGuard.Statement)
                && HandlerSelectionIsStable(
                    dispatch,
                    selection,
                    call,
                    cardinalityGuard.Condition);
        }

        private bool LaunchGapRecoveryDispatchIsExact(
            AuthoredMember dispatch,
            InvocationExpressionSyntax call,
            bool allowLegacyFallback)
        {
            if (dispatch.Symbol.Name != "DispatchAsync"
                || !IsExactAuthoredProtocolType(
                    dispatch.Symbol.ContainingType,
                    "RetroDownfall.Arcanum.Infrastructure.GrimoireTransitions.GrimoireOfflineTransitionHandlerDispatch",
                    dispatch.Model.Compilation))
            {
                return false;
            }

            IParameterSymbol[] ownerEvidenceParameters = dispatch.Symbol.Parameters
                .Where(parameter =>
                    IsExactAuthoredProtocolType(
                        parameter.Type,
                        "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningRecoveryOwnerEvidence",
                        dispatch.Model.Compilation))
                .ToArray();

            if (ownerEvidenceParameters is not [IParameterSymbol ownerEvidence])
            {
                return false;
            }

            if (!TryGetExactRecoveryHandlerSelection(
                    dispatch,
                    call,
                    out RecoveryHandlerSelection selection))
            {
                return false;
            }

            if (selection.CallContainer is not IfStatementSyntax singleHandler
                || !singleHandler.Statement.Span.Contains(call.Span)
                || !DefinitelyTerminates(singleHandler.Statement)
                || !IsHandlerCountComparison(
                    dispatch,
                    singleHandler.Condition,
                    selection.Handlers,
                    SyntaxKind.EqualsExpression,
                    1))
            {
                return false;
            }

            bool excludesAuthenticatedEvidence = selection.Block.Statements
                .OfType<IfStatementSyntax>()
                .Any(guard => guard.Span.End < selection.Declaration.SpanStart
                    && IsAuthenticatedEvidenceGuard(
                        dispatch,
                        guard.Condition,
                        ownerEvidence)
                    && !guard.Statement.DescendantNodesAndSelf()
                        .OfType<GotoStatementSyntax>()
                        .Any()
                    && DefinitelyTerminates(guard.Statement));

            if (!excludesAuthenticatedEvidence)
            {
                return false;
            }

            IfStatementSyntax[] duplicateRefusals = selection.Block.Statements
                .OfType<IfStatementSyntax>()
                .Where(guard => guard.SpanStart > selection.Declaration.Span.End
                    && guard.Span.End < singleHandler.SpanStart
                    && ExactFailureTermination(dispatch, guard.Statement)
                    && IsHandlerCountComparison(
                        dispatch,
                        guard.Condition,
                        selection.Handlers,
                        SyntaxKind.GreaterThanExpression,
                        1))
                .ToArray();

            int singleHandlerIndex = selection.Block.Statements.IndexOf(singleHandler);

            if (duplicateRefusals is not [IfStatementSyntax duplicateRefusal]
                || singleHandlerIndex < 0)
            {
                return false;
            }

            if (!ExactLaunchGapFallback(
                    dispatch,
                    selection,
                    call,
                    ownerEvidence,
                    singleHandlerIndex,
                    allowLegacyFallback))
            {
                return false;
            }

            if (!HandlerSelectionIsStable(
                    dispatch,
                    selection,
                    call,
                    duplicateRefusal.Condition,
                    singleHandler.Condition))
            {
                return false;
            }

            return true;
        }

        private bool ExactLaunchGapFallback(
            AuthoredMember dispatch,
            RecoveryHandlerSelection selection,
            InvocationExpressionSyntax handlerCall,
            IParameterSymbol ownerEvidence,
            int singleHandlerIndex,
            bool allowLegacyFallback)
        {
            if (singleHandlerIndex + 1 >= selection.Block.Statements.Count)
            {
                return false;
            }

            StatementSyntax fallbackStatement =
                selection.Block.Statements[singleHandlerIndex + 1];

            InvocationExpressionSyntax[] fallbacks = fallbackStatement
                .DescendantNodesAndSelf(node => node == fallbackStatement
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<InvocationExpressionSyntax>()
                .Where(fallback => dispatch.Model.GetSymbolInfo(fallback).Symbol is
                    IMethodSymbol method
                    && method.Name == "SettleExactlyAsync"
                    && IsExactAuthoredProtocolType(
                        method.ContainingType,
                        "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationReconciler",
                        dispatch.Model.Compilation))
                .ToArray();

            if (fallbacks is not [InvocationExpressionSyntax fallback]
                || dispatch.Model.GetSymbolInfo(fallback).Symbol is not
                    IMethodSymbol fallbackMethod
                || !IsExactAwaitedInvocationStatement(
                    dispatch,
                    fallbackStatement,
                    fallback))
            {
                return false;
            }

            if (fallback.ArgumentList.Arguments is
                [ArgumentSyntax fallbackOperation, ArgumentSyntax fallbackEvidence])
            {
                return allowLegacyFallback
                    && ExactRecoveryFallbackReceiver(
                        dispatch,
                        selection,
                        fallback,
                        allowConstruction: true)
                    && fallbackMethod.DeclaredAccessibility == Accessibility.Internal
                    && fallbackMethod.Parameters.Length == 2
                    && SymbolEqualityComparer.Default.Equals(
                        dispatch.Model.GetSymbolInfo(fallbackOperation.Expression).Symbol,
                        dispatch.Model.GetSymbolInfo(selection.Operation).Symbol)
                    && SymbolEqualityComparer.Default.Equals(
                        dispatch.Model.GetSymbolInfo(fallbackEvidence.Expression).Symbol,
                        ownerEvidence);
            }

            if (fallback.ArgumentList.Arguments.Count != 4
                || fallbackMethod.DeclaredAccessibility != Accessibility.Internal
                || fallbackMethod.IsStatic
                || fallbackMethod.Parameters is not
                [
                    IParameterSymbol operationId,
                    IParameterSymbol ownerId,
                    IParameterSymbol evidence,
                    IParameterSymbol cancellationToken,
                ]
                || TypeKey(operationId.Type) != "System.Guid"
                || ownerId.Type.SpecialType != SpecialType.System_String
                || !IsExactAuthoredProtocolType(
                    evidence.Type,
                    "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningRecoveryOwnerEvidence",
                    dispatch.Model.Compilation)
                || TypeKey(cancellationToken.Type) !=
                    "System.Threading.CancellationToken"
                || !TryGetLaunchGapAdoptionProof(
                    dispatch,
                    selection.Operation,
                    fallback,
                    selection,
                    out LaunchGapAdoptionProof proof))
            {
                return false;
            }

            var arguments = AdmissionArguments(dispatch, fallback).ToArray();

            ExpressionSyntax? operationIdArgument = arguments
                .SingleOrDefault(argument => argument.Parameter?.Ordinal == 0)
                .Expression;
            ExpressionSyntax? ownerIdArgument = arguments
                .SingleOrDefault(argument => argument.Parameter?.Ordinal == 1)
                .Expression;
            ExpressionSyntax? evidenceArgument = arguments
                .SingleOrDefault(argument => argument.Parameter?.Ordinal == 2)
                .Expression;
            ExpressionSyntax? tokenArgument = arguments
                .SingleOrDefault(argument => argument.Parameter?.Ordinal == 3)
                .Expression;

            return ExactRecoveryFallbackReceiver(
                    dispatch,
                    selection,
                    fallback,
                    allowConstruction: false)
                && operationIdArgument is not null
                && ExactPropertyPath(
                    dispatch,
                    operationIdArgument,
                    proof.Expected,
                    "OperationId")
                && ownerIdArgument is not null
                && SymbolEqualityComparer.Default.Equals(
                    dispatch.Model.GetSymbolInfo(ownerIdArgument).Symbol,
                    proof.OwnerId)
                && evidenceArgument is not null
                && SymbolEqualityComparer.Default.Equals(
                    dispatch.Model.GetSymbolInfo(evidenceArgument).Symbol,
                    proof.OwnerEvidence)
                && SymbolEqualityComparer.Default.Equals(
                    proof.OwnerEvidence,
                    ownerEvidence)
                && tokenArgument is not null
                && SymbolEqualityComparer.Default.Equals(
                    dispatch.Model.GetSymbolInfo(tokenArgument).Symbol,
                    proof.CancellationToken)
                && RecoveryTupleSourceIsStable(
                    dispatch,
                    proof.Adopted,
                    handlerCall,
                    allowSimpleLocalAssignments: false);
        }

        private bool ExactRecoveryFallbackReceiver(
            AuthoredMember dispatch,
            RecoveryHandlerSelection selection,
            InvocationExpressionSyntax fallback,
            bool allowConstruction)
        {
            if (fallback.Expression is not MemberAccessExpressionSyntax
                {
                    Expression: { } receiver,
                })
            {
                return false;
            }

            receiver = StripTransparentExpression(receiver);

            if (receiver is BaseObjectCreationExpressionSyntax creation)
            {
                return allowConstruction
                    && dispatch.Model.GetTypeInfo(creation).Type is { } created
                    && IsExactAuthoredProtocolType(
                        created,
                        "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationReconciler",
                        dispatch.Model.Compilation);
            }

            if (receiver is not InvocationExpressionSyntax serviceResolution
                || dispatch.Model.GetSymbolInfo(serviceResolution).Symbol is not
                    IMethodSymbol resolver
                || !IsExactFrameworkMethod(
                    resolver,
                    "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions",
                    "GetRequiredService",
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
                || resolver.TypeArguments is not [ITypeSymbol service]
                || !IsExactAuthoredProtocolType(
                    service,
                    "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationReconciler",
                    dispatch.Model.Compilation)
                || serviceResolution.Expression is not MemberAccessExpressionSyntax
                {
                    Expression: MemberAccessExpressionSyntax
                    {
                        Expression: { } fallbackScope,
                        Name.Identifier.ValueText: "ServiceProvider",
                    },
                })
            {
                return false;
            }

            return TryGetSelectionScope(
                    dispatch,
                    selection,
                    out ILocalSymbol selectedScope)
                && SymbolEqualityComparer.Default.Equals(
                    dispatch.Model.GetSymbolInfo(fallbackScope).Symbol,
                    selectedScope);
        }

        private static bool TryGetSelectionScope(
            AuthoredMember dispatch,
            RecoveryHandlerSelection selection,
            out ILocalSymbol scope)
        {
            ILocalSymbol? selectedScope = selection.Declaration
                .DescendantNodes()
                .OfType<InvocationExpressionSyntax>()
                .Where(invocation => dispatch.Model.GetSymbolInfo(invocation).Symbol is
                    IMethodSymbol method
                    && method.Name == "GetServices")
                .SelectMany(static invocation => invocation
                    .DescendantNodesAndSelf()
                    .OfType<MemberAccessExpressionSyntax>())
                .Where(static access =>
                    access.Name.Identifier.ValueText == "ServiceProvider")
                .Select(access => dispatch.Model.GetSymbolInfo(access.Expression).Symbol)
                .OfType<ILocalSymbol>()
                .SingleOrDefault();

            scope = selectedScope!;

            return selectedScope is not null;
        }

        private bool TryGetExactRecoveryHandlerSelection(
            AuthoredMember dispatch,
            InvocationExpressionSyntax call,
            out RecoveryHandlerSelection result)
        {
            result = default;

            if (call.ArgumentList.Arguments.FirstOrDefault()?.Expression is not
                { } operation
                || call.Expression is not MemberAccessExpressionSyntax
                {
                    Expression: ElementAccessExpressionSyntax
                    {
                        Expression: { } handlerCollection,
                        ArgumentList.Arguments: [ArgumentSyntax handlerIndex],
                    },
                }
                || dispatch.Model.GetConstantValue(handlerIndex.Expression) is not
                {
                    HasValue: true,
                    Value: 0,
                }
                || dispatch.Model.GetSymbolInfo(handlerCollection).Symbol is not
                    ILocalSymbol handlers)
            {
                return false;
            }

            VariableDeclaratorSyntax[] declarations = dispatch.Syntax
                .DescendantNodes()
                .OfType<VariableDeclaratorSyntax>()
                .Where(variable => SymbolEqualityComparer.Default.Equals(
                    dispatch.Model.GetDeclaredSymbol(variable),
                    handlers))
                .ToArray();

            if (declarations is not
                [VariableDeclaratorSyntax
                {
                    Initializer.Value: CollectionExpressionSyntax
                    {
                        Elements:
                        [
                            SpreadElementSyntax
                        {
                            Expression: InvocationExpressionSyntax take,
                        },
                        ],
                    },
                } declaration]
                || take.Expression is not MemberAccessExpressionSyntax
                {
                    Expression: InvocationExpressionSyntax where,
                }
                || dispatch.Model.GetSymbolInfo(take).Symbol is not
                    IMethodSymbol takeMethod
                || !IsExactFrameworkMethod(
                    takeMethod,
                    "System.Linq.Enumerable",
                    "Take",
                    "System.Linq")
                || dispatch.Model.GetSymbolInfo(where).Symbol is not
                    IMethodSymbol whereMethod
                || !IsExactFrameworkMethod(
                    whereMethod,
                    "System.Linq.Enumerable",
                    "Where",
                    "System.Linq")
                || take.ArgumentList.Arguments is not [ArgumentSyntax count]
                || dispatch.Model.GetConstantValue(count.Expression) is not
                {
                    HasValue: true,
                    Value: 2,
                }
                || where.ArgumentList.Arguments.LastOrDefault()?.Expression is not
                    AnonymousFunctionExpressionSyntax predicate
                || predicate.Body is not ExpressionSyntax predicateBody
                || !AuthenticatedHandlerSourceIsExact(
                    dispatch,
                    where,
                    declaration)
                || !ExactAuthenticatedTuplePredicate(
                    dispatch,
                    predicate,
                    predicateBody,
                    operation))
            {
                return false;
            }

            if (declaration.Parent?.Parent is not
                    LocalDeclarationStatementSyntax declarationStatement
                || declarationStatement.Parent is not BlockSyntax selectionBlock
                || call.Ancestors().OfType<StatementSyntax>()
                    .FirstOrDefault(statement => statement.Parent == selectionBlock) is not
                    { } callContainer
                || selectionBlock.DescendantNodes(node =>
                        node == selectionBlock
                        || node is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .OfType<GotoStatementSyntax>()
                    .Any(jump => jump.SpanStart > declarationStatement.Span.End
                        && jump.SpanStart < call.SpanStart))
            {
                return false;
            }

            result = new(
                operation,
                handlers,
                declarationStatement,
                selectionBlock,
                callContainer);

            return DispatcherCompositionIsExact(dispatch);
        }

        private static bool HandlerSelectionIsStable(
            AuthoredMember dispatch,
            RecoveryHandlerSelection selection,
            InvocationExpressionSyntax call,
            params ExpressionSyntax[] allowedConditions)
        {
            bool directReferencesAreStable = selection.Block.DescendantNodes()
                .OfType<IdentifierNameSyntax>()
                .Where(reference => reference.SpanStart > selection.Declaration.Span.End
                    && reference.SpanStart < call.SpanStart
                    && SymbolEqualityComparer.Default.Equals(
                        dispatch.Model.GetSymbolInfo(reference).Symbol,
                        selection.Handlers))
                .All(reference => allowedConditions.Any(condition =>
                    condition.Span.Contains(reference.Span)));

            if (!directReferencesAreStable)
            {
                return false;
            }

            Dictionary<IMethodSymbol, LocalFunctionStatementSyntax> localFunctions =
                new(SymbolEqualityComparer.Default);

            foreach (LocalFunctionStatementSyntax function in selection.Block
                .DescendantNodes().OfType<LocalFunctionStatementSyntax>())
            {
                if (dispatch.Model.GetDeclaredSymbol(function) is { } symbol)
                {
                    localFunctions.TryAdd(symbol, function);
                }
            }

            bool CapturesSelectedHandlers(
                IMethodSymbol function,
                HashSet<IMethodSymbol> path)
            {
                if (!localFunctions.TryGetValue(function, out LocalFunctionStatementSyntax? declaration)
                    || !path.Add(function))
                {
                    return false;
                }

                try
                {
                    if (declaration.DescendantNodes().OfType<IdentifierNameSyntax>()
                        .Any(reference => SymbolEqualityComparer.Default.Equals(
                            dispatch.Model.GetSymbolInfo(reference).Symbol,
                            selection.Handlers)))
                    {
                        return true;
                    }

                    return declaration.DescendantNodes(node =>
                            node == declaration
                            || node is not AnonymousFunctionExpressionSyntax
                                and not LocalFunctionStatementSyntax)
                        .OfType<InvocationExpressionSyntax>()
                        .Select(invocation =>
                            dispatch.Model.GetSymbolInfo(invocation).Symbol)
                        .OfType<IMethodSymbol>()
                        .Any(target => CapturesSelectedHandlers(target, path));
                }
                finally
                {
                    _ = path.Remove(function);
                }
            }

            return !selection.Block.DescendantNodes(node =>
                    node == selection.Block
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<InvocationExpressionSyntax>()
                .Where(invocation =>
                    invocation.SpanStart > selection.Declaration.Span.End
                    && invocation.SpanStart < call.SpanStart)
                .Select(invocation => dispatch.Model.GetSymbolInfo(invocation).Symbol)
                .OfType<IMethodSymbol>()
                .Any(target => target.MethodKind == MethodKind.DelegateInvoke
                    || CapturesSelectedHandlers(
                        target,
                        new(SymbolEqualityComparer.Default)));
        }

        private static bool IsHandlerCountComparison(
            AuthoredMember dispatch,
            ExpressionSyntax condition,
            ILocalSymbol handlers,
            SyntaxKind comparisonKind,
            int expected) =>
            StripTransparentExpression(condition) is BinaryExpressionSyntax comparison
            && comparison.IsKind(comparisonKind)
            && (IsHandlerLength(
                    dispatch,
                    comparison.Left,
                    handlers)
                    && IsConstant(
                        dispatch,
                        comparison.Right,
                        expected)
                || IsHandlerLength(
                    dispatch,
                    comparison.Right,
                    handlers)
                    && IsConstant(
                        dispatch,
                        comparison.Left,
                        expected));

        private bool AuthenticatedHandlerSourceIsExact(
            AuthoredMember dispatch,
            InvocationExpressionSyntax where,
            VariableDeclaratorSyntax handlerDeclaration)
        {
            if (where.Expression is not MemberAccessExpressionSyntax
                {
                    Expression: InvocationExpressionSyntax services,
                }
                || dispatch.Model.GetSymbolInfo(services).Symbol is not
                    IMethodSymbol serviceResolver
                || !IsExactFrameworkMethod(
                    serviceResolver,
                    "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions",
                    "GetServices",
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
                || serviceResolver.TypeArguments is not [ITypeSymbol service]
                || !IsExactAuthoredProtocolType(
                    service,
                    "RetroDownfall.Arcanum.Infrastructure.Data.IAuthenticatedCovenantErasureRecoveryHandler",
                    dispatch.Model.Compilation)
                || services.ArgumentList.Arguments.Count != 0
                || services.Expression is not MemberAccessExpressionSyntax
                {
                    Expression: MemberAccessExpressionSyntax
                    {
                        Expression: { } scopeExpression,
                        Name.Identifier.ValueText: "ServiceProvider",
                    },
                }
                || dispatch.Model.GetSymbolInfo(scopeExpression).Symbol is not
                    ILocalSymbol scope
                || !IsExactFrameworkType(
                    scope.Type,
                    "Microsoft.Extensions.DependencyInjection.AsyncServiceScope",
                    typeof(Microsoft.Extensions.DependencyInjection.AsyncServiceScope)
                        .Assembly.GetName())
                || scope.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax() is not
                    VariableDeclaratorSyntax
                {
                    Initializer.Value: InvocationExpressionSyntax createScope,
                } scopeDeclaration
                || createScope.Expression is not MemberAccessExpressionSyntax
                {
                    Expression: { } scopeFactory,
                }
                || dispatch.Model.GetSymbolInfo(createScope).Symbol is not
                    IMethodSymbol createScopeMethod
                || !IsExactFrameworkMethod(
                    createScopeMethod,
                    "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions",
                    "CreateAsyncScope",
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
                || !IsStableInjectedScopeFactory(
                    dispatch,
                    scopeFactory)
                || scopeDeclaration.Parent?.Parent is not
                    LocalDeclarationStatementSyntax
                {
                    AwaitKeyword.RawKind: not 0,
                    UsingKeyword.RawKind: not 0,
                } scopeStatement
                || handlerDeclaration.Parent?.Parent is not
                    LocalDeclarationStatementSyntax handlerStatement
                || scopeStatement.Parent is not BlockSyntax scopeBlock
                || !scopeBlock.Span.Contains(handlerStatement.Span)
                || scopeStatement.Span.End >= handlerStatement.SpanStart)
            {
                return false;
            }

            return true;
        }

        private bool IsStableInjectedScopeFactory(
            AuthoredMember dispatch,
            ExpressionSyntax expression)
        {
            expression = StripTransparentExpression(expression);

            if (dispatch.Model.GetSymbolInfo(expression).Symbol is not
                    IFieldSymbol
                {
                    IsReadOnly: true,
                    DeclaredAccessibility: Accessibility.Private,
                } field
                || !SymbolEqualityComparer.Default.Equals(
                    field.ContainingType,
                    dispatch.Symbol.ContainingType)
                || !IsExactFrameworkType(
                    field.Type,
                    "Microsoft.Extensions.DependencyInjection.IServiceScopeFactory",
                    typeof(Microsoft.Extensions.DependencyInjection.IServiceScopeFactory)
                        .Assembly.GetName())
                || field.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                    is not VariableDeclaratorSyntax
                    {
                        Initializer.Value: { } initializer,
                    }
                || dispatch.Model.GetSymbolInfo(
                    StripTransparentExpression(initializer)).Symbol is not
                    IParameterSymbol parameter
                || !IsExactFrameworkType(
                    parameter.Type,
                    "Microsoft.Extensions.DependencyInjection.IServiceScopeFactory",
                    typeof(Microsoft.Extensions.DependencyInjection.IServiceScopeFactory)
                        .Assembly.GetName())
                || parameter.ContainingSymbol is not IMethodSymbol constructor
                || constructor.MethodKind != MethodKind.Constructor
                || !SymbolEqualityComparer.Default.Equals(
                    constructor.ContainingType,
                    dispatch.Symbol.ContainingType))
            {
                return false;
            }

            foreach (SyntaxNode declaration in dispatch.Symbol.ContainingType
                .DeclaringSyntaxReferences
                .Select(static reference => reference.GetSyntax()))
            {
                if (!semanticModels.TryGetValue(
                        declaration.SyntaxTree,
                        out SemanticModel? model))
                {
                    return false;
                }

                if (declaration.DescendantNodes().Any(node =>
                    node is AssignmentExpressionSyntax assignment
                        && SymbolEqualityComparer.Default.Equals(
                            model.GetSymbolInfo(assignment.Left).Symbol,
                            field)
                    || node is ArgumentSyntax argument
                        && argument.RefKindKeyword.Kind() is
                            SyntaxKind.RefKeyword or SyntaxKind.OutKeyword
                        && SymbolEqualityComparer.Default.Equals(
                            model.GetSymbolInfo(argument.Expression).Symbol,
                            field)))
                {
                    return false;
                }
            }

            return true;
        }

        private bool DispatcherCompositionIsExact(AuthoredMember dispatch)
        {
            _ = RecoveryRegistrationCompositions();

            (BaseObjectCreationExpressionSyntax Creation, SemanticModel Model)[]
                constructions = objectCreations
                    .Where(candidate => candidate.Model.GetTypeInfo(
                            candidate.Creation).Type is { } created
                        && SameBoundType(
                            created,
                            candidate.Model.Compilation,
                            dispatch.Symbol.ContainingType,
                            dispatch.Model.Compilation))
                    .ToArray();

            if (invalidRecoveryComposition != RecoveryCompositionKind.None
                || constructions is not
                [(BaseObjectCreationExpressionSyntax creation, SemanticModel model)]
                || creation.Ancestors().OfType<AnonymousFunctionExpressionSyntax>()
                    .FirstOrDefault() is not { } factory
                || factory switch
                {
                    SimpleLambdaExpressionSyntax simple => simple.ExpressionBody,
                    ParenthesizedLambdaExpressionSyntax parenthesized =>
                        parenthesized.ExpressionBody,
                    _ => null,
                } is not { } factoryResult
                || StripTransparentExpression(factoryResult) != creation
                || creation.Ancestors().OfType<InvocationExpressionSyntax>()
                    .FirstOrDefault(invocation => invocation.Span.Contains(
                        factory.Span)) is not { } registration
                || model.GetSymbolInfo(registration).Symbol is not
                    IMethodSymbol registrationMethod
                || !IsExactFrameworkMethod(
                    registrationMethod,
                    "Microsoft.Extensions.DependencyInjection.Extensions.ServiceCollectionDescriptorExtensions",
                    "TryAddSingleton",
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
                || registrationMethod.TypeArguments is not [ITypeSymbol contract]
                || !IsExactAuthoredProtocolType(
                    contract,
                    "RetroDownfall.Arcanum.Infrastructure.GrimoireTransitions.IGrimoireOfflineTransitionHandlerDispatch",
                    model.Compilation)
                || !RecoveryRegistrationCompositions()
                    .GetValueOrDefault(registration)
                    .HasFlag(RecoveryCompositionKind.Serving)
                || !RecoveryRegistrationCompositions()
                    .GetValueOrDefault(registration)
                    .HasFlag(RecoveryCompositionKind.StoppedHost)
                || !recoveryRegistrationMustExecuteCompositions
                    .GetValueOrDefault(registration)
                    .HasFlag(RecoveryCompositionKind.Serving)
                || !recoveryRegistrationMustExecuteCompositions
                    .GetValueOrDefault(registration)
                    .HasFlag(RecoveryCompositionKind.StoppedHost)
                || factory switch
                {
                    SimpleLambdaExpressionSyntax simple =>
                        model.GetDeclaredSymbol(simple.Parameter),
                    ParenthesizedLambdaExpressionSyntax
                    {
                        ParameterList.Parameters: [ParameterSyntax parameter],
                    } => model.GetDeclaredSymbol(parameter),
                    _ => null,
                } is not IParameterSymbol provider
                || !IsExactFrameworkType(
                    provider.Type,
                    "System.IServiceProvider",
                    typeof(IServiceProvider).Assembly.GetName())
                || model.GetOperation(creation) is not
                    IObjectCreationOperation createdOperation)
            {
                return false;
            }

            IArgumentOperation[] scopeArguments = createdOperation.Arguments
                .Where(argument => argument.Parameter is { } parameter
                    && IsExactFrameworkType(
                        parameter.Type,
                        "Microsoft.Extensions.DependencyInjection.IServiceScopeFactory",
                        typeof(Microsoft.Extensions.DependencyInjection.IServiceScopeFactory)
                            .Assembly.GetName()))
                .ToArray();

            if (scopeArguments is not
                [IArgumentOperation
                {
                    Value.Syntax: ExpressionSyntax scopeFactoryExpression,
                }]
                || StripTransparentExpression(scopeFactoryExpression) is not
                    InvocationExpressionSyntax resolution
                || model.GetSymbolInfo(resolution).Symbol is not
                    IMethodSymbol resolver
                || !IsExactFrameworkMethod(
                    resolver,
                    "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions",
                    "GetRequiredService",
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
                || resolver.TypeArguments is not [ITypeSymbol resolved]
                || !IsExactFrameworkType(
                    resolved,
                    "Microsoft.Extensions.DependencyInjection.IServiceScopeFactory",
                    typeof(Microsoft.Extensions.DependencyInjection.IServiceScopeFactory)
                        .Assembly.GetName())
                || resolution.Expression is not MemberAccessExpressionSyntax
                {
                    Expression: { } providerExpression,
                }
                || !SymbolEqualityComparer.Default.Equals(
                    model.GetSymbolInfo(providerExpression).Symbol,
                    provider))
            {
                return false;
            }

            return factory.Modifiers.Any(SyntaxKind.StaticKeyword);
        }

        private static bool ExactAuthenticatedTuplePredicate(
            AuthoredMember dispatch,
            AnonymousFunctionExpressionSyntax predicate,
            ExpressionSyntax expression,
            ExpressionSyntax operation)
        {
            expression = StripTransparentExpression(expression);

            if (expression is not BinaryExpressionSyntax conjunction
                || !conjunction.IsKind(SyntaxKind.LogicalAndExpression))
            {
                return false;
            }

            IParameterSymbol? candidate = predicate switch
            {
                SimpleLambdaExpressionSyntax simple =>
                    dispatch.Model.GetDeclaredSymbol(simple.Parameter),
                ParenthesizedLambdaExpressionSyntax
                {
                    ParameterList.Parameters: [ParameterSyntax parameter],
                } => dispatch.Model.GetDeclaredSymbol(parameter),
                _ => null,
            };

            return candidate is not null
                && (IsAuthenticatedKindEquality(
                        dispatch,
                        conjunction.Left,
                        candidate,
                        operation)
                    && IsAuthenticatedVersionEquality(
                        dispatch,
                        conjunction.Right,
                        candidate,
                        operation)
                    || IsAuthenticatedKindEquality(
                        dispatch,
                        conjunction.Right,
                        candidate,
                        operation)
                    && IsAuthenticatedVersionEquality(
                        dispatch,
                        conjunction.Left,
                        candidate,
                        operation));
        }

        private static bool IsAuthenticatedKindEquality(
            AuthoredMember dispatch,
            ExpressionSyntax expression,
            IParameterSymbol candidate,
            ExpressionSyntax operation)
        {
            expression = StripTransparentExpression(expression);

            if (expression is BinaryExpressionSyntax comparison
                && comparison.IsKind(SyntaxKind.EqualsExpression))
            {
                return ExactAuthenticatedPropertyPair(
                    dispatch,
                    comparison.Left,
                    comparison.Right,
                    candidate,
                    "Kind",
                    operation,
                    "Kind")
                    || ExactAuthenticatedPropertyPair(
                        dispatch,
                        comparison.Right,
                        comparison.Left,
                        candidate,
                        "Kind",
                        operation,
                        "Kind");
            }

            return expression is InvocationExpressionSyntax equality
                && dispatch.Model.GetSymbolInfo(equality).Symbol is IMethodSymbol method
                && method.Name == "Equals"
                && TypeKey(method.ContainingType) == "System.String"
                && equality.ArgumentList.Arguments is
                    [ArgumentSyntax left, ArgumentSyntax right, ArgumentSyntax comparisonKind]
                && ExactAuthenticatedPropertyPair(
                    dispatch,
                    left.Expression,
                    right.Expression,
                    candidate,
                    "Kind",
                    operation,
                    "Kind")
                && dispatch.Model.GetSymbolInfo(comparisonKind.Expression).Symbol is
                    IFieldSymbol
                {
                    Name: "Ordinal",
                } field
                && TypeKey(field.ContainingType) == "System.StringComparison";
        }

        private static bool IsAuthenticatedVersionEquality(
            AuthoredMember dispatch,
            ExpressionSyntax expression,
            IParameterSymbol candidate,
            ExpressionSyntax operation)
        {
            expression = StripTransparentExpression(expression);

            return expression is BinaryExpressionSyntax comparison
                && comparison.IsKind(SyntaxKind.EqualsExpression)
                && (ExactAuthenticatedPropertyPair(
                        dispatch,
                        comparison.Left,
                        comparison.Right,
                        candidate,
                        "SupportedCheckpointVersion",
                        operation,
                        "CheckpointVersion")
                    || ExactAuthenticatedPropertyPair(
                        dispatch,
                        comparison.Right,
                        comparison.Left,
                        candidate,
                        "SupportedCheckpointVersion",
                        operation,
                        "CheckpointVersion"));
        }

        private static bool ExactAuthenticatedPropertyPair(
            AuthoredMember dispatch,
            ExpressionSyntax candidateExpression,
            ExpressionSyntax operationExpression,
            IParameterSymbol candidate,
            string candidateProperty,
            ExpressionSyntax operation,
            string operationProperty) =>
            StripTransparentExpression(candidateExpression) is MemberAccessExpressionSyntax
            {
                Expression: { } candidateReceiver,
                Name.Identifier.ValueText: var candidateName,
            }
            && candidateName == candidateProperty
            && SymbolEqualityComparer.Default.Equals(
                dispatch.Model.GetSymbolInfo(candidateReceiver).Symbol,
                candidate)
            && StripTransparentExpression(operationExpression) is MemberAccessExpressionSyntax
            {
                Expression: { } operationReceiver,
                Name.Identifier.ValueText: var operationName,
            }
            && operationName == operationProperty
            && SyntaxFactory.AreEquivalent(
                StripTransparentExpression(operationReceiver),
                StripTransparentExpression(operation));

        private static bool IsHandlerLength(
            AuthoredMember dispatch,
            ExpressionSyntax expression,
            ILocalSymbol handlers) =>
            StripTransparentExpression(expression) is MemberAccessExpressionSyntax
            {
                Expression: { } receiver,
                Name.Identifier.ValueText: "Length",
            }
            && SymbolEqualityComparer.Default.Equals(
                dispatch.Model.GetSymbolInfo(receiver).Symbol,
                handlers);

        private static bool IsConstant(
            AuthoredMember member,
            ExpressionSyntax expression,
            int expected) =>
            member.Model.GetConstantValue(expression) is
            {
                HasValue: true,
                Value: int value,
            }
            && value == expected;

        private bool OwnerRecoveryDispatchIsExact(
            IReadOnlySet<TraversalStateIdentity> active,
            out string failure)
        {
            AuthoredMember[] candidates = AuthoredMembers
                .Where(static member => member.Symbol.Name == "SettleExactlyAsync")
                .Where(member => IsExactAuthoredProtocolType(
                    member.Symbol.ContainingType,
                    "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationReconciler",
                    member.Model.Compilation))
                .Where(member => member.Symbol.Parameters.Any(parameter =>
                    IsExactAuthoredProtocolType(
                        parameter.Type,
                        "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningRecoveryOwnerEvidence",
                        member.Model.Compilation)))
                .ToArray();

            if (candidates is not [AuthoredMember method]
                || !active.Any(state => state.Member == MemberIdentity(method)))
            {
                failure = candidates.Length == 1
                    ? "the authenticated settlement entry is not present in the active call path"
                    : $"the production graph contains {candidates.Length} authenticated settlement entries";

                return false;
            }

            InvocationExpressionSyntax[] settlements = method.Syntax
                .DescendantNodes()
                .OfType<InvocationExpressionSyntax>()
                .Where(call => method.Model.GetSymbolInfo(call).Symbol is IMethodSymbol target
                    && target.Name == "SettleLeasedAsync"
                    && SymbolEqualityComparer.Default.Equals(
                        target.ContainingType,
                        method.Symbol.ContainingType))
                .ToArray();

            if (settlements is not [InvocationExpressionSyntax settlement])
            {
                failure = $"the authenticated settlement entry contains {settlements.Length} shared settlements";

                return false;
            }

            IParameterSymbol? ownerEvidence = method.Symbol.Parameters
                .SingleOrDefault(parameter => IsExactAuthoredProtocolType(
                    parameter.Type,
                    "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningRecoveryOwnerEvidence",
                    method.Model.Compilation));

            if (ownerEvidence is null)
            {
                failure = "the authenticated settlement entry has no exact owner-evidence parameter";

                return false;
            }

            foreach (LocalDeclarationStatementSyntax declaration in method.Syntax
                .DescendantNodes()
                .OfType<LocalDeclarationStatementSyntax>())
            {
                if (declaration.Declaration.Variables is not
                    [VariableDeclaratorSyntax
                    {
                        Initializer.Value: InvocationExpressionSyntax classification,
                    } variable]
                    || method.Model.GetDeclaredSymbol(variable) is not ILocalSymbol
                    || method.Model.GetSymbolInfo(classification).Symbol is not IMethodSymbol
                    {
                        Name: "Classify",
                    } classifier
                    || TypeKey(classifier.ContainingType)
                        != "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationRecoveryAdmission"
                    || AdmissionArguments(method, classification)
                        .Select(static argument => argument.Expression)
                        .Skip(1)
                        .SingleOrDefault() is not { } evidenceExpression
                    || !SymbolEqualityComparer.Default.Equals(
                        method.Model.GetSymbolInfo(evidenceExpression).Symbol,
                        ownerEvidence))
                {
                    continue;
                }

                bool IsOwnerRefusal(ExpressionSyntax expression)
                    => IsRecoveryDispositionTest(
                        method,
                        expression,
                        "OwnerBoundOffline",
                        negated: true);

                if (method.Syntax.DescendantNodes()
                    .OfType<IfStatementSyntax>()
                    .Any(guard => guard.SpanStart > declaration.Span.End
                        && guard.Span.End < settlement.SpanStart
                        && DefinitelyTerminates(guard.Statement)
                        && IsOwnerRefusal(guard.Condition)))
                {
                    failure = string.Empty;

                    return true;
                }
            }

            failure = "the authenticated settlement entry does not terminate every non-owner classification before shared dispatch";

            return false;
        }

        private TraversalEvidence TraverseOwnerRecoveryDispatch(
            AuthoredMember caller,
            InvocationExpressionSyntax call,
            string rootType,
            string operationId,
            HashSet<TraversalStateIdentity> active,
            bool lifecycle,
            RecoveryMatrix matrix,
            IReadOnlyList<RecoveryHandlerTarget> targets)
        {
            RecoveryTuple[] tuples = OwnerTupleAt(caller, call, matrix) is { } exact
                ? [exact]
                : ExactOwnerRereadDispatchIsExact(active, caller, call)
                    ? matrix.Tuples
                        .Where(static tuple =>
                            tuple.Disposition == RecoveryDisposition.OwnerBound)
                        .ToArray()
                    : [];

            if (tuples.Length == 0)
            {
                diagnostics.Add(new(
                    "HOSTED_RECOVERY_OWNER_DISPATCH_UNPROVEN",
                    operationId,
                    "Every owner recovery dispatch call must bind exactly one current owner-bound kind and checkpoint version."));

                return TraversalEvidence.Inconclusive;
            }

            TraversalEvidence evidence = TraversalEvidence.NoEvidence;

            foreach (RecoveryTuple tuple in tuples)
            {
                RecoveryHandlerTarget[] exactTargets = targets
                    .Where(target => target.Composition.HasFlag(
                            RecoveryCompositionKind.StoppedHost)
                        && target.Kind == tuple.Kind
                        && target.SupportedCheckpointVersion ==
                            tuple.CheckpointVersion)
                    .ToArray();

                TraversalEvidence tupleEvidence = exactTargets is
                    [RecoveryHandlerTarget target]
                        ? TraverseOwnerRecoveryTarget(
                            caller,
                            call,
                            rootType,
                            operationId,
                            active,
                            lifecycle,
                            target,
                            tuple,
                            "recovery",
                            "RecoverAsync")
                        : TraversalEvidence.Inconclusive;

                evidence = MergeEvidence(evidence, tupleEvidence);
            }

            return evidence;
        }

        private bool ExactOwnerRereadDispatchIsExact(
            IReadOnlySet<TraversalStateIdentity> active,
            AuthoredMember caller,
            InvocationExpressionSyntax handlerCall)
        {
            AuthoredMember[] candidates = AuthoredMembers
                .Where(static member => member.Symbol.Name == "SettleExactlyAsync")
                .Where(member => member.Symbol.DeclaredAccessibility ==
                        Accessibility.Internal
                    && IsExactAuthoredProtocolType(
                        member.Symbol.ContainingType,
                        "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationReconciler",
                        member.Model.Compilation)
                    && member.Symbol.Parameters is
                    [
                        IParameterSymbol operationId,
                        IParameterSymbol ownerId,
                        IParameterSymbol ownerEvidence,
                        IParameterSymbol cancellationToken,
                    ]
                    && TypeKey(operationId.Type) == "System.Guid"
                    && ownerId.Type.SpecialType == SpecialType.System_String
                    && IsExactAuthoredProtocolType(
                        ownerEvidence.Type,
                        "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningRecoveryOwnerEvidence",
                        member.Model.Compilation)
                    && TypeKey(cancellationToken.Type) ==
                        "System.Threading.CancellationToken")
                .ToArray();

            if (candidates is not [AuthoredMember method]
                || !active.Any(state => state.Member == MemberIdentity(method))
                || method.Symbol.Parameters is not
                [
                    IParameterSymbol operationId,
                    IParameterSymbol ownerId,
                    IParameterSymbol ownerEvidence,
                    IParameterSymbol cancellationToken,
                ])
            {
                return false;
            }

            InvocationExpressionSyntax[] reads = method.Syntax
                .DescendantNodes(node => node == method.Syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<InvocationExpressionSyntax>()
                .Where(read => method.Model.GetSymbolInfo(read).Symbol is
                    IMethodSymbol { Name: "GetAsync" } readMethod
                    && IsExactAuthoredProtocolType(
                        readMethod.ContainingType,
                        "RetroDownfall.Arcanum.Core.Operations.ILongRunningOperationStore",
                        method.Model.Compilation))
                .ToArray();

            if (reads is not [InvocationExpressionSyntax read]
                || read.Ancestors().OfType<VariableDeclaratorSyntax>()
                    .FirstOrDefault() is not { } leasedDeclaration
                || method.Model.GetDeclaredSymbol(leasedDeclaration) is not
                    ILocalSymbol leased
                || read.Expression is not MemberAccessExpressionSyntax
                { Expression: { } storeExpression }
                || method.Model.GetSymbolInfo(storeExpression).Symbol is not
                    IFieldSymbol { IsReadOnly: true } store
                || !SymbolEqualityComparer.Default.Equals(
                    store.ContainingType,
                    method.Symbol.ContainingType)
                || !InvocationArgumentsAreExact(
                    method,
                    read,
                    operationId,
                    cancellationToken))
            {
                return false;
            }

            IfStatementSyntax[] nullRefusals = method.Syntax.DescendantNodes()
                .OfType<IfStatementSyntax>()
                .Where(guard => guard.SpanStart > leasedDeclaration.Span.End
                    && DefinitelyTerminates(guard.Statement)
                    && IsExactNullTest(method, guard.Condition, leased))
                .ToArray();

            VariableDeclaratorSyntax[] expectedDeclarations = method.Syntax
                .DescendantNodes()
                .OfType<VariableDeclaratorSyntax>()
                .Where(declaration => declaration.Initializer?.Value is { } initializer
                    && ExactPropertyPath(
                        method,
                        initializer,
                        ownerEvidence,
                        "ExpectedOperation"))
                .ToArray();

            if (nullRefusals is not [IfStatementSyntax nullRefusal]
                || expectedDeclarations is not
                    [VariableDeclaratorSyntax expectedDeclaration]
                || method.Model.GetDeclaredSymbol(expectedDeclaration) is not
                    ILocalSymbol expected
                || !DirectGuardDominates(
                    method,
                    leasedDeclaration,
                    nullRefusal,
                    expectedDeclaration))
            {
                return false;
            }

            InvocationExpressionSyntax[] classifications = method.Syntax
                .DescendantNodes()
                .OfType<InvocationExpressionSyntax>()
                .Where(classification => method.Model.GetSymbolInfo(classification).Symbol is
                    IMethodSymbol { Name: "Classify" } classifier
                    && IsExactAuthoredProtocolType(
                        classifier.ContainingType,
                        "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationRecoveryAdmission",
                        method.Model.Compilation)
                    && AdmissionArguments(method, classification)
                        .Select(static argument => argument.Expression)
                        .ToArray() is
                        [ExpressionSyntax classified, ExpressionSyntax evidence]
                    && ExactPropertyPath(method, classified, leased)
                    && ExactPropertyPath(method, evidence, ownerEvidence))
                .ToArray();

            InvocationExpressionSyntax[] settlements = method.Syntax
                .DescendantNodes()
                .OfType<InvocationExpressionSyntax>()
                .Where(settlement => method.Model.GetSymbolInfo(settlement).Symbol is
                    IMethodSymbol { Name: "SettleLeasedAsync" } target
                    && SymbolEqualityComparer.Default.Equals(
                        target.ContainingType,
                        method.Symbol.ContainingType))
                .ToArray();

            if (classifications is not [InvocationExpressionSyntax classification]
                || settlements is not [InvocationExpressionSyntax settlement]
                || nullRefusal.Span.End >= expectedDeclaration.SpanStart
                || nullRefusal.Span.End >= classification.SpanStart
                || SymbolReferencedBetween(
                    method,
                    leased,
                    leasedDeclaration.Span.End,
                    nullRefusal.SpanStart)
                || !ExactOwnerRereadRefusal(
                    method,
                    leased,
                    expected,
                    ownerId,
                    ownerEvidence,
                    classification,
                    settlement)
                || !RecoveryTupleSourceIsStable(
                    method,
                    leased,
                    settlement,
                    allowSimpleLocalAssignments: false)
                || !RecoveryTupleSourceIsStable(
                    method,
                    expected,
                    settlement,
                    allowSimpleLocalAssignments: false)
                || !ExactOwnerSettlementForwarding(
                    active,
                    method,
                    settlement,
                    store,
                    leased,
                    ownerId,
                    cancellationToken,
                    caller,
                    handlerCall))
            {
                return false;
            }

            return nullRefusal.Span.End < settlement.SpanStart;
        }

        private static bool InvocationArgumentsAreExact(
            AuthoredMember member,
            InvocationExpressionSyntax invocation,
            params ISymbol[] expected)
        {
            var arguments = AdmissionArguments(member, invocation).ToArray();

            return arguments.Length == expected.Length
                && expected.Select((symbol, ordinal) => (symbol, ordinal))
                    .All(item => arguments.SingleOrDefault(argument =>
                            argument.Parameter?.Ordinal == item.ordinal)
                        .Expression is { } expression
                        && SymbolEqualityComparer.Default.Equals(
                            member.Model.GetSymbolInfo(expression).Symbol,
                            item.symbol));
        }

        private bool ExactOwnerRereadRefusal(
            AuthoredMember method,
            ILocalSymbol leased,
            ILocalSymbol expected,
            IParameterSymbol ownerId,
            IParameterSymbol ownerEvidence,
            InvocationExpressionSyntax classification,
            InvocationExpressionSyntax settlement)
        {
            IfStatementSyntax[] refusals = method.Syntax.DescendantNodes()
                .OfType<IfStatementSyntax>()
                .Where(guard => guard.SpanStart > classification.Span.End
                    && guard.Span.End < settlement.SpanStart
                    && DefinitelyTerminates(guard.Statement)
                    && ExactOwnerRereadRefusalCondition(
                        method,
                        guard.Condition,
                        leased,
                        expected,
                        ownerId,
                        ownerEvidence))
                .ToArray();

            return refusals is [_];
        }

        private bool ExactOwnerRereadRefusalCondition(
            AuthoredMember method,
            ExpressionSyntax condition,
            ILocalSymbol leased,
            ILocalSymbol expected,
            IParameterSymbol ownerId,
            IParameterSymbol ownerEvidence)
        {
            ExpressionSyntax[] leaves = ExactLogicalOrLeaves(condition);

            return leaves.Length == 6
                && leaves.Count(leaf => IsExactBinaryComparison(
                    method,
                    leaf,
                    SyntaxKind.NotEqualsExpression,
                    leased,
                    ["Id"],
                    expected,
                    ["OperationId"])) == 1
                && leaves.Count(leaf => IsExactNegatedOrdinalStringEquality(
                    method,
                    leaf,
                    leased,
                    ["Kind"],
                    expected,
                    ["Kind"])) == 1
                && leaves.Count(leaf => IsExactBinaryComparison(
                    method,
                    leaf,
                    SyntaxKind.NotEqualsExpression,
                    leased,
                    ["CheckpointVersion"],
                    expected,
                    ["CheckpointVersion"])) == 1
                && leaves.Count(leaf => IsExactIncrementedRevisionMismatch(
                    method,
                    leaf,
                    leased,
                    expected)) == 1
                && leaves.Count(leaf => IsExactNegatedOrdinalStringEquality(
                    method,
                    leaf,
                    leased,
                    ["LeaseOwner"],
                    ownerId,
                    [])) == 1
                && leaves.Count(leaf => ExactOwnerClassificationCheck(
                    method,
                    leaf,
                    leased,
                    ownerEvidence,
                    negated: true)) == 1;
        }

        private static bool IsExactIncrementedRevisionMismatch(
            AuthoredMember member,
            ExpressionSyntax expression,
            ISymbol leased,
            ISymbol expected) =>
            StripTransparentExpression(expression) is
                BinaryExpressionSyntax comparison
            && comparison.IsKind(SyntaxKind.NotEqualsExpression)
            && (ExactPropertyPath(
                    member,
                    comparison.Left,
                    leased,
                    "Revision")
                && IsExactIncrement(
                    member,
                    comparison.Right,
                    expected,
                    "Revision")
                || ExactPropertyPath(
                    member,
                    comparison.Right,
                    leased,
                    "Revision")
                && IsExactIncrement(
                    member,
                    comparison.Left,
                    expected,
                    "Revision"));

        private static bool IsExactIncrement(
            AuthoredMember member,
            ExpressionSyntax expression,
            ISymbol root,
            params string[] property) =>
            StripTransparentExpression(expression) is BinaryExpressionSyntax increment
            && increment.IsKind(SyntaxKind.AddExpression)
            && ExactPropertyPath(member, increment.Left, root, property)
            && member.Model.GetConstantValue(increment.Right) is
            {
                HasValue: true,
                Value: 1,
            };

        private bool ExactOwnerSettlementForwarding(
            IReadOnlySet<TraversalStateIdentity> active,
            AuthoredMember settlementEntry,
            InvocationExpressionSyntax settlement,
            IFieldSymbol store,
            ILocalSymbol leased,
            IParameterSymbol ownerId,
            IParameterSymbol cancellationToken,
            AuthoredMember caller,
            InvocationExpressionSyntax handlerCall)
        {
            var settlementArguments = AdmissionArguments(
                    settlementEntry,
                    settlement)
                .ToArray();

            if (settlementArguments.Length != 5
                || settlementArguments.SingleOrDefault(argument =>
                        argument.Parameter?.Ordinal == 1)
                    .Expression is not { } handlersExpression
                || settlementEntry.Model.GetSymbolInfo(handlersExpression).Symbol is not
                    IFieldSymbol { IsReadOnly: true } handlers
                || !SymbolEqualityComparer.Default.Equals(
                    handlers.ContainingType,
                    settlementEntry.Symbol.ContainingType)
                || !InvocationArgumentsMatchSymbols(
                    settlementEntry,
                    settlementArguments,
                    (0, store),
                    (2, leased),
                    (3, ownerId),
                    (4, cancellationToken))
                || settlementEntry.Model.GetSymbolInfo(settlement).Symbol is not
                    IMethodSymbol settlementMethod
                || ResolveInvocationTarget(
                    settlementMethod,
                    settlementEntry,
                    settlement) is not { } settlementTarget
                || !active.Any(state => state.Member == MemberIdentity(settlementTarget)))
            {
                return false;
            }

            InvocationExpressionSyntax[] recoveryCalls = settlementTarget.Syntax
                .DescendantNodes(node => node == settlementTarget.Syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<InvocationExpressionSyntax>()
                .Where(recovery => settlementTarget.Model.GetSymbolInfo(recovery).Symbol is
                    IMethodSymbol { Name: "RecoverOneAsync" } method
                    && SymbolEqualityComparer.Default.Equals(
                        method.ContainingType,
                        settlementEntry.Symbol.ContainingType))
                .ToArray();

            if (recoveryCalls is not [InvocationExpressionSyntax recoveryCall]
                || settlementTarget.Model.GetSymbolInfo(recoveryCall).Symbol is not
                    IMethodSymbol recoveryMethod
                || ResolveInvocationTarget(
                    recoveryMethod,
                    settlementTarget,
                    recoveryCall) is not { } recoveryTarget
                || !active.Any(state => state.Member == MemberIdentity(recoveryTarget))
                || settlementTarget.Symbol.Parameters is not
                [
                    IParameterSymbol operationStore,
                    IParameterSymbol operationHandlers,
                    IParameterSymbol operation,
                    IParameterSymbol settledOwnerId,
                    IParameterSymbol settledToken,
                ]
                || !InvocationArgumentsMatchSymbols(
                    settlementTarget,
                    AdmissionArguments(settlementTarget, recoveryCall).ToArray(),
                    (0, operationHandlers),
                    (1, operation),
                    (2, settledToken))
                || !SymbolIsStableBetween(
                    settlementTarget,
                    operationHandlers,
                    settlementTarget.Syntax.SpanStart,
                    recoveryCall)
                || !SymbolIsStableBetween(
                    settlementTarget,
                    operation,
                    settlementTarget.Syntax.SpanStart,
                    recoveryCall)
                || !SymbolIsStableBetween(
                    settlementTarget,
                    settledToken,
                    settlementTarget.Syntax.SpanStart,
                    recoveryCall)
                || MemberIdentity(caller) != MemberIdentity(recoveryTarget)
                || recoveryTarget.Symbol.Parameters is not
                [
                    IParameterSymbol handlersForOperation,
                    IParameterSymbol recoveredOperation,
                    IParameterSymbol recoveredToken,
                ]
                || !InvocationArgumentsMatchSymbols(
                    caller,
                    AdmissionArguments(caller, handlerCall).ToArray(),
                    (0, recoveredOperation),
                    (1, recoveredToken))
                || !SymbolIsStableBetween(
                    recoveryTarget,
                    handlersForOperation,
                    recoveryTarget.Syntax.SpanStart,
                    handlerCall)
                || !SymbolIsStableBetween(
                    recoveryTarget,
                    recoveredOperation,
                    recoveryTarget.Syntax.SpanStart,
                    handlerCall)
                || !SymbolIsStableBetween(
                    recoveryTarget,
                    recoveredToken,
                    recoveryTarget.Syntax.SpanStart,
                    handlerCall))
            {
                return false;
            }

            InvocationExpressionSyntax[] handlerSelections = recoveryTarget.Syntax
                .DescendantNodes(node => node == recoveryTarget.Syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<InvocationExpressionSyntax>()
                .Where(selection => recoveryTarget.Model.GetSymbolInfo(selection).Symbol is
                    IMethodSymbol selectionMethod
                    && IsExactFrameworkMethod(
                        selectionMethod,
                        "System.Collections.Generic.IReadOnlyDictionary`2",
                        "TryGetValue",
                        "System.Private.CoreLib"))
                .ToArray();

            if (!IsExactRecoveryHandlerDictionary(
                    handlersForOperation.Type,
                    recoveryTarget.Model.Compilation)
                || handlerSelections is not
                    [InvocationExpressionSyntax handlerSelection]
                || handlerSelection.Expression is not MemberAccessExpressionSyntax
                { Expression: { } handlersReceiver }
                || !ExactPropertyPath(
                    recoveryTarget,
                    handlersReceiver,
                    handlersForOperation)
                || handlerSelection.ArgumentList.Arguments is not
                    [
                        ArgumentSyntax { Expression: { } handlerKey },
                        ArgumentSyntax
                    {
                        RefOrOutKeyword.RawKind: (int)SyntaxKind.OutKeyword,
                        Expression: DeclarationExpressionSyntax
                        {
                            Designation: SingleVariableDesignationSyntax handlerDesignation,
                        },
                    },
                    ]
                || !ExactPropertyPath(
                    recoveryTarget,
                    handlerKey,
                    recoveredOperation,
                    "Kind")
                || recoveryTarget.Model.GetDeclaredSymbol(handlerDesignation) is not
                    ILocalSymbol selectedHandler
                || handlerSelection.Ancestors().OfType<IfStatementSyntax>()
                    .FirstOrDefault(guard => guard.Condition.Span.Contains(
                        handlerSelection.Span)) is not { } missingHandler
                || !DefinitelyTerminates(missingHandler.Statement)
                || !IsExactLogicalNotInvocation(
                    missingHandler.Condition,
                    handlerSelection)
                || missingHandler.Span.End >= handlerCall.SpanStart
                || handlerCall.Expression is not MemberAccessExpressionSyntax
                { Expression: { } handlerReceiver }
                || !ExactPropertyPath(
                    recoveryTarget,
                    handlerReceiver,
                    selectedHandler)
                || !SymbolIsStableBetween(
                    recoveryTarget,
                    selectedHandler,
                    missingHandler.Span.End,
                    handlerCall)
                || CompletionPreservingExpression(handlerCall, caller.Model).Parent is not
                    AwaitExpressionSyntax)
            {
                return false;
            }

            _ = operationStore;
            _ = settledOwnerId;

            return true;
        }

        private static bool SymbolIsStableBetween(
            AuthoredMember member,
            ISymbol symbol,
            int after,
            SyntaxNode use) =>
            SymbolIsStableWithin(
                member,
                symbol,
                after,
                use.SpanStart);

        private static bool SymbolIsStableThrough(
            AuthoredMember member,
            ISymbol symbol,
            int after,
            SyntaxNode use) =>
            SymbolIsStableWithin(
                member,
                symbol,
                after,
                use.Span.End);

        private static bool SymbolIsStableWithin(
            AuthoredMember member,
            ISymbol symbol,
            int after,
            int before)
        {
            IEnumerable<SyntaxNode> directNodes = member.Syntax
                .DescendantNodesAndSelf(node => node == member.Syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .Where(node => node.SpanStart > after
                    && node.SpanStart < before);

            if (directNodes.Any(node => SyntaxNodeWritesSymbol(
                member.Model,
                node,
                symbol)))
            {
                return false;
            }

            return !InvokedCallableMayMutateSymbol(
                member,
                symbol,
                before,
                after);
        }

        private static bool SyntaxReferencesSymbol(
            SemanticModel model,
            SyntaxNode syntax,
            ISymbol symbol) =>
            syntax.DescendantNodesAndSelf()
                .Any(node => SymbolEqualityComparer.Default.Equals(
                    model.GetSymbolInfo(node).Symbol,
                    symbol));

        private static bool SyntaxNodeWritesSymbol(
            SemanticModel model,
            SyntaxNode node,
            ISymbol symbol) =>
            node switch
            {
                AssignmentExpressionSyntax assignment =>
                    AssignmentTargetWritesSymbol(
                        model,
                        assignment.Left,
                        symbol),
                ArgumentSyntax argument when argument.RefKindKeyword.Kind() is
                    SyntaxKind.RefKeyword or SyntaxKind.OutKeyword =>
                    SyntaxReferencesSymbol(model, argument.Expression, symbol),
                RefExpressionSyntax reference =>
                    SyntaxReferencesSymbol(model, reference.Expression, symbol),
                PrefixUnaryExpressionSyntax prefix when prefix.Kind() is
                    SyntaxKind.PreIncrementExpression
                        or SyntaxKind.PreDecrementExpression =>
                    SyntaxReferencesSymbol(model, prefix.Operand, symbol),
                PostfixUnaryExpressionSyntax postfix when postfix.Kind() is
                    SyntaxKind.PostIncrementExpression
                        or SyntaxKind.PostDecrementExpression =>
                    SyntaxReferencesSymbol(model, postfix.Operand, symbol),
                _ => false,
            };

        private static bool AssignmentTargetWritesSymbol(
            SemanticModel model,
            ExpressionSyntax target,
            ISymbol symbol)
        {
            target = StripTransparentExpression(target);

            if (SymbolEqualityComparer.Default.Equals(
                model.GetSymbolInfo(target).Symbol,
                symbol))
            {
                return true;
            }

            return target is TupleExpressionSyntax tuple
                && tuple.Arguments.Any(argument =>
                    AssignmentTargetWritesSymbol(
                        model,
                        argument.Expression,
                        symbol));
        }

        private static bool SymbolReferencedBetween(
            AuthoredMember member,
            ISymbol symbol,
            int after,
            int before) =>
            member.Syntax.DescendantNodes(node => node == member.Syntax
                || node is not AnonymousFunctionExpressionSyntax
                    and not LocalFunctionStatementSyntax)
                .OfType<IdentifierNameSyntax>()
                .Where(reference => reference.SpanStart > after
                    && reference.SpanStart < before)
                .Any(reference => SymbolEqualityComparer.Default.Equals(
                    member.Model.GetSymbolInfo(reference).Symbol,
                    symbol));

        private bool IsExactRecoveryHandlerDictionary(
            ITypeSymbol type,
            Compilation compilation) =>
            type is INamedTypeSymbol
            {
                TypeArguments:
                [
                    ITypeSymbol key,
                    ITypeSymbol handler,
                ],
            }
            && TypeKey(type) ==
                "System.Collections.Generic.IReadOnlyDictionary`2"
            && key.SpecialType == SpecialType.System_String
            && IsExactAuthoredProtocolType(
                handler,
                "RetroDownfall.Arcanum.Core.Operations.ILongRunningOperationRecoveryHandler",
                compilation);

        private static bool InvocationArgumentsMatchSymbols(
            AuthoredMember member,
            (ExpressionSyntax Expression, IParameterSymbol? Parameter, RefKind RefKind)[] arguments,
            params (int Ordinal, ISymbol Symbol)[] expected) =>
            expected.All(item => arguments.SingleOrDefault(argument =>
                    argument.Parameter?.Ordinal == item.Ordinal)
                .Expression is { } expression
                && SymbolEqualityComparer.Default.Equals(
                    member.Model.GetSymbolInfo(expression).Symbol,
                    item.Symbol));

        private RecoveryTuple? OwnerTupleAt(
            AuthoredMember caller,
            InvocationExpressionSyntax call,
            RecoveryMatrix matrix)
        {
            RecoveryTuple? boundOperation =
                call.ArgumentList.Arguments.FirstOrDefault()?.Expression is { } operation
                    ? BoundRecoveryTuple(caller, operation, [])
                    : null;

            return boundOperation is { } exactOperation
                && matrix.Tuples.Count(tuple => tuple == exactOperation
                    && tuple.Disposition == RecoveryDisposition.OwnerBound) == 1
                    ? exactOperation
                    : null;
        }

        private RecoveryTuple[] ProvenOwnerTuplesAt(
            AuthoredMember caller,
            InvocationExpressionSyntax call,
            RecoveryMatrix matrix,
            bool allowAuthenticatedAdmission = false,
            bool allowLaunchGapAdoption = false)
        {
            if (OwnerTupleAt(caller, call, matrix) is { } exact)
            {
                return [exact];
            }

            return (allowAuthenticatedAdmission
                    && AuthenticatedAdmissionOperationIsExact(caller, call)
                || allowLaunchGapAdoption
                    && TryGetExactRecoveryHandlerSelection(
                        caller,
                        call,
                        out RecoveryHandlerSelection selection)
                    && TryGetLaunchGapAdoptionProof(
                        caller,
                        call.ArgumentList.Arguments.First().Expression,
                        call,
                        selection,
                        out _))
                    ? matrix.Tuples
                        .Where(static tuple =>
                            tuple.Disposition == RecoveryDisposition.OwnerBound)
                        .ToArray()
                    : [];
        }

        private bool AuthenticatedAdmissionOperationIsExact(
            AuthoredMember dispatch,
            InvocationExpressionSyntax call)
        {
            if (call.ArgumentList.Arguments is not
                [
                    ArgumentSyntax
                {
                    Expression: MemberAccessExpressionSyntax
                    {
                        Expression: { } admissionReceiver,
                        Name.Identifier.ValueText: "AdoptedOperation",
                    } adoptedOperation,
                },
                    ArgumentSyntax { Expression: { } admissionArgument },
                    ..
                ]
                || dispatch.Model.GetSymbolInfo(adoptedOperation).Symbol is not
                    IPropertySymbol
                {
                    SetMethod: null,
                    ContainingType.IsSealed: true,
                } operationProperty
                || !IsExactAuthoredProtocolType(
                    operationProperty.ContainingType,
                    "RetroDownfall.Arcanum.Infrastructure.Data.CovenantErasureCoordinator.AuthenticatedCovenantErasureRecoveryAdmission",
                    dispatch.Model.Compilation)
                || !IsExactAuthoredProtocolType(
                    operationProperty.Type,
                    "RetroDownfall.Arcanum.Core.Operations.LongRunningOperation",
                    dispatch.Model.Compilation)
                || dispatch.Model.GetSymbolInfo(admissionReceiver).Symbol is not
                    ILocalSymbol admission
                || !SymbolEqualityComparer.Default.Equals(
                    dispatch.Model.GetSymbolInfo(admissionArgument).Symbol,
                    admission)
                || !RecoveryTupleSourceIsStable(
                    dispatch,
                    admission,
                    adoptedOperation,
                    allowSimpleLocalAssignments: false)
                || admission.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                    is not VariableDeclaratorSyntax
                    {
                        Initializer.Value: { } admissionInitializer,
                    } admissionDeclaration
                || StripTransparentExpression(admissionInitializer) is not
                    MemberAccessExpressionSyntax
                {
                    Expression: { } preparedReceiver,
                    Name.Identifier.ValueText: "Value",
                }
                || dispatch.Model.GetSymbolInfo(preparedReceiver).Symbol is not
                    ILocalSymbol prepared
                || prepared.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                    is not VariableDeclaratorSyntax
                    {
                        Initializer.Value: { } preparedInitializer,
                    } preparedDeclaration)
            {
                return false;
            }

            InvocationExpressionSyntax[] preparations = preparedInitializer
                .DescendantNodesAndSelf()
                .OfType<InvocationExpressionSyntax>()
                .Where(invocation => dispatch.Model.GetSymbolInfo(invocation).Symbol is
                    IMethodSymbol method
                    && method.Name == "PrepareAuthenticatedRecoveryAsync"
                    && IsExactAuthoredProtocolType(
                        method.ContainingType,
                        "RetroDownfall.Arcanum.Infrastructure.Data.CovenantErasureCoordinator",
                        dispatch.Model.Compilation))
                .ToArray();

            if (preparations is not [InvocationExpressionSyntax preparation]
                || !IsExactAwaitedInvocationInitializer(
                    dispatch,
                    preparedInitializer,
                    preparation)
                || dispatch.Model.GetSymbolInfo(preparation).Symbol is not
                    IMethodSymbol preparationMethod
                || ResolveInvocationTarget(
                    preparationMethod,
                    dispatch,
                    preparation) is not { } factory
                || !AuthenticatedPreparationArgumentsAreExact(
                    dispatch,
                    preparation,
                    factory,
                    call)
                || !AuthenticatedAdmissionFactoryIsExact(factory))
            {
                return false;
            }

            BlockSyntax? block = admissionDeclaration.Ancestors()
                .OfType<BlockSyntax>()
                .FirstOrDefault();

            if (block is null
                || preparedDeclaration.Ancestors().OfType<BlockSyntax>()
                    .FirstOrDefault() != block)
            {
                return false;
            }

            IfStatementSyntax[] failureGuards = block.Statements
                .OfType<IfStatementSyntax>()
                .Where(guard => guard.SpanStart > preparedDeclaration.Span.End
                    && guard.Span.End < admissionDeclaration.SpanStart
                    && ExactFailureTermination(dispatch, guard.Statement)
                    && ExactPropertyPath(
                        dispatch,
                        guard.Condition,
                        prepared,
                        "IsFailure"))
                .ToArray();

            if (failureGuards is not [IfStatementSyntax failureGuard]
                || preparedDeclaration.Ancestors().OfType<StatementSyntax>()
                    .FirstOrDefault() is not { } preparedStatement
                || admissionDeclaration.Ancestors().OfType<StatementSyntax>()
                    .FirstOrDefault() is not { } admissionStatement)
            {
                return false;
            }

            int preparedIndex = block.Statements.IndexOf(preparedStatement);
            int failureIndex = block.Statements.IndexOf(failureGuard);
            int admissionIndex = block.Statements.IndexOf(admissionStatement);

            return preparedIndex >= 0
                && failureIndex == preparedIndex + 1
                && admissionIndex == failureIndex + 1
                && SymbolIsStableBetween(
                    dispatch,
                    prepared,
                    failureGuard.Span.End,
                    admissionInitializer);
        }

        private bool AuthenticatedPreparationArgumentsAreExact(
            AuthoredMember dispatch,
            InvocationExpressionSyntax preparation,
            AuthoredMember factory,
            InvocationExpressionSyntax handlerCall)
        {
            if (factory.Symbol.Parameters is not
                [
                    IParameterSymbol
                {
                    Name: "heldInstallationLock",
                } heldLockFormal,
                    IParameterSymbol
                {
                    Name: "guardedDirectory",
                    Type.SpecialType: SpecialType.System_String,
                },
                    IParameterSymbol
                {
                    Name: "evidence",
                } evidenceFormal,
                    IParameterSymbol
                {
                    Name: "adoption",
                } adoptionFormal,
                    IParameterSymbol
                {
                    Name: "ownerId",
                    Type.SpecialType: SpecialType.System_String,
                },
                    IParameterSymbol
                {
                    Name: "utcNow",
                } utcNowFormal,
                    IParameterSymbol
                {
                    Name: "leaseExpiresAt",
                } expiryFormal,
                    IParameterSymbol
                {
                    Name: "cancellationToken",
                } cancellationFormal,
                ]
                || !IsExactAuthoredProtocolType(
                    heldLockFormal.Type,
                    "RetroDownfall.Arcanum.Infrastructure.Backup.ArcanumMaintenanceLock",
                    factory.Model.Compilation)
                || !IsExactAuthoredProtocolType(
                    evidenceFormal.Type,
                    "RetroDownfall.Arcanum.Infrastructure.GrimoireTransitions.AuthenticatedJournalRecoveryOwnerEvidence",
                    factory.Model.Compilation)
                || !IsExactAuthoredProtocolType(
                    adoptionFormal.Type,
                    "RetroDownfall.Arcanum.Infrastructure.Operations.ILongRunningOperationMaintenanceLeaseAdoption",
                    factory.Model.Compilation)
                || TypeKey(utcNowFormal.Type) != "System.DateTimeOffset"
                || TypeKey(expiryFormal.Type) != "System.DateTimeOffset"
                || TypeKey(cancellationFormal.Type) !=
                    "System.Threading.CancellationToken")
            {
                return false;
            }

            Dictionary<string, ExpressionSyntax> arguments = AdmissionArguments(
                    dispatch,
                    preparation)
                .Where(static argument => argument.Parameter is not null)
                .ToDictionary(
                    static argument => argument.Parameter!.Name,
                    static argument => argument.Expression,
                    StringComparer.Ordinal);

            if (arguments.Count != 8
                || !TryGetAuthenticatedEvidenceBinding(
                    dispatch,
                    preparation,
                    out ILocalSymbol authenticated)
                || !arguments.TryGetValue("evidence", out ExpressionSyntax? evidence)
                || !ExactPropertyPath(dispatch, evidence, authenticated)
                || !RecoveryTupleSourceIsStable(
                    dispatch,
                    authenticated,
                    handlerCall,
                    allowSimpleLocalAssignments: false)
                || !arguments.TryGetValue("adoption", out ExpressionSyntax? adoption)
                || dispatch.Model.GetSymbolInfo(adoption).Symbol is not
                    ILocalSymbol adoptionService
                || !IsExactAuthoredProtocolType(
                    adoptionService.Type,
                    "RetroDownfall.Arcanum.Infrastructure.Operations.ILongRunningOperationMaintenanceLeaseAdoption",
                    dispatch.Model.Compilation)
                || !TryGetExactRecoveryHandlerSelection(
                    dispatch,
                    handlerCall,
                    out RecoveryHandlerSelection selection)
                || !TryGetSelectionScope(
                    dispatch,
                    selection,
                    out ILocalSymbol scope)
                || adoptionService.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                    is not VariableDeclaratorSyntax
                    {
                        Initializer.Value: { } adoptionInitializer,
                    }
                || !IsExactServiceResolutionFromScope(
                    dispatch,
                    adoptionInitializer,
                    "RetroDownfall.Arcanum.Infrastructure.Operations.ILongRunningOperationMaintenanceLeaseAdoption",
                    scope)
                || !RecoveryTupleSourceIsStable(
                    dispatch,
                    adoptionService,
                    preparation,
                    allowSimpleLocalAssignments: false)
                || !arguments.TryGetValue("ownerId", out ExpressionSyntax? owner)
                || dispatch.Model.GetSymbolInfo(owner).Symbol is not
                    ILocalSymbol ownerId
                || ownerId.Type.SpecialType != SpecialType.System_String
                || !RecoveryTupleSourceIsStable(
                    dispatch,
                    ownerId,
                    preparation,
                    allowSimpleLocalAssignments: false)
                || !arguments.TryGetValue(
                    "cancellationToken",
                    out ExpressionSyntax? cancellation)
                || dispatch.Model.GetSymbolInfo(cancellation).Symbol is not
                    IParameterSymbol cancellationToken
                || TypeKey(cancellationToken.Type) !=
                    "System.Threading.CancellationToken"
                || !SymbolEqualityComparer.Default.Equals(
                    cancellationToken.ContainingSymbol,
                    dispatch.Symbol)
                || !RecoveryTupleSourceIsStable(
                    dispatch,
                    cancellationToken,
                    preparation,
                    allowSimpleLocalAssignments: false)
                || !arguments.TryGetValue(
                    "heldInstallationLock",
                    out ExpressionSyntax? heldLockExpression)
                || dispatch.Model.GetSymbolInfo(
                    StripTransparentExpression(heldLockExpression)).Symbol is not
                    IParameterSymbol heldInstallationLock
                || heldInstallationLock.Name != "heldInstallationLock"
                || !IsExactAuthoredProtocolType(
                    heldInstallationLock.Type,
                    "RetroDownfall.Arcanum.Infrastructure.Backup.ArcanumMaintenanceLock",
                    dispatch.Model.Compilation)
                || !SymbolEqualityComparer.Default.Equals(
                    heldInstallationLock.ContainingSymbol,
                    dispatch.Symbol)
                || !RecoveryTupleSourceIsStable(
                    dispatch,
                    heldInstallationLock,
                    preparation,
                    allowSimpleLocalAssignments: false)
                || !arguments.TryGetValue(
                    "guardedDirectory",
                    out ExpressionSyntax? directoryExpression)
                || dispatch.Model.GetSymbolInfo(directoryExpression).Symbol is not
                    IParameterSymbol guardedDirectory
                || guardedDirectory.Name != "guardedDirectory"
                || guardedDirectory.Type.SpecialType !=
                    SpecialType.System_String
                || !SymbolEqualityComparer.Default.Equals(
                    guardedDirectory.ContainingSymbol,
                    dispatch.Symbol)
                || !RecoveryTupleSourceIsStable(
                    dispatch,
                    guardedDirectory,
                    preparation,
                    allowSimpleLocalAssignments: false)
                || !arguments.TryGetValue("utcNow", out ExpressionSyntax? now)
                || dispatch.Model.GetSymbolInfo(now).Symbol is not ILocalSymbol utcNow
                || !ExactUtcNowSource(dispatch, utcNow)
                || !RecoveryTupleSourceIsStable(
                    dispatch,
                    utcNow,
                    preparation,
                    allowSimpleLocalAssignments: false)
                || !arguments.TryGetValue(
                    "leaseExpiresAt",
                    out ExpressionSyntax? expiry)
                || !ExactRecoveryLeaseExpiry(dispatch, expiry, utcNow))
            {
                return false;
            }

            return true;
        }

        private bool TryGetAuthenticatedEvidenceBinding(
            AuthoredMember dispatch,
            InvocationExpressionSyntax preparation,
            out ILocalSymbol authenticated)
        {
            authenticated = null!;

            IParameterSymbol[] evidenceParameters = dispatch.Symbol.Parameters
                .Where(parameter => IsExactAuthoredProtocolType(
                    parameter.Type,
                    "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningRecoveryOwnerEvidence",
                    dispatch.Model.Compilation))
                .ToArray();

            if (evidenceParameters is not [IParameterSymbol ownerEvidence])
            {
                return false;
            }

            IfStatementSyntax[] guards = preparation.Ancestors()
                .OfType<IfStatementSyntax>()
                .Where(guard => guard.Statement.Span.Contains(preparation.Span)
                    && IsAuthenticatedEvidenceGuard(
                        dispatch,
                        guard.Condition,
                        ownerEvidence))
                .ToArray();

            if (guards is not [IfStatementSyntax
                {
                    Condition: IsPatternExpressionSyntax
                    {
                        Pattern: DeclarationPatternSyntax
                        {
                            Designation: SingleVariableDesignationSyntax designation,
                        },
                    },
                }])
            {
                return false;
            }

            if (dispatch.Model.GetDeclaredSymbol(designation) is not
                ILocalSymbol exactAuthenticated)
            {
                return false;
            }

            authenticated = exactAuthenticated;

            return true;
        }

        private bool TryGetLaunchGapAdoptionProof(
            AuthoredMember dispatch,
            ExpressionSyntax operation,
            SyntaxNode use,
            RecoveryHandlerSelection selection,
            out LaunchGapAdoptionProof proof)
        {
            proof = default;

            if (use is not ExpressionSyntax exactUse
                || !TryGetSelectionScope(dispatch, selection, out ILocalSymbol scope)
                || StripTransparentExpression(operation) is not
                    MemberAccessExpressionSyntax
                {
                    Expression: { } adoptedReceiver,
                    Name.Identifier.ValueText: "Operation",
                } operationAccess
                || dispatch.Model.GetSymbolInfo(operationAccess).Symbol is not
                    IPropertySymbol operationProperty
                || !IsExactAuthoredProtocolType(
                    operationProperty.ContainingType,
                    "RetroDownfall.Arcanum.Core.Operations.LongRunningOperationLeaseResult",
                    dispatch.Model.Compilation)
                || !IsExactAuthoredProtocolType(
                    operationProperty.Type,
                    "RetroDownfall.Arcanum.Core.Operations.LongRunningOperation",
                    dispatch.Model.Compilation)
                || dispatch.Model.GetSymbolInfo(adoptedReceiver).Symbol is not
                    ILocalSymbol adopted
                || adopted.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax() is not
                    VariableDeclaratorSyntax
                {
                    Initializer.Value: { } adoptedInitializer,
                } adoptedDeclaration
                || !RecoveryTupleSourceIsStable(
                    dispatch,
                    adopted,
                    operationAccess,
                    allowSimpleLocalAssignments: false))
            {
                return false;
            }

            InvocationExpressionSyntax[] adoptions = adoptedInitializer
                .DescendantNodesAndSelf()
                .OfType<InvocationExpressionSyntax>()
                .Where(invocation => dispatch.Model.GetSymbolInfo(invocation).Symbol is
                    IMethodSymbol method
                    && method.Name == "AdoptUnderInstallationLockAsync"
                    && IsExactAuthoredProtocolType(
                        method.ContainingType,
                        "RetroDownfall.Arcanum.Infrastructure.Operations.ILongRunningOperationMaintenanceLeaseAdoption",
                        dispatch.Model.Compilation))
                .ToArray();

            if (adoptions is not [InvocationExpressionSyntax adoption]
                || !IsExactAwaitedInvocationInitializer(
                    dispatch,
                    adoptedInitializer,
                    adoption)
                || adoption.Expression is not MemberAccessExpressionSyntax
                { Expression: { } adoptionReceiver }
                || dispatch.Model.GetSymbolInfo(adoptionReceiver).Symbol is not
                    ILocalSymbol adoptionService
                || adoptionService.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                    is not VariableDeclaratorSyntax
                    {
                        Initializer.Value: { } adoptionServiceInitializer,
                    }
                || !IsExactServiceResolutionFromScope(
                    dispatch,
                    adoptionServiceInitializer,
                    "RetroDownfall.Arcanum.Infrastructure.Operations.ILongRunningOperationMaintenanceLeaseAdoption",
                    scope)
                || !RecoveryTupleSourceIsStable(
                    dispatch,
                    adoptionService,
                    adoption,
                    allowSimpleLocalAssignments: false)
                || dispatch.Model.GetSymbolInfo(adoption).Symbol is not
                    IMethodSymbol adoptionMethod)
            {
                return false;
            }

            Dictionary<string, ExpressionSyntax> arguments = AdmissionArguments(
                    dispatch,
                    adoption)
                .Where(static argument => argument.Parameter is not null)
                .ToDictionary(
                    static argument => argument.Parameter!.Name,
                    static argument => argument.Expression,
                    StringComparer.Ordinal);

            if (!arguments.TryGetValue("expected", out ExpressionSyntax? expectedArgument)
                || dispatch.Model.GetSymbolInfo(expectedArgument).Symbol is not
                    ILocalSymbol expected
                || !arguments.TryGetValue("ownerId", out ExpressionSyntax? ownerArgument)
                || dispatch.Model.GetSymbolInfo(ownerArgument).Symbol is not
                    ILocalSymbol ownerId
                || !arguments.TryGetValue(
                    "cancellationToken",
                    out ExpressionSyntax? cancellationArgument)
                || dispatch.Model.GetSymbolInfo(cancellationArgument).Symbol is not
                    IParameterSymbol cancellationToken
                || expected.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax() is not
                    VariableDeclaratorSyntax
                {
                    Initializer.Value: { } expectedInitializer,
                } expectedDeclaration
                || dispatch.Model.GetSymbolInfo(
                    StripTransparentExpression(expectedInitializer)).Symbol is not
                    IPropertySymbol { Name: "ExpectedOperation" } expectedProperty
                || !IsExactAuthoredProtocolType(
                    expectedProperty.ContainingType,
                    "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningRecoveryOwnerEvidence",
                    dispatch.Model.Compilation)
                || StripTransparentExpression(expectedInitializer) is not
                    MemberAccessExpressionSyntax { Expression: { } evidenceReceiver }
                || dispatch.Model.GetSymbolInfo(evidenceReceiver).Symbol is not
                    IParameterSymbol ownerEvidence
                || !IsExactAuthoredProtocolType(
                    ownerEvidence.Type,
                    "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningRecoveryOwnerEvidence",
                    dispatch.Model.Compilation)
                || cancellationToken.ContainingSymbol is not IMethodSymbol tokenOwner
                || !SymbolEqualityComparer.Default.Equals(
                    tokenOwner,
                    dispatch.Symbol)
                || !arguments.TryGetValue(
                    "heldInstallationLock",
                    out ExpressionSyntax? lockArgument)
                || dispatch.Model.GetSymbolInfo(
                    StripTransparentExpression(lockArgument)).Symbol is not
                    IParameterSymbol heldInstallationLock
                || heldInstallationLock.Name != "heldInstallationLock"
                || !SymbolEqualityComparer.Default.Equals(
                    heldInstallationLock.ContainingSymbol,
                    dispatch.Symbol)
                || !arguments.TryGetValue(
                    "guardedDirectory",
                    out ExpressionSyntax? directoryArgument)
                || dispatch.Model.GetSymbolInfo(directoryArgument).Symbol is not
                    IParameterSymbol guardedDirectory
                || guardedDirectory.Name != "guardedDirectory"
                || guardedDirectory.Type.SpecialType !=
                    SpecialType.System_String
                || !SymbolEqualityComparer.Default.Equals(
                    guardedDirectory.ContainingSymbol,
                    dispatch.Symbol)
                || !arguments.TryGetValue("utcNow", out ExpressionSyntax? nowArgument)
                || dispatch.Model.GetSymbolInfo(nowArgument).Symbol is not
                    ILocalSymbol utcNow
                || !ExactUtcNowSource(dispatch, utcNow)
                || !arguments.TryGetValue(
                    "leaseExpiresAt",
                    out ExpressionSyntax? expiryArgument)
                || !ExactRecoveryLeaseExpiry(dispatch, expiryArgument, utcNow)
                || !RecoveryTupleSourceIsStable(
                    dispatch,
                    expected,
                    exactUse,
                    allowSimpleLocalAssignments: false)
                || !RecoveryTupleSourceIsStable(
                    dispatch,
                    ownerId,
                    exactUse,
                    allowSimpleLocalAssignments: false)
                || !RecoveryTupleSourceIsStable(
                    dispatch,
                    ownerEvidence,
                    exactUse,
                    allowSimpleLocalAssignments: false)
                || !RecoveryTupleSourceIsStable(
                    dispatch,
                    heldInstallationLock,
                    adoption,
                    allowSimpleLocalAssignments: false)
                || !RecoveryTupleSourceIsStable(
                    dispatch,
                    guardedDirectory,
                    adoption,
                    allowSimpleLocalAssignments: false)
                || !RecoveryTupleSourceIsStable(
                    dispatch,
                    utcNow,
                    adoption,
                    allowSimpleLocalAssignments: false)
                || !RecoveryTupleSourceIsStable(
                    dispatch,
                    cancellationToken,
                    exactUse,
                    allowSimpleLocalAssignments: false)
                || !RecoveryTupleSourceIsStable(
                    dispatch,
                    scope,
                    exactUse,
                    allowSimpleLocalAssignments: false))
            {
                return false;
            }

            BlockSyntax? block = adoptedDeclaration.Ancestors()
                .OfType<BlockSyntax>()
                .FirstOrDefault();

            if (block is null
                || expectedDeclaration.Ancestors().OfType<BlockSyntax>()
                    .FirstOrDefault() != block)
            {
                return false;
            }

            IfStatementSyntax[] acquisitionRefusals = block.Statements
                .OfType<IfStatementSyntax>()
                .Where(guard => guard.SpanStart > adoptedDeclaration.Span.End
                    && guard.Span.End < use.SpanStart
                    && ExactFailureTermination(dispatch, guard.Statement)
                    && IsExactLogicalNotProperty(
                        dispatch,
                        guard.Condition,
                        adopted,
                        "Acquired"))
                .ToArray();

            (IfStatementSyntax Guard, ILocalSymbol Candidate)[] candidateRefusals =
                block.Statements
                    .OfType<IfStatementSyntax>()
                    .Where(guard => guard.Span.End < adoptedDeclaration.SpanStart
                        && ExactFailureTermination(dispatch, guard.Statement))
                    .Select(guard => (
                        Guard: guard,
                        Exact: ExactLaunchGapCandidateRefusal(
                            dispatch,
                            guard.Condition,
                            expected,
                            ownerEvidence,
                            out ILocalSymbol candidate),
                        Candidate: candidate))
                    .Where(static item => item.Exact)
                    .Select(static item => (item.Guard, item.Candidate))
                    .ToArray();

            if (acquisitionRefusals is not [IfStatementSyntax acquisitionRefusal]
                || candidateRefusals is not
                    [(IfStatementSyntax candidateRefusal, ILocalSymbol candidate)]
                || candidate.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                    is not VariableDeclaratorSyntax candidateDeclaration
                || !DirectGuardDominates(
                    dispatch,
                    candidateDeclaration,
                    candidateRefusal,
                    adoptedDeclaration)
                || SymbolReferencedBetween(
                    dispatch,
                    candidate,
                    candidateDeclaration.Span.End,
                    candidateRefusal.SpanStart)
                || !DirectGuardDominates(
                    dispatch,
                    adoptedDeclaration,
                    acquisitionRefusal,
                    selection.Declaration)
                || !ExactLaunchGapCandidateRead(
                    dispatch,
                    candidate,
                    expected,
                    cancellationToken,
                    scope,
                    adoption))
            {
                return false;
            }

            _ = adoptionMethod;

            proof = new(
                adopted,
                expected,
                ownerId,
                ownerEvidence,
                cancellationToken,
                scope);

            return true;
        }

        private static bool DirectGuardDominates(
            AuthoredMember member,
            SyntaxNode definition,
            IfStatementSyntax guard,
            SyntaxNode use)
        {
            if (guard.Parent is not BlockSyntax block
                || DirectStatement(block, definition) is not { } definitionStatement
                || DirectStatement(block, use) is not { } useStatement)
            {
                return false;
            }

            int definitionIndex = block.Statements.IndexOf(definitionStatement);
            int guardIndex = block.Statements.IndexOf(guard);
            int useIndex = block.Statements.IndexOf(useStatement);

            if (definitionIndex < 0
                || guardIndex != definitionIndex + 1
                || useIndex <= guardIndex)
            {
                return false;
            }

            ControlFlowAnalysis? flow = member.Model.AnalyzeControlFlow(
                guard,
                useStatement);

            return flow is { Succeeded: true }
                && flow.EntryPoints.Length == 0;
        }

        private static StatementSyntax? DirectStatement(
            BlockSyntax block,
            SyntaxNode node) =>
            node.AncestorsAndSelf()
                .OfType<StatementSyntax>()
                .FirstOrDefault(statement => statement.Parent == block);

        private bool ExactLaunchGapCandidateRead(
            AuthoredMember dispatch,
            ILocalSymbol candidate,
            ILocalSymbol expected,
            IParameterSymbol cancellationToken,
            ILocalSymbol scope,
            InvocationExpressionSyntax adoption)
        {
            if (candidate.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax() is not
                VariableDeclaratorSyntax
                {
                    Initializer.Value: { } initializer,
                })
            {
                return false;
            }

            InvocationExpressionSyntax[] reads = initializer.DescendantNodesAndSelf()
                .OfType<InvocationExpressionSyntax>()
                .Where(read => dispatch.Model.GetSymbolInfo(read).Symbol is
                    IMethodSymbol { Name: "GetAsync" } method
                    && IsExactAuthoredProtocolType(
                        method.ContainingType,
                        "RetroDownfall.Arcanum.Core.Operations.ILongRunningOperationStore",
                        dispatch.Model.Compilation))
                .ToArray();

            return reads is [InvocationExpressionSyntax read]
                && IsExactAwaitedInvocationInitializer(dispatch, initializer, read)
                && read.Expression is MemberAccessExpressionSyntax
                { Expression: { } store }
                && IsExactServiceResolutionFromScope(
                    dispatch,
                    store,
                    "RetroDownfall.Arcanum.Core.Operations.ILongRunningOperationStore",
                    scope)
                && AdmissionArguments(dispatch, read).ToArray() is
                    [
                        (ExpressionSyntax operationId, _, _),
                        (ExpressionSyntax token, _, _),
                    ]
                && ExactPropertyPath(
                    dispatch,
                    operationId,
                    expected,
                    "OperationId")
                && ExactPropertyPath(dispatch, token, cancellationToken)
                && RecoveryTupleSourceIsStable(
                    dispatch,
                    candidate,
                    adoption,
                    allowSimpleLocalAssignments: false);
        }

        private bool IsExactServiceResolutionFromScope(
            AuthoredMember member,
            ExpressionSyntax expression,
            string serviceType,
            ILocalSymbol scope)
        {
            if (StripTransparentExpression(expression) is not
                    InvocationExpressionSyntax serviceResolution
                || member.Model.GetSymbolInfo(serviceResolution).Symbol is not
                    IMethodSymbol resolver
                || !IsExactFrameworkMethod(
                    resolver,
                    "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions",
                    "GetRequiredService",
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
                || resolver.TypeArguments is not [ITypeSymbol service]
                || !IsExactAuthoredProtocolType(
                    service,
                    serviceType,
                    member.Model.Compilation)
                || serviceResolution.ArgumentList.Arguments.Count != 0
                || serviceResolution.Expression is not MemberAccessExpressionSyntax
                {
                    Expression: MemberAccessExpressionSyntax
                    {
                        Expression: { } scopeExpression,
                        Name.Identifier.ValueText: "ServiceProvider",
                    },
                })
            {
                return false;
            }

            return ExactPropertyPath(member, scopeExpression, scope);
        }

        private static bool ExactUtcNowSource(
            AuthoredMember member,
            ILocalSymbol utcNow)
        {
            if (utcNow.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax() is not
                    VariableDeclaratorSyntax
                {
                    Initializer.Value: { } initializer,
                }
                || StripTransparentExpression(initializer) is not
                    InvocationExpressionSyntax invocation
                || member.Model.GetSymbolInfo(invocation).Symbol is not
                    IMethodSymbol method
                || !IsExactFrameworkMethod(
                    method,
                    "System.TimeProvider",
                    "GetUtcNow",
                    "System.Private.CoreLib")
                || invocation.ArgumentList.Arguments.Count != 0
                || invocation.Expression is not MemberAccessExpressionSyntax
                { Expression: { } receiver })
            {
                return false;
            }

            return member.Model.GetSymbolInfo(receiver).Symbol switch
            {
                IFieldSymbol { IsReadOnly: true } field =>
                    SymbolEqualityComparer.Default.Equals(
                        field.ContainingType,
                        member.Symbol.ContainingType),
                IPropertySymbol { Name: "System", IsStatic: true } property =>
                    TypeKey(property.ContainingType) == "System.TimeProvider"
                    && FrameworkAssemblyIdentityMatches(
                        property.ContainingAssembly.Identity,
                        typeof(TimeProvider).Assembly.GetName()),
                _ => false,
            };
        }

        private static bool ExactRecoveryLeaseExpiry(
            AuthoredMember member,
            ExpressionSyntax expression,
            ILocalSymbol utcNow)
        {
            if (StripTransparentExpression(expression) is not
                    InvocationExpressionSyntax invocation
                || member.Model.GetSymbolInfo(invocation).Symbol is not
                    IMethodSymbol method
                || !IsExactFrameworkMethod(
                    method,
                    "System.DateTimeOffset",
                    method.Name,
                    "System.Private.CoreLib")
                || method.Name is not ("Add" or "AddMinutes")
                || invocation.Expression is not MemberAccessExpressionSyntax
                { Expression: { } receiver }
                || !ExactPropertyPath(member, receiver, utcNow)
                || invocation.ArgumentList.Arguments is not
                    [ArgumentSyntax { Expression: { } interval }])
            {
                return false;
            }

            if (method.Name == "AddMinutes")
            {
                return ExactPositiveFiniteNumber(member, interval);
            }

            if (member.Model.GetSymbolInfo(interval).Symbol is not
                IFieldSymbol
                {
                    Name: "RecoveryLease",
                    IsStatic: true,
                    IsReadOnly: true,
                    Type: { } intervalType,
                } field
                || TypeKey(intervalType) != "System.TimeSpan"
                || !SymbolEqualityComparer.Default.Equals(
                    field.ContainingType,
                    member.Symbol.ContainingType)
                || field.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax() is not
                    VariableDeclaratorSyntax
                {
                    Initializer.Value: { } fieldInitializer,
                }
                || StripTransparentExpression(fieldInitializer) is not
                    InvocationExpressionSyntax duration
                || member.Model.GetSymbolInfo(duration).Symbol is not
                    IMethodSymbol durationMethod
                || !IsExactFrameworkMethod(
                    durationMethod,
                    "System.TimeSpan",
                    "FromMinutes",
                    "System.Private.CoreLib")
                || duration.ArgumentList.Arguments is not
                    [ArgumentSyntax { Expression: { } minutes }]
                || RecoveryLeaseFieldHasAdditionalWrites(member, field))
            {
                return false;
            }

            return ExactPositiveFiniteNumber(member, minutes);
        }

        private static bool ExactPositiveFiniteNumber(
            AuthoredMember member,
            ExpressionSyntax expression)
        {
            Optional<object?> constant = member.Model.GetConstantValue(expression);

            if (!constant.HasValue || constant.Value is not IConvertible value)
            {
                return false;
            }

            try
            {
                double duration = value.ToDouble(CultureInfo.InvariantCulture);

                return double.IsFinite(duration)
                    && duration > 0
                    && TimeSpan.FromMinutes(duration).Ticks > 0;
            }
            catch (Exception exception) when (exception is
                ArgumentException or FormatException or InvalidCastException
                    or OverflowException)
            {
                return false;
            }
        }

        private static bool RecoveryLeaseFieldHasAdditionalWrites(
            AuthoredMember member,
            IFieldSymbol field)
        {
            foreach (SyntaxReference declarationReference in
                field.ContainingType.DeclaringSyntaxReferences)
            {
                SyntaxNode declaration = declarationReference.GetSyntax();
                SemanticModel model = member.Model.Compilation.GetSemanticModel(
                    declaration.SyntaxTree);

                if (declaration.DescendantNodes().Any(node =>
                    SyntaxNodeWritesSymbol(model, node, field)))
                {
                    return true;
                }
            }

            return false;
        }

        private static bool IsExactAwaitedInvocationInitializer(
            AuthoredMember member,
            ExpressionSyntax initializer,
            InvocationExpressionSyntax invocation)
        {
            SyntaxNode completed = invocation;

            while (true)
            {
                if (completed.Parent is ParenthesizedExpressionSyntax parentheses)
                {
                    completed = parentheses;

                    continue;
                }

                if (completed.Parent is MemberAccessExpressionSyntax
                    {
                        Name.Identifier.ValueText: "ConfigureAwait",
                        Parent: InvocationExpressionSyntax configured,
                    }
                    && member.Model.GetSymbolInfo(configured).Symbol is
                        IMethodSymbol configureAwait
                    && IsExactFrameworkConfigureAwait(configureAwait))
                {
                    completed = configured;

                    continue;
                }

                break;
            }

            return completed.Parent is AwaitExpressionSyntax awaited
                && StripTransparentExpression(initializer) == awaited;
        }

        private static bool IsExactAwaitedInvocationStatement(
            AuthoredMember member,
            StatementSyntax statement,
            InvocationExpressionSyntax invocation) =>
            statement switch
            {
                ExpressionStatementSyntax expression =>
                    IsExactAwaitedInvocationExpressionStatement(
                        member,
                        expression,
                        invocation),
                LocalDeclarationStatementSyntax
                {
                    Declaration.Variables:
                    [
                        VariableDeclaratorSyntax
                    {
                        Initializer.Value: { } initializer,
                    },
                    ],
                } => IsExactAwaitedInvocationInitializer(
                    member,
                    initializer,
                    invocation),
                _ => false,
            };

        private static bool IsExactAwaitedInvocationExpressionStatement(
            AuthoredMember member,
            ExpressionStatementSyntax statement,
            InvocationExpressionSyntax invocation)
        {
            ExpressionSyntax expression = statement.Expression;

            if (StripTransparentExpression(expression) is
                AssignmentExpressionSyntax
                {
                    RawKind: (int)SyntaxKind.SimpleAssignmentExpression,
                    Left: IdentifierNameSyntax { Identifier.ValueText: "_" },
                    Right: { } awaited,
                })
            {
                expression = awaited;
            }

            return IsExactAwaitedInvocationInitializer(
                member,
                expression,
                invocation);
        }

        private bool ExactLaunchGapCandidateRefusal(
            AuthoredMember dispatch,
            ExpressionSyntax condition,
            ILocalSymbol expected,
            IParameterSymbol ownerEvidence,
            out ILocalSymbol candidate)
        {
            candidate = null!;

            ILocalSymbol[] candidates = condition.DescendantNodesAndSelf()
                .OfType<IdentifierNameSyntax>()
                .Select(identifier => dispatch.Model.GetSymbolInfo(identifier).Symbol)
                .OfType<ILocalSymbol>()
                .Where(candidate => !SymbolEqualityComparer.Default.Equals(
                        candidate,
                        expected)
                    && TypeKey(candidate.Type) ==
                        "RetroDownfall.Arcanum.Core.Operations.LongRunningOperation")
                .Cast<ISymbol>()
                .Distinct(SymbolEqualityComparer.Default)
                .OfType<ILocalSymbol>()
                .ToArray();

            if (candidates is not [ILocalSymbol exactCandidate])
            {
                return false;
            }

            candidate = exactCandidate;

            ExpressionSyntax[] leaves = ExactLogicalOrLeaves(condition);

            return leaves.Length == 6
                && IsExactNullTest(
                    dispatch,
                    leaves[0],
                    exactCandidate)
                && leaves.Count(leaf => IsExactBinaryComparison(
                    dispatch,
                    leaf,
                    SyntaxKind.NotEqualsExpression,
                    exactCandidate,
                    ["Id"],
                    expected,
                    ["OperationId"])) == 1
                && leaves.Count(leaf => IsExactNegatedOrdinalStringEquality(
                    dispatch,
                    leaf,
                    exactCandidate,
                    ["Kind"],
                    expected,
                    ["Kind"])) == 1
                && leaves.Count(leaf => IsExactBinaryComparison(
                    dispatch,
                    leaf,
                    SyntaxKind.NotEqualsExpression,
                    exactCandidate,
                    ["CheckpointVersion"],
                    expected,
                    ["CheckpointVersion"])) == 1
                && leaves.Count(leaf => IsExactBinaryComparison(
                    dispatch,
                    leaf,
                    SyntaxKind.NotEqualsExpression,
                    exactCandidate,
                    ["Revision"],
                    expected,
                    ["Revision"])) == 1
                && leaves.Count(leaf => ExactOwnerClassificationCheck(
                    dispatch,
                    leaf,
                    exactCandidate,
                    ownerEvidence,
                    negated: true)) == 1;
        }

        private bool AuthenticatedAdmissionFactoryIsExact(AuthoredMember factory)
        {
            InvocationExpressionSyntax[] adoptedChecks = factory.Syntax
                .DescendantNodes(node => node == factory.Syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<InvocationExpressionSyntax>()
                .Where(invocation => factory.Model.GetSymbolInfo(invocation).Symbol is
                    IMethodSymbol method
                    && method.Name == "ExactAdoptedOperation"
                    && SymbolEqualityComparer.Default.Equals(
                        method.ContainingType,
                        factory.Symbol.ContainingType))
                .ToArray();

            if (adoptedChecks is not [InvocationExpressionSyntax adoptedCheck]
                || adoptedCheck.Ancestors().OfType<IfStatementSyntax>()
                    .FirstOrDefault(guard => guard.Condition.Span.Contains(
                        adoptedCheck.Span)) is not { } guard
                || !ExactAuthenticatedAdmissionGuardTermination(
                    factory,
                    guard.Statement)
                || adoptedCheck.ArgumentList.Arguments is not
                    [
                        ArgumentSyntax { Expression: { } adoptedOperation },
                        ArgumentSyntax { Expression: { } suppliedEvidence },
                        ArgumentSyntax { Expression: { } suppliedOwnerId },
                    ]
                || !TryGetPropertyPath(
                    factory,
                    adoptedOperation,
                    out ISymbol adoptedRoot,
                    out string[] adoptedOperationPath)
                || adoptedRoot is not ILocalSymbol adopted
                || adopted.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax() is not
                    VariableDeclaratorSyntax adoptedDeclaration
                || adoptedOperationPath.Length == 0
                || adoptedOperationPath[^1] != "Operation"
                || factory.Model.GetSymbolInfo(suppliedEvidence).Symbol is not
                    IParameterSymbol evidenceArgument
                || factory.Model.GetSymbolInfo(suppliedOwnerId).Symbol is not
                    IParameterSymbol ownerArgument
                || !SymbolEqualityComparer.Default.Equals(
                    evidenceArgument.ContainingSymbol,
                    factory.Symbol)
                || !SymbolEqualityComparer.Default.Equals(
                    ownerArgument.ContainingSymbol,
                    factory.Symbol)
                || evidenceArgument.Name != "evidence"
                || ownerArgument.Name != "ownerId"
                || !IsExactAuthenticatedAdmissionRefusal(
                    factory,
                    guard.Condition,
                    adoptedCheck,
                    adopted,
                    adoptedOperationPath)
                || factory.Model.GetSymbolInfo(adoptedCheck).Symbol is not
                    IMethodSymbol verifierMethod
                || ResolveInvocationTarget(
                    verifierMethod,
                    factory,
                    adoptedCheck) is not { } verifier)
            {
                return false;
            }

            if (verifier.Symbol.Parameters is not
                [
                    IParameterSymbol operation,
                    IParameterSymbol evidence,
                    IParameterSymbol ownerId,
                ])
            {
                return false;
            }

            ExpressionSyntax? verifierReturn = ExactReturnedBooleanExpression(verifier);
            ExpressionSyntax[] verifierLeaves = verifierReturn is null
                ? []
                : ExactLogicalAndLeaves(verifierReturn);

            bool verifierParametersAreStable = verifierReturn is not null
                && SymbolIsStableThrough(
                    verifier,
                    operation,
                    verifier.Syntax.SpanStart,
                    verifierReturn)
                && SymbolIsStableThrough(
                    verifier,
                    evidence,
                    verifier.Syntax.SpanStart,
                    verifierReturn)
                && SymbolIsStableThrough(
                    verifier,
                    ownerId,
                    verifier.Syntax.SpanStart,
                    verifierReturn);

            bool candidateProof = verifierParametersAreStable
                && (verifierLeaves.Length == 7
                    && ExactOwnerCandidateLeaves(
                        verifier,
                        verifierLeaves,
                        operation,
                        evidence)
                    || verifierLeaves.Length == 4
                    && ExactDelegatedOwnerCandidateCheck(
                        verifier,
                        verifierLeaves,
                        operation,
                        evidence));

            bool exactRevision = verifierLeaves.Count(leaf =>
                IsExactIncrementedRevisionEquality(
                    verifier,
                    leaf,
                    operation,
                    evidence)) == 1;

            bool exactState = verifierLeaves.Count(leaf =>
                IsExactRunningStateEquality(verifier, leaf, operation)) == 1;

            bool exactLeaseOwner = verifierLeaves.Count(leaf =>
                IsExactOrdinalStringEquality(
                    verifier,
                    leaf,
                    operation,
                    ["LeaseOwner"],
                    ownerId,
                    [])) == 1;

            BaseObjectCreationExpressionSyntax[] admissions = factory.Syntax
                .DescendantNodesAndSelf()
                .OfType<BaseObjectCreationExpressionSyntax>()
                .Where(creation => factory.Model.GetTypeInfo(creation).Type is { } type
                    && IsExactAuthoredProtocolType(
                        type,
                        "RetroDownfall.Arcanum.Infrastructure.Data.CovenantErasureCoordinator.AuthenticatedCovenantErasureRecoveryAdmission",
                        factory.Model.Compilation))
                .ToArray();

            bool constructsExactAdmission = admissions is
                [BaseObjectCreationExpressionSyntax admission]
                && admission.ArgumentList?.Arguments.Count(argument =>
                    ExactPropertyPath(
                        factory,
                        argument.Expression,
                        adopted,
                        adoptedOperationPath)) == 1
                && admission.ArgumentList?.Arguments.Count(argument =>
                    ExactPropertyPath(
                        factory,
                        argument.Expression,
                        evidenceArgument)) == 1
                && admission.ArgumentList?.Arguments.Count(argument =>
                    ExactPropertyPath(
                        factory,
                        argument.Expression,
                        ownerArgument)) == 1
                && SymbolIsStableBetween(
                    factory,
                    adopted,
                    guard.Span.End,
                    admission)
                && SymbolIsStableBetween(
                    factory,
                    evidenceArgument,
                    guard.Span.End,
                    admission)
                && SymbolIsStableBetween(
                    factory,
                    ownerArgument,
                    guard.Span.End,
                    admission)
                && ExactAuthenticatedAdmissionSuccessReturn(
                    factory,
                    admission,
                    guard,
                    out ReturnStatementSyntax successReturn)
                && ExactAuthenticatedAdmissionCarrier(
                    factory,
                    admission,
                    adopted,
                    adoptedOperationPath,
                    evidenceArgument,
                    ownerArgument)
                && ExactAuthenticatedAdmissionReturns(
                    factory,
                    guard,
                    successReturn)
                && ExactAuthenticatedAdoptionOrigin(
                    factory,
                    adoptedDeclaration,
                    evidenceArgument,
                    ownerArgument,
                    successReturn)
                && SymbolIsStableThrough(
                    factory,
                    adopted,
                    adoptedDeclaration.Span.End,
                    successReturn)
                && SymbolIsStableThrough(
                    factory,
                    evidenceArgument,
                    factory.Syntax.SpanStart,
                    successReturn)
                && SymbolIsStableThrough(
                    factory,
                    ownerArgument,
                    factory.Syntax.SpanStart,
                    successReturn);

            return candidateProof
                ? exactRevision
                    && exactState
                    && exactLeaseOwner
                    && constructsExactAdmission
                : false;
        }

        private bool ExactAuthenticatedAdoptionOrigin(
            AuthoredMember factory,
            VariableDeclaratorSyntax adoptedDeclaration,
            ISymbol evidence,
            ISymbol ownerId,
            SyntaxNode use)
        {
            if (adoptedDeclaration.Initializer?.Value is not { } initializer)
            {
                return false;
            }

            InvocationExpressionSyntax[] ledgerWindows = initializer
                .DescendantNodesAndSelf()
                .OfType<InvocationExpressionSyntax>()
                .Where(invocation => factory.Model.GetSymbolInfo(invocation).Symbol is
                    IMethodSymbol method
                    && method.Name == "WithRequiredLedgerAsync"
                    && SymbolEqualityComparer.Default.Equals(
                        method.ContainingType,
                        factory.Symbol.ContainingType))
                .ToArray();

            if (ledgerWindows is not [InvocationExpressionSyntax ledgerWindow]
                || !IsExactAwaitedInvocationInitializer(
                    factory,
                    initializer,
                    ledgerWindow)
                || factory.Model.GetSymbolInfo(ledgerWindow).Symbol is not
                    IMethodSymbol
                {
                    IsStatic: true,
                    Parameters.Length: 3,
                }
                || ledgerWindow.ArgumentList.Arguments is not
                    [
                        ArgumentSyntax { Expression: { } grimoireArgument },
                        ArgumentSyntax { Expression: AnonymousFunctionExpressionSyntax callback },
                        ArgumentSyntax { Expression: { } windowToken },
                    ]
                || factory.Model.GetSymbolInfo(
                    StripTransparentExpression(grimoireArgument)).Symbol is not
                    ILocalSymbol { Name: "grimoire" }
                || factory.Symbol.Parameters.FirstOrDefault(parameter =>
                    parameter.Name == "cancellationToken") is not
                    { } cancellationToken
                || !ExactPropertyPath(
                    factory,
                    windowToken,
                    cancellationToken))
            {
                return false;
            }

            ParameterSyntax? callbackTokenSyntax = callback switch
            {
                SimpleLambdaExpressionSyntax simple => simple.Parameter,
                ParenthesizedLambdaExpressionSyntax
                { ParameterList.Parameters: [ParameterSyntax parameter] } =>
                    parameter,
                _ => null,
            };

            ExpressionSyntax? callbackResult = callback switch
            {
                SimpleLambdaExpressionSyntax { ExpressionBody: { } body } => body,
                ParenthesizedLambdaExpressionSyntax { ExpressionBody: { } body } =>
                    body,
                _ => null,
            };

            if (callbackTokenSyntax is null
                || factory.Model.GetDeclaredSymbol(callbackTokenSyntax) is not
                    IParameterSymbol callbackToken
                || callbackResult is null)
            {
                return false;
            }

            InvocationExpressionSyntax[] adoptions = callbackResult
                .DescendantNodesAndSelf()
                .OfType<InvocationExpressionSyntax>()
                .Where(invocation => factory.Model.GetSymbolInfo(invocation).Symbol is
                    IMethodSymbol method
                    && method.Name == "AdoptUnderInstallationLockAsync"
                    && IsExactAuthoredProtocolType(
                        method.ContainingType,
                        "RetroDownfall.Arcanum.Infrastructure.Operations.ILongRunningOperationMaintenanceLeaseAdoption",
                        factory.Model.Compilation))
                .ToArray();

            bool exactCallbackResult = adoptions is
                    [InvocationExpressionSyntax callbackAdoption]
                && (IsExactAwaitedInvocationInitializer(
                        factory,
                        callbackResult,
                        callbackAdoption)
                    || StripTransparentExpression(callbackResult) is
                        InvocationExpressionSyntax success
                        && factory.Model.GetSymbolInfo(success).Symbol is
                            IMethodSymbol
                        {
                            Name: "Success",
                            IsStatic: true,
                            ContainingType: { } resultType,
                        }
                        && TypeKey(resultType) is
                            "RetroDownfall.Arcanum.Core.Primitives.Result"
                                or "RetroDownfall.Arcanum.Core.Primitives.Result`1"
                        && success.ArgumentList.Arguments is
                            [ArgumentSyntax { Expression: { } successValue }]
                        && IsExactAwaitedInvocationInitializer(
                            factory,
                            successValue,
                            callbackAdoption));

            if (!exactCallbackResult
                || adoptions is not [InvocationExpressionSyntax adoption]
                || adoption.Expression is not MemberAccessExpressionSyntax
                { Expression: { } receiver }
                || factory.Model.GetSymbolInfo(receiver).Symbol is not
                    IParameterSymbol { Name: "adoption" } adoptionService
                || factory.Symbol.Parameters.FirstOrDefault(parameter =>
                    parameter.Name == "heldInstallationLock") is not { } heldLock
                || factory.Symbol.Parameters.FirstOrDefault(parameter =>
                    parameter.Name == "guardedDirectory") is not { } guardedDirectory
                || factory.Symbol.Parameters.FirstOrDefault(parameter =>
                    parameter.Name == "utcNow") is not { } utcNow
                || factory.Symbol.Parameters.FirstOrDefault(parameter =>
                    parameter.Name == "leaseExpiresAt") is not { } leaseExpiresAt
                || adoption.ArgumentList.Arguments is not
                    [
                        ArgumentSyntax adoptionLock,
                        ArgumentSyntax adoptionDirectory,
                        ArgumentSyntax adoptionExpected,
                        ArgumentSyntax adoptionOwner,
                        ArgumentSyntax adoptionNow,
                        ArgumentSyntax adoptionExpiry,
                        ArgumentSyntax adoptionToken,
                    ]
                || !ExactPropertyPath(factory, adoptionLock.Expression, heldLock)
                || !ExactPropertyPath(
                    factory,
                    adoptionDirectory.Expression,
                    guardedDirectory)
                || !ExactPropertyPath(
                    factory,
                    adoptionExpected.Expression,
                    evidence,
                    "ExpectedOperation")
                || !ExactPropertyPath(
                    factory,
                    adoptionOwner.Expression,
                    ownerId)
                || !ExactPropertyPath(factory, adoptionNow.Expression, utcNow)
                || !ExactPropertyPath(
                    factory,
                    adoptionExpiry.Expression,
                    leaseExpiresAt)
                || !ExactPropertyPath(
                    factory,
                    adoptionToken.Expression,
                    callbackToken))
            {
                return false;
            }

            return SymbolIsStableThrough(
                factory,
                adoptionService,
                factory.Syntax.SpanStart,
                use);
        }

        private bool ExactAuthenticatedAdmissionCarrier(
            AuthoredMember factory,
            BaseObjectCreationExpressionSyntax admission,
            ISymbol adopted,
            IReadOnlyList<string> adoptedOperationPath,
            ISymbol evidence,
            ISymbol ownerId)
        {
            if (factory.Model.GetOperation(admission) is not
                IObjectCreationOperation
                {
                    Constructor: { } constructor,
                    Arguments: { } arguments,
                }
                || Resolve(constructor, factory.Model.Compilation) is not
                { } constructorBody)
            {
                return false;
            }

            IArgumentOperation[] operationArguments = arguments
                .Where(argument => argument.Value.Syntax is ExpressionSyntax expression
                    && ExactPropertyPath(
                        factory,
                        expression,
                        adopted,
                        [.. adoptedOperationPath]))
                .ToArray();

            IArgumentOperation[] evidenceArguments = arguments
                .Where(argument => argument.Value.Syntax is ExpressionSyntax expression
                    && ExactPropertyPath(factory, expression, evidence))
                .ToArray();

            IArgumentOperation[] ownerArguments = arguments
                .Where(argument => argument.Value.Syntax is ExpressionSyntax expression
                    && ExactPropertyPath(factory, expression, ownerId))
                .ToArray();

            if (operationArguments is not
                    [IArgumentOperation { Parameter: { } operationFormal }]
                || evidenceArguments is not
                    [IArgumentOperation { Parameter: { } evidenceFormal }]
                || ownerArguments is not
                    [IArgumentOperation { Parameter: { } ownerFormal }]
                || constructorBody.Symbol.Parameters.ElementAtOrDefault(
                    operationFormal.Ordinal) is not { } operationParameter
                || constructorBody.Symbol.Parameters.ElementAtOrDefault(
                    evidenceFormal.Ordinal) is not { } evidenceParameter
                || constructorBody.Symbol.Parameters.ElementAtOrDefault(
                    ownerFormal.Ordinal) is not { } ownerParameter)
            {
                return false;
            }

            bool ExactMappedProperty(
                string name,
                IParameterSymbol parameter)
            {
                IPropertySymbol[] properties = constructor.ContainingType
                    .GetMembers(name)
                    .OfType<IPropertySymbol>()
                    .Where(static property => !property.IsStatic)
                    .ToArray();

                if (properties is not [IPropertySymbol property]
                    || property.SetMethod is not null
                    || !SymbolEqualityComparer.Default.Equals(
                        property.Type,
                        parameter.Type)
                    || property.DeclaringSyntaxReferences.SingleOrDefault()
                        ?.GetSyntax() is not PropertyDeclarationSyntax
                        {
                            ExpressionBody: null,
                            Initializer: null,
                            AccessorList.Accessors:
                            [
                                AccessorDeclarationSyntax
                            {
                                RawKind: (int)SyntaxKind.GetAccessorDeclaration,
                                Body: null,
                                ExpressionBody: null,
                                SemicolonToken.RawKind: (int)SyntaxKind.SemicolonToken,
                            },
                            ],
                        })
                {
                    return false;
                }

                AssignmentExpressionSyntax[] writes = constructorBody.Syntax
                    .DescendantNodes(node => node == constructorBody.Syntax
                        || node is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .OfType<AssignmentExpressionSyntax>()
                    .Where(write => SymbolEqualityComparer.Default.Equals(
                        constructorBody.Model.GetSymbolInfo(write.Left).Symbol,
                        property))
                    .ToArray();

                return writes is [AssignmentExpressionSyntax write]
                    && write.IsKind(SyntaxKind.SimpleAssignmentExpression)
                    && SymbolEqualityComparer.Default.Equals(
                        constructorBody.Model.GetSymbolInfo(write.Right).Symbol,
                        parameter)
                    && IsUnconditionalExecution(
                        constructorBody,
                        write,
                        constructorBody.Syntax.SpanStart)
                    && SymbolIsStableThrough(
                        constructorBody,
                        parameter,
                        constructorBody.Syntax.SpanStart,
                        write);
            }

            bool ExactMappedField(
                string name,
                IParameterSymbol parameter,
                out IFieldSymbol mapped)
            {
                mapped = null!;

                IFieldSymbol[] fields = constructor.ContainingType
                    .GetMembers(name)
                    .OfType<IFieldSymbol>()
                    .Where(static field => !field.IsStatic)
                    .ToArray();

                if (fields is not [IFieldSymbol { IsReadOnly: true } field]
                    || !SymbolEqualityComparer.Default.Equals(
                        field.Type,
                        parameter.Type))
                {
                    return false;
                }

                AssignmentExpressionSyntax[] writes = constructorBody.Syntax
                    .DescendantNodes(node => node == constructorBody.Syntax
                        || node is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .OfType<AssignmentExpressionSyntax>()
                    .Where(write => SymbolEqualityComparer.Default.Equals(
                        constructorBody.Model.GetSymbolInfo(write.Left).Symbol,
                        field))
                    .ToArray();

                mapped = field;

                return writes is [AssignmentExpressionSyntax write]
                    && write.IsKind(SyntaxKind.SimpleAssignmentExpression)
                    && SymbolEqualityComparer.Default.Equals(
                        constructorBody.Model.GetSymbolInfo(write.Right).Symbol,
                        parameter)
                    && IsUnconditionalExecution(
                        constructorBody,
                        write,
                        constructorBody.Syntax.SpanStart)
                    && SymbolIsStableThrough(
                        constructorBody,
                        parameter,
                        constructorBody.Syntax.SpanStart,
                        write);
            }

            bool ExactFieldProperty(
                string name,
                IFieldSymbol field)
            {
                IPropertySymbol[] properties = constructor.ContainingType
                    .GetMembers(name)
                    .OfType<IPropertySymbol>()
                    .Where(static property => !property.IsStatic)
                    .ToArray();

                return properties is [IPropertySymbol { SetMethod: null } property]
                    && property.DeclaringSyntaxReferences.SingleOrDefault()
                        ?.GetSyntax() is PropertyDeclarationSyntax
                    {
                        ExpressionBody.Expression: { } expression,
                    }
                    && SymbolEqualityComparer.Default.Equals(
                        constructorBody.Model.GetSymbolInfo(expression).Symbol,
                        field);
            }

            bool ExactCarrierLifetime(
                IFieldSymbol creatorField,
                IFieldSymbol ledgerField,
                IFieldSymbol covenantField,
                IFieldSymbol grimoireField)
            {
                IMethodSymbol[] consumes = constructor.ContainingType
                    .GetMembers("TryConsume")
                    .OfType<IMethodSymbol>()
                    .Where(static method => !method.IsStatic)
                    .ToArray();

                IMethodSymbol[] releases = constructor.ContainingType
                    .GetMembers("ReleaseKeepClosedAsync")
                    .OfType<IMethodSymbol>()
                    .Where(static method => !method.IsStatic)
                    .ToArray();

                IMethodSymbol[] disposals = constructor.ContainingType
                    .GetMembers("DisposeAsync")
                    .OfType<IMethodSymbol>()
                    .Where(static method => !method.IsStatic)
                    .ToArray();

                IMethodSymbol[] consumedClosures = constructor.ContainingType
                    .GetMembers("KeepClosedAfterConsumptionAsync")
                    .OfType<IMethodSymbol>()
                    .Where(static method => !method.IsStatic)
                    .ToArray();

                IFieldSymbol? available = constructor.ContainingType
                    .GetMembers("Available")
                    .OfType<IFieldSymbol>()
                    .SingleOrDefault();

                IFieldSymbol? consumed = constructor.ContainingType
                    .GetMembers("Consumed")
                    .OfType<IFieldSymbol>()
                    .SingleOrDefault();

                IFieldSymbol? released = constructor.ContainingType
                    .GetMembers("Released")
                    .OfType<IFieldSymbol>()
                    .SingleOrDefault();

                IFieldSymbol? state = constructor.ContainingType
                    .GetMembers("_state")
                    .OfType<IFieldSymbol>()
                    .SingleOrDefault();

                if (consumes is not [IMethodSymbol consume]
                    || releases is not [IMethodSymbol release]
                    || disposals is not [IMethodSymbol disposal]
                    || consumedClosures is not [IMethodSymbol consumedClosure]
                    || available?.ConstantValue is not 0
                    || consumed?.ConstantValue is not 1
                    || released?.ConstantValue is not 2
                    || state is not
                    {
                        IsStatic: false,
                        DeclaredAccessibility: Accessibility.Private,
                        Type.SpecialType: SpecialType.System_Int32,
                    }
                    || consume.Parameters is not
                        [IParameterSymbol creator, IParameterSymbol ledger]
                    || creator.Name != "creator"
                    || ledger.Name != "ledger"
                    || Resolve(consume, factory.Model.Compilation) is not
                    { } consumeBody
                    || Resolve(release, factory.Model.Compilation) is not
                    { } releaseBody
                    || Resolve(disposal, factory.Model.Compilation) is not
                    { } disposalBody
                    || Resolve(consumedClosure, factory.Model.Compilation) is not
                    { } consumedClosureBody)
                {
                    return false;
                }

                ExpressionSyntax? consumeReturn =
                    ExactReturnedBooleanExpression(consumeBody);

                ExpressionSyntax[] consumeLeaves = consumeReturn is null
                    ? []
                    : ExactLogicalAndLeaves(consumeReturn);

                bool ExactReference(
                    ExpressionSyntax leaf,
                    IFieldSymbol field,
                    IParameterSymbol parameter) =>
                        StripTransparentExpression(leaf) is
                            InvocationExpressionSyntax invocation
                        && consumeBody.Model.GetSymbolInfo(invocation).Symbol is
                                IMethodSymbol
                        {
                            Name: "ReferenceEquals",
                            IsStatic: true,
                            ContainingType: { } objectType,
                        }
                            && TypeKey(objectType) == "System.Object"
                            && invocation.ArgumentList.Arguments is
                                [
                                    ArgumentSyntax { Expression: { } left },
                                    ArgumentSyntax { Expression: { } right },
                                ]
                            && SymbolEqualityComparer.Default.Equals(
                                consumeBody.Model.GetSymbolInfo(left).Symbol,
                                field)
                            && SymbolEqualityComparer.Default.Equals(
                                consumeBody.Model.GetSymbolInfo(right).Symbol,
                                parameter);

                bool ExactForward(
                    AuthoredMember forwarder,
                    IFieldSymbol expectedState) => forwarder.Syntax is
                        MethodDeclarationSyntax
                    {
                        Body: null,
                        ExpressionBody.Expression:
                                InvocationExpressionSyntax invocation,
                    }
                    && SymbolEqualityComparer.Default.Equals(
                        forwarder.Model.GetSymbolInfo(invocation).Symbol,
                        release)
                    && invocation.ArgumentList.Arguments is
                        [ArgumentSyntax { Expression: { } argument }]
                    && SymbolEqualityComparer.Default.Equals(
                        forwarder.Model.GetSymbolInfo(argument).Symbol,
                        expectedState);

                bool exactLedgerClosed = consumeLeaves.ElementAtOrDefault(2) is
                    BinaryExpressionSyntax equality
                    && equality.IsKind(SyntaxKind.EqualsExpression)
                    && TryGetPropertyPath(
                        consumeBody,
                        equality.Left,
                        out ISymbol ledgerRoot,
                        out string[] ledgerPath)
                    && SymbolEqualityComparer.Default.Equals(
                        ledgerRoot,
                        ledgerField)
                    && ledgerPath is ["Connection", "State"]
                    && consumeBody.Model.GetSymbolInfo(equality.Right).Symbol is
                        IFieldSymbol { Name: "Closed", ConstantValue: 0 };

                bool ExactCompareExchange(
                    AuthoredMember member,
                    InvocationExpressionSyntax invocation,
                    ISymbol replacement,
                    ISymbol expected) => member.Model.GetSymbolInfo(invocation).Symbol is
                        IMethodSymbol
                    {
                        Name: "CompareExchange",
                        IsStatic: true,
                        ContainingType: { } interlocked,
                    }
                    && TypeKey(interlocked) == "System.Threading.Interlocked"
                    && invocation.ArgumentList.Arguments is
                        [
                            ArgumentSyntax { Expression: { } stateArgument },
                            ArgumentSyntax { Expression: { } releasedArgument },
                            ArgumentSyntax { Expression: { } expectedArgument },
                        ]
                    && SymbolEqualityComparer.Default.Equals(
                        member.Model.GetSymbolInfo(stateArgument).Symbol,
                        state)
                    && SymbolEqualityComparer.Default.Equals(
                        member.Model.GetSymbolInfo(releasedArgument).Symbol,
                        replacement)
                    && SymbolEqualityComparer.Default.Equals(
                        member.Model.GetSymbolInfo(expectedArgument).Symbol,
                        expected);

                bool exactConsumeTransition = consumeLeaves.ElementAtOrDefault(3)
                        is BinaryExpressionSyntax transition
                    && transition.IsKind(SyntaxKind.EqualsExpression)
                    && StripTransparentExpression(transition.Left) is
                        InvocationExpressionSyntax compare
                    && ExactCompareExchange(
                        consumeBody,
                        compare,
                        consumed,
                        available)
                    && SymbolEqualityComparer.Default.Equals(
                        consumeBody.Model.GetSymbolInfo(transition.Right).Symbol,
                        available);

                InvocationExpressionSyntax[] releaseCalls = releaseBody.Syntax
                    .DescendantNodesAndSelf()
                    .OfType<InvocationExpressionSyntax>()
                    .ToArray();

                bool ExactAuthorityCall(
                    string name,
                    IFieldSymbol authority,
                    int arguments,
                    out InvocationExpressionSyntax exact)
                {
                    InvocationExpressionSyntax[] matches = releaseCalls
                        .Where(invocation =>
                            invocation.Expression is MemberAccessExpressionSyntax
                            {
                                Expression: { } receiver,
                            }
                            && SymbolEqualityComparer.Default.Equals(
                                releaseBody.Model.GetSymbolInfo(receiver).Symbol,
                                authority)
                            && releaseBody.Model.GetSymbolInfo(invocation).Symbol is
                                IMethodSymbol { Name: var methodName }
                            && methodName == name
                            && invocation.ArgumentList.Arguments.Count == arguments
                            && invocation.Ancestors()
                                .OfType<ExpressionStatementSyntax>()
                                .FirstOrDefault() is { } statement
                            && IsExactAwaitedInvocationStatement(
                                releaseBody,
                                statement,
                                invocation))
                        .ToArray();

                    exact = matches.Length == 1
                        ? matches[0]
                        : null!;

                    return matches.Length == 1;
                }

                bool exactGrimoireRelease = ExactAuthorityCall(
                    "ReleaseAsync",
                    grimoireField,
                    2,
                    out InvocationExpressionSyntax grimoireRelease);

                bool exactCovenantComplete = ExactAuthorityCall(
                    "CompleteAsync",
                    covenantField,
                    2,
                    out InvocationExpressionSyntax covenantComplete);

                bool exactCovenantDispose = ExactAuthorityCall(
                    "DisposeAsync",
                    covenantField,
                    0,
                    out InvocationExpressionSyntax covenantDispose);

                bool releaseCallsExact = exactGrimoireRelease
                    && exactCovenantComplete
                    && exactCovenantDispose
                    && grimoireRelease.SpanStart < covenantComplete.SpanStart
                    && covenantComplete.SpanStart < covenantDispose.SpanStart
                    && new[] { grimoireRelease, covenantComplete }
                        .All(call =>
                            call.ArgumentList.Arguments.FirstOrDefault() is
                            { Expression: { } disposition }
                            && releaseBody.Model.GetSymbolInfo(disposition).Symbol is
                                IFieldSymbol
                            {
                                Name: "KeepClosed",
                                ConstantValue: (byte)3,
                                ContainingType: { } dispositionType,
                            }
                            && IsExactAuthoredProtocolType(
                                dispositionType,
                                "RetroDownfall.Arcanum.Core.Covenant.CovenantExclusiveLeaseDisposition",
                                releaseBody.Model.Compilation)
                            && call.ArgumentList.Arguments.LastOrDefault() is
                            { Expression: { } token }
                            && releaseBody.Model.GetSymbolInfo(token).Symbol is
                                IPropertySymbol { Name: "None", IsStatic: true }
                            && releaseBody.Model.GetTypeInfo(token).Type is
                            { } tokenType
                            && TypeKey(tokenType) ==
                                "System.Threading.CancellationToken");

                bool exactReleaseTransition = release.Parameters is
                    [IParameterSymbol expectedState]
                    && releaseBody.Syntax is MethodDeclarationSyntax
                    {
                        Body.Statements:
                            [IfStatementSyntax guard, _, _, _],
                    }
                    && guard.Condition is
                            BinaryExpressionSyntax inequality
                    && inequality.IsKind(SyntaxKind.NotEqualsExpression)
                    && StripTransparentExpression(inequality.Left) is
                        InvocationExpressionSyntax releaseCompare
                    && ExactCompareExchange(
                        releaseBody,
                        releaseCompare,
                        released,
                        expectedState)
                    && SymbolEqualityComparer.Default.Equals(
                        releaseBody.Model.GetSymbolInfo(
                            inequality.Right).Symbol,
                        expectedState)
                    && DefinitelyTerminates(guard.Statement);

                bool exactReleaseStatements = exactGrimoireRelease
                    && exactCovenantComplete
                    && exactCovenantDispose
                    && releaseBody.Syntax is
                    MethodDeclarationSyntax
                    {
                        Body.Statements:
                        [
                            IfStatementSyntax,
                            ExpressionStatementSyntax grimoireStatement,
                            ExpressionStatementSyntax covenantStatement,
                            ExpressionStatementSyntax disposeStatement,
                        ],
                    }
                    && grimoireRelease.Ancestors().Contains(grimoireStatement)
                    && covenantComplete.Ancestors().Contains(covenantStatement)
                    && covenantDispose.Ancestors().Contains(disposeStatement);

                bool stateIsOnlyChangedByExactTransitions =
                    state.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                        is VariableDeclaratorSyntax { Initializer: null }
                    &&
                    constructor.ContainingType.DeclaringSyntaxReferences
                        .SelectMany(reference => reference.GetSyntax()
                            .DescendantNodes()
                            .Where(node => node is AssignmentExpressionSyntax
                                or PrefixUnaryExpressionSyntax
                                or PostfixUnaryExpressionSyntax))
                        .All(node => !node.DescendantNodesAndSelf()
                            .OfType<IdentifierNameSyntax>()
                            .Any(identifier =>
                                SymbolEqualityComparer.Default.Equals(
                                    constructorBody.Model.GetSymbolInfo(
                                        identifier).Symbol,
                                    state)));

                InvocationExpressionSyntax[] stateInterlockedWrites =
                    constructor.ContainingType.DeclaringSyntaxReferences
                        .SelectMany(reference => reference.GetSyntax()
                            .DescendantNodes()
                            .OfType<InvocationExpressionSyntax>())
                        .Where(invocation =>
                        {
                            SemanticModel model = factory.Model.Compilation
                                .GetSemanticModel(invocation.SyntaxTree);

                            return model.GetSymbolInfo(invocation).Symbol is
                                IMethodSymbol
                            {
                                IsStatic: true,
                                ContainingType: { } interlocked,
                            }
                                && TypeKey(interlocked) ==
                                    "System.Threading.Interlocked"
                                && invocation.ArgumentList.Arguments.Any(argument =>
                                    argument.RefKindKeyword.IsKind(
                                        SyntaxKind.RefKeyword)
                                    && SymbolEqualityComparer.Default.Equals(
                                        model.GetSymbolInfo(
                                            argument.Expression).Symbol,
                                        state));
                        })
                        .ToArray();

                bool exactStateTransitionInventory =
                    stateInterlockedWrites.Length == 2
                    && stateInterlockedWrites.All(invocation =>
                    {
                        SemanticModel model = factory.Model.Compilation
                            .GetSemanticModel(invocation.SyntaxTree);

                        return model.GetSymbolInfo(invocation).Symbol is
                            IMethodSymbol { Name: "CompareExchange" };
                    })
                    && stateInterlockedWrites.Count(invocation =>
                        consumeBody.Syntax.Span.Contains(invocation.Span)) == 1
                    && stateInterlockedWrites.Count(invocation =>
                        releaseBody.Syntax.Span.Contains(invocation.Span)) == 1;

                return consumeLeaves.Length == 4
                    && consumeBody.Syntax is MethodDeclarationSyntax
                    {
                        Body: null,
                        ExpressionBody.Expression: { } directConsume,
                    }
                    && directConsume == consumeReturn
                    && ExactReference(consumeLeaves[0], creatorField, creator)
                    && ExactReference(consumeLeaves[1], ledgerField, ledger)
                    && exactLedgerClosed
                    && exactConsumeTransition
                    && ExactForward(disposalBody, available)
                    && ExactForward(consumedClosureBody, consumed)
                    && exactReleaseTransition
                    && exactReleaseStatements
                    && releaseCallsExact
                    && stateIsOnlyChangedByExactTransitions
                    && exactStateTransitionInventory;
            }

            bool exactPrimaryValues = operationParameter.Name == "adoptedOperation"
                && evidenceParameter.Name == "evidence"
                && ownerParameter.Name == "ownerId"
                && ExactMappedProperty("AdoptedOperation", operationParameter)
                && ExactMappedProperty("Evidence", evidenceParameter)
                && ExactMappedProperty("OwnerId", ownerParameter);

            if (!exactPrimaryValues)
            {
                return false;
            }

            if (constructorBody.Symbol.Parameters is not
                [
                    IParameterSymbol creatorParameter,
                    IParameterSymbol ledgerParameter,
                    _,
                    _,
                    _,
                    IParameterSymbol covenantParameter,
                    IParameterSymbol grimoireParameter,
                ]
                || creatorParameter.Name != "creator"
                || ledgerParameter.Name != "ledger"
                || covenantParameter.Name != "covenant"
                || grimoireParameter.Name != "grimoire"
                || arguments.FirstOrDefault(argument =>
                    argument.Parameter?.Ordinal == creatorParameter.Ordinal)
                    ?.Value.Syntax is not ThisExpressionSyntax
                || arguments.FirstOrDefault(argument =>
                    argument.Parameter?.Ordinal == ledgerParameter.Ordinal)
                    ?.Value.Syntax is not ExpressionSyntax ledgerExpression
                || factory.Model.GetSymbolInfo(ledgerExpression).Symbol is not
                    IFieldSymbol
                {
                    Name: "_ledgerConnection",
                    IsReadOnly: true,
                } ledgerSource
                || !SymbolEqualityComparer.Default.Equals(
                    ledgerSource.ContainingType,
                    factory.Symbol.ContainingType)
                || arguments.FirstOrDefault(argument =>
                    argument.Parameter?.Ordinal == covenantParameter.Ordinal)
                    ?.Value.Syntax is not ExpressionSyntax covenantExpression
                || factory.Model.GetSymbolInfo(
                    StripTransparentExpression(covenantExpression)).Symbol is not
                    ILocalSymbol { Name: "covenant" } covenantSource
                || arguments.FirstOrDefault(argument =>
                    argument.Parameter?.Ordinal == grimoireParameter.Ordinal)
                    ?.Value.Syntax is not ExpressionSyntax grimoireExpression
                || factory.Model.GetSymbolInfo(
                    StripTransparentExpression(grimoireExpression)).Symbol is not
                    ILocalSymbol { Name: "grimoire" } grimoireSource
                || !ExactMappedField(
                    "_creator",
                    creatorParameter,
                    out IFieldSymbol creatorField)
                || !ExactMappedField(
                    "_ledger",
                    ledgerParameter,
                    out IFieldSymbol ledgerField)
                || !ExactMappedField(
                    "_covenant",
                    covenantParameter,
                    out IFieldSymbol covenantField)
                || !ExactMappedField(
                    "_grimoire",
                    grimoireParameter,
                    out IFieldSymbol grimoireField))
            {
                return false;
            }

            return ExactFieldProperty("Covenant", covenantField)
                && ExactFieldProperty("Grimoire", grimoireField)
                && ExactAuthenticatedAdmissionAuthorityOrigins(
                    factory,
                    admission,
                    covenantSource,
                    grimoireSource)
                && ExactCarrierLifetime(
                    creatorField,
                    ledgerField,
                    covenantField,
                    grimoireField);
        }

        private bool ExactAuthenticatedAdmissionAuthorityOrigins(
            AuthoredMember factory,
            BaseObjectCreationExpressionSyntax admission,
            ILocalSymbol covenant,
            ILocalSymbol grimoire)
        {
            if (covenant.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                    is not VariableDeclaratorSyntax
                    {
                        Initializer.Value: MemberAccessExpressionSyntax
                        {
                            Expression: IdentifierNameSyntax resumedReference,
                            Name.Identifier.ValueText: "Value",
                        },
                    } covenantDeclaration
                || factory.Model.GetSymbolInfo(resumedReference).Symbol is not
                    ILocalSymbol resumed
                || resumed.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                    is not VariableDeclaratorSyntax
                    {
                        Initializer.Value: { } resumedInitializer,
                    } resumedDeclaration
                || factory.Symbol.Parameters.FirstOrDefault(parameter =>
                    parameter.Name == "evidence") is not { } evidence
                || factory.Symbol.Parameters.FirstOrDefault(parameter =>
                    parameter.Name == "cancellationToken") is not { } cancellationToken
                || grimoire.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                    is not VariableDeclaratorSyntax
                    {
                        Initializer.Value.RawKind:
                            (int)SyntaxKind.NullLiteralExpression,
                    } grimoireDeclaration)
            {
                return false;
            }

            InvocationExpressionSyntax[] resumeCalls = resumedInitializer
                .DescendantNodesAndSelf()
                .OfType<InvocationExpressionSyntax>()
                .Where(invocation => factory.Model.GetSymbolInfo(invocation).Symbol is
                    IMethodSymbol { Name: "ResumeExclusiveAsync" })
                .ToArray();

            if (resumeCalls is not [InvocationExpressionSyntax resume]
                || !IsExactAwaitedInvocationInitializer(
                    factory,
                    resumedInitializer,
                    resume)
                || resume.Expression is not MemberAccessExpressionSyntax
                { Expression: { } resumeReceiver }
                || factory.Model.GetSymbolInfo(resumeReceiver).Symbol is not
                    IFieldSymbol
                {
                    Name: "_gate",
                    IsReadOnly: true,
                    IsStatic: false,
                } gate
                || !SymbolEqualityComparer.Default.Equals(
                    gate.ContainingType,
                    factory.Symbol.ContainingType)
                || resume.ArgumentList.Arguments is not
                    [ArgumentSyntax resumeEvidence, ArgumentSyntax resumeToken]
                || !ExactPropertyPath(
                    factory,
                    resumeEvidence.Expression,
                    evidence)
                    && !ExactPropertyPath(
                        factory,
                        resumeEvidence.Expression,
                        evidence,
                        "Owner")
                || !ExactPropertyPath(
                    factory,
                    resumeToken.Expression,
                    cancellationToken)
                || !SymbolIsStableBetween(
                    factory,
                    resumed,
                    resumedDeclaration.Span.End,
                    covenantDeclaration)
                || !SymbolIsStableBetween(
                    factory,
                    gate,
                    factory.Syntax.SpanStart,
                    resume))
            {
                return false;
            }

            BlockSyntax? preflightBlock = resumedDeclaration.Ancestors()
                .OfType<BlockSyntax>()
                .FirstOrDefault();

            IfStatementSyntax[] resumeRefusals = preflightBlock is null
                ? []
                : preflightBlock.Statements
                    .OfType<IfStatementSyntax>()
                    .Where(guard => guard.SpanStart > resumedDeclaration.Span.End
                        && guard.Span.End < covenantDeclaration.SpanStart
                        && ExactPropertyPath(
                            factory,
                            guard.Condition,
                            resumed,
                            "IsFailure")
                        && ExactAuthenticatedAdmissionFailureStatement(
                            factory,
                            guard.Statement))
                    .ToArray();

            if (resumeRefusals is not [IfStatementSyntax resumeRefusal]
                || preflightBlock is null
                || DirectStatement(preflightBlock, resumedDeclaration) is not
                { } resumedDeclarationStatement
                || DirectStatement(preflightBlock, covenantDeclaration) is not
                { } covenantDeclarationStatement
                || preflightBlock.Statements.IndexOf(resumeRefusal) !=
                    preflightBlock.Statements.IndexOf(
                        resumedDeclarationStatement) + 1
                || preflightBlock.Statements.IndexOf(
                    covenantDeclarationStatement) !=
                    preflightBlock.Statements.IndexOf(resumeRefusal) + 1)
            {
                return false;
            }

            AssignmentExpressionSyntax[] grimoireAssignments = factory.Syntax
                .DescendantNodes(node => node == factory.Syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<AssignmentExpressionSyntax>()
                .Where(assignment => SymbolEqualityComparer.Default.Equals(
                    factory.Model.GetSymbolInfo(assignment.Left).Symbol,
                    grimoire))
                .ToArray();

            if (grimoireAssignments is not
                    [AssignmentExpressionSyntax
                    {
                        Right: MemberAccessExpressionSyntax
                        {
                            Expression: IdentifierNameSyntax closedReference,
                            Name.Identifier.ValueText: "Value",
                        },
                    } grimoireAssignment]
                || factory.Model.GetSymbolInfo(closedReference).Symbol is not
                    ILocalSymbol closed
                || closed.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                    is not VariableDeclaratorSyntax
                    {
                        Initializer.Value: { } closedInitializer,
                    } closedDeclaration
                || factory.Syntax.DescendantNodesAndSelf()
                    .Where(node => node.SpanStart > covenantDeclaration.Span.End
                        && node.SpanStart < admission.SpanStart)
                    .Any(node => SyntaxNodeWritesSymbol(
                        factory.Model,
                        node,
                        covenant))
                || factory.Syntax.DescendantNodesAndSelf()
                    .Where(node => node.SpanStart > grimoireAssignment.Span.End
                        && node.SpanStart < admission.SpanStart)
                    .Any(node => SyntaxNodeWritesSymbol(
                        factory.Model,
                        node,
                        grimoire))
                || resumedDeclaration.SpanStart >= covenantDeclaration.SpanStart
                || grimoireDeclaration.SpanStart >= grimoireAssignment.SpanStart)
            {
                return false;
            }

            InvocationExpressionSyntax[] closeCalls = closedInitializer
                .DescendantNodesAndSelf()
                .OfType<InvocationExpressionSyntax>()
                .Where(invocation => factory.Model.GetSymbolInfo(invocation).Symbol is
                    IMethodSymbol { Name: "CloseGrimoireAsync" })
                .ToArray();

            if (closeCalls is not [InvocationExpressionSyntax close]
                || !IsExactAwaitedInvocationInitializer(
                    factory,
                    closedInitializer,
                    close)
                || factory.Model.GetSymbolInfo(close).Symbol is not
                    IMethodSymbol
                {
                    Parameters:
                        [
                            _,
                            _,
                            _,
                            IParameterSymbol { Name: "stranded" },
                            IParameterSymbol { Name: "keepClosedOnFailure" },
                        ],
                } closeMethod
                || !SymbolEqualityComparer.Default.Equals(
                    closeMethod.ContainingType,
                    factory.Symbol.ContainingType)
                || close.Expression is not IdentifierNameSyntax
                    and not MemberAccessExpressionSyntax
                    {
                        Expression: ThisExpressionSyntax,
                    }
                || close.ArgumentList.Arguments is not
                    [
                        ArgumentSyntax closeEvidence,
                        ArgumentSyntax closeCovenant,
                        ArgumentSyntax closeToken,
                        ArgumentSyntax closeStranded,
                        ArgumentSyntax closeKeepClosed,
                    ]
                || !ExactPropertyPath(
                    factory,
                    closeEvidence.Expression,
                    evidence)
                    && !ExactPropertyPath(
                        factory,
                        closeEvidence.Expression,
                        evidence,
                        "Owner")
                || !ExactPropertyPath(
                    factory,
                    closeCovenant.Expression,
                    covenant)
                || !ExactPropertyPath(
                    factory,
                    closeToken.Expression,
                    cancellationToken)
                || factory.Model.GetConstantValue(closeStranded.Expression) is not
                { HasValue: true, Value: null }
                || factory.Model.GetConstantValue(closeKeepClosed.Expression) is not
                { HasValue: true, Value: true }
                || !SymbolIsStableBetween(
                    factory,
                    closed,
                    closedDeclaration.Span.End,
                    grimoireAssignment))
            {
                return false;
            }

            BlockSyntax? closedBlock = closedDeclaration.Ancestors()
                .OfType<BlockSyntax>()
                .FirstOrDefault();

            IfStatementSyntax[] closedRefusals = closedBlock is null
                ? []
                : closedBlock.Statements
                    .OfType<IfStatementSyntax>()
                    .Where(guard => guard.SpanStart > closedDeclaration.Span.End
                        && guard.Span.End < grimoireAssignment.SpanStart
                        && ExactPropertyPath(
                            factory,
                            guard.Condition,
                            closed,
                            "IsFailure")
                        && guard.Statement is BlockSyntax
                        {
                            Statements:
                                [
                                    StatementSyntax cleanup,
                                    ReturnStatementSyntax failure,
                                ],
                        }
                        && IsExactAwaitedAuthenticatedAdmissionCleanup(
                            factory,
                            cleanup,
                            "KeepCovenantClosedAsync")
                        && ExactAuthenticatedAdmissionFailure(
                            factory,
                            failure))
                    .ToArray();

            if (closedRefusals is not [IfStatementSyntax closedRefusal]
                || closedBlock is null
                || DirectStatement(closedBlock, closedDeclaration) is not
                { } closedDeclarationStatement
                || DirectStatement(closedBlock, grimoireAssignment) is not
                { } grimoireAssignmentStatement
                || closedBlock.Statements.IndexOf(closedRefusal) !=
                    closedBlock.Statements.IndexOf(closedDeclarationStatement) + 1
                || closedBlock.Statements.IndexOf(grimoireAssignmentStatement) !=
                    closedBlock.Statements.IndexOf(closedRefusal) + 1)
            {
                return false;
            }

            return true;
        }

        private static bool ExactAuthenticatedAdmissionFailureStatement(
            AuthoredMember factory,
            StatementSyntax statement) => statement switch
            {
                ReturnStatementSyntax failure =>
                    ExactAuthenticatedAdmissionFailure(factory, failure),
                BlockSyntax { Statements: [ReturnStatementSyntax failure] } =>
                    ExactAuthenticatedAdmissionFailure(factory, failure),
                _ => false,
            };

        private bool ExactAuthenticatedAdmissionReturns(
            AuthoredMember factory,
            IfStatementSyntax refusal,
            ReturnStatementSyntax success)
        {
            ReturnStatementSyntax[] returns = factory.Syntax
                .DescendantNodes(node => node == factory.Syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<ReturnStatementSyntax>()
                .ToArray();

            ReturnStatementSyntax[] failures = returns
                .Where(returned => returned != success)
                .ToArray();

            if (success != returns.SingleOrDefault(returned => returned == success)
                || failures.Any(failure =>
                    !ExactAuthenticatedAdmissionFailure(factory, failure)))
            {
                return false;
            }

            if (failures is [ReturnStatementSyntax failure])
            {
                return failure.Ancestors().Contains(refusal.Statement);
            }

            VariableDeclaratorSyntax? covenantDeclaration = factory.Syntax
                .DescendantNodes(node => node == factory.Syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<VariableDeclaratorSyntax>()
                .SingleOrDefault(declaration => factory.Model.GetDeclaredSymbol(
                        declaration) is ILocalSymbol { Name: "covenant" });

            TryStatementSyntax? authorityTry = success.Ancestors()
                .OfType<TryStatementSyntax>()
                .FirstOrDefault();

            return failures is
                [
                    ReturnStatementSyntax preflightFailure,
                    ReturnStatementSyntax covenantFailure,
                    ReturnStatementSyntax candidateFailure,
                    ReturnStatementSyntax adoptedFailure,
                    ReturnStatementSyntax catchFailure,
                ]
                && covenantDeclaration is not null
                && preflightFailure.Span.End < covenantDeclaration.SpanStart
                && authorityTry is not null
                && ExactAuthenticatedFailureGuard(
                    factory,
                    preflightFailure,
                    "resumed")
                && ExactAuthenticatedFailureGuard(
                    factory,
                    covenantFailure,
                    "closed")
                && ExactAuthenticatedCandidateFailureGuard(
                    factory,
                    candidateFailure)
                && covenantFailure.Ancestors().Contains(authorityTry.Block)
                && candidateFailure.Ancestors().Contains(authorityTry.Block)
                && adoptedFailure.Ancestors().Contains(authorityTry.Block)
                && adoptedFailure.Ancestors().Contains(refusal.Statement)
                && HasExactAuthenticatedAdmissionCleanup(
                    factory,
                    covenantFailure,
                    "KeepCovenantClosedAsync")
                && HasExactAuthenticatedAdmissionCleanup(
                    factory,
                    candidateFailure,
                    "KeepRecoveryClosedAsync")
                && HasExactAuthenticatedAdmissionCleanup(
                    factory,
                    adoptedFailure,
                    "KeepRecoveryClosedAsync")
                && HasExactAuthenticatedAdmissionCleanupChoice(
                    factory,
                    catchFailure)
                && ExactAuthenticatedAdmissionCatches(
                    factory,
                    catchFailure,
                    authorityTry);
        }

        private static bool ExactAuthenticatedFailureGuard(
            AuthoredMember factory,
            ReturnStatementSyntax failure,
            string localName)
        {
            IfStatementSyntax? guard = failure.Parent switch
            {
                IfStatementSyntax direct => direct,
                BlockSyntax { Parent: IfStatementSyntax enclosing }
                    when failure.Parent == enclosing.Statement => enclosing,
                BlockSyntax block when block.Parent is IfStatementSyntax enclosing
                    && enclosing.Statement == block => enclosing,
                _ => null,
            };

            if (guard?.Condition is not { } condition)
            {
                return false;
            }

            ILocalSymbol[] locals = condition.DescendantNodesAndSelf()
                    .OfType<IdentifierNameSyntax>()
                    .Select(identifier => factory.Model.GetSymbolInfo(identifier).Symbol)
                    .OfType<ILocalSymbol>()
                    .Where(local => local.Name == localName)
                    .Cast<ISymbol>()
                    .Distinct(SymbolEqualityComparer.Default)
                    .OfType<ILocalSymbol>()
                    .ToArray();

            return locals is [ILocalSymbol local]
                && ExactPropertyPath(factory, condition, local, "IsFailure");
        }

        private static bool ExactAuthenticatedCandidateFailureGuard(
            AuthoredMember factory,
            ReturnStatementSyntax failure)
        {
            IfStatementSyntax? guard = failure.Parent is BlockSyntax
            {
                Parent: IfStatementSyntax enclosing,
            }
                ? enclosing
                : failure.Parent as IfStatementSyntax;

            if (guard?.Condition is not BinaryExpressionSyntax
                {
                    RawKind: (int)SyntaxKind.LogicalOrExpression,
                    Left: { } failed,
                    Right: PrefixUnaryExpressionSyntax
                    {
                        RawKind: (int)SyntaxKind.LogicalNotExpression,
                        Operand: InvocationExpressionSyntax validation,
                    },
                }
                )
            {
                return false;
            }

            ILocalSymbol[] candidates = failed.DescendantNodesAndSelf()
                    .OfType<IdentifierNameSyntax>()
                    .Select(identifier => factory.Model.GetSymbolInfo(identifier).Symbol)
                    .OfType<ILocalSymbol>()
                    .Cast<ISymbol>()
                    .Distinct(SymbolEqualityComparer.Default)
                    .OfType<ILocalSymbol>()
                    .ToArray();

            if (candidates is not [ILocalSymbol candidate]
                || !ExactPropertyPath(
                    factory,
                    failed,
                    candidate,
                    "IsFailure")
                || validation.ArgumentList.Arguments is not
                    [ArgumentSyntax { Expression: { } value }, ArgumentSyntax { Expression: { } evidence }]
                || !ExactPropertyPath(factory, value, candidate, "Value")
                || factory.Model.GetSymbolInfo(evidence).Symbol is not
                    IParameterSymbol { Name: "evidence" } evidenceParameter
                || factory.Model.GetSymbolInfo(validation).Symbol is not
                    IMethodSymbol
                {
                    Name: "ExactAuthenticatedCandidate",
                    IsStatic: true,
                } validationMethod
                || !SymbolEqualityComparer.Default.Equals(
                    validationMethod.ContainingType,
                    factory.Symbol.ContainingType)
                || candidate.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                    is not VariableDeclaratorSyntax
                    {
                        Initializer.Value: { } initializer,
                    } declaration)
            {
                return false;
            }

            InvocationExpressionSyntax[] ledgerWindows = initializer
                .DescendantNodesAndSelf()
                .OfType<InvocationExpressionSyntax>()
                .Where(invocation => factory.Model.GetSymbolInfo(invocation).Symbol is
                    IMethodSymbol { Name: "WithRequiredLedgerAsync" })
                .ToArray();

            return ledgerWindows is [InvocationExpressionSyntax ledgerWindow]
                && IsExactAwaitedInvocationInitializer(
                    factory,
                    initializer,
                    ledgerWindow)
                && SymbolIsStableBetween(
                    factory,
                    candidate,
                    declaration.Span.End,
                    guard)
                && SymbolIsStableBetween(
                    factory,
                    evidenceParameter,
                    factory.Syntax.SpanStart,
                    guard);
        }

        private bool ExactAuthenticatedAdmissionCatches(
            AuthoredMember factory,
            ReturnStatementSyntax exceptionFailure,
            TryStatementSyntax authorityTry)
        {
            CatchClauseSyntax[] catches = authorityTry.Catches.ToArray();

            if (catches is not
                [CatchClauseSyntax cancellation, CatchClauseSyntax exception]
                || cancellation.Declaration?.Type is not { } cancellationType
                || factory.Model.GetTypeInfo(cancellationType).Type is not
                { } cancellationExceptionType
                || TypeKey(cancellationExceptionType) !=
                    "System.OperationCanceledException"
                || cancellation.Filter?.FilterExpression is not
                { } cancellationFilter
                || factory.Symbol.Parameters.FirstOrDefault(parameter =>
                    parameter.Name == "cancellationToken") is not
                    { } cancellationToken
                || !ExactPropertyPath(
                    factory,
                    cancellationFilter,
                    cancellationToken,
                    "IsCancellationRequested")
                || cancellation.Block.Statements is not
                    [IfStatementSyntax _, ThrowStatementSyntax { Expression: null } rethrow]
                || !HasExactAuthenticatedAdmissionCleanupChoiceBefore(
                    factory,
                    rethrow)
                || exception.Declaration?.Type is not { } exceptionType
                || factory.Model.GetTypeInfo(exceptionType).Type is not
                { } generalExceptionType
                || TypeKey(generalExceptionType) !=
                    "System.Exception"
                || exception.Filter is not null
                || exception.Block.Statements.LastOrDefault() != exceptionFailure)
            {
                return false;
            }

            return HasExactAuthenticatedAdmissionCleanupChoice(
                factory,
                exceptionFailure);
        }

        private bool ExactAuthenticatedAdmissionGuardTermination(
            AuthoredMember factory,
            StatementSyntax statement)
        {
            if (statement is BlockSyntax
                {
                    Statements:
                    [
                        StatementSyntax cleanup,
                        ReturnStatementSyntax failure,
                    ],
                })
            {
                return IsExactAwaitedAuthenticatedAdmissionCleanup(
                        factory,
                        cleanup,
                        "KeepRecoveryClosedAsync")
                    && ExactAuthenticatedAdmissionFailure(factory, failure);
            }

            return ExactFailureTermination(factory, statement);
        }

        private static bool ExactAuthenticatedAdmissionFailure(
            AuthoredMember factory,
            ReturnStatementSyntax returned)
        {
            if (returned.Expression is not { } returnedExpression)
            {
                return false;
            }

            ExpressionSyntax expression = StripTransparentExpression(
                returnedExpression);

            if (expression is BaseObjectCreationExpressionSyntax
                {
                    ArgumentList.Arguments:
                    [
                        ArgumentSyntax { Expression: { } failure },
                        ArgumentSyntax { Expression: { } value },
                    ],
                })
            {
                return factory.Model.GetConstantValue(failure) is
                { HasValue: true, Value: true }
                    && StripTransparentExpression(value).IsKind(
                        SyntaxKind.NullLiteralExpression);
            }

            return expression is InvocationExpressionSyntax failureCall
                && factory.Model.GetSymbolInfo(failureCall).Symbol is
                    IMethodSymbol
                {
                    Name: "Failure",
                    IsStatic: true,
                    ContainingType: { } resultType,
                }
                && TypeKey(resultType) is
                    "RetroDownfall.Arcanum.Core.Primitives.Result"
                    or "RetroDownfall.Arcanum.Core.Primitives.Result`1"
                && failureCall.ArgumentList.Arguments.Count == 1;
        }

        private bool HasExactAuthenticatedAdmissionCleanup(
            AuthoredMember factory,
            ReturnStatementSyntax returned,
            string cleanupName)
        {
            if (returned.Parent is not BlockSyntax block)
            {
                return false;
            }

            int returnIndex = block.Statements.IndexOf(returned);

            return returnIndex > 0
                && IsExactAwaitedAuthenticatedAdmissionCleanup(
                    factory,
                    block.Statements[returnIndex - 1],
                    cleanupName);
        }

        private bool HasExactAuthenticatedAdmissionCleanupChoice(
            AuthoredMember factory,
            ReturnStatementSyntax returned) =>
            HasExactAuthenticatedAdmissionCleanupChoiceBefore(factory, returned);

        private bool HasExactAuthenticatedAdmissionCleanupChoiceBefore(
            AuthoredMember factory,
            StatementSyntax terminal)
        {
            if (terminal.Parent is not BlockSyntax block)
            {
                return false;
            }

            int terminalIndex = block.Statements.IndexOf(terminal);

            if (terminalIndex <= 0
                || block.Statements[terminalIndex - 1] is not IfStatementSyntax
                {
                    Condition: IsPatternExpressionSyntax
                    {
                        Expression: { } tested,
                        Pattern: ConstantPatternSyntax
                        {
                            Expression.RawKind: (int)SyntaxKind.NullLiteralExpression,
                        },
                    },
                    Statement: { } whenCovenant,
                    Else.Statement: { } whenRecovery,
                }
                || factory.Model.GetSymbolInfo(tested).Symbol is not
                { Name: "grimoire" })
            {
                return false;
            }

            return IsExactAwaitedAuthenticatedAdmissionCleanup(
                    factory,
                    whenCovenant,
                    "KeepCovenantClosedAsync")
                && IsExactAwaitedAuthenticatedAdmissionCleanup(
                    factory,
                    whenRecovery,
                    "KeepRecoveryClosedAsync");
        }

        private bool IsExactAwaitedAuthenticatedAdmissionCleanup(
            AuthoredMember factory,
            StatementSyntax statement,
            string cleanupName)
        {
            if (statement is BlockSyntax { Statements: [StatementSyntax only] })
            {
                return IsExactAwaitedAuthenticatedAdmissionCleanup(
                    factory,
                    only,
                    cleanupName);
            }

            InvocationExpressionSyntax[] cleanupCalls = statement
                .DescendantNodesAndSelf()
                .OfType<InvocationExpressionSyntax>()
                .Where(invocation =>
                    factory.Model.GetSymbolInfo(invocation).Symbol is
                        IMethodSymbol method
                    && method.Name == cleanupName
                    && SymbolEqualityComparer.Default.Equals(
                        method.ContainingType,
                        factory.Symbol.ContainingType)
                    && IsExactAwaitedInvocationStatement(
                        factory,
                        statement,
                        invocation))
                .ToArray();

            if (cleanupCalls is not [InvocationExpressionSyntax cleanup]
                || factory.Model.GetSymbolInfo(cleanup).Symbol is not
                    IMethodSymbol method)
            {
                return false;
            }

            string[] authorityNames = cleanup.ArgumentList.Arguments
                .Select(argument => factory.Model.GetSymbolInfo(
                    StripTransparentExpression(argument.Expression)).Symbol?.Name)
                .Where(static name => name is not null)
                .Cast<string>()
                .ToArray();

            string[] expectedAuthorities = cleanupName switch
            {
                "KeepCovenantClosedAsync" => ["covenant"],
                "KeepRecoveryClosedAsync" => ["covenant", "grimoire"],
                _ => [],
            };

            return authorityNames.SequenceEqual(expectedAuthorities)
                && method.Parameters.Length == expectedAuthorities.Length
                && statement is ExpressionStatementSyntax
                && statement.DescendantNodesAndSelf()
                    .OfType<AwaitExpressionSyntax>()
                    .Count() == 1
                && ExactAuthenticatedAdmissionCleanupHelper(
                    factory,
                    method,
                    cleanupName);
        }

        private bool ExactAuthenticatedAdmissionCleanupHelper(
            AuthoredMember caller,
            IMethodSymbol method,
            string cleanupName)
        {
            if (Resolve(method, caller.Model.Compilation) is not
                { Syntax: MethodDeclarationSyntax { Body: { } body } } helper)
            {
                return false;
            }

            bool ExactAwaitedReceiverCall(
                StatementSyntax statement,
                ISymbol receiver,
                string name,
                int argumentCount,
                out InvocationExpressionSyntax exact)
            {
                InvocationExpressionSyntax[] calls = statement
                    .DescendantNodesAndSelf()
                    .OfType<InvocationExpressionSyntax>()
                    .Where(invocation => invocation.Expression is
                            MemberAccessExpressionSyntax
                    {
                        Expression: { } expression,
                    }
                        && SymbolEqualityComparer.Default.Equals(
                            helper.Model.GetSymbolInfo(expression).Symbol,
                            receiver)
                        && helper.Model.GetSymbolInfo(invocation).Symbol is
                            IMethodSymbol { Name: var methodName }
                        && methodName == name
                        && invocation.ArgumentList.Arguments.Count == argumentCount
                        && IsExactAwaitedInvocationStatement(
                            helper,
                            statement,
                            invocation))
                    .ToArray();

                exact = calls.Length == 1
                    ? calls[0]
                    : null!;

                return statement is ExpressionStatementSyntax
                    && calls.Length == 1;
            }

            bool ExactKeepClosedArguments(InvocationExpressionSyntax invocation) =>
                invocation.ArgumentList.Arguments is
                    [
                        ArgumentSyntax { Expression: { } disposition },
                        ArgumentSyntax { Expression: { } token },
                    ]
                && helper.Model.GetSymbolInfo(disposition).Symbol is
                    IFieldSymbol
                {
                    Name: "KeepClosed",
                    ConstantValue: (byte)3,
                    ContainingType: { } dispositionType,
                }
                && IsExactAuthoredProtocolType(
                    dispositionType,
                    "RetroDownfall.Arcanum.Core.Covenant.CovenantExclusiveLeaseDisposition",
                    helper.Model.Compilation)
                && helper.Model.GetSymbolInfo(token).Symbol is
                    IPropertySymbol { Name: "None", IsStatic: true }
                && helper.Model.GetTypeInfo(token).Type is { } tokenType
                && TypeKey(tokenType) ==
                    "System.Threading.CancellationToken";

            if (cleanupName == "KeepCovenantClosedAsync"
                && helper.Symbol.Parameters is [IParameterSymbol covenant]
                && body.Statements is
                    [StatementSyntax completeStatement, StatementSyntax disposeStatement]
                && ExactAwaitedReceiverCall(
                    completeStatement,
                    covenant,
                    "CompleteAsync",
                    2,
                    out InvocationExpressionSyntax complete)
                && ExactKeepClosedArguments(complete)
                && ExactAwaitedReceiverCall(
                    disposeStatement,
                    covenant,
                    "DisposeAsync",
                    0,
                    out _))
            {
                return true;
            }

            if (cleanupName != "KeepRecoveryClosedAsync"
                || helper.Symbol.Parameters is not
                    [IParameterSymbol recoveryCovenant, IParameterSymbol grimoire]
                || body.Statements is not
                    [StatementSyntax releaseStatement, StatementSyntax covenantStatement]
                || !ExactAwaitedReceiverCall(
                    releaseStatement,
                    grimoire,
                    "ReleaseAsync",
                    2,
                    out InvocationExpressionSyntax release)
                || !ExactKeepClosedArguments(release)
                || covenantStatement is not ExpressionStatementSyntax
                || covenantStatement.DescendantNodesAndSelf()
                    .OfType<InvocationExpressionSyntax>()
                    .Where(invocation => helper.Model.GetSymbolInfo(invocation).Symbol is
                            IMethodSymbol nested
                        && nested.Name == "KeepCovenantClosedAsync"
                        && SymbolEqualityComparer.Default.Equals(
                            nested.ContainingType,
                            helper.Symbol.ContainingType)
                        && invocation.ArgumentList.Arguments is
                            [ArgumentSyntax { Expression: { } argument }]
                        && SymbolEqualityComparer.Default.Equals(
                            helper.Model.GetSymbolInfo(argument).Symbol,
                    recoveryCovenant)
                        && IsExactAwaitedInvocationStatement(
                            helper,
                            covenantStatement,
                            invocation))
                    .ToArray() is not [InvocationExpressionSyntax keepCovenant]
                || helper.Model.GetSymbolInfo(keepCovenant).Symbol is not
                    IMethodSymbol keepCovenantMethod)
            {
                return false;
            }

            return ExactAuthenticatedAdmissionCleanupHelper(
                helper,
                keepCovenantMethod,
                "KeepCovenantClosedAsync");
        }

        private static bool IsExactAuthenticatedAdmissionRefusal(
            AuthoredMember factory,
            ExpressionSyntax condition,
            InvocationExpressionSyntax adoptedCheck,
            ILocalSymbol adopted,
            IReadOnlyList<string> adoptedOperationPath)
        {
            ExpressionSyntax[] leaves = ExactLogicalOrLeaves(condition);
            string[] acquiredPath = [
                .. adoptedOperationPath.Take(adoptedOperationPath.Count - 1),
                "Acquired",
            ];

            bool exactFailure = leaves.Count(leaf => ExactPropertyPath(
                factory,
                leaf,
                adopted,
                "IsFailure")) == 1;

            return leaves switch
            {
                [ExpressionSyntax acquired, ExpressionSyntax verifier] =>
                    !exactFailure
                    && IsExactLogicalNotProperty(
                        factory,
                        acquired,
                        adopted,
                        acquiredPath)
                    && IsExactLogicalNotInvocation(verifier, adoptedCheck),
                [ExpressionSyntax failure, ExpressionSyntax acquired,
                    ExpressionSyntax verifier] =>
                    exactFailure
                    && ExactPropertyPath(factory, failure, adopted, "IsFailure")
                    && IsExactLogicalNotProperty(
                        factory,
                        acquired,
                        adopted,
                        acquiredPath)
                    && IsExactLogicalNotInvocation(verifier, adoptedCheck),
                _ => false,
            };
        }

        private static bool ExactAuthenticatedAdmissionSuccessReturn(
            AuthoredMember factory,
            BaseObjectCreationExpressionSyntax admission,
            IfStatementSyntax refusal,
            out ReturnStatementSyntax returned)
        {
            returned = null!;

            ReturnStatementSyntax? candidate = admission.Ancestors()
                .OfType<ReturnStatementSyntax>()
                .FirstOrDefault();

            if (candidate?.Expression is not { } returnedExpression
                || candidate.SpanStart <= refusal.Span.End
                || refusal.Parent is not BlockSyntax block
                || candidate.Parent != block
                || block.Statements.IndexOf(candidate)
                    != block.Statements.IndexOf(refusal) + 1
                || factory.Model.AnalyzeControlFlow(candidate)?.StartPointIsReachable
                    != true)
            {
                return false;
            }

            returned = candidate;

            ExpressionSyntax result = StripTransparentExpression(returnedExpression);

            if (result is InvocationExpressionSyntax success
                && factory.Model.GetSymbolInfo(success).Symbol is
                    IMethodSymbol
                {
                    Name: "Success",
                    IsStatic: true,
                    ContainingType: { } resultType,
                }
                && TypeKey(resultType) is
                    "RetroDownfall.Arcanum.Core.Primitives.Result"
                    or "RetroDownfall.Arcanum.Core.Primitives.Result`1"
                && success.ArgumentList.Arguments is
                    [ArgumentSyntax { Expression: { } value }])
            {
                return StripTransparentExpression(value) == admission;
            }

            return result is BaseObjectCreationExpressionSyntax wrapper
                && wrapper.ArgumentList?.Arguments is
                    [ArgumentSyntax { Expression: { } failure }, ArgumentSyntax { Expression: { } createdValue }]
                && factory.Model.GetConstantValue(failure) is
                { HasValue: true, Value: false }
                && StripTransparentExpression(createdValue) == admission;
        }

        private bool ExactDelegatedOwnerCandidateCheck(
            AuthoredMember verifier,
            IReadOnlyList<ExpressionSyntax> leaves,
            IParameterSymbol operation,
            IParameterSymbol evidence)
        {
            InvocationExpressionSyntax[] delegatedChecks = leaves
                .Select(StripTransparentExpression)
                .OfType<InvocationExpressionSyntax>()
                .Where(invocation => verifier.Model.GetSymbolInfo(invocation).Symbol is
                    IMethodSymbol method
                    && method.Name == "ExactAuthenticatedCandidate"
                    && SymbolEqualityComparer.Default.Equals(
                        method.ContainingType,
                        verifier.Symbol.ContainingType))
                .ToArray();

            if (delegatedChecks is not [InvocationExpressionSyntax delegated]
                || AdmissionArguments(verifier, delegated).ToArray() is not
                    [
                        (ExpressionSyntax candidateArgument, _, _),
                        (ExpressionSyntax evidenceArgument, _, _),
                    ]
                || !ExactOperationWithExpectedRevision(
                    verifier,
                    candidateArgument,
                    operation,
                    evidence)
                || !ExactPropertyPath(verifier, evidenceArgument, evidence)
                || verifier.Model.GetSymbolInfo(delegated).Symbol is not
                    IMethodSymbol delegatedMethod
                || ResolveInvocationTarget(
                    delegatedMethod,
                    verifier,
                    delegated) is not { } candidateVerifier
                || candidateVerifier.Symbol.Parameters is not
                    [IParameterSymbol candidate, IParameterSymbol candidateEvidence])
            {
                return false;
            }

            return ExactOwnerCandidateChecks(
                candidateVerifier,
                candidate,
                candidateEvidence);
        }

        private static bool ExactOperationWithExpectedRevision(
            AuthoredMember verifier,
            ExpressionSyntax expression,
            IParameterSymbol operation,
            IParameterSymbol evidence) =>
            StripTransparentExpression(expression) is WithExpressionSyntax
            {
                Expression: { } source,
                Initializer.Expressions:
                [
                    AssignmentExpressionSyntax
                {
                    Left: IdentifierNameSyntax
                    {
                        Identifier.ValueText: "Revision",
                    },
                    Right: { } revision,
                } assignment,
                ],
            }
            && assignment.IsKind(SyntaxKind.SimpleAssignmentExpression)
            && ExactPropertyPath(verifier, source, operation)
            && ExactPropertyPath(
                verifier,
                revision,
                evidence,
                "ExpectedOperation",
                "Revision");

        private bool ExactOwnerCandidateChecks(
            AuthoredMember verifier,
            IParameterSymbol operation,
            IParameterSymbol evidence)
        {
            ExpressionSyntax? returned = ExactReturnedBooleanExpression(verifier);
            ExpressionSyntax[] leaves = returned is null
                ? []
                : ExactLogicalAndLeaves(returned);

            return returned is not null
                && leaves.Length is 4 or 20
                && SymbolIsStableThrough(
                    verifier,
                    operation,
                    verifier.Syntax.SpanStart,
                    returned)
                && SymbolIsStableThrough(
                    verifier,
                    evidence,
                    verifier.Syntax.SpanStart,
                    returned)
                && (leaves.Length == 4
                    ? ExactOwnerCandidateLeaves(
                        verifier,
                        leaves,
                        operation,
                        evidence)
                    : ExactProductionOwnerCandidateChecks(
                        verifier,
                        leaves,
                        operation,
                        evidence,
                        returned));
        }

        private bool ExactProductionOwnerCandidateChecks(
            AuthoredMember verifier,
            IReadOnlyList<ExpressionSyntax> leaves,
            IParameterSymbol operation,
            IParameterSymbol evidence,
            ExpressionSyntax returned)
        {
            if (!TryGetExactOwnerCandidateLocals(
                    verifier,
                    operation,
                    evidence,
                    returned,
                    out ILocalSymbol expected,
                    out ILocalSymbol binding,
                    out ILocalSymbol launch))
            {
                return false;
            }

            (string Launch, string Binding)[] bindingComparisons =
            [
                ("OperationId", "OperationId"),
                ("Kind", "Kind"),
                ("EffectDigest", "EffectDigest"),
                ("SourceDatasetGeneration", "SourceDatasetGeneration"),
                ("TargetDatasetGeneration", "TargetDatasetGeneration"),
                ("SourceEpochs", "SourceEpochs"),
                ("TargetEpochs", "TargetEpochs"),
                ("Digest", "DatabaseOperationLaunchBindingDigest"),
            ];

            return leaves.Count(leaf => ExactPropertyPath(
                    verifier,
                    leaf,
                    launch,
                    "IsSuccess")) == 1
                && leaves.Count(leaf => IsExactEquality(
                    verifier,
                    leaf,
                    operation,
                    ["Id"],
                    expected,
                    ["OperationId"])) == 1
                && leaves.Count(leaf => IsExactOrdinalStringEquality(
                    verifier,
                    leaf,
                    operation,
                    ["Kind"],
                    expected,
                    ["Kind"])) == 1
                && leaves.Count(leaf => IsExactEquality(
                    verifier,
                    leaf,
                    operation,
                    ["CheckpointVersion"],
                    expected,
                    ["CheckpointVersion"])) == 1
                && leaves.Count(leaf => IsExactEquality(
                    verifier,
                    leaf,
                    operation,
                    ["Revision"],
                    expected,
                    ["Revision"])) == 1
                && leaves.Count(leaf => ExactOwnerRecoveryPolicyCheck(
                    verifier,
                    leaf,
                    operation)) == 1
                && leaves.Count(leaf => ExactOwnerCheckpointReferenceCheck(
                    verifier,
                    leaf,
                    operation)) == 1
                && leaves.Count(leaf => ExactOwnerActiveStateCheck(
                    verifier,
                    leaf,
                    operation)) == 1
                && leaves.Count(leaf => ExactOwnerClassificationCheck(
                    verifier,
                    leaf,
                    operation,
                    evidence)) == 1
                && bindingComparisons.All(comparison => leaves.Count(leaf =>
                    IsExactEquality(
                        verifier,
                        leaf,
                        launch,
                        ["Value", comparison.Launch],
                        binding,
                        [comparison.Binding])) == 1)
                && leaves.Count(leaf => IsExactEquality(
                    verifier,
                    leaf,
                    binding,
                    ["SlotEpoch"],
                    evidence,
                    ["Journal", "SlotEpoch"])) == 1
                && leaves.Count(leaf => IsExactDirectedBinaryComparison(
                    verifier,
                    leaf,
                    SyntaxKind.GreaterThanExpression,
                    binding,
                    ["ExpectedDatabaseOperationRevision"],
                    launch,
                    ["Value", "StartingRevision"])) == 1
                && leaves.Count(leaf => IsExactDirectedBinaryComparison(
                    verifier,
                    leaf,
                    SyntaxKind.LessThanOrEqualExpression,
                    binding,
                    ["ExpectedDatabaseOperationRevision"],
                    operation,
                    ["Revision"])) == 1;
        }

        private bool TryGetExactOwnerCandidateLocals(
            AuthoredMember verifier,
            IParameterSymbol operation,
            IParameterSymbol evidence,
            ExpressionSyntax returned,
            out ILocalSymbol expected,
            out ILocalSymbol binding,
            out ILocalSymbol launch)
        {
            expected = null!;
            binding = null!;
            launch = null!;

            VariableDeclaratorSyntax[] variables = verifier.Syntax
                .DescendantNodes(node => node == verifier.Syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<VariableDeclaratorSyntax>()
                .Where(static variable => variable.Initializer is not null)
                .ToArray();

            ILocalSymbol[] expectedCandidates = variables
                .Where(variable => variable.Initializer?.Value is { } initializer
                    && verifier.Model.GetDeclaredSymbol(variable) is ILocalSymbol local
                    && IsExactAuthoredProtocolType(
                        local.Type,
                        "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationRecoveryFingerprint",
                        verifier.Model.Compilation)
                    && ExactPropertyPath(
                        verifier,
                        initializer,
                        evidence,
                        "ExpectedOperation"))
                .Select(variable =>
                    (ILocalSymbol)verifier.Model.GetDeclaredSymbol(variable)!)
                .ToArray();

            ILocalSymbol[] bindingCandidates = variables
                .Where(variable => variable.Initializer?.Value is { } initializer
                    && verifier.Model.GetDeclaredSymbol(variable) is ILocalSymbol local
                    && IsExactAuthoredProtocolType(
                        local.Type,
                        "RetroDownfall.Arcanum.Infrastructure.GrimoireTransitions.GrimoireOfflineTransitionBinding",
                        verifier.Model.Compilation)
                    && ExactPropertyPath(
                        verifier,
                        initializer,
                        evidence,
                        "Journal",
                        "Binding"))
                .Select(variable =>
                    (ILocalSymbol)verifier.Model.GetDeclaredSymbol(variable)!)
                .ToArray();

            ILocalSymbol[] launchCandidates = variables
                .Where(variable => variable.Initializer?.Value is { } initializer
                    && verifier.Model.GetDeclaredSymbol(variable) is ILocalSymbol
                    && ExactCommittedLaunchProjection(
                        verifier,
                        initializer,
                        operation))
                .Select(variable =>
                    (ILocalSymbol)verifier.Model.GetDeclaredSymbol(variable)!)
                .ToArray();

            if (expectedCandidates is not [ILocalSymbol expectedCandidate]
                || bindingCandidates is not [ILocalSymbol bindingCandidate]
                || launchCandidates is not [ILocalSymbol launchCandidate]
                || !SymbolIsStableThrough(
                    verifier,
                    expectedCandidate,
                    verifier.Syntax.SpanStart,
                    returned)
                || !SymbolIsStableThrough(
                    verifier,
                    bindingCandidate,
                    verifier.Syntax.SpanStart,
                    returned)
                || !SymbolIsStableThrough(
                    verifier,
                    launchCandidate,
                    verifier.Syntax.SpanStart,
                    returned))
            {
                return false;
            }

            expected = expectedCandidate;
            binding = bindingCandidate;
            launch = launchCandidate;

            return true;
        }

        private bool ExactCommittedLaunchProjection(
            AuthoredMember verifier,
            ExpressionSyntax expression,
            IParameterSymbol operation)
        {
            if (StripTransparentExpression(expression) is not
                    InvocationExpressionSyntax projection
                || verifier.Model.GetSymbolInfo(projection).Symbol is not
                    IMethodSymbol
                {
                    Name: "FromCommittedCheckpoint",
                    IsStatic: true,
                } method
                || !IsExactAuthoredProtocolType(
                    method.ContainingType,
                    "RetroDownfall.Arcanum.Infrastructure.GrimoireTransitions.GrimoireOfflineTransitionLaunch",
                    verifier.Model.Compilation)
                || AdmissionArguments(verifier, projection)
                    .Select(static argument => argument.Expression)
                    .ToArray() is not
                    [ExpressionSyntax version, ExpressionSyntax payload]
                || !ExactPropertyPath(
                    verifier,
                    version,
                    operation,
                    "CheckpointVersion")
                || StripTransparentExpression(payload) is not
                    BinaryExpressionSyntax fallback
                || !fallback.IsKind(SyntaxKind.CoalesceExpression)
                || !ExactPropertyPath(
                    verifier,
                    fallback.Left,
                    operation,
                    "CheckpointPayload")
                || StripTransparentExpression(fallback.Right) is not
                    CollectionExpressionSyntax { Elements.Count: 0 })
            {
                return false;
            }

            return true;
        }

        private bool ExactOwnerRecoveryPolicyCheck(
            AuthoredMember verifier,
            ExpressionSyntax expression,
            IParameterSymbol operation)
        {
            if (StripTransparentExpression(expression) is not
                    BinaryExpressionSyntax comparison
                || !comparison.IsKind(SyntaxKind.EqualsExpression))
            {
                return false;
            }

            ExpressionSyntax choice;

            if (ExactPropertyPath(
                    verifier,
                    comparison.Left,
                    operation,
                    "RecoveryPolicy"))
            {
                choice = comparison.Right;
            }
            else if (ExactPropertyPath(
                    verifier,
                    comparison.Right,
                    operation,
                    "RecoveryPolicy"))
            {
                choice = comparison.Left;
            }
            else
            {
                return false;
            }

            return StripTransparentExpression(choice) is
                    ConditionalExpressionSyntax conditional
                && ExactMutationKindTest(
                    verifier,
                    conditional.Condition,
                    operation)
                && ExactAuthoredEnumMember(
                    verifier,
                    conditional.WhenTrue,
                    "RetroDownfall.Arcanum.Core.Operations.LongRunningOperationRecoveryPolicy",
                    "ReconcileAndComplete")
                && ExactAuthoredEnumMember(
                    verifier,
                    conditional.WhenFalse,
                    "RetroDownfall.Arcanum.Core.Operations.LongRunningOperationRecoveryPolicy",
                    "RestartIdempotently");
        }

        private bool ExactMutationKindTest(
            AuthoredMember verifier,
            ExpressionSyntax expression,
            IParameterSymbol operation)
        {
            if (StripTransparentExpression(expression) is not
                    InvocationExpressionSyntax comparison
                || verifier.Model.GetSymbolInfo(comparison).Symbol is not
                    IMethodSymbol method
                || !IsExactFrameworkMethod(
                    method,
                    "System.String",
                    "Equals",
                    "System.Private.CoreLib")
                || comparison.ArgumentList.Arguments is not
                    [ArgumentSyntax left, ArgumentSyntax right, ArgumentSyntax ordinal])
            {
                return false;
            }

            return ExactPropertyPath(
                    verifier,
                    left.Expression,
                    operation,
                    "Kind")
                && ExactAuthoredEnumMember(
                    verifier,
                    right.Expression,
                    "RetroDownfall.Arcanum.Core.Operations.LongRunningOperationKinds",
                    "DataRetentionMutation")
                && ExactEnumMember(
                    verifier,
                    ordinal.Expression,
                    "System.StringComparison",
                    "Ordinal");
        }

        private bool ExactOwnerCheckpointReferenceCheck(
            AuthoredMember verifier,
            ExpressionSyntax expression,
            IParameterSymbol operation)
        {
            if (StripTransparentExpression(expression) is not
                    InvocationExpressionSyntax comparison
                || verifier.Model.GetSymbolInfo(comparison).Symbol is not
                    IMethodSymbol stringEquals
                || !IsExactFrameworkMethod(
                    stringEquals,
                    "System.String",
                    "Equals",
                    "System.Private.CoreLib")
                || comparison.ArgumentList.Arguments is not
                    [ArgumentSyntax checkpoint, ArgumentSyntax derived, ArgumentSyntax ordinal]
                || !ExactPropertyPath(
                    verifier,
                    checkpoint.Expression,
                    operation,
                    "CheckpointReference")
                || StripTransparentExpression(derived.Expression) is not
                    InvocationExpressionSyntax derivation
                || verifier.Model.GetSymbolInfo(derivation).Symbol is not
                    IMethodSymbol
                {
                    Name: "CheckpointReference",
                    IsStatic: true,
                } method
                || !IsExactAuthoredProtocolType(
                    method.ContainingType,
                    "RetroDownfall.Arcanum.Infrastructure.Data.Covenant.CovenantResetCheckpointInitiator",
                    verifier.Model.Compilation)
                || AdmissionArguments(verifier, derivation)
                    .Select(static argument => argument.Expression)
                    .ToArray() is not
                    [ExpressionSyntax kind, ExpressionSyntax operationId])
            {
                return false;
            }

            return ExactPropertyPath(verifier, kind, operation, "Kind")
                && ExactPropertyPath(verifier, operationId, operation, "Id")
                && ExactEnumMember(
                    verifier,
                    ordinal.Expression,
                    "System.StringComparison",
                    "Ordinal");
        }

        private bool ExactOwnerActiveStateCheck(
            AuthoredMember verifier,
            ExpressionSyntax expression,
            IParameterSymbol operation)
        {
            if (StripTransparentExpression(expression) is not
                    IsPatternExpressionSyntax
                {
                    Expression: { } state,
                    Pattern: { } pattern,
                }
                || !ExactPropertyPath(verifier, state, operation, "State"))
            {
                return false;
            }

            PatternSyntax[] exclusions = ExactAndPatternLeaves(pattern);

            return exclusions.Length == 3
                && exclusions.Count(exclusion => ExactNegatedAuthoredEnumPattern(
                    verifier,
                    exclusion,
                    "LongRunningOperationState",
                    "Completed")) == 1
                && exclusions.Count(exclusion => ExactNegatedAuthoredEnumPattern(
                    verifier,
                    exclusion,
                    "LongRunningOperationState",
                    "Failed")) == 1
                && exclusions.Count(exclusion => ExactNegatedAuthoredEnumPattern(
                    verifier,
                    exclusion,
                    "LongRunningOperationState",
                    "Abandoned")) == 1;
        }

        private static PatternSyntax[] ExactAndPatternLeaves(PatternSyntax pattern) =>
            pattern is BinaryPatternSyntax conjunction
                && conjunction.IsKind(SyntaxKind.AndPattern)
                ? [
                    .. ExactAndPatternLeaves(conjunction.Left),
                    .. ExactAndPatternLeaves(conjunction.Right),
                ]
                : [pattern];

        private bool ExactNegatedAuthoredEnumPattern(
            AuthoredMember verifier,
            PatternSyntax pattern,
            string containingTypeName,
            string memberName) =>
            pattern is UnaryPatternSyntax negation
            && negation.IsKind(SyntaxKind.NotPattern)
            && negation.Pattern is ConstantPatternSyntax
            { Expression: { } constant }
            && ExactAuthoredEnumMember(
                verifier,
                constant,
                "RetroDownfall.Arcanum.Core.Operations." + containingTypeName,
                memberName);

        private bool ExactAuthoredEnumMember(
            AuthoredMember verifier,
            ExpressionSyntax expression,
            string containingType,
            string name) =>
            verifier.Model.GetSymbolInfo(
                StripTransparentExpression(expression)).Symbol is
                IFieldSymbol field
            && field.Name == name
            && IsExactAuthoredProtocolType(
                field.ContainingType,
                containingType,
                verifier.Model.Compilation);

        private bool ExactOwnerCandidateLeaves(
            AuthoredMember verifier,
            IReadOnlyList<ExpressionSyntax> leaves,
            IParameterSymbol operation,
            IParameterSymbol evidence) =>
            leaves.Count(leaf => IsExactEquality(
                    verifier,
                    leaf,
                    operation,
                    ["Id"],
                    evidence,
                    ["ExpectedOperation", "OperationId"])) == 1
                && leaves.Count(leaf => IsExactOrdinalStringEquality(
                    verifier,
                    leaf,
                    operation,
                    ["Kind"],
                    evidence,
                    ["ExpectedOperation", "Kind"])) == 1
                && leaves.Count(leaf => IsExactEquality(
                    verifier,
                    leaf,
                    operation,
                    ["CheckpointVersion"],
                    evidence,
                    ["ExpectedOperation", "CheckpointVersion"])) == 1
                && leaves.Count(leaf => ExactOwnerClassificationCheck(
                    verifier,
                    leaf,
                    operation,
                    evidence)) == 1;

        private static ExpressionSyntax? ExactReturnedBooleanExpression(
            AuthoredMember member)
        {
            ExpressionSyntax? expression = member.Syntax switch
            {
                MethodDeclarationSyntax
                {
                    ExpressionBody.Expression: { } value,
                } => value,
                LocalFunctionStatementSyntax
                {
                    ExpressionBody.Expression: { } value,
                } => value,
                _ => null,
            };

            if (expression is null)
            {
                ReturnStatementSyntax[] returns = member.Syntax
                    .DescendantNodes(node => node == member.Syntax
                        || node is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .OfType<ReturnStatementSyntax>()
                    .Where(static returned => returned.Expression is not null)
                    .ToArray();

                if (returns is not [ReturnStatementSyntax { Expression: { } returned }])
                {
                    return null;
                }

                expression = returned;
            }

            return expression;
        }

        private static ExpressionSyntax[] ExactLogicalAndLeaves(
            ExpressionSyntax expression)
        {
            expression = StripTransparentExpression(expression);

            return expression is BinaryExpressionSyntax conjunction
                    && conjunction.IsKind(SyntaxKind.LogicalAndExpression)
                ? [
                    .. ExactLogicalAndLeaves(conjunction.Left),
                    .. ExactLogicalAndLeaves(conjunction.Right),
                ]
                : [expression];
        }

        private static bool IsExactIncrementedRevisionEquality(
            AuthoredMember member,
            ExpressionSyntax expression,
            ISymbol operation,
            ISymbol evidence) =>
            StripTransparentExpression(expression) is
                BinaryExpressionSyntax comparison
            && comparison.IsKind(SyntaxKind.EqualsExpression)
            && (ExactPropertyPath(
                    member,
                    comparison.Left,
                    operation,
                    "Revision")
                && IsExactIncrement(
                    member,
                    comparison.Right,
                    evidence,
                    "ExpectedOperation",
                    "Revision")
                || ExactPropertyPath(
                    member,
                    comparison.Right,
                    operation,
                    "Revision")
                && IsExactIncrement(
                    member,
                    comparison.Left,
                    evidence,
                    "ExpectedOperation",
                    "Revision"));

        private static bool IsExactRunningStateEquality(
            AuthoredMember member,
            ExpressionSyntax expression,
            ISymbol operation) =>
            StripTransparentExpression(expression) is
                BinaryExpressionSyntax comparison
            && comparison.IsKind(SyntaxKind.EqualsExpression)
            && (ExactPropertyPath(
                    member,
                    comparison.Left,
                    operation,
                    "State")
                && ExactEnumMember(
                    member,
                    comparison.Right,
                    "RetroDownfall.Arcanum.Core.Operations.LongRunningOperationState",
                    "Running")
                || ExactPropertyPath(
                    member,
                    comparison.Right,
                    operation,
                    "State")
                && ExactEnumMember(
                    member,
                    comparison.Left,
                    "RetroDownfall.Arcanum.Core.Operations.LongRunningOperationState",
                    "Running"));

        private bool ExactOwnerClassificationCheck(
            AuthoredMember verifier,
            ExpressionSyntax expression,
            ISymbol operation,
            ISymbol evidence,
            bool negated = false)
        {
            if (!TryMatchRecoveryDisposition(
                    verifier.Model,
                    expression,
                    "OwnerBoundOffline",
                    negated,
                    out ExpressionSyntax receiver))
            {
                return false;
            }

            InvocationExpressionSyntax? classification =
                StripTransparentExpression(receiver) as InvocationExpressionSyntax;

            if (classification is null
                && verifier.Model.GetSymbolInfo(receiver).Symbol is ILocalSymbol decision
                && decision.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax() is
                    VariableDeclaratorSyntax
                {
                    Initializer.Value: InvocationExpressionSyntax initializer,
                } declaration
                && !verifier.Syntax.DescendantNodesAndSelf()
                    .OfType<AssignmentExpressionSyntax>()
                    .Any(assignment => assignment.SpanStart > declaration.Span.End
                        && assignment.Span.End < expression.SpanStart
                        && SymbolEqualityComparer.Default.Equals(
                            verifier.Model.GetSymbolInfo(assignment.Left).Symbol,
                            decision)))
            {
                classification = initializer;
            }

            return classification is not null
                && verifier.Model.GetSymbolInfo(classification).Symbol is
                    IMethodSymbol { Name: "Classify" } classifier
                && IsExactAuthoredProtocolType(
                    classifier.ContainingType,
                    "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationRecoveryAdmission",
                    verifier.Model.Compilation)
                && AdmissionArguments(verifier, classification)
                    .Select(static argument => argument.Expression)
                    .ToArray() is
                    [ExpressionSyntax classified, ExpressionSyntax ownerEvidence]
                && ExactPropertyPath(verifier, classified, operation)
                && ExactPropertyPath(verifier, ownerEvidence, evidence);
        }

        private static ExpressionSyntax[] ExactLogicalOrLeaves(
            ExpressionSyntax expression)
        {
            expression = StripTransparentExpression(expression);

            return expression is BinaryExpressionSyntax disjunction
                    && disjunction.IsKind(SyntaxKind.LogicalOrExpression)
                ? [
                    .. ExactLogicalOrLeaves(disjunction.Left),
                    .. ExactLogicalOrLeaves(disjunction.Right),
                ]
                : [expression];
        }

        private static bool IsExactNullTest(
            AuthoredMember member,
            ExpressionSyntax expression,
            ISymbol symbol) =>
            StripTransparentExpression(expression) is IsPatternExpressionSyntax
            {
                Expression: { } tested,
                Pattern: ConstantPatternSyntax
                {
                    Expression: LiteralExpressionSyntax literal,
                },
            }
            && literal.IsKind(SyntaxKind.NullLiteralExpression)
            && ExactPropertyPath(member, tested, symbol);

        private static bool IsExactLogicalNotProperty(
            AuthoredMember member,
            ExpressionSyntax expression,
            ISymbol symbol,
            params string[] path) =>
            StripTransparentExpression(expression) is PrefixUnaryExpressionSyntax negation
            && negation.IsKind(SyntaxKind.LogicalNotExpression)
            && ExactPropertyPath(member, negation.Operand, symbol, path);

        private static bool IsExactLogicalNotInvocation(
            ExpressionSyntax expression,
            InvocationExpressionSyntax invocation) =>
            StripTransparentExpression(expression) is PrefixUnaryExpressionSyntax negation
            && negation.IsKind(SyntaxKind.LogicalNotExpression)
            && StripTransparentExpression(negation.Operand) == invocation;

        private static bool TryGetPropertyPath(
            AuthoredMember member,
            ExpressionSyntax expression,
            out ISymbol root,
            out string[] path)
        {
            var segments = new List<string>();

            expression = StripTransparentExpression(expression);

            while (expression is MemberAccessExpressionSyntax access)
            {
                segments.Add(access.Name.Identifier.ValueText);
                expression = StripTransparentExpression(access.Expression);
            }

            root = member.Model.GetSymbolInfo(expression).Symbol!;
            segments.Reverse();
            path = [.. segments];

            return root is not null;
        }

        private static bool IsExactBinaryComparison(
            AuthoredMember member,
            ExpressionSyntax expression,
            SyntaxKind comparisonKind,
            ISymbol leftRoot,
            string[] leftPath,
            ISymbol rightRoot,
            string[] rightPath) =>
            StripTransparentExpression(expression) is
                BinaryExpressionSyntax comparison
            && comparison.IsKind(comparisonKind)
            && (ExactPropertyPath(
                    member,
                    comparison.Left,
                    leftRoot,
                    leftPath)
                && ExactPropertyPath(
                    member,
                    comparison.Right,
                    rightRoot,
                    rightPath)
                || ExactPropertyPath(
                    member,
                    comparison.Right,
                    leftRoot,
                    leftPath)
                && ExactPropertyPath(
                    member,
                    comparison.Left,
                    rightRoot,
                    rightPath));

        private static bool IsExactDirectedBinaryComparison(
            AuthoredMember member,
            ExpressionSyntax expression,
            SyntaxKind comparisonKind,
            ISymbol leftRoot,
            string[] leftPath,
            ISymbol rightRoot,
            string[] rightPath) =>
            StripTransparentExpression(expression) is
                BinaryExpressionSyntax comparison
            && comparison.IsKind(comparisonKind)
            && ExactPropertyPath(
                member,
                comparison.Left,
                leftRoot,
                leftPath)
            && ExactPropertyPath(
                member,
                comparison.Right,
                rightRoot,
                rightPath);

        private static bool IsExactNegatedOrdinalStringEquality(
            AuthoredMember member,
            ExpressionSyntax expression,
            ISymbol leftRoot,
            string[] leftPath,
            ISymbol rightRoot,
            string[] rightPath) =>
            StripTransparentExpression(expression) is
                PrefixUnaryExpressionSyntax negation
            && negation.IsKind(SyntaxKind.LogicalNotExpression)
            && StripTransparentExpression(negation.Operand) is
                InvocationExpressionSyntax invocation
            && member.Model.GetSymbolInfo(invocation).Symbol is IMethodSymbol method
            && method.Name == "Equals"
            && TypeKey(method.ContainingType) == "System.String"
            && invocation.ArgumentList.Arguments is
                [ArgumentSyntax left, ArgumentSyntax right, ArgumentSyntax ordinal]
            && ExactPropertyPath(
                member,
                left.Expression,
                leftRoot,
                leftPath)
            && ExactPropertyPath(
                member,
                right.Expression,
                rightRoot,
                rightPath)
            && ExactEnumMember(
                member,
                ordinal.Expression,
                "System.StringComparison",
                "Ordinal");

        private static bool HasExactEquality(
            AuthoredMember member,
            ISymbol leftRoot,
            string[] leftPath,
            ISymbol rightRoot,
            string[] rightPath) =>
            member.Syntax.DescendantNodesAndSelf()
                .OfType<ExpressionSyntax>()
                .Any(expression => IsExactEquality(
                    member,
                    expression,
                    leftRoot,
                    leftPath,
                    rightRoot,
                    rightPath));

        private static bool IsExactEquality(
            AuthoredMember member,
            ExpressionSyntax expression,
            ISymbol leftRoot,
            string[] leftPath,
            ISymbol rightRoot,
            string[] rightPath) =>
            StripTransparentExpression(expression) is
                BinaryExpressionSyntax comparison
            && comparison.IsKind(SyntaxKind.EqualsExpression)
            && (ExactPropertyPath(
                    member,
                    comparison.Left,
                    leftRoot,
                    leftPath)
                && ExactPropertyPath(
                    member,
                    comparison.Right,
                    rightRoot,
                    rightPath)
                || ExactPropertyPath(
                    member,
                    comparison.Right,
                    leftRoot,
                    leftPath)
                && ExactPropertyPath(
                    member,
                    comparison.Left,
                    rightRoot,
                    rightPath));

        private static bool HasExactOrdinalStringEquality(
            AuthoredMember member,
            ISymbol leftRoot,
            string[] leftPath,
            ISymbol rightRoot,
            string[] rightPath) =>
            member.Syntax.DescendantNodesAndSelf()
                .OfType<ExpressionSyntax>()
                .Any(expression => IsExactOrdinalStringEquality(
                    member,
                    expression,
                    leftRoot,
                    leftPath,
                    rightRoot,
                    rightPath));

        private static bool IsExactOrdinalStringEquality(
            AuthoredMember member,
            ExpressionSyntax expression,
            ISymbol leftRoot,
            string[] leftPath,
            ISymbol rightRoot,
            string[] rightPath) =>
            StripTransparentExpression(expression) is
                InvocationExpressionSyntax invocation
            && member.Model.GetSymbolInfo(invocation).Symbol is IMethodSymbol method
            && method.Name == "Equals"
            && TypeKey(method.ContainingType) == "System.String"
            && invocation.ArgumentList.Arguments is
                [ArgumentSyntax left, ArgumentSyntax right, ArgumentSyntax ordinal]
            && ExactPropertyPath(
                member,
                left.Expression,
                leftRoot,
                leftPath)
            && ExactPropertyPath(
                member,
                right.Expression,
                rightRoot,
                rightPath)
            && ExactEnumMember(
                member,
                ordinal.Expression,
                "System.StringComparison",
                "Ordinal");

        private static bool ExactPropertyPath(
            AuthoredMember member,
            ExpressionSyntax expression,
            ISymbol root,
            params string[] path)
        {
            expression = StripTransparentExpression(expression);

            for (int index = path.Length - 1; index >= 0; index--)
            {
                if (expression is not MemberAccessExpressionSyntax access
                    || access.Name.Identifier.ValueText != path[index])
                {
                    return false;
                }

                expression = StripTransparentExpression(access.Expression);
            }

            return SymbolEqualityComparer.Default.Equals(
                member.Model.GetSymbolInfo(expression).Symbol,
                root);
        }

        private static bool ExactEnumMember(
            AuthoredMember member,
            ExpressionSyntax expression,
            string containingType,
            string name) =>
            member.Model.GetSymbolInfo(StripTransparentExpression(expression)).Symbol is
                IFieldSymbol field
            && field.Name == name
            && TypeKey(field.ContainingType) == containingType;

        private TraversalEvidence TraverseOwnerRecoveryTarget(
            AuthoredMember caller,
            InvocationExpressionSyntax call,
            string rootType,
            string operationId,
            HashSet<TraversalStateIdentity> active,
            bool lifecycle,
            RecoveryHandlerTarget target,
            RecoveryTuple tuple,
            string pathSegment,
            string handlerMethod)
        {
            IParameterSymbol? operation = target.Member.Symbol.Parameters
                .SingleOrDefault(parameter => TypeKey(parameter.Type)
                    == "RetroDownfall.Arcanum.Core.Operations.LongRunningOperation");

            if (operation is null)
            {
                diagnostics.Add(new(
                    "HOSTED_RECOVERY_HANDLER_UNPROVEN",
                    Location(target.Member.Syntax),
                    TypeKey(target.Member.Symbol.ContainingType)
                        + "; "
                        + handlerMethod
                        + " must receive one exact durable operation."));

                return TraversalEvidence.Inconclusive;
            }

            AuthoredMember bound = BindAdmissionArguments(
                caller,
                call,
                target.Member);

            Dictionary<ISymbol, RecoveryTuple> bindings =
                bound.RecoveryBindings is null
                    ? new(SymbolEqualityComparer.Default)
                    : new(bound.RecoveryBindings, SymbolEqualityComparer.Default);

            bindings[operation] = tuple;

            bound = bound with
            {
                RecoveryBindings = bindings,
                RecoveryContext = tuple,
            };

            string tupleOperation = operationId
                + "/"
                + pathSegment
                + "@"
                + Uri.EscapeDataString(tuple.Kind)
                + ":"
                + tuple.CheckpointVersion
                + "/call@"
                + Location(call);

            ownerRecoveryAssociations.Add((
                RootOperation(operationId),
                tuple.Kind,
                tuple.CheckpointVersion));

            return Traverse(
                bound,
                rootType,
                tupleOperation,
                active,
                lifecycle,
                completionOwned: true);
        }

        private bool RecoveryNodeMayExecute(
            AuthoredMember member,
            SyntaxNode node,
            RecoveryConditionEvaluationContext? evaluationContext = null,
            bool includeOrdinaryStorageObservation = true)
        {
            // This lifetime query must not use ordinary observations to prove
            // itself, including through generic local/helper Boolean evaluation.
            // Treat all its control flow as reachable instead.
            if (!includeOrdinaryStorageObservation && member.ReadinessSource is null
                && member.OrdinaryScopedHolder is not null) return true;

            if (evaluationContext is not null)
            {
                evaluationContext.FeasibilityQueries++;
            }

            bool hasRecoveryBindings = member.RecoveryBindings is { Count: > 0 };

            bool hasValueBindings = member.ValueBindings is { Count: > 0 } || member.ReadinessSource is not null
                || member.OrdinaryScopedHolder is not null;

            if (!hasRecoveryBindings && !hasValueBindings)
            {
                return true;
            }

            if (evaluationContext is not null)
            {
                if (evaluationContext.Plan is null
                    && !evaluationContext.PlanBuildInProgress)
                {
                    evaluationContext.PlanBuildInProgress = true;

                    try
                    {
                        evaluationContext.Plan = RecoveryReachabilityPlanFor(
                            member,
                            evaluationContext,
                            hasRecoveryBindings);
                    }
                    finally
                    {
                        evaluationContext.PlanBuildInProgress = false;
                    }
                }

                if (evaluationContext.Plan is { } plan)
                {
                    return !RecoveryReachabilityPlanContains(
                        plan.UnreachableSpans,
                        node,
                        evaluationContext);
                }
            }

            foreach (SyntaxNode ancestor in node.Ancestors()
                .TakeWhile(ancestor => ancestor != member.Syntax))
            {
                if (ancestor is IfStatementSyntax conditional)
                {
                    bool? value = RecoveryConditionBoolean(
                        member,
                        conditional.Condition,
                        evaluationContext,
                        hasRecoveryBindings);

                    if (value == true && conditional.Else?.Statement.Span.Contains(node.Span) == true
                        || value == false && conditional.Statement.Span.Contains(node.Span))
                    {
                        return false;
                    }
                }
                else if (ancestor is ConditionalExpressionSyntax choice)
                {
                    bool? value = RecoveryConditionBoolean(
                        member,
                        choice.Condition,
                        evaluationContext,
                        hasRecoveryBindings);

                    if (value == true && choice.WhenFalse.Span.Contains(node.Span)
                        || value == false && choice.WhenTrue.Span.Contains(node.Span))
                    {
                        return false;
                    }
                }
                else if (ancestor is SwitchExpressionArmSyntax arm
                    && arm.Parent is SwitchExpressionSyntax selection
                    && EvaluateRecoveryCondition(
                        member,
                        selection.GoverningExpression,
                        evaluationContext) is
                    {
                        IsKnown: true,
                    } governing
                    && RecoveryPatternMatches(
                        member,
                        arm.Pattern,
                        governing.Value) is false)
                {
                    return false;
                }
                else if (ancestor is BinaryExpressionSyntax binary
                    && binary.Right.Span.Contains(node.Span)
                    && RecoveryConditionBoolean(
                        member,
                        binary.Left,
                        evaluationContext,
                        hasRecoveryBindings) is { } left
                    && (binary.IsKind(SyntaxKind.LogicalAndExpression) && !left
                        || binary.IsKind(SyntaxKind.LogicalOrExpression) && left))
                {
                    return false;
                }
            }

            foreach (BlockSyntax block in node.Ancestors()
                .OfType<BlockSyntax>()
                .TakeWhile(block => block != member.Syntax))
            {
                StatementSyntax? path = block.Statements
                    .FirstOrDefault(statement => statement.Span.Contains(node.Span));

                if (path is null)
                {
                    continue;
                }

                foreach (IfStatementSyntax guard in block.Statements
                    .TakeWhile(statement => statement != path)
                    .OfType<IfStatementSyntax>())
                {
                    bool? value = RecoveryConditionBoolean(
                        member,
                        guard.Condition,
                        evaluationContext,
                        hasRecoveryBindings);

                    if (value == true && DefinitelyTerminates(guard.Statement)
                        || value == false
                            && guard.Else is { } alternate
                            && DefinitelyTerminates(alternate.Statement))
                    {
                        return false;
                    }
                }
            }

            return true;
        }

        private RecoveryReachabilityPlan RecoveryReachabilityPlanFor(
            AuthoredMember member,
            RecoveryConditionEvaluationContext context,
            bool hasRecoveryBindings)
        {
            int? environmentToken = evaluationEnvironmentTokens.TryGetValue(
                    member,
                    out int knownToken)
                ? knownToken
                : TryRegisterEvaluationEnvironmentToken(member);

            RecoveryReachabilityPlanIdentity? identity = environmentToken is int token
                ? new(MemberIdentity(member), token)
                : null;

            if (identity is { } exact
                && recoveryReachabilityPlans.TryGetValue(
                    exact,
                    out RecoveryReachabilityPlan? cached))
            {
                return cached;
            }

            RecoveryReachabilityPlan plan = BuildRecoveryReachabilityPlan(
                member,
                context,
                hasRecoveryBindings);

            if (identity is { } cacheable)
            {
                recoveryReachabilityPlans.TryAdd(cacheable, plan);
            }

            return plan;
        }

        private RecoveryReachabilityPlan BuildRecoveryReachabilityPlan(
            AuthoredMember member,
            RecoveryConditionEvaluationContext context,
            bool hasRecoveryBindings)
        {
            context.PlanBuilds++;

            HashSet<SyntaxNode> unreachableRoots =
                new(ReferenceEqualityComparer.Instance);

            void Exclude(SyntaxNode root)
            {
                if (!unreachableRoots.Add(root))
                {
                    return;
                }

                context.UnreachableSpans.Add(new(
                    root.SpanStart,
                    root.Span.End));
            }

            void Visit(SyntaxNode node)
            {
                context.StructuralInspections++;

                bool nestedCallable = node != member.Syntax
                    && (node is LocalFunctionStatementSyntax
                        or AnonymousFunctionExpressionSyntax);

                if (unreachableRoots.Contains(node)
                    || nestedCallable)
                {
                    return;
                }

                if (node is IfStatementSyntax conditional)
                {
                    bool? value = RecoveryConditionBoolean(
                        member,
                        conditional.Condition,
                        context,
                        hasRecoveryBindings);

                    if (value == true && conditional.Else is { } alternate)
                    {
                        Exclude(alternate.Statement);
                    }
                    else if (value == false)
                    {
                        Exclude(conditional.Statement);
                    }

                    bool chosenBranchTerminates = value == true
                        && DefinitelyTerminates(conditional.Statement)
                        || value == false
                            && conditional.Else is { } chosenAlternate
                            && DefinitelyTerminates(chosenAlternate.Statement);

                    if (chosenBranchTerminates
                        && conditional.Parent is BlockSyntax block)
                    {
                        int guardIndex = block.Statements.IndexOf(conditional);

                        for (int index = guardIndex + 1;
                            guardIndex >= 0 && index < block.Statements.Count;
                            index++)
                        {
                            Exclude(block.Statements[index]);
                        }
                    }
                }
                else if (node is ConditionalExpressionSyntax choice)
                {
                    bool? value = RecoveryConditionBoolean(
                        member,
                        choice.Condition,
                        context,
                        hasRecoveryBindings);

                    if (value == true)
                    {
                        Exclude(choice.WhenFalse);
                    }
                    else if (value == false)
                    {
                        Exclude(choice.WhenTrue);
                    }
                }
                else if (node is SwitchExpressionSyntax selection
                    && EvaluateRecoveryCondition(
                        member,
                        selection.GoverningExpression,
                        context) is
                    {
                        IsKnown: true,
                    } governing)
                {
                    foreach (SwitchExpressionArmSyntax arm in selection.Arms)
                    {
                        if (RecoveryPatternMatches(
                            member,
                            arm.Pattern,
                            governing.Value) is not false)
                        {
                            continue;
                        }

                        Exclude(arm.Pattern);

                        if (arm.WhenClause is { } whenClause)
                        {
                            Exclude(whenClause);
                        }

                        Exclude(arm.Expression);
                    }
                }
                else if (node is BinaryExpressionSyntax binary
                    && RecoveryConditionBoolean(
                        member,
                        binary.Left,
                        context,
                        hasRecoveryBindings) is { } left
                    && (binary.IsKind(SyntaxKind.LogicalAndExpression) && !left
                        || binary.IsKind(SyntaxKind.LogicalOrExpression) && left))
                {
                    Exclude(binary.Right);
                }

                foreach (SyntaxNode child in node.ChildNodes())
                {
                    Visit(child);
                }
            }

            Visit(member.Syntax);

            NormalizeRecoveryUnreachableSpans(context.UnreachableSpans);

            context.UnreachableIntervals = context.UnreachableSpans.Count;

            RecoveryReachabilityPlan plan = new([.. context.UnreachableSpans]);

            if (auditRecoveryReachabilityParity)
            {
                AuditRecoveryReachabilityParity(member, plan, context);
            }

            return plan;
        }

        private static void NormalizeRecoveryUnreachableSpans(
            List<HostedProducerRecoverySpan> spans)
        {
            spans.Sort(static (left, right) =>
            {
                int start = left.Start.CompareTo(right.Start);

                return start != 0
                    ? start
                    : left.End.CompareTo(right.End);
            });

            if (spans.Count <= 1)
            {
                return;
            }

            List<HostedProducerRecoverySpan> disjoint = [];

            foreach (HostedProducerRecoverySpan span in spans)
            {
                if (disjoint.Count == 0
                    || span.Start >= disjoint[^1].End)
                {
                    disjoint.Add(span);

                    continue;
                }

                if (span.End > disjoint[^1].End)
                {
                    disjoint[^1] = disjoint[^1] with
                    {
                        End = span.End,
                    };
                }
            }

            spans.Clear();

            spans.AddRange(disjoint);
        }

        internal static HostedProducerRecoverySpanProbe ProbeRecoveryReachabilitySpans(
            IReadOnlyList<HostedProducerRecoverySpan> intervals,
            IReadOnlyList<HostedProducerRecoverySpan> nodes)
        {
            List<HostedProducerRecoverySpan> normalized = [.. intervals];

            NormalizeRecoveryUnreachableSpans(normalized);

            int comparisons = 0;

            bool[] nodeMayExecute = nodes
                .Select(node => !RecoveryReachabilityPlanContains(
                    normalized,
                    node.Start,
                    node.End,
                    context: null,
                    onComparison: () => comparisons++))
                .ToArray();

            return new(normalized, nodeMayExecute, comparisons);
        }

        private void AuditRecoveryReachabilityParity(
            AuthoredMember member,
            RecoveryReachabilityPlan plan,
            RecoveryConditionEvaluationContext context)
        {
            foreach (SyntaxNode node in member.Syntax.DescendantNodesAndSelf(candidate =>
                    candidate == member.Syntax
                    || candidate is not LocalFunctionStatementSyntax
                        and not AnonymousFunctionExpressionSyntax))
            {
                bool planned = !RecoveryReachabilityPlanContains(
                    plan.UnreachableSpans,
                    node,
                    context: null);

                bool fallback = RecoveryNodeMayExecute(member, node);

                context.ParityComparisons++;

                if (planned == fallback)
                {
                    continue;
                }

                context.ParityMismatches++;

                diagnostics.Add(new(
                    "HOSTED_RECOVERY_REACHABILITY_PARITY_MISMATCH",
                    MethodKey(member.Symbol) + "@" + Location(node),
                    "Planned="
                        + planned
                        + "; fallback="
                        + fallback
                        + "; syntax="
                        + node.Kind()
                        + "."));
            }
        }

        private KnownValue EvaluateRecoveryCondition(
            AuthoredMember member,
            ExpressionSyntax expression,
            RecoveryConditionEvaluationContext? context)
        {
            if (context is not null
                && context.Values.TryGetValue(
                    expression,
                    out KnownValue cached))
            {
                return cached;
            }

            if (context is not null)
            {
                context.EvaluationCount++;
            }

            KnownValue value = RecoveryValue(member, expression, [], context);

            if (context is not null)
            {
                context.Values.Add(expression, value);
            }

            return value;
        }

        private bool? RecoveryConditionBoolean(
            AuthoredMember member,
            ExpressionSyntax expression,
            RecoveryConditionEvaluationContext? context,
            bool hasRecoveryBindings)
        {
            if (ReadinessConditionBoolean(member, expression) is { } readinessValue) return readinessValue;

            if (!hasRecoveryBindings
                && !expression.DescendantNodesAndSelf()
                    .OfType<IdentifierNameSyntax>()
                    .Any(reference => member.Model.GetSymbolInfo(reference).Symbol is { } symbol
                        && member.ValueBindings?.ContainsKey(symbol) == true))
            {
                return null;
            }

            return EvaluateRecoveryCondition(member, expression, context).Value
                is bool value
                ? value
                : null;
        }

        private static bool RecoveryReachabilityPlanContains(
            IReadOnlyList<HostedProducerRecoverySpan> spans,
            SyntaxNode node,
            RecoveryConditionEvaluationContext? context) =>
            RecoveryReachabilityPlanContains(
                spans,
                node.SpanStart,
                node.Span.End,
                context,
                onComparison: null);

        private static bool RecoveryReachabilityPlanContains(
            IReadOnlyList<HostedProducerRecoverySpan> spans,
            int nodeStart,
            int nodeEnd,
            RecoveryConditionEvaluationContext? context,
            Action? onComparison)
        {
            int lower = 0;

            int upper = spans.Count - 1;

            while (lower <= upper)
            {
                if (context is not null)
                {
                    context.ProbeComparisons++;
                }

                onComparison?.Invoke();

                int middle = lower + (upper - lower) / 2;

                HostedProducerRecoverySpan span = spans[middle];

                if (nodeStart < span.Start)
                {
                    upper = middle - 1;
                }
                else if (nodeStart >= span.End)
                {
                    lower = middle + 1;
                }
                else
                {
                    return nodeEnd <= span.End;
                }
            }

            return false;
        }

        private KnownValue RecoveryValue(
            AuthoredMember member,
            ExpressionSyntax expression,
            HashSet<GraphMemberIdentity> path,
            RecoveryConditionEvaluationContext? context = null)
        {
            string metricMember = MethodKey(member.Symbol);

            totalRecoveryValueQueries[metricMember] =
                totalRecoveryValueQueries.GetValueOrDefault(metricMember) + 1;

            expression = StripRecoveryTransparentSyntax(expression);

            Optional<object?> constant = member.Model.GetConstantValue(expression);

            if (constant.HasValue)
            {
                return new(true, constant.Value);
            }

            if (expression is CastExpressionSyntax cast)
            {
                return RecoveryCastPreservesKnownValue(member, cast)
                    ? RecoveryValue(member, cast.Expression, path, context)
                    : default;
            }

            if (member.Model.GetSymbolInfo(expression).Symbol is IFieldSymbol
                {
                    HasConstantValue: true,
                } constantField)
            {
                return new(true, constantField.ConstantValue);
            }

            if (expression is PrefixUnaryExpressionSyntax negation
                && negation.IsKind(SyntaxKind.LogicalNotExpression)
                && RecoveryOperationUsesOnlyBuiltInSemantics(
                    member,
                    negation)
                && RecoveryValue(member, negation.Operand, path, context) is
                {
                    IsKnown: true,
                    Value: bool operand,
                })
            {
                return new(true, !operand);
            }

            if (expression is BinaryExpressionSyntax enumPattern
                && enumPattern.IsKind(SyntaxKind.IsExpression)
                && member.Model.GetOperation(enumPattern) is IIsPatternOperation
                {
                    Value.Syntax: ExpressionSyntax inputExpression,
                    Pattern: IConstantPatternOperation constantPattern,
                }
                && constantPattern.Value.Syntax is ExpressionSyntax expectedExpression
                && RecoveryValue(member, inputExpression, path, context) is
                {
                    IsKnown: true,
                } enumInput
                && RecoveryValue(member, expectedExpression, path, context) is
                {
                    IsKnown: true,
                } enumExpected
                && RecoveryConstantPatternMayUseKnownValues(
                    constantPattern,
                    enumInput.Value,
                    enumExpected.Value))
            {
                return new(true, Equals(enumInput.Value, enumExpected.Value));
            }

            if (expression is BinaryExpressionSyntax binary
                && RecoveryOperationUsesOnlyBuiltInSemantics(
                    member,
                    binary))
            {
                KnownValue left = RecoveryValue(member, binary.Left, path, context);

                if (binary.IsKind(SyntaxKind.LogicalAndExpression)
                    && left is { IsKnown: true, Value: false }
                    || binary.IsKind(SyntaxKind.LogicalOrExpression)
                    && left is { IsKnown: true, Value: true })
                {
                    return left;
                }

                KnownValue right = RecoveryValue(member, binary.Right, path, context);

                if (binary.IsKind(SyntaxKind.LogicalAndExpression)
                    && right is { IsKnown: true, Value: false }
                    || binary.IsKind(SyntaxKind.LogicalOrExpression)
                    && right is { IsKnown: true, Value: true })
                {
                    return right;
                }

                if (left.IsKnown && right.IsKnown)
                {
                    if (binary.IsKind(SyntaxKind.LogicalAndExpression)
                        && left.Value is bool leftAnd
                        && right.Value is bool rightAnd)
                    {
                        return new(true, leftAnd && rightAnd);
                    }

                    if (binary.IsKind(SyntaxKind.LogicalOrExpression)
                        && left.Value is bool leftOr
                        && right.Value is bool rightOr)
                    {
                        return new(true, leftOr || rightOr);
                    }

                    if ((binary.IsKind(SyntaxKind.EqualsExpression)
                            || binary.IsKind(SyntaxKind.NotEqualsExpression))
                        && RecoveryEqualityMayUseKnownValues(
                            member,
                            binary,
                            left.Value,
                            right.Value))
                    {
                        bool equal = Equals(left.Value, right.Value);

                        return new(
                            true,
                            binary.IsKind(SyntaxKind.EqualsExpression)
                                ? equal
                                : !equal);
                    }
                }
            }

            if (expression is IsPatternExpressionSyntax pattern
                && AuthenticatedOwnerEvidenceTypeTest(member, pattern) is
                    bool authenticatedEvidence)
            {
                return new(true, authenticatedEvidence);
            }

            if (expression is IsPatternExpressionSyntax recoveryPattern
                && RecoveryValue(member, recoveryPattern.Expression, path, context) is
                {
                    IsKnown: true,
                } input
                && RecoveryPatternMatches(
                    member,
                    recoveryPattern.Pattern,
                    input.Value) is bool patternMatches)
            {
                return new(true, patternMatches);
            }

            if (expression is ConditionalExpressionSyntax conditional
                && RecoveryValue(member, conditional.Condition, path, context) is
                {
                    IsKnown: true,
                    Value: bool condition,
                })
            {
                return RecoveryValue(
                    member,
                    condition ? conditional.WhenTrue : conditional.WhenFalse,
                    path,
                    context);
            }

            if (expression is SwitchExpressionSyntax selection
                && RecoveryValue(member, selection.GoverningExpression, path, context) is
                {
                    IsKnown: true,
                } governing)
            {
                foreach (SwitchExpressionArmSyntax arm in selection.Arms)
                {
                    if (RecoveryPatternMatches(
                            member,
                            arm.Pattern,
                            governing.Value) is not bool matches)
                    {
                        return default;
                    }

                    if (!matches)
                    {
                        continue;
                    }

                    if (arm.WhenClause is null)
                    {
                        return RecoveryValue(member, arm.Expression, path, context);
                    }

                    if (RecoveryValue(
                            member,
                            arm.WhenClause.Condition,
                            path,
                            context) is not
                            {
                                IsKnown: true,
                                Value: bool whenClause,
                            })
                    {
                        return default;
                    }

                    if (whenClause)
                    {
                        return RecoveryValue(member, arm.Expression, path, context);
                    }
                }

                return default;
            }

            if (expression is MemberAccessExpressionSyntax access
                && BoundRecoveryTuple(member, access.Expression, []) is { } recovery)
            {
                return access.Name.Identifier.ValueText switch
                {
                    "Kind" => new(true, recovery.Kind),
                    "CheckpointVersion" => new(true, recovery.CheckpointVersion),
                    _ => default,
                };
            }

            if (expression is InvocationExpressionSyntax call
                && member.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method)
            {
                if (IsExactOrdinalStringEquals(method))
                {
                    ExpressionSyntax[] values = AdmissionArguments(member, call)
                        .Select(static argument => argument.Expression)
                        .ToArray();

                    if (values is [ExpressionSyntax first, ExpressionSyntax second])
                    {
                        KnownValue left = RecoveryValue(member, first, path, context);
                        KnownValue right = RecoveryValue(member, second, path, context);

                        if (left.IsKnown
                            && right.IsKnown
                            && left.Value is null or string
                            && right.Value is null or string)
                        {
                            return new(
                                true,
                                string.Equals(
                                    (string?)left.Value,
                                    (string?)right.Value,
                                    StringComparison.Ordinal));
                        }
                    }
                }

                if (ResolveInvocationTarget(method, member, call) is { } target)
                {
                    AuthoredMember bound = BindAdmissionArguments(member, call, target);

                    GraphMemberIdentity identity = MemberIdentity(bound);

                    if (!path.Add(identity))
                    {
                        return default;
                    }

                    try
                    {
                        ExpressionSyntax[] returns = bound.Syntax switch
                        {
                            MethodDeclarationSyntax { ExpressionBody.Expression: { } result } =>
                                [result],
                            MethodDeclarationSyntax { Body: { } body } =>
                                [.. body.DescendantNodes(node => node is not AnonymousFunctionExpressionSyntax
                                        and not LocalFunctionStatementSyntax)
                                    .OfType<ReturnStatementSyntax>()
                                    .Select(static statement => statement.Expression)
                                    .OfType<ExpressionSyntax>()],
                            LocalFunctionStatementSyntax { ExpressionBody.Expression: { } result } =>
                                [result],
                            LocalFunctionStatementSyntax { Body: { } body } =>
                                [.. body.DescendantNodes(node => node is not AnonymousFunctionExpressionSyntax
                                        and not LocalFunctionStatementSyntax)
                                    .OfType<ReturnStatementSyntax>()
                                    .Select(static statement => statement.Expression)
                                    .OfType<ExpressionSyntax>()],
                            _ => [],
                        };

                        KnownValue[] returned = returns
                            .Where(result => RecoveryNodeMayExecute(bound, result))
                            .Select(result => RecoveryValue(bound, result, path))
                            .ToArray();

                        if (returned.Length != 0
                            && returned.All(static result => result.IsKnown)
                            && returned.Select(static result => result.Value)
                                .Distinct()
                                .Count() == 1)
                        {
                            return returned[0];
                        }
                    }
                    finally
                    {
                        path.Remove(identity);
                    }
                }
            }

            ISymbol? symbol = member.Model.GetSymbolInfo(expression).Symbol;

            if (symbol is IParameterSymbol
                && TryResolveStableBoundValueSource(
                    member,
                    expression,
                    out BoundValueSource? binding)
                && binding is not null
                && !path.Contains(MemberIdentity(binding.Caller)))
            {
                return RecoveryValue(
                    binding.Caller,
                    binding.Expression,
                    path);
            }

            if (symbol is IPropertySymbol { IsStatic: false } recordProperty
                && recordProperty.ContainingType.IsRecord && recordProperty.ContainingType.IsSealed
                && SymbolEqualityComparer.Default.Equals(recordProperty.ContainingType, member.Symbol.ContainingType)
                && HasExactAutoInitAssignmentSemantics(recordProperty)
                && TryResolveStableBoundValueSource(member, expression, out BoundValueSource? propertySource)
                && propertySource is { Expression: LiteralExpressionSyntax recordLiteral }
                && (recordLiteral.Parent is ArgumentSyntax
                    || recordLiteral.Parent is AssignmentExpressionSyntax literalAssignment && literalAssignment.Right == recordLiteral)
                && SymbolEqualityComparer.Default.Equals(propertySource.Caller.Model.GetTypeInfo(recordLiteral).Type, recordProperty.Type)
                && !path.Contains(MemberIdentity(propertySource.Caller)))
            {
                return RecoveryValue(propertySource.Caller, propertySource.Expression, path, context);
            }

            if (symbol is IPropertySymbol property
                && SymbolEqualityComparer.Default.Equals(
                    property.ContainingType,
                    member.Symbol.ContainingType)
                && ConstantRecoveryHandlerProperty(member, property.Name) is { } propertyValue)
            {
                return new(true, propertyValue);
            }

            if (symbol is ILocalSymbol local
                && local.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax() is
                    VariableDeclaratorSyntax { Initializer.Value: { } initializer } declarator)
            {
                var localKey = (MemberIdentity(member), initializer.SpanStart);

                if (!activeRecoveryLocals.Add(localKey))
                {
                    return default;
                }

                try
                {
                    List<ExpressionSyntax> values = [initializer];

                    // The initializer and the plain assignments before the use are the local's values only when no other write
                    // can reach the use; a local written through a reference, by a compound assignment or around a loop is unknown.
                    if (!RecoveryLocalAssignments(
                            member,
                            local,
                            declarator,
                            (SyntaxNode?)initializer.Ancestors().OfType<BlockSyntax>().FirstOrDefault() ?? initializer.SyntaxTree.GetRoot(),
                            expression,
                            out IReadOnlyList<AssignmentExpressionSyntax> assignments))
                    {
                        return default;
                    }

                    values.AddRange(assignments
                        .Where(assignment => assignment.SpanStart < expression.SpanStart
                            && RecoveryNodeMayExecute(
                                member,
                                assignment,
                                context))
                        .Select(static assignment => assignment.Right));

                    RecoveryLocalValueIdentity? valueIdentity = context is null
                        ? null
                        : new(
                            initializer.SpanStart,
                            string.Join(
                                ",",
                                values.Select(static value =>
                                    value.SpanStart.ToString(CultureInfo.InvariantCulture)
                                    + ":"
                                    + value.Span.Length.ToString(CultureInfo.InvariantCulture))));

                    if (valueIdentity is { } cacheKey
                        && context!.LocalValues.TryGetValue(
                            cacheKey,
                            out KnownValue cached))
                    {
                        return cached;
                    }

                    KnownValue[] candidates = values
                        .Select(value => RecoveryValue(member, value, path, context))
                        .ToArray();

                    KnownValue result = candidates.Length != 0
                        && candidates.All(static candidate => candidate.IsKnown)
                        && candidates.Select(static candidate => candidate.Value)
                            .Distinct()
                            .Count() == 1
                        ? candidates[0]
                        : default;

                    if (result.IsKnown && valueIdentity is { } knownKey)
                    {
                        context!.LocalValues.TryAdd(knownKey, result);
                    }

                    return result;
                }
                finally
                {
                    _ = activeRecoveryLocals.Remove(localKey);
                }
            }

            return default;
        }

        private static bool IsExactOrdinalStringEquals(IMethodSymbol method) =>
            method.IsStatic
            && method.Arity == 0
            && TypeKey(method.ReturnType) == "System.Boolean"
            && HasExactParameterTypes(
                method,
                "System.String",
                "System.String")
            && IsExactFrameworkMethod(
                method,
                "System.String",
                "Equals",
                "System.Private.CoreLib");

        private static ExpressionSyntax StripRecoveryTransparentSyntax(
            ExpressionSyntax expression)
        {
            while (true)
            {
                switch (expression)
                {
                    case ParenthesizedExpressionSyntax parentheses:
                        expression = parentheses.Expression;

                        continue;
                    case PostfixUnaryExpressionSyntax suppression
                        when suppression.IsKind(
                            SyntaxKind.SuppressNullableWarningExpression):
                        expression = suppression.Operand;

                        continue;
                    default:
                        return expression;
                }
            }
        }

        private static bool RecoveryCastPreservesKnownValue(
            AuthoredMember member,
            CastExpressionSyntax cast)
        {
            if (member.Model.GetTypeInfo(cast.Type).Type is not { } targetType)
            {
                return false;
            }

            Conversion conversion = member.Model.ClassifyConversion(
                cast.Expression,
                targetType);

            return conversion.Exists
                && !conversion.IsUserDefined
                && !conversion.IsDynamic
                && (conversion.IsIdentity || conversion.IsReference)
                && RecoveryOperationUsesOnlyBuiltInSemantics(member, cast);
        }

        private static bool RecoveryOperationUsesOnlyBuiltInSemantics(
            AuthoredMember member,
            ExpressionSyntax expression)
        {
            if (member.Model.GetOperation(expression) is not { } operation)
            {
                return false;
            }

            bool IsBuiltIn(IOperation candidate)
            {
                if (candidate is IInvalidOperation
                    || candidate.Type?.TypeKind == TypeKind.Dynamic
                    || candidate is IConversionOperation conversion
                        && (!conversion.Conversion.Exists
                            || conversion.Conversion.MethodSymbol is not null)
                    || candidate is IBinaryOperation
                    {
                        OperatorMethod: not null,
                    }
                    || candidate is IUnaryOperation
                    {
                        OperatorMethod: not null,
                    })
                {
                    return false;
                }

                return candidate.ChildOperations.All(IsBuiltIn);
            }

            return IsBuiltIn(operation);
        }

        private AuthoredMember BindPropertyAccessorArguments(
            AuthoredMember caller,
            IPropertyReferenceOperation reference,
            IMethodSymbol accessor,
            AuthoredMember target,
            ExpressionSyntax? assignedValue)
        {
            List<(ExpressionSyntax Expression, IParameterSymbol? Parameter, RefKind RefKind)>
                arguments = [];

            foreach (IArgumentOperation argument in reference.Arguments)
            {
                if (argument.Parameter is not { } propertyParameter
                    || propertyParameter.Ordinal < 0
                    || propertyParameter.Ordinal >= accessor.Parameters.Length
                    || (argument.Syntax is ArgumentSyntax argumentSyntax
                            ? argumentSyntax.Expression
                            : argument.Value.Syntax) is not ExpressionSyntax expression)
                {
                    continue;
                }

                IParameterSymbol accessorParameter =
                    accessor.Parameters[propertyParameter.Ordinal];

                arguments.Add((
                    expression,
                    accessorParameter,
                    accessorParameter.RefKind));
            }

            if (accessor.MethodKind == MethodKind.PropertySet
                && assignedValue is not null
                && accessor.Parameters.LastOrDefault() is { } valueParameter
                && valueParameter.Ordinal >= reference.Arguments.Length)
            {
                arguments.Add((assignedValue, valueParameter, valueParameter.RefKind));
            }

            AuthoredMember bound = arguments.Count == 0
                ? target
                : BindArguments(caller, arguments, target);

            Dictionary<ISymbol, BoundValueSource> exactValues =
                bound.ValueBindings?.ToDictionary(
                    static pair => pair.Key,
                    static pair => pair.Value,
                    SymbolEqualityComparer.Default)
                ?? new(SymbolEqualityComparer.Default);

            foreach (var argument in arguments)
            {
                if (argument.Parameter is not { } parameter
                    || argument.RefKind != RefKind.None
                    || parameter.Ordinal < 0
                    || parameter.Ordinal >= target.Symbol.Parameters.Length
                    || !RecoveryEqualityTypeHasObjectEqualsSemantics(
                        parameter.Type))
                {
                    continue;
                }

                Conversion conversion = caller.Model.ClassifyConversion(
                    argument.Expression,
                    parameter.Type);

                if (!conversion.Exists
                    || !conversion.IsIdentity
                    || conversion.IsDynamic
                    || conversion.IsUserDefined
                    || !RecoveryValue(caller, argument.Expression, []).IsKnown)
                {
                    continue;
                }

                exactValues[target.Symbol.Parameters[parameter.Ordinal]] = new(
                    caller,
                    argument.Expression);
            }

            if (exactValues.Count == (bound.ValueBindings?.Count ?? 0))
            {
                return bound;
            }

            bound = bound with
            {
                ValueBindings = exactValues,
            };

            _ = TryRegisterEvaluationEnvironmentToken(bound);

            return bound;
        }

        private static (
            bool Reads,
            bool Writes,
            ExpressionSyntax? AssignedValue) PropertyAccessorModes(
                IPropertyReferenceOperation? reference,
                SyntaxNode syntax)
        {
            if (reference is null)
            {
                bool writes = syntax.Parent is AssignmentExpressionSyntax write
                        && write.Left == syntax
                    || syntax.Parent?.Kind() is
                        SyntaxKind.PreIncrementExpression
                        or SyntaxKind.PostIncrementExpression
                        or SyntaxKind.PreDecrementExpression
                        or SyntaxKind.PostDecrementExpression;

                bool reads = syntax.Parent is not AssignmentExpressionSyntax simple
                    || simple.Left != syntax
                    || !simple.IsKind(SyntaxKind.SimpleAssignmentExpression);

                ExpressionSyntax? assignedValue = syntax.Parent is
                    AssignmentExpressionSyntax
                {
                    Left: { } left,
                    Right: { } right,
                }
                    && left == syntax
                        ? right
                        : null;

                return (reads, writes, assignedValue);
            }

            for (IOperation? ancestor = reference.Parent;
                ancestor is not null;
                ancestor = ancestor.Parent)
            {
                if (ancestor is ICompoundAssignmentOperation compound
                    && ReferenceEquals(compound.Target, reference)
                    || ancestor is IIncrementOrDecrementOperation increment
                    && ReferenceEquals(increment.Target, reference))
                {
                    return RefReturnAccessorMode(
                        reference,
                        reads: true,
                        assignedValue: null);
                }

                if (ancestor is ICoalesceAssignmentOperation coalescing
                    && ReferenceEquals(coalescing.Target, reference))
                {
                    return RefReturnAccessorMode(
                        reference,
                        reads: true,
                        assignedValue:
                            coalescing.Value.Syntax as ExpressionSyntax);
                }

                if (ancestor is ISimpleAssignmentOperation assignment
                    && ReferenceEquals(assignment.Target, reference))
                {
                    return RefReturnAccessorMode(
                        reference,
                        reads: false,
                        ReferenceEquals(assignment.Target, reference)
                            && assignment.Value.Syntax is ExpressionSyntax value
                                ? value
                                : null);
                }

                if (ancestor is IDeconstructionAssignmentOperation deconstruction
                    && IsExactDeconstructionTargetLeaf(
                        deconstruction.Target,
                        reference))
                {
                    return RefReturnAccessorMode(
                        reference,
                        reads: false,
                        assignedValue: null);
                }
            }

            return (true, false, null);
        }

        private static (
            bool Reads,
            bool Writes,
            ExpressionSyntax? AssignedValue) RefReturnAccessorMode(
                IPropertyReferenceOperation reference,
                bool reads,
                ExpressionSyntax? assignedValue) =>
            reference.Property.SetMethod is null
                && reference.Property.GetMethod is not null
                && (reference.Property.ReturnsByRef
                    || reference.Property.ReturnsByRefReadonly)
                    ? (true, false, null)
                    : (reads, true, assignedValue);

        private static bool IsExactDeconstructionTargetLeaf(
            IOperation target,
            IPropertyReferenceOperation reference)
        {
            IOperation? current = reference;

            while (!ReferenceEquals(current, target))
            {
                current = current?.Parent switch
                {
                    ITupleOperation tuple => tuple,
                    IParenthesizedOperation parenthesized => parenthesized,
                    IConversionOperation
                    {
                        IsImplicit: true,
                        Conversion.IsIdentity: true,
                    } conversion => conversion,
                    _ => null,
                };

                if (current is null)
                {
                    return false;
                }
            }

            return true;
        }

        private bool? AuthenticatedOwnerEvidenceTypeTest(
            AuthoredMember member,
            IsPatternExpressionSyntax expression)
        {
            if (member.Model.GetSymbolInfo(expression.Expression).Symbol is not
                    IParameterSymbol evidence
                || !IsExactAuthoredProtocolType(
                    evidence.Type,
                    "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningRecoveryOwnerEvidence",
                    member.Model.Compilation)
                || member.ConcreteBindings?.TryGetValue(
                    evidence,
                    out ITypeSymbol? concreteEvidence) != true)
            {
                return null;
            }

            TypeSyntax? testedType = expression.Pattern switch
            {
                DeclarationPatternSyntax declaration => declaration.Type,
                TypePatternSyntax type => type.Type,
                RecursivePatternSyntax recursive
                    when RecoveryRecursivePatternHasNoSubpatterns(recursive) =>
                    recursive.Type,
                _ => null,
            };

            if (testedType is null
                || member.Model.GetTypeInfo(testedType).Type is not { } patternType
                || !IsExactAuthoredProtocolType(
                    patternType,
                    "RetroDownfall.Arcanum.Infrastructure.GrimoireTransitions.AuthenticatedJournalRecoveryOwnerEvidence",
                    member.Model.Compilation))
            {
                return null;
            }

            return SymbolEqualityComparer.Default.Equals(
                concreteEvidence,
                patternType);
        }

        private bool? RecoveryPatternMatches(
            AuthoredMember member,
            PatternSyntax pattern,
            object? value)
        {
            if (pattern is DiscardPatternSyntax or VarPatternSyntax)
            {
                return true;
            }

            // A null test of a work lease the traversal knows to be the null constant. Only the lease protocol interface has this
            // rule: it declares no operators, so `is null` is the reference test and the null constant matches it.
            if (value is null
                && pattern is ConstantPatternSyntax { Expression: LiteralExpressionSyntax { RawKind: (int)SyntaxKind.NullLiteralExpression } } nullTest
                && member.Model.GetOperation(nullTest) is IConstantPatternOperation { InputType: { } leaseType }
                && TypeKey(leaseType) == "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease")
            {
                return true;
            }

            if (pattern is ConstantPatternSyntax constant
                && RecoveryValue(member, constant.Expression, []) is
                {
                    IsKnown: true,
                } expected
                && RecoveryConstantPatternMayUseKnownValues(
                    member,
                    constant,
                    value,
                    expected.Value))
            {
                return Equals(value, expected.Value);
            }

            if (pattern is UnaryPatternSyntax unary
                && unary.IsKind(SyntaxKind.NotPattern))
            {
                return RecoveryPatternMatches(
                        member,
                        unary.Pattern,
                        value) is bool nested
                    ? !nested
                    : null;
            }

            if (pattern is BinaryPatternSyntax binary
                && binary.Kind() is SyntaxKind.OrPattern
                    or SyntaxKind.AndPattern)
            {
                bool? left = RecoveryPatternMatches(
                    member,
                    binary.Left,
                    value);

                bool? right = RecoveryPatternMatches(
                    member,
                    binary.Right,
                    value);

                return left is bool exactLeft && right is bool exactRight
                    ? binary.IsKind(SyntaxKind.OrPattern)
                        ? exactLeft || exactRight
                        : exactLeft && exactRight
                    : null;
            }

            if (pattern is RecursivePatternSyntax recursive
                && recursive.Type is null
                && RecoveryRecursivePatternHasNoSubpatterns(recursive))
            {
                return value is not null;
            }

            return null;
        }

        private static bool RecoveryEqualityMayUseKnownValues(
            AuthoredMember member,
            BinaryExpressionSyntax expression,
            object? leftValue,
            object? rightValue)
        {
            if (member.Model.GetOperation(expression) is not IBinaryOperation operation
                || operation.OperatorMethod is not null
                || operation.IsLifted
                || !RecoveryOperationUsesOnlyIdentityConversions(operation.LeftOperand)
                || !RecoveryOperationUsesOnlyIdentityConversions(operation.RightOperand)
                || operation.LeftOperand.Type is not { } leftType
                || operation.RightOperand.Type is not { } rightType
                || !SymbolEqualityComparer.Default.Equals(leftType, rightType)
                || !RecoveryEqualityTypeHasObjectEqualsSemantics(leftType))
            {
                return false;
            }

            return leftValue is not null
                && rightValue is not null
                && leftValue.GetType() == rightValue.GetType();
        }

        private static bool RecoveryConstantPatternMayUseKnownValues(
            AuthoredMember member,
            ConstantPatternSyntax pattern,
            object? inputValue,
            object? expectedValue)
        {
            return member.Model.GetOperation(pattern) is
                    IConstantPatternOperation operation
                && RecoveryConstantPatternMayUseKnownValues(
                    operation,
                    inputValue,
                    expectedValue);
        }

        private static bool RecoveryConstantPatternMayUseKnownValues(
            IConstantPatternOperation operation,
            object? inputValue,
            object? expectedValue)
        {
            if (operation.InputType is not { } inputType
                || operation.Value.Type is not { } valueType
                || !SymbolEqualityComparer.Default.Equals(inputType, valueType)
                || !RecoveryOperationUsesOnlyIdentityConversions(operation.Value)
                || !RecoveryEqualityTypeHasObjectEqualsSemantics(inputType))
            {
                return false;
            }

            return inputValue is not null
                && expectedValue is not null
                && inputValue.GetType() == expectedValue.GetType();
        }

        private static bool RecoveryOperationUsesOnlyIdentityConversions(
            IOperation operation)
        {
            if (operation is IConversionOperation conversion
                && !conversion.Conversion.IsIdentity)
            {
                return false;
            }

            return operation.ChildOperations.All(
                RecoveryOperationUsesOnlyIdentityConversions);
        }

        private static bool RecoveryEqualityTypeHasObjectEqualsSemantics(
            ITypeSymbol type) =>
            type.TypeKind == TypeKind.Enum
            || type.SpecialType is
                SpecialType.System_Boolean
                or SpecialType.System_Char
                or SpecialType.System_SByte
                or SpecialType.System_Byte
                or SpecialType.System_Int16
                or SpecialType.System_UInt16
                or SpecialType.System_Int32
                or SpecialType.System_UInt32
                or SpecialType.System_Int64
                or SpecialType.System_UInt64
                or SpecialType.System_String;

        private static bool RecoveryRecursivePatternHasNoSubpatterns(
            RecursivePatternSyntax pattern) =>
            pattern.PositionalPatternClause is null
            && pattern.PropertyPatternClause is null or
            {
                Subpatterns.Count: 0,
            };

        private static bool DefinitelyTerminates(StatementSyntax statement) =>
            statement switch
            {
                ReturnStatementSyntax or ThrowStatementSyntax => true,
                BlockSyntax block when block.Statements.LastOrDefault() is { } last =>
                    DefinitelyTerminates(last),
                _ => false,
            };

        private static bool ExactFailureTermination(
            AuthoredMember member,
            StatementSyntax statement)
        {
            if (statement is BlockSyntax { Statements: [StatementSyntax only] })
            {
                return ExactFailureTermination(member, only);
            }

            if (statement is ThrowStatementSyntax)
            {
                return true;
            }

            if (statement is not ReturnStatementSyntax { Expression: { } returned })
            {
                return false;
            }

            ExpressionSyntax expression = StripTransparentExpression(returned);

            if (expression is BaseObjectCreationExpressionSyntax
                {
                    ArgumentList.Arguments:
                    [
                        ArgumentSyntax { Expression: { } failure },
                        ArgumentSyntax { Expression: { } value },
                    ],
                }
                && member.Model.GetConstantValue(failure) is
                { HasValue: true, Value: true }
                && StripTransparentExpression(value).IsKind(
                    SyntaxKind.NullLiteralExpression))
            {
                return true;
            }

            return expression is InvocationExpressionSyntax failureCall
                && member.Model.GetSymbolInfo(failureCall).Symbol is
                    IMethodSymbol
                {
                    Name: "Failure",
                    IsStatic: true,
                    ContainingType: { } resultType,
                }
                && TypeKey(resultType) is
                    "RetroDownfall.Arcanum.Core.Primitives.Result"
                    or "RetroDownfall.Arcanum.Core.Primitives.Result`1"
                && failureCall.ArgumentList.Arguments is
                    [
                        ArgumentSyntax
                    {
                        Expression: MemberAccessExpressionSyntax
                        {
                            Expression: InvocationExpressionSyntax
                            {
                                ArgumentList.Arguments.Count: 0,
                            } refusal,
                            Name.Identifier.ValueText: "Error",
                        },
                    },
                    ]
                && member.Model.GetSymbolInfo(refusal).Symbol is
                    IMethodSymbol
                {
                    Name: "Refusal",
                    IsStatic: true,
                    ContainingType: { } refusalType,
                }
                && TypeKey(refusalType)
                    == "RetroDownfall.Arcanum.Infrastructure.GrimoireTransitions.GrimoireOfflineTransitionStartupRecovery";
        }

        private static bool IsRecoveryDispositionTest(
            AuthoredMember member,
            ExpressionSyntax expression,
            string disposition,
            bool negated = false)
        {
            if (expression is ParenthesizedExpressionSyntax parentheses)
            {
                return IsRecoveryDispositionTest(
                    member,
                    parentheses.Expression,
                    disposition,
                    negated);
            }

            if (expression is BinaryExpressionSyntax disjunction
                && disjunction.IsKind(SyntaxKind.LogicalOrExpression))
            {
                return IsRecoveryDispositionTest(
                        member,
                        disjunction.Left,
                        disposition,
                        negated)
                    || IsRecoveryDispositionTest(
                        member,
                        disjunction.Right,
                        disposition,
                        negated);
            }

            if (!TryMatchRecoveryDisposition(
                    member.Model,
                    expression,
                    disposition,
                    negated,
                    out ExpressionSyntax receiver)
                || member.Model.GetSymbolInfo(receiver).Symbol is not ILocalSymbol decision
                || decision.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax() is not
                    VariableDeclaratorSyntax
                {
                    Initializer.Value: InvocationExpressionSyntax classification,
                } declaration
                || member.Model.GetSymbolInfo(classification).Symbol is not IMethodSymbol classifier
                || classifier.Name != "Classify"
                || TypeKey(classifier.ContainingType)
                    != "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationRecoveryAdmission"
                || member.Syntax.DescendantNodes()
                    .OfType<AssignmentExpressionSyntax>()
                    .Any(assignment => assignment.SpanStart > declaration.Span.End
                        && assignment.Span.End < expression.SpanStart
                        && SymbolEqualityComparer.Default.Equals(
                            member.Model.GetSymbolInfo(assignment.Left).Symbol,
                            decision)))
            {
                return false;
            }

            return true;
        }

        private static bool TryMatchRecoveryDisposition(
            SemanticModel model,
            ExpressionSyntax expression,
            string disposition,
            bool negated,
            out ExpressionSyntax receiver)
        {
            receiver = null!;

            ExpressionSyntax? expected = null;

            if (!negated
                && expression is BinaryExpressionSyntax classic
                && classic.IsKind(SyntaxKind.IsExpression)
                && classic.Left is MemberAccessExpressionSyntax
                {
                    Expression: { } classicReceiver,
                    Name.Identifier.ValueText: "Kind",
                })
            {
                receiver = classicReceiver;
                expected = classic.Right;
            }
            else if (expression is IsPatternExpressionSyntax
            {
                Expression: MemberAccessExpressionSyntax
                {
                    Expression: { } patternReceiver,
                    Name.Identifier.ValueText: "Kind",
                },
                Pattern: { } candidate,
            })
            {
                PatternSyntax? pattern = negated
                    ? candidate is UnaryPatternSyntax unary
                        && unary.IsKind(SyntaxKind.NotPattern)
                            ? unary.Pattern
                            : null
                    : candidate;

                if (pattern is ConstantPatternSyntax { Expression: { } constant })
                {
                    receiver = patternReceiver;
                    expected = constant;
                }
            }

            return expected is not null
                && model.GetSymbolInfo(expected).Symbol is IFieldSymbol field
                && field.Name == disposition;
        }

        private bool HasAuthoredTarget(IMethodSymbol method) => members.TryGetValue(MethodKey(method), out List<AuthoredMember>? group) && group.Any(static candidate => candidate.Syntax is not MethodDeclarationSyntax { Body: null, ExpressionBody: null });

        private void RefuseTraversalCompletion()
        {
            if (traversalCompletion is { } frame) frame.Complete = false;
        }

        private TraversalEvidence Traverse(AuthoredMember member, string rootType, string operationId, HashSet<TraversalStateIdentity> active, bool lifecycle, string? inheritedWork = null, string? inheritedEffect = null, SyntaxNode? selection = null, IReadOnlySet<int>? fieldPublications = null, bool completionOwned = false, string? recoveryEffect = null, PlannedRoot? plannedRoot = null)
        {
            TraversalCompletionFrame? parent = traversalCompletion;

            NestedRootCohort? previousCohort = nestedRootCohort;

            bool rootEntry = active.Count == 0;

            if (rootEntry)
            {
                if (previousCohort is not null) previousCohort.Eligible = false;

                nestedRootCohort = null;
            }

            TraversalCompletionFrame frame = new();

            traversalCompletion = frame;

            bool returned = false;

            try
            {
                TraversalEvidence result = TraverseState(member, rootType, operationId, active, lifecycle, inheritedWork, inheritedEffect, selection, fieldPublications, completionOwned, recoveryEffect, plannedRoot);

                if (rootEntry && nestedRootCohort is { Eligible: true, Plan.Lifecycle: true } cohort
                    && !boundedDataProbeEncountered && cohort.Pending.Count != 0
                    && completedNestedRoots.TryAdd(cohort.State, new(cohort.Plan, cohort.State, new Dictionary<(TraversalStateIdentity State, string Operation), CompletedNestedBody>(cohort.Pending))))
                {
                    retainedNestedWitnesses += cohort.Pending.Count;
                }

                returned = true;

                return result;
            }
            finally
            {
                if (rootEntry) nestedRootCohort = previousCohort;

                if (!returned) frame.Complete = false;

                if (!frame.Complete && parent is not null) parent.Complete = false;

                if (!returned) frame.FreshNestedPath = false;

                if (!frame.FreshNestedPath && parent is not null) parent.FreshNestedPath = false;

                traversalCompletion = parent;
            }
        }

        private TraversalEvidence TraverseState(AuthoredMember member, string rootType, string operationId, HashSet<TraversalStateIdentity> active, bool lifecycle, string? inheritedWork, string? inheritedEffect, SyntaxNode? selection, IReadOnlySet<int>? fieldPublications, bool completionOwned, string? recoveryEffect, PlannedRoot? plannedRoot)
        {
            // An ordinary holder read needs its actual route witness before any child
            // getter/call can inherit work. Generic WorkAt keeps its existing contract.
            if (inheritedWork is not null && member.RecoveryContext is null
                && declaredOperations.Any(operation => operation.Authority == HostedProducerAuthorityKind.OrdinaryHostedWork
                    && RootOperation(operation.OperationId) == RootOperation(operationId))
                && RequiresOrdinaryScopedHolderWitness(member)
                && !OrdinaryScopedHolderWorkIsCurrent(member, inheritedWork)) inheritedWork = null;

            member = ProjectTraversalRecoveryEnvironment(member);

            member = ProjectTraversalEvaluationEnvironment(
                member,
                out int? environmentToken,
                out bool environmentTokenObtained);

            GraphMemberIdentity visitKey = MemberIdentity(member);

            string rootOperation = RootOperation(operationId);

            string root = rootType + "|" + rootOperation;

            if (active.Count >= traversalMaximumDepth)
            {
                if (limitedRoots.Add(root))
                {
                    diagnostics.Add(new(
                        "HOSTED_TRAVERSAL_STATE_LIMIT_EXCEEDED",
                        rootOperation,
                        $"The exact semantic graph exceeded {traversalMaximumDepth} nested states for one authority root."));
                }

                RefuseTraversalCompletion();

                return TraversalEvidence.Inconclusive;
            }

            TraversalStateIdentity state = TraversalState(
                member,
                rootType,
                operationId,
                lifecycle,
                inheritedWork,
                inheritedEffect,
                recoveryEffect,
                selection,
                fieldPublications,
                completionOwned,
                environmentToken,
                environmentTokenObtained);

            if (state.EvaluationEnvironmentToken is null || activeBoundedDataProbe is not null)
            {
                RefuseTraversalCompletion();
            }

            bool wholePlannedRoot = plannedRoot is { } planned
                && active.Count == 0
                && activeBoundedDataProbe is null
                && planned.Lifecycle == lifecycle
                && planned.Operation == operationId
                && operationId == TypeKey(member.Symbol.ContainingType) + "." + member.Symbol.Name
                && planned.Member.Syntax == member.Syntax
                && (lifecycle ? selection is null : selection == member.Syntax)
                && !selectedRoots.ContainsKey(visitKey)
                && state.EvaluationEnvironmentToken is not null;

            // This is a directed planned-root lookup, never a false-state cache alias.
            // Both binders and projections have already produced the exact current inputs.
            if (wholePlannedRoot && !lifecycle
                && completedLifecycleRoots.TryGetValue(state with { Lifecycle = true }, out CompletedLifecycleRoot completedRoot)
                && completedRoot.Operation == operationId
                && completedRoot.Occurrence < plannedRoot!.Occurrence
                && traversalCompletion!.Complete)
            {
                traversalCompletion!.FreshNestedPath = false;

                return completedRoot.Evidence;
            }

            if (wholePlannedRoot && !boundedDataProbeEncountered)
            {
                if (lifecycle)
                {
                    nestedRootCohort = new(plannedRoot!, state, null);
                }
                else if (completedNestedRoots.TryGetValue(state with { Lifecycle = true }, out CompletedNestedRoot? earlier)
                    && earlier is not null
                    && earlier.Plan.Operation == operationId
                    && earlier.Plan.Family == plannedRoot!.Family
                    && earlier.Plan.Member.Syntax == plannedRoot.Member.Syntax
                    && earlier.Plan.Occurrence < plannedRoot.Occurrence)
                {
                    nestedRootCohort = new(plannedRoot, state, earlier);
                }
            }

            if (nestedRootCohort is { } current && active.Count != 0)
            {
                // A certificate cannot indirectly skip a selected or independent root lane.
                if (state.RootType != current.State.RootType || state.RootOperation != current.State.RootOperation
                    || state.Lifecycle != current.State.Lifecycle
                    || !operationId.StartsWith(current.Plan.Operation + "/", StringComparison.Ordinal)
                    || selection is not null && selection != member.Syntax
                    || selectedRoots.ContainsKey(visitKey)
                    || !active.Contains(current.State)
                    || active.Any(ancestor => ancestor.RootType != current.State.RootType
                        || ancestor.RootOperation != current.State.RootOperation
                        || ancestor.Lifecycle != current.State.Lifecycle
                        || ancestor.EvaluationEnvironmentToken is null))
                {
                    current.Eligible = false;
                }

                // Full projected identities and the raw path are necessary but insufficient:
                // the original active ancestor set must also match, without normalizing keys.
                if (current.Eligible && !boundedDataProbeEncountered && !lifecycle
                    && state.EvaluationEnvironmentToken is not null && !active.Contains(state)
                    && current.Earlier is { } source
                    && source.Bodies.TryGetValue((state with { Lifecycle = true }, operationId), out CompletedNestedBody? body)
                    && body is not null
                    && body.Ancestors.Length == active.Count
                    && body.Ancestors.All(ancestor => active.Contains(ancestor with { Lifecycle = false })))
                {
                    nestedReuseHits++;

                    traversalCompletion!.FreshNestedPath = false;

                    return body.Evidence;
                }
            }

            if (analyzedStates.TryGetValue(state, out TraversalEvidence cachedEvidence))
            {
                traversalCompletion!.FreshNestedPath = false;

                if (!completedTraversalStates.GetValueOrDefault(state)) RefuseTraversalCompletion();

                return cachedEvidence;
            }

            int stateCount = analyzedStateCounts.GetValueOrDefault(root);

            if (stateCount >= maximumAnalyzedStatesPerRoot)
            {
                if (limitedRoots.Add(root))
                {
                    diagnostics.Add(new("HOSTED_TRAVERSAL_STATE_LIMIT_EXCEEDED", state.RootOperation, $"The exact semantic graph exceeded {maximumAnalyzedStatesPerRoot} states for one authority root."));
                }

                RefuseTraversalCompletion();

                return TraversalEvidence.Inconclusive;
            }

            TraversalStateIdentity[]? nestedAncestors = nestedRootCohort is { Eligible: true, Plan.Lifecycle: true }
                && !boundedDataProbeEncountered && state.EvaluationEnvironmentToken is not null
                && active.Count != 0 && !active.Contains(state)
                    ? active.ToArray()
                    : null;

            if (!active.Add(state))
            {
                RefuseTraversalCompletion();

                return TraversalEvidence.Inconclusive;
            }

            analyzedStateCounts[root] = stateCount + 1;

            if (admittedStateObserver is not null)
            {
                admittedStateObserver(new(
                    progressWorker,
                    progressOccurrence,
                    rootTraversalSequence,
                    stateCount + 1,
                    state.RootType,
                    state.RootOperation,
                    state.Member.Assembly.Name,
                    state.Member.Assembly.Version.ToString(),
                    state.Member.Assembly.CultureName,
                    Convert.ToHexString((state.Member.Assembly.HasPublicKey ? state.Member.Assembly.PublicKey : state.Member.Assembly.PublicKeyToken).AsSpan()),
                    state.Member.Assembly.HasPublicKey,
                    state.Member.Assembly.IsRetargetable,
                    (int)state.Member.Assembly.ContentType,
                    state.Member.Compilation,
                    state.Member.Tree,
                    state.Member.Method,
                    state.Member.SpanStart,
                    state.Member.SpanLength,
                    state.SelectionStart,
                    state.SelectionLength,
                    state.EvaluationEnvironmentToken,
                    state.FallbackAdmissionBindings,
                    state.FallbackEvaluationEnvironment,
                    state.FallbackValueBindings,
                    state.FallbackConcreteBindings,
                    state.FallbackRecoveryBindings,
                    state.WorkFrontier,
                    state.EffectFrontier,
                    state.RecoveryEffectFrontier,
                    state.FieldPublications,
                    state.CompletionOwned,
                    state.Lifecycle));
            }

            if (!analyzedMemberStateCounts.TryGetValue(
                    root,
                    out Dictionary<GraphMemberIdentity, int>? memberStates))
            {
                memberStates = [];

                analyzedMemberStateCounts.Add(root, memberStates);
            }

            int memberStateCount = memberStates.GetValueOrDefault(visitKey) + 1;

            memberStates[visitKey] = memberStateCount;

            int analyzedStateCount = stateCount + 1;

            if (analyzedStateCount == 1
                || analyzedStateCount % RootStateProgressInterval == 0)
            {
                WriteRootStateProgress(
                    rootType,
                    rootOperation,
                    analyzedStateCount,
                    visitKey,
                    memberStateCount,
                    memberStates);
            }

            TraversalEvidence emittedEvidence = TraversalEvidence.NoEvidence;

            RecoveryConditionEvaluationContext recoveryConditionEvaluations = new();

            HashSet<(int Start, int Length, MethodIdentity Method)> executedConversions = [];

            try
            {
                if (lifecycle)
                {
                    lifecycleMembers.Add(visitKey);
                }

                HostedProducerOperationEntry? ordinary = declaredOperations.FirstOrDefault(entry => entry.Authority == HostedProducerAuthorityKind.OrdinaryHostedWork && (operationId == entry.OperationId || operationId.StartsWith(entry.OperationId + "/", StringComparison.Ordinal)));

                // The Root Lease Formal is a handoff root's admission origin, so its frontier row is the root's own.
                if (ordinary is { LeaseFormal: not null } handoffRoot
                    && operationId == handoffRoot.OperationId
                    && LeaseHandoffRootFor(handoffRoot) is { } formalRoot
                    && SymbolEqualityComparer.Default.Equals(formalRoot.Member.Symbol, member.Symbol))
                {
                    emittedEvidence = MergeEvidence(emittedEvidence, AddLeaseFormalSite(member, rootType, operationId, formalRoot));
                }

                if (ordinary is not null && selection is not null && selection != member.Syntax)
                {
                    foreach (string admissionName in new[] { "TryAcquireWorkLease", "TryBeginExternalEffectGroup" })
                    {
                        string? retained = FindRetainedAdmission(member, selection, admissionName, admissionName == "TryAcquireWorkLease" ? ordinary.WorkKind : null);

                        InvocationExpressionSyntax? admission = member.Syntax.DescendantNodes().OfType<InvocationExpressionSyntax>().SingleOrDefault(call => Location(call) == retained);

                        if (admission is not null && member.Model.GetSymbolInfo(admission).Symbol is IMethodSymbol gate)
                        {
                            emittedEvidence = MergeEvidence(emittedEvidence, AddSite(HostedProducerSiteKind.EffectFrontier, Normalize(gate), member, rootType, operationId, admission));
                        }
                    }
                }

                if (selection is null && AsyncBuilderReachesProducerSite(member, out INamedTypeSymbol? asyncBuilder))
                {
                    RefuseTraversalCompletion();

                    diagnostics.Add(new(
                        "HOSTED_SITE_UNCLASSIFIED",
                        Location(member.Syntax),
                        TypeKey(asyncBuilder!) + "; An authored async method builder runs its Create, Start, AwaitOnCompleted, SetResult, SetException and Task members at points of the state machine nothing here places."));
                }

                if (selection is null
                    && member.Symbol is { MethodKind: MethodKind.Constructor, IsStatic: false }
                    && member.Syntax is ConstructorDeclarationSyntax constructorDeclaration)
                {
                    emittedEvidence = MergeEvidence(
                        emittedEvidence,
                        TraverseConstructionPreamble(
                            member,
                            constructorDeclaration,
                            rootType,
                            operationId,
                            active,
                            lifecycle,
                            ordinary?.WorkKind,
                            inheritedWork,
                            inheritedEffect,
                            recoveryEffect));
                }

                foreach (SyntaxNode node in (selection ?? member.Syntax).DescendantNodesAndSelf(node => node == (selection ?? member.Syntax) || node is not LocalFunctionStatementSyntax and not AnonymousFunctionExpressionSyntax))
                {
                    bool recoveryNodeMayExecute = RecoveryNodeMayExecute(
                        member,
                        node,
                        recoveryConditionEvaluations);

                    if (!recoveryNodeMayExecute)
                    {
                        continue;
                    }

                    if (selection is null && operationId == TypeKey(member.Symbol.ContainingType) + "." + member.Symbol.Name && selectedRoots.TryGetValue(visitKey, out List<SyntaxNode>? selections) && selections.Any(selected => selected.Span.Contains(node.Span)))
                    {
                        continue;
                    }

                    if (node is InvocationExpressionSyntax && member.Model.GetOperation(node) is INameOfOperation)
                    {
                        continue;
                    }

                    if (node is InvocationExpressionSyntax && member.Model.GetOperation(node) is IDynamicInvocationOperation)
                    {
                        RefuseTraversalCompletion();

                        diagnostics.Add(new("HOSTED_CALL_TARGET_UNRESOLVED", Location(node), "Dynamic invocation has no exact call target."));

                        continue;
                    }

                    if (node is ElementAccessExpressionSyntax
                            or ElementBindingExpressionSyntax
                            or ImplicitElementAccessSyntax
                        && member.Model.GetOperation(node) is IDynamicIndexerAccessOperation)
                    {
                        RefuseTraversalCompletion();

                        diagnostics.Add(new(
                            "HOSTED_CALL_TARGET_UNRESOLVED",
                            Location(node),
                            "Dynamic indexer access has no exact accessor target."));

                        continue;
                    }

                    if (node is AssignmentExpressionSyntax staticStore && StoresAdmissionCarrierInStaticStorage(member, staticStore, out string staticRoot))
                    {
                        RefuseTraversalCompletion();

                        diagnostics.Add(new("HOSTED_ADMISSION_HANDLE_ESCAPE", operationId + "/store@" + Location(node), staticRoot + "; A retained handle stored in static storage has no proven lifetime continuation."));
                    }

                    if (StaticInitializationStartedAt(member, node) is { } initializedType)
                    {
                        RefuseTraversalCompletion();

                        diagnostics.Add(new(
                            "HOSTED_SITE_UNCLASSIFIED",
                            Location(node),
                            TypeKey(initializedType) + ".cctor; The static initialization of the type can reach a producer site, and the point at which the runtime first uses the type is not modeled."));
                    }

                    if (ImplicitCallsAt(member, selection ?? member.Syntax, node) is { Count: > 0 } implicitCalls)
                    {
                        emittedEvidence = MergeEvidence(
                            emittedEvidence,
                            TraverseImplicitCalls(
                                member,
                                implicitCalls,
                                rootType,
                                operationId,
                                active,
                                lifecycle,
                                ordinary?.WorkKind,
                                inheritedWork,
                                inheritedEffect,
                                recoveryEffect));
                    }

                    foreach (IConversionOperation conversion in UserConversionsAt(member, node))
                    {
                        IMethodSymbol selectedOperator = conversion.OperatorMethod!;

                        SyntaxNode conversionSyntax = conversion.Syntax;

                        if (!(selection ?? member.Syntax).Span.Contains(conversionSyntax.Span)
                            || !executedConversions.Add((conversionSyntax.SpanStart,
                                conversionSyntax.Span.Length, Identity(selectedOperator)))) continue;

                        string callee = Normalize(selectedOperator);

                        AuthoredMember? target = Resolve(selectedOperator, member.Model.Compilation);

                        if (target is null)
                        {
                            if (!IsReviewedEffectFreeExternalMember(selectedOperator,
                                conversionSyntax, member.Model, member))
                            {
                                RefuseTraversalCompletion();

                                diagnostics.Add(new("HOSTED_SITE_UNCLASSIFIED", Location(conversionSyntax), callee));
                            }

                            continue;
                        }

                        if (target.Syntax is ConversionOperatorDeclarationSyntax { Body: null, ExpressionBody: null }
                            || selectedOperator.Parameters is not [IParameterSymbol parameter]
                            || conversion.Operand.Syntax is not ExpressionSyntax operand)
                        {
                            RefuseTraversalCompletion();

                            diagnostics.Add(new("HOSTED_CALL_TARGET_UNRESOLVED", Location(conversionSyntax), callee));

                            continue;
                        }

                        // The operand has completed before this operator begins. Existing
                        // lifetime comparisons use strict <, so include a call ending exactly
                        // at the operand boundary while retaining the conversion's region.
                        int position = conversion.Operand.Syntax.Span.End + 1;

                        string? workAdmitted = WorkAt(member, conversionSyntax, operationId, ordinary?.WorkKind, inheritedWork, position);

                        string? effectGroup = EffectAt(member, conversionSyntax, operationId, inheritedEffect, position);

                        bool operandLifetimeUnproven = (workAdmitted is not null || effectGroup is not null || recoveryEffect is not null)
                            && ConversionOperandHasUnsupportedLifetime(member, conversion.Operand, target);

                        if (operandLifetimeUnproven)
                        {
                            RefuseTraversalCompletion();

                            workAdmitted = null;

                            effectGroup = null;
                        }

                        AuthoredMember bound = BindArguments(member, [(operand, parameter, parameter.RefKind)], target);

                        bool detached = IsAwaitable(target.Symbol.ReturnType) || IsLazySequence(target.Symbol.ReturnType);

                        if (detached)
                        {
                            RefuseTraversalCompletion();

                            diagnostics.Add(new("HOSTED_CALLBACK_OWNERSHIP_UNPROVEN",
                                operationId + "/conversion@" + Location(conversionSyntax),
                                callee + "; An awaitable or lazy conversion has no proven completion within its caller's retained lifetime."));
                        }

                        emittedEvidence = MergeEvidence(emittedEvidence,
                            Traverse(bound, rootType, operationId + "/conversion@" + Location(conversionSyntax),
                                active, lifecycle, detached ? null : workAdmitted, detached ? null : effectGroup,
                                recoveryEffect: detached || operandLifetimeUnproven ? null : recoveryEffect));
                    }

                    if (UserDefinedOperatorAt(member, node) is { } selectedOperation)
                    {
                        IMethodSymbol selectedOperator = selectedOperation.Method;

                        string callee = Normalize(selectedOperator);

                        AuthoredMember? target = Resolve(selectedOperator, member.Model.Compilation);

                        if (target is null)
                        {
                            List<AuthoredMember> equalityTargets = [];

                            bool canonicalEquality = false;

                            bool liftedEquality = selectedOperation.Unsupported
                                && member.Model.GetOperation(node) is IBinaryOperation
                                {
                                    IsLifted: true,
                                    OperatorKind: BinaryOperatorKind.Equals or BinaryOperatorKind.NotEquals,
                                };

                            bool equalityCertified = (!selectedOperation.Unsupported || liftedEquality)
                                && TryGeneratedRecordEqualityTargets(member, selectedOperator, selectedOperation.Operands, out equalityTargets, out canonicalEquality, liftedEquality);

                            if (equalityCertified || equalityTargets.Count != 0)
                            {
                                int position = selectedOperation.Operands.Max(static operand => operand.Syntax.Span.End) + 1;

                                string? workAdmitted = WorkAt(member, node, operationId, ordinary?.WorkKind, inheritedWork, position);

                                string? effectGroup = EffectAt(member, node, operationId, inheritedEffect, position);

                                CleanupProvenanceContext operandProof = new();

                                bool operandLifetimeUnproven = !equalityCertified
                                    || (workAdmitted is not null || effectGroup is not null || recoveryEffect is not null)
                                        && equalityTargets.Any(equalityTarget => selectedOperation.Operands.Any(operand =>
                                                ConversionOperandHasUnsupportedLifetime(member, operand, equalityTarget, operandProof,
                                                    typeInitializationProven: canonicalEquality)));

                                if (operandLifetimeUnproven)
                                {
                                    RefuseTraversalCompletion();

                                    workAdmitted = null;

                                    effectGroup = null;
                                }

                                foreach (AuthoredMember equalityTarget in equalityTargets)
                                {
                                    // Canonical Equals Traversal names the body by its root and type, so every
                                    // comparison site under one root and frontier reaches the one state.
                                    string equalityOperation = canonicalEquality
                                        ? RootOperation(operationId) + "/equals@" + TypeKey(equalityTarget.Symbol.ContainingType)
                                        : operationId + "/operator@" + Location(node);

                                    emittedEvidence = MergeEvidence(emittedEvidence,
                                        Traverse(equalityTarget, rootType, equalityOperation, active, lifecycle,
                                            workAdmitted, effectGroup,
                                            recoveryEffect: operandLifetimeUnproven ? null : recoveryEffect));
                                }
                            }

                            if (!equalityCertified && !IsReviewedEffectFreeExternalMember(selectedOperator, node, member.Model, member))
                            {
                                RefuseTraversalCompletion();

                                diagnostics.Add(new("HOSTED_SITE_UNCLASSIFIED", Location(node), callee));
                            }
                        }
                        else if (selectedOperation.Unsupported
                            || target.Syntax is not OperatorDeclarationSyntax operatorDeclaration
                            || operatorDeclaration.Body is null && operatorDeclaration.ExpressionBody is null
                            || !selectedOperator.IsStatic
                            || selectedOperator.Parameters.Length != selectedOperation.Operands.Length
                            || selectedOperator.Parameters.Any(static parameter => parameter.RefKind != RefKind.None)
                            || selectedOperation.Operands.Any(static operand => operand.Syntax is not ExpressionSyntax))
                        {
                            RefuseTraversalCompletion();

                            diagnostics.Add(new("HOSTED_CALL_TARGET_UNRESOLVED", Location(node), callee));
                        }
                        else
                        {
                            int position = selectedOperation.Operands.Max(static operand => operand.Syntax.Span.End) + 1;

                            string? workAdmitted = WorkAt(member, node, operationId, ordinary?.WorkKind, inheritedWork, position);

                            string? effectGroup = EffectAt(member, node, operationId, inheritedEffect, position);

                            CleanupProvenanceContext operandProof = new();

                            bool operandLifetimeUnproven = (workAdmitted is not null || effectGroup is not null || recoveryEffect is not null)
                                && selectedOperation.Operands.Any(operand => ConversionOperandHasUnsupportedLifetime(member, operand, target, operandProof));

                            if (operandLifetimeUnproven)
                            {
                                RefuseTraversalCompletion();

                                workAdmitted = null;

                                effectGroup = null;
                            }

                            AuthoredMember bound = BindArguments(member, selectedOperation.Operands.Select((operand, index) =>
                                ((ExpressionSyntax)operand.Syntax, (IParameterSymbol?)selectedOperator.Parameters[index], RefKind.None)), target);

                            bool detached = IsAwaitable(target.Symbol.ReturnType) || IsLazySequence(target.Symbol.ReturnType);

                            if (detached)
                            {
                                RefuseTraversalCompletion();

                                diagnostics.Add(new("HOSTED_CALLBACK_OWNERSHIP_UNPROVEN", operationId + "/operator@" + Location(node),
                                    callee + "; An awaitable or lazy operator has no proven completion within its caller's retained lifetime."));
                            }

                            emittedEvidence = MergeEvidence(emittedEvidence,
                                Traverse(bound, rootType, operationId + "/operator@" + Location(node), active, lifecycle,
                                    detached ? null : workAdmitted, detached ? null : effectGroup,
                                    recoveryEffect: detached || operandLifetimeUnproven ? null : recoveryEffect));
                        }
                    }

                    // An implicit-this DbContext property used as the receiver of a further member
                    // (`Database.CanConnect()`) is not visited as a property read below, but it is
                    // the first use of the context's services all the same.
                    if (node is IdentifierNameSyntax { Parent: MemberAccessExpressionSyntax receiverAccess } receiverName
                        && ReferenceEquals(receiverAccess.Expression, receiverName)
                        && IsExactEfDbContext(member.Symbol.ContainingType)
                        && !IsLongRestSdkFactoryReceiverProperty(node, member)
                        && member.Model.GetSymbolInfo(receiverName).Symbol is IPropertySymbol receiverProperty
                        && DbContextFirstUseHooks(member, node, receiverProperty) is { Count: > 0 } receiverHooks)
                    {
                        // EF runs the context's authored hooks at the first service use, which is not this read, so
                        // no admission current here is inherited (see DbContextFirstUseHooks).
                        emittedEvidence = MergeEvidence(
                            emittedEvidence,
                            TraverseDbContextHooks(receiverHooks, rootType, operationId, node, active, lifecycle));
                    }

                    ISymbol? symbol = node is InvocationExpressionSyntax
                        or ObjectCreationExpressionSyntax
                        or ImplicitObjectCreationExpressionSyntax
                        or MemberAccessExpressionSyntax
                        or ElementAccessExpressionSyntax
                        or ElementBindingExpressionSyntax
                        or ImplicitElementAccessSyntax
                            ? member.Model.GetSymbolInfo(node).Symbol
                            : node is IdentifierNameSyntax
                                && (node.Parent is not MemberAccessExpressionSyntax readReceiver
                                    || readReceiver.Expression == node
                                    || IsLongRestSdkFactoryReceiverProperty(node, member))
                                    ? member.Model.GetSymbolInfo(node).Symbol switch
                                    {
                                        IPropertySymbol property => property,
                                        IEventSymbol declaredEvent => declaredEvent,
                                        _ => null,
                                    }
                                    : null;

                    if (symbol is IFieldSymbol dbSetField && IsEfDbSetType(dbSetField.Type) && node is ExpressionSyntax dbSetFieldRead)
                    {
                        RefuseEscapingEfQuery(member, dbSetFieldRead, Normalize(dbSetField));
                    }

                    if (symbol is IMethodSymbol method && node is not MemberAccessExpressionSyntax)
                    {
                        int? readinessPosition = (member.ReadinessSource is { OwnedAdmission: not null }
                                || member.ScopedLeaseInstance is not null)
                            && node is InvocationExpressionSyntax readinessBoundary ? readinessBoundary.Span.End : null;

                        string? workAdmitted = WorkAt(member, node, operationId, ordinary?.WorkKind, inheritedWork, readinessPosition);

                        if (workAdmitted is null && node is InvocationExpressionSyntax rootSettlement)
                        {
                            workAdmitted = PerUnitWorkAtRootSettlement(member, rootSettlement,
                                rootType, operationId, ordinary?.WorkKind);
                        }

                        if (workAdmitted is null && node is InvocationExpressionSyntax ordinaryDispatch)
                        {
                            workAdmitted = OrdinaryScopedHolderAtDispatch(member, ordinaryDispatch,
                                rootType, operationId, ordinary?.WorkKind)?.Work;
                        }

                        string? effectGroup = EffectAt(member, node, operationId, inheritedEffect,
                            member.ScopedLeaseInstance is not null ? readinessPosition : null);

                        string callee = Normalize(method);

                        // A call that builds an EF query hands back a value whose execution must be followed from here.
                        if (node is InvocationExpressionSyntax queryBuilding
                            && Resolve(method.ReducedFrom ?? method, member.Model.Compilation) is null
                            && IsEfQueryOperand(member, queryBuilding))
                        {
                            RefuseEscapingEfQuery(member, queryBuilding, callee);
                        }

                        // Disposing a context, or a container scope that disposes the contexts it built, raises the disposal
                        // callbacks of the connection under the frontiers live at the disposal.
                        if (node is InvocationExpressionSyntax
                            {
                                Expression: MemberAccessExpressionSyntax { Expression: { } disposedResource },
                                ArgumentList.Arguments.Count: 0,
                            } disposalCall
                            && method.Name is "Dispose" or "DisposeAsync")
                        {
                            bool disposalJoined = !IsAwaitable(method.ReturnType)
                                || CompletionPoint(member, disposalCall, completionOwned) is not null;

                            emittedEvidence = MergeEvidence(
                                emittedEvidence,
                                TraverseDisposalCallbacks(
                                    member,
                                    disposedResource,
                                    member.Model.GetTypeInfo(disposedResource).Type,
                                    method.Name == "DisposeAsync",
                                    node,
                                    rootType,
                                    operationId,
                                    active,
                                    lifecycle,
                                    disposalJoined ? workAdmitted : null,
                                    disposalJoined ? effectGroup : null,
                                    recoveryEffect));
                        }

                        // H7: EF runs OnConfiguring at the first use of the context's services,
                        // whichever DbContext member that is; judge it at every such use.
                        if (node is InvocationExpressionSyntax
                            && DbContextFirstUseHooks(member, node, method) is { Count: > 0 } firstUseHooks)
                        {
                            emittedEvidence = MergeEvidence(
                                emittedEvidence,
                                TraverseDbContextHooks(firstUseHooks, rootType, operationId, node, active, lifecycle));
                        }

                        // Activating a context runs the field and property initializers of the type and of every
                        // authored base where the creation is written, under the frontiers live there. The constructor
                        // the creation names is traversed with the other targets below.
                        if (node is BaseObjectCreationExpressionSyntax contextCreation
                            && method.ContainingType is { TypeKind: TypeKind.Class } createdContext
                            && IsAuthoredSymbol(createdContext)
                            && IsExactEfDbContext(createdContext))
                        {
                            foreach (AuthoredMember initializer in ActivationMembers(createdContext, member.Model.Compilation, includeConstructors: false))
                            {
                                emittedEvidence = MergeEvidence(
                                    emittedEvidence,
                                    Traverse(
                                        initializer,
                                        rootType,
                                        operationId + "/activate@" + Location(contextCreation),
                                        active,
                                        lifecycle,
                                        workAdmitted,
                                        effectGroup,
                                        recoveryEffect: recoveryEffect));
                            }
                        }

                        if ((node is InvocationExpressionSyntax or BaseObjectCreationExpressionSyntax)
                            && Resolve(method, member.Model.Compilation) is null
                            && method.Locations.All(static location => !location.IsInSource)
                            && FrameworkMemberRunsAuthoredEnumerator(member, node, method, out string enumerationDetail))
                        {
                            RefuseTraversalCompletion();

                            diagnostics.Add(new("HOSTED_CALLBACK_OWNERSHIP_UNPROVEN", RootOperation(operationId) + "/enumerable@" + Location(node), enumerationDetail));
                        }

                        if ((node is InvocationExpressionSyntax or BaseObjectCreationExpressionSyntax)
                            && Resolve(method, member.Model.Compilation) is null
                            && method.Locations.All(static location => !location.IsInSource)
                            && FrameworkMemberRunsAuthoredCallback(member, node, method, out string callbackDetail))
                        {
                            RefuseTraversalCompletion();

                            diagnostics.Add(new("HOSTED_CALLBACK_OWNERSHIP_UNPROVEN", RootOperation(operationId) + "/callback@" + Location(node), callbackDetail));
                        }

                        if (node is InvocationExpressionSyntax explicitCleanup
                            && (IsTrustedFrameworkCleanupSlot(method)
                                || IsExactSdkSessionCleanup(method))
                            && AdmissionReceiver(member, explicitCleanup) is { } cleanupReceiver)
                        {
                            EffectiveCleanupResolution cleanup = ResolveEffectiveCleanup(
                                member,
                                member.Model.GetTypeInfo(cleanupReceiver).Type ?? method.ContainingType,
                                cleanupReceiver,
                                method.Name,
                                explicitCleanupSlot: method);

                            bool joined = !IsAwaitable(method.ReturnType)
                                || CompletionPoint(member, explicitCleanup, completionOwned) is not null;

                            if (!joined)
                            {
                                RefuseTraversalCompletion();

                                diagnostics.Add(new("HOSTED_CALLBACK_OWNERSHIP_UNPROVEN",
                                    operationId + "/call@" + Location(node),
                                    callee + "; Explicit asynchronous cleanup must complete within its caller's retained lifetime."));
                            }

                            foreach (AuthoredMember cleanupTarget in cleanup.Targets)
                            {
                                emittedEvidence = MergeEvidence(emittedEvidence,
                                    Traverse(cleanupTarget, rootType, operationId + "/dispose@" + Location(node),
                                        active, lifecycle, joined ? workAdmitted : null, joined ? effectGroup : null,
                                        completionOwned: joined, recoveryEffect: joined ? recoveryEffect : null));
                            }

                            foreach (ExternalCleanupResolution external in cleanup.ExternalEffects)
                            {
                                emittedEvidence = MergeEvidence(emittedEvidence,
                                    AddSite(external.Kind, external.Callee, member, rootType, operationId, node,
                                        joined ? effectGroup : null, joined ? workAdmitted : null));
                            }

                            if (cleanup.MustResolve
                                && cleanup.Targets.Count == 0
                                && cleanup.ExternalEffects.Count == 0
                                && !IsExactAdmissionCleanupValue(member, cleanupReceiver,
                                    new HashSet<ISymbol>(SymbolEqualityComparer.Default))
                                && !IsExactConditionalNullCleanupValue(member, explicitCleanup, cleanupReceiver))
                            {
                                RefuseTraversalCompletion();

                                diagnostics.Add(new("HOSTED_DISPOSAL_TARGET_UNRESOLVED",
                                    operationId + "/dispose@" + Location(node),
                                    callee + "; Explicit cleanup must resolve to exactly one compiler-effective target."));
                            }

                            continue;
                        }

                        bool asynchronousCallback = callee is
                            "System.Threading.Tasks.Task.Run"
                                or "System.Threading.Tasks.TaskFactory.StartNew"
                                or "System.Threading.Tasks.Task.ContinueWith"
                                or "System.Threading.Tasks.Task`1.ContinueWith"
                                or "System.Threading.Tasks.Parallel.ForEachAsync";

                        bool lazyCallback = IsKnownLazyCallback(method);

                        bool synchronousCallback = method.MethodKind == MethodKind.DelegateInvoke
                            || IsKnownSynchronousCallback(method)
                                && method.Parameters.Any(static parameter =>
                                    parameter.Type.TypeKind == TypeKind.Delegate)
                                && (!IsExactEagerCollectionCallback(method)
                                    || node is InvocationExpressionSyntax eagerCall
                                        && eagerCall.ArgumentList.Arguments
                                            .Where(argument => IsDelegateExpression(member.Model, argument.Expression))
                                            .All(argument => HasCompleteEagerCallableOrigin(argument.Expression, member.Model,
                                                new HashSet<ISymbol>(SymbolEqualityComparer.Default), member)));

                        bool knownCallback = asynchronousCallback || synchronousCallback || lazyCallback;

                        bool ownedTransparentCallbackCarrier =
                            TransparentProducerBoundaries.Contains(callee)
                            && node is InvocationExpressionSyntax transparentCall
                            && HasOwnedLongLivedReturn(member, transparentCall);

                        if (callee == "System.ArgumentNullException.ThrowIfNull")
                        {
                            continue;
                        }

                        if (CompletionOwnedExternalAwaitables.Contains(callee)
                            || node is InvocationExpressionSyntax channelRead
                                && IsOwnedBoundedGuidChannelRead(member, channelRead, method))
                        {
                            if (node is not InvocationExpressionSyntax ownedAwaitable
                                || CompletionPoint(
                                    member,
                                    ownedAwaitable,
                                    completionOwned) is null)
                            {
                                RefuseTraversalCompletion();

                                diagnostics.Add(new(
                                    "HOSTED_CALLBACK_OWNERSHIP_UNPROVEN",
                                    RootOperation(operationId)
                                        + "/call@"
                                        + Location(node),
                                    callee
                                        + "; Timer-backed asynchronous work must complete within its caller's retained lifetime."));
                            }

                            continue;
                        }

                        if (callee == "System.Lazy`1..ctor")
                        {
                            continue;
                        }

                        if (node is InvocationExpressionSyntax recoveryTerminal
                            && IsReviewedEffectFreeRecoveryTerminal(
                                member,
                                recoveryTerminal,
                                method))
                        {
                            emittedEvidence = MergeEvidence(
                                emittedEvidence,
                                TraversalEvidence.Evidence);

                            continue;
                        }

                        if (node is InvocationExpressionSyntax testSeamCall
                            && IsReviewedDormantTestSeam(method))
                        {
                            if (IsAwaitable(method.ReturnType)
                                && CompletionPoint(
                                    member,
                                    testSeamCall,
                                    completionOwned) is null)
                            {
                                RefuseTraversalCompletion();

                                diagnostics.Add(new(
                                    "HOSTED_CALLBACK_OWNERSHIP_UNPROVEN",
                                    RootOperation(operationId)
                                        + "/call@"
                                        + Location(node),
                                    callee
                                        + "; The dormant test checkpoint must still be completion-owned by its caller."));
                            }

                            continue;
                        }

                        if (DetachedExternalCallbackMethods.Contains(callee)
                            && node is InvocationExpressionSyntax detachedCarrier)
                        {
                            ExpressionSyntax[] detachedCallbacks = detachedCarrier
                                .ArgumentList
                                .Arguments
                                .Where(argument =>
                                    !argument.RefKindKeyword.IsKind(
                                        SyntaxKind.OutKeyword)
                                    && IsDelegateExpression(
                                        member.Model,
                                        argument.Expression))
                                .Select(static argument => argument.Expression)
                                .ToArray();

                            emittedEvidence = MergeEvidence(
                                emittedEvidence,
                                TraverseDetachedExternalCallbacks(
                                    member,
                                    detachedCallbacks,
                                    callee,
                                    node,
                                    rootType,
                                    operationId,
                                    active,
                                    lifecycle));

                            continue;
                        }

                        ArgumentSyntax[] opaqueCallbackArguments = node switch
                        {
                            InvocationExpressionSyntax opaqueCall =>
                                opaqueCall.ArgumentList.Arguments.ToArray(),
                            BaseObjectCreationExpressionSyntax opaqueCreation
                                when opaqueCreation.ArgumentList is not null =>
                                opaqueCreation.ArgumentList.Arguments.ToArray(),
                            _ => [],
                        };

                        if (!knownCallback
                            && !ownedTransparentCallbackCarrier
                            && Resolve(method, member.Model.Compilation) is null
                            && method.Locations.All(static location =>
                                !location.IsInSource)
                            && opaqueCallbackArguments.Any(argument =>
                                !argument.RefKindKeyword.IsKind(SyntaxKind.OutKeyword)
                                && IsDelegateExpression(
                                    member.Model,
                                    argument.Expression)))
                        {
                            ExpressionSyntax[] opaqueCallbacks = opaqueCallbackArguments
                                .Where(argument =>
                                    !argument.RefKindKeyword.IsKind(SyntaxKind.OutKeyword)
                                    && IsDelegateExpression(
                                        member.Model,
                                        argument.Expression))
                                .Select(static argument => argument.Expression)
                                .ToArray();

                            if (opaqueCallbacks.Any(callback => ResolveCallable(callback, member.Model, member.CallableBindings, member.AbsentCallables) is not { } body || HasAdmissionSeed(body) || ContainsPotentialProducerSite(body)))
                            {
                                RefuseTraversalCompletion();

                                diagnostics.Add(new("HOSTED_CALLBACK_OWNERSHIP_UNPROVEN", RootOperation(operationId) + "/callback@" + Location(node), callee + "; Opaque callback semantics cannot prove execution or completion ownership."));
                            }
                        }

                        if (node is InvocationExpressionSyntax callbackCall && knownCallback)
                        {
                            ExpressionSyntax[] callbacks = method.MethodKind == MethodKind.DelegateInvoke
                                ? [DelegateReceiver(member, callbackCall)]
                                : callbackCall.ArgumentList.Arguments.Where(argument => !argument.RefKindKeyword.IsKind(SyntaxKind.OutKeyword) && IsDelegateExpression(member.Model, argument.Expression)).Select(static argument => argument.Expression).ToArray();

                            // The exact containing instance cannot lend its origin through
                            // a delegate boundary, even when the body has no physical site.
                            if (member.ScopedLeaseInstance is not null)
                            {
                                emittedEvidence = MergeEvidence(emittedEvidence,
                                    TraverseDetachedExternalCallbacks(member, callbacks, callee, callbackCall,
                                        rootType, operationId, active, lifecycle));

                                continue;
                            }

                            if (method.MethodKind == MethodKind.DelegateInvoke && member.Model.GetSymbolInfo(callbacks[0]).Symbol is { } callable && IsProvenAbsentCallable(callable))
                            {
                                continue;
                            }

                            if (method.MethodKind == MethodKind.DelegateInvoke && member.Model.GetSymbolInfo(callbacks[0]).Symbol is { } invoked && member.AbsentCallables?.Contains(invoked) == true)
                            {
                                continue;
                            }

                            if (IsReviewedHostedTaskCallbackTransfer(
                                member,
                                callbackCall))
                            {
                                foreach (ExpressionSyntax callback in callbacks)
                                {
                                    foreach (AuthoredMember body in ResolveCallableTargets(
                                        callback,
                                        member.Model,
                                        member.CallableBindings,
                                        member.AbsentCallables))
                                    {
                                        emittedEvidence = MergeEvidence(
                                            emittedEvidence,
                                            Traverse(
                                                WithoutInheritedAdmission(body),
                                                rootType,
                                                operationId
                                                    + "/callback@"
                                                    + Location(callbackCall),
                                                active,
                                                lifecycle,
                                                inheritedWork: null,
                                                inheritedEffect: null,
                                                completionOwned: true,
                                                recoveryEffect: null));
                                    }
                                }

                                continue;
                            }

                            if (IsReviewedTrackedTaskHandoff(
                                member,
                                callbackCall))
                            {
                                foreach (ExpressionSyntax callback in callbacks)
                                {
                                    foreach (AuthoredMember body in ResolveCallableTargets(
                                        callback,
                                        member.Model,
                                        member.CallableBindings,
                                        member.AbsentCallables))
                                    {
                                        AuthoredMember ownedBody = WithoutInheritedAdmission(
                                            body with
                                            {
                                                AdmissionBindings = member.AdmissionBindings,
                                                CallableBindings = member.CallableBindings,
                                                AbsentCallables = member.AbsentCallables,
                                                ConcreteBindings = member.ConcreteBindings,
                                                RecoveryBindings = member.RecoveryBindings,
                                                RecoveryContext = member.RecoveryContext,
                                                ValueBindings = member.ValueBindings,
                                            });

                                        emittedEvidence = MergeEvidence(
                                            emittedEvidence,
                                            Traverse(
                                                ownedBody,
                                                rootType,
                                                operationId
                                                    + "/callback@"
                                                    + Location(callbackCall),
                                                active,
                                                lifecycle,
                                                inheritedWork: null,
                                                inheritedEffect: null,
                                                completionOwned: true,
                                                recoveryEffect: null));
                                    }
                                }

                                continue;
                            }

                            if (TryHostHandoff(member, callbackCall) is { } handoff)
                            {
                                // A host-owned task transfers to an independently admitted root, never its caller's handles.
                                emittedEvidence = MergeEvidence(emittedEvidence, Traverse(
                                    handoff.Target,
                                    rootType,
                                    handoff.Root.OperationId,
                                    active,
                                    lifecycle,
                                    selection: handoff.Selection));

                                continue;
                            }

                            if (TrySelfAdmittedTaskHandoff(member, callbackCall) is { } selfAdmitted)
                            {
                                emittedEvidence = MergeEvidence(emittedEvidence, Traverse(selfAdmitted.Target, rootType, selfAdmitted.Root.OperationId, active, lifecycle));

                                continue;
                            }

                            bool awaitableReturn = TypeKey(method.ReturnType) is "System.Threading.Tasks.Task" or "System.Threading.Tasks.Task`1" or "System.Threading.Tasks.ValueTask" or "System.Threading.Tasks.ValueTask`1";

                            SyntaxNode? completion = awaitableReturn ? CompletionPoint(member, callbackCall, completionOwned) : lazyCallback ? LazyCompletionPoint(member, callbackCall) : synchronousCallback ? callbackCall : null;

                            // A lazy operator runs its callbacks on every MoveNext of its consumer, so a consuming loop is judged at
                            // its operand, its back-edge and its end, exactly as a lazy iterator result is.
                            int?[] completionPositions = completion is not null && lazyCallback
                                ? LazyConsumptionPositions(completion)
                                : [null];

                            string? completionWork = completion is null
                                ? null
                                : CommonFrontier(completionPositions.Select(completionPosition => WorkAt(
                                    member,
                                    completion,
                                    operationId,
                                    ordinary?.WorkKind,
                                    inheritedWork,
                                    completionPosition)));

                            string? completionEffect = completion is null
                                ? null
                                : CommonFrontier(completionPositions.Select(completionPosition => EffectAt(
                                    member,
                                    completion,
                                    operationId,
                                    inheritedEffect,
                                    completionPosition)));

                            bool owned = knownCallback
                                && completion is not null
                                && completionWork == workAdmitted
                                && completionEffect == effectGroup;

                            foreach (ExpressionSyntax callback in callbacks)
                            {
                                AuthoredMember[] bodies = ResolveCallableTargets(
                                    callback,
                                    member.Model,
                                    member.CallableBindings,
                                    member.AbsentCallables);

                                bool everyBodyOwned = bodies.Length != 0;

                                TraversalEvidence callbackEvidence = TraversalEvidence.NoEvidence;

                                if (bodies.Length == 0
                                    && member.Model.GetSymbolInfo(callback).Symbol
                                        is IMethodSymbol externalCallback)
                                {
                                    string callbackCallee = Normalize(
                                        externalCallback);

                                    HostedProducerSiteKind? callbackKind = Classify(
                                        externalCallback,
                                        callbackCallee,
                                        callback,
                                        member);

                                    if (callbackKind is { } externalKind)
                                    {
                                        everyBodyOwned = owned;

                                        callbackEvidence = AddSite(
                                            externalKind,
                                            callbackCallee,
                                            member,
                                            rootType,
                                            operationId,
                                            callback,
                                            owned ? effectGroup : null,
                                            owned ? workAdmitted : null);

                                        emittedEvidence = MergeEvidence(
                                            emittedEvidence,
                                            callbackEvidence);
                                    }
                                    else if (RequiresExternalBoundaryClassification(
                                        externalCallback,
                                        member.Model.Compilation,
                                        callback,
                                        member.Model,
                                        member))
                                    {
                                        RefuseTraversalCompletion();

                                        diagnostics.Add(new(
                                            "HOSTED_SITE_UNCLASSIFIED",
                                            Location(callback),
                                            callbackCallee));
                                    }
                                }

                                foreach (AuthoredMember body in bodies)
                                {
                                    bool callbackOwned = owned
                                        && (body.Symbol.IsAsync != true
                                            || awaitableReturn && !body.Symbol.ReturnsVoid);

                                    everyBodyOwned &= callbackOwned;

                                    AuthoredMember invokedBody =
                                        method.MethodKind == MethodKind.DelegateInvoke
                                            ? NormalizeEvaluationCallableTarget(
                                                BindResolvedCallableInvocationContext(
                                                    member,
                                                    callbackCall,
                                                    body))
                                            : body;

                                    AuthoredMember capturedBody =
                                        BindStableCapturedCleanupContext(
                                            member,
                                            callback,
                                            invokedBody);

                                    AuthoredMember callbackBody = callbackOwned
                                        ? capturedBody with
                                        {
                                            AdmissionBindings = MergeAdmissionBindings(
                                                member.AdmissionBindings,
                                                capturedBody.AdmissionBindings),
                                        }
                                        : capturedBody with { ReadinessSource = null };

                                    TraversalEvidence bodyEvidence = Traverse(callbackBody, rootType, operationId + "/callback@" + Location(callbackCall) + "/body@" + Location(callback), active, lifecycle, callbackOwned ? workAdmitted : null, callbackOwned ? effectGroup : null, completionOwned: callbackOwned, recoveryEffect: callbackOwned ? recoveryEffect : null);

                                    callbackEvidence = MergeEvidence(
                                        callbackEvidence,
                                        bodyEvidence);

                                    emittedEvidence = MergeEvidence(emittedEvidence, bodyEvidence);
                                }

                                if (IsExactSinglePredicateDelegateInvoke(method)
                                    && IsEffectFreeExternalCallable(callback, member)
                                    && (member.Model.GetOperation(callbackCall) is not IInvocationOperation singlePredicateInvocation
                                        || !singlePredicateInvocation.Arguments.All(argument => HasReviewedValueConversions(argument.Value, member))))
                                {
                                    RefuseTraversalCompletion();

                                    diagnostics.Add(new(
                                        "HOSTED_SITE_UNCLASSIFIED",
                                        Location(callbackCall),
                                        callee));
                                }

                                if (!everyBodyOwned
                                    && !IsEffectFreeExternalCallable(callback, member)
                                    && (bodies.Length == 0
                                        || callbackEvidence != TraversalEvidence.NoEvidence
                                        || bodies.Any(HasAdmissionSeed))
                                    && !IsReviewedBoundedOsCredentialRead(
                                        member,
                                        callbackCall,
                                        callbackEvidence,
                                        bodies))
                                {
                                    string reason = completion is null
                                        ? "no exact completion observation"
                                        : completionWork != workAdmitted
                                            ? "work admission does not survive to completion"
                                            : completionEffect != effectGroup
                                                ? "effect admission does not survive to completion"
                                                : bodies.Length == 0
                                                    ? "callback target is not exact"
                                                    : "callback body cannot inherit this completion";

                                    RefuseTraversalCompletion();

                                    diagnostics.Add(new("HOSTED_CALLBACK_OWNERSHIP_UNPROVEN", operationId + "/callback@" + Location(callbackCall), callee + "; Callback execution must bind once and complete before its inherited admission lifetime ends; " + reason + "."));
                                }
                            }

                            continue;
                        }

                        if (method.Name is "Dispose" or "DisposeAsync" && node is InvocationExpressionSyntax { Expression: MemberAccessExpressionSyntax access } && member.Model.GetTypeInfo(access.Expression).Type is { } receiver && TypeKey(receiver) is "RetroDownfall.Arcanum.Core.Storage.EncryptedBlobWriter" or "System.IO.StreamWriter")
                        {
                            callee = TypeKey(receiver) + "." + method.Name;
                        }

                        bool aggregate = AggregateBoundaries.Contains(callee);

                        HostedProducerSiteKind? kind = Classify(
                            method,
                            callee,
                            node,
                            member);

                        if (kind == HostedProducerSiteKind.DatabaseAccess
                            && !ReviewedProviderMemberIsClosed(method, node, member.Model, member))
                        {
                            // The access is real whatever the receiver is, and is reported below. What the receiver may
                            // hold behind the framework wrapper is code no traversal reaches.
                            RefuseTraversalCompletion();

                            diagnostics.Add(new(
                                "HOSTED_CALL_TARGET_UNRESOLVED",
                                Location(node),
                                callee + "; The receiver can be an authored subclass of the provider type, whose overrides this call would run."));
                        }

                        if (kind is not null && !aggregate)
                        {
                            if (node is InvocationExpressionSyntax lazyRead && IsLazyDirectoryEnumeration(callee))
                            {
                                SyntaxNode? consumption = LazyCompletionPoint(member, lazyRead);

                                bool ownedByIteratorConsumer = consumption is null && completionOwned && IsIteratorMember(member);

                                string? consumedWork = ownedByIteratorConsumer
                                    ? workAdmitted
                                    : consumption is null
                                        ? null
                                        : CommonFrontier(LazyConsumptionPositions(consumption).Select(consumedPosition => WorkAt(member, consumption, operationId, ordinary?.WorkKind, inheritedWork, consumedPosition)));

                                if ((!ownedByIteratorConsumer && consumption is null) || consumedWork != workAdmitted)
                                {
                                    RefuseTraversalCompletion();

                                    diagnostics.Add(new("HOSTED_CALLBACK_OWNERSHIP_UNPROVEN", RootOperation(operationId) + "/call@" + Location(node), callee + "; A lazy filesystem sequence must be consumed synchronously before its work lease ends."));

                                    workAdmitted = null;
                                }
                            }

                            if (node is InvocationExpressionSyntax sensitiveCall && IsAwaitable(method.ReturnType) && CompletionPoint(member, sensitiveCall, completionOwned) is null)
                            {
                                RefuseTraversalCompletion();

                                diagnostics.Add(new("HOSTED_CALLBACK_OWNERSHIP_UNPROVEN", RootOperation(operationId) + "/call@" + Location(node), callee + "; An awaitable sensitive boundary must complete before its retained admission lifetime ends."));

                                workAdmitted = null;

                                effectGroup = null;
                            }

                            emittedEvidence = MergeEvidence(emittedEvidence, AddSite(kind.Value, callee, member, rootType, operationId, node, effectGroup, workAdmitted));

                            // An EF operation raises the callbacks of the interceptors registered on its context.
                            if (kind == HostedProducerSiteKind.DatabaseAccess && node is InvocationExpressionSyntax efCall
                                && InterceptionOf(method.ReducedFrom ?? method) != EfInterception.None)
                            {
                                emittedEvidence = MergeEvidence(
                                    emittedEvidence,
                                    TraverseEfOperationCallbacks(member, efCall, method.ReducedFrom ?? method, callee, rootType, operationId, active, lifecycle, workAdmitted, effectGroup, recoveryEffect));
                            }
                            else if (kind == HostedProducerSiteKind.DatabaseAccess
                                && node is InvocationExpressionSyntax or BaseObjectCreationExpressionSyntax
                                && ClassifyEfQueryCall(member, node, method, out List<ExpressionSyntax> queryOperands) == EfQueryCall.Terminal)
                            {
                                emittedEvidence = MergeEvidence(
                                    emittedEvidence,
                                    TraverseEfQueryCallbacks(member, node, queryOperands, method.ReducedFrom ?? method, callee, rootType, operationId, active, lifecycle, workAdmitted, effectGroup, recoveryEffect));
                            }
                            else if (kind == HostedProducerSiteKind.DatabaseAccess
                                && node is InvocationExpressionSyntax
                                && IsConnectionStateChangingCall(method))
                            {
                                // The connection raises StateChange inside this call, so its handlers run under the frontiers live here.
                                emittedEvidence = MergeEvidence(
                                    emittedEvidence,
                                    TraverseConnectionStateHandlers(node, callee, rootType, operationId, active, lifecycle, workAdmitted, effectGroup, recoveryEffect));
                            }
                        }

                        if (node is InvocationExpressionSyntax recoveryCall
                            && method.Name == "RecoverAsync"
                            && IsExactAuthoredProtocolType(
                                method.ContainingType,
                                "RetroDownfall.Arcanum.Core.Operations.ILongRunningOperationRecoveryHandler",
                                member.Model.Compilation))
                        {
                            emittedEvidence = MergeEvidence(
                                emittedEvidence,
                                TraverseRecoveryDispatch(
                                    member,
                                    recoveryCall,
                                    method,
                                    rootType,
                                    operationId,
                                    active,
                                    lifecycle,
                                    workAdmitted,
                                    recoveryEffect));

                            continue;
                        }

                        if (node is InvocationExpressionSyntax authenticatedRecoveryCall
                            && method.Name == "RecoverAuthenticatedAsync"
                            && IsExactAuthoredProtocolType(
                                method.ContainingType,
                                "RetroDownfall.Arcanum.Infrastructure.Data.IAuthenticatedCovenantErasureRecoveryHandler",
                                member.Model.Compilation))
                        {
                            emittedEvidence = MergeEvidence(
                                emittedEvidence,
                                TraverseAuthenticatedRecoveryDispatch(
                                    member,
                                    authenticatedRecoveryCall,
                                    method,
                                    rootType,
                                    operationId,
                                    active,
                                    lifecycle));

                            continue;
                        }

                        AuthoredMember? target = node is InvocationExpressionSyntax sdkFactoryCall
                            ? ResolveLongRestSdkFactoryTarget(method, member, sdkFactoryCall, new CleanupProvenanceContext())
                                ?? ResolveInvocationTarget(method, member, node)
                            : ResolveInvocationTarget(method, member, node);

                        AuthoredMember[] boundTargets = target is null
                            ? ResolveBoundImplementations(method, member.Model.Compilation)
                            : [];

                        AuthoredMember[] strategyTargets = ResolveStrategyTargets(method);

                        AuthoredMember[] reviewedClosedTargets =
                            ResolveReviewedClosedDispatchTargets(
                                method,
                                node,
                                member);

                        if (callee == "RetroDownfall.Arcanum.Infrastructure.Data.Schema.IGrimoireSchemaBackfill.AdvanceBatchAsync" && strategyTargets.Length != SchemaBackfillStrategies.Count)
                        {
                            RefuseTraversalCompletion();

                            diagnostics.Add(new("HOSTED_STRATEGY_BINDING_UNRESOLVED", Location(node), callee + "; Every configured concrete strategy must bind exactly once."));
                        }

                        bool unresolvedAuthoredTarget = target is null
                            && boundTargets.Length == 0
                            && strategyTargets.Length == 0
                            && reviewedClosedTargets.Length == 0
                            && HasAuthoredTarget(method);

                        if (kind is null
                            && target is null
                            && !callee.StartsWith("<ambiguous:", StringComparison.Ordinal)
                            && RequiresExternalBoundaryClassification(
                                method,
                                member.Model.Compilation,
                                node,
                                member.Model,
                                member))
                        {
                            RefuseTraversalCompletion();

                            diagnostics.Add(new("HOSTED_SITE_UNCLASSIFIED", Location(node), callee));
                        }

                        if (node is InvocationExpressionSyntax handleCall && !IsCompletionCombinator(method) && (AdmissionArguments(member, handleCall).Any(argument => argument.Expression is not DeclarationExpressionSyntax && MayCarryAdmissionHandle(member, argument.Expression) && (argument.RefKind is RefKind.Ref or RefKind.Out || target is null && boundTargets.Length == 0 && reviewedClosedTargets.Length == 0))
                            || AdmissionReceiver(member, handleCall) is { } receiverExpression && MayCarryAdmissionHandle(member, receiverExpression) && !PreservesAdmissionReceiver(method) && !ConsumesAdmissionReceiver(method)
                                && target?.ScopedLeaseInstance?.ContinuationProven != true))
                        {
                            RefuseTraversalCompletion();

                            diagnostics.Add(new("HOSTED_ADMISSION_HANDLE_ESCAPE", operationId + "/call@" + Location(node), callee + "; A retained handle passed by ref/out or to an opaque callee has no proven lifetime continuation."));
                        }

                        if (target?.Symbol.GetAttributes().Any(static attribute => attribute.AttributeClass?.Name == "GrimoireConnectionAcquisitionRouteAttribute") == true && kind is null)
                        {
                            emittedEvidence = MergeEvidence(emittedEvidence, AddSite(HostedProducerSiteKind.OrdinaryConnectionRoute, Normalize(target.Symbol), member, rootType, operationId, node, effectGroup, workAdmitted));

                            kind = HostedProducerSiteKind.OrdinaryConnectionRoute;
                        }

                        if (kind is null
                            || aggregate
                            || TransparentProducerBoundaries.Contains(callee))
                        {
                            // A virtual or abstract method of a class the source declares runs the override of the runtime type of
                            // its receiver, not the body of the slot the call names.
                            AccessorDispatch? classDispatch = strategyTargets.Length == 0 && boundTargets.Length == 0 && reviewedClosedTargets.Length == 0
                                ? ClassMethodDispatch(member, method, node)
                                : null;

                            AuthoredMember[] targets = strategyTargets.Length != 0
                                ? strategyTargets
                                : classDispatch is { } dispatched
                                    ? [.. dispatched.Targets]
                                    : target is not null
                                        ? [target]
                                        : boundTargets.Length != 0
                                            ? boundTargets
                                            : reviewedClosedTargets;

                            if (classDispatch is { Unresolved: true })
                            {
                                RefuseTraversalCompletion();

                                diagnostics.Add(new("HOSTED_CALL_TARGET_UNRESOLVED", Location(node), callee));
                            }

                            if (target is null && boundTargets.Length != 0
                                && HasIncompleteDefaultInterfaceBinding(method, member.Model.Compilation))
                            {
                                RefuseTraversalCompletion();

                                diagnostics.Add(new("HOSTED_CALL_TARGET_UNRESOLVED", Location(node), callee));
                            }

                            if (targets.Length != 0)
                            {
                                SyntaxNode? directCompletion = node is InvocationExpressionSyntax invocation
                                    ? CompletionPoint(member, invocation, completionOwned) : null;

                                bool directlyJoined = directCompletion is not null;

                                TraversalEvidence targetEvidence = TraversalEvidence.NoEvidence;

                                foreach (AuthoredMember exactTarget in targets)
                                {
                                    // A lease-carried awaited call to a declared handoff root re-roots under that root's operation id and
                                    // canonical Work, so the root's closure is judged once, under its own budget.
                                    if (node is InvocationExpressionSyntax handoffCall
                                        && TryLeaseHandoff(member, handoffCall, exactTarget, targets.Length, rootType, operationId, ordinary, workAdmitted, effectGroup, recoveryEffect) is { } handoffEdge)
                                    {
                                        TraversalEvidence handoffEvidence = MergeEvidence(
                                            Traverse(handoffEdge.Root.Member, handoffEdge.Root.RootType, handoffEdge.Root.Entry.OperationId, active, false, handoffEdge.Root.Work, null, handoffEdge.Root.Selection),
                                            AddSite(HostedProducerSiteKind.LeaseHandoff, handoffEdge.Root.Entry.OperationId, member, rootType, operationId, node, null, workAdmitted));

                                        targetEvidence = MergeEvidence(targetEvidence, handoffEvidence);

                                        emittedEvidence = MergeEvidence(emittedEvidence, handoffEvidence);

                                        continue;
                                    }

                                    bool hostedTaskTransfer =
                                        node is InvocationExpressionSyntax hostedTaskCall
                                        && IsReviewedHostedTaskTransfer(
                                            member,
                                            hostedTaskCall,
                                            exactTarget);

                                    bool joined = directlyJoined
                                        || node is InvocationExpressionSyntax ownedCall
                                            && IsReviewedOwnedCompletionTransfer(
                                                member,
                                                ownedCall,
                                                exactTarget)
                                        || hostedTaskTransfer;

                                    IReadOnlySet<int>? carrier = node is InvocationExpressionSyntax call ? VerifyFieldPublication(member, call, exactTarget, operationId, inheritedEffect) : null;

                                    string? nextRecoveryEffect = recoveryEffect;

                                    if (node is InvocationExpressionSyntax recoveryEntry
                                        && exactTarget.Symbol.Name == "SettleDiscoveredRuntimeAsync"
                                        && TypeKey(exactTarget.Symbol.ContainingType)
                                            == "RetroDownfall.Arcanum.Infrastructure.Operations.LongRunningOperationReconciler")
                                    {
                                        nextRecoveryEffect = RecoveryEffectFrontierAt(
                                            member,
                                            recoveryEntry,
                                            operationId,
                                            workAdmitted);
                                    }

                                    SyntaxNode? lazyCompletion = node is InvocationExpressionSyntax lazyCall && IsLazySequence(exactTarget.Symbol.ReturnType) ? LazyCompletionPoint(member, lazyCall) : null;

                                    (SyntaxNode Site, int Position)? scopedConsumption = lazyCompletion is null && node is InvocationExpressionSyntax scopedCall && IsLazySequence(exactTarget.Symbol.ReturnType)
                                        ? ScopedEnumeratorConsumption(member, scopedCall) : null;

                                    bool lazyOwned = lazyCompletion is not null
                                            && LazyConsumptionPositions(lazyCompletion).All(lazyPosition => WorkAt(member, lazyCompletion, operationId, ordinary?.WorkKind, inheritedWork, lazyPosition) == workAdmitted && EffectAt(member, lazyCompletion, operationId, inheritedEffect, lazyPosition) == effectGroup)
                                        || scopedConsumption is { } scoped
                                            && WorkAt(member, scoped.Site, operationId, ordinary?.WorkKind, inheritedWork, scoped.Position) == workAdmitted
                                            && EffectAt(member, scoped.Site, operationId, inheritedEffect, scoped.Position) == effectGroup;

                                    // An iterator that returns an enumerator runs its body on the MoveNext calls that follow. That is owned only
                                    // by the enumeration of the loop that called the provider returning it; anywhere else it is unowned.
                                    bool lazyEnumerator = node is InvocationExpressionSyntax && IsLazyEnumerator(exactTarget.Symbol.ReturnType) && IsIteratorMember(exactTarget);

                                    if (lazyEnumerator && OwnsLazyEnumeratorCall(node))
                                    {
                                        lazyOwned = true;
                                    }

                                    bool detached = IsAwaitable(exactTarget.Symbol.ReturnType) && !joined || IsLazySequence(exactTarget.Symbol.ReturnType) && !lazyOwned || lazyEnumerator && !lazyOwned;

                                    // An asynchronous sequence's body runs where it is consumed. When no consumption can be proven, the
                                    // body is traversed with no frontier, and the refusal is owed only if that traversal finds a site.
                                    bool deferredAsyncRefusal = detached && IsAsyncSequence(exactTarget.Symbol.ReturnType) && !IsAwaitable(exactTarget.Symbol.ReturnType);

                                    SyntaxNode? targetCompletion = IsAwaitable(exactTarget.Symbol.ReturnType) ? directCompletion
                                        : IsLazySequence(exactTarget.Symbol.ReturnType) ? lazyCompletion ?? scopedConsumption?.Site : node;

                                    if (detached && !deferredAsyncRefusal)
                                    {
                                        RefuseTraversalCompletion();

                                        diagnostics.Add(new("HOSTED_CALLBACK_OWNERSHIP_UNPROVEN", operationId + "/call@" + Location(node), callee + "; An awaitable or lazy helper must complete within its caller's retained lifetime."));
                                    }

                                    AuthoredMember boundTarget = node switch
                                    {
                                        InvocationExpressionSyntax boundCall when IsLongRestSdkSetupDependency(exactTarget)
                                            || IsExactLongRestHttpFactoryMethod(method) && IsLongRestSdkSetupDependency(member) =>
                                            BindCleanupInvocationContext(member, boundCall, exactTarget, new CleanupProvenanceContext()),
                                        InvocationExpressionSyntax boundCall =>
                                            BindInvocationContext(
                                                member,
                                                boundCall,
                                                exactTarget),
                                        BaseObjectCreationExpressionSyntax creation =>
                                            BindConstructorArguments(
                                                member,
                                                creation,
                                                exactTarget),
                                        _ => exactTarget,
                                    };

                                    if (hostedTaskTransfer)
                                    {
                                        boundTarget = WithoutInheritedAdmission(boundTarget);
                                    }

                                    AuthoredMember[] receiverTargets = node is InvocationExpressionSyntax cleanupCall
                                        ? ExactSelectedCleanupInvocationTargets(member, cleanupCall, exactTarget, boundTarget)
                                        : [boundTarget];

                                    foreach (AuthoredMember receiverTarget in receiverTargets)
                                    {
                                        AuthoredMember entryReceiver = node is InvocationExpressionSyntax recoveryEntryCall
                                            ? BindPerUnitReconcilerEntryContext(member, recoveryEntryCall, receiverTarget,
                                                rootType, operationId, detached || hostedTaskTransfer ? null : workAdmitted)
                                            : receiverTarget;

                                        if (node is InvocationExpressionSyntax readinessCall)
                                        {
                                            entryReceiver = BindReadinessReconcilerSource(member, readinessCall,
                                                entryReceiver, operationId, detached || hostedTaskTransfer);
                                        }

                                        AuthoredMember selectedReceiver = member.RecoveryContext is
                                            { Disposition: RecoveryDisposition.OrdinaryPerUnitExternalEffect }
                                            && node is InvocationExpressionSyntax perUnitCall
                                            ? BindPerUnitRecoveryReceiverContext(member, perUnitCall,
                                                entryReceiver, entryReceiver, rootType, operationId,
                                                detached || hostedTaskTransfer ? null : workAdmitted,
                                                detached || hostedTaskTransfer, targetCompletion)
                                            : entryReceiver;

                                        selectedReceiver = PreservePerUnitReconcilerFieldContext(member, node, selectedReceiver);

                                        if (node is InvocationExpressionSyntax ordinaryCall)
                                        {
                                            selectedReceiver = BindOrdinaryScopedHolderInvocation(member, ordinaryCall,
                                                selectedReceiver, rootType, operationId, ordinary?.WorkKind,
                                                workAdmitted, detached || hostedTaskTransfer);
                                        }

                                        // The selected lease body is visible, but this small bridge does
                                        // not lend its instance authority through another callee boundary.
                                        bool leaseBoundary = member.ScopedLeaseInstance is not null;

                                        if (leaseBoundary) RefuseTraversalCompletion();

                                        TraversalEvidence exactEvidence = Traverse(selectedReceiver, rootType, operationId + "/call@" + Location(node), active, lifecycle, detached || hostedTaskTransfer || leaseBoundary ? null : workAdmitted, detached || hostedTaskTransfer || leaseBoundary ? null : effectGroup, fieldPublications: carrier, completionOwned: joined || lazyOwned, recoveryEffect: detached || hostedTaskTransfer || leaseBoundary ? null : nextRecoveryEffect);

                                        targetEvidence = MergeEvidence(targetEvidence, exactEvidence);

                                        emittedEvidence = MergeEvidence(emittedEvidence, exactEvidence);

                                        if (deferredAsyncRefusal && exactEvidence != TraversalEvidence.NoEvidence)
                                        {
                                            RefuseTraversalCompletion();

                                            diagnostics.Add(new("HOSTED_CALLBACK_OWNERSHIP_UNPROVEN", operationId + "/call@" + Location(node), callee + "; An awaitable or lazy helper must complete within its caller's retained lifetime."));
                                        }
                                    }
                                }

                                if (AggregateBoundaries.Contains(callee) && targetEvidence == TraversalEvidence.NoEvidence)
                                {
                                    RefuseTraversalCompletion();

                                    diagnostics.Add(new("HOSTED_AGGREGATE_PROOF_MISSING", operationId + "/call@" + Location(node), "The exact bound aggregate target set produced no executable site evidence; prose is not a proof."));
                                }

                                if (TransparentProducerBoundaries.Contains(callee)
                                    && (!ownedTransparentCallbackCarrier
                                        || targetEvidence == TraversalEvidence.NoEvidence))
                                {
                                    RefuseTraversalCompletion();

                                    diagnostics.Add(new(
                                        "HOSTED_CALLBACK_OWNERSHIP_UNPROVEN",
                                        operationId + "/callback@" + Location(node),
                                        callee + "; A long-lived callback boundary must publish one disposable owner and expose its concrete activation under the same work frontier."));
                                }
                            }
                            else if (aggregate)
                            {
                                RefuseTraversalCompletion();

                                diagnostics.Add(new("HOSTED_AGGREGATE_PROOF_MISSING", Location(node), callee));
                            }
                            else if ((unresolvedAuthoredTarget || method.ContainingType.TypeKind == TypeKind.Interface && method.ContainingNamespace.ToDisplayString().StartsWith("RetroDownfall.", StringComparison.Ordinal) || method.ContainingType.TypeKind == TypeKind.Interface && method.ContainingType.Locations.Any(static location => location.IsInSource))
                                && !IsReviewedEffectFreeExternalMember(
                                    method,
                                    node,
                                    member.Model))
                            {
                                RefuseTraversalCompletion();

                                diagnostics.Add(new("HOSTED_CALL_TARGET_UNRESOLVED", Location(node), callee));
                            }
                        }
                    }
                    else if (symbol is IPropertySymbol property)
                    {
                        IPropertyReferenceOperation? propertyReference =
                            member.Model.GetOperation(node)
                                as IPropertyReferenceOperation;

                        (bool reads, bool writes, ExpressionSyntax? assignedValue) =
                            PropertyAccessorModes(propertyReference, node);

                        int? accessorPosition = member.ScopedLeaseInstance is not null
                            ? assignedValue?.Span.End ?? node.Span.End : null;

                        string? workAdmitted = WorkAt(member, node, operationId, ordinary?.WorkKind, inheritedWork, accessorPosition);

                        string? effectGroup = EffectAt(member, node, operationId, inheritedEffect, accessorPosition);

                        string callee = Normalize(property);

                        if (node is MemberAccessExpressionSyntax access && member.Model.GetTypeInfo(access.Expression).Type is { } receiver && TypeKey(receiver) == "System.IO.FileInfo")
                        {
                            callee = "System.IO.FileInfo." + property.Name;
                        }

                        string setter = callee + " setter";

                        bool propertyMutation = writes;

                        if (propertyMutation
                            && DetachedExternalCallbackProperties.Contains(setter)
                            && node.Parent is AssignmentExpressionSyntax callbackAssignment)
                        {
                            emittedEvidence = MergeEvidence(
                                emittedEvidence,
                                TraverseDetachedExternalCallbacks(
                                    member,
                                    [callbackAssignment.Right],
                                    callee,
                                    node,
                                    rootType,
                                    operationId,
                                    active,
                                    lifecycle));
                        }

                        if (!propertyMutation
                            && TypeKey(property.ContainingType) == "System.Lazy`1"
                            && property.Name == "Value"
                            && node is MemberAccessExpressionSyntax lazyValue)
                        {
                            if (IsProvenCreatedLazyRead(member, lazyValue))
                            {
                                continue;
                            }

                            LazyFactoryResolution? resolution = ResolveLazyFactory(
                                member,
                                lazyValue.Expression);

                            if (resolution is null)
                            {
                                RefuseTraversalCompletion();

                                diagnostics.Add(new(
                                    "HOSTED_SITE_UNCLASSIFIED",
                                    Location(node),
                                    callee));

                                continue;
                            }

                            BoundedDataProof boundedData = ProveBoundedLazyData(
                                resolution);

                            if (boundedData == BoundedDataProof.PureBoundedData)
                            {
                                continue;
                            }

                            if (boundedData == BoundedDataProof.Unknown)
                            {
                                RefuseTraversalCompletion();

                                diagnostics.Add(new(
                                    "HOSTED_SITE_UNCLASSIFIED",
                                    Location(node),
                                    callee));

                                continue;
                            }

                            TraversalEvidence factoryEvidence = Traverse(
                                resolution.Factory,
                                rootType,
                                operationId
                                    + "/lazy@"
                                    + Location(node),
                                active,
                                lifecycle,
                                workAdmitted,
                                effectGroup,
                                completionOwned: true,
                                recoveryEffect: recoveryEffect);

                            emittedEvidence = MergeEvidence(
                                emittedEvidence,
                                factoryEvidence);

                            if ((workAdmitted is null
                                    && !HasAdmissionSeed(resolution.Factory))
                                || HasEscapingDeferredWork(
                                    resolution.Factory,
                                    new HashSet<GraphMemberIdentity>()))
                            {
                                RefuseTraversalCompletion();

                                diagnostics.Add(new(
                                    "HOSTED_CALLBACK_OWNERSHIP_UNPROVEN",
                                    RootOperation(operationId)
                                        + "/lazy@"
                                        + Location(node),
                                    "System.Lazy`1..ctor; A deferred factory must execute under the consumer's retained admission or reacquire its own. Proof evidence: "
                                        + string.Join(
                                            ", ",
                                            boundedLazyDataEvidence.GetValueOrDefault(
                                                resolution.Storage)
                                                ?? [])));
                            }

                            continue;
                        }

                        if (!propertyMutation && IsEfDbSetType(property.Type) && node is ExpressionSyntax dbSetRead)
                        {
                            RefuseEscapingEfQuery(member, dbSetRead, callee);
                        }

                        if (!propertyMutation
                            && DbContextFirstUseHooks(member, node, property) is { Count: > 0 } propertyHooks)
                        {
                            // EF runs the context's authored hooks on the first use of its services, which can be a
                            // later consumer of a value read here, so no admission current at this read is inherited.
                            emittedEvidence = MergeEvidence(
                                emittedEvidence,
                                TraverseDbContextHooks(propertyHooks, rootType, operationId, node, active, lifecycle));
                        }

                        HostedProducerSiteKind? externalPropertyKind =
                            IsBootstrapConsoleRedirection(member)
                            && TypeKey(property.ContainingType) == "System.IO.StreamWriter"
                            && property.Name == "AutoFlush"
                            && propertyMutation
                                ? HostedProducerSiteKind.FileSystemEffect
                                : IsExactSqliteBaseReaderProperty(property, propertyMutation, node, member)
                                    ? HostedProducerSiteKind.DatabaseAccess
                                    : TryClassifyExternalProducer(
                                        property,
                                        propertyMutation,
                                        out HostedProducerSiteKind classifiedProperty)
                                            ? classifiedProperty
                                            : null;

                        if (TypeKey(property.ContainingType)
                                == "System.IO.FileSystemWatcher"
                            && property.Name == "EnableRaisingEvents"
                            && node is MemberAccessExpressionSyntax watcherActivation
                            && !HasOwnedFileSystemWatcherLifetime(
                                member,
                                watcherActivation.Expression))
                        {
                            RefuseTraversalCompletion();

                            diagnostics.Add(new(
                                "HOSTED_CALLBACK_OWNERSHIP_UNPROVEN",
                                RootOperation(operationId)
                                    + "/watcher@"
                                    + Location(node),
                                callee
                                    + "; Watcher activation requires one exact disposable lifecycle owner."));
                        }

                        if (propertyMutation
                            && (Vocabulary.ContainsKey(setter)
                                || externalPropertyKind is not null
                                || RequiresExternalBoundaryClassification(
                                    property,
                                    member.Model.Compilation,
                                    mutation: true,
                                    node,
                                    member.Model,
                                    member)))
                        {
                            bool authoredAutoProperty = property.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax() is PropertyDeclarationSyntax { AccessorList.Accessors.Count: > 0 } propertyDeclaration
                                && propertyDeclaration.AccessorList.Accessors.All(static accessor => accessor.Body is null && accessor.ExpressionBody is null);

                            if (Vocabulary.TryGetValue(setter, out HostedProducerSiteKind setterKind))
                            {
                                emittedEvidence = MergeEvidence(emittedEvidence, AddSite(setterKind, setter, member, rootType, operationId, node, effectGroup, workAdmitted));
                            }
                            else if (externalPropertyKind is { } externalSetterKind)
                            {
                                emittedEvidence = MergeEvidence(emittedEvidence, AddSite(externalSetterKind, setter, member, rootType, operationId, node, effectGroup, workAdmitted));
                            }
                            else if (!authoredAutoProperty)
                            {
                                RefuseTraversalCompletion();

                                diagnostics.Add(new("HOSTED_SITE_UNCLASSIFIED", Location(node), setter));
                            }

                            continue;
                        }

                        if (Vocabulary.TryGetValue(callee, out HostedProducerSiteKind kind))
                        {
                            emittedEvidence = MergeEvidence(emittedEvidence, AddSite(kind, callee, member, rootType, operationId, node, effectGroup, workAdmitted));
                        }
                        else if (externalPropertyKind is { } externalGetterKind)
                        {
                            emittedEvidence = MergeEvidence(emittedEvidence, AddSite(externalGetterKind, callee, member, rootType, operationId, node, effectGroup, workAdmitted));
                        }
                        else if (RequiresExternalBoundaryClassification(
                            property,
                            member.Model.Compilation,
                            mutation: false,
                            node,
                            member.Model,
                            member))
                        {
                            RefuseTraversalCompletion();

                            diagnostics.Add(new("HOSTED_SITE_UNCLASSIFIED", Location(node), callee));
                        }

                        (ITypeSymbol? receiverType, ExpressionSyntax? receiverExpression, bool exactReceiver) = AccessorReceiver(propertyReference?.Instance);

                        foreach (IMethodSymbol accessor in new[] { reads ? property.GetMethod : null, writes ? property.SetMethod : null }.OfType<IMethodSymbol>())
                        {
                            AccessorDispatch dispatch = ResolveAccessorDispatch(member, accessor, receiverType, receiverExpression, exactReceiver, property.IsIndexer);

                            foreach (AuthoredMember target in dispatch.Targets)
                            {
                                AuthoredMember boundTarget = propertyReference is null
                                    ? target
                                    : BindPropertyAccessorArguments(
                                        member,
                                        propertyReference,
                                        accessor,
                                        target,
                                        assignedValue);

                                boundTarget = BindReceiverContext(
                                    member,
                                    propertyReference?.Instance is { IsImplicit: false, Syntax: ExpressionSyntax writtenReceiver } ? writtenReceiver : null,
                                    target,
                                    boundTarget);

                                bool leaseBoundary = member.ScopedLeaseInstance is not null;

                                bool sameLease = leaseBoundary
                                    && IsScopedLeaseInstanceOperation(member, propertyReference?.Instance)
                                    && ReferenceEquals(boundTarget.Model.Compilation, member.Model.Compilation)
                                    && SymbolEqualityComparer.Default.Equals(boundTarget.Symbol.ContainingType,
                                        member.ScopedLeaseInstance!.Type);

                                if (leaseBoundary)
                                {
                                    RefuseTraversalCompletion();

                                    // Only compiler-bound access on this exact instance carries
                                    // its origin into the accessor. Its own disposal scan still
                                    // decides authority at each physical site inside the body.
                                    boundTarget = boundTarget with
                                    {
                                        ScopedLeaseInstance = sameLease
                                            ? member.ScopedLeaseInstance! with { ContinuationProven = false }
                                            : null,
                                    };
                                }

                                emittedEvidence = MergeEvidence(emittedEvidence, Traverse(boundTarget, rootType, operationId + (accessor.MethodKind == MethodKind.PropertyGet ? "/get@" : "/set@") + Location(node), active, lifecycle, leaseBoundary && !sameLease ? null : workAdmitted, leaseBoundary && !sameLease ? null : effectGroup, recoveryEffect: leaseBoundary ? null : recoveryEffect));
                            }

                            if (dispatch.Unresolved)
                            {
                                RefuseTraversalCompletion();

                                diagnostics.Add(new(
                                    "HOSTED_CALL_TARGET_UNRESOLVED",
                                    Location(node),
                                    Normalize(accessor)));
                            }
                        }
                    }
                    else if (symbol is IEventSymbol authoredEvent
                        && node.Parent is AssignmentExpressionSyntax authoredMutation
                        && authoredMutation.Left == node
                        && authoredMutation.Kind() is SyntaxKind.AddAssignmentExpression
                            or SyntaxKind.SubtractAssignmentExpression
                        && authoredEvent.Locations.Any(static location => location.IsInSource)
                        && (authoredEvent.DeclaringSyntaxReferences
                                .Select(static reference => reference.GetSyntax())
                                .SingleOrDefault() is EventDeclarationSyntax
                            || (authoredEvent.AddMethod is { } declaredAdd && IsDispatchedMember(declaredAdd))))
                    {
                        bool addsHandler = authoredMutation.IsKind(
                            SyntaxKind.AddAssignmentExpression);

                        IMethodSymbol? accessor = addsHandler
                            ? authoredEvent.AddMethod
                            : authoredEvent.RemoveMethod;

                        string? workAdmitted = WorkAt(
                            member,
                            node,
                            operationId,
                            ordinary?.WorkKind,
                            inheritedWork);

                        string? effectGroup = EffectAt(
                            member,
                            node,
                            operationId,
                            inheritedEffect);

                        (ITypeSymbol? receiverType, ExpressionSyntax? receiverExpression, bool exactReceiver) = AccessorReceiver(
                            member.Model.GetOperation(authoredMutation) is IEventAssignmentOperation { EventReference: IEventReferenceOperation eventReference }
                                ? eventReference.Instance
                                : null);

                        AccessorDispatch dispatch = accessor is null
                            ? new([], true)
                            : ResolveAccessorDispatch(member, accessor, receiverType, receiverExpression, exactReceiver, indexer: false);

                        foreach (AuthoredMember target in dispatch.Targets)
                        {
                            AuthoredMember boundTarget = accessor!.Parameters is
                                [IParameterSymbol handler]
                                    ? BindArguments(
                                        member,
                                        [(authoredMutation.Right, handler, RefKind.None)],
                                        target)
                                    : target;

                            boundTarget = BindReceiverContext(
                                member,
                                receiverExpression,
                                target,
                                boundTarget);

                            bool leaseBoundary = member.ScopedLeaseInstance is not null;

                            if (leaseBoundary)
                            {
                                RefuseTraversalCompletion();

                                // Custom event accessors may retain or execute handlers. Keep
                                // their selected body visible without lending this instance's
                                // origin or inherited authority across that unsupported boundary.
                                boundTarget = boundTarget with { ScopedLeaseInstance = null };
                            }

                            emittedEvidence = MergeEvidence(
                                emittedEvidence,
                                Traverse(
                                    boundTarget,
                                    rootType,
                                    operationId
                                        + (addsHandler ? "/add@" : "/remove@")
                                        + Location(node),
                                    active,
                                    lifecycle,
                                    leaseBoundary ? null : workAdmitted,
                                    leaseBoundary ? null : effectGroup,
                                    recoveryEffect: leaseBoundary ? null : recoveryEffect));
                        }

                        if (dispatch.Unresolved || dispatch.Targets.Count == 0 && authoredEvent.DeclaringSyntaxReferences.Select(static reference => reference.GetSyntax()).SingleOrDefault() is EventDeclarationSyntax)
                        {
                            RefuseTraversalCompletion();

                            diagnostics.Add(new(
                                "HOSTED_CALL_TARGET_UNRESOLVED",
                                Location(node),
                                accessor is null
                                    ? Normalize(authoredEvent)
                                    : Normalize(accessor)));
                        }
                    }
                    else if (symbol is IEventSymbol stateEvent
                        && node.Parent is AssignmentExpressionSyntax stateMutation
                        && stateMutation.Left == node
                        && stateMutation.Kind() is SyntaxKind.AddAssignmentExpression
                            or SyntaxKind.SubtractAssignmentExpression
                        && stateEvent.Locations.All(static location => !location.IsInSource)
                        && IsReviewedConnectionStateWiring(stateEvent))
                    {
                        // Subscribing a handler to DbConnection.StateChange runs none: every handler in the analysed source
                        // is named, and each is entered where a connection changes state (see TraverseConnectionStateHandlers).
                    }
                    else if (symbol is IEventSymbol declaredEvent
                        && node.Parent is AssignmentExpressionSyntax eventMutation
                        && eventMutation.Left == node
                        && eventMutation.Kind() is SyntaxKind.AddAssignmentExpression
                            or SyntaxKind.SubtractAssignmentExpression
                        && declaredEvent.Locations.All(static location => !location.IsInSource))
                    {
                        bool addsHandler = eventMutation.IsKind(
                            SyntaxKind.AddAssignmentExpression);

                        string operation = addsHandler ? " add" : " remove";

                        bool ownedWatcherEvent =
                            TypeKey(declaredEvent.ContainingType)
                                == "System.IO.FileSystemWatcher"
                            && node is MemberAccessExpressionSyntax eventAccess
                            && HasOwnedFileSystemWatcherLifetime(
                                member,
                                eventAccess.Expression);

                        if (!ownedWatcherEvent)
                        {
                            RefuseTraversalCompletion();

                            diagnostics.Add(new(
                                "HOSTED_SITE_UNCLASSIFIED",
                                Location(node),
                                Normalize(declaredEvent) + operation));
                        }

                        if (addsHandler
                            && IsDelegateExpression(
                                member.Model,
                                eventMutation.Right))
                        {
                            AuthoredMember? handler = ResolveCallable(
                                    eventMutation.Right,
                                    member.Model,
                                    member.CallableBindings,
                                    member.AbsentCallables);

                            if (handler is not null)
                            {
                                handler = handler with
                                {
                                    AdmissionBindings = member.AdmissionBindings,
                                    CallableBindings = member.CallableBindings,
                                    AbsentCallables = member.AbsentCallables,
                                    ConcreteBindings = member.ConcreteBindings,
                                    RecoveryBindings = member.RecoveryBindings,
                                    RecoveryContext = member.RecoveryContext,
                                    ValueBindings = member.ValueBindings,
                                };
                            }

                            TraversalEvidence handlerEvidence = handler is null
                                ? TraversalEvidence.Inconclusive
                                : Traverse(
                                    WithoutInheritedAdmission(handler),
                                    rootType,
                                    operationId + "/callback@" + Location(node),
                                    active,
                                    lifecycle,
                                    inheritedWork: null,
                                    inheritedEffect: null,
                                    completionOwned: true,
                                    recoveryEffect: null);

                            emittedEvidence = MergeEvidence(
                                emittedEvidence,
                                handlerEvidence);

                            if (!ownedWatcherEvent
                                || handler is null
                                || handlerEvidence != TraversalEvidence.NoEvidence
                                    && !HasAdmissionSeed(handler))
                            {
                                RefuseTraversalCompletion();

                                diagnostics.Add(new(
                                    "HOSTED_CALLBACK_OWNERSHIP_UNPROVEN",
                                    RootOperation(operationId)
                                        + "/callback@"
                                        + Location(node),
                                    Normalize(declaredEvent)
                                        + "; External event lifetime ownership is not proven."));
                            }
                        }
                    }
                    else if (node is InvocationExpressionSyntax && symbol is null)
                    {
                        RefuseTraversalCompletion();

                        diagnostics.Add(new("HOSTED_CALL_TARGET_UNRESOLVED", Location(node), node.ToString()));
                    }

                    if (node is CommonForEachStatementSyntax or SpreadElementSyntax)
                    {
                        emittedEvidence = MergeEvidence(
                            emittedEvidence,
                            TraverseEnumeration(
                                member,
                                node,
                                rootType,
                                operationId,
                                active,
                                lifecycle,
                                ordinary?.WorkKind,
                                inheritedWork,
                                inheritedEffect,
                                recoveryEffect));
                    }

                    if (node is UsingStatementSyntax { Expression: { } resource } expressionUsing)
                    {
                        string disposeName = expressionUsing.AwaitKeyword.RawKind != 0 ? "DisposeAsync" : "Dispose";

                        ITypeSymbol? resourceType = member.Model.GetTypeInfo(resource).Type;

                        EffectiveCleanupResolution cleanup = resourceType is null
                            ? new(null, [], [], false, false)
                            : ResolveEffectiveCleanup(
                                member,
                                resourceType,
                                resource,
                                disposeName);

                        int exit = expressionUsing.Statement.Span.End - 1;

                        string? retainedWork = WorkAt(member, resource, operationId, ordinary?.WorkKind, inheritedWork, exit, resource);

                        string? retainedEffect = EffectAt(member, resource, operationId, inheritedEffect, exit, resource);

                        if (resourceType?.ToDisplayString() is "System.IO.StreamWriter" or "RetroDownfall.Arcanum.Core.Storage.EncryptedBlobWriter")
                        {
                            emittedEvidence = MergeEvidence(emittedEvidence, AddSite(HostedProducerSiteKind.FileSystemEffect, resourceType.ToDisplayString() + "." + disposeName, member, rootType, operationId, resource, retainedEffect, retainedWork));
                        }
                        else
                        {
                            foreach (AuthoredMember cleanupTarget in cleanup.Targets)
                            {
                                emittedEvidence = MergeEvidence(emittedEvidence, Traverse(cleanupTarget, rootType, operationId + "/dispose@" + Location(resource), active, lifecycle, retainedWork, retainedEffect, completionOwned: expressionUsing.AwaitKeyword.RawKind != 0, recoveryEffect: recoveryEffect));
                            }

                            foreach (ExternalCleanupResolution external in cleanup.ExternalEffects)
                            {
                                emittedEvidence = MergeEvidence(
                                    emittedEvidence,
                                    AddSite(
                                        external.Kind,
                                        external.Callee,
                                        member,
                                        rootType,
                                        operationId,
                                        resource,
                                        retainedEffect,
                                        retainedWork));
                            }

                            if (cleanup.Targets.Count == 0
                                && cleanup.ExternalEffects.Count == 0
                                && resourceType is not null
                                && cleanup.MustResolve
                                && (cleanup.HasAuthoredSource
                                    || AdmissionOrigins(
                                        member,
                                        resource,
                                        new HashSet<ISymbol>(
                                            SymbolEqualityComparer.Default)).Count == 0))
                            {
                                RefuseTraversalCompletion();

                                diagnostics.Add(new(
                                    "HOSTED_DISPOSAL_TARGET_UNRESOLVED",
                                    operationId + "/dispose@" + Location(resource),
                                    resourceType.ToDisplayString()
                                        + "."
                                        + disposeName
                                        + "; Expression disposal must resolve to exactly one compiler-effective authored cleanup."));
                            }

                            emittedEvidence = MergeEvidence(
                                emittedEvidence,
                                TraverseDisposalCallbacks(
                                    member,
                                    resource,
                                    resourceType,
                                    expressionUsing.AwaitKeyword.RawKind != 0,
                                    resource,
                                    rootType,
                                    operationId,
                                    active,
                                    lifecycle,
                                    retainedWork,
                                    retainedEffect,
                                    recoveryEffect));
                        }
                    }

                    if (node is VariableDeclarationSyntax declaration && (declaration.Parent is LocalDeclarationStatementSyntax { UsingKeyword.RawKind: not 0 } || declaration.Parent is UsingStatementSyntax))
                    {
                        ITypeSymbol? type = member.Model.GetTypeInfo(declaration.Type).Type;

                        if (type?.ToDisplayString() is "System.IO.StreamWriter" or "RetroDownfall.Arcanum.Core.Storage.EncryptedBlobWriter")
                        {
                            bool asynchronous = declaration.Parent is LocalDeclarationStatementSyntax { AwaitKeyword.RawKind: not 0 } or UsingStatementSyntax { AwaitKeyword.RawKind: not 0 };

                            int disposeAt = DisposalPosition(declaration);

                            string? disposalGroup = EffectAt(member, declaration, operationId, inheritedEffect, disposeAt, declaration);

                            string? retainedWork = WorkAt(member, declaration, operationId, ordinary?.WorkKind, inheritedWork, disposeAt, declaration);

                            emittedEvidence = MergeEvidence(emittedEvidence, AddSite(HostedProducerSiteKind.FileSystemEffect, type.ToDisplayString() + "." + (asynchronous ? "DisposeAsync" : "Dispose"), member, rootType, operationId, node, disposalGroup, retainedWork));
                        }
                        else if (type is INamedTypeSymbol disposable)
                        {
                            bool asynchronous = declaration.Parent is LocalDeclarationStatementSyntax { AwaitKeyword.RawKind: not 0 } or UsingStatementSyntax { AwaitKeyword.RawKind: not 0 };

                            foreach (VariableDeclaratorSyntax variable in declaration.Variables)
                            {
                                ExpressionSyntax? cleanupResource = variable.Initializer?.Value;

                                EffectiveCleanupResolution cleanup = ResolveEffectiveCleanup(
                                    member,
                                    disposable,
                                    cleanupResource,
                                    asynchronous ? "DisposeAsync" : "Dispose");

                                int position = DisposalPosition(declaration);

                                string? retainedWork = WorkAt(member, declaration, operationId, ordinary?.WorkKind, inheritedWork, position, declaration);

                                string? retainedEffect = EffectAt(member, declaration, operationId, inheritedEffect, position, declaration);

                                foreach (AuthoredMember target in cleanup.Targets)
                                {
                                    emittedEvidence = MergeEvidence(emittedEvidence, Traverse(target, rootType, operationId + "/dispose@" + Location(variable), active, lifecycle, retainedWork, retainedEffect, completionOwned: asynchronous, recoveryEffect: recoveryEffect));
                                }

                                foreach (ExternalCleanupResolution external in cleanup.ExternalEffects)
                                {
                                    emittedEvidence = MergeEvidence(
                                        emittedEvidence,
                                        AddSite(
                                            external.Kind,
                                            external.Callee,
                                            member,
                                            rootType,
                                            operationId,
                                            variable,
                                            retainedEffect,
                                            retainedWork));
                                }

                                if (cleanup.Targets.Count == 0
                                    && cleanup.ExternalEffects.Count == 0
                                    && cleanup.MustResolve
                                    && (cleanupResource is null
                                        || cleanup.HasAuthoredSource
                                        || AdmissionOrigins(
                                            member,
                                            cleanupResource,
                                            new HashSet<ISymbol>(
                                                SymbolEqualityComparer.Default)).Count == 0))
                                {
                                    RefuseTraversalCompletion();

                                    diagnostics.Add(new(
                                        "HOSTED_DISPOSAL_TARGET_UNRESOLVED",
                                        operationId + "/dispose@" + Location(variable),
                                        disposable.ToDisplayString()
                                            + "."
                                            + (asynchronous
                                                ? "DisposeAsync"
                                                : "Dispose")
                                            + "; Declaration disposal must resolve to exactly one compiler-effective authored cleanup."));
                                }

                                if (cleanupResource is not null)
                                {
                                    emittedEvidence = MergeEvidence(
                                        emittedEvidence,
                                        TraverseDisposalCallbacks(
                                            member,
                                            cleanupResource,
                                            disposable,
                                            asynchronous,
                                            variable,
                                            rootType,
                                            operationId,
                                            active,
                                            lifecycle,
                                            retainedWork,
                                            retainedEffect,
                                            recoveryEffect));
                                }
                            }
                        }
                    }
                }

                ValidatePublicationRegions(member, selection ?? member.Syntax, operationId, inheritedEffect, fieldPublications);
            }
            finally
            {
                string metricMember = MethodKey(member.Symbol);

                maximumRecoveryConditionEvaluations[metricMember] = Math.Max(
                    maximumRecoveryConditionEvaluations.GetValueOrDefault(metricMember),
                    recoveryConditionEvaluations.EvaluationCount);

                totalRecoveryConditionEvaluations[metricMember] =
                    totalRecoveryConditionEvaluations.GetValueOrDefault(metricMember)
                    + recoveryConditionEvaluations.EvaluationCount;

                totalRecoveryFeasibilityQueries[metricMember] =
                    totalRecoveryFeasibilityQueries.GetValueOrDefault(metricMember)
                    + recoveryConditionEvaluations.FeasibilityQueries;

                totalRecoveryPlanBuilds[metricMember] =
                    totalRecoveryPlanBuilds.GetValueOrDefault(metricMember)
                    + recoveryConditionEvaluations.PlanBuilds;

                totalRecoveryStructuralInspections[metricMember] =
                    totalRecoveryStructuralInspections.GetValueOrDefault(metricMember)
                    + recoveryConditionEvaluations.StructuralInspections;

                totalRecoveryUnreachableIntervals[metricMember] =
                    totalRecoveryUnreachableIntervals.GetValueOrDefault(metricMember)
                    + recoveryConditionEvaluations.UnreachableIntervals;

                totalRecoveryProbeComparisons[metricMember] =
                    totalRecoveryProbeComparisons.GetValueOrDefault(metricMember)
                    + recoveryConditionEvaluations.ProbeComparisons;

                totalRecoveryParityComparisons[metricMember] =
                    totalRecoveryParityComparisons.GetValueOrDefault(metricMember)
                    + recoveryConditionEvaluations.ParityComparisons;

                totalRecoveryParityMismatches[metricMember] =
                    totalRecoveryParityMismatches.GetValueOrDefault(metricMember)
                    + recoveryConditionEvaluations.ParityMismatches;

                active.Remove(state);
            }

            analyzedStates[state] = emittedEvidence;

            bool complete = traversalCompletion!.Complete;

            completedTraversalStates[state] = complete;

            if (complete && traversalCompletion!.FreshNestedPath && nestedAncestors is not null && !boundedDataProbeEncountered
                && nestedRootCohort is { Eligible: true, Plan.Lifecycle: true } sourceCohort)
            {
                // Only a fresh body reaches this point. Cache hits cannot invent raw provenance.
                sourceCohort.Pending.TryAdd((state, operationId), new(nestedAncestors, emittedEvidence));
            }

            if (wholePlannedRoot && lifecycle && complete)
            {
                completedLifecycleRoots[state] = new(operationId, plannedRoot!.Occurrence, emittedEvidence);
            }

            return emittedEvidence;
        }

        private bool ConversionOperandHasUnsupportedLifetime(AuthoredMember member, IOperation operand, AuthoredMember conversionTarget, CleanupProvenanceContext? sharedProof = null, bool typeInitializationProven = false)
        {
            CleanupProvenanceContext proof = sharedProof ?? new();

            HashSet<GraphMemberIdentity> path = [];

            bool HasInitializationFreeEntry(INamedTypeSymbol type, bool defaultConstruction = false)
            {
                if (type.TypeKind != TypeKind.Class || type.DeclaringSyntaxReferences.IsEmpty) return false;

                if (defaultConstruction && (type.BaseType is not { } baseType
                    || !IsExactFrameworkType(baseType, "System.Object", typeof(object).Assembly.GetName()))) return false;

                foreach (SyntaxReference reference in type.DeclaringSyntaxReferences)
                {
                    if (proof.RemainingWork-- <= 0
                        || reference.GetSyntax() is not TypeDeclarationSyntax declaration
                        || declaration is not ClassDeclarationSyntax
                            && declaration is not RecordDeclarationSyntax { ParameterList: null }
                        || declaration is RecordDeclarationSyntax && (!type.IsRecord || !type.IsSealed)
                        || !semanticModels.TryGetValue(declaration.SyntaxTree, out SemanticModel? model)
                        || !SymbolEqualityComparer.Default.Equals(model.GetDeclaredSymbol(declaration)?.OriginalDefinition,
                            type.OriginalDefinition)) return false;

                    foreach (MemberDeclarationSyntax declared in declaration.Members)
                    {
                        if (proof.RemainingWork-- <= 0) return false;

                        // Source bodies omit declaring-type initialization. Default
                        // construction also needs the existing instance-initializer exclusion.
                        // Record entry uses only an unparameterized declaration's implicit
                        // zero-argument constructor; authored record constructors stay refused.
                        if (declared is ConstructorDeclarationSyntax initializer
                                && (initializer.Modifiers.Any(SyntaxKind.StaticKeyword) || declaration is RecordDeclarationSyntax)
                            || declared is PropertyDeclarationSyntax { Initializer: not null } property
                                && (defaultConstruction || property.Modifiers.Any(SyntaxKind.StaticKeyword))) return false;

                        if (declared is BaseFieldDeclarationSyntax field && !field.Modifiers.Any(SyntaxKind.ConstKeyword)
                            && (defaultConstruction || field.Modifiers.Any(SyntaxKind.StaticKeyword)))
                        {
                            foreach (VariableDeclaratorSyntax variable in field.Declaration.Variables)
                            {
                                if (proof.RemainingWork-- <= 0 || variable.Initializer is not null) return false;
                            }
                        }
                    }
                }

                return true;
            }

            bool SourceHasUnsupportedLifetime(AuthoredMember owner, IMethodSymbol method, SyntaxNode syntax)
            {
                if (method is { IsImplicitlyDeclared: true, MethodKind: MethodKind.Constructor, Parameters.Length: 0 })
                    return !HasInitializationFreeEntry(method.ContainingType, defaultConstruction: true);

                AuthoredMember? target = ResolveInvocationTarget(method, owner, syntax);

                if (target is null)
                {
                    // Ordinary reviewed cleanup is already included in the post-operand
                    // frontier query. Opaque execution does not earn a new lifetime proof.
                    return !ConsumesAdmissionReceiver(method) && !PreservesAdmissionReceiver(method)
                        && !IsReviewedEffectFreeExternalMember(method, syntax, owner.Model, owner);
                }

                // Captured admission in a called local/lambda body is not accounted for
                // by the explicit-argument lifetime walk used by the ordinary query.
                if (target.Syntax is LocalFunctionStatementSyntax or AnonymousFunctionExpressionSyntax
                    || !HasInitializationFreeEntry(target.Symbol.ContainingType)) return true;

                GraphMemberIdentity identity = MemberIdentity(target);

                if (!path.Add(identity)) return true;

                try
                {
                    return target.Model.GetOperation(target.Syntax) is not { } body
                        || Inspect(target, body, enteredCallable: true);
                }
                finally
                {
                    path.Remove(identity);
                }
            }

            bool Inspect(AuthoredMember owner, IOperation operation, bool enteredCallable = false)
            {
                if (proof.RemainingWork-- <= 0) return true;

                if (!enteredCallable && operation is IAnonymousFunctionOperation or ILocalFunctionOperation) return false;

                // AdmissionEndedBefore follows explicit calls. Only known transparent
                // data/structure and the checked execution lanes below retain authority;
                // unknown semantic operations may hide execution absent from their children.
                if (operation.Type?.TypeKind == TypeKind.Dynamic) return true;

                switch (operation)
                {
                    case IInvocationOperation call:
                        if (SourceHasUnsupportedLifetime(owner, call.TargetMethod, call.Syntax)) return true;

                        break;

                    case IObjectCreationOperation { Constructor: { } constructor } creation:
                        if (constructor.Parameters.Length != 0
                            || SourceHasUnsupportedLifetime(owner, constructor, creation.Syntax)) return true;

                        break;

                    case IConversionOperation conversion when conversion.OperatorMethod is null
                        && conversion.Conversion.Exists && conversion.Conversion.MethodSymbol is null:
                    case IArgumentOperation argument when argument.Parameter?.RefKind == RefKind.None
                        && argument.InConversion.MethodSymbol is null && argument.OutConversion.MethodSymbol is null:
                    case IMethodBodyOperation:
                    case IBlockOperation:
                    case IReturnOperation:
                    case IExpressionStatementOperation:
                    case IVariableDeclarationGroupOperation:
                    case IVariableDeclarationOperation:
                    case IVariableDeclaratorOperation:
                    case IVariableInitializerOperation:
                    case ILocalReferenceOperation:
                    case IParameterReferenceOperation:
                    case IInstanceReferenceOperation:
                    case ILiteralOperation:
                    case IDefaultValueOperation:
                    case IParenthesizedOperation:
                    case IDelegateCreationOperation:
                    case IMethodReferenceOperation:
                    case IEmptyOperation:
                        break;

                    default:
                        return true;
                }

                foreach (IOperation child in operation.ChildOperations)
                {
                    if (Inspect(owner, child)) return true;
                }

                return false;
            }

            // A closed-value record target has already proved that neither it nor any nested record
            // declares a static constructor or static initializer, so no hidden type initialization
            // can run before its Equals. The operand walk below is unchanged.
            return !(typeInitializationProven || HasInitializationFreeEntry(conversionTarget.Symbol.ContainingType)) || Inspect(member, operand);
        }

        private static (IMethodSymbol Method, IOperation[] Operands, bool Unsupported)? UserDefinedOperatorAt(AuthoredMember member, SyntaxNode node)
        {
            if (node is not (PrefixUnaryExpressionSyntax or BinaryExpressionSyntax)) return null;

            return member.Model.GetOperation(node) switch
            {
                IUnaryOperation { OperatorMethod: { } method } unary => (method, [unary.Operand], unary.IsLifted),
                IBinaryOperation { OperatorMethod: { } method } binary => (method, [binary.LeftOperand, binary.RightOperand],
                    binary.IsLifted || binary.OperatorKind is BinaryOperatorKind.ConditionalAnd or BinaryOperatorKind.ConditionalOr),
                _ => null,
            };
        }

        private static IEnumerable<IConversionOperation> UserConversionsAt(AuthoredMember member, SyntaxNode node)
        {
            if (node is not ExpressionSyntax) yield break;

            // The operation selected for an expression can be its operand, with a
            // contextual return, argument or initializer conversion only in Parent.
            // Parentheses can share that syntax. The state's occurrence set emits each
            // compiler-selected operator once without walking uninvoked callable bodies.
            for (IOperation? operation = member.Model.GetOperation(node); operation is not null; operation = operation.Parent)
            {
                if (operation is IConversionOperation { OperatorMethod: not null } conversion) yield return conversion;

                if (operation.Parent is not (IConversionOperation or IParenthesizedOperation)) yield break;
            }
        }

        private TraversalEvidence MergeEvidence(TraversalEvidence left, TraversalEvidence right)
        {
            if (left == TraversalEvidence.Inconclusive || right == TraversalEvidence.Inconclusive)
            {
                RefuseTraversalCompletion();
            }

            if (left == TraversalEvidence.Evidence || right == TraversalEvidence.Evidence)
            {
                return TraversalEvidence.Evidence;
            }

            return left == TraversalEvidence.Inconclusive || right == TraversalEvidence.Inconclusive ? TraversalEvidence.Inconclusive : TraversalEvidence.NoEvidence;
        }

        private static int DisposalPosition(VariableDeclarationSyntax declaration) => declaration.Parent is UsingStatementSyntax statement ? statement.Statement.Span.End - 1 : declaration.Ancestors().OfType<BlockSyntax>().First().CloseBraceToken.SpanStart;

        private static bool IsExplicitlyUnknownDisposable(AuthoredMember member, ExpressionSyntax resource)
        {
            resource = StripTransparentExpression(resource);

            if (member.Model.GetSymbolInfo(resource).Symbol is IParameterSymbol)
            {
                return true;
            }

            if (member.Model.GetSymbolInfo(resource).Symbol is not ILocalSymbol local || local.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax() is not VariableDeclaratorSyntax variable)
            {
                return false;
            }

            return variable.Initializer?.Value is { } initializer
                && (member.Model.GetConstantValue(initializer) is
                {
                    HasValue: true,
                    Value: null,
                }
                    || initializer is DefaultExpressionSyntax
                    || IsExplicitlyUnknownDisposable(member, initializer));
        }

        private sealed record HostHandoffProof(AuthoredMember Target, HostedProducerOperationEntry Root, SyntaxNode Selection, IFieldSymbol TaskField, string DispatchAnchor, string JoinAnchor);

        private sealed record SelfAdmittedTaskHandoffProof(AuthoredMember Target, HostedProducerOperationEntry Root);

        private bool IsReviewedOwnedCompletionTransfer(
            AuthoredMember caller,
            InvocationExpressionSyntax call,
            AuthoredMember target)
        {
            string type = TypeKey(caller.Symbol.ContainingType);

            string edge = type
                + "."
                + caller.Symbol.Name
                + "->"
                + target.Symbol.Name;

            if (edge is
                "RetroDownfall.Arcanum.Infrastructure.Hosting.WorkspaceIndexingService.StartHandle->StopAsync")
            {
                return true;
            }

            if (edge is
                    "RetroDownfall.Arcanum.Infrastructure.Mcp.McpConnectionManager.EnsureGlobalLoadedAsync->RunGlobalInitOperationAsync")
            {
                if (call.Parent is not AssignmentExpressionSyntax
                    {
                        Right: { } assigned,
                        Left: { } localTarget,
                    } assignment
                    || assigned != call
                    || caller.Model.GetSymbolInfo(localTarget).Symbol
                        is not ILocalSymbol operation)
                {
                    return false;
                }

                bool published = caller.Syntax.DescendantNodes()
                    .OfType<AssignmentExpressionSyntax>()
                    .Any(write => write.SpanStart > assignment.Span.End
                        && caller.Model.GetSymbolInfo(write.Left).Symbol
                            is IFieldSymbol { Name: "_globalInitOperation" }
                        && SymbolEqualityComparer.Default.Equals(
                            caller.Model.GetSymbolInfo(write.Right).Symbol,
                            operation));

                bool joined = caller.Syntax.DescendantNodes()
                    .OfType<AwaitExpressionSyntax>()
                    .Any(awaited => awaited.SpanStart > assignment.Span.End
                        && awaited.DescendantNodesAndSelf()
                            .OfType<ExpressionSyntax>()
                            .Any(expression => SymbolEqualityComparer.Default.Equals(
                                caller.Model.GetSymbolInfo(expression).Symbol,
                                operation)));

                return published && joined;
            }

            if (edge is not
                ("RetroDownfall.Arcanum.Infrastructure.Hosting.WorkspaceIndexingService.StopAsync->CompleteStopAsync"
                    or "RetroDownfall.Arcanum.Infrastructure.Mcp.McpServerBootstrapHostedService.GetOrStartStopOperation->CompleteStopOperationAsync"
                    or "RetroDownfall.Arcanum.Infrastructure.Mcp.McpConnectionManager.GetOrStartStopOperation->CompleteStopOperationAsync"))
            {
                return false;
            }

            IParameterSymbol? owner = target.Symbol.Parameters
                .FirstOrDefault(static parameter => parameter.Name == "owner");

            if (owner is null
                || TypeKey(owner.Type)
                    != "System.Threading.Tasks.TaskCompletionSource")
            {
                return false;
            }

            InvocationExpressionSyntax[] completions = target.Syntax
                .DescendantNodes()
                .OfType<InvocationExpressionSyntax>()
                .Where(candidate => target.Model.GetSymbolInfo(candidate).Symbol
                    is IMethodSymbol method
                    && method.Name is "TrySetResult" or "TrySetException"
                    && candidate.Expression is MemberAccessExpressionSyntax access
                    && SymbolEqualityComparer.Default.Equals(
                        target.Model.GetSymbolInfo(access.Expression).Symbol,
                        owner))
                .ToArray();

            return completions.Select(candidate =>
                    ((IMethodSymbol)target.Model.GetSymbolInfo(candidate).Symbol!).Name)
                .ToHashSet(StringComparer.Ordinal)
                .SetEquals(["TrySetResult", "TrySetException"]);
        }

        private bool IsReviewedHostedTaskTransfer(
            AuthoredMember caller,
            InvocationExpressionSyntax call,
            AuthoredMember target)
        {
            const string sagaType =
                "RetroDownfall.Arcanum.Infrastructure.Hosting.SagaExtractionService";

            const string servantType =
                "RetroDownfall.Arcanum.Infrastructure.Hosting.UnseenServantService";

            string type = TypeKey(caller.Symbol.ContainingType);

            if (type == sagaType
                && caller.Symbol.Name == "ScheduleRetry"
                && target.Symbol.Name == "RetryAfterDelayAsync")
            {
                if (call.Parent is not EqualsValueClauseSyntax
                    {
                        Parent: VariableDeclaratorSyntax taskDeclaration,
                    }
                    || caller.Model.GetDeclaredSymbol(taskDeclaration)
                        is not ILocalSymbol scheduledTask)
                {
                    return false;
                }

                bool published = caller.Syntax.DescendantNodes()
                    .OfType<InvocationExpressionSyntax>()
                    .Any(candidate => candidate.SpanStart > call.Span.End
                        && caller.Model.GetSymbolInfo(candidate).Symbol
                            is IMethodSymbol { Name: "Add" }
                        && candidate.Expression is MemberAccessExpressionSyntax
                        {
                            Expression: { } receiver,
                        }
                        && caller.Model.GetSymbolInfo(receiver).Symbol
                            is IFieldSymbol { Name: "_scheduledRetryTasks" }
                        && candidate.ArgumentList.Arguments.Any(argument =>
                            SymbolEqualityComparer.Default.Equals(
                                caller.Model.GetSymbolInfo(argument.Expression).Symbol,
                                scheduledTask))
                        && candidate.Ancestors().OfType<LockStatementSyntax>().Any());

                bool observed = AuthoredMembers.Any(observer =>
                        TypeKey(observer.Symbol.ContainingType) == sagaType
                        && observer.Symbol.Name == "ObserveScheduledRetriesAsync"
                        && observer.Syntax.DescendantNodes()
                            .OfType<InvocationExpressionSyntax>()
                            .Any(candidate => observer.Model.GetSymbolInfo(candidate).Symbol
                                    is IMethodSymbol method
                                && Normalize(method) == "System.Threading.Tasks.Task.WhenAll"
                                && candidate.FirstAncestorOrSelf<AwaitExpressionSyntax>()
                                    is not null))
                    && AuthoredMembers.Any(owner =>
                        TypeKey(owner.Symbol.ContainingType) == sagaType
                        && owner.Symbol.Name == "ExecuteAsync"
                        && owner.Syntax.DescendantNodes()
                            .OfType<InvocationExpressionSyntax>()
                            .Any(candidate => owner.Model.GetSymbolInfo(candidate).Symbol
                                    is IMethodSymbol method
                                && method.Name == "ObserveScheduledRetriesAsync"
                                && candidate.FirstAncestorOrSelf<AwaitExpressionSyntax>()
                                    is not null
                                && candidate.Ancestors().OfType<FinallyClauseSyntax>()
                                    .Any()));

                return published && observed;
            }

            if (type != servantType
                || caller.Symbol.Name != "DispatchDueJobsCore"
                || target.Symbol.Name != "TrackJobTask"
                || call.ArgumentList.Arguments.FirstOrDefault()?.Expression
                    is not { } registry
                || caller.Model.GetSymbolInfo(registry).Symbol
                    is not IFieldSymbol { Name: "_activeJobTasks" }
                || target.Symbol.Parameters is not
                    [IParameterSymbol activeTasks,
                        IParameterSymbol taskId,
                        IParameterSymbol startJob])
            {
                return false;
            }

            InvocationExpressionSyntax[] starts = target.Syntax.DescendantNodes()
                .OfType<InvocationExpressionSyntax>()
                .Where(candidate => target.Model.GetSymbolInfo(candidate).Symbol
                        is IMethodSymbol method
                    && method.MethodKind == MethodKind.DelegateInvoke
                    && candidate.Expression is ExpressionSyntax invoked
                    && SymbolEqualityComparer.Default.Equals(
                        target.Model.GetSymbolInfo(invoked).Symbol,
                        startJob))
                .ToArray();

            bool proxyPublishedFirst = starts is [InvocationExpressionSyntax start]
                && target.Syntax.DescendantNodes()
                    .OfType<AssignmentExpressionSyntax>()
                    .Any(assignment => assignment.Span.End < start.SpanStart
                        && assignment.Left is ElementAccessExpressionSyntax index
                        && SymbolEqualityComparer.Default.Equals(
                            target.Model.GetSymbolInfo(index.Expression).Symbol,
                            activeTasks)
                        && index.ArgumentList.Arguments.Any(argument =>
                            SymbolEqualityComparer.Default.Equals(
                                target.Model.GetSymbolInfo(argument.Expression).Symbol,
                                taskId)));

            return proxyPublishedFirst
                && HasReviewedTrackedTaskStopJoin(
                    caller.Symbol.ContainingType,
                    "_activeJobTasks");
        }

        private bool IsReviewedHostedTaskCallbackTransfer(
            AuthoredMember member,
            InvocationExpressionSyntax callbackCall)
        {
            if (TypeKey(member.Symbol.ContainingType)
                    != "RetroDownfall.Arcanum.Infrastructure.Hosting.UnseenServantService"
                || member.Symbol.Name != "TrackJobTask"
                || member.Model.GetSymbolInfo(callbackCall).Symbol
                    is not IMethodSymbol
                    {
                        MethodKind: MethodKind.DelegateInvoke,
                    }
                || callbackCall.Expression is not ExpressionSyntax invoked
                || member.Model.GetSymbolInfo(invoked).Symbol
                    is not IParameterSymbol { Name: "startJob" }
                || callbackCall.Parent is not EqualsValueClauseSyntax
                {
                    Parent: VariableDeclaratorSyntax taskDeclaration,
                }
                || member.Model.GetDeclaredSymbol(taskDeclaration)
                    is not ILocalSymbol jobTask)
            {
                return false;
            }

            InvocationExpressionSyntax[] transfers = member.Syntax
                .DescendantNodes()
                .OfType<InvocationExpressionSyntax>()
                .Where(call => call.SpanStart > callbackCall.Span.End
                    && member.Model.GetSymbolInfo(call).Symbol
                        is IMethodSymbol { Name: "SetResult" }
                    && call.ArgumentList.Arguments.Any(argument =>
                        SymbolEqualityComparer.Default.Equals(
                            member.Model.GetSymbolInfo(argument.Expression).Symbol,
                            jobTask)))
                .ToArray();

            return transfers is [InvocationExpressionSyntax]
                && HasReviewedTrackedTaskStopJoin(
                    member.Symbol.ContainingType,
                    "_activeJobTasks");
        }

        /// <summary>
        /// R-048's two bounded OS credential reads: <c>MirroredOsCredential.ReadOsAsync</c>, whose one
        /// outstanding read every caller joins, and the master-key bootstrapper's direct probe of a store
        /// that is not the shipping one. Each hands exactly one <c>IOsCredentialStore.TryGet</c> to
        /// <c>Task.Run</c> and waits for it only through a timed <c>WaitAsync</c>, so a parked platform
        /// prompt is abandoned rather than allowed to wedge startup, and the abandoned read finishes after
        /// its caller. That is reviewed only because the read reaches no producer site: the shipping store
        /// decorates its own interface, which leaves the callback's evidence inconclusive, never evidence.
        /// A site reached inside the read, an admission seed, any other owner, a callback that is not
        /// exactly that one call, or a read no timed wait bounds is not this proof.
        /// </summary>
        private bool IsReviewedBoundedOsCredentialRead(
            AuthoredMember caller,
            InvocationExpressionSyntax dispatch,
            TraversalEvidence callbackEvidence,
            AuthoredMember[] bodies)
        {
            if (callbackEvidence == TraversalEvidence.Evidence
                || bodies.Length == 0
                || bodies.Any(HasAdmissionSeed)
                || caller.Model.GetSymbolInfo(dispatch).Symbol is not IMethodSymbol taskRun
                || Normalize(taskRun) != "System.Threading.Tasks.Task.Run"
                || dispatch.ArgumentList.Arguments is not
                [
                    {
                        Expression: ParenthesizedLambdaExpressionSyntax
                        {
                            ParameterList.Parameters.Count: 0,
                            Block: null,
                            ExpressionBody: InvocationExpressionSyntax read,
                        },
                    },
                    {
                        Expression: MemberAccessExpressionSyntax cancellation,
                    },
                ]
                || caller.Model.GetSymbolInfo(read).Symbol is not IMethodSymbol readMethod
                || Normalize(readMethod) != "RetroDownfall.Arcanum.Secrets.Security.IOsCredentialStore.TryGet"
                || read.ArgumentList.Arguments.Any(argument =>
                    argument.RefKindKeyword.IsKind(SyntaxKind.OutKeyword)
                    || IsDelegateExpression(caller.Model, argument.Expression))
                || caller.Model.GetSymbolInfo(cancellation).Symbol
                    is not IPropertySymbol { Name: "None" } none
                || TypeKey(none.ContainingType) != "System.Threading.CancellationToken")
            {
                return false;
            }

            string type = TypeKey(caller.Symbol.ContainingType);

            bool reviewedOwner = type == "RetroDownfall.Arcanum.Infrastructure.Security.MirroredOsCredential"
                    && caller.Symbol.Name == "ReadOsAsync"
                || type == "RetroDownfall.Arcanum.Infrastructure.Security.ArcanumMasterKeyBootstrapper"
                    && caller.Symbol.Name == "ProbeOsKeyStorageAsync";

            return reviewedOwner
                && caller.Syntax.DescendantNodes()
                    .OfType<InvocationExpressionSyntax>()
                    .Any(call => caller.Model.GetSymbolInfo(call).Symbol
                            is IMethodSymbol wait
                        && Normalize(wait) is "System.Threading.Tasks.Task.WaitAsync"
                            or "System.Threading.Tasks.Task`1.WaitAsync"
                        && wait.Parameters.Any(static parameter =>
                            TypeKey(parameter.Type) == "System.TimeSpan"));
        }

        private bool IsReviewedTrackedTaskHandoff(
            AuthoredMember caller,
            InvocationExpressionSyntax dispatch)
        {
            if (caller.Model.GetSymbolInfo(dispatch).Symbol is not IMethodSymbol taskRun
                || Normalize(taskRun) != "System.Threading.Tasks.Task.Run"
                || dispatch.ArgumentList.Arguments.FirstOrDefault()?.Expression
                    is not AnonymousFunctionExpressionSyntax callback)
            {
                return false;
            }

            string type = TypeKey(caller.Symbol.ContainingType);

            if (type == "RetroDownfall.Arcanum.Api.Intelligence.BatchProcessingService"
                && caller.Symbol.Name == "TickAsync")
            {
                InvocationExpressionSyntax[] ownedRuns = callback.Body
                    .DescendantNodesAndSelf()
                    .OfType<InvocationExpressionSyntax>()
                    .Where(call => caller.Model.GetSymbolInfo(call).Symbol
                        is IMethodSymbol method
                        && method.Name == "ProcessBatchWithCleanupAsync"
                        && SymbolEqualityComparer.Default.Equals(
                            method.ContainingType,
                            caller.Symbol.ContainingType))
                    .ToArray();

                if (ownedRuns is not [InvocationExpressionSyntax ownedRun]
                    || ownedRun.FirstAncestorOrSelf<AwaitExpressionSyntax>() is null
                    || callback.Body is not BlockSyntax
                    {
                        Statements: [TryStatementSyntax protectedRun],
                    }
                    || protectedRun.Finally is null)
                {
                    return false;
                }

                ISymbol? completion = protectedRun.Finally.Block
                    .DescendantNodes()
                    .OfType<InvocationExpressionSyntax>()
                    .Where(call => caller.Model.GetSymbolInfo(call).Symbol
                        is IMethodSymbol { Name: "TrySetResult" })
                    .Select(call => call.Expression is MemberAccessExpressionSyntax access
                        ? caller.Model.GetSymbolInfo(access.Expression).Symbol
                        : null)
                    .SingleOrDefault();

                if (completion is not ILocalSymbol
                    || !caller.Syntax.DescendantNodes()
                        .OfType<InvocationExpressionSyntax>()
                        .Any(call => call.Span.End < dispatch.SpanStart
                            && caller.Model.GetSymbolInfo(call).Symbol
                                is IMethodSymbol { Name: "TryAdd" }
                            && call.ArgumentList.Arguments.Any(argument =>
                                argument.Expression
                                    is MemberAccessExpressionSyntax
                                {
                                    Expression: { } owner,
                                    Name.Identifier.ValueText: "Task",
                                }
                                && SymbolEqualityComparer.Default.Equals(
                                    caller.Model.GetSymbolInfo(owner).Symbol,
                                    completion))))
                {
                    return false;
                }

                return HasReviewedTrackedTaskStopJoin(
                    caller.Symbol.ContainingType,
                    "_inFlight");
            }

            if (type == "RetroDownfall.Arcanum.Infrastructure.Hosting.WorkspaceIndexingService"
                && caller.Symbol.Name == "StartHandle")
            {
                InvocationExpressionSyntax[] ownedRuns = callback.Body
                    .DescendantNodesAndSelf()
                    .OfType<InvocationExpressionSyntax>()
                    .Where(call => caller.Model.GetSymbolInfo(call).Symbol
                        is IMethodSymbol method
                        && method.Name == "RunHandleAsync"
                        && SymbolEqualityComparer.Default.Equals(
                            method.ContainingType,
                            caller.Symbol.ContainingType))
                    .ToArray();

                AuthoredMember? run = ownedRuns is [InvocationExpressionSyntax ownedRun]
                    && caller.Model.GetSymbolInfo(ownedRun).Symbol is IMethodSymbol runMethod
                    ? Resolve(runMethod, caller.Model.Compilation)
                    : null;

                if (run is null)
                {
                    return false;
                }

                AuthoredMember[] finishers = AuthoredMembers
                    .Where(member => SymbolEqualityComparer.Default.Equals(
                            member.Symbol.ContainingType,
                            caller.Symbol.ContainingType)
                        && member.Symbol.Name == "FinishHandle")
                    .ToArray();

                return finishers is [AuthoredMember finisher]
                    && finisher.Syntax.DescendantNodes()
                        .OfType<InvocationExpressionSyntax>()
                        .Any(call => finisher.Model.GetSymbolInfo(call).Symbol
                            is IMethodSymbol { Name: "TrySetResult" });
            }

            return false;
        }

        private bool HasReviewedTrackedTaskStopJoin(
            INamedTypeSymbol owner,
            string trackedFieldName)
        {
            IFieldSymbol? tracked = owner.GetMembers(trackedFieldName)
                .OfType<IFieldSymbol>()
                .SingleOrDefault();

            if (tracked is null)
            {
                return false;
            }

            return AuthoredMembers
                .Where(member => SymbolEqualityComparer.Default.Equals(
                        member.Symbol.ContainingType,
                        owner)
                    && member.Symbol.Name == "StopAsync")
                .Any(stop => stop.Syntax.DescendantNodes()
                    .OfType<InvocationExpressionSyntax>()
                    .Any(call => stop.Model.GetSymbolInfo(call).Symbol
                        is IMethodSymbol aggregate
                        && Normalize(aggregate)
                            == "System.Threading.Tasks.Task.WhenAll"
                        && call.Ancestors().FirstOrDefault() is not null
                        && stop.Syntax.DescendantNodes()
                            .OfType<ExpressionSyntax>()
                            .Any(expression => SymbolEqualityComparer.Default.Equals(
                                stop.Model.GetSymbolInfo(expression).Symbol,
                                tracked))));
        }

        private SelfAdmittedTaskHandoffProof? TrySelfAdmittedTaskHandoff(AuthoredMember caller, InvocationExpressionSyntax dispatch)
        {
            if (TypeKey(caller.Symbol.ContainingType) != "RetroDownfall.Arcanum.Infrastructure.Hosting.ApprenticeService" || caller.Symbol.Name != "BeginExecutionTask" || caller.Model.GetSymbolInfo(dispatch).Symbol is not IMethodSymbol taskRun || Normalize(taskRun) != "System.Threading.Tasks.Task.Run" || dispatch.ArgumentList.Arguments.FirstOrDefault()?.Expression is not AnonymousFunctionExpressionSyntax callback)
            {
                return null;
            }

            if (dispatch.Parent is not AssignmentExpressionSyntax dispatchAssignment
                || dispatchAssignment.Right != dispatch
                || caller.Model.GetSymbolInfo(dispatchAssignment.Left).Symbol is not ILocalSymbol taskLocal
                || TypeKey(taskLocal.Type) != "System.Threading.Tasks.Task"
                || taskLocal.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                    is not VariableDeclaratorSyntax
                    {
                        Initializer.Value.RawKind: (int)SyntaxKind.NullLiteralExpression,
                    }
                || dispatchAssignment.Parent is not ExpressionStatementSyntax
                {
                    Parent: BlockSyntax publicationBlock,
                }
                || publicationBlock.Parent is not LockStatementSyntax publicationLock
                || caller.Model.GetSymbolInfo(publicationLock.Expression).Symbol
                    is not IFieldSymbol
                    {
                        Name: "_executionLifecycleLock",
                    } lifecycleLock
                || callback.Body is not BlockSyntax
                {
                    Statements:
                        [
                            LockStatementSyntax callbackBarrier,
                            TryStatementSyntax guardedRun,
                        ],
                }
                || callbackBarrier.Statement is not BlockSyntax
                {
                    Statements.Count: 0,
                }
                || !SymbolEqualityComparer.Default.Equals(
                    caller.Model.GetSymbolInfo(callbackBarrier.Expression).Symbol,
                    lifecycleLock)
                || guardedRun.Block.Statements is not
                    [ExpressionStatementSyntax { Expression: AwaitExpressionSyntax awaitedRun }]
                || guardedRun.Catches is not [CatchClauseSyntax observedFault]
                || observedFault.Filter is not null
                || observedFault.Declaration is not { Type: { } caughtType }
                || TypeKey(caller.Model.GetTypeInfo(caughtType).Type!) != "System.Exception"
                || observedFault.Block.DescendantNodes()
                    .Any(static node => node is ThrowStatementSyntax)
                || guardedRun.Finally?.Block.Statements is not
                    [ExpressionStatementSyntax { Expression: InvocationExpressionSyntax cleanupCall }])
            {
                return null;
            }

            InvocationExpressionSyntax[] runCalls = guardedRun.Block
                .DescendantNodes()
                .OfType<InvocationExpressionSyntax>()
                .Where(call => caller.Model.GetSymbolInfo(call).Symbol is IMethodSymbol candidate
                    && Resolve(candidate, caller.Model.Compilation) is { } resolved
                    && resolved.Symbol.Name == "RunApprenticeAsync"
                    && SymbolEqualityComparer.Default.Equals(
                        resolved.Symbol.ContainingType,
                        caller.Symbol.ContainingType))
                .ToArray();

            if (runCalls is not [InvocationExpressionSyntax runCall]
                || !awaitedRun.DescendantNodesAndSelf().Contains(runCall)
                || guardedRun.Block.DescendantNodes()
                    .OfType<InvocationExpressionSyntax>()
                    .Any(call => call != runCall
                        && (caller.Model.GetSymbolInfo(call).Symbol is not IMethodSymbol method
                            || !IsExactFrameworkConfigureAwait(method)
                            || TypeKey((method.ReducedFrom ?? method).ContainingType)
                                is not "System.Threading.Tasks.Task"
                                    and not "System.Threading.Tasks.Task`1"))
                || caller.Model.GetSymbolInfo(runCall).Symbol is not IMethodSymbol targetSymbol
                || Resolve(targetSymbol, caller.Model.Compilation) is not { } target)
            {
                return null;
            }

            IParameterSymbol? apprenticeId = caller.Symbol.Parameters
                .SingleOrDefault(static parameter => parameter.Name == "apprenticeId");

            ISymbol? generation = runCall.ArgumentList.Arguments.Count == 2
                ? caller.Model.GetSymbolInfo(
                    StripTransparentExpression(
                        runCall.ArgumentList.Arguments[1].Expression)).Symbol
                : null;

            bool RefersTo(ExpressionSyntax expression, ISymbol? symbol) =>
                symbol is not null
                && SymbolEqualityComparer.Default.Equals(
                    caller.Model.GetSymbolInfo(
                        StripTransparentExpression(expression)).Symbol,
                    symbol);

            if (apprenticeId is null
                || generation is not ILocalSymbol
                || runCall.ArgumentList.Arguments.Count != 2
                || !RefersTo(runCall.ArgumentList.Arguments[0].Expression, apprenticeId)
                || caller.Model.GetSymbolInfo(cleanupCall).Symbol is not IMethodSymbol cleanupSymbol
                || Resolve(cleanupSymbol, caller.Model.Compilation) is not { } cleanup
                || cleanup.Symbol.Name != "CleanupExecution"
                || !SymbolEqualityComparer.Default.Equals(
                    cleanup.Symbol.ContainingType,
                    caller.Symbol.ContainingType)
                || cleanupCall.ArgumentList.Arguments.Count != 3
                || !RefersTo(cleanupCall.ArgumentList.Arguments[0].Expression, apprenticeId)
                || !RefersTo(cleanupCall.ArgumentList.Arguments[1].Expression, generation)
                || !RefersTo(cleanupCall.ArgumentList.Arguments[2].Expression, taskLocal))
            {
                return null;
            }

            foreach (InvocationExpressionSyntax catchCall in observedFault.Block
                .DescendantNodes()
                .OfType<InvocationExpressionSyntax>())
            {
                if (caller.Model.GetSymbolInfo(catchCall).Symbol is not IMethodSymbol method
                    || !IsReviewedEffectFreeExternalMember(
                        method,
                        catchCall,
                        caller.Model))
                {
                    return null;
                }
            }

            AssignmentExpressionSyntax[] taskWrites = caller.Syntax
                .DescendantNodes()
                .OfType<AssignmentExpressionSyntax>()
                .Where(write => RefersTo(write.Left, taskLocal))
                .ToArray();

            AssignmentExpressionSyntax[] publications = publicationBlock.Statements
                .OfType<ExpressionStatementSyntax>()
                .Select(static statement => statement.Expression)
                .OfType<AssignmentExpressionSyntax>()
                .Where(write => write.SpanStart > dispatchAssignment.Span.End
                    && RefersTo(write.Right, taskLocal)
                    && write.Left is ElementAccessExpressionSyntax index
                    && caller.Model.GetSymbolInfo(index.Expression).Symbol
                        is IFieldSymbol
                    {
                        Name: "_activeTasks",
                    } activeTasks
                    && SymbolEqualityComparer.Default.Equals(
                        activeTasks.ContainingType,
                        caller.Symbol.ContainingType)
                    && index.ArgumentList.Arguments is [ArgumentSyntax key]
                    && RefersTo(key.Expression, apprenticeId))
                .ToArray();

            bool taskEscapes = caller.Syntax.DescendantNodes()
                .OfType<ArgumentSyntax>()
                .Any(argument => argument.RefKindKeyword.Kind() is
                        SyntaxKind.RefKeyword or SyntaxKind.OutKeyword
                    && RefersTo(argument.Expression, taskLocal));

            if (taskWrites is not [AssignmentExpressionSyntax exactWrite]
                || exactWrite != dispatchAssignment
                || publications is not [AssignmentExpressionSyntax]
                || taskEscapes)
            {
                return null;
            }

            HostedProducerOperationEntry[] roots = declaredOperations.Where(entry => entry.Authority == HostedProducerAuthorityKind.OrdinaryHostedWork && entry.WorkKind == GrimoireWorkKind.ApprenticeExecution && entry.SourcePath == target.Syntax.SyntaxTree.FilePath && entry.EnclosingType == TypeKey(target.Symbol.ContainingType) && entry.Member == target.Symbol.Name && entry.OperationId == entry.EnclosingType + "." + entry.Member).ToArray();

            return roots.Length == 1 ? new(target, roots[0]) : null;
        }

        private HostHandoffProof? TryHostHandoff(AuthoredMember caller, InvocationExpressionSyntax dispatch)
        {
            if (caller.Symbol.Name != "StartAsync" || !IsLifecycle(caller.Symbol) || !caller.Symbol.ContainingType.AllInterfaces.Any(static type => TypeKey(type) == "Microsoft.Extensions.Hosting.IHostedService") || caller.Model.GetSymbolInfo(dispatch).Symbol is not IMethodSymbol taskDispatch)
            {
                return null;
            }

            string dispatchKind = Normalize(taskDispatch);

            InvocationExpressionSyntax publishedTask = dispatch;

            if (dispatchKind == "System.Threading.Tasks.TaskFactory.StartNew")
            {
                if (dispatch.Parent is not MemberAccessExpressionSyntax { Name.Identifier.ValueText: "Unwrap", Parent: InvocationExpressionSyntax unwrap } || caller.Model.GetSymbolInfo(unwrap).Symbol is not IMethodSymbol unwrapMethod || Normalize(unwrapMethod) != "System.Threading.Tasks.TaskExtensions.Unwrap")
                {
                    return null;
                }

                publishedTask = unwrap;
            }
            else if (dispatchKind != "System.Threading.Tasks.Task.Run")
            {
                return null;
            }

            if (publishedTask.Parent is not AssignmentExpressionSyntax assignment || assignment.Right != publishedTask || caller.Model.GetSymbolInfo(assignment.Left).Symbol is not IFieldSymbol field || TypeKey(field.Type) != "System.Threading.Tasks.Task" || !SymbolEqualityComparer.Default.Equals(field.ContainingType, caller.Symbol.ContainingType))
            {
                return null;
            }

            AuthoredMember[] owners = AuthoredMembers.Where(member => SymbolEqualityComparer.Default.Equals(member.Symbol.ContainingType, caller.Symbol.ContainingType)).ToArray();

            bool RefersToField(AuthoredMember member, SyntaxNode syntax) => syntax.DescendantNodesAndSelf().OfType<ExpressionSyntax>().Any(expression => SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(expression).Symbol, field));

            bool escapes = owners.Any(member => member.Syntax.DescendantNodes().Any(node => node is ArgumentSyntax argument && argument.RefKindKeyword.RawKind != 0 && RefersToField(member, argument.Expression) || node is RefExpressionSyntax reference && RefersToField(member, reference.Expression) || node is PrefixUnaryExpressionSyntax address && address.IsKind(SyntaxKind.AddressOfExpression) && RefersToField(member, address.Operand)));

            ExpressionSyntax? callback = dispatch.ArgumentList.Arguments.FirstOrDefault()?.Expression;

            AuthoredMember? target = callback is AnonymousFunctionExpressionSyntax { Body: InvocationExpressionSyntax targetCall } && caller.Model.GetSymbolInfo(targetCall).Symbol is IMethodSymbol targetSymbol
                ? Resolve(targetSymbol, caller.Model.Compilation)
                : callback is null ? null : ResolveCallable(callback, caller.Model, caller.CallableBindings, caller.AbsentCallables);

            (AuthoredMember Member, AssignmentExpressionSyntax Write)[] writes = owners.SelectMany(member => member.Syntax.DescendantNodes().OfType<AssignmentExpressionSyntax>().Where(write => RefersToField(member, write.Left)).Select(write => (member, write))).ToArray();

            static bool Terminates(StatementSyntax statement)
            {
                StatementSyntax? terminal = statement is BlockSyntax block ? block.Statements.LastOrDefault() : statement;

                return terminal is ReturnStatementSyntax or ThrowStatementSyntax;
            }

            bool MutuallyExclusiveWithDispatch(AuthoredMember owner, AssignmentExpressionSyntax write)
            {
                if (owner != caller)
                {
                    return false;
                }

                foreach (IfStatementSyntax branch in write.Ancestors().OfType<IfStatementSyntax>().TakeWhile(candidate => caller.Syntax.Span.Contains(candidate.Span)))
                {
                    bool writeInThen = branch.Statement.Span.Contains(write.Span);

                    bool writeInElse = branch.Else?.Statement.Span.Contains(write.Span) == true;

                    bool dispatchInThen = branch.Statement.Span.Contains(assignment.Span);

                    bool dispatchInElse = branch.Else?.Statement.Span.Contains(assignment.Span) == true;

                    if (writeInThen && dispatchInElse || writeInElse && dispatchInThen)
                    {
                        return true;
                    }

                    StatementSyntax? writeBranch = writeInThen ? branch.Statement : writeInElse ? branch.Else?.Statement : null;

                    if (writeBranch is not null && branch.Span.End < assignment.SpanStart && Terminates(writeBranch))
                    {
                        return true;
                    }
                }

                return false;
            }

            bool exactPublication = writes.Count(candidate => candidate.Write == assignment) == 1 && writes.Where(candidate => candidate.Write != assignment).All(candidate => MutuallyExclusiveWithDispatch(candidate.Member, candidate.Write));

            if (escapes || !exactPublication || target is null)
            {
                return null;
            }

            (HostedProducerOperationEntry Root, SyntaxNode Selection)[] roots = declaredOperations
                .Where(entry => entry.Authority == HostedProducerAuthorityKind.OrdinaryHostedWork
                    && entry.WorkKind is not null
                    && entry.SourcePath == target.Syntax.SyntaxTree.FilePath
                    && entry.EnclosingType == TypeKey(target.Symbol.ContainingType)
                    && entry.Member == target.Symbol.Name)
                .Select(entry => (Root: entry, Selection: SelectRoot(target, entry.OperationId)))
                .Where(static candidate => candidate.Selection is not null)
                .Select(static candidate => (candidate.Root, candidate.Selection!))
                .ToArray();

            if (roots.Length != 1)
            {
                return null;
            }

            List<AwaitExpressionSyntax> joins = [];

            HashSet<GraphMemberIdentity> stopReachable = [];

            Queue<AuthoredMember> pendingStopMembers = new(owners.Where(static member => member.Symbol.Name == "StopAsync" && IsLifecycle(member.Symbol)));

            while (pendingStopMembers.TryDequeue(out AuthoredMember? reachable))
            {
                if (!stopReachable.Add(MemberIdentity(reachable)))
                {
                    continue;
                }

                foreach (InvocationExpressionSyntax call in reachable.Syntax.DescendantNodes(node => node is not AnonymousFunctionExpressionSyntax and not LocalFunctionStatementSyntax).OfType<InvocationExpressionSyntax>())
                {
                    if (reachable.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method && Resolve(method, reachable.Model.Compilation) is { } next && SymbolEqualityComparer.Default.Equals(next.Symbol.ContainingType, caller.Symbol.ContainingType))
                    {
                        pendingStopMembers.Enqueue(next);
                    }
                }
            }

            foreach (AuthoredMember stop in owners.Where(member => stopReachable.Contains(MemberIdentity(member))))
            {
                bool RefersToPublishedTask(ExpressionSyntax expression)
                {
                    ISymbol? symbol = stop.Model.GetSymbolInfo(expression).Symbol;

                    if (SymbolEqualityComparer.Default.Equals(symbol, field))
                    {
                        return true;
                    }

                    if (symbol is not ILocalSymbol local
                        || local.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                            is not VariableDeclaratorSyntax variable)
                    {
                        return false;
                    }

                    BlockSyntax block = variable.Ancestors().OfType<BlockSyntax>().First();

                    if (variable.Initializer?.Value is { } initializer)
                    {
                        return RefersToField(stop, initializer)
                            && !block.DescendantNodes()
                                .OfType<AssignmentExpressionSyntax>()
                                .Any(write => SymbolEqualityComparer.Default.Equals(
                                    stop.Model.GetSymbolInfo(write.Left).Symbol,
                                    local));
                    }

                    AssignmentExpressionSyntax[] writes = block.DescendantNodes()
                        .OfType<AssignmentExpressionSyntax>()
                        .Where(write => SymbolEqualityComparer.Default.Equals(
                            stop.Model.GetSymbolInfo(write.Left).Symbol,
                            local))
                        .ToArray();

                    if (writes is not [AssignmentExpressionSyntax exactWrite]
                        || !exactWrite.IsKind(SyntaxKind.SimpleAssignmentExpression)
                        || exactWrite.Span.End >= expression.SpanStart
                        || !RefersToField(stop, exactWrite.Right)
                        || exactWrite.Ancestors()
                            .TakeWhile(ancestor => ancestor != block)
                            .Any(static ancestor => ancestor is IfStatementSyntax
                                or ElseClauseSyntax
                                or SwitchStatementSyntax
                                or ForStatementSyntax
                                or ForEachStatementSyntax
                                or ForEachVariableStatementSyntax
                                or WhileStatementSyntax
                                or DoStatementSyntax
                                or CatchClauseSyntax
                                or AnonymousFunctionExpressionSyntax
                                or LocalFunctionStatementSyntax))
                    {
                        return false;
                    }

                    return !block.DescendantNodes()
                        .Any(candidate => candidate.SpanStart >= variable.Span.End
                            && candidate.Span.End < exactWrite.SpanStart
                            && candidate is ReturnStatementSyntax
                                or ThrowStatementSyntax
                                or GotoStatementSyntax);
                }

                foreach (AwaitExpressionSyntax awaited in stop.Syntax.DescendantNodes(node => node is not AnonymousFunctionExpressionSyntax and not LocalFunctionStatementSyntax).OfType<AwaitExpressionSyntax>())
                {
                    bool ExactNonNullGuard(IfStatementSyntax guard) => guard.Statement.Span.Contains(awaited.Span) && guard.Condition is IsPatternExpressionSyntax { Expression: { } tested, Pattern: UnaryPatternSyntax { Pattern: ConstantPatternSyntax { Expression.RawKind: (int)SyntaxKind.NullLiteralExpression } } } && RefersToPublishedTask(tested);

                    if (awaited.Ancestors().Any(static node => node is ForStatementSyntax or ForEachStatementSyntax or WhileStatementSyntax or DoStatementSyntax or ConditionalExpressionSyntax or SwitchStatementSyntax) || awaited.Ancestors().OfType<IfStatementSyntax>().Any(guard => !ExactNonNullGuard(guard)))
                    {
                        continue;
                    }

                    ExpressionSyntax expression = awaited.Expression;

                    if (expression is InvocationExpressionSyntax { Expression: MemberAccessExpressionSyntax { Name.Identifier.ValueText: "ConfigureAwait" } configured })
                    {
                        expression = configured.Expression;
                    }

                    if (expression is InvocationExpressionSyntax { Expression: MemberAccessExpressionSyntax wait } waitCall && stop.Model.GetSymbolInfo(waitCall).Symbol is IMethodSymbol waitMethod && Normalize(waitMethod) == "System.Threading.Tasks.Task.WaitAsync")
                    {
                        expression = wait.Expression;
                    }

                    if (RefersToPublishedTask(expression))
                    {
                        joins.Add(awaited);
                    }
                }
            }

            return joins.Count == 1
                ? new(
                    target,
                    roots[0].Root,
                    roots[0].Selection,
                    field,
                    Location(dispatch),
                    Location(joins[0]))
                : null;
        }

        private bool IsOwnedBoundedGuidChannelRead(AuthoredMember member, InvocationExpressionSyntax read, IMethodSymbol method)
        {
            static bool GuidType(ITypeSymbol type) => IsExactFrameworkType(type, "System.Guid", typeof(Guid).Assembly.GetName());

            static bool ChannelType(ITypeSymbol type, string name, int arity) => type is INamedTypeSymbol named
                && named.TypeArguments.Length == arity && named.TypeArguments.All(GuidType)
                && IsExactFrameworkType(type, name, typeof(System.Threading.Channels.Channel).Assembly.GetName());

            if (method.IsStatic || method.Name != "ReadAsync" || method.Arity != 0
                || !ChannelType(method.ContainingType, "System.Threading.Channels.ChannelReader`1", 1)
                || !HasExactParameterTypes(method, "System.Threading.CancellationToken")
                || method.ReturnType is not INamedTypeSymbol { TypeArguments: [{ } result] } returned
                || !GuidType(result)
                || !IsExactFrameworkType(returned, "System.Threading.Tasks.ValueTask`1", typeof(ValueTask<>).Assembly.GetName())
                || read.Expression is not MemberAccessExpressionSyntax access)
            {
                return false;
            }

            CleanupProvenanceContext proof = new();

            bool Origin(ExpressionSyntax expression, SemanticModel model, HashSet<ISymbol> path, AuthoredMember? context, bool reader)
            {
                if (context is null || proof.RemainingWork-- <= 0)
                {
                    return false;
                }

                expression = StripTransparentExpression(expression);

                AuthoredMember owner = context with { Model = model };

                ISymbol? symbol = model.GetSymbolInfo(expression).Symbol;

                if (reader && expression is MemberAccessExpressionSyntax propertyAccess
                    && symbol is IPropertySymbol { Name: "Reader", IsStatic: false, GetMethod.DeclaredAccessibility: Accessibility.Public, SetMethod.DeclaredAccessibility: Accessibility.Protected } property
                    && ChannelType(property.ContainingType, "System.Threading.Channels.Channel`2", 2)
                    && ChannelType(property.Type, "System.Threading.Channels.ChannelReader`1", 1))
                {
                    return Origin(propertyAccess.Expression, model, path, owner, false);
                }

                if (expression is InvocationExpressionSyntax call && symbol is IMethodSymbol factory)
                {
                    if (!reader && factory.IsStatic && factory.Name == "CreateBounded"
                        && factory.TypeArguments is [{ } item] && GuidType(item)
                        && IsExactFrameworkType(factory.ContainingType, "System.Threading.Channels.Channel", typeof(System.Threading.Channels.Channel).Assembly.GetName())
                        && HasExactParameterTypes(factory, "System.Threading.Channels.BoundedChannelOptions")
                        && ChannelType(factory.ReturnType, "System.Threading.Channels.Channel`1", 1)
                        && call.ArgumentList.Arguments is [{ Expression: BaseObjectCreationExpressionSyntax options }]
                        && model.GetSymbolInfo(options).Symbol is IMethodSymbol constructor
                        && IsExactFrameworkType(constructor.ContainingType, "System.Threading.Channels.BoundedChannelOptions", typeof(System.Threading.Channels.Channel).Assembly.GetName())
                        && HasExactParameterTypes(constructor, "System.Int32")
                        && options.ArgumentList?.Arguments is [{ Expression: { } capacity }]
                        && model.GetConstantValue(capacity) is { HasValue: true, Value: 1 }
                        && options.Initializer?.Expressions is { Count: 2 } settings)
                    {
                        bool single = false;
                        bool drop = false;

                        foreach (ExpressionSyntax setting in settings)
                        {
                            if (setting is not AssignmentExpressionSyntax { RawKind: (int)SyntaxKind.SimpleAssignmentExpression } assignment
                                || model.GetSymbolInfo(assignment.Left).Symbol is not IPropertySymbol option)
                            {
                                return false;
                            }

                            single |= option.Name == "SingleReader"
                                && IsExactFrameworkType(option.ContainingType, "System.Threading.Channels.ChannelOptions", typeof(System.Threading.Channels.Channel).Assembly.GetName())
                                && model.GetConstantValue(assignment.Right) is { HasValue: true, Value: true };

                            drop |= option.Name == "FullMode"
                                && IsExactFrameworkType(option.ContainingType, "System.Threading.Channels.BoundedChannelOptions", typeof(System.Threading.Channels.Channel).Assembly.GetName())
                                && model.GetSymbolInfo(assignment.Right).Symbol is IFieldSymbol { Name: "DropWrite" } mode
                                && IsExactFrameworkType(mode.ContainingType, "System.Threading.Channels.BoundedChannelFullMode", typeof(System.Threading.Channels.Channel).Assembly.GetName());
                        }

                        return single && drop;
                    }

                    if (ResolveCleanupInvocationTarget(factory, owner, call, proof) is { } target && path.Add(factory))
                    {
                        try
                        {
                            AuthoredMember bound = BindCleanupInvocationContext(owner, call, target, proof);

                            ExpressionSyntax[] values = ReturnedExpressions(bound.Syntax);

                            return values.Length != 0 && values.All(value => Origin(value, bound.Model, path, bound, reader));
                        }
                        finally
                        {
                            path.Remove(factory);
                        }
                    }
                }

                return HasOnlyReviewedValueSources(expression, model, path, owner,
                    (value, sourceModel, sourcePath, sourceContext) => Origin(value, sourceModel, sourcePath, sourceContext, reader));
            }

            return Origin(access.Expression, member.Model, new(SymbolEqualityComparer.Default), member, true);
        }

        private bool HasCompleteEagerCallableOrigin(
            ExpressionSyntax expression,
            SemanticModel model,
            HashSet<ISymbol> path,
            AuthoredMember? context)
        {
            if (expression is AnonymousFunctionExpressionSyntax
                || expression is not InvocationExpressionSyntax
                    && model.GetSymbolInfo(expression).Symbol is IMethodSymbol)
            {
                return true;
            }

            if (expression is ConditionalExpressionSyntax conditional)
            {
                return HasCompleteEagerCallableOrigin(conditional.WhenTrue, model, path, context)
                    && HasCompleteEagerCallableOrigin(conditional.WhenFalse, model, path, context);
            }

            return HasOnlyReviewedValueSources(expression, model, path, context, HasCompleteEagerCallableOrigin);
        }

        private static bool IsExactEagerCollectionCallback(IMethodSymbol method)
        {
            IMethodSymbol definition = (method.ReducedFrom ?? method).OriginalDefinition;

            if (definition.Parameters.Any(static parameter => parameter.RefKind != RefKind.None)
                || IsAwaitable(method.ReturnType))
            {
                return false;
            }

            static bool Same(ITypeSymbol left, ITypeSymbol right) => SymbolEqualityComparer.Default.Equals(left, right);

            static bool Carrier(ITypeSymbol type, string name, params ITypeSymbol[] arguments) =>
                type is INamedTypeSymbol named
                && IsExactFrameworkType(named, name, name == "System.Collections.Immutable.ImmutableArray`1"
                    ? typeof(ImmutableArray<>).Assembly.GetName() : typeof(Func<>).Assembly.GetName())
                && named.TypeArguments.Length == arguments.Length
                && named.TypeArguments.Zip(arguments).All(static pair => Same(pair.First, pair.Second));

            if (!definition.IsStatic && definition.Name == "Find" && definition.Arity == 0
                && IsExactFrameworkType(definition.ContainingType, "System.Collections.Generic.List`1", typeof(List<>).Assembly.GetName())
                && definition.ContainingType.TypeArguments is [{ } element]
                && definition.Parameters is [{ Type: { } predicate }])
            {
                return Same(definition.ReturnType, element)
                    && Carrier(predicate, "System.Predicate`1", element);
            }

            if (!definition.IsStatic
                || !IsExactFrameworkType(definition.ContainingType, "System.Linq.ImmutableArrayExtensions", typeof(ImmutableArray<>).Assembly.GetName()))
            {
                return false;
            }

            if (definition.Name == "Aggregate"
                && definition.TypeParameters is [{ } accumulator, { } item]
                && definition.Parameters is [{ Type: { } source }, { Type: { } seed }, { Type: { } callback }])
            {
                return Carrier(source, "System.Collections.Immutable.ImmutableArray`1", item)
                    && Same(seed, accumulator)
                    && Same(definition.ReturnType, accumulator)
                    && Carrier(callback, "System.Func`3", accumulator, item, accumulator);
            }

            if (definition.Name is "All" or "Single"
                && definition.TypeParameters is [{ } value]
                && definition.Parameters is [{ Type: { } values }, { Type: INamedTypeSymbol { TypeArguments: [_, { } result] } filter }])
            {
                return Carrier(values, "System.Collections.Immutable.ImmutableArray`1", value)
                    && result.SpecialType == SpecialType.System_Boolean
                    && Carrier(filter, "System.Func`2", value, result)
                    && (definition.Name == "All" ? definition.ReturnType.SpecialType == SpecialType.System_Boolean
                        : Same(definition.ReturnType, value));
            }

            return false;
        }

        private static bool IsKnownSynchronousCallback(IMethodSymbol method)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            string type = TypeKey(definition.ContainingType);

            return IsExactEagerCollectionCallback(method)
                || type == "System.Linq.Enumerable"
                    && definition.Name is "Aggregate" or "All" or "Any" or "Average" or "Count" or "First" or "FirstOrDefault" or "Last" or "LastOrDefault" or "LongCount" or "Max" or "MaxBy" or "Min" or "MinBy" or "Single" or "SingleOrDefault" or "Sum" or "ToDictionary" or "ToHashSet" or "ToLookup"
                || type == "System.Array"
                    && definition.Name is "Exists" or "Sort"
                || type == "System.Collections.Concurrent.ConcurrentDictionary`2"
                    && definition.Name is "AddOrUpdate" or "GetOrAdd"
                || type == "System.Collections.Generic.List`1"
                    && definition.Name is "ConvertAll" or "FindIndex" or "ForEach" or "RemoveAll" or "Sort"
                || type == "System.Collections.Generic.HashSet`1"
                    && definition.Name == "RemoveWhere"
                || type == "System.String"
                    && definition.Name == "Create"
                || type == "System.Linq.ImmutableArrayExtensions"
                    && definition.Name is "Any" or "First" or "FirstOrDefault"
                || type == "System.Threading.Tasks.Parallel"
                    && definition.Name is "For" or "ForEach" or "Invoke";
        }

        private static bool IsReviewedEffectFreeRecoveryTerminal(
            AuthoredMember member,
            InvocationExpressionSyntax call,
            IMethodSymbol method)
        {
            if (member.RecoveryContext is not
                {
                    Kind: "data-retention-mutation",
                    CheckpointVersion: 0,
                    Disposition: RecoveryDisposition.OrdinaryDbOnly,
                }
                || TypeKey(member.Symbol.ContainingType)
                    != "RetroDownfall.Arcanum.Infrastructure.Data.DataRetentionService"
                || member.Symbol.Name != "RecoverMutationAsync"
                || TypeKey(method.ContainingType)
                    != "RetroDownfall.Arcanum.Core.Operations.LongRunningOperationRecoveryResult"
                || method.Name != "Abandoned"
                || call.Parent is not ReturnStatementSyntax
                || call.Ancestors().OfType<IfStatementSyntax>().FirstOrDefault() is not
                { Condition: { } condition })
            {
                return false;
            }

            return condition.DescendantNodesAndSelf()
                .OfType<BinaryExpressionSyntax>()
                .Any(comparison => comparison.IsKind(SyntaxKind.EqualsExpression)
                    && member.Model.GetConstantValue(comparison.Right) is
                    {
                        HasValue: true,
                        Value: 0,
                    }
                    && member.Model.GetSymbolInfo(comparison.Left).Symbol is
                        IPropertySymbol { Name: "CheckpointVersion" });
        }

        private bool IsReviewedDormantTestSeam(IMethodSymbol method)
        {
            const string cleanupObserverType =
                "RetroDownfall.Arcanum.Infrastructure.InstallationReset.IInstallationResetOfflineCleanupTestObserver";

            if (TypeKey(method.ContainingType) == cleanupObserverType
                && method.Name is
                    "AfterInitialCapture" or "AfterFileDeleted" or "AfterDirectoryDeleted")
            {
                const string cleanupType =
                    "RetroDownfall.Arcanum.Infrastructure.InstallationReset.InstallationResetOfflineCleanup";

                bool productionConstructsObserver = AuthoredMembers
                    .SelectMany(member => member.Syntax.DescendantNodes()
                        .OfType<BaseObjectCreationExpressionSyntax>()
                        .Select(creation => (member, creation)))
                    .Any(candidate => candidate.member.Model.GetSymbolInfo(candidate.creation).Symbol
                            is IMethodSymbol constructor
                        && TypeKey(constructor.ContainingType) == cleanupType
                        && constructor.Parameters.Any(parameter =>
                            TypeKey(parameter.Type) == cleanupObserverType));

                int invocationCount = AuthoredMembers
                    .Where(member => TypeKey(member.Symbol.ContainingType) == cleanupType)
                    .SelectMany(member => member.Syntax.DescendantNodes()
                        .OfType<InvocationExpressionSyntax>()
                        .Select(call => (member, call)))
                    .Count(candidate => candidate.member.Model.GetSymbolInfo(candidate.call).Symbol
                            is IMethodSymbol called
                        && TypeKey(called.ContainingType) == cleanupObserverType
                        && called.Name == method.Name);

                return !productionConstructsObserver && invocationCount == 1;
            }

            const string seamType =
                "RetroDownfall.Arcanum.Infrastructure.Data.GrimoireScopedConsumerTestSeam";

            if (TypeKey(method.ContainingType) != seamType
                || method.Name != "PauseAsync")
            {
                return false;
            }

            AuthoredMember[] pauses = AuthoredMembers
                .Where(member => SymbolEqualityComparer.Default.Equals(
                    member.Symbol.OriginalDefinition,
                    method.OriginalDefinition))
                .ToArray();

            if (pauses is not [AuthoredMember pause])
            {
                return false;
            }

            AuthoredMember[] overrides = AuthoredMembers
                .Where(member => TypeKey(member.Symbol.ContainingType) == seamType
                    && member.Symbol.Name == "Override")
                .ToArray();

            if (overrides is not [AuthoredMember])
            {
                return false;
            }

            bool productionRegistersCheckpoint = AuthoredMembers
                .Where(member => TypeKey(member.Symbol.ContainingType) != seamType)
                .Any(member => member.Syntax.DescendantNodes()
                    .OfType<InvocationExpressionSyntax>()
                    .Any(call => member.Model.GetSymbolInfo(call).Symbol
                            is IMethodSymbol called
                        && TypeKey(called.ContainingType) == seamType
                        && called.Name == "Override"));

            InvocationExpressionSyntax[] callbackInvocations = pause.Syntax
                .DescendantNodes()
                .OfType<InvocationExpressionSyntax>()
                .Where(call => pause.Model.GetSymbolInfo(call).Symbol
                    is IMethodSymbol
                {
                    MethodKind: MethodKind.DelegateInvoke,
                })
                .ToArray();

            return !productionRegistersCheckpoint
                && callbackInvocations is [InvocationExpressionSyntax];
        }

        private TraversalEvidence TraverseDetachedExternalCallbacks(
            AuthoredMember member,
            IReadOnlyList<ExpressionSyntax> callbacks,
            string callee,
            SyntaxNode carrier,
            string rootType,
            string operationId,
            HashSet<TraversalStateIdentity> active,
            bool lifecycle)
        {
            bool proven = callbacks.Count != 0;

            TraversalEvidence evidence = TraversalEvidence.NoEvidence;

            foreach (ExpressionSyntax callback in callbacks)
            {
                AuthoredMember[] bodies = ResolveCallableTargets(
                    callback,
                    member.Model,
                    member.CallableBindings,
                    member.AbsentCallables);

                proven &= bodies.Length != 0;

                foreach (AuthoredMember body in bodies)
                {
                    AuthoredMember capturedBody = BindExternalCallbackContext(member, body);

                    bool capturesOuterAdmission = member.ScopedLeaseInstance is not null
                        || CallbackCapturesOuterAdmission(capturedBody);

                    AuthoredMember detachedBody = WithoutInheritedAdmission(capturedBody);

                    TraversalEvidence bodyEvidence = Traverse(
                        detachedBody,
                        rootType,
                        operationId + "/callback@" + Location(carrier),
                        active,
                        lifecycle,
                        inheritedWork: null,
                        inheritedEffect: null,
                        completionOwned: true,
                        recoveryEffect: null);

                    evidence = MergeEvidence(evidence, bodyEvidence);

                    proven &= !capturesOuterAdmission
                        && (bodyEvidence == TraversalEvidence.NoEvidence
                            || HasAdmissionSeed(detachedBody));
                }
            }

            if (!proven)
            {
                RefuseTraversalCompletion();

                diagnostics.Add(new(
                    "HOSTED_CALLBACK_OWNERSHIP_UNPROVEN",
                    RootOperation(operationId)
                        + "/callback@"
                        + Location(carrier),
                    callee
                        + "; A retained external callback must be exactly bound and reacquire admission for every later producer unit."));
            }

            return evidence;
        }

        private static AuthoredMember BindExternalCallbackContext(
            AuthoredMember caller,
            AuthoredMember body) => body with
            {
                AdmissionBindings = caller.AdmissionBindings,
                CallableBindings = caller.CallableBindings,
                AbsentCallables = caller.AbsentCallables,
                ConcreteBindings = caller.ConcreteBindings,
                RecoveryBindings = caller.RecoveryBindings,
                RecoveryContext = caller.RecoveryContext,
                ValueBindings = caller.ValueBindings,
            };

        private bool CallbackCapturesOuterAdmission(AuthoredMember body, string? origin = null)
        {
            AdmissionOriginQueryContext query = new();

            Stack<SyntaxNode> pending = new();

            pending.Push(body.Syntax);

            while (pending.TryPop(out SyntaxNode? node))
            {
                if (!query.Visit()) return true;

                if (node is InvocationExpressionSyntax invocation)
                {
                    if (!query.Visit()) return true;

                    if (body.Model.GetOperation(invocation) is INameOfOperation) continue;
                }

                foreach (SyntaxNode child in node.ChildNodes())
                {
                    if (!query.Visit()) return true;

                    pending.Push(child);
                }

                if (node is not IdentifierNameSyntax reference) continue;

                ISymbol? symbol = body.Model.GetSymbolInfo(reference).Symbol;

                if (symbol is not ILocalSymbol and not IParameterSymbol
                    || symbol.DeclaringSyntaxReferences.Any(declaration =>
                        declaration.SyntaxTree == body.Syntax.SyntaxTree
                            && body.Syntax.Span.Contains(declaration.Span))) continue;

                // A captured outer handle is not admission acquired by the callback.
                // Keep the caller's bindings for this check, before detaching authority.
                ITypeSymbol? capturedType = body.Model.GetTypeInfo(reference).Type;

                if (capturedType?.TypeKind == TypeKind.Enum
                    || capturedType?.SpecialType is SpecialType.System_String or SpecialType.System_Boolean
                        or SpecialType.System_Char or SpecialType.System_SByte or SpecialType.System_Byte
                        or SpecialType.System_Int16 or SpecialType.System_UInt16
                        or SpecialType.System_Int32 or SpecialType.System_UInt32
                        or SpecialType.System_Int64 or SpecialType.System_UInt64
                        or SpecialType.System_Single or SpecialType.System_Double or SpecialType.System_Decimal
                        or SpecialType.System_IntPtr or SpecialType.System_UIntPtr) continue;

                bool carries = MayCarryAdmissionHandle(body, reference, query);

                if (!query.Complete) return true;

                if (carries)
                {
                    if (origin is null) return true;

                    IReadOnlySet<string> origins = AdmissionOrigins(body, reference,
                        new HashSet<ISymbol>(SymbolEqualityComparer.Default), query);

                    if (!query.Complete || origins.Contains(origin)) return true;
                }
            }

            return false;
        }

        private LazyFactoryResolution? ResolveLazyFactory(
            AuthoredMember member,
            ExpressionSyntax receiver)
        {
            ITypeSymbol? lazyType = member.Model.GetTypeInfo(receiver).Type;

            if (lazyType is null
                || TypeKey(lazyType) != "System.Lazy`1")
            {
                return null;
            }

            List<BaseObjectCreationExpressionSyntax> constructions = [];

            bool usesAtomicPublication = TryResolveAtomicLazyPublication(
                member,
                receiver,
                lazyType,
                out ISymbol? storage,
                out BaseObjectCreationExpressionSyntax? atomicConstruction);

            if (usesAtomicPublication)
            {
                constructions.Add(atomicConstruction!);
            }
            else
            {
                storage = member.Model.GetSymbolInfo(
                    StripTransparentExpression(receiver)).Symbol;

                if (storage is not IFieldSymbol and not ILocalSymbol
                    and not IPropertySymbol)
                {
                    return null;
                }

                CollectLazyConstructions(
                    receiver,
                    member.Model,
                    lazyType,
                    constructions,
                    new HashSet<ISymbol>(SymbolEqualityComparer.Default));
            }

            BaseObjectCreationExpressionSyntax[] exactConstructions = constructions
                .DistinctBy(static construction =>
                    (construction.SyntaxTree, construction.SpanStart))
                .ToArray();

            if (exactConstructions is not
                [BaseObjectCreationExpressionSyntax construction])
            {
                return null;
            }

            SemanticModel model = semanticModels[construction.SyntaxTree];

            if (model.GetOperation(construction) is not
                IObjectCreationOperation operation)
            {
                return null;
            }

            IArgumentOperation[] factoryArguments = operation.Arguments
                .Where(static argument => argument.Parameter?.Type.TypeKind
                    == TypeKind.Delegate)
                .ToArray();

            if (factoryArguments is not [IArgumentOperation factoryArgument]
                || (factoryArgument.Syntax is ArgumentSyntax argument
                        ? argument.Expression
                        : factoryArgument.Value.Syntax) is not
                    ExpressionSyntax factoryExpression)
            {
                return null;
            }

            bool contextual = member.Syntax.SyntaxTree == construction.SyntaxTree
                && member.Syntax.Span.Contains(construction.Span);

            AuthoredMember[] factories = ResolveCallableTargets(
                factoryExpression,
                model,
                contextual ? member.CallableBindings : null,
                contextual ? member.AbsentCallables : null);

            if (factories is not [AuthoredMember factory])
            {
                return null;
            }

            IArgumentOperation[] modeArguments = operation.Arguments
                .Where(static argument => argument.Parameter is { Type: { } type }
                    && TypeKey(type)
                        == "System.Threading.LazyThreadSafetyMode")
                .ToArray();

            bool usesExecutionAndPublication = modeArguments.Length switch
            {
                0 => operation.Constructor is { } constructor
                    && !constructor.Parameters.Any(static parameter =>
                        parameter.Type.SpecialType
                            == SpecialType.System_Boolean),
                1 => modeArguments[0].Value.ConstantValue is
                {
                    HasValue: true,
                    Value: int value,
                }
                    && value
                        == (int)System.Threading.LazyThreadSafetyMode
                            .ExecutionAndPublication,
                _ => false,
            };

            return new(
                storage!,
                construction,
                factory,
                usesExecutionAndPublication,
                usesAtomicPublication);
        }

        private static bool TryResolveAtomicLazyPublication(
            AuthoredMember member,
            ExpressionSyntax receiver,
            ITypeSymbol lazyType,
            out ISymbol? storage,
            out BaseObjectCreationExpressionSyntax? construction)
        {
            storage = null;

            construction = null;

            if (StripTransparentExpression(receiver) is not
                    InvocationExpressionSyntax call
                || member.Model.GetOperation(call) is not
                    IInvocationOperation operation
                || operation.TargetMethod.Name != "GetOrAdd"
                || TypeKey(operation.TargetMethod.ContainingType)
                    != "System.Collections.Concurrent.ConcurrentDictionary`2"
                || !SymbolEqualityComparer.Default.Equals(
                    operation.TargetMethod.ReturnType,
                    lazyType))
            {
                return false;
            }

            IArgumentOperation[] factories = operation.Arguments
                .Where(static argument => argument.Parameter?.Type.TypeKind
                    == TypeKind.Delegate)
                .ToArray();

            if (factories is not [IArgumentOperation factoryArgument]
                || (factoryArgument.Syntax is ArgumentSyntax argument
                        ? argument.Expression
                        : factoryArgument.Value.Syntax) is not
                    ExpressionSyntax factoryExpression)
            {
                return false;
            }

            factoryExpression = StripTransparentExpression(factoryExpression);

            construction = factoryExpression switch
            {
                SimpleLambdaExpressionSyntax
                {
                    Body: BaseObjectCreationExpressionSyntax created,
                } => created,
                ParenthesizedLambdaExpressionSyntax
                {
                    Body: BaseObjectCreationExpressionSyntax created,
                } => created,
                _ => null,
            };

            if (construction is null
                || member.Model.GetTypeInfo(construction).Type is not
                { } constructedType
                || !SymbolEqualityComparer.Default.Equals(
                    constructedType,
                    lazyType)
                || member.Model.GetSymbolInfo(factoryExpression).Symbol is not
                    IMethodSymbol factorySymbol)
            {
                construction = null;

                return false;
            }

            storage = factorySymbol;

            return true;
        }

        private static bool IsProvenCreatedLazyRead(
            AuthoredMember member,
            MemberAccessExpressionSyntax lazyValue)
        {
            ISymbol? storage = member.Model.GetSymbolInfo(
                StripTransparentExpression(lazyValue.Expression)).Symbol;

            if (storage is null)
            {
                return false;
            }

            bool ProvesCreated(ExpressionSyntax condition, bool whenTrue) =>
                condition switch
                {
                    ParenthesizedExpressionSyntax parentheses =>
                        ProvesCreated(parentheses.Expression, whenTrue),
                    PrefixUnaryExpressionSyntax negation
                        when negation.IsKind(SyntaxKind.LogicalNotExpression) =>
                        ProvesCreated(negation.Operand, !whenTrue),
                    BinaryExpressionSyntax conjunction
                        when whenTrue
                            && conjunction.IsKind(
                                SyntaxKind.LogicalAndExpression) =>
                        ProvesCreated(conjunction.Left, true)
                            || ProvesCreated(conjunction.Right, true),
                    BinaryExpressionSyntax disjunction
                        when !whenTrue
                            && disjunction.IsKind(
                                SyntaxKind.LogicalOrExpression) =>
                        ProvesCreated(disjunction.Left, false)
                            || ProvesCreated(disjunction.Right, false),
                    MemberAccessExpressionSyntax
                    {
                        Name.Identifier.ValueText: "IsValueCreated",
                    } created
                        when whenTrue
                            && member.Model.GetSymbolInfo(created).Symbol is
                                IPropertySymbol
                            {
                                ContainingType: { } containing,
                            }
                            && TypeKey(containing) == "System.Lazy`1"
                            && SymbolEqualityComparer.Default.Equals(
                                member.Model.GetSymbolInfo(
                                    StripTransparentExpression(
                                        created.Expression)).Symbol,
                                storage) => true,
                    _ => false,
                };

            foreach (IfStatementSyntax guard in lazyValue.Ancestors()
                .OfType<IfStatementSyntax>())
            {
                if (guard.Statement.Span.Contains(lazyValue.Span)
                        && ProvesCreated(guard.Condition, true)
                    || guard.Else?.Statement.Span.Contains(lazyValue.Span) == true
                        && ProvesCreated(guard.Condition, false))
                {
                    return true;
                }
            }

            StatementSyntax? useStatement = lazyValue.Ancestors()
                .OfType<StatementSyntax>()
                .FirstOrDefault();

            if (useStatement?.Parent is not BlockSyntax block)
            {
                return false;
            }

            foreach (IfStatementSyntax guard in block.Statements
                .OfType<IfStatementSyntax>()
                .Where(guard => guard.Span.End < useStatement.SpanStart
                    && guard.Else is null
                    && FailureTerminates(guard)
                    && ProvesCreated(guard.Condition, false)))
            {
                bool reassigned = block.DescendantNodes()
                    .Where(node => node.SpanStart > guard.Span.End
                        && node.Span.End < lazyValue.SpanStart)
                    .Any(node => node switch
                    {
                        AssignmentExpressionSyntax assignment =>
                            SymbolEqualityComparer.Default.Equals(
                                member.Model.GetSymbolInfo(
                                    assignment.Left).Symbol,
                                storage),
                        ArgumentSyntax argument
                            when argument.RefKindKeyword.Kind() is
                                SyntaxKind.RefKeyword or SyntaxKind.OutKeyword =>
                            SymbolEqualityComparer.Default.Equals(
                                member.Model.GetSymbolInfo(
                                    argument.Expression).Symbol,
                                storage),
                        _ => false,
                    });

                if (!reassigned)
                {
                    return true;
                }
            }

            return false;
        }

        private BoundedDataProof ProveBoundedLazyData(
            LazyFactoryResolution resolution)
        {
            // Permanent for this graph, including cached proofs: rollback leaves helper caches.
            boundedDataProbeEncountered = true;

            // Even a previously completed proof belongs to the rollback lane, not this witness.
            RefuseTraversalCompletion();

            if (boundedLazyData.TryGetValue(
                    resolution.Storage,
                    out BoundedDataProof cached))
            {
                return cached;
            }

            if (!activeBoundedLazyData.Add(resolution.Storage))
            {
                return BoundedDataProof.Unknown;
            }

            BoundedDataProof proof;

            ISymbol? previousProbe = activeBoundedDataProbe;

            activeBoundedDataProbe = resolution.Storage;

            boundedLazyDataEvidence[resolution.Storage] = [];

            try
            {
                BoundedDataProof structure = InspectBoundedDataStructure(
                    resolution.Factory,
                    new HashSet<GraphMemberIdentity>());

                proof = structure == BoundedDataProof.PureBoundedData
                    ? ProbeBoundedDataTraversal(resolution)
                    : structure;

                if (proof == BoundedDataProof.PureBoundedData
                    && (!resolution.UsesExecutionAndPublication
                        || !resolution.UsesAtomicPublication
                            && !HasStableLazyStorage(resolution)))
                {
                    proof = BoundedDataProof.Unknown;
                }
            }
            finally
            {
                activeBoundedDataProbe = previousProbe;

                activeBoundedLazyData.Remove(resolution.Storage);
            }

            boundedLazyData[resolution.Storage] = proof;

            return proof;
        }

        private bool HasStableLazyStorage(LazyFactoryResolution resolution)
        {
            bool exactInitializer = resolution.Storage
                .DeclaringSyntaxReferences.Any(reference =>
                    reference.GetSyntax() is VariableDeclaratorSyntax
                    {
                        Initializer.Value: { } initializer,
                    }
                    && initializer.Span.Contains(
                        resolution.Construction.Span));

            bool stableKind = resolution.Storage is ILocalSymbol
                || resolution.Storage is IFieldSymbol
                {
                    IsStatic: true,
                    IsReadOnly: true,
                };

            if (!exactInitializer || !stableKind)
            {
                return false;
            }

            return !AuthoredMembers.Any(owner => owner.Syntax
                .DescendantNodesAndSelf()
                .Any(node => node switch
                {
                    AssignmentExpressionSyntax assignment =>
                        SymbolEqualityComparer.Default.Equals(
                            owner.Model.GetSymbolInfo(assignment.Left).Symbol,
                            resolution.Storage),
                    ArgumentSyntax argument
                        when argument.RefKindKeyword.Kind() is
                            SyntaxKind.RefKeyword or SyntaxKind.OutKeyword =>
                        SymbolEqualityComparer.Default.Equals(
                            owner.Model.GetSymbolInfo(argument.Expression).Symbol,
                            resolution.Storage),
                    _ => false,
                }));
        }

        private BoundedDataProof ProbeBoundedDataTraversal(
            LazyFactoryResolution resolution)
        {
            boundedDataProbeEncountered = true;

            int diagnosticStart = diagnostics.Count;

            HashSet<string> existingSites = [.. sites.Keys];

            HashSet<string> existingCapsules = [.. admissionCapsules.Keys];

            TraversalEvidence evidence;

            bool emittedDiagnostic;

            ISymbol? previousProbe = activeBoundedDataProbe;

            activeBoundedDataProbe = resolution.Storage;

            try
            {
                evidence = Traverse(
                    resolution.Factory,
                    "<bounded-data-proof>",
                    "<bounded-data-proof>:" + Location(resolution.Construction),
                    new HashSet<TraversalStateIdentity>(),
                    lifecycle: false,
                    completionOwned: true);

                emittedDiagnostic = diagnostics.Count != diagnosticStart;
            }
            finally
            {
                activeBoundedDataProbe = previousProbe;

                if (diagnostics.Count > diagnosticStart)
                {
                    diagnostics.RemoveRange(
                        diagnosticStart,
                        diagnostics.Count - diagnosticStart);
                }

                foreach (string site in sites.Keys
                    .Where(site => !existingSites.Contains(site))
                    .ToArray())
                {
                    sites.Remove(site);

                    siteOccurrences.Remove(site);
                }

                foreach (string capsule in admissionCapsules.Keys
                    .Where(capsule => !existingCapsules.Contains(capsule))
                    .ToArray())
                {
                    admissionCapsules.Remove(capsule);
                }
            }

            if (evidence == TraversalEvidence.Evidence)
            {
                return BoundedDataProof.Producer;
            }

            return evidence == TraversalEvidence.Inconclusive
                    || emittedDiagnostic
                ? BoundedDataProof.Unknown
                : BoundedDataProof.PureBoundedData;
        }

        internal (string[] Proofs, int Sites, int OccurrenceStamps, IReadOnlyList<HostedProducerInventoryDiagnostic> Diagnostics, bool MatrixResolved) ProbeRepeatedBoundedDataRollback(int repetitions, bool useStructuralEntry)
        {
            AuthoredMember reader = AuthoredMembers.Single(static member => member.Symbol.ContainingType.Name == "LazyRollbackFixture" && member.Symbol.Name == "Read");

            MemberAccessExpressionSyntax value = reader.Syntax.DescendantNodesAndSelf().OfType<MemberAccessExpressionSyntax>().Single();

            LazyFactoryResolution resolution = ResolveLazyFactory(reader, value.Expression)
                ?? throw new InvalidOperationException("The rollback fixture must resolve one exact lazy factory.");

            boundedLazyDataEvidence[resolution.Storage] = [];

            string[] proofs = Enumerable.Range(0, repetitions).Select(_ => (useStructuralEntry ? ProveBoundedLazyData(resolution) : ProbeBoundedDataTraversal(resolution)).ToString()).ToArray();

            return (proofs, sites.Count, siteOccurrences.Count, CompleteDiscovery().Diagnostics, recoveryMatrixResolved);
        }

        private BoundedDataProof InspectBoundedDataStructure(
            AuthoredMember member,
            HashSet<GraphMemberIdentity> path)
        {
            GraphMemberIdentity identity = MemberIdentity(member);

            if (!path.Add(identity))
            {
                return BoundedDataProof.Unknown;
            }

            try
            {
                if (member.Symbol.IsAsync
                    || IsDeferredDataCarrier(member.Symbol.ReturnType)
                    || IsIteratorMember(member))
                {
                    return RecordBoundedDataProducer(
                        "deferred-member:"
                            + Normalize(member.Symbol));
                }

                BoundedDataProof proof = BoundedDataProof.PureBoundedData;

                foreach (SyntaxNode node in member.Syntax.DescendantNodesAndSelf(
                    candidate => candidate == member.Syntax
                        || candidate is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax))
                {
                    if (node is AssignmentExpressionSyntax
                            or PrefixUnaryExpressionSyntax
                            or PostfixUnaryExpressionSyntax
                        && WritesSharedState(member, node)
                        || node is ArgumentSyntax refArgument
                            && refArgument.RefKindKeyword.Kind() is
                                SyntaxKind.RefKeyword or SyntaxKind.OutKeyword
                            && member.Model.GetSymbolInfo(
                                refArgument.Expression).Symbol is IFieldSymbol)
                    {
                        return RecordBoundedDataProducer(
                            "shared-mutation@" + Location(node));
                    }

                    if (node is InvocationExpressionSyntax call
                        && member.Model.GetOperation(call) is
                            IDynamicInvocationOperation)
                    {
                        return BoundedDataProof.Unknown;
                    }

                    if (node is not InvocationExpressionSyntax
                            and not BaseObjectCreationExpressionSyntax
                        || member.Model.GetSymbolInfo(node).Symbol is not
                            IMethodSymbol method)
                    {
                        continue;
                    }

                    string callee = Normalize(method);

                    if (IsDetachedBoundedDataCarrier(method, callee))
                    {
                        return RecordBoundedDataProducer(
                            "detached-call:" + callee + "@" + Location(node));
                    }

                    if (node is InvocationExpressionSyntax invocation)
                    {
                        if ((IsAsynchronousCallback(method)
                                || CompletionOwnedExternalAwaitables.Contains(
                                    callee))
                            && CompletionPoint(member, invocation, false) is null
                            || IsKnownLazyCallback(method)
                                && LazyCompletionPoint(member, invocation) is null)
                        {
                            return RecordBoundedDataProducer(
                                "unjoined-call:" + callee + "@" + Location(node));
                        }
                    }

                    ExpressionSyntax[] callbacks = node switch
                    {
                        InvocationExpressionSyntax callbackCall
                            when method.MethodKind
                                == MethodKind.DelegateInvoke =>
                            [DelegateReceiver(member, callbackCall)],
                        InvocationExpressionSyntax callbackCall =>
                            callbackCall.ArgumentList.Arguments
                                .Where(argument =>
                                    !argument.RefKindKeyword.IsKind(
                                        SyntaxKind.OutKeyword)
                                    && IsDelegateExpression(
                                        member.Model,
                                        argument.Expression))
                                .Select(static argument => argument.Expression)
                                .ToArray(),
                        BaseObjectCreationExpressionSyntax creation
                            when creation.ArgumentList is not null =>
                            creation.ArgumentList.Arguments
                                .Where(argument =>
                                    !argument.RefKindKeyword.IsKind(
                                        SyntaxKind.OutKeyword)
                                    && IsDelegateExpression(
                                        member.Model,
                                        argument.Expression))
                                .Select(static argument => argument.Expression)
                                .ToArray(),
                        _ => [],
                    };

                    if (callee != "System.Lazy`1..ctor")
                    {
                        foreach (ExpressionSyntax callback in callbacks)
                        {
                            AuthoredMember[] bodies = ResolveCallableTargets(
                                callback,
                                member.Model,
                                member.CallableBindings,
                                member.AbsentCallables);

                            if (bodies.Length == 0)
                            {
                                if (!IsEffectFreeExternalCallable(
                                        callback,
                                        member))
                                {
                                    proof = MergeBoundedDataProof(
                                        proof,
                                        BoundedDataProof.Unknown);
                                }

                                continue;
                            }

                            foreach (AuthoredMember body in bodies)
                            {
                                proof = MergeBoundedDataProof(
                                    proof,
                                    InspectBoundedDataStructure(
                                        body,
                                        path));
                            }
                        }
                    }

                    AuthoredMember? target = ResolveInvocationTarget(
                        method,
                        member,
                        node);

                    AuthoredMember[] boundTargets = target is null
                        ? ResolveBoundImplementations(
                            method,
                            member.Model.Compilation)
                        : [];

                    AuthoredMember[] strategyTargets = ResolveStrategyTargets(
                        method);

                    AuthoredMember[] reviewedClosedTargets =
                        ResolveReviewedClosedDispatchTargets(
                            method,
                            node,
                            member);

                    AuthoredMember[] targets = strategyTargets.Length != 0
                        ? strategyTargets
                        : target is not null
                            ? [target]
                            : boundTargets.Length != 0
                                ? boundTargets
                                : reviewedClosedTargets;

                    if (target is null && HasIncompleteDefaultInterfaceBinding(method, member.Model.Compilation))
                    {
                        proof = MergeBoundedDataProof(proof, BoundedDataProof.Unknown);
                    }

                    foreach (AuthoredMember exactTarget in targets)
                    {
                        AuthoredMember boundTarget = node switch
                        {
                            InvocationExpressionSyntax boundCall =>
                                BindAdmissionArguments(
                                    member,
                                    boundCall,
                                    exactTarget),
                            BaseObjectCreationExpressionSyntax creation =>
                                BindConstructorArguments(
                                    member,
                                    creation,
                                    exactTarget),
                            _ => exactTarget,
                        };

                        proof = MergeBoundedDataProof(
                            proof,
                            InspectBoundedDataStructure(boundTarget, path));
                    }

                    if (proof == BoundedDataProof.Producer)
                    {
                        RecordBoundedDataProducer(
                            "producer-target:" + callee + "@" + Location(node));

                        return proof;
                    }
                }

                foreach (MemberAccessExpressionSyntax lazyValue in member.Syntax
                    .DescendantNodesAndSelf(candidate =>
                        candidate == member.Syntax
                            || candidate is not AnonymousFunctionExpressionSyntax
                                and not LocalFunctionStatementSyntax)
                    .OfType<MemberAccessExpressionSyntax>())
                {
                    if (member.Model.GetSymbolInfo(lazyValue).Symbol is not
                            IPropertySymbol
                        {
                            Name: "Value",
                            ContainingType: { } lazy,
                        }
                        || TypeKey(lazy) != "System.Lazy`1")
                    {
                        continue;
                    }

                    LazyFactoryResolution? nested = ResolveLazyFactory(
                        member,
                        lazyValue.Expression);

                    proof = MergeBoundedDataProof(
                        proof,
                        nested is null
                            ? BoundedDataProof.Unknown
                            : ProveBoundedLazyData(nested));
                }

                return proof;
            }
            finally
            {
                path.Remove(identity);
            }
        }

        private BoundedDataProof RecordBoundedDataProducer(string evidence)
        {
            if (activeBoundedDataProbe is { } storage)
            {
                boundedLazyDataEvidence
                    .GetValueOrDefault(storage)?
                    .Add(evidence);
            }

            return BoundedDataProof.Producer;
        }

        private bool HasEscapingDeferredWork(
            AuthoredMember member,
            HashSet<GraphMemberIdentity> path,
            bool root = true)
        {
            GraphMemberIdentity identity = MemberIdentity(member);

            if (!path.Add(identity))
            {
                return true;
            }

            try
            {
                if (root && (member.Symbol.IsAsync
                    || IsDeferredDataCarrier(member.Symbol.ReturnType)
                    || IsIteratorMember(member)))
                {
                    return true;
                }

                foreach (InvocationExpressionSyntax call in member.Syntax
                    .DescendantNodesAndSelf(candidate =>
                        candidate == member.Syntax
                            || candidate is not AnonymousFunctionExpressionSyntax
                                and not LocalFunctionStatementSyntax)
                    .OfType<InvocationExpressionSyntax>())
                {
                    if (member.Model.GetSymbolInfo(call).Symbol is not
                        IMethodSymbol method)
                    {
                        return true;
                    }

                    string callee = Normalize(method);

                    if (IsDetachedBoundedDataCarrier(method, callee)
                        || (IsAsynchronousCallback(method)
                                || CompletionOwnedExternalAwaitables.Contains(
                                    callee))
                            && CompletionPoint(member, call, false) is null
                        || IsKnownLazyCallback(method)
                            && LazyCompletionPoint(member, call) is null)
                    {
                        return true;
                    }

                    AuthoredMember? target = ResolveInvocationTarget(
                        method,
                        member,
                        call);

                    if (target is not null
                        && HasEscapingDeferredWork(
                            BindAdmissionArguments(member, call, target),
                            path,
                            root: false))
                    {
                        return true;
                    }
                }

                return false;
            }
            finally
            {
                path.Remove(identity);
            }
        }

        private static bool IsDeferredDataCarrier(ITypeSymbol type) =>
            IsAwaitable(type)
            || IsLazySequence(type)
            || TypeKey(type) is
                "System.Collections.Generic.IAsyncEnumerable`1"
                    or "System.Lazy`1";

        private static bool IsAsynchronousCallback(IMethodSymbol method) =>
            Normalize(method) is
                "System.Threading.Tasks.Task.Run"
                    or "System.Threading.Tasks.TaskFactory.StartNew"
                    or "System.Threading.Tasks.Task.ContinueWith"
                    or "System.Threading.Tasks.Task`1.ContinueWith"
                    or "System.Threading.Tasks.Parallel.ForEachAsync";

        private static bool IsDetachedBoundedDataCarrier(
            IMethodSymbol method,
            string callee) =>
            DetachedExternalCallbackMethods.Contains(callee)
            || TypeKey(method.ContainingType) is
                "System.IO.FileSystemWatcher"
                    or "System.Threading.Timer"
                    or "System.Threading.PeriodicTimer"
                    or "System.Timers.Timer";

        private static BoundedDataProof MergeBoundedDataProof(
            BoundedDataProof left,
            BoundedDataProof right)
        {
            if (left == BoundedDataProof.Producer
                || right == BoundedDataProof.Producer)
            {
                return BoundedDataProof.Producer;
            }

            return left == BoundedDataProof.Unknown
                    || right == BoundedDataProof.Unknown
                ? BoundedDataProof.Unknown
                : BoundedDataProof.PureBoundedData;
        }

        private static bool WritesSharedState(
            AuthoredMember member,
            SyntaxNode node)
        {
            ExpressionSyntax? target = node switch
            {
                AssignmentExpressionSyntax assignment => assignment.Left,
                PrefixUnaryExpressionSyntax prefix
                    when prefix.IsKind(SyntaxKind.PreIncrementExpression)
                        || prefix.IsKind(SyntaxKind.PreDecrementExpression) =>
                    prefix.Operand,
                PostfixUnaryExpressionSyntax postfix
                    when postfix.IsKind(SyntaxKind.PostIncrementExpression)
                        || postfix.IsKind(SyntaxKind.PostDecrementExpression) =>
                    postfix.Operand,
                _ => null,
            };

            if (target is null)
            {
                return false;
            }

            if (node is AssignmentExpressionSyntax initializerAssignment
                && initializerAssignment.Ancestors()
                    .TakeWhile(ancestor => ancestor != member.Syntax)
                    .OfType<InitializerExpressionSyntax>()
                    .Any(initializer => initializer.Parent is
                        BaseObjectCreationExpressionSyntax
                            or WithExpressionSyntax))
            {
                return false;
            }

            ISymbol? symbol = member.Model.GetSymbolInfo(target).Symbol
                ?? member.Model.GetOperation(target) switch
                {
                    IFieldReferenceOperation field => field.Field,
                    IPropertyReferenceOperation property => property.Property,
                    IEventReferenceOperation declaredEvent => declaredEvent.Event,
                    _ => null,
                };

            if (symbol is not IFieldSymbol and not IPropertySymbol
                and not IEventSymbol)
            {
                return false;
            }

            if (symbol.IsStatic)
            {
                return true;
            }

            ExpressionSyntax? receiver = target switch
            {
                MemberAccessExpressionSyntax access => access.Expression,
                ElementAccessExpressionSyntax element => element.Expression,
                _ => null,
            };

            if (receiver is not null
                && HasLocallyOwnedMutationReceiver(
                    member,
                    receiver,
                    new HashSet<ISymbol>(SymbolEqualityComparer.Default)))
            {
                return false;
            }

            return member.Symbol.MethodKind != MethodKind.Constructor
                || !SymbolEqualityComparer.Default.Equals(
                    symbol.ContainingType,
                    member.Symbol.ContainingType);
        }

        private static bool HasLocallyOwnedMutationReceiver(
            AuthoredMember member,
            ExpressionSyntax expression,
            HashSet<ISymbol> path)
        {
            expression = StripTransparentExpression(expression);

            if (expression is BaseObjectCreationExpressionSyntax
                    or ArrayCreationExpressionSyntax
                    or ImplicitArrayCreationExpressionSyntax
                    or CollectionExpressionSyntax)
            {
                return true;
            }

            ISymbol? symbol = member.Model.GetSymbolInfo(expression).Symbol;

            if (symbol is IParameterSymbol
                && member.ValueBindings?.TryGetValue(
                    symbol,
                    out BoundValueSource? binding) == true
                && binding is not null)
            {
                if (!path.Add(symbol))
                {
                    return false;
                }

                try
                {
                    return HasLocallyOwnedMutationReceiver(
                        binding.Caller,
                        binding.Expression,
                        path);
                }
                finally
                {
                    path.Remove(symbol);
                }
            }

            if (symbol is not ILocalSymbol local || !path.Add(local))
            {
                return false;
            }

            try
            {
                ExpressionSyntax[] sources = local.DeclaringSyntaxReferences
                    .Select(reference => reference.GetSyntax())
                    .OfType<VariableDeclaratorSyntax>()
                    .Select(static variable => variable.Initializer?.Value)
                    .OfType<ExpressionSyntax>()
                    .Concat(member.Syntax.DescendantNodes()
                        .OfType<AssignmentExpressionSyntax>()
                        .Where(assignment => assignment.IsKind(
                                SyntaxKind.SimpleAssignmentExpression)
                            && assignment.SpanStart < expression.SpanStart
                            && SymbolEqualityComparer.Default.Equals(
                                member.Model.GetSymbolInfo(assignment.Left).Symbol,
                                local))
                        .Select(static assignment => assignment.Right))
                    .Where(source => member.Model.GetConstantValue(source) is not
                    {
                        HasValue: true,
                        Value: null,
                    })
                    .ToArray();

                return sources.Length != 0
                    && sources.All(source => HasLocallyOwnedMutationReceiver(
                        member,
                        source,
                        path));
            }
            finally
            {
                path.Remove(local);
            }
        }

        private void CollectLazyConstructions(
            ExpressionSyntax expression,
            SemanticModel model,
            ITypeSymbol lazyType,
            List<BaseObjectCreationExpressionSyntax> constructions,
            HashSet<ISymbol> path)
        {
            expression = expression switch
            {
                ParenthesizedExpressionSyntax parenthesized =>
                    parenthesized.Expression,
                CastExpressionSyntax cast => cast.Expression,
                PostfixUnaryExpressionSyntax suppressed
                    when suppressed.IsKind(
                        SyntaxKind.SuppressNullableWarningExpression) =>
                    suppressed.Operand,
                _ => expression,
            };

            if (expression is BaseObjectCreationExpressionSyntax creation
                && SymbolEqualityComparer.Default.Equals(
                    model.GetTypeInfo(creation).Type,
                    lazyType))
            {
                constructions.Add(creation);

                return;
            }

            if (expression is ConditionalExpressionSyntax conditional)
            {
                CollectLazyConstructions(
                    conditional.WhenTrue,
                    model,
                    lazyType,
                    constructions,
                    path);

                CollectLazyConstructions(
                    conditional.WhenFalse,
                    model,
                    lazyType,
                    constructions,
                    path);

                return;
            }

            ISymbol? symbol = model.GetSymbolInfo(expression).Symbol;

            if (symbol is null || !path.Add(symbol))
            {
                return;
            }

            try
            {
                foreach (SyntaxReference reference in
                    symbol.DeclaringSyntaxReferences)
                {
                    ExpressionSyntax? initializer = reference.GetSyntax() switch
                    {
                        VariableDeclaratorSyntax variable =>
                            variable.Initializer?.Value,
                        PropertyDeclarationSyntax property =>
                            property.Initializer?.Value
                                ?? property.ExpressionBody?.Expression,
                        _ => null,
                    };

                    if (initializer is not null)
                    {
                        CollectLazyConstructions(
                            initializer,
                            semanticModels[initializer.SyntaxTree],
                            lazyType,
                            constructions,
                            path);
                    }
                }
            }
            finally
            {
                path.Remove(symbol);
            }
        }

        private bool HasOwnedLongLivedReturn(
            AuthoredMember member,
            InvocationExpressionSyntax call)
        {
            ISymbol? carrier = call.Parent switch
            {
                AssignmentExpressionSyntax assignment
                    when assignment.Right == call =>
                    member.Model.GetSymbolInfo(assignment.Left).Symbol,
                EqualsValueClauseSyntax
                {
                    Parent: VariableDeclaratorSyntax variable,
                } when variable.Initializer?.Value == call =>
                    member.Model.GetDeclaredSymbol(variable),
                _ => null,
            };

            if (carrier is IFieldSymbol field
                && IsWorkspaceWatcherType(field.Type))
            {
                return LifecycleReachesWatcherDispose(
                    field.ContainingType);
            }

            if (carrier is not ILocalSymbol local
                || !IsWorkspaceWatcherType(local.Type))
            {
                return false;
            }

            TryStatementSyntax? guarded = call.Ancestors()
                .OfType<TryStatementSyntax>()
                .FirstOrDefault(candidate => candidate.Finally is not null);

            bool fallbackDispose = guarded?.Finally?.Block.DescendantNodes()
                .OfType<InvocationExpressionSyntax>()
                .Any(disposal =>
                    member.Model.GetSymbolInfo(disposal).Symbol
                        is IMethodSymbol { Name: "Dispose" }
                    && AdmissionReceiver(member, disposal) is { } receiver
                    && SymbolEqualityComparer.Default.Equals(
                        member.Model.GetSymbolInfo(receiver).Symbol,
                        local)) == true;

            bool transferred = member.Syntax.DescendantNodes()
                .OfType<AssignmentExpressionSyntax>()
                .Any(assignment =>
                    assignment.SpanStart > call.Span.End
                    && SymbolEqualityComparer.Default.Equals(
                        member.Model.GetSymbolInfo(assignment.Right).Symbol,
                        local)
                    && member.Model.GetTypeInfo(assignment.Left).Type is { } type
                    && IsWorkspaceWatcherType(type));

            return fallbackDispose
                && transferred
                && LifecycleReachesWatcherDispose(
                    member.Symbol.ContainingType);
        }

        private bool HasOwnedFileSystemWatcherLifetime(
            AuthoredMember member,
            ExpressionSyntax receiver)
        {
            ISymbol? carrier = member.Model.GetSymbolInfo(receiver).Symbol;

            if (carrier is not IFieldSymbol
                {
                    IsReadOnly: true,
                    Type: { } fieldType,
                } field
                || TypeKey(fieldType) != "System.IO.FileSystemWatcher"
                || !SymbolEqualityComparer.Default.Equals(
                    field.ContainingType,
                    member.Symbol.ContainingType))
            {
                return false;
            }

            AuthoredMember[] owners = AuthoredMembers
                .Where(candidate => SymbolEqualityComparer.Default.Equals(
                    candidate.Symbol.ContainingType,
                    field.ContainingType))
                .ToArray();

            AssignmentExpressionSyntax[] assignments = owners
                .SelectMany(owner => owner.Syntax.DescendantNodesAndSelf()
                    .OfType<AssignmentExpressionSyntax>()
                    .Where(assignment => SymbolEqualityComparer.Default.Equals(
                        owner.Model.GetSymbolInfo(assignment.Left).Symbol,
                        field)))
                .ToArray();

            bool oneConstruction = assignments is [AssignmentExpressionSyntax construction]
                && construction.Right is BaseObjectCreationExpressionSyntax creation
                && member.Model.GetTypeInfo(creation).Type is { } createdType
                && TypeKey(createdType) == "System.IO.FileSystemWatcher";

            bool exactDisposal = owners
                .Where(static owner => owner.Symbol.Name == "Dispose")
                .SelectMany(static owner => owner.Syntax.DescendantNodesAndSelf()
                    .OfType<InvocationExpressionSyntax>()
                    .Select(call => (Owner: owner, Call: call)))
                .Count(candidate =>
                    candidate.Owner.Model.GetSymbolInfo(candidate.Call).Symbol
                        is IMethodSymbol { Name: "Dispose" }
                    && AdmissionReceiver(candidate.Owner, candidate.Call)
                        is { } disposalReceiver
                    && SymbolEqualityComparer.Default.Equals(
                        candidate.Owner.Model.GetSymbolInfo(disposalReceiver).Symbol,
                        field)) == 1;

            return oneConstruction && exactDisposal;
        }

        private static AuthoredMember WithoutInheritedAdmission(
            AuthoredMember member)
        {
            IReadOnlyDictionary<ISymbol, AuthoredMember>? detachedCallables =
                member.CallableBindings?.ToDictionary(
                    static pair => pair.Key,
                    static pair => pair.Value with
                    {
                        AdmissionBindings = null,
                        RecoveryBindings = null,
                        RecoveryContext = null,
                        OrdinaryScopedHolder = null,
                        ReadinessSource = null,
                        ScopedLeaseInstance = null,
                    },
                    SymbolEqualityComparer.Default);

            return member with
            {
                AdmissionBindings = null,
                CallableBindings = detachedCallables,
                RecoveryBindings = null,
                RecoveryContext = null,
                OrdinaryScopedHolder = null,
                ReadinessSource = null,
                ScopedLeaseInstance = null,
            };
        }

        private bool LifecycleReachesWatcherDispose(INamedTypeSymbol ownerType)
        {
            AuthoredMember[] roots = AuthoredMembers
                .Where(member => SymbolEqualityComparer.Default.Equals(
                        member.Symbol.ContainingType,
                        ownerType)
                    && member.Symbol.Name is "StopAsync" or "Dispose" or "DisposeAsync")
                .ToArray();

            HashSet<GraphMemberIdentity> visited = [];

            bool Reaches(AuthoredMember current)
            {
                if (!visited.Add(MemberIdentity(current)))
                {
                    return false;
                }

                foreach (InvocationExpressionSyntax invocation in current.Syntax
                    .DescendantNodesAndSelf(node => node == current.Syntax
                        || node is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .OfType<InvocationExpressionSyntax>())
                {
                    if (current.Model.GetSymbolInfo(invocation).Symbol
                            is not IMethodSymbol method)
                    {
                        continue;
                    }

                    if (method.Name == "Dispose"
                        && AdmissionReceiver(current, invocation)
                            is { } receiver
                        && current.Model.GetTypeInfo(receiver).Type is { } receiverType
                        && IsWorkspaceWatcherType(receiverType))
                    {
                        return true;
                    }

                    if (Resolve(method, current.Model.Compilation) is { } target
                        && SymbolEqualityComparer.Default.Equals(
                            target.Symbol.ContainingType,
                            ownerType)
                        && Reaches(target))
                    {
                        return true;
                    }
                }

                return false;
            }

            return roots.Any(Reaches);
        }

        private static bool IsWorkspaceWatcherType(ITypeSymbol type) =>
            TypeKey(type)
                == "RetroDownfall.Arcanum.Infrastructure.Hosting.IWorkspaceFileWatcher"
            || type is INamedTypeSymbol named
                && named.AllInterfaces.Any(static contract =>
                    TypeKey(contract)
                        == "RetroDownfall.Arcanum.Infrastructure.Hosting.IWorkspaceFileWatcher");

        private static bool IsKnownLazyCallback(IMethodSymbol method)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            string type = TypeKey(definition.ContainingType);

            return type == "System.Linq.Enumerable"
                    && definition.Name is "Append" or "Cast" or "Chunk" or "Concat" or "DefaultIfEmpty" or "Distinct" or "DistinctBy" or "Except" or "ExceptBy" or "GroupBy" or "GroupJoin" or "Intersect" or "IntersectBy" or "Join" or "OfType" or "Order" or "OrderBy" or "OrderByDescending" or "Prepend" or "Reverse" or "Select" or "SelectMany" or "Skip" or "SkipLast" or "SkipWhile" or "Take" or "TakeLast" or "TakeWhile" or "ThenBy" or "ThenByDescending" or "Union" or "UnionBy" or "Where" or "Zip"
                || type == "System.Linq.ImmutableArrayExtensions"
                    && definition.Name is "Select" or "Where";
        }

        private static bool IsLazySequence(ITypeSymbol type) => TypeKey(type) is "System.Collections.IEnumerable" or "System.Collections.Generic.IEnumerable`1" or "System.Collections.Generic.IAsyncEnumerable`1";

        private static bool IsIteratorMember(AuthoredMember member) => member.Syntax.DescendantNodesAndSelf(node => node == member.Syntax || node is not AnonymousFunctionExpressionSyntax and not LocalFunctionStatementSyntax).Any(static node => node is YieldStatementSyntax);

        private static bool IsLazyDirectoryEnumeration(string callee) => callee is "System.IO.Directory.EnumerateDirectories" or "System.IO.Directory.EnumerateFileSystemEntries" or "System.IO.Directory.EnumerateFiles";

        private static bool IsEagerEnumerationTerminal(IMethodSymbol method)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            if (TypeKey(definition.ContainingType) == "System.Collections.Generic.List`1"
                && definition.Name == "AddRange")
            {
                return true;
            }

            return TypeKey(definition.ContainingType) == "System.Linq.Enumerable"
                && definition.Name is "Aggregate" or "All" or "Any" or "Average" or "Contains" or "Count" or "ElementAt" or "ElementAtOrDefault" or "First" or "FirstOrDefault" or "Last" or "LastOrDefault" or "LongCount" or "Max" or "MaxBy" or "Min" or "MinBy" or "SequenceEqual" or "Single" or "SingleOrDefault" or "Sum" or "ToArray" or "ToDictionary" or "ToHashSet" or "ToList" or "ToLookup";
        }

        // A lazy sequence's body runs on every MoveNext of its consumer, wherever the consumer resumes it, so the Work
        // and effect group it ran under must be live at every one of those points. A consuming loop resumes it
        // after its operand, after each pass of its body (the back-edge) and when it ends; any other consumer
        // consumes it in one step.
        private static int?[] LazyConsumptionPositions(SyntaxNode completion)
        {
            if (completion is not CommonForEachStatementSyntax loop)
            {
                return [null];
            }

            int entry = loop.Expression.Span.End + 1;

            int backEdge = Math.Max(entry, loop.Statement.Span.End);

            int exit = Math.Max(backEdge, loop.Span.End);

            return [entry, backEdge, exit];
        }

        // The frontier several positions share, or null when any two differ.
        private static string? CommonFrontier(IEnumerable<string?> frontiers)
        {
            string?[] all = [.. frontiers];

            return all.Length != 0 && all.All(frontier => frontier == all[0]) ? all[0] : null;
        }

        private SyntaxNode? LazyCompletionPoint(AuthoredMember member, InvocationExpressionSyntax source)
        {
            SyntaxNode? Consumption(SyntaxNode expression)
            {
                foreach (SyntaxNode ancestor in expression.AncestorsAndSelf())
                {
                    if (ancestor != expression && ancestor is (AnonymousFunctionExpressionSyntax or LocalFunctionStatementSyntax))
                    {
                        return null;
                    }

                    if (ancestor is ForEachStatementSyntax loop && loop.Expression.Span.Contains(expression.Span)
                        || ancestor is ForEachVariableStatementSyntax variableLoop && variableLoop.Expression.Span.Contains(expression.Span))
                    {
                        return ancestor;
                    }

                    if (ancestor is InvocationExpressionSyntax terminal && terminal != source && member.Model.GetSymbolInfo(terminal).Symbol is IMethodSymbol method && IsEagerEnumerationTerminal(method))
                    {
                        return terminal;
                    }

                    if (ancestor is CollectionExpressionSyntax collection && collection.Elements.OfType<SpreadElementSyntax>().Any(spread => spread.Expression.Span.Contains(expression.Span)))
                    {
                        return collection;
                    }

                    if (ancestor == member.Syntax)
                    {
                        break;
                    }
                }

                return null;
            }

            if (Consumption(source) is { } direct)
            {
                return direct;
            }

            if (source.Ancestors().OfType<ArgumentSyntax>().FirstOrDefault() is { } argument
                && argument.Parent is ArgumentListSyntax { Parent: InvocationExpressionSyntax consumerCall }
                && member.Model.GetOperation(argument) is IArgumentOperation
                {
                    Parameter: { } suppliedParameter,
                }
                && member.Model.GetSymbolInfo(consumerCall).Symbol is IMethodSymbol consumerMethod
                && ResolveInvocationTarget(consumerMethod, member, consumerCall) is { } consumer
                && suppliedParameter.Ordinal < consumer.Symbol.Parameters.Length
                && ConsumesLazyParameterSynchronously(
                    consumer,
                    consumer.Symbol.Parameters[suppliedParameter.Ordinal])
                && !ConsumerMayHoldTheAdmission(member, consumerCall, argument))
            {
                return consumerCall;
            }

            VariableDeclaratorSyntax? declaration = source.Ancestors().OfType<VariableDeclaratorSyntax>().FirstOrDefault(variable => variable.Initializer?.Value.Span.Contains(source.Span) == true);

            if (declaration is null || member.Model.GetDeclaredSymbol(declaration) is not ILocalSymbol local || declaration.Ancestors().OfType<BlockSyntax>().FirstOrDefault() is not { } block)
            {
                return null;
            }

            IdentifierNameSyntax[] uses = block.DescendantNodes().OfType<IdentifierNameSyntax>().Where(identifier => identifier.SpanStart > declaration.Span.End && SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(identifier).Symbol, local)).ToArray();

            if (declaration.Initializer?.Value is InvocationExpressionSyntax enumeratorFactory
                && enumeratorFactory.Span.Contains(source.Span)
                && member.Model.GetSymbolInfo(enumeratorFactory).Symbol is IMethodSymbol { Name: "GetEnumerator", Parameters.Length: 0, ReturnType: { } enumeratorType }
                && TypeKey(enumeratorType) is "System.Collections.IEnumerator" or "System.Collections.Generic.IEnumerator`1"
                && declaration.Parent?.Parent is LocalDeclarationStatementSyntax { UsingKeyword.RawKind: not 0 } usingDeclaration
                && uses is [IdentifierNameSyntax enumeratorUse]
                && enumeratorUse.Parent is MemberAccessExpressionSyntax { Name.Identifier.ValueText: "MoveNext" } moveNextAccess
                && moveNextAccess.Parent is InvocationExpressionSyntax moveNext
                && member.Model.GetSymbolInfo(moveNext).Symbol is IMethodSymbol { Name: "MoveNext", Parameters.Length: 0, ReturnType.SpecialType: SpecialType.System_Boolean }
                && IsImmediateFollowingStatement(usingDeclaration, moveNext))
            {
                return moveNext;
            }

            return uses is [IdentifierNameSyntax use] ? Consumption(use) : null;
        }

        // The sequence runs in the consumer's loop, wherever that loop and its body put the lease. A consumer that is
        // handed anything that carries the admission (another argument, or the receiver it is called on) can end it
        // between two MoveNext calls, so the Work live at the call says nothing about the body.
        private bool ConsumerMayHoldTheAdmission(AuthoredMember member, InvocationExpressionSyntax consumerCall, ArgumentSyntax lazyArgument) =>
            consumerCall.ArgumentList.Arguments.Any(other => other != lazyArgument && MayCarryAdmissionHandle(member, other.Expression))
            || consumerCall.Expression is MemberAccessExpressionSyntax { Expression: { } receiver } && MayCarryAdmissionHandle(member, receiver);

        private static bool ConsumesLazyParameterSynchronously(
            AuthoredMember consumer,
            IParameterSymbol parameter)
        {
            if (IsAwaitable(consumer.Symbol.ReturnType)
                || IsLazySequence(consumer.Symbol.ReturnType)
                || IsIteratorMember(consumer))
            {
                return false;
            }

            IdentifierNameSyntax[] references = consumer.Syntax.DescendantNodesAndSelf()
                .OfType<IdentifierNameSyntax>()
                .Where(reference => SymbolEqualityComparer.Default.Equals(
                    consumer.Model.GetSymbolInfo(reference).Symbol,
                    parameter))
                .ToArray();

            bool consumed = false;

            foreach (IdentifierNameSyntax reference in references)
            {
                if (reference.Ancestors()
                    .TakeWhile(ancestor => ancestor != consumer.Syntax)
                    .Any(static ancestor => ancestor is AnonymousFunctionExpressionSyntax or LocalFunctionStatementSyntax))
                {
                    return false;
                }

                if (reference.Ancestors().OfType<ForEachStatementSyntax>()
                    .Any(loop => loop.Expression.Span.Contains(reference.Span))
                    || reference.Ancestors().OfType<ForEachVariableStatementSyntax>()
                        .Any(loop => loop.Expression.Span.Contains(reference.Span)))
                {
                    consumed = true;

                    continue;
                }

                InvocationExpressionSyntax? call = reference.Ancestors()
                    .OfType<InvocationExpressionSyntax>()
                    .FirstOrDefault();

                if (call is not null
                    && consumer.Model.GetOperation(call) is INameOfOperation)
                {
                    continue;
                }

                if (call is not null
                    && consumer.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method
                    && Normalize(method) == "System.ArgumentNullException.ThrowIfNull")
                {
                    continue;
                }

                if (call is not null
                    && consumer.Model.GetSymbolInfo(call).Symbol is IMethodSymbol terminal
                    && IsEagerEnumerationTerminal(terminal))
                {
                    consumed = true;

                    continue;
                }

                return false;
            }

            return consumed;
        }

        private static bool IsImmediateFollowingStatement(LocalDeclarationStatementSyntax declaration, InvocationExpressionSyntax invocation)
        {
            if (declaration.Parent is not BlockSyntax block || invocation.Ancestors().OfType<StatementSyntax>().FirstOrDefault() is not ExpressionStatementSyntax statement || statement.Parent != block)
            {
                return false;
            }

            int declarationIndex = block.Statements.IndexOf(declaration);

            return declarationIndex >= 0 && declarationIndex + 1 < block.Statements.Count && block.Statements[declarationIndex + 1] == statement;
        }

        private static ExpressionSyntax DelegateReceiver(AuthoredMember member, InvocationExpressionSyntax call)
        {
            if (member.Model.GetOperation(call) is IInvocationOperation { Instance.Syntax: ExpressionSyntax receiver } && receiver != call)
            {
                return receiver;
            }

            if (call.Expression is MemberAccessExpressionSyntax access)
            {
                return access.Expression;
            }

            return call.Ancestors().OfType<ConditionalAccessExpressionSyntax>().FirstOrDefault(conditional => conditional.WhenNotNull.Span.Contains(call.Span))?.Expression ?? call.Expression;
        }

        private bool IsEffectFreeExternalCallable(
            ExpressionSyntax expression,
            AuthoredMember member)
        {
            ClosedCallableValue value = ResolveContextualCallable(
                expression,
                member.Model,
                member.CallableBindings,
                member.AbsentCallables,
                new HashSet<ISymbol>(SymbolEqualityComparer.Default));

            return value.IsKnown
                && CallableTargets(value).Length == 0
                && value.EffectFreeExternal;
        }

        private bool IsEffectFreeExternalCallable(
            IMethodSymbol method,
            Compilation compilation) => Resolve(method, compilation) is null
                && !Vocabulary.ContainsKey(Normalize(method))
                && (IsExactSingleFinitePredicate(method)
                    || IsReviewedEffectFreeExternalMember(method));

        private static bool IsExactSingleFinitePredicate(IMethodSymbol method) =>
            method.MethodKind == MethodKind.Ordinary
            && method.IsStatic
            && method.Name == "IsFinite"
            && method.Arity == 0
            && !method.ReturnsByRef
            && !method.ReturnsByRefReadonly
            && method.ReturnType.SpecialType == SpecialType.System_Boolean
            && method.Parameters is [{ RefKind: RefKind.None, Type.SpecialType: SpecialType.System_Single }]
            && method.ContainingType.SpecialType == SpecialType.System_Single
            && method.DeclaringSyntaxReferences.Length == 0
            && !method.Locations.Any(static location => location.IsInSource)
            && IsExactFrameworkType(method.ContainingType, "System.Single", typeof(float).Assembly.GetName());

        private static bool IsExactSinglePredicateDelegateInvoke(IMethodSymbol method) =>
            method.MethodKind == MethodKind.DelegateInvoke
            && !method.IsStatic
            && method.Arity == 0
            && method.ReturnType.SpecialType == SpecialType.System_Boolean
            && method.Parameters is [{ RefKind: RefKind.None, Type.SpecialType: SpecialType.System_Single }]
            && method.ContainingType.TypeArguments is
                [{ SpecialType: SpecialType.System_Single }, { SpecialType: SpecialType.System_Boolean }]
            && IsExactFrameworkType(method.ContainingType, "System.Func`2", typeof(Func<,>).Assembly.GetName());

        private bool RequiresExternalBoundaryClassification(
            IMethodSymbol method,
            Compilation compilation,
            SyntaxNode? node = null,
            SemanticModel? model = null,
            AuthoredMember? context = null)
        {
            string callee = Normalize(method);

            if (HasRejectedCampaignEncodingArgument(method, node, model, context))
            {
                return true;
            }

            if (Vocabulary.ContainsKey(callee)
                || PureSensitiveMethods.Contains(callee)
                || ReviewedInProcessSynchronizationMembers.Contains(callee)
                || ReviewedProcessRuntimeInitializationMembers.Contains(callee)
                || IsReviewedEnumeratorMethod(method, node, model, context)
                || IsExactOwnedWatcherCleanup(method, node, context)
                || IsReviewedInMemoryStreamReaderMember(
                    method,
                    node,
                    model,
                    context)
                || IsReviewedLongRestHistogramObservation(method, node, model, context)
                || IsReviewedArcanumTokenHistogramObservation(method, node, model, context)
                || IsReviewedCodeOwnedSdkConstruction(method, node, model, context)
                || IsReviewedConcreteTokenizerCall(method, node, model, context)
                || IsReviewedCampaignEncodingMethod(method, node, model, context)
                || IsReviewedCampaignAclMethod(method, node, model, context)
                || IsReviewedAbsentHttpClientCleanup(method, node, model, context)
                || IsReviewedEffectFreeExternalMember(
                    method,
                    node,
                    model,
                    context))
            {
                return false;
            }

            if (SensitiveBoundaryTypes.Contains(TypeKey(method.ContainingType)))
            {
                return Resolve(method, compilation) is null;
            }

            if (method.MethodKind == MethodKind.Ordinary
                && method.IsExtern
                && !method.IsAbstract
                && method.ContainingType.TypeKind != TypeKind.Interface
                && method.PartialDefinitionPart is null
                && method.PartialImplementationPart is null
                && method.DeclaringSyntaxReferences.Any(static reference =>
                    reference.GetSyntax() is MethodDeclarationSyntax { Body: null, ExpressionBody: null } declaration
                    && declaration.Modifiers.Any(SyntaxKind.ExternKeyword)
                    && !declaration.Modifiers.Any(SyntaxKind.PartialKeyword)))
            {
                return true;
            }

            return Resolve(method, compilation) is null
                && method.Locations.All(static location => !location.IsInSource)
                && !method.ContainingNamespace.ToDisplayString()
                    .StartsWith("RetroDownfall.", StringComparison.Ordinal);
        }

        private static bool IsExactLongRestHistogramRecord(IMethodSymbol method) =>
            !method.IsStatic && method.Name == "Record" && method.Arity == 0 && method.ReturnsVoid
            && HasExactParameterTypes(method, "System.Int32")
            && method.ContainingType.TypeArguments is [{ SpecialType: SpecialType.System_Int32 }]
            && IsExactFrameworkType(method.ContainingType, "System.Diagnostics.Metrics.Histogram`1", typeof(System.Diagnostics.Metrics.Histogram<>).Assembly.GetName());

        private bool IsReviewedLongRestHistogramObservation(IMethodSymbol method, SyntaxNode? node, SemanticModel? model, AuthoredMember? context)
        {
            if (!IsExactLongRestHistogramRecord(method)
                || node is not InvocationExpressionSyntax call || model?.GetOperation(call) is not IInvocationOperation { Instance.Syntax: ExpressionSyntax receiver } invocation
                || context is null || !invocation.Arguments.All(argument => HasReviewedValueConversions(argument.Value, context, hierarchyObservation: true))) return false;

            CleanupProvenanceContext proof = new();

            bool ExactMeter(IFieldSymbol meter)
            {
                if (!meter.IsReadOnly || !meter.IsStatic || meter.Name != "Meter"
                    || TypeKey(meter.ContainingType) != "RetroDownfall.Arcanum.Core.Telemetry.ArcanumMetrics"
                    || !IsExactFrameworkType(meter.Type, "System.Diagnostics.Metrics.Meter", typeof(System.Diagnostics.Metrics.Meter).Assembly.GetName())
                    || HasAuthoredStorageWrite(meter)
                    || meter.DeclaringSyntaxReferences is not [SyntaxReference declaration]
                    || declaration.GetSyntax() is not VariableDeclaratorSyntax { Initializer.Value: { } value }
                    || !semanticModels.TryGetValue(value.SyntaxTree, out SemanticModel? meterModel)
                    || meterModel.GetOperation(value) is not IObjectCreationOperation { Constructor: { } constructor, Initializer: null } creation) return false;

                return IsExactFrameworkType(constructor.ContainingType, "System.Diagnostics.Metrics.Meter", typeof(System.Diagnostics.Metrics.Meter).Assembly.GetName())
                    && HasExactParameterTypes(constructor, "System.String", "System.String")
                    && creation.Arguments is [{ Value.ConstantValue: { HasValue: true, Value: "Arcanum" } },
                        { Value.ConstantValue: { HasValue: true, Value: "0.1.0" } }];
            }

            bool ExactInstrument(IFieldSymbol field)
            {
                if (!field.IsReadOnly || !field.IsStatic || HasAuthoredStorageWrite(field)
                    || field.Type is not INamedTypeSymbol { TypeArguments: [{ SpecialType: SpecialType.System_Int32 }] }
                    || !IsExactFrameworkType(field.Type, "System.Diagnostics.Metrics.Histogram`1", typeof(System.Diagnostics.Metrics.Histogram<>).Assembly.GetName())
                    || field.DeclaringSyntaxReferences is not [SyntaxReference declaration]
                    || declaration.GetSyntax() is not VariableDeclaratorSyntax { Initializer.Value: { } initializer }
                    || !semanticModels.TryGetValue(initializer.SyntaxTree, out SemanticModel? fieldModel)
                    || fieldModel.GetOperation(initializer) is not IInvocationOperation { Instance: IFieldReferenceOperation meter } created) return false;

                IMethodSymbol factory = created.TargetMethod;

                return !factory.IsStatic && factory.Name == "CreateHistogram" && factory.Arity == 1
                    && factory.TypeArguments is [{ SpecialType: SpecialType.System_Int32 }]
                    && IsExactFrameworkType(factory.ContainingType, "System.Diagnostics.Metrics.Meter", typeof(System.Diagnostics.Metrics.Meter).Assembly.GetName())
                    && HasExactParameterTypes(factory, "System.String")
                    && SymbolEqualityComparer.Default.Equals(factory.ReturnType, field.Type)
                    && created.Arguments is [{ Value.ConstantValue: { HasValue: true, Value: string name } }]
                    && name is "arcanum.long_rest.discovery.selected_summaries" or "arcanum.long_rest.discovery.frontier" or "arcanum.long_rest.discovery.expanded_leaves"
                    && ExactMeter(meter.Field);
            }

            bool Origin(ExpressionSyntax value, SemanticModel valueModel, HashSet<ISymbol> path, AuthoredMember? owner)
            {
                if (owner is null || proof.RemainingWork-- <= 0) return false;

                value = StripTransparentExpression(value);

                ISymbol? symbol = valueModel.GetSymbolInfo(value).Symbol;

                if (symbol is IFieldSymbol field) return ExactInstrument(field);

                if (symbol is ILocalSymbol or IParameterSymbol && HasCollectionValueReplacement(owner, symbol)) return false;

                if (value is InvocationExpressionSyntax invocation && symbol is IMethodSymbol invoked
                    && ResolveCleanupInvocationTarget(invoked, owner, invocation, proof) is { } target && path.Add(invoked))
                {
                    try
                    {
                        AuthoredMember bound = BindCleanupInvocationContext(owner, invocation, target, proof);

                        ExpressionSyntax[] returns = ReturnedExpressions(bound.Syntax);

                        return returns.Length != 0 && returns.All(returned => Origin(returned, bound.Model, path, bound));
                    }
                    finally
                    {
                        path.Remove(invoked);
                    }
                }

                if (symbol is IPropertySymbol { SetMethod: null, GetMethod: { } getter } && Resolve(getter, valueModel.Compilation) is { } property && path.Add(getter))
                {
                    try
                    {
                        ExpressionSyntax[] returns = ReturnedExpressions(property.Syntax);

                        return returns.Length != 0 && returns.All(returned => Origin(returned, property.Model, path, property));
                    }
                    finally
                    {
                        path.Remove(getter);
                    }
                }

                return HasOnlyReviewedValueSources(value, valueModel, path, owner, Origin);
            }

            // This is tagless observation under DESIGN 10.4, not listener purity. Record can
            // synchronously execute and propagate faults from runtime observers. Authored
            // arguments/getters/wrappers and listener work remain traversed or refused; ambient/static initialization,
            // reflection/loader/native behavior and third-party observer closure remain unproved.
            return Origin(receiver, context.Model, new(SymbolEqualityComparer.Default), context);
        }

        // Exact reviewed contract (Triage Ladder D4) for the three Arcanum token-count instruments. Each is a
        // static readonly Histogram<long> of ArcanumMetrics, created from the exact ArcanumMetrics.Meter by
        // the exact CreateHistogram<long>(string, string?, string?) overload with constant arguments, under
        // one of these constant names. The recorded value is evaluated, and any authored work in it is
        // traversed, where it is written; it needs only the argument-boundary rule. Each tag is narrower
        // (IsReviewedArcanumTokenTag), because the first-party Prometheus listener runs synchronously inside
        // Record and formats every tag value with Convert.ToString: an authored ToString or IFormattable on
        // a tag value would be executable work that no traversal of this call site reaches. Other listeners
        // run synchronously and may do work or throw, as for every histogram here, and nothing in this
        // contract waives that limit or any producer authority.
        private static readonly HashSet<string> ArcanumTokenHistogramNames = new(StringComparer.Ordinal)
        {
            "arcanum_estimated_input_tokens",
            "arcanum_provider_reported_input_tokens",
            "arcanum_input_token_estimation_variance",
        };

        private static bool IsExactArcanumTokenHistogramRecord(IMethodSymbol method) =>
            !method.IsStatic && method.Name == "Record" && method.Arity == 0 && method.ReturnsVoid
            && method.ContainingType.TypeArguments is [{ SpecialType: SpecialType.System_Int64 }]
            && IsExactFrameworkType(method.ContainingType, "System.Diagnostics.Metrics.Histogram`1", typeof(System.Diagnostics.Metrics.Histogram<>).Assembly.GetName())
            && method.Parameters.Length is >= 1 and <= 4
            && method.Parameters[0] is { RefKind: RefKind.None, Type.SpecialType: SpecialType.System_Int64 }
            && method.Parameters.Skip(1).All(static tag => tag is { RefKind: RefKind.None, IsParams: false }
                && tag.Type is INamedTypeSymbol { TypeArguments: [{ SpecialType: SpecialType.System_String }, { SpecialType: SpecialType.System_Object }] } pair
                && IsExactFrameworkType(pair, "System.Collections.Generic.KeyValuePair`2", typeof(KeyValuePair<,>).Assembly.GetName()));

        private bool IsReviewedArcanumTokenHistogramObservation(IMethodSymbol method, SyntaxNode? node, SemanticModel? model, AuthoredMember? context)
        {
            if (!IsExactArcanumTokenHistogramRecord(method)
                || context is null || node is not InvocationExpressionSyntax
                || model?.GetOperation(node) is not IInvocationOperation { Instance.Syntax: ExpressionSyntax receiver } invocation
                || !invocation.Arguments.All(ArgumentBoundaryUsesOnlyBuiltInConversions)
                || !invocation.Arguments.Where(static argument => argument.Parameter?.Ordinal != 0)
                    .All(argument => IsReviewedArcanumTokenTag(argument, context))
                || model.GetSymbolInfo(StripTransparentExpression(receiver)).Symbol is not IFieldSymbol field) return false;

            bool ExactMeter(IFieldSymbol meter)
            {
                if (!meter.IsReadOnly || !meter.IsStatic || meter.Name != "Meter"
                    || TypeKey(meter.ContainingType) != "RetroDownfall.Arcanum.Core.Telemetry.ArcanumMetrics"
                    || !IsExactFrameworkType(meter.Type, "System.Diagnostics.Metrics.Meter", typeof(System.Diagnostics.Metrics.Meter).Assembly.GetName())
                    || HasAuthoredStorageWrite(meter)
                    || meter.DeclaringSyntaxReferences is not [SyntaxReference declaration]
                    || declaration.GetSyntax() is not VariableDeclaratorSyntax { Initializer.Value: { } value }
                    || !semanticModels.TryGetValue(value.SyntaxTree, out SemanticModel? meterModel)
                    || meterModel.GetOperation(value) is not IObjectCreationOperation { Constructor: { } constructor, Initializer: null } creation) return false;

                return IsExactFrameworkType(constructor.ContainingType, "System.Diagnostics.Metrics.Meter", typeof(System.Diagnostics.Metrics.Meter).Assembly.GetName())
                    && HasExactParameterTypes(constructor, "System.String", "System.String")
                    && creation.Arguments is [{ Value.ConstantValue: { HasValue: true, Value: "Arcanum" } },
                        { Value.ConstantValue: { HasValue: true, Value: "0.1.0" } }];
            }

            if (!field.IsReadOnly || !field.IsStatic || HasAuthoredStorageWrite(field)
                || TypeKey(field.ContainingType) != "RetroDownfall.Arcanum.Core.Telemetry.ArcanumMetrics"
                || field.Type is not INamedTypeSymbol { TypeArguments: [{ SpecialType: SpecialType.System_Int64 }] }
                || !IsExactFrameworkType(field.Type, "System.Diagnostics.Metrics.Histogram`1", typeof(System.Diagnostics.Metrics.Histogram<>).Assembly.GetName())
                || field.DeclaringSyntaxReferences is not [SyntaxReference declaration]
                || declaration.GetSyntax() is not VariableDeclaratorSyntax { Initializer.Value: { } initializer }
                || !semanticModels.TryGetValue(initializer.SyntaxTree, out SemanticModel? fieldModel)
                || fieldModel.GetOperation(initializer) is not IInvocationOperation { Instance: IFieldReferenceOperation meterReference } created) return false;

            IMethodSymbol factory = created.TargetMethod;

            // Only the (name, unit, description) overload is reviewed: the instrument-tags and advice overloads
            // carry authored data into the instrument, and a constant argument keeps static initialization free
            // of work that no traversal reaches.
            return !factory.IsStatic && factory.Name == "CreateHistogram" && factory.Arity == 1
                && factory.TypeArguments is [{ SpecialType: SpecialType.System_Int64 }]
                && IsExactFrameworkType(factory.ContainingType, "System.Diagnostics.Metrics.Meter", typeof(System.Diagnostics.Metrics.Meter).Assembly.GetName())
                && HasExactParameterTypes(factory, "System.String", "System.String", "System.String")
                && factory.ReturnType is INamedTypeSymbol { TypeArguments: [{ SpecialType: SpecialType.System_Int64 }] } returned
                && IsExactFrameworkType(returned, "System.Diagnostics.Metrics.Histogram`1", typeof(System.Diagnostics.Metrics.Histogram<>).Assembly.GetName())
                && created.Arguments is [
                    { ArgumentKind: ArgumentKind.Explicit, Value.ConstantValue: { HasValue: true, Value: string name } },
                    { ArgumentKind: ArgumentKind.Explicit, Value.ConstantValue: { HasValue: true, Value: null or string } },
                    { ArgumentKind: ArgumentKind.Explicit, Value.ConstantValue: { HasValue: true, Value: null or string } }]
                && ArcanumTokenHistogramNames.Contains(name)
                && ExactMeter(meterReference.Field);
        }

        // A tag is either an inline KeyValuePair<string, object?> creation or a never-reassigned local whose
        // only definition is one. The key is a constant and the value is statically System.String (or a null
        // or string constant), so the object the listener formats is a string or null and never a type with an
        // authored ToString or IFormattable. Authored work that produces the string is traversed where written.
        private bool IsReviewedArcanumTokenTag(IArgumentOperation argument, AuthoredMember context)
        {
            IOperation tag = argument.Value;

            while (tag is IParenthesizedOperation parenthesized) tag = parenthesized.Operand;

            if (tag is ILocalReferenceOperation { Local: { RefKind: RefKind.None, IsConst: false } local })
            {
                if (local.DeclaringSyntaxReferences is not [SyntaxReference declaration]
                    || declaration.GetSyntax() is not VariableDeclaratorSyntax { Initializer.Value: { } initializer }
                    || initializer.SyntaxTree != context.Model.SyntaxTree
                    || !IsExactTokenTagType(local.Type)
                    || HasCollectionValueReplacement(context, local)
                    || context.Model.SyntaxTree.GetRoot().DescendantNodes().OfType<PrefixUnaryExpressionSyntax>()
                        .Any(address => address.IsKind(SyntaxKind.AddressOfExpression)
                            && SyntaxReferencesSymbol(context.Model, address.Operand, local))
                    || context.Model.GetOperation(initializer) is not { } initial) return false;

                tag = initial;

                while (tag is IParenthesizedOperation parenthesizedInitial) tag = parenthesizedInitial.Operand;
            }

            return tag is IObjectCreationOperation { Initializer: null, Constructor: { MethodKind: MethodKind.Constructor } constructor } creation
                && IsExactTokenTagType(constructor.ContainingType)
                && constructor.Parameters.Length == 2
                && creation.Arguments.SingleOrDefault(static item => item.Parameter?.Ordinal == 0) is { } key
                && creation.Arguments.SingleOrDefault(static item => item.Parameter?.Ordinal == 1) is { } value
                && creation.Arguments.Length == 2
                && ArgumentBoundaryUsesOnlyBuiltInConversions(key)
                && key.Value.ConstantValue is { HasValue: true, Value: string }
                && ArgumentBoundaryUsesOnlyBuiltInConversions(value)
                && IsStringOrNullTagValue(value.Value);
        }

        private static bool IsExactTokenTagType(ITypeSymbol? type) =>
            type is INamedTypeSymbol { TypeArguments: [{ SpecialType: SpecialType.System_String }, { SpecialType: SpecialType.System_Object }] } pair
            && IsExactFrameworkType(pair, "System.Collections.Generic.KeyValuePair`2", typeof(KeyValuePair<,>).Assembly.GetName());

        // Looks through parentheses and the reference or boxing conversions to object; what remains must be
        // statically System.String, or a constant that is null or a string. A boxed value, an object-typed
        // value and a value of any other class or struct type are refused.
        private static bool IsStringOrNullTagValue(IOperation value)
        {
            for (int depth = 0; depth < 64; depth++)
            {
                switch (value)
                {
                    case IParenthesizedOperation parenthesized:
                        value = parenthesized.Operand;

                        continue;

                    case IConversionOperation { OperatorMethod: null, Conversion.IsUserDefined: false, Type.SpecialType: SpecialType.System_Object } conversion:
                        value = conversion.Operand;

                        continue;
                }

                return value.ConstantValue.HasValue
                    ? value.ConstantValue.Value is null or string
                    : value.Type?.SpecialType == SpecialType.System_String;
            }

            return false;
        }

        private bool IsReviewedCodeOwnedSdkConstruction(
            IMethodSymbol method,
            SyntaxNode? node,
            SemanticModel? model,
            AuthoredMember? context)
        {
            bool chat = IsExactFrameworkType(method.ContainingType, "OpenAI.Chat.ChatClient", typeof(OpenAI.Chat.ChatClient).Assembly.GetName());

            bool embedding = IsExactFrameworkType(method.ContainingType, "OpenAI.Embeddings.EmbeddingClient", typeof(OpenAI.Embeddings.EmbeddingClient).Assembly.GetName());

            if (method.MethodKind != MethodKind.Constructor
                || !chat && !embedding
                || !HasExactParameterTypes(method, "System.String", "System.ClientModel.ApiKeyCredential", "OpenAI.OpenAIClientOptions")
                || node is null
                || model?.GetOperation(node) is not IObjectCreationOperation creation
                || creation.Arguments.SingleOrDefault(static argument => argument.Parameter?.Name == "options")
                    ?.Value.Syntax is not ExpressionSyntax options)
            {
                return false;
            }

            return chat && HasExactCodeOwnedChatOptions(options, model, context)
                || context is not null && HasExactLongRestSdkOptions(options, context);
        }

        private static bool IsExactLongRestHttpFactoryMethod(IMethodSymbol method) =>
            !method.IsStatic && method.Arity == 0 && method.Name == "CreateClient"
            && IsExactFrameworkType(method.ContainingType, "System.Net.Http.IHttpClientFactory", typeof(System.Net.Http.IHttpClientFactory).Assembly.GetName())
            && HasExactParameterTypes(method, "System.String")
            && IsExactFrameworkType(method.ReturnType, "System.Net.Http.HttpClient", typeof(System.Net.Http.HttpClient).Assembly.GetName());

        private static bool IsLongRestSdkFactoryReceiverProperty(SyntaxNode node, AuthoredMember member) =>
            node.Parent is MemberAccessExpressionSyntax access
            && access.Expression == node && access.Parent is InvocationExpressionSyntax call
            && member.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method
            && IsExactLongRestHttpFactoryMethod(method)
            && IsLongRestSdkSetupDependency(member)
            && member.Model.GetSymbolInfo(node).Symbol is IPropertySymbol property
            && IsExactFrameworkType(property.Type, "System.Net.Http.IHttpClientFactory", typeof(System.Net.Http.IHttpClientFactory).Assembly.GetName());

        private static bool IsLongRestSdkSetupDependency(AuthoredMember member) =>
            member.Syntax.DescendantNodesAndSelf().OfType<BaseObjectCreationExpressionSyntax>()
                .Any(creation => member.Model.GetSymbolInfo(creation).Symbol is IMethodSymbol constructor
                    && (IsExactFrameworkType(constructor.ContainingType, "OpenAI.OpenAIClientOptions", typeof(OpenAI.OpenAIClientOptions).Assembly.GetName())
                            && constructor.Parameters.IsEmpty
                        || (IsExactFrameworkType(constructor.ContainingType, "OpenAI.Chat.ChatClient", typeof(OpenAI.Chat.ChatClient).Assembly.GetName())
                                || IsExactFrameworkType(constructor.ContainingType, "OpenAI.Embeddings.EmbeddingClient", typeof(OpenAI.Embeddings.EmbeddingClient).Assembly.GetName()))
                            && HasExactParameterTypes(constructor, "System.String", "System.ClientModel.ApiKeyCredential", "OpenAI.OpenAIClientOptions")));

        private BoundValueSource[]? LongRestSdkValueSources(
            AuthoredMember member,
            ExpressionSyntax expression,
            CleanupProvenanceContext proof)
        {
            List<BoundValueSource> origins = [];

            static bool ConstantOrDefault(IArgumentOperation argument)
            {
                if (argument.InConversion.MethodSymbol is not null || argument.OutConversion.MethodSymbol is not null) return false;

                IOperation value = argument.Value;

                while (value is IConversionOperation { OperatorMethod: null } conversion) value = conversion.Operand;

                return value.ConstantValue.HasValue || value is IDefaultValueOperation;
            }

            bool StableOrigin(ExpressionSyntax value, SemanticModel model, HashSet<ISymbol> path, AuthoredMember? owner)
            {
                if (owner is null || proof.RemainingWork-- <= 0) return false;

                IOperation? operation = model.GetOperation(value);

                // Returned syntax and bound argument syntax omit implicit conversions. Keep
                // the compiler context at each followed source; no authored or unknown external
                // conversion body is proved by the exact construction found further downstream.
                while (operation?.Parent is IConversionOperation or IParenthesizedOperation) operation = operation.Parent;

                if (operation is null) return false;

                Stack<IOperation> pending = new();

                pending.Push(operation);

                while (pending.TryPop(out IOperation? current))
                {
                    if (proof.RemainingWork-- <= 0 || current is IConversionOperation { OperatorMethod: not null }) return false;

                    foreach (IOperation child in current.ChildOperations) pending.Push(child);
                }

                value = StripTransparentExpression(value);

                ISymbol? symbol = model.GetSymbolInfo(value).Symbol;

                if (symbol is ILocalSymbol or IParameterSymbol && HasCollectionValueReplacement(owner, symbol)) return false;

                if (symbol is IParameterSymbol { ContainingSymbol: IMethodSymbol { MethodKind: MethodKind.Constructor } constructor } captured
                    && captured.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax() is ParameterSyntax { Parent.Parent: TypeDeclarationSyntax }
                    && !HasExactPrimaryConstructorParameterReadSemantics(captured, constructor.ContainingType, constructor)) return false;

                if (symbol is IFieldSymbol field)
                {
                    if (!field.IsReadOnly || !CanUseCurrentInstanceStorageBinding(field, value)
                        || HasAuthoredStorageWrite(field)) return false;

                    if (owner.ValueBindings?.TryGetValue(field, out BoundValueSource? bound) == true && bound is not null && path.Add(field))
                    {
                        try { return StableOrigin(bound.Expression, bound.Caller.Model, path, bound.Caller); }
                        finally { path.Remove(field); }
                    }
                }

                if (symbol is IPropertySymbol { IsStatic: false, SetMethod: null, Parameters.Length: 0, GetMethod: { IsVirtual: false } getter } property
                    && property.ContainingType.IsSealed && !owner.Symbol.IsStatic
                    && (value is IdentifierNameSyntax or MemberAccessExpressionSyntax { Expression: ThisExpressionSyntax })
                    && SymbolEqualityComparer.Default.Equals(property.ContainingType, owner.Symbol.ContainingType)
                    && Resolve(getter, model.Compilation) is { } getterTarget && path.Add(getter))
                {
                    try
                    {
                        AuthoredMember bound = BindStableCapturedCleanupContext(owner, value, getterTarget);

                        ExpressionSyntax[] returns = ReturnedExpressions(bound.Syntax);

                        return returns.Length != 0 && returns.All(returned => StableOrigin(returned, bound.Model, path, bound));
                    }
                    finally { path.Remove(getter); }
                }

                if (value is BaseObjectCreationExpressionSyntax)
                {
                    // This new setup profile closes only construction with no initializer and
                    // compiler-proved constant/default inputs. A primitive declared type on a
                    // local or helper result does not prove its earlier conversions or effects.
                    // Ordinary authored constructor/helper traversal remains independent.
                    if (model.GetOperation(value) is not IObjectCreationOperation { Initializer: null } creation
                        || creation.Arguments.Any(static argument => !ConstantOrDefault(argument))) return false;

                    origins.Add(new(owner, value));

                    return true;
                }

                if (value is ConditionalExpressionSyntax conditional)
                    return StableOrigin(conditional.WhenTrue, model, path, owner) && StableOrigin(conditional.WhenFalse, model, path, owner);

                if (value is InvocationExpressionSyntax invocation && symbol is IMethodSymbol invoked
                    && ResolveCleanupInvocationTarget(invoked, owner, invocation, proof) is { } target && path.Add(invoked))
                {
                    try
                    {
                        // Even unused helper inputs are evaluated. Preserve complete actual
                        // conversion origins before following the helper's exact returned object.
                        if (model.GetOperation(invocation) is not IInvocationOperation call
                            || call.Arguments.Any(argument => argument.Parameter?.RefKind != RefKind.None
                                || argument.InConversion.MethodSymbol is not null || argument.OutConversion.MethodSymbol is not null
                                || !HasReviewedValueConversions(argument.Value, owner))) return false;

                        AuthoredMember bound = BindCleanupInvocationContext(owner, invocation, target, proof);

                        ExpressionSyntax[] returns = ReturnedExpressions(bound.Syntax);

                        return returns.Length != 0 && returns.All(returned => StableOrigin(returned, bound.Model, path, bound));
                    }
                    finally { path.Remove(invoked); }
                }

                return HasOnlyReviewedValueSources(value, model, path, owner, StableOrigin);
            }

            return StableOrigin(expression, member.Model, new(SymbolEqualityComparer.Default), member)
                ? origins.ToArray()
                : null;
        }

        private AuthoredMember? ResolveLongRestSdkFactoryTarget(
            IMethodSymbol method,
            AuthoredMember member,
            InvocationExpressionSyntax call,
            CleanupProvenanceContext proof)
        {
            if (!IsExactLongRestHttpFactoryMethod(method)
                || !IsLongRestSdkSetupDependency(member)
                || AdmissionReceiver(member, call) is not { } receiver)
            {
                return null;
            }

            // The setup observation profile needs the exact caller-selected factory, not a
            // declaration or DI fallback. Primary captures are checked across all partials;
            // known bodies still enter ordinary traversal with their original frontiers.
            if (LongRestSdkValueSources(member, receiver, proof) is not [BoundValueSource source]
                || CleanupProvenanceOf(source.Caller, source.Expression, proof) is not { Complete: true, Candidates: [CleanupTypeCandidate candidate] }
                || candidate.Type is not INamedTypeSymbol { IsSealed: true, IsAbstract: false } concrete) return null;

            IMethodSymbol[] implementations = concrete.AllInterfaces
                .Where(contract => contract.ContainingAssembly.Identity.Equals(method.ContainingAssembly.Identity)
                    && TypeKey(contract) == TypeKey(method.ContainingType))
                .SelectMany(static contract => contract.GetMembers()).OfType<IMethodSymbol>()
                .Where(slot => MethodKey(slot) == MethodKey(method))
                .Select(slot => concrete.FindImplementationForInterfaceMember(slot)).OfType<IMethodSymbol>()
                .DistinctBy(static implementation => implementation.OriginalDefinition, SymbolEqualityComparer.Default).ToArray();

            return implementations is [IMethodSymbol implementation]
                && Resolve(implementation, member.Model.Compilation) is { } target
                    ? BindCleanupInvocationContext(member, call, target, proof, selectedReceiver: source)
                    : null;
        }

        private bool HasExactLongRestSdkOptions(ExpressionSyntax expression, AuthoredMember member)
        {
            CleanupProvenanceContext proof = new();

            HashSet<ISymbol> uses = new(SymbolEqualityComparer.Default);

            bool ClosedUses(ISymbol storage, AuthoredMember owner)
            {
                if (!uses.Add(storage)) return false;

                try
                {
                    if (HasCollectionValueReplacement(owner, storage)) return false;

                    foreach (ExpressionSyntax reference in SymbolReferences(owner, storage))
                    {
                        if (reference == expression || reference.Parent is ReturnStatementSyntax) continue;

                        if (reference.Parent is EqualsValueClauseSyntax { Parent: VariableDeclaratorSyntax alias }
                            && owner.Model.GetDeclaredSymbol(alias) is ILocalSymbol local && ClosedUses(local, owner)) continue;

                        return false;
                    }

                    return true;
                }
                finally
                {
                    uses.Remove(storage);
                }
            }

            bool ExactCreation(IObjectCreationOperation creation, AuthoredMember owner)
            {
                if (creation.Constructor is not { Parameters.Length: 0 } constructor
                    || !IsExactFrameworkType(constructor.ContainingType, "OpenAI.OpenAIClientOptions", typeof(OpenAI.OpenAIClientOptions).Assembly.GetName())
                    || creation.Initializer?.Initializers is not { Length: 3 } initializers) return false;

                HashSet<string> assigned = new(StringComparer.Ordinal);

                foreach (IOperation initializer in initializers)
                {
                    if (initializer is not ISimpleAssignmentOperation { Target: IPropertyReferenceOperation target, Value: { } value }
                        || !assigned.Add(target.Property.Name)) return false;

                    while (value is IConversionOperation { OperatorMethod: null } conversion) value = conversion.Operand;

                    if (value is not IObjectCreationOperation { Constructor: { } nested, Initializer: null } child) return false;

                    bool accepted = target.Property.Name switch
                    {
                        "Endpoint" => IsExactFrameworkType(target.Property.ContainingType, "OpenAI.OpenAIClientOptions", typeof(OpenAI.OpenAIClientOptions).Assembly.GetName())
                            && (IsExactFrameworkType(target.Property.Type, "System.Uri", typeof(Uri).Assembly.GetName())
                                || IsExactFrameworkType(target.Property.Type, "System.Uri", typeof(object).Assembly.GetName()))
                            && (IsExactFrameworkType(nested.ContainingType, "System.Uri", typeof(Uri).Assembly.GetName())
                                || IsExactFrameworkType(nested.ContainingType, "System.Uri", typeof(object).Assembly.GetName()))
                            && HasExactParameterTypes(nested, "System.String"),
                        "RetryPolicy" => IsExactFrameworkType(target.Property.ContainingType, "System.ClientModel.Primitives.ClientPipelineOptions", typeof(System.ClientModel.Primitives.ClientPipelineOptions).Assembly.GetName())
                            && IsExactFrameworkType(target.Property.Type, "System.ClientModel.Primitives.PipelinePolicy", typeof(System.ClientModel.Primitives.PipelinePolicy).Assembly.GetName())
                            && IsExactFrameworkType(nested.ContainingType, "System.ClientModel.Primitives.ClientRetryPolicy", typeof(System.ClientModel.Primitives.ClientRetryPolicy).Assembly.GetName())
                            && HasExactParameterTypes(nested, "System.Int32")
                            && child.Arguments is [{ Value.ConstantValue: { HasValue: true, Value: 0 } }],
                        "Transport" => IsExactFrameworkType(target.Property.ContainingType, "System.ClientModel.Primitives.ClientPipelineOptions", typeof(System.ClientModel.Primitives.ClientPipelineOptions).Assembly.GetName())
                            && IsExactFrameworkType(target.Property.Type, "System.ClientModel.Primitives.PipelineTransport", typeof(System.ClientModel.Primitives.PipelineTransport).Assembly.GetName())
                            && IsExactFrameworkType(nested.ContainingType, "System.ClientModel.Primitives.HttpClientPipelineTransport", typeof(System.ClientModel.Primitives.HttpClientPipelineTransport).Assembly.GetName())
                            && HasExactParameterTypes(nested, "System.Net.Http.HttpClient")
                            && child.Arguments is [{ Value: { Type: { } clientType } suppliedClient }]
                            && IsExactFrameworkType(clientType, "System.Net.Http.HttpClient", typeof(System.Net.Http.HttpClient).Assembly.GetName())
                            && !suppliedClient.DescendantsAndSelf().OfType<IConversionOperation>()
                                .Any(static conversion => conversion.OperatorMethod is not null),
                        _ => false,
                    };

                    if (!accepted) return false;
                }

                return true;
            }

            bool Origin(ExpressionSyntax value, SemanticModel model, HashSet<ISymbol> path, AuthoredMember? owner)
            {
                if (owner is null || proof.RemainingWork-- <= 0) return false;

                value = StripTransparentExpression(value);

                ISymbol? symbol = model.GetSymbolInfo(value).Symbol;

                if (symbol is ILocalSymbol or IParameterSymbol && !ClosedUses(symbol, owner)) return false;

                if (model.GetOperation(value) is IObjectCreationOperation creation) return ExactCreation(creation, owner);

                if (value is InvocationExpressionSyntax call && symbol is IMethodSymbol method
                    && ResolveCleanupInvocationTarget(method, owner, call, proof) is { } target && path.Add(method))
                {
                    try
                    {
                        AuthoredMember bound = BindCleanupInvocationContext(owner, call, target, proof);

                        ExpressionSyntax[] returns = ReturnedExpressions(bound.Syntax);

                        return returns.Length != 0 && returns.All(returned => Origin(returned, bound.Model, path, bound));
                    }
                    finally
                    {
                        path.Remove(method);
                    }
                }

                return HasOnlyReviewedValueSources(value, model, path, owner, Origin);
            }

            // Exact transport construction validates and stores its typed client; factory/getter/
            // conversion work and future sends are separate execution obligations, never purity.
            // Ambient Chat telemetry switches, BeforeFieldInit/shared HttpClient
            // observers, reflection/loader/native behavior and third-party observer closure are
            // outside this authored proof. Authored arguments, getters and callbacks still traverse.
            return Origin(expression, member.Model, new(SymbolEqualityComparer.Default), member);
        }

        private bool HasExactCodeOwnedChatOptions(ExpressionSyntax expression, SemanticModel model, AuthoredMember? context)
        {
            expression = StripTransparentExpression(expression);

            if (model.GetSymbolInfo(expression).Symbol is ILocalSymbol local)
            {
                if (context is null
                    || !HasOnlyReferences(context, local, expression)
                    || local.DeclaringSyntaxReferences is not [SyntaxReference declaration]
                    || declaration.GetSyntax() is not VariableDeclaratorSyntax { Initializer.Value: { } initializer })
                {
                    return false;
                }

                expression = StripTransparentExpression(initializer);
                model = semanticModels[expression.SyntaxTree];
            }

            if (model.GetOperation(expression) is not IObjectCreationOperation creation
                || creation.Constructor is not { Parameters.Length: 0 } constructor
                || !IsExactFrameworkType(constructor.ContainingType, "OpenAI.OpenAIClientOptions",
                    typeof(OpenAI.OpenAIClientOptions).Assembly.GetName()))
            {
                return false;
            }

            foreach (IOperation initializer in creation.Initializer?.Initializers ?? [])
            {
                if (initializer is not ISimpleAssignmentOperation { Target: IPropertyReferenceOperation property, Value: { } value }
                    || property.Property.Name switch
                    {
                        "Endpoint" => !IsExactSdkOptionCreation(value, "System.Uri", typeof(Uri).Assembly.GetName()),
                        "Transport" => !IsExactSdkOptionCreation(value, "System.ClientModel.Primitives.HttpClientPipelineTransport",
                            typeof(System.ClientModel.Primitives.HttpClientPipelineTransport).Assembly.GetName()),
                        "RetryPolicy" => !IsExactSdkOptionCreation(value, "System.ClientModel.Primitives.ClientRetryPolicy",
                            typeof(System.ClientModel.Primitives.ClientRetryPolicy).Assembly.GetName()),
                        _ => true,
                    })
                {
                    return false;
                }
            }

            // The pinned SDK constructs policies and freezes its options here. Only an exact,
            // unescaped SDK options object may be treated as mechanical: a derived Freeze or
            // caller-owned logging/options object could execute arbitrary code in this ctor.
            return true;
        }

        private static bool IsExactSdkOptionCreation(IOperation value, string type, AssemblyName assembly)
        {
            while (value is IConversionOperation conversion)
            {
                value = conversion.Operand;
            }

            return value is IObjectCreationOperation { Constructor: { } constructor }
                && (IsExactFrameworkType(constructor.ContainingType, type, assembly)
                    || type == "System.Uri"
                        && IsExactFrameworkType(constructor.ContainingType, type, typeof(object).Assembly.GetName()));
        }

        private bool IsReviewedConcreteTokenizerCall(IMethodSymbol method, SyntaxNode? node, SemanticModel? model, AuthoredMember? context)
        {
            if (node is not InvocationExpressionSyntax call
                || model?.GetOperation(call) is not IInvocationOperation invocation
                || !FrameworkAssemblyIdentityMatches(method.ContainingAssembly.Identity,
                    typeof(Microsoft.ML.Tokenizers.TiktokenTokenizer).Assembly.GetName()))
            {
                return false;
            }

            if (IsExactDefaultTokenizerFactory(method, invocation))
            {
                return true;
            }

            if (method.Name != "CountTokens"
                || TypeKey(method.ContainingType) != "Microsoft.ML.Tokenizers.Tokenizer"
                || !HasExactParameterTypes(method, "System.String", "System.Boolean", "System.Boolean")
                || invocation.Instance?.Syntax is not ExpressionSyntax receiver
                || !IsExactFrameworkType(invocation.Instance.Type!, "Microsoft.ML.Tokenizers.TiktokenTokenizer",
                    typeof(Microsoft.ML.Tokenizers.TiktokenTokenizer).Assembly.GetName())
                || invocation.Arguments.SingleOrDefault(static argument => argument.Parameter?.Name == "considerPreTokenization")
                    ?.Value.ConstantValue is not { HasValue: true, Value: true }
                || invocation.Arguments.SingleOrDefault(static argument => argument.Parameter?.Name == "considerNormalization")
                    ?.Value.ConstantValue is not { HasValue: true, Value: false })
            {
                return false;
            }

            return HasOnlyReviewedValueSources(receiver, model, new HashSet<ISymbol>(SymbolEqualityComparer.Default),
                context, HasExactDefaultTokenizerValue);
        }

        private bool HasExactDefaultTokenizerValue(ExpressionSyntax expression, SemanticModel model, HashSet<ISymbol> path, AuthoredMember? context)
        {
            expression = StripTransparentExpression(expression);

            if (model.GetOperation(expression) is IInvocationOperation factory
                && IsExactDefaultTokenizerFactory(factory.TargetMethod, factory))
            {
                return true;
            }

            return HasOnlyReviewedValueSources(expression, model, path, context, HasExactDefaultTokenizerValue);
        }

        private static bool IsExactDefaultTokenizerFactory(IMethodSymbol method, IInvocationOperation invocation) =>
            method.IsStatic
            && method.Name == "CreateForEncoding"
            && IsExactFrameworkType(method.ContainingType, "Microsoft.ML.Tokenizers.TiktokenTokenizer",
                typeof(Microsoft.ML.Tokenizers.TiktokenTokenizer).Assembly.GetName())
            && HasExactParameterTypes(method, "System.String", "System.Collections.Generic.IReadOnlyDictionary`2", "Microsoft.ML.Tokenizers.Normalizer")
            && invocation.Arguments.Where(static argument => argument.Parameter?.Ordinal != 0)
                .All(static argument => argument.Value.ConstantValue is { HasValue: true, Value: null });

        private bool IsExactOwnedWatcherCleanup(
            IMethodSymbol method,
            SyntaxNode? node,
            AuthoredMember? member)
        {
            if (member is null
                || method.Name != "Dispose"
                || method.IsStatic
                || method.Parameters.Length != 0
                || !method.ReturnsVoid
                || !IsExactFrameworkType(method.ContainingType,
                    "System.ComponentModel.Component",
                    typeof(System.ComponentModel.Component).Assembly.GetName())
                || node is not InvocationExpressionSyntax call
                || AdmissionReceiver(member, call) is not { } receiver
                || !HasOwnedFileSystemWatcherLifetime(member, receiver))
            {
                return false;
            }

            CleanupProvenance provenance = CleanupProvenanceOf(
                member, receiver, new CleanupProvenanceContext());

            return provenance.Complete
                && provenance.Candidates is [CleanupTypeCandidate candidate]
                && IsExactFrameworkType(candidate.Type,
                    "System.IO.FileSystemWatcher",
                    typeof(FileSystemWatcher).Assembly.GetName());
        }

        private bool RequiresExternalBoundaryClassification(
            IPropertySymbol property,
            Compilation compilation,
            bool mutation,
            SyntaxNode? node = null,
            SemanticModel? model = null,
            AuthoredMember? context = null)
        {
            string callee = Normalize(property);

            if (Vocabulary.ContainsKey(callee)
                || IsPureFileSystemMetadataProperty(property)
                || IsReviewedEnumeratorProperty(
                    property,
                    mutation,
                    node,
                    model,
                    context)
                || IsReviewedFrameworkCollectionIndexer(
                    property,
                    mutation,
                    node,
                    model,
                    context)
                || IsReviewedPrimitiveQueueProperty(property, mutation, node, context)
                || IsReviewedExactMeAiDimensionsProperty(property, mutation)
                || IsReviewedNonProducerExternalMember(property, mutation)
                || !mutation && IsReviewedFrameworkEventDataRead(property)
                || IsReviewedDatabaseSupportMember(property, mutation)
                    && !(mutation && TrackingBlockedByIdentityResolution(property))
                    && ReviewedProviderMemberIsClosed(property, node, model, context))
            {
                return false;
            }

            IMethodSymbol[] accessors = new IMethodSymbol?[]
                {
                    property.GetMethod,
                    property.SetMethod,
                }
                .OfType<IMethodSymbol>()
                .ToArray();

            if (SensitiveBoundaryTypes.Contains(TypeKey(property.ContainingType)))
            {
                return accessors.All(accessor => Resolve(accessor, compilation) is null);
            }

            return accessors.Length != 0
                && accessors.All(accessor => Resolve(accessor, compilation) is null
                    && accessor.Locations.All(static location => !location.IsInSource))
                && !property.ContainingNamespace.ToDisplayString()
                    .StartsWith("RetroDownfall.", StringComparison.Ordinal);
        }

        private bool IsReviewedEffectFreeExternalMember(
            IMethodSymbol method,
            SyntaxNode? node = null,
            SemanticModel? model = null,
            AuthoredMember? context = null)
        {
            if (IsExactSqliteCommandFactorySlot(method))
                return IsReviewedExactSqliteCommandFactory(method, node, context);

            if (CompletionOwnedExternalAwaitables.Contains(Normalize(method))
                || ReviewedBoundedIntrinsicMembers.Contains(Normalize(method))
                || ReviewedNonProducerExternalMembers.Contains(Normalize(method))
                || IsReviewedExactNativeImport(method)
                || IsReviewedExactBoundedExternalMember(method)
                || IsExactEmbeddingSdkAdapterFactory(method)
                || IsReviewedDatabaseSupportMember(method)
                    && !TrackingBlockedByIdentityResolution(method)
                    && ReviewedProviderMemberIsClosed(method, node, model, context)
                || IsReviewedEfInterceptorBaseCall(method, node, model)
                || IsReviewedAccessorLoggerFactoryRead(method) && inventoryFacts.AuthoredLoggerType is null
                || IsReviewedEfQueryOperator(method, node, model, context)
                || IsReviewedProviderNeutralOptionsBuilderMember(method)
                || IsReviewedRuntimeCleanup(method)
                || IsReviewedFloatVectorMember(method, node, model, context)
                || IsReviewedExactInMemoryConstruction(method)
                || IsReviewedAsyncStateMachineMember(method)
                || IsReviewedExactFrameworkScalarOperator(method, node, model, context)
                || IsReviewedExactTypeOfEqualityOperator(method, node, model)
                || IsReviewedPrimitiveQueueMember(method, node, model, context)
                || IsReviewedInvariantDateTimeParser(method, node, model)
                || IsReviewedDefaultProviderUInt32Format(method, node, model)
                || IsExactIntegerRange(method)
                || IsReviewedCollectionMechanicalMember(method)
                || IsReviewedInterpolatedStringCreate(method)
                || IsReviewedSequenceOperation(method, node, model)
                || IsReviewedInMemoryOrderingOperation(method, node, model))
            {
                return true;
            }

            if (!ReviewedIntrinsicExternalTypes.Contains(
                    TypeKey(method.ContainingType))
                || !HasExactSpecialTypeIdentity(method.ContainingType)
                || method.Parameters.Any(static parameter =>
                    parameter.RefKind != RefKind.None
                    || parameter.Type.TypeKind == TypeKind.Delegate))
            {
                return false;
            }

            return HasOnlyReviewedComparerArguments(
                method,
                node,
                model);
        }

        private static bool IsExactIntegerRange(IMethodSymbol method) =>
            method is { IsStatic: true, Arity: 0, Name: "Range" }
                && IsExactFrameworkType(method.ContainingType,
                    "System.Linq.Enumerable", typeof(Enumerable).Assembly.GetName())
                && method.Parameters is
                [
                    { RefKind: RefKind.None, Type.SpecialType: SpecialType.System_Int32 },
                    { RefKind: RefKind.None, Type.SpecialType: SpecialType.System_Int32 },
                ]
                && method.ReturnType is INamedTypeSymbol
                {
                    TypeArguments: [{ SpecialType: SpecialType.System_Int32 }],
                } sequence
                && IsExactFrameworkType(sequence, "System.Collections.Generic.IEnumerable`1",
                    typeof(IEnumerable<>).Assembly.GetName());

        // The state machine an async method compiles to is the body of that async method: an authored builder's Start calls
        // its MoveNext, and what MoveNext runs is the async method, which is traversed as the method itself.
        private static bool IsReviewedAsyncStateMachineMember(IMethodSymbol method) =>
            method is { Name: "MoveNext" or "SetStateMachine", IsStatic: false }
            && IsExactFrameworkType(method.ContainingType, "System.Runtime.CompilerServices.IAsyncStateMachine", typeof(System.Runtime.CompilerServices.IAsyncStateMachine).Assembly.GetName());

        // UInt32.TryFormat(Span<char>, out int, ReadOnlySpan<char>, IFormatProvider) writes the digits of the value into the
        // caller's span. It runs no supplied code when the provider is the default one the caller did not pass: a provider
        // that was passed is asked for its number format, which an authored provider answers with code of its own.
        private static bool IsReviewedDefaultProviderUInt32Format(
            IMethodSymbol method,
            SyntaxNode? node,
            SemanticModel? model) =>
            !method.IsStatic && method.Arity == 0 && method.Name == "TryFormat"
            && method.ReturnType.SpecialType == SpecialType.System_Boolean
            && IsExactFrameworkType(method.ContainingType, "System.UInt32", typeof(uint).Assembly.GetName())
            && method.Parameters is
            [
                { RefKind: RefKind.None, Type: INamedTypeSymbol { Name: "Span", TypeArguments: [{ SpecialType: SpecialType.System_Char }] } destination },
                { RefKind: RefKind.Out, Type.SpecialType: SpecialType.System_Int32 },
                { RefKind: RefKind.None, Type: INamedTypeSymbol { Name: "ReadOnlySpan", TypeArguments: [{ SpecialType: SpecialType.System_Char }] } format },
                { RefKind: RefKind.None, Type: { } providerType },
            ]
            && IsExactFrameworkType(destination, "System.Span`1", typeof(Span<>).Assembly.GetName())
            && IsExactFrameworkType(format, "System.ReadOnlySpan`1", typeof(ReadOnlySpan<>).Assembly.GetName())
            && IsExactFrameworkType(providerType, "System.IFormatProvider", typeof(IFormatProvider).Assembly.GetName())
            && node is not null
            && model?.GetOperation(node) is IInvocationOperation invocation
            && invocation.Arguments.Any(static argument => argument.Parameter?.Ordinal == 3 && argument.ArgumentKind == ArgumentKind.DefaultValue);

        private bool IsReviewedInvariantDateTimeParser(
            IMethodSymbol method,
            SyntaxNode? node,
            SemanticModel? model)
        {
            if (!method.IsStatic || method.Arity != 0 || method.Name != "TryParse"
                || method.ReturnType.SpecialType != SpecialType.System_Boolean
                || !IsExactFrameworkType(method.ContainingType, "System.DateTimeOffset", typeof(DateTimeOffset).Assembly.GetName())
                || method.Parameters is not
                [
                    { RefKind: RefKind.None, Type.SpecialType: SpecialType.System_String },
                    { RefKind: RefKind.None, Type: { } providerType },
                    { RefKind: RefKind.None, Type: { } stylesType },
                    { RefKind: RefKind.Out, Type: { } resultType },
                ]
                || !IsExactFrameworkType(providerType, "System.IFormatProvider", typeof(IFormatProvider).Assembly.GetName())
                || !IsExactFrameworkType(stylesType, "System.Globalization.DateTimeStyles", typeof(DateTimeStyles).Assembly.GetName())
                || !IsExactFrameworkType(resultType, "System.DateTimeOffset", typeof(DateTimeOffset).Assembly.GetName())
                || node is null || model?.GetOperation(node) is not IInvocationOperation invocation
                || invocation.Arguments.FirstOrDefault(static argument => argument.Parameter?.Ordinal == 1)?.Value.Syntax
                    is not ExpressionSyntax provider)
            {
                return false;
            }

            bool InvariantOrigin(ExpressionSyntax expression, SemanticModel semanticModel, HashSet<ISymbol> path, AuthoredMember? context)
            {
                ITypeSymbol? valueType = semanticModel.GetTypeInfo(expression).Type;

                if (valueType is null
                    || !IsExactFrameworkType(valueType, "System.Globalization.CultureInfo", typeof(CultureInfo).Assembly.GetName())
                        && !IsExactFrameworkType(valueType, "System.IFormatProvider", typeof(IFormatProvider).Assembly.GetName()))
                {
                    return false;
                }

                if (semanticModel.GetSymbolInfo(expression).Symbol is IPropertySymbol
                    { Name: "InvariantCulture", IsStatic: true, GetMethod: not null, SetMethod: null } property
                    && IsExactFrameworkType(property.ContainingType, "System.Globalization.CultureInfo", typeof(CultureInfo).Assembly.GetName())
                    && IsExactFrameworkType(property.Type, "System.Globalization.CultureInfo", typeof(CultureInfo).Assembly.GetName()))
                {
                    return true;
                }

                return HasOnlyReviewedValueSources(expression, semanticModel, path, context, InvariantOrigin);
            }

            return InvariantOrigin(provider, model, new(SymbolEqualityComparer.Default), null);
        }

        private static bool IsExactFrameworkScalarConversionOperator(IMethodSymbol method)
        {
            bool index = method is { IsStatic: true, Arity: 0, Name: "op_Implicit", Parameters: [{ RefKind: RefKind.None, Type.SpecialType: SpecialType.System_Int32 }] }
                && IsExactFrameworkType(method.ContainingType, "System.Index", typeof(Index).Assembly.GetName())
                && IsExactFrameworkType(method.ReturnType, "System.Index", typeof(Index).Assembly.GetName());

            bool int128 = method is { IsStatic: true, Arity: 0, Name: "op_Implicit", Parameters: [{ RefKind: RefKind.None, Type.SpecialType: SpecialType.System_SByte or SpecialType.System_Byte or SpecialType.System_Int16 or SpecialType.System_UInt16 or SpecialType.System_Int32 or SpecialType.System_UInt32 or SpecialType.System_Int64 or SpecialType.System_UInt64 }] }
                && IsExactFrameworkType(method.ContainingType, "System.Int128", typeof(Int128).Assembly.GetName())
                && IsExactFrameworkType(method.ReturnType, "System.Int128", typeof(Int128).Assembly.GetName());

            return index || int128;
        }

        // Exact framework scalar binary operators: Int128 arithmetic and CancellationToken equality.
        private static bool IsExactFrameworkScalarBinaryOperator(IMethodSymbol method)
        {
            bool int128 = method is { IsStatic: true, Arity: 0, MethodKind: MethodKind.UserDefinedOperator, Name: "op_Addition" or "op_Subtraction" or "op_Multiply" or "op_Division" }
                && method.Parameters is [{ RefKind: RefKind.None } leftInt, { RefKind: RefKind.None } rightInt]
                && IsExactFrameworkType(method.ContainingType, "System.Int128", typeof(Int128).Assembly.GetName())
                && IsExactFrameworkType(method.ReturnType, "System.Int128", typeof(Int128).Assembly.GetName())
                && IsExactFrameworkType(leftInt.Type, "System.Int128", typeof(Int128).Assembly.GetName())
                && IsExactFrameworkType(rightInt.Type, "System.Int128", typeof(Int128).Assembly.GetName());

            bool token = method is { IsStatic: true, Arity: 0, MethodKind: MethodKind.UserDefinedOperator, Name: "op_Equality" or "op_Inequality", ReturnType.SpecialType: SpecialType.System_Boolean }
                && method.Parameters is [{ RefKind: RefKind.None } leftToken, { RefKind: RefKind.None } rightToken]
                && IsExactFrameworkType(method.ContainingType, "System.Threading.CancellationToken", typeof(CancellationToken).Assembly.GetName())
                && IsExactFrameworkType(leftToken.Type, "System.Threading.CancellationToken", typeof(CancellationToken).Assembly.GetName())
                && IsExactFrameworkType(rightToken.Type, "System.Threading.CancellationToken", typeof(CancellationToken).Assembly.GetName());

            return int128 || token;
        }

        // Framework value conversions that may appear inside an operand without making it an
        // authored conversion: the exact scalar operators above, and the exact float Span carriers.
        private static bool IsReviewedFrameworkValueConversion(IMethodSymbol method) =>
            IsExactFrameworkScalarConversionOperator(method)
            || method is { IsStatic: true, Arity: 0, MethodKind: MethodKind.Conversion, Name: "op_Implicit", Parameters: [{ RefKind: RefKind.None }] }
                && (IsExactFloatCarrier(method.ContainingType, "System.Span`1")
                    || IsExactFloatCarrier(method.ContainingType, "System.ReadOnlySpan`1"));

        // Structural Operand Rule. The operand expression contains no user-defined conversion at
        // the operator boundary: only parentheses and conversions are walked, and every selected
        // conversion operator must be an exact framework value conversion. Everything beneath
        // that boundary (calls, property reads, locals, operators) is traversed where it is
        // written, so no execution is hidden by accepting the framework operator itself.
        private static bool OperandUsesOnlyBuiltInConversions(IOperation operand)
        {
            for (int depth = 0; depth < 64; depth++)
            {
                switch (operand)
                {
                    case IParenthesizedOperation parenthesized:
                        operand = parenthesized.Operand;

                        continue;

                    case IConversionOperation conversion:
                        IMethodSymbol? selected = conversion.OperatorMethod ?? conversion.Conversion.MethodSymbol;

                        if (selected is null ? conversion.Conversion.IsUserDefined : !IsReviewedFrameworkValueConversion(selected)) return false;

                        operand = conversion.Operand;

                        continue;

                    default:
                        return true;
                }
            }

            return false;
        }

        private static bool ArgumentBoundaryUsesOnlyBuiltInConversions(IArgumentOperation argument) =>
            argument.Parameter is { RefKind: RefKind.None }
            && argument.InConversion.MethodSymbol is null
            && argument.OutConversion.MethodSymbol is null
            && OperandUsesOnlyBuiltInConversions(argument.Value);

        private bool IsReviewedExactFrameworkScalarOperator(
            IMethodSymbol method,
            SyntaxNode? node,
            SemanticModel? model,
            AuthoredMember? context)
        {
            if (context is null || node is null || model is null) return false;

            if (IsExactFrameworkScalarConversionOperator(method))
            {
                IConversionOperation? conversion = UserConversionsAt(context, node)
                    .FirstOrDefault(candidate => SymbolEqualityComparer.Default.Equals(candidate.OperatorMethod, method));

                return conversion is not null && OperandUsesOnlyBuiltInConversions(conversion.Operand);
            }

            return IsExactFrameworkScalarBinaryOperator(method)
                && node is BinaryExpressionSyntax
                && model.GetOperation(node) is IBinaryOperation { IsLifted: false, OperatorMethod: { } selected } binary
                && SymbolEqualityComparer.Default.Equals(selected, method)
                && OperandUsesOnlyBuiltInConversions(binary.LeftOperand)
                && OperandUsesOnlyBuiltInConversions(binary.RightOperand);
        }

        private static bool IsExactFloatCarrier(ITypeSymbol type, string metadataName) =>
            type is INamedTypeSymbol { TypeArguments: [{ SpecialType: SpecialType.System_Single }] }
            && IsExactFrameworkType(type, metadataName, typeof(float).Assembly.GetName());

        private static bool IsExactFloatVectorCarrier(ITypeSymbol type) =>
            type is INamedTypeSymbol { TypeArguments: [{ SpecialType: SpecialType.System_Single }] }
            && IsExactFloatVectorType(type, "System.Numerics.Vector`1");

        private static bool IsExactFloatVectorType(ITypeSymbol type, string metadataName) =>
            metadataName is "System.Numerics.Vector" or "System.Numerics.Vector`1"
            && (IsExactFrameworkType(type, metadataName, typeof(float).Assembly.GetName())
                || IsExactFrameworkType(
                    type,
                    metadataName,
                    Assembly.Load(new AssemblyName("System.Numerics.Vectors")).GetName()));

        private static bool IsReviewedFloatVectorProperty(IPropertySymbol property) =>
            property.Name == "Count"
            && property.IsStatic
            && property.Parameters.IsEmpty
            && property.GetMethod is not null
            && property.SetMethod is null
            && property.Type.SpecialType == SpecialType.System_Int32
            && IsExactFloatVectorCarrier(property.ContainingType);

        private static bool IsReviewedExactGeneratedEmbeddingRead(IPropertySymbol property, bool mutation)
        {
            AssemblyName sdkAssembly = typeof(Microsoft.Extensions.AI.GeneratedEmbeddings<>).Assembly.GetName();

            if (mutation
                || property.IsStatic
                || property.Locations.Any(static location => location.IsInSource)
                || property.ExplicitInterfaceImplementations.Length != 0
                || property.GetMethod is not { } getter
                || getter.IsStatic
                || getter.IsAbstract
                || getter.IsVirtual
                || getter.IsOverride
                || getter.ReturnsByRef
                || getter.ReturnsByRefReadonly
                || getter.MethodKind != MethodKind.PropertyGet
                || getter.Locations.Any(static location => location.IsInSource)
                || !IsExactFrameworkType(property.ContainingType,
                    "Microsoft.Extensions.AI.GeneratedEmbeddings`1", sdkAssembly)
                || property.ContainingType is not INamedTypeSymbol
                    { IsSealed: true, TypeArguments: [INamedTypeSymbol embedding] }
                || !IsExactFrameworkType(embedding, "Microsoft.Extensions.AI.Embedding`1", sdkAssembly)
                || embedding.TypeArguments is not [{ SpecialType: SpecialType.System_Single }]
                || !IsExactFrameworkType(getter.ContainingType,
                    "Microsoft.Extensions.AI.GeneratedEmbeddings`1", sdkAssembly)
                || !SymbolEqualityComparer.Default.Equals(getter.ReturnType, property.Type))
            {
                return false;
            }

            bool exactCount = property.Name == "Count"
                && !property.IsIndexer
                && property.Parameters.IsEmpty
                && property.SetMethod is null
                && property.Type.SpecialType == SpecialType.System_Int32
                && getter.MetadataName == "get_Count"
                && getter.Parameters.IsEmpty;

            bool exactIndexer = property.IsIndexer
                && property.MetadataName == "Item"
                && property.Parameters is [{ RefKind: RefKind.None, Type.SpecialType: SpecialType.System_Int32 }]
                && getter.MetadataName == "get_Item"
                && getter.Parameters is [{ RefKind: RefKind.None, Type.SpecialType: SpecialType.System_Int32 }]
                && SymbolEqualityComparer.Default.Equals(property.Type, embedding)
                && SymbolEqualityComparer.Default.Equals(getter.ReturnType, embedding);

            return exactCount || exactIndexer;
        }

        private static bool IsExactPrimitivePriorityQueue(ITypeSymbol type) => type is INamedTypeSymbol
            {
                TypeArguments: [_, INamedTypeSymbol priority],
            } queue
            && IsExactFrameworkType(queue, "System.Collections.Generic.PriorityQueue`2", typeof(PriorityQueue<,>).Assembly.GetName())
            && IsExactFrameworkType(priority.TupleUnderlyingType ?? priority, "System.ValueTuple`3", typeof(object).Assembly.GetName())
            && priority.TypeArguments is
                [{ SpecialType: SpecialType.System_Double }, { SpecialType: SpecialType.System_UInt64 }, { SpecialType: SpecialType.System_UInt64 }];

        private static bool IsExactPrimitiveQueueMember(IMethodSymbol method)
        {
            if (!IsExactPrimitivePriorityQueue(method.ContainingType) || method.IsStatic || method.Arity != 0) return false;

            return method.MethodKind == MethodKind.Constructor && method.Parameters.IsEmpty
                || method.Name == "Enqueue" && method.ReturnsVoid && method.Parameters is [{ RefKind: RefKind.None } element, { RefKind: RefKind.None } priority]
                    && SymbolEqualityComparer.Default.Equals(element.Type, method.ContainingType.TypeArguments[0])
                    && SymbolEqualityComparer.Default.Equals(priority.Type, method.ContainingType.TypeArguments[1])
                || method.Name == "Dequeue" && method.Parameters.IsEmpty
                    && SymbolEqualityComparer.Default.Equals(method.ReturnType, method.ContainingType.TypeArguments[0]);
        }

        private static bool IsExactPrimitiveQueueProperty(IPropertySymbol property) => !property.IsStatic
            && IsExactPrimitivePriorityQueue(property.ContainingType)
            && property.Parameters.IsEmpty && property.GetMethod is not null && property.SetMethod is null
            && (property.Name == "Count" && property.Type.SpecialType == SpecialType.System_Int32
                || property.Name == "UnorderedItems" && property.Type is INamedTypeSymbol items
                    && items.Name == "UnorderedItemsCollection"
                    && SymbolEqualityComparer.Default.Equals(items.ContainingType, property.ContainingType)
                    && FrameworkAssemblyIdentityMatches(items.ContainingAssembly.Identity, typeof(PriorityQueue<,>).Assembly.GetName()));

        private bool HasExactDefaultPrimitiveQueueOrigin(ExpressionSyntax expression, AuthoredMember member)
        {
            CleanupProvenanceContext proof = new();

            bool Origin(ExpressionSyntax value, SemanticModel model, HashSet<ISymbol> path, AuthoredMember? owner)
            {
                if (owner is null || proof.RemainingWork-- <= 0) return false;

                value = StripTransparentExpression(value);

                ISymbol? symbol = model.GetSymbolInfo(value).Symbol;

                if (symbol is ILocalSymbol or IParameterSymbol
                    && HasCollectionValueReplacement(owner, symbol)) return false;

                if (model.GetOperation(value) is IObjectCreationOperation { Constructor: { } constructor, Initializer: null }
                    && IsExactPrimitiveQueueMember(constructor)) return true;

                if (value is InvocationExpressionSyntax call && symbol is IMethodSymbol method
                    && ResolveCleanupInvocationTarget(method, owner, call, proof) is { } target && path.Add(method))
                {
                    try
                    {
                        AuthoredMember bound = BindCleanupInvocationContext(owner, call, target, proof);

                        ExpressionSyntax[] returns = ReturnedExpressions(bound.Syntax);

                        return returns.Length != 0 && returns.All(returned => Origin(returned, bound.Model, path, bound));
                    }
                    finally
                    {
                        path.Remove(method);
                    }
                }

                return HasOnlyReviewedValueSources(value, model, path, owner, Origin);
            }

            return Origin(expression, member.Model, new(SymbolEqualityComparer.Default), member);
        }

        private bool IsReviewedPrimitiveQueueMember(IMethodSymbol method, SyntaxNode? node, SemanticModel? model, AuthoredMember? context)
        {
            if (!IsExactPrimitiveQueueMember(method) || node is null || model is null || context is null) return false;

            if (method.MethodKind == MethodKind.Constructor) return model.GetOperation(node) is IObjectCreationOperation { Initializer: null };

            // The receiver must still be an exact default-constructed queue, so its priority comparison is the
            // pure primitive tuple comparison. The arguments need only the argument-boundary rule: they are
            // evaluated and traversed where they are written, and the queue merely stores and orders them.
            return model.GetOperation(node) is IInvocationOperation invocation
                && invocation.Instance?.Syntax is ExpressionSyntax receiver
                && HasExactDefaultPrimitiveQueueOrigin(receiver, context)
                && invocation.Arguments.All(ArgumentBoundaryUsesOnlyBuiltInConversions);
        }

        private bool IsReviewedPrimitiveQueueProperty(IPropertySymbol property, bool mutation, SyntaxNode? node, AuthoredMember? context) =>
            !mutation && IsExactPrimitiveQueueProperty(property) && context is not null
            && node is MemberAccessExpressionSyntax access && HasExactDefaultPrimitiveQueueOrigin(access.Expression, context);

        private bool HasReviewedPrimitiveQueueItems(ExpressionSyntax expression, SemanticModel model, AuthoredMember? context) =>
            context is not null && expression is MemberAccessExpressionSyntax access
            && model.GetSymbolInfo(access).Symbol is IPropertySymbol { Name: "UnorderedItems" } property
            && IsExactPrimitiveQueueProperty(property)
            && HasExactDefaultPrimitiveQueueOrigin(access.Expression, context);

        private static bool IsExactFloatVectorSignature(IMethodSymbol method)
        {
            bool finite = method.IsStatic
                && method.Name == "IsFinite"
                && method.Arity == 0
                && method.ReturnType.SpecialType == SpecialType.System_Boolean
                && HasExactParameterTypes(method, "System.Single")
                && IsExactFrameworkType(method.ContainingType, "System.Single", typeof(float).Assembly.GetName());

            bool constructor = method.MethodKind == MethodKind.Constructor
                && !method.IsStatic
                && IsExactFloatVectorCarrier(method.ContainingType)
                && method.Parameters is [{ RefKind: RefKind.None, Type: { } span }]
                && IsExactFloatCarrier(span, "System.ReadOnlySpan`1");

            bool dot = method.IsStatic
                && method.Name == "Dot"
                && method.TypeArguments is [{ SpecialType: SpecialType.System_Single }]
                && method.ReturnType.SpecialType == SpecialType.System_Single
                && method.Parameters.Length == 2
                && method.Parameters.All(static parameter => parameter.RefKind == RefKind.None
                    && IsExactFloatVectorCarrier(parameter.Type))
                && IsExactFloatVectorType(method.ContainingType, "System.Numerics.Vector");

            return finite || constructor || dot;
        }

        // The pure intrinsic table: float and double IsFinite, the Vector<float>(ReadOnlySpan<float>)
        // constructor and Vector.Dot<float>. Each is an exact framework identity with no effect and
        // no handle; the argument-boundary rule (no ref or out parameter, no user-defined
        // conversion at the boundary) is the whole demand, because the argument expressions are
        // themselves traversed where they are written.
        private static bool IsExactDoubleFiniteSignature(IMethodSymbol method) =>
            method.IsStatic
            && method.Name == "IsFinite"
            && method.Arity == 0
            && method.ReturnType.SpecialType == SpecialType.System_Boolean
            && HasExactParameterTypes(method, "System.Double")
            && IsExactFrameworkType(method.ContainingType, "System.Double", typeof(double).Assembly.GetName());

        private bool IsReviewedFloatVectorMember(
            IMethodSymbol method,
            SyntaxNode? node,
            SemanticModel? model,
            AuthoredMember? context)
        {
            if (!IsExactFloatVectorSignature(method) && !IsExactDoubleFiniteSignature(method))
            {
                return false;
            }

            IEnumerable<IArgumentOperation> arguments = node is null || model is null ? [] : model.GetOperation(node) switch
            {
                IInvocationOperation invocation => invocation.Arguments,
                IObjectCreationOperation creation => creation.Arguments,
                _ => [],
            };

            return node is not null && model is not null
                && arguments.All(ArgumentBoundaryUsesOnlyBuiltInConversions);
        }

        private bool HasReviewedValueConversions(IOperation value, AuthoredMember? member, bool hierarchyObservation = false)
        {
            if (member is null)
            {
                return false;
            }

            CleanupProvenanceContext proof = new();

            HashSet<ISymbol> path = new(SymbolEqualityComparer.Default);

            bool Carrier(ITypeSymbol? type) => type is IArrayTypeSymbol
                || type is INamedTypeSymbol named
                    && (IsExactFrameworkType(named, "System.Span`1", typeof(object).Assembly.GetName())
                        || IsExactFrameworkType(named, "System.ReadOnlySpan`1", typeof(object).Assembly.GetName()));

            HashSet<ISymbol> carrierUses = new(SymbolEqualityComparer.Default);

            bool ClosedCarrierUses(ISymbol storage, AuthoredMember owner)
            {
                if (!carrierUses.Add(storage)) return false;

                try
                {
                    if (HasCollectionValueReplacement(owner, storage)) return false;

                    bool ReadUse(IOperation operation, bool view = false)
                    {
                        if (proof.RemainingWork-- <= 0) return false;

                        while (operation.Parent is IParenthesizedOperation
                            || operation.Parent is IConversionOperation conversion
                                && (conversion.OperatorMethod is null
                                    || IsExactFloatCarrier(conversion.OperatorMethod.ContainingType, "System.Span`1")
                                    || IsExactFloatCarrier(conversion.OperatorMethod.ContainingType, "System.ReadOnlySpan`1")))
                        {
                            view |= operation.Parent is IConversionOperation converted && Carrier(converted.Type);

                            operation = operation.Parent;
                        }

                        if (operation.Parent is IArrayElementReferenceOperation element && element.ArrayReference == operation) return true;

                        if (operation.Parent is IPropertyReferenceOperation property && property.Instance == operation
                            && FrameworkAssemblyIdentityMatches(property.Property.ContainingAssembly.Identity, typeof(object).Assembly.GetName())
                            && (property.Property.Name == "Length" && property.Property.Parameters.IsEmpty
                                && property.Property.Type.SpecialType == SpecialType.System_Int32
                                || property.Property.IsIndexer && Carrier(property.Property.ContainingType)
                                    && property.Property.Parameters is [{ Type.SpecialType: SpecialType.System_Int32 }])) return true;

                        if (operation.Parent is IInvocationOperation slice && slice.Instance == operation
                            && Carrier(slice.TargetMethod.ContainingType) && Carrier(slice.TargetMethod.ReturnType)
                            && slice.TargetMethod.Name == "Slice" && slice.TargetMethod.Parameters.Length is 1 or 2
                            && slice.TargetMethod.Parameters.All(static parameter => parameter.RefKind == RefKind.None
                                && parameter.Type.SpecialType == SpecialType.System_Int32)) return ReadUse(slice, true);

                        if (operation.Parent is IArgumentOperation argument && argument.Parameter?.RefKind == RefKind.None)
                        {
                            IMethodSymbol? consumer = argument.Parent switch
                            {
                                IInvocationOperation invocation => invocation.TargetMethod,
                                IObjectCreationOperation creation => creation.Constructor,
                                _ => null,
                            };

                            if (consumer is not null && IsExactFloatVectorSignature(consumer)) return true;

                            if (consumer is not null && argument.Parameter.Ordinal == 0
                                && IsExactFrameworkType(consumer.ContainingType, "System.MemoryExtensions", typeof(object).Assembly.GetName())
                                && consumer.Name == "AsSpan" && consumer.IsStatic && consumer.TypeArguments.Length == 1
                                && consumer.Parameters.Length is 1 or 2 or 3
                                && consumer.Parameters[0].Type is IArrayTypeSymbol
                                && consumer.Parameters.Skip(1).All(static parameter => parameter.RefKind == RefKind.None
                                    && parameter.Type.SpecialType == SpecialType.System_Int32)
                                && Carrier(consumer.ReturnType)) return ReadUse(argument.Parent!, true);

                            if (consumer is not null && consumer.IsStatic && consumer.Name == "ReadUInt64BigEndian"
                                && consumer.ReturnType.SpecialType == SpecialType.System_UInt64
                                && consumer.Parameters is [{ RefKind: RefKind.None, Type: INamedTypeSymbol span }]
                                && span.TypeArguments is [{ SpecialType: SpecialType.System_Byte }]
                                && IsExactFrameworkType(span, "System.ReadOnlySpan`1", typeof(object).Assembly.GetName())
                                && IsExactFrameworkType(consumer.ContainingType, "System.Buffers.Binary.BinaryPrimitives", typeof(object).Assembly.GetName())) return true;
                        }

                        // Only exact framework views can transfer to another local. Ordinary
                        // mutable aliases and unproved consumers refuse; no heap model is inferred.
                        if (view && operation.Parent is IVariableInitializerOperation { Parent: IVariableDeclaratorOperation variable }
                            && Carrier(variable.Symbol.Type)) return ClosedCarrierUses(variable.Symbol, owner);

                        return false;
                    }

                    foreach (IdentifierNameSyntax reference in owner.Model.SyntaxTree.GetRoot().DescendantNodes().OfType<IdentifierNameSyntax>()
                        .Where(reference => SymbolEqualityComparer.Default.Equals(owner.Model.GetSymbolInfo(reference).Symbol, storage)))
                    {
                        if (owner.Model.GetOperation(reference) is not { } operation || !ReadUse(operation)) return false;
                    }

                    return true;
                }
                finally
                {
                    carrierUses.Remove(storage);
                }
            }

            bool ExactList(INamedTypeSymbol? type) => type is not null
                && IsExactFrameworkType(type, "System.Collections.Generic.List`1", typeof(List<>).Assembly.GetName());

            bool FrameCardinality(IPropertyReferenceOperation count, AuthoredMember owner)
            {
                if (count.Property.Name != "Count" || count.Property.IsStatic || count.Property.IsIndexer
                    || count.Property.Type.SpecialType != SpecialType.System_Int32 || !ExactList(count.Property.ContainingType)
                    || count.Instance is not IFieldReferenceOperation
                    {
                        Field: { IsStatic: false, IsReadOnly: true, DeclaredAccessibility: Accessibility.Private } field,
                        Instance: IInstanceReferenceOperation { ReferenceKind: InstanceReferenceKind.ContainingTypeInstance },
                    }
                    || !SymbolEqualityComparer.Default.Equals(field.ContainingType, owner.Symbol.ContainingType)
                    || !ExactList(field.Type as INamedTypeSymbol) || HasAuthoredStorageWrite(field)
                    || field.DeclaringSyntaxReferences is not [SyntaxReference declaration]
                    || declaration.GetSyntax() is not VariableDeclaratorSyntax { Initializer.Value: CollectionExpressionSyntax initializer }
                    || initializer.Elements.Any(static element => element is not ExpressionElementSyntax)) return false;

                // Cardinality certifies the exact owned list receiver, not values obtained from
                // its elements. Its source-authored mutations and evaluated inputs still traverse.
                // Complete symbol uses permit only the actual frame Count/index/Add/RemoveAt
                // grammar; aliases, replacement, escaped receivers and opaque consumers refuse.
                foreach (SemanticModel model in semanticModels.Values.Where(model => ReferenceEquals(model.Compilation, owner.Model.Compilation)))
                {
                    foreach (IdentifierNameSyntax reference in model.SyntaxTree.GetRoot().DescendantNodes().OfType<IdentifierNameSyntax>()
                        .Where(reference => SymbolEqualityComparer.Default.Equals(model.GetSymbolInfo(reference).Symbol, field)))
                    {
                        if (proof.RemainingWork-- <= 0 || model.GetOperation(reference) is not IFieldReferenceOperation
                            { Instance: IInstanceReferenceOperation { ReferenceKind: InstanceReferenceKind.ContainingTypeInstance } }) return false;

                        if (reference.Parent is MemberAccessExpressionSyntax access && access.Expression == reference)
                        {
                            ISymbol? selected = model.GetSymbolInfo(access).Symbol;

                            if (selected is IPropertySymbol { Name: "Count", IsStatic: false, Parameters.Length: 0, Type.SpecialType: SpecialType.System_Int32 } property
                                && ExactList(property.ContainingType)) continue;

                            if (selected is IMethodSymbol { IsStatic: false, Arity: 0, ReturnsVoid: true } method
                                && ExactList(method.ContainingType) && access.Parent is InvocationExpressionSyntax call
                                && call.Expression == access
                                && (method.Name == "Add" && method.Parameters is [{ RefKind: RefKind.None }]
                                    || method.Name == "RemoveAt" && HasExactParameterTypes(method, "System.Int32"))) continue;
                        }

                        if (reference.Parent is ElementAccessExpressionSyntax element && element.Expression == reference
                            && model.GetSymbolInfo(element).Symbol is IPropertySymbol { IsIndexer: true, IsStatic: false } indexer
                            && ExactList(indexer.ContainingType) && indexer.Parameters is [{ Type.SpecialType: SpecialType.System_Int32 }]) continue;

                        return false;
                    }
                }

                return true;
            }

            bool ContextualOperatorsAreBuiltin(ExpressionSyntax expression, AuthoredMember owner)
            {
                IOperation? operation = owner.Model.GetOperation(expression);

                while (operation?.Parent is IConversionOperation or IParenthesizedOperation) operation = operation.Parent;

                if (operation is null) return false;

                Stack<IOperation> pending = new();

                pending.Push(operation);

                while (pending.TryPop(out IOperation? current))
                {
                    if (proof.RemainingWork-- <= 0 || current is IConversionOperation { OperatorMethod: not null }
                        or IUnaryOperation { OperatorMethod: not null } or IBinaryOperation { OperatorMethod: not null }) return false;

                    foreach (IOperation child in current.ChildOperations) pending.Push(child);
                }

                return true;
            }

            bool ExactHierarchySequence(IMethodSymbol method)
            {
                IMethodSymbol selected = method.ReducedFrom ?? method;

                if (!selected.IsStatic || selected.Parameters.Any(static parameter => parameter.RefKind != RefKind.None)
                    || !IsExactFrameworkType(selected.ContainingType, "System.Linq.Enumerable", typeof(Enumerable).Assembly.GetName())
                    || selected.Parameters.Length == 0
                    || selected.Parameters[0].Type is not INamedTypeSymbol { TypeArguments: [ITypeSymbol element] } source
                    || !IsExactFrameworkType(source, "System.Collections.Generic.IEnumerable`1", typeof(List<>).Assembly.GetName())) return false;

                if (selected.Name == "ToList") return selected.Arity == 1 && selected.Parameters.Length == 1
                    && selected.ReturnType is INamedTypeSymbol list && ExactList(list)
                    && SymbolEqualityComparer.Default.Equals(list.TypeArguments[0], element);

                return selected.Parameters is [_, { Type: INamedTypeSymbol { TypeArguments: [ITypeSymbol input, ITypeSymbol output] } callback }]
                    && IsExactFrameworkType(callback, "System.Func`2", typeof(object).Assembly.GetName())
                    && SymbolEqualityComparer.Default.Equals(input, element)
                    && (selected.Name == "Sum" && selected.Arity == 1 && output.SpecialType == SpecialType.System_Int32
                            && selected.ReturnType.SpecialType == SpecialType.System_Int32
                        || selected.Name == "Select" && selected.Arity == 2
                            && selected.ReturnType is INamedTypeSymbol { TypeArguments: [ITypeSymbol result] } sequence
                            && IsExactFrameworkType(sequence, "System.Collections.Generic.IEnumerable`1", typeof(List<>).Assembly.GetName())
                            && SymbolEqualityComparer.Default.Equals(output, result));
            }

            bool ClosedBranchListUses(ISymbol storage, AuthoredMember owner)
            {
                if (storage is not ILocalSymbol { RefKind: RefKind.None }
                    and not IParameterSymbol { RefKind: RefKind.None }
                    || HasCollectionValueReplacement(owner, storage)) return false;

                foreach (IdentifierNameSyntax reference in owner.Model.SyntaxTree.GetRoot().DescendantNodes().OfType<IdentifierNameSyntax>()
                    .Where(reference => SymbolEqualityComparer.Default.Equals(owner.Model.GetSymbolInfo(reference).Symbol, storage)))
                {
                    if (proof.RemainingWork-- <= 0 || owner.Model.GetOperation(reference) is not { } use) return false;

                    while (use.Parent is IConversionOperation { OperatorMethod: null } or IParenthesizedOperation) use = use.Parent;

                    if (use.Parent is IPropertyReferenceOperation property && property.Instance == use && ExactList(property.Property.ContainingType))
                    {
                        if (property.Property.Name == "Count" && property.Property.Parameters.IsEmpty
                            && property.Property.Type.SpecialType == SpecialType.System_Int32) continue;

                        if (property.Property.IsIndexer && property.Property.Parameters is [{ RefKind: RefKind.None, Type.SpecialType: SpecialType.System_Int32 }]
                            && property.Parent is not IAssignmentOperation and not IIncrementOrDecrementOperation
                            && property.Parent is not IArgumentOperation { Parameter.RefKind: not RefKind.None }
                            && property.Syntax.Parent is not RefExpressionSyntax
                            && property.Arguments.All(argument => Review(argument.Value, owner))) continue;
                    }

                    if (use.Parent is IInvocationOperation removal && removal.Instance == use
                        && removal.TargetMethod is { Name: "RemoveAt", IsStatic: false, Arity: 0, ReturnsVoid: true } method
                        && ExactList(method.ContainingType) && HasExactParameterTypes(method, "System.Int32")
                        && removal.Arguments.All(argument => Review(argument.Value, owner))) continue;

                    if (use.Parent is IArgumentOperation { Parameter.Ordinal: 0, Parameter.RefKind: RefKind.None, Parent: IInvocationOperation call }
                        && ExactHierarchySequence(call.TargetMethod)) continue;

                    return false;
                }

                return true;
            }

            BoundValueSource[]? BoundHierarchySelector(IInvocationOperation call, AuthoredMember owner, BoundValueSource[] elements)
            {
                if (call.Arguments is not [_, IArgumentOperation selector]
                    || selector.Value.Syntax is not ExpressionSyntax expression
                    || !HasCompleteEagerCallableOrigin(expression, owner.Model, new(SymbolEqualityComparer.Default), owner)
                    || ResolveCallable(expression, owner.Model, owner.CallableBindings, owner.AbsentCallables) is not { Symbol.IsAsync: false } target
                    || target.Symbol.Parameters is not [IParameterSymbol { RefKind: RefKind.None } parameter]) return null;

                ISymbol? storage = owner.Model.GetSymbolInfo(expression).Symbol;

                if (storage is ILocalSymbol or IParameterSymbol && (HasCollectionValueReplacement(owner, storage)
                    || owner.Model.SyntaxTree.GetRoot().DescendantNodes().OfType<RefExpressionSyntax>()
                        .Any(reference => SyntaxReferencesSymbol(owner.Model, reference.Expression, storage)))) return null;

                AuthoredMember captured = BindStableCapturedCleanupContext(owner, expression, target);

                List<BoundValueSource> returns = [];

                foreach (BoundValueSource element in elements)
                {
                    Dictionary<ISymbol, BoundValueSource> bindings = captured.ValueBindings?.ToDictionary(
                        static pair => pair.Key, static pair => pair.Value, SymbolEqualityComparer.Default)
                        ?? new(SymbolEqualityComparer.Default);

                    bindings[parameter] = element;

                    AuthoredMember bound = captured with { ValueBindings = bindings };

                    ExpressionSyntax[] values = ReturnedExpressions(bound.Syntax);

                    if (values.Length == 0) return null;

                    returns.AddRange(values.Select(value => new BoundValueSource(bound, value)));
                }

                return returns.ToArray();
            }

            bool ExactGuidList(ITypeSymbol? type) => type is INamedTypeSymbol { TypeArguments: [ITypeSymbol element] } list
                && ExactList(list) && IsExactFrameworkType(element, "System.Guid", typeof(Guid).Assembly.GetName());

            // A list the helper created empty and may only fill: nothing else can be the list it returns, so it is the framework List<Guid>
            // and not a subclass whose enumerator is authored work that no traversal of the Select would reach.
            bool ExactEmptyGuidList(ExpressionSyntax source, SemanticModel model, HashSet<ISymbol> active, AuthoredMember? caller) => source switch
            {
                CollectionExpressionSyntax { Elements.Count: 0 } => ExactGuidList(model.GetTypeInfo(source).ConvertedType),
                BaseObjectCreationExpressionSyntax { Initializer: null, ArgumentList: null or { Arguments.Count: 0 } } => model.GetOperation(source)
                    is IObjectCreationOperation { Constructor.Parameters.Length: 0 } created && ExactGuidList(created.Type),
                _ => false,
            };

            // The children of one summary are read from storage by an authored helper, so how many there are and which ids they carry is data.
            // The Record argument depends on neither: a cursor is built from an id, no certified getter reads it, and every cursor is the one
            // sealed class. The sequence is therefore taken as an opaque run of System.Guid values, and as nothing else, when the helper is
            // an exact authored static method that returns the framework List<Guid> it created empty itself, its call boundary uses only
            // built-in conversions, and the id reaches the cursor as the System.Guid lambda parameter (StorageGuidElement). The helper, its
            // arguments and the ids are ordinary executable work, traversed where they are written. A helper that cannot be resolved exactly,
            // a list that is not the empty framework list, a list the helper replaces (by assignment, an out or ref argument, a deconstruction
            // or a ref alias; HasCollectionValueReplacement), a boundary conversion and any other element type are all refused.
            bool StorageGuidSequence(ExpressionSyntax expression, AuthoredMember owner)
            {
                // Only parentheses are looked through: a cast is a conversion, and a conversion the helper's list goes through may be authored.
                static ExpressionSyntax Unparenthesized(ExpressionSyntax value)
                {
                    while (value is ParenthesizedExpressionSyntax parenthesized) value = parenthesized.Expression;

                    return value;
                }

                expression = Unparenthesized(expression);

                // The list must reach its use as itself: a user-defined conversion between the helper's result and the place that
                // receives it (a local's declared type, an argument) would be authored work in the sequence that nothing here proves.
                for (IOperation? context = owner.Model.GetOperation(expression)?.Parent; context is IConversionOperation or IParenthesizedOperation; context = context.Parent)
                {
                    if (context is IConversionOperation { OperatorMethod: not null } or IConversionOperation { Conversion.IsUserDefined: true }) return false;
                }

                bool awaited = expression is AwaitExpressionSyntax;

                if (expression is AwaitExpressionSyntax awaiting)
                {
                    expression = Unparenthesized(awaiting.Expression);

                    if (expression is InvocationExpressionSyntax { Expression: MemberAccessExpressionSyntax { Expression: { } pending } } configure
                        && owner.Model.GetOperation(configure) is IInvocationOperation
                        {
                            TargetMethod: { Name: "ConfigureAwait", IsStatic: false, Arity: 0 } configured,
                            Arguments: [{ ArgumentKind: ArgumentKind.Explicit, Value.ConstantValue: { HasValue: true, Value: false } }],
                        }
                        && IsExactFrameworkType(configured.ContainingType, "System.Threading.Tasks.Task`1", typeof(Task<>).Assembly.GetName()))
                    {
                        expression = Unparenthesized(pending);
                    }
                }

                if (expression is not InvocationExpressionSyntax call
                    || owner.Model.GetOperation(call) is not IInvocationOperation { TargetMethod: { IsStatic: true, Arity: 0 } helper } invoked
                    || !invoked.Arguments.All(ArgumentBoundaryUsesOnlyBuiltInConversions)) return false;

                ITypeSymbol returnType = helper.ReturnType;

                if (awaited)
                {
                    if (returnType is not INamedTypeSymbol { TypeArguments: [ITypeSymbol result] } task
                        || !IsExactFrameworkType(task, "System.Threading.Tasks.Task`1", typeof(Task<>).Assembly.GetName())) return false;

                    returnType = result;
                }

                if (!ExactGuidList(returnType)
                    || ResolveCleanupInvocationTarget(helper, owner, call, proof) is not { } target
                    || !SymbolEqualityComparer.Default.Equals(target.Symbol.OriginalDefinition, helper.OriginalDefinition)) return false;

                AuthoredMember bound = BindCleanupInvocationContext(owner, call, target, proof);

                ExpressionSyntax[] returns = ReturnedExpressions(bound.Syntax);

                return returns.Length != 0 && returns.All(returned => StripTransparentExpression(returned) is IdentifierNameSyntax identifier
                    && bound.Model.GetSymbolInfo(identifier).Symbol is ILocalSymbol local && ExactGuidList(local.Type)
                    && HasOnlyReviewedValueSources(identifier, bound.Model, new(SymbolEqualityComparer.Default), bound, ExactEmptyGuidList)
                    && !HasCollectionValueReplacement(bound, local));
            }

            bool StorageGuidElement(IParameterSymbol parameter, BoundValueSource bound) =>
                IsExactFrameworkType(parameter.Type, "System.Guid", typeof(Guid).Assembly.GetName()) && StorageGuidSequence(bound.Expression, bound.Caller);

            HashSet<(SyntaxTree Tree, int Start, int Length)> hierarchyElementPath = [];

            BoundValueSource[]? HierarchyElements(ExpressionSyntax expression, AuthoredMember owner, Func<ISymbol, AuthoredMember, bool>? storageProof = null)
            {
                var identity = (expression.SyntaxTree, expression.SpanStart, expression.Span.Length);

                if (!hierarchyElementPath.Add(identity)) return null;

                try
                {
                    // The ids are opaque, and the cursors a selector builds from them are still enumerated (see StorageGuidSequence). Its own
                    // boundary check stands in for the operator walk below, which would charge the proof for every node of the helper call.
                    if (StorageGuidSequence(expression, owner)) return [new BoundValueSource(owner, expression)];

                    if (!ContextualOperatorsAreBuiltin(expression, owner)) return null;

                    expression = StripTransparentExpression(expression);

                    ISymbol? symbol = owner.Model.GetSymbolInfo(expression).Symbol;

                    if (symbol is ILocalSymbol or IParameterSymbol)
                    {
                        if (!(storageProof?.Invoke(symbol, owner) ?? ClosedBranchListUses(symbol, owner))) return null;

                        List<BoundValueSource> values = [];

                        bool complete = HasOnlyReviewedValueSources(expression, owner.Model, new(SymbolEqualityComparer.Default), owner,
                            (source, _, _, context) =>
                            {
                                if (context is null || HierarchyElements(source, context, storageProof) is not { } elements) return false;

                                values.AddRange(elements);

                                return true;
                            });

                        return complete ? values.ToArray() : null;
                    }

                    if (expression is InvocationExpressionSyntax call && owner.Model.GetOperation(call) is IInvocationOperation invoked)
                    {
                        if (ExactHierarchySequence(invoked.TargetMethod)
                            && invoked.Arguments[0].Value.Syntax is ExpressionSyntax sequence
                            && HierarchyElements(sequence, owner, storageProof) is { } elements)
                        {
                            if (invoked.TargetMethod.Name == "ToList") return elements;

                            if (invoked.TargetMethod.Name == "Select") return BoundHierarchySelector(invoked, owner, elements);
                        }

                        // A returned list does not excuse evaluated inputs, including an
                        // unused argument whose conversion occurred in a local or helper return.
                        if (invoked.Arguments.Any(argument => argument.Parameter?.RefKind != RefKind.None
                                || argument.InConversion.MethodSymbol is not null || argument.OutConversion.MethodSymbol is not null
                                || !HasReviewedValueConversions(argument.Value, owner))
                            || ResolveCleanupInvocationTarget(invoked.TargetMethod, owner, call, proof) is not { } target) return null;

                        AuthoredMember bound = BindCleanupInvocationContext(owner, call, target, proof);

                        ExpressionSyntax[] returns = ReturnedExpressions(bound.Syntax);

                        if (returns.Length == 0) return null;

                        List<BoundValueSource> sources = [];

                        foreach (ExpressionSyntax returned in returns)
                        {
                            if (HierarchyElements(returned, bound, storageProof) is not { } values) return null;

                            sources.AddRange(values);
                        }

                        return sources.ToArray();
                    }

                    // Keep raw elements and their bound context. Cleanup's object identity
                    // reduction is insufficient evidence for contextual element conversions.
                    if (expression is CollectionExpressionSyntax collection && IsExactFrameworkCollectionMaterialization(owner, expression)
                        && collection.Elements.All(static element => element is ExpressionElementSyntax))
                    {
                        return collection.Elements.OfType<ExpressionElementSyntax>()
                            .Select(element => new BoundValueSource(owner, element.Expression)).ToArray();
                    }

                    return null;
                }
                finally { hierarchyElementPath.Remove(identity); }
            }

            bool HierarchySum(IInvocationOperation call, AuthoredMember owner)
            {
                return call.TargetMethod.Name == "Sum" && ExactHierarchySequence(call.TargetMethod)
                    && call.Arguments[0].Value.Syntax is ExpressionSyntax sequence
                    && HierarchyElements(sequence, owner) is { Length: > 0 } elements
                    && BoundHierarchySelector(call, owner, elements) is { Length: > 0 } values
                    && values.All(value => Expression(value.Expression, value.Caller));
            }

            BoundValueSource[]? HierarchyReceiverOrigins(ExpressionSyntax expression, AuthoredMember owner, Func<ISymbol, AuthoredMember, bool>? storageProof = null)
            {
                List<BoundValueSource> sources = [];

                bool Origin(ExpressionSyntax value, SemanticModel model, HashSet<ISymbol> active, AuthoredMember? caller)
                {
                    if (caller is null || proof.RemainingWork-- <= 0) return false;

                    if (!ContextualOperatorsAreBuiltin(value, caller)) return false;

                    value = StripTransparentExpression(value);

                    if (model.GetOperation(value) is IPropertyReferenceOperation { Property.IsIndexer: true } indexed
                        && ExactList(indexed.Property.ContainingType)
                        && indexed.Property.Parameters is [{ RefKind: RefKind.None, Type.SpecialType: SpecialType.System_Int32 }]
                        && indexed.Instance?.Syntax is ExpressionSyntax sequence
                        && indexed.Arguments.All(argument => Review(argument.Value, caller))
                        && HierarchyElements(sequence, caller, storageProof) is { Length: > 0 } elements)
                    {
                        return elements.All(element => Origin(element.Expression, element.Caller.Model, active, element.Caller));
                    }

                    ISymbol? symbol = model.GetSymbolInfo(value).Symbol;

                    if (symbol is ILocalSymbol or IParameterSymbol && storageProof is not null && !storageProof(symbol, caller)) return false;

                    // Keep raw source and compiler conversion context before cleanup reduces
                    // receiver identity. This observation lane does not certify storage getters,
                    // mixed branches, or arbitrary heap aliases by their declared cursor type.
                    if (symbol is IFieldSymbol or IPropertySymbol
                        || symbol is ILocalSymbol { RefKind: not RefKind.None }
                        || symbol is IParameterSymbol { RefKind: not RefKind.None }
                        || symbol is ILocalSymbol or IParameterSymbol && HasCollectionValueReplacement(caller, symbol)) return false;

                    if (value is BaseObjectCreationExpressionSyntax)
                    {
                        sources.Add(new(caller, value));

                        return true;
                    }

                    if (value is InvocationExpressionSyntax call && symbol is IMethodSymbol method
                        && ResolveCleanupInvocationTarget(method, caller, call, proof) is { } target && active.Add(method))
                    {
                        try
                        {
                            if (model.GetOperation(call) is not IInvocationOperation invoked
                                || invoked.Arguments.Any(argument => argument.Parameter?.RefKind != RefKind.None
                                    || argument.InConversion.MethodSymbol is not null || argument.OutConversion.MethodSymbol is not null
                                    || !HasReviewedValueConversions(argument.Value, caller))) return false;

                            AuthoredMember bound = BindCleanupInvocationContext(caller, call, target, proof);

                            ExpressionSyntax[] returns = ReturnedExpressions(bound.Syntax);

                            return returns.Length != 0 && returns.All(returned => Origin(returned, bound.Model, active, bound));
                        }
                        finally { active.Remove(method); }
                    }

                    return HasOnlyReviewedValueSources(value, model, active, caller, Origin);
                }

                return Origin(expression, owner.Model, new(SymbolEqualityComparer.Default), owner) ? sources.ToArray() : null;
            }

            bool HierarchyGetter(IPropertyReferenceOperation access, AuthoredMember owner)
            {
                IPropertySymbol property = access.Property;

                if (property.IsStatic || property.Parameters.Length != 0 || property.SetMethod is not null
                    || property.Type.SpecialType != SpecialType.System_Int32
                    || property.ContainingType is not { IsSealed: true, DeclaredAccessibility: Accessibility.Private or Accessibility.Internal }
                    || property.GetMethod is not { IsVirtual: false } getter
                    || Resolve(getter, owner.Model.Compilation) is not { } target || !path.Add(property)) return false;

                try
                {
                    List<AuthoredMember> getters = [];

                    if (access.Instance is IInstanceReferenceOperation { ReferenceKind: InstanceReferenceKind.ContainingTypeInstance }
                        && SymbolEqualityComparer.Default.Equals(owner.Symbol.ContainingType, property.ContainingType))
                    {
                        getters.Add(BindStableCapturedCleanupContext(owner, (ExpressionSyntax)access.Syntax, target));
                    }
                    else
                    {
                        if (access.Instance?.Syntax is not ExpressionSyntax receiver) return false;

                        ISymbol? storage = owner.Model.GetSymbolInfo(receiver).Symbol;

                        if (storage is ILocalSymbol or IParameterSymbol && HasCollectionValueReplacement(owner, storage)) return false;

                        BoundValueSource[]? sources = HierarchyReceiverOrigins(receiver, owner);

                        if (sources is not { Length: > 0 }) return false;

                        foreach (BoundValueSource source in sources)
                        {
                            if (StripTransparentExpression(source.Expression) is not BaseObjectCreationExpressionSyntax creation
                                || source.Caller.Model.GetOperation(creation) is not IObjectCreationOperation { Constructor: { } constructor, Initializer: null } created
                                || !SameBoundType(constructor.ContainingType, source.Caller.Model.Compilation, property.ContainingType, owner.Model.Compilation)
                                || !created.Arguments.All(argument => HasReviewedValueConversions(argument.Value, source.Caller))
                                || ResolveConstructorContextTarget(constructor, source.Caller.Model.Compilation) is not { } constructorTarget) return false;

                            AuthoredMember constructed = BindConstructedReadonlyFieldContext(BindCleanupConstructorArguments(source.Caller, creation, constructorTarget));

                            getters.Add(MergeValueContext(target, constructed));
                        }
                    }

                    return getters.All(getterContext => GetterValueLeaves(getterContext) is { Length: > 0 } returns
                        && returns.All(returned => Expression(returned, getterContext)));
                }
                finally { path.Remove(property); }
            }

            bool HierarchyScalar(IPropertyReferenceOperation access, AuthoredMember owner)
            {
                IPropertySymbol property = access.Property;

                if (property.IsStatic || property.IsIndexer || property.Type.SpecialType != SpecialType.System_Int32
                    || property.ContainingType is not { IsSealed: true, TypeKind: TypeKind.Class, DeclaredAccessibility: Accessibility.Private, ContainingType: { } domainType } carrier
                    || !SymbolEqualityComparer.Default.Equals(carrier.BaseType, owner.Model.Compilation.GetSpecialType(SpecialType.System_Object))
                    || property.GetMethod is not { IsVirtual: false, IsStatic: false, IsExtern: false, IsAbstract: false }
                    || property.SetMethod is not { IsVirtual: false, IsStatic: false, IsExtern: false, IsAbstract: false, IsInitOnly: false, DeclaredAccessibility: Accessibility.Private }
                    || property.DeclaringSyntaxReferences is not [SyntaxReference declaration]
                    || declaration.GetSyntax() is not PropertyDeclarationSyntax { AccessorList.Accessors: var accessors } syntax
                    || accessors.Count != 2 || accessors.Any(static accessor => accessor.Body is not null
                        || accessor.ExpressionBody is not null || accessor.SemicolonToken.RawKind == 0)
                    || !accessors.Any(static accessor => accessor.IsKind(SyntaxKind.GetAccessorDeclaration))
                    || !accessors.Any(static accessor => accessor.IsKind(SyntaxKind.SetAccessorDeclaration))
                    || !IsAuthoredCleanupSymbol(property, owner.Model.Compilation)
                    || access.Instance?.Syntax is not ExpressionSyntax receiver
                    || !path.Add(property)) return false;

                try
                {
                    for (INamedTypeSymbol? type = carrier; type is not null; type = type.ContainingType)
                    {
                        if (proof.RemainingWork-- <= 0 || type.Arity != 0) return false;
                    }

                    bool Same(ISymbol? symbol) => SymbolEqualityComparer.Default.Equals(symbol, property);

                    bool SameCarrier(ITypeSymbol? type) => SymbolEqualityComparer.Default.Equals(type, carrier);

                    bool Carries(ITypeSymbol? type) => SameCarrier(type) || type is IArrayTypeSymbol array && Carries(array.ElementType)
                        || type is INamedTypeSymbol named && named.TypeArguments.Any(Carries);

                    HashSet<ISymbol> usePath = new(SymbolEqualityComparer.Default);

                    bool ClosedUses(ISymbol storage, AuthoredMember context, bool sequence)
                    {
                        if (storage is not ILocalSymbol { RefKind: RefKind.None } and not IParameterSymbol { RefKind: RefKind.None }
                            || HasCollectionValueReplacement(context, storage) || !usePath.Add(storage)) return false;

                        try
                        {
                            foreach (IdentifierNameSyntax reference in context.Model.SyntaxTree.GetRoot().DescendantNodes().OfType<IdentifierNameSyntax>()
                                .Where(reference => SymbolEqualityComparer.Default.Equals(context.Model.GetSymbolInfo(reference).Symbol, storage)))
                            {
                                // ClosedUse charges this reference operation once, including
                                // any nested result-use checks; do not charge it a second time here.
                                if (!SymbolEqualityComparer.Default.Equals(context.Model.GetEnclosingSymbol(reference.SpanStart)?.OriginalDefinition, storage.ContainingSymbol.OriginalDefinition)
                                    || context.Model.GetOperation(reference) is not { } use || !ClosedUse(use, context, sequence)) return false;
                            }

                            return true;
                        }
                        finally { usePath.Remove(storage); }
                    }

                    bool ClosedUse(IOperation use, AuthoredMember context, bool sequence)
                    {
                        if (proof.RemainingWork-- <= 0) return false;

                        while (use.Parent is IParenthesizedOperation || use.Parent is IConversionOperation { OperatorMethod: null } conversion
                            && (conversion.Conversion.IsIdentity || sequence && conversion.Conversion.IsReference
                                && use.Type is INamedTypeSymbol { TypeArguments: [ITypeSymbol element] } list && ExactList(list)
                                && conversion.Type is INamedTypeSymbol { TypeArguments: [ITypeSymbol selectedElement] } enumerable
                                && SymbolEqualityComparer.Default.Equals(element, selectedElement)
                                && IsExactFrameworkType(enumerable, "System.Collections.Generic.IEnumerable`1", typeof(List<>).Assembly.GetName())
                                && conversion.Parent is IArgumentOperation { Parameter.Ordinal: 0, Parameter.RefKind: RefKind.None, Parent: IInvocationOperation sequenceArgument }
                                && ExactHierarchySequence(sequenceArgument.TargetMethod))) use = use.Parent;

                        if (use.Parent is IVariableInitializerOperation { Parent: IVariableDeclaratorOperation variable })
                            return ClosedUses(variable.Symbol, context, sequence);

                        if (!sequence)
                        {
                            if (use.Parent is IPropertyReferenceOperation selected && selected.Instance == use
                                && SameCarrier(selected.Property.ContainingType) && !selected.Property.IsIndexer
                                && selected.Parent is not IAssignmentOperation and not IIncrementOrDecrementOperation
                                && selected.Property.Type.SpecialType == SpecialType.System_Int32) return true;

                            return use.Parent is IInvocationOperation invoked && invoked.Instance == use
                                && SameCarrier(invoked.TargetMethod.ContainingType) && !invoked.TargetMethod.IsStatic
                                && !Carries(invoked.TargetMethod.ReturnType)
                                && IsAuthoredCleanupSymbol(invoked.TargetMethod, context.Model.Compilation);
                        }

                        if (use.Parent is IPropertyReferenceOperation listProperty && listProperty.Instance == use && ExactList(listProperty.Property.ContainingType))
                        {
                            if (listProperty.Property is { Name: "Count", IsStatic: false, Parameters.Length: 0, Type.SpecialType: SpecialType.System_Int32 }) return true;

                            return listProperty.Property is { IsIndexer: true, IsStatic: false, Parameters: [{ RefKind: RefKind.None, Type.SpecialType: SpecialType.System_Int32 }] }
                                && listProperty.Arguments.All(argument => argument.InConversion.MethodSymbol is null && argument.OutConversion.MethodSymbol is null && Review(argument.Value, context))
                                && ClosedUse(listProperty, context, false);
                        }

                        if (use.Parent is IInvocationOperation removal && removal.Instance == use
                            && removal.TargetMethod is { Name: "RemoveAt", IsStatic: false, Arity: 0, ReturnsVoid: true }
                            && ExactList(removal.TargetMethod.ContainingType) && HasExactParameterTypes(removal.TargetMethod, "System.Int32"))
                            return removal.Arguments.All(argument => argument.InConversion.MethodSymbol is null && argument.OutConversion.MethodSymbol is null && Review(argument.Value, context));

                        if (use.Parent is IArgumentOperation { Parameter.Ordinal: 0, Parameter.RefKind: RefKind.None, Parent: IInvocationOperation sequenceCall }
                            && ExactHierarchySequence(sequenceCall.TargetMethod) && sequenceCall.TargetMethod.Name == "Sum"
                            && sequenceCall.Arguments is [_, { Value.Syntax: ExpressionSyntax selector }]
                            && HasCompleteEagerCallableOrigin(selector, context.Model, new(SymbolEqualityComparer.Default), context)
                            && ResolveCallable(selector, context.Model, context.CallableBindings, context.AbsentCallables) is { Symbol.IsAsync: false, Symbol.Parameters: [IParameterSymbol { RefKind: RefKind.None } parameter] } target)
                            return ClosedUses(parameter, target, false);

                        return false;
                    }

                    bool ScalarStorageUses(ISymbol storage, AuthoredMember context)
                    {
                        ITypeSymbol? type = storage switch { ILocalSymbol local => local.Type, IParameterSymbol parameter => parameter.Type, _ => null };

                        return Carries(type) ? ClosedUses(storage, context, !SameCarrier(type)) : ClosedBranchListUses(storage, context);
                    }

                    // The strict use predicate travels through every already-authenticated raw
                    // receiver/element source. A separate origin traversal would repeat that proof.
                    BoundValueSource[]? receivers = HierarchyReceiverOrigins(receiver, owner, ScalarStorageUses);

                    if (receivers is not { Length: > 0 }) return false;

                    List<AuthoredMember> constructions = [];

                    foreach (BoundValueSource source in receivers)
                    {
                        if (StripTransparentExpression(source.Expression) is not BaseObjectCreationExpressionSyntax creation
                            || source.Caller.Model.GetOperation(creation) is not IObjectCreationOperation { Constructor: { } constructor, Initializer: null } created
                            || !SameCarrier(constructor.ContainingType)
                            || !created.Arguments.All(argument => HasReviewedValueConversions(argument.Value, source.Caller))
                            || ResolveConstructorContextTarget(constructor, source.Caller.Model.Compilation) is not { } target) return false;

                        constructions.Add(BindConstructedReadonlyFieldContext(BindCleanupConstructorArguments(source.Caller, creation, target)));
                    }

                    // Source-domain enumeration follows the private mutable-property precedent,
                    // but retains raw contextual RHS operations and never treats a cycle as proof.
                    List<(SyntaxNode Domain, SemanticModel Model)> domains = [];

                    foreach (SyntaxReference reference in domainType.DeclaringSyntaxReferences)
                    {
                        if (reference.GetSyntax() is not TypeDeclarationSyntax domain
                            || !semanticModels.TryGetValue(domain.SyntaxTree, out SemanticModel? model)
                            || !ReferenceEquals(model.Compilation, owner.Model.Compilation)) return false;

                        domains.Add((domain, model));
                    }

                    if (domains.Count == 0) return false;

                    bool CurrentProperty(IOperation operation) => operation is IPropertyReferenceOperation selected && Same(selected.Property)
                        && selected.Instance is IInstanceReferenceOperation { ReferenceKind: InstanceReferenceKind.ContainingTypeInstance };

                    foreach ((SyntaxNode domain, SemanticModel model) in domains)
                    {
                        foreach (TypeDeclarationSyntax type in domain.DescendantNodesAndSelf().OfType<TypeDeclarationSyntax>()
                            .Where(type => SameCarrier(model.GetDeclaredSymbol(type))))
                        {
                            if (type.Members.OfType<BaseMethodDeclarationSyntax>().Any(static method => method.Modifiers.Any(SyntaxKind.ExternKeyword))) return false;

                            // As in FrameCardinality, enumerate the complete syntax domain but
                            // spend proof work on relevant instance uses, not unrelated SQL nodes.
                            // This includes accessors and nested captures as well as method bodies.
                            foreach (ExpressionSyntax expression in type.DescendantNodes().OfType<ExpressionSyntax>()
                                .Where(expression => SameCarrier(model.GetEnclosingSymbol(expression.SpanStart)?.ContainingType)))
                            {
                                IOperation? selectedOperation = model.GetOperation(expression);

                                bool memberName = expression.Parent is MemberAccessExpressionSyntax memberAccess && memberAccess.Name == expression
                                    || expression.Parent is InvocationExpressionSyntax call && call.Expression == expression;

                                if (selectedOperation is null && !memberName
                                    && (expression is ThisExpressionSyntax || model.GetSymbolInfo(expression).Symbol is { IsStatic: false } unresolved
                                        && SameCarrier(unresolved.ContainingType))) return false;

                                IInstanceReferenceOperation? instance = selectedOperation switch
                                {
                                    IInstanceReferenceOperation current => current,
                                    IFieldReferenceOperation { Instance: IInstanceReferenceOperation current } => current,
                                    IPropertyReferenceOperation { Instance: IInstanceReferenceOperation current } => current,
                                    IInvocationOperation { Instance: IInstanceReferenceOperation current } => current,
                                    IMethodReferenceOperation { Instance: IInstanceReferenceOperation current } => current,
                                    _ => null,
                                };

                                if (instance is not { ReferenceKind: InstanceReferenceKind.ContainingTypeInstance } || !SameCarrier(instance.Type)) continue;

                                if (proof.RemainingWork-- <= 0 || !(instance.Parent is IFieldReferenceOperation field && SameCarrier(field.Field.ContainingType)
                                    || instance.Parent is IPropertyReferenceOperation selected && SameCarrier(selected.Property.ContainingType)
                                    || instance.Parent is IInvocationOperation invoked && invoked.Instance == instance
                                        && SameCarrier(invoked.TargetMethod.ContainingType) && IsAuthoredCleanupSymbol(invoked.TargetMethod, model.Compilation))) return false;

                                for (IOperation? parent = instance.Parent; parent is not null; parent = parent.Parent)
                                    if (parent is IAnonymousFunctionOperation or ILocalFunctionOperation) return false;
                            }
                        }

                        foreach (AssignmentExpressionSyntax assignment in domain.DescendantNodesAndSelf().OfType<AssignmentExpressionSyntax>())
                        {
                            if (!assignment.Left.DescendantNodesAndSelf().OfType<ExpressionSyntax>().Any(left => Same(model.GetSymbolInfo(left).Symbol))) continue;

                            if (!assignment.IsKind(SyntaxKind.SimpleAssignmentExpression) || !Same(model.GetSymbolInfo(assignment.Left).Symbol)
                                || model.GetOperation(assignment.Left) is not { } left || !CurrentProperty(left)
                                || model.GetEnclosingSymbol(assignment.SpanStart) is not IMethodSymbol writer
                                || !SameCarrier(writer.ContainingType) || Resolve(writer, model.Compilation) is not { } target) return false;

                            foreach (AuthoredMember constructed in constructions)
                            {
                                AuthoredMember context = MergeValueContext(ValueExpressionContext(target, assignment.Right, model), constructed);

                                if (model.GetOperation(assignment.Right) is IInvocationOperation max
                                    && max.TargetMethod.Name == "Max" && max.TargetMethod.IsStatic
                                    && max.TargetMethod.ReturnType.SpecialType == SpecialType.System_Int32
                                    && HasExactParameterTypes(max.TargetMethod, "System.Int32", "System.Int32")
                                    && IsExactFrameworkType(max.TargetMethod.ContainingType, "System.Math", typeof(Math).Assembly.GetName())
                                    && max.Arguments is [IArgumentOperation self, IArgumentOperation other] && CurrentProperty(self.Value)
                                    && self.InConversion.IsIdentity && self.OutConversion.IsIdentity
                                    && other.InConversion.MethodSymbol is null && other.OutConversion.MethodSymbol is null)
                                {
                                    if (!Review(other.Value, context)) return false;
                                }
                                else if (!Expression(assignment.Right, context)) return false;
                            }
                        }

                        if (domain.DescendantNodesAndSelf().Any(node => node switch
                            {
                                PrefixUnaryExpressionSyntax prefix when prefix.IsKind(SyntaxKind.PreIncrementExpression) || prefix.IsKind(SyntaxKind.PreDecrementExpression) => Same(model.GetSymbolInfo(prefix.Operand).Symbol),
                                PostfixUnaryExpressionSyntax postfix when postfix.IsKind(SyntaxKind.PostIncrementExpression) || postfix.IsKind(SyntaxKind.PostDecrementExpression) => Same(model.GetSymbolInfo(postfix.Operand).Symbol),
                                _ => false,
                            })) return false;
                    }

                    return syntax.Initializer is null || constructions.All(constructed =>
                        Expression(syntax.Initializer.Value, constructed with { Model = owner.Model.Compilation.GetSemanticModel(syntax.SyntaxTree) }));
                }
                finally { path.Remove(property); }
            }

            bool Expression(ExpressionSyntax expression, AuthoredMember owner)
            {
                IOperation? operation = owner.Model.GetOperation(expression);

                // Syntax-only initializer/return sources omit their compiler-inserted conversion.
                // Retain its contextual operation instead of trusting the final primitive type.
                while (operation?.Parent is IConversionOperation conversion)
                {
                    operation = conversion;
                }

                return operation is not null && Review(operation, owner);
            }

            bool Review(IOperation operation, AuthoredMember owner)
            {
                if (proof.RemainingWork-- <= 0)
                {
                    return false;
                }

                if (operation is IConversionOperation { OperatorMethod: { } conversion }
                    && !(conversion.Name == "op_Implicit"
                        && conversion.IsStatic
                        && IsExactFloatCarrier(conversion.ReturnType, "System.ReadOnlySpan`1")
                        && (IsExactFloatCarrier(conversion.ContainingType, "System.ReadOnlySpan`1")
                            || IsExactFloatCarrier(conversion.ContainingType, "System.Span`1"))
                        && conversion.Parameters is [{ RefKind: RefKind.None, Type: { } source }]
                        && (source is IArrayTypeSymbol { Rank: 1, ElementType.SpecialType: SpecialType.System_Single }
                            || IsExactFloatCarrier(source, "System.Span`1"))))
                {
                    return false;
                }

                // These exact intrinsic profiles do not prove authored or unknown
                // operator bodies. Keep their consuming boundary refused instead.
                if (operation is IUnaryOperation { OperatorMethod: not null }
                    or IBinaryOperation { OperatorMethod: not null }) return false;

                if (operation.ConstantValue.HasValue || operation is IDefaultValueOperation)
                {
                    return true;
                }

                if (operation is ILocalReferenceOperation localReference)
                {
                    ILocalSymbol local = localReference.Local;

                    if (Carrier(local.Type) && !ClosedCarrierUses(local, owner)) return false;

                    if (!path.Add(local)) return false;

                    try
                    {
                        if (local.DeclaringSyntaxReferences is not [SyntaxReference declaration]
                            || declaration.GetSyntax() is not VariableDeclaratorSyntax variable)
                        {
                            return false;
                        }

                        SemanticModel model = semanticModels[variable.SyntaxTree];

                        SyntaxNode root = variable.SyntaxTree.GetRoot();

                        bool Refers(ExpressionSyntax expression) => SymbolEqualityComparer.Default.Equals(model.GetSymbolInfo(expression).Symbol, local);

                        if (root.DescendantNodes().Any(node => node switch
                            {
                                ArgumentSyntax argument when argument.RefKindKeyword.Kind() is SyntaxKind.RefKeyword or SyntaxKind.OutKeyword => Refers(argument.Expression),
                                RefExpressionSyntax reference => SyntaxReferencesSymbol(model, reference.Expression, local),
                                PrefixUnaryExpressionSyntax address when address.IsKind(SyntaxKind.AddressOfExpression) => SyntaxReferencesSymbol(model, address.Operand, local),
                                _ => false,
                            })) return false;

                        AssignmentExpressionSyntax[] assignments = root.DescendantNodes().OfType<AssignmentExpressionSyntax>()
                            .Where(assignment => Refers(assignment.Left)).ToArray();

                        AssignmentExpressionSyntax[] initialWrites = assignments.Where(static assignment =>
                            assignment.IsKind(SyntaxKind.SimpleAssignmentExpression)).ToArray();

                        if (initialWrites.Length + (variable.Initializer is null ? 0 : 1) != 1) return false;

                        AuthoredMember sourceOwner = owner with { Model = model };

                        foreach (AssignmentExpressionSyntax update in assignments.Except(initialWrites))
                        {
                            // Norm's counted loop uses only int32 addition. This proves the
                            // absence of hidden conversions, not arbitrary mutable local purity.
                            if (model.GetOperation(update) is not ICompoundAssignmentOperation
                                {
                                    OperatorKind: BinaryOperatorKind.Add,
                                    OperatorMethod: null,
                                    Type.SpecialType: SpecialType.System_Int32,
                                    Target.Type.SpecialType: SpecialType.System_Int32,
                                    Value.Type.SpecialType: SpecialType.System_Int32,
                                    InConversion.IsIdentity: true,
                                    InConversion.MethodSymbol: null,
                                    OutConversion.IsIdentity: true,
                                    OutConversion.MethodSymbol: null,
                                } compound
                                || !Review(compound.Value, sourceOwner)) return false;
                        }

                        IEnumerable<ExpressionSyntax> changes = root.DescendantNodes().OfType<ExpressionSyntax>().Where(change =>
                            change is PostfixUnaryExpressionSyntax postfix && Refers(postfix.Operand)
                                && (postfix.IsKind(SyntaxKind.PostIncrementExpression) || postfix.IsKind(SyntaxKind.PostDecrementExpression))
                            || change is PrefixUnaryExpressionSyntax prefix && Refers(prefix.Operand)
                                && (prefix.IsKind(SyntaxKind.PreIncrementExpression) || prefix.IsKind(SyntaxKind.PreDecrementExpression)));

                        if (changes.Any(change => model.GetOperation(change) is not IIncrementOrDecrementOperation
                            {
                                OperatorMethod: null,
                                Type.SpecialType: SpecialType.System_Int32,
                                Target.Type.SpecialType: SpecialType.System_Int32,
                            })) return false;

                        ExpressionSyntax localSource = variable.Initializer?.Value ?? initialWrites[0].Right;

                        return Expression(localSource, sourceOwner);
                    }
                    finally
                    {
                        path.Remove(local);
                    }
                }

                if (operation is IParameterReferenceOperation parameter)
                {
                    if (parameter.Parameter.RefKind != RefKind.None
                        || Carrier(parameter.Parameter.Type) && !ClosedCarrierUses(parameter.Parameter, owner)
                        || HasCollectionValueReplacement(owner, parameter.Parameter)
                        || !path.Add(parameter.Parameter)) return false;

                    try
                    {
                        return owner.ValueBindings?.TryGetValue(parameter.Parameter, out BoundValueSource? bound) == true
                            && bound is not null && (StorageGuidElement(parameter.Parameter, bound) || Expression(bound.Expression, bound.Caller));
                    }
                    finally
                    {
                        path.Remove(parameter.Parameter);
                    }
                }

                if (operation is IInvocationOperation invocation && invocation.Syntax is InvocationExpressionSyntax call)
                {
                    if (hierarchyObservation && HierarchySum(invocation, owner)) return true;

                    if (!invocation.ChildOperations.All(child => Review(child, owner))) return false;

                    if (ResolveCleanupInvocationTarget(invocation.TargetMethod, owner, call, proof) is { } target)
                    {
                        if (!path.Add(invocation.TargetMethod)) return false;

                        try
                        {
                            AuthoredMember bound = BindCleanupInvocationContext(owner, call, target, proof);

                            ExpressionSyntax[] returns = ReturnedExpressions(bound.Syntax);

                            return returns.Length != 0 && returns.All(expression => Expression(expression, bound));
                        }
                        finally
                        {
                            path.Remove(invocation.TargetMethod);
                        }
                    }

                    return FrameworkAssemblyIdentityMatches(invocation.TargetMethod.ContainingAssembly.Identity, typeof(object).Assembly.GetName())
                        && ReviewedIntrinsicExternalTypes.Contains(TypeKey(invocation.TargetMethod.ContainingType));
                }

                if (operation is IFieldReferenceOperation or IPropertyReferenceOperation)
                {
                    ISymbol symbol = operation is IFieldReferenceOperation field ? field.Field : ((IPropertyReferenceOperation)operation).Property;

                    // Only the owned Histogram consumption may compose the bounded hierarchy
                    // cardinality/getter certificate. Numeric/queue/general cleanup rules stay strict.
                    if (hierarchyObservation && operation is IPropertyReferenceOperation hierarchyProperty
                        && (FrameCardinality(hierarchyProperty, owner) || HierarchyGetter(hierarchyProperty, owner) || HierarchyScalar(hierarchyProperty, owner))) return true;

                    // Count uses the already-closed exact default queue certificate. Its
                    // receiver/helper/getter evaluations still traverse as ordinary authored work.
                    if (symbol is IPropertySymbol { Name: "Count", Type.SpecialType: SpecialType.System_Int32 } count
                        && IsReviewedPrimitiveQueueProperty(count, mutation: false, operation.Syntax, owner)) return true;

                    // Mutable carrier storage behind a field/property has no closed local
                    // use proof here. Do not infer its contents from its declared type.
                    if (Carrier(operation.Type)) return false;

                    if (FrameworkAssemblyIdentityMatches(symbol.ContainingAssembly.Identity, typeof(object).Assembly.GetName())
                            && ReviewedIntrinsicExternalTypes.Contains(TypeKey(symbol.ContainingType))
                        || symbol is IPropertySymbol property && IsReviewedFloatVectorProperty(property))
                    {
                        return operation.ChildOperations.All(child => Review(child, owner));
                    }

                    if (operation.Syntax is not ExpressionSyntax expression || !path.Add(symbol)) return false;

                    try
                    {
                        CleanupValueFlow flow = CleanupValueFlowOf(owner, expression, proof);

                        return flow.Complete && flow.Values.Count != 0 && flow.Values.All(source =>
                            source.Expression != expression && Expression(source.Expression, source.Caller));
                    }
                    finally
                    {
                        path.Remove(symbol);
                    }
                }

                return operation.ChildOperations.All(child => Review(child, owner));
            }

            return Review(value, member);
        }

        private static bool IsReviewedRuntimeCleanup(IMethodSymbol method)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            return TypeKey(definition.ContainingType)
                    == "System.Threading.Lock.Scope"
                && definition.Name == "Dispose"
                && definition.Parameters.Length == 0
                && TypeKey(definition.ReturnType) == "System.Void"
                && FrameworkAssemblyIdentityMatches(
                    definition.ContainingAssembly.Identity,
                    typeof(System.Threading.Lock).Assembly.GetName());
        }

        private static bool IsReviewedInterpolatedStringCreate(
            IMethodSymbol method)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            return definition.IsStatic
                && definition.Name == "Create"
                && TypeKey(definition.ContainingType) == "System.String"
                && definition.ReturnType.SpecialType == SpecialType.System_String
                && definition.Parameters is
                [
                    IParameterSymbol
                {
                    RefKind: RefKind.None,
                    Type: { } provider,
                },
                    IParameterSymbol
                {
                    RefKind: RefKind.Ref,
                    Type: { } handler,
                },
                ]
                && TypeKey(provider) == "System.IFormatProvider"
                && TypeKey(handler)
                    == "System.Runtime.CompilerServices.DefaultInterpolatedStringHandler";
        }

        private bool IsReviewedSequenceOperation(
            IMethodSymbol method,
            SyntaxNode? node,
            SemanticModel? model)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            string type = TypeKey(definition.ContainingType);

            if (!(type == "System.Linq.Enumerable"
                    && definition.Name is "Any" or "Contains" or "Count" or "First" or "FirstOrDefault" or "Last" or "SequenceEqual" or "Single" or "Sum" or "ToHashSet"
                || type == "System.Linq.ImmutableArrayExtensions"
                    && definition.Name is "FirstOrDefault" or "SequenceEqual"))
            {
                return false;
            }

            return !definition.Parameters.Any(static parameter =>
                    parameter.RefKind != RefKind.None
                    || parameter.Type.TypeKind == TypeKind.Delegate)
                && HasOnlyReviewedComparerArguments(
                    method,
                    node,
                    model);
        }

        private bool IsReviewedInMemoryOrderingOperation(
            IMethodSymbol method,
            SyntaxNode? node,
            SemanticModel? model)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            string type = TypeKey(definition.ContainingType);

            if (!(type == "System.Array"
                    && definition.Name == "Sort"
                || type == "System.Collections.Generic.List`1"
                    && definition.Name == "Sort"))
            {
                return false;
            }

            return !definition.Parameters.Any(static parameter =>
                    parameter.RefKind != RefKind.None
                    || parameter.Type.TypeKind == TypeKind.Delegate)
                && HasOnlyReviewedComparerArguments(
                    method,
                    node,
                    model);
        }

        private bool IsReviewedEnumeratorMethod(
            IMethodSymbol method,
            SyntaxNode? node,
            SemanticModel? model,
            AuthoredMember? context = null)
        {
            if (node is not InvocationExpressionSyntax call
                || model is null
                || model.GetOperation(call) is not IInvocationOperation
                {
                    Instance.Syntax: ExpressionSyntax receiver,
                })
            {
                return false;
            }

            string type = TypeKey(method.ContainingType);

            if (method.Name == "GetEnumerator"
                && type is "System.Collections.Generic.IEnumerable`1"
                    or "System.Collections.IEnumerable"
                || method.Name == "GetAsyncEnumerator"
                    && type == "System.Collections.Generic.IAsyncEnumerable`1")
            {
                return HasReviewedSequenceProvenance(
                    receiver,
                    model,
                    new HashSet<ISymbol>(SymbolEqualityComparer.Default),
                    context);
            }

            if (method.Name is "MoveNext" or "MoveNextAsync"
                && type is "System.Collections.Generic.IEnumerator`1"
                    or "System.Collections.IEnumerator"
                    or "System.Collections.Generic.IAsyncEnumerator`1")
            {
                return HasReviewedEnumeratorProvenance(
                    receiver,
                    model,
                    new HashSet<ISymbol>(SymbolEqualityComparer.Default),
                    context);
            }

            return false;
        }

        private bool IsReviewedInMemoryStreamReaderMember(
            IMethodSymbol method,
            SyntaxNode? node,
            SemanticModel? model,
            AuthoredMember? context = null)
        {
            if (TypeKey(method.ContainingType) != "System.IO.StreamReader"
                || model is null)
            {
                return false;
            }

            if (method.Name == ".ctor"
                && node is BaseObjectCreationExpressionSyntax creation
                && model.GetOperation(creation) is IObjectCreationOperation operation)
            {
                IArgumentOperation? streamArgument = operation.Arguments
                    .SingleOrDefault(static argument =>
                        argument.Parameter?.Ordinal == 0
                        && TypeKey(argument.Parameter.Type)
                            == "System.IO.Stream");

                ExpressionSyntax? stream = streamArgument?.Syntax switch
                {
                    ArgumentSyntax argument => argument.Expression,
                    ExpressionSyntax expression => expression,
                    _ => streamArgument?.Value.Syntax as ExpressionSyntax,
                };

                return stream is not null
                    && HasReviewedInMemoryStreamProvenance(
                        stream,
                        model,
                        new HashSet<ISymbol>(
                            SymbolEqualityComparer.Default),
                        context);
            }

            if (!method.Name.StartsWith("Read", StringComparison.Ordinal)
                || node is not InvocationExpressionSyntax call
                || model.GetOperation(call) is not IInvocationOperation
                {
                    Instance.Syntax: ExpressionSyntax receiver,
                })
            {
                return false;
            }

            return HasReviewedInMemoryStreamReaderProvenance(
                receiver,
                model,
                new HashSet<ISymbol>(SymbolEqualityComparer.Default),
                context);
        }

        private bool HasReviewedInMemoryStreamReaderProvenance(
            ExpressionSyntax expression,
            SemanticModel model,
            HashSet<ISymbol> path,
            AuthoredMember? context)
        {
            expression = StripTransparentExpression(expression);

            if (expression is BaseObjectCreationExpressionSyntax creation
                && model.GetTypeInfo(creation).Type is { } createdType
                && TypeKey(createdType) == "System.IO.StreamReader"
                && creation.ArgumentList?.Arguments.FirstOrDefault()?.Expression
                    is { } stream)
            {
                return HasReviewedInMemoryStreamProvenance(
                    stream,
                    model,
                    path,
                    context);
            }

            return HasOnlyReviewedValueSources(
                expression,
                model,
                path,
                context,
                HasReviewedInMemoryStreamReaderProvenance);
        }

        private bool HasExactNonOwningStreamReaderProvenance(
            ExpressionSyntax expression,
            SemanticModel model,
            HashSet<ISymbol> path,
            AuthoredMember? context)
        {
            expression = StripTransparentExpression(expression);

            if (expression is BaseObjectCreationExpressionSyntax creation
                && model.GetOperation(creation) is IObjectCreationOperation
                {
                    Constructor: { } constructor,
                } operation
                && TypeKey(constructor.ContainingType)
                    == "System.IO.StreamReader"
                && !constructor.ContainingType.Locations.Any(
                    static location => location.IsInSource)
                && FrameworkAssemblyIdentityMatches(
                    constructor.ContainingAssembly.Identity,
                    typeof(System.IO.StreamReader).Assembly.GetName())
                && operation.Arguments.SingleOrDefault(static argument =>
                    argument.Parameter?.Name == "leaveOpen") is
                {
                    Value.ConstantValue:
                    {
                        HasValue: true,
                        Value: true,
                    },
                })
            {
                return true;
            }

            return HasOnlyReviewedValueSources(
                expression,
                model,
                path,
                context,
                HasExactNonOwningStreamReaderProvenance);
        }

        private bool HasReviewedInMemoryStreamProvenance(
            ExpressionSyntax expression,
            SemanticModel model,
            HashSet<ISymbol> path,
            AuthoredMember? context)
        {
            expression = StripTransparentExpression(expression);

            if (expression is BaseObjectCreationExpressionSyntax creation
                && model.GetTypeInfo(creation).Type is { } createdType
                && TypeKey(createdType) == "System.IO.MemoryStream")
            {
                return true;
            }

            if (expression is InvocationExpressionSyntax call
                && model.GetSymbolInfo(call).Symbol is IMethodSymbol method
                && IsExactManifestResourceStreamFactory(method))
            {
                return true;
            }

            return HasOnlyReviewedValueSources(
                expression,
                model,
                path,
                context,
                HasReviewedInMemoryStreamProvenance);
        }

        private bool HasExactReadOnlyFileStreamProvenance(
            ExpressionSyntax expression,
            SemanticModel model,
            HashSet<ISymbol> path,
            AuthoredMember? context)
        {
            expression = StripTransparentExpression(expression);

            ISymbol? symbol = model.GetSymbolInfo(expression).Symbol;

            if (symbol is not null
                && context?.ValueBindings?.TryGetValue(
                    symbol,
                    out BoundValueSource? bound) == true
                && bound is not null)
            {
                if (!path.Add(symbol))
                {
                    return false;
                }

                try
                {
                    return HasExactReadOnlyFileStreamProvenance(
                        bound.Expression,
                        bound.Caller.Model,
                        path,
                        bound.Caller);
                }
                finally
                {
                    path.Remove(symbol);
                }
            }

            if (expression is BaseObjectCreationExpressionSyntax creation
                && model.GetOperation(creation) is IObjectCreationOperation
                {
                    Constructor: { } constructor,
                } operation
                && TypeKey(constructor.ContainingType)
                    == "System.IO.FileStream"
                && !constructor.ContainingType.Locations.Any(
                    static location => location.IsInSource)
                && FrameworkAssemblyIdentityMatches(
                    constructor.ContainingAssembly.Identity,
                    typeof(FileStream).Assembly.GetName())
                && IsExactReadOnlyFileStreamArguments(operation.Arguments, model))
            {
                return true;
            }

            if (expression is InvocationExpressionSyntax call
                && model.GetSymbolInfo(call).Symbol is IMethodSymbol method
                && Normalize(method) == "System.IO.File.OpenRead"
                && HasExactParameterTypes(method, "System.String")
                && FrameworkAssemblyIdentityMatches(
                    method.ContainingAssembly.Identity,
                    typeof(File).Assembly.GetName())
                && !method.Locations.Any(static location => location.IsInSource))
            {
                return true;
            }

            return HasOnlyReviewedValueSources(
                expression,
                model,
                path,
                context,
                HasExactReadOnlyFileStreamProvenance);
        }

        private bool HasExactReadOnlyFileStreamCleanupProvenance(
            AuthoredMember member,
            ExpressionSyntax resource)
        {
            if (HasExactReadOnlyFileStreamProvenance(
                    resource,
                    member.Model,
                    new HashSet<ISymbol>(SymbolEqualityComparer.Default),
                    member))
            {
                return true;
            }

            CleanupValueFlow flow = CleanupValueFlowOf(
                member,
                resource,
                new CleanupProvenanceContext());

            if (!flow.Complete)
            {
                return false;
            }

            BoundValueSource[] fileStreams = flow.Values
                .Where(static value =>
                    value.Caller.Model.GetTypeInfo(
                        ExactNonThrowingValue(value.Expression)).Type is
                    { } sourceType
                    && TypeKey(sourceType) == "System.IO.FileStream")
                .ToArray();

            return fileStreams.Length != 0
                && fileStreams.All(value =>
                    HasExactReadOnlyFileStreamProvenance(
                        ExactNonThrowingValue(value.Expression),
                        value.Caller.Model,
                        new HashSet<ISymbol>(SymbolEqualityComparer.Default),
                        value.Caller));
        }

        private static bool IsExactReadOnlyFileStreamArguments(
            IEnumerable<IArgumentOperation> arguments,
            SemanticModel model)
        {
            IArgumentOperation[] values = arguments.ToArray();

            IArgumentOperation? fileOptions = values.SingleOrDefault(
                static argument =>
                    argument.Parameter?.Name == "options"
                    && TypeKey(argument.Parameter.Type)
                        == "System.IO.FileOptions");

            if (fileOptions is not null
                && (fileOptions.Value.ConstantValue is not
                {
                    HasValue: true,
                    Value: int argumentFlags,
                }
                    || (argumentFlags & (int)FileOptions.DeleteOnClose) != 0))
            {
                return false;
            }

            bool open = values.Any(static argument =>
                argument.Parameter?.Name == "mode"
                && argument.Value.ConstantValue is
                {
                    HasValue: true,
                    Value: int mode,
                }
                && mode == (int)FileMode.Open);

            bool read = values.Any(static argument =>
                argument.Parameter?.Name == "access"
                && argument.Value.ConstantValue is
                {
                    HasValue: true,
                    Value: int access,
                }
                && access == (int)FileAccess.Read);

            if (open && read)
            {
                return true;
            }

            ExpressionSyntax? options = values
                .SingleOrDefault(static argument =>
                    argument.Parameter?.Name == "options")
                ?.Value.Syntax as ExpressionSyntax;

            if (options is not BaseObjectCreationExpressionSyntax
                {
                    Initializer: { } initializer,
                })
            {
                return false;
            }

            AssignmentExpressionSyntax[] optionAssignments = initializer
                .Expressions
                .OfType<AssignmentExpressionSyntax>()
                .Where(assignment =>
                    model.GetSymbolInfo(assignment.Left).Symbol is
                        IPropertySymbol property
                    && TypeKey(property.ContainingType)
                        == "System.IO.FileStreamOptions"
                    && property.Name == "Options")
                .ToArray();

            if (optionAssignments.Length > 1
                || optionAssignments is
                    [AssignmentExpressionSyntax optionAssignment]
                && (model.GetConstantValue(optionAssignment.Right) is not
                {
                    HasValue: true,
                    Value: int initializerFlags,
                }
                    || (initializerFlags & (int)FileOptions.DeleteOnClose) != 0))
            {
                return false;
            }

            bool OptionsSet(string propertyName, int expected) =>
                initializer.Expressions
                    .OfType<AssignmentExpressionSyntax>()
                    .Any(assignment =>
                        model.GetSymbolInfo(assignment.Left).Symbol is
                            IPropertySymbol property
                        && TypeKey(property.ContainingType)
                            == "System.IO.FileStreamOptions"
                        && property.Name == propertyName
                        && model.GetConstantValue(assignment.Right) is
                        {
                            HasValue: true,
                            Value: int actual,
                        }
                        && actual == expected);

            return OptionsSet("Mode", (int)FileMode.Open)
                && OptionsSet("Access", (int)FileAccess.Read);
        }

        private bool IsReviewedEnumeratorProperty(
            IPropertySymbol property,
            bool mutation,
            SyntaxNode? node,
            SemanticModel? model,
            AuthoredMember? context = null)
        {
            if (mutation
                || property.Name != "Current"
                || TypeKey(property.ContainingType) is not
                    ("System.Collections.Generic.IEnumerator`1"
                        or "System.Collections.IEnumerator"
                        or "System.Collections.Generic.IAsyncEnumerator`1")
                || node is not MemberAccessExpressionSyntax access
                || model is null)
            {
                return false;
            }

            return HasReviewedEnumeratorProvenance(
                access.Expression,
                model,
                new HashSet<ISymbol>(SymbolEqualityComparer.Default),
                context);
        }

        private bool IsReviewedFrameworkCollectionIndexer(
            IPropertySymbol property,
            bool mutation,
            SyntaxNode? node,
            SemanticModel? model,
            AuthoredMember? context)
        {
            if (!property.IsIndexer
                || property.Parameters is not [IParameterSymbol parameter]
                || node is not ElementAccessExpressionSyntax access
                || model is null
                || property.Locations.Any(static location => location.IsInSource))
            {
                return false;
            }

            string type = TypeKey(property.ContainingType);

            bool exactGetter = !mutation
                && property.GetMethod is not null
                && property.SetMethod is null;

            bool exactSetter = mutation
                && property.SetMethod is not null;

            bool exactFrameworkProperty = type switch
            {
                "System.Collections.Generic.IReadOnlyList`1" =>
                    exactGetter
                    && parameter.Type.SpecialType == SpecialType.System_Int32
                    && FrameworkAssemblyIdentityMatches(
                        property.ContainingAssembly.Identity,
                        typeof(IReadOnlyList<>).Assembly.GetName()),
                "System.Text.RegularExpressions.GroupCollection" =>
                    exactGetter
                    && parameter.Type.SpecialType is
                        SpecialType.System_Int32 or SpecialType.System_String
                    && FrameworkAssemblyIdentityMatches(
                        property.ContainingAssembly.Identity,
                        typeof(System.Text.RegularExpressions.GroupCollection)
                            .Assembly.GetName()),
                "System.Collections.IDictionary" =>
                    exactSetter
                    && parameter.Type.SpecialType == SpecialType.System_Object
                    && FrameworkAssemblyIdentityMatches(
                        property.ContainingAssembly.Identity,
                        typeof(System.Collections.IDictionary).Assembly.GetName()),
                _ => false,
            };

            if (!exactFrameworkProperty)
            {
                return false;
            }

            if (type == "System.Text.RegularExpressions.GroupCollection")
            {
                return true;
            }

            // Authored Enumerables Absent: no authored type implements the read-only list contract, so a value of that
            // interface is a framework list and its indexer a framework member, whatever produced the value.
            if (type == "System.Collections.Generic.IReadOnlyList`1"
                && AuthoredEnumerablesAbsentByUse
                && IsPremiseCoveredEnumerationInterface(property.ContainingType))
            {
                return true;
            }

            return HasReviewedFrameworkCollectionIndexerReceiver(
                access.Expression,
                model,
                new HashSet<ISymbol>(SymbolEqualityComparer.Default),
                context,
                type);
        }

        private bool HasReviewedFrameworkCollectionIndexerReceiver(
            ExpressionSyntax expression,
            SemanticModel model,
            HashSet<ISymbol> path,
            AuthoredMember? context,
            string contract)
        {
            if (context is null)
            {
                return false;
            }

            CleanupProvenanceContext provenance = new()
            {
                CollectionIndexerProof = true,
            };

            if (HasReviewedFrameworkCollectionIndexerValue(context, expression, provenance, contract))
            {
                return true;
            }

            if (IsLifecycle(context.Symbol)
                && context.ValueBindings is not { Count: > 0 }
                && diActivationRegistrations.TryGetValue(
                    new(context.Symbol.ContainingAssembly.Identity, TypeKey(context.Symbol.ContainingType)),
                    out List<ResolvedRegistration>? registrations))
            {
                foreach (ResolvedRegistration registration in registrations)
                {
                    if (registration.Call.ArgumentList.Arguments is not [ArgumentSyntax { Expression: AnonymousFunctionExpressionSyntax factory }]
                        || ExactFactoryCreation(factory) is not BaseObjectCreationExpressionSyntax creation
                        || registration.Model.GetSymbolInfo(creation).Symbol is not IMethodSymbol constructor
                        || !SameBoundType(constructor.ContainingType, registration.Model.Compilation,
                            context.Symbol.ContainingType, context.Model.Compilation)
                        || constructor.Parameters.FirstOrDefault() is not { } parameter
                        || !TryDiActivationFor(registration.Call, registration.Method, registration.Model,
                            constructor, parameter, parameter.Type, context.Model.Compilation, out _)
                        || ResolveCallable(factory, registration.Model, null, null) is not { } caller
                        || ResolveConstructorContextTarget(constructor, registration.Model.Compilation) is not { } target)
                    {
                        return false;
                    }

                    AuthoredMember constructed = BindConstructedReadonlyFieldContext(
                        BindCleanupConstructorArguments(caller, creation, target));

                    if (!HasReviewedFrameworkCollectionIndexerValue(
                        MergeValueContext(context, constructed), expression, provenance, contract))
                    {
                        return false;
                    }
                }

                return registrations.Count != 0;
            }

            return false;
        }

        private bool HasReviewedFrameworkCollectionIndexerValue(
            AuthoredMember member,
            ExpressionSyntax expression,
            CleanupProvenanceContext provenance,
            string contract)
        {
            CleanupValueFlow flow = CleanupValueFlowOf(member, expression, provenance);

            return flow.Complete
                && flow.Values.Count != 0
                && flow.Values.All(source => IsReviewedFrameworkCollectionTerminal(
                    source.Caller,
                    source.Expression,
                    provenance,
                    contract));
        }

        private bool IsReviewedFrameworkCollectionTerminal(
            AuthoredMember member,
            ExpressionSyntax expression,
            CleanupProvenanceContext provenance,
            string contract)
        {
            SemanticModel model = member.Model;

            expression = StripTransparentExpression(expression);

            ITypeSymbol? type = model.GetTypeInfo(expression).Type;

            if (contract == "System.Collections.Generic.IReadOnlyList`1"
                && type is IArrayTypeSymbol)
            {
                return true;
            }

            if (contract == "System.Collections.Generic.IReadOnlyList`1"
                && IsExactFrameworkCollectionMaterialization(member, expression))
            {
                return true;
            }

            if (type is INamedTypeSymbol readOnlyCollection
                && TypeKey(readOnlyCollection)
                    == "System.Collections.ObjectModel.ReadOnlyCollection`1"
                && !readOnlyCollection.Locations.Any(
                    static location => location.IsInSource)
                && FrameworkAssemblyIdentityMatches(
                    readOnlyCollection.ContainingAssembly.Identity,
                    typeof(System.Collections.ObjectModel.ReadOnlyCollection<>).Assembly
                        .GetName())
                && expression is BaseObjectCreationExpressionSyntax creation
                && model.GetOperation(creation) is IObjectCreationOperation operation
                && operation.Arguments.SingleOrDefault(static argument =>
                    argument.Parameter?.Ordinal == 0) is { } backingArgument
                && (backingArgument.Syntax switch
                {
                    ArgumentSyntax argument => argument.Expression,
                    ExpressionSyntax argument => argument,
                    _ => backingArgument.Value.Syntax as ExpressionSyntax,
                }) is { } backing)
            {
                return HasReviewedFrameworkCollectionIndexerValue(
                    member,
                    backing,
                    provenance,
                    contract);
            }

            if (type is INamedTypeSymbol named
                && TypeKey(named) is
                    "System.Collections.Generic.List`1"
                        or "System.Collections.Immutable.ImmutableArray`1"
                        or "System.Collections.Hashtable"
                && !named.Locations.Any(static location => location.IsInSource)
                && FrameworkAssemblyIdentityMatches(
                    named.ContainingAssembly.Identity,
                    contract == "System.Collections.IDictionary"
                        ? typeof(System.Collections.Hashtable).Assembly.GetName()
                        : TypeKey(named)
                            == "System.Collections.Immutable.ImmutableArray`1"
                                ? typeof(System.Collections.Immutable.ImmutableArray<>).Assembly
                                    .GetName()
                                : typeof(List<>).Assembly.GetName())
                && (named.IsValueType
                    || named.IsSealed
                    || expression is BaseObjectCreationExpressionSyntax))
            {
                return true;
            }

            return false;
        }

        private static bool IsExactFrameworkCollectionMaterialization(
            AuthoredMember member,
            ExpressionSyntax expression)
        {
            if (expression is CollectionExpressionSyntax
                && member.Model.GetTypeInfo(expression).ConvertedType is { } converted)
            {
                return converted is IArrayTypeSymbol
                    || converted is INamedTypeSymbol named
                        && TypeKey(named) is "System.Collections.Generic.List`1"
                            or "System.Collections.Generic.IReadOnlyList`1"
                            or "System.Collections.Generic.IList`1"
                            or "System.Collections.Generic.IEnumerable`1"
                        && IsExactFrameworkType(named, TypeKey(named), typeof(List<>).Assembly.GetName());
            }

            return expression is InvocationExpressionSyntax call
                && member.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method
                && (method.ReducedFrom ?? method) is
                {
                    IsStatic: true,
                    Arity: 1,
                    Parameters: [IParameterSymbol parameter],
                    Name: "ToList" or "ToArray",
                } materializer
                && TypeKey(parameter.Type) == "System.Collections.Generic.IEnumerable`1"
                && IsExactFrameworkType(materializer.ContainingType,
                    "System.Linq.Enumerable", typeof(Enumerable).Assembly.GetName());
        }

        private bool HasReviewedEnumeratorProvenance(
            ExpressionSyntax expression,
            SemanticModel model,
            HashSet<ISymbol> path,
            AuthoredMember? context)
        {
            expression = StripTransparentExpression(expression);

            if (expression is InvocationExpressionSyntax factory
                && model.GetSymbolInfo(factory).Symbol is IMethodSymbol method
                && method.Name is "GetEnumerator" or "GetAsyncEnumerator"
                && model.GetOperation(factory) is IInvocationOperation
                {
                    Instance.Syntax: ExpressionSyntax sequence,
                })
            {
                return HasReviewedSequenceProvenance(
                    sequence,
                    model,
                    path,
                    context);
            }

            return HasOnlyReviewedValueSources(
                expression,
                model,
                path,
                context,
                HasReviewedEnumeratorProvenance);
        }

        private bool HasReviewedSequenceProvenance(
            ExpressionSyntax expression,
            SemanticModel model,
            HashSet<ISymbol> path,
            AuthoredMember? context)
        {
            expression = StripTransparentExpression(expression);

            ITypeSymbol? expressionType = model.GetTypeInfo(expression).Type;

            if (HasReviewedPrimitiveQueueItems(expression, model, context)) return true;

            if (expressionType is IArrayTypeSymbol
                || expressionType is not null
                    && ReviewedInMemoryEnumerableTypes.Contains(
                        TypeKey(expressionType)))
            {
                return true;
            }

            if (expression is InvocationExpressionSyntax call
                && model.GetSymbolInfo(call).Symbol is IMethodSymbol method)
            {
                string callee = Normalize(method);

                if (Vocabulary.ContainsKey(callee)
                    || IsExactIntegerRange(method)
                    || Resolve(method, model.Compilation) is not null
                    || callee is
                        "System.Text.Json.JsonElement.EnumerateArray"
                            or "System.Text.Json.JsonElement.EnumerateObject"
                            or "System.Threading.Channels.ChannelReader`1.ReadAllAsync")
                {
                    return true;
                }

                if (IsKnownLazyCallback(method)
                    && call.ArgumentList.Arguments.FirstOrDefault()?.Expression
                        is { } source)
                {
                    return HasReviewedSequenceProvenance(
                        source,
                        model,
                        path,
                        context);
                }
            }

            return HasOnlyReviewedValueSources(
                expression,
                model,
                path,
                context,
                HasReviewedSequenceProvenance);
        }

        private bool HasOnlyReviewedValueSources(
            ExpressionSyntax expression,
            SemanticModel model,
            HashSet<ISymbol> path,
            AuthoredMember? context,
            Func<ExpressionSyntax, SemanticModel, HashSet<ISymbol>, AuthoredMember?, bool>
                review)
        {
            ISymbol? symbol = model.GetSymbolInfo(expression).Symbol;

            if (symbol is IParameterSymbol
                && context?.ValueBindings?.TryGetValue(
                    symbol,
                    out BoundValueSource? bound) == true
                && bound is not null)
            {
                if (!path.Add(symbol))
                {
                    return false;
                }

                try
                {
                    return review(
                        bound.Expression,
                        bound.Caller.Model,
                        path,
                        bound.Caller);
                }
                finally
                {
                    path.Remove(symbol);
                }
            }

            if (symbol is not ILocalSymbol
                and not IFieldSymbol
                and not IPropertySymbol
                || !path.Add(symbol))
            {
                return false;
            }

            try
            {
                if (symbol is IFieldSymbol { IsReadOnly: false }
                    || symbol is IPropertySymbol { SetMethod: not null }
                    || (symbol is IFieldSymbol or IPropertySymbol
                        && HasAuthoredStorageWrite(symbol)))
                {
                    return false;
                }

                ExpressionSyntax[] sources = symbol.DeclaringSyntaxReferences
                    .Select(reference => reference.GetSyntax())
                    .Select(static syntax => syntax switch
                    {
                        VariableDeclaratorSyntax variable =>
                            variable.Initializer?.Value,
                        PropertyDeclarationSyntax property =>
                            property.Initializer?.Value
                                ?? property.ExpressionBody?.Expression,
                        _ => null,
                    })
                    .OfType<ExpressionSyntax>()
                    .ToArray();

                if (symbol is ILocalSymbol local)
                {
                    sources = sources
                        .Where(static source => source is not LiteralExpressionSyntax literal
                                || !literal.IsKind(SyntaxKind.NullLiteralExpression)
                            && !literal.IsKind(SyntaxKind.DefaultLiteralExpression))
                        .Where(static source => source is not DefaultExpressionSyntax)
                        .ToArray();

                    SyntaxNode root = model.SyntaxTree.GetRoot();

                    AssignmentExpressionSyntax[] assignments = root
                        .DescendantNodes()
                        .OfType<AssignmentExpressionSyntax>()
                        .Where(assignment => SymbolEqualityComparer.Default.Equals(
                            model.GetSymbolInfo(assignment.Left).Symbol,
                            local))
                        .ToArray();

                    bool mutatedByReference = root.DescendantNodes()
                        .OfType<ArgumentSyntax>()
                        .Any(argument => argument.RefKindKeyword.Kind()
                                is SyntaxKind.RefKeyword or SyntaxKind.OutKeyword
                            && SymbolEqualityComparer.Default.Equals(
                                model.GetSymbolInfo(argument.Expression).Symbol,
                                local));

                    // A tuple deconstruction reassigns each local it names, but its left side is a tuple, not the
                    // local, so the assignments above never see it.
                    bool deconstructed = root.DescendantNodes()
                        .OfType<AssignmentExpressionSyntax>()
                        .Any(assignment => DeconstructsInto(assignment, model, local));

                    if (mutatedByReference
                        || deconstructed
                        || assignments.Any(static assignment =>
                            !assignment.IsKind(
                                SyntaxKind.SimpleAssignmentExpression)))
                    {
                        return false;
                    }

                    sources = sources
                        .Concat(assignments.Select(static assignment =>
                            assignment.Right))
                        .ToArray();
                }

                // A source in a tree the analysis does not hold (generated code) cannot be followed, so the value is not proved.
                return sources.Length != 0
                    && sources.All(source => semanticModels.TryGetValue(source.SyntaxTree, out SemanticModel? sourceModel)
                        && review(
                            source,
                            sourceModel,
                            path,
                            context));
            }
            finally
            {
                path.Remove(symbol);
            }
        }

        private bool HasAuthoredStorageWrite(ISymbol storage) =>
            storage.ContainingType?.DeclaringSyntaxReferences
                .SelectMany(static reference => reference.GetSyntax()
                    .DescendantNodes()
                    .OfType<AssignmentExpressionSyntax>())
                .Any(assignment => semanticModels.TryGetValue(assignment.SyntaxTree, out SemanticModel? assignmentModel)
                    && (SymbolEqualityComparer.Default.Equals(
                            assignmentModel.GetSymbolInfo(assignment.Left).Symbol,
                            storage)
                        || DeconstructsInto(assignment, assignmentModel, storage))) == true;

        // True when the assignment is a tuple deconstruction that names the storage among its targets.
        private static bool DeconstructsInto(AssignmentExpressionSyntax assignment, SemanticModel model, ISymbol storage) =>
            assignment.Left is TupleExpressionSyntax tuple
            && tuple.DescendantNodes().OfType<IdentifierNameSyntax>().Any(name =>
                SymbolEqualityComparer.Default.Equals(model.GetSymbolInfo(name).Symbol, storage));

        private static ExpressionSyntax StripTransparentExpression(
            ExpressionSyntax expression) => expression switch
            {
                ParenthesizedExpressionSyntax parenthesized =>
                    StripTransparentExpression(parenthesized.Expression),
                CastExpressionSyntax cast =>
                    StripTransparentExpression(cast.Expression),
                PostfixUnaryExpressionSyntax suppression
                    when suppression.IsKind(
                        SyntaxKind.SuppressNullableWarningExpression) =>
                    StripTransparentExpression(suppression.Operand),
                BinaryExpressionSyntax coalesce
                    when coalesce.IsKind(SyntaxKind.CoalesceExpression)
                        && coalesce.Right is ThrowExpressionSyntax =>
                    StripTransparentExpression(coalesce.Left),
                _ => expression,
            };

        private static bool IsReviewedCollectionMechanicalMember(
            IMethodSymbol method)
        {
            string type = TypeKey(method.ContainingType);

            return type is
                    "System.Collections.Concurrent.ConcurrentDictionary`2"
                        or "System.Collections.Generic.Dictionary`2"
                        or "System.Collections.Generic.Dictionary`2.AlternateLookup`1"
                        or "System.Collections.Generic.IReadOnlyDictionary`2"
                && method.Name == "TryGetValue"
                && !method.Parameters.Any(static parameter =>
                    parameter.Type.TypeKind == TypeKind.Delegate);
        }

        private bool HasOnlyReviewedComparerArguments(
            IMethodSymbol method,
            SyntaxNode? node,
            SemanticModel? model)
        {
            IParameterSymbol[] comparerParameters = method.Parameters
                .Where(static parameter => IsComparerType(parameter.Type))
                .ToArray();

            if (comparerParameters.Length == 0)
            {
                return true;
            }

            if (node is null || model is null)
            {
                return false;
            }

            IArgumentOperation[] arguments = model.GetOperation(node) switch
            {
                IInvocationOperation invocation => invocation.Arguments.ToArray(),
                IObjectCreationOperation creation => creation.Arguments.ToArray(),
                _ => [],
            };

            IArgumentOperation[] comparerArguments = arguments
                .Where(static argument => argument.Parameter is { Type: { } type }
                    && IsComparerType(type))
                .ToArray();

            if (comparerArguments.Length != comparerParameters.Length)
            {
                return false;
            }

            foreach (IArgumentOperation argument in comparerArguments)
            {
                if (argument.ArgumentKind == ArgumentKind.DefaultValue
                    && argument.Value.ConstantValue is
                    {
                        HasValue: true,
                        Value: null,
                    })
                {
                    continue;
                }

                ExpressionSyntax? expression = argument?.Syntax switch
                {
                    ArgumentSyntax syntax => syntax.Expression,
                    ExpressionSyntax syntax => syntax,
                    _ => argument?.Value.Syntax as ExpressionSyntax,
                };

                if (expression is null
                    || !IsReviewedPureComparerExpression(
                        expression,
                        model,
                        new HashSet<ISymbol>(
                            SymbolEqualityComparer.Default)))
                {
                    return false;
                }
            }

            return true;
        }

        private bool IsReviewedPureComparerExpression(
            ExpressionSyntax expression,
            SemanticModel model,
            HashSet<ISymbol> path)
        {
            expression = expression switch
            {
                ParenthesizedExpressionSyntax parenthesized =>
                    parenthesized.Expression,
                CastExpressionSyntax cast => cast.Expression,
                _ => expression,
            };

            if (expression is ConditionalExpressionSyntax conditional)
            {
                return IsReviewedPureComparerExpression(
                        conditional.WhenTrue,
                        model,
                        path)
                    && IsReviewedPureComparerExpression(
                        conditional.WhenFalse,
                        model,
                        path);
            }

            ISymbol? symbol = model.GetSymbolInfo(expression).Symbol;

            if (symbol is IPropertySymbol property
                && (TypeKey(property.ContainingType) == "System.StringComparer"
                        && property.Name is "Ordinal" or "OrdinalIgnoreCase"
                    || TypeKey(property.ContainingType) is
                        "System.Collections.Generic.Comparer`1"
                            or "System.Collections.Generic.EqualityComparer`1"
                        && property.Name == "Default"
                    || TypeKey(property.ContainingType)
                            == "System.Collections.Generic.ReferenceEqualityComparer"
                        && property.Name == "Instance"))
            {
                return true;
            }

            if (symbol is IFieldSymbol or IPropertySymbol or ILocalSymbol)
            {
                if (!path.Add(symbol))
                {
                    return false;
                }

                try
                {
                    foreach (SyntaxReference reference in symbol.DeclaringSyntaxReferences)
                    {
                        ExpressionSyntax? initializer = reference.GetSyntax() switch
                        {
                            VariableDeclaratorSyntax variable =>
                                variable.Initializer?.Value,
                            PropertyDeclarationSyntax declaredProperty =>
                                declaredProperty.Initializer?.Value
                                    ?? declaredProperty.ExpressionBody?.Expression,
                            _ => null,
                        };

                        if (initializer is not null
                            && IsReviewedPureComparerExpression(
                                initializer,
                                semanticModels[initializer.SyntaxTree],
                                path))
                        {
                            return true;
                        }
                    }
                }
                finally
                {
                    path.Remove(symbol);
                }
            }

            INamedTypeSymbol? comparerType = model.GetTypeInfo(expression).Type
                as INamedTypeSymbol;

            if (comparerType is null
                || !comparerType.AllInterfaces.Any(static contract =>
                    IsComparerType(contract)))
            {
                return false;
            }

            AuthoredMember[] comparisons = comparerType
                .GetMembers()
                .OfType<IMethodSymbol>()
                .Where(static candidate => candidate.Name is
                    "Compare" or "Equals" or "GetHashCode")
                .Select(candidate => Resolve(
                    candidate,
                    model.Compilation))
                .OfType<AuthoredMember>()
                .ToArray();

            return comparisons.Length != 0
                && comparisons.All(comparison =>
                    !ContainsPotentialProducerSite(comparison));
        }

        private static bool IsComparerType(ITypeSymbol type) =>
            TypeKey(type) is
                "System.Collections.IComparer"
                    or "System.Collections.IEqualityComparer"
                    or "System.Collections.Generic.IComparer`1"
                    or "System.Collections.Generic.IEqualityComparer`1";

        // Pinned M.E.AI 10.8.1 EmbeddingGenerationOptions.Dimensions is a nonvirtual nullable-int
        // storage getter; its nonvirtual setter validates null or values >= 1 before storing. Keep it
        // separate from the storage-only inventory so no other validating setter is implied.
        private static bool IsReviewedExactMeAiDimensionsProperty(
            IPropertySymbol property,
            bool mutation)
        {
            if (Normalize(property) != "Microsoft.Extensions.AI.EmbeddingGenerationOptions.Dimensions"
                || property.IsStatic
                || property.IsIndexer
                || !property.Parameters.IsEmpty
                || property.ExplicitInterfaceImplementations.Length != 0
                || !IsExactFrameworkType(
                    property.ContainingType,
                    "Microsoft.Extensions.AI.EmbeddingGenerationOptions",
                    typeof(Microsoft.Extensions.AI.EmbeddingGenerationOptions).Assembly.GetName())
                || !IsExactFrameworkType(property.Type, "System.Nullable`1", typeof(int?).Assembly.GetName())
                || property.Type is not INamedTypeSymbol
                { TypeArguments: [{ SpecialType: SpecialType.System_Int32 }] })
            {
                return false;
            }

            IMethodSymbol? accessor = mutation ? property.SetMethod : property.GetMethod;

            if (accessor is null
                || accessor.IsStatic
                || accessor.IsAbstract
                || accessor.IsVirtual
                || accessor.IsOverride)
            {
                return false;
            }

            bool exactGetter = !mutation
                && accessor.MethodKind == MethodKind.PropertyGet
                && accessor.Parameters.IsEmpty
                && SymbolEqualityComparer.Default.Equals(accessor.ReturnType, property.Type);

            bool exactSetter = mutation
                && accessor.MethodKind == MethodKind.PropertySet
                && accessor.ReturnType.SpecialType == SpecialType.System_Void
                && accessor.Parameters is [{ RefKind: RefKind.None } parameter]
                && SymbolEqualityComparer.Default.Equals(parameter.Type, property.Type);

            // Setter behavior is the pinned null-or->=1 validation followed by storage. Its receiver
            // and input expressions remain subject to the ordinary authored traversal.
            return (exactGetter || exactSetter)
                && HasReviewedExactExternalIdentity(property);
        }

        private static bool IsReviewedExactStoredExternalProperty(
            IPropertySymbol property,
            bool mutation)
        {
            IMethodSymbol? accessor = mutation
                ? property.SetMethod
                : property.GetMethod;

            return accessor is not null
                && !accessor.IsAbstract
                && !accessor.IsVirtual
                && !accessor.IsOverride
                && (ReviewedExactStoredExternalProperties.Contains(Normalize(property))
                    || !mutation && ReviewedExactReadOnlyStoredExternalProperties.Contains(Normalize(property)))
                && HasReviewedExactExternalIdentity(property);
        }

        private static bool IsReviewedExactBoundedExternalMember(IMethodSymbol method)
        {
            IMethodSymbol definition = (method.ReducedFrom ?? method).OriginalDefinition;

            return !definition.IsAbstract
                && (!definition.IsVirtual
                    || definition.ContainingType.IsSealed
                    || definition.ContainingType.IsValueType)
                && definition.GetDocumentationCommentId() is { } identity
                && ReviewedExactBoundedExternalMethods.Contains(identity)
                && HasReviewedExactExternalIdentity(definition);
        }

        private static bool HasReviewedExactExternalIdentity(ISymbol symbol)
        {
            string type = TypeKey(symbol.ContainingType);

            AssemblyName? trusted = type switch
            {
                "Microsoft.Extensions.AI.OpenAIClientExtensions" => typeof(Microsoft.Extensions.AI.OpenAIClientExtensions).Assembly.GetName(),
                _ when type.StartsWith("Microsoft.Extensions.AI.", StringComparison.Ordinal) => typeof(Microsoft.Extensions.AI.ChatOptions).Assembly.GetName(),
                "Microsoft.ML.Tokenizers.EncodedToken" => typeof(Microsoft.ML.Tokenizers.EncodedToken).Assembly.GetName(),
                "OpenAI.OpenAIClientOptions" => typeof(OpenAI.OpenAIClientOptions).Assembly.GetName(),
                _ when type.StartsWith("System.ClientModel.", StringComparison.Ordinal) => typeof(System.ClientModel.ApiKeyCredential).Assembly.GetName(),
                "System.Collections.Generic.LinkedList`1" or "System.Collections.Generic.LinkedListNode`1" => typeof(LinkedList<>).Assembly.GetName(),
                "System.Range" => typeof(Range).Assembly.GetName(),
                "System.Security.Cryptography.IncrementalHash" or "System.Security.Cryptography.SHA256" => typeof(SHA256).Assembly.GetName(),
                _ when type.StartsWith("System.Text.Json.", StringComparison.Ordinal) => typeof(JsonDocument).Assembly.GetName(),
                _ => null,
            };

            return trusted is not null
                && FrameworkAssemblyIdentityMatches(symbol.ContainingAssembly.Identity, trusted);
        }

        private static bool IsReviewedNonProducerExternalMember(
            IPropertySymbol property,
            bool mutation) =>
            ReviewedIntrinsicExternalTypes.Contains(TypeKey(property.ContainingType))
            || !mutation && IsReviewedFloatVectorProperty(property)
            || IsReviewedExactGeneratedEmbeddingRead(property, mutation)
            || IsReviewedExactStoredExternalProperty(property, mutation)
            || !mutation && IsReviewedProviderNeutralOptionsBuilderMember(property)
            || ReviewedNonProducerExternalMembers.Contains(
                Normalize(property) + (mutation ? " setter" : string.Empty));

        private AuthoredMember? ResolveCallable(
            ExpressionSyntax expression,
            SemanticModel model,
            IReadOnlyDictionary<ISymbol, AuthoredMember>? callableBindings = null,
            IReadOnlySet<ISymbol>? absentCallables = null)
        {
            AuthoredMember[] targets = ResolveCallableTargets(
                expression,
                model,
                callableBindings,
                absentCallables);

            return targets is [AuthoredMember target]
                ? target
                : null;
        }

        private AuthoredMember[] ResolveCallableTargets(
            ExpressionSyntax expression,
            SemanticModel model,
            IReadOnlyDictionary<ISymbol, AuthoredMember>? callableBindings = null,
            IReadOnlySet<ISymbol>? absentCallables = null)
        {
            ClosedCallableValue contextual = ResolveContextualCallable(
                expression,
                model,
                callableBindings,
                absentCallables,
                new HashSet<ISymbol>(SymbolEqualityComparer.Default));

            if (contextual.IsKnown)
            {
                return CallableTargets(contextual);
            }

            ISymbol? symbol = model.GetSymbolInfo(expression).Symbol;

            if (symbol is not null && callableBindings?.TryGetValue(symbol, out AuthoredMember? bound) == true)
            {
                return [bound];
            }

            if (expression is AnonymousFunctionExpressionSyntax lambda && model.GetOperation(lambda) is IAnonymousFunctionOperation operation)
            {
                return
                [
                    new(
                        operation.Symbol,
                        lambda.Body,
                        model,
                        CallableBindings: callableBindings,
                        AbsentCallables: absentCallables),
                ];
            }

            if (expression is not InvocationExpressionSyntax && model.GetSymbolInfo(expression).Symbol is IMethodSymbol method)
            {
                return Resolve(method, model.Compilation) is { } target
                    ? [target]
                    : [];
            }

            if (symbol is ILocalSymbol local && local.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax() is VariableDeclaratorSyntax { Initializer.Value: { } initializer } variable && !variable.Ancestors().OfType<BlockSyntax>().First().DescendantNodes().OfType<AssignmentExpressionSyntax>().Any(assignment => SymbolEqualityComparer.Default.Equals(model.GetSymbolInfo(assignment.Left).Symbol, local)))
            {
                return initializer == expression
                    ? []
                    : ResolveCallableTargets(initializer, model, callableBindings, absentCallables);
            }

            if (symbol is not null)
            {
                ClosedCallableValue value = ResolveClosedCallable(symbol);

                if (value.IsKnown)
                {
                    return CallableTargets(value);
                }
            }

            return [];
        }

        private ClosedCallableValue ResolveContextualCallable(
            ExpressionSyntax expression,
            SemanticModel model,
            IReadOnlyDictionary<ISymbol, AuthoredMember>? callableBindings,
            IReadOnlySet<ISymbol>? absentCallables,
            HashSet<ISymbol> path)
        {
            while (expression is ParenthesizedExpressionSyntax
                or CastExpressionSyntax
                or PostfixUnaryExpressionSyntax
                {
                    RawKind: (int)SyntaxKind.SuppressNullableWarningExpression,
                })
            {
                expression = expression switch
                {
                    ParenthesizedExpressionSyntax parenthesized => parenthesized.Expression,
                    CastExpressionSyntax cast => cast.Expression,
                    PostfixUnaryExpressionSyntax postfix => postfix.Operand,
                    _ => expression,
                };
            }

            if (expression is DefaultExpressionSyntax
                || expression is LiteralExpressionSyntax literal
                    && literal.IsKind(SyntaxKind.DefaultLiteralExpression)
                || model.GetConstantValue(expression) is
                {
                    HasValue: true,
                    Value: null,
                })
            {
                return new(true, null, true, false);
            }

            if (expression is AnonymousFunctionExpressionSyntax lambda
                && model.GetOperation(lambda) is IAnonymousFunctionOperation operation)
            {
                return new(
                    true,
                    new(
                        operation.Symbol,
                        lambda.Body,
                        model,
                        CallableBindings: callableBindings,
                        AbsentCallables: absentCallables),
                    false,
                    false);
            }

            if (expression is BinaryExpressionSyntax
                {
                    RawKind: (int)SyntaxKind.CoalesceExpression,
                } coalesce)
            {
                ClosedCallableValue left = ResolveContextualCallable(
                    coalesce.Left,
                    model,
                    callableBindings,
                    absentCallables,
                    path);

                if (!left.IsKnown || !left.CanBeAbsent)
                {
                    return left;
                }

                ClosedCallableValue right = ResolveContextualCallable(
                    coalesce.Right,
                    model,
                    callableBindings,
                    absentCallables,
                    path);

                if (left.Target is null
                    && left.Targets is null
                    && !left.EffectFreeExternal)
                {
                    return right;
                }

                return MergeClosedCallables([
                    left with
                    {
                        CanBeAbsent = false,
                    },
                    right,
                ]);
            }

            if (expression is ConditionalExpressionSyntax conditional)
            {
                return MergeClosedCallables([
                    ResolveContextualCallable(
                        conditional.WhenTrue,
                        model,
                        callableBindings,
                        absentCallables,
                        path),
                    ResolveContextualCallable(
                        conditional.WhenFalse,
                        model,
                        callableBindings,
                        absentCallables,
                        path),
                ]);
            }

            if (expression is SwitchExpressionSyntax switchExpression)
            {
                return MergeClosedCallables(
                    switchExpression.Arms.Select(arm => ResolveContextualCallable(
                        arm.Expression,
                        model,
                        callableBindings,
                        absentCallables,
                        path)));
            }

            ISymbol? symbol = model.GetSymbolInfo(expression).Symbol;

            if (symbol is not null
                && callableBindings?.TryGetValue(symbol, out AuthoredMember? bound) == true)
            {
                return new(true, bound, false, false);
            }

            if (symbol is not null
                && absentCallables?.Contains(symbol) == true)
            {
                return new(true, null, true, false);
            }

            if (symbol is IMethodSymbol method
                && expression is not InvocationExpressionSyntax)
            {
                AuthoredMember? target = Resolve(method, model.Compilation);

                return target is not null
                    ? new(true, target, false, false)
                    : IsEffectFreeExternalCallable(method, model.Compilation)
                        ? new(true, null, false, true)
                        : default;
            }

            if (symbol is IFieldSymbol
                {
                    IsReadOnly: true,
                } field
                && !HasAuthoredCallableMutation(field)
                && path.Add(field))
            {
                try
                {
                    VariableDeclaratorSyntax[] declarations = field
                        .DeclaringSyntaxReferences
                        .Select(static reference => reference.GetSyntax())
                        .OfType<VariableDeclaratorSyntax>()
                        .Where(static declaration =>
                            declaration.Initializer is not null)
                        .ToArray();

                    if (declarations is
                        [
                        {
                            Initializer.Value: { } initializer,
                        },
                        ])
                    {
                        return ResolveContextualCallable(
                            initializer,
                            semanticModels[initializer.SyntaxTree],
                            callableBindings,
                            absentCallables,
                            path);
                    }
                }
                finally
                {
                    _ = path.Remove(field);
                }
            }

            if (symbol is ILocalSymbol local
                && path.Add(local))
            {
                try
                {
                    if (local.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                            is VariableDeclaratorSyntax
                        {
                            Initializer.Value: { } initializer,
                        } variable
                        && !variable.Ancestors().OfType<BlockSyntax>().First()
                            .DescendantNodes().OfType<AssignmentExpressionSyntax>()
                            .Any(assignment => SymbolEqualityComparer.Default.Equals(
                                model.GetSymbolInfo(assignment.Left).Symbol,
                                local)))
                    {
                        return ResolveContextualCallable(
                            initializer,
                            model,
                            callableBindings,
                            absentCallables,
                            path);
                    }
                }
                finally
                {
                    _ = path.Remove(local);
                }
            }

            return symbol is null
                ? default
                : ResolveClosedCallable(symbol);
        }

        private static AuthoredMember[] CallableTargets(ClosedCallableValue value) =>
            value.Targets is { } targets
                ? [.. targets]
                : value.Target is { } target
                    ? [target]
                    : [];

        private ClosedCallableValue ResolveClosedCallable(ISymbol symbol)
        {
            string identity = (symbol.ContainingAssembly?.Identity.ToString()
                    ?? "no-assembly")
                + "|"
                + symbol.ToDisplayString(
                    SymbolDisplayFormat.FullyQualifiedFormat);

            if (!closedCallableAnalysis.TryGetValue(
                    identity,
                    out ClosedCallableAnalysisCounter? analysis))
            {
                analysis = new();

                closedCallableAnalysis.Add(identity, analysis);
            }

            analysis.ResolutionRequests++;

            if (closedCallableValues.TryGetValue(
                    symbol,
                    out ClosedCallableValue cached))
            {
                return cached;
            }

            analysis.ResolutionBuilds++;

            ClosedCallableValue result = ResolveClosedCallable(
                symbol,
                new HashSet<ISymbol>(SymbolEqualityComparer.Default));

            closedCallableValues.Add(symbol, result);

            return result;
        }

        private ClosedCallableValue ResolveClosedCallable(ISymbol symbol, HashSet<ISymbol> path)
        {
            if (!path.Add(symbol))
            {
                return default;
            }

            try
            {
                ITypeSymbol? callableType = symbol switch
                {
                    IEventSymbol declaredEvent => declaredEvent.Type,
                    IFieldSymbol declaredField => declaredField.Type,
                    ILocalSymbol declaredLocal => declaredLocal.Type,
                    IParameterSymbol declaredParameter => declaredParameter.Type,
                    IPropertySymbol declaredProperty => declaredProperty.Type,
                    _ => null,
                };

                if (callableType?.TypeKind != TypeKind.Delegate || !IsEffectivelyClosed(symbol))
                {
                    return default;
                }

                if (symbol is IEventSymbol eventSymbol)
                {
                    return HasAuthoredCallableMutation(eventSymbol) ? default : new(true, null, true, false);
                }

                if (symbol is IParameterSymbol { ContainingSymbol: IMethodSymbol method } parameter)
                {
                    return ResolveParameter(parameter, method, path);
                }

                if (symbol is ILocalSymbol local)
                {
                    SyntaxNode? declaration = local.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax();

                    if (declaration is VariableDeclaratorSyntax { Initializer.Value: { } initializer } variable
                        && !variable.Ancestors().OfType<BlockSyntax>().First().DescendantNodes().OfType<AssignmentExpressionSyntax>().Any(assignment => SymbolEqualityComparer.Default.Equals(semanticModels[assignment.SyntaxTree].GetSymbolInfo(assignment.Left).Symbol, local)))
                    {
                        return ResolveClosedCallable(initializer, semanticModels[initializer.SyntaxTree], path);
                    }

                    if (declaration?.AncestorsAndSelf().OfType<IsPatternExpressionSyntax>().FirstOrDefault() is { } pattern)
                    {
                        return ResolveClosedCallable(pattern.Expression, semanticModels[pattern.SyntaxTree], path);
                    }

                    return default;
                }

                if (symbol is IPropertySymbol property)
                {
                    if (PositionalRecordConstructorParameter(property) is
                        {
                            ContainingSymbol: IMethodSymbol primaryConstructor,
                        } positional)
                    {
                        return HasAuthoredCallableMutation(property)
                            ? default
                            : ResolveParameter(positional, primaryConstructor, path);
                    }

                    if (!PropertyStorageIsOnlyWrittenThroughItself(property))
                    {
                        return default;
                    }

                    bool initialized = property.DeclaringSyntaxReferences.Any(reference => reference.GetSyntax() is PropertyDeclarationSyntax { Initializer: not null });

                    return initialized || HasAuthoredCallableMutation(property) ? default : new(true, null, true, false);
                }

                if (symbol is not IFieldSymbol field)
                {
                    return default;
                }

                bool mutatedByReference = AuthoredMembers.Any(member => member.Syntax.DescendantNodesAndSelf().OfType<ArgumentSyntax>().Any(argument => argument.RefKindKeyword.Kind() is SyntaxKind.RefKeyword or SyntaxKind.OutKeyword && SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(argument.Expression).Symbol, field)));

                AssignmentExpressionSyntax[] writes = AuthoredMembers.SelectMany(member => member.Syntax.DescendantNodesAndSelf().OfType<AssignmentExpressionSyntax>().Where(assignment => SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(assignment.Left).Symbol, field))).DistinctBy(static assignment => (assignment.SyntaxTree, assignment.SpanStart)).ToArray();

                if (mutatedByReference)
                {
                    return default;
                }

                List<ClosedCallableValue> values = [];

                foreach (SyntaxReference reference in field.DeclaringSyntaxReferences)
                {
                    if (reference.GetSyntax() is VariableDeclaratorSyntax { Initializer.Value: { } initializer })
                    {
                        values.Add(ResolveClosedCallable(initializer, semanticModels[initializer.SyntaxTree], path));
                    }
                }

                foreach (AssignmentExpressionSyntax write in writes)
                {
                    AuthoredMember[] owners = AuthoredMembers.Where(member => member.Syntax.SyntaxTree == write.SyntaxTree && member.Syntax.Span.Contains(write.Span)).OrderBy(member => member.Syntax.Span.Length).ToArray();

                    AuthoredMember? owner = owners.FirstOrDefault();

                    if (!write.IsKind(SyntaxKind.SimpleAssignmentExpression) || owner is null || owner.Symbol.MethodKind is not (MethodKind.Constructor or MethodKind.StaticConstructor) || !SymbolEqualityComparer.Default.Equals(owner.Symbol.ContainingType, field.ContainingType) || !IsAssignedOnEverySuccessfulConstruction(owner, write))
                    {
                        return default;
                    }

                    values.Add(ResolveClosedCallable(write.Right, owner.Model, path));
                }

                return values.Count == 0 ? new(true, null, true, false) : MergeClosedCallables(values);
            }
            finally
            {
                path.Remove(symbol);
            }
        }

        private ClosedCallableValue ResolveClosedCallable(ExpressionSyntax expression, SemanticModel model, HashSet<ISymbol> path)
        {
            while (expression is ParenthesizedExpressionSyntax parenthesized || expression is CastExpressionSyntax || expression is PostfixUnaryExpressionSyntax { RawKind: (int)SyntaxKind.SuppressNullableWarningExpression })
            {
                expression = expression switch
                {
                    ParenthesizedExpressionSyntax parenthesizedExpression => parenthesizedExpression.Expression,
                    CastExpressionSyntax cast => cast.Expression,
                    PostfixUnaryExpressionSyntax postfix => postfix.Operand,
                    _ => expression,
                };
            }

            if (expression is DefaultExpressionSyntax || expression is LiteralExpressionSyntax literal && literal.IsKind(SyntaxKind.DefaultLiteralExpression) || model.GetConstantValue(expression) is { HasValue: true, Value: null })
            {
                return new(true, null, true, false);
            }

            if (expression is AnonymousFunctionExpressionSyntax lambda && model.GetOperation(lambda) is IAnonymousFunctionOperation operation)
            {
                return new(true, new(operation.Symbol, lambda.Body, model), false, false);
            }

            if (expression is BinaryExpressionSyntax { RawKind: (int)SyntaxKind.CoalesceExpression } coalesce)
            {
                ClosedCallableValue left = ResolveClosedCallable(coalesce.Left, model, path);

                if (!left.IsKnown || !left.CanBeAbsent)
                {
                    return left;
                }

                ClosedCallableValue right = ResolveClosedCallable(coalesce.Right, model, path);

                if (left.Target is null && !left.EffectFreeExternal)
                {
                    return right;
                }

                return MergeClosedCallables([left with { CanBeAbsent = false }, right]);
            }

            if (expression is ConditionalExpressionSyntax conditional)
            {
                return MergeClosedCallables([
                    ResolveClosedCallable(conditional.WhenTrue, model, path),
                    ResolveClosedCallable(conditional.WhenFalse, model, path),
                ]);
            }

            if (expression is SwitchExpressionSyntax switchExpression)
            {
                return MergeClosedCallables(switchExpression.Arms.Select(arm => ResolveClosedCallable(arm.Expression, model, path)));
            }

            if (expression is ImplicitObjectCreationExpressionSyntax or ObjectCreationExpressionSyntax && model.GetTypeInfo(expression).ConvertedType?.TypeKind == TypeKind.Delegate && expression is BaseObjectCreationExpressionSyntax { ArgumentList.Arguments: [ArgumentSyntax argument] })
            {
                return ResolveClosedCallable(argument.Expression, model, path);
            }

            ISymbol? symbol = model.GetSymbolInfo(expression).Symbol;

            if (symbol is IMethodSymbol method
                && expression is not InvocationExpressionSyntax)
            {
                AuthoredMember? target = Resolve(method, model.Compilation);

                return target is not null
                    ? new(true, target, false, false)
                    : IsEffectFreeExternalCallable(method, model.Compilation) ? new(true, null, false, true) : default;
            }

            if (symbol is ILocalSymbol local && local.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax() is VariableDeclaratorSyntax { Initializer.Value: { } initializer } variable && !variable.Ancestors().OfType<BlockSyntax>().First().DescendantNodes().OfType<AssignmentExpressionSyntax>().Any(assignment => SymbolEqualityComparer.Default.Equals(model.GetSymbolInfo(assignment.Left).Symbol, local)))
            {
                return ResolveClosedCallable(initializer, model, path);
            }

            return symbol is null ? default : ResolveClosedCallable(symbol, path);
        }

        private ClosedCallableValue ResolveParameter(IParameterSymbol parameter, IMethodSymbol method, HashSet<ISymbol> path)
        {
            List<ClosedCallableValue> values = [];

            Dictionary<GraphMemberIdentity, List<ClosedCallableValue>> constructionValues = [];

            bool SameCallableValue(ClosedCallableValue left, ClosedCallableValue right)
            {
                if (left.IsKnown != right.IsKnown
                    || left.CanBeAbsent != right.CanBeAbsent
                    || left.EffectFreeExternal != right.EffectFreeExternal)
                {
                    return false;
                }

                HashSet<GraphMemberIdentity> leftTargets = CallableTargets(left)
                    .Select(MemberIdentity)
                    .ToHashSet();

                return leftTargets.SetEquals(
                    CallableTargets(right).Select(MemberIdentity));
            }

            if (method.MethodKind == MethodKind.Constructor)
            {
                foreach ((BaseObjectCreationExpressionSyntax creation, SemanticModel model) in objectCreations)
                {
                    if (model.GetSymbolInfo(creation).Symbol is IMethodSymbol target && Identity(target) == Identity(method))
                    {
                        ClosedCallableValue value = ResolveArgument(
                            parameter,
                            creation.ArgumentList?.Arguments ?? default,
                            model,
                            path);

                        values.Add(value);

                        AuthoredMember? owner = AuthoredMembers
                            .Where(member => member.Syntax.SyntaxTree == creation.SyntaxTree
                                && member.Syntax.Span.Contains(creation.Span))
                            .OrderBy(member => member.Syntax.Span.Length)
                            .FirstOrDefault();

                        if (owner is not null)
                        {
                            GraphMemberIdentity identity = MemberIdentity(owner);

                            if (!constructionValues.TryGetValue(
                                    identity,
                                    out List<ClosedCallableValue>? ownedValues))
                            {
                                constructionValues.Add(identity, ownedValues = []);
                            }

                            ownedValues.Add(value);
                        }
                    }
                }

                foreach ((ConstructorInitializerSyntax initializer, SemanticModel model) in constructorInitializers)
                {
                    if (model.GetSymbolInfo(initializer).Symbol is IMethodSymbol target && Identity(target) == Identity(method))
                    {
                        values.Add(ResolveArgument(parameter, initializer.ArgumentList.Arguments, model, path));
                    }
                }

                if (constructionValues.Values.Any(group => group
                    .Skip(1)
                    .Any(value => !SameCallableValue(group[0], value))))
                {
                    return default;
                }
            }
            else
            {
                foreach ((InvocationExpressionSyntax call, SemanticModel model) in invocations)
                {
                    if (model.GetSymbolInfo(call).Symbol is IMethodSymbol target && Identity(target) == Identity(method))
                    {
                        values.Add(ResolveArgument(parameter, call.ArgumentList.Arguments, model, path));
                    }
                }
            }

            return values.Count == 0 ? default : MergeClosedCallables(values);
        }

        private ClosedCallableValue ResolveArgument(IParameterSymbol parameter, SeparatedSyntaxList<ArgumentSyntax> arguments, SemanticModel model, HashSet<ISymbol> path)
        {
            ArgumentSyntax? supplied = arguments.SingleOrDefault(argument => model.GetOperation(argument) is IArgumentOperation { Parameter: { } target } && target.Ordinal == parameter.Ordinal);

            if (supplied is not null)
            {
                return ResolveClosedCallable(supplied.Expression, model, path);
            }

            return parameter.HasExplicitDefaultValue && parameter.ExplicitDefaultValue is null
                ? new(true, null, true, false)
                : default;
        }

        private ClosedCallableValue MergeClosedCallables(IEnumerable<ClosedCallableValue> values)
        {
            Dictionary<GraphMemberIdentity, AuthoredMember> targets = [];

            bool canBeAbsent = false;

            bool effectFreeExternal = false;

            foreach (ClosedCallableValue value in values)
            {
                if (!value.IsKnown)
                {
                    return default;
                }

                canBeAbsent |= value.CanBeAbsent;

                effectFreeExternal |= value.EffectFreeExternal;

                foreach (AuthoredMember target in CallableTargets(value))
                {
                    targets.TryAdd(MemberIdentity(target), target);
                }
            }

            AuthoredMember[] exactTargets = targets.Values
                .OrderBy(static target => TypeKey(target.Symbol.ContainingType), StringComparer.Ordinal)
                .ThenBy(static target => MethodKey(target.Symbol), StringComparer.Ordinal)
                .ThenBy(static target => target.Syntax.SyntaxTree.FilePath, StringComparer.Ordinal)
                .ThenBy(static target => target.Syntax.SpanStart)
                .ToArray();

            return new(
                true,
                exactTargets is [AuthoredMember singleTarget] ? singleTarget : null,
                canBeAbsent,
                effectFreeExternal,
                exactTargets.Length > 1 ? exactTargets : null);
        }

        private bool HasAuthoredCallableMutation(ISymbol symbol)
        {
            if (authoredCallableMutations.TryGetValue(symbol, out bool cached))
            {
                return cached;
            }

            authoredCallableMutationCorpusScans++;

            // Every authored tree is scanned, not only member bodies: a field or property initializer can write a
            // seam through an object initializer or a with-expression. A deconstruction writes each element of
            // its tuple target.
            bool Writes(SemanticModel model, ExpressionSyntax target) => target switch
            {
                TupleExpressionSyntax tuple => tuple.Arguments.Any(element => Writes(model, element.Expression)),
                ParenthesizedExpressionSyntax parenthesized => Writes(model, parenthesized.Expression),
                _ => SymbolEqualityComparer.Default.Equals(model.GetSymbolInfo(target).Symbol, symbol),
            };

            bool mutated = semanticModels.Any(pair => pair.Key.GetRoot().DescendantNodes().Any(node => node switch
            {
                AssignmentExpressionSyntax assignment => Writes(pair.Value, assignment.Left),
                ArgumentSyntax argument when argument.RefKindKeyword.Kind() is SyntaxKind.RefKeyword or SyntaxKind.OutKeyword => SymbolEqualityComparer.Default.Equals(pair.Value.GetSymbolInfo(argument.Expression).Symbol, symbol),
                _ => false,
            }));

            authoredCallableMutations.Add(symbol, mutated);

            return mutated;
        }

        private static bool IsEffectivelyClosed(ISymbol symbol) =>
            symbol is ILocalSymbol
            || symbol.DeclaredAccessibility is Accessibility.Private or Accessibility.Internal or Accessibility.ProtectedAndInternal
            || symbol is IParameterSymbol
                && symbol.ContainingSymbol.DeclaredAccessibility is Accessibility.Private or Accessibility.Internal or Accessibility.ProtectedAndInternal
            || IsEffectivelyClosed(symbol.ContainingType);

        private static bool IsEffectivelyClosed(INamedTypeSymbol? type)
        {
            while (type is not null)
            {
                if (type.DeclaredAccessibility is Accessibility.Private or Accessibility.Internal or Accessibility.ProtectedAndInternal)
                {
                    return true;
                }

                type = type.ContainingType;
            }

            return false;
        }

        private static bool IsDelegateExpression(SemanticModel model, ExpressionSyntax expression)
        {
            Microsoft.CodeAnalysis.TypeInfo type = model.GetTypeInfo(expression);

            return type.Type?.TypeKind == TypeKind.Delegate || type.ConvertedType?.TypeKind == TypeKind.Delegate;
        }

        private bool IsProvenAbsentCallable(ISymbol symbol)
        {
            if (absentTestCallables.TryGetValue(symbol, out bool absent))
            {
                return absent;
            }

            ITypeSymbol? callableType = symbol switch
            {
                IEventSymbol declaredEvent => declaredEvent.Type,
                IFieldSymbol declaredField => declaredField.Type,
                IPropertySymbol declaredProperty => declaredProperty.Type,
                _ => null,
            };

            bool initialized = symbol.DeclaringSyntaxReferences.Select(static reference => reference.GetSyntax()).Select(static syntax => syntax switch
            {
                VariableDeclaratorSyntax variable => variable.Initializer?.Value,
                PropertyDeclarationSyntax property => property.Initializer?.Value,
                _ => null,
            }).OfType<ExpressionSyntax>().Any(initializer => initializer is not DefaultExpressionSyntax && !(initializer is LiteralExpressionSyntax literal && literal.IsKind(SyntaxKind.DefaultLiteralExpression)) && semanticModels[initializer.SyntaxTree].GetConstantValue(initializer) is not { HasValue: true, Value: null });

            absent = symbol.DeclaredAccessibility is Accessibility.Private or Accessibility.Internal or Accessibility.ProtectedAndInternal
                && callableType?.TypeKind == TypeKind.Delegate
                && callableType.NullableAnnotation == NullableAnnotation.Annotated
                && !initialized
                && !HasAuthoredCallableMutation(symbol)
                && (symbol is not IPropertySymbol property || PropertyStorageIsOnlyWrittenThroughItself(property));

            if (absent)
            {
                absentTestCallables[symbol] = true;

                return true;
            }

            ClosedCallableValue value = ResolveClosedCallable(symbol);

            absent = value.IsKnown
                && CallableTargets(value).Length == 0
                && value.CanBeAbsent
                && !value.EffectFreeExternal;

            absentTestCallables[symbol] = absent;

            return absent;
        }

        // A delegate property no authored code assigns is proven never set only when assignments to it are the
        // only writes that can change what it returns: an auto-property, or a getter that is exactly the Value
        // of a private readonly framework AsyncLocal field of the declaring type that nothing outside the
        // property names. An overridable or partial property is neither: the getter that runs is another
        // declaration's.
        private bool PropertyStorageIsOnlyWrittenThroughItself(IPropertySymbol property)
        {
            if (property.IsAbstract
                || property.IsVirtual
                || property.IsOverride
                || property.IsExtern
                || property.DeclaringSyntaxReferences is not [SyntaxReference reference]
                || reference.GetSyntax() is not PropertyDeclarationSyntax declaration
                || declaration.Modifiers.Any(SyntaxKind.PartialKeyword))
            {
                return false;
            }

            if (declaration.ExpressionBody is null
                && declaration.AccessorList is { } accessors
                && accessors.Accessors.All(static accessor =>
                    accessor.Body is null
                    && accessor.ExpressionBody is null))
            {
                return true;
            }

            ExpressionSyntax? getter = declaration.ExpressionBody?.Expression
                ?? (declaration.AccessorList?.Accessors
                        .Where(static accessor => accessor.IsKind(SyntaxKind.GetAccessorDeclaration))
                        .ToArray() is [{ ExpressionBody.Expression: { } accessorGetter }]
                    ? accessorGetter
                    : null);

            if (getter is not MemberAccessExpressionSyntax
                {
                    Expression: IdentifierNameSyntax storage,
                    Name: IdentifierNameSyntax { Identifier.ValueText: "Value" },
                } access
                || !access.IsKind(SyntaxKind.SimpleMemberAccessExpression)
                || !semanticModels.TryGetValue(declaration.SyntaxTree, out SemanticModel? model)
                || model.GetSymbolInfo(storage).Symbol is not IFieldSymbol
                {
                    DeclaredAccessibility: Accessibility.Private,
                    IsReadOnly: true,
                } field
                || !SymbolEqualityComparer.Default.Equals(field.ContainingType, property.ContainingType)
                || !IsExactFrameworkType(
                    field.Type,
                    "System.Threading.AsyncLocal`1",
                    typeof(AsyncLocal<>).Assembly.GetName())
                || model.GetSymbolInfo(access).Symbol is not IPropertySymbol { Name: "Value" } valueProperty
                || !SymbolEqualityComparer.Default.Equals(
                    valueProperty.ContainingType.OriginalDefinition,
                    field.Type.OriginalDefinition)
                || field.DeclaringSyntaxReferences is not [SyntaxReference fieldReference]
                || fieldReference.GetSyntax() is not VariableDeclaratorSyntax fieldDeclarator
                || fieldDeclarator.Initializer?.Value is { } initializer
                    && (initializer is not ImplicitObjectCreationExpressionSyntax
                        {
                            ArgumentList.Arguments.Count: 0,
                            Initializer: null,
                        }
                        and not ObjectCreationExpressionSyntax
                        {
                            ArgumentList: null or { Arguments.Count: 0 },
                            Initializer: null,
                        }
                        || !semanticModels.TryGetValue(initializer.SyntaxTree, out SemanticModel? initializerModel)
                        || !SymbolEqualityComparer.Default.Equals(initializerModel.GetTypeInfo(initializer).Type, field.Type)))
            {
                return false;
            }

            foreach (SyntaxReference part in property.ContainingType.DeclaringSyntaxReferences)
            {
                foreach (IdentifierNameSyntax name in part.GetSyntax().DescendantNodes().OfType<IdentifierNameSyntax>())
                {
                    if (name.Identifier.ValueText != field.Name
                        || name.SyntaxTree == declaration.SyntaxTree && declaration.Span.Contains(name.Span))
                    {
                        continue;
                    }

                    if (!semanticModels.TryGetValue(name.SyntaxTree, out SemanticModel? partModel))
                    {
                        return false;
                    }

                    SymbolInfo bound = partModel.GetSymbolInfo(name);

                    if (SymbolEqualityComparer.Default.Equals(bound.Symbol, field)
                        || bound.CandidateSymbols.Contains(field, SymbolEqualityComparer.Default))
                    {
                        return false;
                    }
                }
            }

            return true;
        }

        // A positional property of a sealed record class is declared by its primary-constructor parameter, and
        // only that constructor, an initializer or a with-expression can set it; HasAuthoredCallableMutation sees
        // the last two. Its value is therefore the primary-constructor argument at each authored construction. A
        // record struct is excluded because its default value runs no constructor, and an unsealed record because
        // a derived record constructs it through its own base clause, which no construction list here records.
        private IParameterSymbol? PositionalRecordConstructorParameter(IPropertySymbol property)
        {
            if (property.IsStatic
                || property.ContainingType is not
                {
                    TypeKind: TypeKind.Class,
                    IsRecord: true,
                    IsSealed: true,
                }
                || property.DeclaringSyntaxReferences is not [SyntaxReference reference]
                || reference.GetSyntax() is not ParameterSyntax
                {
                    Parent: ParameterListSyntax
                    {
                        Parent: RecordDeclarationSyntax,
                    },
                } parameter
                || !semanticModels.TryGetValue(parameter.SyntaxTree, out SemanticModel? model)
                || model.GetDeclaredSymbol(parameter) is not IParameterSymbol
                {
                    ContainingSymbol: IMethodSymbol
                    {
                        MethodKind: MethodKind.Constructor,
                    },
                } constructorParameter
                || !SymbolEqualityComparer.Default.Equals(constructorParameter.Type, property.Type))
            {
                return null;
            }

            return constructorParameter;
        }

        // The scan of a member from a fresh path depends only on its syntax and semantic model, so a root scan is
        // computed once. A scan that continues a path ends where it meets the path, so it is never cached. A root scan
        // that is asked for again while it is being computed (a body whose implicit call resolves to the body itself)
        // ends there as a scan meeting its own path does, and a result that was cut that way is not cached.
        private readonly Dictionary<ProducerSiteScanKey, bool> producerSiteScans = new(ProducerSiteScanKeyComparer.Instance);

        private readonly HashSet<GraphMemberIdentity> producerSiteScansInProgress = [];

        private int producerSiteScanCuts;

        // What a scan consults besides the syntax and the semantic model: the bindings the member was bound with (callables,
        // values, concrete types, admissions, the scoped holder, the readiness source), which a receiver proof and a callable
        // resolution read. Two scans of one body are the same scan only when they were bound with the very same bindings.
        private readonly record struct ProducerSiteScanKey(GraphMemberIdentity Member, object?[] Bindings);

        private sealed class ProducerSiteScanKeyComparer : IEqualityComparer<ProducerSiteScanKey>
        {
            internal static readonly ProducerSiteScanKeyComparer Instance = new();

            public bool Equals(ProducerSiteScanKey left, ProducerSiteScanKey right) =>
                left.Member.Equals(right.Member)
                && left.Bindings.Length == right.Bindings.Length
                && left.Bindings.Zip(right.Bindings).All(static pair => ReferenceEquals(pair.First, pair.Second));

            public int GetHashCode(ProducerSiteScanKey key)
            {
                HashCode hash = new();

                hash.Add(key.Member);

                foreach (object? binding in key.Bindings)
                {
                    hash.Add(binding is null ? 0 : System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode(binding));
                }

                return hash.ToHashCode();
            }
        }

        private static ProducerSiteScanKey ScanKey(GraphMemberIdentity identity, AuthoredMember member) =>
            new(identity, [member.AdmissionBindings, member.CallableBindings, member.AbsentCallables, member.ConcreteBindings, member.RecoveryBindings, member.RecoveryContext, member.ValueBindings, member.ConstructorContexts, member.OrdinaryScopedHolder, member.ReadinessSource, member.ScopedLeaseInstance]);

        private bool ContainsPotentialProducerSite(AuthoredMember member)
        {
            GraphMemberIdentity identity = MemberIdentity(member);

            ProducerSiteScanKey scanKey = ScanKey(identity, member);

            if (producerSiteScans.TryGetValue(scanKey, out bool reaches))
            {
                return reaches;
            }

            if (!producerSiteScansInProgress.Add(identity))
            {
                producerSiteScanCuts++;

                return false;
            }

            int cutsBefore = producerSiteScanCuts;

            try
            {
                reaches = ContainsPotentialProducerSite(member, []);
            }
            finally
            {
                producerSiteScansInProgress.Remove(identity);
            }

            if (producerSiteScanCuts == cutsBefore)
            {
                producerSiteScans[scanKey] = reaches;
            }

            return reaches;
        }

        private bool ContainsPotentialProducerSite(AuthoredMember member, HashSet<GraphMemberIdentity> path)
        {
            if (!path.Add(MemberIdentity(member)))
            {
                return false;
            }

            try
            {
                if (ConstructionPreambleReachesProducerSite(member, path) || AsyncBuilderReachesProducerSite(member, out _))
                {
                    return true;
                }

                foreach (SyntaxNode node in member.Syntax.DescendantNodesAndSelf(candidate => candidate == member.Syntax || candidate is not AnonymousFunctionExpressionSyntax and not LocalFunctionStatementSyntax))
                {
                    if (node is CommonForEachStatementSyntax or SpreadElementSyntax
                        && EnumerationReachesProducerSite(member, node, path))
                    {
                        return true;
                    }

                    if (ImplicitCallsAt(member, member.Syntax, node).Any(call => ImplicitCallReachesProducerSite(member, call, path))
                        || LaneImplicitCallsReachProducerSite(member, node, path)
                        || LaneRefusalsReachProducerSite(member, node, path))
                    {
                        return true;
                    }

                    // A method group names a method without calling it. Whether a body can reach a producer site through it is
                    // the question of where the delegate is called, which a scan for sites alone does not ask of the body that
                    // merely passes it (the factory handed to a Lazy runs at the first read of its value).
                    if (scanSitesOnly && member.Model.GetOperation(node) is IMethodReferenceOperation)
                    {
                        continue;
                    }

                    if (member.Model.GetSymbolInfo(node).Symbol is IMethodSymbol method)
                    {
                        string callee = Normalize(method);

                        if (Vocabulary.ContainsKey(callee)
                            || callee is "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions.CreateScope"
                                or "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions.CreateAsyncScope"
                                or "Microsoft.Extensions.DependencyInjection.IServiceScopeFactory.CreateScope"
                                or "System.IO.FileStream..ctor"
                                or "System.IO.File.Open"
                            || method.GetAttributes().Any(static attribute => attribute.AttributeClass?.Name == "GrimoireConnectionAcquisitionRouteAttribute")
                            || TryClassifyExternalProducer(method, out _))
                        {
                            return true;
                        }

                        AuthoredMember? target = Resolve(method, member.Model.Compilation);

                        if (ClassMethodDispatch(member, method, node) is { } scannedDispatch)
                        {
                            if (!scanSitesOnly && scannedDispatch.Unresolved || scannedDispatch.Targets.Any(dispatched => ContainsPotentialProducerSite(dispatched, path)))
                            {
                                return true;
                            }
                        }
                        else if (target is not null && ContainsPotentialProducerSite(target, path)
                            || target is null
                                && !scanSitesOnly
                                && !IsReviewedFrameworkRangeMember(method)
                                && RequiresExternalBoundaryClassification(
                                    method,
                                    member.Model.Compilation,
                                    node,
                                    member.Model,
                                    member))
                        {
                            return true;
                        }
                    }
                    else if (member.Model.GetSymbolInfo(node).Symbol is IPropertySymbol property
                        && (Vocabulary.ContainsKey(Normalize(property))
                            || TryClassifyExternalProducer(
                                property,
                                node.Parent is AssignmentExpressionSyntax assignment
                                    && assignment.Left == node,
                                out _)
                            || !scanSitesOnly
                                && RequiresExternalBoundaryClassification(
                                    property,
                                    member.Model.Compilation,
                                    node.Parent is AssignmentExpressionSyntax propertyMutation
                                        && propertyMutation.Left == node,
                                    node,
                                    member.Model,
                                    member)))
                    {
                        return true;
                    }
                }

                return false;
            }
            finally
            {
                path.Remove(MemberIdentity(member));
            }
        }

        private sealed class AdmissionOriginQueryContext(CleanupProvenanceContext? sharedProof = null)
        {
            private int remaining = CleanupProvenanceContext.MaximumWork;

            internal bool Complete { get; set; } = true;

            internal bool Visit()
            {
                if (Complete && (sharedProof is null ? remaining-- > 0 : sharedProof.RemainingWork-- > 0)) return true;

                Complete = false;

                return false;
            }
        }

        private IReadOnlySet<string> AdmissionOrigins(AuthoredMember member, ExpressionSyntax expression, HashSet<ISymbol> path,
            AdmissionOriginQueryContext? query = null)
        {
            if (query is not null)
            {
                return query.Visit() ? ResolveAdmissionOrigins(member, expression, path, query) : new HashSet<string>();
            }

            bool cacheable = path.Count == 0;

            GraphMemberIdentity memberIdentity = MemberIdentity(member);

            var key = (Member: memberIdentity, ExpressionStart: expression.SpanStart, ExpressionLength: expression.Span.Length, Bindings: AdmissionBindingIdentity(member));

            if (cacheable && admissionOrigins.TryGetValue(key, out IReadOnlySet<string>? cached))
            {
                return cached;
            }

            IReadOnlySet<string> resolved = ResolveAdmissionOrigins(member, expression, path, query);

            if (cacheable)
            {
                admissionOrigins[key] = resolved.ToImmutableHashSet(StringComparer.Ordinal);
            }

            return resolved;
        }

        // A parameter or local is identified by its declaration, never by its ordinal or name alone. A lambda or a local function sees the formals of
        // the method that declares it as well as its own, and two different binding maps that label their formals by ordinal alone
        // (`parameter:0 L0; parameter:1 L0`) are not the same map: one may bind the formal a body reads and the other bind nothing
        // it reads. Every cache keyed on this identity must tell them apart.
        private string AdmissionBindingIdentity(AuthoredMember member)
        {
            string scoped = member.OrdinaryScopedHolder is { } ordinary
                ? "|ordinary:" + ordinary.Identity + "|" + MethodKey(ordinary.Constructor.Symbol) : "";

            if (member.ScopedLeaseInstance is { } instance)
                scoped += "|instance:" + instance.Identity + ":" + instance.EntryPreservesAdmission + ":" + instance.ContinuationProven;

            if (member.AdmissionBindings is null)
            {
                return "unbound" + scoped;
            }

            System.Text.StringBuilder identity = new();

            identity.Append(scoped);

            static void AppendPart(System.Text.StringBuilder target, string value) => target.Append(value.Length).Append(':').Append(value);

            string Declaration(ISymbol symbol) => symbol.DeclaringSyntaxReferences.FirstOrDefault() is { } reference
                ? TreeIdentity(reference.SyntaxTree).ToString(System.Globalization.CultureInfo.InvariantCulture) + "@" + reference.Span.Start.ToString(System.Globalization.CultureInfo.InvariantCulture)
                : "external";

            foreach ((ISymbol symbol, IReadOnlySet<string> origins) in member.AdmissionBindings.OrderBy(static pair => pair.Key is IParameterSymbol parameter ? parameter.Ordinal : int.MaxValue).ThenBy(static pair => pair.Key.Kind).ThenBy(static pair => pair.Key.ToDisplayString(), StringComparer.Ordinal).ThenBy(pair => Declaration(pair.Key), StringComparer.Ordinal))
            {
                AppendPart(identity, symbol is IParameterSymbol parameter ? "parameter:" + parameter.Ordinal.ToString(System.Globalization.CultureInfo.InvariantCulture) + "@" + Declaration(parameter) : symbol.Kind + ":" + symbol.ToDisplayString() + "@" + Declaration(symbol));

                foreach (string origin in origins.Order(StringComparer.Ordinal))
                {
                    AppendPart(identity, origin);
                }

                identity.Append(';');
            }

            return identity.ToString();
        }

        private static IReadOnlyDictionary<ISymbol, IReadOnlySet<string>>?
            MergeAdmissionBindings(
                IReadOnlyDictionary<ISymbol, IReadOnlySet<string>>? inherited,
                IReadOnlyDictionary<ISymbol, IReadOnlySet<string>>? local)
        {
            if (inherited is null)
            {
                return local;
            }

            if (local is null)
            {
                return inherited;
            }

            Dictionary<ISymbol, IReadOnlySet<string>> merged = new(
                SymbolEqualityComparer.Default);

            foreach ((ISymbol symbol, IReadOnlySet<string> origins) in inherited)
            {
                merged[symbol] = origins;
            }

            foreach ((ISymbol symbol, IReadOnlySet<string> origins) in local)
            {
                merged[symbol] = merged.TryGetValue(
                        symbol,
                        out IReadOnlySet<string>? existing)
                    ? existing.Concat(origins).ToImmutableHashSet(StringComparer.Ordinal)
                    : origins;
            }

            return merged;
        }

        private IReadOnlySet<string> ResolveAdmissionOrigins(AuthoredMember member, ExpressionSyntax expression, HashSet<ISymbol> path,
            AdmissionOriginQueryContext? query = null)
        {
            SemanticModel model = expression.SyntaxTree == member.Model.SyntaxTree ? member.Model : member.Model.Compilation.GetSemanticModel(expression.SyntaxTree);

            HashSet<string> origins = new(StringComparer.Ordinal);

            if (member.ScopedLeaseInstance is { } instance)
            {
                // Exact value provenance only. The existing stable local/formal
                // facts recurse through this same query; operand ancestry cannot
                // turn a foreign projection into the tagged containing instance.
                if (IsScopedLeaseInstanceOperation(member, model.GetOperation(expression)))
                {
                    origins.Add(instance.Origin);

                    return origins;
                }

                if (query is null || model.GetOperation(expression) is not (ILocalReferenceOperation or IParameterReferenceOperation))
                    return origins;

                ISymbol? slot = model.GetSymbolInfo(expression).Symbol;

                if (slot is null || !path.Add(slot))
                {
                    query.Complete = false;

                    return origins;
                }

                try
                {
                    BoundValueSource? value;

                    if ((TryResolveStableBoundValueSource(member, expression, out value)
                            || TryResolveStableLocalInitializerValueSource(member, expression, out value))
                        && value is not null && value.Caller.ScopedLeaseInstance?.Identity == instance.Identity)
                        origins.UnionWith(AdmissionOrigins(value.Caller, value.Expression, path, query));

                    return origins;
                }
                finally
                {
                    path.Remove(slot);
                }
            }

            if (query is not null && (member.ReadinessSource is { AdmissionActive: true }
                || member.OrdinaryScopedHolder is not null))
            {
                // The independent readiness proof has its own context; do not enter it
                // as an uncharged subproof of this bounded callback-origin query.
                query.Complete = false;

                return origins;
            }

            if (member.ReadinessSource is { AdmissionActive: true, OwnedAdmission: { } own } independent
                && ReadinessLeaseReceiver(member, expression, expression.Span.End, independent, new CleanupProvenanceContext()))
                origins.Add(Location(own.Acquisition));

            if (member.OrdinaryScopedHolder is not null && ScopedAdmissionOf(member) is { } ordinary
                && ScopedAdmissionLeaseReceiver(member, expression, expression.Span.End, ordinary, new CleanupProvenanceContext()))
                origins.Add(ordinary.Origin);

            if (query is null)
            {
                origins.UnionWith(
                    ResolveReturnedAdmissionProofs(member, expression)
                        .Select(static proof => proof.Origin));
            }

            HashSet<ISymbol> references = new(SymbolEqualityComparer.Default);

            ISymbol? direct = model.GetSymbolInfo(expression).Symbol;

            if (direct is ILocalSymbol or IParameterSymbol)
            {
                references.Add(direct);
            }

            if (model.GetOperation(expression) is { } operation)
            {
                Stack<IOperation> pending = new();

                pending.Push(operation);

                while (pending.TryPop(out IOperation? current))
                {
                    if (query?.Visit() == false) return origins;

                    if (query is not null && current is IInvocationOperation)
                    {
                        // Returned-handle source/lifetime proofs are not part of this
                        // query. Unknown is a refusal, never a complete empty origin set.
                        query.Complete = false;

                        return origins;
                    }

                    if (current is IAnonymousFunctionOperation or ILocalFunctionOperation)
                    {
                        continue;
                    }

                    if (query is not null && current is IPropertyReferenceOperation unknownProperty
                        && !IsMaintenanceRevocationValueProjection(unknownProperty.Property, model.Compilation))
                    {
                        query.Complete = false;

                        return origins;
                    }

                    if (current is IPropertyReferenceOperation property
                        && IsMaintenanceRevocationValueProjection(property.Property, model.Compilation))
                    {
                        // This protocol property returns a token value, not the lease receiver.
                        // Getter and argument effects are still visited by the normal call traversal.
                        continue;
                    }

                    if (current is ILocalReferenceOperation local)
                    {
                        references.Add(local.Local);
                    }
                    else if (current is IParameterReferenceOperation parameter)
                    {
                        references.Add(parameter.Parameter);
                    }

                    foreach (IOperation child in current.ChildOperations)
                    {
                        if (query?.Visit() == false) return origins;

                        pending.Push(child);
                    }
                }
            }

            foreach (ISymbol symbol in references)
            {
                // Closed pure data cannot carry a lease or a group, whatever call produced it.
                if (HoldsHandleIncapableValue(symbol, model.Compilation)) continue;

                origins.UnionWith(AdmissionOrigins(member, symbol, model, path, query));
            }

            return origins;
        }

        private bool IsMaintenanceRevocationValueProjection(
            IPropertySymbol property,
            Compilation consumingCompilation) =>
            property.MetadataName == "MaintenanceRevocation"
            && !property.IsStatic
            && !property.IsIndexer
            && !property.ReturnsByRef
            && !property.ReturnsByRefReadonly
            && property.Parameters.IsEmpty
            && property.GetMethod is { Parameters.IsEmpty: true }
            && property.SetMethod is null
            && property.ContainingType.TypeKind == TypeKind.Interface
            && property.ContainingAssembly.Name == "RetroDownfall.Arcanum.Infrastructure"
            && IsExactAuthoredProtocolType(
                property.ContainingType,
                "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease",
                consumingCompilation)
            && IsExactFrameworkType(
                property.Type,
                "System.Threading.CancellationToken",
                typeof(CancellationToken).Assembly.GetName());

        private readonly record struct ReturnedAdmissionProof(
            string Origin,
            string WorkKind);

        private IReadOnlyList<ReturnedAdmissionProof> ResolveReturnedAdmissionProofs(
            AuthoredMember caller,
            ExpressionSyntax expression)
        {
            SemanticModel model = expression.SyntaxTree == caller.Model.SyntaxTree
                ? caller.Model
                : caller.Model.Compilation.GetSemanticModel(expression.SyntaxTree);

            if (model.GetTypeInfo(expression).Type is not { } expressionType
                || TypeKey(expressionType) !=
                "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease")
            {
                return [];
            }

            if (expression.DescendantNodesAndSelf().Any(static node =>
                node is ConditionalExpressionSyntax
                    or SwitchExpressionSyntax
                    or AssignmentExpressionSyntax
                    or BaseObjectCreationExpressionSyntax
                    || node is BinaryExpressionSyntax binary
                        && binary.IsKind(SyntaxKind.CoalesceExpression)))
            {
                return [];
            }

            List<ReturnedAdmissionProof> proofs = [];

            foreach (InvocationExpressionSyntax call in expression.DescendantNodesAndSelf()
                .OfType<InvocationExpressionSyntax>())
            {
                if (model.GetSymbolInfo(call).Symbol is not IMethodSymbol method)
                {
                    continue;
                }

                ITypeSymbol returnedType = method.ReturnType;

                if (returnedType is INamedTypeSymbol
                    {
                        TypeArguments: [ITypeSymbol result],
                    } awaitable
                    && awaitable.OriginalDefinition.ToDisplayString() is
                        "System.Threading.Tasks.Task<TResult>"
                            or "System.Threading.Tasks.ValueTask<TResult>")
                {
                    returnedType = result;
                }

                if (TypeKey(returnedType) !=
                    "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease")
                {
                    continue;
                }

                SyntaxNode completed = CompletionPreservingExpression(call, model);

                if (completed.Parent is AwaitExpressionSyntax awaited
                    && awaited.Expression == completed)
                {
                    completed = CompletionPreservingExpression(awaited, model);
                }

                if (completed != expression
                    || ResolveInvocationTarget(method, caller, call) is not { } target)
                {
                    return [];
                }

                ExpressionSyntax[] returns = target.Syntax.DescendantNodesAndSelf(node =>
                        node == target.Syntax
                        || node is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .OfType<ReturnStatementSyntax>()
                    .Select(static returned => returned.Expression)
                    .OfType<ExpressionSyntax>()
                    .ToArray();

                if (returns.Length == 0)
                {
                    return [];
                }

                ReturnedAdmissionProof? exact = null;

                foreach (ExpressionSyntax returned in returns)
                {
                    if (returned.DescendantNodesAndSelf().Any(static node =>
                        node is InvocationExpressionSyntax
                            or BaseObjectCreationExpressionSyntax
                            or ConditionalExpressionSyntax
                            or SwitchExpressionSyntax
                            or AssignmentExpressionSyntax
                            || node is BinaryExpressionSyntax binary
                                && binary.IsKind(SyntaxKind.CoalesceExpression)))
                    {
                        return [];
                    }

                    IReadOnlySet<string> origins = AdmissionOrigins(
                        target,
                        returned,
                        new HashSet<ISymbol>(SymbolEqualityComparer.Default));

                    if (origins.Count != 1)
                    {
                        return [];
                    }

                    string origin = origins.Single();

                    if (target.Syntax.DescendantNodesAndSelf()
                            .OfType<InvocationExpressionSyntax>()
                            .SingleOrDefault(candidate => Location(candidate) == origin) is not { } admission
                        || target.Model.GetSymbolInfo(admission).Symbol is not IMethodSymbol gate
                        || Normalize(gate) !=
                            "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireConnectionAdmissionGate.TryAcquireWorkLease"
                        || !IsGuardedAdmission(admission)
                        || admission.ArgumentList.Arguments.FirstOrDefault()?.Expression is not { } kindExpression
                        || target.Model.GetSymbolInfo(kindExpression).Symbol is not IFieldSymbol workKind
                        || AdmissionEndedBefore(target, origin, returned.SpanStart, []))
                    {
                        return [];
                    }

                    ReturnedAdmissionProof current = new(origin, workKind.Name);

                    if (exact is { } prior && prior != current)
                    {
                        return [];
                    }

                    exact = current;
                }

                if (exact is not { } proof)
                {
                    return [];
                }

                proofs.Add(proof);
            }

            return proofs
                .Distinct()
                .ToArray();
        }

        private bool MayContainAdmissionOrigin(AuthoredMember member)
        {
            RetainedAdmissionAnalysisCounter analysis =
                RetainedAdmissionCounter(member);

            analysis.OriginPossibilityRequests++;

            // A captured holder can terminate admission without any explicit lease
            // local/formal in this body. It is not an origin-free fast path.
            if (member.OrdinaryScopedHolder is not null || member.ScopedLeaseInstance is not null) return true;

            var key = (
                Member: MemberIdentity(member),
                Bindings: AdmissionBindingIdentity(member));

            if (admissionOriginPossibility.TryGetValue(key, out bool possible))
            {
                return possible;
            }

            analysis.OriginPossibilityBuilds++;

            possible = member.AdmissionBindings?.Values.Any(
                static origins => origins.Count > 0) == true;

            if (!possible)
            {
                possible = member.Syntax.DescendantNodesAndSelf(node =>
                        node == member.Syntax
                        || node is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .OfType<IdentifierNameSyntax>()
                    .Where(identifier => member.Model.GetSymbolInfo(identifier).Symbol
                        is ILocalSymbol or IParameterSymbol)
                    .Any(identifier => AdmissionOrigins(
                        member,
                        identifier,
                        new HashSet<ISymbol>(
                            SymbolEqualityComparer.Default)).Count > 0);
            }

            if (!possible)
            {
                foreach (InvocationExpressionSyntax call in member.Syntax
                    .DescendantNodesAndSelf()
                    .OfType<InvocationExpressionSyntax>())
                {
                    IMethodSymbol? method =
                        member.Model.GetSymbolInfo(call).Symbol as IMethodSymbol;

                    string? name = method is null ? null : Normalize(method);

                    if (name is
                            "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireConnectionAdmissionGate.TryAcquireWorkLease"
                                or "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease.TryBeginExternalEffectGroup"
                        || PotentialAdmissionHandleType(method?.ReturnType)
                        || PotentialAdmissionHandleType(
                            member.Model.GetTypeInfo(call).Type)
                        || call.Expression is MemberAccessExpressionSyntax access
                            && AdmissionOrigins(
                                member,
                                access.Expression,
                                new HashSet<ISymbol>(
                                    SymbolEqualityComparer.Default)).Count > 0
                        || call.ArgumentList.Arguments.Any(argument =>
                            PotentialAdmissionHandleType(
                                member.Model.GetTypeInfo(argument.Expression).Type))
                        || method is null
                            && call.Expression.ToString() is
                                "TryAcquireWorkLease"
                                    or "TryBeginExternalEffectGroup")
                    {
                        possible = true;

                        break;
                    }
                }
            }

            admissionOriginPossibility[key] = possible;

            return possible;
        }

        private static bool PotentialAdmissionHandleType(ITypeSymbol? type)
        {
            if (type is null)
            {
                return false;
            }

            if (TypeKey(type)
                == "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease")
            {
                return true;
            }

            return type is INamedTypeSymbol
            {
                TypeArguments: [ITypeSymbol result],
            } named
                && named.OriginalDefinition.ToDisplayString() is
                    "System.Threading.Tasks.Task<TResult>"
                        or "System.Threading.Tasks.ValueTask<TResult>"
                && TypeKey(result)
                    == "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease";
        }

        private bool HasAdmissionSeed(AuthoredMember member)
        {
            if (member.AdmissionBindings?.Values.Any(static origins => origins.Count > 0) == true)
            {
                return true;
            }

            var key = (Member: MemberIdentity(member), Bindings: AdmissionBindingIdentity(member));

            if (!admissionSeeds.TryGetValue(key, out bool seeded))
            {
                seeded = member.Syntax.DescendantNodes().OfType<InvocationExpressionSyntax>().Any(call => member.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method && Normalize(method) is "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease.TryBeginExternalEffectGroup" or "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireConnectionAdmissionGate.TryAcquireWorkLease");

                if (!seeded)
                {
                    seeded = member.Syntax.DescendantNodesAndSelf(node => node == member.Syntax || node is not AnonymousFunctionExpressionSyntax and not LocalFunctionStatementSyntax).OfType<IdentifierNameSyntax>().Select(identifier => member.Model.GetSymbolInfo(identifier).Symbol).OfType<ISymbol>().Where(static symbol => symbol is ILocalSymbol or IParameterSymbol).Distinct(SymbolEqualityComparer.Default).Any(symbol => HasAdmissionSeed(member, symbol, new HashSet<ISymbol>(SymbolEqualityComparer.Default)));
                }

                admissionSeeds[key] = seeded;
            }

            return seeded;
        }

        private static bool HasAdmissionSeed(AuthoredMember member, ISymbol symbol, HashSet<ISymbol> path)
        {
            if (!path.Add(symbol))
            {
                return false;
            }

            try
            {
                if (member.AdmissionBindings?.TryGetValue(symbol, out IReadOnlySet<string>? bound) == true && bound.Count > 0)
                {
                    return true;
                }

                SyntaxNode? declaration = symbol.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax();

                if (declaration is SingleVariableDesignationSyntax designation && designation.Ancestors().OfType<InvocationExpressionSyntax>().FirstOrDefault() is { } admission && member.Model.GetSymbolInfo(admission).Symbol is IMethodSymbol method && Normalize(method) is "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease.TryBeginExternalEffectGroup" or "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireConnectionAdmissionGate.TryAcquireWorkLease")
                {
                    return true;
                }

                if (symbol is not ILocalSymbol || declaration is not VariableDeclaratorSyntax variable)
                {
                    return false;
                }

                IEnumerable<ExpressionSyntax> values = variable.Initializer is null ? [] : [variable.Initializer.Value];

                if (variable.Ancestors().OfType<BlockSyntax>().FirstOrDefault() is { } block)
                {
                    values = values.Concat(block.DescendantNodes().OfType<AssignmentExpressionSyntax>().Where(assignment => SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(assignment.Left).Symbol, symbol)).Select(static assignment => assignment.Right));
                }

                return values.SelectMany(static value => value.DescendantNodesAndSelf().OfType<IdentifierNameSyntax>()).Select(identifier => member.Model.GetSymbolInfo(identifier).Symbol).OfType<ISymbol>().Where(static candidate => candidate is ILocalSymbol or IParameterSymbol).Distinct(SymbolEqualityComparer.Default).Any(candidate => HasAdmissionSeed(member, candidate, path));
            }
            finally
            {
                path.Remove(symbol);
            }
        }

        private IReadOnlySet<string> AdmissionOrigins(AuthoredMember member, ISymbol symbol, SemanticModel model, HashSet<ISymbol> path,
            AdmissionOriginQueryContext? query = null)
        {
            if (query?.Visit() == false) return new HashSet<string>();

            if (!path.Add(symbol))
            {
                return new HashSet<string>();
            }

            try
            {
                HashSet<string> origins = new(StringComparer.Ordinal);

                if (member.AdmissionBindings?.TryGetValue(symbol, out IReadOnlySet<string>? bound) == true)
                {
                    foreach (string origin in bound)
                    {
                        if (query?.Visit() == false) return origins;

                        origins.Add(origin);
                    }
                }

                SyntaxNode? declaration = symbol.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax();

                if (declaration is SingleVariableDesignationSyntax designation && designation.Ancestors().TakeWhile(_ => query?.Visit() != false).OfType<InvocationExpressionSyntax>().FirstOrDefault() is { } call && model.GetSymbolInfo(call).Symbol is IMethodSymbol method && Normalize(method) is "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease.TryBeginExternalEffectGroup" or "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireConnectionAdmissionGate.TryAcquireWorkLease")
                {
                    origins.Add(Location(call));
                }

                if (symbol is ILocalSymbol && declaration is VariableDeclaratorSyntax variable)
                {
                    if (variable.Initializer is not null)
                    {
                        origins.UnionWith(AdmissionOrigins(member, variable.Initializer.Value, path, query));
                    }

                    BlockSyntax? block = variable.Ancestors().TakeWhile(_ => query?.Visit() != false)
                        .OfType<BlockSyntax>().FirstOrDefault();

                    if (query is not null && (!query.Complete || block is null))
                    {
                        query.Complete = false;

                        return origins;
                    }

                    // May-alias joins deliberately retain prior origins across ambiguous assignments.
                    foreach (SyntaxNode node in (block ?? variable.Ancestors().OfType<BlockSyntax>().First()).DescendantNodes())
                    {
                        if (query?.Visit() == false) return origins;

                        if (node is AssignmentExpressionSyntax assignment
                            && SymbolEqualityComparer.Default.Equals(model.GetSymbolInfo(assignment.Left).Symbol, symbol))
                        {
                            origins.UnionWith(AdmissionOrigins(member, assignment.Right, path, query));
                        }
                    }
                }

                return origins;
            }
            finally
            {
                path.Remove(symbol);
            }
        }

        private static bool HasFiniteEnumMethodShape(IMethodSymbol method, Compilation compilation)
        {
            if (method is not { MethodKind: MethodKind.Ordinary, IsStatic: true, Arity: 1, ReducedFrom: null }
                || method.IsVirtual || method.IsOverride || method.IsAbstract || method.IsVararg
                || method.ReturnsByRef || method.ReturnsByRefReadonly
                || !SymbolEqualityComparer.Default.Equals(method, method.OriginalDefinition)
                || method.DeclaringSyntaxReferences.Length != 1
                || method.DeclaringSyntaxReferences[0].GetSyntax() is not MethodDeclarationSyntax
                || method.Parameters.Any(static parameter => parameter.RefKind != RefKind.None))
            {
                return false;
            }

            for (INamedTypeSymbol? containing = method.ContainingType; containing is not null; containing = containing.ContainingType)
            {
                if (containing.Arity != 0) return false;
            }

            ITypeParameterSymbol ownType = method.TypeParameters[0];

            return ownType.TypeParameterKind == TypeParameterKind.Method
                && SymbolEqualityComparer.Default.Equals(ownType.ContainingSymbol, method)
                && ownType.HasValueTypeConstraint
                && ownType.ConstraintTypes.Length == 1
                && SymbolEqualityComparer.Default.Equals(ownType.ConstraintTypes[0], compilation.GetSpecialType(SpecialType.System_Enum));
        }

        private static bool IsClosedFiniteEnum(ITypeSymbol? type)
        {
            if (type is not INamedTypeSymbol { TypeKind: TypeKind.Enum, Arity: 0 } enumeration) return false;

            for (INamedTypeSymbol? containing = enumeration.ContainingType; containing is not null; containing = containing.ContainingType)
            {
                if (containing.Arity != 0) return false;
            }

            return true;
        }

        private static bool IsCertifiedOwnEnumSlot(AuthoredMember member, ISymbol candidate)
        {
            return HasFiniteEnumMethodShape(member.Symbol, member.Model.Compilation)
                && SymbolEqualityComparer.Default.Equals(candidate, member.Symbol.TypeParameters[0])
                && member.ConcreteBindings?.TryGetValue(candidate, out ITypeSymbol? type) == true
                && IsClosedFiniteEnum(type);
        }

        private IReadOnlyDictionary<ISymbol, ITypeSymbol>? ClosedEnumInvocationBindings(
            AuthoredMember caller,
            InvocationExpressionSyntax call,
            AuthoredMember target)
        {
            // This is one selected invocation's finite substitution, not a type-based
            // purity rule or a change to value/ref demand. Unsupported inputs retain
            // the existing conservative binding and authored traversal paths.
            if (!HasFiniteEnumMethodShape(target.Symbol, target.Model.Compilation)
                || caller.Model.GetOperation(call) is not IInvocationOperation invocation
                || invocation.IsVirtual
                || invocation.TargetMethod.ReducedFrom is not null
                || !SymbolEqualityComparer.Default.Equals(invocation.TargetMethod.OriginalDefinition, target.Symbol)
                || invocation.TargetMethod.TypeArguments.Length != 1)
            {
                return null;
            }

            ITypeParameterSymbol targetType = target.Symbol.TypeParameters[0];

            ITypeSymbol selectedType = invocation.TargetMethod.TypeArguments[0];

            ITypeSymbol closedType = selectedType;

            if (selectedType is ITypeParameterSymbol)
            {
                // One exact caller-own slot lookup only; no recursive substitution.
                if (!HasFiniteEnumMethodShape(caller.Symbol, caller.Model.Compilation)
                    || !SymbolEqualityComparer.Default.Equals(selectedType, caller.Symbol.TypeParameters[0])
                    || caller.ConcreteBindings?.TryGetValue(selectedType, out ITypeSymbol? boundType) != true
                    || boundType is null
                    || !IsClosedFiniteEnum(boundType))
                {
                    return null;
                }

                closedType = boundType;
            }

            if (!IsClosedFiniteEnum(closedType)) return null;

            foreach (IArgumentOperation argument in invocation.Arguments)
            {
                if (argument.ArgumentKind != ArgumentKind.Explicit
                    || argument.Parameter is not { RefKind: RefKind.None } parameter
                    || parameter.Ordinal < 0 || parameter.Ordinal >= target.Symbol.Parameters.Length
                    || !SymbolEqualityComparer.Default.Equals(parameter.OriginalDefinition, target.Symbol.Parameters[parameter.Ordinal])
                    || !argument.InConversion.IsIdentity || !argument.OutConversion.IsIdentity
                    || argument.Value.DescendantsAndSelf().OfType<IConversionOperation>().Any(static conversion => !conversion.Conversion.IsIdentity))
                {
                    return null;
                }

                if (!SymbolEqualityComparer.Default.Equals(target.Symbol.Parameters[parameter.Ordinal].Type, targetType)) continue;

                if (!SymbolEqualityComparer.Default.Equals(parameter.Type, selectedType)
                    || !SymbolEqualityComparer.Default.Equals(argument.Value.Type, selectedType)) return null;

                if (argument.Value.Syntax is not ExpressionSyntax expression) return null;

                if (ConcreteType(caller, expression) is { } concrete
                    && !SymbolEqualityComparer.Default.Equals(concrete, closedType)) return null;
            }

            Dictionary<ISymbol, ITypeSymbol> bindings = new(SymbolEqualityComparer.Default)
            {
                [targetType] = closedType,
            };

            foreach (IParameterSymbol parameter in target.Symbol.Parameters)
            {
                if (SymbolEqualityComparer.Default.Equals(parameter.Type, targetType)) bindings.Add(parameter, closedType);
            }

            return bindings;
        }

        private AuthoredMember BindAdmissionArguments(
            AuthoredMember caller,
            InvocationExpressionSyntax call,
            AuthoredMember target,
            RecoveryTupleProvenanceContext? recoveryProvenance = null)
        {
            return BindArguments(
                caller,
                AdmissionArguments(caller, call),
                target,
                recoveryProvenance,
                ClosedEnumInvocationBindings(caller, call, target));
        }

        private AuthoredMember BindInvocationContext(
            AuthoredMember caller,
            InvocationExpressionSyntax call,
            AuthoredMember target,
            RecoveryTupleProvenanceContext? recoveryProvenance = null)
        {
            AuthoredMember bound = BindAdmissionArguments(
                caller,
                call,
                target,
                recoveryProvenance);

            ExpressionSyntax? written = call.Expression is MemberAccessExpressionSyntax access
                ? access.Expression
                : null;

            return BindReceiverContext(caller, written, target, bound, recoveryProvenance);
        }

        // The context the receiver of an instance member brings to the member it runs: the callables and values the receiver
        // was constructed with, which a written call and an accessor access bind the same way. A receiver that is not written
        // (an implicit this) brings the caller's own context.
        private AuthoredMember BindReceiverContext(
            AuthoredMember caller,
            ExpressionSyntax? written,
            AuthoredMember target,
            AuthoredMember bound,
            RecoveryTupleProvenanceContext? recoveryProvenance = null)
        {
            if (target.Symbol.IsStatic)
            {
                return bound.ScopedLeaseInstance is null ? bound : bound with { ScopedLeaseInstance = null };
            }

            if (target.ScopedLeaseInstance is not null) return bound;

            bool hasCallableContext = caller.CallableBindings is { Count: > 0 }
                || caller.AbsentCallables is { Count: > 0 };

            bool typeCarriesCallableState = target.Symbol.ContainingType
                    .InstanceConstructors.Any(static constructor =>
                        constructor.Parameters.Any(static parameter =>
                            parameter.Type.TypeKind == TypeKind.Delegate))
                || target.Symbol.ContainingType.GetMembers()
                    .OfType<IFieldSymbol>()
                    .Any(static field => field.Type.TypeKind == TypeKind.Delegate);

            bool typeCarriesCleanupState =
                ReceiverTargetMayCarryCleanupState(target);

            bool hasReceiverValueContext = caller.ValueBindings?.Keys.Any(
                symbol => symbol switch
                {
                    IFieldSymbol field => !field.IsStatic
                        && SymbolEqualityComparer.Default.Equals(
                            field.ContainingType,
                            target.Symbol.ContainingType),
                    IParameterSymbol
                    {
                        ContainingSymbol: IMethodSymbol
                        {
                            MethodKind: MethodKind.Constructor,
                        } constructor,
                    } => SymbolEqualityComparer.Default.Equals(
                        constructor.ContainingType,
                        target.Symbol.ContainingType),
                    _ => false,
                }) == true;

            ExpressionSyntax? receiver = written;

            bool hasBoundReceiverContext = receiver is not null
                && caller.Model.GetSymbolInfo(
                    StripTransparentExpression(receiver)).Symbol is
                { } receiverSymbol
                && caller.ValueBindings?.ContainsKey(receiverSymbol) == true;

            if (!hasCallableContext
                && !typeCarriesCallableState
                && !typeCarriesCleanupState
                && !IsLongRestSdkSetupDependency(target)
                && !hasReceiverValueContext
                && !hasBoundReceiverContext)
            {
                return bound;
            }

            AuthoredMember? receiverContext = receiver is null
                ? hasCallableContext || hasReceiverValueContext
                    ? caller
                    : null
                : ResolveConstructedReceiverContext(
                    caller,
                    receiver,
                    target.Symbol.ContainingType,
                    new HashSet<(GraphMemberIdentity Member, int Start, int Length)>(),
                    recoveryProvenance);

            if (receiverContext is null
                && receiver is not null
                && typeCarriesCleanupState)
            {
                receiverContext = ResolveExactDiReceiverConstructorContext(
                    caller,
                    receiver,
                    target);
            }

            if (receiverContext is null)
            {
                return bound;
            }

            if (typeCarriesCleanupState)
            {
                receiverContext = BindDemandedReceiverReadonlyFieldContext(
                    receiverContext,
                    target);
            }

            if (hasCallableContext || typeCarriesCallableState)
            {
                bound = MergeCallableContext(bound, receiverContext);
            }

            return MergeValueContext(bound, receiverContext);
        }

        private AuthoredMember? ResolveExactDiReceiverConstructorContext(
            AuthoredMember caller,
            ExpressionSyntax receiver,
            AuthoredMember target)
        {
            receiver = StripTransparentExpression(receiver);

            if (caller.Model.GetTypeInfo(receiver).Type is not
                    INamedTypeSymbol contract
                || !IsExactDiBoundCleanupReceiver(
                    caller,
                    receiver,
                    contract,
                    []))
            {
                return null;
            }

            BoundContractIdentity registrationKey = new(
                contract.ContainingAssembly.Identity,
                TypeKey(contract));

            ResolvedRegistration[] registrations =
                (diActivationRegistrations.TryGetValue(
                        registrationKey,
                        out List<ResolvedRegistration>? registered)
                    ? registered
                    : [])
                .DistinctBy(
                    static registration => registration.Call,
                    ReferenceEqualityComparer.Instance)
                .ToArray();

            if (registrations is not [ResolvedRegistration registration]
                || !IsExactRootFactoryRegistrationMethod(registration.Method)
                || registration.Method.TypeArguments.FirstOrDefault() is not
                { } registeredContract
                || !SameBoundType(
                    registeredContract,
                    registration.Model.Compilation,
                    contract,
                    caller.Model.Compilation))
            {
                return null;
            }

            AuthoredMember? ResolveConstruction(
                ResolvedRegistration activation)
            {
                ArgumentSyntax[] activationArguments = activation.Call
                    .ArgumentList.Arguments
                    .ToArray();

                if (activationArguments.Length == 0)
                {
                    if (activation.Method.TypeArguments.LastOrDefault() is not
                    { } registeredImplementation
                        || !SameBoundType(
                            registeredImplementation,
                            activation.Model.Compilation,
                            target.Symbol.ContainingType,
                            target.Model.Compilation))
                    {
                        return null;
                    }

                    IMethodSymbol[] constructors = target.Symbol.ContainingType
                        .InstanceConstructors
                        .Where(static constructor =>
                            !constructor.IsStatic
                            && constructor.DeclaredAccessibility
                                == Accessibility.Public)
                        .DistinctBy(
                            static constructor => constructor.OriginalDefinition,
                            SymbolEqualityComparer.Default)
                        .ToArray();

                    if (constructors is not
                            [IMethodSymbol activationConstructor]
                        || ResolveConstructorContextTarget(
                            activationConstructor,
                            target.Model.Compilation) is not { } selected)
                    {
                        return null;
                    }

                    return BindConstructedReadonlyFieldContext(selected with
                    {
                        ConstructorContexts = new HashSet<IMethodSymbol>(
                            [activationConstructor],
                            SymbolEqualityComparer.Default),
                    });
                }

                if (activationArguments is not
                        [ArgumentSyntax
                        {
                            Expression:
                                AnonymousFunctionExpressionSyntax factory,
                        }]
                    || !TryResolveExactFactoryConstruction(
                        factory,
                        activation.Model,
                        target.Symbol.ContainingType,
                        target.Model.Compilation,
                        out _,
                        out _,
                        out AuthoredMember constructionContext))
                {
                    return null;
                }

                return constructionContext;
            }

            if (ResolveConstruction(registration) is { } direct)
            {
                return direct;
            }

            if (registration.Call.ArgumentList.Arguments is not
                    [ArgumentSyntax
                    {
                        Expression: AnonymousFunctionExpressionSyntax factory,
                    }]
                || (factory switch
                    {
                        SimpleLambdaExpressionSyntax simple =>
                            registration.Model.GetDeclaredSymbol(
                                simple.Parameter),
                        ParenthesizedLambdaExpressionSyntax
                        {
                            ParameterList.Parameters:
                                [ParameterSyntax parameter],
                        } => registration.Model.GetDeclaredSymbol(parameter),
                        _ => null,
                    }) is not { } provider
                || !IsExactFrameworkType(
                    provider.Type,
                    "System.IServiceProvider",
                    typeof(IServiceProvider).Assembly.GetName())
                || ExactFactoryCreation(factory) is not { } forwardedService
                || !IsExactFactoryServiceResolution(
                    registration.Model,
                    forwardedService,
                    provider,
                    target.Symbol.ContainingType,
                    target.Model.Compilation))
            {
                return null;
            }

            BoundContractIdentity implementationKey = new(
                target.Symbol.ContainingAssembly.Identity,
                TypeKey(target.Symbol.ContainingType));

            ResolvedRegistration[] implementationRegistrations =
                (diActivationRegistrations.TryGetValue(
                        implementationKey,
                        out List<ResolvedRegistration>? implementations)
                    ? implementations
                    : [])
                .DistinctBy(
                    static candidate => candidate.Call,
                    ReferenceEqualityComparer.Instance)
                .ToArray();

            return implementationRegistrations is
                    [ResolvedRegistration implementation]
                && IsExactRootFactoryRegistrationMethod(
                    implementation.Method)
                    ? ResolveConstruction(implementation)
                    : null;
        }

        private AuthoredMember BindDemandedReceiverReadonlyFieldContext(
            AuthoredMember constructionContext,
            AuthoredMember target)
        {
            if (constructionContext.Symbol is not
                {
                    MethodKind: MethodKind.Constructor,
                })
            {
                return constructionContext;
            }

            IReadOnlyDictionary<ISymbol, BoundValueSource> available =
                constructionContext.ValueBindings
                ?? new Dictionary<ISymbol, BoundValueSource>(
                    SymbolEqualityComparer.Default);

            Dictionary<ISymbol, BoundValueSource> demanded = new(
                SymbolEqualityComparer.Default);

            foreach (ISymbol symbol in DeclaredRootDemandedConstructionBindings(
                target,
                target.Syntax,
                available.Keys))
            {
                demanded[symbol] = available[symbol];
            }

            foreach ((IFieldSymbol field, ExpressionSyntax use) in
                DeclaredRootDemandedFieldUses(target, target.Syntax, allowRelinquishedFields: true)
                    .DistinctBy(
                        static candidate => candidate.Item1,
                        SymbolEqualityComparer.Default))
            {
                BoundValueSource[] values;

                if (available.TryGetValue(
                        field,
                        out BoundValueSource? selected)
                    && selected is not null)
                {
                    values = [selected];
                }
                else if (!field.IsReadOnly)
                {
                    CleanupValueFlow? relinquished =
                        ExactAssignedFieldCleanupValueFlow(
                            constructionContext,
                            use,
                            field,
                            new CleanupProvenanceContext(),
                            allowSameOwnerLifetimeWriters:
                                HasExactSameOwnerLifetimeFieldWriterSemantics(
                                    field));

                    values = relinquished is { Complete: true }
                        ? relinquished.Values.ToArray()
                        : [];

                    if (values.Length > 1
                        && HasExactGuardedFieldReadSemantics(
                            field,
                            allowNullingAssignments: true))
                    {
                        values = ExactReadOnlyFieldValues(
                            constructionContext,
                            StripTransparentExpression(use),
                            field)
                            .Where(value => SymbolEqualityComparer.Default.Equals(
                                value.Caller.Symbol.OriginalDefinition,
                                constructionContext.Symbol.OriginalDefinition))
                            .ToArray();
                    }
                }
                else
                {
                    values = ExactReadOnlyFieldValues(
                        constructionContext,
                        StripTransparentExpression(use),
                        field)
                        .Where(value => SymbolEqualityComparer.Default.Equals(
                            value.Caller.Symbol.OriginalDefinition,
                            constructionContext.Symbol.OriginalDefinition))
                        .ToArray();
                }

                if (values is [BoundValueSource value])
                {
                    HashSet<ISymbol> dependencies =
                        DeclaredRootConstructorDependencies(
                            value,
                            constructionContext);

                    AuthoredMember stableCaller = value.Caller with
                    {
                        ValueBindings = value.Caller.ValueBindings?
                            .Where(pair => dependencies.Contains(pair.Key))
                            .ToDictionary(
                                static pair => pair.Key,
                                static pair => pair.Value,
                                SymbolEqualityComparer.Default),
                    };

                    demanded[field] = value with
                    {
                        Caller = stableCaller,
                    };
                }
            }

            return constructionContext with
            {
                ValueBindings = demanded,
            };
        }

        private IEnumerable<ISymbol> DeclaredRootDemandedConstructionBindings(
            AuthoredMember root,
            SyntaxNode selection,
            IEnumerable<ISymbol> candidates)
        {
            HashSet<ISymbol> available = new(
                candidates,
                SymbolEqualityComparer.Default);

            HashSet<ISymbol> emitted = new(SymbolEqualityComparer.Default);

            HashSet<GraphMemberIdentity> visited = [];

            Stack<(AuthoredMember Member, SyntaxNode Scope, int Depth)> pending =
                new();

            pending.Push((root, selection, 0));

            while (pending.TryPop(out var current))
            {
                if (current.Depth >= ReceiverCleanupForwardingMaximumDepth
                    || !visited.Add(MemberIdentity(current.Member)))
                {
                    continue;
                }

                foreach (ExpressionSyntax expression in current.Scope
                    .DescendantNodesAndSelf()
                    .OfType<ExpressionSyntax>())
                {
                    ISymbol? symbol = current.Member.Model
                        .GetSymbolInfo(expression).Symbol;

                    if (symbol is IParameterSymbol
                        {
                            ContainingSymbol: IMethodSymbol
                            {
                                MethodKind: MethodKind.Constructor,
                            } constructor,
                        }
                        && SymbolEqualityComparer.Default.Equals(
                            constructor.ContainingType,
                            root.Symbol.ContainingType)
                        && available.Contains(symbol)
                        && emitted.Add(symbol))
                    {
                        yield return symbol;
                    }

                    if (symbol is not IPropertySymbol
                        {
                            IsStatic: false,
                            GetMethod: { } getter,
                        } property
                        || !SymbolEqualityComparer.Default.Equals(
                            symbol.ContainingType,
                            root.Symbol.ContainingType)
                        || StripTransparentExpression(expression) is not
                            (IdentifierNameSyntax or MemberAccessExpressionSyntax
                            {
                                Expression: ThisExpressionSyntax,
                            }))
                    {
                        continue;
                    }

                    if (property.SetMethod is null
                        && property.DeclaringSyntaxReferences is [SyntaxReference propertyDeclaration]
                        && propertyDeclaration.GetSyntax() is PropertyDeclarationSyntax
                        {
                            ExpressionBody: null,
                            AccessorList.Accessors: [AccessorDeclarationSyntax
                            {
                                Body: null,
                                ExpressionBody: null,
                            } accessor],
                        }
                        && accessor.IsKind(SyntaxKind.GetAccessorDeclaration)
                        && accessor.SemicolonToken.RawKind != 0)
                    {
                        foreach (IMethodSymbol selected in available
                            .OfType<IParameterSymbol>()
                            .Select(static parameter => parameter.ContainingSymbol)
                            .OfType<IMethodSymbol>()
                            .Where(candidate => candidate.MethodKind == MethodKind.Constructor
                                && SymbolEqualityComparer.Default.Equals(
                                    candidate.ContainingType,
                                    property.ContainingType))
                            .Distinct<IMethodSymbol>(SymbolEqualityComparer.Default))
                        {
                            if (ResolveConstructorContextTarget(
                                selected,
                                current.Member.Model.Compilation) is not { } construction)
                            {
                                continue;
                            }

                            AssignmentExpressionSyntax[] assignments = construction.Syntax
                                .DescendantNodesAndSelf(node => node == construction.Syntax
                                    || node is not AnonymousFunctionExpressionSyntax
                                        and not LocalFunctionStatementSyntax)
                                .OfType<AssignmentExpressionSyntax>()
                                .Where(assignment => assignment.IsKind(SyntaxKind.SimpleAssignmentExpression)
                                    && SymbolEqualityComparer.Default.Equals(
                                        construction.Model.GetSymbolInfo(assignment.Left).Symbol,
                                        property))
                                .ToArray();

                            if (assignments is not [AssignmentExpressionSyntax assignment]
                                || !IsAssignedOnEverySuccessfulConstruction(construction, assignment))
                            {
                                continue;
                            }

                            foreach (ISymbol dependency in DeclaredRootConstructorDependencies(
                                new(construction, assignment.Right),
                                construction))
                            {
                                if (available.Contains(dependency) && emitted.Add(dependency))
                                {
                                    yield return dependency;
                                }
                            }
                        }
                    }

                    if (Resolve(getter, current.Member.Model.Compilation) is { } target)
                    {
                        pending.Push((target, target.Syntax, current.Depth + 1));
                    }
                }

                foreach (InvocationExpressionSyntax call in current.Scope
                    .DescendantNodesAndSelf()
                    .OfType<InvocationExpressionSyntax>())
                {
                    if (current.Member.Model.GetSymbolInfo(call).Symbol is not
                            IMethodSymbol method
                        || ResolveInvocationTarget(
                            method,
                            current.Member,
                            call) is not { Symbol.IsStatic: false } target
                        || !SymbolEqualityComparer.Default.Equals(
                            target.Symbol.ContainingType,
                            root.Symbol.ContainingType)
                        || StripTransparentExpression(call.Expression) is not
                            (IdentifierNameSyntax or GenericNameSyntax
                                or MemberAccessExpressionSyntax
                            {
                                Expression: ThisExpressionSyntax,
                            }))
                    {
                        continue;
                    }

                    pending.Push((target, target.Syntax, current.Depth + 1));
                }
            }
        }

        private AuthoredMember? ResolveConstructedReceiverContext(
            AuthoredMember caller,
            ExpressionSyntax expression,
            INamedTypeSymbol expectedType,
            HashSet<(GraphMemberIdentity Member, int Start, int Length)> path,
            RecoveryTupleProvenanceContext? recoveryProvenance = null)
        {
            expression = StripTransparentExpression(expression);

            var identity = (MemberIdentity(caller), expression.SpanStart, expression.Span.Length);

            if (!path.Add(identity))
            {
                return null;
            }

            try
            {
                if (expression is ThisExpressionSyntax
                    && SymbolEqualityComparer.Default.Equals(
                        caller.Symbol.ContainingType,
                        expectedType))
                {
                    return caller;
                }

                ISymbol? symbol = caller.Model.GetSymbolInfo(expression).Symbol;

                if (symbol is not null
                    && CanUseCurrentInstanceStorageBinding(symbol, expression)
                    && caller.ValueBindings?.TryGetValue(
                        symbol,
                        out BoundValueSource? boundValue) == true
                    && boundValue is not null)
                {
                    return ResolveConstructedReceiverContext(
                        boundValue.Caller,
                        ExactNonThrowingValue(boundValue.Expression),
                        expectedType,
                        path,
                        recoveryProvenance);
                }

                if (expression is ConditionalExpressionSyntax conditional)
                {
                    ExpressionSyntax[] values =
                    [conditional.WhenTrue, conditional.WhenFalse];

                    ExpressionSyntax[] nonempty = values
                        .Where(value => !IsSemanticallyEmptyCleanupValue(
                            caller.Model,
                            value))
                        .ToArray();

                    if (nonempty.Length == 0)
                    {
                        return null;
                    }

                    AuthoredMember? exact = null;

                    foreach (ExpressionSyntax value in nonempty)
                    {
                        AuthoredMember? candidate =
                            ResolveConstructedReceiverContext(
                                caller,
                                value,
                                expectedType,
                                path,
                                recoveryProvenance);

                        if (candidate is null)
                        {
                            return null;
                        }

                        if (exact is not null)
                        {
                            EvaluationEnvironmentFingerprint prior =
                                EvaluationEnvironmentIdentity(exact);

                            EvaluationEnvironmentFingerprint current =
                                EvaluationEnvironmentIdentity(candidate);

                            if (!prior.Complete
                                || prior.ContainsBackreference
                                || !current.Complete
                                || current.ContainsBackreference
                                || prior.Identity != current.Identity)
                            {
                                return null;
                            }
                        }

                        exact = candidate;
                    }

                    return exact;
                }

                if (expression is BaseObjectCreationExpressionSyntax creation
                    && caller.Model.GetSymbolInfo(creation).Symbol is IMethodSymbol constructor
                    && SymbolEqualityComparer.Default.Equals(
                        constructor.ContainingType,
                        expectedType)
                    && (ResolveConstructorContextTarget(
                            constructor,
                            caller.Model.Compilation)
                        ?? ImplicitConstructorContext(
                            constructor,
                            creation,
                            caller.Model)) is { } target)
                {
                    return BindConstructedReadonlyFieldContext(
                        BindCleanupConstructorArguments(
                            caller,
                            creation,
                            target));
                }

                if (expression is InvocationExpressionSyntax invocation
                    && caller.Model.GetSymbolInfo(invocation).Symbol is IMethodSymbol method
                    && ResolveInvocationTarget(method, caller, invocation) is { } factory)
                {
                    AuthoredMember boundFactory = BindInvocationContext(
                        caller,
                        invocation,
                        factory,
                        recoveryProvenance);

                    ExpressionSyntax[] returned = ReturnedExpressions(factory.Syntax);

                    AuthoredMember? exact = null;

                    foreach (ExpressionSyntax value in returned)
                    {
                        AuthoredMember? candidate = ResolveConstructedReceiverContext(
                            boundFactory,
                            value,
                            expectedType,
                            path,
                            recoveryProvenance);

                        if (candidate is null)
                        {
                            return null;
                        }

                        if (exact is not null
                            && CallableContextIdentity(exact)
                                != CallableContextIdentity(candidate))
                        {
                            return null;
                        }

                        exact = candidate;
                    }

                    return exact;
                }

                if (symbol is IPropertySymbol
                    {
                        IsStatic: false,
                        SetMethod: null,
                    } assignedProperty
                    && SymbolEqualityComparer.Default.Equals(
                        assignedProperty.Type,
                        expectedType))
                {
                    ExpressionSyntax[] initializers = assignedProperty
                        .DeclaringSyntaxReferences
                        .Select(static reference => reference.GetSyntax())
                        .OfType<PropertyDeclarationSyntax>()
                        .Select(static declaration => declaration.Initializer?.Value)
                        .OfType<ExpressionSyntax>()
                        .ToArray();

                    (AssignmentExpressionSyntax Assignment, AuthoredMember Constructor)[]
                        assignments = AuthoredMembers
                            .Where(member =>
                                member.Symbol.MethodKind == MethodKind.Constructor
                                && SymbolEqualityComparer.Default.Equals(
                                    member.Symbol.ContainingType,
                                    assignedProperty.ContainingType))
                            .SelectMany(member => member.Syntax
                                .DescendantNodesAndSelf(node =>
                                    node == member.Syntax
                                    || node is not AnonymousFunctionExpressionSyntax
                                        and not LocalFunctionStatementSyntax)
                                .OfType<AssignmentExpressionSyntax>()
                                .Where(assignment => assignment.IsKind(
                                        SyntaxKind.SimpleAssignmentExpression)
                                    && SymbolEqualityComparer.Default.Equals(
                                        member.Model.GetSymbolInfo(
                                            assignment.Left).Symbol,
                                        assignedProperty))
                                .Select(assignment => (assignment, member)))
                            .ToArray();

                    (ExpressionSyntax Expression, SemanticModel Model)? value =
                        initializers is [ExpressionSyntax propertyInitializer]
                            && assignments.Length == 0
                                ? (
                                    propertyInitializer,
                                    semanticModels[propertyInitializer.SyntaxTree])
                                : initializers.Length == 0
                                    && assignments is
                                    [
                                        (
                                            AssignmentExpressionSyntax assignment,
                                            AuthoredMember propertyConstructor
                                        ),
                                    ]
                                    && IsAssignedOnEverySuccessfulConstruction(
                                        propertyConstructor,
                                        assignment)
                                        ? (assignment.Right, propertyConstructor.Model)
                                        : null;

                    if (value is { } exactValue)
                    {
                        return ResolveConstructedReceiverContext(
                            caller with
                            {
                                Syntax = exactValue.Expression,
                                Model = exactValue.Model,
                            },
                            exactValue.Expression,
                            expectedType,
                            path,
                            recoveryProvenance);
                    }
                }

                if (expression is MemberAccessExpressionSyntax
                        && symbol is IPropertySymbol
                    || symbol is IFieldSymbol { IsReadOnly: true, IsStatic: false }
                    || symbol is ILocalSymbol)
                {
                    CleanupValueFlow propertyValue = CleanupValueFlowOf(
                        caller,
                        expression,
                        new CleanupProvenanceContext());

                    if (!propertyValue.Complete
                        && !IsFailureGuardedSuccessfulValueAccess(
                            caller,
                            expression))
                    {
                        return null;
                    }

                    AuthoredMember? exact = null;

                    Compilation expectedCompilation = expectedType
                        .DeclaringSyntaxReferences.FirstOrDefault() is
                    { SyntaxTree: { } expectedTree }
                        && semanticModels.TryGetValue(
                            expectedTree,
                            out SemanticModel? expectedModel)
                            ? expectedModel.Compilation
                            : caller.Model.Compilation;

                    foreach (BoundValueSource propertySource in
                        propertyValue.Values)
                    {
                        ExpressionSyntax propertyExpression =
                            ExactNonThrowingValue(propertySource.Expression);

                        ITypeSymbol? propertyType = propertySource.Caller.Model
                            .GetTypeInfo(propertyExpression).Type;

                        if (propertyType is null
                            || !SameBoundType(
                                propertyType,
                                propertySource.Caller.Model.Compilation,
                                expectedType,
                                expectedCompilation))
                        {
                            continue;
                        }

                        AuthoredMember? candidate =
                            ResolveConstructedReceiverContext(
                                propertySource.Caller,
                                propertyExpression,
                                expectedType,
                                path,
                                recoveryProvenance);

                        if (candidate is null)
                        {
                            return null;
                        }

                        if (exact is not null)
                        {
                            EvaluationEnvironmentFingerprint prior =
                                EvaluationEnvironmentIdentity(exact);

                            EvaluationEnvironmentFingerprint current =
                                EvaluationEnvironmentIdentity(candidate);

                            if (!prior.Complete
                                || prior.ContainsBackreference
                                || !current.Complete
                                || current.ContainsBackreference
                                || prior.Identity != current.Identity)
                            {
                                return null;
                            }
                        }

                        exact = candidate;
                    }

                    return exact;
                }

                if (symbol is ILocalSymbol local
                    && local.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                        is VariableDeclaratorSyntax
                    {
                        Initializer.Value: { } initializer,
                    } variable
                    && !variable.Ancestors().OfType<BlockSyntax>().First()
                        .DescendantNodes().OfType<AssignmentExpressionSyntax>()
                        .Any(assignment => SymbolEqualityComparer.Default.Equals(
                            caller.Model.GetSymbolInfo(assignment.Left).Symbol,
                            local)))
                {
                    return ResolveConstructedReceiverContext(
                        caller,
                        initializer,
                        expectedType,
                        path,
                        recoveryProvenance);
                }

                if (symbol is IFieldSymbol field
                    && SymbolEqualityComparer.Default.Equals(field.Type, expectedType))
                {
                    List<(ExpressionSyntax Expression, SemanticModel Model)> values = [];

                    foreach (SyntaxReference reference in field.DeclaringSyntaxReferences)
                    {
                        if (reference.GetSyntax() is VariableDeclaratorSyntax
                            {
                                Initializer.Value: { } fieldInitializer,
                            })
                        {
                            values.Add((
                                fieldInitializer,
                                semanticModels[fieldInitializer.SyntaxTree]));
                        }
                    }

                    values.AddRange(AuthoredMembers
                        .Where(member =>
                            member.Symbol.MethodKind == MethodKind.Constructor
                            && SymbolEqualityComparer.Default.Equals(
                                member.Symbol.ContainingType,
                                field.ContainingType))
                        .SelectMany(member => member.Syntax.DescendantNodesAndSelf()
                            .OfType<AssignmentExpressionSyntax>()
                            .Where(assignment =>
                                assignment.IsKind(
                                    SyntaxKind.SimpleAssignmentExpression)
                                && SymbolEqualityComparer.Default.Equals(
                                    member.Model.GetSymbolInfo(
                                        assignment.Left).Symbol,
                                    field))
                            .Select(assignment => (
                                assignment.Right,
                                member.Model))));

                    if (values.Count != 1)
                    {
                        return null;
                    }

                    return ResolveConstructedReceiverContext(
                        caller with
                        {
                            Syntax = values[0].Expression,
                            Model = values[0].Model,
                        },
                        values[0].Expression,
                        expectedType,
                        path,
                        recoveryProvenance);
                }

                return null;
            }
            finally
            {
                _ = path.Remove(identity);
            }
        }

        private static bool CanUseCurrentInstanceStorageBinding(ISymbol symbol, ExpressionSyntax expression)
        {
            if (symbol is not IFieldSymbol { IsStatic: false } and not IPropertySymbol { IsStatic: false })
            {
                return true;
            }

            expression = StripTransparentExpression(expression);

            // A storage symbol identifies a slot, not its receiver. In particular the
            // Name child of other.Client still resolves to this same property symbol.
            return expression is MemberAccessExpressionSyntax { Expression: ThisExpressionSyntax }
                || expression is IdentifierNameSyntax identifier
                    && (identifier.Parent is not MemberAccessExpressionSyntax access || access.Name != identifier)
                    && identifier.Parent is not MemberBindingExpressionSyntax;
        }

        private bool IsFailureGuardedSuccessfulValueAccess(
            AuthoredMember member,
            ExpressionSyntax expression)
        {
            expression = StripTransparentExpression(expression);

            ISymbol? symbol = member.Model.GetSymbolInfo(expression).Symbol;

            if (symbol is not null
                && CanUseCurrentInstanceStorageBinding(symbol, expression)
                && member.ValueBindings?.TryGetValue(
                    symbol,
                    out BoundValueSource? bound) == true
                && bound is not null)
            {
                return IsFailureGuardedSuccessfulValueAccess(
                    bound.Caller,
                    bound.Expression);
            }

            ILocalSymbol[] resultLocals = expression
                .DescendantNodesAndSelf()
                .OfType<MemberAccessExpressionSyntax>()
                .Where(static access =>
                    access.Name.Identifier.ValueText == "Value")
                .Select(access =>
                    member.Model.GetSymbolInfo(access.Expression).Symbol)
                .OfType<ILocalSymbol>()
                .Cast<ISymbol>()
                .Distinct(SymbolEqualityComparer.Default)
                .OfType<ILocalSymbol>()
                .ToArray();

            if (resultLocals is not [ILocalSymbol result]
                || result.DeclaringSyntaxReferences.SingleOrDefault()
                    ?.GetSyntax() is not { } resultDeclaration)
            {
                return false;
            }

            StatementSyntax[] declarationStatements = resultDeclaration
                .Ancestors().OfType<StatementSyntax>().ToArray();

            BlockSyntax? block = expression.Ancestors()
                .OfType<BlockSyntax>()
                .FirstOrDefault(candidate => declarationStatements.Any(
                    statement => statement.Parent == candidate));

            if (block is null
                || block.Statements.FirstOrDefault(statement =>
                    statement.Span.Contains(expression.Span)) is not
                    { } useStatement
                || declarationStatements.FirstOrDefault(statement =>
                    statement.Parent == block) is not
                    { } declarationStatement)
            {
                return false;
            }

            int declarationIndex = block.Statements.IndexOf(
                declarationStatement);

            int useIndex = block.Statements.IndexOf(useStatement);

            IfStatementSyntax[] guards = block.Statements
                .OfType<IfStatementSyntax>()
                .Where(guard =>
                    block.Statements.IndexOf(guard) > declarationIndex
                    && block.Statements.IndexOf(guard) < useIndex
                    && ExactPropertyPath(
                        member,
                        guard.Condition,
                        result,
                        "IsFailure")
                    && DefinitelyTerminates(guard.Statement)
                    && SymbolIsStableBetween(
                        member,
                        result,
                        guard.Span.End,
                        expression))
                .ToArray();

            return declarationIndex >= 0
                && useIndex > declarationIndex
                && guards.Length == 1;
        }

        private static bool TypeMayCarryCleanupProvenance(ITypeSymbol type)
        {
            if (TypeKey(type) is "System.IDisposable" or "System.IAsyncDisposable")
            {
                return true;
            }

            return type is INamedTypeSymbol named
                && named.AllInterfaces.Any(static contract =>
                    TypeKey(contract) is
                        "System.IDisposable" or "System.IAsyncDisposable");
        }

        private AuthoredMember BindConstructedReadonlyFieldContext(
            AuthoredMember constructor)
        {
            Dictionary<ISymbol, BoundValueSource> values =
                constructor.ValueBindings?.ToDictionary(
                    static pair => pair.Key,
                    static pair => pair.Value,
                    SymbolEqualityComparer.Default)
                ?? new(SymbolEqualityComparer.Default);

            bool delegated = false;

            if (constructor.Syntax is ConstructorDeclarationSyntax
                {
                    Initializer: { } initializer,
                }
                && initializer.ThisOrBaseKeyword.IsKind(
                    SyntaxKind.ThisKeyword)
                && constructor.Model.GetSymbolInfo(initializer).Symbol is
                    IMethodSymbol delegatedConstructor
                && SymbolEqualityComparer.Default.Equals(
                    delegatedConstructor.ContainingType,
                    constructor.Symbol.ContainingType)
                && ResolveConstructorContextTarget(
                    delegatedConstructor,
                    constructor.Model.Compilation) is { } delegatedTarget)
            {
                (ExpressionSyntax Expression, IParameterSymbol? Parameter, RefKind RefKind)[]
                    arguments = initializer.ArgumentList.Arguments.Select(argument =>
                    {
                        IParameterSymbol? parameter =
                            (constructor.Model.GetOperation(argument) as
                                IArgumentOperation)?.Parameter;

                        RefKind refKind = argument.RefKindKeyword.Kind() switch
                        {
                            SyntaxKind.RefKeyword => RefKind.Ref,
                            SyntaxKind.OutKeyword => RefKind.Out,
                            _ => RefKind.None,
                        };

                        return (argument.Expression, parameter, refKind);
                    }).ToArray();

                AuthoredMember boundDelegated = BindArguments(
                    constructor,
                    arguments,
                    delegatedTarget);

                boundDelegated = AddCleanupValueBindings(
                    constructor,
                    arguments,
                    delegatedTarget,
                    boundDelegated);

                boundDelegated = BindConstructedReadonlyFieldContext(
                    boundDelegated);

                foreach ((ISymbol symbol, BoundValueSource value) in
                    boundDelegated.ValueBindings
                        ?? Enumerable.Empty<KeyValuePair<ISymbol, BoundValueSource>>())
                {
                    if (symbol is IFieldSymbol)
                    {
                        values[symbol] = value;
                    }
                }

                HashSet<IMethodSymbol> constructorContexts = new(
                    constructor.ConstructorContexts
                        ?? Enumerable.Empty<IMethodSymbol>(),
                    SymbolEqualityComparer.Default);

                constructorContexts.UnionWith(
                    boundDelegated.ConstructorContexts
                        ?? Enumerable.Empty<IMethodSymbol>());

                constructor = constructor with
                {
                    ConstructorContexts = constructorContexts,
                };

                delegated = true;
            }

            foreach (IFieldSymbol field in constructor.Symbol.ContainingType
                .GetMembers()
                .OfType<IFieldSymbol>()
                .Where(static field => !field.IsStatic
                    && field.IsReadOnly
                    && field.DeclaredAccessibility == Accessibility.Private
                    && (TypeMayCarryCleanupProvenance(field.Type)
                        || RequiresSourceProvenance(field.Type))))
            {
                if (field.ContainingType.DeclaringSyntaxReferences.Any(reference =>
                    !semanticModels.TryGetValue(reference.SyntaxTree, out SemanticModel? model)
                    || HasUnreviewedFieldReference(reference.GetSyntax(), model, field)))
                {
                    values.Remove(field);

                    continue;
                }

                ExpressionSyntax[] initializers = field.DeclaringSyntaxReferences
                    .Select(static reference => reference.GetSyntax())
                    .OfType<VariableDeclaratorSyntax>()
                    .Select(static declaration => declaration.Initializer?.Value)
                    .OfType<ExpressionSyntax>()
                    .ToArray();

                AssignmentExpressionSyntax[] assignments = constructor.Syntax
                    .DescendantNodesAndSelf(node => node == constructor.Syntax
                        || node is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .OfType<AssignmentExpressionSyntax>()
                    .Where(assignment => assignment.IsKind(
                            SyntaxKind.SimpleAssignmentExpression)
                        && SymbolEqualityComparer.Default.Equals(
                            constructor.Model.GetSymbolInfo(
                                assignment.Left).Symbol,
                            field))
                    .ToArray();

                ExpressionSyntax? value = initializers.Length == 1
                        && assignments.Length == 0
                        && !delegated
                    ? initializers[0]
                    : assignments is
                            [AssignmentExpressionSyntax assignment]
                        && IsAssignedOnEverySuccessfulConstruction(
                            constructor,
                            assignment)
                            ? assignment.Right
                            : null;

                if (value is not null)
                {
                    values[field] = new(ValueExpressionContext(constructor, value), value);
                }
                else if (assignments.Length != 0)
                {
                    values.Remove(field);
                }
            }

            return constructor with
            {
                ValueBindings = values,
            };
        }

        private static AuthoredMember ValueExpressionContext(
            AuthoredMember member,
            ExpressionSyntax expression,
            SemanticModel? sourceModel = null)
        {
            SemanticModel model = sourceModel
                ?? (expression.SyntaxTree == member.Model.SyntaxTree
                    ? member.Model
                    : member.Model.Compilation.GetSemanticModel(expression.SyntaxTree));

            if (ReferenceEquals(model, member.Model)
                && expression.SyntaxTree == member.Syntax.SyntaxTree)
            {
                return member;
            }

            // Partial-type initializers must carry both their semantic model and
            // syntax identity, while retaining the constructor's bound arguments.
            return member with
            {
                Syntax = expression,
                Model = model,
            };
        }

        private AuthoredMember? ResolveConstructorContextTarget(
            IMethodSymbol constructor,
            Compilation consumingCompilation)
        {
            if (Resolve(constructor, consumingCompilation) is { } authored)
            {
                return authored;
            }

            SyntaxNode? declaration = constructor.DeclaringSyntaxReferences
                .Select(static reference => reference.GetSyntax())
                .SingleOrDefault(static syntax =>
                    syntax is TypeDeclarationSyntax
                    {
                        ParameterList: not null,
                    });

            return declaration is TypeDeclarationSyntax
            {
                ParameterList: { } parameters,
            }
                ? new(
                    constructor,
                    parameters,
                    semanticModels[parameters.SyntaxTree])
                : null;
        }

        private static AuthoredMember? ImplicitConstructorContext(
            IMethodSymbol constructor,
            BaseObjectCreationExpressionSyntax creation,
            SemanticModel model) =>
            constructor.IsImplicitlyDeclared
                && constructor.MethodKind == MethodKind.Constructor
                && constructor.Parameters.Length == 0
                    ? new(
                        constructor,
                        creation,
                        model,
                        ConstructorContexts: new HashSet<IMethodSymbol>(
                            [constructor],
                            SymbolEqualityComparer.Default))
                    : null;

        private static ExpressionSyntax[] ReturnedExpressions(SyntaxNode syntax)
        {
            ExpressionSyntax? expressionBody = syntax switch
            {
                MethodDeclarationSyntax method => method.ExpressionBody?.Expression,
                LocalFunctionStatementSyntax local => local.ExpressionBody?.Expression,
                AccessorDeclarationSyntax accessor => accessor.ExpressionBody?.Expression,
                ConversionOperatorDeclarationSyntax conversion =>
                    conversion.ExpressionBody?.Expression,
                ExpressionSyntax expression => expression,
                _ => null,
            };

            if (expressionBody is not null)
            {
                return [expressionBody];
            }

            return syntax.DescendantNodes(node =>
                    node == syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<ReturnStatementSyntax>()
                .Select(static returned => returned.Expression)
                .OfType<ExpressionSyntax>()
                .ToArray();
        }

        private (AuthoredMember Member, ExpressionSyntax[] Returns)
            ExactSqlitePatternArmReturns(
                AuthoredMember member,
                ExpressionSyntax[] returned,
                CleanupProvenanceContext context)
        {
            if (member.Syntax is not MethodDeclarationSyntax
                {
                    Body: { } body,
                }
                || returned is not [ExpressionSyntax branchValue, ExpressionSyntax fallback]
                || body.Statements.OfType<IfStatementSyntax>()
                    .Take(2)
                    .ToArray() is not
                    [
                    {
                        Else: null,
                        Condition: { } condition,
                        Statement: { } branch,
                    } selection,
                    ]
                || StripTransparentExpression(condition) is not
                    IsPatternExpressionSyntax
                {
                    Expression: { } tested,
                    Pattern: DeclarationPatternSyntax
                    {
                        Type: { } declaredType,
                        Designation: SingleVariableDesignationSyntax
                                designation,
                    },
                }
                || UnconditionalReturnExpression(branch) is not { } selected
                || selected.SyntaxTree != branchValue.SyntaxTree
                || selected.Span != branchValue.Span
                || fallback.Parent is not ReturnStatementSyntax
                {
                    Parent: BlockSyntax fallbackBlock,
                }
                || fallbackBlock != body
                || fallback.SpanStart <= selection.Span.End
                || member.Model.GetSymbolInfo(tested).Symbol is not
                    IParameterSymbol
                {
                    Type: { } parameterType,
                } parameter
                || TypeKey(parameterType) != "System.Data.Common.DbConnection"
                || member.Model.GetTypeInfo(declaredType).Type is not
                { } patternType
                || TypeKey(patternType)
                    != "Microsoft.Data.Sqlite.SqliteConnection"
                || patternType.Locations.Any(static location =>
                    location.IsInSource)
                || !AssemblyIdentityMatches(
                    patternType.ContainingAssembly.Identity,
                    typeof(Microsoft.Data.Sqlite.SqliteConnection)
                        .Assembly.GetName())
                || member.Model.GetDeclaredSymbol(designation) is not
                    ILocalSymbol patternLocal
                || !RecoveryTupleSourceIsStable(
                    member,
                    parameter,
                    tested,
                    allowSimpleLocalAssignments: false)
                || !RecoveryTupleSourceIsStable(
                    member,
                    patternLocal,
                    selected,
                    allowSimpleLocalAssignments: false))
            {
                return (member, returned);
            }

            CleanupProvenance testedProvenance = CleanupProvenanceOf(
                member,
                tested,
                context);

            if (!testedProvenance.Complete
                || testedProvenance.Candidates is not
                    [CleanupTypeCandidate exact]
                || TypeKey(exact.Type)
                    != "Microsoft.Data.Sqlite.SqliteConnection"
                || exact.Type.Locations.Any(static location =>
                    location.IsInSource)
                || !AssemblyIdentityMatches(
                    exact.Type.ContainingAssembly.Identity,
                    typeof(Microsoft.Data.Sqlite.SqliteConnection)
                        .Assembly.GetName())
                || !SameBoundType(
                    exact.Type,
                    member.Model.Compilation,
                    patternType,
                    member.Model.Compilation))
            {
                return (member, returned);
            }

            Dictionary<ISymbol, ITypeSymbol> concrete =
                member.ConcreteBindings?.ToDictionary(
                    static pair => pair.Key,
                    static pair => pair.Value,
                    SymbolEqualityComparer.Default)
                ?? new(SymbolEqualityComparer.Default);

            concrete[patternLocal] = exact.Type;

            return (
                member with
                {
                    ConcreteBindings = concrete,
                },
                [selected]);
        }

        private static ExpressionSyntax? UnconditionalReturnExpression(
            StatementSyntax statement) => statement switch
            {
                ReturnStatementSyntax
                {
                    Expression: { } expression,
                } => expression,
                BlockSyntax
                {
                    Statements:
                    [
                        ReturnStatementSyntax
                    {
                        Expression: { } expression,
                    },
                    ],
                } => expression,
                _ => null,
            };

        private static string CallableContextIdentity(AuthoredMember member)
        {
            IEnumerable<string> bound = member.CallableBindings?
                .OrderBy(static pair => pair.Key.ToDisplayString(), StringComparer.Ordinal)
                .Select(static pair => pair.Key.ToDisplayString()
                    + "="
                    + MethodKey(pair.Value.Symbol))
                ?? [];

            IEnumerable<string> absent = member.AbsentCallables?
                .OrderBy(static symbol => symbol.ToDisplayString(), StringComparer.Ordinal)
                .Select(static symbol => symbol.ToDisplayString())
                ?? [];

            return string.Join(";", bound)
                + "|absent:"
                + string.Join(";", absent);
        }

        private static AuthoredMember MergeCallableContext(
            AuthoredMember target,
            AuthoredMember source)
        {
            Dictionary<ISymbol, AuthoredMember> callables = source.CallableBindings?
                .ToDictionary(
                    static pair => pair.Key,
                    static pair => pair.Value,
                    SymbolEqualityComparer.Default)
                ?? new(SymbolEqualityComparer.Default);

            foreach ((ISymbol symbol, AuthoredMember callable) in
                target.CallableBindings ??
                    Enumerable.Empty<KeyValuePair<ISymbol, AuthoredMember>>())
            {
                callables[symbol] = callable;
            }

            HashSet<ISymbol> absent = new(
                source.AbsentCallables ?? Enumerable.Empty<ISymbol>(),
                SymbolEqualityComparer.Default);

            absent.UnionWith(
                target.AbsentCallables ?? Enumerable.Empty<ISymbol>());

            foreach (ISymbol callable in callables.Keys)
            {
                absent.Remove(callable);
            }

            return target with
            {
                CallableBindings = callables,
                AbsentCallables = absent,
            };
        }

        private static AuthoredMember MergeValueContext(
            AuthoredMember target,
            AuthoredMember source)
        {
            Dictionary<ISymbol, BoundValueSource> values =
                target.ValueBindings?.ToDictionary(
                    static pair => pair.Key,
                    static pair => pair.Value,
                    SymbolEqualityComparer.Default)
                ?? new(SymbolEqualityComparer.Default);

            foreach ((ISymbol symbol, BoundValueSource value) in
                source.ValueBindings
                    ?? Enumerable.Empty<KeyValuePair<ISymbol, BoundValueSource>>())
            {
                values[symbol] = value;
            }

            HashSet<INamedTypeSymbol> sourceTypes = new(
                source.ConstructorContexts?
                    .Select(static constructor => constructor.ContainingType)
                    ?? Enumerable.Empty<INamedTypeSymbol>(),
                SymbolEqualityComparer.Default);

            HashSet<IMethodSymbol> constructors = new(
                (target.ConstructorContexts
                    ?? Enumerable.Empty<IMethodSymbol>())
                .Where(constructor => !sourceTypes.Contains(
                    constructor.ContainingType)),
                SymbolEqualityComparer.Default);

            constructors.UnionWith(
                source.ConstructorContexts
                    ?? Enumerable.Empty<IMethodSymbol>());

            return target with
            {
                ValueBindings = values,
                ConstructorContexts = constructors,
            };
        }

        private AuthoredMember BindStableCapturedCleanupContext(
            AuthoredMember caller,
            ExpressionSyntax use,
            AuthoredMember target)
        {
            HashSet<ISymbol> referenced = target.Syntax
                .DescendantNodesAndSelf(node => node == target.Syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<ExpressionSyntax>()
                .Select(expression =>
                    target.Model.GetSymbolInfo(expression).Symbol)
                .OfType<ISymbol>()
                .ToHashSet(SymbolEqualityComparer.Default);

            if (caller.ValueBindings is { Count: > 0 })
            {
                referenced.UnionWith(DeclaredRootDemandedConstructionBindings(
                    target,
                    target.Syntax,
                    caller.ValueBindings.Keys));
            }

            bool capturesCallerInstance = referenced.Any(symbol =>
                !symbol.IsStatic
                && SymbolEqualityComparer.Default.Equals(
                    symbol.ContainingType,
                    caller.Symbol.ContainingType));

            Dictionary<ISymbol, BoundValueSource> values =
                target.ValueBindings?.ToDictionary(
                    static pair => pair.Key,
                    static pair => pair.Value,
                    SymbolEqualityComparer.Default)
                ?? new(SymbolEqualityComparer.Default);

            Dictionary<ISymbol, ITypeSymbol> concrete =
                target.ConcreteBindings?.ToDictionary(
                    static pair => pair.Key,
                    static pair => pair.Value,
                    SymbolEqualityComparer.Default)
                ?? new(SymbolEqualityComparer.Default);

            foreach ((ISymbol symbol, BoundValueSource value) in
                caller.ValueBindings
                    ?? Enumerable.Empty<KeyValuePair<ISymbol, BoundValueSource>>())
            {
                if ((referenced.Contains(symbol)
                        || capturesCallerInstance
                            && symbol is IFieldSymbol field
                            && SymbolEqualityComparer.Default.Equals(
                                field.ContainingType,
                                caller.Symbol.ContainingType))
                    && RecoveryTupleSourceIsStable(
                        caller,
                        symbol,
                        use,
                        allowSimpleLocalAssignments: false))
                {
                    values[symbol] = value;
                }
            }

            foreach (ExpressionSyntax captured in target.Syntax
                .DescendantNodesAndSelf(node => node == target.Syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<ExpressionSyntax>())
            {
                ISymbol? symbol = target.Model.GetSymbolInfo(captured).Symbol;

                if (symbol is not ILocalSymbol and not IParameterSymbol
                    || ExactDirectRuntimeTypeGuardedProvenance(
                        caller,
                        use,
                        symbol) is not
                        {
                            Complete: true,
                            Candidates: [CleanupTypeCandidate exact],
                        })
                {
                    continue;
                }

                concrete[symbol] = exact.Type;
            }

            foreach ((ISymbol symbol, ITypeSymbol type) in
                caller.ConcreteBindings
                    ?? Enumerable.Empty<KeyValuePair<ISymbol, ITypeSymbol>>())
            {
                if (referenced.Contains(symbol)
                    && RecoveryTupleSourceIsStable(
                        caller,
                        symbol,
                        use,
                        allowSimpleLocalAssignments: false))
                {
                    concrete[symbol] = type;
                }
            }

            return target with
            {
                ConcreteBindings = concrete,
                ValueBindings = values,
                ReadinessSource = capturesCallerInstance ? caller.ReadinessSource : null,
            };
        }

        private AuthoredMember BindResolvedCallableInvocationContext(
            AuthoredMember caller,
            InvocationExpressionSyntax call,
            AuthoredMember target)
        {
            (ExpressionSyntax Expression, IParameterSymbol? Parameter, RefKind RefKind)[]
                arguments = AdmissionArguments(caller, call).ToArray();

            AuthoredMember bound = BindArguments(
                caller,
                arguments,
                target);

            Dictionary<ISymbol, BoundValueSource> carriedValues =
                target.ValueBindings?.ToDictionary(
                    static pair => pair.Key,
                    static pair => pair.Value,
                    SymbolEqualityComparer.Default)
                ?? new(SymbolEqualityComparer.Default);

            foreach ((ISymbol symbol, BoundValueSource value) in
                bound.ValueBindings
                    ?? Enumerable.Empty<KeyValuePair<ISymbol, BoundValueSource>>())
            {
                carriedValues[symbol] = value;
            }

            Dictionary<ISymbol, ITypeSymbol> carriedConcrete =
                target.ConcreteBindings?.ToDictionary(
                    static pair => pair.Key,
                    static pair => pair.Value,
                    SymbolEqualityComparer.Default)
                ?? new(SymbolEqualityComparer.Default);

            foreach ((ISymbol symbol, ITypeSymbol value) in
                bound.ConcreteBindings
                    ?? Enumerable.Empty<KeyValuePair<ISymbol, ITypeSymbol>>())
            {
                carriedConcrete[symbol] = value;
            }

            Dictionary<ISymbol, AuthoredMember> carriedCallables =
                target.CallableBindings?.ToDictionary(
                    static pair => pair.Key,
                    static pair => pair.Value,
                    SymbolEqualityComparer.Default)
                ?? new(SymbolEqualityComparer.Default);

            foreach ((ISymbol symbol, AuthoredMember value) in
                bound.CallableBindings
                    ?? Enumerable.Empty<KeyValuePair<ISymbol, AuthoredMember>>())
            {
                carriedCallables[symbol] = value;
            }

            HashSet<ISymbol> carriedAbsentCallables = new(
                target.AbsentCallables ?? Enumerable.Empty<ISymbol>(),
                SymbolEqualityComparer.Default);

            carriedAbsentCallables.UnionWith(
                bound.AbsentCallables ?? Enumerable.Empty<ISymbol>());

            carriedAbsentCallables.ExceptWith(carriedCallables.Keys);

            bound = bound with
            {
                AbsentCallables = carriedAbsentCallables,
                CallableBindings = carriedCallables,
                ConcreteBindings = carriedConcrete,
                ValueBindings = carriedValues,
            };

            (ExpressionSyntax Expression, IParameterSymbol? Parameter, RefKind RefKind)[]
                stableArguments = arguments.Where(argument =>
                {
                    ISymbol? symbol = caller.Model.GetSymbolInfo(
                        argument.Expression).Symbol;

                    return symbol is null
                        || RecoveryTupleSourceIsStable(
                            caller,
                            symbol,
                            argument.Expression,
                            allowSimpleLocalAssignments: false);
                }).ToArray();

            HashSet<ISymbol> unstableParameters = arguments
                .Except(stableArguments)
                .Select(argument => argument.Parameter)
                .Where(parameter => parameter is not null
                    && parameter.Ordinal >= 0
                    && parameter.Ordinal < target.Symbol.Parameters.Length)
                .Select(parameter =>
                    (ISymbol)target.Symbol.Parameters[parameter!.Ordinal])
                .ToHashSet(SymbolEqualityComparer.Default);

            bound = bound with
            {
                ConcreteBindings = bound.ConcreteBindings?
                    .Where(pair => !unstableParameters.Contains(pair.Key))
                    .ToDictionary(
                        static pair => pair.Key,
                        static pair => pair.Value,
                        SymbolEqualityComparer.Default),
                ValueBindings = bound.ValueBindings?
                    .Where(pair => !unstableParameters.Contains(pair.Key))
                    .ToDictionary(
                        static pair => pair.Key,
                        static pair => pair.Value,
                        SymbolEqualityComparer.Default),
            };

            return AddCleanupValueBindings(
                caller,
                stableArguments,
                target,
                bound);
        }

        private AuthoredMember BindConstructorArguments(
            AuthoredMember caller,
            BaseObjectCreationExpressionSyntax creation,
            AuthoredMember target,
            RecoveryTupleProvenanceContext? recoveryProvenance = null)
        {
            return BindArguments(
                caller,
                ConstructorArguments(caller, creation),
                target,
                recoveryProvenance);
        }

        private AuthoredMember BindArguments(
            AuthoredMember caller,
            IEnumerable<(ExpressionSyntax Expression, IParameterSymbol? Parameter, RefKind RefKind)> arguments,
            AuthoredMember target,
            RecoveryTupleProvenanceContext? recoveryProvenance = null,
            IReadOnlyDictionary<ISymbol, ITypeSymbol>? closedEnumBindings = null)
        {
            Dictionary<ISymbol, IReadOnlySet<string>> bindings = new(SymbolEqualityComparer.Default);

            Dictionary<ISymbol, AuthoredMember> callableBindings = new(SymbolEqualityComparer.Default);

            HashSet<ISymbol> absentCallables = new(SymbolEqualityComparer.Default);

            Dictionary<ISymbol, ITypeSymbol> concreteBindings = new(SymbolEqualityComparer.Default);

            if (closedEnumBindings is not null)
            {
                foreach (var binding in closedEnumBindings)
                {
                    concreteBindings.Add(binding.Key, binding.Value);
                }
            }

            Dictionary<ISymbol, RecoveryTuple> recoveryBindings = new(SymbolEqualityComparer.Default);

            Dictionary<ISymbol, BoundValueSource> valueBindings = new(SymbolEqualityComparer.Default);

            foreach (IParameterSymbol parameter in target.Symbol.Parameters.Where(static parameter => parameter.Type.TypeKind == TypeKind.Delegate && parameter.HasExplicitDefaultValue && parameter.ExplicitDefaultValue is null))
            {
                absentCallables.Add(parameter);
            }

            foreach (var argument in arguments)
            {
                if (argument.Parameter is { } parameter && parameter.Ordinal < target.Symbol.Parameters.Length)
                {
                    IParameterSymbol targetParameter = target.Symbol.Parameters[parameter.Ordinal];

                    bindings[targetParameter] = BoundAdmissionOrigins(caller, argument.Expression);

                    if (argument.RefKind is not RefKind.Out
                        && (RequiresExactValueProvenance(target, targetParameter)
                            || RequiresPerUnitHolderArgumentSource(caller, argument.Expression, targetParameter)
                            || RequiresPerUnitReconcilerSourceValue(caller, argument.Expression, targetParameter, target)
                            || RequiresEnumArgumentSource(caller, argument.Expression, argument.RefKind,
                                target, targetParameter, closedEnumBindings)
                            || argument.RefKind == RefKind.None
                                && targetParameter.RefKind == RefKind.None
                                && targetParameter.Type.SpecialType == SpecialType.System_Boolean
                                && IsStableKnownBooleanArgument(caller, argument.Expression)
                            || RequiresConstantControlProvenance(
                                    target,
                                    targetParameter)
                                && RecoveryValue(caller, argument.Expression, []).IsKnown))
                    {
                        valueBindings[targetParameter] = new(
                            caller,
                            argument.Expression);
                    }

                    if (ConcreteType(caller, argument.Expression) is { } concrete)
                    {
                        concreteBindings[targetParameter] = concrete;
                    }

                    if (TypeKey(targetParameter.Type)
                            == "RetroDownfall.Arcanum.Core.Operations.LongRunningOperation")
                    {
                        RecoveryTupleProvenance provenance =
                            RecoveryTupleProvenanceOf(
                                caller,
                                argument.Expression,
                                recoveryProvenance
                                    ?? new RecoveryTupleProvenanceContext());

                        if (provenance.Complete
                            && provenance.Tuple is { } recovery)
                        {
                            recoveryBindings[targetParameter] = recovery;
                        }
                    }

                    if (targetParameter.Type.TypeKind == TypeKind.Delegate)
                    {
                        absentCallables.Remove(targetParameter);

                        ISymbol? callableSymbol = caller.Model.GetSymbolInfo(argument.Expression).Symbol;

                        AuthoredMember? callback = null;

                        bool carriesCapturedContext = callableSymbol is not null && caller.CallableBindings?.TryGetValue(callableSymbol, out callback) == true;

                        callback ??= ResolveCallable(
                            argument.Expression,
                            caller.Model,
                            caller.CallableBindings,
                            caller.AbsentCallables);

                        if (callback is not null)
                        {
                            callback = BindStableCapturedCleanupContext(
                                caller,
                                argument.Expression,
                                callback);

                            callback = carriesCapturedContext
                                ? callback
                                : callback with
                                {
                                    AdmissionBindings = caller.AdmissionBindings,
                                    CallableBindings = caller.CallableBindings,
                                    AbsentCallables = caller.AbsentCallables,
                                    RecoveryBindings = caller.RecoveryBindings,
                                    RecoveryContext = caller.RecoveryContext,
                                };

                            callback =
                                ProjectStaticCallbackCaptureEnvironment(callback);

                            _ = TryRegisterEvaluationEnvironmentToken(callback);

                            callableBindings[targetParameter] = callback;
                        }
                        else if (callableSymbol is not null && caller.AbsentCallables?.Contains(callableSymbol) == true)
                        {
                            absentCallables.Add(targetParameter);
                        }
                        else if (caller.Model.GetConstantValue(argument.Expression) is { HasValue: true, Value: null })
                        {
                            absentCallables.Add(targetParameter);
                        }
                    }
                }
            }

            if (bindings.Count == 0
                && callableBindings.Count == 0
                && absentCallables.Count == 0
                && concreteBindings.Count == 0
                && recoveryBindings.Count == 0
                && valueBindings.Count == 0
                && caller.RecoveryContext is null
                && (target.AdmissionBindings is null
                    || target.AdmissionBindings.Count == 0)
                && (target.CallableBindings is null
                    || target.CallableBindings.Count == 0)
                && (target.AbsentCallables is null
                    || target.AbsentCallables.Count == 0)
                && (target.ConcreteBindings is null
                    || target.ConcreteBindings.Count == 0)
                && (target.RecoveryBindings is null
                    || target.RecoveryBindings.Count == 0)
                && target.RecoveryContext is null
                && (target.ValueBindings is null
                    || target.ValueBindings.Count == 0))
            {
                return target;
            }

            AuthoredMember bound = target with
            {
                AdmissionBindings = bindings,
                CallableBindings = callableBindings,
                AbsentCallables = absentCallables,
                ConcreteBindings = concreteBindings,
                RecoveryBindings = recoveryBindings,
                RecoveryContext = caller.RecoveryContext,
                ValueBindings = valueBindings,
            };

            _ = TryRegisterEvaluationEnvironmentToken(bound);

            return bound;
        }

        private static bool IsEnumConstrainedParameter(
            AuthoredMember member,
            IParameterSymbol parameter)
        {
            // Deliberately broader than the finite optimization shape: excluded
            // multi-T and containing-type-T edges must retain their source too.
            return parameter.Type is ITypeParameterSymbol type
                && type.ConstraintTypes.Any(constraint => SymbolEqualityComparer.Default.Equals(
                    constraint,
                    member.Model.Compilation.GetSpecialType(SpecialType.System_Enum)));
        }

        private static ExpressionSyntax EnumCopyOperand(ExpressionSyntax expression)
        {
            while (expression is ParenthesizedExpressionSyntax parenthesized)
            {
                expression = parenthesized.Expression;
            }

            return expression;
        }

        private static bool IsPlainOwnEnumForwarding(
            AuthoredMember caller,
            IParameterSymbol source,
            AuthoredMember callee,
            IParameterSymbol destination,
            IArgumentOperation argument)
        {
            if (!HasFiniteEnumMethodShape(caller.Symbol, caller.Model.Compilation)
                || !HasFiniteEnumMethodShape(callee.Symbol, callee.Model.Compilation)
                || source.RefKind != RefKind.None || destination.RefKind != RefKind.None
                || !SymbolEqualityComparer.Default.Equals(source.ContainingSymbol, caller.Symbol)
                || !SymbolEqualityComparer.Default.Equals(destination.ContainingSymbol, callee.Symbol)
                || !SymbolEqualityComparer.Default.Equals(source.Type, caller.Symbol.TypeParameters[0])
                || !SymbolEqualityComparer.Default.Equals(destination.Type, callee.Symbol.TypeParameters[0])
                || argument.Parent is not IInvocationOperation invocation
                || invocation.IsVirtual || invocation.TargetMethod.ReducedFrom is not null
                || !SymbolEqualityComparer.Default.Equals(invocation.TargetMethod.OriginalDefinition, callee.Symbol)
                || invocation.TargetMethod.TypeArguments.Length != 1
                || !SymbolEqualityComparer.Default.Equals(invocation.TargetMethod.TypeArguments[0], caller.Symbol.TypeParameters[0])
                || argument.Parameter is not { RefKind: RefKind.None } selectedParameter
                || !SymbolEqualityComparer.Default.Equals(selectedParameter.OriginalDefinition, destination)
                || !argument.InConversion.IsIdentity || !argument.OutConversion.IsIdentity
                || argument.Syntax is not ArgumentSyntax { RefKindKeyword.RawKind: 0 } syntax
                || EnumCopyOperand(syntax.Expression) is not IdentifierNameSyntax identifier
                || !SymbolEqualityComparer.Default.Equals(caller.Model.GetSymbolInfo(identifier).Symbol, source))
            {
                return false;
            }

            IOperation value = argument.Value;

            while (value is IParenthesizedOperation parenthesized) value = parenthesized.Operand;

            return value is IParameterReferenceOperation reference
                && SymbolEqualityComparer.Default.Equals(reference.Parameter, source)
                && SymbolEqualityComparer.Default.Equals(value.Type, caller.Symbol.TypeParameters[0]);
        }

        private bool RequiresEnumArgumentSource(
            AuthoredMember caller,
            ExpressionSyntax expression,
            RefKind refKind,
            AuthoredMember target,
            IParameterSymbol parameter,
            IReadOnlyDictionary<ISymbol, ITypeSymbol>? selectedBindings)
        {
            if (!IsEnumConstrainedParameter(target, parameter)) return false;

            if (!HasFiniteEnumMethodShape(target.Symbol, target.Model.Compilation)
                || refKind != RefKind.None || parameter.RefKind != RefKind.None
                || !SymbolEqualityComparer.Default.Equals(parameter.ContainingSymbol, target.Symbol)
                || !SymbolEqualityComparer.Default.Equals(parameter.Type, target.Symbol.TypeParameters[0])
                || selectedBindings is null
                || !selectedBindings.TryGetValue(target.Symbol.TypeParameters[0], out ITypeSymbol? ownType)
                || !selectedBindings.TryGetValue(parameter, out ITypeSymbol? valueType)
                || !IsClosedFiniteEnum(ownType)
                || !SymbolEqualityComparer.Default.Equals(ownType, valueType))
            {
                return true;
            }

            // Only the explicit per-invocation R88 certificate is consulted here.
            // General concrete bindings and definition-cached booleans cannot
            // reconstruct an earlier excluded wrapper or captured source.
            ExpressionSyntax operand = EnumCopyOperand(expression);

            if (caller.Model.GetSymbolInfo(operand).Symbol is ILocalSymbol) return true;

            if (caller.Model.GetSymbolInfo(operand).Symbol is IParameterSymbol source)
            {
                return expression.Parent is not ArgumentSyntax syntax
                    || caller.Model.GetOperation(syntax) is not IArgumentOperation argument
                    || !IsPlainOwnEnumForwarding(caller, source, target, parameter, argument);
            }

            IOperation? operation = caller.Model.GetOperation(operand);

            if (HasOwnedEnumPropertyIngress(caller, operand, target, parameter, ownType!, selectedBindings)) return false;

            // Closed ingress can be an evaluated factory/property/field/constant.
            // A nested local/parameter source is conservatively retained rather
            // than treated as a new closed ingress or recursively reconstructed.
            return operation is null
                || !SymbolEqualityComparer.Default.Equals(operation.Type, ownType)
                || operation.DescendantsAndSelf().Any(static value => value is ILocalReferenceOperation or IParameterReferenceOperation);
        }

        private bool HasOwnedEnumPropertyIngress(
            AuthoredMember caller,
            ExpressionSyntax expression,
            AuthoredMember target,
            IParameterSymbol parameter,
            ITypeSymbol closedType,
            IReadOnlyDictionary<ISymbol, ITypeSymbol> selectedBindings)
        {
            // Each use supplies its own complete certificate. The original caller,
            // receiver and getter still traverse with their independent demands.
            if (!TryGetOwnedEnumPropertyReceiver(caller, expression, target, parameter, closedType, selectedBindings, out ISymbol receiverSymbol)) return false;

            // Retain the existing stable local source requirement at this use.
            if (receiverSymbol is ILocalSymbol
                && (!TryResolveStableLocalInitializerValueSource(caller, ((MemberAccessExpressionSyntax)expression).Expression, out BoundValueSource? stable)
                    || stable is null)) return false;

            // This certificate belongs to the copied enum argument, not its
            // receiver's other uses. Caller/getter effects retain their original
            // contexts; the receiving helper still needs its exact own-T proof.
            return HasDirectOwnedEnumBytePair(target, parameter, closedType, selectedBindings)
                || HasOwnedEnumUIntTail(target, parameter, closedType, selectedBindings)
                || HasOwnedEnumUIntWrapper(target, parameter, closedType, selectedBindings);
        }

        private bool TryGetOwnedEnumPropertyReceiver(
            AuthoredMember caller,
            ExpressionSyntax expression,
            AuthoredMember target,
            IParameterSymbol parameter,
            ITypeSymbol closedType,
            IReadOnlyDictionary<ISymbol, ITypeSymbol> selectedBindings,
            out ISymbol receiverSymbol)
        {
            receiverSymbol = null!;

            if (caller.Symbol.MethodKind != MethodKind.Ordinary
                || caller.Syntax is not MethodDeclarationSyntax
                || !ReferenceEquals(caller.Model.Compilation, target.Model.Compilation)
                || !HasFiniteEnumMethodShape(target.Symbol, target.Model.Compilation)
                || parameter.RefKind != RefKind.None
                || !SymbolEqualityComparer.Default.Equals(parameter.ContainingSymbol, target.Symbol)
                || !SymbolEqualityComparer.Default.Equals(parameter.Type, target.Symbol.TypeParameters[0])
                || !IsClosedFiniteEnum(closedType)
                || !selectedBindings.TryGetValue(target.Symbol.TypeParameters[0], out ITypeSymbol? ownType)
                || !selectedBindings.TryGetValue(parameter, out ITypeSymbol? valueType)
                || !SymbolEqualityComparer.Default.Equals(ownType, closedType)
                || !SymbolEqualityComparer.Default.Equals(valueType, closedType)
                || expression is not MemberAccessExpressionSyntax { Expression: IdentifierNameSyntax receiver } access
                || access.SyntaxTree != caller.Syntax.SyntaxTree || !caller.Syntax.Span.Contains(access.Span)
                || access.Parent is not ArgumentSyntax { RefKindKeyword.RawKind: 0 } argumentSyntax
                || caller.Model.GetOperation(argumentSyntax) is not IArgumentOperation argument
                || argument.ArgumentKind != ArgumentKind.Explicit
                || !argument.InConversion.IsIdentity || !argument.OutConversion.IsIdentity
                || argument.Parameter is not { RefKind: RefKind.None } selectedParameter
                || !SymbolEqualityComparer.Default.Equals(selectedParameter.OriginalDefinition, parameter)
                || !SymbolEqualityComparer.Default.Equals(selectedParameter.Type, closedType)
                || argument.Parent is not IInvocationOperation invocation
                || invocation.IsVirtual || invocation.Instance is not null || !invocation.TargetMethod.IsStatic
                || invocation.TargetMethod.ReducedFrom is not null
                || (invocation.Arguments.Length != 1
                    && !HasOwnedEnumUIntWrapperCall(caller, invocation, argument, target, parameter, closedType, selectedBindings))
                || !SymbolEqualityComparer.Default.Equals(invocation.TargetMethod.OriginalDefinition, target.Symbol)
                || invocation.TargetMethod.TypeArguments is not [var selectedType]
                || !SymbolEqualityComparer.Default.Equals(selectedType, closedType)
                || argument.Value is not IPropertyReferenceOperation read
                || read.Syntax != access
                || read.Property is not { IsStatic: false, IsIndexer: false, IsVirtual: false, IsOverride: false, IsAbstract: false, ReturnsByRef: false, ReturnsByRefReadonly: false, GetMethod: { } getter }
                || !SymbolEqualityComparer.Default.Equals(read.Type, closedType)
                || read.Property.ContainingType is not { TypeKind: TypeKind.Class, IsSealed: true } container
                || getter.IsVirtual || getter.IsOverride || getter.IsAbstract || getter.IsExtern
                || (getter.DeclaringSyntaxReferences.Length != 1
                || Resolve(getter, caller.Model.Compilation) is not { } authoredGetter
                || !SymbolEqualityComparer.Default.Equals(authoredGetter.Symbol, getter)
                || !(authoredGetter.Syntax is AccessorDeclarationSyntax { Body: not null } or AccessorDeclarationSyntax { ExpressionBody: not null }
                    || authoredGetter.Syntax is ExpressionSyntax { Parent: ArrowExpressionClauseSyntax { Parent: PropertyDeclarationSyntax propertyDeclaration } } getterExpression
                        && propertyDeclaration.ExpressionBody?.Expression == getterExpression
                        && SymbolEqualityComparer.Default.Equals(authoredGetter.Model.GetDeclaredSymbol(propertyDeclaration), read.Property)))
                    && !HasExactGeneratedPositionalEnumGetter(read.Property, getter, caller.Model.Compilation))
            {
                return false;
            }

            for (INamedTypeSymbol? containing = container; containing is not null; containing = containing.ContainingType)
            {
                if (containing.Arity != 0) return false;
            }

            if (read.Instance is IParameterReferenceOperation { Parameter.RefKind: RefKind.None } input
                && SymbolEqualityComparer.Default.Equals(input.Parameter.ContainingSymbol, caller.Symbol)
                && SymbolEqualityComparer.Default.Equals(input.Parameter.Type, container))
            {
                receiverSymbol = input.Parameter;
            }
            else if (read.Instance is ILocalReferenceOperation { Local.RefKind: RefKind.None } local
                && SymbolEqualityComparer.Default.Equals(local.Local.ContainingSymbol, caller.Symbol)
                && SymbolEqualityComparer.Default.Equals(local.Local.Type, container)
                && local.Local.DeclaringSyntaxReferences.Length == 1
                && local.Local.DeclaringSyntaxReferences[0].GetSyntax() is VariableDeclaratorSyntax { Initializer.Value: { } initializer } declaration
                && declaration.SyntaxTree == caller.Syntax.SyntaxTree
                && caller.Syntax.Span.Contains(declaration.Span)
                && declaration.Span.End < receiver.SpanStart
                && caller.Model.GetOperation(initializer) is IInvocationOperation { IsVirtual: false, TargetMethod.ReturnsByRef: false, TargetMethod.ReturnsByRefReadonly: false } factory
                && SymbolEqualityComparer.Default.Equals(factory.Type, container)
                && Resolve(factory.TargetMethod, caller.Model.Compilation) is { Syntax: MethodDeclarationSyntax { Body: not null } or MethodDeclarationSyntax { ExpressionBody: not null } })
            {
                receiverSymbol = local.Local;
            }
            else
            {
                return false;
            }

            return true;
        }

        private bool HasExactGeneratedPositionalEnumGetter(IPropertySymbol property, IMethodSymbol getter, Compilation compilation)
        {
            // A generated positional getter has primary-parameter syntax, not an
            // authored body. Authenticate that exact compiler/source association.
            if (!getter.IsImplicitlyDeclared
                || getter.MethodKind != MethodKind.PropertyGet
                || !SymbolEqualityComparer.Default.Equals(getter.AssociatedSymbol, property)
                || !SymbolEqualityComparer.Default.Equals(property.GetMethod, getter)
                || property.IsStatic || property.IsIndexer || property.IsVirtual || property.IsOverride || property.IsAbstract
                || property.ReturnsByRef || property.ReturnsByRefReadonly
                || property.ContainingType is not { TypeKind: TypeKind.Class, IsRecord: true, IsSealed: true, Arity: 0 } container
                || getter.IsStatic || getter.IsVirtual || getter.IsOverride || getter.IsAbstract || getter.IsExtern
                || getter.ReturnsByRef || getter.ReturnsByRefReadonly || getter.Parameters.Length != 0
                || !SymbolEqualityComparer.Default.Equals(getter.ContainingType, container)
                || !SymbolEqualityComparer.Default.Equals(getter.ReturnType, property.Type)
                || property.DeclaringSyntaxReferences is not [SyntaxReference propertyReference]
                || getter.DeclaringSyntaxReferences is not [SyntaxReference getterReference]
                || propertyReference.GetSyntax() is not ParameterSyntax
                {
                    Parent: ParameterListSyntax { Parent: RecordDeclarationSyntax record } parameterList,
                } parameterSyntax
                || getterReference.SyntaxTree != parameterSyntax.SyntaxTree
                || getterReference.Span != parameterSyntax.Span
                || getterReference.GetSyntax() is not ParameterSyntax
                || record.ParameterList != parameterList
                || !compilation.ContainsSyntaxTree(parameterSyntax.SyntaxTree)
                || !semanticModels.TryGetValue(parameterSyntax.SyntaxTree, out SemanticModel? model)
                || !ReferenceEquals(model.Compilation, compilation)
                || !SymbolEqualityComparer.Default.Equals(model.GetDeclaredSymbol(record), container)
                || model.GetDeclaredSymbol(parameterSyntax) is not IParameterSymbol
                {
                    RefKind: RefKind.None,
                    ContainingSymbol: IMethodSymbol { MethodKind: MethodKind.Constructor, IsStatic: false } constructor,
                } parameter
                || !SymbolEqualityComparer.Default.Equals(constructor.ContainingType, container)
                || !SymbolEqualityComparer.Default.Equals(parameter.Type, property.Type)
                || parameter.Name != property.Name
                || parameter.Ordinal != parameterList.Parameters.IndexOf(parameterSyntax)
                || parameter.Ordinal < 0 || parameter.Ordinal >= constructor.Parameters.Length
                || !SymbolEqualityComparer.Default.Equals(constructor.Parameters[parameter.Ordinal], parameter)
                || parameter.DeclaringSyntaxReferences is not [SyntaxReference parameterReference]
                || parameterReference.SyntaxTree != parameterSyntax.SyntaxTree
                || parameterReference.Span != parameterSyntax.Span)
            {
                return false;
            }

            return true;
        }

        private bool HasDirectOwnedEnumBytePair(
            AuthoredMember forward,
            IParameterSymbol parameter,
            ITypeSymbol closedType,
            IReadOnlyDictionary<ISymbol, ITypeSymbol> selectedBindings)
        {
            if (!HasImmediateEnumByteMethodShape(forward)
                || SingleRuntimeEnumParameterUse(forward, parameter) is not { Parent: ArgumentSyntax syntax } use
                || syntax.Expression != use
                || forward.Model.GetOperation(syntax) is not IArgumentOperation argument
                || argument.ArgumentKind != ArgumentKind.Explicit
                || argument.Parent is not IInvocationOperation { Syntax: InvocationExpressionSyntax call } invocation
                || Resolve(invocation.TargetMethod, forward.Model.Compilation) is not { } copy
                || !HasImmediateEnumByteMethodShape(copy)
                || SymbolEqualityComparer.Default.Equals(copy.Symbol, forward.Symbol)
                || !IsPlainOwnEnumForwarding(forward, parameter, copy, copy.Symbol.Parameters[0], argument)
                || !IsImmediateEnumByteReturn(forward, invocation, call)
                || SingleRuntimeEnumParameterUse(copy, copy.Symbol.Parameters[0]) is not { Parent: ArgumentSyntax storage } leaf
                || storage.Expression != leaf
                || !IsOwnedEnumByteValueRead(copy, copy.Symbol.Parameters[0], storage))
            {
                return false;
            }

            // Only the already-selected own-T slots cross this one authored edge.
            // This temporary proof view neither binds runtime values nor registers
            // a new evaluation context or a reusable certificate cache.
            AuthoredMember selectedForward = forward with { ConcreteBindings = selectedBindings };

            IReadOnlyDictionary<ISymbol, ITypeSymbol>? copiedBindings = ClosedEnumInvocationBindings(selectedForward, call, copy);

            return copiedBindings is not null
                && copiedBindings.TryGetValue(copy.Symbol.TypeParameters[0], out ITypeSymbol? copyType)
                && copiedBindings.TryGetValue(copy.Symbol.Parameters[0], out ITypeSymbol? copyValue)
                && SymbolEqualityComparer.Default.Equals(copyType, closedType)
                && SymbolEqualityComparer.Default.Equals(copyValue, closedType);
        }

        private bool HasOwnedEnumUIntWrapperCall(
            AuthoredMember caller,
            IInvocationOperation invocation,
            IArgumentOperation enumArgument,
            AuthoredMember target,
            IParameterSymbol parameter,
            ITypeSymbol closedType,
            IReadOnlyDictionary<ISymbol, ITypeSymbol> selectedBindings)
        {
            // The same selected two-argument alternative guards both ingress
            // and every receiver use. The string keeps ordinary source binding.
            if (!HasFiniteEnumMethodShape(target.Symbol, target.Model.Compilation)
                || !ReferenceEquals(caller.Model.Compilation, target.Model.Compilation)
                || invocation.Syntax is not InvocationExpressionSyntax { ArgumentList.Arguments: [var valueSyntax, var nameSyntax] } call
                || call.SyntaxTree != caller.Syntax.SyntaxTree || !caller.Syntax.Span.Contains(call.Span)
                || valueSyntax.RefKindKeyword.RawKind != 0 || nameSyntax.RefKindKeyword.RawKind != 0
                || invocation.IsVirtual || invocation.Instance is not null || !invocation.TargetMethod.IsStatic
                || invocation.TargetMethod.ReducedFrom is not null
                || !SymbolEqualityComparer.Default.Equals(invocation.TargetMethod.OriginalDefinition, target.Symbol)
                || invocation.TargetMethod.TypeArguments is not [var selectedType]
                || !SymbolEqualityComparer.Default.Equals(selectedType, closedType)
                || invocation.Type?.SpecialType != SpecialType.System_UInt32
                || target.Symbol.Parameters is not [var valueParameter, var nameParameter]
                || !SymbolEqualityComparer.Default.Equals(valueParameter, parameter)
                || !SymbolEqualityComparer.Default.Equals(valueParameter.Type, target.Symbol.TypeParameters[0])
                || nameParameter.Type.SpecialType != SpecialType.System_String
                || invocation.Arguments is not [var valueArgument, var nameArgument]
                || !ReferenceEquals(valueArgument, enumArgument)
                || valueArgument.Syntax != valueSyntax || nameArgument.Syntax != nameSyntax
                || !SymbolEqualityComparer.Default.Equals(valueArgument.Value.Type, closedType)
                || nameArgument.Value.Type?.SpecialType != SpecialType.System_String) return false;

            for (int index = 0; index < invocation.Arguments.Length; index++)
            {
                IArgumentOperation argument = invocation.Arguments[index];

                if (argument.ArgumentKind != ArgumentKind.Explicit
                    || argument.Parameter is not { RefKind: RefKind.None } formal
                    || formal.Ordinal != index
                    || !SymbolEqualityComparer.Default.Equals(formal.OriginalDefinition, target.Symbol.Parameters[index])
                    || !argument.InConversion.IsIdentity || !argument.OutConversion.IsIdentity) return false;
            }

            return ClosedEnumInvocationBindings(caller, call, target) is { } bindings
                && bindings.TryGetValue(target.Symbol.TypeParameters[0], out ITypeSymbol? ownType)
                && SymbolEqualityComparer.Default.Equals(ownType, closedType)
                && bindings.TryGetValue(parameter, out ITypeSymbol? valueType)
                && SymbolEqualityComparer.Default.Equals(valueType, closedType)
                && HasOwnedEnumUIntWrapper(target, parameter, closedType, selectedBindings);
        }

        private bool HasOwnedEnumUIntWrapper(
            AuthoredMember wrapper,
            IParameterSymbol parameter,
            ITypeSymbol closedType,
            IReadOnlyDictionary<ISymbol, ITypeSymbol> selectedBindings)
        {
            // One fixed outer edge around the unchanged ten-role child. This
            // proof view supplies own-T slots without changing traversal state.
            if (!HasEnumTailSourceShape(wrapper, wrapper, true)
                || !IsClosedFiniteEnum(closedType)
                || wrapper.Symbol.ReturnType.SpecialType != SpecialType.System_UInt32
                || wrapper.Symbol.Parameters is not [var valueParameter, var nameParameter]
                || !SymbolEqualityComparer.Default.Equals(parameter, valueParameter)
                || !SymbolEqualityComparer.Default.Equals(valueParameter.Type, wrapper.Symbol.TypeParameters[0])
                || nameParameter.Type.SpecialType != SpecialType.System_String
                || !selectedBindings.TryGetValue(wrapper.Symbol.TypeParameters[0], out ITypeSymbol? ownType)
                || !SymbolEqualityComparer.Default.Equals(ownType, closedType)
                || !selectedBindings.TryGetValue(parameter, out ITypeSymbol? valueType)
                || !SymbolEqualityComparer.Default.Equals(valueType, closedType)
                || wrapper.Syntax is not MethodDeclarationSyntax { ExpressionBody: null, Body.Statements: [TryStatementSyntax trySyntax] } declaration
                || !SymbolEqualityComparer.Default.Equals(wrapper.Model.GetDeclaredSymbol(declaration), wrapper.Symbol)
                || trySyntax.Finally is not null
                || trySyntax.Block.Statements is not [ReturnStatementSyntax { Expression: InvocationExpressionSyntax childSyntax } returnSyntax]
                || childSyntax.ArgumentList.Arguments is not [ArgumentSyntax { RefKindKeyword.RawKind: 0, Expression: IdentifierNameSyntax enumUse }]
                || trySyntax.Catches is not [CatchClauseSyntax
                {
                    Declaration: { } catchDeclaration,
                    Filter.FilterExpression: IsPatternExpressionSyntax { Expression: IdentifierNameSyntax filterUse } filterSyntax,
                    Block.Statements: [ThrowStatementSyntax
                    {
                        Expression: ObjectCreationExpressionSyntax
                        {
                            Initializer: null,
                            ArgumentList.Arguments:
                            [
                                ArgumentSyntax { RefKindKeyword.RawKind: 0, Expression: IdentifierNameSyntax nameUse },
                                ArgumentSyntax { RefKindKeyword.RawKind: 0, Expression: IdentifierNameSyntax exceptionUse },
                            ],
                        } creationSyntax,
                    } throwSyntax],
                } catchSyntax]) return false;

            Compilation compilation = wrapper.Model.Compilation;

            INamedTypeSymbol? exceptionType = compilation.GetTypeByMetadataName("System.Exception");

            INamedTypeSymbol? systemExceptionType = compilation.GetTypeByMetadataName("System.SystemException");

            INamedTypeSymbol? argumentType = compilation.GetTypeByMetadataName("System.ArgumentException");

            INamedTypeSymbol? outOfRangeType = compilation.GetTypeByMetadataName("System.ArgumentOutOfRangeException");

            if (!IsEnumWrapperFrameworkType(compilation, exceptionType, "System.Exception")
                || !IsEnumWrapperFrameworkType(compilation, systemExceptionType, "System.SystemException")
                || !IsEnumWrapperFrameworkType(compilation, argumentType, "System.ArgumentException")
                || !IsEnumWrapperFrameworkType(compilation, outOfRangeType, "System.ArgumentOutOfRangeException")
                || !SymbolEqualityComparer.Default.Equals(exceptionType!.BaseType, compilation.GetSpecialType(SpecialType.System_Object))
                || !SymbolEqualityComparer.Default.Equals(systemExceptionType!.BaseType, exceptionType)
                || !SymbolEqualityComparer.Default.Equals(argumentType!.BaseType, systemExceptionType)
                || !SymbolEqualityComparer.Default.Equals(outOfRangeType!.BaseType, argumentType)
                || wrapper.Model.GetOperation(trySyntax) is not ITryOperation
                {
                    IsImplicit: false,
                    Finally: null,
                    Body.Operations: [IReturnOperation { IsImplicit: false, ReturnedValue: IInvocationOperation childCall } returned],
                    Catches: [var caught],
                } tried
                || tried.Body.Syntax != trySyntax.Block || returned.Syntax != returnSyntax || childCall.Syntax != childSyntax
                || caught.Syntax != catchSyntax || caught.Locals is not [var catchLocal]
                || catchLocal.RefKind != RefKind.None
                || !SymbolEqualityComparer.Default.Equals(catchLocal.ContainingSymbol, wrapper.Symbol)
                || !SymbolEqualityComparer.Default.Equals(wrapper.Model.GetDeclaredSymbol(catchDeclaration), catchLocal)
                || !SymbolEqualityComparer.Default.Equals(caught.ExceptionType, exceptionType)
                || !SymbolEqualityComparer.Default.Equals(catchLocal.Type, exceptionType)
                || !SymbolEqualityComparer.Default.Equals(wrapper.Model.GetTypeInfo(catchDeclaration.Type).Type, exceptionType)
                || caught.Filter is not IIsPatternOperation
                {
                    IsImplicit: false,
                    Type.SpecialType: SpecialType.System_Boolean,
                    Value: ILocalReferenceOperation filterReference,
                    Pattern: IBinaryPatternOperation
                    {
                        OperatorKind: BinaryOperatorKind.Or,
                        LeftPattern: ITypePatternOperation leftPattern,
                        RightPattern: ITypePatternOperation rightPattern,
                    } pattern,
                } filter
                || filter.Syntax != filterSyntax || filterReference.Syntax != filterUse || pattern.Syntax != filterSyntax.Pattern
                || !IsEnumTailReference(filterReference, catchLocal)
                || !SymbolEqualityComparer.Default.Equals(leftPattern.MatchedType, argumentType)
                || !SymbolEqualityComparer.Default.Equals(rightPattern.MatchedType, outOfRangeType)
                || caught.Handler.Syntax != catchSyntax.Block
                || caught.Handler.Operations is not [IThrowOperation { IsImplicit: false, Type: null } thrown]
                || thrown.Syntax != throwSyntax
                || !IsEnumWrapperException(wrapper, thrown, creationSyntax, nameParameter, catchLocal, exceptionType!, outOfRangeType!)
                || tried.DescendantsAndSelf().Any(static operation => operation.Kind is OperationKind.Invalid or OperationKind.None
                    || operation is INameOfOperation or IDefaultValueOperation)
                || !HasExactEnumWrapperUses(wrapper, parameter, enumUse)
                || !HasExactEnumWrapperUses(wrapper, nameParameter, nameUse)
                || !HasExactEnumWrapperUses(wrapper, catchLocal, filterUse, exceptionUse)) return false;

            wrapper = wrapper with { ConcreteBindings = selectedBindings };

            if (childCall.IsVirtual || childCall.Instance is not null || !childCall.TargetMethod.IsStatic
                || childCall.TargetMethod.ReducedFrom is not null
                || childCall.Type?.SpecialType != SpecialType.System_UInt32
                || childCall.TargetMethod.TypeArguments is not [var childType]
                || !SymbolEqualityComparer.Default.Equals(childType, wrapper.Symbol.TypeParameters[0])
                || childCall.Arguments is not [var childArgument]
                || childArgument.ArgumentKind != ArgumentKind.Explicit
                || !childArgument.InConversion.IsIdentity || !childArgument.OutConversion.IsIdentity
                || childArgument.Value.Syntax != enumUse || !IsEnumTailReference(childArgument.Value, parameter)
                || !SymbolEqualityComparer.Default.Equals(childArgument.Value.Type, wrapper.Symbol.TypeParameters[0])
                || Resolve(childCall.TargetMethod, compilation) is not { } child
                || !ReferenceEquals(child.Model.Compilation, compilation)
                || !HasEnumTailSourceShape(child, child, true)
                || child.Syntax is not MethodDeclarationSyntax childDeclaration
                || !SymbolEqualityComparer.Default.Equals(child.Model.GetDeclaredSymbol(childDeclaration), child.Symbol)
                || !SymbolEqualityComparer.Default.Equals(childCall.TargetMethod.OriginalDefinition, child.Symbol)
                || SymbolEqualityComparer.Default.Equals(child.Symbol, wrapper.Symbol)
                || child.Symbol.Parameters is not [var childParameter]
                || !SymbolEqualityComparer.Default.Equals(childParameter.Type, child.Symbol.TypeParameters[0])
                || childArgument.Parameter is not { Ordinal: 0, RefKind: RefKind.None } selectedParameter
                || !SymbolEqualityComparer.Default.Equals(selectedParameter.OriginalDefinition, childParameter)
                || !SymbolEqualityComparer.Default.Equals(selectedParameter.Type, wrapper.Symbol.TypeParameters[0])
                || ClosedEnumInvocationBindings(wrapper, childSyntax, child) is not { } childBindings
                || !childBindings.TryGetValue(child.Symbol.TypeParameters[0], out ITypeSymbol? childOwnType)
                || !SymbolEqualityComparer.Default.Equals(childOwnType, closedType)
                || !childBindings.TryGetValue(childParameter, out ITypeSymbol? childValueType)
                || !SymbolEqualityComparer.Default.Equals(childValueType, closedType)) return false;

            // Only the selected child becomes a new root. Its original same-tree,
            // same-container and distinct-role checks are unchanged. None of its
            // ten role signatures can be this two-formal own-T/string wrapper.
            return HasOwnedEnumUIntTail(child, childParameter, closedType, childBindings);
        }

        private static bool IsEnumWrapperFrameworkType(Compilation compilation, INamedTypeSymbol? type, string metadataType)
        {
            IAssemblySymbol core = compilation.GetSpecialType(SpecialType.System_Object).ContainingAssembly;

            AssemblyIdentity assembly = core.Identity;

            string token = Convert.ToHexString(assembly.PublicKeyToken.AsSpan());

            return type is { TypeKind: TypeKind.Class, Arity: 0 }
                && SymbolEqualityComparer.Default.Equals(type, compilation.GetTypeByMetadataName(metadataType))
                && SymbolEqualityComparer.Default.Equals(type.ContainingAssembly, core)
                && assembly.Version == new Version(10, 0, 0, 0) && string.IsNullOrEmpty(assembly.CultureName)
                && !assembly.IsRetargetable && assembly.ContentType == System.Reflection.AssemblyContentType.Default
                && (assembly.Name == "System.Private.CoreLib" && token == "7CEC85D7BEA7798E"
                    || assembly.Name == "System.Runtime" && token == "B03F5F7F11D50A3A")
                && type.DeclaringSyntaxReferences.Length == 0
                && !type.Locations.Any(static location => location.IsInSource);
        }

        private static bool IsEnumWrapperException(
            AuthoredMember wrapper,
            IThrowOperation thrown,
            ObjectCreationExpressionSyntax syntax,
            IParameterSymbol nameParameter,
            ILocalSymbol catchLocal,
            INamedTypeSymbol exceptionType,
            INamedTypeSymbol outOfRangeType)
        {
            // The observed throw statement has only the implicit framework
            // exception upcast. This constructor's first string is its message.
            if (thrown.Exception is not IConversionOperation
                {
                    IsImplicit: true,
                    IsChecked: false,
                    IsTryCast: false,
                    OperatorMethod: null,
                    Conversion: { Exists: true, IsIdentity: false, IsNumeric: false, IsReference: true, IsUserDefined: false, MethodSymbol: null },
                    Operand: IObjectCreationOperation { IsImplicit: false, Constructor: { } constructor, Initializer: null } creation,
                } upcast
                || upcast.Syntax != syntax || creation.Syntax != syntax
                || !SymbolEqualityComparer.Default.Equals(upcast.Type, exceptionType)
                || !SymbolEqualityComparer.Default.Equals(creation.Type, outOfRangeType)
                || !IsEnumTailFrameworkMethod(wrapper.Model.Compilation, constructor, "System.ArgumentOutOfRangeException")
                || constructor.MethodKind != MethodKind.Constructor || constructor.IsStatic || constructor.Arity != 0
                || constructor.Parameters is not [var messageParameter, var innerParameter]
                || messageParameter.Type.SpecialType != SpecialType.System_String
                || !SymbolEqualityComparer.Default.Equals(innerParameter.Type, exceptionType)
                || creation.Arguments is not [var messageArgument, var innerArgument]
                || !IsEnumTailReference(messageArgument.Value, nameParameter)
                || messageArgument.Value.Type?.SpecialType != SpecialType.System_String
                || !IsEnumTailReference(innerArgument.Value, catchLocal)
                || !SymbolEqualityComparer.Default.Equals(innerArgument.Value.Type, exceptionType)) return false;

            for (int index = 0; index < creation.Arguments.Length; index++)
            {
                IArgumentOperation argument = creation.Arguments[index];

                if (argument.ArgumentKind != ArgumentKind.Explicit
                    || argument.Parameter is not { RefKind: RefKind.None } formal
                    || formal.Ordinal != index
                    || !SymbolEqualityComparer.Default.Equals(formal.OriginalDefinition, constructor.Parameters[index])
                    || argument.Syntax != syntax.ArgumentList!.Arguments[index]
                    || argument.Value.Syntax != syntax.ArgumentList.Arguments[index].Expression
                    || !argument.InConversion.IsIdentity || !argument.OutConversion.IsIdentity) return false;
            }

            return true;
        }

        private static bool HasExactEnumWrapperUses(AuthoredMember wrapper, ISymbol symbol, params IdentifierNameSyntax[] expected)
        {
            IdentifierNameSyntax[] uses = wrapper.Syntax.DescendantNodesAndSelf().OfType<IdentifierNameSyntax>()
                .Where(use => SymbolEqualityComparer.Default.Equals(wrapper.Model.GetSymbolInfo(use).Symbol, symbol)).ToArray();

            return uses.Length == expected.Length
                && uses.SequenceEqual(expected)
                && uses.All(use => !use.Ancestors().TakeWhile(node => node != wrapper.Syntax)
                    .Any(static node => node is AnonymousFunctionExpressionSyntax or LocalFunctionStatementSyntax));
        }

        private bool HasOwnedEnumUIntTail(
            AuthoredMember root,
            IParameterSymbol parameter,
            ITypeSymbol closedType,
            IReadOnlyDictionary<ISymbol, ITypeSymbol> selectedBindings)
        {
            // Fixed, distinct source roles, discovered only through selected edges:
            // root, copy, support, three zero predicates, positive predicate,
            // positive range, maximum, range. No role recursion or reusable cache.
            AuthoredMember?[] roles = new AuthoredMember?[10];

            roles[0] = root with { ConcreteBindings = selectedBindings };

            bool Bind(AuthoredMember caller, InvocationExpressionSyntax syntax, int role, out AuthoredMember target)
            {
                target = null!;

                if (caller.Model.GetOperation(syntax) is not IInvocationOperation invocation
                    || invocation.IsVirtual || invocation.Instance is not null
                    || invocation.TargetMethod.ReducedFrom is not null
                    || Resolve(invocation.TargetMethod, caller.Model.Compilation) is not { } selected
                    || !HasEnumTailSourceShape(selected, root, role != 9)
                    || !SymbolEqualityComparer.Default.Equals(invocation.TargetMethod.OriginalDefinition, selected.Symbol)
                    || invocation.Arguments.Length != selected.Symbol.Parameters.Length
                    || invocation.Arguments.Where((argument, index) => argument.ArgumentKind != ArgumentKind.Explicit
                        || argument.Parameter?.Ordinal != index
                        || !SymbolEqualityComparer.Default.Equals(argument.Parameter.OriginalDefinition, selected.Symbol.Parameters[index])
                        || argument.Parameter.RefKind != RefKind.None
                        || !argument.InConversion.IsIdentity || !argument.OutConversion.IsIdentity).Any()) return false;

                if (role != 9)
                {
                    // An explicitly closed argument is not this caller's own-T
                    // edge, even when it happens to name the selected enum.
                    if (caller.Symbol.TypeParameters.Length != 1
                        || invocation.TargetMethod.TypeArguments.Length != 1
                        || !SymbolEqualityComparer.Default.Equals(invocation.TargetMethod.TypeArguments[0], caller.Symbol.TypeParameters[0])
                        || ClosedEnumInvocationBindings(caller, syntax, selected) is not { } bindings
                        || !bindings.TryGetValue(selected.Symbol.TypeParameters[0], out ITypeSymbol? selectedType)
                        || !SymbolEqualityComparer.Default.Equals(selectedType, closedType)) return false;

                    foreach (IParameterSymbol formal in selected.Symbol.Parameters)
                    {
                        if (SymbolEqualityComparer.Default.Equals(formal.Type, selected.Symbol.TypeParameters[0])
                            && (!bindings.TryGetValue(formal, out ITypeSymbol? valueType)
                                || !SymbolEqualityComparer.Default.Equals(valueType, closedType))) return false;
                    }

                    selected = selected with { ConcreteBindings = bindings };
                }

                for (int index = 0; index < roles.Length; index++)
                {
                    if (roles[index] is not { } previous) continue;

                    bool same = SymbolEqualityComparer.Default.Equals(previous.Symbol, selected.Symbol);

                    if (index == role ? !same : same) return false;
                }

                roles[role] ??= selected;

                target = roles[role]!;

                return true;
            }

            root = roles[0]!;

            if (!HasEnumTailSourceShape(root, root, true)
                || root.Symbol.ReturnType.SpecialType != SpecialType.System_UInt32
                || root.Symbol.Parameters.Length != 1
                || !SymbolEqualityComparer.Default.Equals(root.Symbol.Parameters[0], parameter)
                || !SymbolEqualityComparer.Default.Equals(parameter.Type, root.Symbol.TypeParameters[0])
                || root.Syntax is not MethodDeclarationSyntax { ExpressionBody: null, Body.Statements: var statements }
                || statements.Count != 5
                || !TryEnumTailByteLocal(root, statements[0], out ILocalSymbol code, out InvocationExpressionSyntax copyCall)
                || !Bind(root, copyCall, 1, out AuthoredMember copy)
                || copy.Symbol.ReturnType.SpecialType != SpecialType.System_Byte
                || copy.Symbol.Parameters.Length != 1
                || !SymbolEqualityComparer.Default.Equals(copy.Symbol.Parameters[0].Type, copy.Symbol.TypeParameters[0])
                || root.Model.GetOperation(copyCall) is not IInvocationOperation { Arguments: [var copyArgument] }
                || !IsEnumTailReference(copyArgument.Value, parameter)) return false;

            for (int index = 0; index < 3; index++)
            {
                if (statements[index + 1] is not IfStatementSyntax
                    {
                        Else: null,
                        Condition: InvocationExpressionSyntax predicateCall,
                        Statement: BlockSyntax { Statements: [ReturnStatementSyntax { Expression: InvocationExpressionSyntax rangeCall }] },
                    }
                    || !Bind(root, predicateCall, index + 3, out AuthoredMember predicate)
                    || !IsEnumTailZeroParameterReturn(predicate, SpecialType.System_Boolean)
                    || !Bind(root, rangeCall, 9, out _)
                    || root.Model.GetOperation(rangeCall) is not IInvocationOperation { Arguments: [var value, var minimum, var maximum, var name] }
                    || !IsEnumTailReference(value.Value, code)
                    || !IsEnumTailByteLiteral(minimum.Value, 0)
                    || !IsEnumTailByteLiteral(maximum.Value, index + 1)
                    || !IsEnumTailName(name.Value, parameter)) return false;
            }

            if (statements[4] is not ReturnStatementSyntax { Expression: InvocationExpressionSyntax positiveCall }
                || !Bind(root, positiveCall, 7, out AuthoredMember positiveRange)
                || root.Model.GetOperation(positiveCall) is not IInvocationOperation { Arguments: [var positiveValue, var positiveName] }
                || !IsEnumTailReference(positiveValue.Value, code)
                || !IsEnumTailName(positiveName.Value, parameter)
                || SingleRuntimeEnumParameterUse(root, parameter) is not { } rootUse
                || rootUse != copyCall.ArgumentList.Arguments[0].Expression) return false;

            if (copy.Syntax is not MethodDeclarationSyntax
                {
                    ExpressionBody: null,
                    Body.Statements:
                    [
                        IfStatementSyntax
                        {
                            Else: null,
                            Condition: BinaryExpressionSyntax guard,
                            Statement: BlockSyntax { Statements: [ThrowStatementSyntax unsupported] },
                        },
                        ReturnStatementSyntax { Expression: InvocationExpressionSyntax asCall },
                    ],
                }
                || copy.Model.GetOperation(guard) is not IBinaryOperation
                {
                    OperatorKind: BinaryOperatorKind.ConditionalOr,
                    OperatorMethod: null,
                    IsLifted: false,
                    Type.SpecialType: SpecialType.System_Boolean,
                    LeftOperand: IBinaryOperation
                    {
                        OperatorKind: BinaryOperatorKind.NotEquals,
                        OperatorMethod: null,
                        IsLifted: false,
                        Type.SpecialType: SpecialType.System_Boolean,
                        LeftOperand: IInvocationOperation size,
                        RightOperand: ISizeOfOperation { TypeOperand.SpecialType: SpecialType.System_Byte, Type.SpecialType: SpecialType.System_Int32 },
                    },
                    RightOperand: IUnaryOperation
                    {
                        OperatorKind: UnaryOperatorKind.Not,
                        OperatorMethod: null,
                        IsLifted: false,
                        Type.SpecialType: SpecialType.System_Boolean,
                        Operand: IInvocationOperation { Syntax: InvocationExpressionSyntax supportedCall },
                    },
                }
                || !IsEnumTailSizeOf(copy, size)
                || !Bind(copy, supportedCall, 2, out AuthoredMember support)
                || !IsEnumTailZeroParameterReturn(support, SpecialType.System_Boolean)
                || !IsEnumTailException(copy, unsupported, "System.ArgumentException", copy.Symbol.Parameters[0])
                || asCall.ArgumentList.Arguments is not [ArgumentSyntax storage]
                || !IsOwnedEnumByteValueRead(copy, copy.Symbol.Parameters[0], storage)) return false;

            if (support.Syntax is not MethodDeclarationSyntax { Body: null, ExpressionBody.Expression: { } supportExpression }
                || !TryEnumTailOrLeaves(support, supportExpression, 4, out ExpressionSyntax[] supportTerms)) return false;

            for (int index = 0; index < supportTerms.Length; index++)
            {
                if (supportTerms[index] is not InvocationExpressionSyntax call
                    || !Bind(support, call, index == 3 ? 6 : index + 3, out _)) return false;
            }

            HashSet<ISymbol> enumerations = new(SymbolEqualityComparer.Default);

            for (int role = 3; role <= 6; role++)
            {
                AuthoredMember predicate = roles[role]!;

                if (!IsEnumTailZeroParameterReturn(predicate, SpecialType.System_Boolean)
                    || predicate.Syntax is not MethodDeclarationSyntax { Body: null, ExpressionBody.Expression: { } expression }
                    || !TryEnumTailTypeSet(predicate, expression, role == 6 ? 47 : 1, enumerations)) return false;
            }

            if (enumerations.Count != 50
                || positiveRange.Symbol.ReturnType.SpecialType != SpecialType.System_UInt32
                || positiveRange.Symbol.Parameters is not [var rangeValue, var rangeName]
                || rangeValue.Type.SpecialType != SpecialType.System_Byte
                || rangeName.Type.SpecialType != SpecialType.System_String
                || positiveRange.Syntax is not MethodDeclarationSyntax
                {
                    ExpressionBody: null,
                    Body.Statements: [var maximumStatement, ReturnStatementSyntax { Expression: InvocationExpressionSyntax finalRangeCall }],
                }
                || !TryEnumTailByteLocal(positiveRange, maximumStatement, out ILocalSymbol maximumLocal, out InvocationExpressionSyntax maximumCall)
                || !Bind(positiveRange, maximumCall, 8, out AuthoredMember maximumMember)
                || !IsEnumTailZeroParameterReturn(maximumMember, SpecialType.System_Byte)
                || !Bind(positiveRange, finalRangeCall, 9, out _)
                || positiveRange.Model.GetOperation(finalRangeCall) is not IInvocationOperation { Arguments: [var finalCode, var finalMinimum, var finalMaximum, var finalName] }
                || !IsEnumTailReference(finalCode.Value, rangeValue)
                || !IsEnumTailByteLiteral(finalMinimum.Value, 1)
                || !IsEnumTailReference(finalMaximum.Value, maximumLocal)
                || !IsEnumTailReference(finalName.Value, rangeName)
                || maximumMember.Syntax is not MethodDeclarationSyntax { ExpressionBody: null, Body.Statements: var maximumStatements }
                || maximumStatements.Count != 11) return false;

            int[] maxima = [16, 11, 8, 7, 7, 7, 6, 5, 4, 3];

            int[] typeCounts = [1, 1, 1, 1, 1, 1, 2, 1, 11, 13];

            HashSet<ISymbol> maximumTypes = new(SymbolEqualityComparer.Default);

            for (int index = 0; index < maxima.Length; index++)
            {
                if (maximumStatements[index] is not IfStatementSyntax
                    {
                        Else: null,
                        Condition: { } condition,
                        Statement: BlockSyntax { Statements: [ReturnStatementSyntax returned] },
                    }
                    || !TryEnumTailTypeSet(maximumMember, condition, typeCounts[index], maximumTypes)
                    || maximumMember.Model.GetOperation(returned) is not IReturnOperation { ReturnedValue: { } literal }
                    || !IsEnumTailByteLiteral(literal, maxima[index])) return false;
            }

            if (!maximumTypes.IsSubsetOf(enumerations)
                || maximumStatements[10] is not ReturnStatementSyntax fallback
                || maximumMember.Model.GetOperation(fallback) is not IReturnOperation { ReturnedValue: { } fallbackValue }
                || !IsEnumTailByteLiteral(fallbackValue, 2)) return false;

            AuthoredMember range = roles[9]!;

            return roles.All(static role => role is not null)
                && range.Symbol.ReturnType.SpecialType == SpecialType.System_UInt32
                && range.Symbol.Parameters is [var rangeCode, var rangeMinimum, var rangeMaximum, var parameterName]
                && rangeCode.Type.SpecialType == SpecialType.System_Byte
                && rangeMinimum.Type.SpecialType == SpecialType.System_Byte
                && rangeMaximum.Type.SpecialType == SpecialType.System_Byte
                && parameterName.Type.SpecialType == SpecialType.System_String
                && range.Syntax is MethodDeclarationSyntax { Body: null, ExpressionBody.Expression: ConditionalExpressionSyntax conditional }
                && range.Model.GetOperation(conditional) is IConditionalOperation
                {
                    IsRef: false,
                    Type.SpecialType: SpecialType.System_Byte,
                    Condition: IBinaryOperation
                    {
                        OperatorKind: BinaryOperatorKind.ConditionalAnd,
                        OperatorMethod: null,
                        IsLifted: false,
                        Type.SpecialType: SpecialType.System_Boolean,
                        LeftOperand: IBinaryOperation lower,
                        RightOperand: IBinaryOperation upper,
                    },
                    WhenTrue: { Type.SpecialType: SpecialType.System_Byte } accepted,
                    WhenFalse: { } rejected,
                } selectedConditional
                && IsEnumTailComparison(lower, BinaryOperatorKind.GreaterThanOrEqual, rangeCode, rangeMinimum)
                && IsEnumTailComparison(upper, BinaryOperatorKind.LessThanOrEqual, rangeCode, rangeMaximum)
                && IsEnumTailReference(accepted, rangeCode)
                && IsEnumTailUIntResult(selectedConditional)
                && conditional.WhenFalse is ThrowExpressionSyntax outOfRange
                && IsEnumTailRangeThrow(range, rejected, outOfRange)
                && IsEnumTailException(range, outOfRange, "System.ArgumentOutOfRangeException", parameterName);
        }

        private static bool IsEnumTailUIntResult(IConditionalOperation conditional)
        {
            // The authenticated compiler profile promotes the whole byte-valued
            // conditional, not its true arm. Only this exact return placement fits.
            return conditional.Type?.SpecialType == SpecialType.System_Byte
                && conditional.Parent is IConversionOperation
                {
                    IsImplicit: true,
                    IsChecked: false,
                    IsTryCast: false,
                    OperatorMethod: null,
                    Type.SpecialType: SpecialType.System_UInt32,
                    Conversion: { Exists: true, IsIdentity: false, IsNumeric: true, IsReference: false, IsUserDefined: false, MethodSymbol: null },
                    Parent: IReturnOperation { IsImplicit: true } returned,
                } conversion
                && ReferenceEquals(conversion.Operand, conditional)
                && ReferenceEquals(returned.ReturnedValue, conversion)
                && conversion.Syntax == conditional.Syntax && returned.Syntax == conditional.Syntax;
        }

        private static bool IsEnumTailRangeThrow(AuthoredMember member, IOperation operation, ThrowExpressionSyntax syntax)
        {
            // These are the compiler's exact throw-expression adaptation and
            // framework exception upcast, not primitive numeric conversions.
            return operation is IConversionOperation
                {
                    IsImplicit: true,
                    IsChecked: false,
                    IsTryCast: false,
                    OperatorMethod: null,
                    Type.SpecialType: SpecialType.System_Byte,
                    Conversion: { Exists: true, IsIdentity: false, IsNumeric: false, IsReference: false, IsUserDefined: false, MethodSymbol: null },
                    Operand: IThrowOperation
                    {
                        Type: null,
                        IsImplicit: false,
                        Exception: IConversionOperation
                        {
                            IsImplicit: true,
                            IsChecked: false,
                            IsTryCast: false,
                            OperatorMethod: null,
                            Conversion: { Exists: true, IsIdentity: false, IsNumeric: false, IsReference: true, IsUserDefined: false, MethodSymbol: null },
                            Operand: IObjectCreationOperation { IsImplicit: false, Constructor: { } constructor, Initializer: null } creation,
                        } upcast,
                    } thrown,
                }
                && operation.Syntax == syntax && thrown.Syntax == syntax
                && upcast.Syntax == syntax.Expression && creation.Syntax == syntax.Expression
                && SymbolEqualityComparer.Default.Equals(upcast.Type, member.Model.Compilation.GetTypeByMetadataName("System.Exception"))
                && SymbolEqualityComparer.Default.Equals(creation.Type, member.Model.Compilation.GetTypeByMetadataName("System.ArgumentOutOfRangeException"))
                && IsEnumTailFrameworkMethod(member.Model.Compilation, constructor, "System.ArgumentOutOfRangeException");
        }

        private static bool HasEnumTailSourceShape(AuthoredMember member, AuthoredMember root, bool generic)
        {
            IMethodSymbol symbol = member.Symbol;

            return symbol.MethodKind == MethodKind.Ordinary
                && symbol.IsStatic && !symbol.IsExtern && !symbol.IsAbstract && !symbol.IsVirtual && !symbol.IsOverride
                && !symbol.IsVararg && symbol.ReducedFrom is null && !symbol.ReturnsByRef && !symbol.ReturnsByRefReadonly
                && symbol.ContainingType.Arity == 0
                && SymbolEqualityComparer.Default.Equals(symbol.ContainingType, root.Symbol.ContainingType)
                && SymbolEqualityComparer.Default.Equals(symbol.ContainingAssembly, member.Model.Compilation.Assembly)
                && ReferenceEquals(member.Model.Compilation, root.Model.Compilation)
                && member.Syntax.SyntaxTree == root.Syntax.SyntaxTree
                && member.Model.Compilation.ContainsSyntaxTree(member.Syntax.SyntaxTree)
                && symbol.DeclaringSyntaxReferences is [var declaration]
                && declaration.SyntaxTree == member.Syntax.SyntaxTree && declaration.Span == member.Syntax.Span
                && member.Syntax is MethodDeclarationSyntax { Body: not null, ExpressionBody: null } or MethodDeclarationSyntax { Body: null, ExpressionBody: not null }
                && (generic ? HasFiniteEnumMethodShape(symbol, member.Model.Compilation) : symbol.Arity == 0)
                && symbol.Parameters.All(static parameter => parameter.RefKind == RefKind.None && !parameter.IsOptional && !parameter.IsParams)
                && !member.Syntax.DescendantNodes().Any(static syntax => syntax is AnonymousFunctionExpressionSyntax or LocalFunctionStatementSyntax);
        }

        private static bool IsEnumTailZeroParameterReturn(AuthoredMember member, SpecialType result)
        {
            return member.Symbol.Parameters.Length == 0 && member.Symbol.ReturnType.SpecialType == result;
        }

        private static bool TryEnumTailByteLocal(AuthoredMember member, StatementSyntax statement, out ILocalSymbol local, out InvocationExpressionSyntax call)
        {
            local = null!;

            call = null!;

            if (statement is not LocalDeclarationStatementSyntax
                {
                    Modifiers.Count: 0,
                    UsingKeyword.RawKind: 0,
                    AwaitKeyword.RawKind: 0,
                    Declaration.Variables: [VariableDeclaratorSyntax { Initializer.Value: InvocationExpressionSyntax initializer } declaration],
                }
                || member.Model.GetDeclaredSymbol(declaration) is not ILocalSymbol { RefKind: RefKind.None, Type.SpecialType: SpecialType.System_Byte } selected
                || !SymbolEqualityComparer.Default.Equals(selected.ContainingSymbol, member.Symbol)
                || member.Model.GetOperation(initializer) is not IInvocationOperation { Type.SpecialType: SpecialType.System_Byte }) return false;

            local = selected;

            call = initializer;

            return true;
        }

        private static bool IsEnumTailReference(IOperation operation, ISymbol symbol)
        {
            return operation.Syntax is IdentifierNameSyntax
                && (operation is IParameterReferenceOperation parameter && SymbolEqualityComparer.Default.Equals(parameter.Parameter, symbol)
                    || operation is ILocalReferenceOperation local && local.Local.RefKind == RefKind.None && SymbolEqualityComparer.Default.Equals(local.Local, symbol));
        }

        private static bool IsEnumTailName(IOperation operation, IParameterSymbol parameter)
        {
            return operation is INameOfOperation { Type.SpecialType: SpecialType.System_String, Argument: { } argument }
                && IsEnumTailReference(argument, parameter)
                && operation.ConstantValue is { HasValue: true, Value: string name } && name == parameter.Name;
        }

        private static bool IsEnumTailByteLiteral(IOperation operation, int expected)
        {
            // Only the actual fitting literal-to-byte conversion in a byte slot.
            return expected is >= byte.MinValue and <= byte.MaxValue
                && operation is IConversionOperation
                {
                    IsImplicit: true,
                    OperatorMethod: null,
                    Type.SpecialType: SpecialType.System_Byte,
                    Conversion: { Exists: true, IsIdentity: false, IsReference: false, IsUserDefined: false, MethodSymbol: null },
                    Operand: ILiteralOperation { Syntax: LiteralExpressionSyntax, Type.SpecialType: SpecialType.System_Int32, ConstantValue: { HasValue: true, Value: int value } },
                }
                && value == expected;
        }

        private static bool IsEnumTailPromotion(IOperation operation, SpecialType result, IParameterSymbol parameter)
        {
            return parameter.Type.SpecialType == SpecialType.System_Byte
                && result is SpecialType.System_Int32 or SpecialType.System_UInt32
                && operation is IConversionOperation
                {
                    IsImplicit: true,
                    OperatorMethod: null,
                    Conversion: { Exists: true, IsNumeric: true, IsUserDefined: false, MethodSymbol: null },
                    Operand: { Type.SpecialType: SpecialType.System_Byte } operand,
                }
                && operation.Type?.SpecialType == result
                && IsEnumTailReference(operand, parameter);
        }

        private static bool IsEnumTailComparison(IBinaryOperation operation, BinaryOperatorKind kind, IParameterSymbol left, IParameterSymbol right)
        {
            return operation.OperatorKind == kind && operation.OperatorMethod is null && !operation.IsLifted
                && operation.Type?.SpecialType == SpecialType.System_Boolean
                && IsEnumTailPromotion(operation.LeftOperand, SpecialType.System_Int32, left)
                && IsEnumTailPromotion(operation.RightOperand, SpecialType.System_Int32, right);
        }

        private static bool TryEnumTailOrLeaves(AuthoredMember member, ExpressionSyntax expression, int count, out ExpressionSyntax[] leaves)
        {
            List<ExpressionSyntax> pending = [expression];

            List<ExpressionSyntax> terms = [];

            // Each expansion consumes one of this fixed profile's finite ORs.
            for (int index = 0; index < pending.Count && pending.Count <= count * 2 - 1; index++)
            {
                ExpressionSyntax current = pending[index];

                if (current is BinaryExpressionSyntax binary && binary.IsKind(SyntaxKind.LogicalOrExpression))
                {
                    if (member.Model.GetOperation(binary) is not IBinaryOperation
                        {
                            OperatorKind: BinaryOperatorKind.ConditionalOr,
                            OperatorMethod: null,
                            IsLifted: false,
                            Type.SpecialType: SpecialType.System_Boolean,
                            LeftOperand.Type.SpecialType: SpecialType.System_Boolean,
                            RightOperand.Type.SpecialType: SpecialType.System_Boolean,
                        }) break;

                    pending.Add(binary.Left);

                    pending.Add(binary.Right);
                }
                else terms.Add(current);
            }

            leaves = terms.OrderBy(static term => term.SpanStart).ToArray();

            return pending.Count == count * 2 - 1 && leaves.Length == count;
        }

        private static bool TryEnumTailTypeSet(AuthoredMember member, ExpressionSyntax expression, int count, HashSet<ISymbol> types)
        {
            if (!TryEnumTailOrLeaves(member, expression, count, out ExpressionSyntax[] terms)) return false;

            foreach (ExpressionSyntax term in terms)
            {
                if (term is not BinaryExpressionSyntax { Left: TypeOfExpressionSyntax, Right: TypeOfExpressionSyntax }
                    || member.Model.GetOperation(term) is not IBinaryOperation
                    {
                        OperatorKind: BinaryOperatorKind.Equals,
                        IsLifted: false,
                        Type.SpecialType: SpecialType.System_Boolean,
                        OperatorMethod: { } equality,
                        LeftOperand: ITypeOfOperation left,
                        RightOperand: ITypeOfOperation right,
                    }
                    || !SymbolEqualityComparer.Default.Equals(left.TypeOperand, member.Symbol.TypeParameters[0])
                    || !IsClosedFiniteEnum(right.TypeOperand)
                    || right.TypeOperand is not INamedTypeSymbol { EnumUnderlyingType.SpecialType: SpecialType.System_Byte } enumeration
                    || !SymbolEqualityComparer.Default.Equals(enumeration.ContainingAssembly, member.Model.Compilation.Assembly)
                    || !IsEnumTailFrameworkMethod(member.Model.Compilation, equality, "System.Type")
                    || equality.MethodKind != MethodKind.UserDefinedOperator || equality.Name != "op_Equality"
                    || !equality.IsStatic || equality.Arity != 0 || equality.Parameters is not [var first, var second]
                    || equality.ReturnType.SpecialType != SpecialType.System_Boolean
                    || !SymbolEqualityComparer.Default.Equals(first.Type, equality.ContainingType)
                    || !SymbolEqualityComparer.Default.Equals(second.Type, equality.ContainingType)
                    || !SymbolEqualityComparer.Default.Equals(left.Type, equality.ContainingType)
                    || !SymbolEqualityComparer.Default.Equals(right.Type, equality.ContainingType)
                    || !types.Add(enumeration)) return false;
            }

            return true;
        }

        // Runtime Type Identity Comparison. Type == and != are classified when each operand is a
        // typeof expression or an exact System.Object.GetType() call, so both sides are always
        // RuntimeType values and the comparison is reference identity. An arbitrary Type value can
        // be any subclass whose Equals is authored, so it stays unclassified.
        private static bool IsReviewedExactTypeOfEqualityOperator(
            IMethodSymbol method,
            SyntaxNode? node,
            SemanticModel? model)
        {
            return node is BinaryExpressionSyntax
                && model?.GetOperation(node) is IBinaryOperation
                {
                    OperatorKind: BinaryOperatorKind.Equals or BinaryOperatorKind.NotEquals,
                    IsLifted: false,
                    Type.SpecialType: SpecialType.System_Boolean,
                    OperatorMethod: { } selected,
                    LeftOperand: { } left,
                    RightOperand: { } right,
                } comparison
                && SymbolEqualityComparer.Default.Equals(selected, method)
                && IsEnumTailFrameworkMethod(model.Compilation, method, "System.Type")
                && method.MethodKind == MethodKind.UserDefinedOperator
                && method.Name == (comparison.OperatorKind == BinaryOperatorKind.Equals ? "op_Equality" : "op_Inequality")
                && method.IsStatic
                && method.Arity == 0
                && method.Parameters is [var first, var second]
                && method.ReturnType.SpecialType == SpecialType.System_Boolean
                && SymbolEqualityComparer.Default.Equals(first.Type, method.ContainingType)
                && SymbolEqualityComparer.Default.Equals(second.Type, method.ContainingType)
                && IsRuntimeTypeIdentityOperand(left, method.ContainingType, model.Compilation)
                && IsRuntimeTypeIdentityOperand(right, method.ContainingType, model.Compilation);
        }

        private static bool IsRuntimeTypeIdentityOperand(IOperation operand, INamedTypeSymbol type, Compilation compilation)
        {
            if (!SymbolEqualityComparer.Default.Equals(operand.Type, type)) return false;

            if (operand is ITypeOfOperation) return operand.Syntax is TypeOfExpressionSyntax;

            return operand is IInvocationOperation
            {
                TargetMethod: { } getType,
                Instance: { } receiver,
                IsVirtual: false,
                Arguments.Length: 0,
            } call
                && call.Syntax is InvocationExpressionSyntax
                && getType is { Name: "GetType", MethodKind: MethodKind.Ordinary, IsStatic: false, Arity: 0, Parameters.IsEmpty: true }
                && SymbolEqualityComparer.Default.Equals(getType.ReturnType, type)
                && IsEnumTailFrameworkMethod(compilation, getType, "System.Object")
                && OperandUsesOnlyBuiltInConversions(receiver);
        }

        private static bool IsEnumTailFrameworkMethod(Compilation compilation, IMethodSymbol method, string metadataType)
        {
            IAssemblySymbol core = compilation.GetSpecialType(SpecialType.System_Object).ContainingAssembly;

            AssemblyIdentity assembly = core.Identity;

            string token = Convert.ToHexString(assembly.PublicKeyToken.AsSpan());

            return SymbolEqualityComparer.Default.Equals(method.ContainingAssembly, core)
                && SymbolEqualityComparer.Default.Equals(method.ContainingType, compilation.GetTypeByMetadataName(metadataType))
                && assembly.Version == new Version(10, 0, 0, 0) && string.IsNullOrEmpty(assembly.CultureName)
                && !assembly.IsRetargetable && assembly.ContentType == System.Reflection.AssemblyContentType.Default
                && (assembly.Name == "System.Private.CoreLib" && token == "7CEC85D7BEA7798E"
                    || assembly.Name == "System.Runtime" && token == "B03F5F7F11D50A3A")
                && method.DeclaringSyntaxReferences.Length == 0 && method.ContainingType.DeclaringSyntaxReferences.Length == 0
                && !method.Locations.Any(static location => location.IsInSource)
                && !method.IsVararg && method.ReducedFrom is null && !method.ReturnsByRef && !method.ReturnsByRefReadonly
                && method.Parameters.All(static parameter => parameter.RefKind == RefKind.None && !parameter.IsParams && !parameter.IsOptional);
        }

        private static bool IsEnumTailSizeOf(AuthoredMember member, IInvocationOperation operation)
        {
            IMethodSymbol method = operation.TargetMethod;

            return operation.Syntax is InvocationExpressionSyntax && !operation.IsVirtual && operation.Instance is null
                && operation.Arguments.Length == 0 && operation.Type?.SpecialType == SpecialType.System_Int32
                && IsEnumTailFrameworkMethod(member.Model.Compilation, method, "System.Runtime.CompilerServices.Unsafe")
                && method.Name == "SizeOf" && method.MethodKind == MethodKind.Ordinary && method.IsStatic
                && method.Arity == 1 && method.Parameters.Length == 0 && method.ReturnType.SpecialType == SpecialType.System_Int32
                && SymbolEqualityComparer.Default.Equals(method.TypeArguments[0], member.Symbol.TypeParameters[0])
                && method.OriginalDefinition.TypeParameters[0].TypeParameterKind == TypeParameterKind.Method
                && method.OriginalDefinition.TypeParameters[0].Ordinal == 0
                && SymbolEqualityComparer.Default.Equals(method.OriginalDefinition.TypeParameters[0].ContainingSymbol, method.OriginalDefinition);
        }

        private static bool IsEnumTailException(AuthoredMember member, SyntaxNode syntax, string metadataType, IParameterSymbol parameter)
        {
            ExpressionSyntax? expression = syntax switch
            {
                ThrowStatementSyntax statement => statement.Expression,
                ThrowExpressionSyntax thrown => thrown.Expression,
                _ => null,
            };

            if (expression is not ObjectCreationExpressionSyntax { Initializer: null }
                || member.Model.GetOperation(syntax) is not IThrowOperation
                || member.Model.GetOperation(expression) is not IObjectCreationOperation { Constructor: { } constructor, Initializer: null } creation
                || !IsEnumTailFrameworkMethod(member.Model.Compilation, constructor, metadataType)
                || constructor.MethodKind != MethodKind.Constructor || constructor.IsStatic || constructor.Arity != 0
                || constructor.Parameters.Any(static formal => formal.Type.SpecialType != SpecialType.System_String)
                || creation.Arguments.Where((argument, index) => argument.ArgumentKind != ArgumentKind.Explicit
                    || argument.Parameter?.Ordinal != index || !argument.InConversion.IsIdentity || !argument.OutConversion.IsIdentity).Any()) return false;

            if (metadataType == "System.ArgumentException")
            {
                return creation.Arguments is [var message, var name]
                    && constructor.Parameters.Length == 2
                    && message.Value is ILiteralOperation
                    {
                        Type.SpecialType: SpecialType.System_String,
                        ConstantValue: { HasValue: true, Value: "The enum type is not part of the Covenant policy-v1 manifest." },
                    }
                    && IsEnumTailName(name.Value, parameter);
            }

            return metadataType == "System.ArgumentOutOfRangeException"
                && constructor.Parameters.Length == 1 && creation.Arguments is [var parameterName]
                && IsEnumTailReference(parameterName.Value, parameter);
        }

        private static bool HasImmediateEnumByteMethodShape(AuthoredMember member)
        {
            return HasFiniteEnumMethodShape(member.Symbol, member.Model.Compilation)
                && !member.Symbol.IsExtern
                && member.Syntax is MethodDeclarationSyntax { Body: not null } or MethodDeclarationSyntax { ExpressionBody: not null }
                && member.Symbol.Parameters.Length == 1
                && SymbolEqualityComparer.Default.Equals(member.Symbol.Parameters[0].Type, member.Symbol.TypeParameters[0])
                && member.Symbol.ReturnType.SpecialType == SpecialType.System_Byte;
        }

        private static IdentifierNameSyntax? SingleRuntimeEnumParameterUse(AuthoredMember member, IParameterSymbol parameter)
        {
            IdentifierNameSyntax? runtime = null;

            // Include nested callable syntax: capture and unknown dependent uses
            // cannot disappear behind a false existential demand or an absent site.
            foreach (IdentifierNameSyntax use in member.Syntax.DescendantNodesAndSelf().OfType<IdentifierNameSyntax>())
            {
                if (!SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(use).Symbol, parameter)) continue;

                if (use.Ancestors().TakeWhile(node => node != member.Syntax).Any(static node => node is AnonymousFunctionExpressionSyntax or LocalFunctionStatementSyntax)) return null;

                if (use.Parent is ArgumentSyntax nameArgument
                    && nameArgument.Parent is ArgumentListSyntax { Parent: InvocationExpressionSyntax nameCall }
                    && member.Model.GetOperation(nameCall) is INameOfOperation { Argument: IParameterReferenceOperation nameReference }
                    && SymbolEqualityComparer.Default.Equals(nameReference.Parameter, parameter)) continue;

                if (runtime is not null) return null;

                runtime = use;
            }

            return runtime;
        }

        private static bool IsImmediateEnumByteReturn(AuthoredMember member, IInvocationOperation invocation, InvocationExpressionSyntax call)
        {
            if (!(call.Parent is ReturnStatementSyntax { Expression: { } returned } && returned == call
                    || call.Parent is ArrowExpressionClauseSyntax { Expression: { } expression } arrow
                        && expression == call && arrow.Parent == member.Syntax)) return false;

            IOperation consumed = invocation;

            while (consumed.Parent is IConversionOperation { Conversion.IsIdentity: true, OperatorMethod: null } conversion)
            {
                consumed = conversion;
            }

            return consumed.Parent is IReturnOperation result
                && result.ReturnedValue == consumed
                && consumed.Type?.SpecialType == SpecialType.System_Byte;
        }

        private static bool IsOwnedEnumByteValueRead(
            AuthoredMember target,
            IParameterSymbol parameter,
            ArgumentSyntax argument)
        {
            if (!HasFiniteEnumMethodShape(target.Symbol, target.Model.Compilation)
                || target.Symbol.Parameters.Length != 1
                || !SymbolEqualityComparer.Default.Equals(target.Symbol.Parameters[0], parameter)
                || !SymbolEqualityComparer.Default.Equals(parameter.Type, target.Symbol.TypeParameters[0])
                || target.Symbol.ReturnType.SpecialType != SpecialType.System_Byte
                || !argument.RefKindKeyword.IsKind(SyntaxKind.RefKeyword)
                || EnumCopyOperand(argument.Expression) is not IdentifierNameSyntax storage
                || !SymbolEqualityComparer.Default.Equals(target.Model.GetSymbolInfo(storage).Symbol, parameter)
                || target.Model.GetOperation(argument) is not IArgumentOperation selectedArgument
                || selectedArgument.Parent is not IInvocationOperation invocation
                || invocation.Syntax is not InvocationExpressionSyntax call
                || invocation.Arguments.Length != 1
                || invocation.IsVirtual
                || selectedArgument.Parameter is not { RefKind: RefKind.Ref } selectedParameter
                || !selectedArgument.InConversion.IsIdentity || !selectedArgument.OutConversion.IsIdentity
                || call.Ancestors().Any(static node => node is AnonymousFunctionExpressionSyntax or LocalFunctionStatementSyntax))
            {
                return false;
            }

            IOperation storageOperation = selectedArgument.Value;

            while (storageOperation is IParenthesizedOperation parenthesized) storageOperation = parenthesized.Operand;

            if (storageOperation is not IParameterReferenceOperation storageReference
                || !SymbolEqualityComparer.Default.Equals(storageReference.Parameter, parameter)) return false;

            IMethodSymbol selected = invocation.TargetMethod;

            IMethodSymbol definition = selected.OriginalDefinition;

            AssemblyIdentity assembly = selected.ContainingAssembly.Identity;

            string token = Convert.ToHexString(assembly.PublicKeyToken.AsSpan());

            if (!SymbolEqualityComparer.Default.Equals(selected.ContainingAssembly, target.Model.Compilation.GetSpecialType(SpecialType.System_Object).ContainingAssembly)
                || assembly.Version != new Version(10, 0, 0, 0)
                || !string.IsNullOrEmpty(assembly.CultureName)
                || assembly.IsRetargetable
                || assembly.ContentType != System.Reflection.AssemblyContentType.Default
                || !(assembly.Name == "System.Private.CoreLib" && token == "7CEC85D7BEA7798E"
                    || assembly.Name == "System.Runtime" && token == "B03F5F7F11D50A3A")
                || selected.Name != "As"
                || !SymbolEqualityComparer.Default.Equals(selected.ContainingType, target.Model.Compilation.GetTypeByMetadataName("System.Runtime.CompilerServices.Unsafe"))
                || selected.DeclaringSyntaxReferences.Length != 0
                || selected.ContainingType.DeclaringSyntaxReferences.Length != 0
                || selected.Locations.Any(static location => location.IsInSource)
                || selected.MethodKind != MethodKind.Ordinary || !selected.IsStatic
                || selected.ReducedFrom is not null || selected.IsVararg
                || selected.Arity != 2 || selected.Parameters.Length != 1
                || !selected.ReturnsByRef || selected.ReturnsByRefReadonly
                || selected.Parameters[0].RefKind != RefKind.Ref
                || !SymbolEqualityComparer.Default.Equals(selectedParameter, selected.Parameters[0])
                || !SymbolEqualityComparer.Default.Equals(selected.TypeArguments[0], target.Symbol.TypeParameters[0])
                || selected.TypeArguments[1].SpecialType != SpecialType.System_Byte
                || !SymbolEqualityComparer.Default.Equals(selected.Parameters[0].Type, selected.TypeArguments[0])
                || !SymbolEqualityComparer.Default.Equals(selected.ReturnType, selected.TypeArguments[1])
                || definition.TypeParameters[0].Ordinal != 0 || definition.TypeParameters[1].Ordinal != 1
                || definition.TypeParameters.Any(type => type.TypeParameterKind != TypeParameterKind.Method
                    || !SymbolEqualityComparer.Default.Equals(type.ContainingSymbol, definition))
                || !SymbolEqualityComparer.Default.Equals(definition.Parameters[0].Type, definition.TypeParameters[0])
                || !SymbolEqualityComparer.Default.Equals(definition.ReturnType, definition.TypeParameters[1])
                || !SymbolEqualityComparer.Default.Equals(selectedParameter.OriginalDefinition, definition.Parameters[0]))
            {
                return false;
            }

            // Conditional compiler/source profile only: the intended intrinsic
            // returns an alias, and this exact authored form consumes a byte value.
            // This neither proves native lowering nor skips type/size guards/effects.
            if (!(call.Parent is ReturnStatementSyntax { Expression: { } returned } && returned == call
                    || call.Parent is ArrowExpressionClauseSyntax { Expression: { } expression } arrow
                        && expression == call && arrow.Parent == target.Syntax)) return false;

            IOperation consumed = invocation;

            while (consumed.Parent is IConversionOperation { Conversion.IsIdentity: true, OperatorMethod: null } conversion)
            {
                consumed = conversion;
            }

            if (consumed.Parent is not IReturnOperation returnedOperation
                || returnedOperation.ReturnedValue != consumed
                || consumed.Type?.SpecialType != SpecialType.System_Byte) return false;

            int storageUses = 0;

            foreach (IdentifierNameSyntax use in target.Syntax.DescendantNodesAndSelf().OfType<IdentifierNameSyntax>())
            {
                if (!SymbolEqualityComparer.Default.Equals(target.Model.GetSymbolInfo(use).Symbol, parameter)) continue;

                if (use == storage)
                {
                    storageUses++;
                    continue;
                }

                if (use.Parent is ArgumentSyntax nameArgument
                    && nameArgument.Parent is ArgumentListSyntax { Parent: InvocationExpressionSyntax nameCall }
                    && target.Model.GetOperation(nameCall) is INameOfOperation { Argument: IParameterReferenceOperation nameReference }
                    && SymbolEqualityComparer.Default.Equals(nameReference.Parameter, parameter)) continue;

                return false;
            }

            return storageUses == 1;
        }

        private bool RequiresExactValueProvenance(
            AuthoredMember target,
            IParameterSymbol parameter)
        {
            var identity = (MemberIdentity(target), parameter.Ordinal);

            if (exactValueProvenanceRequirements.TryGetValue(
                    identity,
                    out bool cached))
            {
                return cached;
            }

            bool result = RequiresExactValueProvenance(
                target,
                parameter,
                new HashSet<(GraphMemberIdentity Member, int Parameter)>());

            exactValueProvenanceRequirements.Add(identity, result);

            return result;
        }

        private bool RequiresExactValueProvenance(
            AuthoredMember target,
            IParameterSymbol parameter,
            HashSet<(GraphMemberIdentity Member, int Parameter)> visited)
        {
            var identity = (MemberIdentity(target), parameter.Ordinal);

            // This is one existential reachability query. Keep every inspected
            // node visited across sibling edges, and cache only the root result.
            // A cycle cutoff is not a reusable negative result for its member.
            if (!visited.Add(identity))
            {
                return false;
            }

            EvaluationEnvironmentCounter(target).ExactValueProvenanceVisits++;

            if (RequiresSourceProvenance(parameter.Type))
            {
                return true;
            }

            foreach (ExpressionSyntax expression in target.Syntax.DescendantNodesAndSelf(node =>
                node == target.Syntax
                    || node is not AnonymousFunctionExpressionSyntax and not LocalFunctionStatementSyntax)
                .OfType<ExpressionSyntax>())
            {
                // A closed-value record whose authored Equals can reach no producer site reads no operand
                // provenance: the canonical traversal binds that Equals with no arguments. Every other
                // record still needs the actual argument preserved. Keeping the demand for a pure
                // closed-value comparison would split every caller of a one-line comparison helper into
                // one state per call site.
                if (UserDefinedOperatorAt(target, expression) is { Method: { IsImplicitlyDeclared: true,
                        ContainingType.IsRecord: true, Name: "op_Equality" or "op_Inequality" } } equality
                    && equality.Operands.Any(operand => operand.Syntax is ExpressionSyntax source
                        && ExpressionDependsOnSymbol(target, source, parameter,
                            new HashSet<ISymbol>(SymbolEqualityComparer.Default), symbols: dependencySymbols))
                    && !IsProvenanceFreeClosedValueRecordEquality(target, equality.Method))
                {
                    // Preserve the actual argument before an authored Equals receiver
                    // is bound; a concrete record type alone does not identify its fields.
                    return true;
                }

                // The Structural Operand Rule classifies an exact framework scalar conversion from its own
                // operand syntax, so it never reads the value a caller passed for one of its formals.
            }

            if (target.Syntax.DescendantNodesAndSelf(node =>
                        node == target.Syntax
                        || node is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .OfType<ElementAccessExpressionSyntax>()
                    .Any(access => target.Model.GetTypeInfo(
                                access.Expression).Type is { } receiverType
                            && RequiresSourceProvenance(receiverType)
                            && ExpressionDependsOnSymbol(
                                target,
                                access.Expression,
                                parameter,
                                new HashSet<ISymbol>(
                                    SymbolEqualityComparer.Default), symbols: dependencySymbols)))
            {
                return true;
            }

            // The new numeric eligibility guard must see incoming compiler-contextual
            // values. Request only arguments consumed by its exact authenticated shapes;
            // existing binding and dependency machinery carries those complete sources.
            foreach (ExpressionSyntax use in target.Syntax.DescendantNodesAndSelf(node =>
                node == target.Syntax
                    || node is not AnonymousFunctionExpressionSyntax and not LocalFunctionStatementSyntax)
                .OfType<ExpressionSyntax>()
                .Where(static expression => expression is InvocationExpressionSyntax or BaseObjectCreationExpressionSyntax))
            {
                (IMethodSymbol? Method, IEnumerable<IArgumentOperation> Arguments) selected = target.Model.GetOperation(use) switch
                {
                    IInvocationOperation invocation => (invocation.TargetMethod, invocation.Arguments),
                    IObjectCreationOperation creation => (creation.Constructor, creation.Arguments),
                    _ => (null, []),
                };

                // Only the consumers that still read a caller's value keep the demand: the Long Rest
                // histogram arguments (hierarchy observation) and the primitive queue receiver (its default
                // origin). The pure float intrinsics and the queue arguments need only the argument boundary.
                if (selected.Method is { } method
                    && (IsExactPrimitiveQueueMember(method) || IsExactLongRestHistogramRecord(method))
                    && (IsExactLongRestHistogramRecord(method)
                            && selected.Arguments.Any(argument => argument.Value.Syntax is ExpressionSyntax expression
                                && ExpressionDependsOnSymbol(target, expression, parameter,
                                    new HashSet<ISymbol>(SymbolEqualityComparer.Default), symbols: dependencySymbols))
                        || IsExactPrimitiveQueueMember(method) && target.Model.GetOperation(use) is IInvocationOperation
                            { Instance.Syntax: ExpressionSyntax receiver }
                            && ExpressionDependsOnSymbol(target, receiver, parameter,
                                new HashSet<ISymbol>(SymbolEqualityComparer.Default), symbols: dependencySymbols)))
                {
                    return true;
                }
            }

            bool cleanupCapable =
                TypeMayCarryCleanupProvenance(parameter.Type);

            foreach (SyntaxNode node in target.Syntax.DescendantNodesAndSelf(
                candidate => candidate == target.Syntax
                    || candidate is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax))
            {
                ExpressionSyntax? cleanupResource = node switch
                {
                    UsingStatementSyntax { Expression: { } expression } =>
                        expression,
                    VariableDeclaratorSyntax
                    {
                        Initializer.Value: { } initializer,
                        Parent: VariableDeclarationSyntax
                        {
                            Parent: LocalDeclarationStatementSyntax
                            {
                                UsingKeyword.RawKind: not 0,
                            } or UsingStatementSyntax,
                        },
                    } => initializer,
                    _ => null,
                };

                if (cleanupResource is null)
                {
                    continue;
                }

                ExpressionSyntax effectiveResource =
                    TryConfiguredAsyncDisposableReceiver(
                        target,
                        cleanupResource)
                    ?? StripTransparentExpression(cleanupResource);

                if (SymbolEqualityComparer.Default.Equals(
                        target.Model.GetSymbolInfo(effectiveResource).Symbol,
                        parameter))
                {
                    if (cleanupCapable
                        || parameter.Type is not INamedTypeSymbol
                        {
                            TypeKind: TypeKind.Struct,
                        }
                            and not INamedTypeSymbol
                            {
                                TypeKind: TypeKind.Class,
                                IsAbstract: false,
                                IsSealed: true,
                            })
                    {
                        return true;
                    }

                    continue;
                }

                if (ExpressionDependsOnSymbol(
                    target,
                    cleanupResource,
                    parameter,
                    new HashSet<ISymbol>(SymbolEqualityComparer.Default), symbols: dependencySymbols))
                {
                    if (cleanupCapable)
                    {
                        return true;
                    }

                    ITypeSymbol? cleanupType =
                        target.Model.GetTypeInfo(effectiveResource).Type;

                    if (cleanupType is not INamedTypeSymbol
                        {
                            TypeKind: TypeKind.Struct,
                            IsAbstract: false,
                        }
                        and not INamedTypeSymbol
                        {
                            TypeKind: TypeKind.Class,
                            IsAbstract: false,
                            IsSealed: true,
                        })
                    {
                        return true;
                    }
                }
            }

            foreach (SyntaxNode node in target.Syntax.DescendantNodesAndSelf(
                candidate => candidate == target.Syntax
                    || candidate is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax))
            {
                ExpressionSyntax? mutationTarget = node switch
                {
                    AssignmentExpressionSyntax assignment => assignment.Left,
                    PrefixUnaryExpressionSyntax prefix
                        when prefix.IsKind(SyntaxKind.PreIncrementExpression)
                            || prefix.IsKind(SyntaxKind.PreDecrementExpression) =>
                        prefix.Operand,
                    PostfixUnaryExpressionSyntax postfix
                        when postfix.IsKind(SyntaxKind.PostIncrementExpression)
                            || postfix.IsKind(SyntaxKind.PostDecrementExpression) =>
                        postfix.Operand,
                    _ => null,
                };

                if (mutationTarget is not null
                    && SymbolEqualityComparer.Default.Equals(
                        target.Model.GetSymbolInfo(
                            MutationRoot(mutationTarget)).Symbol,
                        parameter))
                {
                    return true;
                }

                if (node is ArgumentSyntax argument
                    && argument.RefKindKeyword.Kind() is
                        SyntaxKind.RefKeyword or SyntaxKind.OutKeyword
                    && SymbolEqualityComparer.Default.Equals(
                        target.Model.GetSymbolInfo(argument.Expression).Symbol,
                        parameter)
                    && !IsOwnedEnumByteValueRead(target, parameter, argument))
                {
                    return true;
                }
            }

            foreach (InvocationExpressionSyntax call in target.Syntax
                .DescendantNodesAndSelf(node => node == target.Syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<InvocationExpressionSyntax>())
            {
                if (target.Model.GetSymbolInfo(call).Symbol is not
                        IMethodSymbol method
                    || target.Model.GetOperation(call) is not
                        IInvocationOperation operation)
                {
                    continue;
                }

                AuthoredMember[] callees = method.MethodKind
                        == MethodKind.DelegateInvoke
                    ? ResolveCallableTargets(
                        DelegateReceiver(target, call),
                        target.Model,
                        target.CallableBindings,
                        target.AbsentCallables)
                    : Resolve(method, target.Model.Compilation) is { } resolvedCallee
                        ? [resolvedCallee]
                        : [];

                if (IsExactFrameworkType(
                            parameter.Type,
                            "Microsoft.Extensions.DependencyInjection.IServiceScopeFactory",
                            typeof(Microsoft.Extensions.DependencyInjection.IServiceScopeFactory).Assembly.GetName())
                        && IsExactFrameworkMethod(
                            method,
                            "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions",
                            "CreateAsyncScope",
                            "Microsoft.Extensions.DependencyInjection.Abstractions")
                    && operation.Arguments.Any(argument => argument.Parameter?.Ordinal == 0
                        && argument.Value.Syntax is ExpressionSyntax source
                        && ExpressionDependsOnSymbol(target, source, parameter, new HashSet<ISymbol>(SymbolEqualityComparer.Default), symbols: dependencySymbols)))
                {
                    return true;
                }

                if (AdmissionReceiver(target, call) is { } receiver
                    && ExpressionDependsOnSymbol(
                        target,
                        receiver,
                        parameter,
                        new HashSet<ISymbol>(SymbolEqualityComparer.Default), symbols: dependencySymbols))
                {
                    ITypeSymbol? receiverType = target.Model.GetTypeInfo(
                        StripTransparentExpression(receiver)).Type;

                    bool receiverTargetCarriesCleanupState =
                        ResolveReceiverTargets(
                                method,
                                target.Model.Compilation)
                            .Any(ReceiverTargetMayCarryCleanupState);

                    bool cleanupCapableReceiverUse = cleanupCapable
                        && (receiverType is null
                            || TypeMayCarryCleanupProvenance(receiverType))
                        && !IsTrustedNonOwningSafeHandleObservation(method);

                    if (receiverTargetCarriesCleanupState
                        || cleanupCapableReceiverUse)
                    {
                        return true;
                    }
                }

                foreach (AuthoredMember callee in callees)
                {
                    foreach (IArgumentOperation argument in operation.Arguments)
                    {
                        if (argument.Parameter is not { } sourceParameter
                            || sourceParameter.Ordinal >=
                                callee.Symbol.Parameters.Length
                            || argument.Syntax is not ArgumentSyntax syntax
                            || !ExpressionDependsOnSymbol(
                                target,
                                syntax.Expression,
                                parameter,
                                new HashSet<ISymbol>(
                                    SymbolEqualityComparer.Default), symbols: dependencySymbols))
                        {
                            continue;
                        }

                        IParameterSymbol destination = callee.Symbol.Parameters[sourceParameter.Ordinal];

                        if (IsEnumConstrainedParameter(callee, destination)
                            && !IsPlainOwnEnumForwarding(target, parameter, callee, destination, argument))
                        {
                            return true;
                        }

                        if (RequiresExactValueProvenance(
                            callee,
                            destination,
                            visited))
                        {
                            return true;
                        }
                    }
                }
            }

            foreach (InvocationExpressionSyntax callbackCall in target.Syntax
                .DescendantNodesAndSelf(node => node == target.Syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<InvocationExpressionSyntax>())
            {
                foreach (ArgumentSyntax argument in callbackCall.ArgumentList.Arguments
                    .Where(argument =>
                        !argument.RefKindKeyword.IsKind(SyntaxKind.OutKeyword)
                        && IsDelegateExpression(
                            target.Model,
                            argument.Expression)))
                {
                    foreach (AuthoredMember callback in ResolveCallableTargets(
                        argument.Expression,
                        target.Model,
                        target.CallableBindings,
                        target.AbsentCallables))
                    {
                        if (CapturedCallableRequiresExactValueProvenance(
                            callback,
                            parameter,
                            visited))
                        {
                            return true;
                        }
                    }
                }
            }

            return false;
        }

        private static bool IsTrustedNonOwningSafeHandleObservation(
            IMethodSymbol method)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            return definition.MethodKind == MethodKind.Ordinary
                && !definition.IsStatic
                && definition.Parameters.Length == 0
                && TypeKey(definition.ReturnType) == "System.IntPtr"
                && IsExactFrameworkMethod(
                    definition,
                    "System.Runtime.InteropServices.SafeHandle",
                    "DangerousGetHandle",
                    "System.Private.CoreLib");
        }

        private bool PrimaryConstructorCapturedReceiverCarriesCleanupState(
            AuthoredMember member)
        {
            return PrimaryConstructorCapturedReceiverCarriesCleanupState(
                member,
                new HashSet<GraphMemberIdentity>());
        }

        private bool ReceiverTargetMayCarryCleanupState(AuthoredMember target)
        {
            return ReceiverTargetMayCarryCleanupState(
                target,
                new HashSet<GraphMemberIdentity>(),
                ReceiverCleanupForwardingMaximumDepth);
        }

        private bool ReceiverTargetMayCarryCleanupState(
            AuthoredMember target,
            HashSet<GraphMemberIdentity> path,
            int remainingDepth)
        {
            if (!target.Symbol.ContainingType.IsSealed
                || remainingDepth <= 0)
            {
                return true;
            }

            GraphMemberIdentity identity = MemberIdentity(target);

            if (!path.Add(identity))
            {
                return false;
            }

            try
            {
                if (target.Syntax.DescendantNodesAndSelf(node =>
                            node == target.Syntax
                            || node is not AnonymousFunctionExpressionSyntax
                                and not LocalFunctionStatementSyntax)
                        .OfType<ExpressionSyntax>()
                        .Select(expression =>
                            target.Model.GetSymbolInfo(expression).Symbol)
                        .Any(symbol => symbol switch
                        {
                            IFieldSymbol { IsStatic: false } field =>
                                TypeMayCarryCleanupProvenance(field.Type)
                                    || RequiresSourceProvenance(field.Type),
                            IPropertySymbol { IsStatic: false } property =>
                                TypeMayCarryCleanupProvenance(property.Type)
                                    || RequiresSourceProvenance(property.Type),
                            IParameterSymbol
                            {
                                ContainingSymbol: IMethodSymbol
                                {
                                    MethodKind: MethodKind.Constructor,
                                } constructor,
                                DeclaringSyntaxReferences:
                                [SyntaxReference parameterReference],
                            } parameter =>
                                SymbolEqualityComparer.Default.Equals(
                                    constructor.ContainingType,
                                    target.Symbol.ContainingType)
                                && parameterReference.GetSyntax() is
                                    ParameterSyntax
                                {
                                    Parent: ParameterListSyntax
                                    {
                                        Parent: TypeDeclarationSyntax,
                                    },
                                }
                                && TypeMayCarryCleanupProvenance(
                                    parameter.Type),
                            _ => false,
                        })
                    || target.Symbol.ContainingType.GetMembers()
                        .OfType<IFieldSymbol>()
                        .Any(static field => !field.IsStatic
                            && field.IsReadOnly
                            && TypeMayCarryCleanupProvenance(field.Type))
                    || PrimaryConstructorCapturedReceiverCarriesCleanupState(
                        target))
                {
                    return true;
                }

                IParameterSymbol[] cleanupParameters = target.Symbol
                    .ContainingType.InstanceConstructors
                    .SelectMany(static constructor => constructor.Parameters)
                    .Where(static parameter => TypeMayCarryCleanupProvenance(
                        parameter.Type))
                    .ToArray();

                if (cleanupParameters.Length > 0
                    && DeclaredRootDemandedConstructionBindings(
                        target,
                        target.Syntax,
                        cleanupParameters).Any())
                {
                    return true;
                }

                foreach (InvocationExpressionSyntax call in target.Syntax
                    .DescendantNodesAndSelf(node => node == target.Syntax
                        || node is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .OfType<InvocationExpressionSyntax>())
                {
                    if (!InvocationCanExecuteFromEntry(target, call)
                        || target.Model.GetSymbolInfo(call).Symbol is not
                            IMethodSymbol method)
                    {
                        continue;
                    }

                    if (StripTransparentExpression(call.Expression) is
                            IdentifierNameSyntax or GenericNameSyntax
                            or MemberAccessExpressionSyntax
                            {
                                Expression: ThisExpressionSyntax,
                            })
                    {
                        AuthoredMember? sameInstanceTarget =
                            ResolveInvocationTarget(method, target, call)
                            ?? Resolve(method, target.Model.Compilation);

                        if (sameInstanceTarget is
                            { Symbol.IsStatic: false }
                            && SymbolEqualityComparer.Default.Equals(
                                sameInstanceTarget.Symbol.ContainingType,
                                target.Symbol.ContainingType)
                            && ReceiverTargetMayCarryCleanupState(
                                sameInstanceTarget,
                                path,
                                remainingDepth - 1))
                        {
                            return true;
                        }
                    }

                    if (AdmissionReceiver(target, call) is not { } receiver)
                    {
                        continue;
                    }

                    receiver = StripTransparentExpression(receiver);

                    ISymbol? receiverSymbol = target.Model
                        .GetSymbolInfo(receiver).Symbol;

                    bool currentInstanceMember = receiverSymbol switch
                    {
                        IFieldSymbol { IsStatic: false } field =>
                            SymbolEqualityComparer.Default.Equals(
                                field.ContainingType,
                                target.Symbol.ContainingType),
                        IPropertySymbol { IsStatic: false } property =>
                            SymbolEqualityComparer.Default.Equals(
                                property.ContainingType,
                                target.Symbol.ContainingType),
                        _ => false,
                    };

                    bool directMemberAccess = receiver is IdentifierNameSyntax
                        || receiver is MemberAccessExpressionSyntax
                        {
                            Expression: ThisExpressionSyntax,
                        };

                    if (!currentInstanceMember || !directMemberAccess)
                    {
                        continue;
                    }

                    foreach (AuthoredMember receiverTarget in ResolveReceiverTargets(
                        method,
                        target.Model.Compilation))
                    {
                        if (ReceiverTargetMayCarryCleanupState(
                            receiverTarget,
                            path,
                            remainingDepth - 1))
                        {
                            return true;
                        }
                    }
                }

                return false;
            }
            finally
            {
                _ = path.Remove(identity);
            }
        }

        private AuthoredMember[] ResolveReceiverTargets(
            IMethodSymbol method,
            Compilation consumingCompilation)
        {
            if (method.ContainingType.TypeKind != TypeKind.Interface)
            {
                return Resolve(method, consumingCompilation) is { } target
                    ? [target]
                    : [];
            }

            return AuthoredMembers
                .Where(candidate =>
                    candidate.Symbol.ContainingType.AllInterfaces
                        .Where(contract =>
                            contract.ContainingAssembly.Identity.Equals(
                                method.ContainingAssembly.Identity)
                            && TypeKey(contract) == TypeKey(method.ContainingType))
                        .SelectMany(static contract => contract.GetMembers())
                        .OfType<IMethodSymbol>()
                        .Any(slot => MethodKey(slot) == MethodKey(method)
                            && candidate.Symbol.ContainingType
                                .FindImplementationForInterfaceMember(slot) is
                                IMethodSymbol implementation
                            && SymbolEqualityComparer.Default.Equals(
                                implementation.OriginalDefinition,
                                candidate.Symbol.OriginalDefinition)))
                .DistinctBy(MemberIdentity)
                .ToArray();
        }

        private bool PrimaryConstructorCapturedReceiverCarriesCleanupState(
            AuthoredMember member,
            HashSet<GraphMemberIdentity> path)
        {
            GraphMemberIdentity identity = MemberIdentity(member);

            if (!path.Add(identity))
            {
                return false;
            }

            try
            {
                foreach (InvocationExpressionSyntax call in member.Syntax
                    .DescendantNodesAndSelf(node => node == member.Syntax
                        || node is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .OfType<InvocationExpressionSyntax>())
                {
                    if (member.Model.GetSymbolInfo(call).Symbol is not
                        IMethodSymbol method)
                    {
                        continue;
                    }

                    if (AdmissionReceiver(member, call) is { } receiver
                        && member.Model.GetSymbolInfo(receiver).Symbol is
                            IParameterSymbol
                        {
                            ContainingSymbol: IMethodSymbol
                            {
                                MethodKind: MethodKind.Constructor,
                            } constructor,
                        } parameter
                        && SymbolEqualityComparer.Default.Equals(
                            constructor.ContainingType,
                            member.Symbol.ContainingType)
                        && parameter.DeclaringSyntaxReferences is
                            [SyntaxReference parameterReference]
                        && parameterReference.GetSyntax() is ParameterSyntax
                        {
                            Parent: ParameterListSyntax
                            {
                                Parent: TypeDeclarationSyntax,
                            },
                        })
                    {
                        if (TypeMayCarryCleanupProvenance(parameter.Type))
                        {
                            return true;
                        }

                        AuthoredMember[] targets = ResolveReceiverTargets(
                            method,
                            member.Model.Compilation);

                        if (targets.Any(static target =>
                            target.Symbol.ContainingType.IsSealed
                            && target.Symbol.ContainingType.GetMembers()
                                .OfType<IFieldSymbol>()
                                .Any(static field => !field.IsStatic
                                    && field.IsReadOnly
                                    && TypeMayCarryCleanupProvenance(field.Type))))
                        {
                            return true;
                        }
                    }

                    if (!method.IsStatic
                        && SymbolEqualityComparer.Default.Equals(
                            method.ContainingType,
                            member.Symbol.ContainingType)
                        && Resolve(method, member.Model.Compilation) is { } delegated
                        && PrimaryConstructorCapturedReceiverCarriesCleanupState(
                            delegated,
                            path))
                    {
                        return true;
                    }
                }

                return false;
            }
            finally
            {
                _ = path.Remove(identity);
            }
        }

        private bool CapturedCallableRequiresExactValueProvenance(
            AuthoredMember callback,
            ISymbol captured,
            HashSet<(GraphMemberIdentity Member, int Parameter)> path)
        {
            foreach (SyntaxNode node in callback.Syntax.DescendantNodesAndSelf(
                candidate => candidate == callback.Syntax
                    || candidate is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax))
            {
                ExpressionSyntax? cleanupResource = node switch
                {
                    UsingStatementSyntax { Expression: { } expression } =>
                        expression,
                    VariableDeclaratorSyntax
                    {
                        Initializer.Value: { } initializer,
                        Parent: VariableDeclarationSyntax
                        {
                            Parent: LocalDeclarationStatementSyntax
                            {
                                UsingKeyword.RawKind: not 0,
                            } or UsingStatementSyntax,
                        },
                    } => initializer,
                    _ => null,
                };

                if (cleanupResource is not null
                    && ExpressionDependsOnSymbol(
                        callback,
                        cleanupResource,
                        captured,
                        new HashSet<ISymbol>(SymbolEqualityComparer.Default), symbols: dependencySymbols))
                {
                    return true;
                }
            }

            foreach (InvocationExpressionSyntax call in callback.Syntax
                .DescendantNodesAndSelf(node => node == callback.Syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<InvocationExpressionSyntax>())
            {
                if (callback.Model.GetSymbolInfo(call).Symbol is not
                        IMethodSymbol method
                    || Resolve(method, callback.Model.Compilation) is not
                    { } callee
                    || callback.Model.GetOperation(call) is not
                        IInvocationOperation operation)
                {
                    continue;
                }

                foreach (IArgumentOperation argument in operation.Arguments)
                {
                    if (argument.Parameter is not { } sourceParameter
                        || sourceParameter.Ordinal >=
                            callee.Symbol.Parameters.Length
                        || argument.Syntax is not ArgumentSyntax syntax
                        || !ExpressionDependsOnSymbol(
                            callback,
                            syntax.Expression,
                            captured,
                            new HashSet<ISymbol>(
                                SymbolEqualityComparer.Default), symbols: dependencySymbols))
                    {
                        continue;
                    }

                    if (IsEnumConstrainedParameter(callee, callee.Symbol.Parameters[sourceParameter.Ordinal])
                        || RequiresExactValueProvenance(
                        callee,
                        callee.Symbol.Parameters[sourceParameter.Ordinal],
                        path))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        internal static HostedProducerExpressionDependencyProbe
            ProbeExpressionDependency(
                CSharpCompilation compilation,
                IMethodSymbol method,
                ExpressionSyntax expression,
                ISymbol required)
        {
            SyntaxNode syntax = method.DeclaringSyntaxReferences
                .Select(static reference => reference.GetSyntax())
                .Single();

            TraversalRecoveryProjectionAnalysisCounter analysis = new();

            bool depends = ExpressionDependsOnSymbol(
                new(
                    method,
                    syntax,
                    compilation.GetSemanticModel(syntax.SyntaxTree)),
                expression,
                required,
                new HashSet<ISymbol>(SymbolEqualityComparer.Default),
                analysis);

            return new(
                depends,
                analysis.AssignmentScans,
                analysis.AssignmentInspections,
                analysis.DependencyNodes,
                analysis.DependencyCacheHits);
        }

        internal IReadOnlyList<HostedProducerDependencySymbolProbe> ProbeDependencySymbolLookups(
            IMethodSymbol method,
            IReadOnlyList<(SemanticModel Model, ExpressionSyntax Expression, ISymbol Required, bool BindingClone)> queries)
        {
            SyntaxNode syntax = method.DeclaringSyntaxReferences.Single().GetSyntax();

            List<HostedProducerDependencySymbolProbe> results = [];

            foreach (var query in queries)
            {
                AuthoredMember member = new(method, syntax, query.Model);

                if (query.BindingClone)
                {
                    member = member with
                    {
                        CallableBindings = new Dictionary<ISymbol, AuthoredMember>(SymbolEqualityComparer.Default),
                        AbsentCallables = new HashSet<ISymbol>(SymbolEqualityComparer.Default) { query.Required },
                    };
                }

                TraversalRecoveryProjectionAnalysisCounter analysis = new();

                int requests = dependencySymbols.Requests;

                int builds = dependencySymbols.Builds;

                int hits = dependencySymbols.Hits;

                int nullBuilds = dependencySymbols.NullBuilds;

                ExpressionDependencyResult result = EvaluateExpressionDependency(member, query.Expression, query.Required, new HashSet<ISymbol>(SymbolEqualityComparer.Default), new Dictionary<ExpressionSyntax, bool>(ReferenceEqualityComparer.Instance), analysis, dependencySymbols);

                results.Add(new(result.Depends, result.Complete, analysis.DependencyNodes, dependencySymbols.Requests - requests, dependencySymbols.Builds - builds, dependencySymbols.Hits - hits, dependencySymbols.NullBuilds - nullBuilds));
            }

            return results;
        }

        internal IReadOnlyList<HostedProducerDependencyScopeProbe> ProbeDependencyScopes(
            IReadOnlyList<HostedProducerDependencyScopeQuery> queries,
            bool useContext)
        {
            List<HostedProducerDependencyScopeProbe> results = [];

            foreach (HostedProducerDependencyScopeQuery query in queries)
            {
                AuthoredMember member = new(query.Method, query.Scope, query.Model);

                if (query.BindingClone)
                {
                    member = member with { AbsentCallables = new HashSet<ISymbol>(SymbolEqualityComparer.Default) { query.Required } };
                }

                TraversalRecoveryProjectionAnalysisCounter analysis = new();

                int requests = dependencySymbols.AssignmentRequests;

                int builds = dependencySymbols.AssignmentBuilds;

                int hits = dependencySymbols.AssignmentHits;

                int symbolBuilds = dependencySymbols.Builds;

                ExpressionDependencyResult result = EvaluateExpressionDependency(member, query.Expression, query.Required, new HashSet<ISymbol>(SymbolEqualityComparer.Default), new Dictionary<ExpressionSyntax, bool>(ReferenceEqualityComparer.Instance), analysis, useContext ? dependencySymbols : null);

                results.Add(new(result.Depends, result.Complete, analysis.DependencyNodes, analysis.AssignmentScans, analysis.AssignmentInspections, dependencySymbols.AssignmentRequests - requests, dependencySymbols.AssignmentBuilds - builds, dependencySymbols.AssignmentHits - hits, analysis.UncachedAssignmentEnumerations + dependencySymbols.AssignmentBuilds - builds, dependencySymbols.Builds - symbolBuilds));
            }

            return results;
        }

        private static IEnumerable<AssignmentExpressionSyntax> EnumerateDependencyAssignments(SyntaxNode scope) =>
            scope.DescendantNodesAndSelf(node => node == scope
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<AssignmentExpressionSyntax>();

        private sealed class DependencySymbolLookupContext
        {
            private readonly Dictionary<SemanticModel, Dictionary<SyntaxNode, ISymbol?>> symbols = new(ReferenceEqualityComparer.Instance);

            private readonly Dictionary<SyntaxNode, ImmutableArray<AssignmentExpressionSyntax>> assignments = new(ReferenceEqualityComparer.Instance);

            internal int Requests { get; private set; }

            internal int Builds { get; private set; }

            internal int Hits { get; private set; }

            internal int NullBuilds { get; private set; }

            internal int AssignmentRequests { get; private set; }

            internal int AssignmentBuilds { get; private set; }

            internal int AssignmentHits { get; private set; }

            internal ImmutableArray<AssignmentExpressionSyntax> Assignments(SyntaxNode scope)
            {
                AssignmentRequests++;

                if (assignments.TryGetValue(scope, out ImmutableArray<AssignmentExpressionSyntax> cached))
                {
                    AssignmentHits++;

                    return cached;
                }

                AssignmentBuilds++;

                ImmutableArray<AssignmentExpressionSyntax> ordered = EnumerateDependencyAssignments(scope).ToImmutableArray();

                assignments.Add(scope, ordered);

                return ordered;
            }

            internal ISymbol? Lookup(SemanticModel model, SyntaxNode node)
            {
                Requests++;

                if (!symbols.TryGetValue(model, out Dictionary<SyntaxNode, ISymbol?>? modelSymbols))
                {
                    modelSymbols = new(ReferenceEqualityComparer.Instance);

                    symbols.Add(model, modelSymbols);
                }

                if (modelSymbols.TryGetValue(node, out ISymbol? cached))
                {
                    Hits++;

                    return cached;
                }

                Builds++;

                ISymbol? symbol = model.GetSymbolInfo(node).Symbol;

                if (symbol is null)
                {
                    NullBuilds++;
                }

                modelSymbols.Add(node, symbol);

                return symbol;
            }
        }

        private static bool ExpressionDependsOnSymbol(
            AuthoredMember member,
            ExpressionSyntax expression,
            ISymbol required,
            HashSet<ISymbol> path,
            TraversalRecoveryProjectionAnalysisCounter? analysis = null,
            DependencySymbolLookupContext? symbols = null) =>
            EvaluateExpressionDependency(
                member,
                expression,
                required,
                path,
                new Dictionary<ExpressionSyntax, bool>(
                    ReferenceEqualityComparer.Instance),
                analysis,
                symbols)
            .Depends;

        private readonly record struct ExpressionDependencyResult(
            bool Depends,
            bool Complete);

        private static ExpressionDependencyResult EvaluateExpressionDependency(
            AuthoredMember member,
            ExpressionSyntax expression,
            ISymbol required,
            HashSet<ISymbol> path,
            Dictionary<ExpressionSyntax, bool> completed,
            TraversalRecoveryProjectionAnalysisCounter? analysis,
            DependencySymbolLookupContext? symbols = null)
        {
            if (completed.TryGetValue(expression, out bool cached))
            {
                if (analysis is not null)
                {
                    analysis.DependencyCacheHits++;
                }

                return new(cached, Complete: true);
            }

            bool complete = true;

            foreach (ExpressionSyntax candidate in expression
                .DescendantNodesAndSelf(node => node is not InvocationExpressionSyntax
                    || member.Model.GetOperation(node) is not INameOfOperation)
                .OfType<ExpressionSyntax>())
            {
                if (analysis is not null)
                {
                    analysis.DependencyNodes++;

                    if (symbols is null)
                    {
                        analysis.UncachedSymbolQueries++;
                    }
                }

                ISymbol? symbol = symbols is null
                    ? member.Model.GetSymbolInfo(candidate).Symbol
                    : symbols.Lookup(member.Model, candidate);

                if (SymbolEqualityComparer.Default.Equals(symbol, required))
                {
                    completed[expression] = true;

                    return new(Depends: true, Complete: true);
                }

                if (symbol is not ILocalSymbol local)
                {
                    continue;
                }

                if (!path.Add(local))
                {
                    complete = false;

                    continue;
                }

                try
                {
                    IEnumerable<ExpressionSyntax> AssignmentValues()
                    {
                        if (analysis is not null)
                        {
                            analysis.AssignmentScans++;

                            if (symbols is null)
                            {
                                analysis.UncachedAssignmentEnumerations++;
                            }
                        }

                        IEnumerable<AssignmentExpressionSyntax> assignments = symbols is null
                            ? EnumerateDependencyAssignments(member.Syntax)
                            : symbols.Assignments(member.Syntax);

                        foreach (AssignmentExpressionSyntax assignment in assignments)
                        {
                            if (analysis is not null)
                            {
                                analysis.AssignmentInspections++;
                            }

                            if (assignment.SpanStart < expression.SpanStart
                                && assignment.IsKind(
                                    SyntaxKind.SimpleAssignmentExpression))
                            {
                                if (analysis is not null && symbols is null)
                                {
                                    analysis.UncachedSymbolQueries++;
                                }

                                if (SymbolEqualityComparer.Default.Equals(
                                    symbols is null
                                        ? member.Model.GetSymbolInfo(assignment.Left).Symbol
                                        : symbols.Lookup(member.Model, assignment.Left),
                                    local))
                                {
                                    yield return assignment.Right;
                                }
                            }
                        }
                    }

                    IEnumerable<ExpressionSyntax> values =
                        local.DeclaringSyntaxReferences
                            .Select(static reference => reference.GetSyntax())
                            .OfType<VariableDeclaratorSyntax>()
                            .Select(static variable => variable.Initializer?.Value)
                            .OfType<ExpressionSyntax>()
                            .Concat(AssignmentValues());

                    foreach (ExpressionSyntax value in values)
                    {
                        ExpressionDependencyResult dependency =
                            EvaluateExpressionDependency(
                                member,
                                value,
                                required,
                                path,
                                completed,
                                analysis,
                                symbols);

                        if (dependency.Depends)
                        {
                            completed[expression] = true;

                            return new(Depends: true, Complete: true);
                        }

                        if (!dependency.Complete)
                        {
                            complete = false;
                        }
                    }
                }
                finally
                {
                    _ = path.Remove(local);
                }
            }

            if (complete)
            {
                completed[expression] = false;
            }

            return new(Depends: false, complete);
        }

        private bool IsStableKnownBooleanArgument(AuthoredMember caller, ExpressionSyntax expression)
        {
            Dictionary<AuthoredMember, HashSet<ExpressionSyntax>> path = new(ReferenceEqualityComparer.Instance);

            for (int depth = 0; depth < evaluationEnvironmentMaximumDepth; depth++)
            {
                while (expression is ParenthesizedExpressionSyntax parenthesized)
                {
                    expression = parenthesized.Expression;
                }

                if (!path.TryGetValue(caller, out HashSet<ExpressionSyntax>? expressions))
                {
                    expressions = new(ReferenceEqualityComparer.Instance);

                    path.Add(caller, expressions);
                }

                if (!expressions.Add(expression))
                {
                    return false;
                }

                if (caller.Model.GetConstantValue(expression) is { HasValue: true, Value: bool })
                {
                    return !expression.DescendantNodesAndSelf().OfType<IdentifierNameSyntax>()
                        .Any(reference => caller.Model.GetSymbolInfo(reference).Symbol is ILocalSymbol);
                }

                if (expression is not IdentifierNameSyntax
                    || caller.Model.GetSymbolInfo(expression).Symbol is not IParameterSymbol
                    {
                        RefKind: RefKind.None,
                        Type.SpecialType: SpecialType.System_Boolean,
                    }
                    || !TryResolveStableBoundValueSource(caller, expression, out BoundValueSource? source)
                    || source is null)
                {
                    return false;
                }

                caller = source.Caller;

                expression = source.Expression;
            }

            return false;
        }

        private static bool RequiresConstantControlProvenance(
            AuthoredMember target,
            IParameterSymbol parameter)
        {
            if (ExactConstantControlParameters.Contains(
                    Normalize(target.Symbol) + "#" + parameter.Name))
            {
                return true;
            }

            return target.Symbol.ExplicitInterfaceImplementations.Any(
                implementation => ExactConstantControlParameters.Contains(
                    TypeKey(implementation.ContainingType)
                        + "."
                        + implementation.Name
                        + "#"
                        + parameter.Name));
        }

        private static bool RequiresSourceProvenance(ITypeSymbol type)
        {
            string key = TypeKey(type);

            if (key is "System.Collections.Generic.List`1"
                or "System.Collections.Hashtable"
                or "System.Collections.ObjectModel.ReadOnlyCollection`1")
            {
                return true;
            }

            if (type is IArrayTypeSymbol
                || ReviewedInMemoryEnumerableTypes.Contains(key))
            {
                return false;
            }

            if (key is
                    "System.IO.Stream"
                        or "System.IO.StreamReader"
                        or "System.Collections.IEnumerable"
                        or "System.Collections.Generic.IEnumerable`1"
                        or "System.Collections.Generic.IAsyncEnumerable`1"
                        or "System.Collections.IEnumerator"
                        or "System.Collections.Generic.IEnumerator`1"
                        or "System.Collections.Generic.IAsyncEnumerator`1")
            {
                return true;
            }

            for (INamedTypeSymbol? current = type as INamedTypeSymbol;
                current is not null;
                current = current.BaseType)
            {
                if (TypeKey(current) is
                    "System.IO.Stream" or "System.IO.StreamReader")
                {
                    return true;
                }
            }

            return type is INamedTypeSymbol named
                && named.AllInterfaces.Any(static candidate =>
                    TypeKey(candidate) is
                        "System.Collections.IEnumerable"
                            or "System.Collections.Generic.IEnumerable`1"
                            or "System.Collections.Generic.IAsyncEnumerable`1"
                            or "System.Collections.IEnumerator"
                            or "System.Collections.Generic.IEnumerator`1"
                            or "System.Collections.Generic.IAsyncEnumerator`1");
        }

        private static ExpressionSyntax MutationRoot(ExpressionSyntax target)
        {
            target = StripTransparentExpression(target);

            while (target is MemberAccessExpressionSyntax member)
            {
                target = StripTransparentExpression(member.Expression);
            }

            while (target is ElementAccessExpressionSyntax element)
            {
                target = StripTransparentExpression(element.Expression);

                while (target is MemberAccessExpressionSyntax member)
                {
                    target = StripTransparentExpression(member.Expression);
                }
            }

            return target;
        }

        private RecoveryTuple? BoundRecoveryTuple(
            AuthoredMember member,
            ExpressionSyntax expression,
            HashSet<ISymbol> path)
        {
            _ = path;

            RecoveryTupleProvenance provenance = RecoveryTupleProvenanceOf(
                member,
                expression,
                new RecoveryTupleProvenanceContext());

            return provenance.Complete
                ? provenance.Tuple
                : null;
        }

        private RecoveryTupleProvenance RecoveryTupleProvenanceOf(
            AuthoredMember member,
            ExpressionSyntax expression,
            RecoveryTupleProvenanceContext context)
        {
            expression = StripTransparentExpression(expression);

            RecoveryTupleProvenanceIdentity identity = new(
                MemberIdentity(member),
                RecoveryBindingIdentity(member),
                ConcreteBindingIdentity(member),
                expression.SpanStart,
                expression.Span.Length);

            if (context.Cache.TryGetValue(
                    identity,
                    out RecoveryTupleProvenance cached))
            {
                return cached;
            }

            if (context.RemainingWork-- <= 0
                || !context.Active.Add(identity))
            {
                return default;
            }

            RecoveryTupleProvenance result;

            try
            {
                result = RecoveryTupleProvenanceCore(
                    member,
                    expression,
                    context);
            }
            finally
            {
                _ = context.Active.Remove(identity);
            }

            context.Cache[identity] = result;

            return result;
        }

        private RecoveryTupleProvenance RecoveryTupleProvenanceCore(
            AuthoredMember member,
            ExpressionSyntax expression,
            RecoveryTupleProvenanceContext context)
        {
            if (expression is ConditionalExpressionSyntax conditional)
            {
                return MergeRecoveryTupleProvenance([
                    RecoveryTupleProvenanceOf(
                        member,
                        conditional.WhenTrue,
                        context),
                    RecoveryTupleProvenanceOf(
                        member,
                        conditional.WhenFalse,
                        context),
                ]);
            }

            if (expression is SwitchExpressionSyntax selection)
            {
                return MergeRecoveryTupleProvenance(selection.Arms.Select(arm =>
                    RecoveryTupleProvenanceOf(
                        member,
                        arm.Expression,
                        context)));
            }

            if (expression is BaseObjectCreationExpressionSyntax creation
                && member.Model.GetTypeInfo(creation).Type is { } createdType
                && TypeKey(createdType)
                    == "RetroDownfall.Arcanum.Core.Operations.LongRunningOperation"
                && member.Model.GetOperation(creation) is
                    IObjectCreationOperation operation)
            {
                object? Argument(string name) => operation.Arguments
                    .SingleOrDefault(argument => string.Equals(
                        argument.Parameter?.Name,
                        name,
                        StringComparison.OrdinalIgnoreCase))
                    ?.Value.ConstantValue is
                {
                    HasValue: true,
                } constant
                        ? constant.Value
                        : null;

                if (Argument("Kind") is string kind
                    && Argument("CheckpointVersion") is int checkpointVersion)
                {
                    RecoveryMatrix matrix = ResolveRecoveryMatrix(creation);

                    RecoveryTuple[] matches = matrix.Tuples
                        .Where(tuple => tuple.Kind == kind
                            && tuple.CheckpointVersion == checkpointVersion)
                        .ToArray();

                    return matches is [RecoveryTuple exact]
                        ? new(exact, true)
                        : default;
                }
            }

            ISymbol? symbol = member.Model.GetSymbolInfo(expression).Symbol;

            if (symbol is null)
            {
                return default;
            }

            if (member.RecoveryBindings?.TryGetValue(
                    symbol,
                    out RecoveryTuple bound) == true)
            {
                return RecoveryTupleSourceIsStable(
                    member,
                    symbol,
                    expression,
                    allowSimpleLocalAssignments: false)
                        ? new(bound, true)
                        : default;
            }

            if (expression is InvocationExpressionSyntax call
                && symbol is IMethodSymbol method
                && ResolveInvocationTarget(method, member, call) is { } target)
            {
                AuthoredMember factory = BindInvocationContext(
                    member,
                    call,
                    target,
                    context);

                ExpressionSyntax[] returned = ReturnedExpressions(factory.Syntax);

                return returned.Length == 0
                    ? default
                    : MergeRecoveryTupleProvenance(returned.Select(value =>
                        RecoveryTupleProvenanceOf(
                            factory,
                            value,
                            context)));
            }

            if (symbol is not ILocalSymbol local
                || local.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax() is not
                    VariableDeclaratorSyntax variable
                || !RecoveryTupleSourceIsStable(
                    member,
                    local,
                    expression,
                    allowSimpleLocalAssignments: true))
            {
                return default;
            }

            List<ExpressionSyntax> values = variable.Initializer is null
                ? []
                : [variable.Initializer.Value];

            if (variable.Ancestors().OfType<BlockSyntax>().FirstOrDefault() is { } block)
            {
                values.AddRange(block.DescendantNodes(node =>
                        node == block
                        || node is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .OfType<AssignmentExpressionSyntax>()
                    .Where(assignment => assignment.IsKind(
                            SyntaxKind.SimpleAssignmentExpression)
                        && assignment.SpanStart < expression.SpanStart
                        && SymbolEqualityComparer.Default.Equals(
                            member.Model.GetSymbolInfo(assignment.Left).Symbol,
                            local))
                    .Select(static assignment => assignment.Right));
            }

            return values.Count == 0
                ? default
                : MergeRecoveryTupleProvenance(values.Select(value =>
                    RecoveryTupleProvenanceOf(
                        member,
                        value,
                        context)));
        }

        private static RecoveryTupleProvenance MergeRecoveryTupleProvenance(
            IEnumerable<RecoveryTupleProvenance> values)
        {
            RecoveryTupleProvenance[] provenance = values.ToArray();

            RecoveryTuple[] exact = provenance
                .Where(static value => value.Complete && value.Tuple is not null)
                .Select(static value => value.Tuple!.Value)
                .Distinct()
                .ToArray();

            return provenance.Length != 0
                && provenance.All(static value => value.Complete)
                && exact is [RecoveryTuple tuple]
                    ? new(tuple, true)
                    : default;
        }

        private static bool RecoveryTupleSourceIsStable(
            AuthoredMember member,
            ISymbol symbol,
            ExpressionSyntax use,
            bool allowSimpleLocalAssignments)
        {
            IEnumerable<SyntaxNode> directNodes = member.Syntax.DescendantNodesAndSelf(node =>
                node == member.Syntax
                || node is not AnonymousFunctionExpressionSyntax
                    and not LocalFunctionStatementSyntax);

            foreach (SyntaxNode node in directNodes.Where(node =>
                node.SpanStart < use.SpanStart))
            {
                if (node is AssignmentExpressionSyntax assignment
                    && SyntaxReferencesSymbol(
                        member.Model,
                        assignment.Left,
                        symbol)
                    && (!allowSimpleLocalAssignments
                        || !assignment.IsKind(
                            SyntaxKind.SimpleAssignmentExpression)
                        || !SymbolEqualityComparer.Default.Equals(
                            member.Model.GetSymbolInfo(assignment.Left).Symbol,
                            symbol)))
                {
                    return false;
                }

                if (node is ArgumentSyntax argument
                    && argument.RefKindKeyword.Kind() is
                        SyntaxKind.RefKeyword or SyntaxKind.OutKeyword
                    && SyntaxReferencesSymbol(
                        member.Model,
                        argument.Expression,
                        symbol))
                {
                    return false;
                }

                if (node is RefExpressionSyntax reference
                    && SyntaxReferencesSymbol(
                        member.Model,
                        reference.Expression,
                        symbol))
                {
                    return false;
                }

                if (node is PrefixUnaryExpressionSyntax prefix
                    && prefix.Kind() is SyntaxKind.PreIncrementExpression
                        or SyntaxKind.PreDecrementExpression)
                {
                    if (SyntaxReferencesSymbol(
                            member.Model,
                            prefix.Operand,
                            symbol))
                    {
                        return false;
                    }
                }

                if (node is PostfixUnaryExpressionSyntax postfix
                    && postfix.Kind() is SyntaxKind.PostIncrementExpression
                        or SyntaxKind.PostDecrementExpression)
                {
                    if (SyntaxReferencesSymbol(
                            member.Model,
                            postfix.Operand,
                            symbol))
                    {
                        return false;
                    }
                }
            }

            return !InvokedCallableMayMutateSymbol(
                member,
                symbol,
                use.SpanStart);
        }

        private static bool InvokedCallableMayMutateSymbol(
            AuthoredMember member,
            ISymbol symbol,
            int before,
            int after = int.MinValue)
        {
            const int MaxCallableWork = 256;

            int work = 0;

            Dictionary<IMethodSymbol, LocalFunctionStatementSyntax> localFunctions =
                new(SymbolEqualityComparer.Default);

            foreach (LocalFunctionStatementSyntax function in member.Syntax
                .DescendantNodes().OfType<LocalFunctionStatementSyntax>())
            {
                if (member.Model.GetDeclaredSymbol(function) is { } functionSymbol)
                {
                    localFunctions[functionSymbol] = function;
                }
            }

            AnonymousFunctionExpressionSyntax[] anonymousFunctions = member.Syntax
                .DescendantNodes()
                .OfType<AnonymousFunctionExpressionSyntax>()
                .ToArray();

            bool ReferencesSymbol(ExpressionSyntax expression) =>
                SyntaxReferencesSymbol(member.Model, expression, symbol);

            IEnumerable<SyntaxNode> DirectNodes(SyntaxNode root) =>
                root.DescendantNodesAndSelf(candidate =>
                    candidate == root
                    || candidate is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax);

            bool DirectlyMutates(SyntaxNode callable) =>
                DirectNodes(callable).Any(node => node switch
                {
                    AssignmentExpressionSyntax assignment =>
                        ReferencesSymbol(assignment.Left),
                    ArgumentSyntax argument when argument.RefKindKeyword.Kind() is
                        SyntaxKind.RefKeyword or SyntaxKind.OutKeyword =>
                        ReferencesSymbol(argument.Expression),
                    RefExpressionSyntax reference =>
                        ReferencesSymbol(reference.Expression),
                    PrefixUnaryExpressionSyntax prefix when prefix.IsKind(
                            SyntaxKind.PreIncrementExpression)
                        || prefix.IsKind(SyntaxKind.PreDecrementExpression) =>
                        ReferencesSymbol(prefix.Operand),
                    PostfixUnaryExpressionSyntax postfix when postfix.IsKind(
                            SyntaxKind.PostIncrementExpression)
                        || postfix.IsKind(SyntaxKind.PostDecrementExpression) =>
                        ReferencesSymbol(postfix.Operand),
                    _ => false,
                });

            HashSet<IMethodSymbol> directlyMutatingLocalFunctions = new(
                localFunctions
                    .Where(pair => DirectlyMutates(pair.Value))
                    .Select(static pair => pair.Key),
                SymbolEqualityComparer.Default);

            bool anonymousFunctionMutates = anonymousFunctions.Any(DirectlyMutates);

            Dictionary<IMethodSymbol, bool> memo = new(
                SymbolEqualityComparer.Default);

            bool LocalFunctionMayMutate(
                IMethodSymbol method,
                HashSet<IMethodSymbol> path)
            {
                if (memo.TryGetValue(method, out bool known))
                {
                    return known;
                }

                if (++work > MaxCallableWork
                    || directlyMutatingLocalFunctions.Contains(method))
                {
                    return true;
                }

                if (!localFunctions.TryGetValue(method, out LocalFunctionStatementSyntax? function)
                    || !path.Add(method))
                {
                    return false;
                }

                bool result = DirectNodes(function)
                    .OfType<InvocationExpressionSyntax>()
                    .Select(invocation => member.Model.GetSymbolInfo(invocation).Symbol)
                    .OfType<IMethodSymbol>()
                    .Any(target => target.MethodKind == MethodKind.DelegateInvoke
                        && (anonymousFunctionMutates
                            || directlyMutatingLocalFunctions.Count != 0)
                        || LocalFunctionMayMutate(target, path));

                _ = path.Remove(method);

                memo[method] = result;

                return result;
            }

            bool CallbackMayMutate(
                ExpressionSyntax expression,
                int invocationPosition,
                HashSet<ISymbol> path)
            {
                if (++work > MaxCallableWork)
                {
                    return true;
                }

                expression = StripTransparentExpression(expression);

                if (expression is AnonymousFunctionExpressionSyntax anonymous)
                {
                    return DirectlyMutates(anonymous)
                        || DirectNodes(anonymous)
                            .OfType<InvocationExpressionSyntax>()
                            .Select(call => member.Model.GetSymbolInfo(call).Symbol)
                            .OfType<IMethodSymbol>()
                            .Any(target => LocalFunctionMayMutate(
                                target,
                                new(SymbolEqualityComparer.Default)));
                }

                ISymbol? callback = member.Model.GetSymbolInfo(expression).Symbol;

                if (callback is IMethodSymbol method)
                {
                    return LocalFunctionMayMutate(
                        method,
                        new(SymbolEqualityComparer.Default));
                }

                if (callback is not ILocalSymbol
                    {
                        Type.TypeKind: TypeKind.Delegate,
                    } local)
                {
                    return callback is IParameterSymbol
                    {
                        Type.TypeKind: TypeKind.Delegate,
                    };
                }

                if (!path.Add(local))
                {
                    return true;
                }

                try
                {
                    List<ExpressionSyntax> values = [];

                    if (local.DeclaringSyntaxReferences.SingleOrDefault()
                            ?.GetSyntax() is VariableDeclaratorSyntax
                        {
                            Initializer.Value: { } initializer,
                        }
                        && initializer.SpanStart < invocationPosition)
                    {
                        values.Add(initializer);
                    }

                    values.AddRange(member.Syntax.DescendantNodes(node =>
                            node == member.Syntax
                                || node is not AnonymousFunctionExpressionSyntax
                                    and not LocalFunctionStatementSyntax)
                        .OfType<AssignmentExpressionSyntax>()
                        .Where(assignment => assignment.IsKind(
                                SyntaxKind.SimpleAssignmentExpression)
                            && assignment.SpanStart < invocationPosition
                            && SymbolEqualityComparer.Default.Equals(
                                member.Model.GetSymbolInfo(assignment.Left).Symbol,
                                local))
                        .Select(static assignment => assignment.Right));

                    return values.Count == 0
                        || values.Any(value => CallbackMayMutate(
                            value,
                            invocationPosition,
                            path));
                }
                finally
                {
                    _ = path.Remove(local);
                }
            }

            IEnumerable<SyntaxNode> rootNodes = DirectNodes(member.Syntax);

            foreach (InvocationExpressionSyntax invocation in rootNodes
                .OfType<InvocationExpressionSyntax>()
                .Where(invocation => invocation.SpanStart > after
                    && invocation.Span.End <= before))
            {
                if (member.Model.GetSymbolInfo(invocation).Symbol is not
                    IMethodSymbol method)
                {
                    continue;
                }

                if (method.MethodKind == MethodKind.DelegateInvoke
                    && (anonymousFunctionMutates
                        || directlyMutatingLocalFunctions.Count != 0)
                    || AdmissionArguments(member, invocation).Any(argument =>
                        (argument.Parameter?.Type.TypeKind == TypeKind.Delegate
                            || member.Model.GetTypeInfo(argument.Expression)
                                .ConvertedType?.TypeKind == TypeKind.Delegate)
                        && CallbackMayMutate(
                            argument.Expression,
                            invocation.SpanStart,
                            new(SymbolEqualityComparer.Default)))
                    || LocalFunctionMayMutate(
                        method,
                        new(SymbolEqualityComparer.Default)))
                {
                    return true;
                }
            }

            return false;
        }

        private static IEnumerable<(ExpressionSyntax Expression, IParameterSymbol? Parameter, RefKind RefKind)> AdmissionArguments(AuthoredMember caller, InvocationExpressionSyntax call)
        {
            if (caller.Model.GetOperation(call) is IInvocationOperation invocation)
            {
                // Roslyn includes the reduced extension receiver as an implicit argument to formal 0.
                foreach (IArgumentOperation argument in invocation.Arguments)
                {
                    if (argument.ArgumentKind == ArgumentKind.DefaultValue)
                    {
                        continue;
                    }

                    if ((argument.Syntax is ArgumentSyntax syntax ? syntax.Expression : argument.Value.Syntax) is ExpressionSyntax expression)
                    {
                        yield return (expression, argument.Parameter, argument.Parameter?.RefKind ?? RefKind.None);
                    }
                }
            }
            else
            {
                foreach (ArgumentSyntax argument in call.ArgumentList.Arguments)
                {
                    yield return (argument.Expression, null, argument.RefKindKeyword.IsKind(SyntaxKind.OutKeyword) ? RefKind.Out : argument.RefKindKeyword.IsKind(SyntaxKind.RefKeyword) ? RefKind.Ref : RefKind.None);
                }
            }
        }

        private static IEnumerable<(ExpressionSyntax Expression, IParameterSymbol? Parameter, RefKind RefKind)> ConstructorArguments(
            AuthoredMember caller,
            BaseObjectCreationExpressionSyntax creation)
        {
            if (caller.Model.GetOperation(creation) is IObjectCreationOperation operation)
            {
                foreach (IArgumentOperation argument in operation.Arguments)
                {
                    if (argument.ArgumentKind == ArgumentKind.DefaultValue)
                    {
                        continue;
                    }

                    if ((argument.Syntax is ArgumentSyntax syntax
                            ? syntax.Expression
                            : argument.Value.Syntax) is ExpressionSyntax expression)
                    {
                        yield return (
                            expression,
                            argument.Parameter,
                            argument.Parameter?.RefKind ?? RefKind.None);
                    }
                }

                yield break;
            }

            foreach (ArgumentSyntax argument in creation.ArgumentList?.Arguments ?? default)
            {
                yield return (
                    argument.Expression,
                    null,
                    argument.RefKindKeyword.IsKind(SyntaxKind.OutKeyword)
                        ? RefKind.Out
                        : argument.RefKindKeyword.IsKind(SyntaxKind.RefKeyword)
                            ? RefKind.Ref
                            : RefKind.None);
            }
        }

        private static ExpressionSyntax? AdmissionReceiver(AuthoredMember member, InvocationExpressionSyntax call) => member.Model.GetOperation(call) is IInvocationOperation { Instance.Syntax: ExpressionSyntax receiver } ? receiver : null;

        private static bool IsStableAcrossAdmissionCleanupBackEdges(
            AuthoredMember member,
            ExpressionSyntax expression,
            ISymbol symbol)
        {
            int through = expression.Span.End;

            foreach (SyntaxNode loop in expression.Ancestors().Where(node =>
                node is ForStatementSyntax or CommonForEachStatementSyntax
                    or WhileStatementSyntax or DoStatementSyntax
                && member.Syntax.Span.Contains(node.Span)))
            {
                through = Math.Max(through, loop.Span.End);
            }

            foreach (GotoStatementSyntax jump in member.Syntax
                .DescendantNodesAndSelf(node => node == member.Syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<GotoStatementSyntax>()
                .Where(jump => jump.SpanStart > expression.SpanStart))
            {
                // A known forward label cannot revisit this use. Case/default or an
                // unproven target conservatively retain the possible back-edge window.
                if (jump.IsKind(SyntaxKind.GotoStatement)
                    && jump.Expression is { } target
                    && member.Model.GetSymbolInfo(target).Symbol is ILabelSymbol label
                    && label.DeclaringSyntaxReferences is [SyntaxReference declaration]
                    && declaration.Span.Start > expression.SpanStart)
                {
                    continue;
                }

                through = Math.Max(through, jump.Span.End);
            }

            return through == expression.Span.End
                || SymbolIsStableWithin(member, symbol, expression.SpanStart, through);
        }

        private bool IsExactConditionalNullCleanupValue(
            AuthoredMember member,
            InvocationExpressionSyntax call,
            ExpressionSyntax receiver)
        {
            if (call.Expression is not MemberBindingExpressionSyntax
                || call.Parent is not ConditionalAccessExpressionSyntax conditional
                || conditional.WhenNotNull != call
                || conditional.Expression != receiver)
            {
                return false;
            }

            HashSet<ISymbol> path = new(SymbolEqualityComparer.Default);

            for (int work = 0; work < CleanupProvenanceContext.MaximumWork; work++)
            {
                if (!TryNormalizeBuiltInCleanupValue(member.Model, receiver, out receiver))
                {
                    return false;
                }

                if (IsSemanticallyEmptyCleanupValue(member.Model, receiver))
                {
                    return true;
                }

                if (member.Model.GetSymbolInfo(receiver).Symbol is not { } symbol
                    || symbol is not (ILocalSymbol or IParameterSymbol)
                    || !path.Add(symbol)
                    || !IsStableAcrossAdmissionCleanupBackEdges(member, receiver, symbol))
                {
                    return false;
                }

                if (symbol is IParameterSymbol
                    {
                        ContainingSymbol: IMethodSymbol { MethodKind: MethodKind.Constructor } constructor,
                    } constructorParameter
                    && (ResolveConstructorContextTarget(constructor, member.Model.Compilation) is not { } constructorMember
                        || HasConstructorDependencyMutation(constructorMember, constructorParameter)))
                {
                    return false;
                }

                if (TryResolveStableBoundValueSource(member, receiver, out BoundValueSource? bound)
                    && bound is not null)
                {
                    member = bound.Caller;

                    receiver = bound.Expression;

                    continue;
                }

                if (symbol is ILocalSymbol
                    && symbol.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax() is
                        VariableDeclaratorSyntax { Initializer.Value: { } initializer } declaration
                    && declaration.SyntaxTree == member.Syntax.SyntaxTree
                    && member.Syntax.Span.Contains(declaration.Span)
                    && SymbolIsStableWithin(member, symbol, declaration.Span.End, receiver.SpanStart)
                    && RecoveryTupleSourceIsStable(member, symbol, receiver, allowSimpleLocalAssignments: false))
                {
                    receiver = initializer;

                    continue;
                }

                return false;
            }

            return false;
        }

        private bool IsExactAdmissionCleanupValue(
            AuthoredMember member,
            ExpressionSyntax expression,
            HashSet<ISymbol> path)
        {
            expression = StripTransparentExpression(expression);

            if (member.Model.GetSymbolInfo(expression).Symbol is not { } symbol
                || symbol is not (ILocalSymbol or IParameterSymbol)
                || !path.Add(symbol))
            {
                return false;
            }

            try
            {
                if (!IsStableAcrossAdmissionCleanupBackEdges(member, expression, symbol))
                {
                    return false;
                }

                if (TryResolveStableBoundValueSource(member, expression, out BoundValueSource? bound)
                    && bound is not null)
                {
                    return IsExactAdmissionCleanupValue(bound.Caller, bound.Expression, path);
                }

                SyntaxNode? declaration = symbol.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax();

                if (symbol is not ILocalSymbol
                    || declaration is null
                    || declaration.SyntaxTree != member.Syntax.SyntaxTree
                    || !member.Syntax.Span.Contains(declaration.Span))
                {
                    return false;
                }

                if (declaration is VariableDeclaratorSyntax { Initializer.Value: { } initializer }
                    && SymbolIsStableWithin(member, symbol, declaration.Span.End, expression.SpanStart)
                    && IsExactAdmissionCleanupValue(member, initializer, path))
                {
                    return true;
                }

                InvocationExpressionSyntax[] acquisitions = AdmissionSyntax(member).AdmissionCalls
                    .Where(call => call.Span.End < expression.SpanStart
                        && member.Model.GetOperation(call) is IInvocationOperation operation
                        && operation.Arguments.Any(argument => argument.Parameter?.RefKind == RefKind.Out
                            && (argument.Value is ILocalReferenceOperation local
                                    && SymbolEqualityComparer.Default.Equals(local.Local, symbol)
                                || argument.Syntax.DescendantNodesAndSelf()
                                    .OfType<SingleVariableDesignationSyntax>()
                                    .Any(designation => SymbolEqualityComparer.Default.Equals(
                                        member.Model.GetDeclaredSymbol(designation), symbol)))))
                    .ToArray();

                if (acquisitions is not [InvocationExpressionSyntax acquisition]
                    || member.Model.GetSymbolInfo(acquisition).Symbol is not IMethodSymbol method
                    || Normalize(method) is not
                        ("RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease.TryBeginExternalEffectGroup"
                            or "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireConnectionAdmissionGate.TryAcquireWorkLease")
                    || !SymbolIsStableWithin(member, symbol, acquisition.Span.End, expression.SpanStart))
                {
                    return false;
                }

                if (Normalize(method) == "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease.TryBeginExternalEffectGroup"
                    && (AdmissionReceiver(member, acquisition) is not { } lease
                        || !IsExactAdmissionCleanupValue(member, lease, path)))
                {
                    return false;
                }

                IfStatementSyntax? guard = acquisition.Ancestors().OfType<IfStatementSyntax>()
                    .FirstOrDefault(candidate => candidate.Condition.Span.Contains(acquisition.Span));

                // A terminating negative guard before the protected use overwrites even an
                // unknown initializer. A conditional acquisition cannot make that claim.
                bool dominates = guard is not null
                    && ProvesConditionFalseMeansCallTrue(guard.Condition, acquisition)
                    && FailureTerminates(guard)
                    && guard.Parent is BlockSyntax block
                    && DirectStatement(block, expression) is { } use
                    && block.Statements.IndexOf(use) > block.Statements.IndexOf(guard)
                    && member.Model.AnalyzeControlFlow(guard, use) is
                    { Succeeded: true, EntryPoints.Length: 0 };

                if (dominates)
                {
                    return true;
                }

                // Only the authenticated handle or the untouched null can reach this
                // guarded cleanup. This proves no work/effect authority for the null branch.
                return declaration is VariableDeclaratorSyntax { Initializer.Value: { } initial }
                    && member.Model.GetConstantValue(initial) is { HasValue: true, Value: null }
                    && SymbolIsStableWithin(member, symbol, declaration.Span.End, acquisition.SpanStart)
                    && expression.Ancestors().OfType<IfStatementSyntax>().Any(candidate =>
                        candidate.Statement.Span.Contains(expression.Span)
                        && candidate.Condition is IsPatternExpressionSyntax
                        {
                            Expression: { } tested,
                            Pattern: UnaryPatternSyntax
                            {
                                Pattern: ConstantPatternSyntax
                                {
                                    Expression.RawKind: (int)SyntaxKind.NullLiteralExpression,
                                },
                            },
                        }
                        && SymbolEqualityComparer.Default.Equals(
                            member.Model.GetSymbolInfo(tested).Symbol, symbol));
            }
            finally
            {
                path.Remove(symbol);
            }
        }

        private bool MayCarryAdmissionHandle(AuthoredMember member, ExpressionSyntax expression,
            AdmissionOriginQueryContext? query = null)
        {
            if (AdmissionOrigins(member, expression, new HashSet<ISymbol>(SymbolEqualityComparer.Default), query).Count == 0)
            {
                return false;
            }

            if (IsExactFrameworkPairWithStringPayloads(member, expression))
            {
                return false;
            }

            ITypeSymbol? type = member.Model.GetTypeInfo(expression).Type;

            if (CanCarryAdmissionHandle(type, [], query))
            {
                return true;
            }

            if (query is not null)
            {
                // Nonempty origins in an unsupported carrier are not proof that the
                // captured object is handle-free. Refuse this strict query instead.
                query.Complete = false;

                return false;
            }

            IEnumerable<ExpressionSyntax> storedValues = expression switch
            {
                BaseObjectCreationExpressionSyntax creation => (creation.ArgumentList?.Arguments.Select(static argument => argument.Expression) ?? []).Concat(creation.Initializer?.Expressions.Select(static value => value is AssignmentExpressionSyntax assignment ? assignment.Right : value) ?? []),
                AnonymousObjectCreationExpressionSyntax anonymous => anonymous.Initializers.Select(static initializer => initializer.Expression),
                _ => [],
            };

            return storedValues.Any(value => MayCarryAdmissionHandle(member, value, query));
        }

        private static bool IsExactFrameworkPairWithStringPayloads(
            AuthoredMember member,
            ExpressionSyntax expression)
        {
            if (!TryNormalizeBuiltInCleanupValue(member.Model, expression, out expression))
            {
                return false;
            }

            if (expression is not BaseObjectCreationExpressionSyntax { Initializer: null }
                || member.Model.GetOperation(expression) is not IObjectCreationOperation
                {
                    Constructor: { MethodKind: MethodKind.Constructor, IsStatic: false, IsVararg: false } constructor,
                    Initializer: null,
                    Arguments.Length: 2,
                } creation
                || constructor.Parameters is not [IParameterSymbol key, IParameterSymbol value]
                || creation.Arguments.Count(static argument => argument.Parameter?.Ordinal == 0) != 1
                || creation.Arguments.Count(static argument => argument.Parameter?.Ordinal == 1) != 1
                || key.RefKind != RefKind.None
                || value.RefKind != RefKind.None
                || constructor.ContainingType.TypeArguments is not
                    [ITypeSymbol { SpecialType: SpecialType.System_String },
                     ITypeSymbol { SpecialType: SpecialType.System_Object }]
                || key.Type.SpecialType != SpecialType.System_String
                || value.Type.SpecialType != SpecialType.System_Object
                || !IsExactFrameworkType(
                    constructor.ContainingType,
                    "System.Collections.Generic.KeyValuePair`2",
                    typeof(KeyValuePair<,>).Assembly.GetName()))
            {
                return false;
            }

            foreach (IArgumentOperation argument in creation.Arguments)
            {
                if (argument.ArgumentKind != ArgumentKind.Explicit
                    || argument.Parameter is not { RefKind: RefKind.None } parameter
                    || !SymbolEqualityComparer.Default.Equals(
                        parameter,
                        constructor.Parameters[parameter.Ordinal])
                    || argument.Syntax is not ArgumentSyntax syntax
                    || !TryNormalizeBuiltInCleanupValue(
                        member.Model,
                        syntax.Expression,
                        out ExpressionSyntax payload)
                    || member.Model.GetOperation(payload) is not
                        (ILiteralOperation or ILocalReferenceOperation or IParameterReferenceOperation)
                    || member.Model.GetTypeInfo(payload).Type is not
                        { SpecialType: SpecialType.System_String } payloadType
                    || CanCarryAdmissionHandle(payloadType, []))
                {
                    return false;
                }
            }

            return true;
        }

        private static bool CanCarryAdmissionHandle(ITypeSymbol? type, HashSet<ITypeSymbol> path,
            AdmissionOriginQueryContext? query = null)
        {
            if (query?.Visit() == false) return false;

            if (type is null || !path.Add(type))
            {
                return false;
            }

            if (type.SpecialType == SpecialType.System_Object || type.TypeKind == TypeKind.Dynamic || TypeKey(type) is "System.IDisposable" or "System.IAsyncDisposable" or "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease")
            {
                return true;
            }

            if (type is IArrayTypeSymbol array)
            {
                return CanCarryAdmissionHandle(array.ElementType, path, query);
            }

            if (type is INamedTypeSymbol named)
            {
                // A task is disposable, but it carries a handle only through the result it will produce: it exposes no way to
                // dispose what it was handed, so forwarding a handle to a call that returns one is no escape of the handle.
                if (!IsExactFrameworkTask(named))
                {
                    foreach (INamedTypeSymbol contract in named.AllInterfaces)
                    {
                        if (query?.Visit() == false) return false;

                        if (TypeKey(contract) is "System.IDisposable" or "System.IAsyncDisposable") return true;
                    }
                }

                return named.TypeArguments.Any(argument => CanCarryAdmissionHandle(argument, path, query))
                    || named.IsTupleType && named.TupleElements.Any(element => CanCarryAdmissionHandle(element.Type, path, query));
            }

            return false;
        }

        private static bool IsExactFrameworkTask(INamedTypeSymbol type) =>
            TypeKey(type) is "System.Threading.Tasks.Task" or "System.Threading.Tasks.Task`1"
            && IsExactFrameworkType(type.OriginalDefinition, TypeKey(type), typeof(Task).Assembly.GetName());

        private static bool PreservesAdmissionReceiver(IMethodSymbol method) => Normalize(method) == "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease.TryBeginExternalEffectGroup";

        private static bool IsCompletionCombinator(IMethodSymbol method) =>
            IsExactFrameworkConfigureAwait(method)
            || Normalize(method) is
                "System.Threading.Tasks.Task.WaitAsync"
                    or "System.Threading.Tasks.Task`1.WaitAsync"
                    or "System.Threading.Tasks.ValueTask.AsTask"
                    or "System.Threading.Tasks.ValueTask`1.AsTask"
                    or "System.Threading.Tasks.Task.GetAwaiter"
                    or "System.Threading.Tasks.Task`1.GetAwaiter"
                    or "System.Threading.Tasks.ValueTask.GetAwaiter"
                    or "System.Threading.Tasks.ValueTask`1.GetAwaiter"
                    or "System.Runtime.CompilerServices.TaskAwaiter.GetResult"
                    or "System.Runtime.CompilerServices.TaskAwaiter`1.GetResult"
                    or "System.Runtime.CompilerServices.ValueTaskAwaiter.GetResult"
                    or "System.Runtime.CompilerServices.ValueTaskAwaiter`1.GetResult";

        private static bool ConsumesAdmissionReceiver(IMethodSymbol method)
        {
            if (method.Parameters.Length != 0 || method.Name is not ("Dispose" or "DisposeAsync"))
            {
                return false;
            }

            foreach (INamedTypeSymbol contract in method.ContainingType.AllInterfaces.Where(static contract => TypeKey(contract) is "System.IDisposable" or "System.IAsyncDisposable"))
            {
                IMethodSymbol? slot = contract.GetMembers(method.Name).OfType<IMethodSymbol>().SingleOrDefault(static candidate => candidate.Parameters.Length == 0);

                if (slot is not null && SymbolEqualityComparer.Default.Equals(method.ContainingType.FindImplementationForInterfaceMember(slot)?.OriginalDefinition, method.OriginalDefinition))
                {
                    return true;
                }
            }

            return TypeKey(method.ContainingType) is "System.IDisposable" or "System.IAsyncDisposable";
        }

        private SyntaxNode? CancelledTimerRaceCompletionPoint(
            AuthoredMember member,
            InvocationExpressionSyntax source)
        {
            if (member.Model.GetSymbolInfo(source).Symbol is not IMethodSymbol delayMethod
                || Normalize(delayMethod) != "System.Threading.Tasks.Task.Delay"
                || member.Model.GetOperation(source) is not IInvocationOperation delayOperation
                || delayOperation.Arguments.SingleOrDefault(static argument =>
                    argument.Parameter?.Name == "cancellationToken") is not { } tokenArgument
                || (tokenArgument.Syntax is ArgumentSyntax tokenSyntax
                    ? tokenSyntax.Expression
                    : tokenArgument.Value.Syntax) is not ExpressionSyntax tokenExpression
                || StripTransparentExpression(tokenExpression)
                    is not MemberAccessExpressionSyntax
                    {
                        Expression: { } cancellationReceiver,
                        Name.Identifier.ValueText: "Token",
                    }
                || member.Model.GetSymbolInfo(cancellationReceiver).Symbol
                    is not ILocalSymbol cancellationSource
                || TypeKey(cancellationSource.Type)
                    != "System.Threading.CancellationTokenSource"
                || source.Parent is not AssignmentExpressionSyntax
                {
                    Right: { } assigned,
                    Left: { } assignedTarget,
                    Parent: ExpressionStatementSyntax
                    {
                        Parent: BlockSyntax loopBlock,
                    } assignmentStatement,
                } taskAssignment
                || assigned != source
                || loopBlock.Parent is not WhileStatementSyntax
                || member.Model.GetSymbolInfo(assignedTarget).Symbol
                    is not ILocalSymbol pendingTask
                || pendingTask.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                    is not VariableDeclaratorSyntax
                    {
                        Initializer.Value: { } initialValue,
                        Parent.Parent: LocalDeclarationStatementSyntax
                        {
                            Parent: BlockSyntax lifetimeBlock,
                        } declarationStatement,
                    }
                || member.Model.GetConstantValue(initialValue) is not
                {
                    HasValue: true,
                    Value: null,
                }
                || taskAssignment.Ancestors().OfType<TryStatementSyntax>()
                    .FirstOrDefault(candidate => candidate.Parent == lifetimeBlock)
                    is not TryStatementSyntax
                    {
                        Finally.Block.Statements: [TryStatementSyntax cancellationCleanup],
                    } protectedLifetime
                || declarationStatement.SpanStart >= protectedLifetime.SpanStart)
            {
                return null;
            }

            bool RefersTo(ExpressionSyntax expression, ISymbol symbol) =>
                SymbolEqualityComparer.Default.Equals(
                    member.Model.GetSymbolInfo(
                        StripTransparentExpression(expression)).Symbol,
                    symbol);

            AssignmentExpressionSyntax[] writes = lifetimeBlock
                .DescendantNodes()
                .OfType<AssignmentExpressionSyntax>()
                .Where(write => RefersTo(write.Left, pendingTask))
                .ToArray();

            if (writes is not
                [AssignmentExpressionSyntax exactAssignment, AssignmentExpressionSyntax reset]
                || exactAssignment != taskAssignment
                || member.Model.GetConstantValue(reset.Right) is not
                {
                    HasValue: true,
                    Value: null,
                }
                || reset.Parent is not ExpressionStatementSyntax resetStatement
                || resetStatement.Parent != loopBlock)
            {
                return null;
            }

            int resetIndex = loopBlock.Statements.IndexOf(resetStatement);

            if (resetIndex <= 0
                || loopBlock.Statements[resetIndex - 1]
                    is not ExpressionStatementSyntax
                    {
                        Expression: AwaitExpressionSyntax directJoin,
                    }
                || !directJoin.DescendantNodesAndSelf()
                    .OfType<ExpressionSyntax>()
                    .Any(expression => RefersTo(expression, pendingTask)
                        && CompletionPreservingExpression(expression, member.Model)
                            .Parent == directJoin)
                || loopBlock.Statements
                    .Where(statement => statement.SpanStart > assignmentStatement.Span.End
                        && statement.Span.End < resetStatement.SpanStart)
                    .Any(statement => statement.DescendantNodesAndSelf()
                        .Any(static node => node is ContinueStatementSyntax
                            or GotoStatementSyntax)))
            {
                return null;
            }

            if (cancellationCleanup.Block.Statements is not
                [ExpressionStatementSyntax
                {
                    Expression: InvocationExpressionSyntax cancelCall,
                }]
                || member.Model.GetSymbolInfo(cancelCall).Symbol
                    is not IMethodSymbol cancelMethod
                || Normalize(cancelMethod)
                    != "System.Threading.CancellationTokenSource.Cancel"
                || cancelCall.Expression is not MemberAccessExpressionSyntax
                {
                    Expression: { } cancelledReceiver,
                }
                || !RefersTo(cancelledReceiver, cancellationSource)
                || cancellationCleanup.Catches.Count != 0
                || cancellationCleanup.Finally?.Block.Statements is not
                    [IfStatementSyntax observationGuard]
                || observationGuard.Condition is not IsPatternExpressionSyntax
                {
                    Expression: { } testedTask,
                    Pattern: UnaryPatternSyntax
                    {
                        Pattern: ConstantPatternSyntax
                        {
                            Expression.RawKind:
                                    (int)SyntaxKind.NullLiteralExpression,
                        },
                    },
                }
                || !RefersTo(testedTask, pendingTask)
                || observationGuard.Statement is not BlockSyntax
                {
                    Statements:
                        [
                            ExpressionStatementSyntax
                        {
                            Expression: AwaitExpressionSyntax observedCompletion,
                        },
                        ],
                })
            {
                return null;
            }

            InvocationExpressionSyntax[] observerCalls = observedCompletion
                .DescendantNodesAndSelf()
                .OfType<InvocationExpressionSyntax>()
                .Where(call => call.ArgumentList.Arguments.Any(argument =>
                    RefersTo(argument.Expression, pendingTask)))
                .ToArray();

            if (observerCalls is not [InvocationExpressionSyntax observerCall]
                || member.Model.GetSymbolInfo(observerCall).Symbol
                    is not IMethodSymbol observerMethod
                || ResolveInvocationTarget(observerMethod, member, observerCall)
                    is not { } observer
                || observerCall.ArgumentList.Arguments.SingleOrDefault(argument =>
                    RefersTo(argument.Expression, pendingTask)) is not { } observedArgument
                || member.Model.GetOperation(observedArgument) is not IArgumentOperation
                {
                    Parameter: { } suppliedParameter,
                }
                || suppliedParameter.Ordinal >= observer.Symbol.Parameters.Length)
            {
                return null;
            }

            IParameterSymbol observedParameter =
                observer.Symbol.Parameters[suppliedParameter.Ordinal];

            if (SymbolReferences(observer, observedParameter)
                    is not [ExpressionSyntax observedReference]
                || CompletionPreservingExpression(observedReference, observer.Model)
                    .Parent is not AwaitExpressionSyntax observerJoin
                || observerJoin.Ancestors()
                    .TakeWhile(ancestor => ancestor != observer.Syntax)
                    .Any(static ancestor => ancestor is IfStatementSyntax
                        or ConditionalExpressionSyntax
                        or SwitchStatementSyntax
                        or SwitchExpressionSyntax
                        or ForStatementSyntax
                        or ForEachStatementSyntax
                        or ForEachVariableStatementSyntax
                        or WhileStatementSyntax
                        or DoStatementSyntax
                        or AnonymousFunctionExpressionSyntax
                        or LocalFunctionStatementSyntax)
                || lifetimeBlock.DescendantNodes()
                    .OfType<ArgumentSyntax>()
                    .Any(argument => argument.RefKindKeyword.Kind() is
                            SyntaxKind.RefKeyword or SyntaxKind.OutKeyword
                        && RefersTo(argument.Expression, pendingTask)))
            {
                return null;
            }

            return observedCompletion;
        }

        private SyntaxNode? RetainedQueueRaceCompletionPoint(
            AuthoredMember member,
            InvocationExpressionSyntax source)
        {
            const string ownerType =
                "RetroDownfall.Arcanum.Infrastructure.Weave.SessionAttachmentIndexingService";

            if (TypeKey(member.Symbol.ContainingType) != ownerType
                || member.Symbol.Name != "WaitForWorkAsync"
                || member.Model.GetSymbolInfo(source).Symbol is not IMethodSymbol delay
                || Normalize(delay) != "System.Threading.Tasks.Task.Delay"
                || source.Parent is not AssignmentExpressionSyntax
                {
                    RawKind: (int)SyntaxKind.CoalesceAssignmentExpression,
                    Left: MemberAccessExpressionSyntax
                    {
                        Expression: { } waitReceiver,
                        Name.Identifier.ValueText: "PendingPeriod",
                    },
                }
                || member.Model.GetSymbolInfo(waitReceiver).Symbol
                    is not IParameterSymbol waitParameter
                || waitParameter.Name != "wait")
            {
                return null;
            }

            bool IsWaitProperty(
                AuthoredMember context,
                ExpressionSyntax expression,
                ISymbol wait,
                string propertyName) =>
                expression is MemberAccessExpressionSyntax
                {
                    Expression: { } receiver,
                    Name.Identifier.ValueText: { } name,
                }
                && name == propertyName
                && SymbolEqualityComparer.Default.Equals(
                    context.Model.GetSymbolInfo(receiver).Symbol,
                    wait);

            InvocationExpressionSyntax[] races = member.Syntax.DescendantNodes()
                .OfType<InvocationExpressionSyntax>()
                .Where(call => member.Model.GetSymbolInfo(call).Symbol
                    is IMethodSymbol method
                    && Normalize(method) == "System.Threading.Tasks.Task.WhenAny"
                    && call.FirstAncestorOrSelf<AwaitExpressionSyntax>() is not null
                    && call.ArgumentList.DescendantNodes()
                        .OfType<ExpressionSyntax>()
                        .Any(expression => IsWaitProperty(
                            member,
                            expression,
                            waitParameter,
                            "PendingRead"))
                    && call.ArgumentList.DescendantNodes()
                        .OfType<ExpressionSyntax>()
                        .Any(expression => IsWaitProperty(
                            member,
                            expression,
                            waitParameter,
                            "PendingPeriod")))
                .ToArray();

            AuthoredMember[] observers = AuthoredMembers
                .Where(candidate => TypeKey(candidate.Symbol.ContainingType) == ownerType
                    && candidate.Symbol.Name == "ObserveQueueWaitCompletionAsync")
                .ToArray();

            if (races is not [InvocationExpressionSyntax]
                || observers is not [AuthoredMember observer]
                || observer.Symbol.Parameters.SingleOrDefault(static parameter =>
                    parameter.Name == "wait") is not { } observedWait)
            {
                return null;
            }

            InvocationExpressionSyntax[] aggregateJoins = observer.Syntax
                .DescendantNodes()
                .OfType<InvocationExpressionSyntax>()
                .Where(call => observer.Model.GetSymbolInfo(call).Symbol
                    is IMethodSymbol method
                    && Normalize(method) == "System.Threading.Tasks.Task.WhenAll"
                    && call.FirstAncestorOrSelf<AwaitExpressionSyntax>() is not null)
                .ToArray();

            bool clearsBoth = new[] { "PendingRead", "PendingPeriod" }
                .All(propertyName => observer.Syntax.DescendantNodes()
                    .OfType<AssignmentExpressionSyntax>()
                    .Any(assignment => assignment.Ancestors()
                            .OfType<FinallyClauseSyntax>()
                            .Any()
                        && IsWaitProperty(
                            observer,
                            assignment.Left,
                            observedWait,
                            propertyName)
                        && observer.Model.GetConstantValue(assignment.Right) is
                        {
                            HasValue: true,
                            Value: null,
                        }));

            if (aggregateJoins is not [InvocationExpressionSyntax]
                || !clearsBoth)
            {
                return null;
            }

            foreach (AuthoredMember owner in AuthoredMembers.Where(candidate =>
                TypeKey(candidate.Symbol.ContainingType) == ownerType
                && candidate.Symbol.Name == "ExecuteAsync"))
            {
                InvocationExpressionSyntax[] waitCalls = owner.Syntax
                    .DescendantNodes()
                    .OfType<InvocationExpressionSyntax>()
                    .Where(call => owner.Model.GetSymbolInfo(call).Symbol
                        is IMethodSymbol method
                        && method.Name == "WaitForWorkAsync"
                        && SymbolEqualityComparer.Default.Equals(
                            method.ContainingType,
                            owner.Symbol.ContainingType))
                    .ToArray();

                if (waitCalls is not [InvocationExpressionSyntax waitCall]
                    || waitCall.FirstAncestorOrSelf<AwaitExpressionSyntax>() is null
                    || owner.Model.GetOperation(waitCall) is not IInvocationOperation waitOperation
                    || waitOperation.Arguments.SingleOrDefault(static argument =>
                        argument.Parameter?.Name == "wait") is not { } suppliedWait
                    || (suppliedWait.Syntax is ArgumentSyntax waitArgument
                        ? waitArgument.Expression
                        : suppliedWait.Value.Syntax) is not ExpressionSyntax waitExpression
                    || owner.Model.GetSymbolInfo(waitExpression).Symbol is not
                        ILocalSymbol waitLocal)
                {
                    continue;
                }

                InvocationExpressionSyntax[] observed = owner.Syntax
                    .DescendantNodes()
                    .OfType<InvocationExpressionSyntax>()
                    .Where(call => owner.Model.GetSymbolInfo(call).Symbol
                            is IMethodSymbol method
                        && method.Name == "ObserveQueueWaitCompletionAsync"
                        && SymbolEqualityComparer.Default.Equals(
                            method.ContainingType,
                            owner.Symbol.ContainingType)
                        && call.FirstAncestorOrSelf<AwaitExpressionSyntax>() is not null
                        && call.Ancestors().OfType<FinallyClauseSyntax>().Any()
                        && call.ArgumentList.Arguments.Any(argument =>
                            SymbolEqualityComparer.Default.Equals(
                                owner.Model.GetSymbolInfo(argument.Expression).Symbol,
                                waitLocal)))
                    .ToArray();

                bool cancelsLifetime = owner.Syntax.DescendantNodes()
                    .OfType<InvocationExpressionSyntax>()
                    .Any(call => owner.Model.GetSymbolInfo(call).Symbol
                            is IMethodSymbol method
                        && Normalize(method)
                            == "System.Threading.CancellationTokenSource.CancelAsync"
                        && call.FirstAncestorOrSelf<AwaitExpressionSyntax>() is not null
                        && call.Ancestors().OfType<FinallyClauseSyntax>().Any());

                if (observed is [InvocationExpressionSyntax]
                    && cancelsLifetime)
                {
                    return source;
                }
            }

            return null;
        }

        private SyntaxNode? TrackedTaskCompletionPoint(
            AuthoredMember member,
            ILocalSymbol task,
            VariableDeclaratorSyntax declaration,
            BlockSyntax block)
        {
            if (declaration.Parent?.Parent is not LocalDeclarationStatementSyntax declarationStatement)
            {
                return null;
            }

            int declarationIndex = block.Statements.IndexOf(declarationStatement);

            int protectedLifetimeIndex = declarationIndex + 1;

            while (protectedLifetimeIndex < block.Statements.Count
                && block.Statements[protectedLifetimeIndex]
                    is LocalDeclarationStatementSyntax
                {
                    UsingKeyword.RawKind: 0,
                    Declaration.Variables.Count: > 0,
                } inertDeclaration
                && inertDeclaration.Declaration.Variables.All(variable =>
                    variable.Initializer?.Value is { } initializer
                    && (initializer is DefaultExpressionSyntax
                        || initializer.IsKind(SyntaxKind.DefaultLiteralExpression)
                        || member.Model.GetConstantValue(initializer) is
                        {
                            HasValue: true,
                            Value: null,
                        })))
            {
                protectedLifetimeIndex++;
            }

            if (declarationIndex < 0
                || protectedLifetimeIndex >= block.Statements.Count
                || block.Statements[protectedLifetimeIndex] is not TryStatementSyntax
                {
                    Catches.Count: > 0,
                } protectedLifetime)
            {
                return null;
            }

            bool IsDirectTaskJoin(ExpressionSyntax reference)
            {
                SyntaxNode expression = CompletionPreservingExpression(reference, member.Model);

                return expression.Parent is AwaitExpressionSyntax;
            }

            bool IsExactObserverCall(InvocationExpressionSyntax observerCall)
            {
                if (member.Model.GetSymbolInfo(observerCall).Symbol is not IMethodSymbol observerMethod
                    || !IsAwaitable(observerMethod.ReturnType)
                    || CompletionPoint(member, observerCall, false) is null
                    || Resolve(observerMethod, member.Model.Compilation) is not { } observer
                    || observerCall.ArgumentList.Arguments.SingleOrDefault(argument =>
                        member.Model.GetOperation(argument) is IArgumentOperation
                        {
                            Parameter: { } parameter,
                        }
                        && parameter.Ordinal < observer.Symbol.Parameters.Length
                        && TypeKey(observer.Symbol.Parameters[parameter.Ordinal].Type)
                            is "System.Threading.Tasks.Task"
                                or "System.Threading.Tasks.Task`1") is not { } taskArgument
                    || !SymbolEqualityComparer.Default.Equals(
                        member.Model.GetSymbolInfo(taskArgument.Expression).Symbol,
                        task)
                    || member.Model.GetOperation(taskArgument) is not IArgumentOperation
                    {
                        Parameter: { } sourceParameter,
                    })
                {
                    return false;
                }

                IParameterSymbol observerParameter = observer.Symbol.Parameters[sourceParameter.Ordinal];

                ExpressionSyntax[] observerReferences = SymbolReferences(observer, observerParameter);

                return observerReferences is [ExpressionSyntax observed]
                    && IsDirectObserverJoin(observer, observed);
            }

            static bool IsDirectObserverJoin(
                AuthoredMember observer,
                ExpressionSyntax reference)
            {
                SyntaxNode expression = CompletionPreservingExpression(
                    reference,
                    observer.Model);

                if (expression.Parent is not AwaitExpressionSyntax awaited)
                {
                    return false;
                }

                return !awaited.Ancestors().TakeWhile(ancestor => ancestor != observer.Syntax)
                    .Any(static ancestor => ancestor is IfStatementSyntax
                        or ConditionalExpressionSyntax
                        or SwitchStatementSyntax
                        or SwitchExpressionSyntax
                        or ForStatementSyntax
                        or ForEachStatementSyntax
                        or ForEachVariableStatementSyntax
                        or WhileStatementSyntax
                        or DoStatementSyntax
                        or AnonymousFunctionExpressionSyntax
                        or LocalFunctionStatementSyntax);
            }

            bool HasExceptionalJoin(CatchClauseSyntax caught)
            {
                if (caught.Filter is not null
                    || caught.Declaration?.Type is { } caughtType
                        && member.Model.GetTypeInfo(caughtType).Type is { } exceptionType
                        && TypeKey(exceptionType) != "System.Exception")
                {
                    return false;
                }

                foreach (TryStatementSyntax cleanup in caught.Block.Statements
                    .OfType<TryStatementSyntax>())
                {
                    if (cleanup.Finally?.Block.Statements is not
                        [ExpressionStatementSyntax observationStatement]
                        || observationStatement.Expression.DescendantNodesAndSelf()
                            .OfType<InvocationExpressionSyntax>()
                            .Where(IsExactObserverCall)
                            .ToArray() is not [InvocationExpressionSyntax]
                        || caught.Block.Statements.TakeWhile(statement => statement != cleanup)
                            .Any(static statement => statement is ReturnStatementSyntax
                                or ThrowStatementSyntax
                                or GotoStatementSyntax))
                    {
                        continue;
                    }

                    return true;
                }

                return false;
            }

            if (protectedLifetime.Catches.Any(caught => !HasExceptionalJoin(caught)))
            {
                return null;
            }

            ReturnStatementSyntax[] normalReturns = protectedLifetime.Block.DescendantNodes(
                    static node => node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<ReturnStatementSyntax>()
                .ToArray();

            if (normalReturns.Any(returned => returned.Expression is null
                || returned.Expression.DescendantNodesAndSelf()
                    .OfType<ExpressionSyntax>()
                    .Count(reference => SymbolEqualityComparer.Default.Equals(
                        member.Model.GetSymbolInfo(reference).Symbol,
                        task)
                        && IsDirectTaskJoin(reference)) != 1))
            {
                return null;
            }

            bool fallsThrough = protectedLifetime.Block.Statements.LastOrDefault()
                is not ReturnStatementSyntax
                and not ThrowStatementSyntax;

            if (fallsThrough)
            {
                if (protectedLifetime.Block.Statements.LastOrDefault()
                    is not ExpressionStatementSyntax terminal)
                {
                    return null;
                }

                if (terminal.Expression.DescendantNodesAndSelf()
                    .OfType<ExpressionSyntax>()
                    .Count(reference => SymbolEqualityComparer.Default.Equals(
                        member.Model.GetSymbolInfo(reference).Symbol,
                        task)
                        && IsDirectTaskJoin(reference)) != 1)
                {
                    return null;
                }
            }

            foreach (ExpressionSyntax reference in SymbolReferences(member, task))
            {
                if (IsDirectTaskJoin(reference)
                    || reference.Parent is MemberAccessExpressionSyntax
                    {
                        Name.Identifier.ValueText: "IsCompleted",
                    }
                    || reference.Parent is ArgumentSyntax argument
                        && argument.Parent?.Parent is InvocationExpressionSyntax use
                        && member.Model.GetSymbolInfo(use).Symbol is IMethodSymbol useMethod
                        && (Normalize(useMethod) is "System.Threading.Tasks.Task.WhenAny"
                            or "System.Object.ReferenceEquals"
                            || IsExactObserverCall(use)))
                {
                    continue;
                }

                return null;
            }

            return protectedLifetime;
        }

        private static SyntaxNode? ExactConditionalValueTaskFinallyCompletion(
            AuthoredMember member,
            InvocationExpressionSyntax call)
        {
            if (call.Parent is not EqualsValueClauseSyntax
                {
                    Parent: VariableDeclaratorSyntax variable,
                }
                || variable.Parent?.Parent is not LocalDeclarationStatementSyntax declaration
                || declaration.Parent is not BlockSyntax
                {
                    Parent: FinallyClauseSyntax finalizer,
                    Statements: [LocalDeclarationStatementSyntax first, IfStatementSyntax completion],
                }
                || first != declaration
                || declaration.Declaration.Variables.Count != 1
                || member.Model.GetDeclaredSymbol(variable) is not ILocalSymbol local
                || !IsExactFrameworkType(local.Type, "System.Threading.Tasks.ValueTask",
                    typeof(ValueTask).Assembly.GetName())
                || completion.Else is not null
                || completion.Condition is not PrefixUnaryExpressionSyntax
                {
                    RawKind: (int)SyntaxKind.LogicalNotExpression,
                    Operand: MemberAccessExpressionSyntax
                    {
                        Expression: { } completionReceiver,
                    } status,
                }
                || member.Model.GetSymbolInfo(status).Symbol is not IPropertySymbol
                {
                    Name: "IsCompletedSuccessfully",
                    ContainingType: { } statusType,
                }
                || !IsExactFrameworkType(statusType, "System.Threading.Tasks.ValueTask",
                    typeof(ValueTask).Assembly.GetName())
                || !SymbolEqualityComparer.Default.Equals(
                    member.Model.GetSymbolInfo(completionReceiver).Symbol, local))
            {
                return null;
            }

            ExpressionStatementSyntax? terminal = completion.Statement switch
            {
                ExpressionStatementSyntax statement => statement,
                BlockSyntax { Statements: [ExpressionStatementSyntax statement] } => statement,
                _ => null,
            };

            InvocationExpressionSyntax[] conversions = terminal?.DescendantNodes()
                .OfType<InvocationExpressionSyntax>()
                .Where(conversion => member.Model.GetSymbolInfo(conversion).Symbol is IMethodSymbol method
                    && IsExactFrameworkMethod(method, "System.Threading.Tasks.ValueTask", "AsTask", "System.Private.CoreLib"))
                .ToArray() ?? [];

            return conversions is [InvocationExpressionSyntax asTask]
                && AdmissionReceiver(member, asTask) is { } taskReceiver
                && SymbolEqualityComparer.Default.Equals(
                    member.Model.GetSymbolInfo(taskReceiver).Symbol, local)
                && ExactSynchronousCompletion(asTask, member.Model) == terminal?.Expression
                && HasOnlyReferences(member, local, completionReceiver, taskReceiver)
                    ? finalizer
                    : null;
        }

        private SyntaxNode? ExactCachedTaskReturnCompletion(
            AuthoredMember member,
            InvocationExpressionSyntax call)
        {
            if (member.Symbol.IsAsync
                || member.Symbol.ContainingType is not { IsSealed: true } owner
                || call.Parent is not AssignmentExpressionSyntax
                {
                    RawKind: (int)SyntaxKind.CoalesceAssignmentExpression,
                    Right: { } created,
                    Left: { } cacheReference,
                    Parent: AssignmentExpressionSyntax
                    {
                        RawKind: (int)SyntaxKind.SimpleAssignmentExpression,
                        Left: { } localTarget,
                        Parent: ExpressionStatementSyntax assignmentStatement,
                    } assignment,
                } cacheAssignment
                || created != call
                || assignment.Right != cacheAssignment
                || assignmentStatement.Parent is not BlockSyntax { Parent: LockStatementSyntax held } locked
                || locked.Statements.LastOrDefault() != assignmentStatement
                || held.Parent is not BlockSyntax
                {
                    Statements: [LocalDeclarationStatementSyntax declaration,
                        LockStatementSyntax exactLock,
                        ReturnStatementSyntax { Expression: BaseObjectCreationExpressionSyntax returned } terminal],
                }
                || exactLock != held
                || declaration.Declaration.Variables is not [VariableDeclaratorSyntax { Initializer: null } variable]
                || member.Model.GetDeclaredSymbol(variable) is not ILocalSymbol local
                || !SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(localTarget).Symbol, local)
                || !IsExactFrameworkType(local.Type, "System.Threading.Tasks.Task", typeof(Task).Assembly.GetName())
                || returned.ArgumentList?.Arguments is not [ArgumentSyntax argument]
                || !SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(argument.Expression).Symbol, local)
                || member.Model.GetSymbolInfo(returned).Symbol is not IMethodSymbol constructor
                || !IsExactFrameworkType(constructor.ContainingType, "System.Threading.Tasks.ValueTask", typeof(ValueTask).Assembly.GetName())
                || !HasExactParameterTypes(constructor, "System.Threading.Tasks.Task")
                || !HasOnlyReferences(member, local, localTarget, argument.Expression)
                || member.Model.GetSymbolInfo(cacheReference).Symbol is not IFieldSymbol
                {
                    IsStatic: false,
                    DeclaredAccessibility: Accessibility.Private,
                } cache
                || !SymbolEqualityComparer.Default.Equals(cache.ContainingType, owner)
                || !IsExactFrameworkType(cache.Type, "System.Threading.Tasks.Task", typeof(Task).Assembly.GetName())
                || cache.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax() is not VariableDeclaratorSyntax cacheDeclaration
                || cacheDeclaration.Initializer is { } initializer
                    && member.Model.GetConstantValue(initializer.Value) is not { HasValue: true, Value: null }
                || member.Model.GetSymbolInfo(held.Expression).Symbol is not IFieldSymbol
                {
                    IsStatic: false,
                    IsReadOnly: true,
                    DeclaredAccessibility: Accessibility.Private,
                    Type.SpecialType: SpecialType.System_Object,
                } gate
                || !SymbolEqualityComparer.Default.Equals(gate.ContainingType, owner)
                || member.Syntax.DescendantNodes().OfType<ReturnStatementSyntax>()
                    .Any(statement => statement != terminal))
            {
                return null;
            }

            // The cache has no other source, write, read or escape in the authored owner.
            // This is an exact returned-task proof, not ownership inferred from field storage.
            foreach (SyntaxReference reference in owner.DeclaringSyntaxReferences)
            {
                SyntaxNode declarationSyntax = reference.GetSyntax();

                if (!semanticModels.TryGetValue(declarationSyntax.SyntaxTree, out SemanticModel? model))
                {
                    return null;
                }

                foreach (ExpressionSyntax use in declarationSyntax.DescendantNodes().OfType<ExpressionSyntax>()
                    .Where(use => SymbolEqualityComparer.Default.Equals(model.GetSymbolInfo(use).Symbol, cache)))
                {
                    if (use.SyntaxTree != cacheReference.SyntaxTree || use.Span != cacheReference.Span)
                    {
                        return null;
                    }
                }
            }

            return terminal;
        }

        private static SyntaxNode? ExactPublishedTaskFinallyCompletion(
            AuthoredMember member,
            ILocalSymbol task,
            VariableDeclaratorSyntax declaration,
            BlockSyntax block)
        {
            if (!IsExactFrameworkType(task.Type, "System.Threading.Tasks.Task", typeof(Task).Assembly.GetName())
                || declaration.Parent is not VariableDeclarationSyntax { Variables.Count: 1 }
                || declaration.Parent.Parent is not LocalDeclarationStatementSyntax statement)
            {
                return null;
            }

            int index = block.Statements.IndexOf(statement);

            if (index < 0 || index + 1 >= block.Statements.Count
                || block.Statements[index + 1] is not TryStatementSyntax
                {
                    Finally.Block.Statements: [ExpressionStatementSyntax { Expression: AwaitExpressionSyntax awaited }],
                } protectedLifetime)
            {
                return null;
            }

            ExpressionSyntax[] references = SymbolReferences(member, task);

            ExpressionSyntax[] joined = references.Where(reference => awaited.Expression.Span.Contains(reference.Span)).ToArray();

            if (joined is not [ExpressionSyntax exact]
                || CompletionPreservingExpression(exact, member.Model) != awaited.Expression
                || awaited.Expression.DescendantNodesAndSelf().OfType<InvocationExpressionSyntax>().Any(call =>
                    member.Model.GetSymbolInfo(call).Symbol is not IMethodSymbol method
                    || method.Name != "ConfigureAwait"
                    || !IsExactFrameworkType(method.ContainingType, "System.Threading.Tasks.Task", typeof(Task).Assembly.GetName())
                    || call.ArgumentList.Arguments is not [ArgumentSyntax option]
                    || member.Model.GetConstantValue(option.Expression) is not { HasValue: true, Value: bool }))
            {
                return null;
            }

            foreach (ExpressionSyntax reference in references)
            {
                if (reference == exact)
                {
                    continue;
                }

                // Publication cannot replace the local completion identity. Ref/captured uses
                // and every other local write/alias fail closed, even inside the protected try.
                if (!protectedLifetime.Span.Contains(reference.Span)
                    || reference.Ancestors().TakeWhile(node => node != protectedLifetime)
                        .Any(static node => node is AnonymousFunctionExpressionSyntax or LocalFunctionStatementSyntax))
                {
                    return null;
                }

                if (reference.Parent is AssignmentExpressionSyntax publication
                    && publication.IsKind(SyntaxKind.SimpleAssignmentExpression)
                    && publication.Right == reference
                    && member.Model.GetSymbolInfo(publication.Left).Symbol is IFieldSymbol or IPropertySymbol)
                {
                    continue;
                }

                if (reference.Parent is ArgumentSyntax argument
                    && argument.RefKindKeyword.RawKind == 0
                    && member.Model.GetOperation(argument) is IArgumentOperation { Parameter.RefKind: RefKind.None })
                {
                    continue;
                }

                return null;
            }

            return awaited;
        }

        private SyntaxNode? CompletionPoint(AuthoredMember member, InvocationExpressionSyntax call, bool inheritedCompletion)
        {
            SyntaxNode expression = CompletionPreservingExpression(call, member.Model);

            bool returnedCompletionOwned = inheritedCompletion || IsLifecycle(member.Symbol);

            if (returnedCompletionOwned
                && ExactCachedTaskReturnCompletion(member, call) is { } cachedReturn)
            {
                return cachedReturn;
            }

            if (expression.Parent is AwaitExpressionSyntax awaited)
            {
                return awaited;
            }

            if (ExactSynchronousCompletion(expression, member.Model) is { } synchronous)
            {
                return synchronous;
            }

            if (ExactConditionalValueTaskFinallyCompletion(member, call) is { } finallyJoin)
            {
                return finallyJoin;
            }

            if (CancelledTimerRaceCompletionPoint(member, call) is { } timerJoin)
            {
                return timerJoin;
            }

            if (RetainedQueueRaceCompletionPoint(member, call) is { } queueJoin)
            {
                return queueJoin;
            }

            if (returnedCompletionOwned
                && !member.Symbol.IsAsync
                && (expression.Parent is ReturnStatementSyntax
                    or ArrowExpressionClauseSyntax
                    || member.Syntax is MethodDeclarationSyntax
                    {
                        ExpressionBody.Expression: { } body,
                    }
                        && body == expression
                    || expression == member.Syntax
                        && !member.Symbol.ReturnsVoid))
            {
                return call;
            }

            if (returnedCompletionOwned && expression.Parent is AssignmentExpressionSyntax { Right: { } right } assignment && right == expression && assignment.Parent is ExpressionStatementSyntax assignmentStatement && assignmentStatement.Parent is BlockSyntax assignmentBlock && member.Model.GetSymbolInfo(assignment.Left).Symbol is IFieldSymbol field)
            {
                int assignmentIndex = assignmentBlock.Statements.IndexOf(assignmentStatement);

                if (assignmentIndex >= 0 && assignmentIndex + 1 < assignmentBlock.Statements.Count && assignmentBlock.Statements[assignmentIndex + 1] is ReturnStatementSyntax { Expression: { } returned } returnStatement)
                {
                    ExpressionSyntax[] references = returned.DescendantNodesAndSelf().OfType<ExpressionSyntax>().Where(candidate => SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(candidate).Symbol, field) && !candidate.Ancestors().TakeWhile(ancestor => ancestor != returned).OfType<ExpressionSyntax>().Any(parent => SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(parent).Symbol, field))).ToArray();

                    if (references is [ExpressionSyntax reference] && CompletionPreservingExpression(reference, member.Model).Parent == returnStatement)
                    {
                        return returnStatement;
                    }
                }
            }

            if (expression.Parent is AssignmentExpressionSyntax
                {
                    Right: { } assigned,
                    Left: { } assignedTarget,
                    Parent: ExpressionStatementSyntax localAssignmentStatement,
                } localAssignment
                && assigned == expression
                && localAssignmentStatement.Parent is BlockSyntax localAssignmentBlock
                && member.Model.GetSymbolInfo(assignedTarget).Symbol is ILocalSymbol assignedLocal
                && assignedLocal.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax() is
                    VariableDeclaratorSyntax
                {
                    Initializer: null,
                    Parent.Parent: LocalDeclarationStatementSyntax localDeclaration,
                }
                && localDeclaration.Parent == localAssignmentBlock)
            {
                AssignmentExpressionSyntax[] localWrites = localAssignmentBlock
                    .DescendantNodes()
                    .OfType<AssignmentExpressionSyntax>()
                    .Where(write => SymbolEqualityComparer.Default.Equals(
                        member.Model.GetSymbolInfo(write.Left).Symbol,
                        assignedLocal))
                    .ToArray();

                ExpressionSyntax[] localReferences = localAssignmentBlock
                    .DescendantNodes()
                    .OfType<ExpressionSyntax>()
                    .Where(reference => SymbolEqualityComparer.Default.Equals(
                        member.Model.GetSymbolInfo(reference).Symbol,
                        assignedLocal))
                    .Where(reference => !reference.Ancestors()
                        .TakeWhile(ancestor => ancestor != localAssignmentBlock)
                        .OfType<ExpressionSyntax>()
                        .Any(parent => SymbolEqualityComparer.Default.Equals(
                            member.Model.GetSymbolInfo(parent).Symbol,
                            assignedLocal)))
                    .ToArray();

                ExpressionSyntax[] completionReferences = localReferences
                    .Where(reference => CompletionPreservingExpression(reference, member.Model)
                        .Parent is AwaitExpressionSyntax)
                    .ToArray();

                ExpressionSyntax[] publications = localReferences
                    .Where(reference => reference != assignedTarget
                        && !completionReferences.Contains(reference))
                    .ToArray();

                bool exactPublications = publications.All(reference =>
                    reference.Parent is AssignmentExpressionSyntax
                    {
                        Right: { } publication,
                        Left: { } publicationTarget,
                    } write
                    && publication == reference
                    && member.Model.GetSymbolInfo(publicationTarget).Symbol is IFieldSymbol
                    {
                        Type: { } fieldType,
                    }
                    && TypeKey(fieldType) == "System.Threading.Tasks.Task"
                    && write.Parent is ExpressionStatementSyntax
                    {
                        Parent: { } publicationBlock,
                    }
                    && publicationBlock == localAssignmentBlock);

                if (localWrites is [AssignmentExpressionSyntax exactWrite]
                    && exactWrite == localAssignment
                    && completionReferences is [ExpressionSyntax completionReference]
                    && exactPublications)
                {
                    SyntaxNode completed = CompletionPreservingExpression(
                        completionReference,
                        member.Model);

                    if (completed.Parent is AwaitExpressionSyntax awaitedCompletion
                        && awaitedCompletion.Parent is ExpressionStatementSyntax completionStatement
                        && completionStatement.Parent == localAssignmentBlock
                        && localAssignmentBlock.Statements
                            .Where(statement => statement.SpanStart > localAssignmentStatement.SpanStart
                                && statement.Span.End < completionStatement.SpanStart)
                            .All(statement => statement.DescendantNodesAndSelf()
                                .OfType<AssignmentExpressionSyntax>()
                                .Any(write => publications.Any(reference => write.Right == reference))))
                    {
                        return awaitedCompletion;
                    }
                }
            }

            if (expression.Parent is not EqualsValueClauseSyntax { Parent: VariableDeclaratorSyntax variable } || member.Model.GetDeclaredSymbol(variable) is not ILocalSymbol local || variable.Parent?.Parent is not LocalDeclarationStatementSyntax { Parent: BlockSyntax block })
            {
                return null;
            }

            IdentifierNameSyntax[] uses = block.DescendantNodes().OfType<IdentifierNameSyntax>().Where(identifier => SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(identifier).Symbol, local)).ToArray();

            if (ExactPublishedTaskFinallyCompletion(member, local, variable, block) is { } finallyCompletion)
            {
                return finallyCompletion;
            }

            if (ExactTaskWhenAllCompletion(
                    member,
                    call,
                    uses,
                    inheritedCompletion) is { } aggregateCompletion)
            {
                return aggregateCompletion;
            }

            if (ExactTaskCollectionWhenAllCompletion(
                    member,
                    call,
                    uses,
                    inheritedCompletion) is { } collectionCompletion)
            {
                return collectionCompletion;
            }

            if (uses is not [IdentifierNameSyntax use])
            {
                return TrackedTaskCompletionPoint(member, local, variable, block);
            }

            if (ExactTaskJoinHelperCompletion(
                    member,
                    call,
                    use,
                    inheritedCompletion) is { } helperCompletion)
            {
                return helperCompletion;
            }

            SyntaxNode retained = CompletionPreservingExpression(use, member.Model);

            if (returnedCompletionOwned
                && retained.Parent is ReturnStatementSyntax returnedStatement
                && returnedStatement.Expression == retained
                && !block.Statements.Any(statement =>
                    statement.SpanStart > call.SpanStart
                        && statement.Span.End < returnedStatement.SpanStart))
            {
                return returnedStatement;
            }

            SyntaxNode? join = retained.Parent is AwaitExpressionSyntax awaitedUse
                ? awaitedUse
                : ExactSynchronousCompletion(retained, member.Model);

            if (join?.Parent is not ExpressionStatementSyntax statement
                || statement.Parent != block
                || statement.Expression != join
                || join.SpanStart < call.Span.End)
            {
                return null;
            }

            if (use.Ancestors().TakeWhile(ancestor => ancestor != join).Any(static ancestor => ancestor is ConditionalExpressionSyntax or SwitchExpressionSyntax || ancestor is BinaryExpressionSyntax binary && binary.IsKind(SyntaxKind.CoalesceExpression)))
            {
                return null;
            }

            // An intervening call can throw before the join and unwind the retained handles.
            return block.Statements.Any(statement => statement.SpanStart > call.SpanStart && statement.Span.End < join.SpanStart) ? null : join;
        }

        private SyntaxNode? ExactTaskJoinHelperCompletion(
            AuthoredMember caller,
            InvocationExpressionSyntax source,
            IdentifierNameSyntax taskReference,
            bool inheritedCompletion)
        {
            if (taskReference.Parent is not ArgumentSyntax argument
                || argument.Parent?.Parent is not InvocationExpressionSyntax helperCall
                || caller.Model.GetOperation(argument) is not IArgumentOperation
                {
                    Parameter: { } suppliedParameter,
                }
                || caller.Model.GetSymbolInfo(helperCall).Symbol is not IMethodSymbol helperMethod
                || ResolveInvocationTarget(helperMethod, caller, helperCall) is not { } helper
                || suppliedParameter.Ordinal >= helper.Symbol.Parameters.Length
                || CompletionPoint(caller, helperCall, inheritedCompletion) is null
                || !IsUnconditionalExecution(caller, helperCall, source.Span.End))
            {
                return null;
            }

            IParameterSymbol helperParameter = helper.Symbol.Parameters[suppliedParameter.Ordinal];

            if (SymbolReferences(helper, helperParameter) is not [ExpressionSyntax awaitedReference])
            {
                return null;
            }

            SyntaxNode retained = CompletionPreservingExpression(
                awaitedReference,
                helper.Model);

            if (retained.Parent is not AwaitExpressionSyntax awaited
                || awaited.Ancestors().TakeWhile(ancestor => ancestor != helper.Syntax)
                    .Any(static ancestor => ancestor is IfStatementSyntax
                        or ConditionalExpressionSyntax
                        or SwitchStatementSyntax
                        or SwitchExpressionSyntax
                        or ForStatementSyntax
                        or ForEachStatementSyntax
                        or ForEachVariableStatementSyntax
                        or WhileStatementSyntax
                        or DoStatementSyntax
                        or AnonymousFunctionExpressionSyntax
                        or LocalFunctionStatementSyntax)
                || helper.Syntax.DescendantNodes(candidate =>
                        candidate == helper.Syntax
                            || candidate is not AnonymousFunctionExpressionSyntax
                                and not LocalFunctionStatementSyntax)
                    .Any(candidate => candidate.Span.End < awaited.SpanStart
                        && candidate is ReturnStatementSyntax
                            or ThrowStatementSyntax
                            or GotoStatementSyntax))
            {
                return null;
            }

            return helperCall;
        }

        private SyntaxNode? ExactTaskWhenAllCompletion(
            AuthoredMember member,
            InvocationExpressionSyntax source,
            IReadOnlyList<IdentifierNameSyntax> taskReferences,
            bool inheritedCompletion)
        {
            InvocationExpressionSyntax[] aggregates = taskReferences
                .Select(static taskReference => taskReference.Parent is ArgumentSyntax
                {
                    Parent.Parent: InvocationExpressionSyntax aggregate,
                }
                    ? aggregate
                    : null)
                .OfType<InvocationExpressionSyntax>()
                .Where(aggregate => member.Model.GetSymbolInfo(aggregate).Symbol is IMethodSymbol aggregateMethod
                    && Normalize(aggregateMethod) == "System.Threading.Tasks.Task.WhenAll")
                .Distinct()
                .ToArray();

            if (aggregates is not [InvocationExpressionSyntax aggregate]
                || taskReferences.Count(reference => reference.Ancestors().Contains(aggregate)) != 1
                || CompletionPoint(member, aggregate, inheritedCompletion) is null
                || !IsUnconditionalExecution(member, aggregate, source.Span.End)
                    && !IsDirectlyObservedTryAggregation(source, aggregate))
            {
                return null;
            }

            foreach (IdentifierNameSyntax reference in taskReferences)
            {
                if (reference.Ancestors().Contains(aggregate))
                {
                    continue;
                }

                if (reference.SpanStart < aggregate.Span.End
                    || reference.Ancestors().TakeWhile(ancestor => ancestor != member.Syntax).Any(ancestor => ancestor switch
                    {
                        AssignmentExpressionSyntax assignment => assignment.Left.Span.Contains(reference.Span),
                        ArgumentSyntax argument => argument.RefKindKeyword.Kind() is SyntaxKind.RefKeyword or SyntaxKind.OutKeyword,
                        PrefixUnaryExpressionSyntax prefix => prefix.IsKind(SyntaxKind.PreIncrementExpression) || prefix.IsKind(SyntaxKind.PreDecrementExpression),
                        PostfixUnaryExpressionSyntax postfix => postfix.IsKind(SyntaxKind.PostIncrementExpression) || postfix.IsKind(SyntaxKind.PostDecrementExpression),
                        RefExpressionSyntax => true,
                        _ => false,
                    }))
                {
                    return null;
                }
            }

            return aggregate;
        }

        private SyntaxNode? ExactTaskCollectionWhenAllCompletion(
            AuthoredMember member,
            InvocationExpressionSyntax source,
            IReadOnlyList<IdentifierNameSyntax> taskReferences,
            bool inheritedCompletion)
        {
            if (taskReferences is not [IdentifierNameSyntax taskReference]
                || taskReference.Parent is not ArgumentSyntax
                {
                    Parent.Parent: InvocationExpressionSyntax addCall,
                }
                || member.Model.GetSymbolInfo(addCall).Symbol is not IMethodSymbol addMethod
                || addMethod.Name != "Add"
                || TypeKey(addMethod.ContainingType)
                    != "System.Collections.Generic.List`1"
                || addCall.Expression is not MemberAccessExpressionSyntax
                {
                    Expression: { } listReceiver,
                }
                || member.Model.GetSymbolInfo(listReceiver).Symbol
                    is not ILocalSymbol list
                || list.Type is not INamedTypeSymbol
                {
                    TypeArguments: [ITypeSymbol element],
                } listType
                || TypeKey(listType.OriginalDefinition)
                    != "System.Collections.Generic.List`1"
                || !IsAwaitable(element)
                || list.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                    is not VariableDeclaratorSyntax
                    {
                        Initializer.Value: BaseObjectCreationExpressionSyntax,
                        Parent.Parent: LocalDeclarationStatementSyntax
                        {
                            Parent: BlockSyntax ownerBlock,
                        } listDeclaration,
                    })
            {
                return null;
            }

            ExpressionSyntax[] references = ownerBlock.DescendantNodes()
                .OfType<ExpressionSyntax>()
                .Where(reference => SymbolEqualityComparer.Default.Equals(
                    member.Model.GetSymbolInfo(reference).Symbol,
                    list))
                .Where(reference => !reference.Ancestors()
                    .TakeWhile(ancestor => ancestor != ownerBlock)
                    .OfType<ExpressionSyntax>()
                    .Any(parent => SymbolEqualityComparer.Default.Equals(
                        member.Model.GetSymbolInfo(parent).Symbol,
                        list)))
                .ToArray();

            InvocationExpressionSyntax[] additions = references
                .Select(static reference => reference.Parent
                    is MemberAccessExpressionSyntax
                {
                    Parent: InvocationExpressionSyntax invocation,
                }
                        ? invocation
                        : null)
                .OfType<InvocationExpressionSyntax>()
                .Where(invocation => member.Model.GetSymbolInfo(invocation).Symbol
                    is IMethodSymbol candidate
                    && candidate.Name == "Add"
                    && TypeKey(candidate.ContainingType)
                        == "System.Collections.Generic.List`1")
                .Distinct()
                .ToArray();

            InvocationExpressionSyntax[] aggregates = references
                .Select(static reference => reference.Parent is ArgumentSyntax
                {
                    Parent.Parent: InvocationExpressionSyntax invocation,
                }
                        ? invocation
                        : null)
                .OfType<InvocationExpressionSyntax>()
                .Where(invocation => member.Model.GetSymbolInfo(invocation).Symbol
                    is IMethodSymbol candidate
                    && Normalize(candidate)
                        == "System.Threading.Tasks.Task.WhenAll")
                .Distinct()
                .ToArray();

            if (additions is not [InvocationExpressionSyntax exactAdd]
                || exactAdd != addCall
                || aggregates is not [InvocationExpressionSyntax aggregate]
                || references.Any(reference =>
                    !reference.Ancestors().Contains(exactAdd)
                    && !reference.Ancestors().Contains(aggregate))
                || listDeclaration.Span.End >= source.SpanStart
                || aggregate.SpanStart <= source.Span.End
                || CompletionPoint(member, aggregate, inheritedCompletion) is null
                    && !IsReviewedSimulacrumAggregateJoin(member, aggregate))
            {
                return null;
            }

            return aggregate;
        }

        private static bool IsReviewedSimulacrumAggregateJoin(
            AuthoredMember member,
            InvocationExpressionSyntax aggregate)
        {
            if (TypeKey(member.Symbol.ContainingType)
                    != "RetroDownfall.Arcanum.Infrastructure.Hosting.ApprenticeService"
                || member.Symbol.Name != "StartAndJoinBranchesAsync"
                || aggregate.Parent is not EqualsValueClauseSyntax
                {
                    Parent: VariableDeclaratorSyntax joinDeclaration,
                }
                || member.Model.GetDeclaredSymbol(joinDeclaration)
                    is not ILocalSymbol join)
            {
                return false;
            }

            ExpressionSyntax[] references = member.Syntax.DescendantNodes()
                .OfType<ExpressionSyntax>()
                .Where(expression => SymbolEqualityComparer.Default.Equals(
                    member.Model.GetSymbolInfo(expression).Symbol,
                    join))
                .Where(expression => !expression.Ancestors()
                    .TakeWhile(ancestor => ancestor != member.Syntax)
                    .OfType<ExpressionSyntax>()
                    .Any(parent => SymbolEqualityComparer.Default.Equals(
                        member.Model.GetSymbolInfo(parent).Symbol,
                        join)))
                .ToArray();

            return references.Count(reference =>
                    CompletionPreservingExpression(reference, member.Model)
                        .Parent is AwaitExpressionSyntax) == 2
                && references.All(reference =>
                    CompletionPreservingExpression(reference, member.Model)
                            .Parent is AwaitExpressionSyntax
                        || reference.Parent is MemberAccessExpressionSyntax
                        {
                            Name.Identifier.ValueText: "Exception",
                        });
        }

        private static bool IsDirectlyObservedTryAggregation(
            InvocationExpressionSyntax source,
            InvocationExpressionSyntax aggregate)
        {
            if (aggregate.FirstAncestorOrSelf<AwaitExpressionSyntax>() is not { } awaited
                || awaited.FirstAncestorOrSelf<ExpressionStatementSyntax>() is not { } aggregationStatement
                || aggregationStatement.Parent is not BlockSyntax
                {
                    Parent: TryStatementSyntax protectedJoin,
                } protectedBlock
                || protectedJoin.Block != protectedBlock
                || protectedBlock.Statements.FirstOrDefault() != aggregationStatement
                || source.FirstAncestorOrSelf<StatementSyntax>() is not { Parent: BlockSyntax sourceBlock } sourceStatement
                || protectedJoin.Parent != sourceBlock)
            {
                return false;
            }

            int sourceIndex = sourceBlock.Statements.IndexOf(sourceStatement);

            int joinIndex = sourceBlock.Statements.IndexOf(protectedJoin);

            return sourceIndex >= 0
                && joinIndex > sourceIndex
                && !sourceBlock.Statements.Skip(sourceIndex + 1)
                    .Take(joinIndex - sourceIndex - 1)
                    .Any(static statement => statement is ReturnStatementSyntax
                        or ThrowStatementSyntax
                        or GotoStatementSyntax);
        }

        private static InvocationExpressionSyntax? ExactSynchronousCompletion(
            SyntaxNode expression,
            SemanticModel model)
        {
            if (expression is not ExpressionSyntax awaitable
                || model.GetTypeInfo(awaitable).Type is not { } awaitableType
                || !IsAwaitable(awaitableType)
                || expression.Parent is not MemberAccessExpressionSyntax
                {
                    Expression: { } getAwaiterReceiver,
                    Name.Identifier.ValueText: "GetAwaiter",
                    Parent: InvocationExpressionSyntax
                    {
                        ArgumentList.Arguments.Count: 0,
                    } getAwaiter,
                }
                || getAwaiterReceiver != expression
                || model.GetSymbolInfo(getAwaiter).Symbol is not IMethodSymbol
                {
                    Name: "GetAwaiter",
                    Parameters.Length: 0,
                } getAwaiterMethod
                || !SymbolEqualityComparer.Default.Equals(
                    getAwaiterMethod.ContainingType,
                    model.GetTypeInfo(awaitable).Type)
                || getAwaiter.Parent is not MemberAccessExpressionSyntax
                {
                    Expression: { } getResultReceiver,
                    Name.Identifier.ValueText: "GetResult",
                    Parent: InvocationExpressionSyntax
                    {
                        ArgumentList.Arguments.Count: 0,
                    } getResult,
                }
                || getResultReceiver != getAwaiter
                || model.GetSymbolInfo(getResult).Symbol is not IMethodSymbol
                {
                    Name: "GetResult",
                    Parameters.Length: 0,
                } getResultMethod
                || !SymbolEqualityComparer.Default.Equals(
                    getResultMethod.ContainingType,
                    getAwaiterMethod.ReturnType))
            {
                return null;
            }

            return getResult;
        }

        private static SyntaxNode CompletionPreservingExpression(SyntaxNode expression, SemanticModel model)
        {
            while (true)
            {
                if (expression.Parent is ParenthesizedExpressionSyntax parentheses)
                {
                    expression = parentheses;
                }
                else if (expression.Parent is MemberAccessExpressionSyntax { Name.Identifier.ValueText: "ConfigureAwait", Parent: InvocationExpressionSyntax configured } && model.GetSymbolInfo(configured).Symbol is IMethodSymbol method && IsExactFrameworkConfigureAwait(method))
                {
                    expression = configured;
                }
                else if (expression.Parent is MemberAccessExpressionSyntax { Name.Identifier.ValueText: "WaitAsync", Parent: InvocationExpressionSyntax waited } && model.GetSymbolInfo(waited).Symbol is IMethodSymbol waitMethod && Normalize(waitMethod) is "System.Threading.Tasks.Task.WaitAsync" or "System.Threading.Tasks.Task`1.WaitAsync")
                {
                    expression = waited;
                }
                else if (expression.Parent is MemberAccessExpressionSyntax { Name.Identifier.ValueText: "AsTask", Parent: InvocationExpressionSyntax converted } && model.GetSymbolInfo(converted).Symbol is IMethodSymbol conversionMethod && Normalize(conversionMethod) is "System.Threading.Tasks.ValueTask.AsTask" or "System.Threading.Tasks.ValueTask`1.AsTask")
                {
                    expression = converted;
                }
                else if (expression.Parent is ArgumentSyntax
                {
                    Parent.Parent: BaseObjectCreationExpressionSyntax
                    {
                        ArgumentList.Arguments: [_],
                    } valueTaskCreation,
                } argument
                    && argument.Expression == expression
                    && model.GetSymbolInfo(valueTaskCreation).Symbol is IMethodSymbol valueTaskConstructor
                    && valueTaskConstructor.MethodKind == MethodKind.Constructor
                    && TypeKey(valueTaskConstructor.ContainingType)
                        == "System.Threading.Tasks.ValueTask"
                    && valueTaskConstructor.Parameters is
                        [IParameterSymbol { Type: { } taskParameter }]
                    && TypeKey(taskParameter) == "System.Threading.Tasks.Task")
                {
                    expression = valueTaskCreation;
                }
                else if (expression.Parent is ConditionalAccessExpressionSyntax conditionalAccess
                    && conditionalAccess.WhenNotNull == expression)
                {
                    expression = conditionalAccess;
                }
                else if (expression.Parent is ConditionalExpressionSyntax conditional && (conditional.WhenTrue == expression || conditional.WhenFalse == expression))
                {
                    expression = conditional;
                }
                else if (expression.Parent is SwitchExpressionArmSyntax { Expression: { } armExpression } arm && armExpression == expression && arm.Parent is SwitchExpressionSyntax switchExpression)
                {
                    expression = switchExpression;
                }
                else if (expression.Parent is BinaryExpressionSyntax binary && binary.IsKind(SyntaxKind.CoalesceExpression))
                {
                    expression = binary;
                }
                else if (expression.Parent is CastExpressionSyntax cast)
                {
                    expression = cast;
                }
                else
                {
                    return expression;
                }
            }
        }

        private static ExpressionSyntax[] SymbolReferences(AuthoredMember member, ISymbol symbol) => member.Syntax.DescendantNodes().OfType<ExpressionSyntax>().Where(expression => SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(expression).Symbol, symbol) && !expression.Ancestors().TakeWhile(ancestor => ancestor != member.Syntax).OfType<ExpressionSyntax>().Any(parent => SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(parent).Symbol, symbol))).ToArray();

        private static bool HasOnlyReferences(AuthoredMember member, ISymbol symbol, params ExpressionSyntax[] allowed) => SymbolReferences(member, symbol) is { } references && references.Length == allowed.Length && references.All(reference => allowed.Contains(reference));

        private static bool IsAwaitable(ITypeSymbol type) => TypeKey(type) is "System.Threading.Tasks.Task" or "System.Threading.Tasks.Task`1" or "System.Threading.Tasks.ValueTask" or "System.Threading.Tasks.ValueTask`1";

        private static bool IsExactWriterCompletion(IMethodSymbol method) => TypeKey(method.ContainingType) == "RetroDownfall.Arcanum.Core.Storage.EncryptedBlobWriter"
            && method.Name == "CompleteAsync"
            && method.Parameters is [IParameterSymbol { IsOptional: true, Type: { } cancellation }] && TypeKey(cancellation) == "System.Threading.CancellationToken"
            && method.ReturnType is INamedTypeSymbol { TypeArguments: [ITypeSymbol result] } task && task.OriginalDefinition.ToDisplayString() == "System.Threading.Tasks.Task<TResult>" && TypeKey(result) == "RetroDownfall.Arcanum.Core.Storage.EncryptedBlobDescriptor";

        private static bool IsTrustedFrameworkCleanupSlot(IMethodSymbol method) =>
            !method.IsStatic
            && method.Arity == 0
            && method.Parameters.Length == 0
            && (IsExactFrameworkMethod(method, "System.IDisposable", "Dispose", "System.Private.CoreLib")
                    && method.ReturnsVoid
                || IsExactFrameworkMethod(method, "System.IAsyncDisposable", "DisposeAsync", "System.Private.CoreLib")
                    && IsExactFrameworkType(method.ReturnType, "System.Threading.Tasks.ValueTask", typeof(ValueTask).Assembly.GetName()));

        private static bool IsExactSdkSessionCleanup(IMethodSymbol method) =>
            !method.IsStatic
            && method.Name == "DisposeAsync"
            && method.Arity == 0
            && method.Parameters.Length == 0
            && IsExactFrameworkType(method.ContainingType, "ModelContextProtocol.McpSession",
                typeof(ModelContextProtocol.McpSession).Assembly.GetName())
            && IsExactFrameworkType(method.ReturnType, "System.Threading.Tasks.ValueTask",
                typeof(ValueTask).Assembly.GetName());

        private static bool IsExactSdkClientFactory(IMethodSymbol method) =>
            method.IsStatic
            && method.Name == "CreateAsync"
            && method.Arity == 0
            && IsExactFrameworkType(method.ContainingType, "ModelContextProtocol.Client.McpClient",
                typeof(ModelContextProtocol.Client.McpClient).Assembly.GetName())
            && HasExactParameterTypes(method,
                "ModelContextProtocol.Client.IClientTransport",
                "ModelContextProtocol.Client.McpClientOptions",
                "Microsoft.Extensions.Logging.ILoggerFactory",
                "System.Threading.CancellationToken")
            && method.ReturnType is INamedTypeSymbol { TypeArguments: [ITypeSymbol client] } result
            && IsExactFrameworkType(result, "System.Threading.Tasks.Task`1", typeof(Task<>).Assembly.GetName())
            && IsExactFrameworkType(client, "ModelContextProtocol.Client.McpClient",
                typeof(ModelContextProtocol.Client.McpClient).Assembly.GetName());

        private static bool IsExactChatSdkAdapterFactory(IMethodSymbol method)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            return definition.IsStatic
                && definition.Name == "AsIChatClient"
                && definition.Arity == 0
                && IsExactFrameworkType(definition.ContainingType, "Microsoft.Extensions.AI.OpenAIClientExtensions",
                    typeof(Microsoft.Extensions.AI.OpenAIClientExtensions).Assembly.GetName())
                && HasExactParameterTypes(definition, "OpenAI.Chat.ChatClient")
                && IsExactFrameworkType(definition.ReturnType, "Microsoft.Extensions.AI.IChatClient",
                    typeof(Microsoft.Extensions.AI.IChatClient).Assembly.GetName());
        }

        private static bool IsExactEmbeddingSdkAdapterFactory(IMethodSymbol method)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            return definition.IsStatic && definition.Name == "AsIEmbeddingGenerator" && definition.Arity == 0
                && IsExactFrameworkType(definition.ContainingType, "Microsoft.Extensions.AI.OpenAIClientExtensions",
                    typeof(Microsoft.Extensions.AI.OpenAIClientExtensions).Assembly.GetName())
                && definition.Parameters is [{ RefKind: RefKind.None } client,
                    { RefKind: RefKind.None, IsOptional: true, HasExplicitDefaultValue: true, ExplicitDefaultValue: null,
                        Type: INamedTypeSymbol { TypeArguments: [{ SpecialType: SpecialType.System_Int32 }] } dimensions }]
                && IsExactFrameworkType(client.Type, "OpenAI.Embeddings.EmbeddingClient", typeof(OpenAI.Embeddings.EmbeddingClient).Assembly.GetName())
                && IsExactFrameworkType(dimensions, "System.Nullable`1", typeof(object).Assembly.GetName())
                && IsExactEmbeddingGeneratorContract(definition.ReturnType);
        }

        private static bool IsExactEmbeddingGeneratorContract(ITypeSymbol type) =>
            type is INamedTypeSymbol { TypeArguments: [{ SpecialType: SpecialType.System_String },
                INamedTypeSymbol { TypeArguments: [{ SpecialType: SpecialType.System_Single }] } embedding] } generator
            && IsExactFrameworkType(generator, "Microsoft.Extensions.AI.IEmbeddingGenerator`2", typeof(Microsoft.Extensions.AI.IEmbeddingGenerator<,>).Assembly.GetName())
            && IsExactFrameworkType(embedding, "Microsoft.Extensions.AI.Embedding`1", typeof(Microsoft.Extensions.AI.Embedding<>).Assembly.GetName());

        private static bool IsExactCleanupContract(IMethodSymbol method, ITypeSymbol receiverType)
        {
            bool synchronous = method.Name == "Dispose" && TypeKey(method.ReturnType) == "System.Void";

            bool asynchronous = method.Name == "DisposeAsync" && TypeKey(method.ReturnType) == "System.Threading.Tasks.ValueTask";

            if (method.Parameters.Length != 0 || method.IsStatic || !synchronous && !asynchronous)
            {
                return false;
            }

            string contract = synchronous ? "System.IDisposable" : "System.IAsyncDisposable";

            if (receiverType is not INamedTypeSymbol receiver)
            {
                return false;
            }

            INamedTypeSymbol? contractType = TypeKey(receiver) == contract && receiver.TypeKind == TypeKind.Interface
                ? receiver
                : receiver.AllInterfaces.SingleOrDefault(type => TypeKey(type) == contract);

            IMethodSymbol? slot = contractType?.GetMembers(method.Name).OfType<IMethodSymbol>().SingleOrDefault(static candidate => candidate.Parameters.Length == 0);

            if (slot is null)
            {
                return false;
            }

            if (SymbolEqualityComparer.Default.Equals(method.OriginalDefinition, slot.OriginalDefinition))
            {
                return true;
            }

            return receiver.FindImplementationForInterfaceMember(slot) is IMethodSymbol implementation && SymbolEqualityComparer.Default.Equals(implementation.OriginalDefinition, method.OriginalDefinition);
        }

        private static bool IsExactWriterCleanup(IMethodSymbol method, ITypeSymbol receiverType)
        {
            if (TypeKey(receiverType) != "RetroDownfall.Arcanum.Core.Storage.EncryptedBlobWriter")
            {
                return false;
            }

            return IsExactCleanupContract(method, receiverType);
        }

        private static bool IsCleanupContract(
            INamedTypeSymbol type,
            string name)
        {
            AssemblyName trustedAssembly = (name == "DisposeAsync"
                ? typeof(IAsyncDisposable)
                : typeof(IDisposable)).Assembly.GetName();

            return type.TypeKind == TypeKind.Interface
                && TypeKey(type) == (name == "DisposeAsync"
                    ? "System.IAsyncDisposable"
                    : "System.IDisposable")
                && FrameworkAssemblyIdentityMatches(
                    type.ContainingAssembly.Identity,
                    trustedAssembly)
                && !type.Locations.Any(static location => location.IsInSource);
        }

        private static readonly string[] MicrosoftPublicKeyTokens =
        [
            "adb9793829ddae60",
            "b03f5f7f11d50a3a",
            "31bf3856ad364e35",
            "cc7b13ffcd2ddd51",
            "b77a5c561934e089",
            "7cec85d7bea7798e",
        ];

        private static readonly System.Collections.Concurrent.ConcurrentDictionary<string, AssemblyName?>
            hostLoadedAssemblies = new(StringComparer.Ordinal);

        /// <summary>
        /// A metadata assembly is the Microsoft framework only when it is, by name, version,
        /// culture and public key token, exactly the signed assembly this test host loaded. A
        /// simple name that merely starts with "Microsoft." is not an identity.
        /// </summary>
        private static bool IsHostResolvedMicrosoftAssembly(AssemblyIdentity actual)
        {
            if (actual.PublicKeyToken.IsDefaultOrEmpty
                || !MicrosoftPublicKeyTokens.Contains(
                    Convert.ToHexString(actual.PublicKeyToken.ToArray()).ToLowerInvariant()))
            {
                return false;
            }

            AssemblyName? trusted = hostLoadedAssemblies.GetOrAdd(
                actual.Name,
                static name =>
                {
                    try
                    {
                        return Assembly.Load(new AssemblyName(name)).GetName();
                    }
                    catch (Exception exception) when (exception is
                        System.IO.FileNotFoundException
                        or System.IO.FileLoadException
                        or BadImageFormatException)
                    {
                        return null;
                    }
                });

            return trusted is not null
                && AssemblyIdentityMatches(actual, trusted);
        }

        private static bool AssemblyIdentityMatches(
            AssemblyIdentity actual,
            AssemblyName trusted)
        {
            byte[] trustedToken = trusted.GetPublicKeyToken() ?? [];

            return actual.Name == trusted.Name
                && actual.Version == trusted.Version
                && string.Equals(
                    actual.CultureName ?? string.Empty,
                    trusted.CultureName ?? string.Empty,
                    StringComparison.OrdinalIgnoreCase)
                && actual.PublicKeyToken.SequenceEqual(trustedToken);
        }

        private static bool FrameworkAssemblyIdentityMatches(
            AssemblyIdentity actual,
            AssemblyName trusted)
        {
            if (AssemblyIdentityMatches(actual, trusted))
            {
                return true;
            }

            if (trusted.Name != "System.Private.CoreLib")
            {
                return false;
            }

            string? contractName = actual.Name switch
            {
                "System.Collections" => "System.Collections",
                "System.Runtime" => "System.Runtime",
                "System.Threading" => "System.Threading",
                _ => null,
            };

            if (contractName is null)
            {
                return false;
            }

            AssemblyName runtimeContract = Assembly.Load(
                new AssemblyName(contractName)).GetName();

            return AssemblyIdentityMatches(actual, runtimeContract);
        }

        private static bool HasCleanupReturnShape(
            IMethodSymbol method,
            string name) =>
            name == "DisposeAsync"
                ? IsAwaitable(method.ReturnType)
                : TypeKey(method.ReturnType) == "System.Void";

        private static IMethodSymbol[] SelectPatternCleanupMembers(
            INamedTypeSymbol concrete,
            string name)
        {
            for (INamedTypeSymbol? current = concrete;
                current is not null;
                current = current.BaseType)
            {
                IMethodSymbol[] candidates = current.GetMembers(name)
                    .OfType<IMethodSymbol>()
                    .Where(method => !method.IsStatic
                        && method.Parameters.Length == 0
                        && method.DeclaredAccessibility
                            == Accessibility.Public
                        && HasCleanupReturnShape(method, name))
                    .ToArray();

                if (candidates.Length != 0)
                {
                    return candidates;
                }
            }

            return [];
        }

        private static IMethodSymbol[] SelectEffectiveCleanupMembers(
            ITypeSymbol concreteType,
            string name)
        {
            if (concreteType is not INamedTypeSymbol concrete
                || concrete.TypeKind == TypeKind.Interface
                || concrete.IsAbstract)
            {
                return [];
            }

            IMethodSymbol[] interfaceSlots = concrete.AllInterfaces
                .Where(contract => IsCleanupContract(contract, name))
                .SelectMany(contract => contract.GetMembers(name))
                .OfType<IMethodSymbol>()
                .Where(method => !method.IsStatic
                    && method.Parameters.Length == 0
                    && HasCleanupReturnShape(method, name))
                .ToArray();

            List<IMethodSymbol> implementations = [];

            foreach (IMethodSymbol slot in interfaceSlots)
            {
                if (concrete.FindImplementationForInterfaceMember(slot)
                        is not IMethodSymbol implementation
                    || implementations.Any(candidate =>
                        SymbolEqualityComparer.Default.Equals(
                            candidate.OriginalDefinition,
                            implementation.OriginalDefinition)))
                {
                    continue;
                }

                implementations.Add(MostDerivedCleanupOverride(
                    concrete,
                    implementation,
                    name));
            }

            return implementations.Count != 0
                ? [.. implementations]
                : SelectPatternCleanupMembers(concrete, name);
        }

        private static IMethodSymbol[] SelectEffectiveCleanupMembers(
            ITypeSymbol concreteType,
            ITypeSymbol staticType,
            string name,
            bool configuredAsync)
        {
            IMethodSymbol[] candidateMembers =
                SelectEffectiveCleanupMembers(concreteType, name);

            if (candidateMembers is not [IMethodSymbol candidate]
                || concreteType is not INamedTypeSymbol concrete
                || staticType is not INamedTypeSymbol dispatchType
                || SelectCleanupDispatchMechanism(
                    dispatchType,
                    name,
                    configuredAsync) is not { } mechanism)
            {
                return [];
            }

            if (mechanism == CleanupDispatchMechanism.Interface)
            {
                return candidateMembers;
            }

            IMethodSymbol[] patternSlots = SelectPatternCleanupMembers(
                dispatchType,
                name);

            if (patternSlots is not [IMethodSymbol patternSlot])
            {
                return [];
            }

            IMethodSymbol selected = MostDerivedCleanupOverride(
                concrete,
                patternSlot,
                name);

            return SameCleanupMemberIdentity(candidate, selected)
                ? candidateMembers
                : [selected];
        }

        private static CleanupDispatchMechanism?
            SelectCleanupDispatchMechanism(
                INamedTypeSymbol staticType,
                string name,
                bool configuredAsync)
        {
            bool hasInterfaceContract = IsCleanupContract(staticType, name)
                || staticType.AllInterfaces.Any(
                    contract => IsCleanupContract(contract, name));

            if (configuredAsync
                || name == "Dispose" && hasInterfaceContract)
            {
                return hasInterfaceContract
                    ? CleanupDispatchMechanism.Interface
                    : null;
            }

            if (staticType.TypeKind == TypeKind.Interface)
            {
                return hasInterfaceContract
                    ? CleanupDispatchMechanism.Interface
                    : null;
            }

            if (SelectPatternCleanupMembers(staticType, name) is
                [IMethodSymbol])
            {
                return CleanupDispatchMechanism.Pattern;
            }

            return hasInterfaceContract
                ? CleanupDispatchMechanism.Interface
                : null;
        }

        private static bool IsTrustedCleanupDispatchBase(ITypeSymbol type)
        {
            string typeName = TypeKey(type);

            AssemblyName? trustedAssembly = typeName switch
            {
                "System.Data.Common.DbCommand" =>
                    typeof(System.Data.Common.DbCommand).Assembly.GetName(),
                "System.Data.Common.DbConnection" =>
                    typeof(System.Data.Common.DbConnection).Assembly.GetName(),
                "System.Data.Common.DbDataReader" =>
                    typeof(System.Data.Common.DbDataReader).Assembly.GetName(),
                "System.Data.Common.DbTransaction" =>
                    typeof(System.Data.Common.DbTransaction).Assembly.GetName(),
                "System.IO.Stream" =>
                    typeof(System.IO.Stream).Assembly.GetName(),
                "System.IO.FileStream" =>
                    typeof(System.IO.FileStream).Assembly.GetName(),
                "System.Runtime.InteropServices.SafeHandle" =>
                    typeof(System.Runtime.InteropServices.SafeHandle).Assembly
                        .GetName(),
                "Microsoft.Data.Sqlite.SqliteCommand"
                    or "Microsoft.Data.Sqlite.SqliteConnection"
                    or "Microsoft.Data.Sqlite.SqliteDataReader"
                    or "Microsoft.Data.Sqlite.SqliteTransaction" =>
                    typeof(Microsoft.Data.Sqlite.SqliteConnection).Assembly
                        .GetName(),
                _ => null,
            };

            return trustedAssembly is not null
                && IsExactFrameworkType(
                    type,
                    typeName,
                    trustedAssembly);
        }

        private static IMethodSymbol MostDerivedCleanupOverride(
            INamedTypeSymbol concrete,
            IMethodSymbol implementation,
            string name)
        {
            if (!implementation.IsVirtual
                || implementation.ExplicitInterfaceImplementations.Length != 0)
            {
                return implementation;
            }

            for (INamedTypeSymbol? current = concrete;
                current is not null;
                current = current.BaseType)
            {
                foreach (IMethodSymbol candidate in current.GetMembers(name)
                    .OfType<IMethodSymbol>()
                    .Where(method => !method.IsStatic
                        && method.Parameters.Length == 0
                        && HasCleanupReturnShape(method, name)))
                {
                    for (IMethodSymbol? overridden = candidate;
                        overridden is not null;
                        overridden = overridden.OverriddenMethod)
                    {
                        if (SameCleanupSlot(
                            overridden,
                            implementation,
                            candidate.Locations.Any(static location =>
                                location.IsInSource)))
                        {
                            return candidate;
                        }
                    }
                }
            }

            return implementation;
        }

        private static bool SameCleanupSlot(
            IMethodSymbol left,
            IMethodSymbol right,
            bool authoredCandidate) =>
            SymbolEqualityComparer.Default.Equals(
                left.OriginalDefinition,
                right.OriginalDefinition)
            || authoredCandidate
                && SameCleanupMemberIdentity(left, right);

        private static bool SameCleanupMemberIdentity(
            IMethodSymbol left,
            IMethodSymbol right) =>
            MethodKey(left) == MethodKey(right)
            && (left.ContainingAssembly.Identity.Equals(
                    right.ContainingAssembly.Identity)
                || IsTrustedCleanupDispatchBase(left.ContainingType)
                    && IsTrustedCleanupDispatchBase(
                        right.ContainingType));

        private AuthoredMember? ResolveClosedAuthoredInterfaceCleanup(
            ITypeSymbol staticType,
            string name,
            Compilation consumingCompilation)
        {
            static bool IsClosedInternalType(INamedTypeSymbol type) =>
                type.DeclaredAccessibility is
                    Accessibility.Internal or Accessibility.Private
                || type.ContainingType is { } containing
                    && IsClosedInternalType(containing);

            if (staticType is not INamedTypeSymbol
                {
                    TypeKind: TypeKind.Interface,
                } contract
                || !IsClosedInternalType(contract)
                || AuthoredCompilationIdentity(
                    contract,
                    consumingCompilation) is null)
            {
                return null;
            }

            BoundTypeIdentity contractIdentity = TypeIdentity(
                contract,
                consumingCompilation);

            CleanupContractResolutionIdentity cacheIdentity = new(
                contractIdentity.Assembly,
                contractIdentity.Compilation,
                contract.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat),
                name);

            if (closedInterfaceCleanupTargets.TryGetValue(
                    cacheIdentity,
                    out AuthoredMember? cached))
            {
                return cached;
            }

            AuthoredMember[] implementations = AuthoredMembers
                .Where(candidate =>
                    candidate.Symbol.ContainingType is
                    {
                        IsAbstract: false,
                        TypeKind: not TypeKind.Interface,
                    } concrete
                    && concrete.AllInterfaces.Any(implemented =>
                        SameBoundType(
                            implemented,
                            candidate.Model.Compilation,
                            contract,
                            consumingCompilation)))
                .GroupBy(candidate => TypeIdentity(
                    candidate.Symbol.ContainingType,
                    candidate.Model.Compilation))
                .Select(static group => group.First())
                .ToArray();

            if (implementations is not [AuthoredMember implementation])
            {
                closedInterfaceCleanupTargets.Add(cacheIdentity, null);

                return null;
            }

            IMethodSymbol[] cleanupMembers = SelectEffectiveCleanupMembers(
                implementation.Symbol.ContainingType,
                name);

            AuthoredMember[] targets = cleanupMembers
                .Select(cleanup => Resolve(
                    cleanup,
                    implementation.Model.Compilation))
                .OfType<AuthoredMember>()
                .DistinctBy(MemberIdentity)
                .ToArray();

            AuthoredMember? resolvedTarget = cleanupMembers.Length == 1
                && targets is [AuthoredMember target]
                    ? target
                    : null;

            closedInterfaceCleanupTargets.Add(cacheIdentity, resolvedTarget);

            return resolvedTarget;
        }

        private AuthoredMember? ResolveConvergentAuthoredRecordPropertyCleanup(
            AuthoredMember member,
            ITypeSymbol staticType,
            ExpressionSyntax? resource,
            string name,
            CleanupProvenance provenance)
        {
            if (staticType is not INamedTypeSymbol
                {
                    TypeKind: TypeKind.Interface,
                } contract
                || resource is not MemberAccessExpressionSyntax access
                || member.Model.GetSymbolInfo(resource).Symbol is not
                    IPropertySymbol property
                || property.ContainingType is not
                {
                    IsRecord: true,
                    IsSealed: true,
                } record
                || property.SetMethod is { IsInitOnly: false }
                || !IsAuthoredCleanupSymbol(
                    property,
                    member.Model.Compilation)
                || member.Model.GetTypeInfo(access.Expression).Type is not
                { } receiverType
                || !SameBoundType(
                    receiverType,
                    member.Model.Compilation,
                    record,
                    member.Model.Compilation)
                || !SameBoundType(
                    property.Type,
                    member.Model.Compilation,
                    contract,
                    member.Model.Compilation)
                || !provenance.Complete
                || provenance.Candidates.Count == 0)
            {
                return null;
            }

            CleanupProvenanceIdentity propertyIdentity = CleanupIdentity(
                member,
                resource);

            var cacheIdentity = (propertyIdentity, name);

            if (convergentPropertyCleanupTargets.TryGetValue(
                    cacheIdentity,
                    out AuthoredMember? cached))
            {
                return cached;
            }

            AuthoredMember?[] implementationTargets = provenance.Candidates
                .DistinctBy(static candidate => candidate.Identity)
                .Select(candidate =>
                    SelectEffectiveCleanupMembers(
                        candidate.Type,
                        name) is [IMethodSymbol cleanup]
                        ? Resolve(cleanup, member.Model.Compilation)
                        : null)
                .ToArray();

            AuthoredMember[] targets = implementationTargets
                .OfType<AuthoredMember>()
                .DistinctBy(MemberIdentity)
                .ToArray();

            AuthoredMember? resolvedTarget = targets is [AuthoredMember target]
                && implementationTargets.All(static candidate =>
                    candidate is not null)
                    ? target
                    : null;

            convergentPropertyCleanupTargets.Add(
                cacheIdentity,
                resolvedTarget);

            return resolvedTarget;
        }

        private static IMethodSymbol[] SelectCompilerCleanupMembers(
            INamedTypeSymbol staticType,
            string name)
        {
            IMethodSymbol[] patternMembers = SelectPatternCleanupMembers(
                staticType,
                name);

            if (patternMembers.Length != 0)
            {
                return patternMembers;
            }

            IMethodSymbol[] interfaceSlots = staticType.AllInterfaces
                .Where(contract => IsCleanupContract(contract, name))
                .SelectMany(contract => contract.GetMembers(name))
                .OfType<IMethodSymbol>()
                .Where(method => !method.IsStatic
                    && method.Parameters.Length == 0
                    && HasCleanupReturnShape(method, name))
                .ToArray();

            IMethodSymbol[] implementations = interfaceSlots
                .Select(staticType.FindImplementationForInterfaceMember)
                .OfType<IMethodSymbol>()
                .DistinctBy(static method => method.OriginalDefinition,
                    SymbolEqualityComparer.Default)
                .ToArray();

            return implementations;
        }

        private IMethodSymbol? CompilerSelectedExternalCleanup(
            ITypeSymbol dispatchType,
            string name,
            Compilation consumingCompilation,
            bool exactRuntimeType)
        {
            if (!exactRuntimeType
                || dispatchType is not INamedTypeSymbol
                {
                    TypeKind: not TypeKind.Interface,
                } concrete
                || dispatchType.Locations.Any(static location =>
                    location.IsInSource)
                || AuthoredCompilationIdentity(
                    dispatchType,
                    consumingCompilation) is not null
                || compilationIdentities.Keys
                    .OfType<CSharpCompilation>()
                    .Any(compilation => compilation.Assembly.Identity.Equals(
                        dispatchType.ContainingAssembly.Identity)))
            {
                return null;
            }

            IMethodSymbol[] cleanupMembers = SelectCompilerCleanupMembers(
                concrete,
                name);

            if (cleanupMembers is not [IMethodSymbol cleanup]
                || cleanup.Locations.Any(static location =>
                    location.IsInSource)
                || AuthoredCompilationIdentity(
                    cleanup,
                    consumingCompilation) is not null
                || compilationIdentities.Keys
                    .OfType<CSharpCompilation>()
                    .Any(compilation => compilation.Assembly.Identity.Equals(
                        cleanup.ContainingAssembly.Identity)))
            {
                return null;
            }

            return cleanup;
        }

        private CleanupProvenance? ExactTrustedSqliteFactoryProvenance(
            AuthoredMember member,
            InvocationExpressionSyntax call,
            IMethodSymbol method,
            CleanupProvenanceContext context)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            if (definition.Locations.Any(static location =>
                    location.IsInSource)
                || AdmissionReceiver(member, call) is not { } receiver)
            {
                return null;
            }

            // SqliteSealedByUse: a receiver whose static type is exactly SqliteConnection or SqliteCommand
            // is that exact runtime type whatever its provenance. A receiver typed as an abstract Db* type
            // gets no such shortcut and keeps the provenance proof.
            CleanupProvenance receiverProvenance = SqliteSealedByUse
                && member.Model.GetTypeInfo(receiver).Type is { } sealedReceiver
                && IsSqliteSealedFamilyClass(sealedReceiver)
                    ? ExactCleanupProvenance(member, sealedReceiver)
                    : CleanupProvenanceOf(
                        member,
                        receiver,
                        context);

            if (!receiverProvenance.Complete
                || receiverProvenance.Candidates is not
                    [CleanupTypeCandidate exactReceiver]
                || !AssemblyIdentityMatches(
                    exactReceiver.Type.ContainingAssembly.Identity,
                    typeof(Microsoft.Data.Sqlite.SqliteConnection)
                        .Assembly.GetName()))
            {
                return null;
            }

            string receiverType = TypeKey(exactReceiver.Type);

            string? resultMetadataName = null;

            if (receiverType == "Microsoft.Data.Sqlite.SqliteConnection"
                && TypeKey(definition.ContainingType) is
                    "Microsoft.Data.Sqlite.SqliteConnection"
                        or "System.Data.Common.DbConnection"
                && definition.Name == "CreateCommand"
                && HasExactParameterTypes(definition)
                && TypeKey(definition.ReturnType) is
                    "Microsoft.Data.Sqlite.SqliteCommand"
                        or "System.Data.Common.DbCommand"
                && (AssemblyIdentityMatches(
                        definition.ContainingAssembly.Identity,
                        typeof(Microsoft.Data.Sqlite.SqliteConnection)
                            .Assembly.GetName())
                    || FrameworkAssemblyIdentityMatches(
                        definition.ContainingAssembly.Identity,
                        typeof(System.Data.Common.DbConnection)
                            .Assembly.GetName())))
            {
                resultMetadataName =
                    "Microsoft.Data.Sqlite.SqliteCommand";
            }
            else if (receiverType == "Microsoft.Data.Sqlite.SqliteCommand"
                && TypeKey(definition.ContainingType) is
                    "Microsoft.Data.Sqlite.SqliteCommand"
                        or "System.Data.Common.DbCommand"
                && definition.Name == "ExecuteReaderAsync"
                && HasExactSqliteReaderParameters(definition)
                && definition.ReturnType is INamedTypeSymbol
                {
                    TypeArguments: [ITypeSymbol reader],
                }
                && TypeKey(definition.ReturnType)
                    == "System.Threading.Tasks.Task`1"
                && TypeKey(reader)
                    is "Microsoft.Data.Sqlite.SqliteDataReader"
                        or "System.Data.Common.DbDataReader"
                && (AssemblyIdentityMatches(
                        definition.ContainingAssembly.Identity,
                        typeof(Microsoft.Data.Sqlite.SqliteConnection)
                            .Assembly.GetName())
                    || FrameworkAssemblyIdentityMatches(
                        definition.ContainingAssembly.Identity,
                        typeof(System.Data.Common.DbCommand)
                            .Assembly.GetName())))
            {
                resultMetadataName =
                    "Microsoft.Data.Sqlite.SqliteDataReader";
            }
            else if (receiverType
                    == "Microsoft.Data.Sqlite.SqliteConnection"
                && TypeKey(definition.ContainingType)
                    == "Microsoft.Data.Sqlite.SqliteConnection"
                && definition.Name == "BeginTransaction"
                && (HasExactParameterTypes(definition)
                    || HasExactParameterTypes(
                        definition,
                        "System.Boolean")
                    || HasExactParameterTypes(
                        definition,
                        "System.Data.IsolationLevel")
                    || HasExactParameterTypes(
                        definition,
                        "System.Data.IsolationLevel",
                        "System.Boolean"))
                && TypeKey(definition.ReturnType)
                    == "Microsoft.Data.Sqlite.SqliteTransaction"
                && AssemblyIdentityMatches(
                    definition.ContainingAssembly.Identity,
                    typeof(Microsoft.Data.Sqlite.SqliteConnection)
                        .Assembly.GetName()))
            {
                resultMetadataName =
                    "Microsoft.Data.Sqlite.SqliteTransaction";
            }
            else if (receiverType
                    == "Microsoft.Data.Sqlite.SqliteConnection"
                && TypeKey(definition.ContainingType)
                    == "System.Data.Common.DbConnection"
                && definition.Name == "BeginTransactionAsync"
                && HasExactSqliteTransactionParameters(definition)
                && definition.ReturnType is INamedTypeSymbol
                {
                    TypeArguments: [ITypeSymbol transactionContract],
                }
                && TypeKey(definition.ReturnType)
                    == "System.Threading.Tasks.ValueTask`1"
                && TypeKey(transactionContract)
                    == "System.Data.Common.DbTransaction"
                && FrameworkAssemblyIdentityMatches(
                    definition.ContainingAssembly.Identity,
                    typeof(System.Data.Common.DbConnection)
                        .Assembly.GetName()))
            {
                resultMetadataName =
                    "Microsoft.Data.Sqlite.SqliteTransaction";
            }

            if (resultMetadataName is null
                || exactReceiver.Type.ContainingAssembly
                    .GetTypeByMetadataName(resultMetadataName) is not
                    INamedTypeSymbol resultType
                || resultType.Locations.Any(static location =>
                    location.IsInSource)
                || !SymbolEqualityComparer.Default.Equals(
                    resultType.ContainingAssembly,
                    exactReceiver.Type.ContainingAssembly))
            {
                return null;
            }

            return ExactCleanupProvenance(member, resultType);
        }

        private CleanupProvenance? ExactTrustedExternalFactoryProvenance(
            AuthoredMember member,
            InvocationExpressionSyntax call,
            IMethodSymbol method,
            CleanupProvenanceContext context)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            if (definition.Locations.Any(static location => location.IsInSource))
            {
                return null;
            }

            string callee = Normalize(definition);

            bool exactFactory = callee switch
            {
                "System.Security.Principal.WindowsIdentity.GetCurrent" =>
                    HasExactParameterTypes(definition)
                    && AssemblyIdentityMatches(
                        definition.ContainingAssembly.Identity,
                        typeof(System.Security.Principal.WindowsIdentity)
                            .Assembly.GetName()),
                "System.Threading.CancellationTokenSource.CreateLinkedTokenSource" =>
                    FrameworkAssemblyIdentityMatches(
                        definition.ContainingAssembly.Identity,
                        typeof(CancellationTokenSource).Assembly.GetName()),
                "System.Diagnostics.Process.GetProcessById" =>
                    HasExactParameterTypes(definition, "System.Int32")
                    && AssemblyIdentityMatches(
                        definition.ContainingAssembly.Identity,
                        typeof(System.Diagnostics.Process).Assembly.GetName()),
                "System.IO.FileSystemAclExtensions.Create" =>
                    HasExactParameterTypes(
                        definition,
                        "System.IO.FileInfo",
                        "System.IO.FileMode",
                        "System.Security.AccessControl.FileSystemRights",
                        "System.IO.FileShare",
                        "System.Int32",
                        "System.IO.FileOptions",
                        "System.Security.AccessControl.FileSecurity")
                    && FrameworkAssemblyIdentityMatches(
                        definition.ContainingAssembly.Identity,
                        typeof(System.IO.FileSystemAclExtensions).Assembly.GetName()),
                "System.IO.File.OpenRead" =>
                    HasExactParameterTypes(definition, "System.String")
                    && FrameworkAssemblyIdentityMatches(
                        definition.ContainingAssembly.Identity,
                        typeof(System.IO.File).Assembly.GetName()),
                _ => false,
            };

            if (exactFactory
                && definition.ReturnType is INamedTypeSymbol
                {
                    TypeKind: TypeKind.Class,
                    IsAbstract: false,
                } exactResult)
            {
                return ExactTrustedMetadataProvenance(
                    member,
                    exactResult);
            }

            if (callee is "System.Data.Common.DbDataReader.GetStream"
                    or "Microsoft.Data.Sqlite.SqliteDataReader.GetStream"
                && HasExactParameterTypes(definition, "System.Int32")
                && (FrameworkAssemblyIdentityMatches(
                        definition.ContainingAssembly.Identity,
                        typeof(System.Data.Common.DbDataReader)
                            .Assembly.GetName())
                    || AssemblyIdentityMatches(
                        definition.ContainingAssembly.Identity,
                        typeof(Microsoft.Data.Sqlite.SqliteDataReader)
                            .Assembly.GetName()))
                && AdmissionReceiver(member, call) is { } readerReceiver)
            {
                CleanupProvenance reader = CleanupProvenanceOf(
                    member,
                    readerReceiver,
                    context);

                if (reader.Complete
                    && reader.Candidates is [CleanupTypeCandidate candidate]
                    && TypeKey(candidate.Type)
                        == "Microsoft.Data.Sqlite.SqliteDataReader"
                    && AssemblyIdentityMatches(
                        candidate.Type.ContainingAssembly.Identity,
                        typeof(Microsoft.Data.Sqlite.SqliteDataReader)
                            .Assembly.GetName())
                    && member.Model.Compilation.GetTypeByMetadataName(
                        "System.IO.MemoryStream") is
                        INamedTypeSymbol memoryStream)
                {
                    return ExactTrustedMetadataProvenance(
                        member,
                        memoryStream);
                }
            }

            return null;
        }

        private CleanupProvenance? ExactConfiguredSqliteConnectionProvenance(
            AuthoredMember member,
            InvocationExpressionSyntax call,
            IMethodSymbol method,
            CleanupProvenanceContext context)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            if (definition.Name != "GetDbConnection"
                || TypeKey(definition.ContainingType)
                    != "Microsoft.EntityFrameworkCore.RelationalDatabaseFacadeExtensions"
                || !AssemblyIdentityMatches(
                    definition.ContainingAssembly.Identity,
                    typeof(Microsoft.EntityFrameworkCore.RelationalDatabaseFacadeExtensions)
                        .Assembly.GetName())
                || definition.Locations.Any(static location =>
                    location.IsInSource)
                || TypeKey(definition.ReturnType)
                    != "System.Data.Common.DbConnection"
                || member.Model.GetOperation(call) is not
                    IInvocationOperation operation)
            {
                return null;
            }

            ExpressionSyntax? database = operation.Instance?.Syntax
                    as ExpressionSyntax
                ?? operation.Arguments
                    .Where(static argument => argument.Parameter is not null
                        && TypeKey(argument.Parameter.Type)
                            == "Microsoft.EntityFrameworkCore.Infrastructure.DatabaseFacade")
                    .Select(static argument => argument.Value.Syntax)
                    .OfType<ExpressionSyntax>()
                    .SingleOrDefault();

            database = database is null
                ? null
                : StripTransparentExpression(database);

            if (database is not MemberAccessExpressionSyntax
                {
                    Expression: { } contextExpression,
                }
                || member.Model.GetSymbolInfo(database).Symbol is not
                    IPropertySymbol
                {
                    Name: "Database",
                } databaseProperty
                || TypeKey(databaseProperty.ContainingType)
                    != "Microsoft.EntityFrameworkCore.DbContext"
                || !AssemblyIdentityMatches(
                    databaseProperty.ContainingAssembly.Identity,
                    typeof(Microsoft.EntityFrameworkCore.DbContext)
                        .Assembly.GetName()))
            {
                return null;
            }

            CleanupProvenance contextProvenance = CleanupProvenanceOf(
                member,
                contextExpression,
                context);

            if (!contextProvenance.Complete
                || context.ClosedSqliteProvider
                    && !IsContainerResolvedDbContextInstance(
                        member,
                        contextExpression)
                || contextProvenance.Candidates is not
                    [CleanupTypeCandidate { Type: INamedTypeSymbol dbContext }]
                || dbContext is not
                {
                    IsAbstract: false,
                    IsSealed: true,
                }
                || AuthoredCompilationIdentity(
                    dbContext,
                    member.Model.Compilation) is null
                || !IsExactEfDbContext(dbContext)
                || !HasExactSqliteDbContextRegistration(
                    dbContext,
                    member.Model.Compilation)
                || context.ClosedSqliteProvider
                    && !HasClosedSqliteDbContextConfiguration(
                        dbContext,
                        member.Model.Compilation)
                || member.Model.Compilation.GetTypeByMetadataName(
                    "Microsoft.Data.Sqlite.SqliteConnection") is not
                    INamedTypeSymbol sqliteConnection
                || sqliteConnection.Locations.Any(static location =>
                    location.IsInSource)
                || !AssemblyIdentityMatches(
                    sqliteConnection.ContainingAssembly.Identity,
                    typeof(Microsoft.Data.Sqlite.SqliteConnection)
                        .Assembly.GetName()))
            {
                return null;
            }

            return ExactTrustedMetadataProvenance(
                member,
                sqliteConnection);
        }

        /// <summary>
        /// The type-only provenance above cannot tell a container-resolved context from a
        /// caller-created one: a registration's UseSqlite only configures the instances the
        /// container builds. Every terminal source of the value must be an exact dependency
        /// the container injects or an exact framework service resolution.
        /// </summary>
        private bool IsContainerResolvedDbContextInstance(
            AuthoredMember member,
            ExpressionSyntax contextExpression)
        {
            CleanupValueFlow flow = CleanupValueFlowOf(
                member,
                contextExpression,
                new CleanupProvenanceContext());

            return flow.Complete
                && flow.Values.Count != 0
                && flow.Values.All(IsContainerResolvedDbContextSource);
        }

        private bool IsContainerResolvedDbContextSource(BoundValueSource source)
        {
            ExpressionSyntax value = StripTransparentExpression(
                source.Expression);

            ISymbol? symbol = source.Caller.Model.GetSymbolInfo(value).Symbol;

            if (symbol is IParameterSymbol
                {
                    ContainingSymbol: IMethodSymbol
                    {
                        MethodKind: MethodKind.Constructor,
                    },
                    Type: INamedTypeSymbol
                    {
                        IsAbstract: false,
                        IsSealed: true,
                    } dependencyType,
                } dependency)
            {
                // The value flow follows storage but not a write to the captured parameter itself, so
                // a parameter that anything in its type writes is not the instance the container injected.
                return ConstructorParameterNeverWritten(dependency)
                    && IsExactRegisteredConstructorDependency(
                        source.Caller,
                        dependency,
                        dependencyType);
            }

            // H1: an exact GetRequiredService on an unproven IServiceProvider is not the
            // host container (authored or extern providers can return any instance).
            if (value is not InvocationExpressionSyntax
                {
                    Expression: MemberAccessExpressionSyntax { Expression: { } providerExpression },
                }
                || symbol is not IMethodSymbol resolver
                || resolver.Name is not ("GetRequiredService" or "GetService")
                || !IsExactFrameworkMethod(
                    resolver,
                    "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions",
                    resolver.Name,
                    "Microsoft.Extensions.DependencyInjection.Abstractions"))
            {
                return false;
            }

            // The receiver must be the container's own provider: a registration factory's
            // provider parameter, an injected provider or scope factory of an exactly activated
            // owner, or the ServiceProvider of a scope created from one of those.
            return IsContainerProviderValue(source.Caller, providerExpression, 0);
        }

        private bool IsContainerProviderValue(
            AuthoredMember caller,
            ExpressionSyntax expression,
            int depth)
        {
            if (depth > 4)
            {
                return false;
            }

            ExpressionSyntax stripped = StripTransparentExpression(expression);

            if (IsContainerProviderSource(new BoundValueSource(caller, stripped), depth, direct: true) is true)
            {
                return true;
            }

            CleanupValueFlow flow = CleanupValueFlowOf(
                caller,
                stripped,
                new CleanupProvenanceContext());

            return flow.Complete
                && flow.Values.Count != 0
                && flow.Values.All(value => IsContainerProviderSource(value, depth, direct: false) is true);
        }

        private bool? IsContainerProviderSource(
            BoundValueSource source,
            int depth,
            bool direct)
        {
            ExpressionSyntax value = StripTransparentExpression(
                source.Expression);

            ISymbol? symbol = source.Caller.Model.GetSymbolInfo(value).Symbol;

            // A parameter the factory body writes anywhere is not the container, whether it is
            // named here or reached through an alias that captured it after the write.
            if (IsRegistrationFactoryProvider(symbol)
                && ParameterNeverWritten((IParameterSymbol)symbol!))
            {
                return true;
            }

            if (symbol is IParameterSymbol
                {
                    ContainingSymbol: IMethodSymbol { MethodKind: MethodKind.Constructor },
                } dependency
                && ConstructorParameterNeverWritten(dependency)
                && TypeKey(dependency.Type) is "System.IServiceProvider"
                    or "Microsoft.Extensions.DependencyInjection.IServiceScopeFactory")
            {
                return IsExactRegisteredConstructorDependency(
                    source.Caller,
                    dependency,
                    dependency.Type);
            }

            if (value is MemberAccessExpressionSyntax { Expression: { } scope }
                && symbol is IPropertySymbol { Name: "ServiceProvider", IsStatic: false } property
                && TypeKey(property.ContainingType) is "Microsoft.Extensions.DependencyInjection.IServiceScope"
                    or "Microsoft.Extensions.DependencyInjection.AsyncServiceScope"
                && !property.Locations.Any(static location => location.IsInSource)
                && AssemblyIdentityMatches(
                    property.ContainingAssembly.Identity,
                    typeof(Microsoft.Extensions.DependencyInjection.IServiceScope).Assembly.GetName()))
            {
                CleanupValueFlow scopes = CleanupValueFlowOf(
                    source.Caller,
                    scope,
                    new CleanupProvenanceContext());

                return scopes.Complete
                    && scopes.Values.Count != 0
                    && scopes.Values.All(created => IsContainerScopeCreation(created, depth));
            }

            return direct ? null : false;
        }

        private bool ConstructorParameterNeverWritten(IParameterSymbol parameter) =>
            parameter.ContainingSymbol is IMethodSymbol { ContainingType: { } owner }
            && owner.DeclaringSyntaxReferences.Length != 0
            && ParameterNeverWrittenWithin(parameter, owner.DeclaringSyntaxReferences.Select(static reference => reference.GetSyntax()));

        private bool ParameterNeverWritten(IParameterSymbol parameter) =>
            parameter.DeclaringSyntaxReferences is [{ } reference]
            && reference.GetSyntax().FirstAncestorOrSelf<AnonymousFunctionExpressionSyntax>() is { } function
            && ParameterNeverWrittenWithin(parameter, [function]);

        private bool ParameterNeverWrittenWithin(IParameterSymbol parameter, IEnumerable<SyntaxNode> scopes)
        {
            foreach (SyntaxNode declaration in scopes)
            {
                if (!semanticModels.TryGetValue(declaration.SyntaxTree, out SemanticModel? model))
                {
                    return false;
                }

                foreach (IdentifierNameSyntax name in declaration.DescendantNodes().OfType<IdentifierNameSyntax>())
                {
                    if (name.Identifier.ValueText != parameter.Name
                        || !SymbolEqualityComparer.Default.Equals(model.GetSymbolInfo(name).Symbol, parameter))
                    {
                        continue;
                    }

                    if (IsParameterReferenceWritten(model, name))
                    {
                        return false;
                    }
                }
            }

            return true;
        }

        /// <summary>
        /// A write is judged on the operation the compiler binds, not on the shape of the syntax around
        /// the name: an assignment (simple, compound, coalescing or deconstructing, however deeply the
        /// target tuple nests), a ref, out or in argument, an increment, an address-of, or a ref alias
        /// all change what the parameter holds. A reference the compiler gives no operation is refused
        /// unless it only names the parameter.
        /// </summary>
        private static bool IsParameterReferenceWritten(SemanticModel model, IdentifierNameSyntax name)
        {
            SyntaxNode? parent = name.Parent;

            while (parent is ParenthesizedExpressionSyntax)
            {
                parent = parent.Parent;
            }

            if (parent is ArgumentSyntax { RefKindKeyword.RawKind: not 0 }
                or RefExpressionSyntax
                or PrefixUnaryExpressionSyntax { RawKind: (int)SyntaxKind.AddressOfExpression })
            {
                return true;
            }

            if (model.GetOperation(name) is not { } reference)
            {
                return !name.Ancestors().OfType<InvocationExpressionSyntax>().Any(static invocation =>
                    invocation.Expression is IdentifierNameSyntax { Identifier.ValueText: "nameof" });
            }

            IOperation node = reference;

            while (node.Parent is ITupleOperation)
            {
                node = node.Parent;
            }

            return node.Parent switch
            {
                IAssignmentOperation assignment => ReferenceEquals(assignment.Target, node)
                    || assignment is ISimpleAssignmentOperation { IsRef: true } && ReferenceEquals(assignment.Value, node),
                IIncrementOrDecrementOperation => true,
                IAddressOfOperation => true,
                IArgumentOperation argument => argument.Parameter is null || argument.Parameter.RefKind != RefKind.None,
                IVariableInitializerOperation { Parent: IVariableDeclaratorOperation declarator } =>
                    declarator.Symbol.RefKind != RefKind.None,
                _ => false,
            };
        }

        private bool IsContainerScopeCreation(
            BoundValueSource source,
            int depth)
        {
            if (StripTransparentExpression(source.Expression) is not InvocationExpressionSyntax creation
                || source.Caller.Model.GetSymbolInfo(creation).Symbol is not IMethodSymbol method
                || source.Caller.Model.GetOperation(creation) is not IInvocationOperation operation
                || ExactInvocationReceiverOrFirstArgument(operation) is not { } factory)
            {
                return false;
            }

            IMethodSymbol definition = method.ReducedFrom ?? method;

            bool exact = definition.Name is "CreateScope" or "CreateAsyncScope"
                && (IsExactFrameworkMethod(
                        method,
                        "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions",
                        definition.Name,
                        "Microsoft.Extensions.DependencyInjection.Abstractions")
                    || TypeKey(definition.ContainingType) == "Microsoft.Extensions.DependencyInjection.IServiceScopeFactory"
                        && !definition.Locations.Any(static location => location.IsInSource)
                        && AssemblyIdentityMatches(
                            definition.ContainingAssembly.Identity,
                            typeof(Microsoft.Extensions.DependencyInjection.IServiceScopeFactory).Assembly.GetName()));

            return exact
                && IsContainerProviderValue(source.Caller, factory, depth + 1);
        }

        private bool IsRegistrationFactoryProvider(ISymbol? symbol)
        {
            if (symbol is not IParameterSymbol
                {
                    Ordinal: 0,
                    ContainingSymbol: IMethodSymbol { MethodKind: MethodKind.AnonymousFunction },
                    DeclaringSyntaxReferences: [{ } providerReference],
                } provider
                || TypeKey(provider.Type) != "System.IServiceProvider"
                || providerReference.GetSyntax().FirstAncestorOrSelf<AnonymousFunctionExpressionSyntax>() is not
                {
                    Parent: ArgumentSyntax { Parent: ArgumentListSyntax { Parent: InvocationExpressionSyntax registration } },
                } factory
                || !semanticModels.TryGetValue(factory.SyntaxTree, out SemanticModel? registrationModel)
                || registrationModel.GetSymbolInfo(registration).Symbol is not IMethodSymbol registrationMethod)
            {
                return false;
            }

            string name = (registrationMethod.ReducedFrom ?? registrationMethod).Name;

            return IsExactFrameworkMethod(
                    registrationMethod,
                    "Microsoft.Extensions.DependencyInjection.ServiceCollectionServiceExtensions",
                    name,
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
                || IsExactFrameworkMethod(
                    registrationMethod,
                    "Microsoft.Extensions.DependencyInjection.Extensions.ServiceCollectionDescriptorExtensions",
                    name,
                    "Microsoft.Extensions.DependencyInjection.Abstractions");
        }

        // ---- Final options/provider closure for a container-built DbContext (issue #91).

        private IReadOnlyList<(InvocationExpressionSyntax Call, SemanticModel Model, IMethodSymbol Method)>?
            serviceCollectionMutations;

        private IReadOnlyList<(InvocationExpressionSyntax Call, SemanticModel Model, IMethodSymbol Method)>
            ServiceCollectionMutations()
        {
            if (serviceCollectionMutations is not null)
            {
                return serviceCollectionMutations;
            }

            List<(InvocationExpressionSyntax Call, SemanticModel Model, IMethodSymbol Method)> found = [];

            foreach ((InvocationExpressionSyntax call, SemanticModel model) in invocations)
            {
                if (model.GetSymbolInfo(call).Symbol is not IMethodSymbol method)
                {
                    continue;
                }

                IMethodSymbol definition = method.ReducedFrom ?? method;

                bool touchesCollection = definition.Parameters.Any(static parameter =>
                        IsServiceCollectionType(parameter.Type))
                    || call.Expression is MemberAccessExpressionSyntax
                    {
                        Expression: { } receiver,
                    }
                    && model.GetTypeInfo(receiver).Type is { } receiverType
                    && IsServiceCollectionType(receiverType);

                if (touchesCollection)
                {
                    found.Add((call, model, method));
                }
            }

            serviceCollectionMutations = found;

            return found;
        }

        private static bool IsServiceCollectionType(ITypeSymbol type) =>
            TypeKey(type) is "Microsoft.Extensions.DependencyInjection.IServiceCollection"
                or "Microsoft.Extensions.DependencyInjection.ServiceCollection";

        /// <summary>
        /// A context resolved from the container is configured by exactly the descriptors the
        /// composition leaves in the collection. Any other descriptor for the context or its
        /// options, or any collection mutation this analysis cannot read, can replace them.
        /// </summary>
        private bool HasCompetingDbContextServiceDescriptor(
            INamedTypeSymbol dbContext,
            Compilation consumingCompilation)
        {
            foreach ((InvocationExpressionSyntax call, SemanticModel model, IMethodSymbol method)
                in ServiceCollectionMutations())
            {
                IMethodSymbol definition = method.ReducedFrom ?? method;

                if (definition.Name is "AddDbContext" or "AddDbContextPool"
                    && IsExactFrameworkMethod(
                        method,
                        "Microsoft.Extensions.DependencyInjection.EntityFrameworkServiceCollectionExtensions",
                        definition.Name,
                        "Microsoft.EntityFrameworkCore"))
                {
                    // Exactly EF's registration: for this context the selected registrations are
                    // validated individually, and for any other context it cannot touch this one.
                    // A helper that only borrows the name is judged like any other helper below.
                    continue;
                }

                if (definition.DeclaringSyntaxReferences.Length != 0)
                {
                    if (definition.IsExtern
                        || definition.IsAbstract
                        || definition.ContainingType.TypeKind == TypeKind.Interface
                        || definition.DeclaringSyntaxReferences.Any(static reference =>
                            reference.GetSyntax() is BaseMethodDeclarationSyntax
                            {
                                Body: null,
                                ExpressionBody: null,
                            }))
                    {
                        return true;
                    }

                    // An inspectable authored helper registers through the calls its body
                    // makes; the concrete types reaching it are read at this call site.
                    if (method.TypeArguments.Any(argument => IsDbContextRelevantServiceType(
                            argument,
                            model.Compilation,
                            dbContext,
                            consumingCompilation)))
                    {
                        return true;
                    }

                    continue;
                }

                if (definition.MethodKind == MethodKind.DelegateInvoke)
                {
                    return true;
                }

                // A name that starts with "Microsoft." proves nothing: only the signed assembly this
                // test host itself loaded, by exact identity, is the framework.
                if (!IsHostResolvedMicrosoftAssembly(definition.ContainingAssembly.Identity)
                    && !IsExactProductionFrameworkServiceBuilder(method))
                {
                    return true;
                }

                if (definition.Name is "Clear" or "RemoveAt")
                {
                    return true;
                }

                foreach (ITypeSymbol? serviceType in MutatedServiceTypes(call, model, method))
                {
                    if (IsDbContextRelevantServiceType(
                        serviceType,
                        model.Compilation,
                        dbContext,
                        consumingCompilation))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private static IEnumerable<ITypeSymbol?> MutatedServiceTypes(
            InvocationExpressionSyntax call,
            SemanticModel model,
            IMethodSymbol method)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            bool descriptorLevel = definition.Name is "Add" or "TryAdd" or "TryAddEnumerable"
                or "Replace" or "Remove" or "RemoveAll" or "Insert";

            if (!descriptorLevel)
            {
                if (method.TypeArguments.Length != 0)
                {
                    yield return method.TypeArguments[0];

                    yield break;
                }

                foreach (ArgumentSyntax argument in call.ArgumentList.Arguments)
                {
                    if (model.GetTypeInfo(argument.Expression).Type is { } argumentType
                        && TypeKey(argumentType) == "System.Type")
                    {
                        yield return TypeOfOperand(argument.Expression, model);

                        yield break;
                    }
                }

                yield break;
            }

            if (method.TypeArguments.Length != 0)
            {
                yield return method.TypeArguments[0];

                yield break;
            }

            bool sawDescriptor = false;

            foreach (ArgumentSyntax argument in call.ArgumentList.Arguments)
            {
                ITypeSymbol? type = model.GetTypeInfo(argument.Expression).Type;

                if (type is null)
                {
                    continue;
                }

                if (TypeKey(type) == "System.Type")
                {
                    sawDescriptor = true;

                    yield return TypeOfOperand(argument.Expression, model);

                    continue;
                }

                if (TypeKey(type) != "Microsoft.Extensions.DependencyInjection.ServiceDescriptor")
                {
                    continue;
                }

                sawDescriptor = true;

                yield return DescriptorServiceType(argument.Expression, model);
            }

            if (!sawDescriptor)
            {
                yield return null;
            }
        }

        private static ITypeSymbol? TypeOfOperand(ExpressionSyntax expression, SemanticModel model) =>
            expression is TypeOfExpressionSyntax typeOf
                ? model.GetTypeInfo(typeOf.Type).Type
                : null;

        private static ITypeSymbol? DescriptorServiceType(ExpressionSyntax expression, SemanticModel model)
        {
            if (expression is BaseObjectCreationExpressionSyntax creation
                && model.GetSymbolInfo(creation).Symbol is IMethodSymbol constructor
                && TypeKey(constructor.ContainingType) == "Microsoft.Extensions.DependencyInjection.ServiceDescriptor"
                && creation.ArgumentList?.Arguments.FirstOrDefault()?.Expression is { } first)
            {
                return TypeOfOperand(first, model);
            }

            if (expression is InvocationExpressionSyntax factory
                && model.GetSymbolInfo(factory).Symbol is IMethodSymbol describe
                && TypeKey(describe.ContainingType) == "Microsoft.Extensions.DependencyInjection.ServiceDescriptor")
            {
                if (describe.TypeArguments.Length != 0)
                {
                    return describe.TypeArguments[0];
                }

                return factory.ArgumentList.Arguments.FirstOrDefault()?.Expression is { } typeArgument
                    ? TypeOfOperand(typeArgument, model)
                    : null;
            }

            return null;
        }

        private bool IsDbContextRelevantServiceType(
            ITypeSymbol? serviceType,
            Compilation serviceCompilation,
            INamedTypeSymbol dbContext,
            Compilation consumingCompilation)
        {
            if (serviceType is ITypeParameterSymbol
                {
                    ContainingSymbol: IMethodSymbol { DeclaringSyntaxReferences.Length: > 0 },
                })
            {
                // Bound by the generic helper's own call sites.
                return false;
            }

            if (serviceType is null or ITypeParameterSymbol)
            {
                return true;
            }

            if (serviceType is not INamedTypeSymbol named)
            {
                return false;
            }

            if (named.IsUnboundGenericType
                || SameBoundType(
                    named,
                    serviceCompilation,
                    dbContext,
                    consumingCompilation))
            {
                return true;
            }

            string key = TypeKey(named);

            if (key is "Microsoft.EntityFrameworkCore.DbContextOptions"
                or "System.IServiceProvider"
                or "Microsoft.Extensions.DependencyInjection.IServiceScopeFactory"
                or "Microsoft.Extensions.DependencyInjection.IServiceProviderIsService"
                or "Microsoft.Extensions.DependencyInjection.IKeyedServiceProvider")
            {
                return true;
            }

            if (key == "Microsoft.EntityFrameworkCore.DbContextOptions`1"
                || key.EndsWith(".IDbContextOptionsConfiguration`1", StringComparison.Ordinal))
            {
                return named.TypeArguments is not [ITypeSymbol context]
                    || context is ITypeParameterSymbol
                    || SameBoundType(
                        context,
                        serviceCompilation,
                        dbContext,
                        consumingCompilation);
            }

            // EF may take interceptors from the application's container as well as from the
            // builder, so a registered interceptor is a competing source of authored callbacks.
            return key == "Microsoft.EntityFrameworkCore.Diagnostics.IInterceptor"
                || named.AllInterfaces.Any(static inherited =>
                    TypeKey(inherited) == "Microsoft.EntityFrameworkCore.Diagnostics.IInterceptor");
        }

        // Provider-neutral settings that run no authored code of their own. UseLoggerFactory is
        // deliberately absent: EF hands every event to the factory's authored loggers, a callback
        // lane this analysis does not traverse, so a custom factory refuses the certificate.
        private static readonly HashSet<string> NonProviderOptionsBuilderMembers =
        [
            "ConfigureWarnings",
            "AddInterceptors",
            "UseModel",
            "EnableSensitiveDataLogging",
            "EnableDetailedErrors",
            "UseQueryTrackingBehavior",
            "EnableThreadSafetyChecks",
            "ConfigureLoggingCacheTime",
        ];

        // The only interceptor callbacks an authored interceptor may implement and still leave
        // the certificate standing: they observe a connection EF already owns and cannot hand
        // back a different connection, command or reader.
        private static readonly HashSet<string> ConnectionLifecycleInterceptorCallbacks =
        [
            "ConnectionOpening",
            "ConnectionOpeningAsync",
            "ConnectionOpened",
            "ConnectionOpenedAsync",
            "ConnectionClosing",
            "ConnectionClosingAsync",
            "ConnectionClosed",
            "ConnectionClosedAsync",
            "ConnectionFailed",
            "ConnectionFailedAsync",
            "ConnectionCanceled",
            "ConnectionCanceledAsync",
            "ConnectionDisposing",
            "ConnectionDisposingAsync",
            "ConnectionDisposed",
            "ConnectionDisposedAsync",
        ];

        private static bool IsOptionsBuilderValue(IOperation? operation)
        {
            while (operation is IConversionOperation conversion)
            {
                if (IsOptionsBuilderType(conversion.Operand.Type))
                {
                    return true;
                }

                operation = conversion.Operand;
            }

            return operation is not null && IsOptionsBuilderType(operation.Type);
        }

        private static bool IsOptionsBuilderType(ITypeSymbol? type) =>
            type is not null
            && TypeKey(type) is "Microsoft.EntityFrameworkCore.DbContextOptionsBuilder"
                or "Microsoft.EntityFrameworkCore.DbContextOptionsBuilder`1"
                or "Microsoft.EntityFrameworkCore.Infrastructure.IDbContextOptionsBuilderInfrastructure";

        /// <summary>
        /// The provider a registration selects is final only when every use of the options
        /// builder is the exact SQLite selection, a reviewed provider-neutral setting, or an
        /// authored helper that satisfies the same rule. Any other use, alias or escape
        /// could select another provider or hide a connection.
        /// </summary>
        private bool BuilderScopeCannotChangeProvider(
            SyntaxNode scope,
            SemanticModel model,
            HashSet<GraphMemberIdentity> path,
            BuilderFacts? facts = null,
            bool unconditional = true)
        {
            IOperation? root = model.GetOperation(scope);

            if (root is null)
            {
                return false;
            }

            foreach (IOperation operation in root.DescendantsAndSelf())
            {
                // H5: every builder-valued operation must be consumed by an analysed
                // invocation, a property read, a discard, or a named-method return. Arrays,
                // params, tuples, lambda returns and other carriers are escapes.
                if (IsOptionsBuilderType(operation.Type)
                    && !BuilderValueConsumedInScope(operation))
                {
                    return false;
                }

                switch (operation)
                {
                    case IInvocationOperation invocation
                        when IsOptionsBuilderValue(invocation.Instance)
                            || invocation.Arguments.Any(argument => IsOptionsBuilderValue(argument.Value)):
                    {
                        IMethodSymbol method = invocation.TargetMethod;

                        IMethodSymbol definition = method.ReducedFrom ?? method;

                        if (IsExactSqliteOptionsBuilderCall(method))
                        {
                            // H2: only the connection-string overload selects SQLite's own
                            // connection; a DbConnection argument can be any (derived) connection. The
                            // interceptor and model facts do not depend on which connection it is.
                            if (facts is null && definition.Parameters is not [_, { Type.SpecialType: SpecialType.System_String }, ..])
                            {
                                return false;
                            }

                            break;
                        }

                        if (TypeKey(definition.ContainingType) is
                                "Microsoft.EntityFrameworkCore.DbContextOptionsBuilder"
                                or "Microsoft.EntityFrameworkCore.DbContextOptionsBuilder`1"
                            && NonProviderOptionsBuilderMembers.Contains(definition.Name)
                            && !definition.Locations.Any(static location => location.IsInSource)
                            && AssemblyIdentityMatches(
                                definition.ContainingAssembly.Identity,
                                typeof(Microsoft.EntityFrameworkCore.DbContextOptionsBuilder).Assembly.GetName()))
                        {
                            // The provider certificate admits only interceptors that cannot hand EF another connection,
                            // command or reader. The facts walk collects every interceptor instead, because their
                            // callbacks are traversed at the operations that raise them.
                            if (facts is null
                                && definition.Name == "AddInterceptors"
                                && !InterceptorsCannotReplaceConnection(invocation, model))
                            {
                                return false;
                            }

                            if (facts is not null)
                            {
                                if (definition.Name == "UseModel"
                                    && unconditional
                                    && invocation.Syntax is InvocationExpressionSyntax useModel
                                    && CallExecutesUnconditionallyWithin(scope, useModel)
                                    && invocation.Arguments.LastOrDefault() is { } suppliedModel
                                    && suppliedModel.Value.ConstantValue is not { HasValue: true, Value: null })
                                {
                                    facts.ModelSupplied = true;
                                }
                                else if (definition.Name == "AddInterceptors")
                                {
                                    CollectInterceptors(invocation, model, facts);
                                }
                            }

                            break;
                        }

                        if (Resolve(method, model.Compilation) is { } target)
                        {
                            // H5b: the helper must receive the builder as a builder; an
                            // object/generic parameter hides later uses from this walk.
                            if (invocation.Arguments.Any(argument => IsOptionsBuilderValue(argument.Value)
                                && !IsOptionsBuilderType(argument.Parameter?.Type)))
                            {
                                return false;
                            }

                            GraphMemberIdentity identity = MemberIdentity(target);

                            if (!path.Add(identity))
                            {
                                break;
                            }

                            try
                            {
                                if (!BuilderScopeCannotChangeProvider(
                                    target.Syntax,
                                    target.Model,
                                    path,
                                    facts,
                                    unconditional
                                        && invocation.Syntax is InvocationExpressionSyntax helperCall
                                        && CallExecutesUnconditionallyWithin(scope, helperCall)))
                                {
                                    return false;
                                }
                            }
                            finally
                            {
                                _ = path.Remove(identity);
                            }

                            break;
                        }

                        return false;
                    }

                    case IObjectCreationOperation creation
                        when creation.Arguments.Any(argument => IsOptionsBuilderValue(argument.Value)):
                    case ISimpleAssignmentOperation assignment
                        when IsOptionsBuilderValue(assignment.Value)
                            && assignment.Target is not IDiscardOperation:
                    case IVariableInitializerOperation initializer
                        when IsOptionsBuilderValue(initializer.Value):
                        return false;
                }
            }

            return true;
        }

        // ---- Final-provider closure helpers (judge hardening).

        private static bool InsideNestedFunction(IOperation operation)
        {
            for (IOperation? current = operation.Parent; current is not null; current = current.Parent)
            {
                if (current is IAnonymousFunctionOperation or ILocalFunctionOperation)
                {
                    return true;
                }
            }

            return false;
        }

        private static bool BuilderValueConsumedInScope(IOperation value)
        {
            if (value is IDiscardOperation)
            {
                return true;
            }

            IOperation current = value;

            while (current.Parent is IConversionOperation conversion)
            {
                current = conversion;
            }

            if (!ReferenceEquals(current, value) && IsOptionsBuilderType(current.Type))
            {
                // The outer builder-typed conversion is judged on its own visit.
                return true;
            }

            return current.Parent switch
            {
                null => true,
                IInvocationOperation invocation => ReferenceEquals(invocation.Instance, current),
                IArgumentOperation { Parent: IInvocationOperation } => true,
                IExpressionStatementOperation => true,
                ISimpleAssignmentOperation { Target: IDiscardOperation } assignment =>
                    ReferenceEquals(assignment.Value, current),
                IPropertyReferenceOperation property =>
                    ReferenceEquals(property.Instance, current) && !property.Property.IsIndexer,
                IReturnOperation returned => !InsideNestedFunction(returned),
                _ => false,
            };
        }

        private bool? serviceCollectionValueEscapes;

        /// <summary>
        /// H6: the descriptor scan reads only invocations on IServiceCollection-typed
        /// receivers or parameters. Any other view of the collection (cast, IList parameter,
        /// indexer, conditional access, carrier, lambda return, opaque constructor) or an
        /// authored collection implementation can install a descriptor that scan never sees.
        /// </summary>
        private bool ServiceCollectionValueEscapes()
        {
            if (serviceCollectionValueEscapes is bool cached)
            {
                return cached;
            }

            bool escapes = false;

            foreach ((SyntaxTree tree, SemanticModel model) in semanticModels)
            {
                foreach (SyntaxNode node in tree.GetRoot().DescendantNodes())
                {
                    if (node is BaseTypeDeclarationSyntax declaration
                        && model.GetDeclaredSymbol(declaration) is INamedTypeSymbol declared
                        && declared.AllInterfaces.Any(static candidate => IsServiceCollectionType(candidate)))
                    {
                        escapes = true;

                        break;
                    }

                    if (node is not (IdentifierNameSyntax or MemberAccessExpressionSyntax
                            or InvocationExpressionSyntax or BaseObjectCreationExpressionSyntax
                            or ElementAccessExpressionSyntax or ThisExpressionSyntax)
                        || node.Parent is MemberAccessExpressionSyntax { Name: var name } && ReferenceEquals(name, node)
                        || model.GetOperation(node) is not { } operation
                        || operation.Type is null
                        || !IsServiceCollectionType(operation.Type))
                    {
                        continue;
                    }

                    if (!ServiceCollectionValueConsumed(operation))
                    {
                        escapes = true;

                        break;
                    }
                }

                if (escapes)
                {
                    break;
                }
            }

            serviceCollectionValueEscapes = escapes;

            return escapes;
        }

        private static bool ServiceCollectionValueConsumed(IOperation value)
        {
            IOperation current = value;

            // Conversions and conditional/coalesce branches that keep the collection type are
            // transparent carriers: the combined value is judged where it is consumed.
            while (current.Parent is IConversionOperation
                || current.Parent is IConditionalOperation conditional
                    && !ReferenceEquals(conditional.Condition, current)
                    && conditional.Type is { } conditionalType
                    && IsServiceCollectionType(conditionalType)
                || current.Parent is ICoalesceOperation coalesce
                    && coalesce.Type is { } coalesceType
                    && IsServiceCollectionType(coalesceType))
            {
                current = current.Parent;
            }

            if (current.Type is not null && !IsServiceCollectionType(current.Type))
            {
                // A widened view is only accepted for the exact null guard.
                return current.Parent is IArgumentOperation
                {
                    Parent: IInvocationOperation
                    {
                        TargetMethod: { Name: "ThrowIfNull", ContainingType: { } guardType },
                    },
                }
                    && TypeKey(guardType) == "System.ArgumentNullException"
                    && !guardType.Locations.Any(static location => location.IsInSource);
            }

            return current.Parent switch
            {
                null => true,
                IInvocationOperation invocation => ReferenceEquals(invocation.Instance, current),
                IArgumentOperation { Parameter.Type: { } parameterType, Parent: IInvocationOperation }
                    when IsServiceCollectionType(parameterType) => true,
                IArgumentOperation
                {
                    Parameter.Type: { } parameterType,
                    Parent: IObjectCreationOperation { Constructor: { } constructor },
                } when IsServiceCollectionType(parameterType) =>
                    constructor.Locations.Any(static location => location.IsInSource),
                IExpressionStatementOperation => true,
                ISimpleAssignmentOperation assignment =>
                    ReferenceEquals(assignment.Target, current)
                    || assignment.Target is IDiscardOperation
                    || assignment.Target.Type is { } target && IsServiceCollectionType(target)
                        && (assignment.Target is ILocalReferenceOperation or IParameterReferenceOperation
                            || assignment.Target is IMemberReferenceOperation reference
                                && reference.Member.Locations.Any(static location => location.IsInSource)),
                IVariableInitializerOperation { Parent: IVariableDeclaratorOperation { Symbol.Type: { } local } } =>
                    IsServiceCollectionType(local),
                IPropertyReferenceOperation property =>
                    ReferenceEquals(property.Instance, current) && !property.Property.IsIndexer,
                IReturnOperation returned => !InsideNestedFunction(returned),
                IIsPatternOperation or IIsNullOperation => true,
                _ => false,
            };
        }

        /// <summary>
        /// EF's accessor extensions hand out the context's internal services, which can be used to
        /// replace its connection or provider. The one reviewed read is the logger factory the
        /// connection interceptor uses to report a failed open: a read-only view with no setter.
        /// </summary>
        private static bool IsReviewedAccessorLoggerFactoryRead(IMethodSymbol method)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            return definition.Name == "GetService"
                && method.TypeArguments is [{ } service]
                && IsExactFrameworkType(
                    service,
                    "Microsoft.Extensions.Logging.ILoggerFactory",
                    typeof(Microsoft.Extensions.Logging.ILoggerFactory).Assembly.GetName())
                && !definition.Locations.Any(static location => location.IsInSource)
                && AssemblyIdentityMatches(
                    definition.ContainingAssembly.Identity,
                    typeof(Microsoft.EntityFrameworkCore.Infrastructure.AccessorExtensions).Assembly.GetName());
        }

        /// <summary>
        /// H3: EF lets a caller replace a built context's connection or provider services after
        /// resolution. Every reference to a member that can do so refuses the closed certificate,
        /// whether it is invoked, converted to a delegate, assigned through, or never reached: the
        /// scan reads each simple name's bound symbol, not the shape of the call around it. The
        /// verdict is a property of the analysed compilations alone, so it is computed once per
        /// discovery and shared by every isolated root worker (see <see cref="InventoryFacts"/>).
        /// </summary>
        private bool HasDbContextConnectionReplacement() => inventoryFacts.DbContextConnectionReplacement;

        internal static bool ScanForDbContextConnectionReplacement(IReadOnlyList<CSharpCompilation> compilations, Func<CSharpCompilation, SyntaxTree, SemanticModel> modelOf)
        {
            _ = Interlocked.Increment(ref connectionReplacementScans);

            long started = System.Diagnostics.Stopwatch.GetTimestamp();

            try
            {
                return ScanForDbContextConnectionReplacementCore(compilations, modelOf);
            }
            finally
            {
                _ = Interlocked.Add(ref connectionReplacementScanTicks, System.Diagnostics.Stopwatch.GetElapsedTime(started).Ticks);
            }
        }

        private static bool ScanForDbContextConnectionReplacementCore(IReadOnlyList<CSharpCompilation> compilations, Func<CSharpCompilation, SyntaxTree, SemanticModel> modelOf)
        {
            foreach (CSharpCompilation compilation in compilations)
            {
                foreach (SyntaxTree tree in compilation.SyntaxTrees)
                {
                    // The same trees the graph analyses: its own source, never generated build output.
                    if (!tree.FilePath.StartsWith("src/", StringComparison.Ordinal) || tree.FilePath.Contains("/obj/", StringComparison.Ordinal))
                    {
                        continue;
                    }

                    SemanticModel model = modelOf(compilation, tree);

                    foreach (SimpleNameSyntax name in tree.GetRoot().DescendantNodes().OfType<SimpleNameSyntax>())
                    {
                        SymbolInfo info = model.GetSymbolInfo(name);

                        if (info.Symbol is { } symbol
                                ? IsDbContextConnectionReplacementMember(symbol)
                                : info.CandidateSymbols.Any(IsDbContextConnectionReplacementMember))
                        {
                            return true;
                        }
                    }
                }
            }

            return false;
        }

        private static bool IsDbContextConnectionReplacementMember(ISymbol symbol)
        {
            if (symbol is INamedTypeSymbol)
            {
                return false;
            }

            ISymbol definition = symbol is IMethodSymbol method
                ? method.ReducedFrom ?? method
                : symbol;

            if (definition is IMethodSymbol { Name: "UseServiceProviderFactory" or "ConfigureContainer" })
            {
                return true;
            }

            if (definition.ContainingType is not { } type)
            {
                return false;
            }

            string key = TypeKey(type);

            return key == "Microsoft.EntityFrameworkCore.RelationalDatabaseFacadeExtensions"
                    && definition.Name is "SetDbConnection" or "SetConnectionString"
                || key == "Microsoft.EntityFrameworkCore.Infrastructure.AccessorExtensions"
                    && !(symbol is IMethodSymbol read && IsReviewedAccessorLoggerFactoryRead(read))
                || key == "Microsoft.EntityFrameworkCore.Infrastructure.IInfrastructure`1"
                    && definition.Name == "Instance"
                || key == "Microsoft.EntityFrameworkCore.Storage.IRelationalConnection"
                || type.AllInterfaces.Any(static inherited =>
                    TypeKey(inherited) == "Microsoft.EntityFrameworkCore.Storage.IRelationalConnection");
        }

        /// <summary>
        /// Interface mapping names the base class's virtual member when a derived interceptor
        /// only overrides it, so an authored callback is the implementation itself or any
        /// authored override of it in the interceptor's own hierarchy.
        /// </summary>
        private static bool HasAuthoredCallback(
            INamedTypeSymbol created,
            IMethodSymbol implementation)
        {
            if (implementation.Locations.Any(static location => location.IsInSource))
            {
                return true;
            }

            for (INamedTypeSymbol? current = created;
                current is not null && current.SpecialType != SpecialType.System_Object;
                current = current.BaseType)
            {
                foreach (IMethodSymbol candidate in current.GetMembers(implementation.Name).OfType<IMethodSymbol>())
                {
                    if (!candidate.IsOverride
                        || !candidate.Locations.Any(static location => location.IsInSource))
                    {
                        continue;
                    }

                    for (IMethodSymbol? overridden = candidate.OverriddenMethod;
                        overridden is not null;
                        overridden = overridden.OverriddenMethod)
                    {
                        if (SymbolEqualityComparer.Default.Equals(
                            overridden.OriginalDefinition,
                            implementation.OriginalDefinition))
                        {
                            return true;
                        }
                    }
                }
            }

            return false;
        }

        private bool InterceptorsCannotReplaceConnection(
            IInvocationOperation invocation,
            SemanticModel model)
        {
            foreach (IOperation creation in invocation.Descendants().Where(static operation =>
                operation is IObjectCreationOperation))
            {
                if (((IObjectCreationOperation)creation).Type is not INamedTypeSymbol created
                    || AuthoredCompilationIdentity(created, model.Compilation) is null)
                {
                    return false;
                }

                for (INamedTypeSymbol? current = created;
                    current is not null && current.SpecialType != SpecialType.System_Object;
                    current = current.BaseType)
                {
                    if (current.GetMembers().OfType<IMethodSymbol>().Any(static method =>
                        method.IsOverride
                        && method.Name is "ConnectionCreating" or "ConnectionCreatingAsync"
                            or "ConnectionCreated" or "ConnectionCreatedAsync"))
                    {
                        return false;
                    }
                }

                // H4: an implicit or explicit interface implementation replaces the
                // connection just as an override does; IsOverride is false for both.
                if (model.Compilation.GetTypeByMetadataName(
                        "Microsoft.EntityFrameworkCore.Diagnostics.IDbConnectionInterceptor") is not
                    INamedTypeSymbol connectionInterceptor)
                {
                    return false;
                }

                foreach (IMethodSymbol slot in connectionInterceptor.GetMembers().OfType<IMethodSymbol>()
                    .Where(static slot => slot.Name is "ConnectionCreating" or "ConnectionCreatingAsync"
                        or "ConnectionCreated" or "ConnectionCreatedAsync"))
                {
                    if (created.FindImplementationForInterfaceMember(slot) is { } implementation
                        && !SymbolEqualityComparer.Default.Equals(implementation, slot)
                        && implementation.Locations.Any(static location => location.IsInSource))
                    {
                        return false;
                    }
                }

                // Every other authored interceptor callback runs code the certificate cannot read:
                // only the connection-lifecycle callbacks of IDbConnectionInterceptor are reviewed.
                // Command, transaction, SaveChanges, materialization, query and identity-resolution
                // interceptors, and any callback that could return a replacement object, refuse.
                if (model.Compilation.GetTypeByMetadataName(
                        "Microsoft.EntityFrameworkCore.Diagnostics.IInterceptor") is not
                    INamedTypeSymbol interceptorRoot)
                {
                    return false;
                }

                foreach (INamedTypeSymbol contract in created.AllInterfaces.Where(candidate =>
                    SymbolEqualityComparer.Default.Equals(candidate, interceptorRoot)
                    || candidate.AllInterfaces.Any(inherited => SymbolEqualityComparer.Default.Equals(inherited, interceptorRoot))))
                {
                    bool reviewedContract = TypeKey(contract) == "Microsoft.EntityFrameworkCore.Diagnostics.IDbConnectionInterceptor"
                        && AssemblyIdentityMatches(
                            contract.ContainingAssembly.Identity,
                            typeof(Microsoft.EntityFrameworkCore.Diagnostics.IDbConnectionInterceptor).Assembly.GetName());

                    foreach (IMethodSymbol slot in contract.GetMembers().OfType<IMethodSymbol>())
                    {
                        if (created.FindImplementationForInterfaceMember(slot) is IMethodSymbol implementation
                            && HasAuthoredCallback(created, implementation)
                            && !(reviewedContract && ConnectionLifecycleInterceptorCallbacks.Contains(slot.Name)))
                        {
                            return false;
                        }
                    }
                }
            }

            // Only inline interceptor allocations are reviewed; a stored or returned
            // interceptor value is an unknown type.
            return invocation.Arguments
                .SelectMany(static argument => argument.Value is IArrayCreationOperation array
                    ? array.Initializer?.ElementValues ?? []
                    : [argument.Value])
                .All(static value =>
                {
                    while (value is IConversionOperation conversion)
                    {
                        value = conversion.Operand;
                    }

                    return value is IObjectCreationOperation or IArrayCreationOperation;
                });
        }

        private AuthoredMember? AuthoredOnConfiguring(
            INamedTypeSymbol type,
            Compilation compilation)
        {
            for (INamedTypeSymbol? current = type;
                current is not null
                && TypeKey(current) != "Microsoft.EntityFrameworkCore.DbContext";
                current = current.BaseType)
            {
                foreach (IMethodSymbol method in current.GetMembers("OnConfiguring").OfType<IMethodSymbol>())
                {
                    if (method.IsOverride
                        && Resolve(method, compilation) is { } authored)
                    {
                        return authored;
                    }
                }
            }

            return null;
        }

        // The interfaces the framework context implements: a member read through one of them is
        // the context's own member, whichever spelling reaches it.
        private static readonly HashSet<string> DbContextInterfaceKeys = typeof(Microsoft.EntityFrameworkCore.DbContext)
            .GetInterfaces()
            .Select(static contract => contract.Namespace + "." + contract.Name)
            .ToHashSet(StringComparer.Ordinal);

        private static (ExpressionSyntax? Receiver, bool ImplicitThis) DbContextUseReceiver(SyntaxNode node)
        {
            SyntaxNode name = node is InvocationExpressionSyntax call
                ? call.Expression
                : node;

            switch (name)
            {
                case MemberAccessExpressionSyntax access:
                    return (access.Expression, false);

                case MemberBindingExpressionSyntax binding:
                    return (ConditionalAccessReceiver(binding), false);

                case IdentifierNameSyntax or GenericNameSyntax:
                    return name.Parent switch
                    {
                        MemberBindingExpressionSyntax binding => (ConditionalAccessReceiver(binding), false),
                        MemberAccessExpressionSyntax access when ReferenceEquals(access.Name, name) =>
                            (access.Expression, false),
                        _ => (null, true),
                    };

                default:
                    return (null, false);
            }
        }

        private static ExpressionSyntax? ConditionalAccessReceiver(SyntaxNode binding) =>
            binding.Ancestors()
                .OfType<ConditionalAccessExpressionSyntax>()
                .FirstOrDefault(access => access.WhenNotNull.Span.Contains(binding.Span))
                ?.Expression;

        private bool HasClosedDbContextOnConfiguring(INamedTypeSymbol dbContext)
        {
            for (INamedTypeSymbol? current = dbContext;
                current is not null
                && TypeKey(current) != "Microsoft.EntityFrameworkCore.DbContext";
                current = current.BaseType)
            {
                foreach (IMethodSymbol method in current.GetMembers("OnConfiguring").OfType<IMethodSymbol>())
                {
                    if (!method.IsOverride)
                    {
                        continue;
                    }

                    if (method.DeclaringSyntaxReferences.Length != 1
                        || method.DeclaringSyntaxReferences[0].GetSyntax() is not MethodDeclarationSyntax
                        {
                            Body: { } body,
                        } declaration
                        || method.Parameters is not [IParameterSymbol builder]
                        || !StartsWithConfiguredGuard(body, builder, declaration.SyntaxTree))
                    {
                        return false;
                    }
                }
            }

            return true;
        }

        private bool StartsWithConfiguredGuard(
            BlockSyntax body,
            IParameterSymbol builder,
            SyntaxTree tree)
        {
            if (!semanticModels.TryGetValue(tree, out SemanticModel? model))
            {
                return false;
            }

            foreach (StatementSyntax statement in body.Statements)
            {
                if (statement is ExpressionStatementSyntax
                    {
                        Expression: AssignmentExpressionSyntax
                        {
                            Left: IdentifierNameSyntax { Identifier.ValueText: "_" },
                            Right: IdentifierNameSyntax or ThisExpressionSyntax
                        },
                    })
                {
                    continue;
                }

                return statement is IfStatementSyntax
                    {
                        Else: null,
                        Condition: MemberAccessExpressionSyntax
                        {
                            Name.Identifier.ValueText: "IsConfigured",
                            Expression: IdentifierNameSyntax guarded,
                        },
                        Statement: ReturnStatementSyntax { Expression: null }
                            or BlockSyntax { Statements: [ReturnStatementSyntax { Expression: null }] },
                    }
                    && SymbolEqualityComparer.Default.Equals(
                        model.GetSymbolInfo(guarded).Symbol,
                        builder);
            }

            return false;
        }

        private static bool IsExactEfDbContext(INamedTypeSymbol type)
        {
            for (INamedTypeSymbol? current = type.BaseType;
                current is not null;
                current = current.BaseType)
            {
                if (TypeKey(current) == "Microsoft.EntityFrameworkCore.DbContext"
                    && AssemblyIdentityMatches(
                        current.ContainingAssembly.Identity,
                        typeof(Microsoft.EntityFrameworkCore.DbContext)
                            .Assembly.GetName())
                    && !current.Locations.Any(static location =>
                        location.IsInSource))
                {
                    return true;
                }
            }

            return false;
        }

        private bool HasExactSqliteDbContextRegistration(
            INamedTypeSymbol dbContext,
            Compilation consumingCompilation)
        {
            BoundTypeIdentity identity = TypeIdentity(
                dbContext,
                consumingCompilation);

            if (sqliteDbContextRegistrations.TryGetValue(
                    identity,
                    out bool cached))
            {
                return cached;
            }

            ResolvedRegistration[] registrations = SqliteDbContextRegistrations(
                dbContext,
                consumingCompilation);

            bool result = registrations.Length != 0
                && registrations.All(candidate =>
                    RegistrationConfiguresExactSqliteProvider(
                        candidate.Call,
                        candidate.Model));

            sqliteDbContextRegistrations.Add(identity, result);

            return result;
        }

        private readonly Dictionary<BoundTypeIdentity, ResolvedRegistration[]> dbContextRegistrationCache = [];

        private ResolvedRegistration[] SqliteDbContextRegistrations(
            INamedTypeSymbol dbContext,
            Compilation consumingCompilation)
        {
            BoundTypeIdentity cacheKey = TypeIdentity(dbContext, consumingCompilation);

            if (dbContextRegistrationCache.TryGetValue(cacheKey, out ResolvedRegistration[]? cachedRegistrations))
            {
                return cachedRegistrations;
            }

            return dbContextRegistrationCache[cacheKey] = SelectDbContextRegistrations(dbContext, consumingCompilation);
        }

        private ResolvedRegistration[] SelectDbContextRegistrations(
            INamedTypeSymbol dbContext,
            Compilation consumingCompilation)
        {
            BoundContractIdentity registrationKey = new(
                dbContext.ContainingAssembly.Identity,
                TypeKey(dbContext));

            return (sqliteDbContextRegistrationCalls.TryGetValue(
                        registrationKey,
                        out List<ResolvedRegistration>? candidates)
                    ? candidates
                    : [])
                    .Where(candidate =>
                    {
                        registrationCandidateInspections++;

                        IMethodSymbol method = candidate.Method;

                        if (method.Name is not
                                ("AddDbContext" or "AddDbContextPool")
                            || !IsExactFrameworkMethod(
                                method,
                                "Microsoft.Extensions.DependencyInjection.EntityFrameworkServiceCollectionExtensions",
                                method.Name,
                                "Microsoft.EntityFrameworkCore"))
                        {
                            return false;
                        }

                        return method.TypeArguments.Any(argument =>
                            SameBoundType(
                                argument,
                                candidate.Model.Compilation,
                                dbContext,
                                consumingCompilation));
                    })
                    .ToArray();
        }

        /// <summary>
        /// The registration configures the <c>DbContextOptions&lt;T&gt;</c> the container injects, so a
        /// container-built context is configured by it only when the one constructor the container can
        /// use hands exactly that parameter, unchanged, to EF's <c>DbContext(DbContextOptions)</c>
        /// constructor, directly or through authored constructors that each forward their own
        /// parameter. A context that passes other options to its base class, or whose constructor the
        /// container may not select, reads a provider its registration never chose.
        /// </summary>
        private bool ContextForwardsInjectedOptions(INamedTypeSymbol dbContext)
        {
            if (dbContext.InstanceConstructors.Where(static constructor => !constructor.IsStatic).ToArray() is not [IMethodSymbol only]
                || only.DeclaredAccessibility != Accessibility.Public)
            {
                return false;
            }

            return only.Parameters
                    .Where(parameter => IsDbContextOptions(parameter.Type, dbContext))
                    .ToArray() is [IParameterSymbol options]
                && ConstructorForwardsOptions(only, options, 0);
        }

        private static bool IsDbContextOptions(ITypeSymbol type, INamedTypeSymbol? generic)
        {
            if (type is not INamedTypeSymbol named
                || !AssemblyIdentityMatches(
                    named.ContainingAssembly.Identity,
                    typeof(Microsoft.EntityFrameworkCore.DbContextOptions).Assembly.GetName())
                || named.Locations.Any(static location => location.IsInSource))
            {
                return false;
            }

            return generic is null
                ? TypeKey(named) is "Microsoft.EntityFrameworkCore.DbContextOptions"
                    or "Microsoft.EntityFrameworkCore.DbContextOptions`1"
                : TypeKey(named) == "Microsoft.EntityFrameworkCore.DbContextOptions`1"
                    && named.TypeArguments is [ITypeSymbol argument]
                    && SymbolEqualityComparer.Default.Equals(argument, generic);
        }

        private bool ConstructorForwardsOptions(
            IMethodSymbol constructor,
            IParameterSymbol options,
            int depth)
        {
            if (depth > 8
                || constructor.DeclaringSyntaxReferences is not [{ } reference]
                || !ConstructorParameterNeverWritten(options)
                || !semanticModels.TryGetValue(reference.SyntaxTree, out SemanticModel? model))
            {
                return false;
            }

            SyntaxNode? initializer = reference.GetSyntax() switch
            {
                ConstructorDeclarationSyntax declaration => declaration.Initializer,
                TypeDeclarationSyntax { ParameterList: not null } declaration =>
                    declaration.BaseList?.Types.OfType<PrimaryConstructorBaseTypeSyntax>().SingleOrDefault(),
                ParameterListSyntax { Parent: TypeDeclarationSyntax declaration } =>
                    declaration.BaseList?.Types.OfType<PrimaryConstructorBaseTypeSyntax>().SingleOrDefault(),
                _ => null,
            };

            // An absent initializer is the implicit parameterless base call: nothing is forwarded.
            ArgumentListSyntax? arguments = initializer switch
            {
                ConstructorInitializerSyntax constructorInitializer => constructorInitializer.ArgumentList,
                PrimaryConstructorBaseTypeSyntax primary => primary.ArgumentList,
                _ => null,
            };

            if (arguments is null
                || model.GetSymbolInfo(initializer!).Symbol is not IMethodSymbol target
                || target.MethodKind != MethodKind.Constructor)
            {
                return false;
            }

            IParameterSymbol? forwarded = null;

            for (int index = 0; index < arguments.Arguments.Count; index++)
            {
                ArgumentSyntax argument = arguments.Arguments[index];

                if (StripTransparentExpression(argument.Expression) is not IdentifierNameSyntax name
                    || !SymbolEqualityComparer.Default.Equals(model.GetSymbolInfo(name).Symbol, options))
                {
                    continue;
                }

                IParameterSymbol? receiving = argument.NameColon is { } named
                    ? target.Parameters.FirstOrDefault(parameter => parameter.Name == named.Name.Identifier.ValueText)
                    : index < target.Parameters.Length ? target.Parameters[index] : null;

                if (receiving is null || receiving.IsParams || forwarded is not null)
                {
                    return false;
                }

                forwarded = receiving;
            }

            if (forwarded is null)
            {
                return false;
            }

            INamedTypeSymbol targetType = target.ContainingType;

            if (TypeKey(targetType) == "Microsoft.EntityFrameworkCore.DbContext"
                && targetType.Locations.All(static location => !location.IsInSource)
                && AssemblyIdentityMatches(
                    targetType.ContainingAssembly.Identity,
                    typeof(Microsoft.EntityFrameworkCore.DbContext).Assembly.GetName()))
            {
                return forwarded.Ordinal == 0
                    && target.Parameters.Length == 1
                    && IsDbContextOptions(forwarded.Type, null)
                    && TypeKey(forwarded.Type) == "Microsoft.EntityFrameworkCore.DbContextOptions";
            }

            return IsDbContextOptions(forwarded.Type, null)
                && target.DeclaringSyntaxReferences.Length != 0
                && IsExactEfDbContext(targetType)
                && ConstructorForwardsOptions(target, forwarded, depth + 1);
        }

        private readonly Dictionary<BoundTypeIdentity, bool>
            closedSqliteDbContextConfigurations = [];

        /// <summary>
        /// The selected registrations alone configure a container-built context's final options:
        /// no builder escape or provider change, no competing descriptor, and no authored
        /// OnConfiguring that can run past the provider-complete guard.
        /// </summary>
        private bool HasClosedSqliteDbContextConfiguration(
            INamedTypeSymbol dbContext,
            Compilation consumingCompilation)
        {
            BoundTypeIdentity identity = TypeIdentity(
                dbContext,
                consumingCompilation);

            if (closedSqliteDbContextConfigurations.TryGetValue(
                    identity,
                    out bool cached))
            {
                return cached;
            }

            ResolvedRegistration[] registrations = SqliteDbContextRegistrations(
                dbContext,
                consumingCompilation);

            bool result = registrations.Length != 0
                && registrations.All(candidate =>
                    RegistrationBuilderCannotChangeProvider(
                        candidate.Call,
                        candidate.Model))
                && !HasCompetingDbContextServiceDescriptor(
                    dbContext,
                    consumingCompilation)
                && HasClosedDbContextOnConfiguring(dbContext)
                && ContextForwardsInjectedOptions(dbContext)
                && !HasDbContextConnectionReplacement()
                && !ServiceCollectionValueEscapes();

            closedSqliteDbContextConfigurations.Add(identity, result);

            return result;
        }

        private bool RegistrationBuilderCannotChangeProvider(
            InvocationExpressionSyntax registration,
            SemanticModel model) =>
            registration.ArgumentList.Arguments
                .SelectMany(static argument => argument.Expression
                    .DescendantNodesAndSelf()
                    .OfType<AnonymousFunctionExpressionSyntax>())
                .ToArray() is [AnonymousFunctionExpressionSyntax callback]
            && BuilderScopeCannotChangeProvider(
                callback,
                model,
                []);

        private bool RegistrationConfiguresExactSqliteProvider(
            InvocationExpressionSyntax registration,
            SemanticModel model)
        {
            AnonymousFunctionExpressionSyntax[] callbacks = registration
                .ArgumentList.Arguments
                .SelectMany(static argument => argument.Expression
                    .DescendantNodesAndSelf()
                    .OfType<AnonymousFunctionExpressionSyntax>())
                .ToArray();

            if (callbacks is not [AnonymousFunctionExpressionSyntax callback])
            {
                return false;
            }

            IParameterSymbol[] options = callback switch
            {
                ParenthesizedLambdaExpressionSyntax parenthesized =>
                    parenthesized.ParameterList.Parameters
                        .Select(parameter =>
                            model.GetDeclaredSymbol(parameter))
                        .OfType<IParameterSymbol>()
                        .Where(IsDbContextOptionsBuilder)
                        .ToArray(),
                SimpleLambdaExpressionSyntax simple =>
                    model.GetDeclaredSymbol(simple.Parameter) is
                        IParameterSymbol parameter
                        && IsDbContextOptionsBuilder(parameter)
                            ? [parameter]
                            : [],
                AnonymousMethodExpressionSyntax anonymous =>
                    anonymous.ParameterList?.Parameters
                        .Select(parameter =>
                            model.GetDeclaredSymbol(parameter))
                        .OfType<IParameterSymbol>()
                        .Where(IsDbContextOptionsBuilder)
                        .ToArray()
                    ?? [],
                _ => [],
            };

            return options is [IParameterSymbol builder]
                && ConfiguresExactSqliteProvider(
                    callback,
                    model,
                    builder,
                    []);
        }

        private bool ConfiguresExactSqliteProvider(
            SyntaxNode scope,
            SemanticModel model,
            IParameterSymbol builder,
            HashSet<(GraphMemberIdentity Member, int Parameter)> path)
        {
            foreach (InvocationExpressionSyntax call in scope
                .DescendantNodesAndSelf(node => node == scope
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<InvocationExpressionSyntax>())
            {
                if (!CallExecutesUnconditionallyWithin(scope, call)
                    || model.GetSymbolInfo(call).Symbol is not
                        IMethodSymbol method
                    || model.GetOperation(call) is not
                        IInvocationOperation operation)
                {
                    continue;
                }

                if (IsExactSqliteOptionsBuilderCall(method)
                    && ExactInvocationReceiverOrFirstArgument(
                        operation) is { } providerBuilder
                    && SymbolEqualityComparer.Default.Equals(
                        model.GetSymbolInfo(
                            StripTransparentExpression(providerBuilder)).Symbol,
                        builder))
                {
                    return true;
                }

                if (Resolve(method, model.Compilation) is not { } target)
                {
                    continue;
                }

                foreach (IArgumentOperation argument in operation.Arguments)
                {
                    if (argument.Parameter is not { } parameter
                        || parameter.Ordinal >= target.Symbol.Parameters.Length
                        || argument.Value.Syntax is not
                            ExpressionSyntax argumentExpression
                        || !SymbolEqualityComparer.Default.Equals(
                            model.GetSymbolInfo(
                                StripTransparentExpression(
                                    argumentExpression)).Symbol,
                            builder))
                    {
                        continue;
                    }

                    IParameterSymbol targetParameter =
                        target.Symbol.Parameters[parameter.Ordinal];

                    var identity = (
                        MemberIdentity(target),
                        targetParameter.Ordinal);

                    if (!path.Add(identity))
                    {
                        continue;
                    }

                    try
                    {
                        if (ConfiguresExactSqliteProvider(
                            target.Syntax,
                            target.Model,
                            targetParameter,
                            path))
                        {
                            return true;
                        }
                    }
                    finally
                    {
                        _ = path.Remove(identity);
                    }
                }
            }

            return false;
        }

        private static bool IsDbContextOptionsBuilder(
            IParameterSymbol parameter) =>
            TypeKey(parameter.Type) is
                "Microsoft.EntityFrameworkCore.DbContextOptionsBuilder"
                    or "Microsoft.EntityFrameworkCore.DbContextOptionsBuilder`1";

        private static bool IsExactSqliteOptionsBuilderCall(
            IMethodSymbol method)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            return definition.Name == "UseSqlite"
                && TypeKey(definition.ContainingType)
                    == "Microsoft.EntityFrameworkCore.SqliteDbContextOptionsBuilderExtensions"
                && AssemblyIdentityMatches(
                    definition.ContainingAssembly.Identity,
                    typeof(Microsoft.EntityFrameworkCore.SqliteDbContextOptionsBuilderExtensions)
                        .Assembly.GetName())
                && !definition.Locations.Any(static location =>
                    location.IsInSource);
        }

        private static ExpressionSyntax? ExactInvocationReceiverOrFirstArgument(
            IInvocationOperation operation) =>
            operation.Instance?.Syntax as ExpressionSyntax
            ?? operation.Arguments
                .OrderBy(static argument => argument.Parameter?.Ordinal
                    ?? int.MaxValue)
                .Select(static argument => argument.Value.Syntax)
                .OfType<ExpressionSyntax>()
                .FirstOrDefault();

        private static bool CallExecutesUnconditionallyWithin(
            SyntaxNode scope,
            InvocationExpressionSyntax call) =>
            !call.Ancestors()
                .TakeWhile(ancestor => ancestor != scope)
                .Any(static ancestor => ancestor is
                    IfStatementSyntax
                        or ConditionalExpressionSyntax
                        or SwitchExpressionSyntax
                        or SwitchStatementSyntax
                        or ForStatementSyntax
                        or ForEachStatementSyntax
                        or WhileStatementSyntax
                        or DoStatementSyntax
                        or CatchClauseSyntax);

        private CleanupProvenance ExactTrustedMetadataProvenance(
            AuthoredMember member,
            INamedTypeSymbol type) =>
            new(
                [new(type, TypeIdentity(type, member.Model.Compilation))],
                true,
                false);

        private static bool IsExactFrameworkConfigureAwait(
            IMethodSymbol method)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            string containingType = TypeKey(definition.ContainingType);

            string? returnType = containingType switch
            {
                "System.Threading.Tasks.Task" =>
                    "System.Runtime.CompilerServices.ConfiguredTaskAwaitable",
                "System.Threading.Tasks.Task`1" =>
                    "System.Runtime.CompilerServices.ConfiguredTaskAwaitable`1",
                "System.Threading.Tasks.ValueTask" =>
                    "System.Runtime.CompilerServices.ConfiguredValueTaskAwaitable",
                "System.Threading.Tasks.ValueTask`1" =>
                    "System.Runtime.CompilerServices.ConfiguredValueTaskAwaitable`1",
                _ => null,
            };

            return returnType is not null
                && !definition.IsStatic
                && IsExactFrameworkMethod(
                    definition,
                    containingType,
                    "ConfigureAwait",
                    "System.Private.CoreLib")
                && HasExactParameterTypes(definition, "System.Boolean")
                && IsExactFrameworkType(
                    definition.ReturnType,
                    returnType,
                    typeof(IAsyncDisposable).Assembly.GetName());
        }

        private static bool IsExactManifestResourceStreamFactory(
            IMethodSymbol method)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            return !definition.IsStatic
                && definition.Name == "GetManifestResourceStream"
                && IsExactFrameworkType(
                    definition.ContainingType,
                    "System.Reflection.Assembly",
                    typeof(Assembly).Assembly.GetName())
                && !definition.Locations.Any(static location =>
                    location.IsInSource)
                && IsExactFrameworkType(
                    definition.ReturnType,
                    "System.IO.Stream",
                    typeof(System.IO.Stream).Assembly.GetName())
                && HasExactParameterTypes(definition, "System.String");
        }

        private static bool IsExactSqliteBackupFactory(
            IMethodSymbol method)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            AssemblyName trustedAssembly =
                typeof(SQLitePCL.raw).Assembly.GetName();

            return definition.IsStatic
                && definition.Name == "sqlite3_backup_init"
                && IsExactFrameworkType(
                    definition.ContainingType,
                    "SQLitePCL.raw",
                    trustedAssembly)
                && !definition.Locations.Any(static location =>
                    location.IsInSource)
                && IsExactFrameworkType(
                    definition.ReturnType,
                    "SQLitePCL.sqlite3_backup",
                    trustedAssembly)
                && HasExactSqliteBackupParameters(
                    definition,
                    trustedAssembly);
        }

        private static bool IsExactEcdsaFactory(IMethodSymbol method)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            return definition.IsStatic
                && definition.Name == "Create"
                && IsExactFrameworkType(
                    definition.ContainingType,
                    "System.Security.Cryptography.ECDsa",
                    typeof(ECDsa).Assembly.GetName())
                && !definition.Locations.Any(static location =>
                    location.IsInSource)
                && IsExactFrameworkType(
                    definition.ReturnType,
                    "System.Security.Cryptography.ECDsa",
                    typeof(ECDsa).Assembly.GetName())
                && HasExactParameterTypes(definition);
        }

        private static bool IsExactJsonDocumentFactory(IMethodSymbol method)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            if (!definition.IsStatic
                || definition.Name != "Parse"
                || !IsExactFrameworkType(
                    definition.ContainingType,
                    "System.Text.Json.JsonDocument",
                    typeof(JsonDocument).Assembly.GetName())
                || definition.Locations.Any(static location =>
                    location.IsInSource)
                || !IsExactFrameworkType(
                    definition.ReturnType,
                    "System.Text.Json.JsonDocument",
                    typeof(JsonDocument).Assembly.GetName()))
            {
                return false;
            }

            return HasExactParameterTypes(
                definition,
                "System.String",
                "System.Text.Json.JsonDocumentOptions");
        }

        private static bool HasExactSqliteBackupParameters(
            IMethodSymbol method,
            AssemblyName trustedAssembly)
        {
            if (method.Parameters is not
                [IParameterSymbol destination,
                    IParameterSymbol destinationName,
                    IParameterSymbol source,
                    IParameterSymbol sourceName]
                || method.Parameters.Any(static parameter =>
                    parameter.RefKind != RefKind.None)
                || !IsExactFrameworkType(
                    destination.Type,
                    "SQLitePCL.sqlite3",
                    trustedAssembly)
                || !IsExactFrameworkType(
                    source.Type,
                    "SQLitePCL.sqlite3",
                    trustedAssembly)
                || !IsExactFrameworkType(
                    destinationName.Type,
                    "System.String",
                    typeof(string).Assembly.GetName())
                || !IsExactFrameworkType(
                    sourceName.Type,
                    "System.String",
                    typeof(string).Assembly.GetName()))
            {
                return false;
            }

            return true;
        }

        private static bool HasExactParameterTypes(
            IMethodSymbol method,
            params string[] types) =>
            method.Parameters.Length == types.Length
            && method.Parameters.Select(static parameter =>
                    parameter.RefKind == RefKind.None
                        ? TypeKey(parameter.Type)
                        : string.Empty)
                .SequenceEqual(types, StringComparer.Ordinal);

        private static bool HasExactSqliteReaderParameters(
            IMethodSymbol method) =>
            HasExactParameterTypes(method)
            || HasExactParameterTypes(
                method,
                "System.Threading.CancellationToken")
            || HasExactParameterTypes(
                method,
                "System.Data.CommandBehavior")
            || HasExactParameterTypes(
                method,
                "System.Data.CommandBehavior",
                "System.Threading.CancellationToken");

        private static bool HasExactSqliteTransactionParameters(
            IMethodSymbol method) =>
            HasExactParameterTypes(method)
            || HasExactParameterTypes(
                method,
                "System.Threading.CancellationToken")
            || HasExactParameterTypes(
                method,
                "System.Data.IsolationLevel",
                "System.Threading.CancellationToken");

        private EffectiveCleanupResolution ResolveEffectiveCleanup(
            AuthoredMember member,
            ITypeSymbol staticType,
            ExpressionSyntax? resource,
            string name,
            IMethodSymbol? explicitCleanupSlot = null)
        {
            bool configuredAsync = false;

            if (resource is not null
                && TryConfiguredAsyncDisposableReceiver(
                    member,
                    resource) is { } unconfigured)
            {
                configuredAsync = true;

                resource = unconfigured;

                staticType = member.Model.GetTypeInfo(unconfigured).Type
                    ?? staticType;
            }

            CleanupProvenance provenance = resource is null
                ? new([], false, false)
                : CleanupProvenanceOf(
                    member,
                    resource,
                    new CleanupProvenanceContext());

            CleanupTypeCandidate[] candidates = provenance.Candidates
                .DistinctBy(static candidate => candidate.Identity)
                .ToArray();

            bool completeExactCandidateValueFlow = false;

            if (!provenance.Complete
                && resource is not null
                && candidates is [CleanupTypeCandidate flowCandidate]
                && flowCandidate.Type is INamedTypeSymbol
                {
                    TypeKind: TypeKind.Class,
                    IsSealed: true,
                }
                && IsAuthoredCleanupSymbol(
                    flowCandidate.Type,
                    member.Model.Compilation))
            {
                CleanupValueFlow candidateFlow = CleanupValueFlowOf(
                    member,
                    resource,
                    new CleanupProvenanceContext());

                completeExactCandidateValueFlow = candidateFlow is
                    {
                        Complete: true,
                        Values.Count: > 0,
                    }
                    && candidateFlow.Values.All(source =>
                    {
                        ExpressionSyntax exactSource = ExactNonThrowingValue(
                            source.Expression);

                        return source.Caller.Model.GetTypeInfo(exactSource).Type
                            is { } sourceType
                            && SameBoundType(
                                sourceType,
                                source.Caller.Model.Compilation,
                                flowCandidate.Type,
                                member.Model.Compilation);
                    });
            }

            CleanupTypeCandidate[] exactCandidates = provenance.Complete
                    || completeExactCandidateValueFlow
                ? candidates
                : [];

            if (exactCandidates.Length == 0
                && resource is not null
                && !IsSemanticallyEmptyCleanupValue(
                    member.Model,
                    resource)
                && staticType is INamedTypeSymbol closed
                && (closed.TypeKind == TypeKind.Struct
                    || closed is
                    {
                        TypeKind: TypeKind.Class,
                        IsSealed: true,
                    })
                && IsAuthoredCleanupSymbol(
                    closed,
                    member.Model.Compilation))
            {
                CleanupProvenance staticProvenance = ExactCleanupProvenance(
                    member,
                    closed);

                if (staticProvenance.Complete
                    && staticProvenance.Candidates is
                        [CleanupTypeCandidate staticCandidate])
                {
                    exactCandidates = [staticCandidate];
                }
            }

            List<AuthoredMember> cleanupTargets = [];

            List<ExternalCleanupResolution> externalEffects = [];

            bool exactCandidatesResolved = exactCandidates.Length != 0
                && !(staticType is INamedTypeSymbol
                {
                    TypeKind: TypeKind.Class,
                    IsSealed: false,
                } openStaticType
                    && !IsTrustedCleanupDispatchBase(openStaticType)
                    && exactCandidates.Any(candidate => !SameBoundType(
                        candidate.Type,
                        member.Model.Compilation,
                        openStaticType,
                        member.Model.Compilation)));

            foreach (CleanupTypeCandidate candidate in exactCandidates)
            {
                IMethodSymbol[] selectedCleanup = SelectEffectiveCleanupMembers(
                        candidate.Type,
                        explicitCleanupSlot?.ContainingType ?? staticType,
                        name,
                        configuredAsync);

                if (selectedCleanup is not [IMethodSymbol cleanup])
                {
                    exactCandidatesResolved = false;

                    continue;
                }

                if (Resolve(cleanup, member.Model.Compilation) is
                    { } authoredCleanup)
                {
                    cleanupTargets.AddRange(BindEffectiveCleanupTargets(
                        member,
                        resource,
                        candidate.Type,
                        authoredCleanup,
                        exactCandidates));

                    continue;
                }

                bool externalAccepted = TryResolveExternalCleanup(
                        member,
                        resource,
                        candidate.Type,
                        cleanup,
                        out ExternalCleanupResolution? external);

                if (!externalAccepted)
                {
                    exactCandidatesResolved = false;

                    continue;
                }

                if (external is { } effect)
                {
                    externalEffects.Add(effect);
                }
            }

            AuthoredMember? closedInterfaceTarget = exactCandidates.Length == 0
                ? ResolveClosedAuthoredInterfaceCleanup(
                    staticType,
                    name,
                    member.Model.Compilation)
                : null;

            AuthoredMember? convergentPropertyTarget = exactCandidates.Length == 0
                    && closedInterfaceTarget is null
                ? ResolveConvergentAuthoredRecordPropertyCleanup(
                    member,
                    staticType,
                    resource,
                    name,
                    provenance)
                : null;

            bool reviewedEnumeratorCleanup = exactCandidates.Length == 0
                && closedInterfaceTarget is null
                && convergentPropertyTarget is null
                && resource is not null
                && IsReviewedEnumeratorCleanup(
                    member,
                    staticType,
                    resource,
                    name);

            bool reviewedInMemoryStreamCleanup = exactCandidates.Length == 0
                && TypeKey(staticType) == "System.IO.Stream"
                && resource is not null
                && HasReviewedInMemoryStreamProvenance(
                    resource,
                    member.Model,
                    new HashSet<ISymbol>(SymbolEqualityComparer.Default),
                    member);

            bool dynamicStreamRequiresExactTarget = exactCandidates.Length == 0
                && TypeKey(staticType) == "System.IO.Stream"
                && !reviewedInMemoryStreamCleanup;

            bool exactExternalDispatch = exactCandidates.Length == 0
                && (staticType is INamedTypeSymbol
                {
                    TypeKind: TypeKind.Struct,
                }
                || staticType is INamedTypeSymbol
                {
                    TypeKind: TypeKind.Class,
                    IsAbstract: false,
                    IsSealed: true,
                }
                || SqliteSealedByUse && IsSqliteSealedFamilyClass(staticType));

            IMethodSymbol? externalCleanup = exactCandidates.Length == 0
                && closedInterfaceTarget is null
                && convergentPropertyTarget is null
                && !reviewedEnumeratorCleanup
                && !reviewedInMemoryStreamCleanup
                && !dynamicStreamRequiresExactTarget
                && exactExternalDispatch
                    ? CompilerSelectedExternalCleanup(
                        staticType,
                        name,
                        member.Model.Compilation,
                        exactRuntimeType: true)
                    : null;

            bool staticExternalResolved = false;

            if (externalCleanup is not null
                && TryResolveExternalCleanup(
                    member,
                    resource,
                    staticType,
                    externalCleanup,
                    out ExternalCleanupResolution? staticExternal))
            {
                staticExternalResolved = true;

                if (staticExternal is { } effect)
                {
                    externalEffects.Add(effect);
                }
            }

            ExternalCleanupResolution? trustedFactoryEffect = null;

            bool trustedFactoryResolved = exactCandidates.Length == 0
                && closedInterfaceTarget is null
                && convergentPropertyTarget is null
                && !reviewedEnumeratorCleanup
                && !reviewedInMemoryStreamCleanup
                && resource is not null
                && TryResolveTrustedFactoryCleanup(
                    member,
                    resource,
                    staticType,
                    name,
                    out trustedFactoryEffect);

            if (trustedFactoryEffect is { } trustedEffect)
            {
                externalEffects.Add(trustedEffect);
            }

            if (closedInterfaceTarget is not null)
            {
                cleanupTargets.Add(closedInterfaceTarget);
            }

            if (convergentPropertyTarget is not null)
            {
                cleanupTargets.Add(convergentPropertyTarget);
            }

            AuthoredMember[] distinctTargets = cleanupTargets
                .DistinctBy(candidate => (
                    MemberIdentity(candidate),
                    EvaluationEnvironmentIdentity(candidate).Identity))
                .ToArray();

            ExternalCleanupResolution[] distinctExternalEffects =
                externalEffects.Distinct().ToArray();

            if (distinctTargets
                    .Select(MemberIdentity)
                    .Distinct()
                    .Skip(1)
                    .Any())
            {
                exactCandidatesResolved = false;
            }

            if (exactCandidates.Length != 0
                && !exactCandidatesResolved)
            {
                distinctTargets = [];

                distinctExternalEffects = [];
            }

            bool unknownCleanupContractCanExecute = resource is not null
                && !IsSemanticallyEmptyCleanupValue(member.Model, resource)
                && staticType is INamedTypeSymbol cleanupContract
                && IsCleanupContract(cleanupContract, name);

            bool cleanupCanExecute = resource is null
                || !provenance.Complete
                || candidates.Length != 0
                || dynamicStreamRequiresExactTarget
                || unknownCleanupContractCanExecute;

            bool resolved = exactCandidates.Length != 0
                ? exactCandidatesResolved
                : distinctTargets.Length != 0
                    || distinctExternalEffects.Length != 0
                    || reviewedEnumeratorCleanup
                    || reviewedInMemoryStreamCleanup
                    || staticExternalResolved
                    || trustedFactoryResolved;

            bool mustResolve = !resolved
                && cleanupCanExecute;

            return new(
                exactCandidates is [CleanupTypeCandidate exact]
                    ? exact.Type
                    : closedInterfaceTarget?.Symbol.ContainingType
                        ?? convergentPropertyTarget?.Symbol.ContainingType,
                distinctTargets,
                distinctExternalEffects,
                mustResolve,
                provenance.HasAuthoredSource);
        }

        private AuthoredMember[] BindEffectiveCleanupTargets(
            AuthoredMember member,
            ExpressionSyntax? resource,
            ITypeSymbol exactType,
            AuthoredMember target,
            IReadOnlyList<CleanupTypeCandidate> candidateFamily)
        {
            if (resource is null
                || exactType is not INamedTypeSymbol expectedType
                || !ReceiverTargetMayCarryCleanupState(target))
            {
                return [target];
            }

            CleanupValueFlow flow = CleanupValueFlowOf(
                member,
                resource,
                new CleanupProvenanceContext());

            if (!flow.Complete)
            {
                return [target];
            }

            Compilation expectedCompilation = expectedType
                .DeclaringSyntaxReferences.FirstOrDefault() is
            { SyntaxTree: { } expectedTree }
                && semanticModels.TryGetValue(
                    expectedTree,
                    out SemanticModel? expectedModel)
                    ? expectedModel.Compilation
                    : member.Model.Compilation;

            if (flow.Values.Count == 0
                || flow.Values.Any(value =>
                {
                    ExpressionSyntax expression = ExactNonThrowingValue(
                        value.Expression);

                    ITypeSymbol? sourceType = value.Caller.Model
                        .GetTypeInfo(expression).Type;

                    return sourceType is null
                        || !candidateFamily.Any(candidate => SameBoundType(
                            sourceType,
                            value.Caller.Model.Compilation,
                            candidate.Type,
                            member.Model.Compilation));
                }))
            {
                return [target];
            }

            BoundValueSource[] sources = flow.Values.Where(value =>
                value.Caller.Model.GetTypeInfo(
                    ExactNonThrowingValue(value.Expression)).Type is { } sourceType
                && SameBoundType(
                    sourceType,
                    value.Caller.Model.Compilation,
                    expectedType,
                    expectedCompilation)).ToArray();

            if (sources.Length == 0)
            {
                return [target];
            }

            List<AuthoredMember> targets = [];

            foreach (BoundValueSource source in sources)
            {
                ExpressionSyntax exactSource = ExactNonThrowingValue(
                    source.Expression);

                AuthoredMember? receiver = ResolveConstructedReceiverContext(
                    source.Caller,
                    exactSource,
                    expectedType,
                    new HashSet<(GraphMemberIdentity Member, int Start, int Length)>());

                if (receiver is null)
                {
                    return [target];
                }

                receiver = BindDemandedReceiverReadonlyFieldContext(
                    receiver,
                    target);

                AuthoredMember selected = MergeValueContext(target, receiver);

                selected = BindExactConstructedReceiverPropertyContext(selected, target, source, new CleanupProvenanceContext());

                EvaluationEnvironmentFingerprint environment =
                    EvaluationEnvironmentIdentity(selected);

                if (!environment.Complete
                    || environment.ContainsBackreference)
                {
                    return [target];
                }

                targets.Add(selected);
            }

            return targets.ToArray();
        }

        private bool TryResolveExternalCleanup(
            AuthoredMember member,
            ExpressionSyntax? resource,
            ITypeSymbol exactType,
            IMethodSymbol cleanup,
            out ExternalCleanupResolution? external)
        {
            external = null;

            if (cleanup.Locations.Any(static location => location.IsInSource)
                || AuthoredCompilationIdentity(
                    cleanup,
                    member.Model.Compilation) is not null
                || compilationIdentities.Keys
                    .OfType<CSharpCompilation>()
                    .Any(compilation => compilation.Assembly.Identity.Equals(
                        cleanup.ContainingAssembly.Identity)))
            {
                return false;
            }

            string callee = Normalize(cleanup);

            if (TypeKey(exactType) == "System.IO.StreamReader"
                && cleanup.Name == "Dispose")
            {
                if (resource is not null
                    && (HasExactNonOwningStreamReaderProvenance(
                            resource,
                            member.Model,
                            new HashSet<ISymbol>(
                                SymbolEqualityComparer.Default),
                            member)
                        || HasReviewedInMemoryStreamReaderProvenance(
                            resource,
                            member.Model,
                            new HashSet<ISymbol>(
                                SymbolEqualityComparer.Default),
                            member)))
                {
                    return true;
                }

                external = new(
                    "System.IO.StreamReader.Dispose",
                    HostedProducerSiteKind.FileSystemEffect);

                return true;
            }

            if (TypeKey(exactType) == "System.IO.FileStream"
                && cleanup.Name is "Dispose" or "DisposeAsync")
            {
                external = new(
                    "System.IO.FileStream." + cleanup.Name,
                    resource is not null
                        && HasExactReadOnlyFileStreamCleanupProvenance(
                            member,
                            resource)
                            ? HostedProducerSiteKind.FileSystemRead
                            : HostedProducerSiteKind.FileSystemEffect);

                return true;
            }

            if (IsReviewedExactMechanicalCleanup(exactType, cleanup))
            {
                return true;
            }

            HostedProducerSiteKind? kind = Classify(
                cleanup,
                callee,
                resource ?? member.Syntax,
                member);

            if (kind is { } classified)
            {
                external = new(callee, classified);

                return true;
            }

            return IsReviewedEffectFreeExternalMember(
                cleanup,
                resource,
                member.Model);
        }

        private static bool IsReviewedExactMechanicalCleanup(
            ITypeSymbol exactType,
            IMethodSymbol cleanup)
        {
            if (cleanup.Name is not ("Dispose" or "DisposeAsync")
                || cleanup.Parameters.Length != 0)
            {
                return false;
            }

            AssemblyName? trusted = TypeKey(exactType) switch
            {
                "System.IO.MemoryStream" =>
                    typeof(MemoryStream).Assembly.GetName(),
                "System.Diagnostics.Process" =>
                    typeof(System.Diagnostics.Process).Assembly.GetName(),
                "System.Security.Principal.WindowsIdentity" =>
                    typeof(System.Security.Principal.WindowsIdentity)
                        .Assembly.GetName(),
                "System.Text.Json.JsonDocument" =>
                    typeof(JsonDocument).Assembly.GetName(),
                "System.Threading.CancellationTokenRegistration" =>
                    typeof(CancellationTokenRegistration).Assembly.GetName(),
                "System.Threading.CancellationTokenSource" =>
                    typeof(CancellationTokenSource).Assembly.GetName(),
                "System.Threading.Mutex" =>
                    typeof(Mutex).Assembly.GetName(),
                "System.Threading.PeriodicTimer" =>
                    typeof(PeriodicTimer).Assembly.GetName(),
                _ => null,
            };

            return trusted is not null
                && FrameworkAssemblyIdentityMatches(
                    exactType.ContainingAssembly.Identity,
                    trusted)
                && !exactType.Locations.Any(static location =>
                    location.IsInSource);
        }

        private bool TryResolveTrustedFactoryCleanup(
            AuthoredMember member,
            ExpressionSyntax resource,
            ITypeSymbol staticType,
            string name,
            out ExternalCleanupResolution? external)
        {
            external = null;

            if (name == "Dispose"
                && (IsExactFrameworkType(staticType, "System.IDisposable", typeof(IDisposable).Assembly.GetName())
                    || IsExactEmbeddingGeneratorContract(staticType)))
            {
                ExpressionSyntax adapter = StripTransparentExpression(resource);

                if (adapter is BinaryExpressionSyntax tryCast
                    && tryCast.IsKind(SyntaxKind.AsExpression)
                    && member.Model.GetOperation(tryCast) is IConversionOperation { IsTryCast: true, OperatorMethod: null })
                {
                    // A built-in as conversion can only select this same instance or null.
                    // It cannot invoke a user conversion before the conditional cleanup.
                    adapter = tryCast.Left;
                }

                CleanupValueFlow sources = CleanupValueFlowOf(member, adapter, new CleanupProvenanceContext());

                if (sources.Complete
                    && sources.Values.Count != 0
                    && sources.Values.All(source => StripTransparentExpression(source.Expression) is InvocationExpressionSyntax factory
                        && source.Caller.Model.GetSymbolInfo(factory).Symbol is IMethodSymbol factoryMethod
                        && (IsExactChatSdkAdapterFactory(factoryMethod)
                            || IsExactEmbeddingSdkAdapterFactory(factoryMethod))))
                {
                    // Each exact pinned chat/embedding factory returns its internal sealed SDK
                    // adapter with ret-only explicit IDisposable cleanup. Every complete value
                    // source must be such a factory; arbitrary generators and replacements
                    // gain no cleanup proof. SDK arguments and physical sends still traverse.
                    return true;
                }
            }

            if (name == "Dispose"
                && IsExactFrameworkType(
                    staticType,
                    "System.IDisposable",
                    typeof(IDisposable).Assembly.GetName())
                && TryResolveDefaultOptionsMonitorSubscriptionCleanup(
                    member,
                    resource))
            {
                // OptionsMonitor<T>.OnChange returns its internal sealed
                // ChangeTrackerDisposable. The pinned framework implementation
                // removes only its own listener from the monitor event.
                return true;
            }

            if (name == "DisposeAsync"
                && (IsExactFrameworkType(staticType, "ModelContextProtocol.Client.McpClient",
                        typeof(ModelContextProtocol.Client.McpClient).Assembly.GetName())
                    || IsExactFrameworkType(staticType, "ModelContextProtocol.McpSession",
                        typeof(ModelContextProtocol.McpSession).Assembly.GetName())))
            {
                CleanupValueFlow sources = CleanupValueFlowOf(member, resource, new CleanupProvenanceContext());

                if (sources.Complete
                    && sources.Values.Count != 0
                    && sources.Values.All(source => source.Expression is InvocationExpressionSyntax factory
                        && source.Caller.Model.GetSymbolInfo(factory).Symbol is IMethodSymbol factoryMethod
                        && IsExactSdkClientFactory(factoryMethod)))
                {
                    external = new("ModelContextProtocol.McpSession.DisposeAsync", HostedProducerSiteKind.ProviderCall);

                    return true;
                }

                return false;
            }

            resource = StripTransparentExpression(resource);

            if (resource is AwaitExpressionSyntax awaited)
            {
                resource = StripTransparentExpression(awaited.Expression);

                if (resource is InvocationExpressionSyntax configured
                    && member.Model.GetSymbolInfo(configured).Symbol is
                        IMethodSymbol configuredMethod
                    && IsExactFrameworkConfigureAwait(configuredMethod)
                    && configured.Expression is MemberAccessExpressionSyntax
                    {
                        Expression: { } unconfigured,
                    })
                {
                    resource = StripTransparentExpression(unconfigured);
                }
            }

            if (resource is not InvocationExpressionSyntax call
                || member.Model.GetSymbolInfo(call).Symbol is not
                    IMethodSymbol method)
            {
                return false;
            }

            IMethodSymbol definition = method.ReducedFrom ?? method;

            if (definition.Locations.Any(static location => location.IsInSource))
            {
                return false;
            }

            string callee = Normalize(definition);

            if (name == "Dispose"
                && TypeKey(staticType)
                    == "Microsoft.Extensions.DependencyInjection.IServiceScope"
                && callee is
                    "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions.CreateScope"
                        or "Microsoft.Extensions.DependencyInjection.IServiceScopeFactory.CreateScope"
                && FrameworkAssemblyIdentityMatches(
                    definition.ContainingAssembly.Identity,
                    typeof(Microsoft.Extensions.DependencyInjection.IServiceScope)
                        .Assembly.GetName()))
            {
                return true;
            }

            if (name == "Dispose"
                && TypeKey(staticType) == "SQLitePCL.sqlite3_backup"
                && IsExactSqliteBackupFactory(definition))
            {
                return true;
            }

            if (name == "DisposeAsync"
                && TypeKey(staticType)
                    == "Microsoft.EntityFrameworkCore.Storage.IDbContextTransaction"
                && definition.Name == "BeginTransactionAsync"
                && TypeKey(definition.ReturnType)
                    == "System.Threading.Tasks.Task`1"
                && definition.ReturnType is INamedTypeSymbol
                {
                    TypeArguments: [ITypeSymbol transaction],
                }
                && TypeKey(transaction)
                    == "Microsoft.EntityFrameworkCore.Storage.IDbContextTransaction"
                && ((TypeKey(definition.ContainingType)
                            == "Microsoft.EntityFrameworkCore.Infrastructure.DatabaseFacade"
                        && AssemblyIdentityMatches(
                            definition.ContainingAssembly.Identity,
                            typeof(Microsoft.EntityFrameworkCore.Infrastructure.DatabaseFacade)
                                .Assembly.GetName()))
                    || (TypeKey(definition.ContainingType)
                            == "Microsoft.EntityFrameworkCore.RelationalDatabaseFacadeExtensions"
                        && AssemblyIdentityMatches(
                            definition.ContainingAssembly.Identity,
                            typeof(Microsoft.EntityFrameworkCore.RelationalDatabaseFacadeExtensions)
                                .Assembly.GetName())))
                && !definition.Locations.Any(static location =>
                    location.IsInSource))
            {
                return true;
            }

            return name == "Dispose"
                && ((TypeKey(staticType)
                            == "System.Security.Cryptography.ECDsa"
                        && IsExactEcdsaFactory(definition))
                    || (TypeKey(staticType)
                            == "System.Text.Json.JsonDocument"
                        && IsExactJsonDocumentFactory(definition)));
        }

        private bool TryResolveDefaultOptionsMonitorSubscriptionCleanup(
            AuthoredMember member,
            ExpressionSyntax resource)
        {
            CleanupValueFlow sources = CleanupValueFlowOf(
                member,
                resource,
                new CleanupProvenanceContext());

            BoundValueSource[] subscriptions = sources.Values
                .Where(source => !IsSemanticallyEmptyCleanupValue(
                    source.Caller.Model,
                    source.Expression))
                .ToArray();

            return sources.Complete
                && subscriptions.Length != 0
                && subscriptions.All(IsExactDefaultOptionsMonitorSubscription);
        }

        private bool IsExactDefaultOptionsMonitorSubscription(
            BoundValueSource source)
        {
            ExpressionSyntax expression = StripTransparentExpression(
                source.Expression);

            if (expression is not InvocationExpressionSyntax call
                || source.Caller.Model.GetSymbolInfo(call).Symbol is not
                    IMethodSymbol method
                || !IsExactFrameworkMethod(
                    method,
                    "Microsoft.Extensions.Options.IOptionsMonitor`1",
                    "OnChange",
                    "Microsoft.Extensions.Options")
                || method.ContainingType is not INamedTypeSymbol contract
                || method.ReturnType is not { } returnType
                || !IsExactFrameworkType(
                    returnType,
                    "System.IDisposable",
                    typeof(IDisposable).Assembly.GetName())
                || AdmissionReceiver(source.Caller, call) is not
                { } receiver
                || !IsExactDiBoundCleanupReceiver(
                    source.Caller,
                    receiver,
                    contract,
                    [])
                || !HasExactUnreplacedDefaultOptionsMonitorRegistration(
                    source.Caller,
                    contract,
                    source.Caller.Model.Compilation))
            {
                return false;
            }

            return true;
        }

        private bool HasExactUnreplacedDefaultOptionsMonitorRegistration(
            AuthoredMember member,
            INamedTypeSymbol contract,
            Compilation consumingCompilation)
        {
            if (!IsApplicableOptionsMonitorContract(
                    contract,
                    consumingCompilation,
                    contract,
                    consumingCompilation))
            {
                return false;
            }

            BoundContractIdentity ownerKey = new(
                member.Symbol.ContainingAssembly.Identity,
                TypeKey(member.Symbol.ContainingType));

            ResolvedRegistration[] ownerRegistrations =
                (diActivationRegistrations.TryGetValue(
                        ownerKey,
                        out List<ResolvedRegistration>? registrations)
                    ? registrations
                    : [])
                .DistinctBy(
                    static registration => registration.Call,
                    ReferenceEqualityComparer.Instance)
                .Where(registration =>
                    IsExactRootFactoryRegistrationMethod(
                        registration.Method))
                .ToArray();

            bool configured = invocations.Any(candidate =>
                candidate.Model.GetSymbolInfo(candidate.Call).Symbol is
                    IMethodSymbol candidateMethod
                && IsExactFrameworkMethod(
                    candidateMethod,
                    "Microsoft.Extensions.DependencyInjection.OptionsServiceCollectionExtensions",
                    "Configure",
                    "Microsoft.Extensions.Options")
                && candidateMethod.TypeArguments is
                    [ITypeSymbol configuredOptions]
                && contract.TypeArguments is [ITypeSymbol requiredOptions]
                && SameBoundType(
                    configuredOptions,
                    candidate.Model.Compilation,
                    requiredOptions,
                    consumingCompilation)
                && ownerRegistrations.Any(registration =>
                    SameExactServiceCollectionReceiver(
                        candidate.Call,
                        candidate.Model,
                        registration.Call,
                        registration.Model)
                    && HasExactClosedOptionsComposition(
                        candidate.Call,
                        registration.Call)));

            if (!configured)
            {
                return false;
            }

            bool replacement = invocations.Any(candidate =>
                candidate.Model.GetSymbolInfo(candidate.Call).Symbol is
                    IMethodSymbol candidateMethod
                && IsApplicableOptionsMonitorRegistrationMutation(
                    candidate.Call,
                    candidate.Model,
                    candidateMethod,
                    contract,
                    consumingCompilation));

            bool descriptorConstruction = objectCreations.Any(candidate =>
                candidate.Model.GetSymbolInfo(candidate.Creation).Symbol is
                    IMethodSymbol constructor
                && IsExactFrameworkType(
                    constructor.ContainingType,
                    "Microsoft.Extensions.DependencyInjection.ServiceDescriptor",
                    typeof(Microsoft.Extensions.DependencyInjection.ServiceDescriptor)
                        .Assembly.GetName())
                && candidate.Creation.DescendantNodesAndSelf()
                    .OfType<TypeOfExpressionSyntax>()
                    .Any(typeOf => candidate.Model.GetTypeInfo(typeOf.Type).Type is
                    { } registered
                        && IsApplicableOptionsMonitorContract(
                            registered,
                            candidate.Model.Compilation,
                            contract,
                            consumingCompilation)));

            return !replacement && !descriptorConstruction;
        }

        private static bool SameExactServiceCollectionReceiver(
            InvocationExpressionSyntax left,
            SemanticModel leftModel,
            InvocationExpressionSyntax right,
            SemanticModel rightModel)
        {
            static ExpressionSyntax? Receiver(
                InvocationExpressionSyntax call) =>
                call.Expression is MemberAccessExpressionSyntax access
                    ? access.Expression
                    : null;

            return Receiver(left) is { } leftReceiver
                && Receiver(right) is { } rightReceiver
                && leftModel.GetSymbolInfo(leftReceiver).Symbol is { } leftSymbol
                && rightModel.GetSymbolInfo(rightReceiver).Symbol is { } rightSymbol
                && SymbolEqualityComparer.Default.Equals(
                    leftSymbol,
                    rightSymbol);
        }

        private bool HasExactClosedOptionsComposition(
            InvocationExpressionSyntax configuration,
            InvocationExpressionSyntax ownerRegistration)
        {
            IReadOnlyDictionary<InvocationExpressionSyntax, RecoveryCompositionKind>
                compositions = RecoveryRegistrationCompositions();

            RecoveryCompositionKind common =
                compositions.GetValueOrDefault(configuration)
                & compositions.GetValueOrDefault(ownerRegistration)
                & recoveryRegistrationMustExecuteCompositions
                    .GetValueOrDefault(configuration)
                & recoveryRegistrationMustExecuteCompositions
                    .GetValueOrDefault(ownerRegistration);

            return common != RecoveryCompositionKind.None
                && (invalidRecoveryComposition & common)
                    == RecoveryCompositionKind.None;
        }

        private bool IsApplicableOptionsMonitorRegistrationMutation(
            InvocationExpressionSyntax call,
            SemanticModel model,
            IMethodSymbol method,
            INamedTypeSymbol contract,
            Compilation consumingCompilation) =>
            IsApplicableServiceRegistrationMutation(
                call,
                model,
                method,
                (candidate, candidateCompilation) =>
                    IsApplicableOptionsMonitorContract(
                        candidate,
                        candidateCompilation,
                        contract,
                        consumingCompilation));

        private bool IsApplicableServiceRegistrationMutation(
            InvocationExpressionSyntax call,
            SemanticModel model,
            IMethodSymbol method,
            Func<ITypeSymbol, Compilation, bool> isApplicableContract)
        {
            bool serviceRegistration = method.Name is
                    "AddSingleton" or "AddScoped" or "AddTransient"
                && IsExactFrameworkMethod(
                    method,
                    "Microsoft.Extensions.DependencyInjection.ServiceCollectionServiceExtensions",
                    method.Name,
                    "Microsoft.Extensions.DependencyInjection.Abstractions");

            bool descriptorMutation = method.Name is
                    "TryAddSingleton" or "TryAddScoped" or "TryAddTransient"
                        or "TryAdd" or "TryAddEnumerable" or "Replace"
                        or "RemoveAll"
                && IsExactFrameworkMethod(
                    method,
                    "Microsoft.Extensions.DependencyInjection.Extensions.ServiceCollectionDescriptorExtensions",
                    method.Name,
                    "Microsoft.Extensions.DependencyInjection.Abstractions");

            bool descriptorFactory = method.Name is
                    "Singleton" or "Scoped" or "Transient" or "Describe"
                && IsExactFrameworkMethod(
                    method,
                    "Microsoft.Extensions.DependencyInjection.ServiceDescriptor",
                    method.Name,
                    "Microsoft.Extensions.DependencyInjection.Abstractions");

            bool descriptorCollectionMutation =
                IsExactServiceDescriptorCollectionMutation(method);

            if (!serviceRegistration
                && !descriptorMutation
                && !descriptorFactory
                && !descriptorCollectionMutation)
            {
                return false;
            }

            ITypeSymbol[] resolvedMutationTypes = [];

            if (model.GetEnclosingSymbol(call.SpanStart) is
                    IMethodSymbol enclosing
                && Resolve(enclosing, model.Compilation) is { } member)
            {
                (bool complete, ITypeSymbol[] types) =
                    RecoveryCollectionMutationTypes(
                        member,
                        call,
                        method,
                        new HashSet<ISymbol>(SymbolEqualityComparer.Default));

                if (complete)
                {
                    resolvedMutationTypes = types;
                }
            }

            return method.TypeArguments.Concat(resolvedMutationTypes).Any(type =>
                    isApplicableContract(type, model.Compilation))
                || call.DescendantNodesAndSelf()
                    .OfType<TypeOfExpressionSyntax>()
                    .Any(typeOf => model.GetTypeInfo(typeOf.Type).Type is
                    { } registered
                        && isApplicableContract(
                            registered,
                            model.Compilation));
        }

        private bool IsApplicableOptionsMonitorContract(
            ITypeSymbol candidate,
            Compilation candidateCompilation,
            INamedTypeSymbol contract,
            Compilation consumingCompilation)
        {
            if (candidate is not INamedTypeSymbol named
                || !IsExactFrameworkType(
                    named.OriginalDefinition,
                    "Microsoft.Extensions.Options.IOptionsMonitor`1",
                    Assembly.Load(new AssemblyName("Microsoft.Extensions.Options"))
                        .GetName()))
            {
                return false;
            }

            if (named.IsUnboundGenericType)
            {
                return true;
            }

            return named.TypeArguments is [ITypeSymbol candidateOptions]
                && contract.TypeArguments is [ITypeSymbol requiredOptions]
                && SameBoundType(
                    candidateOptions,
                    candidateCompilation,
                    requiredOptions,
                    consumingCompilation);
        }

        private static ExpressionSyntax? TryConfiguredAsyncDisposableReceiver(
            AuthoredMember member,
            ExpressionSyntax resource)
        {
            resource = StripTransparentExpression(resource);

            return resource is InvocationExpressionSyntax configured
                && member.Model.GetSymbolInfo(configured).Symbol
                    is IMethodSymbol method
                && IsExactFrameworkMethod(
                    method,
                    "System.Threading.Tasks.TaskAsyncEnumerableExtensions",
                    "ConfigureAwait",
                    "System.Private.CoreLib")
                && configured.Expression is MemberAccessExpressionSyntax
                {
                    Expression: { } unconfigured,
                }
                    ? StripTransparentExpression(unconfigured)
                    : null;
        }

        private bool IsReviewedEnumeratorCleanup(
            AuthoredMember member,
            ITypeSymbol staticType,
            ExpressionSyntax resource,
            string name)
        {
            if (staticType is not INamedTypeSymbol enumerator
                || !((name == "Dispose"
                        && TypeKey(enumerator) is
                            "System.Collections.Generic.IEnumerator`1"
                                or "System.Collections.IEnumerator")
                    || (name == "DisposeAsync"
                        && TypeKey(enumerator)
                            == "System.Collections.Generic.IAsyncEnumerator`1"))
                || enumerator.Locations.Any(static location =>
                    location.IsInSource)
                || !FrameworkAssemblyIdentityMatches(
                    enumerator.ContainingAssembly.Identity,
                    (name == "DisposeAsync"
                        ? typeof(IAsyncDisposable)
                        : typeof(System.Collections.IEnumerator))
                        .Assembly.GetName()))
            {
                return false;
            }

            return HasReviewedEnumeratorProvenance(
                resource,
                member.Model,
                new HashSet<ISymbol>(SymbolEqualityComparer.Default),
                member);
        }

        private CleanupProvenance CleanupProvenanceOf(
            AuthoredMember member,
            ExpressionSyntax expression,
            CleanupProvenanceContext context)
        {
            CleanupCacheAnalysisCounter analysis = CleanupCacheCounter(member);

            analysis.ProvenanceRequests++;

            expression = StripTransparentExpression(expression);

            CleanupProvenanceIdentity identity = CleanupIdentity(
                member,
                expression);

            CleanupEnvironmentCacheIdentity? cacheIdentity =
                CompleteCleanupEnvironmentIdentity(member, identity);

            if (!context.CollectionIndexerProof
                && !context.ClosedSqliteProvider
                && cacheIdentity is { } stableIdentity
                && completeCleanupProvenance.TryGetValue(
                    stableIdentity,
                    out CleanupProvenance? stable))
            {
                analysis.ProvenanceStableHits++;

                return stable;
            }

            if (cacheIdentity is { } completeIdentity
                && context.Cache.TryGetValue(
                    completeIdentity,
                    out CleanupProvenance? cached))
            {
                return cached;
            }

            if (context.RemainingWork-- <= 0)
            {
                return new([], false, true);
            }

            bool entered = cacheIdentity is { } completeActiveIdentity
                ? context.CompleteActive.Add(completeActiveIdentity)
                : context.Active.Add(identity);

            if (!entered)
            {
                return new([], false, true);
            }

            analysis.ProvenanceBuilds++;

            CleanupProvenance result;

            try
            {
                result = CleanupProvenanceCore(
                    member,
                    expression,
                    context);
            }
            finally
            {
                if (cacheIdentity is { } completeRemovalIdentity)
                {
                    _ = context.CompleteActive.Remove(completeRemovalIdentity);
                }
                else
                {
                    _ = context.Active.Remove(identity);
                }
            }

            if (cacheIdentity is { } completeCacheIdentity)
            {
                context.Cache[completeCacheIdentity] = result;

                if (result.Complete && !context.CollectionIndexerProof && !context.ClosedSqliteProvider)
                {
                    completeCleanupProvenance.TryAdd(
                        completeCacheIdentity,
                        result);
                }
            }

            return result;
        }

        private CleanupCacheAnalysisCounter CleanupCacheCounter(
            AuthoredMember member)
        {
            string metricMember = MethodKey(member.Symbol);

            if (!cleanupCacheAnalysis.TryGetValue(
                    metricMember,
                    out CleanupCacheAnalysisCounter? analysis))
            {
                analysis = new();

                cleanupCacheAnalysis.Add(metricMember, analysis);
            }

            return analysis;
        }

        private CleanupEnvironmentCacheIdentity?
            CompleteCleanupEnvironmentIdentity(
                AuthoredMember member,
                CleanupProvenanceIdentity expression)
        {
            EvaluationEnvironmentFingerprint environment =
                EvaluationEnvironmentIdentity(member);

            return environment.Complete
                    && !environment.ContainsBackreference
                ? new(expression, environment.Identity)
                : null;
        }

        private CleanupProvenanceIdentity CleanupIdentity(
            AuthoredMember member,
            ExpressionSyntax expression) =>
            new(
                MemberIdentity(member),
                CleanupBindingIdentity(member),
                expression.SpanStart,
                expression.Span.Length);

        private string CleanupBindingIdentity(AuthoredMember member)
        {
            IEnumerable<string> values = member.ValueBindings?
                .OrderBy(pair => BindingSymbolIdentity(
                    pair.Key,
                    member), StringComparer.Ordinal)
                .Select(pair =>
                {
                    GraphMemberIdentity caller = MemberIdentity(
                        pair.Value.Caller);

                    return BindingSymbolIdentity(pair.Key, member)
                        + "="
                        + caller.Compilation.ToString(CultureInfo.InvariantCulture)
                        + ":"
                        + caller.Tree.ToString(CultureInfo.InvariantCulture)
                        + ":"
                        + caller.Method
                        + ":"
                        + pair.Value.Expression.SpanStart.ToString(
                            CultureInfo.InvariantCulture)
                        + ":"
                        + pair.Value.Expression.Span.Length.ToString(
                            CultureInfo.InvariantCulture)
                        + ":"
                        + ConcreteBindingIdentity(pair.Value.Caller);
                })
                ?? [];

            return ConcreteBindingIdentity(member)
                + "|"
                + string.Join(";", values);
        }

        private CleanupProvenance CleanupProvenanceCore(
            AuthoredMember member,
            ExpressionSyntax expression,
            CleanupProvenanceContext context)
        {
            if (expression is AwaitExpressionSyntax awaited)
            {
                ExpressionSyntax awaitedSource = StripTransparentExpression(
                    awaited.Expression);

                if (awaitedSource is InvocationExpressionSyntax configured
                    && member.Model.GetSymbolInfo(configured).Symbol
                        is IMethodSymbol configuredMethod
                    && IsExactFrameworkConfigureAwait(configuredMethod)
                    && configured.Expression
                        is MemberAccessExpressionSyntax
                    {
                        Expression: { } unconfigured,
                    })
                {
                    awaitedSource = unconfigured;
                }

                return CleanupProvenanceOf(
                    member,
                    awaitedSource,
                    context);
            }

            if (expression is ConditionalExpressionSyntax conditional)
            {
                return MergeCleanupProvenance([
                    ConditionalCleanupProvenance(
                        member,
                        conditional.WhenTrue,
                        context),
                    ConditionalCleanupProvenance(
                        member,
                        conditional.WhenFalse,
                        context),
                ]);
            }

            if (expression is BinaryExpressionSyntax coalescing
                && coalescing.IsKind(SyntaxKind.CoalesceExpression))
            {
                return MergeCleanupProvenance([
                    CleanupProvenanceOf(
                        member,
                        coalescing.Left,
                        context),
                    CleanupProvenanceOf(
                        member,
                        coalescing.Right,
                        context),
                ]);
            }

            if (expression is SwitchExpressionSyntax selection)
            {
                return MergeCleanupProvenance(selection.Arms.Select(arm =>
                    CleanupProvenanceOf(
                        member,
                        arm.Expression,
                        context)));
            }

            if (expression is BaseObjectCreationExpressionSyntax
                && member.Model.GetTypeInfo(expression).Type is { } created)
            {
                return ExactCleanupProvenance(member, created);
            }

            if (IsSemanticallyEmptyCleanupValue(
                    member.Model,
                    expression))
            {
                return new([], true, false);
            }

            if ((expression is DefaultExpressionSyntax
                    || expression.IsKind(
                        SyntaxKind.DefaultLiteralExpression))
                && member.Model.GetTypeInfo(expression).Type is { } defaultType)
            {
                return ExactCleanupProvenance(member, defaultType);
            }

            ISymbol? symbol = member.Model.GetSymbolInfo(expression).Symbol;

            if (expression is InvocationExpressionSyntax relinquishingRead
                && symbol is IMethodSymbol relinquishingMethod
                && IsExactFrameworkMethod(relinquishingMethod, "System.Threading.Interlocked", "Exchange", "System.Private.CoreLib")
                && ExactNullingOrReadOnlyFieldReference(member.Model, relinquishingRead, relinquishingMethod)
                && relinquishingRead.ArgumentList.Arguments[0].Expression is { } relinquished
                && member.Model.GetSymbolInfo(relinquished).Symbol is IFieldSymbol relinquishedField
                && relinquished is IdentifierNameSyntax
                    or MemberAccessExpressionSyntax
                {
                    Expression: ThisExpressionSyntax,
                }
                && SymbolEqualityComparer.Default.Equals(
                    relinquishedField.ContainingType,
                    member.Symbol.ContainingType)
                && member.ValueBindings?.ContainsKey(relinquishedField) == true
                && HasExactGuardedFieldReadSemantics(relinquishedField, allowNullingAssignments: true))
            {
                return CleanupProvenanceOf(member, relinquished, context);
            }

            if (expression is InvocationExpressionSyntax completedTask
                && symbol is IMethodSymbol completedTaskMethod
                && ExactCompletedResultValue(
                    member,
                    completedTask,
                    completedTaskMethod) is { } completedValue)
            {
                return CleanupProvenanceOf(
                    member,
                    completedValue,
                    context);
            }

            if (symbol is IFieldSymbol
                && CanUseCurrentInstanceStorageBinding(symbol, expression)
                && member.ValueBindings?.TryGetValue(
                    symbol,
                    out BoundValueSource? boundFieldValue) == true
                && boundFieldValue is not null)
            {
                return CleanupProvenanceOf(
                    boundFieldValue.Caller,
                    boundFieldValue.Expression,
                    context);
            }

            if (expression is InvocationExpressionSyntax configuredConnection
                && symbol is IMethodSymbol configuredConnectionMethod
                && ExactConfiguredSqliteConnectionProvenance(
                    member,
                    configuredConnection,
                    configuredConnectionMethod,
                    context) is { } configuredConnectionProvenance)
            {
                return configuredConnectionProvenance;
            }

            if (expression is InvocationExpressionSyntax externalFactory
                && symbol is IMethodSymbol externalFactoryMethod
                && ExactTrustedExternalFactoryProvenance(
                    member,
                    externalFactory,
                    externalFactoryMethod,
                    context) is { } externalFactoryProvenance)
            {
                return externalFactoryProvenance;
            }

            if (expression is InvocationExpressionSyntax sqliteFactory
                && symbol is IMethodSymbol sqliteFactoryMethod
                && ExactTrustedSqliteFactoryProvenance(
                    member,
                    sqliteFactory,
                    sqliteFactoryMethod,
                    context) is { } sqliteTransaction)
            {
                return sqliteTransaction;
            }

            if (symbol is IPropertySymbol
                && CanUseCurrentInstanceStorageBinding(symbol, expression)
                && member.ValueBindings?.TryGetValue(
                    symbol,
                    out BoundValueSource? propertyValue) == true
                && propertyValue is not null)
            {
                return CleanupProvenanceOf(
                    propertyValue.Caller,
                    propertyValue.Expression,
                    context);
            }

            if (symbol is IPropertySymbol sameInstanceProperty
                && ExactSameInstancePropertyCleanupProvenance(
                    member,
                    expression,
                    sameInstanceProperty,
                    context) is { } sameInstancePropertyProvenance)
            {
                return sameInstancePropertyProvenance;
            }

            if (expression is ConditionalAccessExpressionSyntax conditionalAccess
                && DirectConditionalAccessProperty(
                    member,
                    conditionalAccess) is { } conditionalProperty
                && ExactConditionalPropertyCleanupProvenance(
                    member,
                    conditionalAccess,
                    conditionalProperty,
                    context) is { } conditionalPropertyProvenance)
            {
                return conditionalPropertyProvenance;
            }

            if (expression is MemberAccessExpressionSyntax propertyAccess
                && symbol is IPropertySymbol property
                && ExactAssignedPropertyCleanupProvenance(
                    member,
                    propertyAccess,
                    property,
                    context) is { } propertyProvenance)
            {
                return propertyProvenance;
            }

            if (expression is InvocationExpressionSyntax configuredCleanup
                && symbol is IMethodSymbol configuredCleanupMethod
                && IsExactFrameworkMethod(
                    configuredCleanupMethod,
                    "System.Threading.Tasks.TaskAsyncEnumerableExtensions",
                    "ConfigureAwait",
                    "System.Private.CoreLib")
                && configuredCleanup.Expression is
                    MemberAccessExpressionSyntax
                {
                    Expression: { } unconfiguredCleanup,
                })
            {
                return CleanupProvenanceOf(
                    member,
                    unconfiguredCleanup,
                    context);
            }

            if (symbol is IParameterSymbol
                {
                    ContainingSymbol: IMethodSymbol
                    {
                        MethodKind: MethodKind.Constructor,
                    } constructor,
                } constructorParameter)
            {
                if (ResolveConstructorContextTarget(
                        constructor,
                        member.Model.Compilation) is not { } constructorMember
                    || HasConstructorDependencyMutation(
                        constructorMember,
                        constructorParameter))
                {
                    return new([], false, true);
                }

                if (member.ValueBindings?.TryGetValue(
                        constructorParameter,
                        out BoundValueSource? constructorValue) == true
                    && constructorValue is not null)
                {
                    if (constructorValue.Expression.Ancestors()
                            .OfType<ConstructorInitializerSyntax>()
                            .Any()
                        && ResolveDiConstructorDependency(
                            constructorValue.Caller.Symbol,
                            constructor,
                            constructorParameter,
                            constructorValue.Caller.Model.GetTypeInfo(
                                constructorValue.Expression).Type
                                ?? constructorParameter.Type,
                            member.Model.Compilation,
                            0) is null)
                    {
                        return new([], false, true);
                    }

                    return CleanupProvenanceOf(
                        constructorValue.Caller,
                        constructorValue.Expression,
                        context);
                }

                if (TryExactAbsentOptionalDiDefault(
                        member,
                        constructorParameter,
                        out BoundValueSource optionalDefault))
                {
                    return CleanupProvenanceOf(
                        optionalDefault.Caller,
                        optionalDefault.Expression,
                        context);
                }

                return constructorParameter.Type is INamedTypeSymbol
                {
                    IsAbstract: false,
                    IsSealed: true,
                } registeredConstructorType
                    && IsAuthoredCleanupSymbol(
                        registeredConstructorType,
                        member.Model.Compilation)
                    && IsExactRegisteredConstructorDependency(
                        member,
                        constructorParameter,
                        registeredConstructorType)
                    ? ExactCleanupProvenance(member, registeredConstructorType)
                    : new([], false, true);
            }

            if (symbol is not null
                && CanUseCurrentInstanceStorageBinding(symbol, expression)
                && member.ConcreteBindings?.TryGetValue(
                    symbol,
                    out ITypeSymbol? bound) == true)
            {
                return ExactCleanupProvenance(member, bound);
            }

            if (symbol is ILocalSymbol or IParameterSymbol
                && ExactDirectRuntimeTypeGuardedProvenance(
                    member,
                    expression,
                    symbol) is { } directlyGuarded)
            {
                return directlyGuarded;
            }

            if (symbol is IParameterSymbol
                && member.ValueBindings?.TryGetValue(
                    symbol,
                    out BoundValueSource? parameterValue) == true
                && parameterValue is not null)
            {
                return CleanupProvenanceOf(
                    parameterValue.Caller,
                    parameterValue.Expression,
                    context);
            }

            if (symbol is IParameterSymbol
                {
                    Type: INamedTypeSymbol
                    {
                        IsAbstract: false,
                        IsSealed: true,
                    } registeredType,
                } registeredDependency
                && IsAuthoredCleanupSymbol(
                    registeredType,
                    member.Model.Compilation)
                && IsExactRegisteredConstructorDependency(
                    member,
                    registeredDependency,
                    registeredType))
            {
                return ExactCleanupProvenance(member, registeredType);
            }

            if (expression is InvocationExpressionSyntax absentCall
                && symbol is IMethodSymbol { MethodKind: MethodKind.DelegateInvoke }
                && member.Model.GetSymbolInfo(DelegateReceiver(member, absentCall)).Symbol is { } absentSeam
                && IsProvenAbsentCallable(absentSeam))
            {
                return new([], true, false);
            }

            if (expression is InvocationExpressionSyntax call
                && symbol is IMethodSymbol method
                && ResolveCleanupInvocationTarget(
                    method,
                    member,
                    call,
                    context) is { } target)
            {
                AuthoredMember factory = BindCleanupInvocationContext(
                    member,
                    call,
                    target,
                    context,
                    method.MethodKind == MethodKind.DelegateInvoke);

                ExpressionSyntax[] returned = ReturnedExpressions(factory.Syntax);

                (factory, returned) = ExactSqlitePatternArmReturns(
                    factory,
                    returned,
                    context);

                if (returned.Length == 0)
                {
                    return new([], false, true);
                }

                CleanupProvenance merged = MergeCleanupProvenance(
                    returned.Select(value => CleanupProvenanceOf(
                        factory,
                        value,
                        context)));

                return merged with
                {
                    HasAuthoredSource = true,
                };
            }

            if (expression is InvocationExpressionSyntax
                && member.Model.GetTypeInfo(expression).Type is
                    INamedTypeSymbol exactInvocationType
                && (exactInvocationType.TypeKind == TypeKind.Struct
                    || exactInvocationType is
                    {
                        TypeKind: TypeKind.Class,
                        IsAbstract: false,
                        IsSealed: true,
                    }))
            {
                return ExactCleanupProvenance(
                    member,
                    exactInvocationType);
            }

            if (symbol is IFieldSymbol field
                && ExactAssignedFieldCleanupValueFlow(
                    member,
                    expression,
                    field,
                    context) is { } fieldFlow)
            {
                CleanupProvenance fieldProvenance = MergeCleanupProvenance(
                    fieldFlow.Values.Select(value => CleanupProvenanceOf(
                        value.Caller,
                        value.Expression,
                        context)));

                return fieldProvenance with
                {
                    Complete = fieldFlow.Complete
                        && fieldProvenance.Complete,
                    HasAuthoredSource = true,
                };
            }

            if (symbol is ILocalSymbol local)
            {
                return LocalCleanupProvenance(
                    member,
                    expression,
                    local,
                    context);
            }

            if (symbol is IFieldSymbol or IPropertySymbol)
            {
                return new(
                    [],
                    false,
                    IsAuthoredCleanupSymbol(
                        symbol,
                        member.Model.Compilation));
            }

            if (symbol is IParameterSymbol)
            {
                return new([], false, false);
            }

            if (symbol is null
                && expression is ThisExpressionSyntax
                && member.Model.GetTypeInfo(expression).Type is
                    INamedTypeSymbol
                {
                    IsAbstract: false,
                    TypeKind: not TypeKind.Interface,
                } self)
            {
                return ExactCleanupProvenance(member, self);
            }

            return new(
                [],
                false,
                symbol is not null
                    && IsAuthoredCleanupSymbol(
                        symbol,
                        member.Model.Compilation));
        }

        private static ExpressionSyntax? ExactCompletedResultValue(
            AuthoredMember member,
            InvocationExpressionSyntax call,
            IMethodSymbol method)
        {
            IMethodSymbol definition = method.ReducedFrom ?? method;

            string? awaitableType =
                IsExactFrameworkMethod(
                    definition,
                    "System.Threading.Tasks.Task",
                    "FromResult",
                    "System.Private.CoreLib")
                    ? "System.Threading.Tasks.Task`1"
                    : IsExactFrameworkMethod(
                        definition,
                        "System.Threading.Tasks.ValueTask",
                        "FromResult",
                        "System.Private.CoreLib")
                        ? "System.Threading.Tasks.ValueTask`1"
                        : null;

            if (!definition.IsStatic
                || awaitableType is null
                || definition.TypeArguments is not [ITypeSymbol resultType]
                || definition.Parameters is not [IParameterSymbol value]
                || value.RefKind != RefKind.None
                || !SymbolEqualityComparer.Default.Equals(
                    value.Type,
                    resultType)
                || definition.ReturnType is not INamedTypeSymbol
                {
                    TypeArguments: [ITypeSymbol returnedType],
                } task
                || TypeKey(task.OriginalDefinition) != awaitableType
                || !SymbolEqualityComparer.Default.Equals(
                    returnedType,
                    resultType)
                || member.Model.GetOperation(call) is not
                    IInvocationOperation
                {
                    Arguments:
                        [
                            IArgumentOperation
                        {
                            Parameter.Ordinal: 0,
                            Value.Syntax: ExpressionSyntax expression,
                        },
                        ],
                })
            {
                return null;
            }

            return expression;
        }

        private CleanupProvenance? ExactSameInstancePropertyCleanupProvenance(
            AuthoredMember member,
            ExpressionSyntax access,
            IPropertySymbol property,
            CleanupProvenanceContext context)
        {
            CleanupValueFlow? flow = ExactSameInstancePropertyValueFlow(
                member,
                access,
                property,
                context);

            if (flow is null)
            {
                return null;
            }

            if (flow.Values.Count == 0)
            {
                return new([], flow.Complete, flow.HasAuthoredSource);
            }

            CleanupProvenance provenance = MergeCleanupProvenance(
                flow.Values.Select(value => CleanupProvenanceOf(
                    value.Caller,
                    value.Expression,
                    context)));

            return provenance with
            {
                Complete = flow.Complete && provenance.Complete,
                HasAuthoredSource = true,
            };
        }

        private CleanupValueFlow? ExactSameInstancePropertyValueFlow(
            AuthoredMember member,
            ExpressionSyntax access,
            IPropertySymbol property,
            CleanupProvenanceContext context)
        {
            bool exactCurrentInstanceAccess = access is IdentifierNameSyntax
                || access is MemberAccessExpressionSyntax
                {
                    Expression: ThisExpressionSyntax,
                };

            if (!exactCurrentInstanceAccess
                || member.Symbol.IsStatic
                || property.IsStatic
                || property.Parameters.Length != 0
                || property.SetMethod is not null
                || property.GetMethod is not
                {
                    IsStatic: false,
                } getterSymbol
                || getterSymbol.IsVirtual && !getterSymbol.IsSealed
                || property.ContainingType is not
                {
                    IsSealed: true,
                } containingType
                || !SameBoundType(
                    member.Symbol.ContainingType,
                    member.Model.Compilation,
                    containingType,
                    member.Model.Compilation)
                || !IsAuthoredCleanupSymbol(
                    property,
                    member.Model.Compilation)
                || Resolve(
                    getterSymbol,
                    member.Model.Compilation) is not { } getter)
            {
                return null;
            }

            AuthoredMember boundGetter = BindStableCapturedCleanupContext(
                member,
                access,
                getter);

            ExpressionSyntax[] values = GetterValueLeaves(boundGetter);

            if (values.Length == 0)
            {
                return null;
            }

            if (!context.CollectionIndexerProof
                && !ImportedGetterValueBindingsRemainStable(
                member,
                boundGetter,
                values))
            {
                return null;
            }

            CleanupValueFlow flow = MergeCleanupValueFlow(
                values.Select(value => CleanupReturnedValueFlow(
                    boundGetter,
                    value,
                    context)));

            return flow with
            {
                HasAuthoredSource = true,
            };
        }

        private static bool ImportedGetterValueBindingsRemainStable(
            AuthoredMember caller,
            AuthoredMember getter,
            IReadOnlyList<ExpressionSyntax> values)
        {
            if (caller.ValueBindings is not { Count: > 0 } callerBindings
                || getter.ValueBindings is not { Count: > 0 } getterBindings)
            {
                return true;
            }

            HashSet<ISymbol> importedSymbols = new(
                SymbolEqualityComparer.Default);

            foreach ((ISymbol symbol, BoundValueSource source) in callerBindings)
            {
                if (getterBindings.TryGetValue(
                        symbol,
                        out BoundValueSource? imported)
                    && ReferenceEquals(imported, source))
                {
                    _ = importedSymbols.Add(symbol);
                }
            }

            if (importedSymbols.Count == 0)
            {
                return true;
            }

            return getter.Syntax is ExpressionSyntax expression
                && values.Count == 1
                && IsExactSideEffectFreeImportedGetterExpression(
                    getter,
                    expression,
                    importedSymbols);
        }

        private static bool IsExactSideEffectFreeImportedGetterExpression(
            AuthoredMember getter,
            ExpressionSyntax expression,
            IReadOnlySet<ISymbol> importedSymbols)
        {
            Conversion conversion = getter.Model.ClassifyConversion(
                expression,
                getter.Symbol.ReturnType);

            if (!conversion.Exists || conversion.IsUserDefined)
            {
                return false;
            }

            expression = expression switch
            {
                ParenthesizedExpressionSyntax parenthesized =>
                    parenthesized.Expression,
                PostfixUnaryExpressionSyntax suppression when suppression.IsKind(
                    SyntaxKind.SuppressNullableWarningExpression) =>
                    suppression.Operand,
                _ => expression,
            };

            bool IsImportedStorage(ExpressionSyntax candidate)
            {
                candidate = candidate switch
                {
                    ParenthesizedExpressionSyntax parenthesized =>
                        parenthesized.Expression,
                    PostfixUnaryExpressionSyntax suppression when suppression.IsKind(
                        SyntaxKind.SuppressNullableWarningExpression) =>
                        suppression.Operand,
                    _ => candidate,
                };

                if (candidate is not IdentifierNameSyntax
                    and not MemberAccessExpressionSyntax
                    {
                        Expression: ThisExpressionSyntax,
                    })
                {
                    return false;
                }

                ISymbol? symbol = getter.Model.GetSymbolInfo(candidate).Symbol;

                return (symbol is IFieldSymbol or IParameterSymbol)
                    && importedSymbols.Contains(symbol);
            }

            if (expression is ThisExpressionSyntax
                || IsImportedStorage(expression))
            {
                return true;
            }

            return expression is ConditionalAccessExpressionSyntax
            {
                Expression: { } receiver,
                WhenNotNull: MemberBindingExpressionSyntax binding,
            }
                && IsImportedStorage(receiver)
                && getter.Model.GetSymbolInfo(binding).Symbol is
                    IPropertySymbol
                {
                    IsStatic: false,
                    Parameters.Length: 0,
                    GetMethod: not null,
                    SetMethod: null,
                };
        }

        private CleanupProvenance? ExactConditionalPropertyCleanupProvenance(
            AuthoredMember member,
            ConditionalAccessExpressionSyntax access,
            IPropertySymbol property,
            CleanupProvenanceContext context)
        {
            CleanupValueFlow? flow = ExactAssignedPropertyReceiverValueFlow(
                member,
                access.Expression,
                property,
                context);

            if (flow is null)
            {
                return null;
            }

            if (flow.Values.Count == 0)
            {
                return new([], flow.Complete, flow.HasAuthoredSource);
            }

            CleanupProvenance provenance = MergeCleanupProvenance(
                flow.Values.Select(value => CleanupProvenanceOf(
                    value.Caller,
                    value.Expression,
                    context)));

            return provenance with
            {
                Complete = flow.Complete && provenance.Complete,
                HasAuthoredSource = flow.HasAuthoredSource
                    || provenance.HasAuthoredSource,
            };
        }

        private static IPropertySymbol? DirectConditionalAccessProperty(
            AuthoredMember member,
            ConditionalAccessExpressionSyntax access) =>
            access.WhenNotNull is MemberBindingExpressionSyntax binding
                && member.Model.GetSymbolInfo(binding).Symbol is
                    IPropertySymbol
                {
                    IsStatic: false,
                    Parameters.Length: 0,
                    GetMethod: not null,
                } property
                    ? property
                    : null;

        private CleanupProvenance? ExactAssignedPropertyCleanupProvenance(
            AuthoredMember member,
            MemberAccessExpressionSyntax access,
            IPropertySymbol property,
            CleanupProvenanceContext context)
        {
            CleanupValueFlow? flow =
                ExactFailureGuardedSuccessfulValueFlow(
                    member,
                    access,
                    property,
                    context)
                ?? ExactAssignedPropertyValueFlow(
                    member,
                    access,
                    property,
                    context);

            if (flow is null)
            {
                return null;
            }

            if (flow.Values.Count == 0)
            {
                return new([], flow.Complete, flow.HasAuthoredSource);
            }

            CleanupProvenance provenance = MergeCleanupProvenance(
                flow.Values.Select(value => CleanupProvenanceOf(
                    value.Caller,
                    value.Expression,
                    context)));

            return provenance with
            {
                Complete = flow.Complete && provenance.Complete,
                HasAuthoredSource = flow.HasAuthoredSource
                    || provenance.HasAuthoredSource,
            };
        }

        private CleanupValueFlow? ExactAssignedPropertyValueFlow(
            AuthoredMember member,
            MemberAccessExpressionSyntax access,
            IPropertySymbol property,
            CleanupProvenanceContext context) =>
            ExactAssignedPropertyReceiverValueFlow(
                member,
                access.Expression,
                property,
                context);

        private CleanupValueFlow? ExactAssignedPropertyReceiverValueFlow(
            AuthoredMember member,
            ExpressionSyntax receiverExpression,
            IPropertySymbol property,
            CleanupProvenanceContext context)
        {
            if (ExactClosedSealedCastPropertyValueFlow(
                    member,
                    receiverExpression,
                    property,
                    context) is { } castPropertyFlow)
            {
                return castPropertyFlow;
            }

            if (property.ContainingType.TypeKind == TypeKind.Interface)
            {
                return ExactImplementedPropertyValueFlow(
                    member,
                    receiverExpression,
                    property,
                    context);
            }

            if (property.SetMethod is { IsInitOnly: false }
                && ExactPrivateDomainMutablePropertyValueFlow(
                    member,
                    property,
                    context) is { } mutableProperty)
            {
                return mutableProperty;
            }

            if (property.IsStatic
                || property.ContainingType is not
                {
                    IsSealed: true,
                } containingType
                || property.SetMethod is { IsInitOnly: false }
                || !IsAuthoredCleanupSymbol(
                    property,
                    member.Model.Compilation)
                || member.Model.GetTypeInfo(receiverExpression).Type is not
                { } receiverType
                || !SameBoundType(
                    receiverType,
                    member.Model.Compilation,
                    containingType,
                    member.Model.Compilation))
            {
                return null;
            }

            CleanupValueFlow receivers = CleanupValueFlowOf(
                member,
                receiverExpression,
                context);

            List<CleanupValueFlow> values = [];

            bool complete = receivers.Complete;

            foreach (BoundValueSource receiver in receivers.Values)
            {
                CleanupValueFlow? value = PropertyValueFromExactConstruction(
                    receiver,
                    property,
                    context);

                if (value is null)
                {
                    complete = false;

                    continue;
                }

                complete &= value.Complete;

                values.Add(value);
            }

            CleanupValueFlow merged = MergeCleanupValueFlow(values);

            return merged with
            {
                Complete = complete,
                HasAuthoredSource = true,
            };
        }

        private CleanupSourceCounter CleanupSourceAnalysis(string kind, Compilation compilation, ISymbol symbol)
        {
            var identity = (kind, new CleanupSourceIdentity(CompilationIdentity(compilation), symbol));

            if (!cleanupSourceAnalysis.TryGetValue(identity, out CleanupSourceCounter? counter))
            {
                counter = new();

                cleanupSourceAnalysis.Add(identity, counter);
            }

            return counter;
        }

        private CleanupValueFlow? ExactClosedSealedCastPropertyValueFlow(
            AuthoredMember member,
            ExpressionSyntax receiverExpression,
            IPropertySymbol property,
            CleanupProvenanceContext context)
        {
            while (receiverExpression is ParenthesizedExpressionSyntax parenthesized)
            {
                receiverExpression = parenthesized.Expression;
            }

            if (receiverExpression is not CastExpressionSyntax cast
                || member.Model.GetTypeInfo(cast).Type is not
                    INamedTypeSymbol
                    {
                        IsSealed: true,
                        TypeKind: TypeKind.Class,
                        DeclaredAccessibility: Accessibility.Private
                            or Accessibility.Internal
                            or Accessibility.ProtectedAndInternal,
                    } castType
                || !SameBoundType(
                    castType,
                    member.Model.Compilation,
                    property.ContainingType,
                    member.Model.Compilation)
                || !IsEffectivelyClosed(castType)
                || property.IsStatic
                || property.Parameters.Length != 0
                || property.GetMethod is not
                    {
                        IsStatic: false,
                        IsVirtual: false,
                    }
                || property.SetMethod is
                    {
                        IsStatic: false,
                        IsInitOnly: false,
                    }
                || property.DeclaringSyntaxReferences is not
                    [SyntaxReference propertyReference]
                || !semanticModels.TryGetValue(
                    propertyReference.SyntaxTree,
                    out SemanticModel? propertyModel)
                || !ReferenceEquals(
                    propertyModel.Compilation,
                    member.Model.Compilation))
            {
                return null;
            }

            Compilation compilation = propertyModel.Compilation;

            ClosedCastSourceFacts facts = ClosedCastSources(compilation, castType);

            if (facts.Unsupported)
            {
                return new([], false, true);
            }

            List<CleanupValueFlow> values = [];

            bool complete = true;

            foreach ((SemanticModel model, BaseObjectCreationExpressionSyntax creation) in facts.Constructions)
            {
                if (model.GetEnclosingSymbol(creation.SpanStart) is not
                        IMethodSymbol enclosing
                    || Resolve(enclosing, compilation) is not { } owner
                    || PropertyValueFromExactConstruction(
                        new(
                            ValueExpressionContext(
                                owner,
                                creation,
                                model),
                            creation),
                        property,
                        context) is not { } value)
                {
                    complete = false;

                    continue;
                }

                complete &= value.Complete;

                values.Add(value);
            }

            if (values.Count == 0)
            {
                return new([], false, true);
            }

            CleanupValueFlow merged = MergeCleanupValueFlow(values);

            return merged with
            {
                Complete = complete && merged.Complete,
                HasAuthoredSource = true,
            };
        }

        private ClosedCastSourceFacts ClosedCastSources(Compilation compilation, INamedTypeSymbol castType)
        {
            CleanupSourceCounter analysis = CleanupSourceAnalysis("closed-cast", compilation, castType);

            analysis.Requests++;

            CleanupSourceIdentity identity = new(CompilationIdentity(compilation), castType);

            if (closedCastSources.TryGetValue(identity, out ClosedCastSourceFacts? cached))
            {
                return cached;
            }

            analysis.Builds++;

            ClosedCastSourceFacts facts = BuildClosedCastSources(compilation, castType);

            closedCastSources.Add(identity, facts);

            return facts;
        }

        private ClosedCastSourceFacts BuildClosedCastSources(Compilation compilation, INamedTypeSymbol castType)
        {
            if (semanticModels.Values.Any(model =>
                    !ReferenceEquals(model.Compilation, compilation)
                    && model.SyntaxTree.GetRoot()
                        .DescendantNodesAndSelf()
                        .OfType<ExpressionSyntax>()
                        .Any(expression =>
                            model.GetTypeInfo(expression).Type is
                                INamedTypeSymbol
                                {
                                    TypeKind: not TypeKind.Error,
                                    ContainingAssembly: not null,
                                } expressionType
                            && SameBoundType(
                                expressionType,
                                model.Compilation,
                                castType,
                                compilation))))
            {
                return new(true, []);
            }

            List<(SemanticModel Model, BaseObjectCreationExpressionSyntax Creation)> constructions = [];

            foreach (SyntaxTree tree in compilation.SyntaxTrees)
            {
                SemanticModel model = semanticModels.TryGetValue(
                        tree,
                        out SemanticModel? indexed)
                    && ReferenceEquals(indexed.Compilation, compilation)
                        ? indexed
                        : compilation.GetSemanticModel(tree);

                if (tree.GetRoot().DescendantNodesAndSelf()
                    .OfType<WithExpressionSyntax>()
                    .Any(withExpression =>
                        model.GetTypeInfo(withExpression).Type is
                            INamedTypeSymbol
                            {
                                TypeKind: not TypeKind.Error,
                                ContainingAssembly: not null,
                            } withType
                        && SameBoundType(
                            withType,
                            compilation,
                            castType,
                            compilation)))
                {
                    return new(true, []);
                }

                foreach (BaseObjectCreationExpressionSyntax creation in tree
                    .GetRoot()
                    .DescendantNodesAndSelf()
                    .OfType<BaseObjectCreationExpressionSyntax>()
                    .Where(creation =>
                        model.GetTypeInfo(creation).Type is
                            INamedTypeSymbol
                            {
                                TypeKind: not TypeKind.Error,
                                ContainingAssembly: not null,
                            } createdType
                        && SameBoundType(
                            createdType,
                            compilation,
                            castType,
                            compilation)))
                {
                    constructions.Add((model, creation));
                }
            }

            return new(false, constructions.ToArray());
        }

        private CleanupValueFlow? ExactPrivateDomainMutablePropertyValueFlow(
            AuthoredMember member,
            IPropertySymbol property,
            CleanupProvenanceContext context)
        {
            INamedTypeSymbol? carrier = property.ContainingType;

            if (property.IsStatic
                || property.Parameters.Length != 0
                || !carrier.IsSealed
                || property.GetMethod is not
                {
                    IsStatic: false,
                    IsVirtual: false,
                }
                || property.SetMethod is not
                {
                    IsStatic: false,
                    IsInitOnly: false,
                    IsVirtual: false,
                }
                || property.DeclaringSyntaxReferences is not
                    [SyntaxReference propertyReference]
                || propertyReference.GetSyntax() is not
                    PropertyDeclarationSyntax
                {
                    AccessorList.Accessors: var accessors,
                } propertyDeclaration
                || accessors.Count != 2
                || !accessors.Any(static accessor =>
                    accessor.IsKind(SyntaxKind.GetAccessorDeclaration)
                        && accessor.Body is null
                        && accessor.ExpressionBody is null
                        && accessor.SemicolonToken.RawKind != 0)
                || !accessors.Any(static accessor =>
                    accessor.IsKind(SyntaxKind.SetAccessorDeclaration)
                        && accessor.Body is null
                        && accessor.ExpressionBody is null
                        && accessor.SemicolonToken.RawKind != 0)
                || !IsAuthoredCleanupSymbol(
                    property,
                    member.Model.Compilation))
            {
                return null;
            }

            if (!semanticModels.TryGetValue(
                    propertyDeclaration.SyntaxTree,
                    out SemanticModel? propertyModel)
                || propertyModel.GetDeclaredSymbol(propertyDeclaration) is not
                    IPropertySymbol exactProperty)
            {
                return null;
            }

            carrier = exactProperty.ContainingType;

            bool IsExactPropertySymbol(ISymbol? candidate) =>
                candidate is IPropertySymbol referenced
                && (SymbolEqualityComparer.Default.Equals(
                        referenced.OriginalDefinition,
                        exactProperty.OriginalDefinition)
                    || referenced.DeclaringSyntaxReferences.Any(reference =>
                        (reference.SyntaxTree == propertyDeclaration.SyntaxTree
                            || string.Equals(
                                reference.SyntaxTree.FilePath,
                                propertyDeclaration.SyntaxTree.FilePath,
                                StringComparison.Ordinal))
                        && reference.Span == propertyDeclaration.Span));

            INamedTypeSymbol? privateAccessRoot = carrier.DeclaredAccessibility
                    == Accessibility.Private
                ? carrier.ContainingType
                : null;

            bool internalCompilationDomain = carrier.DeclaredAccessibility
                    == Accessibility.Internal
                && IsEffectivelyClosed(carrier);

            if (privateAccessRoot is null
                && !internalCompilationDomain)
            {
                return null;
            }

            if (propertyDeclaration.Initializer is { Value: { } initializer }
                && !IsSemanticallyEmptyCleanupValue(
                        propertyModel,
                        initializer))
            {
                return null;
            }

            List<BoundValueSource> values = [];

            bool complete = true;

            List<(SyntaxNode Domain, SemanticModel Model)> domains = [];

            if (privateAccessRoot is not null)
            {
                foreach (SyntaxReference reference in
                    privateAccessRoot.DeclaringSyntaxReferences)
                {
                    if (reference.GetSyntax() is not
                            TypeDeclarationSyntax domain
                        || !semanticModels.TryGetValue(
                            domain.SyntaxTree,
                            out SemanticModel? model))
                    {
                        complete = false;

                        continue;
                    }

                    domains.Add((domain, model));
                }
            }
            else
            {
                Compilation carrierCompilation = propertyModel.Compilation;

                if (semanticModels.Values.Any(model =>
                        model.Compilation.Assembly.Identity.Equals(
                            carrier.ContainingAssembly.Identity)
                        && !ReferenceEquals(
                            model.Compilation,
                            carrierCompilation)))
                {
                    complete = false;
                }
                else
                {
                    bool CarriesCarrierAcrossCompilation(
                        ITypeSymbol? type,
                        Compilation compilation)
                    {
                        if (type is null
                            || type.ContainingAssembly is null)
                        {
                            return false;
                        }

                        if (SameBoundType(
                            type,
                            compilation,
                            carrier,
                            carrierCompilation))
                        {
                            return true;
                        }

                        return type switch
                        {
                            IArrayTypeSymbol array =>
                                CarriesCarrierAcrossCompilation(
                                    array.ElementType,
                                    compilation),
                            INamedTypeSymbol named => named.TypeArguments.Any(
                                argument => CarriesCarrierAcrossCompilation(
                                    argument,
                                    compilation)),
                            _ => false,
                        };
                    }

                    if (semanticModels.Values.Any(model =>
                        !ReferenceEquals(
                            model.Compilation,
                            carrierCompilation)
                        && model.SyntaxTree.GetRoot()
                            .DescendantNodesAndSelf()
                            .OfType<ExpressionSyntax>()
                            .Any(expression =>
                                CarriesCarrierAcrossCompilation(
                                    model.GetTypeInfo(expression).Type,
                                    model.Compilation))))
                    {
                        complete = false;
                    }

                    foreach (SyntaxTree tree in
                        carrierCompilation.SyntaxTrees)
                    {
                        if (!semanticModels.TryGetValue(
                                tree,
                                out SemanticModel? model)
                            || !ReferenceEquals(
                                model.Compilation,
                                carrierCompilation))
                        {
                            model = carrierCompilation.GetSemanticModel(tree);
                        }

                        domains.Add((tree.GetRoot(), model));
                    }
                }

                complete &= domains.Count != 0;
            }

            foreach ((SyntaxNode domain, SemanticModel model) in domains)
            {
                if (domain.SyntaxTree is null
                    || !ReferenceEquals(model.SyntaxTree, domain.SyntaxTree)
                    || !ReferenceEquals(
                        model.Compilation,
                        propertyModel.Compilation))
                {
                    complete = false;

                    continue;
                }

                if (PrivateCarrierEscapesDomain(
                    domain,
                    model,
                    carrier,
                    privateAccessRoot,
                    internalCompilationDomain))
                {
                    complete = false;
                }

                foreach (AssignmentExpressionSyntax assignment in domain
                    .DescendantNodesAndSelf()
                    .OfType<AssignmentExpressionSyntax>()
                    .Where(assignment => IsExactPropertySymbol(
                        model.GetSymbolInfo(assignment.Left).Symbol)))
                {
                    if (!assignment.IsKind(
                            SyntaxKind.SimpleAssignmentExpression))
                    {
                        complete = false;

                        continue;
                    }

                    if (IsSemanticallyEmptyCleanupValue(
                        model,
                        assignment.Right))
                    {
                        continue;
                    }

                    if (model.GetEnclosingSymbol(assignment.SpanStart) is not
                            IMethodSymbol enclosing
                        || Resolve(enclosing, model.Compilation) is not
                        { } assignmentMember)
                    {
                        complete = false;

                        continue;
                    }

                    if (ExactClosedMutablePropertyWriterValueFlow(
                            member,
                            assignmentMember,
                            assignment.Right,
                            context) is { } closedWriter)
                    {
                        values.AddRange(closedWriter.Values);

                        complete &= closedWriter.Complete;

                        continue;
                    }

                    values.Add(new(
                        ValueExpressionContext(
                            assignmentMember,
                            assignment.Right,
                            model),
                        assignment.Right));
                }

                if (domain.DescendantNodesAndSelf()
                    .OfType<AssignmentExpressionSyntax>()
                    .Any(assignment => assignment.Left
                            .DescendantNodesAndSelf()
                            .OfType<ExpressionSyntax>()
                            .Any(left => IsExactPropertySymbol(
                                model.GetSymbolInfo(left).Symbol))
                        && (!assignment.IsKind(
                                SyntaxKind.SimpleAssignmentExpression)
                            || !IsExactPropertySymbol(
                                model.GetSymbolInfo(assignment.Left).Symbol))))
                {
                    complete = false;
                }

                if (domain.DescendantNodesAndSelf().Any(node => node switch
                {
                    PrefixUnaryExpressionSyntax prefix
                        when prefix.IsKind(SyntaxKind.PreIncrementExpression)
                            || prefix.IsKind(
                                SyntaxKind.PreDecrementExpression) =>
                        IsExactPropertySymbol(
                            model.GetSymbolInfo(prefix.Operand).Symbol),
                    PostfixUnaryExpressionSyntax postfix
                        when postfix.IsKind(SyntaxKind.PostIncrementExpression)
                            || postfix.IsKind(
                                SyntaxKind.PostDecrementExpression) =>
                        IsExactPropertySymbol(
                            model.GetSymbolInfo(postfix.Operand).Symbol),
                    _ => false,
                }))
                {
                    complete = false;
                }
            }

            CleanupValueFlow merged = MergeCleanupValueFlow(
                values.Select(value => CleanupValueFlowOf(
                    value.Caller,
                    value.Expression,
                    context)));

            return merged with
            {
                Complete = complete && merged.Complete,
                HasAuthoredSource = true,
            };
        }

        private CleanupValueFlow? ExactClosedMutablePropertyWriterValueFlow(
            AuthoredMember authenticatedOwner,
            AuthoredMember writer,
            ExpressionSyntax value,
            CleanupProvenanceContext context)
        {
            BoundValueSource source = new(writer, value);

            if (TryResolveStableLocalInitializerValueSource(
                    writer,
                    value,
                    out BoundValueSource? initialized)
                && initialized is not null)
            {
                source = initialized;
            }

            ExpressionSyntax expression = StripTransparentExpression(
                source.Expression);

            if (source.Caller.Model.GetSymbolInfo(expression).Symbol is not
                    IParameterSymbol parameter
                || parameter.RefKind != RefKind.None
                || parameter.Ordinal < 0
                || parameter.Ordinal >= writer.Symbol.Parameters.Length
                || !SymbolEqualityComparer.Default.Equals(
                    parameter.ContainingSymbol.OriginalDefinition,
                    writer.Symbol.OriginalDefinition))
            {
                return null;
            }

            return ClosedWriterParameterValueFlow(
                authenticatedOwner,
                writer,
                writer.Symbol.Parameters[parameter.Ordinal],
                context,
                0,
                [],
                allowInternalAssemblyWriter: true);
        }

        private bool PrivateCarrierEscapesDomain(
            SyntaxNode domain,
            SemanticModel model,
            INamedTypeSymbol carrier,
            INamedTypeSymbol? privateAccessRoot,
            bool internalCompilationDomain)
        {
            bool SameCarrier(ITypeSymbol? type) =>
                SymbolEqualityComparer.Default.Equals(type, carrier);

            bool CarriesCarrier(ITypeSymbol? type)
            {
                if (SameCarrier(type))
                {
                    return true;
                }

                return type switch
                {
                    IArrayTypeSymbol array => CarriesCarrier(
                        array.ElementType),
                    INamedTypeSymbol named => named.TypeArguments.Any(
                        CarriesCarrier),
                    _ => false,
                };
            }

            bool IsExactCarrierFrameworkInvocation(IMethodSymbol invoked)
            {
                if (IsExactFrameworkType(
                        invoked.ContainingType.OriginalDefinition,
                        "System.Collections.Concurrent.ConcurrentDictionary`2",
                        typeof(System.Collections.Concurrent.ConcurrentDictionary<,>)
                            .Assembly.GetName()))
                {
                    return invoked.Name is "ContainsKey"
                        or "TryGetValue"
                        or "TryRemove"
                        or "Clear";
                }

                if (IsExactFrameworkType(
                        invoked.ContainingType.OriginalDefinition,
                        "System.Collections.Generic.List`1",
                        typeof(List<>).Assembly.GetName()))
                {
                    return invoked.Name == "Add";
                }

                if (IsExactFrameworkType(
                        invoked.ContainingType.OriginalDefinition,
                        "System.Collections.Generic.HashSet`1",
                        typeof(HashSet<>).Assembly.GetName()))
                {
                    return invoked.Name is "Add" or "Contains";
                }

                return IsExactFrameworkType(
                        invoked.ContainingType,
                        "System.Linq.Enumerable",
                        typeof(Enumerable).Assembly.GetName())
                    && invoked.Name is "Where"
                        or "OrderBy"
                        or "ThenBy"
                        or "ToList"
                        or "ToArray";
            }

            bool IsExactCarrierResultReturn(
                ExpressionSyntax expression,
                IMethodSymbol returnedFrom)
            {
                if (returnedFrom.ReturnType is not INamedTypeSymbol result
                    || result.TypeArguments is not [ITypeSymbol valueType]
                    || !SameCarrier(valueType)
                    || !WithinDomain(returnedFrom)
                    || !IsExactAuthoredProtocolType(
                        result.OriginalDefinition,
                        "RetroDownfall.Arcanum.Core.Primitives.Result`1",
                        model.Compilation))
                {
                    return false;
                }

                Conversion conversion = model.GetConversion(expression);

                if (!conversion.IsImplicit
                    || !conversion.IsUserDefined
                    || conversion.MethodSymbol is not { } operatorMethod
                    || operatorMethod.Name != "op_Implicit"
                    || !operatorMethod.IsStatic
                    || operatorMethod.DeclaredAccessibility
                        != Accessibility.Public
                    || operatorMethod.Parameters is not
                        [{ RefKind: RefKind.None } parameter]
                    || !SameCarrier(parameter.Type)
                    || !SymbolEqualityComparer.Default.Equals(
                        operatorMethod.ContainingType.OriginalDefinition,
                        result.OriginalDefinition)
                    || !SymbolEqualityComparer.Default.Equals(
                        operatorMethod.ReturnType,
                        result))
                {
                    return false;
                }

                return true;
            }

            foreach (VariableDeclaratorSyntax declaration in
                internalCompilationDomain
                    ? domain.DescendantNodesAndSelf()
                        .OfType<VariableDeclaratorSyntax>()
                    : [])
            {
                if (model.GetDeclaredSymbol(declaration) is not
                        IFieldSymbol field
                    || !CarriesCarrier(field.Type))
                {
                    continue;
                }

                if (IsEffectivelyClosed(field.ContainingType))
                {
                    continue;
                }

                if (field.IsStatic
                    || !field.IsReadOnly
                    || field.DeclaredAccessibility != Accessibility.Private
                    || field.Type is not INamedTypeSymbol fieldType
                    || !IsExactFrameworkType(
                        fieldType.OriginalDefinition,
                        "System.Collections.Concurrent.ConcurrentDictionary`2",
                        typeof(System.Collections.Concurrent.ConcurrentDictionary<,>)
                            .Assembly.GetName())
                    || declaration.Initializer?.Value is not
                        BaseObjectCreationExpressionSyntax initializer
                    || model.GetSymbolInfo(initializer).Symbol is not
                        IMethodSymbol constructor
                    || !SymbolEqualityComparer.Default.Equals(
                        constructor.ContainingType,
                        fieldType))
                {
                    return true;
                }
            }

            bool WithinDomain(ISymbol member)
            {
                if (internalCompilationDomain)
                {
                    if (!member.ContainingAssembly.Identity.Equals(
                            carrier.ContainingAssembly.Identity))
                    {
                        return false;
                    }

                    for (ISymbol? symbol = member;
                        symbol is not null
                            && symbol.Kind != SymbolKind.Namespace;
                        symbol = symbol.ContainingSymbol)
                    {
                        if (symbol.DeclaredAccessibility is
                            Accessibility.Public
                                or Accessibility.Protected
                                or Accessibility.ProtectedOrInternal)
                        {
                            continue;
                        }

                        return symbol.DeclaredAccessibility is
                            Accessibility.Private
                                or Accessibility.Internal
                                or Accessibility.ProtectedAndInternal;
                    }

                    return false;
                }

                INamedTypeSymbol? type = member.ContainingType;

                while (type is not null)
                {
                    if (SymbolEqualityComparer.Default.Equals(
                        type,
                        privateAccessRoot))
                    {
                        return true;
                    }

                    type = type.ContainingType;
                }

                return false;
            }

            foreach (ExpressionSyntax expression in domain
                .DescendantNodesAndSelf()
                .OfType<ExpressionSyntax>()
                .Where(expression => SameCarrier(
                    model.GetTypeInfo(expression).Type)))
            {
                if (model.GetOperation(expression) is null
                    && expression is not BaseObjectCreationExpressionSyntax)
                {
                    continue;
                }

                SyntaxNode? parent = expression.Parent;

                if (parent is MemberAccessExpressionSyntax access
                    && access.Expression == expression
                    || parent is ConditionalAccessExpressionSyntax conditional
                        && conditional.Expression == expression)
                {
                    continue;
                }

                if (parent is EqualsValueClauseSyntax equals
                    && equals.Parent is VariableDeclaratorSyntax variable
                    && variable.Parent is VariableDeclarationSyntax declaration
                    && SameCarrier(model.GetTypeInfo(declaration.Type).Type))
                {
                    continue;
                }

                if (parent is EqualsValueClauseSyntax propertyEquals
                    && propertyEquals.Parent is
                        PropertyDeclarationSyntax propertyDeclaration
                    && SameCarrier(model.GetTypeInfo(
                        propertyDeclaration.Type).Type))
                {
                    continue;
                }

                if (parent is AssignmentExpressionSyntax assignment
                    && assignment.Right == expression
                    && SameCarrier(model.GetTypeInfo(assignment.Left).Type))
                {
                    continue;
                }

                if (parent is ConditionalExpressionSyntax conditionalValue
                    && SameCarrier(
                        model.GetTypeInfo(conditionalValue).Type))
                {
                    continue;
                }

                if (parent is PostfixUnaryExpressionSyntax suppression
                    && suppression.IsKind(
                        SyntaxKind.SuppressNullableWarningExpression)
                    && SameCarrier(model.GetTypeInfo(suppression).Type))
                {
                    continue;
                }

                if (expression is AssignmentExpressionSyntax
                    {
                        Left: ElementAccessExpressionSyntax elementAccess,
                    } elementAssignment
                    && elementAssignment.IsKind(
                        SyntaxKind.SimpleAssignmentExpression)
                    && model.GetTypeInfo(elementAccess.Expression).Type is
                        INamedTypeSymbol dictionary
                    && IsExactFrameworkType(
                        dictionary.OriginalDefinition,
                        "System.Collections.Concurrent.ConcurrentDictionary`2",
                        typeof(System.Collections.Concurrent.ConcurrentDictionary<,>)
                            .Assembly.GetName())
                    && CarriesCarrier(dictionary))
                {
                    continue;
                }

                if (expression is ElementAccessExpressionSyntax dictionarySlot
                    && parent is AssignmentExpressionSyntax
                    {
                        Left: var assignedSlot,
                    } slotAssignment
                    && assignedSlot == dictionarySlot
                    && slotAssignment.IsKind(
                        SyntaxKind.SimpleAssignmentExpression)
                    && model.GetTypeInfo(dictionarySlot.Expression).Type is
                        INamedTypeSymbol slotDictionary
                    && IsExactFrameworkType(
                        slotDictionary.OriginalDefinition,
                        "System.Collections.Concurrent.ConcurrentDictionary`2",
                        typeof(System.Collections.Concurrent.ConcurrentDictionary<,>)
                            .Assembly.GetName())
                    && CarriesCarrier(slotDictionary))
                {
                    continue;
                }

                if (parent is ReturnStatementSyntax
                    && model.GetEnclosingSymbol(expression.SpanStart) is
                        IMethodSymbol resultReturnedFrom
                    && IsExactCarrierResultReturn(
                        expression,
                        resultReturnedFrom))
                {
                    continue;
                }

                if (parent is ReturnStatementSyntax
                    && model.GetEnclosingSymbol(expression.SpanStart) is
                        IMethodSymbol returnedFrom
                    && returnedFrom.DeclaredAccessibility
                        is Accessibility.Private
                            or Accessibility.Internal
                            or Accessibility.ProtectedAndInternal
                    && SameCarrier(returnedFrom.ReturnType)
                    && WithinDomain(returnedFrom))
                {
                    continue;
                }

                if (parent is ArrowExpressionClauseSyntax
                    && model.GetEnclosingSymbol(expression.SpanStart) is
                        IMethodSymbol expressionReturnedFrom
                    && SameCarrier(expressionReturnedFrom.ReturnType)
                    && WithinDomain(expressionReturnedFrom))
                {
                    continue;
                }

                if (parent is ArgumentSyntax argument
                    && argument.Parent?.Parent is
                        InvocationExpressionSyntax invocation
                    && model.GetSymbolInfo(invocation).Symbol is
                        IMethodSymbol invoked)
                {
                    if (IsExactFrameworkMethod(
                            invoked,
                            "System.Object",
                            "ReferenceEquals",
                            "System.Private.CoreLib")
                        || IsExactFrameworkType(
                                invoked.ContainingType,
                                "System.Runtime.CompilerServices.ConditionalWeakTable`2",
                                typeof(ConditionalWeakTable<,>).Assembly
                                    .GetName())
                            && invoked.Name == "TryGetValue")
                    {
                        continue;
                    }

                    if (invoked.ContainingType is INamedTypeSymbol
                            collection
                        && CarriesCarrier(collection)
                        && IsExactCarrierFrameworkInvocation(invoked))
                    {
                        continue;
                    }

                    if (model.GetOperation(argument) is
                            IArgumentOperation
                        {
                            Parameter: { RefKind: RefKind.None }
                                    carrierParameter,
                        }
                        && SameCarrier(carrierParameter.Type)
                        && invoked.Locations.Any(static location =>
                            location.IsInSource)
                        && invoked.DeclaredAccessibility
                            is Accessibility.Private
                                or Accessibility.Internal
                                or Accessibility.ProtectedAndInternal
                        && WithinDomain(invoked))
                    {
                        continue;
                    }
                }

                if (parent is ArgumentSyntax constructorArgument
                    && constructorArgument.Parent?.Parent is
                        BaseObjectCreationExpressionSyntax creation
                    && model.GetSymbolInfo(creation).Symbol is
                        IMethodSymbol constructor
                    && constructor.MethodKind == MethodKind.Constructor
                    && constructor.Parameters.ElementAtOrDefault(
                        creation.ArgumentList?.Arguments.IndexOf(
                            constructorArgument) ?? -1) is { } parameter
                    && SameCarrier(parameter.Type)
                    && IsEffectivelyClosed(constructor.ContainingType)
                    && WithinDomain(constructor))
                {
                    continue;
                }

                if (expression is IdentifierNameSyntax
                    && parent is VariableDeclaratorSyntax)
                {
                    continue;
                }

                if (parent is ForEachStatementSyntax foreachStatement
                    && foreachStatement.Type == expression)
                {
                    continue;
                }

                return true;
            }

            foreach (ExpressionSyntax expression in domain
                .DescendantNodesAndSelf()
                .OfType<ExpressionSyntax>()
                .Where(expression => !SameCarrier(
                        model.GetTypeInfo(expression).Type)
                    && CarriesCarrier(
                        model.GetTypeInfo(expression).Type)))
            {
                SyntaxNode? parent = expression.Parent;

                if (parent is ArgumentSyntax argument
                    && argument.Parent?.Parent is
                        InvocationExpressionSyntax invocation
                    && model.GetSymbolInfo(invocation).Symbol is
                        IMethodSymbol invoked
                    && !IsExactCarrierFrameworkInvocation(invoked))
                {
                    return true;
                }

                if (parent is AssignmentExpressionSyntax assignment
                    && assignment.Right == expression
                    && !CarriesCarrier(
                        model.GetTypeInfo(assignment.Left).Type))
                {
                    return true;
                }

                if (parent is ReturnStatementSyntax
                    && model.GetEnclosingSymbol(expression.SpanStart) is
                        IMethodSymbol returnedFrom
                    && (!CarriesCarrier(returnedFrom.ReturnType)
                        || !WithinDomain(returnedFrom)))
                {
                    return true;
                }
            }

            return false;
        }

        private CleanupValueFlow? ExactImplementedPropertyValueFlow(
            AuthoredMember member,
            ExpressionSyntax receiverExpression,
            IPropertySymbol property,
            CleanupProvenanceContext context)
        {
            if (property.IsStatic
                || !IsAuthoredCleanupSymbol(
                    property,
                    member.Model.Compilation))
            {
                return null;
            }

            CleanupValueFlow receivers = CleanupValueFlowOf(
                member,
                receiverExpression,
                context);

            if (!receivers.Complete
                || receivers.Values.Count == 0)
            {
                return null;
            }

            List<CleanupValueFlow> values = [];

            foreach (BoundValueSource receiver in receivers.Values)
            {
                if (receiver.Caller.Model.GetTypeInfo(
                        StripTransparentExpression(receiver.Expression)).Type
                        is not INamedTypeSymbol
                        {
                            IsAbstract: false,
                            IsSealed: true,
                        } concrete)
                {
                    return null;
                }

                IPropertySymbol[] implementations = concrete.AllInterfaces
                    .Where(contract =>
                        contract.ContainingAssembly.Identity.Equals(
                            property.ContainingAssembly.Identity)
                        && TypeKey(contract)
                            == TypeKey(property.ContainingType))
                    .SelectMany(static contract => contract.GetMembers())
                    .OfType<IPropertySymbol>()
                    .Where(slot => slot.Name == property.Name
                        && slot.Parameters.Length
                            == property.Parameters.Length
                        && TypeKey(slot.Type) == TypeKey(property.Type)
                        && slot.Parameters.Select(static parameter =>
                                TypeKey(parameter.Type))
                            .SequenceEqual(
                                property.Parameters.Select(static parameter =>
                                    TypeKey(parameter.Type)),
                                StringComparer.Ordinal))
                    .Select(slot => concrete
                        .FindImplementationForInterfaceMember(slot))
                    .OfType<IPropertySymbol>()
                    .DistinctBy(
                        static implementation =>
                            implementation.OriginalDefinition,
                        SymbolEqualityComparer.Default)
                    .ToArray();

                if (implementations is not
                    [IPropertySymbol implementation]
                    || PropertyValueFromExactConstruction(
                        receiver,
                        implementation,
                        context) is not { } value)
                {
                    return null;
                }

                values.Add(value);
            }

            CleanupValueFlow merged = MergeCleanupValueFlow(values);

            return merged with
            {
                HasAuthoredSource = true,
            };
        }

        private CleanupValueFlow? ExactAssignedFieldCleanupValueFlow(
            AuthoredMember member,
            ExpressionSyntax expression,
            IFieldSymbol field,
            CleanupProvenanceContext context,
            bool allowSameOwnerLifetimeWriters = false)
        {
            if (field.IsStatic
                || field.DeclaredAccessibility != Accessibility.Private
                || field.ContainingType is not
                {
                    IsSealed: true,
                } containingType
                || !IsAuthoredCleanupSymbol(
                    field,
                    member.Model.Compilation))
            {
                return null;
            }

            List<BoundValueSource> values = [];

            bool complete = true;

            IMethodSymbol[] boundConstructors = BoundConstructorContexts(
                member,
                containingType);

            if (boundConstructors.Length > 1
                && member.ConstructorContexts is not { Count: > 0 })
            {
                return new([], false, true);
            }

            if (boundConstructors.Length == 0
                && InstanceConstructorCount(containingType) > 1)
            {
                return new([], false, true);
            }

            AssignedFieldSourceFacts facts = AssignedFieldSources(member.Model.Compilation, field);

            complete &= facts.Complete;

            foreach (AssignedFieldSourceDomain domain in facts.Domains)
            {
                SemanticModel model = domain.Model;

                foreach (ExpressionSyntax initializer in domain.Initializers)
                {
                    values.Add(new(
                        ValueExpressionContext(member, initializer, model),
                        initializer));
                }

                foreach (AssignmentExpressionSyntax assignment in domain.Assignments)
                {
                    if (!assignment.IsKind(
                            SyntaxKind.SimpleAssignmentExpression)
                        || model.GetEnclosingSymbol(assignment.SpanStart)
                            is not IMethodSymbol enclosing
                        || Resolve(enclosing, model.Compilation)
                            is not { } assignmentMember)
                    {
                        complete = false;

                        continue;
                    }

                    if (enclosing.MethodKind == MethodKind.Constructor
                        && boundConstructors is [IMethodSymbol boundConstructor]
                        && !SymbolEqualityComparer.Default.Equals(
                            enclosing.OriginalDefinition,
                            boundConstructor.OriginalDefinition))
                    {
                        continue;
                    }

                    bool exactSameOwnerLifetimeWriter =
                        allowSameOwnerLifetimeWriters
                        && enclosing.MethodKind != MethodKind.Constructor
                        && !enclosing.IsStatic
                        && SymbolEqualityComparer.Default.Equals(
                            enclosing.ContainingType,
                            containingType)
                        && assignment.Left is IdentifierNameSyntax
                            or MemberAccessExpressionSyntax
                        {
                            Expression: ThisExpressionSyntax,
                        };

                    values.Add(new(
                        (context.CollectionIndexerProof
                            || exactSameOwnerLifetimeWriter
                            || (field.IsReadOnly
                                    || boundConstructors is [_]
                                        && HasExactGuardedFieldReadSemantics(field, allowNullingAssignments: true))
                                && expression is IdentifierNameSyntax
                                    or MemberAccessExpressionSyntax
                                {
                                    Expression: ThisExpressionSyntax,
                                }
                                && SymbolEqualityComparer.Default.Equals(
                                    field.ContainingType,
                                    member.Symbol.ContainingType))
                            && (enclosing.MethodKind == MethodKind.Constructor
                                || exactSameOwnerLifetimeWriter)
                            ? MergeValueContext(assignmentMember, member)
                            : assignmentMember,
                        assignment.Right));
                }
            }

            CleanupValueFlow merged = MergeCleanupValueFlow(
                values.Select(value => CleanupValueFlowOf(
                    value.Caller,
                    value.Expression,
                    context)));

            return merged with
            {
                Complete = complete
                    && (values.Count == 0 || merged.Complete),
                HasAuthoredSource = true,
            };
        }

        private AssignedFieldSourceFacts AssignedFieldSources(Compilation compilation, IFieldSymbol field)
        {
            CleanupSourceCounter analysis = CleanupSourceAnalysis("assigned-field", compilation, field);

            analysis.Requests++;

            CleanupSourceIdentity identity = new(CompilationIdentity(compilation), field);

            if (assignedFieldSources.TryGetValue(identity, out AssignedFieldSourceFacts? cached))
            {
                return cached;
            }

            analysis.Builds++;

            bool complete = true;

            List<AssignedFieldSourceDomain> domains = [];

            foreach (SyntaxReference reference in field.ContainingType.DeclaringSyntaxReferences)
            {
                if (reference.GetSyntax() is not TypeDeclarationSyntax type
                    || !semanticModels.TryGetValue(type.SyntaxTree, out SemanticModel? model))
                {
                    complete = false;

                    continue;
                }

                ExpressionSyntax[] initializers = type.DescendantNodesAndSelf()
                    .OfType<VariableDeclaratorSyntax>()
                    .Where(declaration => SymbolEqualityComparer.Default.Equals(
                        model.GetDeclaredSymbol(declaration),
                        field))
                    .Select(static declaration => declaration.Initializer?.Value)
                    .OfType<ExpressionSyntax>()
                    .Where(initializer => !IsSemanticallyEmptyCleanupValue(model, initializer))
                    .ToArray();

                AssignmentExpressionSyntax[] assignments = type.DescendantNodesAndSelf()
                    .OfType<AssignmentExpressionSyntax>()
                    .Where(assignment => SymbolEqualityComparer.Default.Equals(
                        model.GetSymbolInfo(assignment.Left).Symbol,
                        field))
                    .ToArray();

                if (HasUnreviewedFieldReference(type, model, field))
                {
                    complete = false;
                }

                domains.Add(new(model, initializers, assignments));
            }

            AssignedFieldSourceFacts facts = new(complete, domains.ToArray());

            assignedFieldSources.Add(identity, facts);

            return facts;
        }

        private bool HasExactSameOwnerLifetimeFieldWriterSemantics(
            IFieldSymbol field)
        {
            if (exactSameOwnerLifetimeFieldWriterSemantics.TryGetValue(
                field,
                out bool cached))
            {
                return cached;
            }

            bool result = HasExactSameOwnerLifetimeFieldWriterSemanticsCore(
                field);

            exactSameOwnerLifetimeFieldWriterSemantics.Add(field, result);

            return result;
        }

        private bool HasExactSameOwnerLifetimeFieldWriterSemanticsCore(
            IFieldSymbol field)
        {
            if (field.IsStatic
                || field.DeclaredAccessibility != Accessibility.Private
                || field.ContainingType is not { IsSealed: true } containingType)
            {
                return false;
            }

            foreach (SyntaxReference reference in
                containingType.DeclaringSyntaxReferences)
            {
                SyntaxNode declaration = reference.GetSyntax();

                if (!semanticModels.TryGetValue(
                        declaration.SyntaxTree,
                        out SemanticModel? model))
                {
                    return false;
                }

                foreach (AssignmentExpressionSyntax assignment in declaration
                    .DescendantNodesAndSelf()
                    .OfType<AssignmentExpressionSyntax>()
                    .Where(assignment => SymbolEqualityComparer.Default.Equals(
                        model.GetSymbolInfo(assignment.Left).Symbol,
                        field)))
                {
                    if (!assignment.IsKind(
                            SyntaxKind.SimpleAssignmentExpression)
                        || assignment.Left is not (IdentifierNameSyntax
                            or MemberAccessExpressionSyntax
                        {
                            Expression: ThisExpressionSyntax,
                        })
                        || model.GetEnclosingSymbol(assignment.SpanStart) is not
                            IMethodSymbol writer
                        || writer.IsStatic
                        || !SymbolEqualityComparer.Default.Equals(
                            writer.ContainingType,
                            containingType)
                        || Resolve(writer, model.Compilation) is null)
                    {
                        return false;
                    }
                }

                if (HasUnreviewedFieldReference(
                    declaration,
                    model,
                    field))
                {
                    return false;
                }
            }

            return true;
        }

        private static bool HasUnreviewedFieldReference(
            SyntaxNode declaration,
            SemanticModel model,
            IFieldSymbol field)
        {
            foreach (ArgumentSyntax argument in declaration
                .DescendantNodesAndSelf()
                .OfType<ArgumentSyntax>()
                .Where(argument => argument.RefKindKeyword.Kind() is
                        SyntaxKind.RefKeyword or SyntaxKind.OutKeyword
                    && SymbolEqualityComparer.Default.Equals(
                        model.GetSymbolInfo(argument.Expression).Symbol,
                        field)))
            {
                if (argument.Parent?.Parent is not InvocationExpressionSyntax call
                    || model.GetSymbolInfo(call).Symbol is not IMethodSymbol method
                    || !ExactNullingOrReadOnlyFieldReference(model, call, method))
                {
                    return true;
                }
            }

            return declaration.DescendantNodesAndSelf()
                .OfType<RefExpressionSyntax>()
                .Any(alias => SymbolEqualityComparer.Default.Equals(
                    model.GetSymbolInfo(alias.Expression).Symbol,
                    field));
        }

        private static bool ExactNullingOrReadOnlyFieldReference(
            SemanticModel model,
            InvocationExpressionSyntax call,
            IMethodSymbol method)
        {
            if (IsExactFrameworkMethod(
                    method,
                    "System.Threading.Volatile",
                    "Read",
                    "System.Private.CoreLib"))
            {
                return true;
            }

            return IsExactFrameworkMethod(
                    method,
                    "System.Threading.Interlocked",
                    "Exchange",
                    "System.Private.CoreLib")
                && call.ArgumentList.Arguments.Count == 2
                && model.GetConstantValue(
                    call.ArgumentList.Arguments[1].Expression) is
                {
                    HasValue: true,
                    Value: null,
                };
        }

        private CleanupValueFlow? PropertyValueFromExactConstruction(
            BoundValueSource receiver,
            IPropertySymbol property,
            CleanupProvenanceContext context)
        {
            ExpressionSyntax expression = StripTransparentExpression(
                receiver.Expression);

            if (expression is not BaseObjectCreationExpressionSyntax creation
                || receiver.Caller.Model.GetTypeInfo(creation).Type is not
                    INamedTypeSymbol createdType
                || property.SetMethod is { IsInitOnly: false }
                || !SameBoundTypeOrGenericDefinition(
                    createdType,
                    property.ContainingType,
                    receiver.Caller.Model.Compilation)
                || receiver.Caller.Model.GetSymbolInfo(creation).Symbol is not
                    IMethodSymbol constructor)
            {
                return null;
            }

            AuthoredMember? constructorTarget = ResolveConstructorContextTarget(
                constructor,
                receiver.Caller.Model.Compilation);

            if (creation.Initializer is
                {
                    Expressions.Count: > 0,
                } initializer)
            {
                AssignmentExpressionSyntax[] assignments = initializer
                    .Expressions
                    .OfType<AssignmentExpressionSyntax>()
                    .Where(static assignment => assignment.IsKind(
                        SyntaxKind.SimpleAssignmentExpression))
                    .ToArray();

                if (assignments.Length != initializer.Expressions.Count
                    || assignments.Any(assignment =>
                        receiver.Caller.Model.GetSymbolInfo(
                            assignment.Left).Symbol is not
                                IPropertySymbol initializedProperty
                        || !HasExactAutoInitAssignmentSemantics(
                            initializedProperty))
                    || assignments.Where(assignment =>
                            receiver.Caller.Model.GetSymbolInfo(
                                assignment.Left).Symbol is
                                IPropertySymbol initializedProperty
                            && SameBoundPropertyDefinition(
                                initializedProperty,
                                receiver.Caller.Model.Compilation,
                                property,
                                receiver.Caller.Model.Compilation))
                        .ToArray() is not
                            [AssignmentExpressionSyntax initializerAssignment])
                {
                    return null;
                }

                return CleanupValueFlowOf(
                    receiver.Caller,
                    initializerAssignment.Right,
                    context);
            }

            if (constructor.DeclaringSyntaxReferences.Length == 0
                && constructor.Parameters.Length == 0
                && createdType.BaseType?.SpecialType
                    == SpecialType.System_Object
                && HasExactAutoInitAssignmentSemantics(property)
                && property.DeclaringSyntaxReferences is
                    [SyntaxReference propertyReference]
                && propertyReference.GetSyntax() is PropertyDeclarationSyntax
                {
                    Initializer: null,
                }
                && (property.Type.IsReferenceType
                    || property.Type is INamedTypeSymbol
                    {
                        OriginalDefinition.SpecialType:
                            SpecialType.System_Nullable_T,
                    }))
            {
                return new([], true, true);
            }

            IParameterSymbol? propertyParameter =
                PropertyConstructorParameter(property);

            if (propertyParameter is null
                && createdType.IsRecord
                && constructorTarget?.Syntax is TypeDeclarationSyntax
                {
                    ParameterList: not null,
                })
            {
                propertyParameter = constructor.Parameters
                    .SingleOrDefault(parameter =>
                        parameter.Name == property.Name
                        && SameBoundType(
                            parameter.Type,
                            receiver.Caller.Model.Compilation,
                            property.Type,
                            receiver.Caller.Model.Compilation));
            }

            if (propertyParameter is not null)
            {
                (ExpressionSyntax Expression, IParameterSymbol? Parameter, RefKind RefKind)[] arguments =
                    ConstructorArguments(receiver.Caller, creation)
                        .Where(argument => argument.Parameter?.Ordinal
                            == propertyParameter.Ordinal)
                        .ToArray();

                return arguments is [var argument]
                    && argument.RefKind == RefKind.None
                        ? CleanupValueFlowOf(
                            receiver.Caller,
                            argument.Expression,
                            context)
                        : null;
            }

            if (constructorTarget is not null)
            {
                AuthoredMember propertyConstructor =
                    BindCleanupConstructorArguments(
                        receiver.Caller,
                        creation,
                        constructorTarget);

                AssignmentExpressionSyntax[] propertyAssignments =
                    propertyConstructor.Syntax.DescendantNodesAndSelf(node =>
                            node == propertyConstructor.Syntax
                            || node is not AnonymousFunctionExpressionSyntax
                                and not LocalFunctionStatementSyntax)
                        .OfType<AssignmentExpressionSyntax>()
                        .Where(assignment => assignment.IsKind(
                                SyntaxKind.SimpleAssignmentExpression)
                            && propertyConstructor.Model.GetSymbolInfo(
                                assignment.Left).Symbol is
                                IPropertySymbol assignedProperty
                            && SameBoundPropertyDefinition(
                                assignedProperty,
                                propertyConstructor.Model.Compilation,
                                property,
                                receiver.Caller.Model.Compilation))
                        .ToArray();

                if (propertyAssignments is
                        [AssignmentExpressionSyntax propertyAssignment]
                    && IsAssignedOnEverySuccessfulConstruction(
                        propertyConstructor,
                        propertyAssignment))
                {
                    return CleanupValueFlowOf(
                        propertyConstructor,
                        propertyAssignment.Right,
                        context);
                }
            }

            if (property.GetMethod is not { } getterSymbol
                || Resolve(
                    getterSymbol,
                    receiver.Caller.Model.Compilation) is not { } getter
                || constructorTarget is null)
            {
                return null;
            }

            ExpressionSyntax[] leaves = GetterValueLeaves(getter);

            IParameterSymbol[] primaryConstructorParameters = leaves
                .Select(leaf => getter.Model.GetSymbolInfo(
                    StripTransparentExpression(leaf)).Symbol)
                .OfType<IParameterSymbol>()
                .DistinctBy(
                    static parameter => parameter,
                    SymbolEqualityComparer.Default)
                .ToArray();

            if (primaryConstructorParameters is
                    [IParameterSymbol primaryConstructorParameter]
                && leaves.All(leaf => SymbolEqualityComparer.Default.Equals(
                    getter.Model.GetSymbolInfo(
                        StripTransparentExpression(leaf)).Symbol,
                    primaryConstructorParameter))
                && HasExactPrimaryConstructorParameterReadSemantics(
                    primaryConstructorParameter,
                    createdType,
                    constructor))
            {
                AuthoredMember boundPrimaryConstructor =
                    BindCleanupConstructorArguments(
                        receiver.Caller,
                        creation,
                        constructorTarget);

                return boundPrimaryConstructor.ValueBindings?.TryGetValue(
                        primaryConstructorParameter,
                        out BoundValueSource? primaryConstructorValue) == true
                    && primaryConstructorValue is not null
                        ? CleanupValueFlowOf(
                            primaryConstructorValue.Caller,
                            primaryConstructorValue.Expression,
                            context)
                        : null;
            }

            IFieldSymbol[] fields = leaves
                .Select(leaf => getter.Model.GetSymbolInfo(
                    StripTransparentExpression(leaf)).Symbol)
                .OfType<IFieldSymbol>()
                .DistinctBy(
                    static field => field.OriginalDefinition,
                    SymbolEqualityComparer.Default)
                .ToArray();

            if (fields is not
                [IFieldSymbol
                {
                    IsStatic: false,
                } field]
                || !field.IsReadOnly
                    && !HasExactGuardedFieldReadSemantics(field))
            {
                return null;
            }

            ExpressionSyntax[] alternateLeaves = leaves
                .Where(leaf => !SymbolEqualityComparer.Default.Equals(
                    getter.Model.GetSymbolInfo(
                        StripTransparentExpression(leaf)).Symbol,
                    field))
                .ToArray();

            if (!context.CollectionIndexerProof
                && alternateLeaves.Length != 0)
            {
                return null;
            }

            AuthoredMember boundConstructor = BindCleanupConstructorArguments(
                receiver.Caller,
                creation,
                constructorTarget);

            ExpressionSyntax[] fieldInitializers = field
                .DeclaringSyntaxReferences
                .Select(static reference => reference.GetSyntax())
                .OfType<VariableDeclaratorSyntax>()
                .Select(static declaration => declaration.Initializer?.Value)
                .OfType<ExpressionSyntax>()
                .ToArray();

            AssignmentExpressionSyntax[] fieldAssignments = boundConstructor.Syntax
                .DescendantNodesAndSelf(node => node == boundConstructor.Syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<AssignmentExpressionSyntax>()
                .Where(assignment => assignment.IsKind(
                        SyntaxKind.SimpleAssignmentExpression)
                    && SymbolEqualityComparer.Default.Equals(
                        boundConstructor.Model.GetSymbolInfo(
                            assignment.Left).Symbol,
                        field))
                .ToArray();

            ExpressionSyntax fieldValueExpression;

            if (fieldInitializers is [ExpressionSyntax fieldInitializer]
                && fieldAssignments.Length == 0)
            {
                fieldValueExpression = fieldInitializer;
            }
            else if (fieldInitializers.Length == 0
                && fieldAssignments is
                    [AssignmentExpressionSyntax fieldAssignment]
                && IsAssignedOnEverySuccessfulConstruction(
                    boundConstructor,
                    fieldAssignment))
            {
                fieldValueExpression = fieldAssignment.Right;
            }
            else
            {
                return null;
            }

            if ((fieldValueExpression is DefaultExpressionSyntax
                    || fieldValueExpression.IsKind(
                        SyntaxKind.DefaultLiteralExpression))
                && (property.Type.IsReferenceType
                    || property.Type is INamedTypeSymbol
                    {
                        OriginalDefinition.SpecialType:
                            SpecialType.System_Nullable_T,
                    }))
            {
                return new([], true, true);
            }

            CleanupValueFlow fieldValue = CleanupValueFlowOf(
                ValueExpressionContext(boundConstructor, fieldValueExpression),
                fieldValueExpression,
                context);

            CleanupValueFlow value = alternateLeaves.Length == 0
                ? fieldValue
                : MergeCleanupValueFlow(
                    [
                        fieldValue,
                        .. alternateLeaves.Select(leaf => CleanupValueFlowOf(
                            ValueExpressionContext(getter, leaf),
                            leaf,
                            context)),
                    ]);

            return value.Complete
                ? value with
                {
                    HasAuthoredSource = true,
                }
                : null;
        }

        private bool HasExactPrimaryConstructorParameterReadSemantics(
            IParameterSymbol parameter,
            INamedTypeSymbol containingType,
            IMethodSymbol constructor)
        {
            if (parameter.RefKind != RefKind.None
                || parameter.ContainingSymbol is not IMethodSymbol
                {
                    MethodKind: MethodKind.Constructor,
                } parameterConstructor
                || !SymbolEqualityComparer.Default.Equals(
                    parameterConstructor.OriginalDefinition,
                    constructor.OriginalDefinition)
                || parameter.DeclaringSyntaxReferences is not
                    [SyntaxReference parameterReference]
                || parameterReference.GetSyntax() is not ParameterSyntax
                {
                    Parent: ParameterListSyntax
                    {
                        Parent: TypeDeclarationSyntax,
                    },
                })
            {
                return false;
            }

            foreach (SyntaxReference reference in
                containingType.DeclaringSyntaxReferences)
            {
                SyntaxNode declaration = reference.GetSyntax();

                if (!semanticModels.TryGetValue(
                        declaration.SyntaxTree,
                        out SemanticModel? model))
                {
                    return false;
                }

                if (declaration.DescendantNodesAndSelf().Any(node =>
                    node switch
                    {
                        AssignmentExpressionSyntax assignment =>
                            SymbolEqualityComparer.Default.Equals(
                                model.GetSymbolInfo(
                                    assignment.Left).Symbol,
                                parameter),
                        PrefixUnaryExpressionSyntax prefix
                            when prefix.IsKind(
                                    SyntaxKind.PreIncrementExpression)
                                || prefix.IsKind(
                                    SyntaxKind.PreDecrementExpression) =>
                            SymbolEqualityComparer.Default.Equals(
                                model.GetSymbolInfo(
                                    prefix.Operand).Symbol,
                                parameter),
                        PostfixUnaryExpressionSyntax postfix
                            when postfix.IsKind(
                                    SyntaxKind.PostIncrementExpression)
                                || postfix.IsKind(
                                    SyntaxKind.PostDecrementExpression) =>
                            SymbolEqualityComparer.Default.Equals(
                                model.GetSymbolInfo(
                                    postfix.Operand).Symbol,
                                parameter),
                        ArgumentSyntax argument
                            when argument.RefKindKeyword.Kind() is
                                SyntaxKind.RefKeyword
                                    or SyntaxKind.OutKeyword =>
                            SymbolEqualityComparer.Default.Equals(
                                model.GetSymbolInfo(
                                    argument.Expression).Symbol,
                                parameter),
                        RefExpressionSyntax referenceExpression =>
                            SymbolEqualityComparer.Default.Equals(
                                model.GetSymbolInfo(
                                    referenceExpression.Expression).Symbol,
                                parameter),
                        _ => false,
                    }))
                {
                    return false;
                }
            }

            return true;
        }

        private bool SameBoundTypeOrGenericDefinition(
            INamedTypeSymbol createdType,
            INamedTypeSymbol propertyType,
            Compilation consumingCompilation) =>
            SameBoundType(
                createdType,
                consumingCompilation,
                propertyType,
                consumingCompilation)
            || createdType.IsGenericType
                && propertyType.IsGenericType
                && SameBoundType(
                    createdType.OriginalDefinition,
                    consumingCompilation,
                    propertyType.OriginalDefinition,
                    consumingCompilation);

        private static bool HasExactAutoInitAssignmentSemantics(
            IPropertySymbol property)
        {
            if (property.SetMethod is not { IsInitOnly: true }
                || property.DeclaringSyntaxReferences is not
                    [SyntaxReference declaration])
            {
                return false;
            }

            SyntaxNode syntax = declaration.GetSyntax();

            if (syntax is ParameterSyntax
                {
                    Parent: ParameterListSyntax
                    {
                        Parent: RecordDeclarationSyntax,
                    },
                })
            {
                return true;
            }

            if (syntax is not PropertyDeclarationSyntax
                {
                    AccessorList.Accessors: var accessors,
                }
                || accessors.Count != 2)
            {
                return false;
            }

            return accessors.Any(static accessor =>
                    accessor.IsKind(SyntaxKind.GetAccessorDeclaration)
                    && accessor.Body is null
                    && accessor.ExpressionBody is null
                    && accessor.SemicolonToken.RawKind != 0)
                && accessors.Any(static accessor =>
                    accessor.IsKind(SyntaxKind.InitAccessorDeclaration)
                    && accessor.Body is null
                    && accessor.ExpressionBody is null
                    && accessor.SemicolonToken.RawKind != 0);
        }

        private IParameterSymbol? PropertyConstructorParameter(
            IPropertySymbol property)
        {
            foreach (SyntaxReference reference in
                property.DeclaringSyntaxReferences)
            {
                SyntaxNode syntax = reference.GetSyntax();

                if (!semanticModels.TryGetValue(
                        syntax.SyntaxTree,
                        out SemanticModel? model))
                {
                    continue;
                }

                if (syntax is ParameterSyntax parameter
                    && parameter.Parent is ParameterListSyntax
                    {
                        Parent: TypeDeclarationSyntax,
                    }
                    && model.GetDeclaredSymbol(parameter) is
                        IParameterSymbol positional)
                {
                    return positional;
                }

                if (syntax is PropertyDeclarationSyntax
                    {
                        Initializer.Value: { } initializer,
                    }
                    && model.GetSymbolInfo(initializer).Symbol is
                        IParameterSymbol initialized)
                {
                    return initialized;
                }
            }

            return null;
        }

        private ExpressionSyntax[] GetterValueLeaves(
            AuthoredMember getter)
        {
            ExpressionSyntax[] returned = getter.Syntax is ExpressionSyntax expression
                ? [expression]
                : ReturnedExpressions(getter.Syntax);

            return returned.SelectMany(ValueLeaves).ToArray();

            IEnumerable<ExpressionSyntax> ValueLeaves(
                ExpressionSyntax expression)
            {
                expression = StripTransparentExpression(expression);

                if (expression is ThrowExpressionSyntax)
                {
                    return [];
                }

                if (expression is BinaryExpressionSyntax coalescing
                    && coalescing.IsKind(SyntaxKind.CoalesceExpression))
                {
                    return ValueLeaves(coalescing.Left)
                        .Concat(ValueLeaves(coalescing.Right));
                }

                if (expression is ConditionalExpressionSyntax conditional)
                {
                    return ValueLeaves(conditional.WhenTrue)
                        .Concat(ValueLeaves(conditional.WhenFalse));
                }

                if (expression is SwitchExpressionSyntax selection)
                {
                    return selection.Arms.SelectMany(arm =>
                        ValueLeaves(arm.Expression));
                }

                if (expression is InvocationExpressionSyntax read
                    && getter.Model.GetSymbolInfo(read).Symbol is
                        IMethodSymbol readMethod
                    && IsExactFrameworkMethod(
                        readMethod,
                        "System.Threading.Volatile",
                        "Read",
                        "System.Private.CoreLib")
                    && read.ArgumentList.Arguments is
                        [ArgumentSyntax
                        {
                            Expression: { } location,
                        } argument]
                    && argument.RefKindKeyword.IsKind(SyntaxKind.RefKeyword))
                {
                    return ValueLeaves(location);
                }

                return [expression];
            }
        }

        private bool HasExactGuardedFieldReadSemantics(IFieldSymbol field, bool allowNullingAssignments = false)
        {
            if (field.IsStatic
                || field.DeclaredAccessibility != Accessibility.Private
                || field.ContainingType is not { IsSealed: true } containingType)
            {
                return false;
            }

            foreach (SyntaxReference reference in
                containingType.DeclaringSyntaxReferences)
            {
                SyntaxNode declaration = reference.GetSyntax();

                if (!semanticModels.TryGetValue(
                        declaration.SyntaxTree,
                        out SemanticModel? model))
                {
                    return false;
                }

                foreach (AssignmentExpressionSyntax assignment in declaration
                    .DescendantNodesAndSelf()
                    .OfType<AssignmentExpressionSyntax>()
                    .Where(assignment => SymbolEqualityComparer.Default.Equals(
                        model.GetSymbolInfo(assignment.Left).Symbol,
                        field)))
                {
                    if (allowNullingAssignments
                        && assignment.IsKind(SyntaxKind.SimpleAssignmentExpression)
                        && IsSemanticallyEmptyCleanupValue(model, assignment.Right))
                    {
                        continue;
                    }

                    if (!assignment.IsKind(
                            SyntaxKind.SimpleAssignmentExpression)
                        || allowNullingAssignments
                            && assignment.Left is not (IdentifierNameSyntax or MemberAccessExpressionSyntax { Expression: ThisExpressionSyntax })
                        || model.GetEnclosingSymbol(assignment.SpanStart) is not
                            IMethodSymbol
                        {
                            MethodKind: MethodKind.Constructor,
                        } constructor
                        || !SymbolEqualityComparer.Default.Equals(
                            constructor.ContainingType,
                            containingType))
                    {
                        return false;
                    }
                }

                foreach (ArgumentSyntax argument in declaration
                    .DescendantNodesAndSelf()
                    .OfType<ArgumentSyntax>()
                    .Where(argument => argument.RefKindKeyword.Kind() is
                            SyntaxKind.RefKeyword or SyntaxKind.OutKeyword
                        && SymbolEqualityComparer.Default.Equals(
                            model.GetSymbolInfo(argument.Expression).Symbol,
                            field)))
                {
                    if (argument.Parent?.Parent is not
                            InvocationExpressionSyntax call
                        || model.GetSymbolInfo(call).Symbol is not
                            IMethodSymbol method
                        || !ExactNullingOrReadOnlyFieldReference(
                            model,
                            call,
                            method))
                    {
                        return false;
                    }
                }
            }

            return true;
        }

        private AuthoredMember[] ExactSelectedCleanupInvocationTargets(
            AuthoredMember caller,
            InvocationExpressionSyntax call,
            AuthoredMember target,
            AuthoredMember fallback)
        {
            if (target.Symbol.Name is not ("Dispose" or "DisposeAsync")
                || target.Symbol.Parameters.Length != 0
                || target.Symbol.IsStatic
                || !ReceiverTargetMayCarryCleanupState(target)
                || AdmissionReceiver(caller, call) is not { } receiver)
            {
                return [fallback];
            }

            CleanupValueFlow flow = CleanupValueFlowOf(
                caller,
                receiver,
                new CleanupProvenanceContext());

            if (!flow.Complete || flow.Values.Count < 2)
            {
                return [fallback];
            }

            List<AuthoredMember> targets = [];

            foreach (BoundValueSource source in flow.Values)
            {
                if (ExactNonThrowingValue(source.Expression) is not BaseObjectCreationExpressionSyntax creation
                    || source.Caller.Model.GetTypeInfo(creation).Type is not INamedTypeSymbol
                    {
                        IsSealed: true,
                        IsAbstract: false,
                    } concrete
                    || !SameBoundType(
                        concrete,
                        source.Caller.Model.Compilation,
                        target.Symbol.ContainingType,
                        target.Model.Compilation)
                    || source.Caller.Model.GetSymbolInfo(creation).Symbol is not IMethodSymbol constructor
                    || ResolveConstructorContextTarget(
                        constructor,
                        source.Caller.Model.Compilation) is not { } constructorTarget)
                {
                    return [fallback];
                }

                AuthoredMember constructed = BindConstructedReadonlyFieldContext(
                    BindCleanupConstructorArguments(
                        source.Caller,
                        creation,
                        constructorTarget));

                constructed = BindDemandedReceiverReadonlyFieldContext(
                    constructed,
                    target);

                AuthoredMember selected = MergeValueContext(
                    BindAdmissionArguments(caller, call, target),
                    constructed);

                EvaluationEnvironmentFingerprint environment =
                    EvaluationEnvironmentIdentity(selected);

                if (!environment.Complete
                    || environment.ContainsBackreference)
                {
                    return [fallback];
                }

                targets.Add(selected);
            }

            return targets.ToArray();
        }

        private AuthoredMember BindCleanupInvocationContext(
            AuthoredMember caller,
            InvocationExpressionSyntax call,
            AuthoredMember target,
            CleanupProvenanceContext context,
            bool resolvedCallable = false,
            BoundValueSource? selectedReceiver = null)
        {
            AuthoredMember bound = selectedReceiver is not null
                ? BindAdmissionArguments(caller, call, target)
                : resolvedCallable
                ? BindResolvedCallableInvocationContext(
                    caller,
                    call,
                    target)
                : BindInvocationContext(
                    caller,
                    call,
                    target);

            if (!resolvedCallable)
            {
                bound = AddCleanupValueBindings(
                    caller,
                    AdmissionArguments(caller, call),
                    target,
                    bound);
            }

            if (target.Symbol.IsStatic
                || call.Expression is not MemberAccessExpressionSyntax
                {
                    Expression: { } receiver,
                })
            {
                return bound;
            }

            CleanupValueFlow receivers = selectedReceiver is { } selected
                ? new([selected], true, true)
                : CleanupValueFlowOf(caller, receiver, context);

            if (!receivers.Complete
                || receivers.Values is not [BoundValueSource exactReceiver]
                || exactReceiver.Caller.Model.GetTypeInfo(
                    StripTransparentExpression(exactReceiver.Expression)).Type
                    is not INamedTypeSymbol
                    {
                        IsAbstract: false,
                        IsSealed: true,
                    } receiverType
                || !SameBoundType(
                    receiverType,
                    exactReceiver.Caller.Model.Compilation,
                    target.Symbol.ContainingType,
                    target.Model.Compilation))
            {
                return bound;
            }

            if (StripTransparentExpression(exactReceiver.Expression) is
                    BaseObjectCreationExpressionSyntax creation
                && exactReceiver.Caller.Model.GetSymbolInfo(creation).Symbol is
                    IMethodSymbol constructor
                && ResolveConstructorContextTarget(
                    constructor,
                    exactReceiver.Caller.Model.Compilation) is
                    { } constructorTarget)
            {
                AuthoredMember constructed = BindConstructedReadonlyFieldContext(
                    BindCleanupConstructorArguments(
                        exactReceiver.Caller,
                        creation,
                        constructorTarget));

                bound = MergeValueContext(bound, constructed);
            }

            return BindExactConstructedReceiverPropertyContext(bound, target, exactReceiver, context);
        }

        private bool TryResolveConvergentCleanupPropertyType(
            CleanupValueFlow flow,
            CleanupProvenanceContext context,
            out ITypeSymbol exactType)
        {
            exactType = null!;

            if (!flow.Complete || flow.Values.Count < 2)
            {
                return false;
            }

            CleanupTypeCandidate? convergent = null;

            foreach (BoundValueSource value in flow.Values)
            {
                EvaluationEnvironmentFingerprint environment =
                    EvaluationEnvironmentIdentity(
                        ProjectEvaluationEnvironment(
                            value.Caller,
                            value.Expression));

                CleanupProvenance provenance = CleanupProvenanceOf(
                    value.Caller,
                    value.Expression,
                    context);

                if (!environment.Complete
                    || environment.ContainsBackreference
                    || !provenance.Complete
                    || provenance.Candidates is not
                        [CleanupTypeCandidate candidate]
                    || convergent is not null
                        && convergent.Identity != candidate.Identity)
                {
                    exactType = null!;

                    return false;
                }

                convergent = candidate;

                exactType ??= candidate.Type;
            }

            return exactType is not null;
        }

        private AuthoredMember BindCleanupConstructorArguments(
            AuthoredMember caller,
            BaseObjectCreationExpressionSyntax creation,
            AuthoredMember target)
        {
            AuthoredMember bound = BindConstructorArguments(
                caller,
                creation,
                target);

            return AddCleanupValueBindings(
                caller,
                ConstructorArguments(caller, creation),
                target,
                bound);
        }

        private static AuthoredMember AddCleanupValueBindings(
            AuthoredMember caller,
            IEnumerable<(ExpressionSyntax Expression, IParameterSymbol? Parameter, RefKind RefKind)> arguments,
            AuthoredMember target,
            AuthoredMember bound)
        {
            Dictionary<ISymbol, BoundValueSource> values =
                bound.ValueBindings?.ToDictionary(
                    static pair => pair.Key,
                    static pair => pair.Value,
                    SymbolEqualityComparer.Default)
                ?? new(SymbolEqualityComparer.Default);

            foreach (var argument in arguments)
            {
                if (argument.RefKind != RefKind.None
                    || argument.Parameter is not { } parameter
                    || parameter.Ordinal >= target.Symbol.Parameters.Length)
                {
                    continue;
                }

                values[target.Symbol.Parameters[parameter.Ordinal]] = new(
                    caller,
                    argument.Expression);
            }

            HashSet<IMethodSymbol> constructors = new(
                bound.ConstructorContexts
                    ?? Enumerable.Empty<IMethodSymbol>(),
                SymbolEqualityComparer.Default);

            if (target.Symbol.MethodKind == MethodKind.Constructor)
            {
                constructors.Add(target.Symbol);
            }

            return bound with
            {
                ValueBindings = values,
                ConstructorContexts = constructors,
            };
        }

        private CleanupValueFlow CleanupValueFlowOf(
            AuthoredMember member,
            ExpressionSyntax expression,
            CleanupProvenanceContext context)
        {
            CleanupCacheAnalysisCounter analysis = CleanupCacheCounter(member);

            analysis.ValueFlowRequests++;

            expression = StripTransparentExpression(expression);

            CleanupProvenanceIdentity identity = CleanupIdentity(
                member,
                expression);

            CleanupEnvironmentCacheIdentity? cacheIdentity =
                CompleteCleanupEnvironmentIdentity(member, identity);

            if (!context.CollectionIndexerProof
                && cacheIdentity is { } stableIdentity
                && completeCleanupValueFlows.TryGetValue(
                    stableIdentity,
                    out CleanupValueFlow? stable))
            {
                analysis.ValueFlowStableHits++;

                return stable;
            }

            if (cacheIdentity is { } completeIdentity
                && context.ValueCache.TryGetValue(
                    completeIdentity,
                    out CleanupValueFlow? cached))
            {
                return cached;
            }

            if (context.RemainingWork-- <= 0)
            {
                return new([], false, true);
            }

            bool entered = cacheIdentity is { } completeActiveIdentity
                ? context.CompleteValueActive.Add(completeActiveIdentity)
                : context.ValueActive.Add(identity);

            if (!entered)
            {
                return new([], false, true);
            }

            analysis.ValueFlowBuilds++;

            CleanupValueFlow result;

            try
            {
                result = CleanupValueFlowCore(
                    member,
                    expression,
                    context);
            }
            finally
            {
                if (cacheIdentity is { } completeRemovalIdentity)
                {
                    _ = context.CompleteValueActive.Remove(
                        completeRemovalIdentity);
                }
                else
                {
                    _ = context.ValueActive.Remove(identity);
                }
            }

            if (cacheIdentity is { } completeCacheIdentity)
            {
                context.ValueCache[completeCacheIdentity] = result;

                if (result.Complete && !context.CollectionIndexerProof)
                {
                    completeCleanupValueFlows.TryAdd(
                        completeCacheIdentity,
                        result);
                }
            }

            return result;
        }

        private CleanupValueFlow CleanupValueFlowCore(
            AuthoredMember member,
            ExpressionSyntax expression,
            CleanupProvenanceContext context)
        {
            if (context.CollectionIndexerProof)
            {
                ISymbol? storage = member.Model.GetSymbolInfo(expression).Symbol;

                if (storage is ILocalSymbol authoredOutLocal
                    && authoredOutLocal.DeclaringSyntaxReferences
                        .SingleOrDefault()?.GetSyntax() is
                        SingleVariableDesignationSyntax designation
                    && ExactAuthoredOutLocalCleanupValueFlow(
                        member,
                        expression,
                        authoredOutLocal,
                        designation,
                        context) is { } authoredOutFlow)
                {
                    return authoredOutFlow;
                }

                // Lexically later writes can reach this use through loop back-edges,
                // including writes in invoked callbacks and local functions.
                if (storage is IParameterSymbol parameter
                    && (parameter.RefKind != RefKind.None
                        || HasCollectionValueReplacement(
                            member,
                            parameter,
                            rejectElementWrites: false))
                    || storage is ILocalSymbol collectionLocal
                        && HasCollectionValueReplacement(member, collectionLocal, rejectElementWrites: false))
                {
                    return new([], false, true);
                }

                if (storage is IFieldSymbol { IsReadOnly: false }
                    || storage is IFieldSymbol readonlyStorage
                        && readonlyStorage.ContainingType.DeclaringSyntaxReferences.Any(reference =>
                            HasCollectionValueReplacement(
                                member with { Model = semanticModels[reference.SyntaxTree] },
                                readonlyStorage,
                                rejectSimpleAssignment: false))
                    || storage is IPropertySymbol { SetMethod.IsInitOnly: false }
                    || storage is IFieldSymbol && expression is MemberAccessExpressionSyntax
                    { Expression: not ThisExpressionSyntax } fieldAccess
                        && member.Model.GetSymbolInfo(fieldAccess.Expression).Symbol is not INamedTypeSymbol)
                {
                    return new([], false, true);
                }

                if (storage is ILocalSymbol iteration
                    && iteration.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                        is ForEachStatementSyntax loop)
                {
                    return CollectionElementValueFlow(member, loop.Expression, context);
                }

                if (expression is ElementAccessExpressionSyntax element)
                {
                    return CollectionElementValueFlow(member, element.Expression, context);
                }

                if (IsExactFrameworkCollectionMaterialization(member, expression)
                    || member.Model.GetTypeInfo(expression).Type is IArrayTypeSymbol)
                {
                    return new([new(member, expression)], true, false);
                }

                if (storage is IFieldSymbol { IsStatic: true, IsReadOnly: true }
                    or IPropertySymbol { IsStatic: true, SetMethod: null })
                {
                    return StableCollectionStorageValueFlow(member, storage, context);
                }
            }

            if (expression is AwaitExpressionSyntax awaited)
            {
                ExpressionSyntax awaitedSource = StripTransparentExpression(
                    awaited.Expression);

                if (awaitedSource is InvocationExpressionSyntax configured
                    && member.Model.GetSymbolInfo(configured).Symbol is
                        IMethodSymbol configuredMethod
                    && IsExactFrameworkConfigureAwait(configuredMethod)
                    && configured.Expression is MemberAccessExpressionSyntax
                    {
                        Expression: { } unconfigured,
                    })
                {
                    awaitedSource = unconfigured;
                }

                return CleanupValueFlowOf(
                    member,
                    awaitedSource,
                    context);
            }

            if (expression is ConditionalExpressionSyntax conditional)
            {
                return MergeCleanupValueFlow([
                    CleanupValueFlowOf(member, conditional.WhenTrue, context),
                    CleanupValueFlowOf(member, conditional.WhenFalse, context),
                ]);
            }

            if (expression is BinaryExpressionSyntax coalescing
                && coalescing.IsKind(SyntaxKind.CoalesceExpression))
            {
                return MergeCleanupValueFlow([
                    CleanupValueFlowOf(member, coalescing.Left, context),
                    CleanupValueFlowOf(member, coalescing.Right, context),
                ]);
            }

            if (expression is SwitchExpressionSyntax selection)
            {
                return MergeCleanupValueFlow(selection.Arms.Select(arm =>
                    CleanupValueFlowOf(member, arm.Expression, context)));
            }

            if (expression is ThrowExpressionSyntax
                || IsSemanticallyEmptyCleanupValue(
                    member.Model,
                    expression))
            {
                return new([], true, false);
            }

            if (expression is BaseObjectCreationExpressionSyntax)
            {
                return new([new(member, expression)], true, true);
            }

            ISymbol? symbol = member.Model.GetSymbolInfo(expression).Symbol;

            if (expression is InvocationExpressionSyntax completedTask
                && symbol is IMethodSymbol completedTaskMethod
                && ExactCompletedResultValue(
                    member,
                    completedTask,
                    completedTaskMethod) is { } completedValue)
            {
                return CleanupValueFlowOf(
                    member,
                    completedValue,
                    context);
            }

            if (expression is InvocationExpressionSyntax configuredCleanup
                && symbol is IMethodSymbol configuredCleanupMethod
                && IsExactFrameworkMethod(
                    configuredCleanupMethod,
                    "System.Threading.Tasks.TaskAsyncEnumerableExtensions",
                    "ConfigureAwait",
                    "System.Private.CoreLib")
                && configuredCleanup.Expression is
                    MemberAccessExpressionSyntax
                {
                    Expression: { } unconfiguredCleanup,
                })
            {
                return CleanupValueFlowOf(
                    member,
                    unconfiguredCleanup,
                    context);
            }

            if (symbol is IParameterSymbol or IPropertySymbol or IFieldSymbol
                && CanUseCurrentInstanceStorageBinding(symbol, expression)
                && member.ValueBindings?.TryGetValue(
                    symbol,
                    out BoundValueSource? bound) == true
                && bound is not null)
            {
                return CleanupValueFlowOf(
                    bound.Caller,
                    bound.Expression,
                    context);
            }

            if (symbol is IParameterSymbol optionalDependency
                && TryExactAbsentOptionalDiDefault(
                    member,
                    optionalDependency,
                    out BoundValueSource optionalDefault))
            {
                return CleanupValueFlowOf(
                    optionalDefault.Caller,
                    optionalDefault.Expression,
                    context);
            }

            if (expression is InvocationExpressionSyntax sdkFactory
                && symbol is IMethodSymbol sdkFactoryMethod
                && (IsExactSdkClientFactory(sdkFactoryMethod)
                    || IsExactChatSdkAdapterFactory(sdkFactoryMethod)
                    || IsExactEmbeddingSdkAdapterFactory(sdkFactoryMethod)))
            {
                return new([new(member, sdkFactory)], true, false);
            }

            if (expression is InvocationExpressionSyntax interfaceFactory
                && symbol is IMethodSymbol
                {
                    ContainingType.TypeKind: TypeKind.Interface,
                } interfaceMethod
                && ExactSelectedInterfaceFactoryValues(
                    member,
                    interfaceFactory,
                    interfaceMethod,
                    context) is { } selectedFactoryValues)
            {
                return selectedFactoryValues;
            }

            if (expression is InvocationExpressionSyntax absentCall
                && symbol is IMethodSymbol { MethodKind: MethodKind.DelegateInvoke }
                && member.Model.GetSymbolInfo(DelegateReceiver(member, absentCall)).Symbol is { } absentSeam
                && IsProvenAbsentCallable(absentSeam))
            {
                return new([], true, false);
            }

            if (expression is InvocationExpressionSyntax call
                && symbol is IMethodSymbol method
                && ResolveCleanupInvocationTarget(
                    method,
                    member,
                    call,
                    context) is { } target)
            {
                AuthoredMember factory = BindCleanupInvocationContext(
                    member,
                    call,
                    target,
                    context,
                    method.MethodKind == MethodKind.DelegateInvoke);

                ExpressionSyntax[] returned = ReturnedExpressions(
                    factory.Syntax);

                (factory, returned) = ExactSqlitePatternArmReturns(
                    factory,
                    returned,
                    context);

                if (returned.Length == 0)
                {
                    return new([], false, true);
                }

                CleanupValueFlow result = MergeCleanupValueFlow(
                    returned.Select(value => CleanupReturnedValueFlow(
                        factory,
                        value,
                        context)));

                return result with
                {
                    HasAuthoredSource = true,
                };
            }

            if (expression is InvocationExpressionSyntax optionsSubscription
                && symbol is IMethodSymbol optionsSubscriptionMethod
                && IsExactFrameworkMethod(
                    optionsSubscriptionMethod,
                    "Microsoft.Extensions.Options.IOptionsMonitor`1",
                    "OnChange",
                    "Microsoft.Extensions.Options")
                && IsExactFrameworkType(
                    optionsSubscriptionMethod.ReturnType,
                    "System.IDisposable",
                    typeof(IDisposable).Assembly.GetName()))
            {
                return new([new(member, optionsSubscription)], true, false);
            }

            if (symbol is ILocalSymbol local)
            {
                return LocalCleanupValueFlow(
                    member,
                    expression,
                    local,
                    context);
            }

            if (symbol is IPropertySymbol sameInstanceProperty
                && ExactSameInstancePropertyValueFlow(
                    member,
                    expression,
                    sameInstanceProperty,
                    context) is { } sameInstancePropertyFlow)
            {
                return sameInstancePropertyFlow;
            }

            if (expression is ConditionalAccessExpressionSyntax conditionalAccess
                && DirectConditionalAccessProperty(
                    member,
                    conditionalAccess) is { } conditionalProperty
                && ExactAssignedPropertyReceiverValueFlow(
                    member,
                    conditionalAccess.Expression,
                    conditionalProperty,
                    context) is { } conditionalPropertyFlow)
            {
                return conditionalPropertyFlow;
            }

            if (expression is MemberAccessExpressionSyntax propertyAccess
                && symbol is IPropertySymbol property)
            {
                CleanupValueFlow? propertyFlow =
                    ExactFailureGuardedSuccessfulValueFlow(
                        member,
                        propertyAccess,
                        property,
                        context)
                    ?? ExactAssignedPropertyValueFlow(
                        member,
                        propertyAccess,
                        property,
                        context);

                if (propertyFlow is not null)
                {
                    return propertyFlow;
                }
            }

            if (symbol is IFieldSymbol boundField
                && CanUseCurrentInstanceStorageBinding(symbol, expression)
                && member.ValueBindings?.TryGetValue(
                    boundField,
                    out BoundValueSource? fieldValue) == true
                && fieldValue is not null)
            {
                return CleanupValueFlowOf(
                    fieldValue.Caller,
                    fieldValue.Expression,
                    context);
            }

            if (symbol is IFieldSymbol field
                && ExactAssignedFieldCleanupValueFlow(
                    member,
                    expression,
                    field,
                    context) is { } fieldFlow)
            {
                return fieldFlow;
            }

            ITypeSymbol? type = member.Model.GetTypeInfo(expression).Type;

            if (type is INamedTypeSymbol
                {
                    TypeKind: TypeKind.Struct,
                } or INamedTypeSymbol
                {
                    TypeKind: TypeKind.Class,
                    IsAbstract: false,
                    IsSealed: true,
                })
            {
                return new(
                    [new(member, expression)],
                    true,
                    type is not null
                        && IsAuthoredCleanupSymbol(
                            type,
                            member.Model.Compilation));
            }

            return new(
                [],
                false,
                symbol is not null
                    && IsAuthoredCleanupSymbol(
                        symbol,
                        member.Model.Compilation));
        }

        private CleanupValueFlow? ExactSelectedInterfaceFactoryValues(
            AuthoredMember member,
            InvocationExpressionSyntax call,
            IMethodSymbol method,
            CleanupProvenanceContext context)
        {
            ITypeSymbol effectiveReturnType = method.ReturnType;

            if (effectiveReturnType is INamedTypeSymbol
                {
                    TypeArguments: [ITypeSymbol awaited],
                } awaitable
                && TypeKey(awaitable.OriginalDefinition) is
                    "System.Threading.Tasks.Task`1"
                        or "System.Threading.Tasks.ValueTask`1")
            {
                effectiveReturnType = awaited;
            }

            if (effectiveReturnType is not INamedTypeSymbol
                {
                    TypeKind: TypeKind.Class,
                    IsSealed: true,
                }
                || !IsAuthoredCleanupSymbol(
                    effectiveReturnType,
                    member.Model.Compilation)
                || AdmissionReceiver(member, call) is not { } receiver)
            {
                return null;
            }

            CleanupValueFlow receivers =
                ExactStaticSingletonInterfaceFactoryReceiverValueFlow(
                    member,
                    receiver,
                    method.ContainingType,
                    context)
                ?? CleanupValueFlowOf(
                    member,
                    receiver,
                    context);

            if (!receivers.Complete || receivers.Values.Count == 0)
            {
                return null;
            }

            List<CleanupValueFlow> results = [];

            foreach (BoundValueSource source in receivers.Values)
            {
                if (StripTransparentExpression(source.Expression) is not
                        BaseObjectCreationExpressionSyntax creation
                    || source.Caller.Model.GetTypeInfo(creation).Type is not
                        INamedTypeSymbol
                        {
                            IsSealed: true,
                            IsAbstract: false,
                        } concrete
                    || !IsAuthoredCleanupSymbol(
                        concrete,
                        source.Caller.Model.Compilation))
                {
                    return new([], false, true);
                }

                IMethodSymbol[] implementations = concrete.AllInterfaces
                    .Where(contract =>
                        contract.ContainingAssembly.Identity.Equals(
                            method.ContainingAssembly.Identity)
                        && TypeKey(contract)
                            == TypeKey(method.ContainingType))
                    .SelectMany(static contract => contract.GetMembers())
                    .OfType<IMethodSymbol>()
                    .Where(slot => MethodKey(slot) == MethodKey(method))
                    .Select(slot =>
                        concrete.FindImplementationForInterfaceMember(slot))
                    .OfType<IMethodSymbol>()
                    .DistinctBy(
                        static implementation =>
                            implementation.OriginalDefinition,
                        SymbolEqualityComparer.Default)
                    .ToArray();

                if (implementations is not
                        [IMethodSymbol implementation]
                    || Resolve(
                        implementation,
                        source.Caller.Model.Compilation) is not { } target)
                {
                    return new([], false, true);
                }

                AuthoredMember factory = BindCleanupInvocationContext(
                    member,
                    call,
                    target,
                    context,
                    selectedReceiver: source);

                ExpressionSyntax[] returned = ReturnedExpressions(
                    factory.Syntax);

                if (returned.Length == 0)
                {
                    return new([], false, true);
                }

                CleanupValueFlow result = MergeCleanupValueFlow(
                    returned.Select(value => CleanupReturnedValueFlow(
                        factory,
                        value,
                        context)));

                if (!result.Complete)
                {
                    return new([], false, true);
                }

                results.Add(result);
            }

            return MergeCleanupValueFlow(results) with
            {
                HasAuthoredSource = true,
            };
        }

        private CleanupValueFlow?
            ExactStaticSingletonInterfaceFactoryReceiverValueFlow(
                AuthoredMember member,
                ExpressionSyntax receiver,
                INamedTypeSymbol contract,
                CleanupProvenanceContext context)
        {
            receiver = StripTransparentExpression(receiver);

            if (member.Model.GetSymbolInfo(receiver).Symbol is not
                    IPropertySymbol
                    {
                        IsStatic: true,
                        SetMethod: null,
                        Parameters.Length: 0,
                        DeclaredAccessibility: Accessibility.Private
                            or Accessibility.Internal,
                        DeclaringSyntaxReferences:
                            [SyntaxReference propertyReference],
                    } property
                || !SameBoundType(
                    property.Type,
                    member.Model.Compilation,
                    contract,
                    member.Model.Compilation)
                || propertyReference.GetSyntax() is not
                    PropertyDeclarationSyntax
                    {
                        Initializer.Value:
                            BaseObjectCreationExpressionSyntax initializer,
                        AccessorList.Accessors: var accessors,
                    }
                || accessors.Count != 1
                || accessors[0] is not
                    {
                        RawKind: (int)SyntaxKind.GetAccessorDeclaration,
                        Body: null,
                        ExpressionBody: null,
                    }
                || !semanticModels.TryGetValue(
                    initializer.SyntaxTree,
                    out SemanticModel? model)
                || !ReferenceEquals(model.Compilation, member.Model.Compilation)
                || model.GetOperation(initializer) is not
                    IObjectCreationOperation
                    {
                        Arguments.Length: 0,
                        Initializer: null,
                        Type: INamedTypeSymbol
                            {
                                IsSealed: true,
                                IsAbstract: false,
                                DeclaredAccessibility: Accessibility.Private,
                            } created,
                    }
                || !SymbolEqualityComparer.Default.Equals(
                    created.ContainingType,
                    property.ContainingType)
                || !created.AllInterfaces.Any(candidate => SameBoundType(
                    candidate,
                    model.Compilation,
                    contract,
                    member.Model.Compilation)))
            {
                return null;
            }

            CleanupValueFlow flow = CleanupValueFlowOf(
                ValueExpressionContext(member, initializer, model),
                initializer,
                context);

            return flow.Complete
                ? flow with
                {
                    HasAuthoredSource = true,
                }
                : new([], false, true);
        }

        private CleanupValueFlow? ExactFailureGuardedSuccessfulValueFlow(
            AuthoredMember member,
            MemberAccessExpressionSyntax access,
            IPropertySymbol property,
            CleanupProvenanceContext context)
        {
            if (property.Name != "Value"
                || !IsFailureGuardedSuccessfulValueAccess(member, access)
                || member.Model.GetSymbolInfo(access.Expression).Symbol is not
                    ILocalSymbol result
                || result.DeclaringSyntaxReferences.SingleOrDefault()
                    ?.GetSyntax() is not
                    VariableDeclaratorSyntax
                    {
                        Initializer.Value: { } initializer,
                    })
            {
                return null;
            }

            ExpressionSyntax source = StripTransparentExpression(initializer);

            if (source is AwaitExpressionSyntax awaited)
            {
                source = StripTransparentExpression(awaited.Expression);
            }

            if (source is InvocationExpressionSyntax configured
                && member.Model.GetSymbolInfo(configured).Symbol is
                    IMethodSymbol configuredMethod
                && IsExactFrameworkConfigureAwait(configuredMethod)
                && configured.Expression is MemberAccessExpressionSyntax
                {
                    Expression: { } unconfigured,
                })
            {
                source = StripTransparentExpression(unconfigured);
            }

            if (source is not InvocationExpressionSyntax call
                || member.Model.GetSymbolInfo(call).Symbol is not
                    IMethodSymbol method)
            {
                return null;
            }

            CleanupValueFlow possibleResults;

            if (method.ContainingType.TypeKind == TypeKind.Interface
                && ExactSelectedInterfaceFactoryValues(
                    member,
                    call,
                    method,
                    context) is { } selectedInterfaceResults)
            {
                possibleResults = selectedInterfaceResults;
            }
            else
            {
                if (ResolveCleanupInvocationTarget(
                        method,
                        member,
                        call,
                        context) is not { } target)
                {
                    return null;
                }

                AuthoredMember factory = BindCleanupInvocationContext(
                    member,
                    call,
                    target,
                    context,
                    method.MethodKind == MethodKind.DelegateInvoke);

                ExpressionSyntax[] returned = ReturnedExpressions(
                    factory.Syntax);

                if (returned.Length == 0)
                {
                    return null;
                }

                possibleResults = MergeCleanupValueFlow(
                    returned.Select(value => CleanupReturnedValueFlow(
                        factory,
                        value,
                        context)));
            }

            if (!possibleResults.Complete
                || possibleResults.Values.Count == 0)
            {
                return null;
            }

            List<BoundValueSource> successful = [];

            foreach (BoundValueSource possible in possibleResults.Values)
            {
                ExpressionSyntax possibleExpression =
                    ExactNonThrowingValue(possible.Expression);

                ITypeSymbol? possibleType = possible.Caller.Model
                    .GetTypeInfo(possibleExpression).Type;

                if (possibleType is not null
                    && SameBoundType(
                        possibleType,
                        possible.Caller.Model.Compilation,
                        property.Type,
                        member.Model.Compilation))
                {
                    successful.Add(possible);

                    continue;
                }

                CleanupValueFlow? projected =
                    ExactGuardedResultValueConstructionFlow(
                        possible,
                        property,
                        context);

                if (projected is null || !projected.Complete)
                {
                    return null;
                }

                successful.AddRange(projected.Values);
            }

            return successful.Count == 0
                ? null
                : new(successful, true, true);
        }

        private CleanupValueFlow? ExactGuardedResultValueConstructionFlow(
            BoundValueSource possible,
            IPropertySymbol valueProperty,
            CleanupProvenanceContext context)
        {
            ExpressionSyntax expression =
                ExactNonThrowingValue(possible.Expression);

            if (expression is not BaseObjectCreationExpressionSyntax creation
                || possible.Caller.Model.GetSymbolInfo(creation).Symbol is not
                    IMethodSymbol
                    {
                        MethodKind: MethodKind.Constructor,
                        IsStatic: false,
                        Parameters: [IParameterSymbol parameter],
                    } constructor
                || valueProperty.ContainingType is not
                    INamedTypeSymbol
                    {
                        IsSealed: true,
                        OriginalDefinition.TypeParameters:
                            [ITypeParameterSymbol valueTypeParameter],
                    } wrapper
                || !SameBoundTypeOrGenericDefinition(
                    constructor.ContainingType,
                    wrapper,
                    possible.Caller.Model.Compilation)
                || constructor.OriginalDefinition.Parameters is not
                    [IParameterSymbol originalParameter])
            {
                return null;
            }

            if (originalParameter.Type is not ITypeParameterSymbol
                {
                    TypeParameterKind: TypeParameterKind.Type,
                } constructorTypeParameter
                || constructorTypeParameter.Ordinal != valueTypeParameter.Ordinal)
            {
                // The preceding exact IsFailure guard excludes authenticated
                // non-success wrapper constructions from the Value access.
                return new([], true, true);
            }

            (ExpressionSyntax Expression, IParameterSymbol? Parameter, RefKind RefKind)[] arguments =
                ConstructorArguments(possible.Caller, creation)
                    .Where(argument => argument.Parameter?.Ordinal
                        == parameter.Ordinal)
                    .ToArray();

            if (arguments is not [var argument]
                || argument.RefKind != RefKind.None)
            {
                return null;
            }

            CleanupValueFlow projected = CleanupValueFlowOf(
                possible.Caller,
                argument.Expression,
                context);

            if (!projected.Complete
                || projected.Values.Count == 0
                || projected.Values.Any(value =>
                    value.Caller.Model.GetTypeInfo(
                        ExactNonThrowingValue(value.Expression)).Type is not
                        { } valueType
                    || !SameBoundType(
                        valueType,
                        value.Caller.Model.Compilation,
                        valueProperty.Type,
                        possible.Caller.Model.Compilation)))
            {
                return null;
            }

            return projected;
        }

        private static bool HasCollectionValueReplacement(
            AuthoredMember member,
            ISymbol symbol,
            bool rejectSimpleAssignment = true,
            bool rejectElementWrites = true)
        {
            bool RefersTo(SyntaxNode node) => node.DescendantNodesAndSelf()
                .OfType<ExpressionSyntax>()
                .Any(expression => SymbolEqualityComparer.Default.Equals(
                    member.Model.GetSymbolInfo(expression).Symbol, symbol));

            return member.Model.SyntaxTree.GetRoot().DescendantNodes().Any(node => node switch
            {
                AssignmentExpressionSyntax assignment
                    when rejectElementWrites || assignment.Left is not ElementAccessExpressionSyntax => RefersTo(assignment.Left)
                    && (rejectSimpleAssignment
                        || !assignment.IsKind(SyntaxKind.SimpleAssignmentExpression)
                        || assignment.Left is TupleExpressionSyntax),
                ArgumentSyntax argument when argument.RefKindKeyword.Kind() is
                    SyntaxKind.RefKeyword or SyntaxKind.OutKeyword => RefersTo(argument.Expression),
                RefExpressionSyntax reference => RefersTo(reference.Expression),
                _ => false,
            });
        }

        private CleanupValueFlow? ExactPopulatedListElementValueFlow(
            AuthoredMember member,
            ExpressionSyntax use,
            ILocalSymbol local,
            CleanupProvenanceContext context)
        {
            if (local.Type is not INamedTypeSymbol localType
                || !IsExactFrameworkType(
                    localType,
                    "System.Collections.Generic.List`1",
                    typeof(List<>).Assembly.GetName())
                || local.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                    is not VariableDeclaratorSyntax
                    {
                        Initializer.Value: { } initializer,
                    }
                || (member.Model.GetTypeInfo(initializer).Type
                    ?? member.Model.GetTypeInfo(initializer).ConvertedType)
                    is not INamedTypeSymbol initializerType
                || !IsExactFrameworkType(
                    initializerType,
                    "System.Collections.Generic.List`1",
                    typeof(List<>).Assembly.GetName()))
            {
                return null;
            }

            bool empty = initializer is CollectionExpressionSyntax
            {
                Elements.Count: 0,
            }
                || initializer is BaseObjectCreationExpressionSyntax
                    && member.Model.GetOperation(initializer) is
                        IObjectCreationOperation
                    {
                        Arguments.Length: 0,
                        Initializer: null,
                    };

            if (!empty || use.Parent is not ReturnStatementSyntax)
            {
                return new([], false, true);
            }

            List<ExpressionSyntax> added = [];

            foreach (IdentifierNameSyntax reference in member.Syntax
                .DescendantNodesAndSelf()
                .OfType<IdentifierNameSyntax>()
                .Where(reference => SymbolEqualityComparer.Default.Equals(
                    member.Model.GetSymbolInfo(reference).Symbol,
                    local)))
            {
                if (reference.Span == use.Span)
                {
                    continue;
                }

                if (reference.Parent is not MemberAccessExpressionSyntax
                    {
                        Expression: { } receiver,
                        Parent: InvocationExpressionSyntax call,
                    }
                    || receiver != reference
                    || member.Model.GetSymbolInfo(call).Symbol is not
                        IMethodSymbol method
                    || method.Name != "Add"
                    || !IsExactFrameworkType(
                        method.ContainingType,
                        "System.Collections.Generic.List`1",
                        typeof(List<>).Assembly.GetName())
                    || call.ArgumentList.Arguments is not
                        [ArgumentSyntax { Expression: { } value }])
                {
                    return new([], false, true);
                }

                added.Add(value);
            }

            if (added.Count == 0)
            {
                return new([], false, true);
            }

            CleanupValueFlow result = MergeCleanupValueFlow(
                added.Select(value => CleanupValueFlowOf(
                    member,
                    value,
                    context)));

            return result with
            {
                HasAuthoredSource = true,
            };
        }

        private CleanupValueFlow? ExactFrameworkDictionaryRemovedValueFlow(
            AuthoredMember member,
            ExpressionSyntax use,
            ILocalSymbol local,
            SingleVariableDesignationSyntax? designation,
            CleanupProvenanceContext context,
            VariableDeclaratorSyntax? existingVariable = null)
        {
            bool completeSources = true;

            ArgumentSyntax? removedArgument = designation is not null
                ? designation.Ancestors().OfType<ArgumentSyntax>()
                    .FirstOrDefault()
                : member.Syntax.DescendantNodesAndSelf()
                    .OfType<ArgumentSyntax>()
                    .Where(candidate => candidate.RefKindKeyword.IsKind(
                            SyntaxKind.OutKeyword)
                        && candidate.SpanStart < use.SpanStart
                        && SymbolEqualityComparer.Default.Equals(
                            member.Model.GetSymbolInfo(
                                candidate.Expression).Symbol,
                            local))
                    .SingleOrDefault();

            if (removedArgument is not
                {
                    RefKindKeyword.RawKind: (int)SyntaxKind.OutKeyword,
                    Parent.Parent: InvocationExpressionSyntax call,
                } argument
                || member.Model.GetOperation(call) is not
                    IInvocationOperation
                {
                    Instance.Syntax: ExpressionSyntax dictionary,
                    TargetMethod:
                    {
                        Name: "TryRemove" or "TryGetValue",
                    } method,
                } operation
                || !IsExactFrameworkType(
                    method.ContainingType,
                    "System.Collections.Concurrent.ConcurrentDictionary`2",
                    typeof(System.Collections.Concurrent.ConcurrentDictionary<,>)
                        .Assembly.GetName())
                || operation.Arguments.SingleOrDefault(candidate =>
                        candidate.Syntax == argument) is not
                    IArgumentOperation
                        {
                            Parameter.Ordinal: 1,
                        }
                || designation is not null
                    && call.Ancestors().OfType<IfStatementSyntax>()
                        .FirstOrDefault(selection =>
                            ProvesCallTrue(selection.Condition, call)
                            && selection.Statement.Span.Contains(use.Span))
                        is null
                || designation is null
                    && (existingVariable?.Initializer is not
                    { Value: { } emptyInitializer }
                        || !IsSemanticallyEmptyCleanupValue(
                            member.Model,
                            emptyInitializer)
                        || member.Syntax.DescendantNodesAndSelf().Any(node =>
                            node.SpanStart >= existingVariable.Span.End
                                && node.SpanStart < call.SpanStart
                                && node switch
                                {
                                    AssignmentExpressionSyntax assignment =>
                                        SymbolEqualityComparer.Default.Equals(
                                            member.Model.GetSymbolInfo(
                                                assignment.Left).Symbol,
                                            local),
                                    ArgumentSyntax earlierArgument
                                        when earlierArgument.RefKindKeyword.Kind()
                                            is SyntaxKind.RefKeyword
                                                or SyntaxKind.OutKeyword =>
                                        SymbolEqualityComparer.Default.Equals(
                                            member.Model.GetSymbolInfo(
                                                earlierArgument.Expression)
                                                .Symbol,
                                            local),
                                    RefExpressionSyntax alias =>
                                        SymbolEqualityComparer.Default.Equals(
                                            member.Model.GetSymbolInfo(
                                                alias.Expression).Symbol,
                                            local),
                                    _ => false,
                                }))
                || !SymbolIsStableWithin(
                    member,
                    local,
                    call.Span.End,
                    use.SpanStart)
                || member.Model.GetSymbolInfo(dictionary).Symbol is not
                    IFieldSymbol
                {
                    IsReadOnly: true,
                    DeclaredAccessibility: Accessibility.Private,
                } storage
                || !SymbolEqualityComparer.Default.Equals(
                    storage.ContainingType,
                    member.Symbol.ContainingType))
            {
                return null;
            }

            List<BoundValueSource> sources = [];

            foreach (SyntaxReference reference in storage.DeclaringSyntaxReferences)
            {
                if (reference.GetSyntax() is not VariableDeclaratorSyntax
                    {
                        Initializer.Value: BaseObjectCreationExpressionSyntax
                            initializer,
                    }
                    || member.Model.Compilation.GetSemanticModel(
                            initializer.SyntaxTree).GetOperation(initializer) is not
                        IObjectCreationOperation
                            {
                                Arguments.Length: 0,
                                Initializer: null,
                            } creation
                    || !IsExactFrameworkType(
                        creation.Type,
                        "System.Collections.Concurrent.ConcurrentDictionary`2",
                        typeof(System.Collections.Concurrent.ConcurrentDictionary<,>)
                            .Assembly.GetName()))
                {
                    return new([], false, true);
                }
            }

            foreach (SyntaxReference reference in
                storage.ContainingType.DeclaringSyntaxReferences)
            {
                SyntaxNode declaration = reference.GetSyntax();

                if (!semanticModels.TryGetValue(
                        declaration.SyntaxTree,
                        out SemanticModel? model))
                {
                    return new([], false, true);
                }

                foreach (ExpressionSyntax storageUse in declaration
                    .DescendantNodesAndSelf()
                    .OfType<ExpressionSyntax>()
                    .Where(candidate => SymbolEqualityComparer.Default.Equals(
                            model.GetSymbolInfo(candidate).Symbol,
                            storage)
                        && (candidate.Parent is not ExpressionSyntax parent
                            || !SymbolEqualityComparer.Default.Equals(
                                model.GetSymbolInfo(parent).Symbol,
                                storage))))
                {
                    if (storageUse is not IdentifierNameSyntax
                        and not MemberAccessExpressionSyntax
                        {
                            Expression: ThisExpressionSyntax,
                        })
                    {
                        return new([], false, true);
                    }

                    bool reviewed = false;

                    if (storageUse.Parent is MemberAccessExpressionSyntax
                        {
                            Expression: { } receiver,
                            Parent: InvocationExpressionSyntax storageCall,
                        }
                        && receiver == storageUse
                        && model.GetOperation(storageCall) is
                            IInvocationOperation storageOperation
                        && IsExactFrameworkType(
                            storageOperation.TargetMethod.ContainingType,
                            "System.Collections.Concurrent.ConcurrentDictionary`2",
                            typeof(System.Collections.Concurrent.ConcurrentDictionary<,>)
                                .Assembly.GetName()))
                    {
                        reviewed = CollectDictionaryInvocationSource(
                            member,
                            model,
                            storageOperation,
                            sources);
                    }
                    else if (storageUse.Parent is ForEachStatementSyntax loop
                        && loop.Expression == storageUse)
                    {
                        reviewed = true;
                    }
                    else if (storageUse.Parent is ElementAccessExpressionSyntax element
                        && element.Expression == storageUse
                        && element.Parent is AssignmentExpressionSyntax assignment
                        && assignment.Left == element
                        && assignment.IsKind(
                            SyntaxKind.SimpleAssignmentExpression))
                    {
                        reviewed = CollectDictionaryValueSource(
                            member,
                            model,
                            assignment.Right,
                            sources);
                    }

                    if (!reviewed)
                    {
                        return new([], false, true);
                    }
                }
            }

            if (sources.Count == 0)
            {
                return new([], false, true);
            }

            CleanupValueFlow result = MergeCleanupValueFlow(
                sources.Select(source => CleanupValueFlowOf(
                    source.Caller,
                    source.Expression,
                    context)));

            return result with
            {
                Complete = completeSources && result.Complete,
                HasAuthoredSource = true,
            };

            bool CollectDictionaryInvocationSource(
                AuthoredMember caller,
                SemanticModel model,
                IInvocationOperation invocation,
                List<BoundValueSource> values)
            {
                if (invocation.TargetMethod.Name is
                    "TryRemove" or "TryGetValue" or "ContainsKey")
                {
                    return true;
                }

                if (invocation.TargetMethod.Name != "TryAdd"
                    || invocation.Arguments.SingleOrDefault(candidate =>
                            candidate.Parameter?.Ordinal == 1) is not
                        IArgumentOperation
                            {
                                Value.Syntax: ExpressionSyntax value,
                            })
                {
                    return false;
                }

                return CollectDictionaryValueSource(
                    caller,
                    model,
                    value,
                    values);
            }

            bool CollectDictionaryValueSource(
                AuthoredMember caller,
                SemanticModel model,
                ExpressionSyntax value,
                List<BoundValueSource> values)
            {
                if (model.GetEnclosingSymbol(value.SpanStart) is not
                        IMethodSymbol enclosing
                    || Resolve(enclosing, model.Compilation) is not
                    { } sourceMember)
                {
                    return false;
                }

                AuthoredMember sourceContext = SymbolEqualityComparer.Default.Equals(
                        enclosing.OriginalDefinition,
                        caller.Symbol.OriginalDefinition)
                    ? caller
                    : sourceMember;

                if (model.GetSymbolInfo(
                        StripTransparentExpression(value)).Symbol is
                    IParameterSymbol parameter
                    && parameter.RefKind == RefKind.None
                    && parameter.Ordinal >= 0
                    && parameter.Ordinal < sourceMember.Symbol.Parameters.Length
                    && SymbolEqualityComparer.Default.Equals(
                        parameter.ContainingSymbol.OriginalDefinition,
                        sourceMember.Symbol.OriginalDefinition))
                {
                    CleanupValueFlow closed = ClosedWriterParameterValueFlow(
                        caller,
                        sourceMember,
                        sourceMember.Symbol.Parameters[parameter.Ordinal],
                        context,
                        0,
                        []);

                    values.AddRange(closed.Values);

                    completeSources &= closed.Complete;

                    return true;
                }

                values.Add(new(
                    ValueExpressionContext(sourceContext, value, model),
                    value));

                return true;
            }
        }

        private CleanupValueFlow ClosedWriterParameterValueFlow(
            AuthoredMember authenticatedOwner,
            AuthoredMember writer,
            IParameterSymbol parameter,
            CleanupProvenanceContext context,
            int depth,
            HashSet<ClosedWriterParameterIdentity> active,
            bool allowInternalAssemblyWriter = false)
        {
            EvaluationEnvironmentFingerprint environment =
                EvaluationEnvironmentIdentity(authenticatedOwner);

            static CleanupValueFlow Reject() => new([], false, true);

            ClosedWriterParameterIdentity identity = new(
                MemberIdentity(writer),
                parameter.Ordinal,
                environment.Identity);

            bool exactAccessibility = writer.Symbol.DeclaredAccessibility
                    == Accessibility.Private
                || allowInternalAssemblyWriter
                    && writer.Symbol.DeclaredAccessibility
                        == Accessibility.Internal;

            if (context.RemainingWork-- <= 0
                || depth >= ReceiverCleanupForwardingMaximumDepth
                || !environment.Complete
                || environment.ContainsBackreference
                || parameter.RefKind != RefKind.None
                || parameter.Ordinal < 0
                || parameter.Ordinal >= writer.Symbol.Parameters.Length
                || !SymbolEqualityComparer.Default.Equals(
                    parameter.OriginalDefinition,
                    writer.Symbol.Parameters[parameter.Ordinal]
                        .OriginalDefinition)
                || !exactAccessibility
                || writer.Symbol.MethodKind is not MethodKind.Ordinary
                || writer.Symbol.IsAbstract
                || writer.Symbol.IsVirtual
                || writer.Symbol.IsOverride
                || writer.Symbol.ContainingType is not
                    {
                        IsSealed: true,
                    }
                || !active.Add(identity))
            {
                return Reject();
            }

            try
            {
                List<(SyntaxNode Declaration, SemanticModel Model)> domains = [];

                if (allowInternalAssemblyWriter)
                {
                    foreach (SyntaxTree tree in writer.Model.Compilation.SyntaxTrees)
                    {
                        if (!semanticModels.TryGetValue(
                                tree,
                                out SemanticModel? model)
                            || !ReferenceEquals(
                                model.Compilation,
                                writer.Model.Compilation))
                        {
                            model = writer.Model.Compilation.GetSemanticModel(tree);
                        }

                        domains.Add((tree.GetRoot(), model));
                    }

                    if (invocations.Any(candidate =>
                        !ReferenceEquals(
                            candidate.Model.Compilation,
                            writer.Model.Compilation)
                        && candidate.Model.GetOperation(candidate.Call) is
                            IInvocationOperation externalOperation
                        && externalOperation.TargetMethod.ContainingAssembly
                            .Identity.Equals(
                                writer.Symbol.ContainingAssembly.Identity)
                        && MethodKey(externalOperation.TargetMethod)
                            == MethodKey(writer.Symbol)))
                    {
                        return Reject();
                    }
                }
                else
                {
                    foreach (SyntaxReference reference in
                        writer.Symbol.ContainingType.DeclaringSyntaxReferences)
                    {
                        SyntaxNode declaration = reference.GetSyntax();

                        if (!semanticModels.TryGetValue(
                                declaration.SyntaxTree,
                                out SemanticModel? model))
                        {
                            return Reject();
                        }

                        domains.Add((declaration, model));
                    }
                }

                List<InvocationExpressionSyntax> auditedCalls = [];

                foreach ((SyntaxNode declaration, SemanticModel model) in
                    domains)
                {
                    foreach (ExpressionSyntax methodUse in declaration
                        .DescendantNodesAndSelf()
                        .OfType<ExpressionSyntax>()
                        .Where(candidate => candidate switch
                        {
                            IdentifierNameSyntax identifier =>
                                identifier.Identifier.ValueText
                                    == writer.Symbol.Name,
                            MemberAccessExpressionSyntax access =>
                                access.Name.Identifier.ValueText
                                    == writer.Symbol.Name,
                            _ => false,
                        })
                        .Where(candidate =>
                            model.GetSymbolInfo(candidate).Symbol is
                                IMethodSymbol referenced
                            && SymbolEqualityComparer.Default.Equals(
                                referenced.OriginalDefinition,
                                writer.Symbol.OriginalDefinition)
                            && (candidate.Parent is not
                                    MemberAccessExpressionSyntax parent
                                || model.GetSymbolInfo(parent).Symbol is not
                                    IMethodSymbol parentMethod
                                || !SymbolEqualityComparer.Default.Equals(
                                    parentMethod.OriginalDefinition,
                                    writer.Symbol.OriginalDefinition))))
                    {
                        if (methodUse.Parent is not
                                InvocationExpressionSyntax direct
                            || direct.Expression != methodUse)
                        {
                            return Reject();
                        }

                        auditedCalls.Add(direct);
                    }
                }

                (InvocationExpressionSyntax Call, SemanticModel Model)[]
                    indexedCalls = invocations
                        .Where(candidate =>
                            ReferenceEquals(
                                candidate.Model.Compilation,
                                writer.Model.Compilation)
                            && candidate.Model.GetOperation(candidate.Call) is
                                IInvocationOperation operation
                            && SymbolEqualityComparer.Default.Equals(
                                operation.TargetMethod.OriginalDefinition,
                                writer.Symbol.OriginalDefinition))
                        .ToArray();

                if (auditedCalls.Count == 0
                    || indexedCalls.Length != auditedCalls.Count
                    || auditedCalls.Any(audited => !indexedCalls.Any(indexed =>
                        indexed.Call.SyntaxTree == audited.SyntaxTree
                        && indexed.Call.Span == audited.Span)))
                {
                    return Reject();
                }

                List<CleanupValueFlow> callerValues = [];

                foreach ((InvocationExpressionSyntax call, SemanticModel model)
                    in indexedCalls)
                {
                    if (model.GetEnclosingSymbol(call.SpanStart) is not
                            IMethodSymbol enclosing
                        || Resolve(enclosing, model.Compilation) is not
                            { } caller
                        || !SameBoundType(
                            caller.Symbol.ContainingType,
                            caller.Model.Compilation,
                            writer.Symbol.ContainingType,
                            writer.Model.Compilation)
                        || !writer.Symbol.IsStatic
                            && call.Expression is not IdentifierNameSyntax
                                and not MemberAccessExpressionSyntax
                                {
                                    Expression: ThisExpressionSyntax,
                                }
                        || model.GetOperation(call) is not
                            IInvocationOperation operation
                        || ResolveInvocationTarget(
                            operation.TargetMethod,
                            caller,
                            call) is not { } exactTarget
                        || MemberIdentity(exactTarget) != MemberIdentity(writer))
                    {
                        return Reject();
                    }

                    AuthoredMember contextualCaller = MergeCallableContext(
                        MergeValueContext(caller, authenticatedOwner),
                        authenticatedOwner) with
                    {
                        AdmissionBindings =
                            authenticatedOwner.AdmissionBindings
                                ?? caller.AdmissionBindings,
                        ConcreteBindings =
                            authenticatedOwner.ConcreteBindings
                                ?? caller.ConcreteBindings,
                        RecoveryBindings =
                            authenticatedOwner.RecoveryBindings
                                ?? caller.RecoveryBindings,
                        RecoveryContext =
                            authenticatedOwner.RecoveryContext
                                ?? caller.RecoveryContext,
                    };

                    AuthoredMember bound = BindCleanupInvocationContext(
                        contextualCaller,
                        call,
                        writer,
                        context);

                    IParameterSymbol exactParameter =
                        writer.Symbol.Parameters[parameter.Ordinal];

                    if (bound.ValueBindings?.TryGetValue(
                            exactParameter,
                            out BoundValueSource? source) != true
                        || source is null)
                    {
                        return Reject();
                    }

                    ExpressionSyntax expression = StripTransparentExpression(
                        source.Expression);

                    CleanupValueFlow? dominating =
                        ExactDominatingLocalAssignmentValueFlow(
                            source.Caller,
                            expression,
                            context);

                    CleanupValueFlow value = dominating
                        ?? (source.Caller.Model.GetSymbolInfo(expression).Symbol is
                            IParameterSymbol forwardedParameter
                        && forwardedParameter.RefKind == RefKind.None
                        && forwardedParameter.Ordinal >= 0
                        && forwardedParameter.Ordinal <
                            source.Caller.Symbol.Parameters.Length
                        && SymbolEqualityComparer.Default.Equals(
                            forwardedParameter.ContainingSymbol
                                .OriginalDefinition,
                            source.Caller.Symbol.OriginalDefinition)
                            ? ClosedWriterParameterValueFlow(
                                authenticatedOwner,
                                source.Caller,
                                source.Caller.Symbol.Parameters[
                                    forwardedParameter.Ordinal],
                                context,
                                depth + 1,
                                active,
                                allowInternalAssemblyWriter)
                            : CleanupValueFlowOf(
                                source.Caller,
                                source.Expression,
                                context));

                    callerValues.Add(value);
                }

                CleanupValueFlow merged = MergeCleanupValueFlow(callerValues);

                return merged with
                {
                    HasAuthoredSource = true,
                };
            }
            finally
            {
                active.Remove(identity);
            }
        }

        private CleanupValueFlow? ExactDominatingLocalAssignmentValueFlow(
            AuthoredMember member,
            ExpressionSyntax use,
            CleanupProvenanceContext context)
        {
            if (member.Model.GetSymbolInfo(use).Symbol is not ILocalSymbol
                {
                    RefKind: RefKind.None,
                } local
                || local.DeclaringSyntaxReferences.SingleOrDefault()
                    ?.GetSyntax() is not VariableDeclaratorSyntax
                || use.Ancestors().OfType<BlockSyntax>().FirstOrDefault()
                    is not { } block
                || member.Syntax.DescendantNodesAndSelf().Any(node =>
                    node is GotoStatementSyntax or LabeledStatementSyntax))
            {
                return null;
            }

            AssignmentExpressionSyntax[] assignments = block.Statements
                .OfType<ExpressionStatementSyntax>()
                .Where(statement => statement.SpanStart < use.SpanStart)
                .Select(static statement => statement.Expression)
                .OfType<AssignmentExpressionSyntax>()
                .Where(assignment => assignment.IsKind(
                        SyntaxKind.SimpleAssignmentExpression)
                    && SymbolEqualityComparer.Default.Equals(
                        member.Model.GetSymbolInfo(assignment.Left).Symbol,
                        local))
                .ToArray();

            if (assignments.LastOrDefault() is not { } assignment
                || !SymbolIsStableWithin(
                    member,
                    local,
                    assignment.Span.End,
                    use.SpanStart))
            {
                return null;
            }

            return CleanupValueFlowOf(
                member,
                assignment.Right,
                context);
        }

        private CleanupValueFlow StableCollectionStorageValueFlow(
            AuthoredMember member,
            ISymbol storage,
            CleanupProvenanceContext context)
        {
            List<BoundValueSource> sources = [];

            foreach (SyntaxReference reference in storage.DeclaringSyntaxReferences)
            {
                ExpressionSyntax? initializer = reference.GetSyntax() switch
                {
                    VariableDeclaratorSyntax variable => variable.Initializer?.Value,
                    PropertyDeclarationSyntax property => property.Initializer?.Value,
                    _ => null,
                };

                if (initializer is not null)
                {
                    sources.Add(new(
                        ValueExpressionContext(member, initializer, semanticModels[initializer.SyntaxTree]),
                        initializer));
                }
            }

            foreach (SyntaxReference reference in storage.ContainingType.DeclaringSyntaxReferences)
            {
                SyntaxNode declaration = reference.GetSyntax();

                SemanticModel model = semanticModels[declaration.SyntaxTree];

                foreach (AssignmentExpressionSyntax assignment in declaration.DescendantNodes().OfType<AssignmentExpressionSyntax>())
                {
                    bool touches = assignment.Left.DescendantNodesAndSelf().OfType<ExpressionSyntax>()
                        .Any(left => SymbolEqualityComparer.Default.Equals(model.GetSymbolInfo(left).Symbol, storage));

                    if (!touches)
                    {
                        continue;
                    }

                    if (!assignment.IsKind(SyntaxKind.SimpleAssignmentExpression)
                        || !SymbolEqualityComparer.Default.Equals(model.GetSymbolInfo(assignment.Left).Symbol, storage)
                        || model.GetEnclosingSymbol(assignment.SpanStart) is not IMethodSymbol
                        { MethodKind: MethodKind.StaticConstructor } constructor
                        || Resolve(constructor, model.Compilation) is not { } target)
                    {
                        return new([], false, true);
                    }

                    sources.Add(new(target, assignment.Right));
                }

                if (declaration.DescendantNodes().OfType<RefExpressionSyntax>().Any(reference =>
                    SymbolEqualityComparer.Default.Equals(model.GetSymbolInfo(reference.Expression).Symbol, storage))
                    || declaration.DescendantNodes().OfType<ArgumentSyntax>().Any(argument =>
                        argument.RefKindKeyword.Kind() is SyntaxKind.RefKeyword or SyntaxKind.OutKeyword
                        && SymbolEqualityComparer.Default.Equals(model.GetSymbolInfo(argument.Expression).Symbol, storage)))
                {
                    return new([], false, true);
                }
            }

            return MergeCleanupValueFlow(sources.Select(source => CleanupValueFlowOf(source.Caller, source.Expression, context)));
        }

        private CleanupValueFlow CollectionElementValueFlow(
            AuthoredMember member,
            ExpressionSyntax expression,
            CleanupProvenanceContext context)
        {
            expression = StripTransparentExpression(expression);

            var identity = (expression.SyntaxTree, expression.SpanStart);

            if (context.RemainingWork-- <= 0 || !context.CollectionElementActive.Add(identity))
            {
                return new([], false, true);
            }

            try
            {
                ISymbol? symbol = member.Model.GetSymbolInfo(expression).Symbol;

                if (symbol is IParameterSymbol sequenceParameter)
                {
                    if (sequenceParameter.RefKind != RefKind.None
                        || HasCollectionValueReplacement(member, sequenceParameter)
                        || member.ValueBindings?.TryGetValue(sequenceParameter, out BoundValueSource? source) != true
                        || source is null
                        || member.Syntax.DescendantNodesAndSelf().OfType<IdentifierNameSyntax>()
                            .Where(reference => SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(reference).Symbol, sequenceParameter))
                            .Any(reference => reference.Parent is not ForEachStatementSyntax loop
                                || loop.Expression != reference))
                    {
                        return new([], false, true);
                    }

                    CleanupValueFlow parameterFlow = CollectionElementValueFlow(
                        source.Caller,
                        source.Expression,
                        context);

                    return parameterFlow;
                }

                if (expression is InvocationExpressionSyntax factoryCall
                    && symbol is IMethodSymbol factoryMethod
                    && ResolveCleanupInvocationTarget(
                        factoryMethod,
                        member,
                        factoryCall,
                        context) is { } target)
                {
                    AuthoredMember factory = BindCleanupInvocationContext(
                        member,
                        factoryCall,
                        target,
                        context,
                        factoryMethod.MethodKind == MethodKind.DelegateInvoke);

                    ExpressionSyntax[] returned = ReturnedExpressions(
                        factory.Syntax);

                    if (returned.Length == 0)
                    {
                        return new([], false, true);
                    }

                    CleanupValueFlow result = MergeCleanupValueFlow(
                        returned.Select(value => CollectionElementValueFlow(
                            factory,
                            value,
                            context)));

                    return result with
                    {
                        HasAuthoredSource = true,
                    };
                }

                if (symbol is IFieldSymbol { IsStatic: true, IsReadOnly: true }
                    or IPropertySymbol { IsStatic: true, SetMethod: null })
                {
                    CleanupValueFlow stable = StableCollectionStorageValueFlow(
                        member,
                        symbol,
                        context);

                    if (!stable.Complete || stable.Values.Count == 0)
                    {
                        return new([], false, stable.HasAuthoredSource);
                    }

                    CleanupValueFlow elements = MergeCleanupValueFlow(
                        stable.Values.Select(value => CollectionElementValueFlow(
                            value.Caller,
                            value.Expression,
                            context)));

                    return elements with
                    {
                        Complete = elements.Complete && stable.Complete,
                        HasAuthoredSource = elements.HasAuthoredSource
                            || stable.HasAuthoredSource,
                    };
                }

                if (symbol is ILocalSymbol local)
                {
                    if (ExactPopulatedListElementValueFlow(
                            member,
                            expression,
                            local,
                            context) is { } populated)
                    {
                        return populated;
                    }

                    if (local.DeclaringSyntaxReferences.SingleOrDefault()
                            ?.GetSyntax() is not
                        VariableDeclaratorSyntax variable)
                    {
                        return new([], false, true);
                    }

                    AssignmentExpressionSyntax? exactAssignment = null;

                    ExpressionSyntax source;

                    if (variable.Initializer is { Value: { } initializer })
                    {
                        if (HasCollectionValueReplacement(member, local))
                        {
                            return new([], false, true);
                        }

                        source = initializer;
                    }
                    else
                    {
                        AssignmentExpressionSyntax[] assignments = member.Syntax
                            .DescendantNodesAndSelf(node => node == member.Syntax
                                || node is not AnonymousFunctionExpressionSyntax
                                    and not LocalFunctionStatementSyntax)
                            .OfType<AssignmentExpressionSyntax>()
                            .Where(assignment =>
                                SymbolEqualityComparer.Default.Equals(
                                    member.Model.GetSymbolInfo(
                                        assignment.Left).Symbol,
                                    local))
                            .ToArray();

                        if (assignments is not
                                [AssignmentExpressionSyntax
                                {
                                    RawKind:
                                        (int)SyntaxKind.SimpleAssignmentExpression,
                                } assignment]
                            || assignment.SpanStart >= expression.SpanStart
                            || !SymbolIsStableWithin(
                                member,
                                local,
                                assignment.Span.End,
                                expression.SpanStart)
                            || member.Syntax.DescendantNodesAndSelf()
                                .OfType<ArgumentSyntax>()
                                .Any(argument =>
                                    argument.RefKindKeyword.Kind() is
                                        SyntaxKind.RefKeyword
                                            or SyntaxKind.OutKeyword
                                    && SymbolEqualityComparer.Default.Equals(
                                        member.Model.GetSymbolInfo(
                                            argument.Expression).Symbol,
                                        local)))
                        {
                            return new([], false, true);
                        }

                        exactAssignment = assignment;

                        source = assignment.Right;
                    }

                    foreach (IdentifierNameSyntax reference in member.Model.SyntaxTree.GetRoot().DescendantNodes().OfType<IdentifierNameSyntax>())
                    {
                        if (!SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(reference).Symbol, local)
                            || reference.Span == expression.Span
                            || exactAssignment?.Left.Span == reference.Span)
                        {
                            continue;
                        }

                        InvocationExpressionSyntax? referenceCall = reference.Ancestors().OfType<InvocationExpressionSyntax>().FirstOrDefault();

                        if (referenceCall is null
                            || member.Model.GetSymbolInfo(referenceCall).Symbol is not IMethodSymbol method
                            || !IsExactFrameworkType(method.ContainingType, "System.Linq.Enumerable", typeof(Enumerable).Assembly.GetName())
                            || method.Name is not ("Select" or "ToList" or "ToArray"))
                        {
                            return new([], false, true);
                        }
                    }

                    // Element provenance must remain closed even when the collection object
                    // itself has an exact framework type.
                    foreach (ArgumentSyntax argument in member.Model.SyntaxTree.GetRoot().DescendantNodes().OfType<ArgumentSyntax>())
                    {
                        if (!SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(argument.Expression).Symbol, local))
                        {
                            continue;
                        }

                        if (argument.Expression.Span == expression.Span)
                        {
                            continue;
                        }

                        if (argument.Parent?.Parent is not InvocationExpressionSyntax use
                            || member.Model.GetSymbolInfo(use).Symbol is not IMethodSymbol method
                            || !IsExactFrameworkType(method.ContainingType, "System.Linq.Enumerable", typeof(Enumerable).Assembly.GetName())
                            || method.Name is not ("Select" or "ToList" or "ToArray"))
                        {
                            return new([], false, true);
                        }
                    }

                    CleanupValueFlow localFlow = CollectionElementValueFlow(
                        member,
                        source,
                        context);

                    return localFlow;
                }

                if (expression is InvocationExpressionSyntax call
                    && symbol is IMethodSymbol called
                    && IsExactFrameworkType(called.ContainingType, "System.Linq.Enumerable", typeof(Enumerable).Assembly.GetName()))
                {
                    IArgumentOperation[] arguments = member.Model.GetOperation(call) is IInvocationOperation operation
                        ? operation.Arguments.ToArray() : [];

                    ExpressionSyntax? Source(IArgumentOperation argument) => argument.Value.Syntax as ExpressionSyntax;

                    if (called.Name is "ToList" or "ToArray"
                        && arguments is [IArgumentOperation source])
                    {
                        return Source(source) is { } input
                            ? CollectionElementValueFlow(member, input, context)
                            : new([], false, true);
                    }

                    if (called.Name == "Select"
                        && arguments is [IArgumentOperation sequence, IArgumentOperation selector]
                        && Source(sequence) is { } sequenceExpression
                        && Source(selector) is { } selectorExpression
                        && ResolveCallable(selectorExpression, member.Model, member.CallableBindings, member.AbsentCallables) is { } projection
                        && projection.Symbol.Parameters is [IParameterSymbol parameter])
                    {
                        CleanupValueFlow elements = CollectionElementValueFlow(member, sequenceExpression, context);

                        if (!elements.Complete || elements.Values.Count == 0)
                        {
                            return new([], false, true);
                        }

                        return MergeCleanupValueFlow(elements.Values.SelectMany(value =>
                        {
                            AuthoredMember bound = projection with
                            {
                                ValueBindings = new Dictionary<ISymbol, BoundValueSource>(SymbolEqualityComparer.Default)
                                {
                                    [parameter] = value,
                                },
                            };

                            return ReturnedExpressions(bound.Syntax).Select(result => CleanupReturnedValueFlow(bound, result, context));
                        }));
                    }
                }

                SeparatedSyntaxList<ExpressionSyntax>? values = expression switch
                {
                    ArrayCreationExpressionSyntax { Initializer: { } initializer } => initializer.Expressions,
                    ImplicitArrayCreationExpressionSyntax array => array.Initializer.Expressions,
                    BaseObjectCreationExpressionSyntax { Initializer: { } initializer }
                        when member.Model.GetTypeInfo(expression).Type is INamedTypeSymbol type
                            && IsExactFrameworkType(type, "System.Collections.Generic.List`1", typeof(List<>).Assembly.GetName())
                            && member.Model.GetOperation(expression) is IObjectCreationOperation { Arguments.Length: 0 } => initializer.Expressions,
                    _ => null,
                };

                if (values is { } initialValues)
                {
                    CleanupValueFlow initializerFlow = MergeCleanupValueFlow(
                        initialValues.Select(value => CleanupValueFlowOf(
                            member,
                            value,
                            context)));

                    return initializerFlow;
                }

                if (expression is CollectionExpressionSyntax collection
                    && IsExactFrameworkCollectionMaterialization(member, expression)
                    && collection.Elements.All(static element => element is ExpressionElementSyntax))
                {
                    CleanupValueFlow collectionFlow = MergeCleanupValueFlow(
                        collection.Elements.OfType<ExpressionElementSyntax>()
                            .Select(element => CleanupValueFlowOf(
                                member,
                                element.Expression,
                                context)));

                    return collectionFlow;
                }

                return new([], false, true);
            }
            finally
            {
                context.CollectionElementActive.Remove(identity);
            }
        }

        private CleanupValueFlow CleanupReturnedValueFlow(
            AuthoredMember factory,
            ExpressionSyntax expression,
            CleanupProvenanceContext context)
        {
            ITypeSymbol expectedType = factory.Symbol.ReturnType;

            if (factory.Symbol.IsAsync
                && expectedType is INamedTypeSymbol
                {
                    TypeArguments: [ITypeSymbol awaited],
                } awaitable
                && TypeKey(awaitable.OriginalDefinition) is
                    "System.Threading.Tasks.Task`1"
                        or "System.Threading.Tasks.ValueTask`1")
            {
                expectedType = awaited;
            }

            Conversion conversion = factory.Model.ClassifyConversion(
                expression,
                expectedType);

            if (!conversion.IsUserDefined)
            {
                return CleanupValueFlowOf(
                    factory,
                    expression,
                    context);
            }

            if (!conversion.IsImplicit
                || conversion.MethodSymbol is not
                {
                    MethodKind: MethodKind.Conversion,
                    IsStatic: true,
                    Parameters: [IParameterSymbol conversionParameter],
                } conversionMethod
                || !SameBoundType(
                    conversionMethod.ReturnType,
                    factory.Model.Compilation,
                    expectedType,
                    factory.Model.Compilation)
                || Resolve(
                    conversionMethod,
                    factory.Model.Compilation) is not { } target
                || target.Symbol.Parameters is not
                    [IParameterSymbol targetParameter])
            {
                return new([], false, true);
            }

            AuthoredMember bound = BindArguments(
                factory,
                [(expression, conversionParameter, RefKind.None)],
                target);

            bound = AddCleanupValueBindings(
                factory,
                [(expression, conversionParameter, RefKind.None)],
                target,
                bound);

            ExpressionSyntax[] returned = ReturnedExpressions(bound.Syntax);

            if (returned.Length == 0)
            {
                return new([], false, true);
            }

            CleanupValueFlow result = MergeCleanupValueFlow(
                returned.Select(value => CleanupReturnedValueFlow(
                    bound,
                    value,
                    context)));

            return result with
            {
                Complete = result.Complete
                    && targetParameter.Ordinal == conversionParameter.Ordinal,
                HasAuthoredSource = true,
            };
        }

        private static ExpressionSyntax? ExactPositivePatternValue(
            AuthoredMember member,
            ExpressionSyntax use,
            ILocalSymbol local,
            SingleVariableDesignationSyntax designation)
        {
            if (designation.Parent is not RecursivePatternSyntax
                {
                    Type: null,
                    PositionalPatternClause: null,
                    PropertyPatternClause.Subpatterns.Count: 0,
                    Parent: IsPatternExpressionSyntax pattern,
                }
                || local.RefKind != RefKind.None
                || HasCollectionValueReplacement(
                    member,
                    local,
                    rejectElementWrites: false))
            {
                return null;
            }

            bool selectedBranch = pattern.Parent switch
            {
                IfStatementSyntax guard => guard.Condition == pattern
                    && guard.Statement.Span.Contains(use.Span),
                WhenClauseSyntax
                {
                    Parent: CasePatternSwitchLabelSyntax
                    {
                        Parent: SwitchSectionSyntax section,
                    },
                } whenClause => whenClause.Condition == pattern
                    && section.Statements.Any(statement =>
                        statement.Span.Contains(use.Span)),
                _ => false,
            };

            return selectedBranch && pattern.Span.End <= use.SpanStart
                ? pattern.Expression
                : null;
        }

        private CleanupValueFlow LocalCleanupValueFlow(
            AuthoredMember member,
            ExpressionSyntax use,
            ILocalSymbol local,
            CleanupProvenanceContext context)
        {
            SyntaxNode? declaration = local.DeclaringSyntaxReferences
                .SingleOrDefault()?.GetSyntax();

            if (declaration is SingleVariableDesignationSyntax designation)
            {
                if (ExactPositivePatternValue(
                    member,
                    use,
                    local,
                    designation) is { } positiveValue)
                {
                    return CleanupValueFlowOf(
                        member,
                        positiveValue,
                        context);
                }

                if (ExactFrameworkDictionaryRemovedValueFlow(
                        member,
                        use,
                        local,
                        designation,
                        context) is { } removed)
                {
                    return removed;
                }

                if (designation.Parent is RecursivePatternSyntax
                    {
                        Type: null,
                        PositionalPatternClause: null,
                        PropertyPatternClause.Subpatterns.Count: 0,
                        Parent: IsPatternExpressionSyntax
                        {
                            Expression: { } positiveTested,
                            Parent: ConditionalExpressionSyntax conditional,
                        } pattern,
                    }
                    && conditional.Condition == pattern
                    && conditional.WhenTrue.Span.Contains(use.Span)
                    && pattern.Span.End <= use.SpanStart
                    && SymbolIsStableBetween(
                        member,
                        local,
                        pattern.Span.End,
                        use))
                {
                    return CleanupValueFlowOf(
                        member,
                        positiveTested,
                        context);
                }

                if (designation.Parent is RecursivePatternSyntax
                    {
                        Type: null,
                        PositionalPatternClause: null,
                        PropertyPatternClause.Subpatterns.Count: 0,
                        Parent: UnaryPatternSyntax
                        {
                            RawKind: (int)SyntaxKind.NotPattern,
                            Parent: IsPatternExpressionSyntax
                            {
                                Expression: { } tested,
                                Parent: IfStatementSyntax guard,
                            },
                        },
                    }
                    && guard.Condition is IsPatternExpressionSyntax
                    && guard.Else is null
                    && guard.Parent is BlockSyntax guardBlock
                    && guardBlock.Span.Contains(use.Span)
                    && guard.Span.End < use.SpanStart
                    && IsDirectNegativePatternTermination(guard.Statement)
                    && SymbolIsStableBetween(member, local, guard.Span.End, use))
                {
                    return CleanupValueFlowOf(member, tested, context);
                }

                if (ExactAuthoredOutLocalCleanupValueFlow(
                        member,
                        use,
                        local,
                        designation,
                        context) is { } outFlow)
                {
                    return outFlow;
                }

                CleanupProvenance? guarded =
                    ExactConfiguredSqlitePatternLocalProvenance(
                        member,
                        use,
                        local,
                        designation,
                        context)
                    ?? ExactRuntimeTypeGuardedLocalProvenance(
                        member,
                        use,
                        local,
                        designation);

                return guarded is
                {
                    Complete: true,
                    Candidates: [CleanupTypeCandidate],
                }
                        ? new(
                            [new(member, use)],
                            true,
                            guarded.HasAuthoredSource)
                        : new([], false, guarded?.HasAuthoredSource ?? false);
            }

            if (declaration is ForEachStatementSyntax loop
                && local.RefKind == RefKind.None)
            {
                return CollectionElementValueFlow(
                    member,
                    loop.Expression,
                    context);
            }

            if (declaration is not VariableDeclaratorSyntax variable
                || variable.Ancestors().OfType<BlockSyntax>().FirstOrDefault()
                    is not { } block)
            {
                return new([], false, false);
            }

            if (ExactFrameworkDictionaryRemovedValueFlow(
                    member,
                    use,
                    local,
                    null,
                    context,
                    variable) is { } existingRemoved)
            {
                return existingRemoved;
            }

            List<ExpressionSyntax> values = variable.Initializer is null
                ? []
                : [variable.Initializer.Value];

            bool exactWrites = true;

            foreach (SyntaxNode node in block.DescendantNodes(candidate =>
                candidate == block
                || candidate is not AnonymousFunctionExpressionSyntax
                    and not LocalFunctionStatementSyntax))
            {
                if (node.SpanStart >= use.SpanStart)
                {
                    continue;
                }

                if (node is AssignmentExpressionSyntax assignment
                    && SymbolEqualityComparer.Default.Equals(
                        member.Model.GetSymbolInfo(assignment.Left).Symbol,
                        local))
                {
                    if (assignment.IsKind(
                            SyntaxKind.SimpleAssignmentExpression))
                    {
                        values.Add(assignment.Right);
                    }
                    else
                    {
                        exactWrites = false;
                    }
                }
                else if (node is ArgumentSyntax argument
                    && argument.RefKindKeyword.Kind() is
                        SyntaxKind.RefKeyword or SyntaxKind.OutKeyword
                    && SymbolEqualityComparer.Default.Equals(
                        member.Model.GetSymbolInfo(argument.Expression).Symbol,
                        local))
                {
                    exactWrites = false;
                }
                else if (node is RefExpressionSyntax reference
                    && SymbolEqualityComparer.Default.Equals(
                        member.Model.GetSymbolInfo(reference.Expression).Symbol,
                        local))
                {
                    exactWrites = false;
                }
            }

            if (InvokedCallableMayMutateSymbol(
                member,
                local,
                use.SpanStart))
            {
                exactWrites = false;
            }

            if (values.Count == 0)
            {
                return new([], false, false);
            }

            CleanupValueFlow merged = MergeCleanupValueFlow(
                values.Select(value => CleanupValueFlowOf(
                    member,
                    value,
                    context)));

            return exactWrites
                ? merged
                : merged with
                {
                    Complete = false,
                };
        }

        private CleanupValueFlow MergeCleanupValueFlow(
            IEnumerable<CleanupValueFlow> values)
        {
            CleanupValueFlow[] flow = values.ToArray();

            List<BoundValueSource> distinct = [];

            HashSet<(
                SyntaxTree CallerTree,
                int CallerStart,
                SyntaxTree ExpressionTree,
                int ExpressionStart,
                int ExpressionLength,
                string Environment)> exact = [];

            bool exactEnvironments = true;

            foreach (BoundValueSource value in flow.SelectMany(
                static value => value.Values))
            {
                EvaluationEnvironmentFingerprint environment =
                    EvaluationEnvironmentIdentity(
                        ProjectEvaluationEnvironment(
                            value.Caller,
                            value.Expression));

                if (!environment.Complete
                    || environment.ContainsBackreference)
                {
                    exactEnvironments = false;

                    distinct.Add(value);

                    continue;
                }

                if (exact.Add((
                    value.Caller.Syntax.SyntaxTree,
                    value.Caller.Syntax.SpanStart,
                    value.Expression.SyntaxTree,
                    value.Expression.SpanStart,
                    value.Expression.Span.Length,
                    environment.Identity)))
                {
                    distinct.Add(value);
                }
            }

            return new(
                distinct.ToArray(),
                flow.Length != 0
                    && flow.All(static value => value.Complete)
                    && exactEnvironments,
                flow.Any(static value => value.HasAuthoredSource));
        }

        private CleanupProvenance ConditionalCleanupProvenance(
            AuthoredMember member,
            ExpressionSyntax expression,
            CleanupProvenanceContext context)
        {
            expression = StripTransparentExpression(expression);

            return IsSemanticallyEmptyCleanupValue(
                    member.Model,
                    expression)
                    ? new([], true, false)
                    : CleanupProvenanceOf(member, expression, context);
        }

        private static bool TryNormalizeBuiltInCleanupValue(
            SemanticModel model,
            ExpressionSyntax expression,
            out ExpressionSyntax normalized,
            bool requireIdentityPreservingCasts = false)
        {
            normalized = expression;

            for (int work = 0; work < CleanupProvenanceContext.MaximumWork; work++)
            {
                Conversion contextual = model.GetConversion(normalized);

                if (contextual.IsUserDefined
                    || contextual.MethodSymbol is not null
                    || contextual.IsDynamic)
                {
                    return false;
                }

                if (normalized is ParenthesizedExpressionSyntax parentheses)
                {
                    normalized = parentheses.Expression;

                    continue;
                }

                if (normalized is PostfixUnaryExpressionSyntax suppression
                    && suppression.IsKind(SyntaxKind.SuppressNullableWarningExpression))
                {
                    normalized = suppression.Operand;

                    continue;
                }

                if (normalized is CastExpressionSyntax cast)
                {
                    ITypeSymbol? target = model.GetTypeInfo(cast).Type;

                    if (model.GetOperation(cast) is not IConversionOperation conversion
                        || conversion.OperatorMethod is not null
                        || conversion.Conversion.IsUserDefined
                        || conversion.Operand.Type?.TypeKind == TypeKind.Dynamic
                        || target is null
                        || target.TypeKind == TypeKind.Dynamic
                        || !(requireIdentityPreservingCasts
                            ? conversion.Conversion.IsIdentity
                                || conversion.Conversion.IsReference
                                    && conversion.Operand.Type?.IsReferenceType == true
                            : target.IsReferenceType
                                || target is INamedTypeSymbol
                                {
                                    OriginalDefinition.SpecialType: SpecialType.System_Nullable_T,
                                }))
                    {
                        return false;
                    }

                    normalized = cast.Expression;

                    continue;
                }

                return true;
            }

            return false;
        }

        private static bool IsSemanticallyEmptyCleanupValue(
            SemanticModel model,
            ExpressionSyntax expression)
        {
            if (!TryNormalizeBuiltInCleanupValue(model, expression, out expression))
            {
                return false;
            }

            if (model.GetConstantValue(expression) is
                {
                    HasValue: true,
                    Value: null,
                })
            {
                return true;
            }

            if (expression is not DefaultExpressionSyntax
                && !expression.IsKind(
                    SyntaxKind.DefaultLiteralExpression))
            {
                return false;
            }

            ITypeSymbol? type = model.GetTypeInfo(expression).Type;

            return type is null
                || type.IsReferenceType
                || type is INamedTypeSymbol
                {
                    OriginalDefinition.SpecialType:
                        SpecialType.System_Nullable_T,
                };
        }

        private AuthoredMember? ResolveCleanupInvocationTarget(
            IMethodSymbol method,
            AuthoredMember member,
            InvocationExpressionSyntax call,
            CleanupProvenanceContext context)
        {
            if (method.MethodKind == MethodKind.DelegateInvoke)
            {
                AuthoredMember[] targets = ResolveCallableTargets(
                    DelegateReceiver(member, call),
                    member.Model,
                    member.CallableBindings,
                    member.AbsentCallables);

                return targets is [AuthoredMember target]
                    ? target
                    : null;
            }

            if (method.ContainingType.TypeKind != TypeKind.Interface
                || AdmissionReceiver(member, call) is not { } receiver)
            {
                return ResolveInvocationTarget(method, member, call, context);
            }

            CleanupProvenance receiverProvenance = CleanupProvenanceOf(
                member,
                receiver,
                context);

            CleanupTypeCandidate[] receiverTypes = receiverProvenance.Candidates
                .DistinctBy(static candidate => candidate.Identity)
                .ToArray();

            AuthoredMember[] boundImplementations =
                ResolveBoundImplementations(
                    method,
                    member.Model.Compilation);

            if (receiverProvenance.Complete
                && receiverTypes is [CleanupTypeCandidate receiverType]
                && receiverType.Type is INamedTypeSymbol concrete)
            {
                IMethodSymbol[] implementations = concrete.AllInterfaces
                    .Where(contract =>
                        contract.ContainingAssembly.Identity.Equals(
                            method.ContainingAssembly.Identity)
                        && TypeKey(contract) == TypeKey(method.ContainingType))
                    .SelectMany(static contract => contract.GetMembers())
                    .OfType<IMethodSymbol>()
                    .Where(slot => MethodKey(slot) == MethodKey(method))
                    .Select(slot => concrete
                        .FindImplementationForInterfaceMember(slot))
                    .OfType<IMethodSymbol>()
                    .DistinctBy(static implementation =>
                        implementation.OriginalDefinition,
                        SymbolEqualityComparer.Default)
                    .ToArray();

                if (implementations is [IMethodSymbol implementation]
                    && Resolve(implementation, member.Model.Compilation)
                        is { } exact)
                {
                    return exact;
                }
            }

            if ((!receiverProvenance.Complete || receiverTypes.Length == 0)
                && boundImplementations is [AuthoredMember bound]
                && IsExactDiBoundCleanupReceiver(
                    member,
                    receiver,
                    method.ContainingType,
                    []))
            {
                return bound;
            }

            bool hasExecutableInterfaceBody = method.DeclaringSyntaxReferences
                .Select(static reference => reference.GetSyntax())
                .Any(static syntax => syntax is MethodDeclarationSyntax
                {
                    Body: not null,
                } or MethodDeclarationSyntax
                {
                    ExpressionBody: not null,
                });

            return hasExecutableInterfaceBody
                ? Resolve(method, member.Model.Compilation)
                : null;
        }

        private bool IsExactDiBoundCleanupReceiver(
            AuthoredMember member,
            ExpressionSyntax expression,
            ITypeSymbol contract,
            HashSet<(SyntaxTree Tree, int Start, int Length)> path)
        {
            expression = StripTransparentExpression(expression);

            var identity = (
                expression.SyntaxTree,
                expression.SpanStart,
                expression.Span.Length);

            if (!path.Add(identity))
            {
                return false;
            }

            try
            {
                ISymbol? symbol = member.Model.GetSymbolInfo(expression).Symbol;

                if (expression is ConditionalExpressionSyntax conditional)
                {
                    ExpressionSyntax[] sources = new[] { conditional.WhenTrue, conditional.WhenFalse }
                        .Where(value => !IsSemanticallyEmptyCleanupValue(member.Model, value))
                        .ToArray();

                    return sources.Length > 0 && sources.All(value =>
                        IsExactDiBoundCleanupReceiver(member, value, contract, path));
                }

                if (symbol is not null
                    && member.ValueBindings?.TryGetValue(
                        symbol,
                        out BoundValueSource? bound) == true
                    && bound is not null)
                {
                    if (symbol is IParameterSymbol
                        && !SymbolIsStableBetween(member, symbol, member.Syntax.SpanStart, expression))
                    {
                        return false;
                    }

                    if (symbol is IParameterSymbol factoryParameter
                        && IsExactRegistrationFactoryArgument(
                            member,
                            factoryParameter,
                            bound,
                            contract))
                    {
                        return true;
                    }

                    return IsExactDiBoundCleanupReceiver(
                        bound.Caller,
                        bound.Expression,
                        contract,
                        path);
                }

                if (symbol is IParameterSymbol parameter)
                {
                    if (!SymbolIsStableBetween(
                            member,
                            parameter,
                            member.Syntax.SpanStart,
                            expression))
                    {
                        return false;
                    }

                    return IsExactRegisteredConstructorDependency(
                        member,
                        parameter,
                        contract);
                }

                if (IsExactScopedDiCleanupResolution(
                    member,
                    expression,
                    contract,
                    path))
                {
                    return true;
                }

                if (symbol is ILocalSymbol local
                    && local.DeclaringSyntaxReferences.SingleOrDefault()
                            ?.GetSyntax() is VariableDeclaratorSyntax
                    {
                        Initializer.Value: { } initializer,
                    } variable
                    && variable.Ancestors().OfType<BlockSyntax>()
                            .FirstOrDefault() is { } block
                    && !block.DescendantNodes(candidate =>
                            candidate == block
                            || candidate is not AnonymousFunctionExpressionSyntax
                                and not LocalFunctionStatementSyntax)
                        .Any(node => node switch
                        {
                            AssignmentExpressionSyntax assignment =>
                                SymbolEqualityComparer.Default.Equals(
                                    member.Model.GetSymbolInfo(
                                        assignment.Left).Symbol,
                                    local),
                            RefExpressionSyntax alias =>
                                SymbolEqualityComparer.Default.Equals(
                                    member.Model.GetSymbolInfo(alias.Expression).Symbol,
                                    local),
                            ArgumentSyntax argument
                                when argument.RefKindKeyword.Kind() is
                                    SyntaxKind.RefKeyword
                                        or SyntaxKind.OutKeyword =>
                                SymbolEqualityComparer.Default.Equals(
                                    member.Model.GetSymbolInfo(
                                        argument.Expression).Symbol,
                                    local),
                            _ => false,
                        }))
                {
                    if (IsExactAuthenticatedFactoryServiceResolution(
                            member,
                            initializer,
                            contract)
                        && IsExactTerminatingNullGuardBeforeUse(
                            member,
                            local,
                            variable,
                            expression))
                    {
                        return true;
                    }

                    return IsExactDiBoundCleanupReceiver(
                        member,
                        initializer,
                        contract,
                        path);
                }

                if (symbol is IFieldSymbol
                    {
                        IsReadOnly: true,
                        IsStatic: false,
                    } field
                    && SameBoundType(
                        field.Type,
                        member.Model.Compilation,
                        contract,
                        member.Model.Compilation)
                    && ExactReadOnlyFieldValues(member, expression, field) is
                        [BoundValueSource fieldValue])
                {
                    return IsExactDiBoundCleanupReceiver(
                        fieldValue.Caller,
                        ExactNonThrowingValue(fieldValue.Expression),
                        contract,
                        path);
                }

                if (expression is MemberAccessExpressionSyntax
                    {
                        Expression: { } propertyReceiver,
                    }
                    && symbol is IPropertySymbol
                    {
                        IsStatic: false,
                        ContainingType.IsSealed: true,
                    } property
                    && SameBoundType(
                        property.Type,
                        member.Model.Compilation,
                        contract,
                        member.Model.Compilation)
                    && HasExactAutoInitAssignmentSemantics(property))
                {
                    CleanupValueFlow receivers = CleanupValueFlowOf(
                        member,
                        propertyReceiver,
                        new CleanupProvenanceContext());

                    if (!receivers.Complete
                        || receivers.Values.Count == 0)
                    {
                        return false;
                    }

                    foreach (BoundValueSource receiver in receivers.Values)
                    {
                        ExpressionSyntax receiverExpression =
                            StripTransparentExpression(receiver.Expression);

                        if (receiverExpression is not
                                BaseObjectCreationExpressionSyntax creation
                            || receiver.Caller.Model.GetSymbolInfo(creation).Symbol
                                is not IMethodSymbol constructor
                            || !SameBoundTypeOrGenericDefinition(
                                constructor.ContainingType,
                                property.ContainingType,
                                receiver.Caller.Model.Compilation)
                            || creation.Initializer?.Expressions
                                .OfType<AssignmentExpressionSyntax>()
                                .Any(assignment =>
                                    receiver.Caller.Model.GetSymbolInfo(
                                        assignment.Left).Symbol is
                                            IPropertySymbol initialized
                                    && SameBoundPropertyDefinition(
                                        initialized,
                                        receiver.Caller.Model.Compilation,
                                        property,
                                        member.Model.Compilation)) == true
                            || PropertyConstructorParameter(property) is not
                            { } propertyParameter
                            || propertyParameter.ContainingSymbol is not
                                IMethodSymbol propertyConstructor
                            || !SymbolEqualityComparer.Default.Equals(
                                constructor.OriginalDefinition,
                                propertyConstructor.OriginalDefinition)
                            || ConstructorArguments(receiver.Caller, creation)
                                .Where(argument => argument.Parameter?.Ordinal
                                    == propertyParameter.Ordinal)
                                .ToArray() is not
                                    [var argument]
                            || argument.RefKind != RefKind.None
                            || !IsExactDiBoundCleanupReceiver(
                                receiver.Caller,
                                argument.Expression,
                                contract,
                                path))
                        {
                            return false;
                        }
                    }

                    return true;
                }

                return false;
            }
            finally
            {
                _ = path.Remove(identity);
            }
        }

        private bool IsExactAuthenticatedFactoryServiceResolution(
            AuthoredMember member,
            ExpressionSyntax expression,
            ITypeSymbol contract)
        {
            if (StripTransparentExpression(expression) is not
                    InvocationExpressionSyntax resolution
                || member.Model.GetSymbolInfo(resolution).Symbol is not
                    IMethodSymbol resolver
                || !IsExactFrameworkMethod(
                    resolver,
                    "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions",
                    "GetService",
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
                || resolver.TypeArguments is not [ITypeSymbol resolved]
                || !SameBoundType(
                    resolved,
                    member.Model.Compilation,
                    contract,
                    member.Model.Compilation)
                || resolution.ArgumentList.Arguments.Count != 0
                || resolution.Expression is not MemberAccessExpressionSyntax
                {
                    Expression: { } providerExpression,
                }
                || member.Model.GetSymbolInfo(providerExpression).Symbol is not
                    IParameterSymbol provider
                || !RecoveryTupleSourceIsStable(
                    member,
                    provider,
                    resolution,
                    allowSimpleLocalAssignments: false)
                || member.ValueBindings?.TryGetValue(
                    provider,
                    out BoundValueSource? boundProvider) != true
                || boundProvider is null
                || boundProvider.Caller.Model.GetSymbolInfo(
                    boundProvider.Expression).Symbol is not
                    IParameterSymbol factoryProvider
                || !IsExactFrameworkType(
                    factoryProvider.Type,
                    "System.IServiceProvider",
                    typeof(IServiceProvider).Assembly.GetName())
                || factoryProvider.DeclaringSyntaxReferences
                    .SingleOrDefault()?.GetSyntax() is not
                        ParameterSyntax factoryParameter
                || factoryParameter.Ancestors()
                    .OfType<AnonymousFunctionExpressionSyntax>()
                    .FirstOrDefault() is not { } factory)
            {
                return false;
            }

            ResolvedRegistration[] rootRegistrations =
                diActivationRegistrations.Values
                .SelectMany(static registrations => registrations)
                .DistinctBy(
                    static registration => registration.Call,
                    ReferenceEqualityComparer.Instance)
                .Where(registration =>
                    IsExactRootFactoryRegistrationMethod(registration.Method)
                    && registration.Call.ArgumentList.Arguments is
                        [ArgumentSyntax { Expression: { } registeredFactory }]
                    && registeredFactory == factory)
                .ToArray();

            if (rootRegistrations is not [ResolvedRegistration rootRegistration]
                || ResolveCallable(
                    factory,
                    rootRegistration.Model,
                    null,
                    null) is not { } factoryMember
                || !RecoveryTupleSourceIsStable(
                    factoryMember,
                    factoryProvider,
                    boundProvider.Expression,
                    allowSimpleLocalAssignments: false))
            {
                return false;
            }

            return HasExactOptionalServiceRegistration(
                contract,
                member.Model.Compilation);
        }

        private static bool IsExactTerminatingNullGuardBeforeUse(
            AuthoredMember member,
            ILocalSymbol local,
            VariableDeclaratorSyntax declaration,
            ExpressionSyntax use)
        {
            if (declaration.Ancestors().OfType<StatementSyntax>()
                    .FirstOrDefault() is not { } declarationStatement
                || use.Ancestors().OfType<StatementSyntax>()
                    .FirstOrDefault() is not { } useStatement
                || declarationStatement.Parent is not BlockSyntax block
                || useStatement.Parent != block)
            {
                return false;
            }

            int declarationIndex = block.Statements.IndexOf(
                declarationStatement);

            int useIndex = block.Statements.IndexOf(useStatement);

            IfStatementSyntax[] guards = block.Statements
                .OfType<IfStatementSyntax>()
                .Where(guard =>
                    block.Statements.IndexOf(guard) > declarationIndex
                    && block.Statements.IndexOf(guard) < useIndex
                    && guard.Else is null
                    && DefinitelyTerminates(guard.Statement)
                    && ExactLogicalOrLeaves(guard.Condition).Count(leaf =>
                        IsExactNullTest(member, leaf, local)) == 1
                    && SymbolIsStableBetween(
                        member,
                        local,
                        guard.Span.End,
                        use))
                .ToArray();

            return declarationIndex >= 0
                && useIndex > declarationIndex
                && SymbolIsStableBetween(
                    member,
                    local,
                    declarationStatement.Span.End,
                    use)
                && guards.Length == 1;
        }

        private bool IsExactScopedDiCleanupResolution(
            AuthoredMember member,
            ExpressionSyntax expression,
            ITypeSymbol contract,
            HashSet<(SyntaxTree Tree, int Start, int Length)> path)
        {
            if (expression is not InvocationExpressionSyntax resolution
                || member.Model.GetSymbolInfo(resolution).Symbol is not
                    IMethodSymbol resolver
                || !(IsExactFrameworkMethod(
                    resolver,
                    "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions",
                    "GetRequiredService",
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
                    || IsExactFrameworkMethod(
                        resolver,
                        "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions",
                        "GetService",
                        "Microsoft.Extensions.DependencyInjection.Abstractions"))
                || resolver.TypeArguments is not [ITypeSymbol resolved]
                || !SameBoundType(
                    resolved,
                    member.Model.Compilation,
                    contract,
                    member.Model.Compilation)
                || resolution.ArgumentList.Arguments.Count != 0
                || resolution.Expression is not MemberAccessExpressionSyntax
                {
                    Expression: MemberAccessExpressionSyntax
                    {
                        Expression: { } scopeExpression,
                        Name.Identifier.ValueText: "ServiceProvider",
                    } providerAccess,
                }
                || member.Model.GetSymbolInfo(providerAccess).Symbol is not
                    IPropertySymbol providerProperty
                || providerProperty.Name != "ServiceProvider"
                || !(IsExactFrameworkType(
                        providerProperty.ContainingType,
                        "Microsoft.Extensions.DependencyInjection.AsyncServiceScope",
                        typeof(Microsoft.Extensions.DependencyInjection.AsyncServiceScope)
                            .Assembly.GetName())
                    || IsExactFrameworkType(
                        providerProperty.ContainingType,
                        "Microsoft.Extensions.DependencyInjection.IServiceScope",
                        typeof(Microsoft.Extensions.DependencyInjection.IServiceScope)
                            .Assembly.GetName()))
                )
            {
                return false;
            }

            return IsExactCleanupScopeSource(member, scopeExpression, path);
        }

        private bool IsExactCleanupScopeSource(
            AuthoredMember member,
            ExpressionSyntax expression,
            HashSet<(SyntaxTree Tree, int Start, int Length)> path)
        {
            expression = StripTransparentExpression(expression);

            ISymbol? source = member.Model.GetSymbolInfo(expression).Symbol;

            if (source is IParameterSymbol
                && member.ValueBindings?.TryGetValue(source, out BoundValueSource? bound) == true
                && bound is not null
                && SymbolIsStableBetween(member, source, member.Syntax.SpanStart, expression))
            {
                var identity = (expression.SyntaxTree, expression.SpanStart, expression.Span.Length);

                if (!path.Add(identity)) return false;

                try
                {
                    return IsExactCleanupScopeSource(bound.Caller, bound.Expression, path);
                }
                finally
                {
                    path.Remove(identity);
                }
            }

            if (source is not ILocalSymbol scope
                || scope.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                    is not VariableDeclaratorSyntax
                    {
                        Initializer.Value: InvocationExpressionSyntax createScope,
                    } declaration
                || declaration.Parent?.Parent is not
                    LocalDeclarationStatementSyntax scopeStatement
                || scopeStatement.UsingKeyword.RawKind == 0
                || createScope.Expression is not MemberAccessExpressionSyntax
                {
                    Expression: { } scopeFactory,
                }
                || member.Model.GetSymbolInfo(createScope).Symbol is not
                    IMethodSymbol createScopeMethod
                || !((scopeStatement.AwaitKeyword.RawKind != 0
                        && IsExactFrameworkType(
                            scope.Type,
                            "Microsoft.Extensions.DependencyInjection.AsyncServiceScope",
                            typeof(Microsoft.Extensions.DependencyInjection.AsyncServiceScope)
                                .Assembly.GetName())
                        && IsExactFrameworkMethod(
                            createScopeMethod,
                            "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions",
                            "CreateAsyncScope",
                            "Microsoft.Extensions.DependencyInjection.Abstractions"))
                    || (scopeStatement.AwaitKeyword.RawKind == 0
                        && IsExactFrameworkType(
                            scope.Type,
                            "Microsoft.Extensions.DependencyInjection.IServiceScope",
                            typeof(Microsoft.Extensions.DependencyInjection.IServiceScope)
                                .Assembly.GetName())
                        && IsExactFrameworkMethod(
                            createScopeMethod,
                            "Microsoft.Extensions.DependencyInjection.IServiceScopeFactory",
                            "CreateScope",
                            "Microsoft.Extensions.DependencyInjection.Abstractions")))
                || member.Model.GetTypeInfo(scopeFactory).Type is not
                    ITypeSymbol scopeFactoryContract
                || !IsExactFrameworkType(
                    scopeFactoryContract,
                    "Microsoft.Extensions.DependencyInjection.IServiceScopeFactory",
                    typeof(Microsoft.Extensions.DependencyInjection.IServiceScopeFactory)
                        .Assembly.GetName())
                || !IsExactDiBoundCleanupReceiver(
                    member,
                    scopeFactory,
                    scopeFactoryContract,
                    path)
                || scopeStatement.Parent is not BlockSyntax block
                || scopeStatement.Span.End >= expression.SpanStart
                || !block.Span.Contains(expression.Span)
                || block.DescendantNodes(candidate => candidate == block
                        || candidate is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .Where(node => node.SpanStart > scopeStatement.Span.End
                        && node.SpanStart < expression.SpanStart)
                    .Any(node => node switch
                    {
                        AssignmentExpressionSyntax assignment =>
                            SymbolEqualityComparer.Default.Equals(
                                member.Model.GetSymbolInfo(
                                    assignment.Left).Symbol,
                                scope),
                        ArgumentSyntax argument
                            when argument.RefKindKeyword.Kind() is
                                SyntaxKind.RefKeyword or SyntaxKind.OutKeyword =>
                            SymbolEqualityComparer.Default.Equals(
                                member.Model.GetSymbolInfo(
                                    argument.Expression).Symbol,
                                scope),
                        _ => false,
                    }))
            {
                return false;
            }

            return true;
        }

        private BoundValueSource[] ExactReadOnlyFieldValues(
            AuthoredMember member,
            ExpressionSyntax expression,
            IFieldSymbol field)
        {
            List<BoundValueSource> values = [];

            IMethodSymbol[] boundConstructors = BoundConstructorContexts(
                member,
                field.ContainingType);

            if (boundConstructors.Length > 1
                && member.ConstructorContexts is not { Count: > 0 })
            {
                return [];
            }

            if (boundConstructors.Length == 0
                && InstanceConstructorCount(field.ContainingType) > 1)
            {
                return [];
            }

            foreach (VariableDeclaratorSyntax declaration in
                field.DeclaringSyntaxReferences
                    .Select(static reference => reference.GetSyntax())
                    .OfType<VariableDeclaratorSyntax>())
            {
                if (declaration.Initializer?.Value is not
                    { } initializer
                    || !semanticModels.TryGetValue(
                        initializer.SyntaxTree,
                        out SemanticModel? model))
                {
                    continue;
                }

                values.Add(new(
                    ValueExpressionContext(member, initializer, model),
                    initializer));
            }

            foreach (AuthoredMember constructor in AuthoredMembers.Where(
                candidate => candidate.Symbol.MethodKind
                        == MethodKind.Constructor
                    && SymbolEqualityComparer.Default.Equals(
                        candidate.Symbol.ContainingType,
                        field.ContainingType)
                    && (boundConstructors.Length == 0
                        || boundConstructors.Any(bound =>
                            SymbolEqualityComparer.Default.Equals(
                                bound.OriginalDefinition,
                                candidate.Symbol.OriginalDefinition)))))
            {
                if (constructor.Syntax.DescendantNodesAndSelf().Any(node =>
                    node is RefExpressionSyntax alias
                        && SymbolEqualityComparer.Default.Equals(
                            constructor.Model.GetSymbolInfo(alias.Expression).Symbol,
                            field)
                    || node is ArgumentSyntax argument
                        && argument.RefKindKeyword.Kind() is SyntaxKind.RefKeyword or SyntaxKind.OutKeyword
                        && SymbolEqualityComparer.Default.Equals(
                            constructor.Model.GetSymbolInfo(argument.Expression).Symbol,
                            field)))
                {
                    return [];
                }

                values.AddRange(constructor.Syntax.DescendantNodesAndSelf(
                        node => node == constructor.Syntax
                            || node is not AnonymousFunctionExpressionSyntax
                                and not LocalFunctionStatementSyntax)
                    .OfType<AssignmentExpressionSyntax>()
                    .Where(assignment => assignment.IsKind(
                            SyntaxKind.SimpleAssignmentExpression)
                        && SymbolEqualityComparer.Default.Equals(
                            constructor.Model.GetSymbolInfo(
                                assignment.Left).Symbol,
                            field))
                    .Select(assignment => new BoundValueSource(
                        expression is IdentifierNameSyntax or MemberAccessExpressionSyntax { Expression: ThisExpressionSyntax }
                            && SymbolEqualityComparer.Default.Equals(field.ContainingType, member.Symbol.ContainingType)
                            ? MergeValueContext(constructor, member)
                            : constructor,
                        assignment.Right)));
            }

            return values.ToArray();
        }

        private static IMethodSymbol[] BoundConstructorContexts(
            AuthoredMember member,
            INamedTypeSymbol containingType) =>
            (member.ConstructorContexts
                ?? Enumerable.Empty<IMethodSymbol>())
            .Concat(
                (member.ValueBindings?.Keys
                    ?? Enumerable.Empty<ISymbol>())
                .OfType<IParameterSymbol>()
                .Select(static parameter => parameter.ContainingSymbol)
                .OfType<IMethodSymbol>())
            .Where(constructor =>
                constructor.MethodKind == MethodKind.Constructor
                && SymbolEqualityComparer.Default.Equals(
                    constructor.ContainingType,
                    containingType))
            .DistinctBy(
                static constructor => constructor.OriginalDefinition,
                SymbolEqualityComparer.Default)
            .ToArray();

        private static int InstanceConstructorCount(
            INamedTypeSymbol containingType) =>
            containingType.InstanceConstructors
                .DistinctBy(
                    static constructor => constructor.OriginalDefinition,
                    SymbolEqualityComparer.Default)
                .Count();

        private bool IsExactRegistrationFactoryArgument(
            AuthoredMember member,
            IParameterSymbol parameter,
            BoundValueSource source,
            ITypeSymbol contract)
        {
            if (parameter.ContainingSymbol is not IMethodSymbol
                {
                    MethodKind: MethodKind.Constructor,
                } constructor
                || !SymbolEqualityComparer.Default.Equals(
                    constructor.ContainingType,
                    member.Symbol.ContainingType))
            {
                return false;
            }

            BoundContractIdentity key = new(
                constructor.ContainingAssembly.Identity,
                TypeKey(constructor.ContainingType));

            ResolvedRegistration[] registrations =
                (diActivationRegistrations.TryGetValue(key, out var candidates)
                    ? candidates
                    : [])
                .DistinctBy(
                    static candidate => candidate.Call,
                    ReferenceEqualityComparer.Instance)
                .ToArray();

            if (registrations is not [ResolvedRegistration registration]
                || !TryDiActivationFor(
                    registration.Call,
                    registration.Method,
                    registration.Model,
                    constructor,
                    parameter,
                    contract,
                    member.Model.Compilation,
                    out bool exact)
                || !exact
                || registration.Call.ArgumentList.Arguments is not
                    [ArgumentSyntax { Expression: AnonymousFunctionExpressionSyntax factory }]
                || !TryResolveExactFactoryConstruction(
                    factory,
                    registration.Model,
                    constructor.ContainingType,
                    member.Model.Compilation,
                    out AuthoredMember factoryMember,
                    out BaseObjectCreationExpressionSyntax creation,
                    out AuthoredMember constructionContext)
                || constructionContext.Symbol is not IMethodSymbol created
                || ResolveDiConstructorDependency(
                    created,
                    constructor,
                    parameter,
                    contract,
                    member.Model.Compilation,
                    0) is not { } dependency
                || !SymbolEqualityComparer.Default.Equals(
                    factoryMember.Symbol,
                    source.Caller.Symbol)
                || !ReferenceEquals(
                    source.Caller.Model.Compilation,
                    registration.Model.Compilation))
            {
                return false;
            }

            IParameterSymbol? provider = factory switch
            {
                SimpleLambdaExpressionSyntax simple =>
                    registration.Model.GetDeclaredSymbol(simple.Parameter),
                ParenthesizedLambdaExpressionSyntax
                {
                    ParameterList.Parameters: [ParameterSyntax syntax],
                } => registration.Model.GetDeclaredSymbol(syntax),
                _ => null,
            };

            IArgumentOperation[] arguments =
                registration.Model.GetOperation(creation) is IObjectCreationOperation operation
                    ? operation.Arguments.Where(argument =>
                        argument.Parameter?.Ordinal == dependency.Ordinal).ToArray()
                    : [];

            return provider is not null
                && IsExactFrameworkType(
                    provider.Type,
                    "System.IServiceProvider",
                    typeof(IServiceProvider).Assembly.GetName())
                && !HasConstructorDependencyMutation(factoryMember, provider)
                && arguments is
                    [IArgumentOperation { Value.Syntax: ExpressionSyntax argumentValue }]
                && argumentValue.SyntaxTree == source.Expression.SyntaxTree
                && StripTransparentExpression(argumentValue).Span
                    == StripTransparentExpression(source.Expression).Span
                && (IsExactFactoryServiceResolution(
                        registration.Model,
                        argumentValue,
                        provider,
                        contract,
                        member.Model.Compilation)
                    || IsExactOptionalFactoryServiceResolution(
                        registration.Model,
                        argumentValue,
                        provider,
                        contract,
                        member.Model.Compilation));
        }

        private bool TryExactAbsentOptionalDiDefault(
            AuthoredMember member,
            IParameterSymbol parameter,
            out BoundValueSource source)
        {
            source = null!;

            if (parameter.RefKind != RefKind.None
                || parameter.ContainingSymbol is not IMethodSymbol
                {
                    MethodKind: MethodKind.Constructor,
                    IsStatic: false,
                } constructor
                || !SymbolEqualityComparer.Default.Equals(
                    constructor.ContainingType,
                    member.Symbol.ContainingType)
                || !parameter.HasExplicitDefaultValue
                || parameter.ExplicitDefaultValue is not null
                || parameter.DeclaringSyntaxReferences
                    .Select(static reference => reference.GetSyntax())
                    .OfType<ParameterSyntax>()
                    .SingleOrDefault() is not
                    {
                        Default.Value: { } defaultExpression,
                    }
                || !semanticModels.TryGetValue(
                    defaultExpression.SyntaxTree,
                    out SemanticModel? defaultModel)
                || defaultModel.GetConstantValue(defaultExpression) is not
                    {
                        HasValue: true,
                        Value: null,
                    }
                || !IsSemanticallyEmptyCleanupValue(
                    defaultModel,
                    defaultExpression))
            {
                return false;
            }

            DiConstructorDependencyIdentity identity = new(
                TypeIdentity(
                    constructor.ContainingType,
                    member.Model.Compilation),
                MethodKey(constructor),
                parameter.Ordinal,
                TypeIdentity(
                    parameter.Type,
                    member.Model.Compilation));

            if (!absentOptionalDiDefaults.TryGetValue(
                    identity,
                    out bool eligible))
            {
                eligible = HasExactAbsentOptionalDiDefaultCertificate(
                    member,
                    constructor,
                    parameter);

                absentOptionalDiDefaults.Add(identity, eligible);
            }

            if (!eligible)
            {
                return false;
            }

            source = new(
                ValueExpressionContext(
                    member,
                    defaultExpression,
                    defaultModel),
                defaultExpression);

            return true;
        }

        private bool HasExactAbsentOptionalDiDefaultCertificate(
            AuthoredMember member,
            IMethodSymbol constructor,
            IParameterSymbol parameter)
        {
            if (ResolveConstructorContextTarget(
                    constructor,
                    member.Model.Compilation) is not { } constructorMember
                || HasConstructorDependencyMutation(
                    constructorMember,
                    parameter))
            {
                return false;
            }

            BoundContractIdentity ownerKey = new(
                constructor.ContainingAssembly.Identity,
                TypeKey(constructor.ContainingType));

            List<(ResolvedRegistration Registration, bool Exact)> activations = [];

            foreach (ResolvedRegistration candidate in
                (diActivationRegistrations.TryGetValue(
                        ownerKey,
                        out List<ResolvedRegistration>? registrations)
                    ? registrations
                    : [])
                .DistinctBy(
                    static registration => registration.Call,
                    ReferenceEqualityComparer.Instance)
                .Where(registration =>
                    IsExactRootFactoryRegistrationMethod(
                        registration.Method)))
            {
                if (TryDiActivationFor(
                        candidate.Call,
                        candidate.Method,
                        candidate.Model,
                        constructor,
                        parameter,
                        parameter.Type,
                        member.Model.Compilation,
                        out bool exact))
                {
                    activations.Add((candidate, exact));
                }
            }

            if (activations.Count != 1
                || !activations[0].Exact)
            {
                return false;
            }

            InvocationExpressionSyntax activation =
                activations[0].Registration.Call;

            IReadOnlyDictionary<InvocationExpressionSyntax, RecoveryCompositionKind>
                compositions = RecoveryRegistrationCompositions();

            if (!compositions.GetValueOrDefault(activation)
                    .HasFlag(RecoveryCompositionKind.Serving)
                || !recoveryRegistrationMustExecuteCompositions
                    .GetValueOrDefault(activation)
                    .HasFlag(RecoveryCompositionKind.Serving)
                || invalidRecoveryComposition.HasFlag(
                    RecoveryCompositionKind.Serving)
                || invocations.Any(candidate =>
                    candidate.Model.GetSymbolInfo(candidate.Call).Symbol is
                        IMethodSymbol candidateMethod
                    && IsApplicableServiceRegistrationMutation(
                        candidate.Call,
                        candidate.Model,
                        candidateMethod,
                        (candidateType, candidateCompilation) =>
                            SameBoundType(
                                candidateType,
                                candidateCompilation,
                                parameter.Type,
                                member.Model.Compilation))))
            {
                return false;
            }

            return true;
        }

        private bool IsExactRegisteredConstructorDependency(
            AuthoredMember member,
            IParameterSymbol parameter,
            ITypeSymbol contract)
        {
            if (parameter.ContainingSymbol is not IMethodSymbol
                {
                    MethodKind: MethodKind.Constructor,
                } constructor
                || !SymbolEqualityComparer.Default.Equals(
                    constructor.ContainingType,
                    member.Symbol.ContainingType)
                || !SameBoundType(
                    parameter.Type,
                    member.Model.Compilation,
                    contract,
                    member.Model.Compilation))
            {
                return false;
            }

            BoundTypeIdentity owner = TypeIdentity(
                constructor.ContainingType,
                member.Model.Compilation);

            BoundTypeIdentity contractIdentity = TypeIdentity(
                contract,
                member.Model.Compilation);

            DiConstructorDependencyIdentity identity = new(
                owner,
                MethodKey(constructor),
                parameter.Ordinal,
                contractIdentity);

            if (diConstructorDependencies.TryGetValue(
                    identity,
                    out bool cached))
            {
                return cached;
            }

            bool observed = false;

            bool exact = true;

            BoundContractIdentity registrationKey = new(
                constructor.ContainingAssembly.Identity,
                TypeKey(constructor.ContainingType));

            foreach (ResolvedRegistration candidate in
                diActivationRegistrations.TryGetValue(
                    registrationKey,
                    out List<ResolvedRegistration>? registrations)
                        ? registrations
                        : [])
            {
                registrationCandidateInspections++;

                InvocationExpressionSyntax registration = candidate.Call;

                SemanticModel model = candidate.Model;

                IMethodSymbol registrationMethod = candidate.Method;

                if (!TryDiActivationFor(
                        registration,
                        registrationMethod,
                        model,
                        constructor,
                        parameter,
                        contract,
                        member.Model.Compilation,
                        out bool exactActivation))
                {
                    continue;
                }

                observed = true;

                exact &= exactActivation;
            }

            bool result = observed && exact;

            diConstructorDependencies.Add(identity, result);

            return result;
        }

        private bool TryDiActivationFor(
            InvocationExpressionSyntax registration,
            IMethodSymbol method,
            SemanticModel model,
            IMethodSymbol constructor,
            IParameterSymbol dependency,
            ITypeSymbol contract,
            Compilation consumingCompilation,
            out bool exact)
        {
            exact = false;

            bool hosted = IsExactFrameworkMethod(
                method,
                "Microsoft.Extensions.DependencyInjection.ServiceCollectionHostedServiceExtensions",
                "AddHostedService",
                "Microsoft.Extensions.Hosting.Abstractions");

            bool service = method.Name is
                    "AddSingleton" or "AddScoped" or "AddTransient"
                && IsExactFrameworkMethod(
                    method,
                    "Microsoft.Extensions.DependencyInjection.ServiceCollectionServiceExtensions",
                    method.Name,
                    "Microsoft.Extensions.DependencyInjection.Abstractions");

            bool tryService = method.Name is
                    "TryAddSingleton" or "TryAddScoped" or "TryAddTransient"
                && IsExactFrameworkMethod(
                    method,
                    "Microsoft.Extensions.DependencyInjection.Extensions.ServiceCollectionDescriptorExtensions",
                    method.Name,
                    "Microsoft.Extensions.DependencyInjection.Abstractions");

            bool resetAware =
                IsExactResetAwareHostedServiceRegistration(method);

            bool scopedDescriptor = IsExactIndexedScopedDescriptor(registration, method, model);

            if (!hosted && !service && !tryService && !resetAware && !scopedDescriptor)
            {
                return false;
            }

            INamedTypeSymbol owner = constructor.ContainingType;

            bool namesOwner = method.TypeArguments switch
            {
                [ITypeSymbol implementation]
                    when SameBoundType(
                        implementation,
                        model.Compilation,
                        owner,
                        consumingCompilation) => true,
                [_, ITypeSymbol implementation]
                    when SameBoundType(
                        implementation,
                        model.Compilation,
                        owner,
                        consumingCompilation) => true,
                _ => false,
            };

            ArgumentSyntax[] arguments = registration.ArgumentList.Arguments
                .ToArray();

            if (namesOwner && arguments.Length == 0)
            {
                IMethodSymbol[] constructors = owner.InstanceConstructors
                    .Where(static candidate => !candidate.IsStatic
                        && candidate.DeclaredAccessibility
                            == Accessibility.Public)
                    .DistinctBy(
                        static candidate => candidate.OriginalDefinition,
                        SymbolEqualityComparer.Default)
                    .ToArray();

                exact = constructors is [IMethodSymbol only]
                    && (SymbolEqualityComparer.Default.Equals(
                            only.OriginalDefinition,
                            constructor.OriginalDefinition)
                        || IsExactOneHopDiConstructorDependencyForwarding(
                            only,
                            constructor,
                            dependency,
                            contract,
                            consumingCompilation));

                return true;
            }

            if (arguments is not [ArgumentSyntax argument]
                || argument.Expression is not
                    AnonymousFunctionExpressionSyntax factory)
            {
                return namesOwner;
            }

            IParameterSymbol? provider = factory switch
            {
                SimpleLambdaExpressionSyntax simple =>
                    model.GetDeclaredSymbol(simple.Parameter),
                ParenthesizedLambdaExpressionSyntax
                {
                    ParameterList.Parameters: [ParameterSyntax parameter],
                } => model.GetDeclaredSymbol(parameter),
                _ => null,
            };

            if (provider is not null
                && ExactFactoryCreation(factory) is { } forwardedService
                && IsExactFactoryServiceResolution(model, forwardedService, provider, owner, consumingCompilation))
            {
                // An alias resolves an existing registration; it does not activate a constructor.
                return false;
            }

            if (!TryResolveExactFactoryConstruction(
                    factory,
                    model,
                    owner,
                    consumingCompilation,
                    out AuthoredMember factoryMember,
                    out BaseObjectCreationExpressionSyntax creation,
                    out AuthoredMember constructionContext)
                || constructionContext.Symbol is not
                    IMethodSymbol createdConstructor
                || ResolveDiConstructorDependency(createdConstructor, constructor, dependency, contract, consumingCompilation, 0) is not { } activationDependency)
            {
                return namesOwner;
            }

            IArgumentOperation[] dependencyArguments =
                model.GetOperation(creation) is
                    IObjectCreationOperation operation
                    ? operation.Arguments.Where(argumentOperation =>
                            argumentOperation.Parameter?.Ordinal
                                == activationDependency.Ordinal)
                        .ToArray()
                    : [];

            exact = provider is not null
                && IsExactFrameworkType(
                    provider.Type,
                    "System.IServiceProvider",
                    typeof(IServiceProvider).Assembly.GetName())
                && !HasConstructorDependencyMutation(
                    factoryMember,
                    provider)
                && dependencyArguments is
                    [IArgumentOperation
                    {
                        Value.Syntax: ExpressionSyntax dependencyValue,
                    }]
                && (IsExactFactoryServiceResolution(
                        model,
                        dependencyValue,
                        provider,
                        contract,
                        consumingCompilation)
                    || ResolveCallable(factory, model, null, null) is
                    { } optionalFactoryMember
                    && !HasConstructorDependencyMutation(
                        optionalFactoryMember,
                        provider)
                    && IsExactOptionalFactoryServiceResolution(
                        model,
                        dependencyValue,
                        provider,
                        contract,
                        consumingCompilation));

            return true;
        }

        private IParameterSymbol? ResolveDiConstructorDependency(
            IMethodSymbol activationConstructor,
            IMethodSymbol assignedConstructor,
            IParameterSymbol assignedDependency,
            ITypeSymbol contract,
            Compilation consumingCompilation,
            int depth)
        {
            if (depth >= ReceiverCleanupForwardingMaximumDepth
                || ResolveConstructorContextTarget(activationConstructor, consumingCompilation) is not { } activation
                || !SameBoundType(activation.Symbol.ContainingType, activation.Model.Compilation, assignedConstructor.ContainingType, consumingCompilation))
            {
                return null;
            }

            if (MethodKey(activation.Symbol) == MethodKey(assignedConstructor))
            {
                IParameterSymbol? parameter = activation.Symbol.Parameters.ElementAtOrDefault(assignedDependency.Ordinal);

                return parameter is not null && !HasConstructorDependencyMutation(activation, parameter) ? parameter : null;
            }

            if (activation.Syntax is not ConstructorDeclarationSyntax { Initializer: { } initializer }
                || !initializer.ThisOrBaseKeyword.IsKind(SyntaxKind.ThisKeyword)
                || activation.Model.GetSymbolInfo(initializer).Symbol is not IMethodSymbol delegated
                || ResolveDiConstructorDependency(delegated, assignedConstructor, assignedDependency, contract, consumingCompilation, depth + 1) is not { } delegatedDependency)
            {
                return null;
            }

            ArgumentSyntax[] arguments = initializer.ArgumentList.Arguments.Where(argument =>
                (activation.Model.GetOperation(argument) as IArgumentOperation)?.Parameter?.Ordinal == delegatedDependency.Ordinal).ToArray();

            return arguments is [ArgumentSyntax { Expression: IdentifierNameSyntax identifier } argument]
                && argument.RefKindKeyword.IsKind(SyntaxKind.None)
                && activation.Model.GetSymbolInfo(identifier).Symbol is IParameterSymbol { RefKind: RefKind.None } forwarded
                && SymbolEqualityComparer.Default.Equals(forwarded.ContainingSymbol, activation.Symbol)
                && SameBoundType(forwarded.Type, activation.Model.Compilation, contract, consumingCompilation)
                && !HasConstructorDependencyMutation(activation, forwarded)
                    ? forwarded
                    : null;
        }

        private bool IsExactOneHopDiConstructorDependencyForwarding(
            IMethodSymbol activationConstructor,
            IMethodSymbol assignedConstructor,
            IParameterSymbol assignedDependency,
            ITypeSymbol contract,
            Compilation consumingCompilation)
        {
            if (Resolve(
                    activationConstructor,
                    consumingCompilation) is not
                    {
                        Syntax: ConstructorDeclarationSyntax
                        {
                            Initializer: { } initializer,
                        },
                    } activation
                || !initializer.ThisOrBaseKeyword.IsKind(
                    SyntaxKind.ThisKeyword)
                || activation.Model.GetSymbolInfo(initializer).Symbol is not
                    IMethodSymbol delegatedConstructor
                || !SymbolEqualityComparer.Default.Equals(
                    delegatedConstructor.OriginalDefinition,
                    assignedConstructor.OriginalDefinition)
                || Resolve(
                    assignedConstructor,
                    consumingCompilation) is not { } assigned
                || assigned.Symbol.Parameters.ElementAtOrDefault(
                    assignedDependency.Ordinal) is not
                    { } resolvedAssignedDependency
                || HasConstructorDependencyMutation(
                    assigned,
                    resolvedAssignedDependency))
            {
                return false;
            }

            ArgumentSyntax[] forwardedArguments = initializer.ArgumentList
                .Arguments
                .Where(argument =>
                    (activation.Model.GetOperation(argument) as
                        IArgumentOperation)?.Parameter?.Ordinal
                            == assignedDependency.Ordinal)
                .ToArray();

            return forwardedArguments is
                [ArgumentSyntax
                {
                    Expression: IdentifierNameSyntax identifier,
                } argument]
                && argument.RefKindKeyword.IsKind(SyntaxKind.None)
                && activation.Model.GetSymbolInfo(identifier).Symbol is
                    IParameterSymbol
                {
                    RefKind: RefKind.None,
                } forwardedDependency
                && forwardedDependency.ContainingSymbol is
                    IMethodSymbol forwardedConstructor
                && SymbolEqualityComparer.Default.Equals(
                    forwardedConstructor.OriginalDefinition,
                    activationConstructor.OriginalDefinition)
                && SameBoundType(
                    forwardedDependency.Type,
                    activation.Model.Compilation,
                    contract,
                    consumingCompilation);
        }

        private static bool HasConstructorDependencyMutation(
            AuthoredMember constructor,
            IParameterSymbol dependency)
        {
            bool ReferencesDependency(SyntaxNode node) =>
                node.DescendantNodesAndSelf()
                    .OfType<ExpressionSyntax>()
                    .Any(expression => SymbolEqualityComparer.Default.Equals(
                        constructor.Model.GetSymbolInfo(expression).Symbol,
                        dependency));

            return constructor.Syntax.DescendantNodes().Any(node => node switch
            {
                AssignmentExpressionSyntax assignment =>
                    ReferencesDependency(assignment.Left),
                RefExpressionSyntax alias =>
                    ReferencesDependency(alias.Expression),
                ArgumentSyntax argument
                    when argument.RefKindKeyword.IsKind(SyntaxKind.RefKeyword)
                        || argument.RefKindKeyword.IsKind(
                            SyntaxKind.OutKeyword) =>
                    ReferencesDependency(argument.Expression),
                _ => false,
            });
        }

        private static ExpressionSyntax? ExactFactoryCreation(
            AnonymousFunctionExpressionSyntax factory) => factory switch
            {
                SimpleLambdaExpressionSyntax simple =>
                    simple.ExpressionBody as ExpressionSyntax,
                ParenthesizedLambdaExpressionSyntax parenthesized =>
                    parenthesized.ExpressionBody as ExpressionSyntax,
                _ => null,
            };

        private bool TryResolveExactFactoryConstruction(
            AnonymousFunctionExpressionSyntax factory,
            SemanticModel model,
            INamedTypeSymbol expectedType,
            Compilation expectedCompilation,
            out AuthoredMember factoryMember,
            out BaseObjectCreationExpressionSyntax creation,
            out AuthoredMember constructionContext)
        {
            factoryMember = null!;

            creation = null!;

            constructionContext = null!;

            if (ResolveCallable(factory, model, null, null) is not
                { } resolvedFactory
                || ReturnedExpressions(resolvedFactory.Syntax) is not
                    [ExpressionSyntax returned])
            {
                return false;
            }

            BaseObjectCreationExpressionSyntax? exactCreation =
                returned as BaseObjectCreationExpressionSyntax
                ?? ExactReturnedLocalFactoryCreation(
                    resolvedFactory,
                    returned,
                    expectedType,
                    expectedCompilation);

            if (exactCreation is null
                || model.GetSymbolInfo(exactCreation).Symbol is not
                    IMethodSymbol creationConstructor
                || !SameBoundType(
                    creationConstructor.ContainingType,
                    model.Compilation,
                    expectedType,
                    expectedCompilation)
                || ResolveConstructedReceiverContext(
                    resolvedFactory,
                    returned,
                    creationConstructor.ContainingType,
                    new HashSet<(
                        GraphMemberIdentity Member,
                        int Start,
                        int Length)>()) is not { } constructed
                || constructed.Symbol is not IMethodSymbol constructor
                || !SymbolEqualityComparer.Default.Equals(
                    creationConstructor.OriginalDefinition,
                    constructor.OriginalDefinition)
                || !SameBoundType(
                    constructor.ContainingType,
                    constructed.Model.Compilation,
                    expectedType,
                    expectedCompilation))
            {
                return false;
            }

            factoryMember = resolvedFactory;

            creation = exactCreation;

            constructionContext = constructed;

            return true;
        }

        private BaseObjectCreationExpressionSyntax?
            ExactReturnedLocalFactoryCreation(
                AuthoredMember factory,
                ExpressionSyntax returned,
                INamedTypeSymbol expectedType,
                Compilation expectedCompilation)
        {
            if (factory.Syntax is not BlockSyntax block
                || factory.Model.GetSymbolInfo(returned).Symbol is not
                    ILocalSymbol local
                || returned.Parent is not ReturnStatementSyntax
                {
                    Parent: BlockSyntax returnBlock,
                }
                || returnBlock != block
                || local.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax()
                    is not VariableDeclaratorSyntax
                    {
                        Initializer.Value:
                            BaseObjectCreationExpressionSyntax creation,
                        Parent.Parent:
                            LocalDeclarationStatementSyntax declaration,
                    }
                || declaration.Parent != block
                || factory.Model.GetTypeInfo(creation).Type is not
                    INamedTypeSymbol createdType
                || !SameBoundType(
                    createdType,
                    factory.Model.Compilation,
                    expectedType,
                    expectedCompilation))
            {
                return null;
            }

            List<ExpressionSyntax> allowedReferences = [returned];

            foreach (StatementSyntax statement in block.Statements)
            {
                if (statement == declaration
                    || statement == returned.Parent)
                {
                    continue;
                }

                if (statement is not ExpressionStatementSyntax
                    {
                        Expression: InvocationExpressionSyntax call,
                    }
                    || call.Expression is not MemberAccessExpressionSyntax
                    {
                        Expression: { } receiver,
                    }
                    || !SymbolEqualityComparer.Default.Equals(
                        factory.Model.GetSymbolInfo(receiver).Symbol,
                        local)
                    || factory.Model.GetSymbolInfo(call).Symbol is not
                        IMethodSymbol
                    {
                        IsStatic: false,
                        ReturnsVoid: true,
                    } method
                    || ResolveInvocationTarget(method, factory, call) is not
                    { } configuration
                    || !SameBoundType(
                        configuration.Symbol.ContainingType,
                        configuration.Model.Compilation,
                        expectedType,
                        expectedCompilation)
                    || configuration.Symbol.ContainingType
                        .InstanceConstructors
                        .SelectMany(static constructor =>
                            constructor.Parameters)
                        .Any(parameter => HasConstructorDependencyMutation(
                            configuration,
                            parameter)))
                {
                    return null;
                }

                allowedReferences.Add(receiver);
            }

            BaseObjectCreationExpressionSyntax[] constructions = block
                .DescendantNodes(node => node == block
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<BaseObjectCreationExpressionSyntax>()
                .Where(candidate => factory.Model.GetTypeInfo(candidate).Type
                        is INamedTypeSymbol candidateType
                    && SameBoundType(
                        candidateType,
                        factory.Model.Compilation,
                        expectedType,
                        expectedCompilation))
                .ToArray();

            return constructions is [BaseObjectCreationExpressionSyntax exact]
                && exact == creation
                && HasOnlyReferences(
                    factory,
                    local,
                    allowedReferences.ToArray())
                    ? creation
                    : null;
        }

        private bool IsExactFactoryServiceResolution(
            SemanticModel model,
            ExpressionSyntax expression,
            IParameterSymbol provider,
            ITypeSymbol contract,
            Compilation consumingCompilation)
        {
            expression = StripTransparentExpression(expression);

            return expression is InvocationExpressionSyntax resolution
                && model.GetSymbolInfo(resolution).Symbol is
                    IMethodSymbol resolver
                && IsExactFrameworkMethod(
                    resolver,
                    "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions",
                    "GetRequiredService",
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
                && resolver.TypeArguments is [ITypeSymbol resolved]
                && SameBoundType(
                    resolved,
                    model.Compilation,
                    contract,
                    consumingCompilation)
                && resolution.ArgumentList.Arguments.Count == 0
                && resolution.Expression is MemberAccessExpressionSyntax
                {
                    Expression: { } providerExpression,
                }
                && SymbolEqualityComparer.Default.Equals(
                    model.GetSymbolInfo(providerExpression).Symbol,
                    provider);
        }

        private bool IsExactOptionalFactoryServiceResolution(
            SemanticModel model,
            ExpressionSyntax expression,
            IParameterSymbol provider,
            ITypeSymbol contract,
            Compilation consumingCompilation)
        {
            expression = StripTransparentExpression(expression);

            return expression is InvocationExpressionSyntax resolution
                && model.GetSymbolInfo(resolution).Symbol is
                    IMethodSymbol resolver
                && IsExactFrameworkMethod(
                    resolver,
                    "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions",
                    "GetService",
                    "Microsoft.Extensions.DependencyInjection.Abstractions")
                && resolver.TypeArguments is [ITypeSymbol resolved]
                && SameBoundType(
                    resolved,
                    model.Compilation,
                    contract,
                    consumingCompilation)
                && resolution.ArgumentList.Arguments.Count == 0
                && resolution.Expression is MemberAccessExpressionSyntax
                {
                    Expression: { } providerExpression,
                }
                && SymbolEqualityComparer.Default.Equals(
                    model.GetSymbolInfo(providerExpression).Symbol,
                    provider)
                && IsExactFrameworkType(
                    provider.Type,
                    "System.IServiceProvider",
                    typeof(IServiceProvider).Assembly.GetName())
                && HasExactOptionalServiceRegistration(
                    contract,
                    consumingCompilation);
        }

        private bool HasExactOptionalServiceRegistration(
            ITypeSymbol contract,
            Compilation consumingCompilation)
        {
            BoundContractIdentity registrationKey = new(
                contract.ContainingAssembly.Identity,
                TypeKey(contract));

            ResolvedRegistration[] serviceRegistrations =
                (diActivationRegistrations.TryGetValue(
                        registrationKey,
                        out List<ResolvedRegistration>? registrations)
                    ? registrations
                    : [])
                .DistinctBy(
                    static registration => registration.Call,
                    ReferenceEqualityComparer.Instance)
                .ToArray();

            if (serviceRegistrations is not
                    [ResolvedRegistration serviceRegistration]
                || !IsExactRootFactoryRegistrationMethod(
                    serviceRegistration.Method)
                || serviceRegistration.Method.TypeArguments.FirstOrDefault()
                    is not { } registeredContract
                || !SameBoundType(
                    registeredContract,
                    serviceRegistration.Model.Compilation,
                    contract,
                    consumingCompilation)
                || ExactOptionalServiceRegistrationCreation(
                    serviceRegistration) is not { } serviceCreation
                || serviceRegistration.Model.GetSymbolInfo(serviceCreation)
                    .Symbol is not IMethodSymbol serviceConstructor)
            {
                return false;
            }

            BoundTypeIdentity contractIdentity = TypeIdentity(
                contract,
                consumingCompilation);

            ServiceBinding[] exactBindings = bindings
                .Where(binding => binding.Contract == contractIdentity)
                .ToArray();

            return exactBindings is [ServiceBinding exactBinding]
                && exactBinding.Implementation == TypeIdentity(
                    serviceConstructor.ContainingType,
                    serviceRegistration.Model.Compilation);
        }

        private static BaseObjectCreationExpressionSyntax?
            ExactOptionalServiceRegistrationCreation(
                ResolvedRegistration registration) =>
            registration.Call.ArgumentList.Arguments.ToArray() switch
            {
                [ArgumentSyntax
                {
                    Expression: AnonymousFunctionExpressionSyntax factory,
                }] => ExactFactoryCreation(factory) as
                    BaseObjectCreationExpressionSyntax,
                [ArgumentSyntax
                {
                    Expression: BaseObjectCreationExpressionSyntax creation,
                }] => creation,
                _ => null,
            };

        private static ExpressionSyntax ExactNonThrowingValue(
            ExpressionSyntax expression)
        {
            expression = StripTransparentExpression(expression);

            if (expression is BinaryExpressionSyntax coalescing
                && coalescing.IsKind(SyntaxKind.CoalesceExpression)
                && StripTransparentExpression(coalescing.Right)
                    is ThrowExpressionSyntax)
            {
                return StripTransparentExpression(coalescing.Left);
            }

            return expression;
        }

        private CleanupProvenance LocalCleanupProvenance(
            AuthoredMember member,
            ExpressionSyntax use,
            ILocalSymbol local,
            CleanupProvenanceContext context)
        {
            SyntaxNode? declaration = local.DeclaringSyntaxReferences
                .SingleOrDefault()?.GetSyntax();

            if (declaration is
                    SingleVariableDesignationSyntax positiveDesignation
                && ExactPositivePatternValue(
                    member,
                    use,
                    local,
                    positiveDesignation) is { } positiveValue)
            {
                return CleanupProvenanceOf(
                    member,
                    positiveValue,
                    context);
            }

            if (declaration is ForEachStatementSyntax loop && local.RefKind == RefKind.None)
            {
                CleanupValueFlow elements = CollectionElementValueFlow(member, loop.Expression, context);

                CleanupProvenance provenance = MergeCleanupProvenance(elements.Values.Select(value =>
                    CleanupProvenanceOf(value.Caller, value.Expression, context)));

                return provenance with
                {
                    Complete = elements.Complete && provenance.Complete,
                    HasAuthoredSource = elements.HasAuthoredSource || provenance.HasAuthoredSource,
                };
            }

            if (declaration is SingleVariableDesignationSyntax
                {
                    Parent: RecursivePatternSyntax
                    {
                        Type: null,
                        PositionalPatternClause: null,
                        PropertyPatternClause.Subpatterns.Count: 0,
                        Parent: IsPatternExpressionSyntax
                        {
                            Expression: { } positiveTested,
                            Parent: ConditionalExpressionSyntax conditional,
                        } pattern,
                    },
                }
                && conditional.Condition == pattern
                && conditional.WhenTrue.Span.Contains(use.Span)
                && pattern.Span.End <= use.SpanStart
                && SymbolIsStableBetween(
                    member,
                    local,
                    pattern.Span.End,
                    use))
            {
                CleanupProvenance positivePattern = CleanupProvenanceOf(
                    member,
                    positiveTested,
                    context);

                return positivePattern;
            }

            if (declaration is SingleVariableDesignationSyntax designation
                && (ExactConfiguredSqlitePatternLocalProvenance(
                        member,
                        use,
                        local,
                        designation,
                        context)
                    ?? ExactRuntimeTypeGuardedLocalProvenance(
                        member,
                        use,
                        local,
                        designation)) is { } guarded)
            {
                return guarded;
            }

            if (declaration is SingleVariableDesignationSyntax outDesignation
                && ExactAuthoredOutLocalCleanupProvenance(
                    member,
                    use,
                    local,
                    outDesignation,
                    context) is { } outProvenance)
            {
                return outProvenance;
            }

            if (declaration is not VariableDeclaratorSyntax variable
                || variable.Ancestors().OfType<BlockSyntax>().FirstOrDefault()
                    is not { } block)
            {
                return new([], false, false);
            }

            if (ExactFrameworkDictionaryRemovedValueFlow(
                    member,
                    use,
                    local,
                    null,
                    context,
                    variable) is { } existingRemoved)
            {
                CleanupProvenance removed = MergeCleanupProvenance(
                    existingRemoved.Values.Select(value =>
                        CleanupProvenanceOf(
                            value.Caller,
                            value.Expression,
                            context)));

                return removed with
                {
                    Complete = existingRemoved.Complete
                        && removed.Complete,
                    HasAuthoredSource = true,
                };
            }

            List<ExpressionSyntax> values = variable.Initializer is null
                ? []
                : [variable.Initializer.Value];

            bool exactWrites = true;

            foreach (SyntaxNode node in block.DescendantNodes(candidate =>
                candidate == block
                || candidate is not AnonymousFunctionExpressionSyntax
                    and not LocalFunctionStatementSyntax))
            {
                if (node.SpanStart >= use.SpanStart)
                {
                    continue;
                }

                if (node is AssignmentExpressionSyntax assignment
                    && SymbolEqualityComparer.Default.Equals(
                        member.Model.GetSymbolInfo(assignment.Left).Symbol,
                        local))
                {
                    if (assignment.IsKind(
                            SyntaxKind.SimpleAssignmentExpression))
                    {
                        values.Add(assignment.Right);
                    }
                    else
                    {
                        exactWrites = false;
                    }
                }
                else if (SyntaxNodeWritesSymbol(
                    member.Model,
                    node,
                    local))
                {
                    exactWrites = false;
                }
            }

            if (InvokedCallableMayMutateSymbol(
                member,
                local,
                use.SpanStart))
            {
                exactWrites = false;
            }

            if (values.Count == 0)
            {
                return new([], false, false);
            }

            CleanupProvenance merged = MergeCleanupProvenance(
                values.Select(value => CleanupProvenanceOf(
                    member,
                    value,
                    context)));

            return exactWrites
                ? merged
                : merged with
                {
                    Complete = false,
                };
        }

        private CleanupProvenance? ExactConfiguredSqlitePatternLocalProvenance(
            AuthoredMember member,
            ExpressionSyntax use,
            ILocalSymbol local,
            SingleVariableDesignationSyntax designation,
            CleanupProvenanceContext context)
        {
            IfStatementSyntax[] matchingGuards = designation.Ancestors()
                .OfType<IfStatementSyntax>()
                .Where(candidate => candidate.Condition.Span.Contains(
                    designation.Span))
                .Take(2)
                .ToArray();

            if (matchingGuards is not [IfStatementSyntax guard]
                || guard.Span.End >= use.SpanStart
                || StripTransparentExpression(guard.Condition) is not
                    IsPatternExpressionSyntax
                {
                    Expression: { } tested,
                    Pattern: UnaryPatternSyntax
                    {
                        Pattern: DeclarationPatternSyntax
                        {
                            Type: { } declaredType,
                            Designation: SingleVariableDesignationSyntax
                                    declared,
                        },
                    } notPattern,
                }
                || !notPattern.IsKind(SyntaxKind.NotPattern)
                || declared.SyntaxTree != designation.SyntaxTree
                || declared.Span != designation.Span
                || member.Model.GetTypeInfo(declaredType).Type is not
                { } patternType
                || !SameBoundType(
                    patternType,
                    member.Model.Compilation,
                    local.Type,
                    member.Model.Compilation)
                || !IsDirectNegativePatternTermination(guard.Statement))
            {
                return null;
            }

            ExpressionSyntax testedExpression =
                StripTransparentExpression(tested);

            CleanupProvenance configured = testedExpression
                    is InvocationExpressionSyntax configuredConnection
                && member.Model.GetSymbolInfo(configuredConnection).Symbol
                    is IMethodSymbol configuredConnectionMethod
                && ExactConfiguredSqliteConnectionProvenance(
                    member,
                    configuredConnection,
                    configuredConnectionMethod,
                    context) is { } direct
                    ? direct
                    : CleanupProvenanceOf(
                        member,
                        testedExpression,
                        context);

            if (!configured.Complete
                || configured.Candidates is not
                    [CleanupTypeCandidate candidate]
                || !SameBoundType(
                    candidate.Type,
                    member.Model.Compilation,
                    patternType,
                    member.Model.Compilation))
            {
                return null;
            }

            return SymbolIsStableWithin(
                member,
                local,
                guard.Span.End,
                use.SpanStart)
                    ? configured
                    : null;
        }

        private static bool IsDirectNegativePatternTermination(
            StatementSyntax statement) =>
            statement is ReturnStatementSyntax or ThrowStatementSyntax
            || statement is BlockSyntax
            {
                Statements: [ReturnStatementSyntax or ThrowStatementSyntax],
            };

        private CleanupProvenance? ExactAuthoredOutLocalCleanupProvenance(
            AuthoredMember member,
            ExpressionSyntax use,
            ILocalSymbol local,
            SingleVariableDesignationSyntax designation,
            CleanupProvenanceContext context)
        {
            if (TryExactAuthoredOutLocalAssignments(
                    member,
                    use,
                    local,
                    designation,
                    context) is not { } exact)
            {
                return null;
            }

            CleanupProvenance result = MergeCleanupProvenance(
                exact.Assignments.Select(assignment => CleanupProvenanceOf(
                    exact.Bound,
                    assignment.Right,
                    context)));

            return result with
            {
                Complete = result.Complete,
                HasAuthoredSource = true,
            };
        }

        private CleanupValueFlow? ExactAuthoredOutLocalCleanupValueFlow(
            AuthoredMember member,
            ExpressionSyntax use,
            ILocalSymbol local,
            SingleVariableDesignationSyntax designation,
            CleanupProvenanceContext context)
        {
            if (TryExactAuthoredOutLocalAssignments(
                    member,
                    use,
                    local,
                    designation,
                    context) is not { } exact)
            {
                return null;
            }

            CleanupValueFlow result = MergeCleanupValueFlow(
                exact.Assignments.Select(assignment => CleanupValueFlowOf(
                    exact.Bound,
                    assignment.Right,
                    context)));

            return result with
            {
                Complete = result.Complete,
                HasAuthoredSource = true,
            };
        }

        private AuthoredMember? ResolveAuthoredOutInvocationTarget(IMethodSymbol method,
            AuthoredMember member, InvocationExpressionSyntax call, CleanupProvenanceContext context)
        {
            if (ResolveInvocationTarget(method, member, call) is { } resolved) return resolved;

            // A literal construction stored in this readonly field closes the
            // receiver. An interface factory body or a registration name does not.
            if (context.RemainingWork-- <= 0 || method.ContainingType.TypeKind != TypeKind.Interface
                || AdmissionReceiver(member, call) is not { } receiver
                || receiver is not (IdentifierNameSyntax or MemberAccessExpressionSyntax { Expression: ThisExpressionSyntax })
                || member.Model.GetSymbolInfo(receiver).Symbol is not IFieldSymbol
                    { IsReadOnly: true, IsStatic: false, DeclaredAccessibility: Accessibility.Private } field
                || !SymbolEqualityComparer.Default.Equals(field.ContainingType, member.Symbol.ContainingType)
                || ExactReadOnlyFieldValues(member, receiver, field) is not [BoundValueSource source]
                || !TryNormalizeBuiltInCleanupValue(source.Caller.Model, source.Expression, out ExpressionSyntax literal)
                || literal is not BaseObjectCreationExpressionSyntax creation
                || source.Caller.Model.GetOperation(creation) is not IObjectCreationOperation
                    { Type: INamedTypeSymbol { IsSealed: true, IsAbstract: false } concrete, Constructor: not null }
                || !IsAuthoredCleanupSymbol(concrete, source.Caller.Model.Compilation)) return null;

            Dictionary<ISymbol, ITypeSymbol> bindings = new(SymbolEqualityComparer.Default);

            if (member.ConcreteBindings is { } previous)
            {
                foreach ((ISymbol symbol, ITypeSymbol type) in previous) bindings[symbol] = type;
            }

            bindings[field] = concrete;

            return ResolveInvocationTarget(method, member with { ConcreteBindings = bindings }, call);
        }

        private (AuthoredMember Bound, AssignmentExpressionSyntax[] Assignments)?
            TryExactAuthoredOutLocalAssignments(
                AuthoredMember member,
                ExpressionSyntax use,
                ILocalSymbol local,
                SingleVariableDesignationSyntax designation,
                CleanupProvenanceContext context)
        {
            if (designation.Ancestors().OfType<ArgumentSyntax>()
                    .FirstOrDefault() is not
                    {
                        RefKindKeyword.RawKind: (int)SyntaxKind.OutKeyword,
                        Parent.Parent: InvocationExpressionSyntax call,
                    } argument
                || member.Model.GetOperation(call) is not
                    IInvocationOperation operation
                || operation.Arguments.SingleOrDefault(candidate =>
                        candidate.Syntax == argument) is not
                    IArgumentOperation
                        {
                            Parameter: { } sourceParameter,
                        }
                || member.Model.GetSymbolInfo(call).Symbol is not
                    IMethodSymbol method
                || ResolveAuthoredOutInvocationTarget(method, member, call, context) is not
                { } target
                || sourceParameter.Ordinal >= target.Symbol.Parameters.Length
                || !SymbolIsStableWithin(
                    member,
                    local,
                    call.Span.End,
                    use.SpanStart))
            {
                return null;
            }

            IParameterSymbol parameter =
                target.Symbol.Parameters[sourceParameter.Ordinal];

            AuthoredMember bound = BindCleanupInvocationContext(
                member,
                call,
                target,
                context);

            HashSet<GraphMemberIdentity> forwardingPath = [];

            for (int depth = 0;
                depth < ReceiverCleanupForwardingMaximumDepth;
                depth++)
            {
                if (!forwardingPath.Add(MemberIdentity(bound)))
                {
                    return null;
                }

                AssignmentExpressionSyntax[] currentAssignments = bound.Syntax
                    .DescendantNodesAndSelf(node => node == bound.Syntax
                        || node is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .OfType<AssignmentExpressionSyntax>()
                    .Where(assignment => assignment.IsKind(
                            SyntaxKind.SimpleAssignmentExpression)
                        && SymbolEqualityComparer.Default.Equals(
                            bound.Model.GetSymbolInfo(assignment.Left).Symbol,
                            parameter))
                    .ToArray();

                if (currentAssignments.Length != 0)
                {
                    break;
                }

                if (!TryExactTailOutParameterForwarding(
                        bound,
                        parameter,
                        context,
                        out AuthoredMember forwarded,
                        out IParameterSymbol forwardedParameter))
                {
                    return null;
                }

                bound = forwarded;

                parameter = forwardedParameter;
            }

            AssignmentExpressionSyntax[] assignments = bound.Syntax
                .DescendantNodesAndSelf(node => node == bound.Syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<AssignmentExpressionSyntax>()
                .Where(assignment => assignment.IsKind(
                        SyntaxKind.SimpleAssignmentExpression)
                    && SymbolEqualityComparer.Default.Equals(
                        bound.Model.GetSymbolInfo(assignment.Left).Symbol,
                        parameter))
                .ToArray();

            if (assignments.Length == 0
                || bound.Syntax.DescendantNodesAndSelf(node =>
                        node == bound.Syntax
                        || node is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .OfType<ArgumentSyntax>()
                    .Any(candidate => candidate != argument
                        && candidate.RefKindKeyword.Kind() is
                            SyntaxKind.RefKeyword or SyntaxKind.OutKeyword
                        && SymbolEqualityComparer.Default.Equals(
                            bound.Model.GetSymbolInfo(
                                candidate.Expression).Symbol,
                            parameter)))
            {
                return null;
            }

            AssignmentExpressionSyntax[] exactAssignments = assignments;

            if (assignments.Any(assignment => !IsUnconditionalExecution(
                    bound,
                    assignment,
                    bound.Syntax.SpanStart)))
            {
                ReturnStatementSyntax[] returns = bound.Syntax
                    .DescendantNodesAndSelf(node => node == bound.Syntax
                        || node is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .OfType<ReturnStatementSyntax>()
                    .Where(static returned => returned.Expression is not null)
                    .ToArray();

                AssignmentExpressionSyntax? ReachingAssignment(
                    ReturnStatementSyntax returned)
                {
                    if (returned.Parent is not BlockSyntax block)
                    {
                        return null;
                    }

                    int returnIndex = block.Statements.IndexOf(returned);

                    for (int index = returnIndex - 1; index >= 0; index--)
                    {
                        StatementSyntax statement = block.Statements[index];

                        AssignmentExpressionSyntax[] writes = statement
                            .DescendantNodesAndSelf(node =>
                                node == statement
                                || node is not AnonymousFunctionExpressionSyntax
                                    and not LocalFunctionStatementSyntax)
                            .OfType<AssignmentExpressionSyntax>()
                            .Where(candidate => candidate.IsKind(
                                    SyntaxKind.SimpleAssignmentExpression)
                                && SymbolEqualityComparer.Default.Equals(
                                    bound.Model.GetSymbolInfo(
                                        candidate.Left).Symbol,
                                    parameter))
                            .ToArray();

                        if (writes is [AssignmentExpressionSyntax exact]
                            && statement is ExpressionStatementSyntax)
                        {
                            return exact;
                        }

                        if (writes.Length != 0
                            || statement.DescendantNodesAndSelf()
                                .OfType<ArgumentSyntax>()
                                .Any(candidate => candidate.RefKindKeyword.Kind()
                                        is SyntaxKind.RefKeyword
                                            or SyntaxKind.OutKeyword
                                    && SymbolEqualityComparer.Default.Equals(
                                        bound.Model.GetSymbolInfo(
                                            candidate.Expression).Symbol,
                                        parameter)))
                        {
                            return null;
                        }
                    }

                    return null;
                }

                AssignmentExpressionSyntax?[] reaching = returns
                    .Select(ReachingAssignment)
                    .ToArray();

                if (returns.Length != 0
                    && reaching.All(static assignment => assignment is not null))
                {
                    exactAssignments = reaching
                        .OfType<AssignmentExpressionSyntax>()
                        .ToArray();
                }
                else if (TryExactSuccessfulOutReturn(
                        member,
                        bound,
                        use,
                        local,
                        call,
                        returns,
                        reaching,
                        assignments,
                        out AssignmentExpressionSyntax[] successful))
                {
                    exactAssignments = successful;
                }
                else
                {
                    return null;
                }
            }

            return (bound, exactAssignments);
        }

        private bool TryExactTailOutParameterForwarding(
            AuthoredMember member,
            IParameterSymbol parameter,
            CleanupProvenanceContext context,
            out AuthoredMember forwarded,
            out IParameterSymbol forwardedParameter)
        {
            forwarded = null!;

            forwardedParameter = null!;

            InvocationExpressionSyntax? forwardingCall = member.Syntax switch
            {
                MethodDeclarationSyntax
                {
                    ExpressionBody.Expression:
                        InvocationExpressionSyntax expressionCall,
                } => expressionCall,
                MethodDeclarationSyntax
                {
                    Body.Statements:
                    [
                        ReturnStatementSyntax
                        {
                            Expression: InvocationExpressionSyntax returnCall,
                        },
                    ],
                } => returnCall,
                LocalFunctionStatementSyntax
                {
                    ExpressionBody.Expression:
                        InvocationExpressionSyntax expressionCall,
                } => expressionCall,
                LocalFunctionStatementSyntax
                {
                    Body.Statements:
                    [
                        ReturnStatementSyntax
                        {
                            Expression: InvocationExpressionSyntax returnCall,
                        },
                    ],
                } => returnCall,
                _ => null,
            };

            if (forwardingCall is null
                || member.Model.GetOperation(forwardingCall) is not
                    IInvocationOperation operation
                || member.Model.GetSymbolInfo(forwardingCall).Symbol is not
                    IMethodSymbol method
                || ResolveAuthoredOutInvocationTarget(method, member, forwardingCall, context)
                    is not { } target
                || !SameBoundType(
                    member.Symbol.ReturnType,
                    member.Model.Compilation,
                    target.Symbol.ReturnType,
                    target.Model.Compilation)
                || operation.Arguments.Where(argument =>
                        argument.Syntax is ArgumentSyntax
                        {
                            RefKindKeyword.RawKind:
                                (int)SyntaxKind.OutKeyword,
                            Expression: { } expression,
                        }
                        && SymbolEqualityComparer.Default.Equals(
                            member.Model.GetSymbolInfo(expression).Symbol,
                            parameter))
                    .ToArray() is not
                    [IArgumentOperation { Parameter: { } targetParameter }]
                || targetParameter.Ordinal >= target.Symbol.Parameters.Length
                || target.Symbol.Parameters[targetParameter.Ordinal] is not
                    { RefKind: RefKind.Out } exactTargetParameter
                || member.Syntax.DescendantNodesAndSelf(node =>
                        node == member.Syntax
                        || node is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .OfType<ExpressionSyntax>()
                    .Count(expression =>
                        SymbolEqualityComparer.Default.Equals(
                            member.Model.GetSymbolInfo(expression).Symbol,
                            parameter)) != 1)
            {
                return false;
            }

            forwarded = BindCleanupInvocationContext(
                member,
                forwardingCall,
                target,
                context);

            forwardedParameter = exactTargetParameter;

            return true;
        }

        private static bool TryExactSuccessfulOutReturn(
            AuthoredMember caller,
            AuthoredMember target,
            ExpressionSyntax use,
            ILocalSymbol local,
            InvocationExpressionSyntax call,
            IReadOnlyList<ReturnStatementSyntax> returns,
            IReadOnlyList<AssignmentExpressionSyntax?> reaching,
            IReadOnlyList<AssignmentExpressionSyntax> assignments,
            out AssignmentExpressionSyntax[] successful)
        {
            successful = [];

            ISymbol? resultCarrier = call.Parent switch
            {
                EqualsValueClauseSyntax
                {
                    Parent: VariableDeclaratorSyntax variable,
                } => caller.Model.GetDeclaredSymbol(variable),
                AssignmentExpressionSyntax { Right: { } right } assignment
                    when right == call => caller.Model.GetSymbolInfo(
                        assignment.Left).Symbol,
                _ => null,
            };

            bool MatchesResult(ExpressionSyntax expression) =>
                expression == call
                || resultCarrier is not null
                    && SymbolEqualityComparer.Default.Equals(
                        caller.Model.GetSymbolInfo(
                            StripTransparentExpression(expression)).Symbol,
                        resultCarrier);

            static bool Terminates(StatementSyntax statement) => statement
                is ReturnStatementSyntax
                    or ThrowStatementSyntax
                    or ContinueStatementSyntax
                    or BreakStatementSyntax
                || statement is BlockSyntax { Statements.Count: > 0 } block
                    && Terminates(block.Statements[^1]);

            bool RejectsFalse(ExpressionSyntax expression)
            {
                expression = StripTransparentExpression(expression);

                return expression switch
                {
                    PrefixUnaryExpressionSyntax negation
                        when negation.IsKind(
                                SyntaxKind.LogicalNotExpression)
                            && MatchesResult(
                                StripTransparentExpression(
                                    negation.Operand)) => true,
                    BinaryExpressionSyntax disjunction
                        when disjunction.IsKind(
                            SyntaxKind.LogicalOrExpression) =>
                        RejectsFalse(disjunction.Left)
                        || RejectsFalse(disjunction.Right),
                    _ => false,
                };
            }

            bool booleanSuccessRequired =
                target.Symbol.ReturnType.SpecialType
                    == SpecialType.System_Boolean
                && caller.Syntax.DescendantNodesAndSelf(node =>
                        node == caller.Syntax
                        || node is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .OfType<IfStatementSyntax>()
                    .Any(guard => guard.Span.End < use.SpanStart
                        && Terminates(guard.Statement)
                        && guard.Parent is BlockSyntax block
                        && call.AncestorsAndSelf()
                            .OfType<StatementSyntax>()
                            .Any(statement => statement.Parent == block
                                && (statement == guard
                                    || statement.Span.End
                                        < guard.SpanStart))
                        && use.AncestorsAndSelf()
                            .OfType<StatementSyntax>()
                            .Any(statement => statement.Parent == block
                                && statement.SpanStart > guard.Span.End)
                        && RejectsFalse(guard.Condition));

            if (booleanSuccessRequired)
            {
                List<AssignmentExpressionSyntax> exactBooleanAssignments = [];

                for (int index = 0; index < returns.Count; index++)
                {
                    if (target.Model.GetConstantValue(
                            returns[index].Expression!) is not
                            {
                                HasValue: true,
                                Value: bool result,
                            })
                    {
                        return false;
                    }

                    if (!result)
                    {
                        continue;
                    }

                    if (reaching[index] is { } assignment)
                    {
                        exactBooleanAssignments.Add(assignment);

                        continue;
                    }

                    exactBooleanAssignments.AddRange(assignments.Where(
                        assignment => assignment.SpanStart
                            < returns[index].SpanStart));
                }

                successful = exactBooleanAssignments.Distinct().ToArray();

                return successful.Length != 0;
            }

            ISymbol? successSymbol = null;

            IfStatementSyntax? successGuard = null;

            foreach (IfStatementSyntax guard in caller.Syntax
                .DescendantNodesAndSelf(node => node == caller.Syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<IfStatementSyntax>()
                .Where(candidate => candidate.Span.End < use.SpanStart
                    && Terminates(candidate.Statement)
                    && candidate.Parent is BlockSyntax block
                    && call.AncestorsAndSelf()
                        .OfType<StatementSyntax>()
                        .Any(statement => statement.Parent == block
                            && (statement == candidate
                                || statement.Span.End
                                    < candidate.SpanStart))
                    && use.AncestorsAndSelf()
                        .OfType<StatementSyntax>()
                        .Any(statement => statement.Parent == block
                            && statement.SpanStart > candidate.Span.End)))
            {
                foreach (ExpressionSyntax candidate in guard.Condition
                    .DescendantNodesAndSelf()
                    .OfType<ExpressionSyntax>())
                {
                    ExpressionSyntax? success = candidate switch
                    {
                        BinaryExpressionSyntax binary
                            when binary.IsKind(
                                SyntaxKind.NotEqualsExpression)
                                && MatchesResult(binary.Left) => binary.Right,
                        BinaryExpressionSyntax binary
                            when binary.IsKind(
                                SyntaxKind.NotEqualsExpression)
                                && MatchesResult(binary.Right) => binary.Left,
                        IsPatternExpressionSyntax
                        {
                            Expression: { } tested,
                            Pattern: UnaryPatternSyntax
                            {
                                Pattern: ConstantPatternSyntax
                                {
                                    Expression: { } constant,
                                },
                            } notPattern,
                        } when notPattern.IsKind(SyntaxKind.NotPattern)
                            && MatchesResult(tested) => constant,
                        _ => null,
                    };

                    if (success is not null
                        && caller.Model.GetSymbolInfo(success).Symbol is
                            IFieldSymbol
                        {
                            ContainingType.TypeKind: TypeKind.Enum,
                        } exact)
                    {
                        successSymbol = exact;

                        successGuard = guard;

                        break;
                    }
                }

                if (successSymbol is not null)
                {
                    break;
                }
            }

            if (successSymbol is null
                || successGuard is null
                || caller.Syntax.DescendantNodesAndSelf(node =>
                        node == caller.Syntax
                        || node is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .Any(node => node.SpanStart > call.Span.End
                        && node.SpanStart < use.SpanStart
                        && (node is AssignmentExpressionSyntax assignment
                            && (SymbolEqualityComparer.Default.Equals(
                                    caller.Model.GetSymbolInfo(
                                        assignment.Left).Symbol,
                                    local)
                                || resultCarrier is not null
                                    && SymbolEqualityComparer.Default.Equals(
                                        caller.Model.GetSymbolInfo(
                                            assignment.Left).Symbol,
                                        resultCarrier))
                            || node is ArgumentSyntax argument
                                && argument.RefKindKeyword.Kind() is
                                    SyntaxKind.RefKeyword
                                        or SyntaxKind.OutKeyword
                                && (SymbolEqualityComparer.Default.Equals(
                                        caller.Model.GetSymbolInfo(
                                            argument.Expression).Symbol,
                                        local)
                                    || resultCarrier is not null
                                        && SymbolEqualityComparer.Default.Equals(
                                            caller.Model.GetSymbolInfo(
                                                argument.Expression).Symbol,
                                            resultCarrier)))))
            {
                return false;
            }

            List<AssignmentExpressionSyntax> exactAssignments = [];

            for (int index = 0; index < returns.Count; index++)
            {
                ReturnStatementSyntax returned = returns[index];

                if (target.Model.GetSymbolInfo(returned.Expression!).Symbol is
                        IFieldSymbol returnedField
                    && SymbolEqualityComparer.Default.Equals(
                        returnedField,
                        successSymbol))
                {
                    if (reaching[index] is not { } assignment)
                    {
                        return false;
                    }

                    exactAssignments.Add(assignment);

                    continue;
                }

                if (target.Model.GetSymbolInfo(returned.Expression!).Symbol is
                        IFieldSymbol otherField
                    && SymbolEqualityComparer.Default.Equals(
                        otherField.ContainingType,
                        successSymbol.ContainingType))
                {
                    continue;
                }

                bool guardedFailure = returned.Ancestors()
                    .OfType<IfStatementSyntax>()
                    .Any(guard => guard.Statement.Span.Contains(returned.Span)
                        && guard.Condition.DescendantNodesAndSelf()
                            .OfType<IsPatternExpressionSyntax>()
                            .Any(test => test.Pattern is UnaryPatternSyntax
                            {
                                Pattern: ConstantPatternSyntax
                                {
                                    Expression: { } constant,
                                },
                            } notPattern
                                && notPattern.IsKind(
                                    SyntaxKind.NotPattern)
                                && SymbolEqualityComparer.Default.Equals(
                                    target.Model.GetSymbolInfo(
                                        StripTransparentExpression(
                                            test.Expression)).Symbol,
                                    target.Model.GetSymbolInfo(
                                        StripTransparentExpression(
                                            returned.Expression!)).Symbol)
                                && SymbolEqualityComparer.Default.Equals(
                                    target.Model.GetSymbolInfo(
                                        constant).Symbol,
                                    successSymbol)));

                if (!guardedFailure)
                {
                    return false;
                }
            }

            successful = exactAssignments.ToArray();

            return successful.Length != 0;
        }

        private CleanupProvenance? ExactDirectRuntimeTypeGuardedProvenance(
            AuthoredMember member,
            ExpressionSyntax use,
            ISymbol symbol)
        {
            if (symbol is not ILocalSymbol and not IParameterSymbol
                || symbol switch
                {
                    ILocalSymbol local => local.Type,
                    IParameterSymbol parameter => parameter.Type,
                    _ => null,
                } is not INamedTypeSymbol
                {
                    IsAbstract: false,
                } exactType
                || TypeKey(exactType)
                    != "Microsoft.Data.Sqlite.SqliteConnection")
            {
                return null;
            }

            IfStatementSyntax[] guards = member.Syntax
                .DescendantNodesAndSelf(node => node == member.Syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .OfType<IfStatementSyntax>()
                .Where(guard => guard.Span.End < use.SpanStart
                    && guard.Statement is ThrowStatementSyntax
                        or BlockSyntax
                    {
                        Statements: [ThrowStatementSyntax],
                    }
                    && StripTransparentExpression(guard.Condition) is
                        BinaryExpressionSyntax
                    {
                        RawKind: (int)SyntaxKind.NotEqualsExpression,
                        Left: InvocationExpressionSyntax
                        {
                            Expression: MemberAccessExpressionSyntax
                            {
                                Expression: { } receiver,
                            },
                            ArgumentList.Arguments.Count: 0,
                        } getType,
                        Right: TypeOfExpressionSyntax typeOf,
                    }
                    && member.Model.GetSymbolInfo(getType).Symbol is
                        IMethodSymbol getTypeMethod
                    && IsExactFrameworkMethod(
                        getTypeMethod,
                        "System.Object",
                        "GetType",
                        "System.Private.CoreLib")
                    && SymbolEqualityComparer.Default.Equals(
                        member.Model.GetSymbolInfo(receiver).Symbol,
                        symbol)
                    && member.Model.GetTypeInfo(typeOf.Type).Type is
                    { } comparedType
                    && SameBoundType(
                        exactType,
                        member.Model.Compilation,
                        comparedType,
                        member.Model.Compilation)
                    && SymbolIsStableBetween(
                        member,
                        symbol,
                        guard.Span.End,
                        use))
                .ToArray();

            return guards.Length == 1
                ? ExactCleanupProvenance(member, exactType)
                : null;
        }

        private CleanupProvenance? ExactRuntimeTypeGuardedLocalProvenance(
            AuthoredMember member,
            ExpressionSyntax use,
            ILocalSymbol local,
            SingleVariableDesignationSyntax designation)
        {
            IfStatementSyntax[] matchingGuards = designation.Ancestors()
                .OfType<IfStatementSyntax>()
                .Where(candidate => candidate.Condition.Span.Contains(
                    designation.Span))
                .Take(2)
                .ToArray();

            if (matchingGuards is not [IfStatementSyntax guard]
                || guard.Span.End >= use.SpanStart
                || StripTransparentExpression(guard.Condition)
                    is not BinaryExpressionSyntax condition
                || !condition.IsKind(
                    SyntaxKind.LogicalOrExpression)
                || StripTransparentExpression(condition.Left)
                    is not IsPatternExpressionSyntax
                    {
                        Expression: { } tested,
                        Pattern: UnaryPatternSyntax
                        {
                            Pattern: DeclarationPatternSyntax
                            {
                                Type: { } declaredType,
                                Designation: SingleVariableDesignationSyntax
                                    declared,
                            },
                        } notPattern,
                    }
                || !notPattern.IsKind(SyntaxKind.NotPattern)
                || declared.SyntaxTree != designation.SyntaxTree
                || declared.Span != designation.Span
                || StripTransparentExpression(condition.Right)
                    is not BinaryExpressionSyntax mismatch
                || !mismatch.IsKind(
                    SyntaxKind.NotEqualsExpression)
                || StripTransparentExpression(mismatch.Left)
                    is not InvocationExpressionSyntax
                    {
                        Expression: MemberAccessExpressionSyntax
                        {
                            Expression: { } typeReceiver,
                        },
                        ArgumentList.Arguments.Count: 0,
                    } getType
                || member.Model.GetSymbolInfo(getType).Symbol
                    is not IMethodSymbol getTypeMethod
                || !IsExactFrameworkMethod(
                    getTypeMethod,
                    "System.Object",
                    "GetType",
                    "System.Private.CoreLib")
                || StripTransparentExpression(mismatch.Right)
                    is not TypeOfExpressionSyntax typeOf
                || member.Model.GetTypeInfo(declaredType).Type
                    is not { } patternType
                || member.Model.GetTypeInfo(typeOf.Type).Type
                    is not { } comparedType
                || !SameBoundType(
                    patternType,
                    member.Model.Compilation,
                    comparedType,
                    member.Model.Compilation)
                || !SameBoundType(
                    patternType,
                    member.Model.Compilation,
                    local.Type,
                    member.Model.Compilation)
                || !SymbolEqualityComparer.Default.Equals(
                    member.Model.GetSymbolInfo(typeReceiver).Symbol,
                    local)
                || guard.Statement is not ThrowStatementSyntax
                    and not BlockSyntax
                    {
                        Statements: [ThrowStatementSyntax],
                    })
            {
                return null;
            }

            bool mutated = member.Syntax.DescendantNodesAndSelf(node =>
                    node == member.Syntax
                    || node is not AnonymousFunctionExpressionSyntax
                        and not LocalFunctionStatementSyntax)
                .Where(node => node.SpanStart > guard.Span.End
                    && node.SpanStart < use.SpanStart)
                .Any(node => node switch
                {
                    AssignmentExpressionSyntax assignment =>
                        SymbolEqualityComparer.Default.Equals(
                            member.Model.GetSymbolInfo(
                                assignment.Left).Symbol,
                            local),
                    ArgumentSyntax argument
                        when argument.RefKindKeyword.Kind() is
                            SyntaxKind.RefKeyword or SyntaxKind.OutKeyword =>
                        SymbolEqualityComparer.Default.Equals(
                            member.Model.GetSymbolInfo(
                                argument.Expression).Symbol,
                            local),
                    _ => false,
                });

            return mutated
                    || InvokedCallableMayMutateSymbol(
                        member,
                        local,
                        use.SpanStart,
                        guard.Span.End)
                ? null
                : ExactCleanupProvenance(member, patternType);
        }

        private CleanupProvenance ExactCleanupProvenance(
            AuthoredMember member,
            ITypeSymbol type)
        {
            if (type is not INamedTypeSymbol
                {
                    IsAbstract: false,
                    TypeKind: not TypeKind.Interface,
                })
            {
                return new(
                    [],
                    false,
                    IsAuthoredCleanupSymbol(
                        type,
                        member.Model.Compilation));
            }

            BoundTypeIdentity identity = TypeIdentity(
                type,
                member.Model.Compilation);

            bool unmappedAuthoredIdentity = identity.Compilation is null
                && compilationIdentities.Keys
                    .OfType<CSharpCompilation>()
                    .Any(compilation => compilation.Assembly.Identity.Equals(
                        type.ContainingAssembly.Identity));

            return new(
                [new(type, identity)],
                !unmappedAuthoredIdentity,
                identity.Compilation is not null
                    || type.Locations.Any(static location => location.IsInSource)
                    || unmappedAuthoredIdentity);
        }

        private bool IsAuthoredCleanupSymbol(
            ISymbol symbol,
            Compilation consumingCompilation) =>
            symbol.Locations.Any(static location => location.IsInSource)
            || AuthoredCompilationIdentity(
                symbol,
                consumingCompilation) is not null;

        private static CleanupProvenance MergeCleanupProvenance(
            IEnumerable<CleanupProvenance> values)
        {
            CleanupProvenance[] provenance = values.ToArray();

            return new(
                provenance.SelectMany(static value => value.Candidates)
                    .DistinctBy(static candidate => candidate.Identity)
                    .ToArray(),
                provenance.Length != 0
                    && provenance.All(static value => value.Complete),
                provenance.Any(static value => value.HasAuthoredSource));
        }

        private static ExpressionStatementSyntax? ExactTerminalStatement(AuthoredMember member, InvocationExpressionSyntax call)
        {
            SyntaxNode expression = CompletionPreservingExpression(call, member.Model);

            if (expression.Parent is AwaitExpressionSyntax awaited)
            {
                expression = awaited;
            }

            return expression.Parent is ExpressionStatementSyntax statement && statement.Expression == expression ? statement : null;
        }

        private bool HasExactTerminalJoin(AuthoredMember member, InvocationExpressionSyntax call, IMethodSymbol method, bool inheritedCompletion)
        {
            if (TypeKey(method.ReturnType) == "System.Void")
            {
                return true;
            }

            return IsAwaitable(method.ReturnType) && CompletionPoint(member, call, inheritedCompletion) is not null;
        }

        private bool HasExactCompletionJoin(AuthoredMember member, InvocationExpressionSyntax call, IMethodSymbol method) => IsAwaitable(method.ReturnType) && CompletionPoint(member, call, false) is AwaitExpressionSyntax awaited && awaited.Parent is ExpressionStatementSyntax;

        private IReadOnlySet<int> VerifyFieldPublication(AuthoredMember caller, InvocationExpressionSyntax factoryCall, AuthoredMember factory, string operationId, string? inherited)
        {
            ITypeSymbol result = factory.Symbol.ReturnType;

            if (result is INamedTypeSymbol named && named.OriginalDefinition.ToDisplayString() is "System.Threading.Tasks.Task<TResult>" or "System.Threading.Tasks.ValueTask<TResult>")
            {
                result = named.TypeArguments[0];
            }

            IFieldSymbol[] fields = result.GetMembers().OfType<IFieldSymbol>().Where(static field => field.Type.ToDisplayString() == "RetroDownfall.Arcanum.Core.Storage.EncryptedBlobWriter").ToArray();

            if (fields.Length == 0 || factoryCall.Ancestors().OfType<VariableDeclaratorSyntax>().FirstOrDefault() is not { } variable || caller.Model.GetDeclaredSymbol(variable) is not { } owner)
            {
                return new HashSet<int>();
            }

            string? group = EffectAt(caller, factoryCall, operationId, inherited);

            bool IsSuccessfulPathOwnerCall(InvocationExpressionSyntax call)
            {
                if (variable.Parent?.Parent is not LocalDeclarationStatementSyntax
                    {
                        Parent: BlockSyntax block,
                    } declaration
                    || call.Ancestors().OfType<StatementSyntax>().FirstOrDefault(statement =>
                        statement.Parent == block) is not { } statement
                    || statement is not ExpressionStatementSyntax
                        and not LocalDeclarationStatementSyntax
                    || statement.SpanStart <= declaration.Span.End
                    || call.Ancestors().TakeWhile(ancestor => ancestor != statement).Any(
                        static ancestor => ancestor is ConditionalExpressionSyntax
                            or SwitchExpressionSyntax
                            or AnonymousFunctionExpressionSyntax
                            or LocalFunctionStatementSyntax))
                {
                    return false;
                }

                int declarationIndex = block.Statements.IndexOf(declaration);

                int statementIndex = block.Statements.IndexOf(statement);

                return declarationIndex >= 0
                    && statementIndex > declarationIndex
                    && !block.Statements.Skip(declarationIndex + 1)
                        .Take(statementIndex - declarationIndex - 1)
                        .Any(static between => between is ReturnStatementSyntax
                            or ThrowStatementSyntax
                            or GotoStatementSyntax);
            }

            InvocationExpressionSyntax[] ownerCalls = caller.Syntax.DescendantNodes()
                .OfType<InvocationExpressionSyntax>()
                .Where(call => call.Expression is MemberAccessExpressionSyntax access
                    && SymbolEqualityComparer.Default.Equals(
                        caller.Model.GetSymbolInfo(access.Expression).Symbol,
                        owner)
                    && IsSuccessfulPathOwnerCall(call))
                .ToArray();

            bool IsNonCancelableCompletionArgument(ArgumentSyntax argument) =>
                caller.Model.GetSymbolInfo(argument.Expression).Symbol is IPropertySymbol
                {
                    Name: "None",
                    ContainingType: { } containingType,
                }
                && TypeKey(containingType) == "System.Threading.CancellationToken";

            bool JoinedCarrierCompletion(InvocationExpressionSyntax call)
            {
                if (caller.Model.GetSymbolInfo(call).Symbol is not IMethodSymbol
                    {
                        Name: "CompleteAsync",
                    } method
                    || !IsAwaitable(method.ReturnType)
                    || CompletionPoint(caller, call, false) is null)
                {
                    return false;
                }

                return method.Parameters.Length == 0
                        && call.ArgumentList.Arguments.Count == 0
                    || method.Parameters is [IParameterSymbol { Type: { } tokenType }]
                        && TypeKey(tokenType) == "System.Threading.CancellationToken"
                        && call.ArgumentList.Arguments is [ArgumentSyntax argument]
                        && IsNonCancelableCompletionArgument(argument);
            }

            AuthoredMember[] completionTargets = ownerCalls.Where(JoinedCarrierCompletion).Select(call => Resolve((IMethodSymbol)caller.Model.GetSymbolInfo(call).Symbol!, caller.Model.Compilation)).OfType<AuthoredMember>().ToArray();

            List<AuthoredMember> disposalTargets = ownerCalls.Where(call => caller.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method && IsExactCleanupContract(method, result) && HasExactTerminalJoin(caller, call, method, false)).Select(call => Resolve((IMethodSymbol)caller.Model.GetSymbolInfo(call).Symbol!, caller.Model.Compilation)).OfType<AuthoredMember>().ToList();

            List<string?> disposalGroups = ownerCalls.Where(call => caller.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method && IsExactCleanupContract(method, result)).Select(call => EffectAt(caller, call, operationId, inherited)).ToList();

            if (variable.Parent is VariableDeclarationSyntax declaration && (declaration.Parent is LocalDeclarationStatementSyntax { UsingKeyword.RawKind: not 0 } || declaration.Parent is UsingStatementSyntax))
            {
                disposalGroups.Add(EffectAt(caller, declaration, operationId, inherited, DisposalPosition(declaration), declaration));

                bool asynchronous = declaration.Parent is LocalDeclarationStatementSyntax { AwaitKeyword.RawKind: not 0 } or UsingStatementSyntax { AwaitKeyword.RawKind: not 0 };

                string methodName = asynchronous ? "DisposeAsync" : "Dispose";

                if (result is INamedTypeSymbol disposable && disposable.AllInterfaces.SingleOrDefault(type => TypeKey(type) == (asynchronous ? "System.IAsyncDisposable" : "System.IDisposable"))?.GetMembers(methodName).OfType<IMethodSymbol>().SingleOrDefault(static method => method.Parameters.Length == 0) is { } slot && disposable.FindImplementationForInterfaceMember(slot) is IMethodSymbol implementation && IsExactCleanupContract(implementation, result) && Resolve(implementation, caller.Model.Compilation) is { } cleanup)
                {
                    disposalTargets.Add(cleanup);
                }
            }

            ObjectCreationExpressionSyntax[] returns = factory.Syntax.DescendantNodes().OfType<ReturnStatementSyntax>().Select(static statement => statement.Expression).OfType<ObjectCreationExpressionSyntax>().ToArray();

            HashSet<int> mappedCreations = [];

            List<(IFieldSymbol Field, AssignmentExpressionSyntax Assignment)> mappedFields = [];

            List<(ILocalSymbol Local, InvocationExpressionSyntax Creation, ExpressionSyntax Assignment)> mappedLocals = [];

            List<string> mappingFailures = [];

            AuthoredMember? mappedConstructor = null;

            bool References(AuthoredMember member, SyntaxNode node, ISymbol symbol) => node.DescendantNodesAndSelf().OfType<ExpressionSyntax>().Any(expression => SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(expression).Symbol, symbol));

            bool Written(AuthoredMember member, ISymbol symbol) => member.Syntax.DescendantNodes().OfType<AssignmentExpressionSyntax>().Any(assignment => References(member, assignment.Left, symbol));

            bool TryMapWriterCreation(
                ILocalSymbol local,
                out InvocationExpressionSyntax creation,
                out ExpressionSyntax assignment)
            {
                creation = null!;

                assignment = null!;

                if (local.DeclaringSyntaxReferences.SingleOrDefault()?.GetSyntax() is not VariableDeclaratorSyntax variable)
                {
                    return false;
                }

                List<(ExpressionSyntax Value, ExpressionSyntax Assignment)> values = [];

                bool nullInitializer = variable.Initializer is not null
                    && (variable.Initializer.Value is DefaultExpressionSyntax
                        || variable.Initializer.Value is LiteralExpressionSyntax literal
                            && literal.IsKind(SyntaxKind.DefaultLiteralExpression)
                        || factory.Model.GetConstantValue(variable.Initializer.Value) is
                        {
                            HasValue: true,
                            Value: null,
                        });

                if (variable.Initializer is not null && !nullInitializer)
                {
                    values.Add((variable.Initializer.Value, variable.Initializer.Value));
                }

                AssignmentExpressionSyntax[] writes = factory.Syntax.DescendantNodes()
                    .OfType<AssignmentExpressionSyntax>()
                    .Where(write => SymbolEqualityComparer.Default.Equals(
                        factory.Model.GetSymbolInfo(write.Left).Symbol,
                        local))
                    .ToArray();

                foreach (AssignmentExpressionSyntax write in writes)
                {
                    if (!write.IsKind(SyntaxKind.SimpleAssignmentExpression)
                        || write.Parent is not ExpressionStatementSyntax)
                    {
                        return false;
                    }

                    values.Add((write.Right, write.Left));
                }

                if (values is not [(ExpressionSyntax value, ExpressionSyntax assigned)])
                {
                    return false;
                }

                InvocationExpressionSyntax[] creations = value.DescendantNodesAndSelf()
                    .OfType<InvocationExpressionSyntax>()
                    .Where(call => factory.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method
                        && Normalize(method) == "RetroDownfall.Arcanum.Core.Storage.IEncryptedBlobStore.CreateWriterAsync")
                    .ToArray();

                if (creations is not [InvocationExpressionSyntax exact]
                    || factory.Model.GetSymbolInfo(exact).Symbol is not IMethodSymbol createMethod
                    || IsAwaitable(createMethod.ReturnType)
                        && CompletionPoint(factory, exact, false) is null)
                {
                    return false;
                }

                creation = exact;

                assignment = assigned;

                return true;
            }

            bool IsNonOwningTextAdapterReference(ILocalSymbol local, ExpressionSyntax reference)
            {
                if (reference.Parent is not ArgumentSyntax argument
                    || argument.Parent?.Parent is not InvocationExpressionSyntax call
                    || factory.Model.GetOperation(argument) is not IArgumentOperation { Parameter: { } parameter }
                    || factory.Model.GetSymbolInfo(call).Symbol is not IMethodSymbol method
                    || TypeKey(method.ReturnType) != "System.IO.StreamWriter"
                    || Resolve(method, factory.Model.Compilation) is not { } adapter)
                {
                    return false;
                }

                BaseObjectCreationExpressionSyntax[] writers = adapter.Syntax.DescendantNodesAndSelf()
                    .OfType<BaseObjectCreationExpressionSyntax>()
                    .Where(created => adapter.Model.GetTypeInfo(created).Type is { } createdType
                        && TypeKey(createdType) == "System.IO.StreamWriter")
                    .ToArray();

                if (writers is not [BaseObjectCreationExpressionSyntax writer]
                    || adapter.Model.GetOperation(writer) is not IObjectCreationOperation operation
                    || operation.Arguments.SingleOrDefault(static candidate => candidate.Parameter?.Name == "leaveOpen") is not { Value.ConstantValue: { HasValue: true, Value: true } }
                    || operation.Arguments.SingleOrDefault(candidate => candidate.Parameter?.Ordinal == 0)?.Value.Syntax is not ExpressionSyntax stream
                    || !SymbolEqualityComparer.Default.Equals(adapter.Model.GetSymbolInfo(stream).Symbol, parameter))
                {
                    return false;
                }

                return HasOnlyReferences(adapter, parameter, stream)
                    && SymbolEqualityComparer.Default.Equals(factory.Model.GetSymbolInfo(reference).Symbol, local);
            }

            bool IsNullGuardReference(ILocalSymbol local, ExpressionSyntax reference) =>
                reference.AncestorsAndSelf().OfType<IsPatternExpressionSyntax>().Any(test =>
                    test.Expression.Span.Contains(reference.Span)
                    && test.Pattern is UnaryPatternSyntax
                    {
                        Pattern: ConstantPatternSyntax
                        {
                            Expression.RawKind: (int)SyntaxKind.NullLiteralExpression,
                        },
                    }
                    && SymbolEqualityComparer.Default.Equals(
                        factory.Model.GetSymbolInfo(test.Expression).Symbol,
                        local));

            bool IsExceptionalCleanupReference(ILocalSymbol local, ExpressionSyntax reference)
            {
                if (reference.Parent is not MemberAccessExpressionSyntax access
                    || access.Expression != reference
                    || access.Parent is not InvocationExpressionSyntax cleanup
                    || factory.Model.GetSymbolInfo(cleanup).Symbol is not IMethodSymbol method
                    || !IsExactWriterCleanup(method, local.Type)
                    || !HasExactTerminalJoin(factory, cleanup, method, false)
                    || cleanup.Ancestors().OfType<CatchClauseSyntax>().FirstOrDefault() is not { } ownerCatch
                    || cleanup.Ancestors().OfType<TryStatementSyntax>().FirstOrDefault() is not { } isolated
                    || isolated.Block.Span.Contains(cleanup.Span) == false
                    || isolated.Catches.Count == 0
                    || isolated.Catches.Any(static caught => caught.Filter is not null
                        || caught.Block.DescendantNodesAndSelf().Any(node => node is ReturnStatementSyntax or ThrowStatementSyntax or GotoStatementSyntax)))
                {
                    return false;
                }

                IfStatementSyntax? guard = cleanup.Ancestors()
                    .OfType<IfStatementSyntax>()
                    .FirstOrDefault(candidate => candidate.Statement.Span.Contains(cleanup.Span));

                return guard is not null
                    && guard.Condition.DescendantNodesAndSelf().OfType<ExpressionSyntax>().Any(expression =>
                        IsNullGuardReference(local, expression))
                    && ownerCatch.Block.Span.Contains(isolated.Span);
            }

            bool HasOnlySupportedFactoryReferences(
                ILocalSymbol local,
                ExpressionSyntax transfer,
                ExpressionSyntax assignment)
            {
                foreach (ExpressionSyntax reference in SymbolReferences(factory, local))
                {
                    if (reference == transfer
                        || reference == assignment
                        || IsNullGuardReference(local, reference)
                        || IsExceptionalCleanupReference(local, reference)
                        || IsNonOwningTextAdapterReference(local, reference))
                    {
                        continue;
                    }

                    mappingFailures.Add(
                        local.Name
                        + ":unsupported@"
                        + reference.SpanStart
                        + ":"
                        + reference.Parent?.Kind()
                        + ":"
                        + reference.Parent?.Parent);

                    return false;
                }

                return true;
            }

            bool HasExceptionalConstructionCleanup()
            {
                if (mappedLocals.Count < 2)
                {
                    return true;
                }

                CatchClauseSyntax[] catches = factory.Syntax.DescendantNodes()
                    .OfType<CatchClauseSyntax>()
                    .Where(caught => caught.Parent is TryStatementSyntax guarded
                        && mappedLocals.All(mapped => guarded.Block.Span.Contains(mapped.Creation.Span))
                        && returns.All(returned => guarded.Block.Span.Contains(returned.Span)))
                    .ToArray();

                if (catches is not [CatchClauseSyntax cleanupCatch]
                    || cleanupCatch.Filter is not null
                    || cleanupCatch.Block.DescendantNodes().OfType<ReturnStatementSyntax>().Any()
                    || !cleanupCatch.Block.DescendantNodes().OfType<ThrowStatementSyntax>().Any())
                {
                    return false;
                }

                return mappedLocals.All(mapped => cleanupCatch.Block.DescendantNodes()
                    .OfType<InvocationExpressionSyntax>()
                    .Count(call => call.Expression is MemberAccessExpressionSyntax access
                        && SymbolEqualityComparer.Default.Equals(
                            factory.Model.GetSymbolInfo(access.Expression).Symbol,
                            mapped.Local)
                        && factory.Model.GetSymbolInfo(call).Symbol is IMethodSymbol cleanup
                        && IsExactWriterCleanup(cleanup, mapped.Local.Type)
                        && IsExceptionalCleanupReference(mapped.Local, access.Expression)) == 1);
            }

            bool mapped = returns.Length == 1 && factory.Model.GetOperation(returns[0]) is IObjectCreationOperation { Constructor: { } constructor } creation && Resolve(constructor, factory.Model.Compilation) is { } constructorBody && SetMappedConstructor(constructorBody) && fields.All(field =>
            {
                AssignmentExpressionSyntax[] writes = constructorBody.Syntax.DescendantNodes().OfType<AssignmentExpressionSyntax>().Where(assignment => References(constructorBody, assignment.Left, field)).ToArray();

                if (!field.IsReadOnly || field.IsStatic || field.DeclaringSyntaxReferences.Any(reference => reference.GetSyntax() is VariableDeclaratorSyntax { Initializer: not null }) || writes.Length != 1 || !writes[0].IsKind(SyntaxKind.SimpleAssignmentExpression) || !IsUnconditionalExecution(constructorBody, writes[0], constructorBody.Syntax.SpanStart) || !SymbolEqualityComparer.Default.Equals(constructorBody.Model.GetSymbolInfo(writes[0].Left).Symbol, field))
                {
                    return false;
                }

                if (constructorBody.Model.GetSymbolInfo(writes[0].Right).Symbol is not IParameterSymbol parameter
                    || Written(constructorBody, parameter)
                    || !HasOnlyReferences(constructorBody, parameter, writes[0].Right)
                    || creation.Arguments.SingleOrDefault(argument => argument.Parameter?.Ordinal == parameter.Ordinal)?.Value.Syntax is not ExpressionSyntax argument
                    || factory.Model.GetSymbolInfo(argument).Symbol is not ILocalSymbol local)
                {
                    mappingFailures.Add(field.Name + ":constructor-transfer");

                    return false;
                }

                if (!TryMapWriterCreation(
                        local,
                        out InvocationExpressionSyntax writerCreation,
                        out ExpressionSyntax assignment))
                {
                    mappingFailures.Add(field.Name + ":writer-creation");

                    return false;
                }

                if (!HasOnlySupportedFactoryReferences(local, argument, assignment))
                {
                    mappingFailures.Add(field.Name + ":writer-reference");

                    return false;
                }

                mappedLocals.Add((local, writerCreation, assignment));

                return mappedCreations.Add(writerCreation.SpanStart)
                    && AddMappedField(field, writes[0]);
            });

            bool exceptionalConstructionCleanup = HasExceptionalConstructionCleanup();

            if (!exceptionalConstructionCleanup)
            {
                mappingFailures.Add("factory:exceptional-cleanup");
            }

            mapped &= exceptionalConstructionCleanup;

            bool SetMappedConstructor(AuthoredMember constructor)
            {
                mappedConstructor = constructor;

                return true;
            }

            bool AddMappedField(IFieldSymbol field, AssignmentExpressionSyntax assignment)
            {
                mappedFields.Add((field, assignment));

                return true;
            }

            bool IsFailureIsolatedCleanup(AuthoredMember member, InvocationExpressionSyntax cleanup)
            {
                if (cleanup.Ancestors().OfType<TryStatementSyntax>().FirstOrDefault() is not { } isolated
                    || !isolated.Block.Span.Contains(cleanup.Span)
                    || isolated.Catches.Count == 0
                    || isolated.Catches.Any(static caught => caught.Filter is not null
                        || caught.Block.DescendantNodesAndSelf().Any(node => node is ReturnStatementSyntax or ThrowStatementSyntax or GotoStatementSyntax)))
                {
                    return false;
                }

                BlockSyntax? body = member.Syntax switch
                {
                    MethodDeclarationSyntax { Body: { } methodBody } => methodBody,
                    LocalFunctionStatementSyntax { Body: { } localBody } => localBody,
                    _ => null,
                };

                return body is not null
                    && isolated.Parent == body
                    && body.Statements.TakeWhile(statement => statement.SpanStart < isolated.SpanStart)
                        .All(statement => statement is LocalDeclarationStatementSyntax
                            or TryStatementSyntax
                            || IsExactIdempotentDisposalGuard(member, statement));
            }

            bool IsExactIdempotentDisposalGuard(AuthoredMember member, StatementSyntax statement)
            {
                if (statement is not IfStatementSyntax
                    {
                        Else: null,
                        Statement: BlockSyntax
                        {
                            Statements: [ReturnStatementSyntax { Expression: null }],
                        },
                    } guard
                    || guard.Condition.DescendantNodesAndSelf().OfType<InvocationExpressionSyntax>().SingleOrDefault() is not { } exchange
                    || member.Model.GetSymbolInfo(exchange).Symbol is not IMethodSymbol method
                    || Normalize(method) != "System.Threading.Interlocked.Exchange"
                    || exchange.ArgumentList.Arguments.Count != 2
                    || member.Model.GetConstantValue(exchange.ArgumentList.Arguments[1].Expression) is not { HasValue: true, Value: 1 })
                {
                    return false;
                }

                return exchange.ArgumentList.Arguments[0].RefKindKeyword.IsKind(SyntaxKind.RefKeyword)
                    && member.Model.GetSymbolInfo(exchange.ArgumentList.Arguments[0].Expression).Symbol is IFieldSymbol
                    {
                        Type.SpecialType: SpecialType.System_Int32,
                    };
            }

            bool IsConditionalCompletion(AuthoredMember member, InvocationExpressionSyntax call)
            {
                SyntaxNode expression = CompletionPreservingExpression(call, member.Model);

                if (expression.Parent is AwaitExpressionSyntax awaited)
                {
                    expression = awaited;
                }

                return expression.Parent is ConditionalExpressionSyntax;
            }

            IEnumerable<(AuthoredMember Member, ExpressionSyntax Receiver)> FieldTerminals(
                IFieldSymbol field,
                bool cleanup,
                IEnumerable<AuthoredMember> targets) => targets.SelectMany(member => member.Syntax.DescendantNodes()
                    .OfType<InvocationExpressionSyntax>()
                    .Where(call => call.Expression is MemberAccessExpressionSyntax access
                        && SymbolEqualityComparer.Default.Equals(
                            member.Model.GetSymbolInfo(access.Expression).Symbol,
                            field)
                        && member.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method
                        && HasExactTerminalJoin(member, call, method, true)
                        && (cleanup
                            ? IsExactWriterCleanup(method, field.Type)
                                && (IsUnconditionalExecution(member, call, member.Syntax.SpanStart)
                                    || IsFailureIsolatedCleanup(member, call))
                            : IsExactWriterCompletion(method)
                                && (IsUnconditionalExecution(member, call, member.Syntax.SpanStart)
                                    || IsConditionalCompletion(member, call))))
                    .Select(call => (member, ((MemberAccessExpressionSyntax)call.Expression).Expression)));

            bool FieldHasTerminal(IFieldSymbol field, bool cleanup, IEnumerable<AuthoredMember> targets) => FieldTerminals(field, cleanup, targets).Any();

            bool AllFieldsTerminate(bool cleanup, IEnumerable<AuthoredMember> targets) =>
                targets.Any(target => fields.All(field => FieldHasTerminal(field, cleanup, [target])));

            bool FieldsHaveOnlyMappedTerminals() => mappedFields.All(mapping => AuthoredMembers.Where(member => SymbolEqualityComparer.Default.Equals(member.Symbol.ContainingType, mapping.Field.ContainingType)).All(member =>
            {
                List<ExpressionSyntax> allowed = [];

                if (mappedConstructor is not null && SymbolEqualityComparer.Default.Equals(member.Symbol, mappedConstructor.Symbol))
                {
                    allowed.Add(mapping.Assignment.Left);
                }

                allowed.AddRange(FieldTerminals(mapping.Field, false, [member]).Select(static terminal => terminal.Receiver));

                allowed.AddRange(FieldTerminals(mapping.Field, true, [member]).Select(static terminal => terminal.Receiver));

                return HasOnlyReferences(member, mapping.Field, [.. allowed]);
            }));

            bool sameDisposalGroup = group is not null
                && disposalGroups.Count > 0
                && disposalGroups.All(disposal => disposal == group);

            bool sameOwnerCallGroup = group is not null
                && ownerCalls.All(call => EffectAt(caller, call, operationId, inherited) == group);

            bool completesFields = AllFieldsTerminate(false, completionTargets);

            bool disposesFields = AllFieldsTerminate(true, disposalTargets);

            bool exclusiveFields = FieldsHaveOnlyMappedTerminals();

            bool valid = mapped
                && sameDisposalGroup
                && sameOwnerCallGroup
                && completesFields
                && disposesFields
                && exclusiveFields;

            if (!valid)
            {
                diagnostics.Add(new(
                    "HOSTED_SITE_PUBLICATION_REGION_INCOMPLETE",
                    operationId + "/site@" + Location(factoryCall),
                    "Field-backed publication requires exact constructor ownership and completion/disposal under its caller's one retained group. "
                    + $"mapping={mapped}({string.Join(",", mappingFailures)}); disposalGroup={sameDisposalGroup}; ownerGroup={sameOwnerCallGroup}; completion={completesFields}; disposal={disposesFields}; exclusive={exclusiveFields}."));
            }

            return valid ? mappedCreations : new HashSet<int>();
        }

        private static bool IsUnconditionalExecution(AuthoredMember member, SyntaxNode node, int after)
        {
            if (node.Ancestors().TakeWhile(ancestor => ancestor != member.Syntax).Any(static ancestor => ancestor is StatementSyntax and not (BlockSyntax or ExpressionStatementSyntax or ReturnStatementSyntax or LocalDeclarationStatementSyntax) || ancestor is ConditionalExpressionSyntax or SwitchExpressionSyntax or AnonymousFunctionExpressionSyntax))
            {
                return false;
            }

            return !member.Syntax.DescendantNodes(candidate => candidate == member.Syntax || candidate is not AnonymousFunctionExpressionSyntax and not LocalFunctionStatementSyntax).Any(candidate => candidate.SpanStart >= after && candidate.Span.End < node.SpanStart && candidate is ReturnStatementSyntax or ThrowStatementSyntax or GotoStatementSyntax);
        }

        private static bool IsAssignedOnEverySuccessfulConstruction(
            AuthoredMember constructor,
            AssignmentExpressionSyntax assignment)
        {
            if (assignment.Ancestors()
                .TakeWhile(ancestor => ancestor != constructor.Syntax)
                .Any(static ancestor => ancestor is StatementSyntax and not (BlockSyntax or ExpressionStatementSyntax or LocalDeclarationStatementSyntax) || ancestor is ConditionalExpressionSyntax or SwitchExpressionSyntax or AnonymousFunctionExpressionSyntax))
            {
                return false;
            }

            return !constructor.Syntax.DescendantNodes(candidate => candidate == constructor.Syntax || candidate is not AnonymousFunctionExpressionSyntax and not LocalFunctionStatementSyntax)
                .Any(candidate => candidate.Span.End < assignment.SpanStart && candidate is ReturnStatementSyntax or GotoStatementSyntax);
        }

        private string? EffectAt(AuthoredMember member, SyntaxNode site, string operationId, string? inherited, int? position = null, SyntaxNode? disposing = null)
        {
            RetainedAdmissionAnalysisCounter analysis =
                RetainedAdmissionCounter(member);

            analysis.AuthorityQueries++;

            if (!MayContainAdmissionOrigin(member))
            {
                analysis.OriginFreeFastPathReturns++;

                return inherited;
            }

            string? local = FindRetainedAdmission(member, site, "TryBeginExternalEffectGroup", null, position, disposing);

            return local is null ? LiveInheritedAdmission(member, site, inherited, position) : RootOperation(operationId) + "@effect:" + local;
        }

        private string? WorkAt(AuthoredMember member, SyntaxNode site, string operationId, GrimoireWorkKind? kind, string? inherited, int? position = null, SyntaxNode? disposing = null)
        {
            RetainedAdmissionAnalysisCounter analysis =
                RetainedAdmissionCounter(member);

            analysis.AuthorityQueries++;

            if (member.ReadinessSource?.OwnedAdmission is not null)
            {
                string? independent = ReadinessWorkAt(member, site, operationId, position);

                if (independent is not null || member.ReadinessSource.AdmissionActive) return independent;
            }

            if (!MayContainAdmissionOrigin(member))
            {
                analysis.OriginFreeFastPathReturns++;

                return inherited;
            }

            string? local = kind is null ? null : FindRetainedAdmission(member, site, "TryAcquireWorkLease", kind, position, disposing);

            return local is null ? LiveInheritedAdmission(member, site, inherited, position) : RootOperation(operationId) + "@work:" + local;
        }

        private string? LiveInheritedAdmission(AuthoredMember member, SyntaxNode site, string? inherited, int? atPosition)
        {
            if (inherited is null)
            {
                return null;
            }

            string origin = inherited[(inherited.LastIndexOf("@", StringComparison.Ordinal) + 1)..];

            origin = origin[(origin.IndexOf(':') + 1)..];

            return AdmissionEndedBefore(member, origin, atPosition ?? site.SpanStart, []) ? null : inherited;
        }

        private bool AdmissionEndedBefore(AuthoredMember member, string origin, int position, HashSet<GraphMemberIdentity> path, CleanupProvenanceContext? readinessProof = null)
        {
            if (member.ScopedLeaseInstance is { } instance)
            {
                if (origin != instance.Origin) return true;

                return ScopedLeaseInstanceEndsBefore(member, position, readinessProof ?? new CleanupProvenanceContext());
            }

            GraphMemberIdentity identity = MemberIdentity(member);

            if (!path.Add(identity))
            {
                return true;
            }

            if (member.ReadinessSource is { OwnedAdmission: not null } || member.OrdinaryScopedHolder is not null)
                readinessProof ??= new();

            if (readinessProof is not null && ReadinessHasUnsupportedHolderAccess(member, origin, position, readinessProof))
            {
                path.Remove(identity);

                return true;
            }

            bool Matches(ExpressionSyntax expression) => AdmissionOrigins(member, expression, new HashSet<ISymbol>(SymbolEqualityComparer.Default)).Contains(origin);

            bool Carries(ExpressionSyntax expression) => Matches(expression) && MayCarryAdmissionHandle(member, expression)
                || ScopedAdmissionOf(member) is { Active: true } source
                    && source.Origin == origin && ReadinessCarriesHolder(member, expression, readinessProof!);

            RetainedAdmissionAnalysisCounter analysis =
                RetainedAdmissionCounter(member);

            try
            {
                foreach (SyntaxNode node in AdmissionSyntax(member).LifetimeNodes)
                {
                    analysis.LifetimeNodeInspections++;

                    if (member.ReadinessSource is { OwnedAdmission: { } independent })
                    {
                        if (node.SyntaxTree == independent.Binding.SyntaxTree && node.Span == independent.Binding.Span
                            && MemberIdentity(member) == MemberIdentity(independent.Shell)) continue;

                        if (!RecoveryNodeMayExecute(member, node)) continue;
                    }
                    else if (member.OrdinaryScopedHolder is not null && !RecoveryNodeMayExecute(member, node,
                        includeOrdinaryStorageObservation: !readinessProof!.SuppressOrdinaryStorageConditions)) continue;

                    if (node is InvocationExpressionSyntax
                        && member.Model.GetOperation(node) is INameOfOperation)
                    {
                        continue;
                    }

                    // Returned or heap-stored handles leave the supported local/formal environment.
                    // Stop inheriting their authority instead of treating the escape as a new handle.
                    if (node.Span.End < position && (node is ReturnStatementSyntax { Expression: { } returned } && Carries(returned)
                        || node is ArrowExpressionClauseSyntax arrow && Carries(arrow.Expression)
                        || node is AssignmentExpressionSyntax assignment && member.Model.GetSymbolInfo(assignment.Left).Symbol is not ILocalSymbol and not IParameterSymbol && Carries(assignment.Right)))
                    {
                        return true;
                    }

                    if (node is InvocationExpressionSyntax { Expression: MemberAccessExpressionSyntax { Name.Identifier.ValueText: "Dispose" or "DisposeAsync" } access } disposal && disposal.Span.End < position && Carries(access.Expression)
                        || node is UsingStatementSyntax { Expression: { } resource } statement && statement.Span.End < position && Carries(resource)
                        || node is VariableDeclarationSyntax declaration && (declaration.Parent is LocalDeclarationStatementSyntax { UsingKeyword.RawKind: not 0 } || declaration.Parent is UsingStatementSyntax) && DisposalPosition(declaration) < position && declaration.Variables.Any(variable => variable.Initializer is not null && Carries(variable.Initializer.Value)))
                    {
                        return true;
                    }

                    if (node.Span.End < position && UserDefinedOperatorAt(member, node) is { } selectedOperation
                        && selectedOperation.Operands.Any(operand => operand.Syntax is ExpressionSyntax expression && Carries(expression)))
                    {
                        IMethodSymbol selectedOperator = selectedOperation.Method;

                        if (selectedOperation.Unsupported || !selectedOperator.IsStatic
                            || selectedOperator.Parameters.Length != selectedOperation.Operands.Length
                            || selectedOperator.Parameters.Any(static parameter => parameter.RefKind != RefKind.None)
                            || selectedOperation.Operands.Any(static operand => operand.Syntax is not ExpressionSyntax)
                            || Resolve(selectedOperator, member.Model.Compilation) is not { } target) return true;

                        AuthoredMember bound = BindArguments(member, selectedOperation.Operands.Select((operand, index) =>
                            ((ExpressionSyntax)operand.Syntax, (IParameterSymbol?)selectedOperator.Parameters[index], RefKind.None)), target);

                        if (AdmissionEndedBefore(bound, origin, int.MaxValue, path, readinessProof)) return true;
                    }

                    if (node is InvocationExpressionSyntax registration && registration.Span.End < position
                        && member.Model.GetSymbolInfo(registration).Symbol is IMethodSymbol registrationMethod
                        && DetachedExternalCallbackMethods.Contains(Normalize(registrationMethod)))
                    {
                        foreach (ArgumentSyntax argument in registration.ArgumentList.Arguments)
                        {
                            if (!IsDelegateExpression(member.Model, argument.Expression)) continue;

                            AuthoredMember[] callbacks = ResolveCallableTargets(argument.Expression,
                                member.Model, member.CallableBindings, member.AbsentCallables);

                            if (callbacks.Length == 0 || callbacks.Any(callback => CallbackCapturesOuterAdmission(
                                BindExternalCallbackContext(member, callback), origin))) return true;
                        }
                    }

                    if (node is InvocationExpressionSyntax implicitCall && implicitCall.Span.End < position
                        && Location(implicitCall) != origin
                        && TryReadinessLifetimeCall(member, implicitCall, origin, path, readinessProof!, out bool implicitEnded))
                    {
                        if (implicitEnded) return true;

                        continue;
                    }

                    if (node is InvocationExpressionSyntax call && call.Span.End < position && Location(call) != origin && AdmissionReceiver(member, call) is { } receiver && Carries(receiver) && (member.Model.GetSymbolInfo(call).Symbol is not IMethodSymbol receiverMethod || !PreservesAdmissionReceiver(receiverMethod) && !IsCompletionCombinator(receiverMethod)))
                    {
                        return true;
                    }

                    if (node is InvocationExpressionSyntax inspection
                        && inspection.Span.End < position
                        && member.Model.GetSymbolInfo(inspection).Symbol is IMethodSymbol inspector
                        && Normalize(inspector) == "System.ArgumentNullException.ThrowIfNull")
                    {
                        continue;
                    }

                    if (node is InvocationExpressionSyntax argumentCall && argumentCall.Span.End < position && Location(argumentCall) != origin && (member.Model.GetSymbolInfo(argumentCall).Symbol is not IMethodSymbol argumentMethod || !IsCompletionCombinator(argumentMethod)) && AdmissionArguments(member, argumentCall).Any(argument => argument.Expression is not DeclarationExpressionSyntax && Carries(argument.Expression)))
                    {
                        if (AdmissionArguments(member, argumentCall).Any(argument => Carries(argument.Expression) && argument.RefKind is RefKind.Ref or RefKind.Out) || member.Model.GetSymbolInfo(argumentCall).Symbol is not IMethodSymbol method || Resolve(method, member.Model.Compilation) is not { } target || AdmissionEndedBefore(BindAdmissionArguments(member, argumentCall, target), origin, int.MaxValue, path, readinessProof)
                            || LeaseHandoffEntryOf(target) is { } handoff && !FormalPreserved(handoff))
                        {
                            return true;
                        }
                    }
                }

                return false;
            }
            finally
            {
                path.Remove(identity);
            }
        }

        private void ValidatePublicationRegions(AuthoredMember member, SyntaxNode selection, string operationId, string? inherited, IReadOnlySet<int>? fieldPublications)
        {
            PublicationRegionAnalysisCounter analysis =
                PublicationRegionCounter(member);

            PublicationRegionSyntaxPlan syntax = PublicationRegionSyntax(member);

            if (syntax.CreationCandidates.Length == 0)
            {
                return;
            }

            InvocationExpressionSyntax[] calls = syntax.Invocations;

            bool DirectCreationInitializer(VariableDeclaratorSyntax variable, InvocationExpressionSyntax create)
            {
                if (variable.Initializer is null || member.Model.GetSymbolInfo(create).Symbol is not IMethodSymbol factory)
                {
                    return false;
                }

                if (create.Ancestors()
                    .TakeWhile(ancestor => ancestor != variable)
                    .Any(static ancestor => ancestor is ConditionalExpressionSyntax
                        or SwitchExpressionSyntax
                        || ancestor is BinaryExpressionSyntax binary
                            && binary.IsKind(SyntaxKind.CoalesceExpression)))
                {
                    return false;
                }

                SyntaxNode expression = CompletionPreservingExpression(create, member.Model);

                if (IsAwaitable(factory.ReturnType))
                {
                    if (expression.Parent is not AwaitExpressionSyntax awaited)
                    {
                        return false;
                    }

                    expression = awaited;
                }

                return expression == variable.Initializer.Value;
            }

            bool TryCreatedWriter(LocalDeclarationStatementSyntax declaration, out ILocalSymbol writer, out InvocationExpressionSyntax create)
            {
                writer = null!;

                create = null!;

                if (declaration.UsingKeyword.RawKind != 0 || declaration.Declaration.Variables is not [VariableDeclaratorSyntax variable] || member.Model.GetDeclaredSymbol(variable) is not ILocalSymbol local)
                {
                    return false;
                }

                InvocationExpressionSyntax[] creations = variable.Initializer?.Value.DescendantNodesAndSelf().OfType<InvocationExpressionSyntax>().Where(call => member.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method && Normalize(method) == "RetroDownfall.Arcanum.Core.Storage.IEncryptedBlobStore.CreateWriterAsync").ToArray() ?? [];

                if (creations is not [InvocationExpressionSyntax exact] || !DirectCreationInitializer(variable, exact))
                {
                    return false;
                }

                writer = local;

                create = exact;

                return true;
            }

            bool DirectReceiver(InvocationExpressionSyntax call, ISymbol writer) => call.Expression is MemberAccessExpressionSyntax access && SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(access.Expression).Symbol, writer);

            bool SupportedRootStatement(StatementSyntax statement) => !statement.Ancestors().TakeWhile(ancestor => ancestor != member.Syntax).Any(static ancestor => ancestor is StatementSyntax and not BlockSyntax || ancestor is AnonymousFunctionExpressionSyntax or LocalFunctionStatementSyntax);

            bool ExactCompletion(InvocationExpressionSyntax call) => call.ArgumentList.Arguments.Count == 0 && member.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method && IsExactWriterCompletion(method) && HasExactCompletionJoin(member, call, method) && ExactTerminalStatement(member, call) is not null;

            bool ExactCleanup(InvocationExpressionSyntax call) => call.Expression is MemberAccessExpressionSyntax access && member.Model.GetTypeInfo(access.Expression).Type is { } receiverType && member.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method && IsExactWriterCleanup(method, receiverType) && HasExactTerminalJoin(member, call, method, false) && ExactTerminalStatement(member, call) is not null;

            bool ValidProtectedTry(TryStatementSyntax statement, ILocalSymbol protectedWriter)
            {
                if (statement.Catches.Count != 0 || statement.Finally?.Block.Statements is not [ExpressionStatementSyntax cleanupStatement] || cleanupStatement.Expression.DescendantNodesAndSelf().OfType<InvocationExpressionSyntax>().ToArray() is not [InvocationExpressionSyntax cleanup] || !DirectReceiver(cleanup, protectedWriter) || !ExactCleanup(cleanup))
                {
                    return false;
                }

                for (int index = 0; index < statement.Block.Statements.Count; index++)
                {
                    StatementSyntax current = statement.Block.Statements[index];

                    if (current is ExpressionStatementSyntax terminal && terminal.Expression.DescendantNodesAndSelf().OfType<InvocationExpressionSyntax>().ToArray() is [InvocationExpressionSyntax completion] && ExactCompletion(completion) && completion.Expression is MemberAccessExpressionSyntax completionAccess && member.Model.GetSymbolInfo(completionAccess.Expression).Symbol is ILocalSymbol)
                    {
                        continue;
                    }

                    if (current is LocalDeclarationStatementSyntax nestedDeclaration && index + 1 < statement.Block.Statements.Count && statement.Block.Statements[index + 1] is TryStatementSyntax nestedTry && TryCreatedWriter(nestedDeclaration, out ILocalSymbol nestedWriter, out _) && ValidProtectedTry(nestedTry, nestedWriter))
                    {
                        index++;

                        continue;
                    }

                    return false;
                }

                return true;
            }

            bool ExactRootProtectedShape(LocalDeclarationStatementSyntax declaration, ILocalSymbol writer, TryStatementSyntax protector)
            {
                TryStatementSyntax root = protector;

                while (root.Parent is BlockSyntax containingBody && containingBody.Parent is TryStatementSyntax containingTry && containingTry.Block == containingBody)
                {
                    root = containingTry;
                }

                if (root.Parent is not BlockSyntax rootBlock)
                {
                    return false;
                }

                int rootIndex = rootBlock.Statements.IndexOf(root);

                if (rootIndex < 1 || rootBlock.Statements[rootIndex - 1] is not LocalDeclarationStatementSyntax rootDeclaration || !TryCreatedWriter(rootDeclaration, out ILocalSymbol rootWriter, out _) || !SupportedRootStatement(rootDeclaration))
                {
                    return false;
                }

                return ValidProtectedTry(root, rootWriter) && declaration.Parent is BlockSyntax declarationBlock && declarationBlock.Statements.IndexOf(declaration) is int declarationIndex && declarationIndex >= 0 && declarationIndex + 1 < declarationBlock.Statements.Count && declarationBlock.Statements[declarationIndex + 1] == protector && ValidProtectedTry(protector, writer);
            }

            bool ExactCatchCleanupRethrowShape(LocalDeclarationStatementSyntax declaration, ILocalSymbol writer, InvocationExpressionSyntax completion, InvocationExpressionSyntax[] cleanups)
            {
                if (!SupportedRootStatement(declaration) || declaration.Parent is not BlockSyntax block)
                {
                    return false;
                }

                int index = block.Statements.IndexOf(declaration);

                if (index < 0 || index + 2 >= block.Statements.Count || block.Statements[index + 1] is not TryStatementSyntax { Finally: null, Catches: [CatchClauseSyntax caught] } guarded || block.Statements[index + 2] is not ExpressionStatementSyntax normalCleanupStatement || guarded.Block.Statements is not [ExpressionStatementSyntax completionStatement] || caught.Filter is not null || caught.Block.Statements is not [ExpressionStatementSyntax exceptionalCleanupStatement, ThrowStatementSyntax { Expression: null }])
                {
                    return false;
                }

                if (completionStatement.Expression.DescendantNodesAndSelf().OfType<InvocationExpressionSyntax>().ToArray() is not [InvocationExpressionSyntax exactCompletion] || exactCompletion != completion || normalCleanupStatement.Expression.DescendantNodesAndSelf().OfType<InvocationExpressionSyntax>().ToArray() is not [InvocationExpressionSyntax normalCleanup] || exceptionalCleanupStatement.Expression.DescendantNodesAndSelf().OfType<InvocationExpressionSyntax>().ToArray() is not [InvocationExpressionSyntax exceptionalCleanup])
                {
                    return false;
                }

                return cleanups.Length == 2 && cleanups.Contains(normalCleanup) && cleanups.Contains(exceptionalCleanup) && DirectReceiver(normalCleanup, writer) && DirectReceiver(exceptionalCleanup, writer) && ExactCleanup(normalCleanup) && ExactCleanup(exceptionalCleanup);
            }

            foreach (InvocationExpressionSyntax create in syntax.CreationCandidates)
            {
                analysis.CandidateInspections++;

                if (fieldPublications?.Contains(create.SpanStart) == true
                    || !selection.Span.Contains(create.Span)
                    || member.Model.GetSymbolInfo(create).Symbol is not
                        IMethodSymbol method
                    || Normalize(method) !=
                        "RetroDownfall.Arcanum.Core.Storage.IEncryptedBlobStore.CreateWriterAsync")
                {
                    continue;
                }

                VariableDeclaratorSyntax? variable = create.Ancestors().OfType<VariableDeclaratorSyntax>().FirstOrDefault();

                ILocalSymbol? writer = variable is null ? null : member.Model.GetDeclaredSymbol(variable) as ILocalSymbol;

                string? creationGroup = EffectAt(member, create, operationId, inherited);

                InvocationExpressionSyntax[] completions = calls.Where(call => writer is not null && DirectReceiver(call, writer) && member.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method && IsExactWriterCompletion(method)).ToArray();

                InvocationExpressionSyntax[] disposals = calls.Where(call => writer is not null && DirectReceiver(call, writer) && member.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method && IsExactWriterCleanup(method, writer.Type)).ToArray();

                List<ExpressionSyntax> allowedReferences = [];

                allowedReferences.AddRange(completions.Select(static call => ((MemberAccessExpressionSyntax)call.Expression).Expression));

                allowedReferences.AddRange(disposals.Select(static call => ((MemberAccessExpressionSyntax)call.Expression).Expression));

                bool exactOwnership = writer is not null && variable is not null && DirectCreationInitializer(variable, create) && HasOnlyReferences(member, writer, [.. allowedReferences]);

                bool exactCompletion = completions is [InvocationExpressionSyntax completion] && ExactCompletion(completion) && EffectAt(member, completion, operationId, inherited) == creationGroup;

                bool valid = false;

                if (variable?.Parent is VariableDeclarationSyntax declaration && (declaration.Parent is LocalDeclarationStatementSyntax { UsingKeyword.RawKind: not 0 } || declaration.Parent is UsingStatementSyntax))
                {
                    bool asynchronous = declaration.Parent is LocalDeclarationStatementSyntax { AwaitKeyword.RawKind: not 0 } or UsingStatementSyntax { AwaitKeyword.RawKind: not 0 };

                    string cleanupName = asynchronous ? "DisposeAsync" : "Dispose";

                    IMethodSymbol[] selectedCleanups = writer is null
                        ? []
                        : SelectEffectiveCleanupMembers(
                            writer.Type,
                            cleanupName);

                    ExpressionStatementSyntax? completionStatement = completions.Length == 1 ? ExactTerminalStatement(member, completions[0]) : null;

                    bool lexical = declaration.Parent switch
                    {
                        LocalDeclarationStatementSyntax local when local.Parent is BlockSyntax block => completionStatement?.Parent == block && completionStatement.SpanStart > local.Span.End && block.Statements.Skip(block.Statements.IndexOf(local) + 1).All(statement => statement is ExpressionStatementSyntax or LocalDeclarationStatementSyntax || statement == block.Statements[^1] && statement is ReturnStatementSyntax),
                        UsingStatementSyntax statement when statement.Statement is BlockSyntax block => completionStatement?.Parent == block && block.Statements.All(nested => nested is ExpressionStatementSyntax or LocalDeclarationStatementSyntax || nested == block.Statements[^1] && nested is ReturnStatementSyntax),
                        _ => false,
                    };

                    valid = exactOwnership && exactCompletion && disposals.Length == 0 && declaration.Variables.Count == 1 && selectedCleanups is [IMethodSymbol selected] && IsExactWriterCleanup(selected, writer!.Type) && lexical && completions is [InvocationExpressionSyntax completed] && IsUnconditionalExecution(member, completed, create.Span.End) && declaration.Parent is StatementSyntax usingStatement && SupportedRootStatement(usingStatement) && EffectAt(member, declaration, operationId, inherited, DisposalPosition(declaration), declaration) == creationGroup;
                }
                else if (variable?.Parent?.Parent is LocalDeclarationStatementSyntax local && writer is not null && local.Parent is BlockSyntax block)
                {
                    int declarationIndex = block.Statements.IndexOf(local);

                    TryStatementSyntax? protector = declarationIndex >= 0 && declarationIndex + 1 < block.Statements.Count ? block.Statements[declarationIndex + 1] as TryStatementSyntax : null;

                    bool sameCleanupGroup = disposals.All(cleanup => EffectAt(member, cleanup, operationId, inherited) == creationGroup);

                    valid = creationGroup is not null && exactOwnership && exactCompletion && sameCleanupGroup && (disposals is [InvocationExpressionSyntax cleanup] && ExactCleanup(cleanup) && protector is not null && protector.Block.Span.Contains(completions[0].Span) && ExactRootProtectedShape(local, writer, protector) || completions is [InvocationExpressionSyntax completed] && ExactCatchCleanupRethrowShape(local, writer, completed, disposals));
                }

                if (!valid || creationGroup is null)
                {
                    diagnostics.Add(new("HOSTED_SITE_PUBLICATION_REGION_INCOMPLETE", operationId + "/site@" + Location(create), "A local writer requires one completion-owned creation, exclusive references, and exact joined completion plus exhaustive cleanup under the same retained group."));
                }
            }
        }

        private PublicationRegionSyntaxPlan PublicationRegionSyntax(
            AuthoredMember member)
        {
            PublicationRegionAnalysisCounter analysis =
                PublicationRegionCounter(member);

            analysis.IndexRequests++;

            GraphMemberIdentity memberKey = MemberIdentity(member);

            if (publicationRegionSyntaxPlans.TryGetValue(
                    memberKey,
                    out PublicationRegionSyntaxPlan? cached))
            {
                return cached;
            }

            analysis.IndexBuilds++;

            InvocationExpressionSyntax[] invocations = member.Syntax
                .DescendantNodesAndSelf()
                .OfType<InvocationExpressionSyntax>()
                .ToArray();

            PublicationRegionSyntaxPlan result = new(
                invocations,
                invocations.Where(static call => call.Expression
                        .DescendantTokens()
                        .Any(static token => token.ValueText ==
                            "CreateWriterAsync"))
                    .ToArray());

            publicationRegionSyntaxPlans.Add(memberKey, result);

            return result;
        }

        private PublicationRegionAnalysisCounter PublicationRegionCounter(
            AuthoredMember member)
        {
            GraphMemberIdentity identity = MemberIdentity(member);

            if (!publicationRegionAnalysis.TryGetValue(
                    identity,
                    out PublicationRegionAnalysisCounter? analysis))
            {
                analysis = new(MethodKey(member.Symbol));

                publicationRegionAnalysis.Add(identity, analysis);
            }

            return analysis;
        }

        private AdmissionSyntaxPlan AdmissionSyntax(AuthoredMember member)
        {
            GraphMemberIdentity memberKey = MemberIdentity(member);

            if (admissionSyntaxPlans.TryGetValue(
                    memberKey,
                    out AdmissionSyntaxPlan? cached))
            {
                return cached;
            }

            SyntaxNode[] descendants = member.Syntax.DescendantNodes().ToArray();

            AdmissionSyntaxPlan result = new(
                descendants
                    .OfType<InvocationExpressionSyntax>()
                    .Where(static call => call.Expression is MemberAccessExpressionSyntax
                    {
                        Name.Identifier.ValueText: "TryAcquireWorkLease"
                            or "TryBeginExternalEffectGroup",
                    })
                    .ToArray(),
                descendants.OfType<InvocationExpressionSyntax>().ToArray(),
                descendants.OfType<AssignmentExpressionSyntax>().ToArray(),
                descendants.OfType<LocalDeclarationStatementSyntax>().ToArray(),
                member.Syntax
                    .DescendantNodesAndSelf(node => node == member.Syntax
                        || node is not AnonymousFunctionExpressionSyntax
                            and not LocalFunctionStatementSyntax)
                    .Where(node => node is InvocationExpressionSyntax
                        or ArrowExpressionClauseSyntax
                        or AssignmentExpressionSyntax
                        or UsingStatementSyntax
                        or VariableDeclarationSyntax
                        || node is ReturnStatementSyntax { Expression: not null }
                        || UserDefinedOperatorAt(member, node) is not null)
                    .ToArray());

            admissionSyntaxPlans.Add(memberKey, result);

            string metricMember = MethodKey(member.Symbol);

            if (!retainedAdmissionAnalysis.TryGetValue(
                    metricMember,
                    out RetainedAdmissionAnalysisCounter? analysis))
            {
                analysis = new();

                retainedAdmissionAnalysis.Add(metricMember, analysis);
            }

            analysis.SourceIndexBuilds++;

            return result;
        }

        private RetainedAdmissionAnalysisCounter RetainedAdmissionCounter(AuthoredMember member)
        {
            string metricMember = MethodKey(member.Symbol);

            if (!retainedAdmissionAnalysis.TryGetValue(
                    metricMember,
                    out RetainedAdmissionAnalysisCounter? analysis))
            {
                analysis = new();

                retainedAdmissionAnalysis.Add(metricMember, analysis);
            }

            return analysis;
        }

        private string? FindRetainedAdmission(AuthoredMember member, SyntaxNode site, string admissionName, GrimoireWorkKind? kind, int? atPosition = null, SyntaxNode? disposing = null)
        {
            int position = atPosition ?? site.SpanStart;

            RetainedAdmissionAnalysisCounter analysis =
                RetainedAdmissionCounter(member);

            analysis.SemanticQueries++;

            analysis.QueryPositions.Add(position);

            AdmissionSyntaxPlan syntax = AdmissionSyntax(member);

            foreach (InvocationExpressionSyntax admission in syntax.AdmissionCalls.Where(call => call.SpanStart < position))
            {
                if (member.Model.GetSymbolInfo(admission).Symbol is not IMethodSymbol method || method.Name != admissionName || !IsGuardedAdmission(admission))
                {
                    continue;
                }

                string expected = admissionName == "TryAcquireWorkLease" ? "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireConnectionAdmissionGate.TryAcquireWorkLease" : "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease.TryBeginExternalEffectGroup";

                if (Normalize(method) != expected || kind is not null && member.Model.GetSymbolInfo(admission.ArgumentList.Arguments[0].Expression).Symbol?.Name != kind.ToString())
                {
                    continue;
                }

                // CK-3: a group begun on a receiver that is not a must-alias of a work lease is retained by nothing.
                if (admissionName == "TryBeginExternalEffectGroup" && !LeaseReceiverProven(member, admission, out _))
                {
                    continue;
                }

                BlockSyntax? block;

                int admittedAt;

                if (TryLoopAdmissionRegion(admission, site, position, out BlockSyntax? loopBlock, out int loopAdmission))
                {
                    block = loopBlock;

                    admittedAt = loopAdmission;
                }
                else
                {
                    IfStatementSyntax guard = admission.Ancestors().OfType<IfStatementSyntax>().First(candidate => candidate.Condition.Span.Contains(admission.Span));

                    bool trueMeansAdmitted = ProvesCallTrue(guard.Condition, admission);

                    StatementSyntax? successful = trueMeansAdmitted ? guard.Statement : guard.Else?.Statement;

                    BlockSyntax? successBranch = successful is BlockSyntax branch && branch.Span.Contains(position) ? branch : null;

                    if (successBranch is null && (trueMeansAdmitted || !FailureTerminates(guard)))
                    {
                        continue;
                    }

                    block = successBranch ?? guard.Parent as BlockSyntax;

                    admittedAt = successBranch?.OpenBraceToken.Span.End ?? guard.Span.End;
                }

                if (block is null || !site.Ancestors().Contains(block) || admittedAt > position || admission.Ancestors().OfType<AnonymousFunctionExpressionSyntax>().FirstOrDefault() != site.Ancestors().OfType<AnonymousFunctionExpressionSyntax>().FirstOrDefault())
                {
                    continue;
                }

                SingleVariableDesignationSyntax? designation = admission.ArgumentList.DescendantNodes().OfType<SingleVariableDesignationSyntax>().LastOrDefault();

                ISymbol? group = designation is null ? member.Model.GetSymbolInfo(admission.ArgumentList.Arguments.Last().Expression).Symbol : member.Model.GetDeclaredSymbol(designation);

                if (group is null)
                {
                    continue;
                }

                // A may-alias set can invalidate an instance, but cannot prove that a using owns it.
                bool ReferencesGroup(ExpressionSyntax expression)
                {
                    IOperation? operation = member.Model.GetOperation(expression);

                    while (operation is IConversionOperation conversion)
                    {
                        operation = conversion.Operand;
                    }

                    return operation switch
                    {
                        ILocalReferenceOperation local => SymbolEqualityComparer.Default.Equals(local.Local, group),
                        IParameterReferenceOperation parameter => SymbolEqualityComparer.Default.Equals(parameter.Parameter, group),
                        _ => SymbolEqualityComparer.Default.Equals(member.Model.GetSymbolInfo(expression).Symbol, group),
                    };
                }

                bool IsNonThrowingPrelude(StatementSyntax statement) =>
                    statement is EmptyStatementSyntax
                    || statement is LocalDeclarationStatementSyntax local
                        && local.Declaration.Variables.All(variable =>
                            variable.Initializer is null
                            || member.Model.GetConstantValue(variable.Initializer.Value).HasValue
                            || variable.Initializer.Value.IsKind(SyntaxKind.DefaultLiteralExpression)
                            || variable.Initializer.Value is DefaultExpressionSyntax);

                bool DominatesWithImmediateOwnership(
                    LocalDeclarationStatementSyntax declaration)
                {
                    if (declaration.UsingKeyword.RawKind == 0
                        || declaration.Declaration.Variables is not [VariableDeclaratorSyntax variable]
                        || variable.Initializer is null
                        || !ReferencesGroup(variable.Initializer.Value)
                        || declaration.SpanStart <= admittedAt
                        || declaration.Span.End >= position
                        || declaration.Parent is not BlockSyntax declarationBlock
                        || !site.AncestorsAndSelf().Contains(declarationBlock)
                        || declarationBlock != block
                            && !declarationBlock.Ancestors().Contains(block))
                    {
                        return false;
                    }

                    StatementSyntax pathStatement = declaration;

                    BlockSyntax pathBlock = declarationBlock;

                    while (true)
                    {
                        if (pathBlock.Statements
                            .TakeWhile(statement => statement != pathStatement)
                            .Any(statement => statement.Span.End > admittedAt
                                && !IsNonThrowingPrelude(statement)))
                        {
                            return false;
                        }

                        if (pathBlock == block)
                        {
                            return true;
                        }

                        if (pathBlock.Parent is BlockSyntax parentBlock)
                        {
                            pathStatement = pathBlock;

                            pathBlock = parentBlock;

                            continue;
                        }

                        if (pathBlock.Parent is TryStatementSyntax protector
                            && protector.Block == pathBlock
                            && protector.Parent is BlockSyntax protectedParent)
                        {
                            pathStatement = protector;

                            pathBlock = protectedParent;

                            continue;
                        }

                        return false;
                    }
                }

                bool DominatesWithExactManualOwnership(
                    LocalDeclarationStatementSyntax declaration)
                {
                    if (declaration.UsingKeyword.RawKind != 0
                        || declaration.Declaration.Variables is not
                            [VariableDeclaratorSyntax variable]
                        || variable.Initializer is null
                        || !ReferencesGroup(variable.Initializer.Value)
                        || member.Model.GetOperation(variable.Initializer) is not IVariableInitializerOperation initializer
                        || initializer.Value.DescendantsAndSelf().OfType<IConversionOperation>().Any(static conversion =>
                            conversion.OperatorMethod is not null
                            || !(conversion.Conversion.IsIdentity
                                || conversion.IsImplicit && conversion.Conversion.IsReference))
                        || PerUnitTransparentOperation(initializer.Value) is not
                            (ILocalReferenceOperation or IParameterReferenceOperation)
                        || member.Model.GetDeclaredSymbol(variable) is not
                            ILocalSymbol lease
                        || declaration.SpanStart <= admittedAt
                        || declaration.Span.End >= position
                        || declaration.Parent != block)
                    {
                        return false;
                    }

                    int declarationIndex = block.Statements.IndexOf(declaration);

                    StatementSyntax[] following = declarationIndex < 0
                        ? []
                        : block.Statements.Skip(declarationIndex + 1).ToArray();

                    int protectorIndex = Array.FindIndex(following,
                        static statement => statement is TryStatementSyntax);

                    if (declarationIndex < 0
                        || block.Statements.Take(declarationIndex)
                            .Where(statement => statement.Span.End > admittedAt)
                            .Any(statement => !IsNonThrowingTransferredPrelude(statement))
                        || protectorIndex < 0
                        || !following.Take(protectorIndex).All(IsNonThrowingTransferredPrelude)
                        || following[protectorIndex] is not TryStatementSyntax
                        {
                            Finally: { } finalizer,
                        } protector
                        || !protector.Block.Span.Contains(site.Span))
                    {
                        return false;
                    }

                    InvocationExpressionSyntax[] cleanups = finalizer.Block
                        .DescendantNodes()
                        .OfType<InvocationExpressionSyntax>()
                        .Where(call => AdmissionReceiver(member, call) is { } receiver
                            && SymbolEqualityComparer.Default.Equals(
                                member.Model.GetSymbolInfo(receiver).Symbol,
                                lease)
                            && member.Model.GetSymbolInfo(call).Symbol is
                                IMethodSymbol method
                            && method.Name is "Dispose" or "DisposeAsync")
                        .ToArray();

                    if (cleanups is not [InvocationExpressionSyntax cleanup]
                        || member.Model.GetSymbolInfo(cleanup).Symbol is not
                            IMethodSymbol cleanupMethod
                        || !SymbolIsStableWithin(member, lease, variable.Span.End, cleanup.Span.End))
                    {
                        return false;
                    }

                    if (cleanupMethod.Name == "Dispose")
                    {
                        return TypeKey(cleanupMethod.ReturnType) == "System.Void"
                            && finalizer.Block.Statements is
                                [ExpressionStatementSyntax statement]
                            && statement.Expression == cleanup;
                    }

                    return ConsumesAdmissionReceiver(cleanupMethod)
                        && CompletionPoint(member, cleanup, false) is not null
                        && (RunsOnEveryFinallyPath(finalizer, cleanup)
                            || ExactConditionalValueTaskFinallyCompletion(member, cleanup) == finalizer);
                }

                bool retained = syntax.LocalDeclarations
                        .Any(declaration =>
                            DominatesWithImmediateOwnership(declaration)
                            || admissionName == "TryAcquireWorkLease"
                                && DominatesWithExactManualOwnership(declaration))
                    || site.Ancestors().OfType<UsingStatementSyntax>().Any(statement => statement.Expression is not null && ReferencesGroup(statement.Expression) || statement.Declaration?.Variables.Any(variable => variable.Initializer is not null && ReferencesGroup(variable.Initializer.Value)) == true);

                if (retained)
                {
                    bool disposed = AdmissionEndedBefore(member, Location(admission), position, []);

                    if (disposed)
                    {
                        continue;
                    }

                    return Location(admission);
                }
            }

            if (admissionName == "TryBeginExternalEffectGroup"
                && FindManuallyRetainedEffectAdmission(member, syntax, site, position) is { } manualEffect)
            {
                return manualEffect;
            }

            if (admissionName != "TryAcquireWorkLease" || kind is null)
            {
                return null;
            }

            bool IsNonThrowingTransferredPrelude(StatementSyntax statement) =>
                statement is EmptyStatementSyntax
                || statement is LocalDeclarationStatementSyntax declaration
                    && declaration.Declaration.Variables.All(variable =>
                        variable.Initializer is null
                        || (member.Model.GetConstantValue(variable.Initializer.Value).HasValue
                            || variable.Initializer.Value.IsKind(SyntaxKind.DefaultLiteralExpression)
                            || variable.Initializer.Value is DefaultExpressionSyntax)
                        && member.Model.GetOperation(variable.Initializer) is IVariableInitializerOperation initializer
                        && (PerUnitTransparentOperation(initializer.Value).ConstantValue.HasValue
                            || PerUnitTransparentOperation(initializer.Value) is IDefaultValueOperation
                            || initializer.Value is IConversionOperation
                            {
                                IsImplicit: true, OperatorMethod: null,
                                Operand: IDefaultValueOperation defaultValue,
                            } defaultConversion && !defaultConversion.Conversion.IsUserDefined
                                && SymbolEqualityComparer.Default.Equals(defaultConversion.Type, defaultValue.Type)
                            || initializer.Value is IConversionOperation
                            {
                                IsImplicit: true, OperatorMethod: null,
                                Operand.ConstantValue: { HasValue: true, Value: null },
                            } conversion && !conversion.Conversion.IsUserDefined));

            bool RunsOnEveryFinallyPath(
                FinallyClauseSyntax finalizer,
                InvocationExpressionSyntax cleanup)
            {
                if (cleanup.Ancestors().TakeWhile(ancestor => ancestor != finalizer)
                    .Any(static ancestor => ancestor is ConditionalExpressionSyntax or SwitchExpressionArmSyntax
                        || ancestor is BinaryExpressionSyntax binary && binary.IsKind(SyntaxKind.CoalesceExpression)))
                {
                    return false;
                }

                if (cleanup.Ancestors().OfType<ExpressionStatementSyntax>()
                        .FirstOrDefault() is not { } cleanupStatement
                    || cleanupStatement.Parent is not BlockSyntax cleanupBlock)
                {
                    return false;
                }

                StatementSyntax path = cleanupStatement;

                BlockSyntax pathBlock = cleanupBlock;

                while (true)
                {
                    if (pathBlock.Statements
                        .TakeWhile(statement => statement != path)
                        .Any(statement => !IsNonThrowingTransferredPrelude(statement)))
                    {
                        return false;
                    }

                    if (pathBlock == finalizer.Block)
                    {
                        return true;
                    }

                    if (pathBlock.Parent is FinallyClauseSyntax nestedFinalizer
                        && nestedFinalizer.Parent is TryStatementSyntax nestedProtector
                        && nestedProtector.Parent is BlockSyntax parentBlock)
                    {
                        path = nestedProtector;

                        pathBlock = parentBlock;

                        continue;
                    }

                    return false;
                }
            }

            foreach (LocalDeclarationStatementSyntax declaration in syntax.LocalDeclarations)
            {
                if (declaration.Declaration.Variables is not [VariableDeclaratorSyntax variable]
                    || variable.Initializer is null
                    || member.Model.GetDeclaredSymbol(variable) is not ILocalSymbol lease
                    || ResolveReturnedAdmissionProofs(member, variable.Initializer.Value) is not
                        [ReturnedAdmissionProof proof]
                    || proof.WorkKind != kind.ToString()
                    || declaration.Span.End >= position
                    || declaration.Parent is not BlockSyntax declarationBlock)
                {
                    continue;
                }

                bool usingOwned = declaration.UsingKeyword.RawKind != 0
                    && site.AncestorsAndSelf().Contains(declarationBlock);

                bool manuallyOwned = false;

                if (declaration.UsingKeyword.RawKind == 0)
                {
                    int declarationIndex = declarationBlock.Statements.IndexOf(declaration);

                    StatementSyntax[] following = declarationIndex < 0
                        ? []
                        : declarationBlock.Statements
                            .Skip(declarationIndex + 1)
                            .ToArray();

                    int protectorIndex = Array.FindIndex(
                        following,
                        static statement => statement is TryStatementSyntax);

                    if (protectorIndex >= 0
                        && following.Take(protectorIndex)
                            .All(IsNonThrowingTransferredPrelude)
                        && following[protectorIndex] is TryStatementSyntax
                        {
                            Finally: { } finalizer,
                        } protector
                        && protector.Block.Span.Contains(site.Span))
                    {
                        InvocationExpressionSyntax[] cleanups = finalizer.Block
                            .DescendantNodes()
                            .OfType<InvocationExpressionSyntax>()
                            .Where(call => AdmissionReceiver(member, call) is { } receiver
                                && SymbolEqualityComparer.Default.Equals(
                                    member.Model.GetSymbolInfo(receiver).Symbol,
                                    lease)
                                && member.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method
                                && method.Name is "Dispose" or "DisposeAsync")
                            .ToArray();

                        manuallyOwned = cleanups is [InvocationExpressionSyntax cleanup]
                            && member.Model.GetSymbolInfo(cleanup).Symbol is IMethodSymbol cleanupMethod
                            && (cleanupMethod.Name == "Dispose"
                                && TypeKey(cleanupMethod.ReturnType) == "System.Void"
                                || cleanupMethod.Name == "DisposeAsync"
                                && CompletionPoint(member, cleanup, false) is not null)
                            && RunsOnEveryFinallyPath(finalizer, cleanup);
                    }
                }

                if ((!usingOwned && !manuallyOwned)
                    || AdmissionEndedBefore(member, proof.Origin, position, []))
                {
                    continue;
                }

                return proof.Origin;
            }

            return null;
        }

        private string? FindManuallyRetainedEffectAdmission(
            AuthoredMember member,
            AdmissionSyntaxPlan syntax,
            SyntaxNode site,
            int position)
        {
            static bool IsNullInitialization(
                SemanticModel model,
                EqualsValueClauseSyntax? initializer) =>
                initializer is null
                || initializer.Value.IsKind(SyntaxKind.DefaultLiteralExpression)
                || initializer.Value is DefaultExpressionSyntax
                || model.GetConstantValue(initializer.Value) is
                {
                    HasValue: true,
                    Value: null,
                };

            bool IsExactNonNullGuard(
                ExpressionSyntax condition,
                ISymbol carrier) =>
                condition is IsPatternExpressionSyntax
                {
                    Expression: { } tested,
                    Pattern: UnaryPatternSyntax
                    {
                        Pattern: ConstantPatternSyntax
                        {
                            Expression.RawKind: (int)SyntaxKind.NullLiteralExpression,
                        },
                    },
                }
                && SymbolEqualityComparer.Default.Equals(
                    member.Model.GetSymbolInfo(tested).Symbol,
                    carrier);

            bool IsProvenNonNullAdmissionGuard(IfStatementSyntax guard)
            {
                if (guard.Else is not null
                    || guard.Condition is not IsPatternExpressionSyntax
                    {
                        Expression: { } tested,
                        Pattern: UnaryPatternSyntax
                        {
                            Pattern: ConstantPatternSyntax
                            {
                                Expression.RawKind: (int)SyntaxKind.NullLiteralExpression,
                            },
                        },
                    })
                {
                    return false;
                }

                return AdmissionOrigins(
                        member,
                        tested,
                        new HashSet<ISymbol>(SymbolEqualityComparer.Default))
                    .Count != 0;
            }

            static bool SharesConditionalBranch(
                IfStatementSyntax guard,
                SyntaxNode first,
                SyntaxNode second) =>
                guard.Statement.Span.Contains(first.Span)
                    && guard.Statement.Span.Contains(second.Span)
                || guard.Else?.Statement.Span.Contains(first.Span) == true
                    && guard.Else.Statement.Span.Contains(second.Span);

            bool IsNonThrowingPrelude(StatementSyntax statement) =>
                statement is EmptyStatementSyntax
                || statement is LocalDeclarationStatementSyntax declaration
                    && declaration.Declaration.Variables.All(variable =>
                        IsNullInitialization(member.Model, variable.Initializer));

            bool RunsOnEveryFinallyPath(
                FinallyClauseSyntax finalizer,
                InvocationExpressionSyntax cleanup,
                ISymbol carrier)
            {
                if (cleanup.Ancestors().OfType<ExpressionStatementSyntax>()
                        .FirstOrDefault() is not { } cleanupStatement)
                {
                    return false;
                }

                StatementSyntax path;
                BlockSyntax pathBlock;

                if (cleanupStatement.Parent is BlockSyntax cleanupBlock)
                {
                    path = cleanupStatement;
                    pathBlock = cleanupBlock;
                }
                else if (cleanupStatement.Parent is IfStatementSyntax guard
                    && guard.Statement == cleanupStatement
                    && IsExactNonNullGuard(guard.Condition, carrier)
                    && guard.Parent is BlockSyntax guardedParent)
                {
                    path = guard;
                    pathBlock = guardedParent;
                }
                else
                {
                    return false;
                }

                while (true)
                {
                    if (pathBlock.Statements
                        .TakeWhile(statement => statement != path)
                        .Any(statement => !IsNonThrowingPrelude(statement)))
                    {
                        return false;
                    }

                    if (pathBlock == finalizer.Block)
                    {
                        return true;
                    }

                    if (pathBlock.Parent is IfStatementSyntax guard
                        && guard.Statement == pathBlock
                        && IsExactNonNullGuard(guard.Condition, carrier)
                        && guard.Parent is BlockSyntax guardedParent)
                    {
                        path = guard;
                        pathBlock = guardedParent;

                        continue;
                    }

                    if (pathBlock.Parent is TryStatementSyntax caught
                        && caught.Block == pathBlock
                        && caught.Finally is null
                        && caught.Catches.Count != 0
                        && caught.Parent is BlockSyntax caughtParent)
                    {
                        path = caught;
                        pathBlock = caughtParent;

                        continue;
                    }

                    if (pathBlock.Parent is TryStatementSyntax protectedTry
                        && protectedTry.Block == pathBlock
                        && protectedTry.Parent is BlockSyntax protectedParent)
                    {
                        path = protectedTry;
                        pathBlock = protectedParent;

                        continue;
                    }

                    if (pathBlock.Parent is FinallyClauseSyntax nestedFinalizer
                        && nestedFinalizer.Parent is TryStatementSyntax nestedProtector
                        && nestedProtector.Parent is BlockSyntax parentBlock)
                    {
                        path = nestedProtector;
                        pathBlock = parentBlock;

                        continue;
                    }

                    return false;
                }
            }

            foreach (InvocationExpressionSyntax admission in syntax.Invocations
                .Where(call => call.SpanStart < position
                    && member.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method
                    && Normalize(method)
                        == "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease.TryBeginExternalEffectGroup"))
            {
                if (!IsGuardedAdmission(admission)
                    || !LeaseReceiverProven(member, admission, out _)
                    || admission.ArgumentList.Arguments.LastOrDefault()?.Expression is not { } outExpression)
                {
                    continue;
                }

                SingleVariableDesignationSyntax? designation = outExpression
                    .DescendantNodesAndSelf()
                    .OfType<SingleVariableDesignationSyntax>()
                    .SingleOrDefault();

                ISymbol? admitted = designation is null
                    ? member.Model.GetSymbolInfo(outExpression).Symbol
                    : member.Model.GetDeclaredSymbol(designation);

                TryStatementSyntax? protector = admission.Ancestors()
                    .OfType<TryStatementSyntax>()
                    .FirstOrDefault(candidate => candidate.Block.Span.Contains(site.Span)
                        && candidate.Finally is not null);

                if (admitted is null || protector?.Finally is not { } finalizer)
                {
                    continue;
                }

                IfStatementSyntax[] conditionalAdmission = admission.Ancestors()
                    .OfType<IfStatementSyntax>()
                    .TakeWhile(guard => protector.Block.Span.Contains(guard.Span))
                    .Where(guard => guard.Statement.Span.Contains(admission.Span)
                        && !guard.Condition.Span.Contains(admission.Span)
                        && !guard.Statement.Span.Contains(site.Span))
                    .ToArray();

                if (conditionalAdmission.Any(guard => !IsProvenNonNullAdmissionGuard(guard)))
                {
                    continue;
                }

                AssignmentExpressionSyntax[] transfers = syntax.Assignments
                    .Where(assignment => assignment.IsKind(SyntaxKind.SimpleAssignmentExpression)
                        && assignment.SpanStart > admission.Span.End
                        && assignment.Span.End < position
                        && SymbolEqualityComparer.Default.Equals(
                            member.Model.GetSymbolInfo(assignment.Right).Symbol,
                            admitted))
                    .ToArray();

                ISymbol carrier = admitted;

                if (transfers is [AssignmentExpressionSyntax singleTransfer])
                {
                    if (singleTransfer.Ancestors()
                        .TakeWhile(ancestor => ancestor != protector.Block)
                        .Any(ancestor => ancestor is IfStatementSyntax guard
                                && !SharesConditionalBranch(
                                    guard,
                                    singleTransfer,
                                    site)
                                && !IsProvenNonNullAdmissionGuard(guard)
                            || ancestor is ConditionalExpressionSyntax
                            or SwitchExpressionSyntax
                            or SwitchStatementSyntax
                            or AnonymousFunctionExpressionSyntax
                            or LocalFunctionStatementSyntax)
                        || member.Model.GetSymbolInfo(singleTransfer.Left).Symbol is not ILocalSymbol transferred)
                    {
                        continue;
                    }

                    carrier = transferred;
                }
                else if (transfers.Length != 0)
                {
                    continue;
                }

                VariableDeclaratorSyntax? carrierDeclaration = carrier.DeclaringSyntaxReferences
                    .Select(static reference => reference.GetSyntax())
                    .OfType<VariableDeclaratorSyntax>()
                    .SingleOrDefault();

                if (carrierDeclaration is null
                    || !SymbolEqualityComparer.Default.Equals(carrier, admitted)
                        && !IsNullInitialization(member.Model, carrierDeclaration.Initializer))
                {
                    continue;
                }

                AssignmentExpressionSyntax[] carrierWrites = syntax.Assignments
                    .Where(assignment => SymbolEqualityComparer.Default.Equals(
                        member.Model.GetSymbolInfo(assignment.Left).Symbol,
                        carrier))
                    .ToArray();

                bool exactWrites = SymbolEqualityComparer.Default.Equals(carrier, admitted)
                    ? carrierWrites.Length == 0
                    : carrierWrites is [AssignmentExpressionSyntax only]
                        && transfers.Length == 1
                        && only == transfers[0];

                if (!exactWrites
                    || AdmissionEndedBefore(
                        member,
                        Location(admission),
                        position,
                        []))
                {
                    continue;
                }

                bool consumedBeforeSite = syntax.Invocations
                    .Where(call => call != admission
                        && call.SpanStart > admission.Span.End
                        && call.Span.End < position)
                    .Any(call => AdmissionReceiver(member, call) is { } receiver
                            && (SymbolEqualityComparer.Default.Equals(
                                    member.Model.GetSymbolInfo(receiver).Symbol,
                                    admitted)
                                || SymbolEqualityComparer.Default.Equals(
                                    member.Model.GetSymbolInfo(receiver).Symbol,
                                    carrier))
                        || AdmissionArguments(member, call).Any(argument =>
                            SymbolEqualityComparer.Default.Equals(
                                member.Model.GetSymbolInfo(argument.Expression).Symbol,
                                admitted)
                            || SymbolEqualityComparer.Default.Equals(
                                member.Model.GetSymbolInfo(argument.Expression).Symbol,
                                carrier)));

                if (consumedBeforeSite)
                {
                    continue;
                }

                InvocationExpressionSyntax[] cleanups = finalizer.Block
                    .DescendantNodes()
                    .OfType<InvocationExpressionSyntax>()
                    .Where(call => AdmissionReceiver(member, call) is { } receiver
                        && SymbolEqualityComparer.Default.Equals(
                            member.Model.GetSymbolInfo(receiver).Symbol,
                            carrier)
                        && member.Model.GetSymbolInfo(call).Symbol is IMethodSymbol method
                        && method.Name is "Dispose" or "DisposeAsync")
                    .ToArray();

                if (cleanups is not [InvocationExpressionSyntax cleanup]
                    || member.Model.GetSymbolInfo(cleanup).Symbol is not IMethodSymbol cleanupMethod
                    || cleanupMethod.Name == "DisposeAsync"
                        && CompletionPoint(member, cleanup, false) is null
                    || cleanupMethod.Name == "Dispose"
                        && TypeKey(cleanupMethod.ReturnType) != "System.Void"
                    || !RunsOnEveryFinallyPath(finalizer, cleanup, carrier))
                {
                    continue;
                }

                return Location(admission);
            }

            return null;
        }

        private HostedProducerSiteKind? Classify(
            IMethodSymbol method,
            string callee,
            SyntaxNode node,
            AuthoredMember member)
        {
            SemanticModel model = member.Model;

            if (callee.StartsWith("<ambiguous:", StringComparison.Ordinal))
            {
                RefuseTraversalCompletion();

                diagnostics.Add(new("HOSTED_CALL_TARGET_UNRESOLVED", Location(node), callee));

                return null;
            }

            // A framework call that executes an EF query is a database access, recognized by the exact framework
            // identity of the call and the provenance of its operand (see ClassifyEfQueryCall).
            if (node is InvocationExpressionSyntax or BaseObjectCreationExpressionSyntax
                && ClassifyEfQueryCall(member, node, method, out _) == EfQueryCall.Terminal)
            {
                return HostedProducerSiteKind.DatabaseAccess;
            }

            if ((IsBootstrapConsoleRedirection(member)
                    || IsBootstrapConsoleRestoration(member))
                && IsExactFrameworkType(method.ContainingType,
                    "System.Console", typeof(Console).Assembly.GetName())
                && method.Name is "SetOut" or "SetError")
            {
                return HostedProducerSiteKind.FileSystemEffect;
            }

            if (TypeKey(method.ContainingType) == "System.IO.FileStream"
                && method.Name is "Dispose" or "DisposeAsync"
                && node is InvocationExpressionSyntax
                {
                    Expression: MemberAccessExpressionSyntax
                    {
                        Expression: { } receiver,
                    },
                }
                && HasExactReadOnlyFileStreamCleanupProvenance(
                    member,
                    receiver))
            {
                return HostedProducerSiteKind.FileSystemRead;
            }

            if (Vocabulary.TryGetValue(callee, out HostedProducerSiteKind kind))
            {
                return kind;
            }

            if (callee is "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions.CreateScope" or "Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions.CreateAsyncScope" or "Microsoft.Extensions.DependencyInjection.IServiceScopeFactory.CreateScope")
            {
                return HostedProducerSiteKind.ScopeCreation;
            }

            if (method.GetAttributes().Any(static attribute => attribute.AttributeClass?.Name == "GrimoireConnectionAcquisitionRouteAttribute"))
            {
                return HostedProducerSiteKind.OrdinaryConnectionRoute;
            }

            if ((callee is "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease.TryBeginExternalEffectGroup" or "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireConnectionAdmissionGate.TryAcquireWorkLease")
                && (IsGuardedAdmission(node)
                    || callee == "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease.TryBeginExternalEffectGroup"
                    && node is InvocationExpressionSyntax conditionalRecovery
                    && IsConditionalRecoveryEffectAdmission(model, conditionalRecovery)))
            {
                return HostedProducerSiteKind.EffectFrontier;
            }

            if (TypeKey(method.ContainingType) == "System.IO.StreamWriter" && method.Name is ".ctor" or "Write" or "WriteAsync" or "WriteLine" or "WriteLineAsync" or "Flush" or "FlushAsync" or "Dispose" or "DisposeAsync" or "Close")
            {
                return HostedProducerSiteKind.FileSystemEffect;
            }

            if (callee is "RetroDownfall.Arcanum.Core.Storage.EncryptedBlobWriter.Dispose" or "RetroDownfall.Arcanum.Core.Storage.EncryptedBlobWriter.DisposeAsync" or "System.IO.StreamWriter.Dispose" or "System.IO.StreamWriter.DisposeAsync")
            {
                return HostedProducerSiteKind.FileSystemEffect;
            }

            if (callee is "System.IO.FileStream..ctor" or "System.IO.File.Open")
            {
                IEnumerable<IArgumentOperation> arguments = model.GetOperation(node) switch
                {
                    IObjectCreationOperation creation => creation.Arguments,
                    IInvocationOperation invocation => invocation.Arguments,
                    _ => [],
                };

                return IsExactReadOnlyFileStreamArguments(arguments, model)
                    ? HostedProducerSiteKind.FileSystemRead
                    : HostedProducerSiteKind.FileSystemEffect;
            }

            if (IsReviewedInMemoryStreamReaderMember(
                method,
                node,
                model,
                member))
            {
                return null;
            }

            if (TryClassifyExternalProducer(method, out HostedProducerSiteKind externalKind))
            {
                return externalKind;
            }

            return null;
        }

        private static bool IsBootstrapConsoleRedirection(AuthoredMember member) =>
            TypeKey(member.Symbol.ContainingType)
                == "RetroDownfall.Arcanum.Cli.Commands.ServeCommand"
            && member.Symbol.Name == "RedirectConsoleToBootstrapLog";

        private static bool IsBootstrapConsoleRestoration(AuthoredMember member) =>
            TypeKey(member.Symbol.ContainingType)
                == "RetroDownfall.Arcanum.Cli.Commands.ServeCommand.ConsoleRedirectionLease"
            && member.Symbol is { Name: "Dispose", Parameters.Length: 0, ReturnsVoid: true, IsStatic: false };

        private static bool TryClassifyExternalProducer(
            IMethodSymbol method,
            out HostedProducerSiteKind kind)
        {
            string type = TypeKey(method.ContainingType);

            if (IsDatabaseOperation(method))
            {
                kind = HostedProducerSiteKind.DatabaseAccess;

                return true;
            }

            if (type == "System.IO.FileSystemAclExtensions"
                && method.Name == "Create"
                && FrameworkAssemblyIdentityMatches(
                    method.ContainingAssembly.Identity,
                    typeof(System.IO.FileSystemAclExtensions).Assembly.GetName()))
            {
                kind = HostedProducerSiteKind.FileSystemEffect;

                return true;
            }

            if (type is "System.Net.Http.HttpClient"
                    or "System.Net.Sockets.Socket"
                    or "System.Diagnostics.Process"
                && method.Name is not ".ctor")
            {
                kind = HostedProducerSiteKind.ProviderCall;

                return true;
            }

            if (type == "Microsoft.AspNetCore.DataProtection.IDataProtector"
                && method.Name is "Protect" or "Unprotect"
                || type == "System.Security.Principal.WindowsIdentity"
                    && method.Name == "GetCurrent"
                || type == "System.IO.FileSystemAclExtensions"
                    && method.Name.StartsWith("Get", StringComparison.Ordinal)
                || type.StartsWith(
                        "System.Security.AccessControl.",
                        StringComparison.Ordinal)
                    && method.Name.StartsWith("Get", StringComparison.Ordinal))
            {
                kind = HostedProducerSiteKind.FileSystemRead;

                return true;
            }

            if (type == "System.IO.RandomAccess")
            {
                kind = method.Name is "Write" or "WriteAsync" or "FlushToDisk"
                    ? HostedProducerSiteKind.FileSystemEffect
                    : HostedProducerSiteKind.FileSystemRead;

                return true;
            }

            if (type is "System.IO.Stream" or "System.IO.TextWriter")
            {
                kind = method.Name.StartsWith("Read", StringComparison.Ordinal)
                    ? HostedProducerSiteKind.FileSystemRead
                    : HostedProducerSiteKind.FileSystemEffect;

                return true;
            }

            if (type == "System.IO.StreamReader")
            {
                kind = HostedProducerSiteKind.FileSystemRead;

                return true;
            }

            if (type == "System.Security.Cryptography.SHA256"
                && method.Name == "HashDataAsync"
                || type == "System.Text.Json.JsonSerializer"
                    && method.Parameters.Any(static parameter =>
                        TypeKey(parameter.Type) == "System.IO.Stream")
                    && method.Name.StartsWith("Deserialize", StringComparison.Ordinal))
            {
                kind = HostedProducerSiteKind.FileSystemRead;

                return true;
            }

            if (type == "System.Text.Json.JsonSerializer"
                && method.Parameters.Any(static parameter =>
                    TypeKey(parameter.Type) == "System.IO.Stream")
                && method.Name.StartsWith("Serialize", StringComparison.Ordinal)
                || type == "Serilog.FileLoggerConfigurationExtensions"
                    && method.Name == "File")
            {
                kind = HostedProducerSiteKind.FileSystemEffect;

                return true;
            }

            kind = default;

            return false;
        }

        private static bool TryClassifyExternalProducer(
            IPropertySymbol property,
            bool mutation,
            out HostedProducerSiteKind kind)
        {
            string type = TypeKey(property.ContainingType);

            if (IsDatabaseOperation(property, mutation))
            {
                kind = HostedProducerSiteKind.DatabaseAccess;

                return true;
            }

            if (type == "System.IO.FileSystemWatcher"
                && property.Name == "EnableRaisingEvents")
            {
                kind = HostedProducerSiteKind.FileSystemRead;

                return true;
            }

            if (type is "System.IO.FileSystemInfo" or "System.IO.DriveInfo"
                || type == "System.Diagnostics.Process"
                    && property.Name is "ExitCode" or "HasExited" or "StandardError" or "StandardOutput" or "StartTime"
                || type.StartsWith("System.Security.AccessControl.", StringComparison.Ordinal)
                    || type == "System.Security.Principal.WindowsIdentity")
            {
                if (mutation
                    && type is "System.IO.FileSystemInfo" or "System.IO.DriveInfo")
                {
                    kind = default;

                    return false;
                }

                kind = type == "System.Diagnostics.Process"
                    ? HostedProducerSiteKind.ProviderCall
                    : HostedProducerSiteKind.FileSystemRead;

                return true;
            }

            if (type == "System.IO.Stream")
            {
                kind = mutation
                    ? HostedProducerSiteKind.FileSystemEffect
                    : HostedProducerSiteKind.FileSystemRead;

                return true;
            }

            kind = default;

            return false;
        }

        private static bool IsDatabaseOperation(IMethodSymbol method)
        {
            string type = TypeKey(method.ContainingType);

            return type == "Microsoft.Data.Sqlite.SqliteCommand"
                    && method.Name.StartsWith("Execute", StringComparison.Ordinal)
                || type == "Microsoft.Data.Sqlite.SqliteConnection"
                    && method.Name is "BeginTransaction" or "ClearAllPools" or "ClearPool" or "Open" or "OpenAsync"
                || type == "Microsoft.EntityFrameworkCore.DbContext"
                    && method.Name.StartsWith("SaveChanges", StringComparison.Ordinal)
                || type == "Microsoft.EntityFrameworkCore.Infrastructure.DatabaseFacade"
                    && method.Name.StartsWith("BeginTransaction", StringComparison.Ordinal)
                || type == "Microsoft.EntityFrameworkCore.RelationalDatabaseFacadeExtensions"
                    && (method.Name.StartsWith("OpenConnection", StringComparison.Ordinal)
                        || method.Name is "CloseConnection" or "CloseConnectionAsync")
                || type == "Microsoft.EntityFrameworkCore.Storage.IDbContextTransaction"
                    && method.Name is "Commit" or "CommitAsync" or "Rollback" or "RollbackAsync"
                || type == "System.Data.Common.DbCommand"
                    && method.Name.StartsWith("Execute", StringComparison.Ordinal)
                || type == "System.Data.Common.DbConnection"
                    && method.Name is "BeginTransaction" or "BeginTransactionAsync" or "Close" or "CloseAsync" or "Open" or "OpenAsync"
                || type == "System.Data.Common.DbDataReader"
                    && method.Name is "CloseAsync" or "Read" or "ReadAsync" or "NextResult" or "NextResultAsync"
                || type == "System.Data.Common.DbTransaction"
                    && method.Name is "Commit" or "CommitAsync" or "Rollback" or "RollbackAsync"
                || type == "SQLitePCL.raw"
                    && method.Name.StartsWith("sqlite3_backup_", StringComparison.Ordinal);
        }

        private bool IsExactSqliteBaseReaderProperty(IPropertySymbol property, bool mutation, SyntaxNode node, AuthoredMember member)
        {
            if (mutation || property.IsStatic || !property.IsIndexer || property.SetMethod is not null
                || property.Type.SpecialType != SpecialType.System_Object
                || property.Parameters is not [{ RefKind: RefKind.None, Type.SpecialType: SpecialType.System_Int32 }]
                || !IsExactFrameworkType(property.ContainingType, "System.Data.Common.DbDataReader", typeof(System.Data.Common.DbDataReader).Assembly.GetName())
                || member.Model.GetOperation(node) is not IPropertyReferenceOperation { Instance.Syntax: ExpressionSyntax receiver }) return false;

            CleanupProvenance provenance = CleanupProvenanceOf(
                member,
                receiver,
                new CleanupProvenanceContext { ClosedSqliteProvider = true });

            // A widened declaration or cast is not a SQLite certificate. Keep this as an
            // database effect only when the existing complete factory chain is exact. Work
            // admission is checked independently at the emitted site.
            return provenance.Complete && provenance.Candidates is [CleanupTypeCandidate candidate]
                && IsExactFrameworkType(candidate.Type, "Microsoft.Data.Sqlite.SqliteDataReader", typeof(Microsoft.Data.Sqlite.SqliteDataReader).Assembly.GetName());
        }

        private static bool IsDatabaseOperation(
            IPropertySymbol property,
            bool mutation) => !mutation
                && property.IsIndexer
                && TypeKey(property.ContainingType) == "Microsoft.Data.Sqlite.SqliteDataReader"
                && AssemblyIdentityMatches(
                    property.ContainingAssembly.Identity,
                    typeof(Microsoft.Data.Sqlite.SqliteDataReader).Assembly.GetName());

        /// <summary>
        /// The members of EF's own options builder that an unconfigured context's OnConfiguring
        /// fallback may call without selecting a provider, a connection or a service: they record
        /// state on the builder and run no code of their own. Reviewed by exact assembly identity,
        /// so a same-named type or member from another assembly or from source stays unclassified.
        /// </summary>
        private static bool IsReviewedProviderNeutralOptionsBuilderMember(ISymbol member)
        {
            ISymbol definition = member is IMethodSymbol method
                ? method.ReducedFrom ?? method
                : member;

            return TypeKey(definition.ContainingType) is
                    "Microsoft.EntityFrameworkCore.DbContextOptionsBuilder"
                    or "Microsoft.EntityFrameworkCore.DbContextOptionsBuilder`1"
                && definition.Name is "IsConfigured" or "AddInterceptors" or "UseModel"
                && !definition.IsStatic
                && !definition.Locations.Any(static location => location.IsInSource)
                && AssemblyIdentityMatches(
                    definition.ContainingAssembly.Identity,
                    typeof(Microsoft.EntityFrameworkCore.DbContextOptionsBuilder).Assembly.GetName());
        }

